class Cell { constructor(public value:number, public next:Cell|null) {} }
function step0(cell:Cell,n:number):Cell { if(n>0)cell.next=new Cell(n,cell.next); return cell; }
function step1(cell:Cell,n:number):Cell { if(n>1)cell.next=new Cell(n,cell.next); return step0(cell,n); }
function step2(cell:Cell,n:number):Cell { if(n>2)cell.next=new Cell(n,cell.next); return step1(cell,n); }
function step3(cell:Cell,n:number):Cell { if(n>3)cell.next=new Cell(n,cell.next); return step2(cell,n); }
function step4(cell:Cell,n:number):Cell { if(n>4)cell.next=new Cell(n,cell.next); return step3(cell,n); }
function step5(cell:Cell,n:number):Cell { if(n>5)cell.next=new Cell(n,cell.next); return step4(cell,n); }
function step6(cell:Cell,n:number):Cell { if(n>6)cell.next=new Cell(n,cell.next); return step5(cell,n); }
function step7(cell:Cell,n:number):Cell { if(n>7)cell.next=new Cell(n,cell.next); return step6(cell,n); }
function step8(cell:Cell,n:number):Cell { if(n>8)cell.next=new Cell(n,cell.next); return step7(cell,n); }
function step9(cell:Cell,n:number):Cell { if(n>9)cell.next=new Cell(n,cell.next); return step8(cell,n); }
function step10(cell:Cell,n:number):Cell { if(n>10)cell.next=new Cell(n,cell.next); return step9(cell,n); }
function step11(cell:Cell,n:number):Cell { if(n>11)cell.next=new Cell(n,cell.next); return step10(cell,n); }
function step12(cell:Cell,n:number):Cell { if(n>12)cell.next=new Cell(n,cell.next); return step11(cell,n); }
function step13(cell:Cell,n:number):Cell { if(n>13)cell.next=new Cell(n,cell.next); return step12(cell,n); }
function step14(cell:Cell,n:number):Cell { if(n>14)cell.next=new Cell(n,cell.next); return step13(cell,n); }
function step15(cell:Cell,n:number):Cell { if(n>15)cell.next=new Cell(n,cell.next); return step14(cell,n); }
export function work(n:number):number {const c=step15(new Cell(n,null),n); return c.next===null?c.value:c.next.value;}

