): AsyncIterableIterator<string>;
export function globIterator(
  pattern: unknown,
  options?: unknown,
): AsyncIterableIterator<string | Dirent>;
export function globIterator(
  pattern: unknown,
  options?: unknown,
): AsyncIterableIterator<string | Dirent> {
  return globIteratorWithFileSystem(
    pattern,
    options,
    publicAsyncGlobFileSystem,
  );
}

