  validateBufferArray(buffers);
  const callback = requireVectorCallback(
    typeof positionOrCallback === "function"
      ? positionOrCallback
      : suppliedCallback,
  );
  if (buffers.length === 0) {
    nextTick(() => callback(null, 0, buffers));
    return;
