    if (fd === undefined) {
      complete(new Error("fs open completed without a file descriptor"));
      return;
    }
    ftruncate(fd, validatedLength, (truncateError: unknown) => {
      close(fd, (closeError: unknown) => {
        complete(aggregateTwoErrors(closeError, truncateError));
      });
    });
  });
}

