// FileHandle's synchronous stream operations use the same established native
// operations as fs.readSync/writeSync/writevSync/closeSync. They are declared
// here too because importing main.ts would create the cycle main -> promises
// -> main.
/** @ntsAbi managed */
declare function nts_fs_read(fd: number, length: number, position: number): number[];
/** @ntsAbi managed */
declare function nts_fs_write(fd: number, bytes: number[], position: number): number;
/** @ntsAbi managed */
declare function nts_fs_writev(
  fd: number,
  bytes: number[],
  lengths: number[],
  position: number,
): number;
/** @ntsAbi managed */
declare function nts_fs_close(fd: number): number;
/** @ntsAbi managed */
declare function nts_errno(): number;

/** A value-producing callback operation as a promise-returning one. */
function promisifyValue<A extends unknown[], T>(
  fn: (...args: [...A, (error: unknown, value?: T) => void]) => void,
  operation: string,
): (...args: A) => Promise<T> {
  return (...args: A) =>
    new Promise<T>((resolve, reject) => {
      fn(...args, (error: unknown, value?: T) => {
        if (error !== null && error !== undefined) {
          reject(error);
        } else if (value === undefined) {
          reject(new Error(`fs ${operation} completed without a result`));
        } else {
          resolve(value);
        }
      });
    });
}

/** A callback operation whose successful result is intentionally absent. */
function promisifyVoid<A extends unknown[]>(
  fn: (...args: [...A, (error: unknown) => void]) => void,
): (...args: A) => Promise<void> {
  return (...args: A) =>
    new Promise<void>((resolve, reject) => {
      fn(...args, (error: unknown) => {
        if (error !== null && error !== undefined) reject(error);
        else resolve();
      });
    });
}

/** A value callback where `undefined` is a documented successful result. */
function promisifyOptionalValue<A extends unknown[], T>(
  fn: (...args: [...A, (error: unknown, value?: T) => void]) => void,
): (...args: A) => Promise<T | undefined> {
  return (...args: A) =>
    new Promise<T | undefined>((resolve, reject) => {
      fn(...args, (error: unknown, value?: T) => {
        if (error !== null && error !== undefined) reject(error);
        else resolve(value);
      });
    });
}

/**
 * An open file, and everything you can do with it.
 *
 * The point over a bare descriptor is ownership. A number can be leaked, can
 * be closed twice, and can be used after closing -- by which time the kernel
 * may have handed it to something else, so the read succeeds and reads the
 * wrong file. A handle can be disposed, knows whether it is closed, and is
 * the only thing holding the number.
 */
interface FileHandleReadOptions {
  buffer?: ArrayBufferView;
  offset?: number | null;
  length?: number | null;
  position?: number | bigint | null;
}

interface FileHandleWriteOptions {
  offset?: number;
  length?: number;
  position?: number;
}

/** One value accepted directly, or yielded, by the promise write APIs. */
export type FileWriteChunk = string | ArrayBufferView;

/** The complete data surface accepted by promise writeFile/appendFile. */
export type FileWriteData =
  | FileWriteChunk
  | Iterable<FileWriteChunk>
  | AsyncIterable<FileWriteChunk>
  | Readable;

type UnknownFileWriteIterable = Iterable<unknown> | AsyncIterable<unknown>;
type FileWriteInput = FileWriteChunk | UnknownFileWriteIterable;
const writeFileMaxChunkSize = 512 * 1024;

function isFileWriteIterable(value: unknown): value is UnknownFileWriteIterable {
  if (
    value === null ||
    typeof value === "string" ||
    ArrayBuffer.isView(value) ||
    (typeof value !== "object" && typeof value !== "function")
  ) {
    return false;
  }
  const hasAsyncIterator =
    Symbol.asyncIterator in value && typeof value[Symbol.asyncIterator] === "function";
  const hasIterator = Symbol.iterator in value && typeof value[Symbol.iterator] === "function";
  return hasAsyncIterator || hasIterator;
}

function requireFileWriteData(value: unknown): FileWriteInput {
  if (typeof value !== "string" && !ArrayBuffer.isView(value) && !isFileWriteIterable(value)) {
    throw new ERR_INVALID_ARG_TYPE(
      "data",
      ["string", "Buffer", "TypedArray", "DataView", "AsyncIterable", "Iterable", "Stream"],
      value,
    );
  }
  return value;
}

function throwIfWriteAborted(signal: AbortSignalLike | undefined): void {
  if (signal?.aborted) {
    throw new AbortError(undefined, { cause: signal.reason });
  }
}

/** Pinned Node's incremental `writeFileHandle` algorithm. */
async function writeFileHandle(
  handle: FileHandle,
  data: FileWriteInput,
  signal: AbortSignalLike | undefined,
  encoding: Encoding,
): Promise<void> {
  throwIfWriteAborted(signal);

  if (isFileWriteIterable(data)) {
    for await (const chunk of data) {
      throwIfWriteAborted(signal);
      let bytes: ArrayBufferView;
      if (typeof chunk === "string") {
        bytes = Buffer.from(chunk, encoding);
      } else if (ArrayBuffer.isView(chunk)) {
        bytes = new Uint8Array(chunk.buffer, chunk.byteOffset, chunk.byteLength);
      } else {
        throw new ERR_INVALID_ARG_TYPE(
          "data",
          ["string", "Buffer", "TypedArray", "DataView"],
          chunk,
        );
      }

      let offset = 0;
      while (offset < bytes.byteLength) {
        const length = Math.min(writeFileMaxChunkSize, bytes.byteLength - offset);
        const { bytesWritten } = await handle.write(bytes, offset, length, null);
        if (bytesWritten === 0) {
          throw new Error("fs write made no progress");
        }
        offset += bytesWritten;
        throwIfWriteAborted(signal);
      }
    }
  } else {
    let bytes: ArrayBufferView;
    if (typeof data === "string") {
      bytes = Buffer.from(data, encoding);
    } else if (ArrayBuffer.isView(data)) {
      bytes = new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
    } else {
      throw new Error("validated fs write data lost its scalar representation");
    }

    let offset = 0;
    while (offset < bytes.byteLength) {
      throwIfWriteAborted(signal);
      const length = Math.min(writeFileMaxChunkSize, bytes.byteLength - offset);
      const { bytesWritten } = await handle.write(bytes, offset, length, null);
      if (bytesWritten === 0) {
        throw new Error("fs write made no progress");
      }
      offset += bytesWritten;
    }
  }
}

async function writeFileToOpenHandle(
  handle: FileHandle,
  data: unknown,
  options: string | FileOptions | undefined,
): Promise<void> {
  const settings = getOptions(options, { encoding: "utf8", flush: false });
  const flush = settings.flush ?? false;
  validateBoolean(flush, "options.flush");
  const encoding = requireTextEncoding(settings.encoding || "utf8", "options.encoding");
  await writeFileHandle(handle, requireFileWriteData(data), settings.signal, encoding);
}

export type WatchOverflow = "ignore" | "error";

export interface PromiseWatchOptions extends Omit<WatchOptions, "throwIfNoEntry"> {
  maxQueue?: number | undefined;
  overflow?: WatchOverflow | undefined;
}

export interface WatchEvent {
  eventType: WatchEventType;
  filename: WatchFileName;
}

interface RawPromiseWatchOptions {
  persistent?: unknown;
  recursive?: unknown;
  encoding?: unknown;
  signal?: unknown;
  ignore?: unknown;
  maxQueue?: unknown;
  overflow?: unknown;
}

interface NormalizedPromiseWatchOptions {
  watcher: WatchOptions;
  signal: WatchSignal | undefined;
  maxQueue: number;
  overflow: WatchOverflow;
}

function normalizePromiseWatchOptions(value: unknown): NormalizedPromiseWatchOptions {
  const raw = value === undefined ? {} : value;
  validateObject(raw, "options");
  const options: RawPromiseWatchOptions = raw;

  const persistent = options.persistent === undefined ? true : options.persistent;
  const recursive = options.recursive === undefined ? false : options.recursive;
  const maxQueue = options.maxQueue === undefined ? 2048 : options.maxQueue;
  const overflow = options.overflow === undefined ? "ignore" : options.overflow;
  validateBoolean(persistent, "options.persistent");
  validateBoolean(recursive, "options.recursive");
  validateInteger(maxQueue, "options.maxQueue");
  if (overflow !== "ignore" && overflow !== "error") {
    throw new ERR_INVALID_ARG_VALUE(
      "options.overflow",
      overflow,
      "must be one of: 'ignore', 'error'",
    );
  }

  const encoding = normalizeFileResultEncoding(options.encoding ?? "utf8");
  const ignore = normalizeWatchIgnore(options.ignore);
  validateWatchSignal(options.signal);
  return {
    watcher: {
      persistent,
      recursive,
      encoding,
      ignore,
    },
    signal: options.signal,
    maxQueue,
    overflow,
  };
}

interface WatchFailure {
  readonly reason: unknown;
}

export function watch(
  filename: PathLike,
  options?: PromiseWatchOptions,
): AsyncIterableIterator<WatchEvent>;
/** One event queue and one native watcher, consumed at most once. */
export async function* watch(
  filenameValue: unknown,
  options?: unknown,
): AsyncGenerator<WatchEvent, void, undefined> {
  const settings = normalizePromiseWatchOptions(options);
  const filename = getValidatedPath(filenameValue, "filename");
  const signal = settings.signal;
  if (signal?.aborted) {
    throw new AbortError(undefined, { cause: signal.reason });
  }

  const watcher = new FSWatcher();
  const queue: Array<WatchEvent | WatchFailure> = [];
  let queueHead = 0;
  let waiter = Promise.withResolvers<void>();
  const onChange = (eventType: WatchEventType, changed: WatchFileName): void => {
    if (queue.length - queueHead < settings.maxQueue) {
      queue.push({ eventType, filename: changed });
      waiter.resolve();
    } else if (settings.overflow === "error") {
      queue.length = 0;
      queueHead = 0;
      queue.push({
        reason: new ERR_FS_WATCH_QUEUE_OVERFLOW(settings.maxQueue),
      });
      waiter.resolve();
    } else {
      emitWarning("fs.watch maxQueue exceeded", "Warning", "");
    }
  };
  const onError = (error: unknown): void => {
    queue.push({ reason: error });
    waiter.resolve();
  };
  const onAbort = (): void => waiter.resolve();

  watcher.on("change", onChange);
  watcher.on("error", onError);
  if (signal !== undefined) {
    signal.addEventListener("abort", onAbort, { once: true });
  }

  try {
    watcher.start(filename, settings.watcher);
    while (!signal?.aborted) {
      await waiter.promise;
      while (queueHead < queue.length) {
        const item = queue[queueHead++];
        if (item === undefined) {
          throw new Error("fs watch queue is missing an event");
        }
        if ("reason" in item) throw item.reason;
        yield item;
      }
      queue.length = 0;
      queueHead = 0;
      waiter = Promise.withResolvers<void>();
    }
    if (signal.aborted) {
      throw new AbortError(undefined, { cause: signal.reason });
    }
  } finally {
    watcher.close();
    watcher.removeListener("change", onChange);
    watcher.removeListener("error", onError);
    signal?.removeEventListener("abort", onAbort);
  }
}

/** Bytes accepted by Node's experimental FileHandle writer. */
export type FileHandleWriterChunk = string | ArrayBufferView;

export interface FileHandleWriterOptions {
  autoClose?: boolean | undefined;
  start?: number | undefined;
  limit?: number | undefined;
  chunkSize?: number | undefined;
}

export interface FileHandleWebStreamOptions {
  type?: string;
  autoClose?: boolean;
}

export interface FileHandlePullOptions extends FileHandleWriterOptions {
  signal?: AbortSignalLike | undefined;
}

export interface FileHandleWriterOperationOptions {
  signal?: AbortSignalLike | undefined;
}

interface RawFileHandleWriterOptions {
  autoClose?: unknown;
  start?: unknown;
  limit?: unknown;
  chunkSize?: unknown;
}

interface NormalizedFileHandleWriterOptions {
  autoClose: boolean;
  start: number;
  limit: number;
  chunkSize: number;
}

interface NormalizedFileHandlePullOptions extends NormalizedFileHandleWriterOptions {
  signal: AbortSignalLike | undefined;
}

interface RawFileHandleWriterOperationOptions {
  signal?: unknown;
}

function writerOptionsObject(value: unknown): asserts value is RawFileHandleWriterOptions {
  validateObject(value, "options");
}

function normalizeValidatedFileHandleOptions(
  options: RawFileHandleWriterOptions,
): NormalizedFileHandleWriterOptions {
  const autoClose = options.autoClose === undefined ? false : options.autoClose;
  const chunkSize = options.chunkSize === undefined ? 128 * 1024 : options.chunkSize;

  validateBoolean(autoClose, "options.autoClose");
  validateInteger(chunkSize, "options.chunkSize", 1);

  // Keep the internal -1 sentinel distinct from an explicitly supplied -1,
  // which Node rejects for both public options.
  let start = -1;
  if (options.start !== undefined) {
    validateInteger(options.start, "options.start", 0);
    start = options.start;
  }
  let limit = -1;
  if (options.limit !== undefined) {
    validateInteger(options.limit, "options.limit", 1);
    limit = options.limit;
  }
  return { autoClose, start, limit, chunkSize };
}

function normalizeWriterOptions(value: unknown): NormalizedFileHandleWriterOptions {
  const options = value === undefined ? {} : value;
  writerOptionsObject(options);
  return normalizeValidatedFileHandleOptions(options);
}

function normalizePullOptions(value: unknown): NormalizedFileHandlePullOptions {
  const options = value === undefined ? {} : value;
  writerOptionsObject(options);
  const signal = "signal" in options ? options.signal : undefined;
  writerSignal(signal);
  const normalized = normalizeValidatedFileHandleOptions(options);
  return {
    autoClose: normalized.autoClose,
    start: normalized.start,
    limit: normalized.limit,
    chunkSize: normalized.chunkSize,
    signal,
  };
}

function writerSignal(value: unknown): asserts value is AbortSignalLike | undefined {
  validateAbortSignal(value, "options.signal");
}

function writerOperationSignal(value: unknown): AbortSignalLike | undefined {
  if (value === undefined) return undefined;
  validateObject(value, "options");
  const options: RawFileHandleWriterOperationOptions = value;
  writerSignal(options.signal);
  return options.signal;
}

function writerChunkBytes(value: unknown): Uint8Array {
  if (typeof value === "string") return Buffer.from(value);
  if (ArrayBuffer.isView(value)) {
    return new Uint8Array(value.buffer, value.byteOffset, value.byteLength);
  }
  throw new ERR_INVALID_ARG_TYPE("chunk", ["string", "Buffer", "TypedArray", "DataView"], value);
}

function writerChunks(value: unknown): Uint8Array[] {
  if (!Array.isArray(value)) {
    throw new ERR_INVALID_ARG_TYPE("chunks", "Array", value);
  }
  const chunks = new Array<Uint8Array>(value.length);
  for (let index = 0; index < value.length; index++) {
    chunks[index] = writerChunkBytes(value[index]);
  }
  return chunks;
}

function copyWriterBytes(value: Uint8Array, offset: number, length: number): number[] {
  const bytes = new Array<number>(length);
  for (let index = 0; index < length; index++) {
    const byte = value[offset + index];
    if (byte === undefined) {
      throw new Error(`FileHandle writer is missing byte ${offset + index}`);
    }
    bytes[index] = byte;
  }
  return bytes;
}

export class FileHandle extends EventEmitter {
  #fd: number;
  #references = 1;
  #closeCapability: PromiseWithResolvers<void> | undefined;
  #descriptorClosed = false;
  #operationLocked = false;

  constructor(fd: number) {
    super();
    this.#fd = fd;
  }

  get fd(): number {
    return this.#fd;
  }

  /** Retain the descriptor while a file stream owns an operation reference. */
  _refForStream(): void {
    if (this.#descriptorClosed) {
      throw new Error("Cannot retain a closed FileHandle");
    }
    this.#references++;
  }

  /** Release the reference acquired when a file stream adopted this handle. */
  _unrefForStream(): void {
    if (this.#references <= 0) {
      throw new Error("FileHandle stream reference count underflow");
    }
    this.#references--;
    if (this.#references === 0 && this.#closeCapability !== undefined) {
      this.#closeDescriptor();
    }
  }

  async read(
    options?: FileHandleReadOptions | null,
  ): Promise<{ bytesRead: number; buffer: ArrayBufferView }>;
  async read<T extends ArrayBufferView>(
    buffer: T,
    options?: {
      offset?: number | null;
      length?: number | null;
      position?: number | bigint | null;
    } | null,
  ): Promise<{ bytesRead: number; buffer: T }>;
  async read<T extends ArrayBufferView>(
    buffer: T,
    offset?: number | null,
    length?: number,
    position?: number | bigint | null,
  ): Promise<{ bytesRead: number; buffer: T }>;
  async read(
    bufferOrOptions?: ArrayBufferView | FileHandleReadOptions | null,
    offsetOrOptions:
      | number
      | null
      | {
          offset?: number | null;
          length?: number | null;
          position?: number | bigint | null;
        } = 0,
    length?: number,
    position: number | bigint | null = null,
  ): Promise<{ bytesRead: number; buffer: ArrayBufferView }> {
    if (!ArrayBuffer.isView(bufferOrOptions)) {
      const options = bufferOrOptions ?? {};
      const buffer = options.buffer ?? Buffer.alloc(16_384);
      return this.#readView(buffer, options);
    }
    return this.#readView(bufferOrOptions, offsetOrOptions, length, position);
  }

  #readView<T extends ArrayBufferView>(
    buffer: T,
    offsetOrOptions: number | null | FileHandleReadOptions = 0,
    length?: number,
    position: number | bigint | null = null,
  ): Promise<{ bytesRead: number; buffer: T }> {
    return new Promise((resolve, reject) => {
      const complete = (error: unknown, bytesRead?: number): void => {
        if (error !== null && error !== undefined) {
          reject(error);
        } else if (bytesRead === undefined) {
          reject(new Error("fs read completed without a byte count"));
        } else {
          resolve({ bytesRead, buffer });
        }
      };
      if (typeof offsetOrOptions === "object") {
        const offset = offsetOrOptions?.offset ?? 0;
        callbacks.readFileHandle(
          this.#fd,
          buffer,
          {
            buffer,
            offset,
            length: offsetOrOptions?.length ?? buffer.byteLength - offset,
            position: offsetOrOptions?.position ?? null,
          },
          complete,
        );
      } else {
        const offset = offsetOrOptions ?? 0;
        callbacks.readFileHandle(
          this.#fd,
          buffer,
          offset,
          length == null ? buffer.byteLength - offset : length,
          position,
          complete,
        );
      }
    });
  }

  async write<T extends ArrayBufferView>(
    data: T,
    offset?: number | null,
    length?: number,
    position?: number | null,
  ): Promise<{ bytesWritten: number; buffer: T }>;
  async write<T extends ArrayBufferView>(
    data: T,
    options?: FileHandleWriteOptions | null,
  ): Promise<{ bytesWritten: number; buffer: T }>;
  async write(
    data: string,
    position?: number | null,
    encoding?: string | null,
  ): Promise<{ bytesWritten: number; buffer: string }>;
  async write(
    data: unknown,
    offsetOrOptions: number | null | FileHandleWriteOptions = 0,
    length?: number | string | null,
    position: number | null = null,
  ): Promise<{ bytesWritten: number; buffer: string | ArrayBufferView }> {
    if (typeof data !== "string" && !ArrayBuffer.isView(data)) {
      throw new ERR_INVALID_ARG_TYPE(
        "buffer",
        ["Buffer", "TypedArray", "DataView", "string"],
        data,
      );
    }
    return new Promise((resolve, reject) => {
      const complete = (error: unknown, written?: number): void => {
        if (error !== null && error !== undefined) {
          reject(error);
        } else if (written === undefined) {
          reject(new Error("fs write completed without a byte count"));
        } else {
          resolve({ bytesWritten: written, buffer: data });
        }
      };
      if (typeof data === "string") {
        callbacks.write(
          this.#fd,
          data,
          typeof offsetOrOptions === "number" ? offsetOrOptions : null,
          typeof length === "string" ? length : "utf8",
          complete,
        );
      } else if (typeof offsetOrOptions === "object" && offsetOrOptions !== null) {
        callbacks.write(this.#fd, data, offsetOrOptions, complete);
      } else {
        const start = offsetOrOptions ?? 0;
        callbacks.write(
          this.#fd,
          data,
          start,
          typeof length === "number" ? length : data.byteLength - start,
          position,
          complete,
        );
      }
    });
  }

  async readv<T extends readonly ArrayBufferView[]>(
    buffers: T,
    position: number | null = null,
  ): Promise<{ bytesRead: number; buffers: T }> {
    return new Promise((resolve, reject) => {
      callbacks.readv(this.#fd, buffers, position, (error, bytesRead) => {
        if (error !== null && error !== undefined) {
          reject(error);
        } else if (bytesRead === undefined) {
          reject(new Error("fs readv completed without a byte count"));
        } else {
          resolve({ bytesRead, buffers });
        }
      });
    });
  }

  async writev<T extends readonly ArrayBufferView[]>(
    buffers: T,
    position: number | null = null,
  ): Promise<{ bytesWritten: number; buffers: T }> {
    return new Promise((resolve, reject) => {
      callbacks.writev(this.#fd, buffers, position, (error, bytesWritten) => {
        if (error !== null && error !== undefined) {
          reject(error);
        } else if (bytesWritten === undefined) {
          reject(new Error("fs writev completed without a byte count"));
        } else {
          resolve({ bytesWritten, buffers });
        }
      });
    });
  }

  #requireOperationAvailable(): void {
    if (this.#descriptorClosed) {
      throw new ERR_INVALID_STATE("The FileHandle is closed");
    }
    if (this.#closeCapability !== undefined) {
      throw new ERR_INVALID_STATE("The FileHandle is closing");
    }
    if (this.#operationLocked) {
      throw new ERR_INVALID_STATE("The FileHandle is locked");
    }
  }

  /** Read this handle as an asynchronous stream/iter byte source. */
  pull(...args: (Transform | FileHandlePullOptions)[]): AsyncByteStream;
  pull(...args: unknown[]): AsyncByteStream {
    this.#requireOperationAvailable();
    const parsed = parsePullArguments(args);
    const settings = normalizePullOptions(parsed.options);
    this.#operationLocked = true;

    const source = new FileHandleAsyncSource(this, settings);
    return parsed.transforms.length === 0 ? source : createParsedPull(source, parsed);
  }

  /** Read this handle as a synchronous stream/iter byte source. */
  pullSync(...args: (Transform | FileHandleWriterOptions)[]): SyncByteStream;
  pullSync(...args: unknown[]): SyncByteStream {
    this.#requireOperationAvailable();
    const parsed = parsePullArguments(args);
    const settings = normalizeWriterOptions(parsed.options);
    this.#operationLocked = true;
    this._refForStream();

    const source = new FileHandleSyncSource(this, this.#fd, settings);
    return parsed.transforms.length === 0
      ? source
      : createParsedPullSync(source, parsed.transforms);
  }

  /**
   * This handle as a web `ReadableStream`, node's `readableWebStream`.
   *
   * Always byte-oriented, whatever `type` says: the stream auto-allocates and
   * the source answers the BYOB request, so a `mode: "byob"` reader has its
   * own buffer filled rather than handed a copy. The `ReadableStream` is the
   * canonical one from `web-platform`; nothing about streams is restated here.
   */
  readableWebStream(options: FileHandleWebStreamOptions = {}): ReadableStream<Uint8Array> {
    this.#requireOperationAvailable();
    // Node locks before it validates, so a rejected `options` still leaves the
    // handle claimed. Transcribed rather than tidied.
    this.#operationLocked = true;

    validateObject(options, "options");
    const type = options.type ?? "bytes";
    const autoClose = options.autoClose ?? false;
    validateBoolean(autoClose, "options.autoClose");
    if (type !== "bytes") {
      emitWarning(
        'A non-"bytes" options.type has no effect. A byte-oriented steam is ' +
          "always created.",
        "ExperimentalWarning",
        "",
      );
    }

    const done = async (): Promise<void> => {
      this._unrefForStream();
      if (autoClose) await this.close();
    };

    const readable = new ReadableStream<Uint8Array>({
      type: "bytes",
      autoAllocateChunkSize: 16_384,
      pull: async (controller) => {
        const request = controller.byobRequest;
        const view = request?.view;
        if (request === null || view === null || view === undefined) {
          throw new Error("auto-allocating byte stream pulled with no BYOB view");
        }
        const { bytesRead } = await this.read(view, view.byteOffset, view.byteLength);
        if (bytesRead === 0) {
          controller.close();
          await done();
        }
        request.respond(bytesRead);
      },
      cancel: async () => {
        await done();
      },
    });

    this._refForStream();
    // Closing the handle ends the stream even while a reader holds it, which
    // is why this is the internal cancel: the public one rejects on a locked
    // stream, and a handle closing under a reader is exactly that case.
    //
    // Reached through the exported symbol rather than by name. The web-platform
    // lane moved its stream internals off the public prototype, which is right
    // -- they are not part of `ReadableStream`'s Web IDL surface and should not
    // be reachable from script. `kStreamCancelInternal` is exported precisely so
    // a runtime that owns the stream's source can still end it, and this is that
    // case: the handle, not script, is closing it.
    this.once("close", () => {
      void readable[kStreamCancelInternal](undefined);
    });
    return readable;
  }

  /**
   * A bounded writer over this handle.
   *
   * The writer retains the descriptor until it ends or fails. That is the
   * important ownership rule: `handle.close()` may begin while a write is in
   * flight, but the numeric descriptor cannot be reused by the OS underneath
   * that operation.
   */
  writer(options?: FileHandleWriterOptions): FileHandleWriter;
  writer(options?: unknown): FileHandleWriter {
    this.#requireOperationAvailable();
    const settings = normalizeWriterOptions(options);
    this.#operationLocked = true;
    this._refForStream();
    return new FileHandleWriterImplementation(this, this.#fd, settings);
  }

  /** Release the descriptor reference owned by a completed pull or writer. */
  async _finishOperation(autoClose: boolean): Promise<void> {
    if (!this.#operationLocked) return;
    this.#operationLocked = false;
    this._unrefForStream();
    if (autoClose) await this.close();
  }

  /** The synchronous counterpart used by pullSync, fail, and endSync. */
  _finishOperationSync(autoClose: boolean): void {
    if (!this.#operationLocked) return;
    this.#operationLocked = false;
    if (this.#references <= 0) {
      throw new Error("FileHandle operation reference count underflow");
    }
    this.#references--;

    if (autoClose && this.#closeCapability === undefined && !this.#descriptorClosed) {
      this.#beginClose(true);
      return;
    }
    if (this.#references === 0 && this.#closeCapability !== undefined) {
      this.#closeDescriptorSync();
    }
  }

  async readFile(options?: string | ReadFileOptions): Promise<string | Buffer> {
    return new Promise((resolve, reject) => {
      callbacks.readFile(this.#fd, options ?? null, (error, contents) => {
        if (error !== null && error !== undefined) {
          reject(error);
        } else if (contents === undefined) {
          reject(new Error("fs readFile completed without file contents"));
        } else {
          resolve(contents);
        }
      });
    });
  }

  readLines(options?: FileStreamOptions): ReadLineInterface {
    return new ReadLineInterface({
      input: this.createReadStream(options),
      crlfDelay: Infinity,
