/**
 * Decode rows returned by the native scandir seam.
 *
 * A row is `[uv_dirent_type_t, ...nameBytes]`. Keeping the name as bytes until
 * this point preserves POSIX filenames that are not UTF-8 and lets every
 * supported output encoding observe the exact directory entry.
 */
export function decodeScandirRows(
  rows: number[][],
  parentPath: string,
  options: ReaddirOptions & { withFileTypes: true },
): Dirent<EncodedFileName>[];
export function decodeScandirRows(
  rows: number[][],
  parentPath: string,
  options: ReaddirOptions & { withFileTypes?: false },
): EncodedFileName[];
export function decodeScandirRows(
  rows: number[][],
  parentPath: string,
  options: ReaddirOptions,
): ReaddirResult;
export function decodeScandirRows(
  rows: number[][],
  parentPath: string,
  options: ReaddirOptions,
): ReaddirResult {
  const names = options.withFileTypes
    ? undefined
    : new Array<EncodedFileName>(rows.length);
  const entries = options.withFileTypes
    ? new Array<Dirent<EncodedFileName>>(rows.length)
    : undefined;
  for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
    const row = rows[rowIndex];
    if (row === undefined || row.length === 0) {
      throw new Error(`fs scandir result is missing row ${rowIndex}`);
    }
    const type = row[0];
    if (type === undefined || !Number.isInteger(type) || type < 0 || type > 7) {
      throw new Error(`fs scandir result has invalid type ${rowIndex}`);
    }
    const bytes = new Array<number>(row.length - 1);
    for (let byteIndex = 1; byteIndex < row.length; byteIndex++) {
      const byte = row[byteIndex];
      if (byte === undefined) {
        throw new Error(`fs scandir row ${rowIndex} is missing byte ${byteIndex}`);
      }
      bytes[byteIndex - 1] = byte;
    }
    const name = encodeNormalizedFileBytes(
      bytes,
      options.encoding === null ? undefined : options.encoding,
    );
    if (entries !== undefined) {
      entries[rowIndex] = new Dirent(name, type, parentPath);
    } else if (names !== undefined) {
      names[rowIndex] = name;
    }
  }
  if (entries !== undefined) return entries;
  if (names !== undefined) return names;
  throw new Error("fs scandir result has no destination");
}

// The asynchronous-resource boundary shared by every callback-style fs request.

import { validateFunction } from "../../internal/validators.ts";
import { AsyncContextFrame } from "../../internal/async-context.ts";
import {
  emitAfter,
  emitBefore,
  emitDestroy,
  emitInit,
  getDefaultTriggerAsyncId,
  initHooksExist,
  newAsyncId,
} from "../../internal/async-hooks.ts";

export type Callback<T = void> = (error: unknown, value?: T) => void;

/** Validate and instrument the one callback owned by an fs request. */
export function asRequest<Arguments extends unknown[]>(
  callback: ((...args: Arguments) => void) | undefined,
  syscall: string,
  callbackName = "cb",
): (...args: Arguments) => void {
  validateFunction(callback, callbackName);

  const asyncId = newAsyncId();
  const trigger = getDefaultTriggerAsyncId();
  const frame = AsyncContextFrame.current();
  const resource = { syscall };
  if (initHooksExist()) emitInit(asyncId, "FSREQCALLBACK", trigger, resource);

  return (...args: Arguments) => {
    const prior = AsyncContextFrame.exchange(frame);
    emitBefore(asyncId, trigger, resource);
    try {
      callback(...args);
    } finally {
      emitAfter(asyncId);
      emitDestroy(asyncId);
      AsyncContextFrame.setCurrent(prior);
    }
  };
}

