  }
  isDirectory(): boolean {
    return this.#type === 2;
  }
  isSymbolicLink(): boolean {
    return this.#type === 3;
  }
  isFIFO(): boolean {
    return this.#type === 4;
  }
  isSocket(): boolean {
    return this.#type === 5;
  }
  isCharacterDevice(): boolean {
    return this.#type === 6;
  }
  isBlockDevice(): boolean {
    return this.#type === 7;
  }
}

// `fs.createReadStream` and `fs.createWriteStream`, from node v24.20.0
// `lib/internal/fs/streams.js`.
//
// A file as a stream, which is the shape almost every program actually wants:
// `readFile` on a large file is a large allocation, and `writeFile` on a slow
// consumer has nowhere to apply backpressure.
//
// The one non-obvious rule is in `_destroy`. It is normally safe to close a
// descriptor while operations are outstanding, but file I/O in libuv is
// implemented with *synchronous* calls on a thread pool, so a descriptor
// closed during a pending read may be reused by the operating system before
// that read runs -- and the read then succeeds against a different file. So a
// stream being destroyed waits for its in-flight operation to report before it
// closes.

import { Buffer } from "../../buffer/src/main.ts";
import type { Encoding } from "../../buffer/src/encodings.ts";
import { Readable, Writable } from "../../stream/src/main.ts";
import { finished } from "../../stream/src/main.ts";
import type { BufferedWrite, WriteCallback } from "../../stream/src/writable.ts";
import { errorOrDestroy } from "../../stream/src/destroy.ts";
import type { AbortSignalLike } from "../../stream/src/end-of-stream.ts";
import { addAbortSignalNoValidate } from "../../stream/src/add-abort-signal.ts";
import { nextTick } from "../../internal/tick.ts";
import {
  validateAbortSignal,
  validateBoolean,
  validateFunction,
  validateInteger,
} from "../../internal/validators.ts";
import {
  ERR_INVALID_ARG_TYPE,
  ERR_METHOD_NOT_IMPLEMENTED,
  ERR_OUT_OF_RANGE,
  ERR_STREAM_DESTROYED,
} from "../../internal/errors.ts";
import { emitWarning } from "../../internal/process-warning.ts";
import * as callbacks from "./async.ts";
import { validateEncodingOption, validateFileDescriptor } from "./options.ts";

let readStreamOpenWarningEmitted = false;
let writeStreamOpenWarningEmitted = false;

function warnReadStreamOpen(): void {
  if (readStreamOpenWarningEmitted) return;
  readStreamOpenWarningEmitted = true;
  emitWarning(
    "ReadStream.prototype.open() is deprecated",
    "DeprecationWarning",
    "DEP0135",
  );
}

function warnWriteStreamOpen(): void {
  if (writeStreamOpenWarningEmitted) return;
  writeStreamOpenWarningEmitted = true;
  emitWarning(
    "WriteStream.prototype.open() is deprecated",
    "DeprecationWarning",
    "DEP0135",
  );
}

interface StreamFileHandle {
  readonly fd: number;
  _refForStream(): void;
  _unrefForStream(): void;
  close(): Promise<void>;
  read(
    buffer: Buffer,
    offset: number,
    length: number,
    position: number | bigint | null,
  ): Promise<{ bytesRead: number; buffer: ArrayBufferView }>;
  sync(): Promise<void>;
  write(
    buffer: Buffer,
    offset: number,
    length: number,
    position: number | null,
  ): Promise<{ bytesWritten: number; buffer: ArrayBufferView }>;
  writev<T extends readonly ArrayBufferView[]>(
    buffers: T,
    position: number | null,
  ): Promise<{ bytesWritten: number; buffers: T }>;
  on(type: "close", listener: () => void): this;
}

interface PendingDestroy {
  error: unknown;
  callback: (error?: unknown) => void;
}

function isStreamFileHandle(value: unknown): value is StreamFileHandle {
  return value !== null && typeof value === "object" &&
    "fd" in value && typeof value.fd === "number" &&
    "_refForStream" in value && typeof value._refForStream === "function" &&
    "_unrefForStream" in value && typeof value._unrefForStream === "function" &&
    "close" in value && typeof value.close === "function" &&
    "read" in value && typeof value.read === "function" &&
    "sync" in value && typeof value.sync === "function" &&
    "write" in value && typeof value.write === "function" &&
    "writev" in value && typeof value.writev === "function" &&
    "on" in value && typeof value.on === "function";
}

export type StreamOpenCallback = (error: unknown, fd?: number) => void;
export type StreamReadCallback = (
  error: unknown,
  bytesRead?: number,
  buffer?: ArrayBufferView,
) => void;
export type StreamWriteCallback = (
  error: unknown,
  bytesWritten?: number,
  buffer?: string | ArrayBufferView,
) => void;
export type StreamWritevCallback = (
  error: unknown,
  bytesWritten?: number,
  buffers?: readonly ArrayBufferView[],
) => void;
export type StreamCloseCallback = (error?: unknown) => void;

export interface StreamFSImplementation {
  open?: (
    path: string,
    flags: string,
    mode: number,
    callback: StreamOpenCallback,
  ) => void;
  close?: (fd: number, callback: StreamCloseCallback) => void;
  read?: (
    fd: number,
    buffer: Buffer,
    offset: number,
    length: number,
    position: number | null,
    callback: StreamReadCallback,
  ) => void;
  write?: (
    fd: number,
    buffer: Buffer,
    offset: number,
    length: number,
    position: number | null,
    callback: StreamWriteCallback,
  ) => void;
  writev?: (
    fd: number,
    buffers: Buffer[],
    position: number | null,
    callback: StreamWritevCallback,
  ) => void;
  fsync?: (fd: number, callback: StreamCloseCallback) => void;
}

export interface FileStreamOptions {
  flags?: string | undefined;
  encoding?: Encoding | undefined;
  fd?: number | StreamFileHandle | null | undefined;
  mode?: number | undefined;
  autoClose?: boolean | undefined;
  emitClose?: boolean | undefined;
  start?: number | undefined;
  end?: number | undefined;
  highWaterMark?: number | undefined;
  fs?: StreamFSImplementation | null | undefined;
  flush?: boolean | null | undefined;
  signal?: AbortSignalLike | null | undefined;
}

export type FileStreamOptionsInput = FileStreamOptions | Encoding | null | undefined;

function normalizeStreamOptions(options: FileStreamOptionsInput): FileStreamOptions {
  if (options === null || options === undefined) return {};
  if (typeof options === "string") {
    validateEncodingOption(options);
    return { encoding: options };
  }
  if (typeof options !== "object") {
    throw new ERR_INVALID_ARG_TYPE("options", ["string", "Object"], options);
  }
  validateEncodingOption(options.encoding);
  return options;
}

function checkPosition(value: number | undefined, name: string): void {
  if (value === undefined) return;
  validateInteger(value, name, 0, Number.MAX_SAFE_INTEGER);
}

function validateOpen(
  operations: StreamFSImplementation,
  required: boolean,
): void {
  if (required || operations.open !== undefined) {
    validateFunction(operations.open, "options.fs.open");
  }
}

function validateClose(
  operations: StreamFSImplementation,
  required: boolean,
): void {
  if (required || operations.close !== undefined) {
    validateFunction(operations.close, "options.fs.close");
  }
}

function isErrorCode(error: unknown, code: string): boolean {
  return error !== null && typeof error === "object" &&
    "code" in error && error.code === code;
}

function destroyFinishedWriteStream(this: WriteStream): void {
  this.destroy();
}

class WriteNoProgressError extends Error {
  readonly code = "ERR_SYSTEM_ERROR";

  constructor() {
    super("A system error occurred: write failed");
    this.name = "SystemError";
  }
}

interface PreparedReadStream {
  path: string | undefined;
  fd: number | null;
  fileHandle: StreamFileHandle | undefined;
  operations: StreamFSImplementation | undefined;
  flags: string;
  mode: number;
  autoClose: boolean;
  start: number | undefined;
  end: number;
}

interface PreparedWriteStream {
  path: string | undefined;
  fd: number | null;
  fileHandle: StreamFileHandle | undefined;
  operations: StreamFSImplementation | undefined;
  flags: string;
  mode: number;
  autoClose: boolean;
  start: number | undefined;
  flush: boolean;
}

function prepareDescriptor(
  path: string | null,
  suppliedDescriptor: number | StreamFileHandle | null | undefined,
  operations: StreamFSImplementation | undefined,
): {
  path: string | undefined;
  fd: number | null;
  fileHandle: StreamFileHandle | undefined;
} {
  if (suppliedDescriptor === null || suppliedDescriptor === undefined) {
    if (typeof path !== "string") {
      throw new ERR_INVALID_ARG_TYPE("path", ["string", "Buffer", "URL"], path);
    }
    return { path, fd: null, fileHandle: undefined };
  }
  if (typeof suppliedDescriptor === "number") {
    validateFileDescriptor(suppliedDescriptor);
    return { path: typeof path === "string" ? path : undefined, fd: suppliedDescriptor, fileHandle: undefined };
  }
  if (!isStreamFileHandle(suppliedDescriptor)) {
    throw new ERR_INVALID_ARG_TYPE("options.fd", ["number", "FileHandle"], suppliedDescriptor);
  }
  validateFileDescriptor(suppliedDescriptor.fd);
  if (operations !== undefined) {
    throw new ERR_METHOD_NOT_IMPLEMENTED("FileHandle with fs");
  }
  return {
    path: typeof path === "string" ? path : undefined,
    fd: suppliedDescriptor.fd,
    fileHandle: suppliedDescriptor,
  };
}

function prepareReadStream(
  path: string | null,
  options: FileStreamOptions,
): PreparedReadStream {
  if (options.signal !== undefined) {
    validateAbortSignal(options.signal, "options.signal");
  }
  checkPosition(options.start, "start");
  if (options.end !== Infinity) checkPosition(options.end, "end");
  if (
    options.start !== undefined && options.end !== undefined &&
    options.end < options.start
  ) {
    throw new ERR_OUT_OF_RANGE("start", `<= "end" (here: ${options.end})`, options.start);
  }

  const operations = options.fs ?? undefined;
  const descriptor = prepareDescriptor(path, options.fd, operations);
  const autoClose = options.autoClose ?? true;
  if (operations !== undefined) {
    validateOpen(operations, descriptor.fd === null);
    validateFunction(operations.read, "options.fs.read");
    validateClose(operations, autoClose);
  }
  return {
    ...descriptor,
    operations,
    flags: options.flags ?? "r",
    mode: options.mode ?? 0o666,
    autoClose,
    start: options.start,
    end: options.end ?? Infinity,
  };
}

function prepareWriteStream(
  path: string | null,
  options: FileStreamOptions,
): PreparedWriteStream {
  if (options.signal !== undefined) {
    validateAbortSignal(options.signal, "options.signal");
  }
  checkPosition(options.start, "start");
  const operations = options.fs ?? undefined;
  const descriptor = prepareDescriptor(path, options.fd, operations);
  const autoClose = options.autoClose ?? true;
  const flush = options.flush ?? false;
  if (options.flush !== null && options.flush !== undefined) {
    validateBoolean(options.flush, "options.flush");
  }
  if (operations !== undefined) {
    validateOpen(operations, descriptor.fd === null);
    if (operations.write === undefined && operations.writev === undefined) {
      validateFunction(operations.write, "options.fs.write");
    }
    if (operations.write !== undefined) {
      validateFunction(operations.write, "options.fs.write");
    }
    if (operations.writev !== undefined) {
      validateFunction(operations.writev, "options.fs.writev");
    }
    validateClose(operations, autoClose);
    if (flush) validateFunction(operations.fsync, "options.fs.fsync");
  }
  return {
    ...descriptor,
    operations,
    flags: options.flags ?? "w",
    mode: options.mode ?? 0o666,
    autoClose,
    start: options.start,
    flush,
  };
}

export class ReadStream extends Readable {
  path: string | undefined;
  fd: number | null;
  flags: string;
  mode: number;
  autoClose: boolean;
  start: number | undefined;
  end: number;
  pos: number | undefined;
  bytesRead = 0;
  #performingIo = false;
  #fileHandle: StreamFileHandle | undefined;
  #operations: StreamFSImplementation | undefined;
  #pendingDestroy: PendingDestroy | undefined;

  constructor(path: string | null, options?: FileStreamOptionsInput) {
    const normalized = normalizeStreamOptions(options);
    const prepared = prepareReadStream(path, normalized);
    super({
      // 64 KiB rather than the stream default, because a file read that costs
      // a system call should bring back enough to be worth the call.
      highWaterMark: normalized.highWaterMark ?? 64 * 1024,
      encoding: normalized.encoding,
      autoDestroy: normalized.autoClose ?? true,
      emitClose: normalized.emitClose ?? true,
    });

    this.path = prepared.path;
    this.fd = prepared.fd;
    this.#fileHandle = prepared.fileHandle;
    this.#operations = prepared.operations;
    this.flags = prepared.flags;
    this.mode = prepared.mode;
    this.autoClose = prepared.autoClose;
    this.start = prepared.start;
    this.end = prepared.end;
    // `pos` tracks where the next read starts, and only exists when a start
    // was given: without one, reads are sequential and the descriptor's own
    // offset is the position.
    this.pos = prepared.start;
    prepared.fileHandle?._refForStream();
    prepared.fileHandle?.on("close", () => this.close());
    if (normalized.signal !== null && normalized.signal !== undefined) {
      addAbortSignalNoValidate(normalized.signal, this);
    }
  }

  /** Whether the file is not open yet. */
  get pending(): boolean {
    return this.fd === null;
  }

  override _construct(callback: (error?: unknown) => void): void {
    if (typeof this.fd === "number") {
      callback();
      return;
    }
    const path = this.path;
    if (path === undefined) {
      callback(new ERR_INVALID_ARG_TYPE("path", ["string", "Buffer", "URL"], path));
      return;
    }
    const onOpen: StreamOpenCallback = (error, fd) => {
      if (error) {
        callback(error);
        return;
      }
      if (fd === undefined) {
        callback(new Error("fs open completed without a file descriptor"));
        return;
      }
      this.fd = fd;
      callback();
      this.emit("open", this.fd);
      this.emit("ready");
    };
    const operations = this.#operations;
    if (operations === undefined) {
      callbacks.open(path, this.flags, this.mode, onOpen);
    } else {
      if (operations.open === undefined) {
        callback(new Error("validated stream filesystem has no open operation"));
        return;
      }
      operations.open(path, this.flags, this.mode, onOpen);
    }
  }

  override _read(size: number): void {
    // Never read past `end`, which is inclusive as node's is.
    const wanted = this.pos !== undefined
      ? Math.min(this.end - this.pos + 1, size)
      : Math.min(this.end - this.bytesRead + 1, size);

    if (wanted <= 0) {
      this.push(null);
      return;
    }

    const buffer = Buffer.allocUnsafe(wanted);
    const fd = this.fd;
    if (fd === null) {
      this.destroy(new Error("fs read stream has no open file descriptor"));
      return;
    }
    this.#performingIo = true;

    const onRead: StreamReadCallback = (error, bytesRead) => {
      this.#performingIo = false;

      // Destroyed while this read was outstanding: `_destroy` is waiting to
      // hear that the descriptor is free.
      if (this.destroyed) {
        const pending = this.#pendingDestroy;
        this.#pendingDestroy = undefined;
        if (pending !== undefined) {
          closeStream(this, pending.error || error, pending.callback);
        }
        return;
      }

      if (error) {
        errorOrDestroy(this, error);
        return;
      }

      if (bytesRead === undefined) {
        errorOrDestroy(this, new Error("fs read completed without a byte count"));
        return;
      }
      const read = bytesRead;
      if (read > 0) {
        if (this.pos !== undefined) this.pos += read;
        this.bytesRead += read;
        // Copied rather than sliced when short: a slice keeps the whole
        // allocation alive, so a stream of small reads from a 64 KiB buffer
        // would retain 64 KiB per chunk.
        this.push(read === buffer.length ? buffer : Buffer.from(buffer.subarray(0, read)));
      } else {
        this.push(null);
      }
    };
    const operations = this.#operations;
    const handle = this.#fileHandle;
    if (handle !== undefined) {
      handle.read(buffer, 0, wanted, this.pos ?? null).then(
        (result) => onRead(null, result.bytesRead, result.buffer),
        (error: unknown) => onRead(error),
      );
      return;
    }
    if (operations === undefined) {
      callbacks.read(fd, buffer, 0, wanted, this.pos ?? null, onRead);
    } else {
      if (operations.read === undefined) {
        this.#performingIo = false;
        this.destroy(new Error("validated stream filesystem has no read operation"));
        return;
      }
      operations.read(fd, buffer, 0, wanted, this.pos ?? null, onRead);
    }
  }

  override _destroy(error: unknown, callback: (error?: unknown) => void): void {
    if (this.#performingIo) {
      this.#pendingDestroy = { error, callback };
    } else {
      closeStream(this, error, callback);
    }
  }

  _takeFileHandle(): StreamFileHandle | undefined {
    const handle = this.#fileHandle;
    this.#fileHandle = undefined;
    return handle;
  }

  _fileSystemOperations(): StreamFSImplementation | undefined {
    return this.#operations;
  }

  close(callback?: (error?: unknown) => void): void {
    if (typeof callback === "function") finished(this, callback);
    this.destroy();
  }

  /** Deprecated compatibility no-op retained by Node as `DEP0135`. */
  open(): void {
    warnReadStreamOpen();
  }
}

export class WriteStream extends Writable {
  path: string | undefined;
  fd: number | null;
  flags: string;
  mode: number;
  autoClose: boolean;
  start: number | undefined;
  pos: number | undefined;
  bytesWritten = 0;
  flush: boolean;
  #performingIo = false;
  #fileHandle: StreamFileHandle | undefined;
  #operations: StreamFSImplementation | undefined;
  #pendingDestroy: PendingDestroy | undefined;

  constructor(path: string | null, options?: FileStreamOptionsInput) {
    const normalized = normalizeStreamOptions(options);
    const prepared = prepareWriteStream(path, normalized);
    super({
      highWaterMark: normalized.highWaterMark ?? 16 * 1024,
      defaultEncoding: normalized.encoding ?? "utf8",
      autoDestroy: normalized.autoClose ?? true,
      emitClose: normalized.emitClose ?? true,
    });
    this._writev = this.#writeVector;

    this.path = prepared.path;
    this.fd = prepared.fd;
    this.#fileHandle = prepared.fileHandle;
    this.#operations = prepared.operations;
    this.flags = prepared.flags;
    this.mode = prepared.mode;
    this.autoClose = prepared.autoClose;
    this.start = prepared.start;
    this.pos = prepared.start;
    this.flush = prepared.flush;
    prepared.fileHandle?._refForStream();
    prepared.fileHandle?.on("close", () => this.close());
    if (normalized.signal !== null && normalized.signal !== undefined) {
      addAbortSignalNoValidate(normalized.signal, this);
    }
  }

  get pending(): boolean {
    return this.fd === null;
  }

  override _construct(callback: (error?: unknown) => void): void {
    if (typeof this.fd === "number") {
      callback();
      return;
    }
    const path = this.path;
    if (path === undefined) {
      callback(new ERR_INVALID_ARG_TYPE("path", ["string", "Buffer", "URL"], path));
      return;
    }
    const onOpen: StreamOpenCallback = (error, fd) => {
      if (error) {
        callback(error);
        return;
      }
      if (fd === undefined) {
        callback(new Error("fs open completed without a file descriptor"));
        return;
      }
      this.fd = fd;
      callback();
      this.emit("open", this.fd);
      this.emit("ready");
    };
    const operations = this.#operations;
    if (operations === undefined) {
      callbacks.open(path, this.flags, this.mode, onOpen);
    } else {
      if (operations.open === undefined) {
        callback(new Error("validated stream filesystem has no open operation"));
        return;
      }
      operations.open(path, this.flags, this.mode, onOpen);
    }
  }

  override _write(chunk: unknown, _encoding: string, callback: (error?: unknown) => void): void {
    if (!ArrayBuffer.isView(chunk)) {
      callback(new ERR_INVALID_ARG_TYPE("chunk", ["Buffer", "TypedArray", "DataView"], chunk));
      return;
    }
    const buffer = Buffer.from(new Uint8Array(chunk.buffer, chunk.byteOffset, chunk.byteLength));
    const fd = this.fd;
    if (fd === null) {
      callback(new Error("fs write stream has no open file descriptor"));
      return;
    }
    this.#performingIo = true;
    this.#writeAll(fd, buffer, this.pos ?? null, callback, 0);
  }

  /**
   * Flush buffered chunks with one vector syscall.
   *
   * Writable calls this only after it has already normalized byte-mode chunks,
   * so the fixed array below is both validation at the subclass boundary and
   * the exact vector handed to fs.writev. A partial vector write is completed
   * through the single-buffer retry path; resending the original vector would
   * duplicate the prefix already written.
   */
  #writeVector(chunks: BufferedWrite[], callback: WriteCallback): void {
    const buffers = new Array<Buffer>(chunks.length);
    let total = 0;
    for (let index = 0; index < chunks.length; index++) {
      const entry = chunks[index];
      if (entry === undefined || !ArrayBuffer.isView(entry.chunk)) {
        callback(new ERR_INVALID_ARG_TYPE(
          "chunk",
          ["Buffer", "TypedArray", "DataView"],
          entry?.chunk,
        ));
        return;
      }
      const chunk = entry.chunk;
      const buffer = Buffer.from(
        new Uint8Array(chunk.buffer, chunk.byteOffset, chunk.byteLength),
      );
      buffers[index] = buffer;
      total += buffer.length;
    }
    if (total === 0) {
      callback();
      return;
    }

    const fd = this.fd;
    if (fd === null) {
      callback(new Error("fs write stream has no open file descriptor"));
      return;
    }
    this.#performingIo = true;
    const position = this.pos ?? null;
    const onWritev: StreamWritevCallback = (receivedError, bytesWritten) => {
      let error = receivedError;
      let written = bytesWritten;
      if (isErrorCode(error, "EAGAIN")) {
        error = undefined;
        written = 0;
      }
      if (this.destroyed || error) {
        this.#finishWrite(error || new ERR_STREAM_DESTROYED("write"), callback);
        return;
      }
      if (
        written === undefined || !Number.isInteger(written) ||
        written < 0 || written > total
      ) {
        this.#finishWrite(
          new Error("fs writev completed with an invalid byte count"),
          callback,
        );
        return;
      }

      this.bytesWritten += written;
      if (this.pos !== undefined) this.pos += written;
      if (written < total) {
        const remaining = Buffer.concat(buffers).subarray(written);
        const nextPosition = position === null ? null : position + written;
        this.#writeAll(fd, remaining, nextPosition, callback, written === 0 ? 1 : 0);
        return;
      }
      this.#finishWrite(undefined, callback);
    };

    const handle = this.#fileHandle;
    if (handle !== undefined) {
      handle.writev(buffers, position).then(
        (result) => onWritev(null, result.bytesWritten, buffers),
        (error: unknown) => onWritev(error),
      );
      return;
    }
    const operations = this.#operations;
    if (operations === undefined) {
      callbacks.writev(fd, buffers, position, onWritev);
    } else if (operations.writev !== undefined) {
      operations.writev(fd, buffers, position, onWritev);
    } else {
      // A custom fs implementation may provide only write(). It still gets
      // the coalesced bytes once, rather than N separate calls.
      this.#writeAll(fd, Buffer.concat(buffers), position, callback, 0);
    }
  }

  #writeAll(
    fd: number,
    buffer: Buffer,
    position: number | null,
    callback: WriteCallback,
    retries: number,
  ): void {
    const onWrite: StreamWriteCallback = (receivedError, bytesWritten) => {
      let error = receivedError;
      let written = bytesWritten;
      if (isErrorCode(error, "EAGAIN")) {
        error = undefined;
        written = 0;
      }

      if (this.destroyed || error) {
        this.#finishWrite(error || new ERR_STREAM_DESTROYED("write"), callback);
        return;
      }
      if (written === undefined) {
        this.#finishWrite(new Error("fs write completed without a byte count"), callback);
        return;
      }
      if (!Number.isInteger(written) || written < 0 || written > buffer.length) {
        this.#finishWrite(new Error("fs write completed with an invalid byte count"), callback);
        return;
      }

      this.bytesWritten += written;
      if (this.pos !== undefined) this.pos += written;
      const nextRetries = written === 0 ? retries + 1 : 0;
      if (nextRetries > 5) {
        this.#finishWrite(new WriteNoProgressError(), callback);
        return;
      }
      if (written < buffer.length) {
        const nextPosition = position === null ? null : position + written;
        this.#writeAll(fd, buffer.subarray(written), nextPosition, callback, nextRetries);
        return;
      }
      this.#finishWrite(undefined, callback);
    };

    const operations = this.#operations;
    const handle = this.#fileHandle;
    if (handle !== undefined) {
      handle.write(buffer, 0, buffer.length, position).then(
        (result) => onWrite(null, result.bytesWritten, result.buffer),
        (error: unknown) => onWrite(error),
      );
      return;
    }
    if (operations === undefined) {
      callbacks.write(fd, buffer, 0, buffer.length, position, onWrite);
      return;
    }
    if (operations.write !== undefined) {
      operations.write(fd, buffer, 0, buffer.length, position, onWrite);
      return;
    }
    if (operations.writev === undefined) {
      this.#finishWrite(new Error("validated stream filesystem has no write operation"), callback);
      return;
    }
    const onWritev: StreamWritevCallback = (error, bytesWritten) => {
      onWrite(error, bytesWritten, buffer);
    };
    operations.writev(fd, [buffer], position, onWritev);
  }

  #finishWrite(error: unknown, callback: WriteCallback): void {
    this.#performingIo = false;
    if (this.destroyed) {
      callback(error);
      const pending = this.#pendingDestroy;
      this.#pendingDestroy = undefined;
      if (pending !== undefined) {
        closeStream(this, pending.error || error, pending.callback);
      }
      return;
    }
    callback(error);
  }

  override _destroy(error: unknown, callback: (error?: unknown) => void): void {
    if (this.#performingIo) {
      this.#pendingDestroy = { error, callback };
    } else {
      closeStream(this, error, callback);
    }
  }

  _takeFileHandle(): StreamFileHandle | undefined {
    const handle = this.#fileHandle;
    this.#fileHandle = undefined;
    return handle;
  }

  _fileSystemOperations(): StreamFSImplementation | undefined {
    return this.#operations;
  }

  close(callback?: (error?: unknown) => void): void {
    if (typeof callback === "function") {
      if (this.closed) {
        nextTick(callback);
        return;
      }
      this.on("close", callback);
    }
    if (!this.autoClose) this.on("finish", destroyFinishedWriteStream);
    this.end();
  }

  /** Deprecated compatibility no-op retained by Node as `DEP0135`. */
  open(): void {
    warnWriteStreamOpen();
  }

  /**
   * Node's older name for `end`, kept because programs still call it.
   *
   * It answers what `end` answers -- the stream -- because upstream it *is* `end`:
   * `WriteStream.prototype.destroySoon = WriteStream.prototype.end`, one function
   * under two names. This wrapped it and dropped the return, so a caller chaining
   * off `destroySoon()` got `undefined` where node gives back the stream.
   */
  destroySoon(): this {
    return this.end();
  }
}

/**
 * Close the descriptor, unless the stream does not own it.
 *
 * `autoClose: false` is for a caller that passed its own `fd` and intends to
 * keep using it; closing it out from under them would be the stream taking
 * ownership it was explicitly not given.
 */
function closeStream(
  stream: ReadStream | WriteStream,
  error: unknown,
  callback: (error?: unknown) => void,
): void {
  if (!stream.autoClose || stream.fd === null) {
    callback(error);
    return;
  }
  const fd = stream.fd;
  if (stream instanceof WriteStream && stream.flush) {
    const handle = stream._takeFileHandle();
    if (handle !== undefined) {
      handle.sync().then(
        () => closeFileDescriptor(stream, fd, handle, error, callback),
        (flushError: unknown) => {
          closeFileDescriptor(stream, fd, handle, error || flushError, callback);
        },
      );
      return;
    }
    const operations = stream._fileSystemOperations();
    const onSync: StreamCloseCallback = (flushError) => {
      closeFileDescriptor(stream, fd, undefined, error || flushError, callback);
    };
    if (operations === undefined) {
      callbacks.fsync(fd, onSync);
      return;
    }
    if (operations.fsync === undefined) {
      callback(new Error("validated stream filesystem has no fsync operation"));
      return;
    }
    operations.fsync(fd, onSync);
    return;
  }
  closeFileDescriptor(stream, fd, stream._takeFileHandle(), error, callback);
}

function closeFileDescriptor(
  stream: ReadStream | WriteStream,
  fd: number,
  handle: StreamFileHandle | undefined,
  error: unknown,
  callback: (error?: unknown) => void,
): void {
  if (handle !== undefined) {
    handle._unrefForStream();
    handle.close().then(
      () => callback(error),
      (closeError: unknown) => callback(error || closeError),
    );
    stream.fd = null;
    return;
  }
  const operations = stream._fileSystemOperations();
  const onClose: StreamCloseCallback = (closeError) => callback(error || closeError);
  if (operations === undefined) {
    callbacks.close(fd, onClose);
  } else {
    if (operations.close === undefined) {
      callback(new Error("validated stream filesystem has no close operation"));
      return;
    }
    operations.close(fd, onClose);
  }
  // Node clears `fd` after dispatching close. A custom implementation may
  // inspect the stream synchronously from inside `close`, and then sees the
  // descriptor it was asked to close.
  stream.fd = null;
}

export function createReadStream(path: string | null, options?: FileStreamOptionsInput): ReadStream {
  return new ReadStream(path, options);
}

export function createWriteStream(path: string | null, options?: FileStreamOptionsInput): WriteStream {
  return new WriteStream(path, options);
}

// `fs.Utf8Stream`, from Node v24.20.0
// `lib/internal/streams/fast-utf8-stream.js`.
//
// This is Node's buffered UTF-8 writer, with its state expressed as two
// statically typed queues. UTF-8 mode stores strings; buffer mode stores
// bounded batches of Buffers plus their byte lengths. Keeping those queues
// separate makes an impossible mixed-content state unrepresentable and avoids
// the casts a direct transcription of Node's dynamically typed `#bufs` needs.

import { Buffer } from "../../buffer/src/main.ts";
import { EventEmitter } from "../../events/src/main.ts";
import { dirname } from "../../path/src/posix.ts";
import { clearInterval, setInterval, setTimeout } from "../../timers/src/main.ts";
import type { Timeout } from "../../timers/src/timeout.ts";
import { nextTick } from "../../internal/tick.ts";
import { sleep } from "../../internal/sleep.ts";
import {
  ERR_INVALID_ARG_TYPE,
  ERR_INVALID_ARG_VALUE_RANGE,
  ERR_INVALID_STATE,
  ERR_OPERATION_FAILED,
} from "../../internal/errors.ts";
import {
  validateBoolean,
  validateFunction,
  validateObject,
  validateOneOf,
  validateString,
  validateUint32,
} from "../../internal/validators.ts";
import {
  close as fsClose,
  fsync as fsFsync,
  mkdir as fsMkdir,
  open as fsOpen,
  write as fsWrite,
} from "./async.ts";
import {
  fsyncSync as fsFsyncSync,
  mkdirSync as fsMkdirSync,
  openSync as fsOpenSync,
  writeSync as fsWriteSync,
} from "./main.ts";

const BUSY_WRITE_TIMEOUT = 100;
const MAX_WRITE = 16 * 1024;
const HIGH_WATER_MARK = 16_387;
const EMPTY_BUFFER = Buffer.allocUnsafe(0);

type Utf8StreamContentMode = "buffer" | "utf8";

interface Utf8StreamSystemError extends Error {
  code?: string | undefined;
}

type Utf8StreamErrorCallback = (
  error?: Utf8StreamSystemError | null,
) => void;

type Utf8StreamWriteCallback = (
  error?: Utf8StreamSystemError | null,
  written?: number,
) => void;

/**
 * The filesystem operations Utf8Stream consumes.
 *
 * Node deliberately supports overriding any subset for fault injection and
 * specialised destinations. This names that structural contract instead of
 * accepting an untyped `object`; JavaScript callers still receive the same
 * runtime validation, while TypeScript callers get the signatures involved.
 */
interface Utf8StreamFileSystem {
  write(fd: number, data: Buffer, callback: Utf8StreamWriteCallback): void;
  write(
    fd: number,
    data: string,
    encoding: "utf8",
    callback: Utf8StreamWriteCallback,
  ): void;
  writeSync(fd: number, data: Buffer): number;
  writeSync(fd: number, data: string, encoding: "utf8"): number;
  fsync(fd: number, callback: Utf8StreamErrorCallback): void;
  fsyncSync(fd: number): void;
  close(fd: number, callback: Utf8StreamErrorCallback): void;
  open(
    path: string,
    flags: "a" | "w",
    mode: number | string | undefined,
    callback: (error: Utf8StreamSystemError | null, fd?: number) => void,
  ): void;
  openSync(
    path: string,
    flags: "a" | "w",
    mode: number | string | undefined,
  ): number;
  mkdir(
    path: string,
    options: { recursive: true },
    callback: Utf8StreamErrorCallback,
  ): void;
  mkdirSync(path: string, options: { recursive: true }): string | undefined;
}

export interface Utf8StreamOptions {
  append?: boolean | undefined;
  contentMode?: Utf8StreamContentMode | undefined;
  dest?: string | undefined;
  fd?: number | undefined;
  fs?: Partial<Utf8StreamFileSystem> | undefined;
  fsync?: boolean | undefined;
  maxLength?: number | undefined;
  maxWrite?: number | undefined;
  minLength?: number | undefined;
  mkdir?: boolean | undefined;
  mode?: number | string | undefined;
  periodicFlush?: number | undefined;
  retryEAGAIN?: (
    error: Error | null,
    writeBufferLength: number,
    remainingBufferLength: number,
  ) => boolean;
  sync?: boolean | undefined;
}

function normalizeSystemError(error: unknown): Utf8StreamSystemError | null {
  if (error === null || error === undefined) return null;
  if (error instanceof Error) return error;
  return new ERR_OPERATION_FAILED(String(error));
}

const defaultFileSystem: Utf8StreamFileSystem = {
  write(
    fd: number,
    data: string | Buffer,
    encodingOrCallback: "utf8" | Utf8StreamWriteCallback,
    suppliedCallback?: Utf8StreamWriteCallback,
  ): void {
    const callback = typeof encodingOrCallback === "function"
      ? encodingOrCallback
      : suppliedCallback;
    if (callback === undefined) {
      throw new ERR_INVALID_ARG_TYPE("callback", "Function", callback);
    }
    const complete = (error: unknown, written?: number): void => {
      callback(normalizeSystemError(error), written);
    };
    if (typeof data === "string") fsWrite(fd, data, null, "utf8", complete);
    else fsWrite(fd, data, complete);
  },

  writeSync(fd: number, data: string | Buffer, encoding?: "utf8"): number {
    return typeof data === "string"
      ? fsWriteSync(fd, data, null, encoding)
      : fsWriteSync(fd, data);
  },

  fsync(fd: number, callback: Utf8StreamErrorCallback): void {
    fsFsync(fd, (error: unknown) => callback(normalizeSystemError(error)));
  },

  fsyncSync: fsFsyncSync,

  close(fd: number, callback: Utf8StreamErrorCallback): void {
    fsClose(fd, (error: unknown) => callback(normalizeSystemError(error)));
  },

  open(
    path: string,
    flags: "a" | "w",
    mode: number | string | undefined,
    callback: (error: Utf8StreamSystemError | null, fd?: number) => void,
  ): void {
    fsOpen(path, flags, mode, (error: unknown, fd?: number) => {
      callback(normalizeSystemError(error), fd);
    });
  },

  openSync: fsOpenSync,

  mkdir(
    path: string,
    options: { recursive: true },
    callback: Utf8StreamErrorCallback,
  ): void {
    fsMkdir(path, options, (error: unknown) => callback(normalizeSystemError(error)));
  },

  mkdirSync: fsMkdirSync,
};

function completeFileSystem(
  override: Partial<Utf8StreamFileSystem>,
): Utf8StreamFileSystem {
  return {
    write: override.write === undefined ? defaultFileSystem.write : override.write,
    writeSync: override.writeSync === undefined
      ? defaultFileSystem.writeSync
      : override.writeSync,
    fsync: override.fsync === undefined ? defaultFileSystem.fsync : override.fsync,
    fsyncSync: override.fsyncSync === undefined
      ? defaultFileSystem.fsyncSync
      : override.fsyncSync,
    close: override.close === undefined ? defaultFileSystem.close : override.close,
    open: override.open === undefined ? defaultFileSystem.open : override.open,
    openSync: override.openSync === undefined
      ? defaultFileSystem.openSync
      : override.openSync,
    mkdir: override.mkdir === undefined ? defaultFileSystem.mkdir : override.mkdir,
    mkdirSync: override.mkdirSync === undefined
      ? defaultFileSystem.mkdirSync
      : override.mkdirSync,
  };
}

function noopFlush(_error?: Utf8StreamSystemError | null): void {}

function retriesBusyError(error: Utf8StreamSystemError | null | undefined): boolean {
  return error?.code === "EAGAIN" || error?.code === "EBUSY";
}

function releaseUtf8Buffer(
  writingBuffer: string,
  bufferedLength: number,
  bytesWritten: number | undefined,
): { writingBuffer: string; bufferedLength: number } {
  // Custom synchronous fs implementations in Node's supported override
  // contract sometimes forward a successful write without returning its byte
  // count. Node's string path treats that as a complete write (through
  // Buffer.subarray's omitted-end semantics), and its own retry fixture relies
  // on it. Make that normalization explicit instead of depending on an
  // `undefined` arithmetic side effect.
  let charactersWritten = bytesWritten ?? writingBuffer.length;
  const byteLength = Buffer.byteLength(writingBuffer);
  if (byteLength === bytesWritten) {
    charactersWritten = writingBuffer.length;
  } else {
    // A partial native write may stop inside one UTF-8 code point. Back up to
    // its leading byte, then count the complete UTF-16 characters before it.
    const encoded = Buffer.from(writingBuffer);
    while (charactersWritten > 0) {
      const byte = encoded[charactersWritten];
      if (byte === undefined || (byte & 0xc0) !== 0x80) break;
      charactersWritten -= 1;
    }
    charactersWritten = encoded.subarray(0, charactersWritten).toString().length;
  }
  return {
    writingBuffer: writingBuffer.slice(charactersWritten),
    bufferedLength: Math.max(bufferedLength - charactersWritten, 0),
  };
}

function mergeBufferBatch(batch: Buffer[] | undefined, length: number | undefined): Buffer {
  if (batch === undefined || batch.length === 0) return EMPTY_BUFFER;
  if (batch.length === 1) return batch[0] ?? EMPTY_BUFFER;
  return Buffer.concat(batch, length);
}

/** Node's high-throughput buffered UTF-8 file writer. */
export class Utf8Stream extends EventEmitter {
  #bufferedLength = 0;
  #fd = -1;
  #utf8Buffers: string[] = [];
  #bufferBatches: Buffer[][] = [];
  #bufferBatchLengths: number[] = [];
  #writingUtf8 = "";
  #writingBuffer = EMPTY_BUFFER;
  #writing = false;
  #ending = false;
  #reopening = false;
  #asyncDrainScheduled = false;
  #flushPending = false;
  #highWaterMark = HIGH_WATER_MARK;
  #file: string | undefined;
  #destroyed = false;
  #minLength = 0;
  #maxLength = 0;
  #maxWrite = MAX_WRITE;
  #opening = false;
  #periodicFlush = 0;
  #periodicFlushTimer: Timeout<[]> | undefined;
  #sync = false;
  #fsync = false;
  #append = true;
  #mode: number | string | undefined;
  #retryEAGAIN: NonNullable<Utf8StreamOptions["retryEAGAIN"]> = () => true;
  #mkdir = false;
  readonly #contentMode: Utf8StreamContentMode;
  readonly #fs: Utf8StreamFileSystem;

  constructor(options: Utf8StreamOptions);
  constructor(options: Utf8StreamOptions = {}) {
    validateObject(options, "options");
    super();

    const {
      dest,
      minLength,
      maxLength,
      maxWrite,
      periodicFlush,
      sync,
      append = true,
      mkdir,
      retryEAGAIN,
      fsync,
      contentMode = "utf8",
      mode,
      fs: overrideFileSystem = {},
    } = options;
    const fd: number | string | undefined = options.fd ?? dest;

    validateObject(overrideFileSystem, "options.fs");
    this.#fs = completeFileSystem(overrideFileSystem);
    validateFunction(this.#fs.write, "options.fs.write");
    validateFunction(this.#fs.writeSync, "options.fs.writeSync");
    validateFunction(this.#fs.fsync, "options.fs.fsync");
    validateFunction(this.#fs.fsyncSync, "options.fs.fsyncSync");
    validateFunction(this.#fs.close, "options.fs.close");
    validateFunction(this.#fs.open, "options.fs.open");
    validateFunction(this.#fs.mkdir, "options.fs.mkdir");
    validateFunction(this.#fs.mkdirSync, "options.fs.mkdirSync");

    this.#highWaterMark = Math.max(minLength || 0, this.#highWaterMark);
    this.#minLength = minLength || 0;
    this.#maxLength = maxLength || 0;
    this.#maxWrite = maxWrite || MAX_WRITE;
    this.#periodicFlush = periodicFlush || 0;
    this.#sync = sync || false;
    this.#fsync = fsync || false;
    this.#append = append || false;
    this.#mode = mode;
    this.#retryEAGAIN = retryEAGAIN || (() => true);
    this.#mkdir = mkdir || false;
    this.#contentMode = contentMode;

    validateUint32(this.#highWaterMark, "options.hwm");
    validateUint32(this.#minLength, "options.minLength");
    validateUint32(this.#maxLength, "options.maxLength");
    validateUint32(this.#maxWrite, "options.maxWrite");
    validateUint32(this.#periodicFlush, "options.periodicFlush");
    validateBoolean(this.#sync, "options.sync");
    validateBoolean(this.#fsync, "options.fsync");
    validateBoolean(this.#append, "options.append");
    validateBoolean(this.#mkdir, "options.mkdir");
    validateFunction(this.#retryEAGAIN, "options.retryEAGAIN");
    validateOneOf(this.#contentMode, "options.contentMode", ["buffer", "utf8"]);

    if (typeof fd === "number") {
      this.#fd = fd;
      nextTick(() => this.emit("ready"));
    } else if (typeof fd === "string") {
      this.#openFile(fd);
    } else {
      throw new ERR_INVALID_ARG_TYPE("fd", ["number", "string"], fd);
    }

    if (this.#minLength >= this.#maxWrite) {
      throw new ERR_INVALID_ARG_VALUE_RANGE(
        "minLength",
        this.#minLength,
        `should be smaller than maxWrite (${this.#maxWrite})`,
      );
    }

    this.on("newListener", (name: unknown) => {
      if (name === "drain") this.#asyncDrainScheduled = false;
    });

    if (this.#periodicFlush !== 0) {
      this.#periodicFlushTimer = setInterval(
        () => this.flush(),
        this.#periodicFlush,
      );
      this.#periodicFlushTimer.unref();
    }
  }

  write(data: string | Buffer): boolean {
    return this.#contentMode === "buffer"
      ? this.#writeBuffer(data)
      : this.#writeUtf8(data);
  }

  flush(callback: Utf8StreamErrorCallback = noopFlush): void {
    validateFunction(callback, "cb");
    if (this.#contentMode === "buffer") this.#flushBuffer(callback);
    else this.#flushUtf8(callback);
  }

  flushSync(): void {
    if (this.#contentMode === "buffer") this.#flushBufferSync();
    else this.#flushUtf8Sync();
  }

  reopen(file?: string): void {
    if (this.#destroyed) throw new ERR_INVALID_STATE("Utf8Stream is destroyed");
    if (this.#opening) {
      this.once("ready", () => this.reopen(file));
      return;
    }
    if (this.#ending) return;
    if (this.#file === undefined) {
      throw new ERR_OPERATION_FAILED(
        "Unable to reopen a file descriptor, you must pass a file to SonicBoom",
      );
    }
    if (file) this.#file = file;
    this.#reopening = true;
    if (this.#writing) return;

    const oldFd = this.#fd;
    this.once("ready", () => {
      if (oldFd !== this.#fd) {
        this.#fs.close(oldFd, (error?: Utf8StreamSystemError | null) => {
          if (error) this.emit("error", error);
        });
      }
    });
    this.#openFile(this.#file);
  }

  end(): void {
    if (this.#destroyed) throw new ERR_INVALID_STATE("Utf8Stream is destroyed");
    if (this.#opening) {
      this.once("ready", () => this.end());
      return;
    }
    if (this.#ending) return;
    this.#ending = true;
    if (this.#writing) return;
    if (this.#bufferedLength > 0 && this.#fd >= 0) this.#actualWrite();
    else this.#actualClose();
  }

  destroy(): void {
    if (!this.#destroyed) this.#actualClose();
  }

  get mode(): number | string | undefined { return this.#mode; }
  get file(): string | undefined { return this.#file; }
  get fd(): number { return this.#fd; }
  get minLength(): number { return this.#minLength; }
  get maxLength(): number { return this.#maxLength; }
  get writing(): boolean { return this.#writing; }
  get sync(): boolean { return this.#sync; }
  get fsync(): boolean { return this.#fsync; }
  get append(): boolean { return this.#append; }
  get periodicFlush(): number { return this.#periodicFlush; }
  get contentMode(): Utf8StreamContentMode { return this.#contentMode; }
  get mkdir(): boolean { return this.#mkdir; }

  [Symbol.dispose](): void { this.destroy(); }

  #currentWritingLength(): number {
    return this.#contentMode === "buffer"
      ? this.#writingBuffer.length
      : this.#writingUtf8.length;
  }

  #hasWritingData(): boolean {
    return this.#currentWritingLength() !== 0;
  }

  #release(
    error?: Utf8StreamSystemError | null,
    written?: number,
  ): void {
    if (error) {
      const writingLength = this.#currentWritingLength();
      if (
        retriesBusyError(error) &&
        this.#retryEAGAIN(
          error,
          writingLength,
          this.#bufferedLength - writingLength,
        )
      ) {
        if (this.#sync) {
          try {
            sleep(BUSY_WRITE_TIMEOUT);
            this.#release(undefined, 0);
          } catch (retryError) {
            this.#release(normalizeSystemError(retryError));
          }
        } else {
          setTimeout(() => this.#writeCurrentAsync(), BUSY_WRITE_TIMEOUT);
        }
      } else {
        this.#writing = false;
        this.emit("error", error);
      }
      return;
    }

    this.emit("write", written);
    if (this.#contentMode === "buffer") {
      const bytesWritten = written ?? 0;
      this.#bufferedLength = Math.max(this.#bufferedLength - bytesWritten, 0);
      this.#writingBuffer = this.#writingBuffer.subarray(bytesWritten);
    } else {
      const released = releaseUtf8Buffer(
        this.#writingUtf8,
        this.#bufferedLength,
        written,
      );
      this.#writingUtf8 = released.writingBuffer;
      this.#bufferedLength = released.bufferedLength;
    }

    if (this.#hasWritingData()) {
      if (!this.#sync) {
        this.#writeCurrentAsync();
        return;
      }
      try {
        do {
          const count = this.#writeCurrentSync();
          if (this.#contentMode === "buffer") {
            this.#bufferedLength = Math.max(this.#bufferedLength - count, 0);
            this.#writingBuffer = this.#writingBuffer.subarray(count);
          } else {
            const released = releaseUtf8Buffer(
              this.#writingUtf8,
              this.#bufferedLength,
              count,
            );
            this.#writingUtf8 = released.writingBuffer;
            this.#bufferedLength = released.bufferedLength;
          }
        } while (this.#hasWritingData());
      } catch (writeError) {
        this.#release(normalizeSystemError(writeError));
        return;
      }
    }

    if (this.#fsync) this.#fs.fsyncSync(this.#fd);

    const remaining = this.#bufferedLength;
    if (this.#reopening) {
      this.#writing = false;
      this.#reopening = false;
      this.reopen();
    } else if (remaining > this.#minLength) {
      this.#actualWrite();
    } else if (this.#ending) {
      if (remaining > 0) this.#actualWrite();
      else {
        this.#writing = false;
        this.#actualClose();
      }
    } else {
      this.#writing = false;
      if (this.#sync) {
        if (!this.#asyncDrainScheduled) {
          this.#asyncDrainScheduled = true;
          nextTick(() => this.#emitDrain());
        }
      } else {
        this.emit("drain");
      }
    }
  }

  #openFile(file: string): void {
    this.#opening = true;
    this.#writing = true;
    this.#asyncDrainScheduled = false;

    const fileOpened = (
      error: Utf8StreamSystemError | null,
      fd?: number,
    ): void => {
      if (error) {
        this.#reopening = false;
        this.#writing = false;
        this.#opening = false;
        if (this.#sync) {
          nextTick(() => {
            if (this.listenerCount("error") > 0) this.emit("error", error);
          });
        } else {
          this.emit("error", error);
        }
        return;
      }
      if (fd === undefined) {
        this.emit("error", new ERR_OPERATION_FAILED("fs.open returned no file descriptor"));
        return;
      }

      const reopening = this.#reopening;
      this.#fd = fd;
      this.#file = file;
      this.#reopening = false;
      this.#opening = false;
      this.#writing = false;

      if (this.#sync) nextTick(() => this.emit("ready"));
      else this.emit("ready");

      if (this.#destroyed) return;
      if ((!this.#writing && this.#bufferedLength > this.#minLength) || this.#flushPending) {
        this.#actualWrite();
      } else if (reopening) {
        nextTick(() => this.emit("drain"));
      }
    };

    const flags = this.#append ? "a" : "w";
    if (this.#sync) {
      try {
        if (this.#mkdir) this.#fs.mkdirSync(dirname(file), { recursive: true });
        fileOpened(null, this.#fs.openSync(file, flags, this.#mode));
      } catch (openError) {
        const error = normalizeSystemError(openError);
        fileOpened(error);
        throw openError;
      }
    } else if (this.#mkdir) {
      this.#fs.mkdir(dirname(file), { recursive: true }, (error) => {
        if (error) fileOpened(error);
        else this.#fs.open(file, flags, this.#mode, fileOpened);
      });
    } else {
      this.#fs.open(file, flags, this.#mode, fileOpened);
    }
  }

  #emitDrain(): void {
    if (this.listenerCount("drain") === 0) return;
    this.#asyncDrainScheduled = false;
    this.emit("drain");
  }

  #actualClose(): void {
    if (this.#fd === -1) {
      this.once("ready", () => this.#actualClose());
      return;
    }
    if (this.#periodicFlushTimer !== undefined) {
      clearInterval(this.#periodicFlushTimer);
    }
    this.#destroyed = true;
    this.#utf8Buffers = [];
    this.#bufferBatches = [];
    this.#bufferBatchLengths = [];

    const done = (error?: Utf8StreamSystemError | null): void => {
      if (error) {
        this.emit("error", error);
        return;
      }
      if (this.#ending && !this.#writing) this.emit("finish");
      this.emit("close");
    };
    const close = (): void => {
      if (this.#fd !== 1 && this.#fd !== 2) this.#fs.close(this.#fd, done);
      else done();
    };
    try {
      this.#fs.fsync(this.#fd, close);
    } catch {
      // Node deliberately ignores a synchronous fsync failure while closing.
    }
  }

  #actualWrite(): void {
    this.#writing = true;
    if (this.#contentMode === "buffer") {
      if (this.#writingBuffer.length === 0) {
        this.#writingBuffer = mergeBufferBatch(
          this.#bufferBatches.shift(),
          this.#bufferBatchLengths.shift(),
        );
      }
    } else if (this.#writingUtf8.length === 0) {
      this.#writingUtf8 = this.#utf8Buffers.shift() ?? "";
    }

    if (this.#sync) {
      try {
        this.#release(null, this.#writeCurrentSync());
      } catch (writeError) {
        this.#release(normalizeSystemError(writeError));
      }
    } else {
      this.#writeCurrentAsync();
    }
  }

  #writeCurrentSync(): number {
    return this.#contentMode === "buffer"
      ? this.#fs.writeSync(this.#fd, this.#writingBuffer)
      : this.#fs.writeSync(this.#fd, this.#writingUtf8, "utf8");
  }

  #writeCurrentAsync(): void {
    if (this.#contentMode === "buffer") {
      this.#fs.write(this.#fd, this.#writingBuffer, (error, written) => {
        this.#release(error, written);
      });
    } else {
      this.#fs.write(this.#fd, this.#writingUtf8, "utf8", (error, written) => {
        this.#release(error, written);
      });
    }
  }

  #requireFlushable(): void {
    if (this.#destroyed) throw new ERR_INVALID_STATE("Utf8Stream is destroyed");
    if (this.#fd < 0) throw new ERR_INVALID_STATE("Invalid file descriptor");
  }

  #flushBufferSync(): void {
    this.#requireFlushable();
    if (!this.#writing && this.#writingBuffer.length > 0) {
      this.#bufferBatches.unshift([this.#writingBuffer]);
      this.#bufferBatchLengths.unshift(this.#writingBuffer.length);
      this.#writingBuffer = EMPTY_BUFFER;
    }

    let buffer = EMPTY_BUFFER;
    while (this.#bufferBatches.length > 0 || buffer.length > 0) {
      if (buffer.length === 0) {
        buffer = mergeBufferBatch(
          this.#bufferBatches[0],
          this.#bufferBatchLengths[0],
        );
      }
      try {
        const written = this.#fs.writeSync(this.#fd, buffer);
        buffer = buffer.subarray(written);
        this.#bufferedLength = Math.max(this.#bufferedLength - written, 0);
        if (buffer.length === 0) {
          this.#bufferBatches.shift();
          this.#bufferBatchLengths.shift();
        }
      } catch (writeError) {
        const error = normalizeSystemError(writeError);
        if (retriesBusyError(error)) {
          if (!this.#retryEAGAIN(
            error,
            buffer.length,
            this.#bufferedLength - buffer.length,
          )) throw writeError;
        }
        sleep(BUSY_WRITE_TIMEOUT);
      }
    }
  }

  #flushUtf8Sync(): void {
    this.#requireFlushable();
    if (!this.#writing && this.#writingUtf8.length > 0) {
      this.#utf8Buffers.unshift(this.#writingUtf8);
      this.#writingUtf8 = "";
    }

    let buffer = "";
    while (this.#utf8Buffers.length > 0 || buffer.length > 0) {
      if (buffer.length === 0) buffer = this.#utf8Buffers[0] ?? "";
      try {
        const written = this.#fs.writeSync(this.#fd, buffer, "utf8");
        const released = releaseUtf8Buffer(buffer, this.#bufferedLength, written);
        buffer = released.writingBuffer;
        this.#bufferedLength = released.bufferedLength;
        if (buffer.length === 0) this.#utf8Buffers.shift();
      } catch (writeError) {
        const error = normalizeSystemError(writeError);
        if (retriesBusyError(error)) {
          if (!this.#retryEAGAIN(
            error,
            buffer.length,
            this.#bufferedLength - buffer.length,
          )) throw writeError;
        }
        sleep(BUSY_WRITE_TIMEOUT);
      }
    }

    try {
      this.#fs.fsyncSync(this.#fd);
    } catch {
      // The descriptor may not support fsync; Node intentionally ignores it.
    }
  }

  #callFlushCallbackOnDrain(callback: Utf8StreamErrorCallback): void {
    this.#flushPending = true;
    const onDrain = (): void => {
      if (!this.#fsync && !this.#destroyed) {
        try {
          this.#fs.fsync(this.#fd, (error) => {
            this.#flushPending = false;
            callback(error?.code === "EBADF" ? undefined : error);
          });
        } catch (flushError) {
          this.#flushPending = false;
          callback(normalizeSystemError(flushError));
        }
      } else {
        this.#flushPending = false;
        callback();
      }
      this.off("error", onError);
    };
    const onError = (error: Utf8StreamSystemError): void => {
      this.#flushPending = false;
      callback(error);
      this.off("drain", onDrain);
    };
    this.once("drain", onDrain);
    this.once("error", onError);
  }

  #flushBuffer(callback: Utf8StreamErrorCallback): void {
    if (this.#destroyed) {
      callback(new ERR_INVALID_STATE("Utf8Stream is destroyed"));
      return;
    }
    if (this.#minLength <= 0) {
      callback();
      return;
    }
    this.#callFlushCallbackOnDrain(callback);
    if (this.#writing) return;
    if (this.#bufferBatches.length === 0) {
      this.#bufferBatches.push([]);
      this.#bufferBatchLengths.push(0);
    }
    this.#actualWrite();
  }

  #flushUtf8(callback: Utf8StreamErrorCallback): void {
    if (this.#destroyed) {
      callback(new ERR_INVALID_STATE("Utf8Stream is destroyed"));
      return;
    }
    if (this.#minLength <= 0) {
      callback();
      return;
    }
    this.#callFlushCallbackOnDrain(callback);
    if (this.#writing) return;
    if (this.#utf8Buffers.length === 0) this.#utf8Buffers.push("");
    this.#actualWrite();
  }

  #writeBuffer(data: string | Buffer): boolean {
    if (this.#destroyed) throw new ERR_INVALID_STATE("Utf8Stream is destroyed");
    if (!Buffer.isBuffer(data)) {
      throw new ERR_INVALID_ARG_TYPE("data", "Buffer", data);
    }

    const nextLength = this.#bufferedLength + data.length;
    if (this.#maxLength !== 0 && nextLength > this.#maxLength) {
      this.emit("drop", data);
      return this.#bufferedLength < this.#highWaterMark;
    }

    const lastBatch = this.#bufferBatches[this.#bufferBatches.length - 1];
    const lastLength = this.#bufferBatchLengths[this.#bufferBatchLengths.length - 1];
    if (
      lastBatch === undefined ||
      lastLength === undefined ||
      lastLength + data.length > this.#maxWrite
    ) {
      this.#bufferBatches.push([data]);
      this.#bufferBatchLengths.push(data.length);
    } else {
      lastBatch.push(data);
      this.#bufferBatchLengths[this.#bufferBatchLengths.length - 1] =
        lastLength + data.length;
    }

    this.#bufferedLength = nextLength;
    if (!this.#writing && this.#bufferedLength >= this.#minLength) {
      this.#actualWrite();
    }
    return this.#bufferedLength < this.#highWaterMark;
  }

  #writeUtf8(data: string | Buffer): boolean {
    if (this.#destroyed) throw new ERR_INVALID_STATE("Utf8Stream is destroyed");
    validateString(data, "data");

    const nextLength = this.#bufferedLength + data.length;
    if (this.#maxLength !== 0 && nextLength > this.#maxLength) {
      this.emit("drop", data);
      return this.#bufferedLength < this.#highWaterMark;
    }

    const lastIndex = this.#utf8Buffers.length - 1;
    const last = this.#utf8Buffers[lastIndex];
    if (last === undefined || last.length + data.length > this.#maxWrite) {
      this.#utf8Buffers.push(data);
    } else {
      this.#utf8Buffers[lastIndex] = last + data;
    }

    this.#bufferedLength = nextLength;
    if (!this.#writing && this.#bufferedLength >= this.#minLength) {
      this.#actualWrite();
    }
    return this.#bufferedLength < this.#highWaterMark;
  }
}

import { ERR_INVALID_ARG_TYPE } from "../../internal/errors.ts";

export function validateBufferArray(
  value: unknown,
): asserts value is readonly ArrayBufferView[] {
  if (!Array.isArray(value)) {
    throw new ERR_INVALID_ARG_TYPE("buffers", "ArrayBufferView[]", value);
  }
  for (const buffer of value) {
    if (!ArrayBuffer.isView(buffer)) {
      throw new ERR_INVALID_ARG_TYPE("buffers", "ArrayBufferView[]", value);
    }
  }
}

export function bufferLengths(buffers: readonly ArrayBufferView[]): number[] {
  const lengths = new Array<number>(buffers.length);
  for (let index = 0; index < buffers.length; index++) {
    const buffer = buffers[index];
    if (buffer === undefined) {
      throw new Error(`fs vector is missing buffer ${index}`);
    }
    lengths[index] = buffer.byteLength;
  }
  return lengths;
}

export function flattenBuffers(buffers: readonly ArrayBufferView[]): number[] {
  let length = 0;
  for (const buffer of buffers) length += buffer.byteLength;
  const bytes = new Array<number>(length);
  let target = 0;
  for (const buffer of buffers) {
    const view = new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength);
    for (const byte of view) bytes[target++] = byte;
  }
  return bytes;
}

export function fillBuffers(
  buffers: readonly ArrayBufferView[],
  bytes: number[],
  count: number,
): void {
  let source = 0;
  for (const buffer of buffers) {
    const view = new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength);
    for (let target = 0; target < view.length && source < count; target++) {
      const byte = bytes[source++];
      if (byte === undefined) {
        throw new Error("fs vector read returned fewer bytes than it reported");
      }
      view[target] = byte;
    }
    if (source === count) return;
  }
  if (source !== count) {
    throw new Error("fs vector read returned more bytes than its buffers hold");
  }
}

// Node's native `GetOffset`: any value other than a safe integer means the
// descriptor's current position. Vector I/O deliberately does not reject a
// non-number position in JavaScript.
export function vectorPosition(position: unknown): number {
  return typeof position === "number" && Number.isSafeInteger(position)
    ? position
    : -1;
}

// `fs.watch` and `fs.watchFile`, from node v24.20.0
// `lib/internal/fs/watchers.js`.
//
// Two mechanisms with one purpose and very different characters, which is why
// node has both and why the documentation warns about each.
//
// `watch` asks the operating system: inotify on Linux, FSEvents on macOS,
// ReadDirectoryChangesW on Windows. It is cheap and prompt, and it is not
// uniform -- whether a rename arrives as one event or two, whether a filename
// is reported at all, and whether watching a directory sees changes inside
// subdirectories are all platform answers rather than node's.
//
// `watchFile` polls `stat` on an interval and compares. It is uniform,
// portable, and costs a system call per file per interval forever. It is what
// to use when the answer has to be the same everywhere, and what not to use
// for many files.

import { EventEmitter } from "../../events/src/main.ts";
import { Buffer } from "../../buffer/src/main.ts";
import { AsyncContextFrame } from "../../internal/async-context.ts";
import {
  defaultTriggerAsyncIdScope,
  emitAfter,
  emitBefore,
  emitDestroy,
  emitInit,
  getDefaultTriggerAsyncId,
  initHooksExist,
  newAsyncId,
} from "../../internal/async-hooks.ts";
import { nextTick } from "../../internal/tick.ts";
import { uvException } from "../../internal/uv.ts";
import {
  compileGlobPatterns,
  matchesCompiledGlobPatterns,
  type CompiledGlobPattern,
} from "../../path/src/glob-matcher.ts";
import { resolve as resolvePosixPath } from "../../path/src/posix.ts";
import { resolve as resolveWindowsPath } from "../../path/src/win32.ts";
import {
  ERR_INVALID_ARG_TYPE,
  ERR_INVALID_ARG_VALUE,
} from "../../internal/errors.ts";
import {
  validateAbortSignal,
  validateBoolean,
  validateFunction,
  validateUint32,
} from "../../internal/validators.ts";
import { BigIntStats, Stats } from "./stats.ts";
import {
  getValidatedPath,
  encodeNormalizedFileBytes,
  normalizeFileResultEncoding,
  type FileResultEncoding,
  type PathLike,
} from "./options.ts";

/** @ntsAbi managed */
declare function nts_platform(): string;

/** Start watching. The handle is what stops it again. */
/** @ntsAbi managed */
declare function nts_fs_watch_start(
  path: string,
  recursive: boolean,
  persistent: boolean,
  throwIfNoEntry: boolean,
  callback: (
    status: number,
    event: WatchEventType,
    filename: number[] | null,
  ) => void,
): number;
/** @ntsAbi managed */
declare function nts_fs_watch_stop(handle: number): void;
/** @ntsAbi managed */
declare function nts_fs_watch_ref(handle: number): void;
/** @ntsAbi managed */
declare function nts_fs_watch_unref(handle: number): void;
/** Poll `path` every `interval` ms, reporting the two stat readings. */
/** @ntsAbi managed */
declare function nts_fs_watchfile_start(
  path: string,
  interval: number,
  persistent: boolean,
  bigint: false,
  callback: (current: number[], previous: number[]) => void,
): number;
/** @ntsAbi managed */
declare function nts_fs_watchfile_start(
  path: string,
  interval: number,
  persistent: boolean,
  bigint: true,
  callback: (current: string[], previous: string[]) => void,
): number;
/** @ntsAbi managed */
declare function nts_fs_watchfile_stop(handle: number): void;
/** @ntsAbi managed */
declare function nts_fs_watchfile_ref(handle: number): void;
/** @ntsAbi managed */
declare function nts_fs_watchfile_unref(handle: number): void;

export interface WatchSignal {
  readonly aborted: boolean;
  readonly reason?: unknown;
  addEventListener(
    type: "abort",
    listener: () => void,
    options?: { once?: boolean },
  ): void;
  removeEventListener(type: "abort", listener: () => void): void;
}

export type WatchFileName = string | Buffer | null;
export type WatchEventType = "rename" | "change";
export type WatchListener = (
  event: WatchEventType,
  filename: WatchFileName,
) => void;
export type WatchIgnoreFunction = (filename: string) => boolean;
export type WatchIgnoreElement = string | RegExp | WatchIgnoreFunction;
export type WatchIgnore = WatchIgnoreElement | WatchIgnoreElement[];

export interface WatchOptions {
  persistent?: boolean | undefined;
  recursive?: boolean | undefined;
  encoding?: string | undefined;
  signal?: WatchSignal | undefined;
  throwIfNoEntry?: boolean | undefined;
  ignore?: WatchIgnore | null | undefined;
}

export function validateWatchSignal(
  value: unknown,
  name = "options.signal",
): asserts value is WatchSignal | undefined {
  validateAbortSignal(value, name);
  if (value === undefined) return;
  if (!("addEventListener" in value)) {
    throw new ERR_INVALID_ARG_TYPE(
      `${name}.addEventListener`,
      "Function",
      undefined,
    );
  }
  if (!("removeEventListener" in value)) {
    throw new ERR_INVALID_ARG_TYPE(
      `${name}.removeEventListener`,
      "Function",
      undefined,
    );
  }
  validateFunction(value.addEventListener, `${name}.addEventListener`);
  validateFunction(value.removeEventListener, `${name}.removeEventListener`);
}

function validateIgnoreElement(
  value: unknown,
  name: string,
): asserts value is WatchIgnoreElement {
  if (typeof value === "string") {
    if (value.length === 0) {
      throw new ERR_INVALID_ARG_VALUE(name, value, "must be a non-empty string");
    }
    return;
  }
  if (value instanceof RegExp || typeof value === "function") return;
  throw new ERR_INVALID_ARG_TYPE(name, ["string", "RegExp", "Function"], value);
}

export function normalizeWatchIgnore(
  value: unknown,
): WatchIgnore | undefined {
  if (value === null || value === undefined) return undefined;
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) {
      validateIgnoreElement(value[i], `options.ignore[${i}]`);
    }
    return value;
  }
  validateIgnoreElement(value, "options.ignore");
  return value;
}

interface CompiledWatchGlob {
  readonly kind: "glob";
  readonly alternatives: CompiledGlobPattern[];
  readonly matchBase: boolean;
}

interface CompiledWatchRegExp {
  readonly kind: "regexp";
  readonly expression: RegExp;
}

interface CompiledWatchFunction {
  readonly kind: "function";
  readonly predicate: WatchIgnoreFunction;
}

type CompiledWatchIgnore =
  | CompiledWatchGlob
  | CompiledWatchRegExp
  | CompiledWatchFunction;

const watchPlatform = nts_platform();
const watchWindows = watchPlatform === "win32";
const watchNocase = watchWindows || watchPlatform === "darwin";

function resolveWatchFilePath(path: string): string {
  return watchWindows ? resolveWindowsPath(path) : resolvePosixPath(path);
}

function watchPatternHasSeparator(pattern: string): boolean {
  return pattern.includes("/") || (watchWindows && pattern.includes("\\"));
}

function watchBaseName(filename: string): string {
  const slash = filename.lastIndexOf("/");
  const backslash = watchWindows ? filename.lastIndexOf("\\") : -1;
  return filename.slice(Math.max(slash, backslash) + 1);
}

function compileWatchIgnoreElement(
  matcher: WatchIgnoreElement,
): CompiledWatchIgnore {
  if (typeof matcher === "string") {
    return {
      kind: "glob",
      alternatives: compileGlobPatterns(matcher, watchWindows, watchNocase),
      matchBase: !watchPatternHasSeparator(matcher),
    };
  }
  if (typeof matcher === "function") {
    return { kind: "function", predicate: matcher };
  }
  return { kind: "regexp", expression: matcher };
}

function compileWatchIgnore(
  ignore: WatchIgnore | undefined,
): CompiledWatchIgnore[] | undefined {
  if (ignore === undefined) return undefined;
  if (!Array.isArray(ignore)) return [compileWatchIgnoreElement(ignore)];

  const compiled = new Array<CompiledWatchIgnore>(ignore.length);
  for (let index = 0; index < ignore.length; index++) {
    const matcher = ignore[index];
    if (matcher === undefined) {
      throw new Error(`watch ignore list is missing element ${index}`);
    }
    compiled[index] = compileWatchIgnoreElement(matcher);
  }
  return compiled;
}

function ignoreElementMatches(
  matcher: CompiledWatchIgnore,
  filename: string,
): boolean {
  if (matcher.kind === "function") return matcher.predicate(filename);
  if (matcher.kind === "regexp") return matcher.expression.test(filename);
  const candidate = matcher.matchBase ? watchBaseName(filename) : filename;
  return matchesCompiledGlobPatterns(
    candidate,
    matcher.alternatives,
    watchWindows,
  );
}

function shouldIgnore(
  ignore: CompiledWatchIgnore[] | undefined,
  filename: string,
): boolean {
  if (ignore === undefined) return false;
  for (let index = 0; index < ignore.length; index++) {
    const matcher = ignore[index];
    if (matcher !== undefined && ignoreElementMatches(matcher, filename)) {
      return true;
    }
  }
  return false;
}

function emitWatcherClose(watcher: FSWatcher): void {
  watcher.emit("close");
}

function emitWatcherStop(watcher: StatWatcher): void {
  watcher.emit("stop");
}

function closeWatcher(watcher: FSWatcher): void {
  watcher.close();
}

export class FSWatcher extends EventEmitter {
  #handle: number | null = null;
  #path: string | undefined;
  #asyncId: number;
  #triggerAsyncId: number;
  #contextFrame: AsyncContextFrame | undefined;
  #destroyed = false;
  #encoding: FileResultEncoding | undefined;
  #signal: WatchSignal | undefined;
  #abortListener: (() => void) | undefined;
  #ignore: CompiledWatchIgnore[] | undefined;

  constructor() {
    super();
    this.#asyncId = newAsyncId();
    this.#triggerAsyncId = getDefaultTriggerAsyncId();
    this.#contextFrame = AsyncContextFrame.current();
    if (initHooksExist()) {
      emitInit(
        this.#asyncId,
        "FSEVENTWRAP",
        this.#triggerAsyncId,
        this,
      );
    }
  }

  /**
   * Begin watching.
   *
   * Separate from the constructor because node's is: `new FSWatcher()` gives
   * an object you can add listeners to before anything can fire, which
   * matters when the first event may arrive during `start`.
   */
  start(path: PathLike, options: WatchOptions = {}): this {
    const persistent = options.persistent ?? true;
    const recursive = options.recursive ?? false;
    const throwIfNoEntry = options.throwIfNoEntry ?? true;
    validateBoolean(persistent, "options.persistent");
    validateBoolean(recursive, "options.recursive");
    validateBoolean(throwIfNoEntry, "options.throwIfNoEntry");
    this.#ignore = compileWatchIgnore(normalizeWatchIgnore(options.ignore));
    this.#encoding = normalizeFileResultEncoding(options.encoding);
    const validatedPath = getValidatedPath(path, "filename");
    this.#path = validatedPath;
    this.#handle = nts_fs_watch_start(
      validatedPath,
      recursive,
      persistent,
      throwIfNoEntry,
      (status: number, event: WatchEventType, filename: number[] | null) => {
        if (status < 0) {
          const error = uvException(status, "watch", validatedPath);
          error.filename = validatedPath;
          this.#stop(false);
          this.emit("error", error);
          return;
        }
        const decoded = filename === null ? null : Buffer.from(filename).toString();
        if (decoded !== null && shouldIgnore(this.#ignore, decoded)) return;
        const prior = AsyncContextFrame.exchange(this.#contextFrame);
        emitBefore(this.#asyncId, this.#triggerAsyncId, this);
        try {
          this.emit(
            "change",
            event,
            filename === null
              ? null
              : encodeNormalizedFileBytes(filename, this.#encoding),
          );
        } finally {
          emitAfter(this.#asyncId);
          AsyncContextFrame.setCurrent(prior);
        }
      },
    );
    if (this.#handle < 0) {
      const error = uvException(this.#handle, "watch", validatedPath);
      error.filename = validatedPath;
      this.#handle = null;
      this.#destroy();
      throw error;
    }
    return this;
  }

  /** Attach cancellation after listeners can be installed on the watcher. */
  attachSignal(signal: WatchSignal): void {
    validateWatchSignal(signal);
    if (signal.aborted) {
      nextTick(closeWatcher, this);
      return;
    }
    const abortListener = (): void => this.close();
    this.#signal = signal;
    this.#abortListener = abortListener;
    signal.addEventListener("abort", abortListener, { once: true });
  }

  close(): void {
    this.#stop(true);
  }

  #stop(emitClose: boolean): void {
    if (this.#handle === null) return;
    const signal = this.#signal;
    const abortListener = this.#abortListener;
    this.#signal = undefined;
    this.#abortListener = undefined;
    if (signal !== undefined && abortListener !== undefined) {
      signal.removeEventListener("abort", abortListener);
    }
    nts_fs_watch_stop(this.#handle);
    this.#handle = null;
    this.#destroy();
    if (emitClose) nextTick(emitWatcherClose, this);
  }

  /**
   * Stop holding the process open, without stopping watching.
   *
   * A watcher on a config file should not be the reason a program never
   * exits, but should still fire while it is running.
   */
  ref(): this {
    if (this.#handle !== null) nts_fs_watch_ref(this.#handle);
    return this;
  }

  unref(): this {
    if (this.#handle !== null) nts_fs_watch_unref(this.#handle);
    return this;
  }

  get path(): string | undefined {
    return this.#path;
  }

  #destroy(): void {
    if (this.#destroyed) return;
    this.#destroyed = true;
    emitDestroy(this.#asyncId);
  }
}

export class StatWatcher extends EventEmitter {
  #handle: number | null = null;
  #asyncId = 0;
  #triggerAsyncId = 0;
  #contextFrame: AsyncContextFrame | undefined;
