// `http.Agent`, from node v24.20.0 `lib/_http_agent.js`.
//
// A pool of sockets, keyed by where they go. It exists because opening a TCP
// connection costs a round trip before any request can be sent -- three for
// TLS -- and a client that talks to one host repeatedly pays that every time
// unless something keeps the connection.
//
// The two limits are what make it a pool rather than a cache. `maxSockets`
// bounds how many connections may be open to one host at once, so a burst of
// requests queues instead of opening a hundred sockets; `maxFreeSockets`
// bounds how many idle ones are kept, so a burst that has passed does not
// leave them held forever.
//
// The reuse rule that matters is not here but in the server: a connection
// whose previous message was not read to the end cannot be reused, because
// what is left of it is indistinguishable from the next response.

import { EventEmitter } from "../../events/src/main.ts";
import { Socket, connect as netConnect } from "../../net/src/main.ts";
import type { ConnectOptions } from "../../net/src/main.ts";
import { nextTick } from "../../internal/tick.ts";
import { AsyncResource } from "../../async_hooks/src/resource.ts";
import { validateNumberRange, validateOneOf } from "../../internal/validators.ts";
import { ERR_FEATURE_UNAVAILABLE_ON_PLATFORM } from "../../internal/errors.ts";
import type { HTTPDuplex } from "./outgoing.ts";
import { env as processEnvironment } from "../../process/src/env.ts";
import { ProxyConfig, proxyConfigFromEnvironment, selectProxy } from "./proxy.ts";
import type { ProxyEnvironment } from "./proxy.ts";

/** Internal fixed-layout field shared with the request rewriter. */
export const kProxyConfig = Symbol("http.proxyConfig");

export interface AgentConnectionOptions extends ConnectOptions {
  socketPath?: string | undefined;
}

interface SocketReceiver {
  readonly destroyed: boolean;
  reusedSocket: boolean;
  timeout?: number | undefined;
  onSocket(socket: HTTPDuplex | null, error?: unknown): void;
}

type CreateSocketCallback = (error: unknown | null, socket?: HTTPDuplex) => void;

export interface AgentOptions extends AgentConnectionOptions {
  /** Port used when a request through this agent does not name one. */
  defaultPort?: number | undefined;
  /** URL protocol accepted by this agent. */
  protocol?: string | undefined;
  /** Keep idle sockets for reuse. Off by default, as node's is. */
  keepAlive?: boolean | undefined;
  /** How long an idle socket is kept before being closed. */
  keepAliveMsecs?: number | undefined;
  agentKeepAliveTimeoutBuffer?: number | undefined;
  maxSockets?: number | undefined;
  maxTotalSockets?: number | undefined;
  maxFreeSockets?: number | undefined;
  /** How long a request may wait for a socket. */
  timeout?: number | undefined;
  scheduling?: "fifo" | "lifo" | undefined;
  /** Environment variables used by Node's built-in proxy routing. */
  proxyEnv?: ProxyEnvironment | undefined;
}

interface Pending {
  options: AgentConnectionOptions;
  request: SocketReceiver;
  resource: AsyncResource;
}

type SocketErrorListener = (error: unknown) => void;

interface ManagedSocketListeners {
  close: () => void;
  timeout: () => void;
  remove: () => void;
}

export class Agent extends EventEmitter {
  /** Node `_http_agent.js:291`, and settable: every agent built after reads it. */
  static defaultMaxSockets = Infinity;

  defaultPort: number;
  protocol: string;
  keepAlive: boolean;
  keepAliveMsecs: number;
  agentKeepAliveTimeoutBuffer: number;
  maxSockets: number;
  maxTotalSockets: number;
  maxFreeSockets: number;
  totalSocketCount = 0;
  scheduling: "fifo" | "lifo";
  options: AgentOptions;

  /** In use, by `host:port`. */
  sockets: Record<string, HTTPDuplex[]> = {};
  /** Idle and reusable, by the same key. */
  freeSockets: Record<string, HTTPDuplex[]> = {};
  /** Waiting for a socket because the host is at `maxSockets`. */
  requests: Record<string, Pending[]> = {};

  /** The error guard installed only while a socket is idle in the pool. */
  #freeSocketErrors = new Map<HTTPDuplex, SocketErrorListener>();
  /** Every live socket created by this agent, independent of pool state. */
  #ownedSockets = new Set<HTTPDuplex>();
  /** Connection identity retained while a socket moves between pool states. */
  #socketOptions = new Map<HTTPDuplex, AgentConnectionOptions>();
  /** Server keep-alive hints waiting to be applied as a socket turns idle. */
  #keepAliveHints = new Map<HTTPDuplex, string>();
  /** Pool lifecycle listeners, retained so an upgraded socket can detach. */
  #socketListeners = new Map<HTTPDuplex, ManagedSocketListeners>();
  /** Parsed once at construction; ordinary agents pay only one null check. */
  readonly [kProxyConfig]: ProxyConfig | null;

  constructor(options: AgentOptions = {}) {
    super();
    this.options = { ...options };
    if (this.options.noDelay === undefined) this.options.noDelay = true;
    this.defaultPort = options.defaultPort || 80;
    this.protocol = options.protocol || "http:";
    this[kProxyConfig] =
      options.proxyEnv === undefined
        ? null
        : proxyConfigFromEnvironment(options.proxyEnv, this.protocol);
    this.keepAlive = options.keepAlive ?? false;
    this.keepAliveMsecs = options.keepAliveMsecs ?? 1000;
    const timeoutBuffer = options.agentKeepAliveTimeoutBuffer;
    this.agentKeepAliveTimeoutBuffer =
      typeof timeoutBuffer === "number" && timeoutBuffer >= 0 && Number.isFinite(timeoutBuffer)
        ? timeoutBuffer
        : 1000;
    // `||`, not `??`, and `Agent.defaultMaxSockets` rather than a literal --
    // node `_http_agent.js:174`. The static is settable, so a program that
    // assigns `http.Agent.defaultMaxSockets = 5` changes every agent built
    // afterwards; a literal here made that documented knob inert. `||` also
    // means `maxSockets: 0` takes the default, which is node's behaviour and
    // what `??` would have changed.
    this.maxSockets = options.maxSockets || Agent.defaultMaxSockets;
    if (options.maxTotalSockets !== undefined) {
      validateNumberRange(options.maxTotalSockets, "maxTotalSockets", 1);
    }
    this.maxTotalSockets = options.maxTotalSockets ?? Infinity;
    this.maxFreeSockets = options.maxFreeSockets ?? 256;
    this.scheduling = options.scheduling ?? "lifo";
    validateOneOf(this.scheduling, "scheduling", ["fifo", "lifo"] as const);
  }

  /**
   * The pool key.
   *
   * Host and port, and nothing else. Anything that changes what the connection
   * *is* -- a different local interface, a different TLS identity -- has to be
   * part of it, or a socket would be handed to a request that must not use it.
   */
  getName(options: AgentConnectionOptions = {}): string {
    let name = `${options.host || "localhost"}:${options.port || ""}:`;
    if (options.localAddress) name += options.localAddress;
    if (options.family === 4 || options.family === 6) name += `:${options.family}`;
    if (options.socketPath) name += `:${options.socketPath}`;
    return name;
  }

  #connectionOptions(options: AgentConnectionOptions): AgentConnectionOptions {
    const merged: AgentConnectionOptions = { ...options, ...this.options };
    if (merged.socketPath !== undefined) merged.path = merged.socketPath;
    return merged;
  }

  createConnection(options: AgentConnectionOptions, callback?: CreateSocketCallback): HTTPDuplex {
    const proxy = selectProxy(this[kProxyConfig], options);
    if (proxy?.protocol === "https:") {
      throw new ERR_FEATURE_UNAVAILABLE_ON_PLATFORM("HTTPS proxy transport");
    }
    const socket = netConnect(proxy?.connectionOptions ?? options);
    if (callback !== undefined) socket.once("connect", () => callback(null, socket));
    return socket;
  }

  /**
   * The overridable connection-construction seam used by Node agents.
   *
   * A custom implementation may either return a socket immediately or invoke
   * the error-first callback later. Completion is guarded so an implementation
   * that does both still installs exactly one socket.
   */
  createSocket(
    request: SocketReceiver,
    options: AgentConnectionOptions,
    callback: CreateSocketCallback,
  ): void {
    const connectionOptions = this.#connectionOptions(options);
    const timeout = request.timeout || this.options.timeout;
    if (timeout !== undefined) connectionOptions.timeout = timeout;
    if (this.keepAlive) {
      connectionOptions.keepAlive = true;
      connectionOptions.keepAliveInitialDelay = this.keepAliveMsecs;
    }

    let completed = false;
    const onCreated: CreateSocketCallback = (error, socket) => {
      if (completed) return;
      completed = true;
      if (error !== null && error !== undefined) {
        callback(error);
      } else if (socket === undefined) {
        callback(new TypeError("createConnection did not provide a socket"));
      } else {
        callback(null, socket);
      }
    };

    let socket: HTTPDuplex | undefined;
    try {
      socket = this.createConnection(connectionOptions, onCreated);
    } catch (error) {
      onCreated(error);
      return;
    }
    // Completion belongs outside the construction catch. If the consumer's
    // callback rejects an otherwise valid transport, that exception is not a
    // second connection error and must never be swallowed here.
    if (socket !== undefined) onCreated(null, socket);
  }

  /** Give `request` a socket, now or when one comes free. */
  addRequest(request: SocketReceiver, options: AgentConnectionOptions): void;
  addRequest(request: SocketReceiver, host: string, port?: number, localAddress?: string): void;
  addRequest(
    request: SocketReceiver,
    optionsOrHost: AgentConnectionOptions | string,
    port?: number,
    localAddress?: string,
  ): void {
    const options: AgentConnectionOptions =
      typeof optionsOrHost === "string"
        ? { host: optionsOrHost, port, localAddress }
        : optionsOrHost;
    const connectionOptions = this.#connectionOptions(options);
    const name = this.getName(connectionOptions);

    const free = this.freeSockets[name];
    if (free !== undefined) {
      // Destruction and its close callback are asynchronous. A caller may
      // destroy an idle socket from its `free`/`timeout` listener and issue a
      // replacement request in the same turn, before accounting cleanup has
      // run. Never hand that visibly destroyed socket back out.
      while (free.length > 0 && free[0]?.destroyed) free.shift();
      if (free.length === 0) delete this.freeSockets[name];
    }
    if (free && free.length > 0) {
      // LIFO by default: the most recently used socket is the one most likely
      // to still be open at the other end, since an idle timeout kills the
      // oldest first.
      const socket = this.scheduling === "fifo" ? free.shift() : free.pop();
      if (free.length === 0) delete this.freeSockets[name];
      if (socket) {
        // A reused connection is doing new work for a new caller, so it gets a
        // new identity. Keeping the old one would attribute this request to
        // whichever request happened to release the socket.
        if (socket instanceof Socket) socket.asyncReset();
        this.reuseSocket(socket, request);
        (this.sockets[name] ??= []).push(socket);
        request.onSocket(socket);
        this.#setRequestSocketTimeout(socket, request);
        return;
      }
    }

    const inUse = this.sockets[name]?.length ?? 0;
    if (inUse >= this.maxSockets || this.totalSocketCount >= this.maxTotalSockets) {
      // Queued rather than refused: the caller asked for a request, not for a
      // socket, and a client that failed here would be failing for a reason
      // the program cannot see or act on.
      (this.requests[name] ??= []).push({
        options: connectionOptions,
        request,
        // The socket becomes available from a different request's callback.
        // This explicit resource carries the queuing request's identity and
        // AsyncLocalStorage frame across that gap.
        resource: new AsyncResource("QueuedRequest", { requireManualDestroy: true }),
      });
      return;
    }

    this.createSocket(request, connectionOptions, (error, socket) => {
      if (error !== null || socket === undefined) {
        nextTick(() => request.onSocket(null, error));
        return;
      }
      this.#assignCreatedSocket(name, socket, request, connectionOptions);
    });
  }

  /**
   * The request is done with this socket.
   *
   * Kept for reuse only if both ends agreed to it and the pool has room;
   * otherwise closed. A socket that is kept must be *idle* -- nothing left
   * unread -- which the caller decides, not this.
   */
  keepSocketAlive(socket: HTTPDuplex): boolean {
    socket.setKeepAlive?.(true, this.keepAliveMsecs);
    // Unrefed while idle: a pooled connection should not be the reason a
    // program cannot exit.
    socket.unref?.();

    let timeout = this.options.timeout ?? 0;
    const keepAlive = this.#keepAliveHints.get(socket);
    if (keepAlive !== undefined) {
      const match = /^timeout=(\d+)/.exec(keepAlive);
      const seconds = match === null ? undefined : Number(match[1]);
      if (seconds !== undefined) {
        const safeTimeout = seconds * 1000 - this.agentKeepAliveTimeoutBuffer;
        if (safeTimeout <= 0) return false;
        if (safeTimeout < timeout) timeout = safeTimeout;
      }
    }
    if (socket.setTimeout !== undefined && socket.timeout !== timeout) socket.setTimeout(timeout);
    return true;
  }

  reuseSocket(socket: HTTPDuplex, request: SocketReceiver): void {
    this.#removeFreeSocketError(socket);
    if (socket instanceof Socket) socket.setIdleReadGuard(false);
    socket.ref?.();
    request.reusedSocket = true;
  }

  release(name: string, socket: HTTPDuplex, reusable: boolean, keepAliveHint?: string): void {
    if (keepAliveHint !== undefined) this.#keepAliveHints.set(socket, keepAliveHint);
    this.#release(name, socket, reusable);
  }

  #release(requestedName: string, socket: HTTPDuplex, reusable: boolean): void {
    if (!this.#owns(socket)) return;
    // The pool key has to be the one this socket was filed under.
    //
    // Node captures one options object when it creates a socket and hands
    // that same object to `getName` at both ends -- acquisition, and again in
    // the `free` handler via `agent.emit('free', s, options)` -- so the two
    // keys agree by construction rather than by two computations happening to
    // match. Recomputing the key from a request's host and port drops every
    // other field `getName` reads, and `socketPath` is one of them: a
    // connection opened for a Unix socket was filed under a key no later
    // lookup could produce, so keep-alive reuse missed and each request
    // opened a new connection.
    const created = this.#socketOptions.get(socket);
    const name = created === undefined ? requestedName : this.getName(created);
    const inUse = this.sockets[name];
    if (inUse) {
      const at = inUse.indexOf(socket);
      if (at !== -1) inUse.splice(at, 1);
      if (inUse.length === 0) delete this.sockets[name];
    }

    // Somebody is waiting: hand it straight on rather than putting it in the
    // free list and taking it out again.
    const waiting = this.#pruneDestroyedRequests(name);
    if (waiting && waiting.length > 0 && reusable && !socket.destroyed) {
      const next = waiting.shift();
      if (next === undefined) return;
      if (waiting.length === 0) delete this.requests[name];
      try {
        next.resource.runInAsyncScope(() => {
          if (socket instanceof Socket) socket.asyncReset();
          (this.sockets[name] ??= []).push(socket);
          this.reuseSocket(socket, next.request);
          next.request.onSocket(socket);
          this.#setRequestSocketTimeout(socket, next.request);
        });
      } finally {
        next.resource.emitDestroy();
      }
      this.#emitFree(socket);
      return;
    }

    if (waiting && waiting.length > 0) {
      // A non-reusable connection must release its global slot before a
      // replacement is opened. The close path selects this origin first.
      this.#emitFree(socket);
      socket.destroy();
      return;
    }

    if (this.#hasWaitingOriginOtherThan(name)) {
      // A TCP connection cannot change origin. Retire this idle candidate so
      // the global maxTotalSockets slot can serve a queued origin.
      this.#emitFree(socket);
      socket.destroy();
      return;
    }

    if (!this.keepAlive || !reusable || socket.destroyed) {
      this.#emitFree(socket);
      socket.destroy();
      return;
    }

    let canKeepAlive = false;
    try {
      canKeepAlive = this.keepSocketAlive(socket);
    } finally {
      this.#keepAliveHints.delete(socket);
    }
    if (!canKeepAlive) {
      this.#emitFree(socket);
      socket.destroy();
      return;
    }

    if (socket instanceof Socket) {
      socket.setIdleReadGuard(true);
      if (socket.destroyed) {
        this.#emitFree(socket);
        return;
      }
    }

    const free = (this.freeSockets[name] ??= []);
    if (free.length >= this.maxFreeSockets) {
      this.#emitFree(socket);
      socket.destroy();
      return;
    }
    free.push(socket);
    // Idle in the pool, belonging to no request. The next acquisition calls
    // `asyncReset()` before handing it out, so no request observes stale
    // identity or context. Node's additional Symbol mirror is internal
    // metaobject state and is deliberately not part of the typed socket.
    this.#installFreeSocketError(socket);
    this.#emitFree(socket);
  }

  #assignCreatedSocket(
    name: string,
    socket: HTTPDuplex,
    request: SocketReceiver,
    options: AgentConnectionOptions,
  ): void {
    this.#ownedSockets.add(socket);
    this.#socketOptions.set(socket, options);
    this.totalSocketCount++;
    (this.sockets[name] ??= []).push(socket);
    socket.setTimeout?.(request.timeout || this.options.timeout || 0);

    const listeners: ManagedSocketListeners = {
      close: () => this.#socketClosed(name, socket),
      timeout: () => {
        if (this.#freeSocketErrors.has(socket)) socket.destroy();
      },
      remove: () => this.#socketRemoved(name, socket),
    };
    this.#socketListeners.set(socket, listeners);
    socket.on("timeout", listeners.timeout);
    socket.once("agentRemove", listeners.remove);

    request.onSocket(socket);
    // Request observers must see the connection as agent-owned while their
    // close/error handling runs. Register the accounting listener after the
    // request's own next-tick activation has installed its socket listeners,
    // so it runs later in that same close emission.
    nextTick(() => {
      if (this.#owns(socket)) socket.once("close", listeners.close);
    });
  }

  #forgetSocket(name: string, socket: HTTPDuplex): boolean {
    this.#removeFromPool(this.sockets, name, socket);
    this.#removeFromPool(this.freeSockets, name, socket);
    this.#removeFreeSocketError(socket);
    this.#keepAliveHints.delete(socket);
    if (socket instanceof Socket) socket.setIdleReadGuard(false);

    const listeners = this.#socketListeners.get(socket);
    if (listeners !== undefined) {
      socket.removeListener("close", listeners.close);
      socket.removeListener("timeout", listeners.timeout);
      socket.removeListener("agentRemove", listeners.remove);
      this.#socketListeners.delete(socket);
    }

    if (!this.#owns(socket)) return false;
    this.#ownedSockets.delete(socket);
    this.#socketOptions.delete(socket);
    this.totalSocketCount--;
    return true;
  }

  #owns(socket: HTTPDuplex): boolean {
    return this.#ownedSockets.has(socket);
  }

  #removeFromPool(pool: Record<string, HTTPDuplex[]>, name: string, socket: HTTPDuplex): void {
    const sockets = pool[name];
    if (sockets === undefined) return;
    const index = sockets.indexOf(socket);
    if (index !== -1) sockets.splice(index, 1);
    if (sockets.length === 0) delete pool[name];
  }

  #installFreeSocketError(socket: HTTPDuplex): void {
    // This callback is already handling the emitted error. Destroying with
    // that same error would schedule a second `error` after this once-listener
    // has removed itself, turning an idle reset into an unhandled exception.
    const onError: SocketErrorListener = (_error) => socket.destroy();
    this.#freeSocketErrors.set(socket, onError);
    socket.once("error", onError);
  }

  #removeFreeSocketError(socket: HTTPDuplex): void {
    const onError = this.#freeSocketErrors.get(socket);
    if (onError === undefined) return;
    this.#freeSocketErrors.delete(socket);
    socket.removeListener("error", onError);
  }

  #emitFree(socket: HTTPDuplex): void {
    socket.emit("free");
    this.emit("free", socket, this.#socketOptions.get(socket));
  }

  #hasWaitingOriginOtherThan(name: string): boolean {
    for (const key of Object.keys(this.requests)) {
      if (key !== name && this.#pruneDestroyedRequests(key) !== undefined) return true;
    }
    return false;
  }

  /** Restore a request-specific timeout after an idle socket is reused. */
  #setRequestSocketTimeout(socket: HTTPDuplex, request: SocketReceiver): void {
    const agentTimeout = this.options.timeout ?? 0;
    if (request.timeout !== undefined && request.timeout !== agentTimeout) {
      socket.setTimeout?.(request.timeout);
    }
  }

  /** Drop requests cancelled while they waited for an Agent socket. */
  #pruneDestroyedRequests(name: string): Pending[] | undefined {
    const requests = this.requests[name];
    if (requests === undefined) return undefined;
    while (requests.length > 0) {
      const first = requests[0];
      if (first === undefined) {
        throw new Error("non-empty HTTP agent queue had no first request");
      }
      if (!first.request.destroyed) return requests;
      requests.shift();
      first.resource.emitDestroy();
    }
    delete this.requests[name];
    return undefined;
  }

  #takePending(preferredName: string): { name: string; pending: Pending } | undefined {
    const preferred = this.#pruneDestroyedRequests(preferredName);
    if (preferred !== undefined) {
      const preferredPending = preferred.shift();
      if (preferredPending === undefined) {
        throw new Error("non-empty HTTP agent queue had no first request");
      }
      if (preferred.length === 0) delete this.requests[preferredName];
      return { name: preferredName, pending: preferredPending };
    }

    for (const name of Object.keys(this.requests)) {
      if ((this.sockets[name]?.length ?? 0) >= this.maxSockets) continue;
      const requests = this.#pruneDestroyedRequests(name);
      if (requests === undefined) continue;
      const pending = requests.shift();
      if (pending === undefined) {
        throw new Error("non-empty HTTP agent queue had no first request");
      }
      if (requests.length === 0) delete this.requests[name];
      return { name, pending };
    }
    return undefined;
  }

  #socketClosed(name: string, socket: HTTPDuplex): void {
    if (this.#forgetSocket(name, socket)) this.#openPending(name);
  }

  #socketRemoved(name: string, socket: HTTPDuplex): void {
    if (this.#forgetSocket(name, socket)) this.#openPending(name);
  }

  #openPending(preferredName: string): void {
    const next = this.#takePending(preferredName);
    if (next === undefined) return;

    const complete: CreateSocketCallback = (error, socket) => {
      try {
        next.pending.resource.runInAsyncScope(() => {
          if (error !== null || socket === undefined) {
            next.pending.request.onSocket(null, error);
            return;
          }
          this.#assignCreatedSocket(next.name, socket, next.pending.request, next.pending.options);
          this.#emitFree(socket);
        });
      } finally {
        next.pending.resource.emitDestroy();
      }
    };

    try {
      this.createSocket(next.pending.request, next.pending.options, complete);
    } catch (error) {
      complete(error);
    }
  }

  /** Close everything, in use and idle. */
  destroy(): void {
    for (const pool of [this.freeSockets, this.sockets]) {
      for (const key of Object.keys(pool)) {
        const sockets = pool[key];
        if (sockets === undefined) continue;
        for (const socket of sockets) socket.destroy();
        delete pool[key];
      }
    }
  }
}

/** Construct Node's keep-alive default, optionally with environment proxy routing. */
export function createGlobalAgent(proxyEnv?: ProxyEnvironment): Agent {
  return new Agent({ keepAlive: true, scheduling: "lifo", timeout: 5000, proxyEnv });
}

/**
 * Whether the global agent routes through the environment's proxy.
 *
 * Node reads one normalized option, `--use-env-proxy`, once and only when the
 * global agent is constructed (`lib/_http_agent.js`). That option is fed from
 * two places: the command-line flag, and `NODE_USE_ENV_PROXY`, which
 * `src/node_options.cc` normalizes with an exact comparison against `"1"` --
 * so `NODE_USE_ENV_PROXY=true` does not enable it and neither does `=0`.
 *
 * Only the environment half is visible from here. This profile has no
 * normalized startup-option state, so the command-line flag cannot be
 * observed; a test that passes `--use-env-proxy` rather than the variable is
 * a genuine runtime gap and is recorded as one rather than approximated by
 * scanning `execArgv`, which would report the flag as present in cases where
 * node's own normalization would have rejected it.
 */
function useEnvironmentProxy(): boolean {
  return processEnvironment.NODE_USE_ENV_PROXY === "1";
}

/** The agent `http.request` uses when the caller does not supply one. */
export let globalAgent = createGlobalAgent(useEnvironmentProxy() ? processEnvironment : undefined);

/** Read the live binding when constructing Node's writable CommonJS facade. */
export function readGlobalAgentBinding(): Agent {
  return globalAgent;
}

/** Update the live binding through Node's writable CommonJS facade. */
export function writeGlobalAgentBinding(agent: Agent): void {
  globalAgent = agent;
}

// `http.ClientRequest`, from node v24.20.0 `lib/_http_client.js`.
//
// The other end of the same protocol: this writes a request and parses a
// response, where the server parses a request and writes a response. It shares
// `OutgoingMessage` with the server for the writing, and the same parser in
// its other mode for the reading.
//
// One asymmetry is worth naming. A server always knows how long a response
// body is, because it is the one framing it. A client does not always know how
// long a *response* body is: a reply with no `Content-Length` and no chunking
// runs until the connection closes, which is why the parser has an
// until-close framing at all and why a client must be told when the socket
// ends rather than only when a message does.

import { Buffer } from "../../buffer/src/main.ts";
import type { LookupFunction } from "../../net/src/main.ts";
import { URL } from "../../url/src/url.ts";
import { urlToHttpOptions } from "../../url/src/fileurl.ts";
import type { AbortSignalLike } from "../../internal/abort.ts";
import { addAbortSignal } from "../../stream/src/add-abort-signal.ts";
import { getTimerDuration } from "../../timers/src/main.ts";
import { nextTick } from "../../internal/tick.ts";
import {
  ERR_HTTP_HEADERS_SENT,
  ConnResetException,
  ERR_INVALID_ARG_VALUE,
  ERR_INVALID_ARG_TYPE,
  ERR_INVALID_HTTP_TOKEN,
  ERR_INVALID_PROTOCOL,
  ERR_INVALID_URL,
  ERR_UNESCAPED_CHARACTERS,
} from "../../internal/errors.ts";
import {
  validateBoolean,
  validateInteger,
  validateOneOf,
  validatePort,
} from "../../internal/validators.ts";
import { acquireHTTPParser, HTTPParseError, RESPONSE } from "./parser.ts";
import { IncomingMessage } from "./incoming.ts";
import { checkIsHttpToken, OutgoingMessage, parseUniqueHeadersOption,
  kHasBody,
  kStatusLine,
  kKeepAliveWithoutFramingWhenEmpty,
} from "./outgoing.ts";
import type { HTTPDuplex, OutgoingHeaders, OutgoingHeaderValue } from "./outgoing.ts";
import { Agent, globalAgent, kProxyConfig } from "./agent.ts";
import type { AgentConnectionOptions } from "./agent.ts";
import { emitHttpDebugWarning } from "./debug.ts";
import { selectProxy } from "./proxy.ts";
import type { ProxyConfig } from "./proxy.ts";
import { channel } from "../../diagnostics_channel/src/main.ts";
import {
  hasObserver,
  startPerf,
  stopPerf,
  type PerfContext,
} from "../../perf_hooks/src/observe.ts";

const clientRequestCreatedChannel = channel("http.client.request.created");
const clientRequestStartChannel = channel("http.client.request.start");
const clientRequestErrorChannel = channel("http.client.request.error");
const clientResponseFinishChannel = channel("http.client.response.finish");

export type RequestHeaderPair = readonly [string, OutgoingHeaderValue];
export type RequestHeaderArray = readonly (string | RequestHeaderPair)[];
export type RequestHeaders = OutgoingHeaders | RequestHeaderArray;

export interface RequestOptions {
  /** Present on WHATWG URL objects accepted by `request()` and `get()`. */
  href?: string | undefined;
  host?: string | undefined;
  hostname?: string | undefined;
  port?: number | string | undefined;
  path?: string | undefined;
  protocol?: string | undefined;
  method?: string | undefined;
  headers?: RequestHeaders | undefined;
  auth?: string | undefined;
  agent?: Agent | false | undefined;
  defaultPort?: number | string | undefined;
  timeout?: number | undefined;
  setHost?: boolean | undefined;
  setDefaultHeaders?: boolean | undefined;
  uniqueHeaders?: readonly string[] | undefined;
  joinDuplicateHeaders?: boolean | undefined;
  httpValidation?: "strict" | "relaxed" | "insecure" | undefined;
  insecureHTTPParser?: boolean | undefined;
  createConnection?:
    | ((
        options: AgentConnectionOptions,
        callback: (error: unknown, socket?: HTTPDuplex) => void,
      ) => HTTPDuplex | undefined)
    | undefined;
  lookup?: LookupFunction | undefined;
  localAddress?: string | undefined;
  localPort?: number | undefined;
  family?: number | undefined;
  hints?: number | undefined;
  socketPath?: string | undefined;
  signal?: AbortSignalLike | undefined;
  highWaterMark?: number | null | undefined;
  /** Node's name for "do not add a body framing", used by GET and HEAD. */
  maxHeaderSize?: number | undefined;
}

/** The public structural contract accepted by Node's `options.agent`. */
interface RequestAgent {
  readonly protocol?: string | undefined;
  readonly defaultPort?: number | undefined;
  readonly keepAlive?: boolean | undefined;
  readonly maxSockets?: number | undefined;
  readonly options?: { readonly timeout?: number | undefined } | undefined;
  addRequest(request: ClientRequest, options: AgentConnectionOptions): void;
}

export type ResponseListener = (response: IncomingMessage) => void;

interface PendingResponseChunk {
  readonly chunk: Buffer;
  next: PendingResponseChunk | null;
}

/** Methods that carry no body, so no framing header should be added. */
const BODILESS = new Set(["GET", "HEAD", "DELETE", "OPTIONS", "TRACE", "CONNECT"]);
const INVALID_PATH = /[^\u0021-\u00ff]/;

function statusIsInformational(statusCode: number): boolean {
  return statusCode >= 100 && statusCode < 200 && statusCode !== 101;
}

function requestHeadersAreArray(headers: RequestHeaders): headers is RequestHeaderArray {
  return Array.isArray(headers);
}

function requestHeaderIsPair(header: unknown): header is RequestHeaderPair {
  return Array.isArray(header);
}

function validateRequestHost(value: unknown, name: "host" | "hostname"): string | null | undefined {
  if (value !== null && value !== undefined && typeof value !== "string") {
    throw new ERR_INVALID_ARG_TYPE(`options.${name}`, ["string", "undefined", "null"], value);
  }
  return value;
}

function isRequestAgent(value: unknown): value is RequestAgent {
  if (value === null || typeof value !== "object" || !("addRequest" in value)) return false;
  return typeof value.addRequest === "function";
}

function applyRequestHeaderArray(
  request: OutgoingMessage,
  headers: RequestHeaderArray,
): RequestHeaderPair[] {
  const pairs: RequestHeaderPair[] = [];
  const first = headers[0];
  if (first !== undefined && requestHeaderIsPair(first)) {
    for (let index = 0; index < headers.length; index++) {
      const header = headers[index];
      if (!requestHeaderIsPair(header)) {
        throw new ERR_INVALID_ARG_VALUE(
          `options.headers[${index}]`,
          typeof header,
          "must be an array when headers is passed as an array of pairs",
        );
      }
      request.appendHeader(header[0], header[1]);
      pairs.push([header[0], header[1]]);
    }
    return pairs;
  }

  if (headers.length % 2 !== 0) {
    throw new ERR_INVALID_ARG_VALUE(
      "options.headers",
      headers,
      "must contain an even number of entries",
    );
  }
  for (let index = 0; index < headers.length; index += 2) {
    const name = headers[index];
    const value = headers[index + 1];
    if (typeof name !== "string" || typeof value !== "string") {
      throw new ERR_INVALID_ARG_VALUE(
        "options.headers",
        headers,
        "must contain alternating string names and values",
      );
    }
    request.appendHeader(name, value);
    pairs.push([name, value]);
  }
  return pairs;
}

interface ProxyAuthority {
  readonly host: string;
  readonly port: number | string;
}

interface ValidatedProxyAuthority {
  readonly requestBase: URL;
  readonly requestURL: URL;
}

function hostFromHeaderPairs(headers: readonly RequestHeaderPair[]): string | undefined {
  let host: string | undefined;
  for (const [name, value] of headers) {
    if (name.toLowerCase() !== "host") continue;
    if (host !== undefined) {
      throw new ERR_INVALID_ARG_VALUE(
        "options.headers",
        "(redacted)",
        "must not contain duplicate Host headers",
      );
    }
    host = String(value);
  }
  return host;
}

function authoritiesMatch(canonicalHost: string, headerHost: string): boolean {
  let parsed: URL;
  try {
    parsed = new URL(`http://${headerHost}`);
  } catch {
    return false;
  }
  if (
    parsed.username.length > 0 ||
    parsed.password.length > 0 ||
    parsed.pathname !== "/" ||
    parsed.search.length > 0 ||
    parsed.hash.length > 0
  ) {
    return false;
  }
  return parsed.host === canonicalHost;
}

function validateProxyAuthority(
  path: string,
  authority: ProxyAuthority,
  explicitHost: string | undefined,
  headerPairs: readonly RequestHeaderPair[] | undefined,
): ValidatedProxyAuthority {
  const port = validatePort(authority.port, "options.port");
  const requestBase = new URL(`http://${authority.host}`);
  requestBase.port = String(port);

  const arrayHost = headerPairs === undefined ? undefined : hostFromHeaderPairs(headerPairs);
  if (arrayHost !== undefined && arrayHost !== requestBase.host) {
    throw new ERR_INVALID_ARG_VALUE(
      "Host in options.headers",
      arrayHost,
      `must match the request authority (${requestBase.host})`,
    );
  }
  if (headerPairs === undefined && explicitHost !== undefined) {
    if (!authoritiesMatch(requestBase.host, explicitHost)) {
      throw new ERR_INVALID_ARG_VALUE(
        "Host in options.headers",
        explicitHost,
        `must match the request authority (${requestBase.host})`,
      );
    }
  }

  let requestURL: URL;
  let absolute = false;
  try {
    requestURL = new URL(path);
    absolute = true;
  } catch {
    if (!path.startsWith("/")) {
      throw new ERR_INVALID_ARG_VALUE(
        "options.path",
        path,
        "must be in absolute-form or start with /",
      );
    }
    // Concatenate with the origin exactly as Node does. Passing `path` as a
    // relative URL would reinterpret a leading `//` as a new authority.
    requestURL = new URL(requestBase.origin + path);
  }

  if (absolute) {
    if (requestURL.username.length > 0 || requestURL.password.length > 0) {
      requestURL.username = "";
      requestURL.password = "";
      throw new ERR_INVALID_ARG_VALUE(
        "options.path",
        requestURL.href,
        "must not contain userinfo, use options.auth instead",
      );
    }
    if (requestURL.protocol !== "http:") {
      throw new ERR_INVALID_ARG_VALUE(
        "options.path",
        requestURL.protocol,
        "must use http: scheme when specified as an absolute URL",
      );
    }
    if (requestBase.host !== requestURL.host) {
      throw new ERR_INVALID_ARG_VALUE(
        "options.path",
        requestURL.href,
        `must match the request authority (${requestBase.host})`,
      );
    }
  }

  return { requestBase, requestURL };
}

function rewriteForProxiedHTTP(
  request: ClientRequest,
  proxy: ProxyConfig,
  authority: ProxyAuthority,
  explicitHost: string | undefined,
  headerPairs: readonly RequestHeaderPair[] | undefined,
): boolean {
  let requestURL: URL | undefined;
  if (request.method !== "CONNECT" && !(request.method === "OPTIONS" && request.path === "*")) {
    const validated = validateProxyAuthority(
      request.path,
      authority,
      explicitHost,
      headerPairs,
    );
    if (headerPairs === undefined) {
      const currentHost = request.getHeader("host");
      if (currentHost !== undefined && currentHost !== validated.requestBase.host) {
        request.setHeader("Host", validated.requestBase.host);
      }
    }
    requestURL = validated.requestURL;
  }

  if (proxy.auth !== undefined) request.setHeader("proxy-authorization", proxy.auth);
  request.setHeader("proxy-connection", request.shouldKeepAlive ? "keep-alive" : "close");
  if (requestURL !== undefined) request.path = requestURL.href;
  return requestURL !== undefined;
}

export class ClientRequest extends OutgoingMessage<HTTPDuplex> {
  method: string;
  host: string;
  protocol: string;
  agent: RequestAgent | null;

  aborted = false;
  reusedSocket = false;
  maxHeadersCount: number | null = null;
  timeout: number | undefined;
  timeoutCb: (() => void) | null = null;
  #pendingSocketTimeout: number | undefined;
  #responseEnded = false;
  /** The response, once its head has arrived. */
  res: IncomingMessage | null = null;

  #options: RequestOptions;
  #port: number;
  /** The options this request's socket was acquired with, for `getName`. */
  #connectionOptions: AgentConnectionOptions | undefined;
  #errorEmitted = false;
  #joinDuplicateHeaders = false;
  /** Node's `kAuthority`: the `Host` the options name, for the performance entry. */
  #authority = "";
  /** Node's `kProxyRewrittenToAbsolute`: the path is already the whole URL. */
  #absoluteForm = false;
  /** The `http` performance entry under way, while something observes the type. */
  #perf: PerfContext | undefined = undefined;
  #path = "";

  get path(): string {
    return this.#path;
  }

  set path(value: string) {
    const path = String(value);
    if (INVALID_PATH.test(path)) {
      throw new ERR_UNESCAPED_CHARACTERS("Request path");
    }
    this.#path = path;
  }

  constructor(options: RequestOptions | string, callback?: ResponseListener) {
    emitHttpDebugWarning();
    const opts: RequestOptions =
      typeof options === "string"
        ? parseUrlish(options)
        : options.href === undefined
          ? { ...options }
          : { ...parseUrlish(options.href), ...options };
    super({ highWaterMark: opts.highWaterMark });
    this.#options = opts;

    const requestedMethod: unknown = opts.method;
    if (
      requestedMethod !== undefined &&
      requestedMethod !== null &&
      typeof requestedMethod !== "string"
    ) {
      throw new ERR_INVALID_ARG_TYPE("options.method", "string", requestedMethod);
    }
    const method = requestedMethod || "GET";
    if (typeof method !== "string" || !checkIsHttpToken(method)) {
      throw new ERR_INVALID_HTTP_TOKEN("Method", String(method));
    }

    this.method = method.toUpperCase();
    this.path = opts.path || "/";
    this.host =
      validateRequestHost(opts.hostname, "hostname") ||
      validateRequestHost(opts.host, "host") ||
      "localhost";

    const agentOption: unknown = opts.agent;
    let selectedAgent: RequestAgent | null;
    if (agentOption === false) {
      selectedAgent = new Agent();
    } else if (agentOption === null || agentOption === undefined) {
      selectedAgent = opts.createConnection === undefined ? globalAgent : null;
    } else if (isRequestAgent(agentOption)) {
      selectedAgent = agentOption;
    } else {
      throw new ERR_INVALID_ARG_TYPE(
        "options.agent",
        ["Agent-like Object", "undefined", "false"],
        agentOption,
      );
    }
    this.protocol = opts.protocol ?? selectedAgent?.protocol ?? "http:";
    const expectedProtocol = selectedAgent?.protocol ?? globalAgent.protocol;
    if (this.protocol !== expectedProtocol) {
      throw new ERR_INVALID_PROTOCOL(this.protocol, expectedProtocol);
    }
    this.agent = selectedAgent;
    const defaultPort = opts.defaultPort || selectedAgent?.defaultPort;
    const port = opts.port || defaultPort || 80;
    this.#port = Number(port);
    const timeoutOption: unknown = opts.timeout;
    this.timeout =
      timeoutOption === undefined ? undefined : getTimerDuration(timeoutOption, "timeout");
    const maxHeaderSize: unknown = opts.maxHeaderSize;
    if (maxHeaderSize !== undefined) validateInteger(maxHeaderSize, "maxHeaderSize", 0);

    const httpValidation: unknown = opts.httpValidation;
    const insecureHTTPParser: unknown = opts.insecureHTTPParser;
    if (httpValidation !== undefined) {
      validateOneOf(httpValidation, "options.httpValidation", [
        "strict",
        "relaxed",
        "insecure",
      ] as const);
    }
    if (insecureHTTPParser !== undefined) {
      validateBoolean(insecureHTTPParser, "options.insecureHTTPParser");
    }
    if (opts.joinDuplicateHeaders !== undefined) {
      validateBoolean(opts.joinDuplicateHeaders, "options.joinDuplicateHeaders");
    }
    if (httpValidation !== undefined && insecureHTTPParser !== undefined) {
      throw new ERR_INVALID_ARG_VALUE(
        "options.httpValidation",
        httpValidation,
        "cannot be used together with options.insecureHTTPParser",
      );
    }
    this._setHeaderValidation(
      httpValidation === "relaxed" || httpValidation === "insecure" || insecureHTTPParser === true,
    );
    this.#joinDuplicateHeaders = opts.joinDuplicateHeaders ?? false;

    if (callback) this.once("response", callback);

    // Node permits an explicit body even on methods such as GET. Such methods
    // merely default to *no framing*: an empty request is self-delimiting, but
    // writing bytes without a Content-Length or Transfer-Encoding makes the
    // connection close-delimited and therefore ineligible for reuse.
    this[kHasBody] = true;
    this.useChunkedEncodingByDefault = !BODILESS.has(this.method);
    this[kKeepAliveWithoutFramingWhenEmpty] = BODILESS.has(this.method);
    this.shouldKeepAlive =
      selectedAgent !== null &&
      (selectedAgent.keepAlive === true || Number.isFinite(selectedAgent.maxSockets));
    this._removedConnection = opts.setDefaultHeaders === false;
    this._removedContLen = opts.setDefaultHeaders === false;
    this._removedTE = opts.setDefaultHeaders === false;

    const rawHeaderArray = opts.headers !== undefined && requestHeadersAreArray(opts.headers);
    let rawHeaderPairs: RequestHeaderPair[] | undefined;
    if (opts.headers !== undefined) {
      if (requestHeadersAreArray(opts.headers)) {
        rawHeaderPairs = applyRequestHeaderArray(this, opts.headers);
      } else {
        for (const [name, value] of Object.entries(opts.headers)) {
          this.setHeader(name, value);
        }
      }
    }

    // `Host` identifies which site on a shared address the request is for, and
    // is mandatory in HTTP/1.1. Added unless the caller set it or opted out.
    const explicitHost = rawHeaderArray ? undefined : this.getHeader("host");
    const setHost =
      opts.setHost !== undefined ? Boolean(opts.setHost) : opts.setDefaultHeaders !== false;
    // Node's `hostHeaderFromOptions`: the host, bracketed if it is an IPv6
    // address, with the port when it is not the scheme's. It is also the
    // authority the `http` performance entry reports the request's URL with.
    const firstColon = this.host.indexOf(":");
    const bracketedHost =
      firstColon !== -1 && this.host.includes(":", firstColon + 1) && !this.host.startsWith("[")
        ? `[${this.host}]`
        : this.host;
    this.#authority = Number(port) !== defaultPort ? `${bracketedHost}:${port}` : bracketedHost;
    if (!rawHeaderArray && setHost && !this.hasHeader("host")) {
      this.setHeader("Host", this.#authority);
    }

    const hostHeader = this.getHeader("host");
    if (!rawHeaderArray && hostHeader !== undefined && typeof hostHeader !== "string") {
      throw new ERR_INVALID_ARG_TYPE("options.headers.host", "string", hostHeader);
    }

    if (!rawHeaderArray && opts.auth && !this.hasHeader("authorization")) {
      this.setHeader("Authorization", `Basic ${Buffer.from(opts.auth).toString("base64")}`);
    }

    const proxyAuthority = {
      host:
        this.host.includes(":") && !this.host.startsWith("[") ? `[${this.host}]` : this.host,
      port,
    };
    const proxy =
      selectedAgent instanceof Agent
        ? selectProxy(selectedAgent[kProxyConfig], {
            host: this.host,
            port,
            socketPath: opts.socketPath,
          })
        : null;
    if (proxy !== null) {
      this.#absoluteForm = rewriteForProxiedHTTP(
        this,
        proxy,
        proxyAuthority,
        typeof explicitHost === "string" ? explicitHost : undefined,
        rawHeaderPairs,
      );
    }

    if (rawHeaderPairs !== undefined) {
      this[kStatusLine] = `${this.method} ${this.path} HTTP/1.1`;
      this._storeRawHeaderPairs(rawHeaderPairs);
    }
    this._setUniqueHeaders(parseUniqueHeadersOption(opts.uniqueHeaders));

    const connectionOptions = {
      host: this.host,
      port,
      lookup: opts.lookup,
      localAddress: opts.localAddress,
      localPort: opts.localPort,
      family: opts.family,
      hints: opts.hints,
      socketPath: opts.socketPath,
      timeout: this.timeout,
      highWaterMark: opts.highWaterMark,
    };
    // Retained so that releasing this request's socket names the same pool
    // entry that acquiring it did. `getName` reads `socketPath`,
    // `localAddress` and `family` as well as host and port.
    this.#connectionOptions = connectionOptions;
    if (opts.signal !== undefined) addAbortSignal(opts.signal, this);
    if (this.destroyed) return;
    if (this.agent) {
      this.agent.addRequest(this, connectionOptions);
    } else {
      // `net.connect` reads `path` as the name of a Unix socket, while HTTP
      // options use `path` for the request target. Node resolves the
      // collision before it creates the connection: `socketPath` is copied
      // over `path`, and `path` is cleared when there is no `socketPath`, so
      // a request for `/` is never mistaken for a pipe name
      // (`lib/_http_client.js`). The agent path does the same copy in
      // `#connectionOptions`; this is the branch that has no agent to do it.
      const connectOptions: AgentConnectionOptions =
        connectionOptions.socketPath === undefined
          ? connectionOptions
          : { ...connectionOptions, path: connectionOptions.socketPath };
      const createConnection = opts.createConnection;
      if (createConnection === undefined) {
        const socket = globalAgent.createConnection(connectOptions);
        nextTick(() => this.onSocket(socket));
      } else {
        let completed = false;
        const onCreated = (error: unknown, socket?: HTTPDuplex): void => {
          if (completed) return;
          completed = true;
          if (error !== null && error !== undefined) {
            nextTick(() => this.#fail(error));
          } else if (socket === undefined) {
            nextTick(() => this.#fail(new TypeError("createConnection did not provide a socket")));
          } else {
            this.onSocket(socket);
          }
        };
        let socket: HTTPDuplex | undefined;
        try {
          socket = createConnection(connectOptions, onCreated);
        } catch (error) {
          onCreated(error);
          return;
        }
        if (socket !== undefined) onCreated(null, socket);
      }
    }

    // `Expect: 100-continue` is a two-phase request. The server cannot grant
    // permission until it has seen the head, while the caller correctly waits
    // for that permission before writing the body. Queue the head immediately
    // (or send it when the socket arrives) to avoid deadlocking both sides.
    if (this.hasHeader("expect")) this.flushHeaders();

    // Last, as node has it: a subscriber sees a request whose socket work is
    // already under way, which is what makes the channel usable for tracing.
    if (clientRequestCreatedChannel.hasSubscribers) {
      clientRequestCreatedChannel.publish({ request: this });
    }
  }

  protected override _finish(): void {
    super._finish();
    if (hasObserver("http")) {
      // Node's `HttpClient` entry. A path already rewritten to absolute-form
      // for a proxy is the whole URL.
      this.#perf = startPerf("http", "HttpClient", {
        req: {
          method: this.method,
          url: this.#absoluteForm ? this.path : `${this.protocol}//${this.#authority}${this.path}`,
          headers: this.getHeaders(),
        },
      });
    }
    if (clientRequestStartChannel.hasSubscribers) {
      clientRequestStartChannel.publish({ request: this });
    }
  }

  /**
   * Node's `emitErrorEvent`: every request failure reaches the channel before
   * the event, so a subscriber cannot be pre-empted by a listener that
   * destroys the request.
   */
  #emitError(error: unknown): void {
    if (clientRequestErrorChannel.hasSubscribers) {
      clientRequestErrorChannel.publish({ request: this, error });
    }
    this.emit("error", error);
  }

  /**
   * `ClientRequest.prototype._implicitHeader`, which renders the head and refuses if
   * it is already out.
   *
   * Node's calls `_storeHeader` and throws `ERR_HTTP_HEADERS_SENT("render")` first if
   * `_header` is set. Both halves were missing: this set the request line and
   * deferred the render, so a second call quietly rebuilt it.
   */
  protected override _implicitHeader(): void {
    if (this._header) throw new ERR_HTTP_HEADERS_SENT("render");
    this[kStatusLine] = `${this.method} ${this.path} HTTP/1.1`;
    this.prepareHeaders();
  }

  /** Given a connection by the agent, or made one. Everything starts here. */
  onSocket(socket: HTTPDuplex | null, error?: unknown): void {
    let onEarlyError: ((error: unknown) => void) | undefined;
    if (socket !== null && error === undefined) {
      onEarlyError = (socketError: unknown): void => this.#fail(socketError, true);
      socket.on("error", onEarlyError);
    }
    nextTick(() => this.#activateSocket(socket, error, onEarlyError));
  }

  #activateSocket(
    socket: HTTPDuplex | null,
    error: unknown,
    onEarlyError: ((error: unknown) => void) | undefined,
  ): void {
    if (this.destroyed || error !== undefined || socket === null) {
      if (error !== undefined) this.#fail(error, true);
      else if (socket === null && !this.destroyed) {
        this.#fail(new Error("Agent did not provide a socket"));
      }
      if (socket !== null) {
        if (error === undefined && this.agent !== null && !socket.destroyed) {
          if (onEarlyError !== undefined) socket.removeListener("error", onEarlyError);
          this.#releaseSocket(socket, true);
        } else {
          if (onEarlyError !== undefined) {
            socket.once("close", () => socket.removeListener("error", onEarlyError));
          }
          if (!socket.destroyed) socket.destroy(error);
        }
      }
      return;
    }
    if (onEarlyError !== undefined) socket.removeListener("error", onEarlyError);

    const parserLease = acquireHTTPParser();
    const parser = parserLease.parser;
    parser.initialize(
      RESPONSE,
      this.#options.maxHeaderSize,
      undefined,
      this.#options.httpValidation === "relaxed" ||
        this.#options.httpValidation === "insecure" ||
        this.#options.insecureHTTPParser === true,
      this.#options.httpValidation === "insecure" || this.#options.insecureHTTPParser === true,
    );
    if (typeof this.maxHeadersCount === "number") {
      parser.maxHeaderPairs = this.maxHeadersCount << 1;
    }
    const maxResponseHeaderEntries = parser.maxHeaderPairs > 0 ? parser.maxHeaderPairs : undefined;

    let response: IncomingMessage | null = null;
    let upgradeResponse: IncomingMessage | null = null;
    let finalMessageComplete = false;
    let parsingResponse = false;
    let pendingResponseHead: PendingResponseChunk | null = null;
    let pendingResponseTail: PendingResponseChunk | null = null;

    const abortResponse = (): void => {
      if (response === null || response.complete || response.destroyed) return;
      const error = new ConnResetException("aborted");
      response._destroyFromSocket(error);
    };

    const onResponseTimeout = (): void => {
      response?.emit("timeout", socket);
    };

    const consumeResponseChunk = (chunk: Buffer): boolean => {
      let offset = 0;
      while (offset < chunk.length) {
        const consumed = parser.execute(chunk.subarray(offset));
        if (consumed < 0) {
          const parserError = parser.error;
          if (parserError === null) {
            throw new Error("HTTP parser failed without an error");
          }
          const error = new HTTPParseError(parserError, chunk, offset);
          parserLease.release();
          cleanupSocketListeners();
          this.#failWithoutSocketError(error);
          return false;
        }
        offset += consumed;

        const acceptedUpgrade = upgradeResponse;
        if (acceptedUpgrade !== null) {
          upgradeResponse = null;
          handoffUpgrade(acceptedUpgrade, chunk.subarray(offset));
          return false;
        }

        if (!finalMessageComplete) return true;
        if (offset < chunk.length) {
          finalMessageComplete = false;
          parser.continueAfterMessage();
          continue;
        }

        parserLease.release();
        cleanupSocketListeners();
        return false;
      }
      return true;
    };

    const enqueueResponseChunk = (chunk: Buffer): void => {
      const entry: PendingResponseChunk = { chunk, next: null };
      const tail = pendingResponseTail;
      if (tail === null) pendingResponseHead = entry;
      else tail.next = entry;
      pendingResponseTail = entry;
    };

    const takePendingResponseChunk = (): Buffer | null => {
      const entry = pendingResponseHead;
      if (entry === null) return null;
      pendingResponseHead = entry.next;
      if (pendingResponseHead === null) pendingResponseTail = null;
      return entry.chunk;
    };

    const clearPendingResponseChunks = (): void => {
      pendingResponseHead = null;
      pendingResponseTail = null;
    };

    const onData = (chunk: Buffer): void => {
      if (parsingResponse) {
        enqueueResponseChunk(chunk);
        return;
      }

      parsingResponse = true;
      let current: Buffer | null = chunk;
      try {
        while (current !== null) {
          if (!consumeResponseChunk(current)) {
            clearPendingResponseChunks();
            return;
          }
          current = takePendingResponseChunk();
        }
      } finally {
        parsingResponse = false;
      }
    };

    const onEnd = (): void => {
      // A response with no framing ends when the connection does, so the end
      // of the socket is what completes the message.
      parser.finish();
      if (response === null) {
        cleanupSocketListeners();
        this.#failWithoutSocketError(new ConnResetException("socket hang up"), true);
      } else {
        abortResponse();
      }
    };

    const onError = (error: unknown): void => {
      parserLease.release();
      cleanupSocketListeners();
      this.#fail(error, true);
    };

    const onClose = (): void => {
      cleanupSocketListeners();
      // The response parser is finished with the connection.
      parserLease.release();
      if (!this.res) {
        // The connection went before any response arrived, which is the one
        // case a client cannot recover from on its own. `abort()` reports its
        // own event, but does not suppress this first transport outcome.
        this.#fail(new ConnResetException("socket hang up"), true);
      } else {
        abortResponse();
      }
      this._emitClose();
    };

    const cleanupSocketListeners = (): void => {
      detachParserListeners();
      socket.removeListener("error", onError);
      socket.removeListener("close", onClose);
    };

    const detachParserListeners = (): void => {
      socket.removeListener("data", onData);
      socket.removeListener("end", onEnd);
      socket.removeListener("timeout", onResponseTimeout);
      if (this.timeoutCb !== null) {
        socket.removeListener("timeout", this.timeoutCb);
        this.timeoutCb = null;
      }
    };

    const handoffUpgrade = (message: IncomingMessage, head: Buffer): void => {
      detachParserListeners();
      parser.finish();
      parserLease.release();

      const eventName = this.method === "CONNECT" ? "connect" : "upgrade";
      if (this.listenerCount(eventName) === 0) {
        socket.destroy();
        return;
      }

      // Agent and OutgoingMessage ownership are independent. Drop both before
      // the callback, while keeping req.socket/res.socket equal to the raw
      // transport as Node's public API promises.
      socket.emit("agentRemove");
      cleanupSocketListeners();
      this._handoffSocket(socket);
      socket.readableFlowing = null;
      this.emit(eventName, message, socket, head);
      this._emitClose();
    };

    parser.onHeadersComplete = (info) => {
      if (info.type !== RESPONSE) {
        throw new Error("response parser produced request metadata");
      }
      const message = new IncomingMessage(socket);
      message.joinDuplicateHeaders = this.#joinDuplicateHeaders;
      message.httpVersionMajor = info.versionMajor;
      message.httpVersionMinor = info.versionMinor;
      message.httpVersion = `${info.versionMajor}.${info.versionMinor}`;
      message.statusCode = info.statusCode;
      message.statusMessage = info.statusMessage;
      message.keepAlive = info.shouldKeepAlive;
      message._addHeaders(info.headers, maxResponseHeaderEntries);
      message.setSource(() => socket.resume());

      if (info.upgrade || this.method === "CONNECT") {
        response = message;
        this.res = message;
        upgradeResponse = message;
        return 2;
      }

      // An informational response is not *the* response: the real one follows
      // on the same connection, so the parser has to carry on rather than
      // treat this as the message.
      if (statusIsInformational(info.statusCode)) {
        if (info.statusCode === 100) this.emit("continue");
        this.emit("information", {
          httpVersion: message.httpVersion,
          httpVersionMajor: info.versionMajor,
          httpVersionMinor: info.versionMinor,
          statusCode: info.statusCode,
          statusMessage: info.statusMessage,
          headers: message.headers,
          rawHeaders: message.rawHeaders,
        });
        return 1;
      }

      // The request begins reusable when its Agent may pool the transport,
      // but the peer has the final say. A non-persistent response makes the
      // public request state and the later pool decision agree.
      if (this.shouldKeepAlive && !info.shouldKeepAlive) this.shouldKeepAlive = false;

      if (this.#perf !== undefined && hasObserver("http")) {
        stopPerf(this.#perf, {
          res: {
            statusCode: message.statusCode,
            statusMessage: message.statusMessage,
            headers: message.headers,
          },
        });
      }
      if (clientResponseFinishChannel.hasSubscribers) {
        clientResponseFinishChannel.publish({ request: this, response: message });
      }
      response = message;
      this.res = message;
      socket.on("timeout", onResponseTimeout);
      message.once("end", () => {
        this.#responseEnded = true;
        message._detachAbortSignal();
        // Registered before the response is exposed, so the request becomes
        // logically destroyed before user `end` listeners run. The actual
        // close/free transition stays deferred, leaving the socket busy for
        // the whole current event emission.
        this.#finishResponse(socket, message);
      });
      if (!this.emit("response", message)) message._dump();

      // HEAD, 204, and 304 may carry representation metadata such as
      // Content-Length, but never a response body. Treating that metadata as
      // framing would wait for bytes that a conforming server will not send.
      return this.method === "HEAD" || info.statusCode === 204 || info.statusCode === 304 ? 1 : 0;
    };

    parser.onBody = (chunk) => {
      if (response && !response.push(Buffer.from(chunk))) socket.pause();
    };

    parser.onHeaders = (headers) => {
      if (response === null) return;
      response._beginTrailers();
      response._addHeaders(headers, maxResponseHeaderEntries);
    };

    parser.onMessageComplete = () => {
      if (upgradeResponse !== null) {
        upgradeResponse.complete = true;
        return;
      }
      if (!response) {
        // Informational responses complete their own parser message, but not
        // this ClientRequest. Reset synchronously so a final response already
        // present later in the same TCP chunk is parsed rather than stranded.
        parser.continueAfterMessage();
        return;
      }
      const completed = response;
      completed.complete = true;
      completed.push(null);
      // `execute()` may still have bytes from the same packet to inspect.
      // Defer detaching until `onData` has either rejected that tail or shown
      // that the response ended exactly at the packet boundary.
      finalMessageComplete = true;
    };

    socket.on("data", onData);
    socket.on("end", onEnd);
    socket.on("error", onError);
    socket.on("close", onClose);
    // Assigning the socket flushes pre-connection writes, so the parser and
    // lifecycle listeners must already be installed when that happens.
    this.socket = socket;

    const pendingSocketTimeout = this.#pendingSocketTimeout;
    this.#pendingSocketTimeout = undefined;
    if (pendingSocketTimeout !== undefined) {
      if (socket.connecting) {
        socket.once("connect", () => socket.setTimeout?.(pendingSocketTimeout));
      } else {
        socket.setTimeout?.(pendingSocketTimeout);
      }
    }

    const timeout = this.timeout ?? this.agent?.options?.timeout;
    if (timeout !== undefined) {
      this.timeoutCb = () => {
        this.emit("timeout");
      };
      socket.once("timeout", this.timeoutCb);
    }

    this.emit("socket", socket);
  }

  #finishResponse(socket: HTTPDuplex, response: IncomingMessage): void {
    if (!this.writableFinished) {
      // A server may answer before it has read the request body. Such a socket
      // is still carrying outbound bytes and cannot be handed to another
      // request. Keep it active; the ordered `finish` callback releases it if
      // and when the write queue actually drains.
      this.once("finish", () => this.#finishResponse(socket, response));
      return;
    }
    if (socket.writableLength > 0) {
      // ClientRequest is not itself the native Writable in this profile; its
      // framed writes are delegated to the socket. Therefore the socket's
      // queue is the final authority even after the request's ordered finish
      // sentinel has completed.
      socket.once("drain", () => this.#finishResponse(socket, response));
      return;
    }
    const reusable = this.shouldKeepAlive && response.keepAlive && !this.destroyed;
    if (reusable) {
      this.destroyed = true;
      // A completed response must not destroy a socket that has already been
      // returned to its owner. Keep `req.socket` for compatibility, while the
      // incoming side relinquishes transport ownership immediately.
      response.socket = null;
    }
    nextTick(() => {
      this._emitClose();
      this.#releaseSocket(
        socket,
        reusable,
        typeof response.headers["keep-alive"] === "string"
          ? response.headers["keep-alive"]
          : undefined,
      );
    });
  }

  #releaseSocket(socket: HTTPDuplex, reusable: boolean, keepAliveHint?: string): void {
    const agent = this.agent;
    if (agent instanceof Agent) {
      agent.release(
        agent.getName(this.#connectionOptions ?? { host: this.host, port: this.#port }),
        socket,
        reusable,
        keepAliveHint,
      );
      return;
    }
    if (reusable) {
      // A custom connection has no built-in pool, but its owner may reuse it
      // by observing Node's public `free` event. This is also how two requests
      // can deliberately share the same generic Duplex.
      socket.emit("free");
      return;
    }
    socket.destroy();
  }

  #fail(error: unknown, allowAfterAbort = false): void {
    if ((!allowAfterAbort && this.aborted) || this.#errorEmitted) return;
    this.#errorEmitted = true;
    this.#emitError(error);
    super.destroy(error);
  }

  /** Report a protocol failure without emitting that request-owned error on the transport. */
  #failWithoutSocketError(error: unknown, allowAfterAbort = false): void {
    if ((!allowAfterAbort && this.aborted) || this.#errorEmitted) return;
    this.#errorEmitted = true;
    this.#emitError(error);
    super.destroy();
  }

  /** Node's older name for `destroy`, kept because programs call it. */
  abort(): void {
    if (this.aborted) return;
    this.aborted = true;
    nextTick(() => this.emit("abort"));
    this.destroy();
  }

  override destroy(error?: unknown): this {
    if (this.destroyed) return this;
    // Once the request is abandoned, remaining response bytes belong to
    // nobody. Drain them without delivering more `data` to user code while
    // the socket teardown completes.
    this.res?._dump();
    if (this.socket === null && this.agent !== null && !this.aborted && !this.#errorEmitted) {
      const failure = error ?? new ConnResetException("socket hang up");
      nextTick(() => {
        if (this.#errorEmitted || this.aborted) return;
        this.#errorEmitted = true;
        this.#emitError(failure);
      });
    }
    return super.destroy(error);
  }

  override setTimeout(msecs: number, callback?: () => void): this {
    if (this.#responseEnded) return this;
    const duration = getTimerDuration(msecs, "msecs");
    this.timeout = duration;
    if (callback) this.once("timeout", callback);
    const socket = this.socket;
    if (socket === null) {
      this.#pendingSocketTimeout = duration;
    } else {
      if (this.timeoutCb !== null) socket.removeListener("timeout", this.timeoutCb);
      if (socket.connecting === true) {
        socket.once("connect", () => socket.setTimeout?.(duration));
      } else {
        socket.setTimeout?.(duration);
      }
      this.timeoutCb = () => {
        this.emit("timeout");
      };
      socket.once("timeout", this.timeoutCb);
    }
    return this;
  }

  clearTimeout(callback?: () => void): this {
    return this.setTimeout(0, callback);
  }

  /** Disable Nagle on the underlying socket once there is one. */
  setNoDelay(enable = true): void {
    this.socket?.setNoDelay?.(enable);
  }

  setSocketKeepAlive(enable = true, initialDelay = 0): void {
    this.socket?.setKeepAlive?.(enable, initialDelay);
  }
}

/** `http.request("http://host/path")`, taken apart. */
function parseUrlish(url: string): RequestOptions {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new ERR_INVALID_URL(url);
  }
  return urlToHttpOptions(parsed);
}

export function request(
  options: RequestOptions | string,
  optionsOrCallback?: RequestOptions | ResponseListener,
  maybeCallback?: ResponseListener,
): ClientRequest {
  // `request(url, options, cb)` as well as `request(options, cb)`, because a
  // URL says where and an options object says how, and a caller often has both.
  let opts: RequestOptions;
  let callback: ResponseListener | undefined;

  if (typeof options === "string") {
    opts = parseUrlish(options);
    if (typeof optionsOrCallback === "function") {
      callback = optionsOrCallback;
    } else if (optionsOrCallback) {
      opts = { ...opts, ...optionsOrCallback };
      callback = maybeCallback;
    }
  } else {
    opts = options;
    callback = typeof optionsOrCallback === "function" ? optionsOrCallback : maybeCallback;
  }

  return new ClientRequest(opts, callback);
}

/**
 * A request that is already finished being written.
 *
 * The whole of the difference from `request` is the `end()`, and it exists
 * because forgetting it is the most common way a `GET` appears to hang: the
 * request has been built and never sent.
 */
export function get(
  options: RequestOptions | string,
  optionsOrCallback?: RequestOptions | ResponseListener,
  maybeCallback?: ResponseListener,
): ClientRequest {
  const req = request(options, optionsOrCallback, maybeCallback);
  req.end();
  return req;
}

import { debugSectionEnabled } from "../../internal/debug-env.ts";
import { emitWarning } from "../../internal/process-warning.ts";

const HTTP_DEBUG_WARNING =
  "Setting the NODE_DEBUG environment variable to 'http' can expose sensitive data " +
  "(such as passwords, tokens and authentication headers) in the resulting log.";
const httpDebugEnabled = debugSectionEnabled("HTTP");
let warningEmitted = false;

/** Emit Node's security warning at the first operation in an enabled process. */
export function emitHttpDebugWarning(): void {
  if (!httpDebugEnabled || warningEmitted) return;
  warningEmitted = true;
  emitWarning(HTTP_DEBUG_WARNING, "Warning", "");
}

// `http.IncomingMessage`, from node v24.20.0 `lib/_http_incoming.js`.
//
// The readable half of a message: a request as the server sees it, or a
// response as the client sees it. It is a `Readable` whose source is the
// parser, so a body arrives as it does on the wire rather than after the whole
// message has been buffered — which is the difference between streaming a
// gigabyte upload and holding it in memory.
//
// The header handling is where the specification's awkwardness lives. Field
// names are case-insensitive, most may appear once, a few may appear many
// times and mean a list, and `Set-Cookie` is a list even though nothing else
// is. Node encodes those rules in `_addHeaderLine`, and they are transcribed
// here because they are the rules, not an implementation.

import { Readable } from "../../stream/src/main.ts";
import type { AbortSignalLike } from "../../internal/abort.ts";
import { nextTick } from "../../internal/tick.ts";

/** The public part of the host AbortSignal exposed by IncomingMessage. */
export interface IncomingAbortSignal extends AbortSignalLike {
  onabort: ((event: unknown) => void) | null;
}

interface IncomingAbortController {
  readonly signal: IncomingAbortSignal;
  abort(reason?: unknown): void;
}

declare const AbortController: {
  new (): IncomingAbortController;
};

/**
 * Fields that keep only the first value, silently.
 *
 * Node's list. The reason these are singled out rather than falling under the
 * general rule is that they are the ones where a duplicate is most likely to
 * be an attack rather than a mistake.
 */
const firstWins = new Set([
  "age",
  "authorization",
  "content-length",
  "content-type",
  "etag",
  "expires",
  "from",
  "host",
  "if-modified-since",
  "if-unmodified-since",
  "last-modified",
  "location",
  "max-forwards",
  "proxy-authorization",
  "referer",
  "retry-after",
  "server",
  "user-agent",
]);

export interface IncomingSocket {
  readonly destroyed: boolean;
  readonly readableHighWaterMark?: number | undefined;
  remoteAddress?: string | undefined;
  remotePort?: number | undefined;
  destroy(error?: unknown, callback?: (error?: unknown) => void): unknown;
  once(event: "close", listener: () => void): unknown;
  removeListener(event: "close", listener: () => void): unknown;
  setTimeout?(msecs: number, callback?: () => void): unknown;
}

export type IncomingHttpHeaders = Record<string, string | string[] | undefined>;
export type IncomingHttpHeadersDistinct = Record<string, string[] | undefined>;

export class IncomingMessage extends Readable {
  httpVersionMajor = 1;
  httpVersionMinor = 1;
  httpVersion = "1.1";

  /** Header names lowercased, values joined per the rules above. */
  headers: IncomingHttpHeaders = {};
  /** The same, in the order and case they arrived: `[name, value, ...]`. */
  rawHeaders: string[] = [];
  trailers: IncomingHttpHeaders = {};
  rawTrailers: string[] = [];

  #headersDistinct: IncomingHttpHeadersDistinct | null = null;
  #trailersDistinct: IncomingHttpHeadersDistinct | null = null;

  /** Set on a request. */
  method: string | null = null;
  url = "";

  /** Set on a response. */
  statusCode: number | null = null;
  statusMessage: string | null = null;

  socket: IncomingSocket | null | undefined;
  complete = false;
  joinDuplicateHeaders = false;

  /**
   * Whether the message ended before it was complete.
   *
   * Set when the message is destroyed with bytes still outstanding, which is
   * how a program tells a client that hung up from one that finished.
   */
  aborted = false;

  /** Whether the readable side has ever asked the parser for bytes. */
  _consuming = false;
  /** The server has decided that user code will not consume this body. */
  _dumped = false;

  /** Whether the sender said it wanted the connection kept open. */
  #keepAlive = true;
  #inTrailers = false;
  #destroySocketOnDestroy = true;
  #abortController: IncomingAbortController | null = null;
  #abortSignalSocket: IncomingSocket | null = null;
  #abortSignalListener: (() => void) | null = null;
  #abortSignalDetached = false;

  constructor(socket?: IncomingSocket | null) {
    // The stream's own defaults, which is what node uses here. `autoDestroy`
    // in particular: a message that has been read to the end is finished, and
    // destroying it is what emits `close`. Programs listen for that to learn
    // that a request is over -- including that a client hung up mid-request --
    // so suppressing it removes the event most servers rely on.
    super(socket == null ? undefined : { highWaterMark: socket.readableHighWaterMark });
    this.socket = socket;
  }

  get connection(): IncomingSocket | null | undefined {
    return this.socket;
  }

  set connection(socket: IncomingSocket | null | undefined) {
    this.socket = socket;
  }

  /** Every received header line retained separately, keyed case-insensitively. */
  get headersDistinct(): IncomingHttpHeadersDistinct {
    if (this.#headersDistinct === null) {
      this.#headersDistinct = this.#createDistinctHeaders(this.rawHeaders);
    }
    return this.#headersDistinct;
  }

  set headersDistinct(headers: IncomingHttpHeadersDistinct) {
    this.#headersDistinct = headers;
  }

  /** The trailer counterpart of `headersDistinct`. */
  get trailersDistinct(): IncomingHttpHeadersDistinct {
    if (this.#trailersDistinct === null) {
      this.#trailersDistinct = this.#createDistinctHeaders(this.rawTrailers);
    }
    return this.#trailersDistinct;
  }

  set trailersDistinct(trailers: IncomingHttpHeadersDistinct) {
    this.#trailersDistinct = trailers;
  }

  /**
   * Cancellation for the lifetime of this individual HTTP message.
   *
   * The host controller is allocated only when observed. A normally completed
   * message detaches before its keep-alive socket can be reused; a premature
   * socket close aborts exactly this message's stable signal.
   */
  get signal(): IncomingAbortSignal {
    if (this.#abortController === null) {
      const controller = new AbortController();
      this.#abortController = controller;
      if (this.destroyed && (!this.readableEnded || !this.complete)) {
        controller.abort();
      } else {
        this.#attachAbortSignal();
      }
    }
    return this.#abortController.signal;
  }

  #attachAbortSignal(): void {
    const controller = this.#abortController;
    if (
      controller === null ||
      controller.signal.aborted ||
      this.#abortSignalDetached ||
      this.#abortSignalListener !== null
    ) {
      return;
    }

    const socket = this.socket;
    if (socket == null) return;
    if (socket.destroyed) {
      this.#abortSignal();
      return;
    }

    const onClose = (): void => this.#abortSignal();
    this.#abortSignalSocket = socket;
    this.#abortSignalListener = onClose;
    socket.once("close", onClose);
  }

  /** Stop observing the transport after this message completes normally. */
  _detachAbortSignal(): void {
    const socket = this.#abortSignalSocket;
    const listener = this.#abortSignalListener;
    this.#abortSignalDetached = true;
    this.#abortSignalSocket = null;
    this.#abortSignalListener = null;
    if (socket !== null && listener !== null) {
      socket.removeListener("close", listener);
    }
  }

  #abortSignal(): void {
    this._detachAbortSignal();
    this.#abortController?.abort();
  }

  /**
   * The parser drives this; there is nothing to ask the socket for.
   *
   * A readable normally pulls from its source, but this one is pushed to. The
   * pull that matters is the *socket's*, and the server resumes it when this
   * message's buffer drains.
   */
  override _read(): void {
    if (!this._consuming) {
      this._readableState.readingMore = false;
      this._consuming = true;
    }
    if (!this.complete) {
      this.#resumeSource?.();
    }
  }

  /**
   * Drain a request body that its handler ignored.
   *
   * Node does this when the response finishes before user code starts reading
   * the request.  Resuming is important even when the parser has already
   * reached EOF: it advances the readable through `end`, auto-destroy, and
   * finally `close`.
   */
  _dump(): void {
    if (this._dumped) return;
    this._dumped = true;
    this.removeAllListeners("data");
    this.resume();
  }

  /**
   * Mark a known-empty request as consumed without scheduling stream events.
   *
   * This is the opt-in fast path behind `server.optimizeEmptyRequests`. The
   * parser still owns the transport and must keep reading, but no body exists
   * for user code to observe, so constructing the usual end/close lifecycle
   * would be pure overhead.
   */
  _dumpAndCloseReadable(): void {
    const state = this._readableState;
    this._dumped = true;
    state.ended = true;
    state.endEmitted = true;
    state.destroyed = true;
    state.closed = true;
    state.closeEmitted = true;
  }

  #resumeSource: (() => void) | null = null;

  /** Told by whoever is feeding it how to ask for more. */
  setSource(resume: () => void): void {
    this.#resumeSource = resume;
  }

  /** One header line, folded into `headers` under the rules above. */
  _addHeaderLine(name: string, value: string, dest: IncomingHttpHeaders): void {
    const key = name.toLowerCase();

    if (key === "set-cookie") {
      // The one field that is genuinely a list. Joining with a comma would be
      // wrong: a cookie's `Expires` attribute contains a comma, so the result
      // could not be split apart again.
      const existing = dest[key];
      if (Array.isArray(existing)) existing.push(value);
      else dest[key] = [value];
      return;
    }

    const existing = dest[key];
    if (firstWins.has(key)) {
      if (typeof existing === "string") {
        if (this.joinDuplicateHeaders) dest[key] = `${existing}, ${value}`;
      } else if (!Array.isArray(existing)) {
        dest[key] = value;
      }
      return;
    }

    // Ordinary and extension fields form a comma-delimited list. Cookie is
    // the sole semicolon-delimited exception because each line carries a
    // separate cookie-pair rather than another value in an HTTP list.
    if (typeof existing === "string") {
      const separator = key === "cookie" ? "; " : ", ";
      dest[key] = `${existing}${separator}${value}`;
    } else {
      // This deliberately treats an inherited Object property as absent in
      // the Node-hosted lane. Native TypeScript records have no prototype,
      // but HTTP field names such as `constructor` must behave identically.
      dest[key] = value;
    }
  }

  _addHeaderLineDistinct(name: string, value: string, dest: IncomingHttpHeadersDistinct): void {
    const key = name.toLowerCase();
    const existing = dest[key];
    if (Array.isArray(existing)) existing.push(value);
    else dest[key] = [value];
  }

  #createDistinctHeaders(raw: string[]): IncomingHttpHeadersDistinct {
    const headers: IncomingHttpHeadersDistinct = {};
    for (let index = 0; index < raw.length; index += 2) {
      const name = raw[index];
      const value = raw[index + 1];
      if (name === undefined || value === undefined) {
        throw new Error("raw HTTP headers must contain name/value pairs");
      }
      this._addHeaderLineDistinct(name, value, headers);
    }
    return headers;
  }

  /**
   * Node's `_addHeaderLines`, which its own tests call directly.
   *
   * Not the same operation as `_addHeaders` below, and both exist because node
   * has both behaviours in one method. This one *replaces* the raw array and
   * chooses its destination by `complete`, which is what a caller handing over
   * a finished header block wants. `_addHeaders` appends, which is what this
   * profile's parser wants as it delivers a block in pieces. Merging them would
   * mean giving one caller the other's semantics.
   */
  _addHeaderLines(headers: readonly string[] | null | undefined, count: number): void {
    if (headers === null || headers === undefined || headers.length === 0) return;

    let destination: IncomingHttpHeaders;
    if (this.complete) {
      this.rawTrailers = [...headers];
      destination = this.trailers;
    } else {
      this.rawHeaders = [...headers];
      destination = this.headers;
    }

    for (let index = 0; index < count; index += 2) {
      const name = headers[index];
      const value = headers[index + 1];
      // Node reads past the end when `count` overshoots and adds nothing;
      // stopping is the same observable outcome without the undefined pair.
      if (name === undefined || value === undefined) break;
      this._addHeaderLine(name, value, destination);
    }
  }

  /** Called by the parser's `kOnHeadersComplete` equivalent. */
  _addHeaders(raw: string[], maxEntries?: number): void {
    const target = this.#inTrailers ? this.trailers : this.headers;
    const distinctTarget = this.#inTrailers ? this.#trailersDistinct : this.#headersDistinct;
    const rawTarget = this.#inTrailers ? this.rawTrailers : this.rawHeaders;
    const length = maxEntries === undefined ? raw.length : Math.min(raw.length, maxEntries);
    for (let i = 0; i < length; i += 2) {
      const name = raw[i];
      const value = raw[i + 1];
      if (name === undefined || value === undefined) {
        throw new Error("raw HTTP headers must contain name/value pairs");
      }
      rawTarget.push(name, value);
      this._addHeaderLine(name, value, target);
      if (distinctTarget !== null) this._addHeaderLineDistinct(name, value, distinctTarget);
    }
  }

  /** Everything after this belongs to the trailers, not the headers. */
  _beginTrailers(): void {
    this.#inTrailers = true;
  }

  set keepAlive(value: boolean) {
    this.#keepAlive = value;
  }

  get keepAlive(): boolean {
    return this.#keepAlive;
  }

  /** The transport ended this message; report it without destroying it again. */
  _destroyFromSocket(error: unknown): void {
    this.#destroySocketOnDestroy = false;
    this.destroy(error);
  }

  /**
   * Stop the socket's idle timer for this message.
   *
   * Node exposes it because a request whose handling is slow -- a long upload,
   * a slow database call -- should not be killed by a timeout meant for an
   * idle connection.
   */
  setTimeout(msecs: number, callback?: () => void): this {
    if (callback !== undefined) this.on("timeout", callback);
    this.socket?.setTimeout?.(msecs);
    return this;
  }

  override _destroy(error: unknown, callback: (error?: unknown) => void): void {
    const destroySocket = this.#destroySocketOnDestroy;
    if (!this.readableEnded || !this.complete) {
      // Destroyed mid-message: the connection cannot be reused, because the
      // rest of this message is still coming and would be read as the next
      // one.
      this.aborted = true;
      this.emit("aborted");
      this.#abortSignal();
    }
    // IncomingMessage keeps its historical rule: its own error is reported
    // only when observed. An explicit client-side destroy still sends that
    // error through the socket to the owning ClientRequest.
    const finish = (): void => callback(this.listenerCount("error") === 0 ? undefined : error);
    const socket = this.socket;
    if (destroySocket && this.aborted && socket != null && !socket.destroyed) {
      // `closed` belongs to completion of `_destroy`, not its start. The
      // response therefore remains visibly open until its transport closes.
      socket.once("close", () => nextTick(finish));
      socket.destroy(error);
      return;
    }
    nextTick(finish);
  }
}

