      const decodedUsername = decodeURIComponent(username);
      const decodedPassword = decodeURIComponent(password);
      this.auth = `Basic ${Buffer.from(`${decodedUsername}:${decodedPassword}`).toString("base64")}`;
    } else {
      this.href = proxyUrl;
      this.auth = undefined;
