  const name = signal || "SIGTERM";
  if (typeof name !== "string") throw new ERR_UNKNOWN_SIGNAL(String(name));
  const number = constants.signals[name];
  if (number === undefined) throw new ERR_UNKNOWN_SIGNAL(String(name));
