export interface ProcessVersions {
  readonly node: string;
  readonly v8: string;
  readonly ares: string;
  readonly uv: string;
  readonly zlib: string;
  readonly modules: string;
  readonly napi: string;
  readonly openssl: string;
  readonly [name: string]: string;
