// The environment intrinsics, as an ordinary-Node emulation.
//
// In a real NTS environment these are intrinsics: they exist before any module runs.
// This file emulates that by being preloaded, and it exists separately from
// `node-runtime.ts` because of what went wrong when it was not.
//
// The definitions used to live inside `node-runtime.ts`, which is evaluated when
// something imports it. That is late. A test that imports the platform barrel, builds an
// `AbortController`, and only then reaches for the host runtime would construct objects
// before the intrinsics existed — and any shared code that consulted the environment
// during construction saw a `ReferenceError` rather than an absent runtime. The failure
// looked like a design problem and was a load-order problem.
//
// So the emulation matches the thing it emulates: preloaded via `--import`, present from
// the first line of the first module. `node-runtime.ts` imports it as well, so a direct
// importer that skips the preload still gets them, and there is one definition rather
// than two that can drift.
import type { WebPlatformRuntime } from "../src/provider.ts";

declare global {
  // eslint-disable-next-line no-var
  var nts_environment_install_platform: (runtime: WebPlatformRuntime) => void;
  // eslint-disable-next-line no-var
  var nts_environment_platform: () => WebPlatformRuntime;
  // eslint-disable-next-line no-var
  var nts_environment_has_platform: () => boolean;
}

let installedPlatform: WebPlatformRuntime | null = null;

globalThis.nts_environment_install_platform = (runtime): void => {
  installedPlatform = runtime;
};

/**
 * Whether this environment has a runtime, without provoking one.
 *
 * The counterpart to the read below. Reading before installation aborts deliberately, so
 * that the declared return stays non-nullable and bootstrap does not depend on how
 * absence is represented; asking is how a caller avoids provoking that.
 */
globalThis.nts_environment_has_platform = (): boolean => installedPlatform !== null;

globalThis.nts_environment_platform = (): WebPlatformRuntime => {
  if (installedPlatform === null) {
    throw new TypeError("the Web-platform runtime was read before it was installed");
  }
  return installedPlatform;
};

import type { Transform } from "node:stream";
import { createBrotliDecompress, createGunzip, createInflate, createInflateRaw } from "node:zlib";
import { ReadableStream } from "../src/streams/readable.ts";
import type { ContentDecoder } from "../src/provider.ts";
import { HostNodeReadable } from "./node-primitives.ts";

type ByteReader = ReturnType<ReadableStream<Uint8Array>["getReader"]>;

/** Native zlib is a codec primitive; HTTP policy and header handling remain shared. */
export class HostNodeContentDecoder implements ContentDecoder {
  readonly codings = ["br", "gzip", "deflate"];

  supports(coding: string): boolean {
    return coding === "gzip" || coding === "deflate" || coding === "br";
  }

  decode(coding: string, source: ReadableStream<Uint8Array>): ReadableStream<Uint8Array> {
    switch (coding) {
      case "gzip":
        return decodeThroughTransform(
          source.getReader(),
          createGunzip({ chunkSize: 65536 }),
          [],
          false,
        );
      case "deflate":
        return decodeDeflate(source);
      case "br":
        return decodeThroughTransform(
          source.getReader(),
          createBrotliDecompress({ chunkSize: 65536 }),
          [],
          false,
        );
      default:
        throw new TypeError("Unsupported content coding");
    }
  }
}

function decodeThroughTransform(
  input: ByteReader,
  transform: Transform,
  initial: readonly Uint8Array[],
  inputEnded: boolean,
): ReadableStream<Uint8Array> {
  const output = new HostNodeReadable(transform);
  let canceled = false;
  const write = (bytes: Uint8Array): Promise<void> =>
    new Promise<void>((resolve, reject) =>
      transform.write(bytes, (error) => (error ? reject(error) : resolve())),
    );

  const feed = async (): Promise<void> => {
    try {
      for (const bytes of initial) {
        if (canceled) return;
        await write(bytes);
      }
      if (inputEnded) {
        transform.end();
        return;
      }
      while (!canceled) {
        const result = await input.read();
        if (result.done) {
          transform.end();
          return;
        }
        await write(result.value);
      }
    } catch (error) {
      transform.destroy(
        error instanceof Error
          ? error
          : new TypeError("Decompression input failed", { cause: error }),
      );
    } finally {
      input.releaseLock();
    }
  };

  feed().catch((error) => output.fail(error));
  return new ReadableStream<Uint8Array>(
    {
      async pull(controller) {
        try {
          const bytes = await output.read(65536);
          if (bytes === null) controller.close();
          else controller.enqueue(bytes);
        } catch (error) {
          canceled = true;
          input.cancel(error).catch(() => {});
          controller.error(error);
        }
      },
      async cancel(reason) {
        canceled = true;
        transform.destroy();
        try {
          await input.cancel(reason);
        } catch {
          /* Already released or errored. */
        }
      },
    },
    { highWaterMark: 0, size: (value) => value.length },
  );
}

/** HTTP peers still send both zlib-wrapped and raw streams under `deflate`. */
function decodeDeflate(source: ReadableStream<Uint8Array>): ReadableStream<Uint8Array> {
  const input = source.getReader();
  let reader: ByteReader | undefined;
  let initialization: Promise<void> | undefined;
  let canceled = false;
  let inputHandedOff = false;
  let decodedReleased = false;
  const releaseDecoded = (): void => {
    if (reader === undefined || decodedReleased) return;
    decodedReleased = true;
    reader.releaseLock();
  };

  const initialize = async (): Promise<void> => {
    const initial: Uint8Array[] = [];
    let byteCount = 0;
    let ended = false;
    while (byteCount < 2 && !canceled) {
      const result = await input.read();
      if (result.done) {
        ended = true;
        break;
      }
      initial.push(result.value);
      byteCount += result.value.length;
    }
    if (canceled) return;
    const transform = hasZlibHeader(initial)
      ? createInflate({ chunkSize: 65536 })
      : createInflateRaw({ chunkSize: 65536 });
    inputHandedOff = true;
    reader = decodeThroughTransform(input, transform, initial, ended).getReader();
  };

  return new ReadableStream<Uint8Array>(
    {
      async pull(controller) {
        try {
          initialization ??= initialize();
          await initialization;
          if (reader === undefined) {
            controller.close();
            return;
          }
          const result = await reader.read();
          if (result.done) {
            releaseDecoded();
            controller.close();
          } else controller.enqueue(result.value);
        } catch (error) {
          try {
            if (reader !== undefined) await reader.cancel(error);
            else await input.cancel(error);
          } catch {
            /* The input may already have been handed to the transform. */
          } finally {
            if (reader !== undefined) releaseDecoded();
            else if (!inputHandedOff) input.releaseLock();
          }
          controller.error(error);
        }
      },
      async cancel(reason) {
        canceled = true;
        if (reader !== undefined) {
          try {
            await reader.cancel(reason);
          } finally {
            releaseDecoded();
          }
        } else {
          try {
            await input.cancel(reason);
          } finally {
            if (!inputHandedOff) input.releaseLock();
          }
        }
      },
    },
    { highWaterMark: 0, size: (value) => value.length },
  );
}

function hasZlibHeader(chunks: readonly Uint8Array[]): boolean {
  let first: number | undefined;
  let second: number | undefined;
  for (const chunk of chunks) {
    for (const byte of chunk) {
      if (first === undefined) first = byte;
      else {
        second = byte;
        break;
      }
    }
    if (second !== undefined) break;
  }
  if (first === undefined || second === undefined) return false;
  return (first & 0x0f) === 8 && first >> 4 <= 7 && ((first << 8) | second) % 31 === 0;
}

// Host filesystem implementation of the durable byte store, written as the strawman
// the JVM lane asked for so the Android side can be built against the same interface.
// It is host conformance tooling, not a production provider.

import { open as openFile, mkdir, readdir, rename, rm, stat } from "node:fs/promises";
import { join } from "node:path";
import type { AbortSignal } from "../src/core/abort.ts";
import type {
  BlobExternalReader,
  BlobExternalSource,
  DurableByteStore,
  DurableRecord,
  DurableWrite,
} from "../src/provider.ts";

const READ_CHUNK_BYTES = 64 * 1024;
const TEMP_PREFIX = ".partial-";

/** Keys and namespaces become path segments, so they are encoded rather than trusted. */
function encodeSegment(value: string): string {
  const bytes = Buffer.from(value, "utf8");
  return bytes.toString("base64url");
}

function decodeSegment(value: string): string {
  return Buffer.from(value, "base64url").toString("utf8");
}

export interface HostNodeDurableStoreOptions {
  /** Directory this store owns entirely. */
  readonly root: string;
}

class HostNodeDurableWrite implements DurableWrite {
  readonly #temporary: string;
  readonly #target: string;
  readonly #directory: string;
  readonly #signal: AbortSignal;
  #handle: import("node:fs/promises").FileHandle | null = null;
  #settled = false;
  readonly #release: () => void;

  constructor(
    handle: import("node:fs/promises").FileHandle,
    temporary: string,
    target: string,
    directory: string,
    signal: AbortSignal,
    release: () => void,
  ) {
    this.#release = release;
    this.#handle = handle;
    this.#temporary = temporary;
    this.#target = target;
    this.#directory = directory;
    this.#signal = signal;
  }

  async append(bytes: Uint8Array): Promise<void> {
    if (this.#settled || this.#handle === null) {
      throw new TypeError("This durable write has already settled");
    }
    // Checked here, between chunks. Interrupting a write in progress is not something
    // every platform can do without tearing the file, so this is the honest point.
    this.#signal.throwIfAborted();
    await this.#handle.write(bytes, 0, bytes.length);
  }

  async commit(): Promise<void> {
    if (this.#settled) return;
    const handle = this.#handle;
    if (handle === null) throw new TypeError("This durable write has no file");
    this.#signal.throwIfAborted();
    this.#settled = true;
    this.#handle = null;
    this.#release();
    // The data sync makes the bytes durable; the rename makes them the value; the
    // directory sync makes the rename durable. Skipping the third leaves a committed
    // value losable to a crash while never leaving a partial one, which is the subtle
    // half and the reason both syncs are named in the contract.
    await handle.sync();
    await handle.close();
    await rename(this.#temporary, this.#target);
    const directory = await openFile(this.#directory, "r");
    try {
      await directory.sync();
    } finally {
      await directory.close();
    }
  }

  async discard(): Promise<void> {
    if (this.#settled) return;
    this.#settled = true;
    const handle = this.#handle;
    this.#handle = null;
    this.#release();
    if (handle !== null) await handle.close();
    // The target is untouched throughout, so discarding leaves whatever it held.
    await rm(this.#temporary, { force: true });
  }
}

export class HostNodeDurableStore implements DurableByteStore {
  readonly #root: string;
  /** Keys with an open, unsettled write. The ABI is sequential per key. */
  readonly #writing = new Set<string>();
  #closed = false;

  constructor(options: HostNodeDurableStoreOptions) {
    this.#root = options.root;
  }

  async #namespaceDirectory(namespace: string, create: boolean): Promise<string> {
    if (this.#closed) throw new TypeError("This durable store is closed");
    const directory = join(this.#root, encodeSegment(namespace));
    if (create) await mkdir(directory, { recursive: true });
    return directory;
  }

  #path(directory: string, key: string): string {
    return join(directory, encodeSegment(key));
  }

  async read(namespace: string, key: string, signal: AbortSignal): Promise<Uint8Array | null> {
    signal.throwIfAborted();
    const directory = await this.#namespaceDirectory(namespace, false);
    let handle;
    try {
      handle = await openFile(this.#path(directory, key), "r");
    } catch {
      return null;
    }
    try {
      const info = await handle.stat();
      const bytes = new Uint8Array(new ArrayBuffer(info.size));
      let offset = 0;
      while (offset < info.size) {
        signal.throwIfAborted();
        const { bytesRead } = await handle.read(bytes, offset, info.size - offset, offset);
        if (bytesRead === 0) break;
        offset += bytesRead;
      }
      return bytes;
    } finally {
      await handle.close();
    }
  }

  async source(
    namespace: string,
    key: string,
    signal: AbortSignal,
  ): Promise<BlobExternalSource | null> {
    signal.throwIfAborted();
    const directory = await this.#namespaceDirectory(namespace, false);
    const path = this.#path(directory, key);
    let size: number;
    try {
      size = (await stat(path)).size;
    } catch {
      return null;
    }
    return {
      size,
      open(start: number, length: number): BlobExternalReader {
        let position = start;
        let remaining = length;
        // Opened eagerly, and by path exactly once. A descriptor pins the value it was
        // opened over, so a later commit -- which is a rename onto this path -- cannot
        // change what this reader sees. Opening lazily on the first read left a window
        // in which the reader took the *replacement* while still reporting the original
        // size, which is a wrong answer rather than a stale one, and it silently
        // violated the immutable-range guarantee Blob is built on.
        const opened = openFile(path, "r").then(async (file) => {
          const current = await file.stat();
          if (current.size !== size) {
            await file.close();
            // Refused rather than clamped. A caller asked for a range of *this* value;
            // a prefix of a different value is not a shorter answer to that question.
            throw new TypeError("The stored value was replaced after this source opened");
          }
          return file;
        });
        // The rejection is observed by every read, but a reader that is closed without
        // ever being read must not leave it unhandled.
        opened.catch(() => {});
        return {
          async read(maximumBytes: number): Promise<Uint8Array<ArrayBuffer> | undefined> {
            if (remaining === 0) return undefined;
            const wanted = Math.min(maximumBytes, remaining, READ_CHUNK_BYTES);
            const file = await opened;
            const buffer = new Uint8Array(new ArrayBuffer(wanted));
            const { bytesRead } = await file.read(buffer, 0, wanted, position);
            if (bytesRead === 0) return undefined;
            position += bytesRead;
            remaining -= bytesRead;
            return buffer.subarray(0, bytesRead) as Uint8Array<ArrayBuffer>;
          },
          async close(): Promise<void> {
            if (remaining < 0) return;
            remaining = -1;
            try {
              await (await opened).close();
            } catch {
              // A reader whose value was replaced has nothing to close.
            }
          },
        };
      },
    };
  }

  async write(namespace: string, key: string, signal: AbortSignal): Promise<DurableWrite> {
    signal.throwIfAborted();
    // Refused rather than queued: see the ABI. The guard is taken before any file
    // exists, so two writers cannot both believe they own the key.
    const guard = namespace + "\u0000" + key;
    if (this.#writing.has(guard)) {
      throw new TypeError("A write to this key is already open");
    }
    this.#writing.add(guard);
    const directory = await this.#namespaceDirectory(namespace, true);
    const target = this.#path(directory, key);
    // A per-write temporary name, so two writers to one key cannot share a partial.
    const temporary = join(
      directory,
      TEMP_PREFIX + encodeSegment(key) + "-" + String(process.pid) + "-" + String(counter++),
    );
    const handle = await openFile(temporary, "w");
    return new HostNodeDurableWrite(handle, temporary, target, directory, signal, () => {
      this.#writing.delete(guard);
    });
  }

  async delete(namespace: string, key: string, signal: AbortSignal): Promise<boolean> {
    signal.throwIfAborted();
    const directory = await this.#namespaceDirectory(namespace, false);
    try {
      await stat(this.#path(directory, key));
    } catch {
      return false;
    }
    await rm(this.#path(directory, key), { force: true });
    return true;
  }

  async list(namespace: string, signal: AbortSignal): Promise<readonly DurableRecord[]> {
    signal.throwIfAborted();
    const directory = await this.#namespaceDirectory(namespace, false);
    let names: string[];
    try {
      names = await readdir(directory);
    } catch {
      return [];
    }
    const records: DurableRecord[] = [];
    for (const name of names) {
      signal.throwIfAborted();
      // A temporary is an uncommitted write, and an uncommitted write is not a record.
      // Ignoring them here is also what makes a crash recoverable: whatever a previous
      // run left behind is invisible rather than half-present.
      if (name.startsWith(TEMP_PREFIX)) continue;
      const info = await stat(join(directory, name));
      records.push({
        key: decodeSegment(name),
        size: info.size,
        modifiedMilliseconds: info.mtimeMs,
      });
    }
    return records;
  }

  async size(namespace: string, signal: AbortSignal): Promise<number> {
    let total = 0;
    for (const record of await this.list(namespace, signal)) total += record.size;
    return total;
  }

  async close(): Promise<void> {
    this.#closed = true;
  }
}

let counter = 0;

// Host-only `file:` provider for conformance tests. It owns the two things the
// shared layer deliberately does not: mapping a file URL to a path, which is platform
// grammar, and deciding which files this application may read, which is policy.

import { open as openFile, realpath } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { resolve, sep } from "node:path";
import type { AbortSignal } from "../src/core/abort.ts";
import type {
  FileURLEntry,
  FileURLProvider,
  URLRecord,
} from "../src/provider.ts";

const READ_CHUNK_BYTES = 64 * 1024;

export interface HostNodeFileURLOptions {
  /** Every served file must resolve inside this directory. */
  readonly root: string;
  /** Media types by lowercase extension, including the dot. */
  readonly types?: Readonly<Record<string, string>>;
}

/** Refuses anything outside the root, after resolving symlinks rather than before. */
async function resolveWithinRoot(root: string, path: string): Promise<string> {
  const realRoot = await realpath(root);
  // realpath first: a symlink inside the root pointing outside it would otherwise pass
  // a purely textual prefix check.
  const real = await realpath(path);
  const prefix = realRoot.endsWith(sep) ? realRoot : realRoot + sep;
  if (real !== realRoot && !real.startsWith(prefix)) {
    throw new TypeError("The file URL resolves outside the permitted root");
  }
  return real;
}

export class HostNodeFileURLProvider implements FileURLProvider {
  readonly #root: string;
  readonly #types: Readonly<Record<string, string>>;

  constructor(options: HostNodeFileURLOptions) {
    this.#root = resolve(options.root);
    this.#types = options.types ?? {};
  }

  async open(url: URLRecord, signal: AbortSignal): Promise<FileURLEntry> {
    signal.throwIfAborted();
    const path = fileURLToPath(url.href);
    const real = await resolveWithinRoot(this.#root, path);
    const handle = await openFile(real, "r");
    let size: number;
    try {
      const stat = await handle.stat();
      if (stat.isDirectory()) throw new TypeError("A directory has no file URL body");
      size = stat.size;
    } catch (error) {
      await handle.close();
      throw error;
    }
    // The handle is closed here: every Blob consumer opens its own independent range,
    // which is what the external-source contract requires.
    await handle.close();

    const dot = real.lastIndexOf(".");
    const extension = dot < 0 ? "" : real.slice(dot).toLowerCase();
    const type = this.#types[extension] ?? "";
    return {
      type,
      source: {
        size,
        open(start: number, length: number) {
          let position = start;
          let remaining = length;
          let opened: Promise<import("node:fs/promises").FileHandle> | null = null;
          const handleFor = (): Promise<import("node:fs/promises").FileHandle> => {
            opened ??= openFile(real, "r");
            return opened;
          };
          return {
            async read(maximumBytes: number): Promise<Uint8Array<ArrayBuffer> | undefined> {
              if (remaining === 0) return undefined;
              const wanted = Math.min(maximumBytes, remaining, READ_CHUNK_BYTES);
              const file = await handleFor();
              const buffer = new Uint8Array(new ArrayBuffer(wanted));
              const { bytesRead } = await file.read(buffer, 0, wanted, position);
              if (bytesRead === 0) return undefined;
              position += bytesRead;
              remaining -= bytesRead;
              return buffer.subarray(0, bytesRead) as Uint8Array<ArrayBuffer>;
            },
            async close(): Promise<void> {
              const pending = opened;
              opened = null;
              if (pending !== null) await (await pending).close();
            },
          };
        },
      },
    };
  }
}

// Ordinary-Node primitives for host-level conformance tests. This code never
// delegates Fetch or WebSocket behavior to Node, Undici, or node:http(s).

import { connect as tcpConnect, createServer, isIP } from "node:net";
