type RawDeflateTransform = DeflateRaw | InflateRaw;

interface PendingTransform {
  readonly chunks: Uint8Array[];
  readonly maxOutputBytes: number;
  readonly result: PromiseWithResolvers<Uint8Array>;
  total: number;
}

