      (this.#bytes[this.#offset + 3] ?? 0);
    this.#offset += 4;
    return value >>> 0;
  }

  flag(): boolean {
    return this.u32() !== 0;
  }

  text(): string {
    const length = this.u32();
    if (this.#offset + length > this.#bytes.length) {
      throw new TypeError("Truncated cache record");
    }
    const value = this.#decoder.decode(this.#bytes.subarray(this.#offset, this.#offset + length));
    this.#offset += length;
    return value;
  }

  /** A stored value outside the vocabulary is corruption, not a new member. */
  oneOf<T extends string>(allowed: readonly T[]): T {
    const value = this.text();
    for (const candidate of allowed) if (candidate === value) return candidate;
    throw new TypeError("Unknown value in a stored cache record");
  }

  headers(): readonly HeaderEntry[] {
    const entries: HeaderEntry[] = [];
    for (let count = this.u32(); count > 0; count--) entries.push([this.text(), this.text()]);
    return entries;
  }
}

function writeRequest(writer: RecordWriter, record: CacheStorageRequestRecord): void {
  writer.text(record.url);
  writer.text(record.urlWithoutFragment);
  writer.text(record.urlWithoutSearchOrFragment);
  writer.text(record.method);
  writer.headers(record.headers);
  writer.text(record.destination);
  writer.text(record.referrer);
  writer.text(record.referrerPolicy);
  writer.text(record.mode);
  writer.text(record.credentials);
  writer.text(record.cache);
  writer.text(record.redirect);
  writer.text(record.integrity);
  writer.flag(record.keepalive);
  writer.text(record.priority);
  writer.flag(record.isReloadNavigation);
  writer.flag(record.isHistoryNavigation);
}

function readRequest(reader: RecordReader): CacheStorageRequestRecord {
  return {
    url: reader.text(),
    urlWithoutFragment: reader.text(),
    urlWithoutSearchOrFragment: reader.text(),
    method: reader.text(),
    headers: reader.headers(),
    destination: reader.oneOf<StoredDestination>(destinations),
    referrer: reader.text(),
    referrerPolicy: reader.oneOf<StoredReferrerPolicy>(referrerPolicies),
    mode: reader.oneOf<StoredMode>(modes),
    credentials: reader.oneOf<StoredCredentials>(credentials),
    cache: reader.oneOf<StoredCache>(caches),
    redirect: reader.oneOf<StoredRedirect>(redirects),
    integrity: reader.text(),
    keepalive: reader.flag(),
    priority: reader.oneOf<StoredPriority>(priorities),
    isReloadNavigation: reader.flag(),
    isHistoryNavigation: reader.flag(),
  };
}

function writeResponse(
  writer: RecordWriter,
  record: CacheStorageResponseRecord,
  bodyId: string | null,
): void {
  writer.u32(record.status);
  writer.text(record.statusText);
  writer.headers(record.headers);
  writer.text(record.url);
  writer.flag(record.redirected);
  writer.text(record.type);
  writer.flag(bodyId !== null);
  if (bodyId !== null) writer.text(bodyId);
}

interface StoredResponse {
  readonly status: number;
  readonly statusText: string;
  readonly headers: readonly HeaderEntry[];
  readonly url: string;
  readonly redirected: boolean;
  readonly type: ResponseType;
  readonly bodyId: string | null;
}

function readResponse(reader: RecordReader): StoredResponse {
  const status = reader.u32();
  const statusText = reader.text();
  const headers = reader.headers();
  const url = reader.text();
  const redirected = reader.flag();
  const type = reader.oneOf<StoredResponseType>(responseTypes);
  const hasBody = reader.flag();
  return {
    status,
    statusText,
    headers,
    url,
    redirected,
    type,
    bodyId: hasBody ? reader.text() : null,
  };
}

function quotaError(): DOMException {
  return new DOMException("Cache storage quota exceeded", "QuotaExceededError");
}

function readLimit(value: number | undefined, fallback: number, name: string): number {
  const result = value ?? fallback;
  if (result !== Infinity && (!Number.isSafeInteger(result) || result < 0)) {
    throw new RangeError("Invalid durable cache storage " + name);
  }
  return result;
}

export interface DurableCacheStorageStoreOptions {
  /** Defaults to `"cache-storage"`. */
  namespace?: string;
  maxCaches?: number;
  maxEntriesPerCache?: number;
  maxBodyBytesPerCache?: number;
}

class DurableCacheStorageHandle implements CacheStorageHandle {
  readonly owner: object;
  readonly id: string;
  revision = 0;
  /** Body id to the Blob handed out for it, so a returned entry is recognisable. */
  readonly bodies = new Map<string, Blob>();
  readonly bodyIds = new Map<Blob, string>();
  readonly bodyLengths = new Map<string, number>();

  constructor(owner: object, id: string) {
    this.owner = owner;
    this.id = id;
  }
}

/**
 * A persistent {@link CacheStorageStore} over the provider-neutral byte store.
 *
 * The name map is one key and a cache's entry list is one key, so both are replaced
 * atomically by construction — `compareExchange` is a read, a revision comparison and a
 * single-key write, and there is no window in which half a list is visible.
 *
 * Bodies are separate keys, written before the list that names them and deleted after
 * the list that stopped naming them. An interruption therefore leaves a body nothing
 * refers to, which {@link DurableCacheStorageStore.open} reclaims, and never a list
 * naming a body that is not there.
 *
 * **`read` returns the same `Blob` for the same stored body every time.** That is what
 * makes a caller's round trip cheap: entries that come back unchanged from `read` are
 * recognised on the next `compareExchange` and their bytes are not rewritten. A body
 * that arrives as a fresh Blob is new by definition and is stored.
 *
 * One store instance is one storage key, as the contract requires; a provider must not
 * share it across origins. Nothing here enforces that, because nothing here can see it.
 */
export class DurableCacheStorageStore implements CacheStorageStore {
  readonly #store: DurableByteStore;
  readonly #namespace: string;
  readonly #maxCaches: number;
  readonly #maxEntriesPerCache: number;
  readonly #maxBodyBytesPerCache: number;
  readonly #signal: AbortSignal;
  readonly #owner = {};
  readonly #names = new Map<string, DurableCacheStorageHandle>();
  #nextId = 0;

  private constructor(store: DurableByteStore, options: DurableCacheStorageStoreOptions) {
    this.#store = store;
    this.#namespace = options.namespace ?? "cache-storage";
    this.#maxCaches = readLimit(options.maxCaches, Infinity, "maxCaches");
    this.#maxEntriesPerCache = readLimit(
      options.maxEntriesPerCache,
      Infinity,
      "maxEntriesPerCache",
    );
    this.#maxBodyBytesPerCache = readLimit(
      options.maxBodyBytesPerCache,
      Infinity,
      "maxBodyBytesPerCache",
    );
    this.#signal = new AbortController().signal;
  }

  static async open(
    store: DurableByteStore,
    options: DurableCacheStorageStoreOptions = {},
  ): Promise<DurableCacheStorageStore> {
    const storage = new DurableCacheStorageStore(store, options);
    await storage.#load();
    return storage;
  }

  async #load(): Promise<void> {
    const records = await this.#store.list(this.#namespace, this.#signal);
    const present = new Set<string>();
    for (const record of records) present.add(record.key);

    const namesBytes = present.has(NAMES_KEY)
      ? await this.#store.read(this.#namespace, NAMES_KEY, this.#signal)
      : null;
    const reachableBodies = new Set<string>();
    if (namesBytes !== null) {
      const reader = new RecordReader(namesBytes);
      if (reader.u32() === FORMAT_VERSION) {
        for (let count = reader.u32(); count > 0; count--) {
          const name = reader.text();
          const id = reader.text();
          const numeric = Number(id);
          if (Number.isSafeInteger(numeric) && numeric >= this.#nextId) this.#nextId = numeric + 1;
          const handle = new DurableCacheStorageHandle(this.#owner, id);
          const snapshot = await this.#readList(handle, present);
          if (snapshot === null) continue;
          for (const bodyId of handle.bodyLengths.keys()) reachableBodies.add(bodyId);
          this.#names.set(name, handle);
        }
      }
    }

    // Anything else is from an interrupted write; nothing can name it again.
    for (const key of present) {
      if (key === NAMES_KEY) continue;
      if (key.startsWith(BODY_PREFIX) && reachableBodies.has(key.slice(1))) continue;
      if (key.startsWith(LIST_PREFIX) && this.#listIsNamed(key.slice(1))) continue;
      await this.#store.delete(this.#namespace, key, this.#signal);
    }
  }

  #listIsNamed(id: string): boolean {
    for (const handle of this.#names.values()) if (handle.id === id) return true;
    return false;
  }

  /** Reads one list into the handle, or null when it is missing or unreadable. */
  async #readList(
    handle: DurableCacheStorageHandle,
    present: Set<string>,
  ): Promise<readonly StoredResponse[] | null> {
    if (!present.has(LIST_PREFIX + handle.id)) return null;
    const bytes = await this.#store.read(this.#namespace, LIST_PREFIX + handle.id, this.#signal);
    if (bytes === null) return null;
    let reader: RecordReader;
    let revision: number;
    const responses: StoredResponse[] = [];
    try {
      reader = new RecordReader(bytes);
      if (reader.u32() !== FORMAT_VERSION) return null;
      revision = reader.u32();
      for (let count = reader.u32(); count > 0; count--) {
        readRequest(reader);
        responses.push(readResponse(reader));
      }
    } catch {
      return null;
    }
    handle.revision = revision;
    for (const response of responses) {
      if (response.bodyId === null) continue;
      if (!present.has(BODY_PREFIX + response.bodyId)) return null;
      handle.bodyLengths.set(response.bodyId, 0);
    }
    return responses;
  }

  async lookup(name: string): Promise<CacheStorageHandle | null> {
    return this.#names.get(name) ?? null;
  }

  async open(name: string): Promise<CacheStorageHandle> {
    const existing = this.#names.get(name);
    if (existing !== undefined) return existing;
    if (this.#names.size >= this.#maxCaches) throw quotaError();
    const handle = new DurableCacheStorageHandle(this.#owner, String(this.#nextId++));
    await this.#writeList(handle, [], 0);
    this.#names.set(name, handle);
    await this.#writeNames();
    return handle;
  }

  async delete(name: string): Promise<boolean> {
    const handle = this.#names.get(name);
    if (handle === undefined) return false;
    this.#names.delete(name);
    // The name map first: once the list is unnamed nothing can reach it, so an
    // interruption after this point loses storage rather than exposing a half-cache.
    await this.#writeNames();
    await this.#store.delete(this.#namespace, LIST_PREFIX + handle.id, this.#signal);
    for (const bodyId of handle.bodyLengths.keys()) {
      await this.#store.delete(this.#namespace, BODY_PREFIX + bodyId, this.#signal);
    }
    return true;
  }

  async keys(): Promise<readonly string[]> {
    return Array.from(this.#names.keys());
  }

  async read(handle: CacheStorageHandle): Promise<CacheStorageSnapshot> {
    const durable = this.#requireHandle(handle);
    const bytes = await this.#store.read(this.#namespace, LIST_PREFIX + durable.id, this.#signal);
    if (bytes === null) throw new TypeError("This cache is no longer stored");
    const reader = new RecordReader(bytes);
    if (reader.u32() !== FORMAT_VERSION) throw new TypeError("Unreadable stored cache");
    const revision = reader.u32();
    const entries: CacheStorageEntry[] = [];
    for (let count = reader.u32(); count > 0; count--) {
      const request = readRequest(reader);
      const response = readResponse(reader);
      entries.push({
        request,
        response: {
          status: response.status,
          statusText: response.statusText,
          headers: response.headers,
          url: response.url,
          redirected: response.redirected,
          type: response.type,
          body: response.bodyId === null ? null : await this.#body(durable, response.bodyId),
        },
      });
    }
    durable.revision = revision;
    return { revision, entries };
  }

  /** One Blob per stored body, so a round-tripped entry is recognisable by identity. */
  async #body(handle: DurableCacheStorageHandle, bodyId: string): Promise<Blob> {
    const existing = handle.bodies.get(bodyId);
    if (existing !== undefined) return existing;
    const source = await this.#store.source(this.#namespace, BODY_PREFIX + bodyId, this.#signal);
    if (source === null) throw new TypeError("A stored cache body is missing");
    const blob = _createBlobFromExternalSource(source);
    handle.bodies.set(bodyId, blob);
    handle.bodyIds.set(blob, bodyId);
    handle.bodyLengths.set(bodyId, source.size);
    return blob;
  }

  async compareExchange(
    handle: CacheStorageHandle,
    expectedRevision: number,
    entries: readonly CacheStorageEntry[],
  ): Promise<boolean> {
    const durable = this.#requireHandle(handle);
    const bytes = await this.#store.read(this.#namespace, LIST_PREFIX + durable.id, this.#signal);
    if (bytes === null) throw new TypeError("This cache is no longer stored");
    const reader = new RecordReader(bytes);
    if (reader.u32() !== FORMAT_VERSION) throw new TypeError("Unreadable stored cache");
    const currentRevision = reader.u32();
    durable.revision = currentRevision;
    if (currentRevision !== expectedRevision) return false;
    if (entries.length > this.#maxEntriesPerCache) throw quotaError();

    const kept = new Set<string>();
    const written: string[] = [];
    let totalBodyBytes = 0;
    const assigned: (string | null)[] = [];
    try {
      for (const entry of entries) {
        const body = entry.response.body;
        if (body === null) {
          assigned.push(null);
          continue;
        }
        totalBodyBytes += body.size;
        if (totalBodyBytes > this.#maxBodyBytesPerCache) throw quotaError();
        const existing = durable.bodyIds.get(body);
        if (existing !== undefined) {
          kept.add(existing);
          assigned.push(existing);
          continue;
        }
        const bodyId = String(this.#nextId++);
        await this.#storeBody(bodyId, body);
        written.push(bodyId);
        kept.add(bodyId);
        assigned.push(bodyId);
        durable.bodyLengths.set(bodyId, body.size);
      }
      // Bodies are all committed before the list that names them.
      await this.#writeList(durable, entries, currentRevision + 1, assigned);
    } catch (error) {
      for (const bodyId of written) {
        await this.#store.delete(this.#namespace, BODY_PREFIX + bodyId, this.#signal);
        durable.bodyLengths.delete(bodyId);
      }
      throw error;
    }

    for (const bodyId of Array.from(durable.bodyLengths.keys())) {
      if (kept.has(bodyId)) continue;
      await this.#store.delete(this.#namespace, BODY_PREFIX + bodyId, this.#signal);
      durable.bodyLengths.delete(bodyId);
      const blob = durable.bodies.get(bodyId);
      if (blob !== undefined) durable.bodyIds.delete(blob);
      durable.bodies.delete(bodyId);
    }
    durable.revision = currentRevision + 1;
    return true;
  }

  async #storeBody(bodyId: string, body: Blob): Promise<void> {
    const write = await this.#store.write(this.#namespace, BODY_PREFIX + bodyId, this.#signal);
    await this.#appendBlob(write, body);
    await write.commit();
  }

  /** Streamed rather than materialised: a cached response may be arbitrarily large. */
  async #appendBlob(write: DurableWrite, body: Blob): Promise<void> {
    const reader = body.stream().getReader();
    try {
      for (;;) {
        const next = await reader.read();
        if (next.done) break;
        if (next.value !== undefined) await write.append(next.value);
      }
    } catch (error) {
      await write.discard();
      throw error;
    } finally {
      reader.releaseLock();
    }
  }

  async #writeList(
    handle: DurableCacheStorageHandle,
    entries: readonly CacheStorageEntry[],
    revision: number,
    assigned?: readonly (string | null)[],
  ): Promise<void> {
    const writer = new RecordWriter();
    writer.u32(FORMAT_VERSION);
    writer.u32(revision);
    writer.u32(entries.length);
    for (let index = 0; index < entries.length; index++) {
      const entry = entries[index];
      if (entry === undefined) continue;
      writeRequest(writer, entry.request);
      writeResponse(writer, entry.response, assigned?.[index] ?? null);
    }
    const write = await this.#store.write(this.#namespace, LIST_PREFIX + handle.id, this.#signal);
    await write.append(writer.bytes());
    await write.commit();
  }

  async #writeNames(): Promise<void> {
    const writer = new RecordWriter();
    writer.u32(FORMAT_VERSION);
    writer.u32(this.#names.size);
    for (const [name, handle] of this.#names) {
      writer.text(name);
      writer.text(handle.id);
    }
    const write = await this.#store.write(this.#namespace, NAMES_KEY, this.#signal);
    await write.append(writer.bytes());
    await write.commit();
  }

  #requireHandle(handle: CacheStorageHandle): DurableCacheStorageHandle {
    if (!(handle instanceof DurableCacheStorageHandle) || handle.owner !== this.#owner) {
      throw new TypeError("Cache handle does not belong to this store");
    }
    return handle;
  }
}

import { AbortController } from "../core/abort.ts";
import type { AbortSignal } from "../core/abort.ts";
import { TextDecoder, TextEncoder } from "../core/encoding.ts";
import { LimitError } from "../core/errors.ts";
import { _createBlobFromExternalSource } from "../file/blob.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type { ReadableStream } from "../streams/readable.ts";
import type { DurableByteStore, DurableWrite } from "../storage/durable.ts";
import type {
  HttpCacheBody,
  HttpCacheEntry,
  HttpCacheEntryMetadata,
  HttpCacheStore,
  HttpCacheVaryField,
  HttpCacheWriter,
} from "./store.ts";

const FORMAT_VERSION = 1;
const METADATA_PREFIX = "m";
const BODY_PREFIX = "b";

/**
 * Length-prefixed framing for one entry's metadata.
 *
 * Every variable-length field carries its own byte length, so nothing is delimited by
 * a byte a value could contain -- a header value may hold anything, and a scan for the
 * next separator would split one field into two.
 *
 * The framing is not the one {@link DurableByteStore.list} uses for records. That one
 * is shaped by what a provider can emit cheaply across a foreign-function boundary;
 * this one is written and read by shared TypeScript at both ends, so it can use fixed
 * binary prefixes and needs no scanning at all.
 */
class MetadataWriter {
  readonly #parts: Uint8Array[] = [];
  readonly #encoder = new TextEncoder();
  #length = 0;

  #push(bytes: Uint8Array): void {
    this.#parts.push(bytes);
    this.#length += bytes.length;
  }

  u32(value: number): void {
    const bytes = new Uint8Array(4);
    bytes[0] = (value >>> 24) & 0xff;
    bytes[1] = (value >>> 16) & 0xff;
    bytes[2] = (value >>> 8) & 0xff;
    bytes[3] = value & 0xff;
    this.#push(bytes);
  }

  /**
   * A safe integer as two 32-bit halves.
   *
   * Wall-clock milliseconds do not fit in 32 bits, and a decimal round-trip through a
   * string would make the codec depend on number parsing to be exact.
   */
  u53(value: number): void {
    this.u32(Math.floor(value / 0x100000000));
    this.u32(value >>> 0);
  }

  text(value: string): void {
    const bytes = this.#encoder.encode(value);
    this.u32(bytes.length);
    this.#push(bytes);
  }

  bytes(): Uint8Array {
    const out = new Uint8Array(this.#length);
    let offset = 0;
    for (const part of this.#parts) {
      out.set(part, offset);
      offset += part.length;
    }
    return out;
  }
}

class MetadataReader {
  readonly #bytes: Uint8Array;
  readonly #decoder = new TextDecoder();
  #offset = 0;

  constructor(bytes: Uint8Array) {
    this.#bytes = bytes;
  }

  u32(): number {
    if (this.#offset + 4 > this.#bytes.length) {
      throw new TypeError("Truncated cache metadata");
    }
    const value =
      ((this.#bytes[this.#offset] ?? 0) << 24) |
      ((this.#bytes[this.#offset + 1] ?? 0) << 16) |
      ((this.#bytes[this.#offset + 2] ?? 0) << 8) |
      (this.#bytes[this.#offset + 3] ?? 0);
    this.#offset += 4;
    return value >>> 0;
  }

  u53(): number {
    const high = this.u32();
    return high * 0x100000000 + this.u32();
  }

  text(): string {
    const length = this.u32();
    if (this.#offset + length > this.#bytes.length) {
      throw new TypeError("Truncated cache metadata");
    }
    const value = this.#decoder.decode(this.#bytes.subarray(this.#offset, this.#offset + length));
    this.#offset += length;
    return value;
  }
}

function encodeMetadata(metadata: HttpCacheEntryMetadata): Uint8Array {
  const writer = new MetadataWriter();
  writer.u32(FORMAT_VERSION);
  writer.text(metadata.url);
  writer.text(metadata.method);
  writer.u32(metadata.status);
  writer.text(metadata.statusText);
  writer.u53(metadata.requestTime);
  writer.u53(metadata.responseTime);
  writer.u32(metadata.requestHeaders.length);
  for (const [name, value] of metadata.requestHeaders) {
    writer.text(name);
    writer.text(value);
  }
  writer.u32(metadata.responseHeaders.length);
  for (const [name, value] of metadata.responseHeaders) {
    writer.text(name);
    writer.text(value);
  }
  writer.u32(metadata.vary.length);
  for (const field of metadata.vary) {
    writer.text(field.name);
    writer.u32(field.value === null ? 0 : 1);
    if (field.value !== null) writer.text(field.value);
  }
  return writer.bytes();
}

function decodeMetadata(bytes: Uint8Array): HttpCacheEntryMetadata | null {
  const reader = new MetadataReader(bytes);
  // A record this process cannot read is discarded rather than guessed at. Version 1
  // is the only version, so this is what a future format change lands on.
  if (reader.u32() !== FORMAT_VERSION) return null;
  const url = reader.text();
  const method = reader.text();
  if (method !== "GET" && method !== "HEAD") return null;
  const status = reader.u32();
  const statusText = reader.text();
  const requestTime = reader.u53();
  const responseTime = reader.u53();
  const requestHeaders: HeaderEntry[] = [];
  for (let count = reader.u32(); count > 0; count--) {
    requestHeaders.push([reader.text(), reader.text()]);
  }
  const responseHeaders: HeaderEntry[] = [];
  for (let count = reader.u32(); count > 0; count--) {
    responseHeaders.push([reader.text(), reader.text()]);
  }
  const vary: HttpCacheVaryField[] = [];
  for (let count = reader.u32(); count > 0; count--) {
    const name = reader.text();
    vary.push({ name, value: reader.u32() === 0 ? null : reader.text() });
  }
  return {
    url,
    method,
    requestHeaders,
    status,
    statusText,
    responseHeaders,
    vary,
    requestTime,
    responseTime,
  };
}

function equalVary(
  left: readonly HttpCacheVaryField[],
  right: readonly HttpCacheVaryField[],
): boolean {
  if (left.length !== right.length) return false;
  for (let index = 0; index < left.length; index++) {
    const a = left[index];
    const b = right[index];
    if (a === undefined || b === undefined || a.name !== b.name || a.value !== b.value) {
      return false;
    }
  }
  return true;
}

function validateLimit(value: number | undefined, fallback: number, name: string): number {
  const result = value ?? fallback;
  if (!Number.isSafeInteger(result) || result < 0) {
    throw new RangeError("Invalid durable cache " + name);
  }
  return result;
}

export interface DurableHttpCacheStoreOptions {
  /** Defaults to `"http-cache"`. */
  namespace?: string;
  /** Defaults to 1024. */
  maxEntries?: number;
  /** Defaults to 100 MiB. */
  maxTotalBytes?: number;
  /** Defaults to 5 MiB. */
  maxEntryBytes?: number;
}

class DurableHttpCacheBody implements HttpCacheBody {
  readonly length: number;
  readonly #store: DurableByteStore;
  readonly #namespace: string;
  readonly #key: string;
  readonly #signal: AbortSignal;

  constructor(
    store: DurableByteStore,
    namespace: string,
    key: string,
    length: number,
    signal: AbortSignal,
  ) {
    this.#store = store;
    this.#namespace = namespace;
    this.#key = key;
    this.length = length;
    this.#signal = signal;
  }

  async open(): Promise<ReadableStream<Uint8Array>> {
    const source = await this.#store.source(this.#namespace, this.#key, this.#signal);
    if (source === null) throw new TypeError("The cached body is no longer stored");
    // Blob already drives a `BlobExternalReader` correctly -- ownership per chunk,
    // empty chunks invalid, `undefined` for the end. A second implementation here
    // would be a second answer to a question already answered.
    return _createBlobFromExternalSource(source).stream();
  }
}

/** One entry as this store hands it out; the id is how `touch` finds it again. */
class DurableCacheEntry implements HttpCacheEntry {
  readonly url: string;
  readonly method: "GET" | "HEAD";
  readonly requestHeaders: readonly HeaderEntry[];
  readonly status: number;
  readonly statusText: string;
  readonly responseHeaders: readonly HeaderEntry[];
  readonly vary: readonly HttpCacheVaryField[];
  readonly requestTime: number;
  readonly responseTime: number;
  readonly body: HttpCacheBody | null;
  readonly id: string;
  readonly bodyLength: number;
  used: number;

  constructor(
    id: string,
    metadata: HttpCacheEntryMetadata,
    body: HttpCacheBody | null,
    bodyLength: number,
    used: number,
  ) {
    this.id = id;
    this.url = metadata.url;
    this.method = metadata.method;
    this.requestHeaders = metadata.requestHeaders;
    this.status = metadata.status;
    this.statusText = metadata.statusText;
    this.responseHeaders = metadata.responseHeaders;
    this.vary = metadata.vary;
    this.requestTime = metadata.requestTime;
    this.responseTime = metadata.responseTime;
    this.body = body;
    this.bodyLength = bodyLength;
    this.used = used;
  }
}

class DurableHttpCacheWriter implements HttpCacheWriter {
  readonly #store: DurableHttpCacheStore;
  readonly #metadata: HttpCacheEntryMetadata;
  readonly #id: string;
  readonly #write: DurableWrite;
  #length = 0;
  #finished = false;

  constructor(
    store: DurableHttpCacheStore,
    metadata: HttpCacheEntryMetadata,
    id: string,
    write: DurableWrite,
  ) {
    this.#store = store;
    this.#metadata = metadata;
    this.#id = id;
    this.#write = write;
  }

  async write(chunk: Uint8Array): Promise<void> {
    if (this.#finished) throw new TypeError("Cache write is already finished");
    const next = this.#length + chunk.length;
    if (next > this.#store.maxEntryBytes) {
      // The bytes already appended stay in the uncommitted write, which is discarded
      // by `abort`. Nothing was published, so nothing has to be undone.
      throw new LimitError("HTTP cache entry exceeded configured byte limit");
    }
    await this.#write.append(chunk);
    this.#length = next;
  }

  async commit(): Promise<void> {
    if (this.#finished) throw new TypeError("Cache write is already finished");
    this.#finished = true;
    await this.#store._publish(this.#id, this.#metadata, this.#write, this.#length);
  }

  async abort(_reason: unknown): Promise<void> {
    if (this.#finished) return;
    this.#finished = true;
    await this.#write.discard();
  }
}

/**
 * A persistent {@link HttpCacheStore} over the provider-neutral byte store.
 *
 * RFC policy, matching and eviction stay in shared TypeScript exactly as they are for
 * the memory store; only the bytes cross the provider boundary. That is the whole point
 * of the pairing -- a filesystem cache and an Android cache differ in where bytes land
 * and nowhere else.
 *
 * **Metadata and body are separate keys, and the order they are written in is the crash
 * story.** The byte store makes one key's replacement atomic and says nothing about two,
 * so a commit writes the body first and the metadata second. An interrupted commit
 * therefore leaves either nothing or a body no metadata names -- never metadata naming
 * a body that is not there. Deleting runs the other way round, metadata first, so the
 * same invariant holds. Orphaned bodies are reclaimed by {@link DurableHttpCacheStore.open}.
 *
 * The split pays for itself twice: `replaceMetadata` rewrites one small key and is
 * atomic for free, where a single-value layout would have had to rewrite the body to
 * change a header.
 *
 * **The index is in memory and this process is assumed to be the only writer.** `find`
 * reads no metadata; it consults an index built once at `open`. A second process writing
 * the same namespace would not be seen, and the byte store cannot make it visible --
 * refusing a concurrent write to one key is not the same as coordinating two openers.
 *
 * **Eviction order does not survive a restart.** `touch` records recency in the index
 * and writes nothing: persisting it would mean a durable write on every cache *hit*,
 * which is a real cost paid for a heuristic. After a restart, entries are ordered by
 * the commit time the provider recorded.
 */
export class DurableHttpCacheStore implements HttpCacheStore {
  readonly maxEntryBytes: number;
  readonly #store: DurableByteStore;
  readonly #namespace: string;
  readonly #maxEntries: number;
  readonly #maxTotalBytes: number;
  readonly #signal: AbortSignal;
  readonly #entries = new Map<string, DurableCacheEntry>();
  #totalBytes = 0;
  #nextId = 0;
  #used = 0;

  private constructor(store: DurableByteStore, options: DurableHttpCacheStoreOptions) {
    this.#store = store;
    this.#namespace = options.namespace ?? "http-cache";
    this.#maxEntries = validateLimit(options.maxEntries, 1024, "entry count");
    this.#maxTotalBytes = validateLimit(options.maxTotalBytes, 100 * 1024 * 1024, "total bytes");
    this.maxEntryBytes = validateLimit(options.maxEntryBytes, 5 * 1024 * 1024, "entry bytes");
    this.#signal = new AbortController().signal;
  }

  /**
   * Reads the namespace once, building the index and reclaiming orphans.
   *
   * A body with no metadata is an interrupted commit or an interrupted delete; either
   * way nothing can name it again, so it is removed. A metadata record that does not
   * decode is discarded with its body for the same reason.
   */
  static async open(
    store: DurableByteStore,
    options: DurableHttpCacheStoreOptions = {},
  ): Promise<DurableHttpCacheStore> {
    const cache = new DurableHttpCacheStore(store, options);
    const records = await store.list(cache.#namespace, cache.#signal);
    const bodies = new Map<string, number>();
    const metadata: string[] = [];
    for (const record of records) {
      const id = record.key.slice(1);
      if (record.key.startsWith(BODY_PREFIX)) bodies.set(id, record.size);
      else if (record.key.startsWith(METADATA_PREFIX)) metadata.push(id);
    }

    // Ordered by id, which is allocated in commit order, so a restart falls back to
    // commit order for eviction rather than to whatever order the provider listed in.
    metadata.sort((left, right) => Number(left) - Number(right));

    for (const id of metadata) {
      const numeric = Number(id);
      if (Number.isSafeInteger(numeric) && numeric >= cache.#nextId) cache.#nextId = numeric + 1;
      const bytes = await store.read(cache.#namespace, METADATA_PREFIX + id, cache.#signal);
      const decoded = bytes === null ? null : decodeMetadata(bytes);
      const bodyLength = bodies.get(id);
      if (decoded === null || bodyLength === undefined) {
        await cache.#remove(id);
        continue;
      }
      bodies.delete(id);
      cache.#entries.set(
        id,
        new DurableCacheEntry(id, decoded, cache.#body(id, bodyLength), bodyLength, ++cache.#used),
      );
      cache.#totalBytes += bodyLength;
    }

    // Whatever is left named no metadata.
    for (const id of bodies.keys()) {
      await store.delete(cache.#namespace, BODY_PREFIX + id, cache.#signal);
    }
    await cache.#evict();
    return cache;
  }

  #body(id: string, length: number): HttpCacheBody {
    return new DurableHttpCacheBody(
      this.#store,
      this.#namespace,
      BODY_PREFIX + id,
      length,
      this.#signal,
    );
  }

  /** Metadata first, so a body is never named by metadata that outlives it. */
  async #remove(id: string): Promise<void> {
    await this.#store.delete(this.#namespace, METADATA_PREFIX + id, this.#signal);
    await this.#store.delete(this.#namespace, BODY_PREFIX + id, this.#signal);
    const entry = this.#entries.get(id);
    if (entry !== undefined) {
      this.#totalBytes -= entry.bodyLength;
      this.#entries.delete(id);
    }
  }

  async find(url: string): Promise<readonly HttpCacheEntry[]> {
    const result: HttpCacheEntry[] = [];
    for (const entry of this.#entries.values()) if (entry.url === url) result.push(entry);
    return result;
  }

  async createWrite(metadata: HttpCacheEntryMetadata): Promise<HttpCacheWriter | null> {
    if (this.#maxEntries === 0 || this.#maxTotalBytes === 0 || this.maxEntryBytes === 0) {
      return null;
    }
    const id = String(this.#nextId++);
    const write = await this.#store.write(this.#namespace, BODY_PREFIX + id, this.#signal);
    return new DurableHttpCacheWriter(this, metadata, id, write);
  }

  async touch(entry: HttpCacheEntry): Promise<void> {
    if (!(entry instanceof DurableCacheEntry)) return;
    if (this.#entries.get(entry.id) !== entry) return;
    entry.used = ++this.#used;
  }

  async replaceMetadata(
    entry: HttpCacheEntry,
    metadata: HttpCacheEntryMetadata,
  ): Promise<HttpCacheEntry | null> {
    if (!(entry instanceof DurableCacheEntry)) return null;
    const current = this.#entries.get(entry.id);
    if (current !== entry) return null;
    // One key, so this is atomic without the body being touched at all.
    const write = await this.#store.write(
      this.#namespace,
      METADATA_PREFIX + entry.id,
      this.#signal,
    );
    await write.append(encodeMetadata(metadata));
    await write.commit();
    const replacement = new DurableCacheEntry(
      entry.id,
      metadata,
      entry.body,
      entry.bodyLength,
      ++this.#used,
    );
    this.#entries.set(entry.id, replacement);
    return replacement;
  }

  async delete(url: string): Promise<void> {
    const doomed: string[] = [];
    for (const entry of this.#entries.values()) if (entry.url === url) doomed.push(entry.id);
    for (const id of doomed) await this.#remove(id);
  }

  /** @internal Publication point used by the write transaction. */
  async _publish(
    id: string,
    metadata: HttpCacheEntryMetadata,
    write: DurableWrite,
    length: number,
  ): Promise<void> {
    // Body first. Until its metadata lands nothing names it, so an interruption here
    // costs a reclaimable orphan and never a dangling reference.
    await write.commit();
    const metadataWrite = await this.#store.write(
      this.#namespace,
      METADATA_PREFIX + id,
      this.#signal,
    );
    await metadataWrite.append(encodeMetadata(metadata));
    await metadataWrite.commit();

    const superseded: string[] = [];
    for (const entry of this.#entries.values()) {
      if (
        entry.url === metadata.url &&
        entry.method === metadata.method &&
        equalVary(entry.vary, metadata.vary)
      ) {
        superseded.push(entry.id);
      }
    }
    for (const old of superseded) await this.#remove(old);

    this.#entries.set(
      id,
      new DurableCacheEntry(id, metadata, this.#body(id, length), length, ++this.#used),
    );
    this.#totalBytes += length;
    await this.#evict();
  }

  async #evict(): Promise<void> {
    while (this.#entries.size > this.#maxEntries || this.#totalBytes > this.#maxTotalBytes) {
      let oldest: DurableCacheEntry | null = null;
      for (const entry of this.#entries.values()) {
        if (oldest === null || entry.used < oldest.used) oldest = entry;
      }
      if (oldest === null) return;
      await this.#remove(oldest.id);
    }
  }
}

import { parseDeltaSeconds } from "./cache-control.ts";
import type { CacheControlDirectives, ParsedCacheControl } from "./cache-control.ts";
import { trimHTTPTabOrSpace } from "../core/ascii.ts";

const months = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
const shortWeekdays = ["sun", "mon", "tue", "wed", "thu", "fri", "sat"];
const longWeekdays = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];

function decimal(value: string, start: number, length: number): number {
  let result = 0;
  for (let index = start; index < start + length; index++) {
    const code = value.charCodeAt(index);
    if (code < 48 || code > 57) return -1;
    result = result * 10 + code - 48;
  }
  return result;
}

function monthIndex(value: string): number {
  return months.indexOf(value.toLowerCase());
}

function validShortWeekday(value: string): boolean {
  return shortWeekdays.includes(value.toLowerCase());
}

function validLongWeekday(value: string): boolean {
  return longWeekdays.includes(value.toLowerCase());
}

function makeTime(
  year: number,
  month: number,
  day: number,
  hour: number,
  minute: number,
  second: number,
): number | null {
  if (
    year < 1601 ||
    month < 0 ||
    month > 11 ||
    day < 1 ||
    day > 31 ||
    hour < 0 ||
    hour > 23 ||
    minute < 0 ||
    minute > 59 ||
    second < 0 ||
    second > 60
  ) {
    return null;
  }
  const ordinarySecond = second === 60 ? 59 : second;
  const base = Date.UTC(year, month, day, hour, minute, ordinarySecond);
  const date = new Date(base);
  if (
    !Number.isFinite(base) ||
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month ||
    date.getUTCDate() !== day ||
    date.getUTCHours() !== hour ||
    date.getUTCMinutes() !== minute ||
    date.getUTCSeconds() !== ordinarySecond
  ) {
    return null;
  }
  return second === 60 ? base + 1000 : base;
}

function parseIMFFixdate(value: string): number | null {
  if (
    value.length !== 29 ||
    !validShortWeekday(value.slice(0, 3)) ||
    value.slice(3, 5) !== ", " ||
    value.charCodeAt(7) !== 32 ||
    value.charCodeAt(11) !== 32 ||
    value.charCodeAt(16) !== 32 ||
    value.charCodeAt(19) !== 58 ||
    value.charCodeAt(22) !== 58 ||
    value.charCodeAt(25) !== 32 ||
    value.slice(26).toLowerCase() !== "gmt"
  ) {
    return null;
  }
  return makeTime(
    decimal(value, 12, 4),
    monthIndex(value.slice(8, 11)),
    decimal(value, 5, 2),
    decimal(value, 17, 2),
    decimal(value, 20, 2),
    decimal(value, 23, 2),
  );
}

function parseRFC850Date(value: string, now: number): number | null {
  const comma = value.indexOf(",");
  if (
    comma < 6 ||
    !validLongWeekday(value.slice(0, comma)) ||
    value.slice(comma, comma + 2) !== ", " ||
    value.length !== comma + 24 ||
    value.charCodeAt(comma + 4) !== 45 ||
    value.charCodeAt(comma + 8) !== 45 ||
    value.charCodeAt(comma + 11) !== 32 ||
    value.charCodeAt(comma + 14) !== 58 ||
    value.charCodeAt(comma + 17) !== 58 ||
    value.charCodeAt(comma + 20) !== 32 ||
    value.slice(comma + 21).toLowerCase() !== "gmt"
  ) {
    return null;
  }
  const shortYear = decimal(value, comma + 9, 2);
  if (shortYear < 0) return null;
  const currentYear = new Date(now).getUTCFullYear();
  let year = Math.floor(currentYear / 100) * 100 + shortYear;
  if (year > currentYear + 50) year -= 100;
  return makeTime(
    year,
    monthIndex(value.slice(comma + 5, comma + 8)),
    decimal(value, comma + 2, 2),
    decimal(value, comma + 12, 2),
    decimal(value, comma + 15, 2),
    decimal(value, comma + 18, 2),
  );
}

function parseASCTime(value: string): number | null {
  if (
    value.length !== 24 ||
    !validShortWeekday(value.slice(0, 3)) ||
    value.charCodeAt(3) !== 32 ||
    value.charCodeAt(7) !== 32 ||
    value.charCodeAt(10) !== 32 ||
    value.charCodeAt(13) !== 58 ||
    value.charCodeAt(16) !== 58 ||
    value.charCodeAt(19) !== 32
  ) {
    return null;
  }
  const day = value.charCodeAt(8) === 32 ? decimal(value, 9, 1) : decimal(value, 8, 2);
  return makeTime(
    decimal(value, 20, 4),
    monthIndex(value.slice(4, 7)),
    day,
    decimal(value, 11, 2),
    decimal(value, 14, 2),
    decimal(value, 17, 2),
  );
}

/** RFC 9110 HTTP-date parsing without host-dependent `Date.parse`. */
export function parseHTTPDate(value: string, now: number): number | null {
  if (!Number.isFinite(now)) return null;
  return parseIMFFixdate(value) ?? parseRFC850Date(value, now) ?? parseASCTime(value);
}

/** Parse the first Age list member, discarding later members per RFC 9111. */
export function parseAge(value: string): number | null {
  const comma = value.indexOf(",");
  return parseDeltaSeconds(trimHTTPTabOrSpace(comma < 0 ? value : value.slice(0, comma)));
}

export interface StoredResponseTiming {
  /** Milliseconds when the request was sent. */
  readonly requestTime: number;
  /** Milliseconds when the response headers arrived. */
  readonly responseTime: number;
  /** Parsed Date field, or responseTime when Date was absent or invalid. */
  readonly dateValue: number;
  /** Parsed Age value in seconds, saturated per RFC 9111. */
  readonly ageValue: number;
}

/** RFC 9111 section 4.2.3 corrected age, in seconds. */
export function currentAgeSeconds(timing: StoredResponseTiming, now: number): number {
  const responseDelay = Math.max(0, (timing.responseTime - timing.requestTime) / 1000);
  const apparentAge = Math.max(0, (timing.responseTime - timing.dateValue) / 1000);
  const correctedAgeValue = Math.max(0, timing.ageValue) + responseDelay;
  const correctedInitialAge = Math.max(apparentAge, correctedAgeValue);
  const residentTime = Math.max(0, (now - timing.responseTime) / 1000);
  return correctedInitialAge + residentTime;
}

export interface FreshnessLifetimeInput {
  readonly shared: boolean;
  readonly parsed: ParsedCacheControl;
  readonly responseTime: number;
  readonly dateValue: number;
  /** `undefined` means absent; `null` means present but invalid. */
  readonly expiresValue?: number | null;
  readonly lastModifiedValue?: number | null;
  /** Whether status/method policy permits heuristic freshness. */
  readonly heuristicAllowed: boolean;
  /** Defaults to the conventional RFC 9111 example of ten percent. */
  readonly heuristicFraction?: number;
}

export type FreshnessSource = "s-maxage" | "max-age" | "expires" | "heuristic" | "none";

export interface FreshnessLifetime {
  readonly seconds: number;
  readonly source: FreshnessSource;
}

/** RFC 9111 section 4.2.1 freshness lifetime, before request constraints. */
export function freshnessLifetime(input: FreshnessLifetimeInput): FreshnessLifetime {
  const directives = input.parsed.directives;
  if (input.parsed.duplicateFreshnessDirective) return { seconds: 0, source: "none" };
  if (input.shared && directives.sMaxage !== undefined) {
    return { seconds: directives.sMaxage, source: "s-maxage" };
  }
  if (directives.maxAge !== undefined) {
    return { seconds: directives.maxAge, source: "max-age" };
  }
  if (input.expiresValue !== undefined) {
    if (input.expiresValue === null) return { seconds: 0, source: "expires" };
    return {
      seconds: Math.max(0, (input.expiresValue - input.dateValue) / 1000),
      source: "expires",
    };
  }
  if (
    input.heuristicAllowed &&
    input.lastModifiedValue !== undefined &&
    input.lastModifiedValue !== null
  ) {
    const fraction = input.heuristicFraction ?? 0.1;
    if (!Number.isFinite(fraction) || fraction < 0 || fraction > 1) {
      throw new RangeError("Invalid heuristic freshness fraction");
    }
    return {
      seconds: Math.max(0, ((input.dateValue - input.lastModifiedValue) / 1000) * fraction),
      source: "heuristic",
    };
  }
  return { seconds: 0, source: "none" };
}

export type CacheReuseDecision = "fresh" | "stale-allowed" | "revalidate";

export interface CacheReuseInput {
  readonly currentAge: number;
  readonly freshnessLifetime: number;
  readonly request: CacheControlDirectives;
  readonly response: CacheControlDirectives;
  readonly shared: boolean;
}

/** Apply request constraints and stale permissions to a stored response. */
export function cacheReuseDecision(input: CacheReuseInput): CacheReuseDecision {
  if (input.request.noCache !== undefined || input.response.noCache === true) {
    return "revalidate";
  }
  let lifetime = input.freshnessLifetime;
  if (input.request.maxAge !== undefined) lifetime = Math.min(lifetime, input.request.maxAge);
  const ageWithRequiredFreshness = input.currentAge + (input.request.minFresh ?? 0);
  if (ageWithRequiredFreshness < lifetime) return "fresh";

  if (
    input.response.mustRevalidate === true ||
    (input.shared &&
      (input.response.proxyRevalidate === true || input.response.sMaxage !== undefined))
  ) {
    return "revalidate";
  }
  const maxStale = input.request.maxStale;
  if (maxStale === true) return "stale-allowed";
  if (typeof maxStale === "number" && input.currentAge - lifetime <= maxStale) {
    return "stale-allowed";
  }
  return "revalidate";
}

import { trimHTTPTabOrSpace } from "../core/ascii.ts";
import { ignoreRejection } from "../core/promise.ts";
import type { URLParser, URLRecord } from "../provider/primitives.ts";
import { ReadableStream } from "../streams/readable.ts";
import type { RequestCache } from "../fetch/request.ts";
import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import { isToken } from "../fetch/headers.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import { MAX_DELTA_SECONDS, parseCacheControl } from "./cache-control.ts";
import type { CacheControlDirectives, ParsedCacheControl } from "./cache-control.ts";
import {
  cacheReuseDecision,
  currentAgeSeconds,
  freshnessLifetime,
  parseAge,
  parseHTTPDate,
} from "./freshness.ts";
import type {
  HttpCacheEntry,
  HttpCacheEntryMetadata,
  HttpCacheStore,
  HttpCacheVaryField,
  HttpCacheWriter,
} from "./store.ts";

export type HttpCacheType = "private" | "shared";
export type HttpCacheState = "network" | "local" | "stale" | "validated";

export interface HttpCacheDiagnostics {
  storeError(error: unknown): void;
}

export interface HttpCacheOptions {
  readonly store: HttpCacheStore;
  readonly type?: HttpCacheType;
  readonly wallTimeMilliseconds: () => number;
  /** Canonical environment URL parser used for relative invalidation targets. */
  readonly urls: URLParser;
  readonly heuristicFraction?: number;
  readonly diagnostics?: HttpCacheDiagnostics;
}

export interface HttpCacheDispatchResult {
  readonly response: TransportResponse;
  /** Headers actually received from the network; null for a pure cache hit. */
  readonly receivedHeaders: readonly HeaderEntry[] | null;
  readonly cacheState: HttpCacheState;
}

interface SelectedEntry {
  readonly entry: HttpCacheEntry;
  readonly age: number;
  readonly lifetime: number;
  readonly requestDirectives: CacheControlDirectives;
  readonly responseDirectives: CacheControlDirectives;
}

interface BackgroundRevalidation {
  readonly key: string;
  readonly promise: Promise<void>;
}

function keyURL(url: URLRecord): string {
  const hash = url.href.indexOf("#");
  return hash < 0 ? url.href : url.href.slice(0, hash);
}

function headerValues(headers: readonly HeaderEntry[], name: string): string[] {
  const result: string[] = [];
  for (const entry of headers) if (entry[0].toLowerCase() === name) result.push(entry[1]);
  return result;
}

function headerValue(headers: readonly HeaderEntry[], name: string): string | null {
  const values = headerValues(headers, name);
  return values.length === 0 ? null : values.join(", ");
}

function firstHeaderValue(headers: readonly HeaderEntry[], name: string): string | null {
  for (const entry of headers) if (entry[0].toLowerCase() === name) return entry[1];
  return null;
}

function parseHeaderCacheControl(headers: readonly HeaderEntry[]): ParsedCacheControl {
  return parseCacheControl(headerValue(headers, "cache-control") ?? "");
}

function normalizeVaryValue(value: string): string {
  let result = "";
  let pendingSpace = false;
  for (let index = 0; index < value.length; index++) {
    const code = value.charCodeAt(index);
    if (code === 9 || code === 32) {
      pendingSpace = result.length > 0;
    } else {
      if (pendingSpace) result += " ";
      result += value.charAt(index);
      pendingSpace = false;
    }
  }
  return result;
}

function requestHeaderValue(headers: readonly HeaderEntry[], name: string): string | null {
  const value = headerValue(headers, name);
  return value === null ? null : normalizeVaryValue(value);
}

/** Return the stored Vary key, or null for the unmatchable `Vary: *`. */
export function createVaryKey(
  responseHeaders: readonly HeaderEntry[],
  requestHeaders: readonly HeaderEntry[],
): HttpCacheVaryField[] | null {
  const value = headerValue(responseHeaders, "vary");
  if (value === null) return [];
  if (trimHTTPTabOrSpace(value).length === 0) return [];
  const names: string[] = [];
  let start = 0;
  for (let index = 0; index <= value.length; index++) {
    if (index !== value.length && value.charCodeAt(index) !== 44) continue;
    const name = trimHTTPTabOrSpace(value.slice(start, index)).toLowerCase();
    if (name.length === 0) {
      start = index + 1;
      continue;
    }
    if (name === "*") return null;
    if (!isToken(name)) return null;
    if (!names.includes(name)) names.push(name);
    start = index + 1;
  }
  names.sort();
  const result: HttpCacheVaryField[] = [];
  for (const name of names) result.push({ name, value: requestHeaderValue(requestHeaders, name) });
  return result;
}

export function varyMatches(
  vary: readonly HttpCacheVaryField[],
  requestHeaders: readonly HeaderEntry[],
): boolean {
  for (const field of vary) {
    if (requestHeaderValue(requestHeaders, field.name) !== field.value) return false;
  }
  return true;
}

function isHeuristicallyCacheableStatus(status: number): boolean {
  return (
    status === 200 ||
    status === 203 ||
    status === 204 ||
    status === 300 ||
    status === 301 ||
    status === 308 ||
    status === 404 ||
    status === 405 ||
    status === 410 ||
    status === 414 ||
    status === 501
  );
}

function statusIsUnderstood(status: number): boolean {
  return (status >= 200 && status <= 599 && status !== 206) || status === 304;
}

function hasExplicitFreshness(
  directives: CacheControlDirectives,
  headers: readonly HeaderEntry[],
  shared: boolean,
): boolean {
  return (
    directives.public === true ||
    directives.private !== undefined ||
    directives.maxAge !== undefined ||
    (shared && directives.sMaxage !== undefined) ||
    firstHeaderValue(headers, "expires") !== null
  );
}

/** RFC 9111 storage eligibility for the complete-response subset this cache implements. */
export function isResponseStorable(
  request: TransportRequest,
  response: TransportResponse,
  shared: boolean,
): boolean {
  if (request.method !== "GET" && request.method !== "HEAD") return false;
  if (response.status === 206 || response.status === 304) return false;
  const requestControl = parseHeaderCacheControl(request.headers).directives;
  const responseControl = parseHeaderCacheControl(response.headers).directives;
  if (requestControl.noStore === true || responseControl.noStore === true) return false;
  if (responseControl.mustUnderstand === true && !statusIsUnderstood(response.status)) return false;
  if (shared && responseControl.private === true) return false;
  if (
    shared &&
    headerValue(request.headers, "authorization") !== null &&
    responseControl.public !== true &&
    responseControl.mustRevalidate !== true &&
    responseControl.sMaxage === undefined
  ) {
    return false;
  }
  if (createVaryKey(response.headers, request.headers) === null) return false;
  return (
    hasExplicitFreshness(responseControl, response.headers, shared) ||
    isHeuristicallyCacheableStatus(response.status)
  );
}

function connectionFieldNames(headers: readonly HeaderEntry[]): string[] {
  const result = [
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authentication-info",
    "proxy-authorization",
    "te",
    "trailer",
    "transfer-encoding",
    "upgrade",
  ];
  const connection = headerValue(headers, "connection");
  if (connection === null) return result;
  for (const member of connection.split(",")) {
    const name = trimHTTPTabOrSpace(member).toLowerCase();
    if (isToken(name) && !result.includes(name)) result.push(name);
  }
  return result;
}

function storedResponseHeaders(
  headers: readonly HeaderEntry[],
  directives: CacheControlDirectives,
  shared: boolean,
): HeaderEntry[] {
  const excluded = connectionFieldNames(headers);
  if (Array.isArray(directives.noCache)) {
    for (const name of directives.noCache) if (!excluded.includes(name)) excluded.push(name);
  }
  if (shared && Array.isArray(directives.private)) {
    for (const name of directives.private) if (!excluded.includes(name)) excluded.push(name);
  }
  if (shared && !excluded.includes("set-cookie")) excluded.push("set-cookie");
  const result: HeaderEntry[] = [];
  for (const entry of headers) {
    if (!excluded.includes(entry[0].toLowerCase())) result.push([entry[0].toLowerCase(), entry[1]]);
  }
  return result;
}

function setHeader(headers: readonly HeaderEntry[], name: string, value: string): HeaderEntry[] {
  const result: HeaderEntry[] = [];
  for (const entry of headers) if (entry[0].toLowerCase() !== name) result.push(entry);
  result.push([name, value]);
  return result;
}

function copyRequest(request: TransportRequest, headers: readonly HeaderEntry[]): TransportRequest {
  return {
    url: request.url,
    method: request.method,
    headers,
    body: request.body,
    bodyLength: request.bodyLength,
    replayBody: request.replayBody,
    signal: request.signal,
  };
}

function requestHasConditional(headers: readonly HeaderEntry[]): boolean {
  return (
    headerValue(headers, "if-modified-since") !== null ||
    headerValue(headers, "if-none-match") !== null ||
    headerValue(headers, "if-unmodified-since") !== null ||
    headerValue(headers, "if-match") !== null ||
    headerValue(headers, "if-range") !== null
  );
}

function hasPragmaNoCache(headers: readonly HeaderEntry[]): boolean {
  const values = headerValues(headers, "pragma");
  for (const value of values) {
    let start = 0;
    for (let index = 0; index <= value.length; index++) {
      if (index !== value.length && value.charCodeAt(index) !== 44) continue;
      if (trimHTTPTabOrSpace(value.slice(start, index)).toLowerCase() === "no-cache") return true;
      start = index + 1;
    }
  }
  return false;
}

function revalidationKey(entry: HttpCacheEntry): string {
  let result = `${entry.method.length}:${entry.method}${entry.url.length}:${entry.url}`;
  for (const field of entry.vary) {
    result += `${field.name.length}:${field.name}`;
    result += field.value === null ? "-" : `${field.value.length}:${field.value}`;
  }
  return result;
}

function responseDate(entry: HttpCacheEntry, now: number): number {
  const value = firstHeaderValue(entry.responseHeaders, "date");
  return value === null ? entry.responseTime : (parseHTTPDate(value, now) ?? entry.responseTime);
}

function selectMoreRecent(
  left: HttpCacheEntry | null,
  right: HttpCacheEntry,
  now: number,
): HttpCacheEntry {
  if (left === null) return right;
  const leftDate = responseDate(left, now);
  const rightDate = responseDate(right, now);
  if (rightDate > leftDate || (rightDate === leftDate && right.responseTime > left.responseTime)) {
    return right;
  }
  return left;
}

function staleBySeconds(selected: SelectedEntry): number {
  return Math.max(0, selected.age - selected.lifetime);
}

function canServeStaleIfError(selected: SelectedEntry, shared: boolean): boolean {
  if (
    selected.responseDirectives.noCache !== undefined ||
    selected.responseDirectives.mustRevalidate === true ||
    (shared &&
      (selected.responseDirectives.proxyRevalidate === true ||
        selected.responseDirectives.sMaxage !== undefined))
  ) {
    return false;
  }
  const requestAllowance = selected.requestDirectives.staleIfError;
  const responseAllowance = selected.responseDirectives.staleIfError;
  const allowance =
    requestAllowance === undefined
      ? responseAllowance
      : responseAllowance === undefined
        ? requestAllowance
        : Math.min(requestAllowance, responseAllowance);
  return allowance !== undefined && staleBySeconds(selected) <= allowance;
}

function canServeStaleWhileRevalidate(selected: SelectedEntry, shared: boolean): boolean {
  const allowance = selected.responseDirectives.staleWhileRevalidate;
  return (
    allowance !== undefined &&
    staleBySeconds(selected) <= allowance &&
    selected.responseDirectives.noCache === undefined &&
    selected.responseDirectives.mustRevalidate !== true &&
    !(
      shared &&
      (selected.responseDirectives.proxyRevalidate === true ||
        selected.responseDirectives.sMaxage !== undefined)
    )
  );
}

function merge304Headers(
  stored: readonly HeaderEntry[],
  received: readonly HeaderEntry[],
): HeaderEntry[] {
  const excluded = connectionFieldNames(received);
  excluded.push("content-length");
  const replacements: string[] = [];
  for (const entry of received) {
    const name = entry[0].toLowerCase();
    if (!excluded.includes(name) && !replacements.includes(name)) replacements.push(name);
  }
  const result: HeaderEntry[] = [];
  for (const entry of stored) {
    if (!replacements.includes(entry[0].toLowerCase())) result.push(entry);
  }
  for (const entry of received) {
    if (!excluded.includes(entry[0].toLowerCase())) result.push([entry[0].toLowerCase(), entry[1]]);
  }
  return result;
}

export class HttpCache {
  private readonly store: HttpCacheStore;
  private readonly shared: boolean;
  private readonly clock: () => number;
  private readonly urls: URLParser;
  private readonly heuristicFraction: number | undefined;
  private readonly diagnostics: HttpCacheDiagnostics | undefined;
  private readonly background: BackgroundRevalidation[] = [];

  constructor(options: HttpCacheOptions) {
    this.store = options.store;
    this.shared = options.type === "shared";
    this.clock = options.wallTimeMilliseconds;
    this.urls = options.urls;
    this.heuristicFraction = options.heuristicFraction;
    this.diagnostics = options.diagnostics;
  }

  async dispatch(
    transport: FetchTransport,
    request: TransportRequest,
    cacheMode: RequestCache,
  ): Promise<HttpCacheDispatchResult> {
    const requestTime = this.now();
    const requestDirectives = parseHeaderCacheControl(request.headers).directives;
    let effectiveMode = cacheMode;
    if (effectiveMode === "default" && requestHasConditional(request.headers)) {
      effectiveMode = "no-store";
    }
    let outbound = request;
    if (effectiveMode === "no-cache" && headerValue(outbound.headers, "cache-control") === null) {
      outbound = copyRequest(outbound, setHeader(outbound.headers, "cache-control", "max-age=0"));
    } else if (effectiveMode === "no-store" || effectiveMode === "reload") {
      let headers = outbound.headers;
      if (headerValue(headers, "pragma") === null)
        headers = setHeader(headers, "pragma", "no-cache");
      if (headerValue(headers, "cache-control") === null) {
        headers = setHeader(headers, "cache-control", "no-cache");
      }
      outbound = copyRequest(outbound, headers);
    }

    if (outbound.method !== "GET" && outbound.method !== "HEAD") {
      const response = await transport.dispatch(outbound);
      if (this.isUnsafe(outbound.method) && response.status >= 200 && response.status <= 399) {
        await this.invalidate(outbound.url, response.headers);
      }
      return { response, receivedHeaders: response.headers, cacheState: "network" };
    }

    let selected: SelectedEntry | null = null;
    if (
      effectiveMode !== "no-store" &&
      effectiveMode !== "reload" &&
      requestDirectives.noStore !== true
    ) {
      selected = await this.select(outbound);
      if (selected !== null) {
        if (effectiveMode === "force-cache" || effectiveMode === "only-if-cached") {
          return this.serve(selected.entry, outbound.method, selected.age, "local");
        }
        const decision = cacheReuseDecision({
          currentAge: selected.age,
          freshnessLifetime: selected.lifetime,
          request: selected.requestDirectives,
          response: selected.responseDirectives,
          shared: this.shared,
        });
        if (effectiveMode === "default" && decision === "fresh") {
          return this.serve(selected.entry, outbound.method, selected.age, "local");
        }
        if (effectiveMode === "default" && canServeStaleWhileRevalidate(selected, this.shared)) {
          this.startBackgroundRevalidation(transport, outbound, selected);
          return this.serve(selected.entry, outbound.method, selected.age, "stale");
        }
        if (effectiveMode === "default" && decision === "stale-allowed") {
          return this.serve(selected.entry, outbound.method, selected.age, "stale");
        }
        const revalidated = await this.revalidate(transport, outbound, selected, requestTime);
        if (revalidated !== null) return revalidated;
      }
    }

    if (effectiveMode === "only-if-cached") {
      throw new TypeError("only-if-cached request had no matching stored response");
    }
    const response = await transport.dispatch(outbound);
    const responseTime = this.now();
    const stored =
      effectiveMode === "no-store" || requestDirectives.noStore === true
        ? response
        : await this.storeNetworkResponse(outbound, response, requestTime, responseTime);
    return { response: stored, receivedHeaders: response.headers, cacheState: "network" };
  }

  private now(): number {
    const value = this.clock();
    if (!Number.isFinite(value))
      throw new TypeError("HTTP cache clock returned a non-finite value");
    return value;
  }

  private isUnsafe(method: string): boolean {
    return method !== "GET" && method !== "HEAD" && method !== "OPTIONS";
  }

  private async invalidate(
    target: URLRecord,
    responseHeaders: readonly HeaderEntry[],
  ): Promise<void> {
    const urls = [keyURL(target)];
    for (const name of ["location", "content-location"]) {
      const values = headerValues(responseHeaders, name);
      // These fields carry one URI-reference, not a comma-list. Ambiguous duplicate
      // fields cannot be resolved safely and never suppress target invalidation.
      if (values.length !== 1) continue;
      let candidate: URLRecord;
      try {
        candidate = this.urls.parse(values[0] ?? "", target.href);
      } catch {
        continue;
      }
      if (candidate.origin !== target.origin) continue;
      const key = keyURL(candidate);
      if (!urls.includes(key)) urls.push(key);
    }
    for (const url of urls) {
      try {
        await this.store.delete(url);
      } catch (error) {
        this.reportStoreError(error);
      }
    }
  }

  private async select(request: TransportRequest): Promise<SelectedEntry | null> {
    const now = this.now();
    const entries = await this.store.find(keyURL(request.url));
    let match: HttpCacheEntry | null = null;
    for (const entry of entries) {
      if (
        entry.method !== request.method &&
        !(request.method === "HEAD" && entry.method === "GET")
      ) {
        continue;
      }
      if (!varyMatches(entry.vary, request.headers)) continue;
      match = selectMoreRecent(match, entry, now);
    }
    if (match === null) return null;

    const responseControl = parseHeaderCacheControl(match.responseHeaders);
    const requestControl = parseHeaderCacheControl(request.headers);
    if (
      headerValue(request.headers, "cache-control") === null &&
      hasPragmaNoCache(request.headers)
    ) {
      requestControl.directives.noCache = true;
    }
    const dateHeader = firstHeaderValue(match.responseHeaders, "date");
    const dateValue =
      dateHeader === null
        ? match.responseTime
        : (parseHTTPDate(dateHeader, now) ?? match.responseTime);
    const ageHeader = firstHeaderValue(match.responseHeaders, "age");
    const ageValue = ageHeader === null ? 0 : (parseAge(ageHeader) ?? 0);
    const expiresValues = headerValues(match.responseHeaders, "expires");
    const expiresValue =
      expiresValues.length === 0
        ? undefined
        : expiresValues.length > 1
          ? null
          : parseHTTPDate(expiresValues[0] ?? "", now);
    const modifiedHeader = firstHeaderValue(match.responseHeaders, "last-modified");
    const modifiedValue = modifiedHeader === null ? undefined : parseHTTPDate(modifiedHeader, now);
    const lifetime = freshnessLifetime({
      shared: this.shared,
      parsed: responseControl,
      responseTime: match.responseTime,
      dateValue,
      expiresValue,
      lastModifiedValue: modifiedValue,
      heuristicAllowed: isHeuristicallyCacheableStatus(match.status),
      heuristicFraction: this.heuristicFraction,
    }).seconds;
    const age = currentAgeSeconds(
      {
        requestTime: match.requestTime,
        responseTime: match.responseTime,
        dateValue,
        ageValue,
      },
      now,
    );
    return {
      entry: match,
      age,
      lifetime,
      requestDirectives: requestControl.directives,
      responseDirectives: responseControl.directives,
    };
  }

  private async serve(
    entry: HttpCacheEntry,
    requestMethod: string,
    age: number,
    state: HttpCacheState,
  ): Promise<HttpCacheDispatchResult> {
    await this.store.touch(entry);
    const seconds = Math.min(MAX_DELTA_SECONDS, Math.max(0, Math.floor(age)));
    const headers = setHeader(entry.responseHeaders, "age", `${seconds}`);
    const body = requestMethod === "HEAD" || entry.body === null ? null : await entry.body.open();
    return {
      response: {
        status: entry.status,
        statusText: entry.statusText,
        headers,
        body,
      },
      receivedHeaders: null,
      cacheState: state,
    };
  }

  private async revalidate(
    transport: FetchTransport,
    request: TransportRequest,
    selected: SelectedEntry,
    requestTime: number,
  ): Promise<HttpCacheDispatchResult | null> {
    let headers = request.headers;
    const etag = firstHeaderValue(selected.entry.responseHeaders, "etag");
    const modified = firstHeaderValue(selected.entry.responseHeaders, "last-modified");
    if (etag !== null && headerValue(headers, "if-none-match") === null) {
      headers = setHeader(headers, "if-none-match", etag);
    }
    if (modified !== null && headerValue(headers, "if-modified-since") === null) {
      headers = setHeader(headers, "if-modified-since", modified);
    }
    if (headers === request.headers) return null;

    let response: TransportResponse;
    try {
      response = await transport.dispatch(copyRequest(request, headers));
    } catch (error) {
      if (canServeStaleIfError(selected, this.shared)) {
        return this.serve(selected.entry, request.method, selected.age, "stale");
      }
      throw error;
    }
    const responseTime = this.now();
    if (
      (response.status === 500 ||
        response.status === 502 ||
        response.status === 503 ||
        response.status === 504) &&
      canServeStaleIfError(selected, this.shared)
    ) {
      response.body?.cancel().catch(() => {});
      return this.serve(selected.entry, request.method, selected.age, "stale");
    }
    if (response.status !== 304) {
      const stored = await this.storeNetworkResponse(request, response, requestTime, responseTime);
      return { response: stored, receivedHeaders: response.headers, cacheState: "network" };
    }

    response.body?.cancel().catch(() => {});
    const responseETag = firstHeaderValue(response.headers, "etag");
    if (responseETag !== null && etag !== null && responseETag !== etag) {
      throw new TypeError("Cache validation returned a mismatched ETag");
    }
    const mergedHeaders = merge304Headers(selected.entry.responseHeaders, response.headers);
    const vary = createVaryKey(mergedHeaders, request.headers);
    if (vary === null) {
      await this.store.delete(selected.entry.url);
      return this.serveEphemeral(selected.entry, mergedHeaders, request.method, response.headers);
    }
    const replacement = await this.store.replaceMetadata(selected.entry, {
      url: selected.entry.url,
      method: selected.entry.method,
      requestHeaders: selected.entry.requestHeaders,
      status: selected.entry.status,
      statusText: selected.entry.statusText,
      responseHeaders: mergedHeaders,
      vary,
      requestTime,
      responseTime,
    });
    if (replacement === null) {
      return this.serveEphemeral(selected.entry, mergedHeaders, request.method, response.headers);
    }
    const served = await this.serve(replacement, request.method, 0, "validated");
    return { ...served, receivedHeaders: response.headers };
  }

  private async serveEphemeral(
    entry: HttpCacheEntry,
    headers: readonly HeaderEntry[],
    requestMethod: string,
    receivedHeaders: readonly HeaderEntry[],
  ): Promise<HttpCacheDispatchResult> {
    const body = requestMethod === "HEAD" || entry.body === null ? null : await entry.body.open();
    return {
      response: {
        status: entry.status,
        statusText: entry.statusText,
        headers: setHeader(headers, "age", "0"),
        body,
      },
      receivedHeaders,
      cacheState: "validated",
    };
  }

  private startBackgroundRevalidation(
    transport: FetchTransport,
    request: TransportRequest,
    selected: SelectedEntry,
  ): void {
    const key = revalidationKey(selected.entry);
    for (const active of this.background) if (active.key === key) return;
    const promise = this.runBackgroundRevalidation(transport, request, selected);
    this.background.push({ key, promise });
    ignoreRejection(promise);
  }

  private async runBackgroundRevalidation(
    transport: FetchTransport,
    request: TransportRequest,
    selected: SelectedEntry,
  ): Promise<void> {
    const key = revalidationKey(selected.entry);
    try {
      const result = await this.revalidate(transport, request, selected, this.now());
      if (result === null) return;
      const body = result.response.body;
      if (body === null) return;
      if (result.cacheState !== "network") {
        await body.cancel();
        return;
      }
      const reader = body.getReader();
      try {
        while (!(await reader.read()).done) {
          // The write-through stream commits only after the complete response.
        }
      } finally {
        reader.releaseLock();
      }
    } catch (error) {
      this.reportStoreError(error);
    } finally {
      for (let index = 0; index < this.background.length; index++) {
        if (this.background[index]?.key === key) {
          this.background.splice(index, 1);
          break;
        }
      }
    }
  }

  private async storeNetworkResponse(
    request: TransportRequest,
    response: TransportResponse,
    requestTime: number,
    responseTime: number,
  ): Promise<TransportResponse> {
    if (!isResponseStorable(request, response, this.shared)) return response;
    const directives = parseHeaderCacheControl(response.headers).directives;
    const storedHeaders = storedResponseHeaders(response.headers, directives, this.shared);
    const vary = createVaryKey(storedHeaders, request.headers);
    if (vary === null) return response;
    const metadata: HttpCacheEntryMetadata = {
      url: keyURL(request.url),
      method: request.method === "HEAD" ? "HEAD" : "GET",
      requestHeaders: request.headers,
      status: response.status,
      statusText: response.statusText,
      responseHeaders: storedHeaders,
      vary,
      requestTime,
      responseTime,
    };
    let writer: HttpCacheWriter | null;
    try {
      writer = await this.store.createWrite(metadata);
    } catch (error) {
      this.reportStoreError(error);
      return response;
    }
    if (writer === null) return response;
    if (response.body === null) {
      try {
        await writer.commit();
      } catch (error) {
        this.reportStoreError(error);
        try {
          await writer.abort(error);
        } catch (abortError) {
          this.reportStoreError(abortError);
        }
      }
      return response;
    }
    return {
      status: response.status,
      statusText: response.statusText,
      headers: response.headers,
      body: this.writeThrough(response.body, writer),
    };
  }

  private writeThrough(
    source: ReadableStream<Uint8Array>,
    initialWriter: HttpCacheWriter,
  ): ReadableStream<Uint8Array> {
    const reader = source.getReader();
    let writer: HttpCacheWriter | null = initialWriter;
    let released = false;
    const reportStoreError = (error: unknown): void => this.reportStoreError(error);
    const release = (): void => {
      if (!released) {
        released = true;
        reader.releaseLock();
      }
    };
    const abandon = async (reason: unknown): Promise<void> => {
      const active = writer;
      writer = null;
      if (active === null) return;
      try {
        await active.abort(reason);
      } catch (error) {
        reportStoreError(error);
      }
    };
    return new ReadableStream<Uint8Array>(
      {
        async pull(controller) {
          try {
            const result = await reader.read();
            if (result.done) {
              const active = writer;
              writer = null;
              if (active !== null) {
                try {
                  await active.commit();
                } catch (error) {
                  reportStoreError(error);
                  try {
                    await active.abort(error);
                  } catch (abortError) {
                    reportStoreError(abortError);
                  }
                }
              }
              release();
              controller.close();
              return;
            }
            const active = writer;
            if (active !== null) {
              try {
                await active.write(result.value);
              } catch (error) {
                reportStoreError(error);
                await abandon(error);
              }
            }
            controller.enqueue(result.value);
          } catch (error) {
            await abandon(error);
            release();
            controller.error(error);
          }
        },
        async cancel(reason) {
          await abandon(reason);
          try {
            await reader.cancel(reason);
          } finally {
            release();
          }
        },
      },
      { highWaterMark: 0, size: (chunk) => chunk.length },
    );
  }

  private reportStoreError(error: unknown): void {
    try {
      this.diagnostics?.storeError(error);
    } catch {
      // Diagnostics never alter cache or Fetch semantics.
    }
  }
}

import { LimitError } from "../core/errors.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import { ReadableStream } from "../streams/readable.ts";

export interface HttpCacheVaryField {
  readonly name: string;
  readonly value: string | null;
}

export interface HttpCacheEntryMetadata {
  readonly url: string;
  readonly method: "GET" | "HEAD";
  readonly requestHeaders: readonly HeaderEntry[];
  readonly status: number;
  readonly statusText: string;
  readonly responseHeaders: readonly HeaderEntry[];
  readonly vary: readonly HttpCacheVaryField[];
  readonly requestTime: number;
  readonly responseTime: number;
}

/** A replayable body owned by a cache provider. */
export interface HttpCacheBody {
  readonly length: number;

  open(): Promise<ReadableStream<Uint8Array>>;
}

export interface HttpCacheEntry extends HttpCacheEntryMetadata {
  readonly body: HttpCacheBody | null;
}

/**
 * Transactional streaming write. `write` borrows the chunk until its promise
 * settles. An entry is not observable until `commit` completes successfully.
 */
export interface HttpCacheWriter {
  write(chunk: Uint8Array): Promise<void>;

  commit(): Promise<void>;

  abort(reason: unknown): Promise<void>;
}

/**
 * Provider-neutral response store. RFC policy, matching and eviction decisions
 * remain in shared TypeScript; filesystem/database providers implement this byte
 * and metadata boundary with atomic commit/replace and crash recovery.
 */
export interface HttpCacheStore {
  find(url: string): Promise<readonly HttpCacheEntry[]>;

  createWrite(metadata: HttpCacheEntryMetadata): Promise<HttpCacheWriter | null>;

  replaceMetadata(
    entry: HttpCacheEntry,
    metadata: HttpCacheEntryMetadata,
  ): Promise<HttpCacheEntry | null>;

  touch(entry: HttpCacheEntry): Promise<void>;

  delete(url: string): Promise<void>;
}

export interface MemoryHttpCacheStoreOptions {
  /** Defaults to 1024. */
  maxEntries?: number;
  /** Defaults to 100 MiB. */
  maxTotalBytes?: number;
  /** Defaults to 5 MiB. */
  maxEntryBytes?: number;
}

interface MemoryEntry extends HttpCacheEntry {
  sequence: number;
}

function validateLimit(value: number | undefined, fallback: number, name: string): number {
  const result = value ?? fallback;
  if (!Number.isSafeInteger(result) || result < 0) {
    throw new RangeError("Invalid memory cache " + name);
  }
  return result;
}

function equalVary(
  left: readonly HttpCacheVaryField[],
  right: readonly HttpCacheVaryField[],
): boolean {
  if (left.length !== right.length) return false;
  for (let index = 0; index < left.length; index++) {
    const a = left[index];
    const b = right[index];
    if (a === undefined || b === undefined || a.name !== b.name || a.value !== b.value)
      return false;
  }
  return true;
}

class MemoryHttpCacheBody implements HttpCacheBody {
  readonly length: number;
  private readonly chunks: readonly Uint8Array[];

  constructor(chunks: readonly Uint8Array[], length: number) {
    this.chunks = chunks;
    this.length = length;
  }

  async open(): Promise<ReadableStream<Uint8Array>> {
    let index = 0;
    const chunks = this.chunks;
    return new ReadableStream<Uint8Array>(
      {
        pull(controller) {
          const chunk = chunks[index++];
          if (chunk === undefined) controller.close();
          else controller.enqueue(chunk.slice());
        },
      },
      { highWaterMark: 0, size: (chunk) => chunk.length },
    );
  }
}

class MemoryHttpCacheWriter implements HttpCacheWriter {
  private readonly store: MemoryHttpCacheStore;
  private readonly metadata: HttpCacheEntryMetadata;
  private readonly chunks: Uint8Array[] = [];
  private length = 0;
  private finished = false;

  constructor(store: MemoryHttpCacheStore, metadata: HttpCacheEntryMetadata) {
    this.store = store;
    this.metadata = metadata;
  }

  async write(chunk: Uint8Array): Promise<void> {
    if (this.finished) throw new TypeError("Cache write is already finished");
    const next = this.length + chunk.length;
    if (next > this.store.maxEntryBytes) {
      throw new LimitError("HTTP cache entry exceeded configured byte limit");
    }
    this.chunks.push(chunk.slice());
    this.length = next;
  }

  async commit(): Promise<void> {
    if (this.finished) throw new TypeError("Cache write is already finished");
    this.finished = true;
    this.store.commit(this.metadata, new MemoryHttpCacheBody(this.chunks, this.length));
  }

  async abort(_reason: unknown): Promise<void> {
    if (this.finished) return;
    this.finished = true;
    this.chunks.length = 0;
  }
}

/** Bounded in-memory implementation; durable providers use the same contract. */
export class MemoryHttpCacheStore implements HttpCacheStore {
  readonly maxEntryBytes: number;
  private readonly maxEntries: number;
  private readonly maxTotalBytes: number;
  private readonly entries: MemoryEntry[] = [];
  private totalBytes = 0;
  private sequence = 0;

  constructor(options: MemoryHttpCacheStoreOptions = {}) {
    this.maxEntries = validateLimit(options.maxEntries, 1024, "entry count");
    this.maxTotalBytes = validateLimit(options.maxTotalBytes, 100 * 1024 * 1024, "total bytes");
    this.maxEntryBytes = validateLimit(options.maxEntryBytes, 5 * 1024 * 1024, "entry bytes");
  }

  async find(url: string): Promise<readonly HttpCacheEntry[]> {
    const result: HttpCacheEntry[] = [];
    for (const entry of this.entries) if (entry.url === url) result.push(entry);
    return result;
  }

  async createWrite(metadata: HttpCacheEntryMetadata): Promise<HttpCacheWriter | null> {
    if (this.maxEntries === 0 || this.maxTotalBytes === 0 || this.maxEntryBytes === 0) return null;
    return new MemoryHttpCacheWriter(this, metadata);
  }

  async touch(entry: HttpCacheEntry): Promise<void> {
    for (let index = 0; index < this.entries.length; index++) {
      const candidate = this.entries[index];
      if (candidate === entry) {
        candidate.sequence = ++this.sequence;
        return;
      }
    }
  }

  async replaceMetadata(
    entry: HttpCacheEntry,
    metadata: HttpCacheEntryMetadata,
  ): Promise<HttpCacheEntry | null> {
    for (let index = 0; index < this.entries.length; index++) {
      const candidate = this.entries[index];
      if (candidate === entry) {
        const replacement: MemoryEntry = {
          ...metadata,
          body: candidate.body,
          sequence: ++this.sequence,
        };
        this.entries[index] = replacement;
        return replacement;
      }
    }
    return null;
  }

  async delete(url: string): Promise<void> {
    let write = 0;
    for (const entry of this.entries) {
      if (entry.url === url) this.totalBytes -= entry.body?.length ?? 0;
      else this.entries[write++] = entry;
    }
    this.entries.length = write;
  }

  /** @internal Atomic publication point used by the memory transaction. */
  commit(metadata: HttpCacheEntryMetadata, body: HttpCacheBody): void {
    let write = 0;
    for (const entry of this.entries) {
      if (
        entry.url === metadata.url &&
        entry.method === metadata.method &&
        equalVary(entry.vary, metadata.vary)
      ) {
        this.totalBytes -= entry.body?.length ?? 0;
      } else this.entries[write++] = entry;
    }
    this.entries.length = write;
    this.entries.push({ ...metadata, body, sequence: ++this.sequence });
    this.totalBytes += body.length;
    this.evict();
  }

  private evict(): void {
    while (this.entries.length > this.maxEntries || this.totalBytes > this.maxTotalBytes) {
      let oldest = 0;
      for (let index = 1; index < this.entries.length; index++) {
        const candidate = this.entries[index];
        const current = this.entries[oldest];
        if (
          candidate !== undefined &&
          current !== undefined &&
          candidate.sequence < current.sequence
        ) {
          oldest = index;
        }
      }
      const removed = this.entries.splice(oldest, 1)[0];
      if (removed !== undefined) this.totalBytes -= removed.body?.length ?? 0;
    }
  }
}

/**
 * Compression Standard §§3–5: formats and their shared stream algorithms.
 * https://compression.spec.whatwg.org/#supported-formats
 * Brotli encoding and RFC 7932 validation belong to the native capability.
 * https://www.rfc-editor.org/rfc/rfc7932#section-1.4
 */
import { coerceToDOMString, requireArguments } from "../core/webidl.ts";
import { currentWebPlatformRuntime, hasWebPlatformRuntime } from "../provider/environment.ts";
import type {
  CompressionContext,
  CompressionFailure,
  CompressionFormat,
  CompressionProvider,
} from "../provider/compression.ts";
import { TransformStream } from "../streams/transform.ts";
import type { Transformer, TransformStreamDefaultController } from "../streams/transform.ts";
import type { ReadableStream } from "../streams/readable.ts";
import type { WritableStream } from "../streams/writable.ts";

const constructionKey: unique symbol = Symbol("Compression Streams construction");
const emptyBytes = new Uint8Array(0);

/** Bootstrap owns the environment slot; an absent capability has no host fallback. */
function currentCompressionProvider(): CompressionProvider | undefined {
  return hasWebPlatformRuntime() ? currentWebPlatformRuntime().compression : undefined;
}

/** Compression §4 and Web IDL enum conversion; format names are case-sensitive. */
function compressionFormat(value: unknown): CompressionFormat {
  const format = coerceToDOMString(value);
  if (format !== "gzip" && format !== "deflate" && format !== "deflate-raw" && format !== "brotli") {
    throw new TypeError("Unsupported compression format");
  }
  return format;
}

/**
 * Compression §§4–5, BufferSource conversion. As in crypto/buffer-source.ts,
 * nts's fixed intrinsic layouts make these plain reads internal slot reads.
 * Detached buffers have no bytes. No copy is observable: the native call finishes
 * before enqueue can invoke script, and the provider cannot retain its input.
 */
function compressionBytes(value: unknown): Uint8Array {
  if (ArrayBuffer.isView(value)) {
    const buffer = value.buffer;
    if (!(buffer instanceof ArrayBuffer) || buffer.resizable) {
      throw new TypeError("Compression chunks require an ordinary fixed ArrayBuffer");
    }
    if (buffer.detached) return emptyBytes;
    if (value instanceof Uint8Array) return value;
    return new Uint8Array(buffer, value.byteOffset, value.byteLength);
  }
  if (!(value instanceof ArrayBuffer) || value.resizable) {
    throw new TypeError("Compression chunks must be BufferSource values");
  }
  return value.detached ? emptyBytes : new Uint8Array(value);
}

function compressionError(result: CompressionFailure): TypeError {
  return new TypeError("Native compression failed: " + result.failure);
}

/** Both Web interfaces use the same GenericTransformStream and lifetime policy. */
class CompressionTransformer implements Transformer<unknown, Uint8Array> {
  private context: CompressionContext | null;

  constructor(context: CompressionContext) {
    this.context = context;
  }

  transform(chunk: unknown, controller: TransformStreamDefaultController<Uint8Array>): void {
    try {
      const context = this.context;
      if (context === null) throw new TypeError("Compression context is closed");
      const bytes = compressionBytes(chunk);
      const inputLength = bytes.byteLength;
      // The entire borrowed range crosses the capability once, before enqueue.
      const result = context.process(bytes, "none", Infinity);
      if ("failure" in result) throw compressionError(result);
      this.enqueue(result.chunks, controller);
      // Compression §5, decompress-and-enqueue step 6: valid output is observable
      // before a trailing-input error. The provider never starts a second member.
      if (result.consumed !== inputLength) {
        throw new TypeError("Compressed input contains trailing data");
      }
    } catch (error) {
      this.close();
      throw error;
    }
  }

  flush(controller: TransformStreamDefaultController<Uint8Array>): void {
    try {
      const context = this.context;
      if (context === null) throw new TypeError("Compression context is closed");
      const result = context.process(emptyBytes, "finish", Infinity);
      if ("failure" in result) {
        // Compression §5, decompress-flush steps 2–3: expose available bytes
        // before reporting that the compressed stream never reached its end.
        if (result.failure === "incomplete") this.enqueue(result.chunks, controller);
        throw compressionError(result);
      }
      this.enqueue(result.chunks, controller);
    } finally {
      this.close();
    }
  }

  cancel(): void {
    this.close();
  }

  private enqueue(
    chunks: readonly Uint8Array[],
    controller: TransformStreamDefaultController<Uint8Array>,
  ): void {
    for (const chunk of chunks) {
      if (chunk.byteLength !== 0) controller.enqueue(chunk);
    }
  }

  private close(): void {
    const context = this.context;
    this.context = null;
    context?.close();
  }
}

function compressionTransform(
  format: CompressionFormat,
  provider: CompressionProvider,
  decompress: boolean,
): TransformStream<unknown, Uint8Array> {
  const context = decompress
    ? provider.createDecompressor(format, 15)
    : provider.createCompressor(format, 15);
  if ("failure" in context) throw compressionError(context);
  try {
    return new TransformStream(new CompressionTransformer(context));
  } catch (error) {
    context.close();
    throw error;
  }
}

/** Compression Standard §4, https://compression.spec.whatwg.org/#compressionstream. */
export class CompressionStream {
  readonly #transform: TransformStream<unknown, Uint8Array>;

  constructor(format: unknown, key: symbol | undefined = undefined, provider?: CompressionProvider) {
    requireArguments(arguments, 1, "CompressionStream");
    const normalized = compressionFormat(format);
    // Web IDL converts format before the constructor steps. Extra public
    // arguments cannot replace the environment-owned capability.
    const capability = key === constructionKey ? provider : currentCompressionProvider();
    if (capability === undefined) {
      throw new TypeError("CompressionStream requires an installed compression provider");
    }
    this.#transform = compressionTransform(normalized, capability, false);
  }

  get readable(): ReadableStream<Uint8Array> {
    return this.#transform.readable;
  }

  get writable(): WritableStream<unknown> {
    return this.#transform.writable;
  }

  get [Symbol.toStringTag](): string {
    return "CompressionStream";
  }
}

/** Compression Standard §5, https://compression.spec.whatwg.org/#decompressionstream. */
export class DecompressionStream {
  readonly #transform: TransformStream<unknown, Uint8Array>;

  constructor(format: unknown, key: symbol | undefined = undefined, provider?: CompressionProvider) {
    requireArguments(arguments, 1, "DecompressionStream");
    const normalized = compressionFormat(format);
    const capability = key === constructionKey ? provider : currentCompressionProvider();
    if (capability === undefined) {
      throw new TypeError("DecompressionStream requires an installed compression provider");
    }
    this.#transform = compressionTransform(normalized, capability, true);
  }

  get readable(): ReadableStream<Uint8Array> {
    return this.#transform.readable;
  }

  get writable(): WritableStream<unknown> {
    return this.#transform.writable;
  }

  get [Symbol.toStringTag](): string {
    return "DecompressionStream";
  }
}

/** Internal provider factory; it is not exported by the public Web API barrel. */
export function createCompressionStream(format: unknown, provider: CompressionProvider): CompressionStream {
  return new CompressionStream(format, constructionKey, provider);
}

/** Internal provider factory; it preserves the canonical class's identity. */
export function createDecompressionStream(format: unknown, provider: CompressionProvider): DecompressionStream {
  return new DecompressionStream(format, constructionKey, provider);
}

import { trimHTTPTabOrSpace } from "../core/ascii.ts";
import {
  coerceToBoolean,
  coerceToDOMString,
  requireArguments,
  requireDictionary,
  toLongLong,
} from "../core/webidl.ts";
import { Headers } from "../fetch/headers.ts";

export type CookieSameSite = "Strict" | "Lax" | "None";

/** The standalone Undici-compatible Set-Cookie helper shape. */
export interface Cookie {
  name: string;
  value: string;
  expires?: Date | number;
  maxAge?: number;
  domain?: string;
  path?: string;
  secure?: boolean;
  httpOnly?: boolean;
  sameSite?: CookieSameSite;
  unparsed?: string[];
}

export interface DeleteCookieAttributes {
  path?: string;
  domain?: string;
}

export type CookiePair = readonly [name: string, value: string];

const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const lowerMonths = [
  "jan",
  "feb",
  "mar",
  "apr",
  "may",
  "jun",
  "jul",
  "aug",
  "sep",
  "oct",
  "nov",
  "dec",
];

function requireHeaders(value: Headers, operation: string): void {
  if (!(value instanceof Headers)) throw new TypeError(operation + " requires Headers");
}

function hasCTLExcludingTab(value: string): boolean {
  for (let index = 0; index < value.length; index++) {
    const code = value.charCodeAt(index);
    if ((code >= 0 && code <= 8) || (code >= 10 && code <= 31) || code === 127) return true;
  }
  return false;
}

function validateCookieName(name: string): void {
  for (let index = 0; index < name.length; index++) {
    const code = name.charCodeAt(index);
    if (
      code < 33 ||
      code > 126 ||
      code === 34 ||
      code === 40 ||
      code === 41 ||
      code === 44 ||
      code === 47 ||
      code === 58 ||
      code === 59 ||
      code === 60 ||
      code === 61 ||
      code === 62 ||
      code === 63 ||
      code === 64 ||
      code === 91 ||
      code === 92 ||
      code === 93 ||
      code === 123 ||
      code === 125
    ) {
      throw new TypeError("Invalid cookie name");
    }
  }
}

function validateCookieValue(value: string): void {
  let start = 0;
  let end = value.length;
  if (value.charCodeAt(0) === 34) {
    if (end === 1 || value.charCodeAt(end - 1) !== 34) {
      throw new TypeError("Invalid cookie value");
    }
    start++;
    end--;
  }
  for (let index = start; index < end; index++) {
    const code = value.charCodeAt(index);
    if (code < 33 || code > 126 || code === 34 || code === 44 || code === 59 || code === 92) {
      throw new TypeError("Invalid cookie value");
    }
  }
}

function isLetterOrDigit(code: number): boolean {
  return (code >= 48 && code <= 57) || (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
}

function validateCookieDomain(domain: string): void {
  if (domain.length === 0 || domain.length > 255) throw new TypeError("Invalid cookie domain");
  let labelLength = 0;
  for (let index = 0; index < domain.length; index++) {
    const code = domain.charCodeAt(index);
    if (code === 46) {
      if (labelLength === 0 || domain.charCodeAt(index - 1) === 45) {
        throw new TypeError("Invalid cookie domain");
      }
      labelLength = 0;
      continue;
    }
    if ((labelLength === 0 && !isLetterOrDigit(code)) || (!isLetterOrDigit(code) && code !== 45)) {
      throw new TypeError("Invalid cookie domain");
    }
    labelLength++;
    if (labelLength > 63) throw new TypeError("Invalid cookie domain");
  }
  if (labelLength === 0 || domain.charCodeAt(domain.length - 1) === 45) {
    throw new TypeError("Invalid cookie domain");
  }
}

function validateCookiePath(path: string): void {
  for (let index = 0; index < path.length; index++) {
    const code = path.charCodeAt(index);
    if (code < 32 || code > 126 || code === 59) throw new TypeError("Invalid cookie path");
  }
}

function twoDigits(value: number): string {
  return value < 10 ? "0" + value : `${value}`;
}

function toIMFDate(input: Date | number): string {
  const date = typeof input === "number" ? new Date(input) : input;
  const time = date.getTime();
  if (!Number.isFinite(time)) throw new TypeError("Invalid cookie expiry");
  const day = days[date.getUTCDay()];
  const month = months[date.getUTCMonth()];
  if (day === undefined || month === undefined) throw new TypeError("Invalid cookie expiry");
  return (
    day +
    ", " +
    twoDigits(date.getUTCDate()) +
    " " +
    month +
    " " +
    date.getUTCFullYear() +
    " " +
    twoDigits(date.getUTCHours()) +
    ":" +
    twoDigits(date.getUTCMinutes()) +
    ":" +
    twoDigits(date.getUTCSeconds()) +
    " GMT"
  );
}

function digitsAtStart(value: string, minimum: number, maximum: number): number {
  let length = 0;
  while (length < value.length && length < maximum) {
    const code = value.charCodeAt(length);
    if (code < 48 || code > 57) break;
    length++;
  }
  return length >= minimum ? length : 0;
}

function parseDecimalPrefix(value: string, length: number): number {
  let result = 0;
  for (let index = 0; index < length; index++) result = result * 10 + value.charCodeAt(index) - 48;
  return result;
}

function isDateDelimiter(code: number): boolean {
  return (
    code === 9 ||
    (code >= 32 && code <= 47) ||
    (code >= 59 && code <= 64) ||
    (code >= 91 && code <= 96) ||
    (code >= 123 && code <= 126)
  );
}

function dateTokens(value: string): string[] {
  const result: string[] = [];
  let start = -1;
  for (let index = 0; index <= value.length; index++) {
    const delimiter = index === value.length || isDateDelimiter(value.charCodeAt(index));
    if (delimiter) {
      if (start >= 0) {
        result.push(value.slice(start, index));
        start = -1;
      }
    } else if (start < 0) start = index;
  }
  return result;
}

/** RFC6265bis cookie-date parsing, deliberately independent of host Date.parse. */
export function parseCookieDate(value: string): Date | null {
  let day = -1;
  let month = -1;
  let year = -1;
  let hour = -1;
  let minute = -1;
  let second = -1;

  for (const token of dateTokens(value)) {
    if (hour < 0) {
      const first = digitsAtStart(token, 1, 2);
      if (first > 0 && token.charCodeAt(first) === 58) {
        const tail = token.slice(first + 1);
        const secondLength = digitsAtStart(tail, 1, 2);
        if (secondLength > 0 && tail.charCodeAt(secondLength) === 58) {
          const last = tail.slice(secondLength + 1);
          const thirdLength = digitsAtStart(last, 1, 2);
          if (
            thirdLength > 0 &&
            (thirdLength === last.length || !isDigit(last.charCodeAt(thirdLength)))
          ) {
            hour = parseDecimalPrefix(token, first);
            minute = parseDecimalPrefix(tail, secondLength);
            second = parseDecimalPrefix(last, thirdLength);
            continue;
          }
        }
      }
    }
    if (day < 0) {
      const length = digitsAtStart(token, 1, 2);
      if (length > 0 && (length === token.length || !isDigit(token.charCodeAt(length)))) {
        day = parseDecimalPrefix(token, length);
        continue;
      }
    }
    if (month < 0 && token.length >= 3) {
      const candidate = token.slice(0, 3).toLowerCase();
      const index = lowerMonths.indexOf(candidate);
      if (index >= 0) {
        month = index;
        continue;
      }
    }
    if (year < 0) {
      const length = digitsAtStart(token, 2, 4);
      if (length >= 2 && (length === token.length || !isDigit(token.charCodeAt(length)))) {
        year = parseDecimalPrefix(token, length);
      }
    }
  }

  if (year >= 70 && year <= 99) year += 1900;
  else if (year >= 0 && year <= 69) year += 2000;
  if (
    day < 1 ||
    day > 31 ||
    month < 0 ||
    year < 1601 ||
    hour < 0 ||
    hour > 23 ||
    minute < 0 ||
    minute > 59 ||
    second < 0 ||
    second > 59
  ) {
    return null;
  }
  const time = Date.UTC(year, month, day, hour, minute, second);
  const date = new Date(time);
  if (
    !Number.isFinite(time) ||
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month ||
    date.getUTCDate() !== day ||
    date.getUTCHours() !== hour ||
    date.getUTCMinutes() !== minute ||
    date.getUTCSeconds() !== second
  ) {
    return null;
  }
  return date;
}

function isDigit(code: number): boolean {
  return code >= 48 && code <= 57;
}

function parseMaxAge(value: string): number | undefined {
  if (value.length === 0) return undefined;
  let start = 0;
  if (value.charCodeAt(0) === 45) {
    if (value.length === 1) return undefined;
    start = 1;
  }
  for (let index = start; index < value.length; index++) {
    if (!isDigit(value.charCodeAt(index))) return undefined;
  }
  const result = Number(value);
  return Number.isFinite(result)
    ? result
    : result < 0
      ? Number.MIN_SAFE_INTEGER
      : Number.MAX_SAFE_INTEGER;
}

/** Parse one Set-Cookie field using RFC6265bis's liberal receiving algorithm. */
export interface ParsedCookie {
  readonly cookie: Cookie;
  readonly pathAttributePresent: boolean;
}

/** @internal The storage algorithm supplies the request URL's default path. */
export function parseCookieForRequest(input: string, defaultPath: string): ParsedCookie | null {
  const header = coerceToDOMString(input);
  if (hasCTLExcludingTab(header)) return null;
  const semicolon = header.indexOf(";");
  const pair = semicolon < 0 ? header : header.slice(0, semicolon);
  const equals = pair.indexOf("=");
  const name = trimHTTPTabOrSpace(equals < 0 ? "" : pair.slice(0, equals));
  const value = trimHTTPTabOrSpace(equals < 0 ? pair : pair.slice(equals + 1));
  if (name.length + value.length > 4096) return null;
  const result: Cookie = { name, value };
  const unparsed: string[] = [];
  let pathAttributePresent = false;
  let cursor = semicolon < 0 ? header.length + 1 : semicolon + 1;

  while (cursor <= header.length) {
    const next = header.indexOf(";", cursor);
    const part = next < 0 ? header.slice(cursor) : header.slice(cursor, next);
    cursor = next < 0 ? header.length + 1 : next + 1;
    const attributeEquals = part.indexOf("=");
    const attributeName = trimHTTPTabOrSpace(
      attributeEquals < 0 ? part : part.slice(0, attributeEquals),
    );
    const attributeValue = trimHTTPTabOrSpace(
      attributeEquals < 0 ? "" : part.slice(attributeEquals + 1),
    );
    if (attributeValue.length > 1024) continue;
    const key = attributeName.toLowerCase();
    if (key === "expires") {
      const expires = parseCookieDate(attributeValue);
      if (expires !== null) result.expires = expires;
    } else if (key === "max-age") {
      const maxAge = parseMaxAge(attributeValue);
      if (maxAge !== undefined) result.maxAge = maxAge;
    } else if (key === "domain") {
      result.domain = (
        attributeValue.charAt(0) === "." ? attributeValue.slice(1) : attributeValue
      ).toLowerCase();
    } else if (key === "path") {
      pathAttributePresent = true;
      result.path =
        attributeValue.length > 0 && attributeValue.charAt(0) === "/"
          ? attributeValue
          : defaultPath;
    } else if (key === "secure") result.secure = true;
    else if (key === "httponly") result.httpOnly = true;
    else if (key === "samesite") {
      const sameSite = attributeValue.toLowerCase();
      if (sameSite === "strict") result.sameSite = "Strict";
      else if (sameSite === "lax") result.sameSite = "Lax";
      else if (sameSite === "none") result.sameSite = "None";
    } else unparsed.push(attributeName + "=" + attributeValue);
  }
  if (unparsed.length > 0) result.unparsed = unparsed;
  return { cookie: result, pathAttributePresent };
}

export function parseCookie(input: string): Cookie | null {
  return parseCookieForRequest(input, "/")?.cookie ?? null;
}

function convertCookie(input: Cookie): Cookie {
  requireDictionary(input, "cookie");
  const result: Cookie = {
    name: coerceToDOMString(input.name),
    value: coerceToDOMString(input.value),
  };
  if (input.expires !== undefined && input.expires !== null) {
    result.expires =
      typeof input.expires === "number" && input.expires >= 0 && Number.isFinite(input.expires)
        ? new Date(Math.floor(input.expires))
        : typeof input.expires === "number"
          ? new Date(Number.NaN)
          : new Date(input.expires);
  }
  if (input.maxAge !== undefined && input.maxAge !== null) result.maxAge = toLongLong(input.maxAge);
  if (input.domain !== undefined && input.domain !== null)
    result.domain = coerceToDOMString(input.domain);
  if (input.path !== undefined && input.path !== null) result.path = coerceToDOMString(input.path);
  if (input.secure !== undefined && input.secure !== null)
    result.secure = coerceToBoolean(input.secure);
  if (input.httpOnly !== undefined && input.httpOnly !== null)
    result.httpOnly = coerceToBoolean(input.httpOnly);
  if (input.sameSite !== undefined) {
    const value = coerceToDOMString(input.sameSite);
    if (value !== "Strict" && value !== "Lax" && value !== "None") {
      throw new TypeError("Invalid cookie SameSite value");
    }
    result.sameSite = value;
  }
  const parts: string[] = [];
  if (input.unparsed !== undefined) {
    for (const part of input.unparsed) parts.push(coerceToDOMString(part));
  }
  result.unparsed = parts;
  return result;
}

/** Serialize one Set-Cookie field without allowing attributes to inject new fields. */
export function serializeCookie(input: Cookie): string | null {
  const cookie = convertCookie(input);
  if (cookie.name.length === 0) return null;
  validateCookieName(cookie.name);
  validateCookieValue(cookie.value);
  const output = [cookie.name + "=" + cookie.value];
  const lowerName = cookie.name.toLowerCase();
  const hostPrefix = lowerName.startsWith("__host-");
  const securePrefix = hostPrefix || lowerName.startsWith("__secure-");
  const secure = cookie.secure === true || securePrefix;
  const domain = hostPrefix ? undefined : cookie.domain;
  const path = hostPrefix ? "/" : cookie.path;
  if (secure) output.push("Secure");
  if (cookie.httpOnly === true) output.push("HttpOnly");
  if (cookie.maxAge !== undefined) {
    if (cookie.maxAge < 0) throw new TypeError("Invalid cookie max-age");
    output.push("Max-Age=" + cookie.maxAge);
  }
  if (domain !== undefined && domain.length > 0) {
    validateCookieDomain(domain);
    output.push("Domain=" + domain);
  }
  if (path !== undefined && path.length > 0) {
    validateCookiePath(path);
    output.push("Path=" + path);
  }
  if (
    cookie.expires !== undefined &&
    Number.isFinite(typeof cookie.expires === "number" ? cookie.expires : cookie.expires.getTime())
  ) {
    output.push("Expires=" + toIMFDate(cookie.expires));
  }
  if (cookie.sameSite !== undefined) output.push("SameSite=" + cookie.sameSite);
  for (const part of cookie.unparsed ?? []) {
    const equals = part.indexOf("=");
    if (equals < 0) throw new TypeError("Invalid unparsed cookie attribute");
    const name = trimHTTPTabOrSpace(part.slice(0, equals));
    const value = part.slice(equals + 1);
    validateCookieName(name);
    validateCookieValue(value);
    output.push(name + "=" + value);
  }
  return output.join("; ");
}

export function getSetCookies(headers: Headers): Cookie[] {
  requireArguments(arguments, 1, "getSetCookies");
  requireHeaders(headers, "getSetCookies");
  const result: Cookie[] = [];
  for (const value of headers.getSetCookie()) {
    const cookie = parseCookie(value);
    if (cookie !== null) result.push(cookie);
  }
  return result;
}

export function setCookie(headers: Headers, cookie: Cookie): void {
  requireArguments(arguments, 2, "setCookie");
  requireHeaders(headers, "setCookie");
  const value = serializeCookie(cookie);
  if (value !== null) headers.append("set-cookie", value);
}

export function deleteCookie(
  headers: Headers,
  name: string,
  attributes: DeleteCookieAttributes = {},
): void {
  requireArguments(arguments, 2, "deleteCookie");
  requireHeaders(headers, "deleteCookie");
  requireDictionary(attributes, "attributes");
  setCookie(headers, {
    name: coerceToDOMString(name),
    value: "",
    expires: 0,
    domain: attributes.domain,
    path: attributes.path,
  });
}

/** Parse a Cookie request field without constructing a dynamic property map. */
export function getCookiePairs(headers: Headers): CookiePair[] {
  requireArguments(arguments, 1, "getCookiePairs");
  requireHeaders(headers, "getCookiePairs");
  const value = headers.get("cookie");
  if (value === null || value.length === 0) return [];
  const result: CookiePair[] = [];
  for (const piece of value.split(";")) {
    const equals = piece.indexOf("=");
    const name = trimHTTPTabOrSpace(equals < 0 ? piece : piece.slice(0, equals));
    const cookieValue = equals < 0 ? "" : piece.slice(equals + 1);
    result.push([name, cookieValue]);
  }
  return result;
}

// A cookie jar that survives the process.
//
// `CookieJarStore` is `loadAll`/`saveAll` over a whole snapshot, and its contract says a
// durable implementation "atomically replaces the previous snapshot or rejects". That maps
// exactly onto one key in a `DurableByteStore`, whose own contract already promises that a
// key holds the old value or the new one after a crash mid-write -- never a mix and never
// absent. So the atomicity is inherited rather than reimplemented, which is the reason this
// module is small.
//
// The part that needed a decision is what to do with bytes that come back wrong.
import type { AbortSignal } from "../core/abort.ts";
import { decodeUTF8, TextEncoder } from "../core/encoding.ts";
import { jsonStringify } from "../../../ecmascript/src/json/json.ts";
import { parseJsonText } from "../../../ecmascript/src/json/parse.ts";
import { JsonValue } from "../../../ecmascript/src/json/value.ts";
import type { DurableByteStore } from "../storage/durable.ts";

import type { CookieJarStore, StoredCookie } from "./jar.ts";
import { validStoredCookieShape } from "./jar.ts";
import type { StoredSameSite } from "./jar.ts";

/**
 * What to do about a stored cookie that does not survive validation.
 *
 * `reject` is the default and it is the safer one. A jar that silently starts empty because
 * one byte was corrupt loses a user's session with no evidence anywhere, and the caller
 * cannot distinguish it from a first run. Dropping is available because a version skew that
 * makes old records unreadable is a real situation and permanently bricking the jar is a bad
 * answer to it -- but it has to be asked for, and it reports what it dropped.
 */
export type InvalidCookiePolicy = "reject" | "drop";

export interface DurableCookieJarStoreOptions {
  /** Defaults to `"cookies"`. */
  readonly namespace?: string;
  /** Defaults to `"jar"`. One key holds the whole snapshot, because `saveAll` replaces it. */
  readonly key?: string;
  /** Defaults to `"reject"`. */
  readonly onInvalid?: InvalidCookiePolicy;
  /**
   * Called when `onInvalid` is `"drop"` and something was dropped.
   *
   * Dropping without a way to observe it is the failure this whole option exists to avoid,
   * so the report is part of the feature rather than a debugging aid.
   */
  readonly reportDropped?: (count: number, total: number) => void;
}

/** Raised when a stored snapshot cannot be read back as cookies. */
export class CookieJarStoreError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CookieJarStoreError";
  }
}

const snapshotEncoder = new TextEncoder();

/**
 * One cookie as a JSON object node.
 *
 * Written out field by field rather than reflected over. That is not a limitation being
 * worked around -- it is what the plan calls direct typed materialization, done by hand for
 * one type: no generic object graph is built and walked, the field names are checked at
 * compile time, and a field added to `StoredCookie` without a line here fails to type-check
 * on the way back in rather than vanishing silently.
 */
function cookieToJson(cookie: StoredCookie): JsonValue {
  const keys = [
    "name",
    "value",
    "expiryTime",
    "domain",
    "path",
    "creationTime",
    "lastAccessTime",
    "creationIndex",
    "persistent",
    "hostOnly",
    "secure",
    "httpOnly",
    "sameSite",
  ];
  const values = [
    JsonValue.stringValue(cookie.name, 0, 0),
    JsonValue.stringValue(cookie.value, 0, 0),
    cookie.expiryTime === null
      ? JsonValue.nullValue(0, 0)
      : JsonValue.numberValue(cookie.expiryTime, 0, 0),
    JsonValue.stringValue(cookie.domain, 0, 0),
    JsonValue.stringValue(cookie.path, 0, 0),
    JsonValue.numberValue(cookie.creationTime, 0, 0),
    JsonValue.numberValue(cookie.lastAccessTime, 0, 0),
    JsonValue.numberValue(cookie.creationIndex, 0, 0),
    JsonValue.booleanValue(cookie.persistent, 0, 0),
    JsonValue.booleanValue(cookie.hostOnly, 0, 0),
    JsonValue.booleanValue(cookie.secure, 0, 0),
    JsonValue.booleanValue(cookie.httpOnly, 0, 0),
    JsonValue.stringValue(cookie.sameSite, 0, 0),
  ];
  return JsonValue.objectValue(keys, values, 0, 0);
}

/** The value a JSON object node holds under `key`, or `undefined` if it has no such key. */
function memberOf(node: JsonValue, key: string): JsonValue | undefined {
  const at = node.keys.indexOf(key);
  return at < 0 ? undefined : node.values[at];
}

function stringMember(node: JsonValue, key: string): string | null {
  const member = memberOf(node, key);
  return member !== undefined && member.kind === "string" ? member.text : null;
}

function numberMember(node: JsonValue, key: string): number | null {
  const member = memberOf(node, key);
  return member !== undefined && member.kind === "number" ? member.number : null;
}

function booleanMember(node: JsonValue, key: string): boolean | null {
  const member = memberOf(node, key);
  return member !== undefined && member.kind === "boolean" ? member.boolean : null;
}

/**
 * Narrowed rather than asserted.
 *
 * A cast from `string` would type-check and admit any text the file happened to contain, which
 * is exactly the corruption this whole path exists to catch; four comparisons give the compiler
 * the same knowledge honestly.
 */
function sameSiteOf(text: string): StoredSameSite | null {
  if (text === "Default") return "Default";
  if (text === "Strict") return "Strict";
  if (text === "Lax") return "Lax";
  if (text === "None") return "None";
  return null;
}

/**
 * One stored cookie read back out of the graph, or `null` if a field is missing or is the
 * wrong kind.
 *
 * These kind checks are the `typeof` half of {@link validStoredCookieShape}, moved to where
 * the kinds actually are; the semantic half -- that a path begins with a solidus, that
 * `persistent` agrees with `expiryTime`, that an index is in range -- still runs afterwards on
 * the assembled record, so nothing that was checked before is checked less now.
 */
function cookieFromJson(node: JsonValue): StoredCookie | null {
  if (node.kind !== "object") return null;

  const name = stringMember(node, "name");
  const value = stringMember(node, "value");
  const domain = stringMember(node, "domain");
  const path = stringMember(node, "path");
  const sameSiteText = stringMember(node, "sameSite");
  const creationTime = numberMember(node, "creationTime");
  const lastAccessTime = numberMember(node, "lastAccessTime");
  const creationIndex = numberMember(node, "creationIndex");
  const persistent = booleanMember(node, "persistent");
  const hostOnly = booleanMember(node, "hostOnly");
  const secure = booleanMember(node, "secure");
  const httpOnly = booleanMember(node, "httpOnly");

  if (
    name === null ||
    value === null ||
    domain === null ||
    path === null ||
    sameSiteText === null ||
    creationTime === null ||
    lastAccessTime === null ||
    creationIndex === null ||
    persistent === null ||
    hostOnly === null ||
    secure === null ||
    httpOnly === null
  ) {
    return null;
  }

  const sameSite = sameSiteOf(sameSiteText);
  if (sameSite === null) return null;

  // `null` is a legitimate value here and not an absence, so it is read directly rather than
  // through one of the typed accessors: a session cookie stores `"expiryTime":null`.
  const expiry = memberOf(node, "expiryTime");
  if (expiry === undefined) return null;
  let expiryTime: number | null;
  if (expiry.kind === "null") expiryTime = null;
  else if (expiry.kind === "number") expiryTime = expiry.number;
  else return null;

  return {
    name,
    value,
    expiryTime,
    domain,
    path,
    creationTime,
    lastAccessTime,
    creationIndex,
    persistent,
    hostOnly,
    secure,
    httpOnly,
    sameSite,
  };
}

function encodeSnapshot(cookies: readonly StoredCookie[]): Uint8Array {
  const items: JsonValue[] = [];
  for (const cookie of cookies) items.push(cookieToJson(cookie));
  const text = jsonStringify(JsonValue.arrayValue(items, 0, 0));
  if (text === undefined) throw new CookieJarStoreError("The cookie snapshot did not serialize");
  // UTF-8 rather than a byte-per-code-unit shortcut. A cookie value is an octet string, so
  // code units up to 0xFF reach this legitimately, and the serializer passes ordinary
  // non-ASCII through literally rather than escaping it.
  return snapshotEncoder.encode(text);
}

function decodeSnapshot(bytes: Uint8Array): string {
  // Fatal, because the replacement character is the wrong answer here. A corrupt byte
  // substituted with U+FFFD produces a cookie whose value is quietly not the one that was
  // stored, and it would be sent to a server that way.
  try {
    return decodeUTF8(bytes, true);
  } catch {
    throw new CookieJarStoreError("The stored cookie snapshot is not valid UTF-8");
  }
}

/**
 * `CookieJarStore` over a provider-owned durable byte store.
 *
 * The whole jar is one key. That is not a size compromise -- `saveAll` replaces the entire
 * snapshot, so per-cookie keys would need a second mechanism to make the replacement atomic,
 * and the store already provides exactly one.
 */
export class DurableCookieJarStore implements CookieJarStore {
  private readonly store: DurableByteStore;
  private readonly namespace: string;
  private readonly key: string;
  private readonly onInvalid: InvalidCookiePolicy;
  private readonly reportDropped: ((count: number, total: number) => void) | undefined;
  private readonly signal: AbortSignal;

  constructor(
    store: DurableByteStore,
    signal: AbortSignal,
    options: DurableCookieJarStoreOptions = {},
  ) {
    this.store = store;
    this.signal = signal;
    this.namespace = options.namespace ?? "cookies";
    this.key = options.key ?? "jar";
    this.onInvalid = options.onInvalid ?? "reject";
    this.reportDropped = options.reportDropped;
  }

  async loadAll(): Promise<readonly StoredCookie[]> {
    const bytes = await this.store.read(this.namespace, this.key, this.signal);
    // An absent key is a first run, which is not a failure.
    if (bytes === null) return [];
    // Decoded outside the JSON guard on purpose: inside it, a UTF-8 failure would be
    // caught and reported as malformed JSON, which sends a reader looking at the wrong
    // layer. The two failures have different causes and different repairs.
    const text = decodeSnapshot(bytes);
    let parsed: JsonValue;
    try {
      parsed = parseJsonText(text);
    } catch {
      throw new CookieJarStoreError("The stored cookie snapshot is not valid JSON");
    }
    if (parsed.kind !== "array") {
      throw new CookieJarStoreError("The stored cookie snapshot is not an array");
    }
    const cookies: StoredCookie[] = [];
    let dropped = 0;
    for (const entry of parsed.items) {
      const cookie = cookieFromJson(entry);
      if (cookie !== null && validStoredCookieShape(cookie)) {
        cookies.push(cookie);
        continue;
      }
      if (this.onInvalid === "reject") {
        throw new CookieJarStoreError("The stored cookie snapshot holds an unreadable cookie");
      }
      dropped++;
    }
    if (dropped > 0 && this.reportDropped !== undefined) {
      this.reportDropped(dropped, parsed.items.length);
    }
    return cookies;
  }

  async saveAll(cookies: readonly StoredCookie[]): Promise<void> {
    // Serialized before the write is opened, so a snapshot that cannot be encoded never
    // claims the key: the store refuses a second concurrent write rather than queueing it,
    // and a failure here would otherwise be paid for by the next caller.
    const bytes = encodeSnapshot(cookies);
    const write = await this.store.write(this.namespace, this.key, this.signal);
    try {
      await write.append(bytes);
      await write.commit();
    } catch (error) {
      // The store's crash contract covers a lost process, not a rejected append: without
      // this the key would keep an uncommitted write and refuse the next `saveAll`, since
      // a second concurrent write to a key is refused rather than queued.
      await write.discard();
      throw error;
    }
  }
}

import { parseCookieForRequest } from "./cookies.ts";
import type { CookieSameSite } from "./cookies.ts";
import type { URLParser, URLRecord } from "../provider/primitives.ts";
import { currentWebPlatformRuntime } from "../provider/environment.ts";

const maximumPersistentAgeSeconds = 400 * 24 * 60 * 60;

export type StoredSameSite = CookieSameSite | "Default";
export type CookieAccessType = "http" | "non-http";
export type CookieSameSiteStatus = "same-site" | "cross-site";

/** Explicit request context; this runtime does not invent a browser top-level site. */
export interface CookieAccessContext {
  type?: CookieAccessType;
  sameSite?: CookieSameSiteStatus;
  topLevelNavigation?: boolean;
  method?: string;
}

export interface StoredCookie {
  readonly name: string;
  readonly value: string;
  readonly expiryTime: number | null;
  readonly domain: string;
  readonly path: string;
  readonly creationTime: number;
  readonly lastAccessTime: number;
  readonly creationIndex: number;
  readonly persistent: boolean;
  readonly hostOnly: boolean;
  readonly secure: boolean;
  readonly httpOnly: boolean;
  readonly sameSite: StoredSameSite;
}

/** Durable implementations atomically replace the previous snapshot or reject. */
export interface CookieJarStore {
  loadAll(): Promise<readonly StoredCookie[]>;
  saveAll(cookies: readonly StoredCookie[]): Promise<void>;
  close?(): Promise<void>;
}

/** A PSL-backed implementation should be pinned and updated independently of cookie policy. */
export interface PublicSuffixChecker {
  isPublicSuffix(canonicalDomain: string): boolean;
}

export interface CookieJarOptions {
  urls?: URLParser;
  wallTimeMilliseconds?: () => number;
  store?: CookieJarStore;
  publicSuffixes?: PublicSuffixChecker;
  isSecure?: (url: URLRecord) => boolean;
  maxCookiesPerDomain?: number;
  maxCookies?: number;
  maxPersistentAgeSeconds?: number;
}

function cloneCookie(cookie: StoredCookie): StoredCookie {
  return {
    name: cookie.name,
    value: cookie.value,
    expiryTime: cookie.expiryTime,
    domain: cookie.domain,
    path: cookie.path,
    creationTime: cookie.creationTime,
    lastAccessTime: cookie.lastAccessTime,
    creationIndex: cookie.creationIndex,
    persistent: cookie.persistent,
    hostOnly: cookie.hostOnly,
    secure: cookie.secure,
    httpOnly: cookie.httpOnly,
    sameSite: cookie.sameSite,
  };
}

export class MemoryCookieJarStore implements CookieJarStore {
  private cookies: StoredCookie[] = [];

  async loadAll(): Promise<readonly StoredCookie[]> {
    return this.cookies.map(cloneCookie);
  }

  async saveAll(cookies: readonly StoredCookie[]): Promise<void> {
    this.cookies = cookies.map(cloneCookie);
  }
}

function validateLimit(value: number, name: string): number {
  if (!Number.isSafeInteger(value) || value < 1) throw new RangeError("Invalid " + name);
  return value;
}

/**
 * Whether a value has the shape the jar's own invariants assume.
 *
 * Exported because a durable store has to answer the same question about bytes it read
 * back, and two definitions of "a valid cookie" would drift. This is the jar's.
 */
export function validStoredCookieShape(cookie: StoredCookie): boolean {
  return (
    typeof cookie.name === "string" &&
    typeof cookie.value === "string" &&
    (cookie.expiryTime === null || Number.isFinite(cookie.expiryTime)) &&
    typeof cookie.domain === "string" &&
    cookie.domain.length > 0 &&
    typeof cookie.path === "string" &&
    cookie.path.startsWith("/") &&
    Number.isFinite(cookie.creationTime) &&
    Number.isFinite(cookie.lastAccessTime) &&
    Number.isSafeInteger(cookie.creationIndex) &&
    cookie.creationIndex >= 0 &&
    cookie.creationIndex < Number.MAX_SAFE_INTEGER &&
    typeof cookie.persistent === "boolean" &&
    cookie.persistent === (cookie.expiryTime !== null) &&
    typeof cookie.hostOnly === "boolean" &&
    typeof cookie.secure === "boolean" &&
    typeof cookie.httpOnly === "boolean" &&
    (cookie.sameSite === "Default" ||
      cookie.sameSite === "Strict" ||
      cookie.sameSite === "Lax" ||
      cookie.sameSite === "None")
  );
}

function hasNonOctet(value: string): boolean {
  for (let index = 0; index < value.length; index++) {
    if (value.charCodeAt(index) > 255) return true;
  }
  return false;
}

function defaultPath(pathname: string): string {
  if (pathname.length === 0 || pathname.charAt(0) !== "/") return "/";
  const lastSlash = pathname.lastIndexOf("/");
  return lastSlash <= 0 ? "/" : pathname.slice(0, lastSlash);
}

function isIPv4(host: string): boolean {
  if (host.length === 0) return false;
  for (let index = 0; index < host.length; index++) {
    const code = host.charCodeAt(index);
    if (code !== 46 && (code < 48 || code > 57)) return false;
  }
  return true;
}

function isIPAddress(host: string): boolean {
  return host.includes(":") || isIPv4(host);
}

export function domainMatches(host: string, domain: string): boolean {
  if (host === domain) return true;
  return !isIPAddress(host) && host.endsWith("." + domain);
}

export function pathMatches(requestPath: string, cookiePath: string): boolean {
  if (requestPath === cookiePath) return true;
  if (!requestPath.startsWith(cookiePath)) return false;
  return cookiePath.endsWith("/") || requestPath.charAt(cookiePath.length) === "/";
}

function isSafeMethod(method: string): boolean {
  const upper = method.toUpperCase();
  return upper === "GET" || upper === "HEAD" || upper === "OPTIONS" || upper === "TRACE";
}

function isSecureURL(url: URLRecord): boolean {
  return url.protocol === "https:" || url.protocol === "wss:";
}

function sameCookieKey(left: StoredCookie, right: StoredCookie): boolean {
  return (
    left.name === right.name &&
    left.domain === right.domain &&
    left.hostOnly === right.hostOnly &&
    left.path === right.path
  );
}

function compareAccess(left: StoredCookie, right: StoredCookie): number {
  if (left.lastAccessTime !== right.lastAccessTime)
    return left.lastAccessTime - right.lastAccessTime;
  return left.creationIndex - right.creationIndex;
}

function compareForHeader(left: StoredCookie, right: StoredCookie): number {
  if (left.path.length !== right.path.length) return right.path.length - left.path.length;
  if (left.creationTime !== right.creationTime) return left.creationTime - right.creationTime;
  return left.creationIndex - right.creationIndex;
}

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function compareCookieKey(left: StoredCookie, right: StoredCookie): number {
  const domain = compareText(left.domain, right.domain);
  if (domain !== 0) return domain;
  const path = compareText(left.path, right.path);
  if (path !== 0) return path;
  const name = compareText(left.name, right.name);
  if (name !== 0) return name;
  return Number(left.hostOnly) - Number(right.hostOnly);
}

interface EvictionCandidate {
  readonly cookie: StoredCookie;
  remove: boolean;
}

function compareDomainEviction(left: EvictionCandidate, right: EvictionCandidate): number {
  const domain = compareText(left.cookie.domain, right.cookie.domain);
  if (domain !== 0) return domain;
  if (left.cookie.secure !== right.cookie.secure) return left.cookie.secure ? 1 : -1;
  return compareAccess(left.cookie, right.cookie);
}

function compareGlobalEviction(left: EvictionCandidate, right: EvictionCandidate): number {
  return compareAccess(left.cookie, right.cookie);
}

function receiptAllowed(sameSite: StoredSameSite, context: Required<CookieAccessContext>): boolean {
  if (sameSite === "None" || context.sameSite === "same-site") return true;
  return context.type === "http" && context.topLevelNavigation;
}

function retrievalAllowed(
  sameSite: StoredSameSite,
  context: Required<CookieAccessContext>,
): boolean {
  if (sameSite === "None" || context.sameSite === "same-site") return true;
  return (
    context.type === "http" &&
    context.topLevelNavigation &&
    (sameSite === "Lax" || sameSite === "Default") &&
    isSafeMethod(context.method)
  );
}

function readContext(context: CookieAccessContext): Required<CookieAccessContext> {
  const result: Required<CookieAccessContext> = {
    type: context.type ?? "http",
    sameSite: context.sameSite ?? "same-site",
    topLevelNavigation: context.topLevelNavigation ?? false,
    method: context.method ?? "GET",
  };
  if (result.type !== "http" && result.type !== "non-http")
    throw new TypeError("Invalid cookie access type");
  if (result.sameSite !== "same-site" && result.sameSite !== "cross-site") {
    throw new TypeError("Invalid cookie same-site status");
  }
  return result;
}

function persistentCookies(cookies: readonly StoredCookie[]): StoredCookie[] {
  const result: StoredCookie[] = [];
  for (const cookie of cookies) {
    if (cookie.persistent) result.push(cloneCookie(cookie));
  }
  return result;
}

/**
 * RFC6265bis storage/retrieval with explicit site policy and pluggable persistence.
 * Operations serialize so concurrent Fetches cannot lose a replacement or eviction.
 */
export class CookieJar {
  private readonly urls: URLParser;
  private readonly now: () => number;
  private readonly store: CookieJarStore;
  private readonly publicSuffixes: PublicSuffixChecker | undefined;
  private readonly secureURL: (url: URLRecord) => boolean;
  private readonly maxCookiesPerDomain: number;
  private readonly maxCookies: number;
  private readonly maxAgeSeconds: number;
  private cookies: StoredCookie[] = [];
  private loaded = false;
  private closed = false;
  private locked = false;
  private readonly waiters: PromiseWithResolvers<void>[] = [];
  private nextCreationIndex = 0;

  constructor(options: CookieJarOptions = {}) {
    this.urls = options.urls ?? currentWebPlatformRuntime().urls;
    this.now =
      options.wallTimeMilliseconds ?? (() => currentWebPlatformRuntime().wallTimeMilliseconds());
    this.store = options.store ?? new MemoryCookieJarStore();
    this.publicSuffixes = options.publicSuffixes;
    this.secureURL = options.isSecure ?? isSecureURL;
    this.maxCookiesPerDomain = validateLimit(
      options.maxCookiesPerDomain ?? 50,
      "per-domain cookie limit",
    );
    this.maxCookies = validateLimit(options.maxCookies ?? 3000, "cookie limit");
    this.maxAgeSeconds = validateLimit(
      options.maxPersistentAgeSeconds ?? maximumPersistentAgeSeconds,
      "persistent cookie age",
    );
    if (this.maxAgeSeconds > maximumPersistentAgeSeconds) {
      throw new RangeError("Persistent cookie age cannot exceed 400 days");
    }
  }

  private async acquire(): Promise<void> {
    if (!this.locked) {
      this.locked = true;
      return;
    }
    const waiter = Promise.withResolvers<void>();
    this.waiters.push(waiter);
    await waiter.promise;
  }

  private release(): void {
    const waiter = this.waiters.shift();
    if (waiter === undefined) this.locked = false;
    else waiter.resolve();
  }

  private async ensureLoaded(): Promise<void> {
    if (this.loaded) return;
    const loaded = await this.store.loadAll();
    const cookies: StoredCookie[] = [];
    let nextIndex = 0;
    for (const candidate of loaded) {
      if (!validStoredCookieShape(candidate) || !candidate.persistent) {
        throw new TypeError("Cookie store returned an invalid persistent cookie");
      }
      const cookie = cloneCookie(candidate);
      if (
        cookie.name.length + cookie.value.length > 4096 ||
        (cookie.name.length === 0 && cookie.value.length === 0) ||
        hasForbiddenCookieControl(cookie.name) ||
        hasForbiddenCookieControl(cookie.value) ||
        hasForbiddenCookieControl(cookie.path) ||
        cookie.path.includes(";") ||
        hasNonOctet(cookie.name) ||
        hasNonOctet(cookie.value) ||
        hasNonOctet(cookie.path) ||
        this.canonicalDomain(cookie.domain) !== cookie.domain ||
        (cookie.sameSite === "None" && !cookie.secure) ||
        (cookie.name.toLowerCase().startsWith("__secure-") && !cookie.secure) ||
        (cookie.name.toLowerCase().startsWith("__host-") &&
          (!cookie.secure || !cookie.hostOnly || cookie.path !== "/")) ||
        (cookie.name.length === 0 &&
          (cookie.value.toLowerCase().startsWith("__secure-") ||
            cookie.value.toLowerCase().startsWith("__host-")))
      ) {
        throw new TypeError("Cookie store returned an invalid persistent cookie");
      }
      cookies.push(cookie);
      nextIndex = Math.max(nextIndex, cookie.creationIndex + 1);
    }
    const byKey = cookies.slice().sort(compareCookieKey);
    const byCreation = cookies
      .slice()
      .sort((left, right) => left.creationIndex - right.creationIndex);
    for (let index = 1; index < cookies.length; index++) {
      const leftKey = byKey[index - 1];
      const rightKey = byKey[index];
      const leftCreation = byCreation[index - 1];
      const rightCreation = byCreation[index];
      if (
        leftKey === undefined ||
        rightKey === undefined ||
        leftCreation === undefined ||
        rightCreation === undefined
      ) {
        throw new TypeError("Cookie store returned an invalid persistent cookie");
      }
      if (sameCookieKey(leftKey, rightKey)) {
        throw new TypeError("Cookie store returned duplicate cookie keys");
      }
      if (leftCreation.creationIndex === rightCreation.creationIndex) {
        throw new TypeError("Cookie store returned duplicate creation indexes");
      }
    }
    const now = this.now();
    if (!Number.isFinite(now)) throw new TypeError("Cookie clock returned a non-finite time");
    const maximumExpiry = now + this.maxAgeSeconds * 1000;
    let normalized = false;
    for (let index = 0; index < cookies.length; index++) {
      const cookie = cookies[index];
      if (cookie !== undefined && cookie.expiryTime !== null && cookie.expiryTime > maximumExpiry) {
        cookies[index] = { ...cookie, expiryTime: maximumExpiry };
        normalized = true;
      }
    }
    const priorLength = cookies.length;
    this.removeExpired(cookies, now);
    this.evict(cookies);
    if (normalized || cookies.length !== priorLength) {
      await this.store.saveAll(persistentCookies(cookies));
    }
    this.cookies = cookies;
    this.nextCreationIndex = nextIndex;
    this.loaded = true;
  }

  private parseURL(input: string | URLRecord): URLRecord {
    const url = typeof input === "string" ? this.urls.parse(input) : input;
    if (url.hostname.length === 0) throw new TypeError("Cookie URL must have a host");
    return url;
  }

  private canonicalDomain(input: string): string | null {
    if (input.length === 0) return "";
    for (let index = 0; index < input.length; index++) {
      if (input.charCodeAt(index) > 127) return null;
    }
    try {
      const parsed = this.urls.parse("http://" + input + "/");
      if (
        parsed.protocol !== "http:" ||
        parsed.username !== "" ||
        parsed.password !== "" ||
        parsed.port !== "" ||
        parsed.pathname !== "/" ||
        parsed.search !== "" ||
        parsed.hash !== "" ||
        parsed.hostname.length === 0
      ) {
        return null;
      }
      return parsed.hostname.toLowerCase();
    } catch {
      return null;
    }
  }

  private removeExpired(cookies: StoredCookie[], now: number): boolean {
    let write = 0;
    for (const cookie of cookies) {
      if (cookie.expiryTime === null || cookie.expiryTime > now) cookies[write++] = cookie;
    }
    if (write === cookies.length) return false;
    cookies.length = write;
    return true;
  }

  private evict(cookies: StoredCookie[]): void {
    const candidates: EvictionCandidate[] = cookies.map((cookie) => ({ cookie, remove: false }));
    const byDomain = candidates.slice().sort(compareDomainEviction);
    let removed = 0;
    let start = 0;
    while (start < byDomain.length) {
      const first = byDomain[start];
      if (first === undefined) break;
      let end = start + 1;
      while (end < byDomain.length && byDomain[end]?.cookie.domain === first.cookie.domain) end++;
      const excess = end - start - this.maxCookiesPerDomain;
      for (let offset = 0; offset < excess; offset++) {
        const candidate = byDomain[start + offset];
        if (candidate !== undefined) {
          candidate.remove = true;
          removed++;
        }
      }
      start = end;
    }
    const globalExcess = candidates.length - removed - this.maxCookies;
    if (globalExcess > 0) {
      const remaining = candidates.filter((candidate) => !candidate.remove);
      remaining.sort(compareGlobalEviction);
      for (let index = 0; index < globalExcess; index++) {
        const candidate = remaining[index];
        if (candidate !== undefined) candidate.remove = true;
      }
    }
    let write = 0;
    for (const candidate of candidates) {
      if (!candidate.remove) cookies[write++] = candidate.cookie;
    }
    cookies.length = write;
  }

  private async save(cookies: StoredCookie[]): Promise<void> {
    await this.store.saveAll(persistentCookies(cookies));
    this.cookies = cookies;
  }

  async setCookie(
    header: string,
    inputURL: string | URLRecord,
    access: CookieAccessContext = {},
  ): Promise<boolean> {
    await this.acquire();
    try {
      if (this.closed) throw new TypeError("CookieJar is closed");
      await this.ensureLoaded();
      const url = this.parseURL(inputURL);
      const now = this.now();
      if (!Number.isFinite(now)) throw new TypeError("Cookie clock returned a non-finite time");
      for (let index = 0; index < header.length; index++) {
        if (header.charCodeAt(index) > 255) return false;
      }
      const parsed = parseCookieForRequest(header, defaultPath(url.pathname));
      if (parsed === null) return false;
      const cookie = parsed.cookie;
      if (cookie.name.length === 0 && cookie.value.length === 0) return false;
      if (hasForbiddenCookieControl(cookie.name) || hasForbiddenCookieControl(cookie.value))
        return false;
      const requestHost = url.hostname.toLowerCase();
      let domainAttribute = this.canonicalDomain(cookie.domain ?? "");
      if (domainAttribute === null) return false;
      if (
        domainAttribute.length > 0 &&
        this.publicSuffixes?.isPublicSuffix(domainAttribute) === true
      ) {
        if (domainAttribute === requestHost) domainAttribute = "";
        else return false;
      }
      const hostOnly = domainAttribute.length === 0;
      const domain = hostOnly ? requestHost : domainAttribute;
      if (!hostOnly && !domainMatches(requestHost, domain)) return false;
      const path = cookie.path ?? defaultPath(url.pathname);
      const secure = cookie.secure === true;
      const httpOnly = cookie.httpOnly === true;
      const context = readContext(access);
      if (secure && !this.secureURL(url)) return false;
      if (httpOnly && context.type === "non-http") return false;
      const sameSite: StoredSameSite = cookie.sameSite ?? "Default";
      if (!receiptAllowed(sameSite, context)) return false;
      if (sameSite === "None" && !secure) return false;
      const lowerName = cookie.name.toLowerCase();
      if (lowerName.startsWith("__secure-") && !secure) return false;
      if (
        lowerName.startsWith("__host-") &&
        (!secure || !hostOnly || !parsed.pathAttributePresent || path !== "/")
      ) {
        return false;
      }
      const lowerValue = cookie.value.toLowerCase();
      if (
        cookie.name.length === 0 &&
        (lowerValue.startsWith("__secure-") || lowerValue.startsWith("__host-"))
      ) {
        return false;
      }

      const next = this.cookies.map(cloneCookie);
      this.removeExpired(next, now);
      if (!secure && !this.secureURL(url)) {
        for (const existing of next) {
          if (
            existing.secure &&
            existing.name === cookie.name &&
            (domainMatches(existing.domain, domain) || domainMatches(domain, existing.domain)) &&
            pathMatches(path, existing.path)
          ) {
            return false;
          }
        }
      }

      let expiryTime: number | null = null;
      let persistent = false;
      if (cookie.maxAge !== undefined) {
        persistent = true;
        expiryTime =
          cookie.maxAge <= 0 ? 0 : now + Math.min(cookie.maxAge, this.maxAgeSeconds) * 1000;
      } else if (cookie.expires !== undefined) {
        persistent = true;
        const raw = typeof cookie.expires === "number" ? cookie.expires : cookie.expires.getTime();
        expiryTime = Math.min(raw, now + this.maxAgeSeconds * 1000);
      }

      let creationTime = now;
      let creationIndex = this.nextCreationIndex;
      const prototype: StoredCookie = {
        name: cookie.name,
        value: cookie.value,
        expiryTime,
        domain,
        path,
        creationTime,
        lastAccessTime: now,
        creationIndex,
        persistent,
        hostOnly,
        secure,
        httpOnly,
        sameSite,
      };
      const existingIndex = next.findIndex((existing) => sameCookieKey(existing, prototype));
      if (existingIndex >= 0) {
        const existing = next[existingIndex];
        if (existing === undefined) throw new TypeError("Cookie replacement index is invalid");
        if (context.type === "non-http" && existing.httpOnly) return false;
        creationTime = existing.creationTime;
        creationIndex = existing.creationIndex;
        next.splice(existingIndex, 1);
      } else this.nextCreationIndex++;

      if (expiryTime !== null && expiryTime <= now) {
        await this.save(next);
        return true;
      }
      next.push({ ...prototype, creationTime, creationIndex });
      this.evict(next);
      await this.save(next);
      return true;
    } finally {
      this.release();
    }
  }

  async getCookieHeader(
    inputURL: string | URLRecord,
    access: CookieAccessContext = {},
  ): Promise<string> {
    await this.acquire();
    try {
      if (this.closed) throw new TypeError("CookieJar is closed");
      await this.ensureLoaded();
      const url = this.parseURL(inputURL);
      const now = this.now();
      if (!Number.isFinite(now)) throw new TypeError("Cookie clock returned a non-finite time");
      const next = this.cookies.map(cloneCookie);
      let changed = this.removeExpired(next, now);
      const context = readContext(access);
      const host = url.hostname.toLowerCase();
      const selected: StoredCookie[] = [];
      for (let index = 0; index < next.length; index++) {
        const cookie = next[index];
        if (cookie === undefined) continue;
        if (cookie.hostOnly ? cookie.domain !== host : !domainMatches(host, cookie.domain))
          continue;
        if (this.publicSuffixes?.isPublicSuffix(cookie.domain) === true && !cookie.hostOnly)
          continue;
        if (!pathMatches(url.pathname, cookie.path)) continue;
        if (cookie.secure && !this.secureURL(url)) continue;
        if (cookie.httpOnly && context.type === "non-http") continue;
        if (!retrievalAllowed(cookie.sameSite, context)) continue;
        const accessed = { ...cookie, lastAccessTime: now };
        next[index] = accessed;
        selected.push(accessed);
        changed = true;
      }
      selected.sort(compareForHeader);
      if (changed) await this.save(next);
      return selected
        .map((cookie) => (cookie.name.length === 0 ? "" : cookie.name + "=") + cookie.value)
        .join("; ");
    } finally {
      this.release();
    }
  }

  async snapshot(): Promise<readonly StoredCookie[]> {
    await this.acquire();
    try {
      if (this.closed) throw new TypeError("CookieJar is closed");
      await this.ensureLoaded();
      const now = this.now();
      if (!Number.isFinite(now)) throw new TypeError("Cookie clock returned a non-finite time");
      const next = this.cookies.map(cloneCookie);
      if (this.removeExpired(next, now)) await this.save(next);
      return next.map(cloneCookie);
    } finally {
      this.release();
    }
  }

  async clear(): Promise<void> {
    await this.acquire();
    try {
      if (this.closed) throw new TypeError("CookieJar is closed");
      await this.ensureLoaded();
      await this.save([]);
    } finally {
      this.release();
    }
  }

  async close(): Promise<void> {
    await this.acquire();
    try {
      if (this.closed) return;
      await this.ensureLoaded();
      const persistent = persistentCookies(this.cookies);
      await this.store.saveAll(persistent);
      this.cookies = [];
      this.closed = true;
      if (this.store.close !== undefined) await this.store.close();
    } finally {
      this.release();
    }
  }
}

function hasForbiddenCookieControl(value: string): boolean {
  for (let index = 0; index < value.length; index++) {
    const code = value.charCodeAt(index);
    if ((code >= 0 && code <= 8) || (code >= 10 && code <= 31) || code === 127) return true;
  }
  return false;
}

/** Internal symbol marker for cancellation-aware modules; not a Web IDL brand check. */
export const abortSignalBrand: unique symbol = Symbol("NTS AbortSignal");

/**
 * Keys for the two members other modules need and the standard does not define.
 *
 * Here rather than in `abort.ts` for the same reason the brand is: this module exists so
 * cancellation-aware code can name these without an import cycle. Symbols so they leave the
 * interface prototype, and deliberately not re-exported from the public barrel.
 */
export const abortSignalSubscribe: unique symbol = Symbol("AbortSignal subscribe");
export const abortSignalTrigger: unique symbol = Symbol("AbortSignal trigger");

/** Internal operations required by cancellation-aware Web APIs. */
export interface AbortSignalOperations {
  readonly [abortSignalBrand]: true;
  readonly aborted: boolean;
  [abortSignalSubscribe](callback: () => void): () => void;
}

type AbortSignalBrandCheck = (value: unknown) => value is AbortSignalOperations;

let checkAbortSignalBrand: AbortSignalBrandCheck | undefined;
let readAbortSignalState!: (signal: AbortSignalOperations) => boolean;
let subscribeAbortSignalState!: (
  signal: AbortSignalOperations,
  callback: () => void,
) => () => void;

/**
 * Installed once by AbortSignal's static initializer, with access to its private
 * state. This module has no runtime imports, keeping EventTarget independent of
 * its AbortSignal subclass. Neither this installer nor the operations are public
 * Web APIs or re-exported from the package's barrels.
 */
export function installAbortSignalOperations(
  brand: AbortSignalBrandCheck,
  aborted: (signal: AbortSignalOperations) => boolean,
  subscribe: (signal: AbortSignalOperations, callback: () => void) => () => void,
): void {
  if (checkAbortSignalBrand !== undefined) {
    throw new TypeError("AbortSignal operations are already installed");
  }
  readAbortSignalState = aborted;
  subscribeAbortSignalState = subscribe;
  checkAbortSignalBrand = brand;
}

/** Web IDL interface conversion never consults script-visible properties. */
export function isAbortSignal(value: unknown): value is AbortSignalOperations {
  return checkAbortSignalBrand !== undefined && checkAbortSignalBrand(value);
}

/** Read the internal abort state of a signal that has passed interface conversion. */
export function isAbortSignalAborted(signal: AbortSignalOperations): boolean {
  return readAbortSignalState(signal);
}

/** Add an abort step without consulting an overridable method on the signal. */
export function subscribeAbortSignal(
  signal: AbortSignalOperations,
  callback: () => void,
): () => void {
  return subscribeAbortSignalState(signal, callback);
}

import { abortSignalBrand, installAbortSignalOperations } from "./abort-brand.ts";
import type { AbortSignalOperations } from "./abort-brand.ts";
import { abortSignalSubscribe, abortSignalTrigger } from "./abort-brand.ts";
export { abortSignalSubscribe, abortSignalTrigger } from "./abort-brand.ts";
import type { EventHandlerSlot } from "./events.ts";
import { Event, EventTarget } from "./events.ts";
import { abortError, DOMException } from "./errors.ts";
import { currentWebPlatformRuntime } from "../provider/environment.ts";
import { requireArguments, toEnforceRangeUnsignedLongLong } from "./webidl.ts";
import { eventTargetDispatchTrusted, eventTargetReportError, eventTargetSetErrorReporter, eventTargetSetHandler, eventTargetSetListenerObserver } from "./events.ts";

interface AbortAlgorithm {
  callback: () => void;
  active: boolean;
  previous: AbortAlgorithm | null;
  next: AbortAlgorithm | null;
}

function doNothing(): void {}

function isObject(value: unknown): value is object {
  return value !== null && (typeof value === "object" || typeof value === "function");
}

const abortSignalConstructorKey: unique symbol = Symbol("construct NTS AbortSignal");

export class AbortSignal extends EventTarget implements AbortSignalOperations {
  readonly [abortSignalBrand] = true;
  // DOM abort state is stored in internal slots, not ordinary script properties.
  // https://dom.spec.whatwg.org/#interface-abortsignal
  #isAborted = false;
  #abortReason: unknown = undefined;
  #dependent = false;
  #firstAlgorithm: AbortAlgorithm | null = null;
  #lastAlgorithm: AbortAlgorithm | null = null;
  #runningAlgorithms = false;
  readonly #sourceSignals: WeakRef<AbortSignal>[] = [];
  readonly #dependentSignals: WeakRef<AbortSignal>[] = [];
  readonly #retainedDependents: AbortSignal[] = [];
  #selfReference: WeakRef<AbortSignal> | null = null;
  #dependentCleanup: FinalizationRegistry<WeakRef<AbortSignal>> | null = null;
  #abortListenerCount = 0;
  #abortAlgorithmCount = 0;
  #retainedBySources = false;
  readonly #abortHandler: EventHandlerSlot<AbortSignal, Event> = {
    callback: null,
    listener: null,
  };

  static {
    // Web IDL interface identity and DOM abort steps depend on private state,
    // even if script replaces the signal's prototype or shadows its properties.
    // https://webidl.spec.whatwg.org/#es-interface
    // https://dom.spec.whatwg.org/#add-an-event-listener
    installAbortSignalOperations(
      (value): value is AbortSignalOperations => isObject(value) && #isAborted in value,
      (signal) => (signal as AbortSignal).#isAborted,
      (signal, callback) => (signal as AbortSignal).#subscribe(callback),
    );
  }

  constructor(key: typeof abortSignalConstructorKey, errorReporter?: (error: unknown) => void) {
    if (key !== abortSignalConstructorKey) {
      throw new TypeError("Illegal constructor");
    }
    super();
    if (errorReporter !== undefined) {
      this[eventTargetSetErrorReporter](errorReporter);
    }
  }

  get onabort(): ((this: AbortSignal, event: Event) => void) | null {
    return this.#abortHandler.callback;
  }

  set onabort(callback: ((this: AbortSignal, event: Event) => void) | null) {
    this[eventTargetSetHandler](this, this.#abortHandler, "abort", callback, (_event): _event is Event => true);
  }

  get aborted(): boolean {
    return this.#isAborted;
  }

  get reason(): unknown {
    return this.#abortReason;
  }

  throwIfAborted(): void {
    if (this.#isAborted) throw this.#abortReason;
  }

  /** Internal cancellation algorithms cannot be blocked by stopImmediatePropagation. */
  [abortSignalSubscribe](callback: () => void): () => void {
    return this.#subscribe(callback);
  }

  #subscribe(callback: () => void): () => void {
    if (this.#isAborted) {
      try {
        callback();
      } catch (error) {
        this[eventTargetReportError](error);
      }
      return doNothing;
    }
    const algorithm: AbortAlgorithm = {
      callback,
      active: true,
      previous: this.#lastAlgorithm,
      next: null,
    };
    if (this.#lastAlgorithm === null) this.#firstAlgorithm = algorithm;
    else this.#lastAlgorithm.next = algorithm;
    this.#lastAlgorithm = algorithm;
    this.#abortAlgorithmCount++;
    this.#updateSourceRetention();
    return () => this.#removeAlgorithm(algorithm);
  }

  [abortSignalTrigger](reason: unknown): void {
    if (!this.#markAborted(reason)) return;

    const dependents = this.#markDependentsAborted();
    this.#detachFromSources();
    for (const dependent of dependents) dependent.#detachFromSources();

    this.#runAbortSteps();
    for (const dependent of dependents) dependent.#runAbortSteps();
  }

  // Web IDL counts required parameters in the operation function's length.
  // https://webidl.spec.whatwg.org/#es-operations
  static abort(reason: unknown = undefined): AbortSignal {
    const signal = new AbortSignal(abortSignalConstructorKey);
    signal[abortSignalTrigger](reason);
    return signal;
  }

  static any(signals: Iterable<AbortSignal>): AbortSignal {
    requireArguments(arguments, 1, "AbortSignal.any");
    // Web IDL sequence conversion requires an object, even when a primitive string
    // would yield no elements. It does not IteratorClose on an element conversion
    // failure, so a for-of loop has observably different behavior here.
    // https://webidl.spec.whatwg.org/#es-sequence
    // https://webidl.spec.whatwg.org/#create-sequence-from-iterable
    if (!isObject(signals)) throw new TypeError("signals must be an iterable object");
    const iterator = signals[Symbol.iterator]();
    if (!isObject(iterator)) throw new TypeError("The signal iterator must be an object");
    const next = iterator.next;
    if (typeof next !== "function") throw new TypeError("The signal iterator must have a next method");
    const converted: AbortSignal[] = [];
    while (true) {
      const result = next.call(iterator);
      if (!isObject(result)) throw new TypeError("The signal iterator result must be an object");
      if (result.done) break;
      const signal = result.value;
      // Interface conversion tests the brand, independently of the prototype chain.
      // https://webidl.spec.whatwg.org/#es-interface
      if (!isObject(signal) || !(#isAborted in signal))
        throw new TypeError("signals must contain AbortSignal values");
      converted.push(signal);
    }

    const result = new AbortSignal(abortSignalConstructorKey);
    for (const signal of converted) {
      if (signal.#isAborted) {
        result[abortSignalTrigger](signal.#abortReason);
        return result;
      }
    }

    // Dependency is separate from the weak source set: any([]) is dependent too.
    // https://dom.spec.whatwg.org/#create-a-dependent-abort-signal
    result.#dependent = true;
    for (const signal of converted) {
      if (!signal.#dependent) result.#addSourceSignal(signal);
      else {
        for (const sourceReference of signal.#sourceSignals) {
          const source = sourceReference.deref();
          if (source !== undefined) result.#addSourceSignal(source);
        }
      }
    }
    result[eventTargetSetListenerObserver]((type, added) => result.#observeListener(type, added));
    return result;
  }

  static timeout(milliseconds: number): AbortSignal {
    requireArguments(arguments, 1, "AbortSignal.timeout");
    const delay = toEnforceRangeUnsignedLongLong(milliseconds);
    const scheduler = currentWebPlatformRuntime().scheduler;
    const signal = new AbortSignal(abortSignalConstructorKey, (error) =>
      scheduler.reportError(error),
    );
    scheduler.delay(delay, () =>
      signal[abortSignalTrigger](new DOMException("The operation timed out", "TimeoutError")),
    );
    return signal;
  }

  #markAborted(reason: unknown): boolean {
    if (this.#isAborted) return false;
    this.#isAborted = true;
    this.#abortReason = reason === undefined ? abortError() : reason;
    return true;
  }

  #markDependentsAborted(): AbortSignal[] {
    const pending: AbortSignal[] = [];
    const cleanup = this.#dependentCleanup;
    for (const reference of this.#dependentSignals) {
      cleanup?.unregister(reference);
      const dependent = reference.deref();
      if (dependent !== undefined && dependent.#markAborted(this.#abortReason))
