import { cancelEvent, ErrorEvent, Event } from "./events.ts";
import { PromiseRejectionEvent } from "./promise-rejection-event.ts";
import { requireArguments } from "./webidl.ts";
import type {
  GlobalErrorCapabilities, GlobalErrorEventType, GlobalErrorListener,
  GlobalExceptionReporter, GlobalHandlerArguments, GlobalHandlerCallback,
  GlobalHandlerContext,
} from "../provider/global-errors.ts";

export type GlobalErrorHandler = (
  this: object, eventOrMessage: Event | string, filename?: string,
  lineno?: number, colno?: number, error?: unknown,
) => unknown;
export type GlobalRejectionHandler = (this: object, event: Event) => unknown;
export type GlobalErrorHandlerValue = GlobalErrorHandler | object | null;
export type GlobalRejectionHandlerValue = GlobalRejectionHandler | object | null;

interface GlobalErrorHandlerProperties {
  readonly onerror?: unknown;
  readonly onunhandledrejection?: unknown;
  readonly onrejectionhandled?: unknown;
}

class HandlerSlot {
  value: object | null = null;
  context: GlobalHandlerContext | null = null;
  active = false;
}

function objectValue(value: unknown): object | null {
  return value !== null && (typeof value === "object" || typeof value === "function") ? value : null;
}

/**
 * HTML global error/rejection policy, owned by one provider global.
 *
 * Bootstrap exposes the callable and the three plain accessors; this class
 * never writes globalThis. Its accessors are the backing slots, so a provider
 * getter must return runtime.onerror (etc.), not read globalThis again.
 */
export class GlobalErrorRuntime implements GlobalExceptionReporter {
  readonly #capabilities: GlobalErrorCapabilities;
  readonly #errorHandler = new HandlerSlot();
  readonly #unhandledHandler = new HandlerSlot();
  readonly #handledHandler = new HandlerSlot();
  readonly #onError: GlobalErrorListener;
  readonly #onUnhandled: GlobalErrorListener;
  readonly #onHandled: GlobalErrorListener;
  readonly #reportListenerException: (exception: unknown) => void;
  #inErrorReportingMode = false;
  #aboutToBeNotified: object[] = [];
  readonly #outstanding = new WeakSet<object>();
  readonly reportError: (this: unknown, exception: unknown) => void;

  constructor(capabilities: GlobalErrorCapabilities) {
    this.#capabilities = capabilities;
    this.#onError = (event): void => this.#processHandler("error", event);
    this.#onUnhandled = (event): void => this.#processHandler("unhandledrejection", event);
    this.#onHandled = (event): void => this.#processHandler("rejectionhandled", event);
    this.#reportListenerException = (exception): void => this.reportException(exception);
    const runtime = this;
    // Keep one required argument and Web IDL's ordinary global receiver rule.
    // A borrowed method resolves its actual destination through the provider.
    this.reportError = function reportError(this: unknown, exception: unknown): void {
      requireArguments(arguments, 1, "reportError");
      const receiver = this === undefined || this === null ? capabilities.globalObject : objectValue(this);
      if (receiver === null) throw new TypeError("reportError requires a global receiver");
      const destination = receiver === capabilities.globalObject
        ? runtime : capabilities.resolveGlobalReporter(receiver);
      if (destination === null) throw new TypeError("reportError requires a global receiver");
      destination.reportException(exception);
    };
  }

  get onerror(): GlobalErrorHandlerValue { return this.#errorHandler.value; }
  set onerror(value: GlobalErrorHandlerValue) {
    this.#setHandler(this.#errorHandler, "error", value, this.#onError);
  }

  get onunhandledrejection(): GlobalRejectionHandlerValue { return this.#unhandledHandler.value; }
  set onunhandledrejection(value: GlobalRejectionHandlerValue) {
    this.#setHandler(this.#unhandledHandler, "unhandledrejection", value, this.#onUnhandled);
  }

  get onrejectionhandled(): GlobalRejectionHandlerValue { return this.#handledHandler.value; }
  set onrejectionhandled(value: GlobalRejectionHandlerValue) {
    this.#setHandler(this.#handledHandler, "rejectionhandled", value, this.#onHandled);
  }

  #setHandler(slot: HandlerSlot, type: GlobalErrorEventType, value: unknown, listener: GlobalErrorListener): void {
    const converted = objectValue(value);
    // Web IDL callback conversion captures incumbent settings on every object
    // assignment, independently of the callback's identity or listener position.
    const context = converted === null ? null : this.#capabilities.captureGlobalHandlerContext();
    slot.value = converted;
    slot.context = context;
    if (slot.value === null) {
      if (slot.active) this.#capabilities.removeGlobalEventListener(type, listener);
      slot.active = false;
    } else if (!slot.active) {
      this.#capabilities.addGlobalEventListener(type, listener);
      slot.active = true;
    }
  }

  #processHandler(type: GlobalErrorEventType, event: Event): void {
    // Bootstrap runs this callback in the global's realm. Read the current IDL
    // attribute exactly once: replacing a handler keeps its listener position.
    const scope = globalThis as GlobalErrorHandlerProperties;
    const callback = type === "error" ? scope.onerror : type === "unhandledrejection"
      ? scope.onunhandledrejection : scope.onrejectionhandled;
    if (typeof callback !== "function") return;
    const slot = type === "error" ? this.#errorHandler : type === "unhandledrejection"
      ? this.#unhandledHandler : this.#handledHandler;
    const context = slot.context;
    if (context === null) return;
    // The provider routes by internal event type. Ordinary subclass getters
    // cannot change HTML's special-handler branch or its initialized arguments.
    const special = type === "error" && event instanceof ErrorEvent;
    let args: GlobalHandlerArguments;
    if (special) {
      const data = this.#capabilities.readErrorEventData(event);
      args = [data.message, data.filename, data.lineno, data.colno, data.error];
    } else {
      args = [event];
    }
    // Web IDL invocation finishes callback/script cleanup before HTML processes
    // the return value. Dispatch cannot defer this to after our wrapper returns.
    const result = this.#capabilities.invokeGlobalHandler(callback as GlobalHandlerCallback, globalThis, args, context);
    if (!result.ok) throw result.error;
    if (special ? result.value === true : result.value === false) cancelEvent(event);
  }

  /** HTML 8.1.4.6: report an exception; listener errors re-enter this algorithm. */
  reportException(exception: unknown, omitError = false): void {
    const information = this.#capabilities.extractErrorInformation(exception);
    const muted = information.muted;
    const message = muted ? "Script error." : information.message;
    const filename = muted ? "" : information.filename;
    const lineno = muted ? 0 : information.lineno;
    const colno = muted ? 0 : information.colno;
    let notHandled = true;
    if (!this.#inErrorReportingMode) {
      this.#inErrorReportingMode = true;
      try {
        const event = new ErrorEvent("error", {
          cancelable: true, message, filename, lineno, colno,
          error: muted || omitError ? null : exception,
        });
        notHandled = this.#capabilities.dispatchGlobalEvent(event, this.#reportListenerException);
      } finally {
        this.#inErrorReportingMode = false;
      }
    }
    if (notHandled) {
      const owner = this.#capabilities.dedicatedWorkerOwner;
      if (owner === undefined) this.#capabilities.reportExceptionToConsole(exception);
      else owner.enqueueGlobalTask(() => {
        const event = new ErrorEvent("error", {
          cancelable: true, message, filename, lineno, colno, error: null,
        });
        if (owner.dispatchWorkerError(event, (error) => owner.reportException(error))) {
          owner.reportException(exception, true);
        }
      });
    }
  }

  /**
   * HTML 8.1.6.4. Called by the compiler's HostPromiseRejectionTracker for the
   * appropriate script/settings global, never by observing public .then.
   */
  hostPromiseRejectionTracker(promise: object, operation: "reject" | "handle", mutedErrors = false): void {
    if (mutedErrors) return;
    if (operation === "reject") {
      this.#aboutToBeNotified.push(promise);
      return;
    }
    const pendingIndex = this.#aboutToBeNotified.indexOf(promise);
    if (pendingIndex !== -1) {
      this.#aboutToBeNotified.splice(pendingIndex, 1);
      return;
    }
    if (!this.#outstanding.delete(promise)) return;
    this.#capabilities.enqueueGlobalTask(() => {
      const event = new PromiseRejectionEvent("rejectionhandled", {
        promise, reason: this.#capabilities.promiseResult(promise),
      });
      this.#capabilities.dispatchGlobalEvent(event, this.#reportListenerException);
    });
  }

  /** HTML 8.1.4.7; called after the actual microtask checkpoint by the engine. */
  notifyRejectedPromises(): void {
    const list = this.#aboutToBeNotified;
    if (list.length === 0) return;
    this.#aboutToBeNotified = [];
    this.#capabilities.enqueueGlobalTask(() => {
      for (const promise of list) {
        if (this.#capabilities.promiseIsHandled(promise)) continue;
        const reason = this.#capabilities.promiseResult(promise);
        const event = new PromiseRejectionEvent("unhandledrejection", {
          cancelable: true, promise, reason,
        });
        if (this.#capabilities.dispatchGlobalEvent(event, this.#reportListenerException)) {
          this.#capabilities.reportRejectionToConsole(reason);
        }
        if (!this.#capabilities.promiseIsHandled(promise)) this.#outstanding.add(promise);
      }
    });
  }
}

// WebIDL's iterator prototype object, and the iterators that inherit from it.
//
// An interface with an `iterable<>` declaration gets one prototype object *per interface*
// (WebIDL 3.7.10). Its [[Prototype]] is %IteratorPrototype%, it carries `next` as a writable,
// enumerable, configurable data property, and its `Symbol.toStringTag` names the interface.
//
// **A generator is not that**, which is what `headers-basic.any.js` checks and what this exists
// to fix. A generator object's chain is
//
//     generator -> the generator function's `.prototype` -> %GeneratorPrototype% -> %IteratorPrototype%
//
// which is one level too deep, and its `next` is non-enumerable and shared with every other
// generator in the realm. Three upstream tests fail on exactly that and on nothing else: the
// values a generator yields are already right.
//
// The traversal stays a generator, because "walk the pairs" is what a generator is for. Only the
// object handed to the caller changes, so iteration order, liveness under mutation and the
// values themselves are untouched by construction.

/**
 * %IteratorPrototype%, reached the only way the language exposes it: it is the prototype of the
 * prototype of an array iterator, and it has no global binding of its own.
 */
const ITERATOR_PROTOTYPE: object = Object.getPrototypeOf(
  Object.getPrototypeOf([][Symbol.iterator]()),
) as object;

/** Where an iterator keeps the traversal it is draining. Not reachable from script. */
const STEPS = Symbol("WebIDL iterator steps");

interface IdlIteratorObject {
  [STEPS]?: Iterator<unknown>;
}

/**
 * The iterator prototype object for one interface.
 *
 * Built once per interface and shared by every iterator that interface hands out, which is what
 * makes `Object.getPrototypeOf(headers.keys()) === Object.getPrototypeOf(headers.values())` --
 * the property WebIDL requires and a generator cannot give, since a generator function has its
 * own `.prototype` per function.
 */
export function idlIteratorPrototype(tag: string): object {
  const prototype = Object.create(ITERATOR_PROTOTYPE) as IdlIteratorObject;
  Object.defineProperty(prototype, "next", {
    // Writable, enumerable and configurable: all three are asserted upstream, and all three are
    // false for the `next` a generator inherits.
    value: function next(this: IdlIteratorObject): IteratorResult<unknown> {
      const steps = this[STEPS];
      if (steps === undefined) {
        throw new TypeError(`next called on an object that is not a ${tag}`);
      }
      return steps.next();
    },
    writable: true,
    enumerable: true,
    configurable: true,
  });
  Object.defineProperty(prototype, Symbol.toStringTag, {
    value: tag,
    writable: false,
    enumerable: false,
    configurable: true,
  });
  return prototype;
}

/**
 * One iterator over `steps`, inheriting from `prototype`.
 *
 * `Symbol.iterator` is not defined here: %IteratorPrototype% already carries one returning
 * `this`, which is the whole reason the chain has to reach it.
 */
export function idlIterator<T>(prototype: object, steps: Iterator<T>): IterableIterator<T> {
  const iterator = Object.create(prototype) as IdlIteratorObject;
  iterator[STEPS] = steps as Iterator<unknown>;
  return iterator as unknown as IterableIterator<T>;
}

// Web IDL surface shape: `@@toStringTag` and constructor arity.
//
// This file holds the rule. The classes hold the calls, written inline as module-level
// statements after each class rather than through a helper exported from here -- below.
//
// **The tag.** Web IDL requires every interface prototype object to carry `@@toStringTag`
// as a *data* property whose value is the interface's identifier, non-writable,
// non-enumerable and configurable. Without it `Object.prototype.toString.call(new Event("x"))`
// answers `[object Object]` rather than `[object Event]`, which is directly observable and
// differs from every other implementation. A `get [Symbol.toStringTag]()` accessor produces
// the right string and the wrong shape; it is the obvious thing to write in a class body,
// and every one of these was written that way before.
//
// **The length.** Web IDL defines an interface object's `length` as the number of *required*
// arguments. It is observable -- `Event.length` is 1 everywhere -- and TypeScript cannot
// produce it here, because these classes take `...args` tuples in order to tell an omitted
// argument from an explicit `undefined`. Web IDL requires that distinction too, and it
// matters more than the arity, so the tuple stays and the arity is declared.
//
// **Why inline rather than a helper.** Passing a class or a prototype to a function is
// `a class used as a value`, which this compiler does not lower yet: the helper form costs
// refusals per interface. The calls used to sit in a `static {}` block inside each class,
// which the refusal count then favoured; the integrity audit later showed the cost that
// hides: nts refuses the descriptor constructs, and inside a class declaration that cut
// the whole class, functional static setup with it, while the same statements at module
// scope are cut one by one and the class compiles. So the reflective statements now stand
// after each class, in their original order (R-1); under node the point in module
// evaluation is the same one the static block ran at.
//
// **What keeps thirty-five copies of the descriptor honest** is
// `runtime/web-platform/test/webidl-surface.test.ts`, which asserts the exact
// descriptor and the exact length for every interface in one table. That table is the single
// source of truth the helper was going to be; drift fails it.
//
// Not applied to the Undici-shaped classes in this runtime. `Agent`, `Pool`, the interceptors
// and the error taxonomy are not Web IDL interfaces, no implementation tags them, and the
// surface test asserts they stay untagged so that a later consistency pass has to say why.
export {};

import { utf8Length, utf8Write } from "./utf8.ts";

function asciiHexValue(code: number): number {
  if (code >= 0x30 && code <= 0x39) return code - 0x30;
  if (code >= 0x41 && code <= 0x46) return code - 0x41 + 10;
  if (code >= 0x61 && code <= 0x66) return code - 0x61 + 10;
  return -1;
}

/** URL percent-decoding over the UTF-8 bytes of a scalar-value string. */
export function percentDecodeBytes(input: string): Uint8Array {
  const raw = new Uint8Array(utf8Length(input));
  utf8Write(raw, input, 0, raw.length);

  let decodedLength = raw.length;
  for (let index = 0; index < raw.length; index++) {
    const first = raw[index + 1];
    const second = raw[index + 2];
    if (
      raw[index] === 0x25 &&
      first !== undefined &&
      second !== undefined &&
      asciiHexValue(first) >= 0 &&
      asciiHexValue(second) >= 0
    ) {
      decodedLength -= 2;
      index += 2;
    }
  }

  const output = new Uint8Array(decodedLength);
  let written = 0;
  for (let index = 0; index < raw.length; index++) {
    const byte = raw[index];
    if (byte === undefined) break;
    const first = raw[index + 1];
    const second = raw[index + 2];
    const high = first === undefined ? -1 : asciiHexValue(first);
    const low = second === undefined ? -1 : asciiHexValue(second);
    if (byte === 0x25 && high >= 0 && low >= 0) {
      output[written++] = high * 16 + low;
      index += 2;
    } else {
      output[written++] = byte;
    }
  }
  return output;
}

