 */
export class QuotaExceededError extends DOMException {
  readonly #quota: number | null;
  readonly #requested: number | null;

  constructor(message: unknown = "", options: unknown = undefined) {
    const text = coerceToDOMString(message);
    requireDictionary(options, "QuotaExceededErrorOptions");
    const dictionary = options as QuotaExceededErrorInput | null | undefined;
    // Web IDL converts every member, in identifier order, before running the
    // constructor steps. A requested conversion error precedes a negative quota.
    const quota = optionalDouble(dictionary?.quota);
    const requested = optionalDouble(dictionary?.requested);
    super(text, "QuotaExceededError");
    if (quota !== null && quota < 0) throw new RangeError("Quota must not be negative");
    if (requested !== null && requested < 0) throw new RangeError("Requested amount must not be negative");
    if (quota !== null && requested !== null && requested < quota) {
      throw new RangeError("Requested amount must not be below quota");
    }
    this.#quota = quota;
    this.#requested = requested;
  }

  get quota(): number | null { return this.#quota; }

  get requested(): number | null { return this.#requested; }

  override get [Symbol.toStringTag](): string { return "QuotaExceededError"; }
}

// UTF-8 between bytes and NTS string code units.
//
// This is the provider-independent codec used by Web encoders, Node Buffer,
// URL parsing, and protocol code. A backend may recognize these operations as
// intrinsics, but their observable fallback semantics live here once.
//
// Both directions live here. `core/encoding.ts` has its own decoder because what a Web
// caller needs is decoding *plus* WHATWG policy -- the replacement character, `fatal`,
// and consuming a leading BOM. The two agree on every malformed sequence tried and
// differ only on the BOM, which is the policy that does not belong at this level.
//
// `utf8Decode` is the codec without that policy, and the Node lane's `Buffer` needs
// exactly that: `toString("utf8")` does not consume a BOM. It is re-exported through
// `runtime/node/internal/utf8.ts`, so it is consumed from outside this directory --
// which is why an audit scoped to this lane called it dead and was wrong.

/** The number of UTF-8 bytes a string needs. */
export function utf8Length(input: string): number {
  let length = 0;
  for (let index = 0; index < input.length; index++) {
    const code = input.charCodeAt(index);
    if (code < 0x80) {
      length++;
    } else if (code < 0x800) {
      length += 2;
    } else if (code >= 0xd800 && code < 0xdc00 && index + 1 < input.length) {
      const next = input.charCodeAt(index + 1);
      if (next >= 0xdc00 && next < 0xe000) {
        length += 4;
        index++;
        continue;
      }
      length += 3;
    } else {
      length += 3;
    }
  }
  return length;
}

/** Code units consumed and bytes written by a bounded UTF-8 write. */
export interface Utf8WriteProgress {
  read: number;
  written: number;
}

/**
 * Write `input` as UTF-8 into `output` at `offset`, up to `maximum` bytes.
 *
 * A partial code point is never written. The return value is the number of
 * bytes written, not the final output offset. `progress` is optional so hot
 * paths such as Node Buffer do not allocate a result object; `encodeInto()`
 * supplies the object it must return and receives the code-unit count too.
 */
export function utf8Write(
  output: Uint8Array,
  input: string,
  offset: number,
  maximum: number,
  progress?: Utf8WriteProgress,
): number {
  let outputIndex = offset;
  let inputIndex = 0;
  const end = offset + maximum;

  while (inputIndex < input.length) {
    let code = input.charCodeAt(inputIndex);
    let inputUnits = 1;

    if (code >= 0xd800 && code < 0xdc00) {
      const next = inputIndex + 1 < input.length ? input.charCodeAt(inputIndex + 1) : 0;
      if (next >= 0xdc00 && next < 0xe000) {
        code = 0x10000 + ((code - 0xd800) << 10) + next - 0xdc00;
        inputUnits = 2;
      } else {
        code = 0xfffd;
      }
    } else if (code >= 0xdc00 && code < 0xe000) {
      code = 0xfffd;
    }

    if (code < 0x80) {
      if (outputIndex + 1 > end) break;
      output[outputIndex++] = code;
    } else if (code < 0x800) {
      if (outputIndex + 2 > end) break;
      output[outputIndex++] = 0xc0 | (code >> 6);
      output[outputIndex++] = 0x80 | (code & 0x3f);
    } else if (code < 0x10000) {
      if (outputIndex + 3 > end) break;
      output[outputIndex++] = 0xe0 | (code >> 12);
      output[outputIndex++] = 0x80 | ((code >> 6) & 0x3f);
      output[outputIndex++] = 0x80 | (code & 0x3f);
    } else {
      if (outputIndex + 4 > end) break;
      output[outputIndex++] = 0xf0 | (code >> 18);
      output[outputIndex++] = 0x80 | ((code >> 12) & 0x3f);
      output[outputIndex++] = 0x80 | ((code >> 6) & 0x3f);
      output[outputIndex++] = 0x80 | (code & 0x3f);
    }

    inputIndex += inputUnits;
  }

  const written = outputIndex - offset;
  if (progress !== undefined) {
    progress.read = inputIndex;
    progress.written = written;
  }
  return written;
}

/**
 * Decode UTF-8, substituting U+FFFD for each maximal invalid subpart.
 *
 * This follows the WHATWG decoder state machine. In particular, a rejected
 * continuation byte is reprocessed as a possible new leading byte, and a
 * sequence cut off by the end of the input emits one replacement character.
 *
 * The C runtime has the same decoder, `nts_string_from_utf8`, for strings C
 * hands back. The table in `runtime/c/tests/utf8_decode.c`, generated by
 * node's `TextDecoder`, is what both are checked against; change either and
 * run the table against both.
 */

export function utf8Decode(bytes: Uint8Array, start: number, end: number): string {
  let output = "";
  let codePoint = 0;
  let bytesSeen = 0;
  let bytesNeeded = 0;
  let lowerBoundary = 0x80;
  let upperBoundary = 0xbf;
  let index = start;

  while (index < end) {
    const byte = bytes[index];
    if (byte === undefined) break;

    if (bytesNeeded === 0) {
      index++;
      if (byte <= 0x7f) {
        output += String.fromCharCode(byte);
      } else if (byte >= 0xc2 && byte <= 0xdf) {
        bytesNeeded = 1;
        codePoint = byte & 0x1f;
      } else if (byte >= 0xe0 && byte <= 0xef) {
        if (byte === 0xe0) lowerBoundary = 0xa0;
        if (byte === 0xed) upperBoundary = 0x9f;
        bytesNeeded = 2;
        codePoint = byte & 0x0f;
      } else if (byte >= 0xf0 && byte <= 0xf4) {
        if (byte === 0xf0) lowerBoundary = 0x90;
        if (byte === 0xf4) upperBoundary = 0x8f;
        bytesNeeded = 3;
        codePoint = byte & 0x07;
      } else {
        output += "\ufffd";
      }
      continue;
    }

    if (byte < lowerBoundary || byte > upperBoundary) {
      codePoint = 0;
      bytesNeeded = 0;
      bytesSeen = 0;
      lowerBoundary = 0x80;
      upperBoundary = 0xbf;
      output += "\ufffd";
      continue;
    }

    lowerBoundary = 0x80;
    upperBoundary = 0xbf;
    codePoint = (codePoint << 6) | (byte & 0x3f);
    bytesSeen++;
    index++;

    if (bytesSeen === bytesNeeded) {
      if (codePoint > 0xffff) {
        const supplementary = codePoint - 0x10000;
        output += String.fromCharCode(
          0xd800 + (supplementary >> 10),
          0xdc00 + (supplementary & 0x3ff),
        );
      } else {
        output += String.fromCharCode(codePoint);
      }
      codePoint = 0;
      bytesNeeded = 0;
      bytesSeen = 0;
    }
  }

  if (bytesNeeded !== 0) output += "\ufffd";
  return output;
}

function roundTiesToEven(value: number): number {
  const lower = Math.floor(value);
  const fraction = value - lower;

  if (fraction < 0.5) {
    return lower;
  }
  if (fraction > 0.5) {
    return lower + 1;
  }
  return lower % 2 === 0 ? lower : lower + 1;
}

/** Enforce Web IDL's required-argument check before converting any argument. */
export function requireArguments(
  args: { readonly length: number },
  required: number,
  operation: string,
): void {
  if (args.length < required) {
    throw new TypeError(operation + " requires at least " + required + " argument(s)");
  }
}

/** Reject values that Web IDL cannot convert to a dictionary. */
export function requireDictionary(value: unknown, name: string): void {
  if (
    value !== undefined &&
    value !== null &&
    typeof value !== "object" &&
    typeof value !== "function"
  ) {
    throw new TypeError(name + " must be a dictionary");
  }
}

/** Apply Web IDL's JavaScript `boolean` conversion. */
export function coerceToBoolean(value: unknown): boolean {
  return value ? true : false;
}

function unsignedInteger(value: number, modulus: number): number {
  const number = +value;
  if (!Number.isFinite(number) || number === 0) {
    return 0;
  }
  const integer = number < 0 ? Math.ceil(number) : Math.floor(number);
  if (integer === 0) {
    return 0;
  }
  const remainder = integer % modulus;
  return remainder < 0 ? remainder + modulus : remainder;
}

/** Convert a number using Web IDL's default `unsigned short` rules. */
export function toUnsignedShort(value: number): number {
  return unsignedInteger(value, 65_536);
}

/** Convert a number using Web IDL's default `unsigned long` rules. */
export function toUnsignedLong(value: number): number {
  return unsignedInteger(value, 4_294_967_296);
}

/** Convert `[EnforceRange] unsigned long long` without narrowing it to a timer ABI. */
export function toEnforceRangeUnsignedLongLong(value: number): number {
  const number = +value;
  if (!Number.isFinite(number)) {
    throw new TypeError("Value is not a finite unsigned long long");
  }
  const integer = number < 0 ? Math.ceil(number) : Math.floor(number);
  // 2^64 is exactly representable; every representable value below it is in range.
  if (integer < 0 || integer >= 18_446_744_073_709_551_616) {
    throw new TypeError("Value is outside the unsigned long long range");
  }
  return integer === 0 ? 0 : integer;
}

/** Convert a number using Web IDL's `[Clamp] unsigned short` rules. */
export function toClampedUnsignedShort(value: number): number {
  const number = +value;
  if (Number.isNaN(number) || number <= 0) {
    return 0;
  }
  if (number >= 65_535) {
    return 65_535;
  }
  return roundTiesToEven(number);
}

/** Convert a number using Web IDL's `[Clamp] long long` rules. */
export function toClampedLongLong(value: number): number {
  const number = +value;
  if (Number.isNaN(number)) {
    return 0;
  }
  if (number <= Number.MIN_SAFE_INTEGER) {
    return Number.MIN_SAFE_INTEGER;
  }
  if (number >= Number.MAX_SAFE_INTEGER) {
    return Number.MAX_SAFE_INTEGER;
  }
  return roundTiesToEven(number);
}

/** Convert a number using Web IDL's default signed `long long` rules. */
export function toLongLong(value: number): number {
  const number = +value;
  if (!Number.isFinite(number) || number === 0) {
    return 0;
  }

  const integer = number < 0 ? Math.ceil(number) : Math.floor(number);
  // Every safe JavaScript integer is already within the signed 64-bit range.
  // Returning it directly also avoids losing the low bits while adding 2^64.
  if (Number.isSafeInteger(integer)) {
    return integer;
  }
  const modulus = 18_446_744_073_709_551_616;
  const signedBoundary = 9_223_372_036_854_775_808;
  let wrapped = integer % modulus;
  if (wrapped < 0) {
    wrapped += modulus;
  }
  return wrapped >= signedBoundary ? wrapped - modulus : wrapped;
}

/** Convert a TypeScript string to a Web IDL scalar-value string. */
export function toUSVString(value: string): string {
  let result = "";
  let runStart = 0;

  for (let index = 0; index < value.length; index++) {
    const unit = value.charCodeAt(index);

    if (unit >= 0xd800 && unit <= 0xdbff) {
      const next = index + 1 < value.length ? value.charCodeAt(index + 1) : 0;
      if (next >= 0xdc00 && next <= 0xdfff) {
        index++;
        continue;
      }
    } else if (unit < 0xdc00 || unit > 0xdfff) {
      continue;
    }

    result += value.slice(runStart, index) + "\ufffd";
    runStart = index + 1;
  }

  return runStart === 0 ? value : result + value.slice(runStart);
}

/** Apply Web IDL's JavaScript `DOMString` conversion. */
export function coerceToDOMString(value: unknown): string {
  return typeof value === "string" ? value : `${value}`;
}

/** Apply JavaScript string coercion before the typed `USVString` conversion. */
export function coerceToUSVString(value: unknown): string {
  return toUSVString(coerceToDOMString(value));
}

/** Apply Web IDL's JavaScript `ByteString` conversion. */
export function coerceToByteString(value: unknown): string {
  const text = coerceToDOMString(value);
  for (let index = 0; index < text.length; index++) {
    if (text.charCodeAt(index) > 255) {
      throw new TypeError("ByteString contains a code unit greater than 255");
    }
  }
  return text;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoAeadParameters, CryptoProvider } from "../provider/crypto.ts";
import type { AeadParams, NormalizedAlgorithm } from "./algorithms.ts";
import { cryptoByteSubarray, cryptoViewByteLength } from "./buffer-source.ts";
import type { CryptoKeySlots } from "./crypto-key.ts";

const emptyBytes = new Uint8Array(0);

function operationError(): DOMException {
  return new DOMException("The authenticated encryption operation failed", "OperationError");
}

/** Modern Algorithms §§10.4.1–2 and 11.3.1–2: IV validation precedes tag policy. */
function aeadParameters(algorithm: AeadParams): CryptoAeadParameters {
  const ivLength = cryptoViewByteLength(algorithm.iv);
  const ocb = algorithm.name === "AES-OCB";
  if (ocb ? ivLength > 15 : ivLength !== 12) throw operationError();
  const tagLength = algorithm.tagLength ?? 128;
  if (ocb ? tagLength !== 64 && tagLength !== 96 && tagLength !== 128 : tagLength !== 128) {
    throw operationError();
  }
  return { name: algorithm.name, iv: algorithm.iv,
    additionalData: algorithm.additionalData ?? emptyBytes, tagLength };
}

/** https://wicg.github.io/webcrypto-modern-algos/#aes-ocb-operations-encrypt */
export function encryptAead(provider: CryptoProvider, algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots, data: Uint8Array): Uint8Array {
  const parameters = aeadParameters(algorithm as AeadParams);
  const result = provider.encrypt(parameters, key.handle, data);
  if ("failure" in result || result.tag === null
    || cryptoViewByteLength(result.tag) !== parameters.tagLength / 8) throw operationError();
  const byteLength = cryptoViewByteLength(result.bytes);
  const output = new Uint8Array(byteLength + cryptoViewByteLength(result.tag));
  output.set(result.bytes);
  output.set(result.tag, byteLength);
  return output;
}

/** Authentication remains a single native operation, with no partial plaintext. */
export function decryptAead(provider: CryptoProvider, algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots, data: Uint8Array): Uint8Array {
  const parameters = aeadParameters(algorithm as AeadParams);
  const tagBytes = parameters.tagLength / 8;
  const byteLength = cryptoViewByteLength(data);
  if (byteLength < tagBytes) throw operationError();
  const result = provider.decrypt(parameters, key.handle, {
    bytes: cryptoByteSubarray(data, 0, byteLength - tagBytes),
    tag: cryptoByteSubarray(data, byteLength - tagBytes, byteLength),
  });
  if ("failure" in result) throw operationError();
  return result;
}

import { DOMException } from "../core/errors.ts";
import type {
  CryptoAesCbcParameters,
  CryptoAesCtrParameters,
  CryptoAesGcmParameters,
  CryptoCiphertext,
  CryptoFailure,
  CryptoProvider,
} from "../provider/crypto.ts";
import type { AesCbcParams, AesCtrParams, AesGcmParams, Algorithm } from "./algorithms.ts";
import { copyCryptoBytes, cryptoByteSubarray, cryptoViewByteLength } from "./buffer-source.ts";
import type { CryptoKeySlots } from "./crypto-key.ts";

const emptyBytes = new Uint8Array(0);
const maximumGcmPlaintextBytes = 2 ** 39 - 256;
const unsignedLongLongLimit = 2 ** 64;

function operationError(): DOMException {
  return new DOMException("The AES operation failed", "OperationError");
}

function cipherBytes(result: CryptoCiphertext | CryptoFailure): Uint8Array {
  if ("failure" in result) throw operationError();
  return result.bytes;
}

function plaintextBytes(result: Uint8Array | CryptoFailure): Uint8Array {
  if ("failure" in result) throw operationError();
  return result;
}

/** §27.7 and SP 800-38A Appendix B: one message cannot reuse a counter block. */
function ctrParameters(algorithm: AesCtrParams, byteLength: number): CryptoAesCtrParameters {
  if (cryptoViewByteLength(algorithm.counter) !== 16) throw operationError();
  if (algorithm.length === 0 || algorithm.length > 128) throw operationError();
  const partialBlock = byteLength % 16;
  const blocks = (byteLength - partialBlock) / 16 + (partialBlock === 0 ? 0 : 1);
  if (blocks > 2 ** algorithm.length) throw operationError();
  return { name: "AES-CTR", counter: algorithm.counter, counterLength: algorithm.length };
}

function cbcParameters(algorithm: AesCbcParams): CryptoAesCbcParameters {
  if (cryptoViewByteLength(algorithm.iv) !== 16) throw operationError();
  return { name: "AES-CBC", iv: algorithm.iv };
}

function gcmTagLength(algorithm: AesGcmParams): number {
  const length = algorithm.tagLength;
  if (length === undefined) return 128;
  switch (length) {
    case 32:
    case 64:
    case 96:
    case 104:
    case 112:
    case 120:
    case 128:
      return length;
    default:
      throw operationError();
  }
}

function checkGcmLengths(algorithm: AesGcmParams): void {
  // >= 2^64 is the exact representable comparison for > 2^64 - 1.
  if (cryptoViewByteLength(algorithm.iv) >= unsignedLongLongLimit) throw operationError();
  if (algorithm.additionalData !== undefined
    && cryptoViewByteLength(algorithm.additionalData) >= unsignedLongLongLimit) {
    throw operationError();
  }
}

function gcmParameters(algorithm: AesGcmParams, tagLength: number): CryptoAesGcmParameters {
  return {
    name: "AES-GCM",
    iv: algorithm.iv,
    additionalData: algorithm.additionalData === undefined ? emptyBytes : algorithm.additionalData,
    tagLength,
  };
}

/**
 * Web Cryptography §§27.7.1, 28.4.1, 29.4.1 and 30.3.1.
 * https://w3c.github.io/webcrypto/#aes-ctr-operations
 * Normalization, key access checks and task settlement are the public wrapper's.
 * AES-KW reaches this function only through wrapKey, never encrypt registration.
 */
export function encryptAes(
  provider: CryptoProvider,
  algorithm: AesCtrParams | AesCbcParams | AesGcmParams | Algorithm,
  key: CryptoKeySlots,
  data: Uint8Array,
): Uint8Array {
  const length = cryptoViewByteLength(data);
  switch (algorithm.name) {
    case "AES-CTR": {
      const parameters = ctrParameters(algorithm as AesCtrParams, length);
      return cipherBytes(provider.encrypt(parameters, key.handle, data));
    }
    case "AES-CBC": {
      const parameters = cbcParameters(algorithm as AesCbcParams);
      // RFC 2315 §10.3: even block-aligned/empty messages receive a full block.
      const padding = 16 - length % 16;
      const padded = new Uint8Array(length + padding);
      padded.set(data);
      for (let index = length; index < padded.length; index++) padded[index] = padding;
      return cipherBytes(provider.encrypt(parameters, key.handle, padded));
    }
    case "AES-GCM": {
      const normalized = algorithm as AesGcmParams;
      // Encryption and decryption have deliberately different validation orders.
      checkGcmLengths(normalized);
      const tagLength = gcmTagLength(normalized);
      if (length > maximumGcmPlaintextBytes) throw operationError();
      const result = provider.encrypt(gcmParameters(normalized, tagLength), key.handle, data);
      if ("failure" in result || result.tag === null) throw operationError();
      const ciphertextLength = cryptoViewByteLength(result.bytes);
      const tagBytes = cryptoViewByteLength(result.tag);
      const ciphertext = new Uint8Array(ciphertextLength + tagBytes);
      ciphertext.set(result.bytes);
      ciphertext.set(result.tag, ciphertextLength);
      return ciphertext;
    }
    case "AES-KW": {
      // RFC 3394 §2.2.1 takes n >= 2 complete 64-bit blocks; this is not KWP.
      if (length < 16 || length % 8 !== 0) throw operationError();
      return cipherBytes(provider.encrypt({ name: "AES-KW" }, key.handle, data));
    }
    default:
      throw new DOMException("The algorithm is not an AES operation", "NotSupportedError");
  }
}

/** Web Cryptography §§27.7.2, 28.4.2, 29.4.2 and 30.3.2. */
export function decryptAes(
  provider: CryptoProvider,
  algorithm: AesCtrParams | AesCbcParams | AesGcmParams | Algorithm,
  key: CryptoKeySlots,
  data: Uint8Array,
): Uint8Array {
  const length = cryptoViewByteLength(data);
  switch (algorithm.name) {
    case "AES-CTR": {
      const parameters = ctrParameters(algorithm as AesCtrParams, length);
      return plaintextBytes(provider.decrypt(parameters, key.handle, { bytes: data, tag: null }));
    }
    case "AES-CBC": {
      const parameters = cbcParameters(algorithm as AesCbcParams);
      if (length === 0 || length % 16 !== 0) throw operationError();
      const padded = plaintextBytes(provider.decrypt(parameters, key.handle, { bytes: data, tag: null }));
      const paddedLength = cryptoViewByteLength(padded);
      const padding = padded[paddedLength - 1]!;
      // Inspect the complete final block regardless of the padding value or the
      // first mismatch. Only the final decision depends on the collected result.
      let invalid = ((padding - 1) >>> 31) | ((16 - padding) >>> 31);
      for (let index = 0; index < 16; index++) {
        invalid |= (padded[paddedLength - index - 1]! ^ padding) & ((index - padding) >> 31);
      }
      if (invalid !== 0) throw operationError();
      // Return an exact buffer: exposing a subview's backing buffer would retain
      // the padding in SubtleCrypto's public ArrayBuffer result.
      return copyCryptoBytes(cryptoByteSubarray(padded, 0, paddedLength - padding));
    }
    case "AES-GCM": {
      const normalized = algorithm as AesGcmParams;
      const tagLength = gcmTagLength(normalized);
      checkGcmLengths(normalized);
      const tagBytes = tagLength / 8;
      if (length < tagBytes) throw operationError();
      const ciphertext = {
        bytes: cryptoByteSubarray(data, 0, length - tagBytes),
        tag: cryptoByteSubarray(data, length - tagBytes, length),
      };
      return plaintextBytes(provider.decrypt(gcmParameters(normalized, tagLength), key.handle, ciphertext));
    }
    case "AES-KW": {
      // RFC 3394 §2.2.2 adds one 64-bit integrity block to n >= 2 data blocks.
      if (length < 24 || length % 8 !== 0) throw operationError();
      return plaintextBytes(provider.decrypt({ name: "AES-KW" }, key.handle, { bytes: data, tag: null }));
    }
    default:
      throw new DOMException("The algorithm is not an AES operation", "NotSupportedError");
  }
}

import { DOMException } from "../core/errors.ts";
import { coerceToDOMString } from "../core/webidl.ts";
import type { CryptoDigestName, CryptoMlAlgorithmName, CryptoMlDsaName } from "../provider/crypto.ts";
import {
  copyCryptoBytes,
  cryptoBytes,
  cryptoTypedArrayName,
  toCryptoArrayBufferView,
  toCryptoBufferSource,
} from "./buffer-source.ts";
import type { CryptoBufferSource } from "./buffer-source.ts";
import { getCryptoKeySlots } from "./crypto-key.ts";
import type { CryptoKey } from "./crypto-key.ts";
import { toCryptoUnsignedInteger } from "./webidl.ts";

/** Web Cryptography §11. Objects are not converted to dictionaries until normalization. */
export type AlgorithmIdentifier = string | object;

/** The operations in Web Cryptography §18.2.2, including deriveKey's internal operation. */
export type CryptoOperation =
  | "encrypt"
  | "decrypt"
  | "sign"
  | "verify"
  | "digest"
  | "generateKey"
  | "deriveBits"
  // supports() also normalizes this public name; it has no direct registration.
  | "deriveKey"
  | "importKey"
  | "exportKey"
  | "wrapKey"
  | "unwrapKey"
  | "get key length"
  | "encapsulate"
  | "decapsulate"
  | "get shared key length";

/** Typed IDL dictionary; later algorithm dictionaries extend this layout. */
export class Algorithm<Name extends string = string> {
  readonly name: Name;

  constructor(name: Name) {
    this.name = name;
  }
}

/** SHA's registration (§32.2) uses Algorithm, with no additional members. */
export class DigestAlgorithm extends Algorithm<CryptoDigestName> {
  constructor(name: CryptoDigestName) {
    super(name);
  }
}

export type AesAlgorithmName = "AES-CTR" | "AES-CBC" | "AES-GCM" | "AES-KW" | "AES-OCB";
export type KmacAlgorithmName = "KMAC128" | "KMAC256";
export type CshakeAlgorithmName = "cSHAKE128" | "cSHAKE256";
export type SecretAlgorithmName = AesAlgorithmName | "HMAC" | KmacAlgorithmName | "ChaCha20-Poly1305";
export type RsaAlgorithmName = "RSASSA-PKCS1-v1_5" | "RSA-PSS" | "RSA-OAEP";
export type EcAlgorithmName = "ECDSA" | "ECDH";
export type OkpAlgorithmName = "Ed25519" | "X25519" | "Ed448" | "X448";
export type Argon2AlgorithmName = "Argon2d" | "Argon2i" | "Argon2id";
export type KdfAlgorithmName = "HKDF" | "PBKDF2" | Argon2AlgorithmName;
type RegisteredAlgorithmName = CryptoMlAlgorithmName | CryptoDigestName | CshakeAlgorithmName | SecretAlgorithmName | RsaAlgorithmName | EcAlgorithmName | OkpAlgorithmName | KdfAlgorithmName;

/** Modern Algorithms §13.3. Dictionary conversion precedes BufferSource snapshots. */
export class CShakeParams extends Algorithm<CshakeAlgorithmName> {
  readonly outputLength: number;
  readonly functionName: Uint8Array | undefined;
  readonly customization: Uint8Array | undefined;

  constructor(name: CshakeAlgorithmName, outputLength: number, functionName: Uint8Array | undefined, customization: Uint8Array | undefined) {
    super(name);
    this.outputLength = outputLength;
    this.functionName = functionName;
    this.customization = customization;
  }
}

/** Modern Algorithms §§16.3–16.4: generation and import share optional bit length. */
export class KmacKeyGenParams extends Algorithm<KmacAlgorithmName> {
  readonly length: number | undefined;

  constructor(name: KmacAlgorithmName, length: number | undefined) {
    super(name);
    this.length = length;
  }
}

export class KmacImportParams extends Algorithm<KmacAlgorithmName> {
  readonly length: number | undefined;

  constructor(name: KmacAlgorithmName, length: number | undefined) {
    super(name);
    this.length = length;
  }
}

/** Modern Algorithms §16.6. Output length is in bits, not the key's length. */
export class KmacParams extends Algorithm<KmacAlgorithmName> {
  readonly outputLength: number;
  readonly customization: Uint8Array | undefined;

  constructor(name: KmacAlgorithmName, outputLength: number, customization: Uint8Array | undefined) {
    super(name);
    this.outputLength = outputLength;
    this.customization = customization;
  }
}

/** Web Cryptography §27.5. Validation of AES key sizes is an operation step. */
export class AesKeyGenParams extends Algorithm<AesAlgorithmName> {
