/** Web IDL's (object or DOMString) union conversion, before later argument conversions. */
export function toAlgorithmIdentifier(value: unknown): AlgorithmIdentifier {
  if ((typeof value === "object" && value !== null) || typeof value === "function") {
    return value;
  }
  return coerceToDOMString(value);
}

function algorithmName(algorithm: object): string {
  // The specification passes an arbitrary object. One ordinary Get, followed
  // by required-member validation and DOMString conversion, is observable.
  const name: unknown = (algorithm as { readonly name?: unknown }).name;
  if (name === undefined) throw new TypeError("Algorithm.name is required");
  return coerceToDOMString(name);
}

function equalIgnoringASCIICase(left: string, right: string): boolean {
  if (left.length !== right.length) return false;
  for (let index = 0; index < left.length; index++) {
    let code = left.charCodeAt(index);
    let expected = right.charCodeAt(index);
    if (code >= 0x61 && code <= 0x7a) code -= 0x20;
    if (expected >= 0x61 && expected <= 0x7a) expected -= 0x20;
    if (code !== expected) return false;
  }
  return true;
}

function findRegistration(name: string, operation: CryptoOperation): AlgorithmRegistration | undefined {
  for (let index = 0; index < registeredAlgorithms.length; index++) {
    const registration = registeredAlgorithms[index]!;
    if (registration.operation === operation && equalIgnoringASCIICase(name, registration.name)) {
      return registration;
    }
  }
  return undefined;
}

/** Internal operation lookup, including exportKey's registry check (§14.3.10). */
export function supportsCryptoOperation(name: string, operation: CryptoOperation): boolean {
  return findRegistration(name, operation) !== undefined;
}

function requiredMember(value: unknown, name: string): unknown {
  if (value === undefined) throw new TypeError(name + " is required");
  return value;
}

function normalizedBytes(source: CryptoBufferSource, copyBuffers: boolean): Uint8Array {
  return copyBuffers ? copyCryptoBytes(source) : cryptoBytes(source);
}

function agreementParameters(algorithm: object, name: "ECDH" | "X25519" | "X448"): EcdhKeyDeriveParams {
  const input = algorithm as { readonly public?: unknown };
  const publicKey = requiredMember(input.public, name + ".public");
  // Web IDL validates the interface brand here. Algorithm, kind and permission
  // checks belong to the later operation and preserve their specified ordering.
  getCryptoKeySlots(publicKey);
  return new EcdhKeyDeriveParams(name, publicKey as CryptoKey);
}

function aeadParameters(algorithm: object, name: "AES-OCB" | "ChaCha20-Poly1305", copyBuffers: boolean): AeadParams {
  const input = algorithm as { readonly additionalData?: unknown; readonly iv?: unknown; readonly tagLength?: unknown };
  // Web IDL converts dictionary members lexicographically; normalization then
  // snapshots BufferSources in their declared order, after all getters finish.
  const additionalDataValue = input.additionalData;
  const additionalData = additionalDataValue === undefined ? undefined : toCryptoBufferSource(additionalDataValue);
  const iv = toCryptoBufferSource(requiredMember(input.iv, name + ".iv"));
  const tagLengthValue = input.tagLength;
  const tagLength = tagLengthValue === undefined ? undefined : toCryptoUnsignedInteger(tagLengthValue, 8);
  return new AeadParams(name, normalizedBytes(iv, copyBuffers),
    additionalData === undefined ? undefined : normalizedBytes(additionalData, copyBuffers), tagLength);
}

function normalizeRegisteredAlgorithm(
  algorithm: object,
  name: RegisteredAlgorithmName,
  operation: CryptoOperation,
  copyBuffers: boolean,
): NormalizedAlgorithm {
  // Every desired dictionary inherits Algorithm: its name is read and converted
  // first, even though normalization subsequently restores the initial match.
  algorithmName(algorithm);

  if (name === "SHA-1" || name === "SHA-256" || name === "SHA-384" || name === "SHA-512"
    || name === "SHA3-256" || name === "SHA3-384" || name === "SHA3-512") {
    return new DigestAlgorithm(name);
  }

  if (name === "cSHAKE128" || name === "cSHAKE256") {
    const input = algorithm as { readonly customization?: unknown; readonly functionName?: unknown; readonly outputLength?: unknown };
    const customizationValue = input.customization;
    const customization = customizationValue === undefined ? undefined : toCryptoBufferSource(customizationValue);
    const functionNameValue = input.functionName;
    const functionName = functionNameValue === undefined ? undefined : toCryptoBufferSource(functionNameValue);
    const outputLength = toCryptoUnsignedInteger(requiredMember(input.outputLength, "cSHAKE.outputLength"), 32);
    // The declared BufferSource order is functionName then customization.
    const functionBytes = functionName === undefined ? undefined : normalizedBytes(functionName, copyBuffers);
    const customizationBytes = customization === undefined ? undefined : normalizedBytes(customization, copyBuffers);
    return new CShakeParams(name, outputLength, functionBytes, customizationBytes);
  }

  if (name === "KMAC128" || name === "KMAC256") {
    if (operation === "generateKey" || operation === "importKey" || operation === "get key length") {
      const input = algorithm as { readonly length?: unknown };
      const lengthValue = input.length;
      const length = lengthValue === undefined ? undefined : toCryptoUnsignedInteger(lengthValue, 32);
      return operation === "generateKey" ? new KmacKeyGenParams(name, length) : new KmacImportParams(name, length);
    }
    if (operation === "exportKey") return new Algorithm(name);
    const input = algorithm as { readonly customization?: unknown; readonly outputLength?: unknown };
    const customizationValue = input.customization;
    const customization = customizationValue === undefined ? undefined : toCryptoBufferSource(customizationValue);
    const outputLength = toCryptoUnsignedInteger(requiredMember(input.outputLength, "KMAC.outputLength"), 32);
    return new KmacParams(name, outputLength, customization === undefined ? undefined : normalizedBytes(customization, copyBuffers));
  }

  if (name === "ChaCha20-Poly1305") {
    return operation === "encrypt" || operation === "decrypt"
      ? aeadParameters(algorithm, name, copyBuffers) : new Algorithm(name);
  }

  if (name === "ML-KEM-512" || name === "ML-KEM-768" || name === "ML-KEM-1024") return new Algorithm(name);

  if (name === "ML-DSA-44" || name === "ML-DSA-65" || name === "ML-DSA-87") {
    if (operation !== "sign" && operation !== "verify") return new Algorithm(name);
    const input = algorithm as { readonly context?: unknown };
    const value = input.context;
    const context = value === undefined ? undefined : toCryptoBufferSource(value);
    return new ContextParams(name, context === undefined ? undefined : normalizedBytes(context, copyBuffers));
  }

  if (name === "Ed25519") return new Algorithm(name);
  if (name === "X25519" || name === "X448") {
    return operation === "deriveBits" ? agreementParameters(algorithm, name) : new Algorithm(name);
  }
  if (name === "Ed448") {
    if (operation !== "sign" && operation !== "verify") return new Algorithm(name);
    const input = algorithm as { readonly context?: unknown };
    const contextValue = input.context;
    const context = contextValue === undefined ? undefined : toCryptoBufferSource(contextValue);
    return new Ed448Params(name, context === undefined ? undefined : normalizedBytes(context, copyBuffers));
  }

  if (name === "HKDF") {
    if (operation !== "deriveBits") return new Algorithm(name);
    const input = algorithm as { readonly hash?: unknown; readonly salt?: unknown; readonly info?: unknown };
    // Web IDL visits members lexicographically; §18.4.4 then processes their
    // declared order: hash normalization, salt snapshot, info snapshot.
    const hash = toAlgorithmIdentifier(requiredMember(input.hash, "HKDF.hash"));
    const info = toCryptoBufferSource(requiredMember(input.info, "HKDF.info"));
    const salt = toCryptoBufferSource(requiredMember(input.salt, "HKDF.salt"));
    const normalizedHash = normalizeHashAlgorithm(hash);
    const saltBytes = normalizedBytes(salt, copyBuffers);
    const infoBytes = normalizedBytes(info, copyBuffers);
    return new HkdfParams(name, normalizedHash, saltBytes, infoBytes);
  }

  if (name === "PBKDF2") {
    if (operation !== "deriveBits") return new Algorithm(name);
    const input = algorithm as { readonly hash?: unknown; readonly salt?: unknown; readonly iterations?: unknown };
    const hash = toAlgorithmIdentifier(requiredMember(input.hash, "PBKDF2.hash"));
    const iterations = toCryptoUnsignedInteger(requiredMember(input.iterations, "PBKDF2.iterations"), 32);
    const salt = toCryptoBufferSource(requiredMember(input.salt, "PBKDF2.salt"));
    // PBKDF2 declares salt before hash. An object hash may execute script during
    // recursive normalization, so its salt must be copied even for immediate use.
    const saltBytes = normalizedBytes(salt, copyBuffers || typeof hash !== "string");
    const normalizedHash = normalizeHashAlgorithm(hash);
    return new Pbkdf2Params(name, normalizedHash, saltBytes, iterations);
  }

  if (name === "Argon2d" || name === "Argon2i" || name === "Argon2id") {
    if (operation !== "deriveBits") return new Algorithm(name);
    const input = algorithm as {
      readonly nonce?: unknown;
      readonly parallelism?: unknown;
      readonly memory?: unknown;
      readonly passes?: unknown;
      readonly version?: unknown;
      readonly secretValue?: unknown;
      readonly associatedData?: unknown;
    };
    // Web IDL converts the inherited name, then own members lexicographically.
    // Every getter/conversion finishes before any BufferSource snapshot.
    const associatedDataValue = input.associatedData;
    const associatedData = associatedDataValue === undefined ? undefined : toCryptoBufferSource(associatedDataValue);
    const memory = toCryptoUnsignedInteger(requiredMember(input.memory, "Argon2.memory"), 32);
    const nonce = toCryptoBufferSource(requiredMember(input.nonce, "Argon2.nonce"));
    const parallelism = toCryptoUnsignedInteger(requiredMember(input.parallelism, "Argon2.parallelism"), 32);
    const passes = toCryptoUnsignedInteger(requiredMember(input.passes, "Argon2.passes"), 32);
    const secretValueInput = input.secretValue;
    const secretValue = secretValueInput === undefined ? undefined : toCryptoBufferSource(secretValueInput);
    const versionValue = input.version;
    const version = versionValue === undefined ? undefined : toCryptoUnsignedInteger(versionValue, 8);
    // §18.4.4 takes snapshots in declared member order after conversion.
    const nonceBytes = normalizedBytes(nonce, copyBuffers);
    const secretBytes = secretValue === undefined ? undefined : normalizedBytes(secretValue, copyBuffers);
    const associatedBytes = associatedData === undefined ? undefined : normalizedBytes(associatedData, copyBuffers);
    return new Argon2Params(name, nonceBytes, parallelism, memory, passes, version, secretBytes, associatedBytes);
  }

  if (name === "HMAC") {
    if (operation !== "generateKey" && operation !== "importKey" && operation !== "get key length") return new Algorithm(name);
    const input = algorithm as { readonly hash?: unknown; readonly length?: unknown };
    const hash = toAlgorithmIdentifier(requiredMember(input.hash, "HMAC.hash"));
    const lengthValue = input.length;
    const length = lengthValue === undefined ? undefined : toCryptoUnsignedInteger(lengthValue, 32);
    // Dictionary conversion is complete before §18.4.4 recursively normalizes
    // HashAlgorithmIdentifier. In particular, length's coercion precedes hash.name.
    const normalizedHash = normalizeHashAlgorithm(hash);
    return operation === "generateKey"
      ? new HmacKeyGenParams(name, normalizedHash, length)
      : new HmacImportParams(name, normalizedHash, length);
  }

  if (name === "RSASSA-PKCS1-v1_5" || name === "RSA-PSS" || name === "RSA-OAEP") {
    if (operation === "generateKey") {
      const input = algorithm as {
        readonly modulusLength?: unknown;
        readonly publicExponent?: unknown;
        readonly hash?: unknown;
      };
      // RsaKeyGenParams members precede its derived RsaHashedKeyGenParams.hash.
      const modulusLength = toCryptoUnsignedInteger(requiredMember(input.modulusLength, "RSA.modulusLength"), 32);
      const publicExponent = toCryptoArrayBufferView(requiredMember(input.publicExponent, "RSA.publicExponent"));
      if (cryptoTypedArrayName(publicExponent) !== "Uint8Array") throw new TypeError("RSA.publicExponent must be a Uint8Array");
      const hash = toAlgorithmIdentifier(requiredMember(input.hash, "RSA.hash"));
      const normalizedHash = normalizeHashAlgorithm(hash);
      // BigInteger is a Uint8Array typedef, not BufferSource. §18.4.4 does not
      // snapshot it: recursive hash normalization can still change its bytes.
      return new RsaHashedKeyGenParams(name, modulusLength, cryptoBytes(publicExponent), normalizedHash);
    }
    if (operation === "importKey") {
      const input = algorithm as { readonly hash?: unknown };
      const hash = toAlgorithmIdentifier(requiredMember(input.hash, "RSA.hash"));
      return new RsaHashedImportParams(name, normalizeHashAlgorithm(hash));
    }
    if (operation === "exportKey" || name === "RSASSA-PKCS1-v1_5") return new Algorithm(name);
    if (name === "RSA-PSS") {
      const input = algorithm as { readonly saltLength?: unknown };
      const saltLength = toCryptoUnsignedInteger(requiredMember(input.saltLength, "RSA-PSS.saltLength"), 32);
      return new RsaPssParams(name, saltLength);
    }
    const input = algorithm as { readonly label?: unknown };
    const labelValue = input.label;
    const label = labelValue === undefined ? undefined : toCryptoBufferSource(labelValue);
    return new RsaOaepParams(name, label === undefined ? undefined : normalizedBytes(label, copyBuffers));
  }

  if (name === "ECDSA" || name === "ECDH") {
    if (operation === "generateKey" || operation === "importKey") {
      const input = algorithm as { readonly namedCurve?: unknown };
      const namedCurve = coerceToDOMString(requiredMember(input.namedCurve, "EC.namedCurve"));
      return operation === "generateKey" ? new EcKeyGenParams(name, namedCurve) : new EcKeyImportParams(name, namedCurve);
    }
    if (operation === "exportKey") return new Algorithm(name);
    if (name === "ECDSA") {
      const input = algorithm as { readonly hash?: unknown };
      const hash = toAlgorithmIdentifier(requiredMember(input.hash, "ECDSA.hash"));
      return new EcdsaParams(name, normalizeHashAlgorithm(hash));
    }
    return agreementParameters(algorithm, name);
  }

  if (operation === "generateKey" || operation === "get key length") {
    const input = algorithm as { readonly length?: unknown };
    const length = toCryptoUnsignedInteger(requiredMember(input.length, "AES.length"), 16);
    return operation === "generateKey" ? new AesKeyGenParams(name, length) : new AesDerivedKeyParams(name, length);
  }
  if (operation === "importKey" || operation === "exportKey" || name === "AES-KW") {
    return new Algorithm(name);
  }

  if (name === "AES-OCB") return aeadParameters(algorithm, name, copyBuffers);

  if (name === "AES-CTR") {
    const input = algorithm as { readonly counter?: unknown; readonly length?: unknown };
    const counter = toCryptoBufferSource(requiredMember(input.counter, "AES-CTR.counter"));
    const length = toCryptoUnsignedInteger(requiredMember(input.length, "AES-CTR.length"), 8);
    return new AesCtrParams(name, normalizedBytes(counter, copyBuffers), length);
  }
  if (name === "AES-CBC") {
    const input = algorithm as { readonly iv?: unknown };
    const iv = toCryptoBufferSource(requiredMember(input.iv, "AES-CBC.iv"));
    return new AesCbcParams(name, normalizedBytes(iv, copyBuffers));
  }

  const input = algorithm as {
    readonly additionalData?: unknown;
    readonly iv?: unknown;
    readonly tagLength?: unknown;
  };
  // Web IDL converts inherited members first, then own members lexicographically:
  // name, additionalData, iv, tagLength, regardless of declaration/property order.
  const additionalDataValue = input.additionalData;
  const additionalData = additionalDataValue === undefined ? undefined : toCryptoBufferSource(additionalDataValue);
  const iv = toCryptoBufferSource(requiredMember(input.iv, "AES-GCM.iv"));
  const tagLengthValue = input.tagLength;
  const tagLength = tagLengthValue === undefined ? undefined : toCryptoUnsignedInteger(tagLengthValue, 8);
  // All getters and conversions finish before any BufferSource snapshot is made.
  const ivBytes = normalizedBytes(iv, copyBuffers);
  const additionalBytes = additionalData === undefined ? undefined : normalizedBytes(additionalData, copyBuffers);
  return new AesGcmParams(name, ivBytes, additionalBytes, tagLength);
}

/**
 * Web Cryptography §18.4.4, https://w3c.github.io/webcrypto/#algorithm-normalization.
 * The initial Algorithm conversion and the registered dictionary conversion
 * are separate: a supported object's name getter and coercion run twice.
 * Borrow bytes only when no script can run before synchronous primitive use.
 * unwrapKey needs snapshots because a second algorithm is normalized afterward.
 */
export function normalizeAlgorithm(
  value: AlgorithmIdentifier,
  operation: "digest",
  copyBuffers?: boolean,
): DigestAlgorithm | CShakeParams;
export function normalizeAlgorithm(
  value: AlgorithmIdentifier,
  operation: CryptoOperation,
  copyBuffers?: boolean,
): NormalizedAlgorithm;
export function normalizeAlgorithm(
  value: AlgorithmIdentifier,
  operation: CryptoOperation,
  copyBuffers = false,
): NormalizedAlgorithm {
  const algorithm = typeof value === "string" ? new Algorithm(value) : value;
  const name = algorithmName(algorithm);
  const registration = findRegistration(name, operation);
  if (registration !== undefined) {
    return normalizeRegisteredAlgorithm(algorithm, registration.name, operation, copyBuffers);
  }
  throw new DOMException("The algorithm is not supported for " + operation, "NotSupportedError");
}

/** Fixed-size hash choices supported by the native RSA/HMAC/EC/KDF operations. */
export function normalizeHashAlgorithm(value: AlgorithmIdentifier): DigestAlgorithm {
  const algorithm = normalizeAlgorithm(value, "digest");
  if (!(algorithm instanceof DigestAlgorithm)) {
    throw new DOMException("An extensible-output digest is not supported as a hash parameter", "NotSupportedError");
  }
  return algorithm;
}

/**
 * Web IDL buffer conversions used by Crypto. These are local because core is
 * owned by another task. https://webidl.spec.whatwg.org/#es-buffer-source-types
 *
 * nts programs have one realm and fixed intrinsic layouts: they cannot redefine
 * intrinsic accessors or patch prototypes. The plain buffer, byteOffset,
 * byteLength, resizable and detached reads below are the Web IDL slot reads.
 * Fixed class identity supplies the buffer/view brands and typed-array kind.
 */
const emptyBytes = new Uint8Array(0);

export type CryptoBufferSource = ArrayBuffer | ArrayBufferView;

export function cryptoTypedArrayName(view: ArrayBufferView): string | undefined {
  if (view instanceof Uint8Array) return "Uint8Array";
  if (view instanceof Int8Array) return "Int8Array";
  if (view instanceof Uint8ClampedArray) return "Uint8ClampedArray";
  if (view instanceof Int16Array) return "Int16Array";
  if (view instanceof Uint16Array) return "Uint16Array";
  if (view instanceof Int32Array) return "Int32Array";
  if (view instanceof Uint32Array) return "Uint32Array";
  if (view instanceof BigInt64Array) return "BigInt64Array";
  if (view instanceof BigUint64Array) return "BigUint64Array";
  return undefined;
}

function requireFixedArrayBuffer(value: unknown): asserts value is ArrayBuffer {
  // Reject SharedArrayBuffer and non-buffers before reading slots. A detached
  // fixed ArrayBuffer is valid Web IDL.
  if (!(value instanceof ArrayBuffer)) throw new TypeError("Expected an ArrayBuffer");
  if (value.resizable) {
    throw new TypeError("Resizable ArrayBuffers are not allowed by this operation");
  }
}

export function toCryptoArrayBufferView(value: unknown): ArrayBufferView {
  if (!ArrayBuffer.isView(value)) throw new TypeError("Expected an ArrayBufferView");
  requireFixedArrayBuffer(value.buffer);
  return value;
}

export function toCryptoBufferSource(value: unknown): CryptoBufferSource {
  if (ArrayBuffer.isView(value)) {
    requireFixedArrayBuffer(value.buffer);
    return value;
  }
  requireFixedArrayBuffer(value);
  return value;
}

/** Select BufferSource before the dictionary branch of importKey's IDL union. */
export function isCryptoBufferSource(value: unknown): boolean {
  return ArrayBuffer.isView(value) || value instanceof ArrayBuffer;
}

/**
 * Borrow precisely the bytes the specification would copy. Native primitives
 * consume them synchronously without running script or retaining input memory.
 * Call only after normalization: its getters may mutate or detach the input.
 * A detached BufferSource has an empty byte sequence (Web IDL #get-buffer-source-copy).
 */
export function cryptoBytes(source: CryptoBufferSource): Uint8Array {
  if (!ArrayBuffer.isView(source)) {
    if (source.detached) return emptyBytes;
    return new Uint8Array(source);
  }
  const name = cryptoTypedArrayName(source);
  const buffer = source.buffer as ArrayBuffer;
  if (buffer.detached) return emptyBytes;
  // The common path passes the caller's very view, allocating no wrapper.
  if (name === "Uint8Array") return source as Uint8Array;
  return new Uint8Array(buffer, source.byteOffset, source.byteLength);
}

export function cryptoViewByteLength(view: ArrayBufferView): number {
  // This helper is used after getRandomValues has rejected DataView/float views.
  return view.byteLength;
}

/** Internal bounds are already checked; intrinsic view slots have fixed layouts. */
export function cryptoByteSubarray(bytes: Uint8Array, start: number, end: number): Uint8Array {
  return new Uint8Array(bytes.buffer, bytes.byteOffset + start, end - start);
}

/** Snapshot only when later author code can observe the specification's copy. */
export function copyCryptoBytes(source: CryptoBufferSource): Uint8Array {
  const bytes = cryptoBytes(source);
  const result = new Uint8Array(bytes.byteLength);
  result.set(bytes);
  return result;
}

import type { CryptoProvider } from "../provider/crypto.ts";
import type { Crypto } from "./crypto.ts";

// Identity is the only key property inspected. The object-keyed reader can
// reject an unregistered object without invoking any public Crypto accessor;
// registration itself accepts only the internally constructed Crypto layout.
const cryptoCapabilities = new WeakMap<object, CryptoProvider>();

export function associateCryptoCapability(crypto: Crypto, provider: CryptoProvider): void {
  cryptoCapabilities.set(crypto, provider);
}

/** Module-internal state for Modern Algorithms §3.2.6, never a public member. */
export function cryptoCapability(crypto: object): CryptoProvider | undefined {
  return cryptoCapabilities.get(crypto);
}

import type { CryptoKeyHandle, CryptoKeyType } from "../provider/crypto.ts";

/** Web Cryptography Level 2, §13.2: the key's kind and permitted operations. */
export type KeyType = CryptoKeyType;

export type KeyUsage =
  | "encrypt"
  | "decrypt"
  | "sign"
  | "verify"
  | "deriveKey"
  | "deriveBits"
  | "wrapKey"
  | "unwrapKey"
  | "encapsulateKey"
  | "encapsulateBits"
  | "decapsulateKey"
  | "decapsulateBits";

/** Web Cryptography §17. An ordinary dictionary containing two independent keys. */
export interface CryptoKeyPair {
  privateKey: CryptoKey;
  publicKey: CryptoKey;
}

function copyUsages(usages: readonly KeyUsage[]): KeyUsage[] {
  const copy: KeyUsage[] = [];
  for (let index = 0; index < usages.length; index++) copy[index] = usages[index]!;
  return copy;
}

/** The ordinary ECMAScript dictionary exposed by CryptoKey.algorithm. */
export interface KeyAlgorithmObject {
  name: string;
}

/**
 * The typed internal KeyAlgorithm dictionary (§12), not its public cached view.
 * Algorithm-specific subclasses copy their nested dictionaries and byte arrays
 * in copy() and toObject(), so neither input aliases nor public mutations can
 * change the key's internal algorithm.
 */
export class KeyAlgorithm {
  readonly name: string;

  constructor(name: string) {
    this.name = name;
  }

  copy(): KeyAlgorithm {
    return new KeyAlgorithm(this.name);
  }

  toObject(): KeyAlgorithmObject {
    return { name: this.name };
  }
}

/**
 * Internal key state (§13.3). Only shared cryptographic algorithms import this
 * type and getCryptoKeySlots; these names are not public Web globals.
 */
export class CryptoKeySlots {
  readonly type: KeyType;
  readonly extractable: boolean;
  readonly algorithm: KeyAlgorithm;
  readonly usages: readonly KeyUsage[];
  readonly handle: CryptoKeyHandle;

  constructor(
    type: KeyType,
    extractable: boolean,
    algorithm: KeyAlgorithm,
    usages: readonly KeyUsage[],
    handle: CryptoKeyHandle,
  ) {
    this.type = type;
    this.extractable = extractable;
    this.algorithm = algorithm.copy();
    this.usages = copyUsages(usages);
    this.handle = handle;
  }
}

class CryptoKeyState {
  readonly slots: CryptoKeySlots;
  readonly algorithmCached: KeyAlgorithmObject;
  readonly usagesCached: KeyUsage[];

  constructor(slots: CryptoKeySlots) {
    this.slots = slots;
    // §9's cached ECMAScript objects are mutable snapshots, not frozen values.
    // Make each snapshot once; reading either attribute must preserve identity.
    this.algorithmCached = slots.algorithm.toObject();
    this.usagesCached = copyUsages(slots.usages);
  }
}

const constructorToken = Symbol("CryptoKey construction");
const keyStates = new WeakMap<object, CryptoKeyState>();
// Rule 405266cf7: nts programs cannot replace intrinsic methods. Read the
// private map directly instead of capturing bound copies of its methods.

function keyState(key: unknown): CryptoKeyState {
  if ((typeof key !== "object" || key === null) && typeof key !== "function") {
    throw new TypeError("Value is not a CryptoKey");
  }
  const state = keyStates.get(key);
  if (state === undefined) throw new TypeError("Value is not a CryptoKey");
  return state;
}

/**
 * Web Cryptography Level 2, §§13.3–13.4.
 * https://w3c.github.io/webcrypto/#cryptokey-interface
 *
 * Slots live outside the public instance: property names, symbols, prototype
 * forgeries and expandos cannot reveal its native handle or alter permissions.
 */
export class CryptoKey {
  get [Symbol.toStringTag](): string { return "CryptoKey"; }

  constructor(token: symbol | undefined = undefined) {
    if (token !== constructorToken) throw new TypeError("Illegal constructor");
  }

  get type(): KeyType {
    return getCryptoKeySlots(this).type;
  }

  get extractable(): boolean {
    return getCryptoKeySlots(this).extractable;
  }

  get algorithm(): KeyAlgorithmObject {
    return keyState(this).algorithmCached;
  }

  get usages(): KeyUsage[] {
    return keyState(this).usagesCached;
  }
}

/**
 * Construct a key after the algorithm's validation and usage normalization.
 * The caller, not the primitive provider or this slot constructor, determines
 * the specification's type, extractability, algorithm and permitted usages.
 */
export function createCryptoKey(
  type: KeyType,
  extractable: boolean,
  algorithm: KeyAlgorithm,
  usages: readonly KeyUsage[],
  handle: CryptoKeyHandle,
): CryptoKey {
  const slots = new CryptoKeySlots(type, extractable, algorithm, usages, handle);
  const state = new CryptoKeyState(slots);
  const key = new CryptoKey(constructorToken);
  keyStates.set(key, state);
  return key;
}

/** Brand-check without reading any author-controlled property of the key. */
export function getCryptoKeySlots(key: unknown): CryptoKeySlots {
  return keyState(key).slots;
}

import { DOMException } from "../core/errors.ts";
import { QuotaExceededError } from "../core/quota-exceeded-error.ts";
import { requireArguments } from "../core/webidl.ts";
import type { CryptoProvider } from "../provider/crypto.ts";
import type { RandomSource, Scheduler } from "../provider/primitives.ts";
import {
  cryptoBytes,
  cryptoTypedArrayName,
  cryptoViewByteLength,
  toCryptoArrayBufferView,
} from "./buffer-source.ts";
import { associateCryptoCapability } from "./capability.ts";
import { createSubtleCrypto } from "./subtle-crypto.ts";
import type { SubtleCrypto } from "./subtle-crypto.ts";

const constructorToken = Symbol("Crypto construction");
const uuidHex: string[] = [];
for (let byte = 0; byte < 256; byte++) uuidHex.push(byte.toString(16).padStart(2, "0"));
const uuidPoolBytes = 128 * 16;

/** Web Cryptography §10, https://w3c.github.io/webcrypto/#crypto-interface. */
export class Crypto {
  readonly #random: RandomSource;
  readonly #subtle: SubtleCrypto;
  #uuidPool: Uint8Array | undefined;
  #uuidOffset: number;

  /** Web IDL supplies no public constructor or capability-injection arguments. */
  constructor(
    token: symbol | undefined = undefined,
    random?: RandomSource,
    provider?: CryptoProvider,
    scheduler?: Scheduler,
  ) {
    if (token !== constructorToken || random === undefined || provider === undefined || scheduler === undefined) {
      throw new TypeError("Illegal constructor");
    }
    this.#random = random;
    this.#subtle = createSubtleCrypto(provider, scheduler, random);
    this.#uuidPool = undefined;
    this.#uuidOffset = uuidPoolBytes;
    associateCryptoCapability(this, provider);
  }

  get subtle(): SubtleCrypto {
    return this.#subtle;
  }

  get [Symbol.toStringTag](): string { return "Crypto"; }

  getRandomValues<T extends ArrayBufferView>(array: T): T {
    const random = this.#random;
    requireArguments(arguments, 1, "Crypto.getRandomValues");
    const view = toCryptoArrayBufferView(array);
    switch (cryptoTypedArrayName(view)) {
      case "Int8Array":
      case "Uint8Array":
      case "Uint8ClampedArray":
      case "Int16Array":
      case "Uint16Array":
      case "Int32Array":
      case "Uint32Array":
      case "BigInt64Array":
      case "BigUint64Array":
        break;
      default:
        throw new DOMException("Expected an integer typed array", "TypeMismatchError");
    }
    if (cryptoViewByteLength(view) > 65_536) {
      throw new QuotaExceededError("The array exceeds 65,536 bytes");
    }
    // No backing-buffer allocation or copy. Non-Uint8 arrays need only a view
    // over the caller's exact byte range; the usual Uint8 path reuses its view.
    random.fill(cryptoBytes(view));
    return array;
  }

  randomUUID(): string {
    let pool = this.#uuidPool;
    if (pool === undefined) {
      pool = new Uint8Array(uuidPoolBytes);
      this.#uuidPool = pool;
    }
    if (this.#uuidOffset === uuidPoolBytes) {
      this.#random.fill(pool);
      this.#uuidOffset = 0;
    }
    const offset = this.#uuidOffset;
    this.#uuidOffset += 16;
    // Use the table directly: no per-UUID byte array, map, join or hex conversion.
    return uuidHex[pool[offset]!]! + uuidHex[pool[offset + 1]!]!
      + uuidHex[pool[offset + 2]!]! + uuidHex[pool[offset + 3]!]! + "-"
      + uuidHex[pool[offset + 4]!]! + uuidHex[pool[offset + 5]!]! + "-"
      + uuidHex[(pool[offset + 6]! & 0x0f) | 0x40]! + uuidHex[pool[offset + 7]!]! + "-"
      + uuidHex[(pool[offset + 8]! & 0x3f) | 0x80]! + uuidHex[pool[offset + 9]!]! + "-"
      + uuidHex[pool[offset + 10]!]! + uuidHex[pool[offset + 11]!]!
      + uuidHex[pool[offset + 12]!]! + uuidHex[pool[offset + 13]!]!
      + uuidHex[pool[offset + 14]!]! + uuidHex[pool[offset + 15]!]!;
  }
}

/** Internal embedding factory; capability injection is not part of the Web constructor. */
export function createCrypto(random: RandomSource, provider: CryptoProvider, scheduler: Scheduler): Crypto {
  return new Crypto(constructorToken, random, provider, scheduler);
}

import { DOMException } from "../core/errors.ts";
import type { CryptoEcComponents, CryptoNamedCurve, CryptoOkpCurve, CryptoRsaComponents, CryptoRsaOtherPrime } from "../provider/crypto.ts";
import { cryptoByteSubarray, cryptoViewByteLength } from "./buffer-source.ts";
import { ecCurveByteLength } from "./ec-curve.ts";
import { okpCurveByteLength } from "./okp-curve.ts";
import type { CryptoMlAlgorithmName } from "../provider/crypto.ts";
import { mlExpandedKeyLength, mlPublicKeyLength, mlSeedLength } from "./ml-parameters.ts";

function invalidDer(): never {
  throw new DOMException("The key is not a valid DER encoding", "DataError");
}

/**
 * Web Cryptography §9's exact ASN.1 parser, restricted to the key structures
 * used here. X.690 §§8–11: definite, shortest lengths; primitive integers and
 * strings; minimal signed integers; exact consumption at every boundary.
 * This checks encodings, not key arithmetic. The native import owns mathematics.
 */
class DerReader {
  readonly bytes: Uint8Array;
  position: number;
  readonly end: number;

  constructor(bytes: Uint8Array, start = 0, end = cryptoViewByteLength(bytes)) {
    this.bytes = bytes;
    this.position = start;
    this.end = end;
  }

  done(): boolean { return this.position === this.end; }

  complete(): void { if (!this.done()) invalidDer(); }

  peek(): number {
    if (this.position >= this.end) invalidDer();
    return this.bytes[this.position]!;
  }

  read(tag: number): DerReader {
    if (this.position >= this.end || this.bytes[this.position++] !== tag) invalidDer();
    return this.readContent();
  }

  readContent(): DerReader {
    if (this.position >= this.end) invalidDer();
    const first = this.bytes[this.position++]!;
    let length = first;
    if (first >= 0x80) {
      const count = first & 0x7f;
      // A valid in-memory view cannot have a length beyond Number's exact integer
      // range. Bounds below additionally avoid overflow while reading each octet.
      if (count === 0 || count > 6 || count > this.end - this.position || this.bytes[this.position] === 0) invalidDer();
      length = 0;
      for (let index = 0; index < count; index++) length = length * 256 + this.bytes[this.position++]!;
      if (length < 0x80) invalidDer();
    }
    if (length > this.end - this.position) invalidDer();
    const result = new DerReader(this.bytes, this.position, this.position + length);
    this.position += length;
    return result;
  }

  content(): Uint8Array { return cryptoByteSubarray(this.bytes, this.position, this.end); }

  integer(allowZero = false): Uint8Array {
    const value = this.read(0x02);
    const length = value.end - value.position;
    if (length === 0) invalidDer();
    const first = value.bytes[value.position]!;
    if ((first & 0x80) !== 0) invalidDer();
    if (length > 1 && first === 0 && (value.bytes[value.position + 1]! & 0x80) === 0) invalidDer();
    if (!allowZero && length === 1 && first === 0) invalidDer();
    return cryptoByteSubarray(value.bytes, value.position + (length > 1 && first === 0 ? 1 : 0), value.end);
  }
}

const rsaEncryptionOid: readonly number[] = [0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x01];

function rsaAlgorithm(reader: DerReader, requireNullParameters: boolean): void {
  const algorithm = reader.read(0x30);
  const oid = algorithm.read(0x06).content();
  if (cryptoViewByteLength(oid) !== rsaEncryptionOid.length) invalidDer();
  for (let index = 0; index < rsaEncryptionOid.length; index++) {
    if (oid[index] !== rsaEncryptionOid[index]) invalidDer();
  }
  // Imports use the generic AlgorithmIdentifier, whose parameters are optional.
  // If present, rsaEncryption defines their type as NULL (RFC 3447 A.1).
  // Exports explicitly require a present NULL in Web Cryptography §§20–22.
  if (requireNullParameters || !algorithm.done()) algorithm.read(0x05).complete();
  algorithm.complete();
}

function readOid(reader: DerReader): void {
  const oid = reader.read(0x06);
  if (oid.done()) invalidDer();
  let first = true;
  while (!oid.done()) {
    const octet = oid.bytes[oid.position++]!;
    if (first && octet === 0x80) invalidDer();
    first = (octet & 0x80) === 0;
  }
  if (!first) invalidDer();
}

function compareEncoding(bytes: Uint8Array, leftStart: number, leftEnd: number, rightStart: number, rightEnd: number): number {
  let left = leftStart;
  let right = rightStart;
  while (left < leftEnd && right < rightEnd) {
    const difference = bytes[left++]! - bytes[right++]!;
    if (difference !== 0) return difference;
  }
  return (leftEnd - left) - (rightEnd - right);
}

class DerValueFrame {
  readonly reader: DerReader;
  readonly ordered: boolean;
  previousStart: number;
  previousEnd: number;

  constructor(reader: DerReader, ordered: boolean) {
    this.reader = reader;
    this.ordered = ordered;
    this.previousStart = -1;
    this.previousEnd = -1;
  }
}

function readAttributeValue(reader: DerReader): DerValueFrame | undefined {
  const tag = reader.peek();
  if ((tag & 0x1f) === 0x1f) {
    reader.position++;
    if (reader.position >= reader.end || reader.bytes[reader.position] === 0x80) invalidDer();
    let number = 0;
    for (;;) {
      if (reader.position >= reader.end) invalidDer();
      const octet = reader.bytes[reader.position++]!;
      // An open type's identity is not otherwise used. Saturating the value
      // avoids a big integer while still rejecting an unnecessary long tag.
      if (number < 31) number = number * 128 + (octet & 0x7f);
      if ((octet & 0x80) === 0) break;
    }
    if (number < 31) invalidDer();
    const value = reader.readContent();
    return (tag & 0x20) !== 0 ? new DerValueFrame(value, false) : undefined;
  }
  if (tag === 0x00) invalidDer();
  const value = reader.read(tag);
  if ((tag & 0x20) !== 0) {
    // DER does not use constructed encodings for primitive universal types.
    if ((tag & 0xc0) === 0 && tag !== 0x30 && tag !== 0x31) invalidDer();
    return new DerValueFrame(value, tag === 0x31);
  }
  if ((tag & 0xc0) !== 0) return undefined;
  const length = value.end - value.position;
  if (tag === 0x10 || tag === 0x11) invalidDer();
  if (tag === 0x01 && (length !== 1 || (value.bytes[value.position] !== 0 && value.bytes[value.position] !== 0xff))) invalidDer();
  if (tag === 0x02 || tag === 0x0a) {
    if (length === 0) invalidDer();
    if (length > 1) {
      const first = value.bytes[value.position]!;
      const second = value.bytes[value.position + 1]!;
      if ((first === 0 && (second & 0x80) === 0) || (first === 0xff && (second & 0x80) !== 0)) invalidDer();
    }
  }
  if (tag === 0x03) {
    if (length === 0) invalidDer();
    const unused = value.bytes[value.position]!;
    if (unused > 7 || (length === 1 && unused !== 0) || (length > 1 && (value.bytes[value.end - 1]! & ((1 << unused) - 1)) !== 0)) invalidDer();
  }
  if (tag === 0x05 && length !== 0) invalidDer();
  if (tag === 0x06) {
    let first = true;
    if (length === 0) invalidDer();
    for (let index = value.position; index < value.end; index++) {
      const octet = value.bytes[index]!;
      if (first && octet === 0x80) invalidDer();
      first = (octet & 0x80) === 0;
    }
    if (!first) invalidDer();
  }
  return undefined;
}

/** Open values may nest deeply; validate iteratively without using the JS stack. */
function attributeValue(reader: DerReader): void {
  const first = readAttributeValue(reader);
  if (first === undefined) return;
  const stack: DerValueFrame[] = [first];
  while (stack.length !== 0) {
    const frame = stack[stack.length - 1]!;
    if (frame.reader.done()) {
      stack.length--;
      continue;
    }
    const start = frame.reader.position;
    const nested = readAttributeValue(frame.reader);
    if (frame.ordered && frame.previousStart >= 0 &&
        compareEncoding(frame.reader.bytes, frame.previousStart, frame.previousEnd, start, frame.reader.position) > 0) invalidDer();
    frame.previousStart = start;
    frame.previousEnd = frame.reader.position;
    if (nested !== undefined) stack[stack.length] = nested;
  }
}

function attributes(reader: DerReader): void {
  const values = reader.read(0xa0);
  let previousStart = -1;
  let previousEnd = -1;
  while (!values.done()) {
    const start = values.position;
    const attribute = values.read(0x30);
    readOid(attribute);
    const entries = attribute.read(0x31);
    if (entries.done()) invalidDer();
    let previousEntryStart = -1;
    let previousEntryEnd = -1;
    while (!entries.done()) {
      const entryStart = entries.position;
      attributeValue(entries);
      if (previousEntryStart >= 0 && compareEncoding(entries.bytes, previousEntryStart, previousEntryEnd, entryStart, entries.position) > 0) invalidDer();
      previousEntryStart = entryStart;
      previousEntryEnd = entries.position;
    }
    attribute.complete();
    if (previousStart >= 0 && compareEncoding(values.bytes, previousStart, previousEnd, start, values.position) > 0) invalidDer();
    previousStart = start;
    previousEnd = values.position;
  }
}

function publicComponents(reader: DerReader): CryptoRsaComponents {
  const key = reader.read(0x30);
  reader.complete();
  const n = key.integer();
  const e = key.integer();
  key.complete();
  return { family: "RSA", n, e };
}

function privateComponents(reader: DerReader): CryptoRsaComponents {
  const key = reader.read(0x30);
  reader.complete();
  const version = key.integer(true);
  if (cryptoViewByteLength(version) !== 1 || (version[0] !== 0 && version[0] !== 1)) invalidDer();
  const n = key.integer();
  const e = key.integer();
  const d = key.integer();
  const p = key.integer();
  const q = key.integer();
  const dp = key.integer();
  const dq = key.integer();
  const qi = key.integer();
  if (version[0] === 0) {
    key.complete();
    return { family: "RSA", n, e, d, p, q, dp, dq, qi };
  }
  const others = key.read(0x30);
  if (others.done()) invalidDer();
  const oth: CryptoRsaOtherPrime[] = [];
  while (!others.done()) {
    const prime = others.read(0x30);
    const r = prime.integer();
    const factorExponent = prime.integer();
    const t = prime.integer();
    prime.complete();
    oth[oth.length] = { r, d: factorExponent, t };
  }
  key.complete();
  return { family: "RSA", n, e, d, p, q, dp, dq, qi, oth };
}

/** Exact SPKI/PKCS #8 envelopes plus the embedded PKCS #1 key structure. */
export function parseRsaDer(format: "spki" | "pkcs8", bytes: Uint8Array, requireNullParameters = false): CryptoRsaComponents {
  const source = new DerReader(bytes);
  const envelope = source.read(0x30);
  source.complete();
  if (format === "spki") {
    rsaAlgorithm(envelope, requireNullParameters);
    const publicKey = envelope.read(0x03);
    if (publicKey.done() || publicKey.bytes[publicKey.position++] !== 0) invalidDer();
    envelope.complete();
    return publicComponents(publicKey);
  }
  const version = envelope.integer(true);
  if (cryptoViewByteLength(version) !== 1 || version[0] !== 0) invalidDer();
  rsaAlgorithm(envelope, requireNullParameters);
  const privateKey = envelope.read(0x04);
  if (!envelope.done()) attributes(envelope);
  envelope.complete();
  return privateComponents(privateKey);
}

const ecPublicKeyOid: readonly number[] = [0x2a, 0x86, 0x48, 0xce, 0x3d, 0x02, 0x01];
const p256Oid: readonly number[] = [0x2a, 0x86, 0x48, 0xce, 0x3d, 0x03, 0x01, 0x07];
const p384Oid: readonly number[] = [0x2b, 0x81, 0x04, 0x00, 0x22];
const p521Oid: readonly number[] = [0x2b, 0x81, 0x04, 0x00, 0x23];

function oidEquals(bytes: Uint8Array, expected: readonly number[]): boolean {
  if (cryptoViewByteLength(bytes) !== expected.length) return false;
  for (let index = 0; index < expected.length; index++) if (bytes[index] !== expected[index]) return false;
  return true;
}

function ecNamedCurve(reader: DerReader): CryptoNamedCurve {
  const oid = reader.read(0x06).content();
  if (oidEquals(oid, p256Oid)) return "P-256";
  if (oidEquals(oid, p384Oid)) return "P-384";
  if (oidEquals(oid, p521Oid)) return "P-521";
  invalidDer();
}

function ecAlgorithm(reader: DerReader): CryptoNamedCurve {
  const algorithm = reader.read(0x30);
  if (!oidEquals(algorithm.read(0x06).content(), ecPublicKeyOid)) invalidDer();
  // RFC 5480 §2.1.1 requires the namedCurve OID. Absent, implicit-curve,
  // and explicit-domain parameters are not Web Cryptography encodings.
  const namedCurve = ecNamedCurve(algorithm);
  algorithm.complete();
  return namedCurve;
}

/** SEC 1 §2.3.4. Compressed points are optional and are not supported here. */
export function parseEcPoint(bytes: Uint8Array, namedCurve: CryptoNamedCurve): CryptoEcComponents {
  const width = ecCurveByteLength(namedCurve);
  if (cryptoViewByteLength(bytes) !== 1 + 2 * width || bytes[0] !== 0x04) invalidDer();
  return {
    family: "EC", namedCurve,
    x: cryptoByteSubarray(bytes, 1, 1 + width),
    y: cryptoByteSubarray(bytes, 1 + width, 1 + 2 * width),
  };
}

function ecBitString(reader: DerReader, namedCurve: CryptoNamedCurve): CryptoEcComponents {
  const value = reader.read(0x03);
  if (value.done() || value.bytes[value.position++] !== 0) invalidDer();
  return parseEcPoint(value.content(), namedCurve);
}

/** A PKCS #8 private key may omit its redundant public point. */
export interface EcDerKey {
  readonly namedCurve: CryptoNamedCurve;
  readonly x: Uint8Array | undefined;
  readonly y: Uint8Array | undefined;
  readonly d: Uint8Array | undefined;
}

/**
 * Web Cryptography §§23.7.4–5, 24.4.3–4; RFC 5480 and RFC 5915.
 * Import permits absent inner parameters/publicKey. Export must include both.
 * Native import validates the scalar/point mathematics; shared key policy also
 * compares a supplied public point with the native scalar-derived point.
 */
export function parseEcDer(format: "spki" | "pkcs8", bytes: Uint8Array, requirePrivateFields = false): EcDerKey {
  const source = new DerReader(bytes);
  const envelope = source.read(0x30);
  source.complete();
  if (format === "spki") {
    const namedCurve = ecAlgorithm(envelope);
    const point = ecBitString(envelope, namedCurve);
    envelope.complete();
    return { namedCurve, x: point.x, y: point.y, d: undefined };
  }
  const version = envelope.integer(true);
  if (cryptoViewByteLength(version) !== 1 || version[0] !== 0) invalidDer();
  const namedCurve = ecAlgorithm(envelope);
  const privateOctets = envelope.read(0x04);
  if (!envelope.done()) attributes(envelope);
  envelope.complete();
  const privateKey = privateOctets.read(0x30);
  privateOctets.complete();
  const privateVersion = privateKey.integer();
  if (cryptoViewByteLength(privateVersion) !== 1 || privateVersion[0] !== 1) invalidDer();
  const d = privateKey.read(0x04).content();
  if (cryptoViewByteLength(d) !== ecCurveByteLength(namedCurve)) invalidDer();
  if (!privateKey.done() && privateKey.peek() === 0xa0) {
    const parameters = privateKey.read(0xa0);
    if (ecNamedCurve(parameters) !== namedCurve) invalidDer();
    parameters.complete();
  } else if (requirePrivateFields) invalidDer();
  let x: Uint8Array | undefined;
  let y: Uint8Array | undefined;
  if (!privateKey.done() && privateKey.peek() === 0xa1) {
    const publicKey = privateKey.read(0xa1);
    const point = ecBitString(publicKey, namedCurve);
    publicKey.complete();
    x = point.x;
    y = point.y;
  } else if (requirePrivateFields) invalidDer();
  privateKey.complete();
  return { namedCurve, x, y, d };
}

/** RFC 8410 key encodings retain the public octets without point validation. */
export interface OkpDerKey {
  readonly namedCurve: CryptoOkpCurve;
  readonly x: Uint8Array | undefined;
  readonly d: Uint8Array | undefined;
}

function okpAlgorithm(reader: DerReader): CryptoOkpCurve {
  const algorithm = reader.read(0x30);
  const oid = algorithm.read(0x06).content();
  // RFC 8410 §3 requires absent parameters, including rejecting a NULL value.
  algorithm.complete();
  if (cryptoViewByteLength(oid) !== 3 || oid[0] !== 0x2b || oid[1] !== 0x65) invalidDer();
  if (oid[2] === 0x70) return "Ed25519";
  if (oid[2] === 0x6e) return "X25519";
  if (oid[2] === 0x71) return "Ed448";
  if (oid[2] === 0x6f) return "X448";
  invalidDer();
}

/**
 * Web Cryptography §§25.3.4–5, 26.3.3–4, Secure Curves §§4.3, 6.4 and
 * RFC 8410 §§4, 7. PKCS8 uses RFC 5208 PrivateKeyInfo, not OneAsymmetricKey:
 * version zero, optional attributes, and an exactly consumed CurvePrivateKey.
 * The inner value is the original seed octets, not an ECPrivateKey sequence. Public
 * imports deliberately impose no canonical, on-curve or small-order check.
 */
export function parseOkpDer(format: "spki" | "pkcs8", bytes: Uint8Array): OkpDerKey {
  const source = new DerReader(bytes);
  const envelope = source.read(0x30);
  source.complete();
  if (format === "spki") {
    const namedCurve = okpAlgorithm(envelope);
    const publicKey = envelope.read(0x03);
    if (publicKey.done() || publicKey.bytes[publicKey.position++] !== 0) invalidDer();
    const x = publicKey.content();
    if (cryptoViewByteLength(x) !== okpCurveByteLength(namedCurve)) invalidDer();
    envelope.complete();
    return { namedCurve, x, d: undefined };
  }
  const version = envelope.integer(true);
  if (cryptoViewByteLength(version) !== 1 || version[0] !== 0) invalidDer();
  const namedCurve = okpAlgorithm(envelope);
  const privateOctets = envelope.read(0x04);
  if (!envelope.done()) attributes(envelope);
  envelope.complete();
  const d = privateOctets.read(0x04).content();
  privateOctets.complete();
  if (cryptoViewByteLength(d) !== okpCurveByteLength(namedCurve)) invalidDer();
  return { namedCurve, x: undefined, d };
}

export interface MlDerKey {
  readonly name: CryptoMlAlgorithmName;
  readonly pub: Uint8Array | undefined;
  readonly seed: Uint8Array | undefined;
  readonly expanded: Uint8Array | undefined;
}

function mlAlgorithm(reader: DerReader): CryptoMlAlgorithmName {
  const algorithm = reader.read(0x30);
  const oid = algorithm.read(0x06).content();
  algorithm.complete(); // Parameters must be absent, including NULL.
  const prefix = [0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04];
  if (oid.byteLength !== prefix.length + 2) invalidDer();
  for (let index = 0; index < prefix.length; index++) if (oid[index] !== prefix[index]) invalidDer();
  if (oid[7] === 0x03) {
    if (oid[8] === 17) return "ML-DSA-44";
    if (oid[8] === 18) return "ML-DSA-65";
    if (oid[8] === 19) return "ML-DSA-87";
  } else if (oid[7] === 0x04) {
    if (oid[8] === 1) return "ML-KEM-512";
    if (oid[8] === 2) return "ML-KEM-768";
    if (oid[8] === 3) return "ML-KEM-1024";
  }
  invalidDer();
}

/**
 * Modern Algorithms §§6.4.5, 8.4.4, RFC 9881/9935: validate the original envelope exactly.
 * Seed expansion and validation of the optional expanded material stay native.
 * Expanded-only private keys are valid encodings but outside the seed profile.
 */
export function parseMlDer(format: "spki" | "pkcs8", bytes: Uint8Array): MlDerKey {
  const source = new DerReader(bytes);
  const envelope = source.read(0x30);
  source.complete();
  if (format === "spki") {
    const name = mlAlgorithm(envelope);
    const publicKey = envelope.read(0x03);
    if (publicKey.done() || publicKey.bytes[publicKey.position++] !== 0) invalidDer();
    const pub = publicKey.content();
    if (pub.byteLength !== mlPublicKeyLength(name)) invalidDer();
    envelope.complete();
    return { name, pub, seed: undefined, expanded: undefined };
  }
  const version = envelope.integer(true);
  if (version.byteLength !== 1 || version[0] !== 0) invalidDer();
  const name = mlAlgorithm(envelope);
  const privateOctets = envelope.read(0x04);
  if (!envelope.done()) attributes(envelope);
  envelope.complete();
  let seed: Uint8Array | undefined;
  let expanded: Uint8Array | undefined;
  if (privateOctets.peek() === 0x80) {
    seed = privateOctets.read(0x80).content();
  } else if (privateOctets.peek() === 0x04) {
    expanded = privateOctets.read(0x04).content();
  } else {
    const both = privateOctets.read(0x30);
    seed = both.read(0x04).content();
    expanded = both.read(0x04).content();
    both.complete();
  }
  privateOctets.complete();
  if (seed !== undefined && seed.byteLength !== mlSeedLength(name)) invalidDer();
  if (expanded !== undefined && expanded.byteLength !== mlExpandedKeyLength(name)) invalidDer();
  return { name, pub: undefined, seed, expanded };
}

/**
 * Web Cryptography §§24.4.2 and 26.3.1: retain the requested leading bits and
 * clear the unused low bits of the final octet. Callers validate the length and
 * the native result first. The native secret already owns its exact-size buffer.
 */
export function truncateDerivationBits(secret: Uint8Array, length: number | null): Uint8Array {
  if (length === null || length === secret.byteLength * 8) return secret;
  const remainder = length % 8;
  const byteLength = (length - remainder) / 8 + (remainder === 0 ? 0 : 1);
  const result = new Uint8Array(byteLength);
  for (let index = 0; index < byteLength; index++) result[index] = secret[index]!;
  if (remainder !== 0) result[byteLength - 1]! &= 0xff << (8 - remainder);
  return result;
}

import type { CryptoNamedCurve } from "../provider/crypto.ts";

/** SEC 1 §2.3.5 / RFC 7518 §6.2: field elements occupy the full curve width. */
export function ecCurveByteLength(namedCurve: CryptoNamedCurve): number {
  switch (namedCurve) {
    case "P-256": return 32;
    case "P-384": return 48;
    case "P-521": return 66;
  }
}

import { DOMException } from "../core/errors.ts";
import type { CryptoEcComponents, CryptoKeyRecord, CryptoNamedCurve, CryptoProvider } from "../provider/crypto.ts";
import { EcKeyGenParams, EcKeyImportParams } from "./algorithms.ts";
import type { EcAlgorithmName, NormalizedAlgorithm } from "./algorithms.ts";
import { cryptoViewByteLength } from "./buffer-source.ts";
import { createCryptoKey, KeyAlgorithm } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeyPair, CryptoKeySlots, KeyAlgorithmObject, KeyUsage } from "./crypto-key.ts";
import { parseEcDer, parseEcPoint } from "./der.ts";
import type { EcDerKey } from "./der.ts";
import { ecCurveByteLength } from "./ec-curve.ts";
import { checkJwkPolicy, decodeBase64Url, encodeBase64Url, JsonWebKey, normalizeKeyUsages } from "./jwk.ts";
import type { KeyFormat } from "./jwk.ts";

interface EcKeyAlgorithmObject extends KeyAlgorithmObject {
  namedCurve: CryptoNamedCurve;
}

/** Web Cryptography §23.5: the curve belongs to the key; the signing hash does not. */
export class EcKeyAlgorithm extends KeyAlgorithm {
  readonly namedCurve: CryptoNamedCurve;

  constructor(name: EcAlgorithmName, namedCurve: CryptoNamedCurve) {
    super(name);
    this.namedCurve = namedCurve;
  }

  override copy(): EcKeyAlgorithm {
    return new EcKeyAlgorithm(this.name as EcAlgorithmName, this.namedCurve);
  }

  override toObject(): EcKeyAlgorithmObject {
    return { name: this.name, namedCurve: this.namedCurve };
  }
}

function supportedCurve(namedCurve: string): CryptoNamedCurve {
  if (namedCurve === "P-256" || namedCurve === "P-384" || namedCurve === "P-521") return namedCurve;
  throw new DOMException("This elliptic curve is not supported", "NotSupportedError");
}

function equalBytes(left: Uint8Array, right: Uint8Array): boolean {
  const length = cryptoViewByteLength(left);
  if (length !== cryptoViewByteLength(right)) return false;
  for (let index = 0; index < length; index++) if (left[index] !== right[index]) return false;
  return true;
}

function usageAllowed(name: string, type: "public" | "private" | "pair", usage: KeyUsage): boolean {
  if (name === "ECDH") return type !== "public" && (usage === "deriveKey" || usage === "deriveBits");
  return (type !== "private" && usage === "verify") || (type !== "public" && usage === "sign");
}

function validateUsages(name: string, type: "public" | "private" | "pair", usages: readonly KeyUsage[]): void {
  for (let index = 0; index < usages.length; index++) {
    if (!usageAllowed(name, type, usages[index]!)) {
      throw new DOMException("The requested usage is not supported by this EC key", "SyntaxError");
    }
  }
}

function intersectUsages(name: string, type: "public" | "private", usages: readonly KeyUsage[]): KeyUsage[] {
  const selected: KeyUsage[] = [];
  for (let index = 0; index < usages.length; index++) {
    const usage = usages[index]!;
    if (usageAllowed(name, type, usage)) selected[selected.length] = usage;
  }
  return normalizeKeyUsages(selected);
}

function ecRecord(record: CryptoKeyRecord, type: "public" | "private", namedCurve: CryptoNamedCurve): void {
  const info = record.info;
  if (info.family !== "EC" || info.type !== type || info.namedCurve !== namedCurve) {
    throw new DOMException("The primitive returned inconsistent EC key metadata", "OperationError");
  }
}

/** §§23.7.3, 24.4.1 and §14.3.6's final private-key usage check. */
export function generateEcKey(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKeyPair {
  if (!(algorithm instanceof EcKeyGenParams)) throw new DOMException("Expected EC generation parameters", "NotSupportedError");
  validateUsages(algorithm.name, "pair", usages);
  const namedCurve = supportedCurve(algorithm.namedCurve);
  const pair = provider.generateKeyPair({ family: "EC", namedCurve });
  if ("failure" in pair) throw new DOMException("EC key generation failed", "OperationError");
  ecRecord(pair.publicKey, "public", namedCurve);
  ecRecord(pair.privateKey, "private", namedCurve);
  const privateUsages = intersectUsages(algorithm.name, "private", usages);
  if (privateUsages.length === 0) throw new DOMException("A private key must have at least one usage", "SyntaxError");
  const keyAlgorithm = new EcKeyAlgorithm(algorithm.name, namedCurve);
  const publicKey = createCryptoKey("public", true, keyAlgorithm, intersectUsages(algorithm.name, "public", usages), pair.publicKey.handle);
  const privateKey = createCryptoKey("private", extractable, keyAlgorithm, privateUsages, pair.privateKey.handle);
  return { privateKey, publicKey };
}

/** RFC 7517 §4.3: unknown operations are permitted; duplicate/inconsistent ones are not. */
function jwkPolicy(jwk: JsonWebKey, name: EcAlgorithmName, namedCurve: CryptoNamedCurve, extractable: boolean, usages: readonly KeyUsage[]): void {
  if (jwk.kty !== "EC") throw new DOMException("The JWK is not an EC key", "DataError");
  checkJwkPolicy(jwk, name === "ECDSA" ? "sig" : "enc", extractable, usages);
  if (jwk.crv !== namedCurve) throw new DOMException("The JWK curve does not match the requested curve", "DataError");
  // ECDSA binds alg to the curve; ECDH has no corresponding alg restriction.
  if (name === "ECDSA" && jwk.alg !== undefined) {
    const expected = namedCurve === "P-256" ? "ES256" : namedCurve === "P-384" ? "ES384" : "ES512";
    if (jwk.alg !== expected) throw new DOMException("The JWK algorithm does not match its curve", "DataError");
  }
}

function jwkOctets(value: string | undefined, namedCurve: CryptoNamedCurve): Uint8Array {
  if (value === undefined) throw new DOMException("An EC JWK component is missing", "DataError");
  const bytes = decodeBase64Url(value);
  if (cryptoViewByteLength(bytes) !== ecCurveByteLength(namedCurve)) {
    throw new DOMException("An EC JWK component has the wrong width", "DataError");
  }
  return bytes;
}

function jwkComponents(jwk: JsonWebKey, namedCurve: CryptoNamedCurve): CryptoEcComponents {
  const x = jwkOctets(jwk.x, namedCurve);
  const y = jwkOctets(jwk.y, namedCurve);
  return jwk.d === undefined ? { family: "EC", namedCurve, x, y }
    : { family: "EC", namedCurve, x, y, d: jwkOctets(jwk.d, namedCurve) };
}

function componentWidths(components: CryptoEcComponents, namedCurve: CryptoNamedCurve, privateKey: boolean): void {
  const width = ecCurveByteLength(namedCurve);
  if (components.namedCurve !== namedCurve || cryptoViewByteLength(components.x) !== width
      || cryptoViewByteLength(components.y) !== width
      || (privateKey && (components.d === undefined || cryptoViewByteLength(components.d) !== width))) {
    throw new DOMException("The native EC components do not match their key", "OperationError");
  }
}

function privatePointMatches(provider: CryptoProvider, record: CryptoKeyRecord, encoded: EcDerKey | CryptoEcComponents): void {
  if (encoded.d === undefined || encoded.x === undefined || encoded.y === undefined) return;
  // Import obtains a mathematical private key. A supplied public point remains
  // format policy: compare it with the point native code computes from d.
  const actual = provider.exportComponents(record.handle);
  if ("failure" in actual || actual.family !== "EC") throw new DOMException("The EC private key cannot be inspected", "OperationError");
  componentWidths(actual, encoded.namedCurve, true);
  if (actual.d === undefined || !equalBytes(actual.d, encoded.d)) {
    throw new DOMException("The primitive changed the EC private scalar", "OperationError");
  }
  if (!equalBytes(actual.x, encoded.x) || !equalBytes(actual.y, encoded.y)) {
    throw new DOMException("The EC public point does not match its private scalar", "DataError");
  }
}

/** §§23.7.4 and 24.4.3: original encodings are validated before native import. */
export function importEcKey(
  provider: CryptoProvider,
  format: KeyFormat,
  data: Uint8Array | JsonWebKey,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKey {
  if (!(algorithm instanceof EcKeyImportParams)) throw new DOMException("Expected EC import parameters", "NotSupportedError");
  const namedCurve = supportedCurve(algorithm.namedCurve);
  if (format === "raw-secret") throw new DOMException("This asymmetric key format is not supported", "NotSupportedError");
  let type: "public" | "private";
  let encoded: EcDerKey | CryptoEcComponents;
  if (format === "jwk") {
    if (!(data instanceof JsonWebKey)) throw new DOMException("Expected an EC JWK", "DataError");
    type = data.d === undefined ? "public" : "private";
    validateUsages(algorithm.name, type, usages);
    jwkPolicy(data, algorithm.name, namedCurve, extractable, usages);
    encoded = jwkComponents(data, namedCurve);
  } else {
    if (format !== "pkcs8" && format !== "spki" && format !== "raw") throw new DOMException("The key format is not supported", "NotSupportedError");
    type = format === "pkcs8" ? "private" : "public";
    validateUsages(algorithm.name, type, usages);
    if (data instanceof JsonWebKey) throw new DOMException("Expected EC key bytes", "DataError");
    encoded = format === "raw" ? parseEcPoint(data, namedCurve) : parseEcDer(format, data);
    if (encoded.namedCurve !== namedCurve) throw new DOMException("The encoded EC curve does not match the requested curve", "DataError");
  }
  const record = provider.importKey(format === "jwk"
    ? { format: "components", components: encoded as CryptoEcComponents }
    : format === "raw" ? { format, family: "EC", namedCurve, bytes: data as Uint8Array }
      : { format, bytes: data as Uint8Array });
  if ("failure" in record) {
    throw new DOMException("The EC key could not be imported", record.failure === "invalid-key" ? "DataError" : "OperationError");
  }
  ecRecord(record, type, namedCurve);
  privatePointMatches(provider, record, encoded);
  if (type === "private" && usages.length === 0) throw new DOMException("A private key must have at least one usage", "SyntaxError");
  return createCryptoKey(type, extractable, new EcKeyAlgorithm(algorithm.name, namedCurve), normalizeKeyUsages(usages), record.handle);
}

function exportJwk(components: CryptoEcComponents, key: CryptoKeySlots): JsonWebKey {
  const algorithm = key.algorithm as EcKeyAlgorithm;
  componentWidths(components, algorithm.namedCurve, key.type === "private");
  const jwk = new JsonWebKey();
  jwk.kty = "EC";
  jwk.crv = algorithm.namedCurve;
  jwk.x = encodeBase64Url(components.x);
  jwk.y = encodeBase64Url(components.y);
  if (key.type === "private") jwk.d = encodeBase64Url(components.d!);
  jwk.key_ops = [];
  for (let index = 0; index < key.usages.length; index++) jwk.key_ops[index] = key.usages[index]!;
  jwk.ext = key.extractable;
  return jwk;
}

/** §§23.7.5 and 24.4.4: material access precedes format/type checks. */
export function exportEcKey(provider: CryptoProvider, format: KeyFormat, key: CryptoKeySlots): Uint8Array | JsonWebKey {
  const algorithm = key.algorithm as EcKeyAlgorithm;
  if (format === "jwk") {
    const components = provider.exportComponents(key.handle);
    if ("failure" in components || components.family !== "EC") throw new DOMException("The EC key cannot be exported", "OperationError");
    return exportJwk(components, key);
  }
  const unsupported = format !== "raw" && format !== "spki" && format !== "pkcs8";
  const nativeFormat = key.type === "private" ? "pkcs8" : format === "raw" ? "raw" : "spki";
  const result = provider.exportKey(key.handle, nativeFormat);
  if ("failure" in result) throw new DOMException("The EC key cannot be exported", "OperationError");
  if (unsupported) throw new DOMException("The key format is not supported", "NotSupportedError");
  if (format !== nativeFormat) throw new DOMException("The EC key type does not match the export format", "InvalidAccessError");
  try {
    const encoded = format === "raw" ? parseEcPoint(result, algorithm.namedCurve) : parseEcDer(format, result, true);
    if (encoded.namedCurve !== algorithm.namedCurve) throw new DOMException("The native EC encoding has the wrong curve", "OperationError");
  } catch {
    throw new DOMException("The native EC key encoding is invalid", "OperationError");
  }
  return result;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoProvider } from "../provider/crypto.ts";
import type { EcdhKeyDeriveParams, EcdsaParams, NormalizedAlgorithm } from "./algorithms.ts";
import { cryptoByteSubarray } from "./buffer-source.ts";
import { getCryptoKeySlots } from "./crypto-key.ts";
import type { CryptoKeySlots } from "./crypto-key.ts";
import { truncateDerivationBits } from "./derive-bits.ts";
import { ecCurveByteLength } from "./ec-curve.ts";
import type { EcKeyAlgorithm } from "./ec-key.ts";


function operationError(): DOMException {
  return new DOMException("The elliptic-curve operation failed", "OperationError");
}

function requireKeyType(key: CryptoKeySlots, type: "public" | "private"): void {
  if (key.type !== type) throw new DOMException("The operation requires a " + type + " key", "InvalidAccessError");
}

/**
 * Web Cryptography §23.7.1: hashing and ECDSA are one native operation. Shared
 * code encodes the native integers as fixed-width r || s, never ASN.1 DER.
 * https://w3c.github.io/webcrypto/#ecdsa-operations-sign
 */
export function signEc(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  bytes: Uint8Array,
): Uint8Array {
  requireKeyType(key, "private");
  const width = ecCurveByteLength((key.algorithm as EcKeyAlgorithm).namedCurve);
  const signature = provider.sign({ name: "ECDSA", hash: (algorithm as EcdsaParams).hash.name }, key.handle, bytes);
  if ("failure" in signature || signature.kind !== "ecdsa") throw operationError();
  const rLength = signature.r.byteLength;
  const sLength = signature.s.byteLength;
  if (rLength === 0 || rLength > width || sLength === 0 || sLength > width) throw operationError();
  const result = new Uint8Array(width * 2);
  for (let index = 0; index < rLength; index++) result[width - rLength + index] = signature.r[index]!;
  for (let index = 0; index < sLength; index++) result[width * 2 - sLength + index] = signature.s[index]!;
  return result;
}

/** §23.7.2: incorrect encoding width is false; native verification checks r/s. */
export function verifyEc(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  signature: Uint8Array,
  bytes: Uint8Array,
): boolean {
  requireKeyType(key, "public");
  const width = ecCurveByteLength((key.algorithm as EcKeyAlgorithm).namedCurve);
  if (signature.byteLength !== width * 2) return false;
  const result = provider.verify(
    { name: "ECDSA", hash: (algorithm as EcdsaParams).hash.name },
    key.handle,
    { kind: "ecdsa", r: cryptoByteSubarray(signature, 0, width), s: cryptoByteSubarray(signature, width, width * 2) },
    bytes,
  );
  if (typeof result !== "boolean") throw new DOMException("The verification operation failed", "OperationError");
  return result;
}

/**
 * Web Cryptography §24.4.2. Maximum output length is the peer curve's field
 * element octet encoding (528 bits for P-521), checked before the base key type.
 * A single native ECDH operation returns the complete secret; truncation keeps
 * the requested leading bits and clears the unused low bits of the last octet.
 * https://w3c.github.io/webcrypto/#ecdh-operations-derive-bits
 */
export function deriveEcBits(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  length: number | null,
): Uint8Array {
  const publicKey = getCryptoKeySlots((algorithm as EcdhKeyDeriveParams).public);
  requireKeyType(publicKey, "public");
  if (publicKey.algorithm.name !== algorithm.name) {
    throw new DOMException("The peer key algorithm does not match ECDH", "InvalidAccessError");
  }
  const publicAlgorithm = publicKey.algorithm as EcKeyAlgorithm;
  const width = ecCurveByteLength(publicAlgorithm.namedCurve);
  if (length !== null && length > width * 8) throw operationError();
  requireKeyType(key, "private");
  if (publicKey.algorithm.name !== key.algorithm.name || publicAlgorithm.namedCurve !== (key.algorithm as EcKeyAlgorithm).namedCurve) {
    throw new DOMException("The ECDH keys must use the same algorithm and curve", "InvalidAccessError");
  }
  const secret = provider.derive({ name: "ECDH", publicKey: publicKey.handle }, key.handle);
  if ("failure" in secret || secret.byteLength !== width) throw operationError();
  return truncateDerivationBits(secret, length);
}

import { DOMException } from "../core/errors.ts";
import { utf8Decode } from "../core/utf8.ts";
import { coerceToDOMString, requireDictionary } from "../core/webidl.ts";
import { parseJsonText } from "../json/parse.ts";
import type { JsonValue } from "../json/value.ts";
import { cryptoViewByteLength } from "./buffer-source.ts";
import type { KeyUsage } from "./crypto-key.ts";

export type KeyFormat = "raw-public" | "raw-private" | "raw-seed" | "raw-secret" | "raw" | "spki" | "pkcs8" | "jwk";

/** Web Cryptography §15. Fields are optional; algorithms check required members. */
export class RsaOtherPrimesInfo {
  d: string | undefined;
  r: string | undefined;
  t: string | undefined;
}

export class JsonWebKey {
  alg: string | undefined;
  crv: string | undefined;
  d: string | undefined;
  dp: string | undefined;
  dq: string | undefined;
  e: string | undefined;
  ext: boolean | undefined;
  k: string | undefined;
  key_ops: string[] | undefined;
  kty: string | undefined;
  n: string | undefined;
  oth: RsaOtherPrimesInfo[] | undefined;
  p: string | undefined;
  priv: string | undefined;
  pub: string | undefined;
  q: string | undefined;
  qi: string | undefined;
  use: string | undefined;
  x: string | undefined;
  y: string | undefined;
}

/**
 * RFC 7517 §§4.2–4.3 and Web Cryptography's shared JWK usage/extractability
 * checks. Algorithms call this at their specified step, between their own
 * key-type, algorithm-identifier and component checks.
 */
export function checkJwkPolicy(jwk: JsonWebKey, expectedUse: "sig" | "enc", extractable: boolean, usages: readonly KeyUsage[]): void {
  if (usages.length !== 0 && jwk.use !== undefined && jwk.use !== expectedUse) {
    throw new DOMException("The JWK use does not permit this operation", "DataError");
  }
  const operations = jwk.key_ops;
  if (operations !== undefined) {
    for (let index = 0; index < operations.length; index++) {
      const operation = operations[index]!;
      for (let earlier = 0; earlier < index; earlier++) {
        if (operations[earlier] === operation) throw new DOMException("The JWK key_ops contains duplicates", "DataError");
      }
      const signing = operation === "sign" || operation === "verify";
      const encryption = operation === "encrypt" || operation === "decrypt" || operation === "wrapKey"
        || operation === "unwrapKey" || operation === "deriveKey" || operation === "deriveBits"
        || operation === "encapsulateKey" || operation === "encapsulateBits"
        || operation === "decapsulateKey" || operation === "decapsulateBits";
      if ((jwk.use === "sig" && encryption) || (jwk.use === "enc" && signing)) {
        throw new DOMException("The JWK use and key_ops are inconsistent", "DataError");
      }
    }
    for (let index = 0; index < usages.length; index++) {
      let present = false;
      for (let at = 0; at < operations.length; at++) if (operations[at] === usages[index]) present = true;
      if (!present) throw new DOMException("The JWK does not permit every requested usage", "DataError");
    }
  }
  if (jwk.ext === false && extractable) throw new DOMException("The JWK is not extractable", "DataError");
}

export interface RsaOtherPrimesInfoObject {
  d?: string;
  r?: string;
  t?: string;
}

/** A fresh ordinary object returned by exportKey, without internal aliases. */
export interface JsonWebKeyObject {
  alg?: string;
  crv?: string;
  d?: string;
  dp?: string;
  dq?: string;
  e?: string;
  ext?: boolean;
  k?: string;
  key_ops?: string[];
  kty?: string;
  n?: string;
  oth?: RsaOtherPrimesInfoObject[];
  p?: string;
  priv?: string;
  pub?: string;
  q?: string;
  qi?: string;
  use?: string;
  x?: string;
  y?: string;
}

interface JsonWebKeyInput {
  readonly alg?: unknown;
  readonly crv?: unknown;
  readonly d?: unknown;
  readonly dp?: unknown;
  readonly dq?: unknown;
  readonly e?: unknown;
  readonly ext?: unknown;
  readonly k?: unknown;
  readonly key_ops?: unknown;
  readonly kty?: unknown;
  readonly n?: unknown;
  readonly oth?: unknown;
  readonly p?: unknown;
  readonly priv?: unknown;
  readonly pub?: unknown;
  readonly q?: unknown;
  readonly qi?: unknown;
  readonly use?: unknown;
  readonly x?: unknown;
  readonly y?: unknown;
}

const base64url = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
const hexadecimal = "0123456789abcdef";
const usageOrder: readonly KeyUsage[] = [
  "encrypt", "decrypt", "sign", "verify", "deriveKey", "deriveBits", "wrapKey", "unwrapKey",
  "encapsulateKey", "encapsulateBits", "decapsulateKey", "decapsulateBits",
];

function append<T>(values: T[], value: T): void {
  values.push(value);
}

function codeUnit(value: string, index: number): number {
  return value.charCodeAt(index);
}

function isObject(value: unknown): value is object {
  return (typeof value === "object" && value !== null) || typeof value === "function";
}

/** Web IDL sequence conversion captures next once and does not IteratorClose. */
function sequence<T>(value: unknown, convert: (item: unknown) => T): T[] {
  if (!isObject(value)) throw new TypeError("A sequence must be an iterable object");
  const method = (value as { readonly [Symbol.iterator]?: unknown })[Symbol.iterator];
  if (typeof method !== "function") throw new TypeError("A sequence must be iterable");
  const iterator = method.call(value);
  if (!isObject(iterator)) throw new TypeError("The iterator must be an object");
  const next = (iterator as { readonly next?: unknown }).next;
  if (typeof next !== "function") throw new TypeError("The iterator next must be callable");
  const result: T[] = [];
  for (;;) {
    const step = next.call(iterator);
    if (!isObject(step)) throw new TypeError("An iterator result must be an object");
    if ((step as { readonly done?: unknown }).done) return result;
    const item = (step as { readonly value?: unknown }).value;
    append(result, convert(item));
  }
}

function optionalString(value: unknown): string | undefined {
  return value === undefined ? undefined : coerceToDOMString(value);
}

function otherPrime(value: unknown): RsaOtherPrimesInfo {
  requireDictionary(value, "RsaOtherPrimesInfo");
  const result = new RsaOtherPrimesInfo();
  if (value === null || value === undefined) return result;
  const source = value as { readonly d?: unknown; readonly r?: unknown; readonly t?: unknown };
  result.d = optionalString(source.d);
  result.r = optionalString(source.r);
  result.t = optionalString(source.t);
  return result;
}

/** Convert every declared member in Web IDL's lexicographic order, once each. */
export function toJsonWebKey(value: unknown): JsonWebKey {
  requireDictionary(value, "JsonWebKey");
  const result = new JsonWebKey();
  if (value === null || value === undefined) return result;
  const source = value as JsonWebKeyInput;
  result.alg = optionalString(source.alg);
  result.crv = optionalString(source.crv);
  result.d = optionalString(source.d);
  result.dp = optionalString(source.dp);
  result.dq = optionalString(source.dq);
  result.e = optionalString(source.e);
  const extractable = source.ext;
  if (extractable !== undefined) result.ext = !!extractable;
  result.k = optionalString(source.k);
  const operations = source.key_ops;
  if (operations !== undefined) result.key_ops = sequence(operations, coerceToDOMString);
  result.kty = optionalString(source.kty);
  result.n = optionalString(source.n);
  const primes = source.oth;
  if (primes !== undefined) result.oth = sequence(primes, otherPrime);
  result.p = optionalString(source.p);
  result.priv = optionalString(source.priv);
  result.pub = optionalString(source.pub);
  result.q = optionalString(source.q);
  result.qi = optionalString(source.qi);
  result.use = optionalString(source.use);
  result.x = optionalString(source.x);
  result.y = optionalString(source.y);
  return result;
}

export function toJsonWebKeyObject(key: JsonWebKey): JsonWebKeyObject {
  let operations: string[] | undefined;
  if (key.key_ops !== undefined) {
    operations = [];
    for (let index = 0; index < key.key_ops.length; index++) append(operations, key.key_ops[index]!);
  }
  // Exported symmetric keys take the ordinary-object literal path. Literals
  // create own data properties without consulting inherited field setters.
  if (key.kty === "oct" && key.alg !== undefined && key.ext !== undefined &&
      key.k !== undefined && operations !== undefined && key.crv === undefined &&
      key.d === undefined && key.dp === undefined && key.dq === undefined &&
      key.e === undefined && key.n === undefined && key.oth === undefined &&
      key.p === undefined && key.priv === undefined && key.pub === undefined && key.q === undefined && key.qi === undefined &&
      key.use === undefined && key.x === undefined && key.y === undefined) {
    return { alg: key.alg, ext: key.ext, k: key.k, key_ops: operations, kty: key.kty };
  }
  let primes: RsaOtherPrimesInfoObject[] | undefined;
  if (key.oth !== undefined) {
    primes = [];
    for (let index = 0; index < key.oth.length; index++) {
      const prime = key.oth[index]!;
      const copy: RsaOtherPrimesInfoObject = { d: prime.d, r: prime.r, t: prime.t };
      if (copy.d === undefined) delete copy.d;
      if (copy.r === undefined) delete copy.r;
      if (copy.t === undefined) delete copy.t;
      append(primes, copy);
    }
  }
  const result: JsonWebKeyObject = {
    alg: key.alg, crv: key.crv, d: key.d, dp: key.dp, dq: key.dq, e: key.e,
    ext: key.ext, k: key.k, key_ops: operations, kty: key.kty, n: key.n, oth: primes,
    p: key.p, priv: key.priv, pub: key.pub, q: key.q, qi: key.qi, use: key.use, x: key.x, y: key.y,
  };
  if (result.alg === undefined) delete result.alg;
  if (result.crv === undefined) delete result.crv;
  if (result.d === undefined) delete result.d;
  if (result.dp === undefined) delete result.dp;
  if (result.dq === undefined) delete result.dq;
  if (result.e === undefined) delete result.e;
  if (result.ext === undefined) delete result.ext;
  if (result.k === undefined) delete result.k;
  if (result.key_ops === undefined) delete result.key_ops;
  if (result.kty === undefined) delete result.kty;
  if (result.n === undefined) delete result.n;
  if (result.oth === undefined) delete result.oth;
  if (result.p === undefined) delete result.p;
  if (result.priv === undefined) delete result.priv;
  if (result.pub === undefined) delete result.pub;
  if (result.q === undefined) delete result.q;
  if (result.qi === undefined) delete result.qi;
  if (result.use === undefined) delete result.use;
  if (result.x === undefined) delete result.x;
  if (result.y === undefined) delete result.y;
  return result;
}

export function toKeyFormat(value: unknown): KeyFormat {
  const format = coerceToDOMString(value);
  if (format === "raw-public" || format === "raw-private" || format === "raw-seed" || format === "raw-secret" || format === "raw" || format === "spki" || format === "pkcs8" || format === "jwk") return format;
  throw new TypeError("Unknown key format");
}

function keyUsage(value: unknown): KeyUsage {
  const usage = coerceToDOMString(value);
  for (let index = 0; index < usageOrder.length; index++) {
    if (usage === usageOrder[index]) return usageOrder[index]!;
  }
  throw new TypeError("Unknown key usage");
}

export function toKeyUsages(value: unknown): KeyUsage[] {
  return sequence(value, keyUsage);
}

/** §9 usage normalization: remove duplicates and use the enum's defined order. */
export function normalizeKeyUsages(usages: readonly KeyUsage[]): KeyUsage[] {
  const result: KeyUsage[] = [];
  for (let order = 0; order < usageOrder.length; order++) {
    const usage = usageOrder[order]!;
    for (let index = 0; index < usages.length; index++) {
      if (usages[index] === usage) {
        append(result, usage);
        break;
      }
    }
  }
  return result;
}

function base64Digit(code: number): number {
  if (code >= 65 && code <= 90) return code - 65;
  if (code >= 97 && code <= 122) return code - 97 + 26;
  if (code >= 48 && code <= 57) return code - 48 + 52;
  if (code === 45) return 62;
  if (code === 95) return 63;
  return -1;
}

/** RFC 7515 §2: URL alphabet, no padding or whitespace. */
export function decodeBase64Url(value: string): Uint8Array {
  if (value.length % 4 === 1) throw new DOMException("Invalid base64url length", "DataError");
  const result = new Uint8Array(Math.floor(value.length * 6 / 8));
  let accumulator = 0;
  let bits = 0;
  let output = 0;
  for (let index = 0; index < value.length; index++) {
    const digit = base64Digit(codeUnit(value, index));
    if (digit < 0) throw new DOMException("Invalid base64url character", "DataError");
    accumulator = (accumulator << 6) | digit;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      result[output++] = (accumulator >>> bits) & 255;
    }
  }
  // RFC 4648 §3.5 permits, but does not require, rejecting nonzero unused pad
  // bits. JWK imposes no stricter decoding requirement; exporters are canonical.
  return result;
}

export function encodeBase64Url(bytes: Uint8Array): string {
  let result = "";
  const length = cryptoViewByteLength(bytes);
  for (let index = 0; index < length; index += 3) {
    const a = bytes[index]!;
    const b = index + 1 < length ? bytes[index + 1]! : 0;
    const c = index + 2 < length ? bytes[index + 2]! : 0;
    result += base64url[a >>> 2]! + base64url[((a & 3) << 4) | (b >>> 4)]!;
    if (index + 1 < length) result += base64url[((b & 15) << 2) | (c >>> 6)]!;
    if (index + 2 < length) result += base64url[c & 63]!;
  }
  return result;
}

function member(node: JsonValue, name: string): JsonValue | undefined {
  if (node.kind !== "object") return undefined;
  for (let index = 0; index < node.keys.length; index++) {
    if (node.keys[index] === name) return node.values[index];
  }
  return undefined;
}

function jsonScalarString(node: JsonValue): string {
  switch (node.kind) {
    case "null": return "null";
    case "boolean": return node.boolean ? "true" : "false";
    case "number": return coerceToDOMString(node.number);
    case "string": return node.text;
    case "object":
      // JSON cannot contain a callable own toString. Without one, a clean
      // realm's ordinary Object.prototype.toString returns this built-in tag.
      if (member(node, "toString") !== undefined) throw new TypeError("Cannot convert object to string");
      return "[object Object]";
    default: throw new TypeError("Unexpected JSON value for scalar conversion");
  }
}

class JsonArrayStringFrame {
  readonly node: JsonValue;
  index: number;

  constructor(node: JsonValue) {
    this.node = node;
    this.index = 0;
  }
}

/** DOMString conversion as if JSON.parse had created values in a fresh realm. */
function jsonString(node: JsonValue): string {
  if (node.kind !== "array") return jsonScalarString(node);
  let result = "";
  const frames: JsonArrayStringFrame[] = [new JsonArrayStringFrame(node)];
  while (frames.length !== 0) {
    const frame = frames[frames.length - 1]!;
    if (frame.index === frame.node.items.length) {
      frames.length--;
      continue;
    }
    if (frame.index !== 0) result += ",";
    const item = frame.node.items[frame.index++]!;
    if (item.kind === "null") continue;
    if (item.kind === "array") append(frames, new JsonArrayStringFrame(item));
    else result += jsonScalarString(item);
  }
  return result;
}

function optionalJsonString(node: JsonValue | undefined): string | undefined {
  return node === undefined ? undefined : jsonString(node);
}

function jsonBoolean(node: JsonValue): boolean {
  switch (node.kind) {
    case "null": return false;
    case "boolean": return node.boolean;
    case "number": return node.number !== 0;
    case "string": return node.text.length !== 0;
    case "array":
    case "object": return true;
    default: throw new TypeError("Unexpected JSON value for boolean conversion");
  }
}

function jsonDictionary(node: JsonValue): void {
  if (node.kind !== "object" && node.kind !== "array" && node.kind !== "null") {
    throw new TypeError("JSON value cannot be converted to a dictionary");
  }
}

function jsonOtherPrime(node: JsonValue): RsaOtherPrimesInfo {
  jsonDictionary(node);
  const result = new RsaOtherPrimesInfo();
  result.d = optionalJsonString(member(node, "d"));
  result.r = optionalJsonString(member(node, "r"));
  result.t = optionalJsonString(member(node, "t"));
  return result;
}

/** §9 parse a JWK: UTF-8 decode, fresh-realm JSON parsing, then IDL conversion. */
export function parseWrappedJwk(bytes: Uint8Array): JsonWebKey {
  let text = utf8Decode(bytes, 0, cryptoViewByteLength(bytes));
  if (codeUnit(text, 0) === 0xfeff) text = text.slice(1);
  const node = parseJsonText(text);
  jsonDictionary(node);
  const result = new JsonWebKey();
  result.alg = optionalJsonString(member(node, "alg"));
  result.crv = optionalJsonString(member(node, "crv"));
  result.d = optionalJsonString(member(node, "d"));
  result.dp = optionalJsonString(member(node, "dp"));
  result.dq = optionalJsonString(member(node, "dq"));
  result.e = optionalJsonString(member(node, "e"));
  const extractable = member(node, "ext");
  if (extractable !== undefined) result.ext = jsonBoolean(extractable);
  result.k = optionalJsonString(member(node, "k"));
  const operations = member(node, "key_ops");
  if (operations !== undefined) {
    if (operations.kind !== "array") throw new TypeError("key_ops must be a sequence");
    const usages: string[] = [];
    for (let index = 0; index < operations.items.length; index++) append(usages, jsonString(operations.items[index]!));
    result.key_ops = usages;
  }
  result.kty = optionalJsonString(member(node, "kty"));
  result.n = optionalJsonString(member(node, "n"));
  const primes = member(node, "oth");
  if (primes !== undefined) {
    if (primes.kind !== "array") throw new TypeError("oth must be a sequence");
    const others: RsaOtherPrimesInfo[] = [];
    for (let index = 0; index < primes.items.length; index++) append(others, jsonOtherPrime(primes.items[index]!));
    result.oth = others;
  }
  result.p = optionalJsonString(member(node, "p"));
  result.priv = optionalJsonString(member(node, "priv"));
  result.pub = optionalJsonString(member(node, "pub"));
  result.q = optionalJsonString(member(node, "q"));
  result.qi = optionalJsonString(member(node, "qi"));
  result.use = optionalJsonString(member(node, "use"));
  result.x = optionalJsonString(member(node, "x"));
  result.y = optionalJsonString(member(node, "y"));
  if (result.kty === undefined) throw new DOMException("The JWK has no kty member", "DataError");
  return result;
}

function quoteAscii(value: string): string {
  let result = '"';
  for (let index = 0; index < value.length; index++) {
    const code = codeUnit(value, index);
    if (code === 34) result += '\\"';
    else if (code === 92) result += "\\\\";
    else if (code === 8) result += "\\b";
    else if (code === 9) result += "\\t";
    else if (code === 10) result += "\\n";
    else if (code === 12) result += "\\f";
    else if (code === 13) result += "\\r";
    else if (code < 32 || code > 126) {
      result += "\\u" + hexadecimal[code >>> 12]! + hexadecimal[(code >>> 8) & 15]!
        + hexadecimal[(code >>> 4) & 15]! + hexadecimal[code & 15]!;
    } else result += value[index];
  }
  return result + '"';
}

function stringJsonMember(text: string, name: string, value: string | undefined): string {
  if (value === undefined) return text;
  return text + (text.length === 1 ? "" : ",") + '"' + name + '":' + quoteAscii(value);
}

/** Serialize a generated key dictionary without observable toJSON/prototype hooks. */
export function serializeWrappedJwk(key: JsonWebKey, padToEight: boolean): Uint8Array {
  if ((key.kty !== "oct" || key.k === undefined) &&
      (key.kty !== "RSA" || key.n === undefined || key.e === undefined) &&
      (key.kty !== "EC" || key.crv === undefined || key.x === undefined || key.y === undefined) &&
      (key.kty !== "OKP" || key.crv === undefined || key.x === undefined) &&
      (key.kty !== "AKP" || key.alg === undefined || key.pub === undefined)) {
    throw new TypeError("Expected an exported octet, RSA, EC, OKP or AKP JWK");
  }
  // Match dictionary-to-object's lexicographic member order. These are internal
  // typed dictionaries from export, so no caller-owned toJSON, replacer, prototype
  // or stringifier callback can run while wrapping parameters remain borrowed.
  let text = "{";
  text = stringJsonMember(text, "alg", key.alg);
  text = stringJsonMember(text, "crv", key.crv);
  text = stringJsonMember(text, "d", key.d);
  text = stringJsonMember(text, "dp", key.dp);
  text = stringJsonMember(text, "dq", key.dq);
  text = stringJsonMember(text, "e", key.e);
  if (key.ext !== undefined) text += (text.length === 1 ? "" : ",") + '"ext":' + (key.ext ? "true" : "false");
  text = stringJsonMember(text, "k", key.k);
  if (key.key_ops !== undefined) {
    text += (text.length === 1 ? "" : ",") + '"key_ops":[';
    for (let index = 0; index < key.key_ops.length; index++) {
      if (index !== 0) text += ",";
      text += quoteAscii(key.key_ops[index]!);
    }
    text += "]";
  }
  text = stringJsonMember(text, "kty", key.kty);
  text = stringJsonMember(text, "n", key.n);
  if (key.oth !== undefined) {
    text += (text.length === 1 ? "" : ",") + '"oth":[';
    for (let index = 0; index < key.oth.length; index++) {
      if (index !== 0) text += ",";
      const prime = key.oth[index]!;
      let object = "{";
      object = stringJsonMember(object, "d", prime.d);
      object = stringJsonMember(object, "r", prime.r);
      object = stringJsonMember(object, "t", prime.t);
      text += object + "}";
    }
    text += "]";
  }
  text = stringJsonMember(text, "p", key.p);
  text = stringJsonMember(text, "priv", key.priv);
  text = stringJsonMember(text, "pub", key.pub);
  text = stringJsonMember(text, "q", key.q);
  text = stringJsonMember(text, "qi", key.qi);
  text = stringJsonMember(text, "use", key.use);
  text = stringJsonMember(text, "x", key.x);
  text = stringJsonMember(text, "y", key.y);
  text += "}";
  // §14.3.11 expressly permits adapting JWK serialization to AES-KW's size.
  if (padToEight) while (text.length % 8 !== 0) text += " ";
  const result = new Uint8Array(text.length);
  for (let index = 0; index < text.length; index++) result[index] = codeUnit(text, index);
  return result;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoArgon2Parameters, CryptoHkdfParameters, CryptoPbkdf2Parameters, CryptoProvider } from "../provider/crypto.ts";
import { Argon2Params, HkdfParams, Pbkdf2Params } from "./algorithms.ts";
import type { NormalizedAlgorithm } from "./algorithms.ts";
import { createCryptoKey, KeyAlgorithm } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeySlots, KeyUsage } from "./crypto-key.ts";
import { JsonWebKey, normalizeKeyUsages } from "./jwk.ts";
import type { KeyFormat } from "./jwk.ts";


function operationError(): DOMException {
  return new DOMException("The key derivation operation failed", "OperationError");
}

/**
 * Web Cryptography §§33.4.2 and 34.4.2 and Modern Algorithms §17.4.2.
 * KDF material is raw, nonextractable
 * secret bytes; unlike HMAC it may be empty and has no visible length or hash.
 * https://w3c.github.io/webcrypto/#hkdf-operations-import-key
 * https://w3c.github.io/webcrypto/#pbkdf2-operations-import-key
 * https://wicg.github.io/webcrypto-modern-algos/#argon2-operations-import-key
 */
export function importKdfKey(
  provider: CryptoProvider,
  format: KeyFormat,
  data: Uint8Array | JsonWebKey,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKey {
  const argon2 = algorithm.name === "Argon2d" || algorithm.name === "Argon2i" || algorithm.name === "Argon2id";
  // Modern Algorithms §17.4.2 has no legacy raw alias for Argon2 material.
  if (format !== "raw-secret" && (format !== "raw" || argon2)) {
    throw new DOMException("The key format is not supported for this KDF", "NotSupportedError");
  }
  for (let index = 0; index < usages.length; index++) {
    if (usages[index] !== "deriveKey" && usages[index] !== "deriveBits") {
      throw new DOMException("A KDF key can only derive keys or bits", "SyntaxError");
    }
  }
  if (extractable) throw new DOMException("A KDF key cannot be extractable", "SyntaxError");
  if (data instanceof JsonWebKey) throw new DOMException("Expected raw key bytes", "DataError");
  const bitLength = data.byteLength * 8;
  const record = provider.importKey({ format: "raw", family: "secret", bytes: data });
  if ("failure" in record) {
    throw new DOMException("The KDF key could not be imported", record.failure === "invalid-key" ? "DataError" : "OperationError");
  }
  if (record.info.family !== "secret" || record.info.type !== "secret" || record.info.length !== bitLength) {
    throw new DOMException("The primitive returned inconsistent secret-key metadata", "OperationError");
  }
  // The common import/unwrap steps reject empty secret-key usages only after the
  // algorithm has produced the key; native failures retain their precedence.
  if (usages.length === 0) throw new DOMException("A secret key must have at least one usage", "SyntaxError");
  return createCryptoKey("secret", false, new KeyAlgorithm(algorithm.name), normalizeKeyUsages(usages), record.handle);
}

/** §§33.4.3, 34.4.3 and Modern Algorithms §17.4.3 request all key bits. */
export function getKdfKeyLength(): null {
  return null;
}

/**
 * Web Cryptography §§33.4.1 and 34.4.1 and Modern Algorithms §17.4.1.
 * Hashing, extraction, expansion, password iterations and memory-hard work
 * stay inside one synchronous native derivation call.
 * https://w3c.github.io/webcrypto/#hkdf-operations-derive-bits
 * https://w3c.github.io/webcrypto/#pbkdf2-operations-derive-bits
 * https://wicg.github.io/webcrypto-modern-algos/#argon2-operations-derive-bits
 */
export function deriveKdfBits(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  length: number | null,
): Uint8Array {
  if (length === null || length % 8 !== 0) throw operationError();
  const byteLength = length / 8;
  let parameters: CryptoHkdfParameters | CryptoPbkdf2Parameters | CryptoArgon2Parameters;
  if (algorithm instanceof HkdfParams) {
    const hash = algorithm.hash.name;
    const hashLength = hash === "SHA-1" ? 160 : hash === "SHA-256" || hash === "SHA3-256" ? 256 : hash === "SHA-384" || hash === "SHA3-384" ? 384 : 512;
    if (length > 255 * hashLength) throw operationError();
    parameters = { name: "HKDF", hash, salt: algorithm.salt, info: algorithm.info, byteLength };
  } else if (algorithm instanceof Pbkdf2Params) {
    if (algorithm.iterations === 0) throw operationError();
    // PBKDF2 explicitly returns here; HKDF still performs its native operation
    // for zero length, so a native failure there remains observable.
    if (length === 0) return new Uint8Array(0);
    parameters = { name: "PBKDF2", hash: algorithm.hash.name, salt: algorithm.salt, iterations: algorithm.iterations, byteLength };
  } else if (algorithm instanceof Argon2Params) {
    // Modern Algorithms §17.4.1. The nonce's RFC 9106 constraints and all
    // cryptographic work remain in the single native operation below.
    if (length < 32) throw operationError();
    if (algorithm.version !== undefined && algorithm.version !== 0x13) throw operationError();
    if (algorithm.parallelism === 0 || algorithm.parallelism > 0xff_ffff) throw operationError();
    if (algorithm.memory < 8 * algorithm.parallelism) throw operationError();
    if (algorithm.passes === 0) throw operationError();
    parameters = {
      name: algorithm.name,
      nonce: algorithm.nonce,
      parallelism: algorithm.parallelism,
      memory: algorithm.memory,
      passes: algorithm.passes,
      version: 0x13,
      secretValue: algorithm.secretValue,
      associatedData: algorithm.associatedData,
      byteLength,
    };
  } else {
    throw new DOMException("This algorithm cannot derive KDF bits", "NotSupportedError");
  }
  const result = provider.derive(parameters, key.handle);
  if ("failure" in result || result.byteLength !== byteLength) throw operationError();
  return result;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoKeyRecord, CryptoKmacParameters, CryptoProvider } from "../provider/crypto.ts";
import type { RandomSource } from "../provider/primitives.ts";
import { KmacImportParams, KmacKeyGenParams, KmacParams } from "./algorithms.ts";
import type { KmacAlgorithmName, NormalizedAlgorithm } from "./algorithms.ts";
import { copyCryptoBytes } from "./buffer-source.ts";
import { createCryptoKey, KeyAlgorithm } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeySlots, KeyAlgorithmObject, KeyUsage } from "./crypto-key.ts";
import { checkJwkPolicy, decodeBase64Url, encodeBase64Url, JsonWebKey, normalizeKeyUsages } from "./jwk.ts";
import type { KeyFormat } from "./jwk.ts";

interface KmacKeyAlgorithmObject extends KeyAlgorithmObject { length: number; }

/** Modern Algorithms §16.5. The logical key length need not fill the last octet. */
export class KmacKeyAlgorithm extends KeyAlgorithm {
  readonly length: number;

  constructor(name: KmacAlgorithmName, length: number) {
    super(name);
    this.length = length;
  }

  override copy(): KmacKeyAlgorithm {
    return new KmacKeyAlgorithm(this.name as KmacAlgorithmName, this.length);
  }

  override toObject(): KmacKeyAlgorithmObject {
    return { name: this.name, length: this.length };
  }
}

function validateUsages(usages: readonly KeyUsage[]): void {
  for (const usage of usages) {
    if (usage !== "sign" && usage !== "verify") throw new DOMException("KMAC keys only sign and verify", "SyntaxError");
  }
}

function finishKey(record: CryptoKeyRecord, name: KmacAlgorithmName, length: number, extractable: boolean, usages: readonly KeyUsage[]): CryptoKey {
  if (record.info.family !== "secret" || record.info.type !== "secret" || record.info.length !== Math.ceil(length / 8) * 8) {
    throw new DOMException("The primitive returned inconsistent KMAC key metadata", "OperationError");
  }
  if (usages.length === 0) throw new DOMException("A secret key must have at least one usage", "SyntaxError");
  return createCryptoKey("secret", extractable, new KmacKeyAlgorithm(name, length), normalizeKeyUsages(usages), record.handle);
}

/** Modern Algorithms §16.7.6. Zero is permitted, unlike HMAC. */
export function getKmacKeyLength(algorithm: NormalizedAlgorithm): number {
  if (!(algorithm instanceof KmacImportParams)) throw new DOMException("Expected KMAC key-length parameters", "NotSupportedError");
  return algorithm.length ?? (algorithm.name === "KMAC128" ? 128 : 256);
}

/** Modern Algorithms §16.7.3. RandomSource generates bytes; the codec keeps low bits. */
export function generateKmacKey(provider: CryptoProvider, random: RandomSource, algorithm: NormalizedAlgorithm, extractable: boolean, usages: readonly KeyUsage[]): CryptoKey {
  if (!(algorithm instanceof KmacKeyGenParams)) throw new DOMException("Expected KMAC generation parameters", "NotSupportedError");
  validateUsages(usages);
  const length = algorithm.length ?? (algorithm.name === "KMAC128" ? 128 : 256);
  let bytes: Uint8Array;
  try {
    bytes = new Uint8Array(Math.ceil(length / 8));
    random.fill(bytes);
  } catch {
    throw new DOMException("KMAC key generation failed", "OperationError");
  }
  // §2.1's Keccak encoding uses the least significant bits of the final octet.
  if (length % 8 !== 0) bytes[bytes.length - 1]! &= (1 << (length % 8)) - 1;
  const record = provider.importKey({ format: "raw", family: "secret", bytes });
  if ("failure" in record) throw new DOMException("KMAC key generation failed", "OperationError");
  return finishKey(record, algorithm.name, length, extractable, usages);
}

/** Modern Algorithms §16.7.4. The legacy raw alias does not apply to new algorithms. */
export function importKmacKey(provider: CryptoProvider, format: KeyFormat, data: Uint8Array | JsonWebKey, algorithm: NormalizedAlgorithm, extractable: boolean, usages: readonly KeyUsage[]): CryptoKey {
  if (!(algorithm instanceof KmacImportParams)) throw new DOMException("Expected KMAC import parameters", "NotSupportedError");
  validateUsages(usages);
  let bytes: Uint8Array;
  if (format === "raw-secret") {
    if (data instanceof JsonWebKey) throw new DOMException("Expected KMAC key bytes", "DataError");
    bytes = data;
  } else if (format === "jwk") {
    if (!(data instanceof JsonWebKey) || data.kty !== "oct" || data.k === undefined) {
      throw new DOMException("Expected an octet JWK with a k member", "DataError");
    }
    bytes = decodeBase64Url(data.k);
    if (data.alg !== undefined && data.alg !== (algorithm.name === "KMAC128" ? "K128" : "K256")) {
      throw new DOMException("The JWK algorithm does not match the KMAC key", "DataError");
    }
    checkJwkPolicy(data, "sig", extractable, usages);
  } else {
    throw new DOMException("KMAC keys require raw-secret or JWK", "NotSupportedError");
  }
  let length = bytes.byteLength * 8;
  if (algorithm.length !== undefined) {
    if (algorithm.length > length || algorithm.length <= length - 8) {
      throw new DOMException("The KMAC length does not match its key bytes", "DataError");
    }
    length = algorithm.length;
    if (length % 8 !== 0) {
      bytes = copyCryptoBytes(bytes);
      bytes[bytes.length - 1]! &= (1 << (length % 8)) - 1;
    }
  }
  const record = provider.importKey({ format: "raw", family: "secret", bytes });
  if ("failure" in record) throw new DOMException("The KMAC key could not be imported", record.failure === "invalid-key" ? "DataError" : "OperationError");
  return finishKey(record, algorithm.name, length, extractable, usages);
}

/** Modern Algorithms §16.7.5. Exported bytes and dictionaries never alias key slots. */
export function exportKmacKey(provider: CryptoProvider, format: KeyFormat, key: CryptoKeySlots): Uint8Array | JsonWebKey {
  const bytes = provider.exportKey(key.handle, "raw");
  if ("failure" in bytes) throw new DOMException("The KMAC key cannot be exported", "OperationError");
  if (format === "raw-secret") return bytes;
  if (format !== "jwk") throw new DOMException("KMAC keys require raw-secret or JWK", "NotSupportedError");
  const jwk = new JsonWebKey();
  jwk.kty = "oct";
  jwk.k = encodeBase64Url(bytes);
  jwk.alg = key.algorithm.name === "KMAC128" ? "K128" : "K256";
  jwk.key_ops = [];
  for (const usage of key.usages) jwk.key_ops.push(usage);
  jwk.ext = key.extractable;
  return jwk;
}

function parameters(algorithm: NormalizedAlgorithm, key: CryptoKeySlots): CryptoKmacParameters {
  if (!(algorithm instanceof KmacParams) || !(key.algorithm instanceof KmacKeyAlgorithm)) {
    throw new DOMException("Expected KMAC signing parameters", "NotSupportedError");
  }
  // §16.6 explicitly permits byte-oriented implementations. Node 24.20's native
  // non-octet KMAC output truncation does not implement §2.1's Keccak encoding.
  // The output length is part of KMAC's domain separation, so rounding it changes
  // the primitive and cannot serve as a fallback.
  if (algorithm.outputLength % 8 !== 0) throw new DOMException("Non-octet KMAC output is not supported", "NotSupportedError");
  return { name: algorithm.name, keyLength: key.algorithm.length, outputLength: algorithm.outputLength,
    customization: algorithm.customization ?? new Uint8Array(0) };
}

/** Modern Algorithms §16.7.1. KMAC framing, hashing and length separation stay native. */
export function signKmac(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots, data: Uint8Array): Uint8Array {
  const normalized = parameters(algorithm, key);
  const result = provider.sign(normalized, key.handle, data);
  if ("failure" in result || result.kind !== "bytes" || result.bytes.byteLength !== normalized.outputLength / 8) {
    throw new DOMException("The KMAC operation failed", "OperationError");
  }
  return result.bytes;
}

/** Modern Algorithms §16.7.2. A native error differs from an invalid signature. */
export function verifyKmac(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots, signature: Uint8Array, data: Uint8Array): boolean {
  const result = provider.verify(parameters(algorithm, key), key.handle, { kind: "bytes", bytes: signature }, data);
  if (typeof result !== "boolean") throw new DOMException("The KMAC operation failed", "OperationError");
  return result;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoMlDsaParameters, CryptoProvider } from "../provider/crypto.ts";
import { ContextParams } from "./algorithms.ts";
import type { NormalizedAlgorithm } from "./algorithms.ts";
import type { CryptoKeySlots } from "./crypto-key.ts";
import { mlSignatureLength } from "./ml-parameters.ts";

function parameters(algorithm: NormalizedAlgorithm, key: CryptoKeySlots, type: "public" | "private"): CryptoMlDsaParameters {
  if (!(algorithm instanceof ContextParams)) throw new DOMException("Expected ML-DSA parameters", "NotSupportedError");
  const context = algorithm.context ?? new Uint8Array(0);
  // Modern Algorithms §§8.4.1–2 deliberately check context before key type.
  if (context.byteLength > 255) throw new DOMException("The ML-DSA context is too long", "OperationError");
  if (key.type !== type) throw new DOMException("The ML-DSA key has the wrong type", "InvalidAccessError");
  return { name: algorithm.name, context };
}

/** Modern Algorithms §8.4.1: pure ML-DSA, one whole-message native operation. */
export function signMlDsa(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots, bytes: Uint8Array): Uint8Array {
  const normalized = parameters(algorithm, key, "private");
  const signature = provider.sign(normalized, key.handle, bytes);
  if ("failure" in signature || signature.kind !== "bytes" || signature.bytes.byteLength !== mlSignatureLength(normalized.name)) {
    throw new DOMException("The ML-DSA signing operation failed", "OperationError");
  }
  return signature.bytes;
}

/** Modern Algorithms §8.4.2: false is an invalid signature, failures are errors. */
export function verifyMlDsa(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots,
  signature: Uint8Array, bytes: Uint8Array): boolean {
  const normalized = parameters(algorithm, key, "public");
  const result = provider.verify(normalized, key.handle, { kind: "bytes", bytes: signature }, bytes);
  if (typeof result !== "boolean") throw new DOMException("The ML-DSA verification operation failed", "OperationError");
  return result;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoEncapsulation, CryptoKemParameters, CryptoProvider } from "../provider/crypto.ts";
import type { NormalizedAlgorithm } from "./algorithms.ts";
import type { CryptoKey, CryptoKeySlots } from "./crypto-key.ts";
import { getMlKemSharedKeyLength, isMlKemAlgorithm, mlCiphertextLength } from "./ml-parameters.ts";

/** Modern Algorithms §4: the public result dictionaries have ordinary members. */
export interface EncapsulatedBits {
  ciphertext: ArrayBuffer;
  sharedKey: ArrayBuffer;
}

export interface EncapsulatedKey {
  ciphertext: ArrayBuffer;
  sharedKey: CryptoKey;
}

function parameters(algorithm: NormalizedAlgorithm, key: CryptoKeySlots, type: "public" | "private"): CryptoKemParameters {
  if (!isMlKemAlgorithm(algorithm.name)) throw new DOMException("Expected ML-KEM parameters", "NotSupportedError");
  if (key.type !== type) throw new DOMException("The ML-KEM key has the wrong type", "InvalidAccessError");
  return { name: algorithm.name };
}

/** Modern Algorithms §6.4.1: FIPS 203 input checks and encapsulation stay native. */
export function encapsulateMlKem(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots): CryptoEncapsulation {
  const normalized = parameters(algorithm, key, "public");
  const result = provider.encapsulate(normalized, key.handle);
  if ("failure" in result || result.sharedKey.byteLength !== getMlKemSharedKeyLength() / 8 ||
      result.ciphertext.byteLength !== mlCiphertextLength(normalized.name)) {
    throw new DOMException("The ML-KEM encapsulation operation failed", "OperationError");
  }
  return result;
}

/** Modern Algorithms §6.4.2: native decapsulation includes implicit rejection. */
export function decapsulateMlKem(provider: CryptoProvider, algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots, ciphertext: Uint8Array): Uint8Array {
  const normalized = parameters(algorithm, key, "private");
  if (ciphertext.byteLength !== mlCiphertextLength(normalized.name)) {
    throw new DOMException("The ML-KEM ciphertext has the wrong width", "OperationError");
  }
  const result = provider.decapsulate(normalized, key.handle, ciphertext);
  if ("failure" in result || result.byteLength !== getMlKemSharedKeyLength() / 8) {
    throw new DOMException("The ML-KEM decapsulation operation failed", "OperationError");
  }
  return result;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoKeyRecord, CryptoMlAlgorithmName, CryptoMlComponents, CryptoProvider } from "../provider/crypto.ts";
import type { NormalizedAlgorithm } from "./algorithms.ts";
import { createCryptoKey, KeyAlgorithm } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeyPair, CryptoKeySlots, KeyUsage } from "./crypto-key.ts";
import { parseMlDer } from "./der.ts";
import { checkJwkPolicy, decodeBase64Url, encodeBase64Url, JsonWebKey, normalizeKeyUsages } from "./jwk.ts";
import type { KeyFormat } from "./jwk.ts";
import { isMlAlgorithm, isMlKemAlgorithm, mlPublicKeyLength, mlSeedLength } from "./ml-parameters.ts";

function mlName(name: string): CryptoMlAlgorithmName {
  if (isMlAlgorithm(name)) return name;
  throw new DOMException("The module-lattice algorithm is not supported", "NotSupportedError");
}

function publicUsage(name: CryptoMlAlgorithmName, usage: KeyUsage): boolean {
  return isMlKemAlgorithm(name) ? usage === "encapsulateKey" || usage === "encapsulateBits" : usage === "verify";
}

function privateUsage(name: CryptoMlAlgorithmName, usage: KeyUsage): boolean {
  return isMlKemAlgorithm(name) ? usage === "decapsulateKey" || usage === "decapsulateBits" : usage === "sign";
}

function validateUsages(name: CryptoMlAlgorithmName, type: "public" | "private" | "pair", usages: readonly KeyUsage[]): void {
  for (const usage of usages) {
    if ((!privateUsage(name, usage) || type === "public") && (!publicUsage(name, usage) || type === "private")) {
      throw new DOMException("The requested usage is not supported by this key", "SyntaxError");
    }
  }
}

function recordShape(record: CryptoKeyRecord, name: CryptoMlAlgorithmName, type: "public" | "private"): void {
  if (record.info.family !== "ML" || record.info.name !== name || record.info.type !== type) {
    throw new DOMException("The native module-lattice key metadata is inconsistent", "OperationError");
  }
}

function bytesEqual(left: Uint8Array, right: Uint8Array): boolean {
  if (left.byteLength !== right.byteLength) return false;
  for (let index = 0; index < left.byteLength; index++) if (left[index] !== right[index]) return false;
  return true;
}

function componentShape(components: CryptoMlComponents, name: CryptoMlAlgorithmName, privateKey: boolean): void {
  if (components.name !== name || components.pub.byteLength !== mlPublicKeyLength(name) ||
      (privateKey && (components.seed === undefined || components.seed.byteLength !== mlSeedLength(name)))) {
    throw new DOMException("The native module-lattice components are inconsistent", "OperationError");
  }
}

/** Modern Algorithms §§6.4.4, 8.4.3: generate natively, then install the specified slots. */
export function generateMlKey(provider: CryptoProvider, algorithm: NormalizedAlgorithm,
  extractable: boolean, usages: readonly KeyUsage[]): CryptoKeyPair {
  const name = mlName(algorithm.name);
  validateUsages(name, "pair", usages);
  const pair = provider.generateKeyPair({ family: "ML", name });
  if ("failure" in pair) throw new DOMException("Module-lattice key generation failed", "OperationError");
  recordShape(pair.publicKey, name, "public");
  recordShape(pair.privateKey, name, "private");
  const selected = normalizeKeyUsages(usages);
  const privateUsages = selected.filter(usage => privateUsage(name, usage));
  if (privateUsages.length === 0) throw new DOMException("A private key must have a usage", "SyntaxError");
  const keyAlgorithm = new KeyAlgorithm(name);
  return {
    privateKey: createCryptoKey("private", extractable, keyAlgorithm, privateUsages, pair.privateKey.handle),
    publicKey: createCryptoKey("public", true, keyAlgorithm, selected.filter(usage => publicUsage(name, usage)), pair.publicKey.handle),
  };
}

function jwkBytes(value: string | undefined, length: number): Uint8Array {
  if (value === undefined) throw new DOMException("A module-lattice JWK component is missing", "DataError");
  const bytes = decodeBase64Url(value);
  if (bytes.byteLength !== length) throw new DOMException("The module-lattice JWK component has the wrong width", "DataError");
  return bytes;
}

/** Modern Algorithms §§6.4.5, 8.4.4: raw seed/public, AKP JWK, exact SPKI and seed PKCS8. */
export function importMlKey(provider: CryptoProvider, format: KeyFormat, data: Uint8Array | JsonWebKey,
  algorithm: NormalizedAlgorithm, extractable: boolean, usages: readonly KeyUsage[]): CryptoKey {
  const name = mlName(algorithm.name);
  let type: "public" | "private";
  let bytes: Uint8Array;
  let expanded: Uint8Array | undefined;
  let expectedPublic: string | undefined;
  if (format === "jwk") {
    if (!(data instanceof JsonWebKey)) throw new DOMException("Expected a module-lattice JWK", "DataError");
    type = data.priv === undefined ? "public" : "private";
    validateUsages(name, type, usages);
    if (data.kty !== "AKP" || data.alg !== name) throw new DOMException("The JWK algorithm does not match the key", "DataError");
    checkJwkPolicy(data, isMlKemAlgorithm(name) ? "enc" : "sig", extractable, usages);
    if (type === "private") {
      bytes = jwkBytes(data.priv, mlSeedLength(name));
      expectedPublic = data.pub;
    } else bytes = jwkBytes(data.pub, mlPublicKeyLength(name));
  } else if (format === "spki" || format === "pkcs8" || format === "raw-public" || format === "raw-seed") {
    type = format === "pkcs8" || format === "raw-seed" ? "private" : "public";
    validateUsages(name, type, usages);
    if (data instanceof JsonWebKey) throw new DOMException("Expected module-lattice key bytes", "DataError");
    if (format === "spki" || format === "pkcs8") {
      const parsed = parseMlDer(format, data);
      if (parsed.name !== name) throw new DOMException("The encoded algorithm does not match the key", "DataError");
      if (format === "pkcs8" && parsed.seed === undefined) {
        throw new DOMException("Expanded-only module-lattice private keys are not supported", "NotSupportedError");
      }
      bytes = format === "spki" ? parsed.pub! : parsed.seed!;
      expanded = parsed.expanded;
    } else {
      bytes = data;
      const width = type === "public" ? mlPublicKeyLength(name) : mlSeedLength(name);
      if (bytes.byteLength !== width) throw new DOMException("The raw module-lattice key has the wrong width", "DataError");
    }
  } else throw new DOMException("The module-lattice key format is not supported", "NotSupportedError");

  const record = provider.importKey({ family: "ML", name, format: type === "public" ? "raw-public" : "raw-seed", bytes, expanded });
  if ("failure" in record) {
    throw new DOMException("The module-lattice key could not be imported", record.failure === "invalid-key" ? "DataError" : "OperationError");
  }
  recordShape(record, name, type);
  if (format === "jwk" && type === "private") {
    // §§6.4.5, 8.4.4 create the seed-backed key before validating its JWK public key.
    // A native import failure therefore precedes a missing or malformed `pub`.
    const publicBytes = jwkBytes(expectedPublic, mlPublicKeyLength(name));
    const components = provider.exportComponents(record.handle);
    if ("failure" in components || components.family !== "ML") throw new DOMException("The private key cannot be inspected", "OperationError");
    componentShape(components, name, true);
    if (!bytesEqual(components.pub, publicBytes)) throw new DOMException("The JWK public key does not correspond to its seed", "DataError");
  }
  if (type === "private" && usages.length === 0) throw new DOMException("A private key must have a usage", "SyntaxError");
  return createCryptoKey(type, extractable, new KeyAlgorithm(name), normalizeKeyUsages(usages), record.handle);
}

/** Modern Algorithms §§6.4.6, 8.4.5: PKCS8 exports are seed-only and never expanded-only. */
export function exportMlKey(provider: CryptoProvider, format: KeyFormat, key: CryptoKeySlots): Uint8Array | JsonWebKey {
  const name = mlName(key.algorithm.name);
  if (format === "jwk") {
    const components = provider.exportComponents(key.handle);
    if ("failure" in components || components.family !== "ML") throw new DOMException("The key cannot be exported", "OperationError");
    componentShape(components, name, key.type === "private");
    const jwk = new JsonWebKey();
    jwk.kty = "AKP";
    jwk.alg = name;
    jwk.pub = encodeBase64Url(components.pub);
    if (key.type === "private") jwk.priv = encodeBase64Url(components.seed!);
    jwk.key_ops = normalizeKeyUsages(key.usages);
    jwk.ext = key.extractable;
    return jwk;
  }
  // Access the actual material before reporting an unsupported or wrong-type format.
  const nativeFormat = key.type === "private" ? format === "raw-seed" ? "raw-seed" : "pkcs8"
    : format === "raw-public" ? "raw" : "spki";
  const result = provider.exportKey(key.handle, nativeFormat);
  if ("failure" in result) throw new DOMException("The key cannot be exported", "OperationError");
  if (format !== "spki" && format !== "pkcs8" && format !== "raw-public" && format !== "raw-seed") {
    throw new DOMException("The module-lattice key format is not supported", "NotSupportedError");
  }
  if ((format === "spki" || format === "raw-public") !== (key.type === "public")) {
    throw new DOMException("The key type does not match the export format", "InvalidAccessError");
  }
  try {
    if (format === "raw-public" || format === "raw-seed") {
      if (result.byteLength !== (format === "raw-public" ? mlPublicKeyLength(name) : mlSeedLength(name))) {
        throw new DOMException("The native key encoding has the wrong width", "OperationError");
      }
    } else {
      const parsed = parseMlDer(format, result);
      if (parsed.name !== name || (format === "pkcs8" && (parsed.seed === undefined || parsed.expanded !== undefined))) {
        throw new DOMException("The native key encoding does not match the export profile", "OperationError");
      }
    }
  } catch {
    throw new DOMException("The native key encoding is invalid", "OperationError");
  }
  return result;
}

import type { CryptoMlAlgorithmName, CryptoMlDsaName, CryptoMlKemName } from "../provider/crypto.ts";

/** Modern Algorithms §§6, 8: encoded widths, not cryptographic operations. */
export function isMlDsaAlgorithm(name: string): name is CryptoMlDsaName {
  return name === "ML-DSA-44" || name === "ML-DSA-65" || name === "ML-DSA-87";
}

export function isMlKemAlgorithm(name: string): name is CryptoMlKemName {
  return name === "ML-KEM-512" || name === "ML-KEM-768" || name === "ML-KEM-1024";
}

export function isMlAlgorithm(name: string): name is CryptoMlAlgorithmName {
  return isMlDsaAlgorithm(name) || isMlKemAlgorithm(name);
}

export function mlPublicKeyLength(name: CryptoMlAlgorithmName): number {
  if (isMlKemAlgorithm(name)) return name === "ML-KEM-512" ? 800 : name === "ML-KEM-768" ? 1184 : 1568;
  return name === "ML-DSA-44" ? 1312 : name === "ML-DSA-65" ? 1952 : 2592;
}

export function mlSeedLength(name: CryptoMlAlgorithmName): number { return isMlKemAlgorithm(name) ? 64 : 32; }

export function mlExpandedKeyLength(name: CryptoMlAlgorithmName): number {
  if (isMlKemAlgorithm(name)) return name === "ML-KEM-512" ? 1632 : name === "ML-KEM-768" ? 2400 : 3168;
  return name === "ML-DSA-44" ? 2560 : name === "ML-DSA-65" ? 4032 : 4896;
}

export function mlSignatureLength(name: CryptoMlDsaName): number {
  return name === "ML-DSA-44" ? 2420 : name === "ML-DSA-65" ? 3309 : 4627;
}

export function mlCiphertextLength(name: CryptoMlKemName): number {
  return name === "ML-KEM-512" ? 768 : name === "ML-KEM-768" ? 1088 : 1568;
}

/** Modern Algorithms §6.4.3, in bits. No truncation is performed by the KEM. */
export function getMlKemSharedKeyLength(): number { return 256; }

import type { CryptoOkpCurve } from "../provider/crypto.ts";

/**
 * RFC 8032 §§5.1.2, 5.2.2, 5.2.5 and RFC 7748 §5. These widths cover the
 * encoded public key and the original private seed, not a decoded field element.
 * The Secure Curves draft's Ed448 raw-import step says 448 bits in error:
 * RFC 8032's Ed448 encoding is 57 octets (456 bits), including its sign bit.
 * https://www.rfc-editor.org/rfc/rfc8032#section-5.2.2
 */
export function okpCurveByteLength(namedCurve: CryptoOkpCurve): number {
  switch (namedCurve) {
    case "Ed25519":
    case "X25519": return 32;
    case "Ed448": return 57;
    case "X448": return 56;
  }
}

/** Edwards signatures and Montgomery agreement use distinct key usages/JWK policy. */
export function isEdwardsCurve(namedCurve: CryptoOkpCurve): boolean {
  return namedCurve === "Ed25519" || namedCurve === "Ed448";
}

import { DOMException } from "../core/errors.ts";
import type { CryptoKeyRecord, CryptoOkpComponents, CryptoProvider } from "../provider/crypto.ts";
import type { NormalizedAlgorithm, OkpAlgorithmName } from "./algorithms.ts";
import { createCryptoKey, KeyAlgorithm } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeyPair, CryptoKeySlots, KeyUsage } from "./crypto-key.ts";
import { parseOkpDer } from "./der.ts";
import { checkJwkPolicy, decodeBase64Url, encodeBase64Url, JsonWebKey, normalizeKeyUsages } from "./jwk.ts";
import type { KeyFormat } from "./jwk.ts";
import { isEdwardsCurve, okpCurveByteLength } from "./okp-curve.ts";

function okpName(name: string): OkpAlgorithmName {
  if (name === "Ed25519" || name === "X25519" || name === "Ed448" || name === "X448") return name;
  throw new DOMException("This octet key-pair algorithm is not supported", "NotSupportedError");
}

function usageAllowed(name: OkpAlgorithmName, type: "public" | "private" | "pair", usage: KeyUsage): boolean {
  if (!isEdwardsCurve(name)) return type !== "public" && (usage === "deriveKey" || usage === "deriveBits");
  return (type !== "private" && usage === "verify") || (type !== "public" && usage === "sign");
}

function validateUsages(name: OkpAlgorithmName, type: "public" | "private" | "pair", usages: readonly KeyUsage[]): void {
  for (let index = 0; index < usages.length; index++) {
    if (!usageAllowed(name, type, usages[index]!)) {
      throw new DOMException("The requested usage is not supported by this key", "SyntaxError");
    }
  }
}

function intersectUsages(name: OkpAlgorithmName, type: "public" | "private", usages: readonly KeyUsage[]): KeyUsage[] {
  const selected: KeyUsage[] = [];
  for (let index = 0; index < usages.length; index++) {
    const usage = usages[index]!;
    if (usageAllowed(name, type, usage)) selected[selected.length] = usage;
  }
  return normalizeKeyUsages(selected);
}

function okpRecord(record: CryptoKeyRecord, type: "public" | "private", name: OkpAlgorithmName): void {
  const info = record.info;
  if (info.family !== "OKP" || info.type !== type || info.namedCurve !== name) {
    throw new DOMException("The primitive returned inconsistent octet key-pair metadata", "OperationError");
  }
}

/** Web Cryptography §§25–26 / Secure Curves §§4, 6: name-only KeyAlgorithm. */
export function generateOkpKey(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKeyPair {
  const name = okpName(algorithm.name);
  validateUsages(name, "pair", usages);
  const pair = provider.generateKeyPair({ family: "OKP", namedCurve: name });
  if ("failure" in pair) throw new DOMException("Octet key-pair generation failed", "OperationError");
  okpRecord(pair.publicKey, "public", name);
  okpRecord(pair.privateKey, "private", name);
  const privateUsages = intersectUsages(name, "private", usages);
  if (privateUsages.length === 0) throw new DOMException("A private key must have at least one usage", "SyntaxError");
  const keyAlgorithm = new KeyAlgorithm(name);
  const publicKey = createCryptoKey("public", true, keyAlgorithm, intersectUsages(name, "public", usages), pair.publicKey.handle);
  const privateKey = createCryptoKey("private", extractable, keyAlgorithm, privateUsages, pair.privateKey.handle);
  return { privateKey, publicKey };
}

function jwkPolicy(jwk: JsonWebKey, name: OkpAlgorithmName, extractable: boolean, usages: readonly KeyUsage[]): void {
  if (jwk.kty !== "OKP") throw new DOMException("The JWK is not an octet key pair", "DataError");
  if (jwk.crv !== name) throw new DOMException("The JWK curve does not match the algorithm", "DataError");
  // The Edwards imports accept the fully specified name and its earlier JOSE
  // family name. X25519 and X448 have no algorithm-member check on import.
  if (isEdwardsCurve(name) && jwk.alg !== undefined && jwk.alg !== name && jwk.alg !== "EdDSA") {
    throw new DOMException("The JWK algorithm does not match the Edwards key", "DataError");
  }
  checkJwkPolicy(jwk, isEdwardsCurve(name) ? "sig" : "enc", extractable, usages);
}

function jwkOctets(value: string | undefined, name: OkpAlgorithmName): Uint8Array {
  if (value === undefined) throw new DOMException("An octet key-pair component is missing", "DataError");
  const bytes = decodeBase64Url(value);
  if (bytes.byteLength !== okpCurveByteLength(name)) throw new DOMException("An octet key-pair component has the wrong width", "DataError");
  return bytes;
}

function componentShape(components: CryptoOkpComponents, name: OkpAlgorithmName, privateKey: boolean): void {
  const width = okpCurveByteLength(name);
  if (components.namedCurve !== name || components.x.byteLength !== width
      || (privateKey && (components.d === undefined || components.d.byteLength !== width))) {
    throw new DOMException("The native octet key-pair components do not match their key", "OperationError");
  }
}

function equalBytes(left: Uint8Array, right: Uint8Array): boolean {
  if (left.byteLength !== right.byteLength) return false;
  for (let index = 0; index < left.byteLength; index++) if (left[index] !== right[index]) return false;
  return true;
}

function privatePublicMatches(provider: CryptoProvider, record: CryptoKeyRecord, supplied: CryptoOkpComponents, name: OkpAlgorithmName): void {
  if (supplied.d === undefined) return;
  const actual = provider.exportComponents(record.handle);
  if ("failure" in actual || actual.family !== "OKP") throw new DOMException("The private key cannot be inspected", "OperationError");
  componentShape(actual, name, true);
  if (actual.d === undefined || !equalBytes(actual.d, supplied.d)) {
    throw new DOMException("The primitive changed the imported private key bytes", "OperationError");
  }
  if (!equalBytes(actual.x, supplied.x)) {
    throw new DOMException("The JWK public key does not match its private key", "DataError");
  }
}

/**
 * Web Cryptography §§25.3.4, 26.3.3 and Secure Curves §§4.3, 6.4.
 * Every public value of the algorithm's encoded width is retained as supplied;
 * canonical, on-curve and small-order checks belong to the operation that uses it.
 * https://wicg.github.io/webcrypto-secure-curves/#ed448-operations
 */
export function importOkpKey(
  provider: CryptoProvider,
  format: KeyFormat,
  data: Uint8Array | JsonWebKey,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKey {
  const name = okpName(algorithm.name);
  if (format === "raw-secret") throw new DOMException("This asymmetric key format is not supported", "NotSupportedError");
  let type: "public" | "private";
  let components: CryptoOkpComponents | undefined;
  if (format === "jwk") {
    if (!(data instanceof JsonWebKey)) throw new DOMException("Expected an octet key-pair JWK", "DataError");
    type = data.d === undefined ? "public" : "private";
    validateUsages(name, type, usages);
    jwkPolicy(data, name, extractable, usages);
    const x = jwkOctets(data.x, name);
    components = data.d === undefined ? { family: "OKP", namedCurve: name, x }
      : { family: "OKP", namedCurve: name, x, d: jwkOctets(data.d, name) };
  } else {
    if (format !== "pkcs8" && format !== "spki" && format !== "raw") throw new DOMException("The key format is not supported", "NotSupportedError");
    type = format === "pkcs8" ? "private" : "public";
    validateUsages(name, type, usages);
    if (data instanceof JsonWebKey) throw new DOMException("Expected octet key-pair bytes", "DataError");
    if (format === "raw") {
      if (data.byteLength !== okpCurveByteLength(name)) throw new DOMException("The raw public key has the wrong encoded width", "DataError");
    } else if (parseOkpDer(format, data).namedCurve !== name) {
      throw new DOMException("The encoded algorithm does not match the requested key", "DataError");
    }
  }
  const record = provider.importKey(components !== undefined ? { format: "components", components }
    : format === "raw" ? { format, family: "OKP", namedCurve: name, bytes: data as Uint8Array }
      : { format: format as "spki" | "pkcs8", bytes: data as Uint8Array });
  if ("failure" in record) {
    throw new DOMException("The octet key pair could not be imported", record.failure === "invalid-key" ? "DataError" : "OperationError");
  }
  okpRecord(record, type, name);
  if (components !== undefined) privatePublicMatches(provider, record, components, name);
  if (type === "private" && usages.length === 0) throw new DOMException("A private key must have at least one usage", "SyntaxError");
  return createCryptoKey(type, extractable, new KeyAlgorithm(name), normalizeKeyUsages(usages), record.handle);
}

/** OKP exports: material-access errors precede export-format type errors. */
export function exportOkpKey(provider: CryptoProvider, format: KeyFormat, key: CryptoKeySlots): Uint8Array | JsonWebKey {
  const name = okpName(key.algorithm.name);
  if (format === "jwk") {
    const components = provider.exportComponents(key.handle);
    if ("failure" in components || components.family !== "OKP") throw new DOMException("The key cannot be exported", "OperationError");
    componentShape(components, name, key.type === "private");
    const jwk = new JsonWebKey();
    jwk.kty = "OKP";
    jwk.crv = name;
    if (isEdwardsCurve(name)) jwk.alg = name;
    jwk.x = encodeBase64Url(components.x);
    if (key.type === "private") jwk.d = encodeBase64Url(components.d!);
    jwk.key_ops = [];
    for (let index = 0; index < key.usages.length; index++) jwk.key_ops[index] = key.usages[index]!;
    jwk.ext = key.extractable;
    return jwk;
  }
  const unsupported = format !== "raw" && format !== "spki" && format !== "pkcs8";
  const nativeFormat = key.type === "private" ? "pkcs8" : format === "raw" ? "raw" : "spki";
  const result = provider.exportKey(key.handle, nativeFormat);
  if ("failure" in result) throw new DOMException("The key cannot be exported", "OperationError");
  if (unsupported) throw new DOMException("The key format is not supported", "NotSupportedError");
  if (format !== nativeFormat) throw new DOMException("The key type does not match the export format", "InvalidAccessError");
  try {
    if (format === "raw") {
      if (result.byteLength !== okpCurveByteLength(name)) throw new DOMException("The native public key has the wrong width", "OperationError");
    } else if (parseOkpDer(format, result).namedCurve !== name) {
      throw new DOMException("The native key encoding has the wrong algorithm", "OperationError");
    }
  } catch {
    throw new DOMException("The native key encoding is invalid", "OperationError");
  }
  return result;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoEd25519Parameters, CryptoEd448Parameters, CryptoProvider } from "../provider/crypto.ts";
import type { EcdhKeyDeriveParams, Ed448Params, NormalizedAlgorithm } from "./algorithms.ts";
import { getCryptoKeySlots } from "./crypto-key.ts";
import type { CryptoKeySlots } from "./crypto-key.ts";
import { truncateDerivationBits } from "./derive-bits.ts";
import { okpCurveByteLength } from "./okp-curve.ts";

const emptyBytes = new Uint8Array(0);

function operationError(): DOMException {
  return new DOMException("The curve operation failed", "OperationError");
}

function requireKeyType(key: CryptoKeySlots, type: "public" | "private"): void {
  if (key.type !== type) throw new DOMException("The operation requires a " + type + " key", "InvalidAccessError");
}

function signatureParameters(algorithm: NormalizedAlgorithm): CryptoEd25519Parameters | CryptoEd448Parameters {
  if (algorithm.name !== "Ed448") return { name: "Ed25519" };
  const context = (algorithm as Ed448Params).context ?? emptyBytes;
  if (context.byteLength > 255) throw operationError();
  return { name: "Ed448", context };
}

/**
 * Web Cryptography §25.3.1 / Secure Curves §6.4 / RFC 8032 §§5.1.6, 5.2.6.
 * Each complete Edwards signature, including hashing and context processing,
 * is one native primitive call. Context length follows the private-key check.
 * https://w3c.github.io/webcrypto/#ed25519-operations-sign
 * https://wicg.github.io/webcrypto-secure-curves/#ed448-operations
 */
export function signOkp(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  bytes: Uint8Array,
): Uint8Array {
  requireKeyType(key, "private");
  const parameters = signatureParameters(algorithm);
  const signature = provider.sign(parameters, key.handle, bytes);
  if ("failure" in signature || signature.kind !== "bytes" || signature.bytes.byteLength !== 2 * okpCurveByteLength(parameters.name)) {
    throw operationError();
  }
  return signature.bytes;
}

/**
 * §25.3.2 / Secure Curves §6.4 / RFC 8032 §§5.1.7, 5.2.7. Native verification checks point decoding,
 * small-order A/R rejection and the cofactorless equation. Public imports keep
 * their encoded bytes; accepting an import does not establish point validity.
 */
export function verifyOkp(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  signature: Uint8Array,
  bytes: Uint8Array,
): boolean {
  requireKeyType(key, "public");
  const parameters = signatureParameters(algorithm);
  if (signature.byteLength !== 2 * okpCurveByteLength(parameters.name)) return false;
  const result = provider.verify(parameters, key.handle, { kind: "bytes", bytes: signature }, bytes);
  if (typeof result !== "boolean") throw new DOMException("The verification operation failed", "OperationError");
  return result;
}

/**
 * §26.3.1 / Secure Curves §4.3 / RFC 7748 §§5–6. Check every secret octet before truncation,
 * including when zero bits were requested. The fixed-count OR scan has no
 * data-dependent early exit; no prefix of an all-zero result may be released.
 * https://w3c.github.io/webcrypto/#x25519-operations-derive-bits
 * https://wicg.github.io/webcrypto-secure-curves/#x448-operations
 */
export function deriveOkpBits(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  length: number | null,
): Uint8Array {
  const name = algorithm.name === "X448" ? "X448" : "X25519";
  // Secure Curves checks X448's base key first and its length after agreement.
  // Level 2's X25519 instead checks peer and length before the base key.
  if (name === "X448") requireKeyType(key, "private");
  const publicKey = getCryptoKeySlots((algorithm as EcdhKeyDeriveParams).public);
  requireKeyType(publicKey, "public");
  if (name === "X25519") {
    if (publicKey.algorithm.name !== name) {
      throw new DOMException("The peer key algorithm does not match X25519", "InvalidAccessError");
    }
    if (length !== null && length > 256) throw operationError();
    requireKeyType(key, "private");
  }
  if (publicKey.algorithm.name !== key.algorithm.name) {
    throw new DOMException("The agreement keys must use the same algorithm", "InvalidAccessError");
  }
  const width = okpCurveByteLength(name);
  const secret = provider.derive({ name, publicKey: publicKey.handle }, key.handle);
  if ("failure" in secret || secret.byteLength !== width) throw operationError();
  let nonzero = 0;
  for (let index = 0; index < width; index++) nonzero |= secret[index]!;
  if (nonzero === 0) throw operationError();
  if (length !== null && length > width * 8) throw operationError();
  return truncateDerivationBits(secret, length);
}

import { DOMException } from "../core/errors.ts";
import type { CryptoKeyInfo, CryptoProvider } from "../provider/crypto.ts";
import { createCryptoKey } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeySlots, KeyUsage } from "./crypto-key.ts";
import { EcKeyAlgorithm } from "./ec-key.ts";
import { normalizeKeyUsages } from "./jwk.ts";
import { isMlAlgorithm, isMlKemAlgorithm } from "./ml-parameters.ts";
import { RsaHashedKeyAlgorithm } from "./rsa-key.ts";

export function supportsPublicKey(name: string): boolean {
  return name === "RSASSA-PKCS1-v1_5" || name === "RSA-PSS" || name === "RSA-OAEP" ||
    name === "ECDSA" || name === "ECDH" || name === "Ed25519" || name === "Ed448" ||
    name === "X25519" || name === "X448" || isMlAlgorithm(name);
}

function allowed(name: string, usage: KeyUsage): boolean {
  if (isMlKemAlgorithm(name)) return usage === "encapsulateKey" || usage === "encapsulateBits";
  if (name === "RSA-OAEP") return usage === "encrypt" || usage === "wrapKey";
  if (name === "ECDH" || name === "X25519" || name === "X448") return false;
  return usage === "verify";
}

function metadataMatches(info: CryptoKeyInfo, key: CryptoKeySlots): boolean {
  if (info.type !== "public") return false;
  const algorithm = key.algorithm;
  if (algorithm instanceof RsaHashedKeyAlgorithm) {
    if (info.family !== "RSA" || info.modulusLength !== algorithm.modulusLength ||
        info.publicExponent.byteLength !== algorithm.publicExponent.byteLength) return false;
    for (let index = 0; index < info.publicExponent.byteLength; index++) {
      if (info.publicExponent[index] !== algorithm.publicExponent[index]) return false;
    }
    return true;
  }
  if (algorithm instanceof EcKeyAlgorithm) return info.family === "EC" && info.namedCurve === algorithm.namedCurve;
  if (isMlAlgorithm(algorithm.name)) return info.family === "ML" && info.name === algorithm.name;
  return info.family === "OKP" && info.namedCurve === algorithm.name;
}

/** Modern Algorithms §3.2.5: no private export and no call through public methods. */
export function derivePublicKey(provider: CryptoProvider, key: CryptoKeySlots, usages: readonly KeyUsage[]): CryptoKey {
  if (key.type !== "private") throw new DOMException("Expected a private key", "InvalidAccessError");
  for (const usage of usages) {
    if (!allowed(key.algorithm.name, usage)) throw new DOMException("The public key does not support this usage", "SyntaxError");
  }
  const record = provider.getPublicKey(key.handle);
  if ("failure" in record || !metadataMatches(record.info, key)) {
    throw new DOMException("The public key could not be derived", "OperationError");
  }
  return createCryptoKey("public", true, key.algorithm, normalizeKeyUsages(usages), record.handle);
}

import { DOMException } from "../core/errors.ts";
import type {
  CryptoDigestName, CryptoKeyRecord, CryptoProvider, CryptoRsaComponents,
  CryptoRsaKeyInfo, CryptoRsaOtherPrime,
} from "../provider/crypto.ts";
import { RsaHashedImportParams, RsaHashedKeyGenParams } from "./algorithms.ts";
import type { NormalizedAlgorithm, RsaAlgorithmName } from "./algorithms.ts";
import { copyCryptoBytes, cryptoByteSubarray, cryptoViewByteLength } from "./buffer-source.ts";
import { createCryptoKey, KeyAlgorithm } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeyPair, CryptoKeySlots, KeyAlgorithmObject, KeyUsage } from "./crypto-key.ts";
import { parseRsaDer } from "./der.ts";
import { checkJwkPolicy, decodeBase64Url, encodeBase64Url, JsonWebKey, normalizeKeyUsages, RsaOtherPrimesInfo } from "./jwk.ts";
import type { KeyFormat } from "./jwk.ts";

interface RsaHashedKeyAlgorithmObject extends KeyAlgorithmObject {
  modulusLength: number;
  publicExponent: Uint8Array;
  hash: KeyAlgorithmObject;
}

/** §§20.6–7: slots and both cached public dictionaries own separate nested values. */
export class RsaHashedKeyAlgorithm extends KeyAlgorithm {
  readonly modulusLength: number;
  readonly publicExponent: Uint8Array;
  readonly hash: KeyAlgorithm;

  constructor(name: RsaAlgorithmName, modulusLength: number, publicExponent: Uint8Array, hash: CryptoDigestName) {
    super(name);
    this.modulusLength = modulusLength;
    this.publicExponent = copyCryptoBytes(minimalUnsigned(publicExponent));
    this.hash = new KeyAlgorithm(hash);
  }

  override copy(): RsaHashedKeyAlgorithm {
    return new RsaHashedKeyAlgorithm(this.name as RsaAlgorithmName, this.modulusLength, this.publicExponent, this.hash.name as CryptoDigestName);
  }

  override toObject(): RsaHashedKeyAlgorithmObject {
    return {
      name: this.name,
      modulusLength: this.modulusLength,
      publicExponent: copyCryptoBytes(this.publicExponent),
      hash: this.hash.toObject(),
    };
  }
}

function minimalUnsigned(bytes: Uint8Array): Uint8Array {
  const length = cryptoViewByteLength(bytes);
  let start = 0;
  while (start < length - 1 && bytes[start] === 0) start++;
  return start === 0 ? bytes : cryptoByteSubarray(bytes, start, length);
}

function bitLength(bytes: Uint8Array): number {
  const length = cryptoViewByteLength(bytes);
  if (length === 0) return 0;
  let leading = 0;
  const first = bytes[0]!;
  while (leading < 8 && (first & (0x80 >>> leading)) === 0) leading++;
  return length * 8 - leading;
}

function equalBytes(left: Uint8Array, right: Uint8Array): boolean {
  const length = cryptoViewByteLength(left);
  if (length !== cryptoViewByteLength(right)) return false;
  for (let index = 0; index < length; index++) if (left[index] !== right[index]) return false;
  return true;
}

function lessThan(left: Uint8Array, right: Uint8Array): boolean {
  const leftLength = cryptoViewByteLength(left);
  const rightLength = cryptoViewByteLength(right);
  if (leftLength !== rightLength) return leftLength < rightLength;
  for (let index = 0; index < leftLength; index++) {
    if (left[index] !== right[index]) return left[index]! < right[index]!;
  }
  return false;
}

function usageAllowed(name: string, type: "public" | "private" | "pair", usage: KeyUsage): boolean {
  if (name === "RSA-OAEP") {
    return (type !== "private" && (usage === "encrypt" || usage === "wrapKey"))
      || (type !== "public" && (usage === "decrypt" || usage === "unwrapKey"));
  }
  return (type !== "private" && usage === "verify") || (type !== "public" && usage === "sign");
}

function validateUsages(name: string, type: "public" | "private" | "pair", usages: readonly KeyUsage[]): void {
  for (let index = 0; index < usages.length; index++) {
    if (!usageAllowed(name, type, usages[index]!)) {
      throw new DOMException("The requested usage is not supported by this RSA key", "SyntaxError");
    }
  }
}

function intersectUsages(name: string, type: "public" | "private", usages: readonly KeyUsage[]): KeyUsage[] {
  const selected: KeyUsage[] = [];
  for (let index = 0; index < usages.length; index++) {
    const usage = usages[index]!;
    if (usageAllowed(name, type, usage)) selected[selected.length] = usage;
  }
  return normalizeKeyUsages(selected);
}

/** §20.5's bounds need only byte inspection, never big-integer arithmetic. */
export function rsaGenerationExponent(algorithm: RsaHashedKeyGenParams): Uint8Array {
  const exponent = minimalUnsigned(algorithm.publicExponent);
  const length = cryptoViewByteLength(exponent);
  const bits = bitLength(exponent);
  const modulusLength = algorithm.modulusLength;
  if (modulusLength < 4 || length === 0 || (length === 1 && exponent[0]! < 3)
      || (exponent[length - 1]! & 1) === 0 || bits > modulusLength) {
    throw new DOMException("The RSA generation parameters are invalid", "OperationError");
  }
  // If the lengths match, only the all-one value reaches 2^modulusLength − 1.
  if (bits === modulusLength) {
    let allOnes = exponent[0] === (0xff >>> ((8 - modulusLength % 8) % 8));
    for (let index = 1; index < length; index++) if (exponent[index] !== 0xff) allOnes = false;
    if (allOnes) throw new DOMException("The RSA public exponent is too large", "OperationError");
  }
  return exponent;
}

function rsaRecord(record: CryptoKeyRecord, type: "public" | "private", modulusLength: number, exponent: Uint8Array): CryptoRsaKeyInfo {
  const info = record.info;
  if (info.family !== "RSA" || info.type !== type || info.modulusLength !== modulusLength
      || !equalBytes(info.publicExponent, exponent)) {
    throw new DOMException("The primitive returned inconsistent RSA key metadata", "OperationError");
  }
  return info;
}

/** §§20.9.3, 21.4.3, 22.4.3 and the common §14.3.6 private-usage check. */
export function generateRsaKey(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKeyPair {
  if (!(algorithm instanceof RsaHashedKeyGenParams)) throw new DOMException("Expected RSA generation parameters", "NotSupportedError");
  validateUsages(algorithm.name, "pair", usages);
  const publicExponent = rsaGenerationExponent(algorithm);
  const pair = provider.generateKeyPair({ family: "RSA", modulusLength: algorithm.modulusLength, publicExponent });
  if ("failure" in pair) throw new DOMException("RSA key generation failed", "OperationError");
  rsaRecord(pair.publicKey, "public", algorithm.modulusLength, publicExponent);
  rsaRecord(pair.privateKey, "private", algorithm.modulusLength, publicExponent);
  const privateUsages = intersectUsages(algorithm.name, "private", usages);
  if (privateUsages.length === 0) throw new DOMException("A private key must have at least one usage", "SyntaxError");
  const keyAlgorithm = new RsaHashedKeyAlgorithm(algorithm.name, algorithm.modulusLength, publicExponent, algorithm.hash.name);
  const publicKey = createCryptoKey("public", true, keyAlgorithm, intersectUsages(algorithm.name, "public", usages), pair.publicKey.handle);
  const privateKey = createCryptoKey("private", extractable, keyAlgorithm, privateUsages, pair.privateKey.handle);
  return { privateKey, publicKey };
}

function jwkAlgorithm(name: string, hash: string): string {
  if (name === "RSA-OAEP") {
    switch (hash) {
      case "SHA-1": return "RSA-OAEP";
      case "SHA-256": return "RSA-OAEP-256";
      case "SHA-384": return "RSA-OAEP-384";
      case "SHA-512": return "RSA-OAEP-512";
    }
  } else {
    const prefix = name === "RSA-PSS" ? "PS" : "RS";
    switch (hash) {
      case "SHA-1": return prefix + "1";
      case "SHA-256": return prefix + "256";
      case "SHA-384": return prefix + "384";
      case "SHA-512": return prefix + "512";
    }
  }
  throw new DOMException("The RSA key hash is not supported", "NotSupportedError");
}

/** RFC 7517 §4.3: unknown key operations are allowed; duplicates are not. */
function jwkPolicy(jwk: JsonWebKey, algorithm: RsaHashedImportParams, extractable: boolean, usages: readonly KeyUsage[]): void {
  if (jwk.kty !== "RSA") throw new DOMException("The JWK is not an RSA key", "DataError");
  checkJwkPolicy(jwk, algorithm.name === "RSA-OAEP" ? "enc" : "sig", extractable, usages);
  if (jwk.alg !== undefined && jwk.alg !== jwkAlgorithm(algorithm.name, algorithm.hash.name)) {
    throw new DOMException("The JWK algorithm does not match the requested hash", "DataError");
  }
}

function jwkInteger(value: string | undefined): Uint8Array {
  if (value === undefined) throw new DOMException("An RSA JWK integer is missing", "DataError");
  const bytes = decodeBase64Url(value);
  // RFC 7518 §2 Base64urlUInt is an unsigned *minimal* octet representation.
  // All actual RSA key parameters below are strictly positive.
  if (cryptoViewByteLength(bytes) === 0 || bytes[0] === 0) throw new DOMException("An RSA JWK integer is not minimally encoded", "DataError");
  return bytes;
}

function jwkComponents(jwk: JsonWebKey): CryptoRsaComponents {
  const n = jwkInteger(jwk.n);
  const e = jwkInteger(jwk.e);
  if (jwk.d === undefined) return { family: "RSA", n, e };
  const d = jwkInteger(jwk.d);
  const anyCrt = jwk.p !== undefined || jwk.q !== undefined || jwk.dp !== undefined
    || jwk.dq !== undefined || jwk.qi !== undefined || jwk.oth !== undefined;
  if (!anyCrt) return { family: "RSA", n, e, d };
  const p = jwkInteger(jwk.p);
  const q = jwkInteger(jwk.q);
  const dp = jwkInteger(jwk.dp);
  const dq = jwkInteger(jwk.dq);
  const qi = jwkInteger(jwk.qi);
  if (jwk.oth === undefined) return { family: "RSA", n, e, d, p, q, dp, dq, qi };
  if (jwk.oth.length === 0) throw new DOMException("The RSA other-primes list is empty", "DataError");
  const oth: CryptoRsaOtherPrime[] = [];
  for (let index = 0; index < jwk.oth.length; index++) {
    const prime = jwk.oth[index]!;
    oth[index] = { r: jwkInteger(prime.r), d: jwkInteger(prime.d), t: jwkInteger(prime.t) };
  }
  return { family: "RSA", n, e, d, p, q, dp, dq, qi, oth };
}

function validatePublicComponents(components: CryptoRsaComponents): number {
  const modulusLength = bitLength(components.n);
  const exponentLength = cryptoViewByteLength(components.e);
  const modulusBytes = cryptoViewByteLength(components.n);
  if (modulusLength < 4 || exponentLength === 0 || (exponentLength === 1 && components.e[0]! < 3)
      || (components.e[exponentLength - 1]! & 1) === 0 || (components.n[modulusBytes - 1]! & 1) === 0
      || !lessThan(components.e, components.n)) {
    throw new DOMException("The RSA public key parameters are invalid", "DataError");
  }
  return modulusLength;
}

/** §§20.9.4, 21.4.4, 22.4.4. The provider sees validated DER or decoded integers. */
export function importRsaKey(
  provider: CryptoProvider,
  format: KeyFormat,
  data: Uint8Array | JsonWebKey,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKey {
  if (!(algorithm instanceof RsaHashedImportParams)) throw new DOMException("Expected RSA import parameters", "NotSupportedError");
  let type: "public" | "private";
  let components: CryptoRsaComponents;
  if (format === "spki" || format === "pkcs8") {
    type = format === "spki" ? "public" : "private";
    validateUsages(algorithm.name, type, usages);
    if (data instanceof JsonWebKey) throw new DOMException("Expected DER key bytes", "DataError");
    components = parseRsaDer(format, data);
  } else if (format === "jwk") {
    if (!(data instanceof JsonWebKey)) throw new DOMException("Expected an RSA JWK", "DataError");
    type = data.d === undefined ? "public" : "private";
    validateUsages(algorithm.name, type, usages);
    jwkPolicy(data, algorithm, extractable, usages);
    components = jwkComponents(data);
  } else {
    throw new DOMException("This RSA key format is not supported", "NotSupportedError");
  }
  const modulusLength = validatePublicComponents(components);
  const record = provider.importKey(format === "jwk"
    ? { format: "components", components }
    : { format, bytes: data as Uint8Array });
  if ("failure" in record) {
    throw new DOMException("The RSA key could not be imported", record.failure === "invalid-key" ? "DataError" : "OperationError");
  }
  rsaRecord(record, type, modulusLength, components.e);
  if (type === "private" && usages.length === 0) throw new DOMException("A private key must have at least one usage", "SyntaxError");
  return createCryptoKey(type, extractable,
    new RsaHashedKeyAlgorithm(algorithm.name, modulusLength, components.e, algorithm.hash.name),
    normalizeKeyUsages(usages), record.handle);
}

function exportedInteger(bytes: Uint8Array | undefined): string {
  if (bytes === undefined || cryptoViewByteLength(bytes) === 0 || bytes[0] === 0) {
    throw new DOMException("The native RSA components are incomplete or nonminimal", "OperationError");
  }
  return encodeBase64Url(bytes);
}

function exportJwk(components: CryptoRsaComponents, key: CryptoKeySlots): JsonWebKey {
  const algorithm = key.algorithm as RsaHashedKeyAlgorithm;
  const jwk = new JsonWebKey();
  jwk.kty = "RSA";
  jwk.alg = jwkAlgorithm(algorithm.name, algorithm.hash.name);
  jwk.n = exportedInteger(components.n);
  jwk.e = exportedInteger(components.e);
  if (key.type === "private") {
    jwk.d = exportedInteger(components.d);
    jwk.p = exportedInteger(components.p);
    jwk.q = exportedInteger(components.q);
    jwk.dp = exportedInteger(components.dp);
    jwk.dq = exportedInteger(components.dq);
    jwk.qi = exportedInteger(components.qi);
    if (components.oth !== undefined) {
      if (components.oth.length === 0) throw new DOMException("The native RSA other-primes list is empty", "OperationError");
      jwk.oth = [];
      for (let index = 0; index < components.oth.length; index++) {
        const source = components.oth[index]!;
        const prime = new RsaOtherPrimesInfo();
        prime.r = exportedInteger(source.r);
        prime.d = exportedInteger(source.d);
        prime.t = exportedInteger(source.t);
        jwk.oth[index] = prime;
      }
    }
  }
  jwk.key_ops = [];
  for (let index = 0; index < key.usages.length; index++) jwk.key_ops[index] = key.usages[index]!;
  jwk.ext = key.extractable;
  return jwk;
}

/** §§20.9.5, 21.4.5, 22.4.5: inaccessible material precedes format/type policy. */
export function exportRsaKey(provider: CryptoProvider, format: KeyFormat, key: CryptoKeySlots): Uint8Array | JsonWebKey {
  const algorithm = key.algorithm as RsaHashedKeyAlgorithm;
  if (format === "jwk") {
    const components = provider.exportComponents(key.handle);
    if ("failure" in components || components.family !== "RSA") throw new DOMException("The RSA key cannot be exported", "OperationError");
    if (bitLength(components.n) !== algorithm.modulusLength || !equalBytes(components.e, algorithm.publicExponent)) {
      throw new DOMException("The native RSA components do not match their key", "OperationError");
    }
    return exportJwk(components, key);
  }
  // Even an unsupported format checks material accessibility first. Select the
  // actual key's encoding for that one native call, then apply requested policy.
  const nativeFormat = key.type === "public" ? "spki" : "pkcs8";
  const result = provider.exportKey(key.handle, nativeFormat);
  if ("failure" in result) throw new DOMException("The RSA key cannot be exported", "OperationError");
  if (format !== "spki" && format !== "pkcs8") throw new DOMException("This RSA export format is not supported", "NotSupportedError");
  if (format !== nativeFormat) throw new DOMException("The RSA key type does not match the export format", "InvalidAccessError");
  try {
    const components = parseRsaDer(format, result, true);
    if (bitLength(components.n) !== algorithm.modulusLength || !equalBytes(components.e, algorithm.publicExponent)) {
      throw new DOMException("The native RSA encoding does not match its key", "OperationError");
    }
  } catch {
    throw new DOMException("The native RSA key encoding is invalid", "OperationError");
  }
  return result;
}

import { DOMException } from "../core/errors.ts";
import type {
  CryptoDigestName,
  CryptoProvider,
  CryptoRsaOaepParameters,
  CryptoSignatureParameters,
} from "../provider/crypto.ts";
import type { NormalizedAlgorithm, RsaOaepParams, RsaPssParams } from "./algorithms.ts";
import { cryptoViewByteLength } from "./buffer-source.ts";
import type { CryptoKeySlots } from "./crypto-key.ts";
import type { RsaHashedKeyAlgorithm } from "./rsa-key.ts";

const emptyBytes = new Uint8Array(0);

function operationError(): DOMException {
  return new DOMException("The RSA operation failed", "OperationError");
}

function requireKeyType(key: CryptoKeySlots, type: "public" | "private"): void {
  if (key.type !== type) throw new DOMException("The RSA operation requires a " + type + " key", "InvalidAccessError");
}

function signatureParameters(algorithm: NormalizedAlgorithm, key: CryptoKeySlots): CryptoSignatureParameters {
  const hash = (key.algorithm as RsaHashedKeyAlgorithm).hash.name as CryptoDigestName;
  if (algorithm.name === "RSASSA-PKCS1-v1_5") return { name: "RSASSA-PKCS1-v1_5", hash };
  return { name: "RSA-PSS", hash, saltLength: (algorithm as RsaPssParams).saltLength };
}

function cipherParameters(algorithm: NormalizedAlgorithm, key: CryptoKeySlots): CryptoRsaOaepParameters {
  return {
    name: "RSA-OAEP",
    hash: (key.algorithm as RsaHashedKeyAlgorithm).hash.name as CryptoDigestName,
    label: (algorithm as RsaOaepParams).label ?? emptyBytes,
  };
}

function oaepMaximumPlaintext(key: CryptoKeySlots): number {
  const algorithm = key.algorithm as RsaHashedKeyAlgorithm;
  const hash = algorithm.hash.name as CryptoDigestName;
  const hashLength = hash === "SHA-1" ? 20 : hash === "SHA-256" || hash === "SHA3-256" ? 32 : hash === "SHA-384" || hash === "SHA3-384" ? 48 : 64;
  return modulusByteLength(algorithm.modulusLength) - 2 * hashLength - 2;
}

function modulusByteLength(bits: number): number {
  return (bits - bits % 8) / 8 + (bits % 8 === 0 ? 0 : 1);
}

/**
 * Web Cryptography §§20.9.1 and 21.4.1. RFC 3447's complete signature operation
 * remains one native call; padding, hashing and PSS's MGF1 use the key's hash.
 * https://w3c.github.io/webcrypto/#rsa-pss-operations-sign
 */
export function signRsa(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  bytes: Uint8Array,
): Uint8Array {
  requireKeyType(key, "private");
  const signature = provider.sign(signatureParameters(algorithm, key), key.handle, bytes);
  if ("failure" in signature || signature.kind !== "bytes") throw operationError();
  return signature.bytes;
}

/** §§20.9.2 and 21.4.2: every invalid signature returns false, including bad PSS salt. */
export function verifyRsa(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  signature: Uint8Array,
  bytes: Uint8Array,
): boolean {
  requireKeyType(key, "public");
  // RFC 3447 §§8.1.2 and 8.2.2 require k octets. Native PSS verification can
  // otherwise accept a shorter encoding of the same integer after zero padding.
  if (cryptoViewByteLength(signature) !== modulusByteLength((key.algorithm as RsaHashedKeyAlgorithm).modulusLength)) {
    return false;
  }
  const result = provider.verify(signatureParameters(algorithm, key), key.handle, { kind: "bytes", bytes: signature }, bytes);
  if (typeof result !== "boolean") throw new DOMException("The verification operation failed", "OperationError");
  return result;
}

/**
 * Web Cryptography §22.4.1 and RFC 3447 §7.1. Shared code checks the byte bound
 * and chooses the hash and label. OAEP encoding remains one native operation.
 */
export function encryptRsa(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  bytes: Uint8Array,
): Uint8Array {
  requireKeyType(key, "public");
  if (cryptoViewByteLength(bytes) > oaepMaximumPlaintext(key)) throw operationError();
  const result = provider.encrypt(cipherParameters(algorithm, key), key.handle, bytes);
  if ("failure" in result) throw operationError();
  return result.bytes;
}

/** §22.4.2: decoding or label mismatch never yields plaintext through a failure. */
export function decryptRsa(
  provider: CryptoProvider,
  algorithm: NormalizedAlgorithm,
  key: CryptoKeySlots,
  bytes: Uint8Array,
): Uint8Array {
  requireKeyType(key, "private");
  // Some native RSA APIs accept shorter ciphertexts by left-padding with zeros.
  // RFC 3447 §7.1.2 explicitly requires k octets, even when the integer is valid.
  const modulusLength = (key.algorithm as RsaHashedKeyAlgorithm).modulusLength;
  if (cryptoViewByteLength(bytes) !== modulusByteLength(modulusLength) || oaepMaximumPlaintext(key) < 0) {
    throw operationError();
  }
  const result = provider.decrypt(cipherParameters(algorithm, key), key.handle, { bytes, tag: null });
  if ("failure" in result) throw operationError();
  return result;
}

import { DOMException } from "../core/errors.ts";
import type { CryptoDigestName, CryptoKeyRecord, CryptoProvider } from "../provider/crypto.ts";
import type { RandomSource } from "../provider/primitives.ts";
import { AesDerivedKeyParams, AesKeyGenParams, HmacImportParams, HmacKeyGenParams } from "./algorithms.ts";
import type { NormalizedAlgorithm } from "./algorithms.ts";
import { copyCryptoBytes, cryptoViewByteLength } from "./buffer-source.ts";
import { createCryptoKey, KeyAlgorithm } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeySlots, KeyAlgorithmObject, KeyUsage } from "./crypto-key.ts";
import { checkJwkPolicy, decodeBase64Url, encodeBase64Url, JsonWebKey, normalizeKeyUsages } from "./jwk.ts";
import type { KeyFormat } from "./jwk.ts";


interface AesKeyAlgorithmObject extends KeyAlgorithmObject {
  length: number;
}

interface HmacKeyAlgorithmObject extends AesKeyAlgorithmObject {
  hash: KeyAlgorithmObject;
}

/** Web Cryptography §§27.4 and 31.4; public dictionaries never alias the slots. */
export class AesKeyAlgorithm extends KeyAlgorithm {
  readonly length: number;

  constructor(name: string, length: number) {
    super(name);
    this.length = length;
  }

  override copy(): AesKeyAlgorithm {
    return new AesKeyAlgorithm(this.name, this.length);
  }

  override toObject(): AesKeyAlgorithmObject {
    return { name: this.name, length: this.length };
  }
}

export class HmacKeyAlgorithm extends KeyAlgorithm {
  readonly length: number;
  readonly hash: KeyAlgorithm;

  constructor(hash: CryptoDigestName, length: number) {
    super("HMAC");
    this.length = length;
    this.hash = new KeyAlgorithm(hash);
  }

  override copy(): HmacKeyAlgorithm {
    return new HmacKeyAlgorithm(this.hash.name as CryptoDigestName, this.length);
  }

  override toObject(): HmacKeyAlgorithmObject {
    return { name: this.name, hash: this.hash.toObject(), length: this.length };
  }
}

function allowedUsage(name: string, usage: KeyUsage): boolean {
  if (name === "HMAC") return usage === "sign" || usage === "verify";
  if (name === "AES-KW") return usage === "wrapKey" || usage === "unwrapKey";
  return usage === "encrypt" || usage === "decrypt" || usage === "wrapKey" || usage === "unwrapKey";
}

function validateUsages(name: string, usages: readonly KeyUsage[]): void {
  for (let index = 0; index < usages.length; index++) {
    if (!allowedUsage(name, usages[index]!)) {
      throw new DOMException("The requested key usage is not supported by " + name, "SyntaxError");
    }
  }
}

function requireAesLength(length: number, error: "OperationError" | "DataError"): void {
  if (length !== 128 && length !== 192 && length !== 256) {
    throw new DOMException("An AES key must contain 128, 192 or 256 bits", error);
  }
}

function requireSecretLength(name: string, length: number, error: "OperationError" | "DataError"): void {
  if (name === "ChaCha20-Poly1305") {
    if (length !== 256) throw new DOMException("A ChaCha20-Poly1305 key must contain 256 bits", error);
  } else {
    requireAesLength(length, error);
  }
}

export function hmacDefaultLength(hash: CryptoDigestName): number {
  // This increment follows Node 24.20's public profile: SHA-3 HMAC is
  // supported with an explicit length, but has no supported omitted default.
  if (hash === "SHA3-256" || hash === "SHA3-384" || hash === "SHA3-512") {
    throw new DOMException("SHA-3 HMAC requires an explicit key length", "NotSupportedError");
  }
  return hash === "SHA-384" || hash === "SHA-512" ? 1024 : 512;
}

/** §§27–31 get-key-length operations, used before deriveKey derives any material. */
export function getSecretKeyLength(algorithm: NormalizedAlgorithm): number {
  if (algorithm.name === "ChaCha20-Poly1305") return 256;
  if (algorithm instanceof AesDerivedKeyParams) {
    requireAesLength(algorithm.length, "OperationError");
    return algorithm.length;
  }
  if (algorithm instanceof HmacImportParams) {
    // HMAC's get-key-length operation specifies TypeError for zero, unlike its
    // generate/import operations. The default is the hash block size, not digest size.
    if (algorithm.length === 0) throw new TypeError("An HMAC key cannot have zero length");
    return algorithm.length ?? hmacDefaultLength(algorithm.hash.name);
  }
  throw new DOMException("This algorithm has no derived key length", "NotSupportedError");
}

function secretRecord(record: CryptoKeyRecord, byteLength: number): void {
  if (record.info.family !== "secret" || record.info.type !== "secret" || record.info.length !== byteLength * 8) {
    throw new DOMException("The primitive returned inconsistent secret-key metadata", "OperationError");
  }
}

function finishSecretKey(
  record: CryptoKeyRecord,
  extractable: boolean,
  algorithm: KeyAlgorithm,
  usages: readonly KeyUsage[],
): CryptoKey {
  // The common generate/import/unwrap steps check this after the algorithm has
  // produced its key, rather than changing earlier algorithm error precedence.
  if (usages.length === 0) throw new DOMException("A secret key must have at least one usage", "SyntaxError");
  return createCryptoKey("secret", extractable, algorithm, normalizeKeyUsages(usages), record.handle);
}

/** §§27–31 generate-key operations, using the existing randomness capability. */
export function generateSecretKey(
  provider: CryptoProvider,
  random: RandomSource,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKey {
  validateUsages(algorithm.name, usages);
  let length: number;
  let keyAlgorithm: KeyAlgorithm;
  if (algorithm instanceof HmacKeyGenParams) {
    length = algorithm.length ?? hmacDefaultLength(algorithm.hash.name);
    if (length === 0) throw new DOMException("An HMAC key cannot have zero length", "OperationError");
    keyAlgorithm = new HmacKeyAlgorithm(algorithm.hash.name, length);
  } else if (algorithm.name === "ChaCha20-Poly1305") {
    length = 256;
    keyAlgorithm = new KeyAlgorithm(algorithm.name);
  } else if (algorithm instanceof AesKeyGenParams) {
    length = algorithm.length;
    requireAesLength(length, "OperationError");
    keyAlgorithm = new AesKeyAlgorithm(algorithm.name, length);
  } else {
    throw new DOMException("This algorithm cannot generate a secret key", "NotSupportedError");
  }
  let bytes: Uint8Array;
  try {
    bytes = new Uint8Array((length - length % 8) / 8 + (length % 8 === 0 ? 0 : 1));
    random.fill(bytes);
  } catch {
    throw new DOMException("Secret key generation failed", "OperationError");
  }
  // The native seam uses octets. Keep the first logical bits and clear the unused
  // low bits, as Node v24.20's secret-key representation does. The logical length
  // remains in HmacKeyAlgorithm and is never inferred from rounded storage.
  const remainder = length % 8;
  if (remainder !== 0) bytes[bytes.length - 1]! &= 0xff << (8 - remainder);
  const record = provider.importKey({ format: "raw", family: "secret", bytes });
  if ("failure" in record) throw new DOMException("Secret key generation failed", "OperationError");
  secretRecord(record, bytes.length);
  return finishSecretKey(record, extractable, keyAlgorithm, usages);
}

function jwkAlgorithm(name: string, length: number, hash: CryptoDigestName | undefined): string {
  switch (name) {
    case "AES-CTR": return "A" + length + "CTR";
    case "AES-CBC": return "A" + length + "CBC";
    case "AES-GCM": return "A" + length + "GCM";
    case "AES-KW": return "A" + length + "KW";
    case "AES-OCB": return "A" + length + "OCB";
    case "ChaCha20-Poly1305": return "C20P";
  }
  switch (hash) {
    case "SHA-1": return "HS1";
    case "SHA-256": return "HS256";
    case "SHA-384": return "HS384";
    case "SHA-512": return "HS512";
    default: throw new DOMException("The key hash is not supported", "NotSupportedError");
  }
}

/** §§27–31 raw/JWK imports. Policy checks precede the one native key import. */
export function importSecretKey(
  provider: CryptoProvider,
  format: KeyFormat,
  data: Uint8Array | JsonWebKey,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKey {
  const hmac = algorithm instanceof HmacImportParams ? algorithm : undefined;
  if (hmac?.length === 0) throw new DOMException("An HMAC key cannot have zero length", "DataError");
  validateUsages(algorithm.name, usages);
  let bytes: Uint8Array;
  if (format === "raw-secret" || (format === "raw" && algorithm.name !== "AES-OCB" && algorithm.name !== "ChaCha20-Poly1305")) {
    if (data instanceof JsonWebKey) throw new DOMException("Expected raw key bytes", "DataError");
    bytes = data;
  } else if (format === "jwk") {
    if (!(data instanceof JsonWebKey) || data.kty !== "oct" || data.k === undefined) {
      throw new DOMException("Expected an octet JWK with a k member", "DataError");
    }
    bytes = decodeBase64Url(data.k);
    const bits = cryptoViewByteLength(bytes) * 8;
    if (hmac === undefined) requireSecretLength(algorithm.name, bits, "DataError");
    if (data.alg !== undefined && data.alg !== jwkAlgorithm(algorithm.name, bits, hmac?.hash.name)) {
      throw new DOMException("The JWK algorithm does not match the requested key", "DataError");
    }
    checkJwkPolicy(data, algorithm.name === "HMAC" ? "sig" : "enc", extractable, usages);
  } else {
    throw new DOMException("This secret-key format is not supported", "NotSupportedError");
  }
  const byteLength = cryptoViewByteLength(bytes);
  let length = byteLength * 8;
  let keyAlgorithm: KeyAlgorithm;
  if (hmac !== undefined) {
    if (length === 0 || (hmac.length !== undefined && (hmac.length > length || hmac.length <= length - 8))) {
      throw new DOMException("The HMAC key length does not match its data", "DataError");
    }
    length = hmac.length ?? length;
    if (length % 8 !== 0) {
      bytes = copyCryptoBytes(bytes);
      bytes[byteLength - 1]! &= 0xff << (8 - length % 8);
    }
    keyAlgorithm = new HmacKeyAlgorithm(hmac.hash.name, length);
  } else {
    requireSecretLength(algorithm.name, length, "DataError");
    keyAlgorithm = algorithm.name === "ChaCha20-Poly1305" ? new KeyAlgorithm(algorithm.name) : new AesKeyAlgorithm(algorithm.name, length);
  }
  const record = provider.importKey(format === "jwk"
    ? { format: "components", components: { family: "secret", k: bytes } }
    : { format: "raw", family: "secret", bytes });
  if ("failure" in record) {
    throw new DOMException("The secret key could not be imported", record.failure === "invalid-key" ? "DataError" : "OperationError");
  }
  secretRecord(record, byteLength);
  return finishSecretKey(record, extractable, keyAlgorithm, usages);
}

/** §§27–31 exports. Components are decoded native bytes, never a provider JWK. */
export function exportSecretKey(provider: CryptoProvider, format: KeyFormat, key: CryptoKeySlots): Uint8Array | JsonWebKey {
  let bytes: Uint8Array;
  if (format === "jwk") {
    const components = provider.exportComponents(key.handle);
    if ("failure" in components || components.family !== "secret") {
      throw new DOMException("The secret key cannot be exported", "OperationError");
    }
    bytes = components.k;
  } else {
    const result = provider.exportKey(key.handle, "raw");
    if ("failure" in result) throw new DOMException("The secret key cannot be exported", "OperationError");
    bytes = result;
  }
  if (format === "raw-secret" || (format === "raw" && key.algorithm.name !== "AES-OCB" && key.algorithm.name !== "ChaCha20-Poly1305")) return bytes;
  if (format !== "jwk") throw new DOMException("This secret-key format is not supported", "NotSupportedError");
  const algorithm = key.algorithm;
  const hmac = algorithm instanceof HmacKeyAlgorithm ? algorithm : undefined;
  const jwk = new JsonWebKey();
  jwk.kty = "oct";
  jwk.k = encodeBase64Url(bytes);
  jwk.alg = jwkAlgorithm(algorithm.name, cryptoViewByteLength(bytes) * 8, hmac?.hash.name as CryptoDigestName | undefined);
  jwk.key_ops = [];
  for (let index = 0; index < key.usages.length; index++) jwk.key_ops[index] = key.usages[index]!;
  jwk.ext = key.extractable;
  return jwk;
}

/** HMAC hashes and constant-time verification remain native whole-input calls. */
export function signHmac(provider: CryptoProvider, key: CryptoKeySlots, bytes: Uint8Array): Uint8Array {
  const hash = (key.algorithm as HmacKeyAlgorithm).hash.name as CryptoDigestName;
  const signature = provider.sign({ name: "HMAC", hash }, key.handle, bytes);
  if ("failure" in signature || signature.kind !== "bytes") throw new DOMException("The HMAC operation failed", "OperationError");
  return signature.bytes;
}

export function verifyHmac(provider: CryptoProvider, key: CryptoKeySlots, signature: Uint8Array, bytes: Uint8Array): boolean {
  const hash = (key.algorithm as HmacKeyAlgorithm).hash.name as CryptoDigestName;
  const result = provider.verify({ name: "HMAC", hash }, key.handle, { kind: "bytes", bytes: signature }, bytes);
  if (typeof result !== "boolean") throw new DOMException("The verification operation failed", "OperationError");
  return result;
}

import { DOMException } from "../core/errors.ts";
import { coerceToBoolean, coerceToDOMString, requireArguments } from "../core/webidl.ts";
import type { CryptoProvider } from "../provider/crypto.ts";
import type { RandomSource, Scheduler } from "../provider/primitives.ts";
import { currentWebPlatformRuntime, hasWebPlatformRuntime } from "../provider/environment.ts";
import { CShakeParams, normalizeAlgorithm, supportsCryptoOperation, toAlgorithmIdentifier } from "./algorithms.ts";
import type { AlgorithmIdentifier, NormalizedAlgorithm } from "./algorithms.ts";
import { decryptAes, encryptAes } from "./aes.ts";
import { decryptAead, encryptAead } from "./aead.ts";
import { cryptoBytes, isCryptoBufferSource, toCryptoBufferSource } from "./buffer-source.ts";
import { getCryptoKeySlots } from "./crypto-key.ts";
import type { CryptoKey, CryptoKeyPair, CryptoKeySlots, KeyUsage } from "./crypto-key.ts";
import { deriveEcBits, signEc, verifyEc } from "./ec.ts";
import { exportEcKey, generateEcKey, importEcKey } from "./ec-key.ts";
import {
  JsonWebKey,
  parseWrappedJwk,
  serializeWrappedJwk,
  toJsonWebKey,
  toJsonWebKeyObject,
  toKeyFormat,
  toKeyUsages,
} from "./jwk.ts";
import type { JsonWebKeyObject, KeyFormat } from "./jwk.ts";
import { deriveKdfBits, getKdfKeyLength, importKdfKey } from "./kdf.ts";
import { deriveOkpBits, signOkp, verifyOkp } from "./okp.ts";
import { exportOkpKey, generateOkpKey, importOkpKey } from "./okp-key.ts";
import { exportMlKey, generateMlKey, importMlKey } from "./ml-key.ts";
import { signMlDsa, verifyMlDsa } from "./ml-dsa.ts";
import { encapsulateMlKem, decapsulateMlKem } from "./ml-kem.ts";
import type { EncapsulatedBits, EncapsulatedKey } from "./ml-kem.ts";
import { isMlAlgorithm, isMlDsaAlgorithm } from "./ml-parameters.ts";
import { derivePublicKey, supportsPublicKey } from "./public-key.ts";
import { decryptRsa, encryptRsa, signRsa, verifyRsa } from "./rsa.ts";
import { exportRsaKey, generateRsaKey, importRsaKey } from "./rsa-key.ts";
import { exportSecretKey, generateSecretKey, getSecretKeyLength, importSecretKey, signHmac, verifyHmac } from "./secret-key.ts";
import { exportKmacKey, generateKmacKey, getKmacKeyLength, importKmacKey, signKmac, verifyKmac } from "./kmac.ts";
