import { cryptoSupports } from "./supports.ts";
import { cryptoCapability } from "./capability.ts";

const constructorToken = Symbol("SubtleCrypto construction");

/**
 * Execute the specification's parallel steps synchronously over native primitives,
 * then settle from one crypto task. Conversion/normalization stays outside this
 * boundary so early IDL errors do not become scheduled operation failures.
 */
function cryptoTask<T>(scheduler: Scheduler, operation: () => T): Promise<T> {
  const pending = Promise.withResolvers<T>();
  try {
    const result = operation();
    scheduler.enqueue(() => pending.resolve(result));
  } catch (error) {
    scheduler.enqueue(() => pending.reject(error));
  }
  return pending.promise;
}

function requireKeyUsage(key: CryptoKeySlots, algorithm: NormalizedAlgorithm, usage: KeyUsage): void {
  let permitted = false;
  for (let index = 0; index < key.usages.length; index++) {
    if (key.usages[index] === usage) permitted = true;
  }
  if (key.algorithm.name !== algorithm.name || !permitted) {
    throw new DOMException("The key does not permit this algorithm and operation", "InvalidAccessError");
  }
}

function requireExportableKey(key: CryptoKeySlots): void {
  if (!supportsCryptoOperation(key.algorithm.name, "exportKey")) {
    throw new DOMException("The key algorithm does not support export", "NotSupportedError");
  }
  if (!key.extractable) throw new DOMException("The key is not extractable", "InvalidAccessError");
}

function normalizeWrappingAlgorithm(identifier: AlgorithmIdentifier, unwrap: boolean): NormalizedAlgorithm {
  // §§14.3.11–12 retry after every normalization error, even an author getter's
  // exception. The fallback therefore performs its own observable dictionary reads.
  try {
    return normalizeAlgorithm(identifier, unwrap ? "unwrapKey" : "wrapKey", unwrap);
  } catch {
    return normalizeAlgorithm(identifier, unwrap ? "decrypt" : "encrypt", unwrap);
  }
}

function isRsaAlgorithm(name: string): boolean {
  return name === "RSASSA-PKCS1-v1_5" || name === "RSA-PSS" || name === "RSA-OAEP";
}

function isEcAlgorithm(name: string): boolean {
  return name === "ECDSA" || name === "ECDH";
}

function isOkpAlgorithm(name: string): boolean {
  return name === "Ed25519" || name === "X25519" || name === "Ed448" || name === "X448";
}

function isKdfAlgorithm(name: string): boolean {
  return name === "HKDF" || name === "PBKDF2" || name === "Argon2d" || name === "Argon2i" || name === "Argon2id";
}

function encryptBytes(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots, bytes: Uint8Array): Uint8Array {
  if (algorithm.name === "AES-OCB" || algorithm.name === "ChaCha20-Poly1305") return encryptAead(provider, algorithm, key, bytes);
  return algorithm.name === "RSA-OAEP"
    ? encryptRsa(provider, algorithm, key, bytes)
    : encryptAes(provider, algorithm, key, bytes);
}

function decryptBytes(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots, bytes: Uint8Array): Uint8Array {
  if (algorithm.name === "AES-OCB" || algorithm.name === "ChaCha20-Poly1305") return decryptAead(provider, algorithm, key, bytes);
  return algorithm.name === "RSA-OAEP"
    ? decryptRsa(provider, algorithm, key, bytes)
    : decryptAes(provider, algorithm, key, bytes);
}

function signBytes(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots, bytes: Uint8Array): Uint8Array {
  if (isMlDsaAlgorithm(algorithm.name)) return signMlDsa(provider, algorithm, key, bytes);
  if (algorithm.name === "Ed25519" || algorithm.name === "Ed448") return signOkp(provider, algorithm, key, bytes);
  if (algorithm.name === "ECDSA") return signEc(provider, algorithm, key, bytes);
  if (algorithm.name === "KMAC128" || algorithm.name === "KMAC256") return signKmac(provider, algorithm, key, bytes);
  if (algorithm.name === "HMAC") return signHmac(provider, key, bytes);
  return signRsa(provider, algorithm, key, bytes);
}

function verifyBytes(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots, signature: Uint8Array, bytes: Uint8Array): boolean {
  if (isMlDsaAlgorithm(algorithm.name)) return verifyMlDsa(provider, algorithm, key, signature, bytes);
  if (algorithm.name === "Ed25519" || algorithm.name === "Ed448") return verifyOkp(provider, algorithm, key, signature, bytes);
  if (algorithm.name === "ECDSA") return verifyEc(provider, algorithm, key, signature, bytes);
  if (algorithm.name === "KMAC128" || algorithm.name === "KMAC256") return verifyKmac(provider, algorithm, key, signature, bytes);
  if (algorithm.name === "HMAC") return verifyHmac(provider, key, signature, bytes);
  return verifyRsa(provider, algorithm, key, signature, bytes);
}

function deriveBytes(provider: CryptoProvider, algorithm: NormalizedAlgorithm, key: CryptoKeySlots, length: number | null): Uint8Array {
  if (isKdfAlgorithm(algorithm.name)) return deriveKdfBits(provider, algorithm, key, length);
  return algorithm.name === "X25519" || algorithm.name === "X448" ? deriveOkpBits(provider, algorithm, key, length)
    : deriveEcBits(provider, algorithm, key, length);
}

function importKeyMaterial(
  provider: CryptoProvider,
  format: KeyFormat,
  data: Uint8Array | JsonWebKey,
  algorithm: NormalizedAlgorithm,
  extractable: boolean,
  usages: readonly KeyUsage[],
): CryptoKey {
  if (algorithm.name === "KMAC128" || algorithm.name === "KMAC256") return importKmacKey(provider, format, data, algorithm, extractable, usages);
  if (isMlAlgorithm(algorithm.name)) return importMlKey(provider, format, data, algorithm, extractable, usages);
  if (format === "raw-public" && (isOkpAlgorithm(algorithm.name) || isEcAlgorithm(algorithm.name) || isRsaAlgorithm(algorithm.name))) format = "raw";
  if (isKdfAlgorithm(algorithm.name)) return importKdfKey(provider, format, data, algorithm, extractable, usages);
  if (isOkpAlgorithm(algorithm.name)) return importOkpKey(provider, format, data, algorithm, extractable, usages);
  if (isEcAlgorithm(algorithm.name)) return importEcKey(provider, format, data, algorithm, extractable, usages);
  if (isRsaAlgorithm(algorithm.name)) return importRsaKey(provider, format, data, algorithm, extractable, usages);
  return importSecretKey(provider, format, data, algorithm, extractable, usages);
}

function exportKeyMaterial(provider: CryptoProvider, format: KeyFormat, key: CryptoKeySlots): Uint8Array | JsonWebKey {
  if (key.algorithm.name === "KMAC128" || key.algorithm.name === "KMAC256") return exportKmacKey(provider, format, key);
  if (isMlAlgorithm(key.algorithm.name)) return exportMlKey(provider, format, key);
  if (format === "raw-public" && (isOkpAlgorithm(key.algorithm.name) || isEcAlgorithm(key.algorithm.name) || isRsaAlgorithm(key.algorithm.name))) format = "raw";
  if (isOkpAlgorithm(key.algorithm.name)) return exportOkpKey(provider, format, key);
  if (isEcAlgorithm(key.algorithm.name)) return exportEcKey(provider, format, key);
  if (isRsaAlgorithm(key.algorithm.name)) return exportRsaKey(provider, format, key);
  return exportSecretKey(provider, format, key);
}

/**
 * Web Cryptography §14 and Secure Curves: shared key, cipher, signature and derivation operations.
 * Members are plain declarations; descriptor-only Web IDL shape is deferred.
 */
export class SubtleCrypto {
  get [Symbol.toStringTag](): string { return "SubtleCrypto"; }

  readonly #provider: CryptoProvider;
  readonly #scheduler: Scheduler;
  readonly #random: RandomSource;

  /** Web IDL supplies no public constructor or capability-injection arguments. */
  constructor(
    token: symbol | undefined = undefined,
    provider?: CryptoProvider,
    scheduler?: Scheduler,
    random?: RandomSource,
  ) {
    if (token !== constructorToken || provider === undefined || scheduler === undefined || random === undefined) {
      throw new TypeError("Illegal constructor");
    }
    this.#provider = provider;
    this.#scheduler = scheduler;
    this.#random = random;
  }

  /** Modern Algorithms §3.2.6; Web IDL §§3.6 and 3.7.7 static operation binding. */
  static supports(operation: unknown, algorithm: unknown, lengthOrAdditionalAlgorithm: unknown = null): boolean {
    requireArguments(arguments, 2, "SubtleCrypto.supports");
    const operationName = coerceToDOMString(operation);
    const identifier = toAlgorithmIdentifier(algorithm);
    let length: number | null = null;
    let additional: AlgorithmIdentifier | undefined;
    // The overload is selected by the third value's type, independently of the
    // operation name. IDL conversion errors precede the method's false result.
    if (lengthOrAdditionalAlgorithm !== null && lengthOrAdditionalAlgorithm !== undefined) {
      if (typeof lengthOrAdditionalAlgorithm === "number") length = toCryptoUnsignedInteger(lengthOrAdditionalAlgorithm, 32);
      else additional = toAlgorithmIdentifier(lengthOrAdditionalAlgorithm);
    }
    const crypto = hasWebPlatformRuntime() ? currentWebPlatformRuntime().crypto : undefined;
    const provider = crypto === undefined ? undefined : cryptoCapability(crypto);
    return cryptoSupports(provider, operationName, identifier, length, additional);
  }

  /** §14.3.5 and §32, https://w3c.github.io/webcrypto/#SubtleCrypto-method-digest. */
  digest(algorithm: unknown, data: unknown): Promise<ArrayBuffer> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 2, "SubtleCrypto.digest");
      const identifier = toAlgorithmIdentifier(algorithm);
      const source = toCryptoBufferSource(data);
      const normalized = normalizeAlgorithm(identifier, "digest");
      const bytes = cryptoBytes(source);
      return cryptoTask(scheduler, () => {
        const digest = normalized instanceof CShakeParams
          ? provider.digestXof({ name: normalized.name, outputLength: normalized.outputLength,
              functionName: normalized.functionName ?? new Uint8Array(0), customization: normalized.customization ?? new Uint8Array(0) }, bytes)
          : provider.digest(normalized.name, bytes);
        if ("failure" in digest || (normalized instanceof CShakeParams && digest.byteLength !== Math.ceil(normalized.outputLength / 8))) {
          throw new DOMException("The digest operation failed", "OperationError");
        }
        return digest.buffer as ArrayBuffer;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.1. All IDL arguments convert before algorithm normalization. */
  encrypt(algorithm: unknown, key: unknown, data: unknown): Promise<ArrayBuffer> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 3, "SubtleCrypto.encrypt");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(key);
      const source = toCryptoBufferSource(data);
      const normalized = normalizeAlgorithm(identifier, "encrypt");
      const bytes = cryptoBytes(source);
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "encrypt");
        return encryptBytes(provider, normalized, slots, bytes).buffer as ArrayBuffer;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.2. */
  decrypt(algorithm: unknown, key: unknown, data: unknown): Promise<ArrayBuffer> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 3, "SubtleCrypto.decrypt");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(key);
      const source = toCryptoBufferSource(data);
      const normalized = normalizeAlgorithm(identifier, "decrypt");
      const bytes = cryptoBytes(source);
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "decrypt");
        return decryptBytes(provider, normalized, slots, bytes).buffer as ArrayBuffer;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.3 and the registered HMAC/RSA/ECDSA/EdDSA signing operation. */
  sign(algorithm: unknown, key: unknown, data: unknown): Promise<ArrayBuffer> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 3, "SubtleCrypto.sign");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(key);
      const source = toCryptoBufferSource(data);
      const normalized = normalizeAlgorithm(identifier, "sign");
      const bytes = cryptoBytes(source);
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "sign");
        return signBytes(provider, normalized, slots, bytes).buffer as ArrayBuffer;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.4; the primitive checks signatures and performs constant-time MAC comparison. */
  verify(algorithm: unknown, key: unknown, signature: unknown, data: unknown): Promise<boolean> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 4, "SubtleCrypto.verify");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(key);
      const signatureSource = toCryptoBufferSource(signature);
      const dataSource = toCryptoBufferSource(data);
      const normalized = normalizeAlgorithm(identifier, "verify");
      const signatureBytes = cryptoBytes(signatureSource);
      const dataBytes = cryptoBytes(dataSource);
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "verify");
        return verifyBytes(provider, normalized, slots, signatureBytes, dataBytes);
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.6. */
  generateKey(algorithm: unknown, extractable: unknown, keyUsages: unknown): Promise<CryptoKey | CryptoKeyPair> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      const random = this.#random;
      requireArguments(arguments, 3, "SubtleCrypto.generateKey");
      const identifier = toAlgorithmIdentifier(algorithm);
      const canExport = coerceToBoolean(extractable);
      const usages = toKeyUsages(keyUsages);
      const normalized = normalizeAlgorithm(identifier, "generateKey");
      return cryptoTask<CryptoKey | CryptoKeyPair>(scheduler, () => {
        if (normalized.name === "KMAC128" || normalized.name === "KMAC256") return generateKmacKey(provider, random, normalized, canExport, usages);
        if (isMlAlgorithm(normalized.name)) return generateMlKey(provider, normalized, canExport, usages);
        if (isOkpAlgorithm(normalized.name)) return generateOkpKey(provider, normalized, canExport, usages);
        if (isEcAlgorithm(normalized.name)) return generateEcKey(provider, normalized, canExport, usages);
        if (isRsaAlgorithm(normalized.name)) return generateRsaKey(provider, normalized, canExport, usages);
        return generateSecretKey(provider, random, normalized, canExport, usages);
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.7. Normalize import and key length separately, in the specified order. */
  deriveKey(algorithm: unknown, baseKey: unknown, derivedKeyType: unknown, extractable: unknown, keyUsages: unknown): Promise<CryptoKey> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 5, "SubtleCrypto.deriveKey");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(baseKey);
      const derivedIdentifier = toAlgorithmIdentifier(derivedKeyType);
      const canExport = coerceToBoolean(extractable);
      const usages = toKeyUsages(keyUsages);
      const normalized = normalizeAlgorithm(identifier, "deriveBits", true);
      const normalizedImport = normalizeAlgorithm(derivedIdentifier, "importKey", true);
      const normalizedLength = normalizeAlgorithm(derivedIdentifier, "get key length");
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "deriveKey");
        const length = isKdfAlgorithm(normalizedLength.name) ? getKdfKeyLength()
          : normalizedLength.name === "KMAC128" || normalizedLength.name === "KMAC256" ? getKmacKeyLength(normalizedLength)
            : getSecretKeyLength(normalizedLength);
        const secret = deriveBytes(provider, normalized, slots, length);
        return importKeyMaterial(provider, "raw-secret", secret, normalizedImport, canExport, usages);
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.8. Algorithms decide whether an omitted or null length is supported. */
  deriveBits(algorithm: unknown, baseKey: unknown, length: unknown = null): Promise<ArrayBuffer> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 2, "SubtleCrypto.deriveBits");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(baseKey);
      const bitLength = length === null || length === undefined ? null : toCryptoUnsignedInteger(length, 32);
      const normalized = normalizeAlgorithm(identifier, "deriveBits");
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "deriveBits");
        return deriveBytes(provider, normalized, slots, bitLength).buffer as ArrayBuffer;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.9. The IDL key-data union is resolved before inspecting format. */
  importKey(format: unknown, keyData: unknown, algorithm: unknown, extractable: unknown, keyUsages: unknown): Promise<CryptoKey> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 5, "SubtleCrypto.importKey");
      const keyFormat = toKeyFormat(format);
      const source = isCryptoBufferSource(keyData) ? toCryptoBufferSource(keyData) : toJsonWebKey(keyData);
      const identifier = toAlgorithmIdentifier(algorithm);
      const canExport = coerceToBoolean(extractable);
      const usages = toKeyUsages(keyUsages);
      const normalized = normalizeAlgorithm(identifier, "importKey");
      const dictionary = source instanceof JsonWebKey;
      if ((keyFormat === "jwk") !== dictionary) throw new TypeError("The key data does not match its format");
      const data = dictionary ? source : cryptoBytes(source);
      return cryptoTask(scheduler, () => importKeyMaterial(provider, keyFormat, data, normalized, canExport, usages));
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** Modern Algorithms §3.2.1: import the complete shared secret as raw-secret. */
  encapsulateKey(algorithm: unknown, key: unknown, sharedKeyAlgorithm: unknown,
    extractable: unknown, keyUsages: unknown): Promise<EncapsulatedKey> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 5, "SubtleCrypto.encapsulateKey");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(key);
      const sharedIdentifier = toAlgorithmIdentifier(sharedKeyAlgorithm);
      const canExport = coerceToBoolean(extractable);
      const usages = toKeyUsages(keyUsages);
      const normalized = normalizeAlgorithm(identifier, "encapsulate", true);
      const normalizedImport = normalizeAlgorithm(sharedIdentifier, "importKey");
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "encapsulateKey");
        const result = encapsulateMlKem(provider, normalized, slots);
        const sharedKey = importKeyMaterial(provider, "raw-secret", result.sharedKey, normalizedImport, canExport, usages);
        if (usages.length === 0) throw new DOMException("A shared key must have a usage", "SyntaxError");
        return { ciphertext: result.ciphertext.buffer as ArrayBuffer, sharedKey };
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** Modern Algorithms §3.2.2: native outputs become a fresh ordinary dictionary. */
  encapsulateBits(algorithm: unknown, key: unknown): Promise<EncapsulatedBits> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 2, "SubtleCrypto.encapsulateBits");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(key);
      const normalized = normalizeAlgorithm(identifier, "encapsulate");
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "encapsulateBits");
        const result = encapsulateMlKem(provider, normalized, slots);
        return { ciphertext: result.ciphertext.buffer as ArrayBuffer, sharedKey: result.sharedKey.buffer as ArrayBuffer };
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** Modern Algorithms §3.2.3: normalize both algorithms before ciphertext bytes. */
  decapsulateKey(algorithm: unknown, key: unknown, ciphertext: unknown,
    sharedKeyAlgorithm: unknown, extractable: unknown, keyUsages: unknown): Promise<CryptoKey> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 6, "SubtleCrypto.decapsulateKey");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(key);
      const source = toCryptoBufferSource(ciphertext);
      const sharedIdentifier = toAlgorithmIdentifier(sharedKeyAlgorithm);
      const canExport = coerceToBoolean(extractable);
      const usages = toKeyUsages(keyUsages);
      const normalized = normalizeAlgorithm(identifier, "decapsulate", true);
      const normalizedImport = normalizeAlgorithm(sharedIdentifier, "importKey");
      const bytes = cryptoBytes(source);
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "decapsulateKey");
        const secret = decapsulateMlKem(provider, normalized, slots, bytes);
        const sharedKey = importKeyMaterial(provider, "raw-secret", secret, normalizedImport, canExport, usages);
        if (usages.length === 0) throw new DOMException("A shared key must have a usage", "SyntaxError");
        return sharedKey;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** Modern Algorithms §3.2.4: input checks precede the single native operation. */
  decapsulateBits(algorithm: unknown, key: unknown, ciphertext: unknown): Promise<ArrayBuffer> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 3, "SubtleCrypto.decapsulateBits");
      const identifier = toAlgorithmIdentifier(algorithm);
      const slots = getCryptoKeySlots(key);
      const source = toCryptoBufferSource(ciphertext);
      const normalized = normalizeAlgorithm(identifier, "decapsulate");
      const bytes = cryptoBytes(source);
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "decapsulateBits");
        return decapsulateMlKem(provider, normalized, slots, bytes).buffer as ArrayBuffer;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** Modern Algorithms §3.2.5; algorithm support precedes private-key type checks. */
  getPublicKey(key: unknown, keyUsages: unknown): Promise<CryptoKey> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 2, "SubtleCrypto.getPublicKey");
      const slots = getCryptoKeySlots(key);
      const usages = toKeyUsages(keyUsages);
      if (!supportsPublicKey(slots.algorithm.name)) throw new DOMException("The algorithm has no public key", "NotSupportedError");
      return cryptoTask(scheduler, () => derivePublicKey(provider, slots, usages));
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.10. Algorithm support precedes extractability, then format policy. */
  exportKey(format: unknown, key: unknown): Promise<ArrayBuffer | JsonWebKeyObject> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 2, "SubtleCrypto.exportKey");
      const keyFormat = toKeyFormat(format);
      const slots = getCryptoKeySlots(key);
      return cryptoTask(scheduler, () => {
        requireExportableKey(slots);
        const result = exportKeyMaterial(provider, keyFormat, slots);
        return result instanceof JsonWebKey ? toJsonWebKeyObject(result) : result.buffer as ArrayBuffer;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.11. Wrapping requires wrapKey usage, independently of encrypt usage. */
  wrapKey(format: unknown, key: unknown, wrappingKey: unknown, wrapAlgorithm: unknown): Promise<ArrayBuffer> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 4, "SubtleCrypto.wrapKey");
      const keyFormat = toKeyFormat(format);
      const slots = getCryptoKeySlots(key);
      const wrappingSlots = getCryptoKeySlots(wrappingKey);
      const identifier = toAlgorithmIdentifier(wrapAlgorithm);
      const normalized = normalizeWrappingAlgorithm(identifier, false);
      return cryptoTask(scheduler, () => {
        requireKeyUsage(wrappingSlots, normalized, "wrapKey");
        requireExportableKey(slots);
        const exported = exportKeyMaterial(provider, keyFormat, slots);
        // Serializing our generated key dictionary invokes no author code, so
        // the normalized parameters can stay borrowed on this operation.
        const bytes = exported instanceof JsonWebKey
          ? serializeWrappedJwk(exported, normalized.name === "AES-KW") : exported;
        return encryptBytes(provider, normalized, wrappingSlots, bytes).buffer as ArrayBuffer;
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }

  /** §14.3.12. Unwrap parameters are snapshotted before the second normalization. */
  unwrapKey(
    format: unknown,
    wrappedKey: unknown,
    unwrappingKey: unknown,
    unwrapAlgorithm: unknown,
    unwrappedKeyAlgorithm: unknown,
    extractable: unknown,
    keyUsages: unknown,
  ): Promise<CryptoKey> {
    try {
      const provider = this.#provider;
      const scheduler = this.#scheduler;
      requireArguments(arguments, 7, "SubtleCrypto.unwrapKey");
      const keyFormat: KeyFormat = toKeyFormat(format);
      const source = toCryptoBufferSource(wrappedKey);
      const slots = getCryptoKeySlots(unwrappingKey);
      const identifier = toAlgorithmIdentifier(unwrapAlgorithm);
      const keyIdentifier = toAlgorithmIdentifier(unwrappedKeyAlgorithm);
      const canExport = coerceToBoolean(extractable);
      const usages = toKeyUsages(keyUsages);
      const normalized = normalizeWrappingAlgorithm(identifier, true);
      const normalizedKey = normalizeAlgorithm(keyIdentifier, "importKey");
      const wrappedBytes = cryptoBytes(source);
      return cryptoTask(scheduler, () => {
        requireKeyUsage(slots, normalized, "unwrapKey");
        const bytes = decryptBytes(provider, normalized, slots, wrappedBytes);
        const data = keyFormat === "jwk" ? parseWrappedJwk(bytes) : bytes;
        return importKeyMaterial(provider, keyFormat, data, normalizedKey, canExport, usages);
      });
    } catch (error) {
      return Promise.reject(error);
    }
  }
}

/** Internal embedding factory; only trusted assembly supplies native capabilities. */
export function createSubtleCrypto(provider: CryptoProvider, scheduler: Scheduler, random: RandomSource): SubtleCrypto {
  return new SubtleCrypto(constructorToken, provider, scheduler, random);
}

import type {
  CryptoDigestName, CryptoProvider, CryptoSupportOperation, CryptoSupportParameters,
} from "../provider/crypto.ts";
import {
  AeadParams, AesCbcParams, AesCtrParams, AesDerivedKeyParams, AesGcmParams, AesKeyGenParams,
  Argon2Params, ContextParams, CShakeParams, DigestAlgorithm, EcdhKeyDeriveParams, EcdsaParams,
  EcKeyGenParams, EcKeyImportParams, Ed448Params, HkdfParams, HmacImportParams, HmacKeyGenParams,
  KmacImportParams, KmacKeyGenParams, KmacParams, normalizeAlgorithm, Pbkdf2Params,
  RsaHashedImportParams, RsaHashedKeyGenParams, RsaOaepParams, RsaPssParams,
} from "./algorithms.ts";
import type { AlgorithmIdentifier, CryptoOperation, NormalizedAlgorithm } from "./algorithms.ts";
import { cryptoViewByteLength } from "./buffer-source.ts";
import { getCryptoKeySlots } from "./crypto-key.ts";
import { EcKeyAlgorithm } from "./ec-key.ts";
import { getKdfKeyLength } from "./kdf.ts";
import { getKmacKeyLength } from "./kmac.ts";
import { getMlKemSharedKeyLength } from "./ml-parameters.ts";
import { supportsPublicKey } from "./public-key.ts";
import { rsaGenerationExponent } from "./rsa-key.ts";
import { getSecretKeyLength, hmacDefaultLength } from "./secret-key.ts";

type SupportOperation = CryptoSupportOperation | "deriveKey" | "encapsulateKey" | "encapsulateBits"
  | "decapsulateKey" | "decapsulateBits";

function publicOperation(value: string): value is SupportOperation {
  switch (value) {
    case "encrypt": case "decrypt": case "sign": case "verify": case "digest":
    case "generateKey": case "deriveKey": case "deriveBits": case "importKey": case "exportKey":
    case "wrapKey": case "unwrapKey": case "encapsulateKey": case "encapsulateBits":
    case "decapsulateKey": case "decapsulateBits": case "getPublicKey": return true;
    default: return false;
  }
}

function optionalBytes(bytes: Uint8Array | undefined): number {
  return bytes === undefined ? 0 : cryptoViewByteLength(bytes);
}

function aesLength(length: number): boolean {
  return length === 128 || length === 192 || length === 256;
}

function hashBits(hash: CryptoDigestName): number {
  if (hash === "SHA-1") return 160;
  if (hash === "SHA-256" || hash === "SHA3-256") return 256;
  return hash === "SHA-384" || hash === "SHA3-384" ? 384 : 512;
}

/**
 * Modern Algorithms §3.3. Walk the parameter-only operation steps, stopping
 * before key/data-dependent work. The native query receives scalar metadata
 * and borrowed public RSA exponent bytes, never author objects, CryptoKeys,
 * messages, secrets or BufferSource copies.
 */
function supportParameters(
  algorithm: NormalizedAlgorithm, operation: CryptoSupportOperation, length: number | null,
): CryptoSupportParameters | undefined {
  const name = algorithm.name;
  if (algorithm instanceof DigestAlgorithm) return { kind: "digest", name: algorithm.name };
  if (algorithm instanceof CShakeParams) {
    return { kind: "cshake", name: algorithm.name, outputBits: algorithm.outputLength,
      functionNameBytes: optionalBytes(algorithm.functionName), customizationBytes: optionalBytes(algorithm.customization) };
  }
  if (name === "AES-CTR" || name === "AES-CBC" || name === "AES-GCM" || name === "AES-KW"
    || name === "AES-OCB" || name === "ChaCha20-Poly1305") {
    let keyBits: number | undefined;
    let ivBytes: number | undefined;
    let additionalDataBytes: number | undefined;
    let counterBits: number | undefined;
    let tagBits: number | undefined;
    if (algorithm instanceof AesKeyGenParams || algorithm instanceof AesDerivedKeyParams) {
      if (!aesLength(algorithm.length)) return undefined;
      keyBits = algorithm.length;
    } else if (name === "ChaCha20-Poly1305") keyBits = 256;
    if (algorithm instanceof AesCtrParams) {
      ivBytes = cryptoViewByteLength(algorithm.counter);
      counterBits = algorithm.length;
      if (ivBytes !== 16 || counterBits === 0 || counterBits > 128) return undefined;
    } else if (algorithm instanceof AesCbcParams) {
      ivBytes = cryptoViewByteLength(algorithm.iv);
      if (ivBytes !== 16) return undefined;
    } else if (algorithm instanceof AesGcmParams) {
      ivBytes = cryptoViewByteLength(algorithm.iv);
      additionalDataBytes = optionalBytes(algorithm.additionalData);
      tagBits = algorithm.tagLength ?? 128;
      if (ivBytes >= 2 ** 64 || additionalDataBytes >= 2 ** 64) return undefined;
      if (tagBits !== 32 && tagBits !== 64 && tagBits !== 96 && tagBits !== 104
        && tagBits !== 112 && tagBits !== 120 && tagBits !== 128) return undefined;
    } else if (algorithm instanceof AeadParams) {
      ivBytes = cryptoViewByteLength(algorithm.iv);
      additionalDataBytes = optionalBytes(algorithm.additionalData);
      tagBits = algorithm.tagLength ?? 128;
      if (name === "AES-OCB") {
        if (ivBytes > 15 || (tagBits !== 64 && tagBits !== 96 && tagBits !== 128)) return undefined;
      } else if (ivBytes !== 12 || tagBits !== 128) return undefined;
    }
    return { kind: "cipher", name, keyBits, ivBytes, additionalDataBytes, counterBits, tagBits };
  }
  if (name === "HMAC") {
    let hash: CryptoDigestName | undefined;
    let keyBits: number | undefined;
    if (algorithm instanceof HmacKeyGenParams || algorithm instanceof HmacImportParams) {
      hash = algorithm.hash.name;
      keyBits = algorithm.length;
      if (operation === "generateKey") {
        keyBits ??= hmacDefaultLength(hash);
        if (keyBits === 0) return undefined;
      }
    }
    return { kind: "hmac", name, hash, keyBits };
  }
  if (name === "KMAC128" || name === "KMAC256") {
    const keyBits = algorithm instanceof KmacKeyGenParams
      ? algorithm.length ?? (name === "KMAC128" ? 128 : 256)
      : algorithm instanceof KmacImportParams ? algorithm.length : undefined;
    const outputBits = algorithm instanceof KmacParams ? algorithm.outputLength : undefined;
    const customizationBytes = algorithm instanceof KmacParams ? optionalBytes(algorithm.customization) : undefined;
    // §16.6 permits a byte-oriented output profile. Key bit lengths are separate.
    if (outputBits !== undefined && outputBits % 8 !== 0) return undefined;
    return { kind: "kmac", name, keyBits, outputBits, customizationBytes };
  }
  if (name === "RSASSA-PKCS1-v1_5" || name === "RSA-PSS" || name === "RSA-OAEP") {
    const generation = algorithm instanceof RsaHashedKeyGenParams ? algorithm : undefined;
    return { kind: "rsa", name,
      hash: algorithm instanceof RsaHashedKeyGenParams || algorithm instanceof RsaHashedImportParams ? algorithm.hash.name : undefined,
      modulusBits: generation?.modulusLength,
      publicExponent: generation === undefined ? undefined : rsaGenerationExponent(generation),
      saltBytes: algorithm instanceof RsaPssParams ? algorithm.saltLength : undefined,
      labelBytes: algorithm instanceof RsaOaepParams ? optionalBytes(algorithm.label) : undefined };
  }
  if (name === "ECDSA" || name === "ECDH") {
    let namedCurve: string | undefined;
    if (algorithm instanceof EcKeyGenParams || algorithm instanceof EcKeyImportParams) {
      namedCurve = algorithm.namedCurve;
      if (namedCurve !== "P-256" && namedCurve !== "P-384" && namedCurve !== "P-521") return undefined;
    } else if (algorithm instanceof EcdhKeyDeriveParams) {
      const peer = getCryptoKeySlots(algorithm.public);
      if (peer.type !== "public" || peer.algorithm.name !== name || !(peer.algorithm instanceof EcKeyAlgorithm)) return undefined;
      namedCurve = peer.algorithm.namedCurve;
      const maximum = namedCurve === "P-256" ? 256 : namedCurve === "P-384" ? 384 : 528;
      if (length !== null && length > maximum) return undefined;
    }
    return { kind: "ec", name, namedCurve, hash: algorithm instanceof EcdsaParams ? algorithm.hash.name : undefined };
  }
  if (name === "Ed25519" || name === "Ed448" || name === "X25519" || name === "X448") {
    // X25519's peer and length checks precede the unavailable base key (§26.3.1).
    if (name === "X25519" && algorithm instanceof EcdhKeyDeriveParams) {
      const peer = getCryptoKeySlots(algorithm.public);
      if (peer.type !== "public" || peer.algorithm.name !== name || (length !== null && length > 256)) return undefined;
    }
    return { kind: "okp", name, contextBytes: algorithm instanceof Ed448Params ? optionalBytes(algorithm.context) : undefined };
  }
  if (name === "HKDF" || name === "PBKDF2") {
    if (operation === "deriveBits") {
      if (length === null || length % 8 !== 0) return undefined;
      if (algorithm instanceof HkdfParams && length > 255 * hashBits(algorithm.hash.name)) return undefined;
      if (algorithm instanceof Pbkdf2Params && algorithm.iterations === 0) return undefined;
    }
    return { kind: "kdf", name,
      hash: algorithm instanceof HkdfParams || algorithm instanceof Pbkdf2Params ? algorithm.hash.name : undefined,
      saltBytes: algorithm instanceof HkdfParams || algorithm instanceof Pbkdf2Params ? cryptoViewByteLength(algorithm.salt) : undefined,
      infoBytes: algorithm instanceof HkdfParams ? cryptoViewByteLength(algorithm.info) : undefined,
      iterations: algorithm instanceof Pbkdf2Params ? algorithm.iterations : undefined };
  }
  if (name === "Argon2d" || name === "Argon2i" || name === "Argon2id") {
    const parameters = algorithm instanceof Argon2Params ? algorithm : undefined;
    if (operation === "deriveBits" && parameters !== undefined) {
      if (length === null || length % 8 !== 0 || length < 32
        || (parameters.version !== undefined && parameters.version !== 0x13)
        || parameters.parallelism === 0 || parameters.parallelism > 0xff_ffff
        || parameters.memory < 8 * parameters.parallelism || parameters.passes === 0) return undefined;
    }
    return { kind: "argon2", name, nonceBytes: parameters === undefined ? undefined : cryptoViewByteLength(parameters.nonce),
      parallelism: parameters?.parallelism, memory: parameters?.memory, passes: parameters?.passes,
      secretBytes: parameters === undefined ? undefined : optionalBytes(parameters.secretValue),
      associatedDataBytes: parameters === undefined ? undefined : optionalBytes(parameters.associatedData) };
  }
  if (name === "ML-DSA-44" || name === "ML-DSA-65" || name === "ML-DSA-87"
    || name === "ML-KEM-512" || name === "ML-KEM-768" || name === "ML-KEM-1024") {
    const contextBytes = algorithm instanceof ContextParams ? optionalBytes(algorithm.context) : undefined;
    // §§8.4.1–2 check the context before the unavailable key. Section 3.3
    // therefore rejects this bound in shared policy, before native availability.
    if (contextBytes !== undefined && contextBytes > 255) return undefined;
    return { kind: "ml", name, contextBytes };
  }
  return undefined;
}

function determineSupport(
  provider: CryptoProvider | undefined, operation: CryptoSupportOperation,
  algorithm: NormalizedAlgorithm, length: number | null,
): boolean {
  if (provider === undefined) return false;
  const parameters = supportParameters(algorithm, operation, length);
  if (parameters === undefined) return false;
  return provider.supports({ operation, parameters, length: operation === "deriveBits" ? length : null }) === true;
}

function checkSupport(
  provider: CryptoProvider | undefined, operation: SupportOperation,
  identifier: AlgorithmIdentifier, length: number | null = null,
): boolean {
  let normalizedOperation: CryptoOperation;
  if (operation === "encapsulateKey" || operation === "encapsulateBits") normalizedOperation = "encapsulate";
  else if (operation === "decapsulateKey" || operation === "decapsulateBits") normalizedOperation = "decapsulate";
  else normalizedOperation = operation === "getPublicKey" ? "exportKey" : operation;
  let algorithm: NormalizedAlgorithm;
  try {
    algorithm = normalizeAlgorithm(identifier, normalizedOperation);
  } catch {
    // §3.3 retries every normalization failure; the fallback reads the original
    // author dictionary anew and can therefore succeed after an earlier throw.
    if (operation === "wrapKey") return checkSupport(provider, "encrypt", identifier);
    if (operation === "unwrapKey") return checkSupport(provider, "decrypt", identifier);
    return false;
  }
  if (operation === "getPublicKey") {
    return supportsPublicKey(algorithm.name) && determineSupport(provider, operation, algorithm, null);
  }
  // No algorithm registers the public deriveKey operation; its additional-
  // algorithm overload below composes get-key-length and deriveBits instead.
  if (normalizedOperation === "deriveKey") return false;
  try {
    return determineSupport(provider, normalizedOperation, algorithm, length);
  } catch {
    // Parameter-only operation steps (including RSA mathematical bounds and
    // the supported HMAC default profile) turn their specified errors into false.
    return false;
  }
}

function derivedKeyLength(algorithm: NormalizedAlgorithm): number | null {
  const name = algorithm.name;
  if (name === "HKDF" || name === "PBKDF2" || name === "Argon2d" || name === "Argon2i" || name === "Argon2id") return getKdfKeyLength();
  return name === "KMAC128" || name === "KMAC256" ? getKmacKeyLength(algorithm) : getSecretKeyLength(algorithm);
}

function checkKeyLength(identifier: AlgorithmIdentifier): boolean {
  try {
    derivedKeyLength(normalizeAlgorithm(identifier, "get key length"));
    return true;
  } catch { return false; }
}

/** §3.2.6 step 3.7: some complete shared secret must be importable as raw-secret. */
function acceptsSharedKey(algorithm: NormalizedAlgorithm, length: number): boolean {
  const name = algorithm.name;
  if (name === "AES-CTR" || name === "AES-CBC" || name === "AES-GCM" || name === "AES-KW" || name === "AES-OCB") return aesLength(length);
  if (name === "ChaCha20-Poly1305") return length === 256;
  if (algorithm instanceof HmacImportParams || algorithm instanceof KmacImportParams) {
    return algorithm.length === undefined || (algorithm.length <= length && algorithm.length > length - 8);
  }
  return name === "HKDF" || name === "PBKDF2" || name === "Argon2d" || name === "Argon2i" || name === "Argon2id";
}

/**
 * Modern Algorithms §§3.2.6–3.3, after Web IDL's overload/argument conversion.
 * Each native query is metadata only. A composed check queries the target first
 * and stops on false before the primary operation's normalization/query. KEM
 * composition first normalizes its algorithm to obtain the shared-key length.
 * https://wicg.github.io/webcrypto-modern-algos/#SubtleCrypto-method-supports
 */
export function cryptoSupports(
  provider: CryptoProvider | undefined, operation: string, identifier: AlgorithmIdentifier,
  length: number | null, additionalAlgorithm: AlgorithmIdentifier | undefined,
): boolean {
  if (!publicOperation(operation)) return false;
  if (additionalAlgorithm === undefined) return checkSupport(provider, operation, identifier, length);
  if (operation === "deriveKey" || operation === "unwrapKey") {
    if (!checkSupport(provider, "importKey", additionalAlgorithm)) return false;
  } else if (operation === "wrapKey") {
    if (!checkSupport(provider, "exportKey", additionalAlgorithm)) return false;
  } else if (operation === "encapsulateKey" || operation === "decapsulateKey") {
    try { normalizeAlgorithm(identifier, "get shared key length"); }
    catch { return false; }
    const sharedKeyLength = getMlKemSharedKeyLength();
    let additional: NormalizedAlgorithm;
    try { additional = normalizeAlgorithm(additionalAlgorithm, "importKey"); }
    catch { return false; }
    if (!determineSupport(provider, "importKey", additional, null) || !acceptsSharedKey(additional, sharedKeyLength)) return false;
  }
  if (operation === "deriveKey") {
    if (!checkKeyLength(additionalAlgorithm)) return false;
    // The final normalization is a distinct specified step, not the normalized
    // dictionary from the earlier support check. Its abrupt completion propagates.
    length = derivedKeyLength(normalizeAlgorithm(additionalAlgorithm, "get key length"));
    return checkSupport(provider, "deriveBits", identifier, length);
  }
  return checkSupport(provider, operation, identifier, null);
}

/**
 * Crypto's [EnforceRange] octet, unsigned short and unsigned long conversions.
 * Local to this feature because core/webidl.ts is owned by another task.
 * https://webidl.spec.whatwg.org/#abstract-opdef-converttoint
 */
export function toCryptoUnsignedInteger(value: unknown, bits: 8 | 16 | 32): number {
  // Unary + performs ToNumber, including rejecting BigInt and Symbol. Number()
  // would incorrectly accept BigInt. The assertion changes no runtime behavior.
  const number = +(value as number);
  if (!Number.isFinite(number)) throw new TypeError("Expected a finite unsigned integer");
  const integer = Math.trunc(number);
  const maximum = bits === 8 ? 255 : bits === 16 ? 65_535 : 4_294_967_295;
  if (integer < 0 || integer > maximum) throw new TypeError("Unsigned integer is outside its range");
  return integer === 0 ? 0 : integer;
}

import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";

export interface OriginDispatcherStats {
  readonly connections: number;
  readonly pending: number;
  readonly running: number;
}

/** A provider dispatcher dedicated to one canonical HTTP(S) origin. */
export interface OriginDispatcher extends FetchTransport {
  /** True only when eviction cannot interrupt a request or live response body. */
  readonly idle: boolean;
  readonly stats: OriginDispatcherStats;

  close(): Promise<void>;

  destroy(reason: unknown): Promise<void>;
}

/** Provider-owned protocol/connection selection for one origin. */
export interface OriginDispatcherFactory {
  create(origin: string): OriginDispatcher;
}

export interface AgentOptions {
  readonly factory: OriginDispatcherFactory;
  /** Bounds retained origin dispatchers. Infinity disables the bound. */
  readonly maximumOrigins?: number;
  /** Bounds requests waiting to create or replace an origin dispatcher. */
  readonly maximumPendingOrigins?: number;
}

export interface AgentOriginStats extends OriginDispatcherStats {
  readonly origin: string;
  readonly idle: boolean;
}

export interface AgentStats {
  readonly origins: number;
  readonly idleOrigins: number;
  readonly connections: number;
  readonly pending: number;
  readonly running: number;
  readonly dispatched: number;
  readonly evicted: number;
  readonly pendingOriginAcquisitions: number;
  readonly entries: readonly AgentOriginStats[];
}

interface AgentRecord {
  readonly origin: string;
  readonly dispatcher: OriginDispatcher;
}

export class AgentOriginLimitError extends Error {
  readonly code = "UND_ERR_MAX_ORIGINS_REACHED";
  readonly maximumOrigins: number;

  constructor(maximumOrigins: number) {
    super("The maximum number of active origins has been reached");
    this.name = "AgentOriginLimitError";
    this.maximumOrigins = maximumOrigins;
  }
}

export class AgentPendingLimitError extends Error {
  readonly code = "UND_ERR_AGENT_QUEUE_FULL";
  readonly maximumPendingOrigins: number;

  constructor(maximumPendingOrigins: number) {
    super("The Agent origin-creation queue is full");
    this.name = "AgentPendingLimitError";
    this.maximumPendingOrigins = maximumPendingOrigins;
  }
}

function originOf(request: TransportRequest): string {
  if (request.url.protocol !== "http:" && request.url.protocol !== "https:") {
    throw new TypeError("Agent requests require an HTTP(S) URL");
  }
  if (request.url.host === "") throw new TypeError("Agent requests require a nonempty host");
  return request.url.protocol + "//" + request.url.host;
}

function promiseFrom(action: () => Promise<void>): Promise<void> {
  try {
    return action();
  } catch (error) {
    return Promise.reject(error);
  }
}

/**
 * Environment-owned multi-origin dispatcher.
 *
 * The map order is an LRU: a successful lookup moves its record to the end. A new
 * origin evicts only the oldest dispatcher whose provider reports it fully idle,
 * and waits for that close before constructing the replacement. Thus a configured
 * origin bound is a resource bound rather than only a bound on map entries.
 */
export class Agent implements FetchTransport {
  private readonly factory: OriginDispatcherFactory;
  private readonly maximumOrigins: number;
  private readonly maximumPendingOrigins: number;
  private readonly records = new Map<string, AgentRecord>();
  private readonly owned = new Set<OriginDispatcher>();
  private mutation: Promise<void> = Promise.resolve();
  private closeResult: Promise<void> | null = null;
  private destroyResult: Promise<void> | null = null;
  private accepting = true;
  private destroyedState = false;
  private dispatchedCount = 0;
  private evictedCount = 0;
  private pendingOriginAcquisitions = 0;

  constructor(options: AgentOptions) {
    this.factory = options.factory;
    this.maximumOrigins = options.maximumOrigins ?? Infinity;
    this.maximumPendingOrigins = options.maximumPendingOrigins ?? 256;
    if (
      this.maximumOrigins !== Infinity &&
      (!Number.isSafeInteger(this.maximumOrigins) || this.maximumOrigins < 1)
    ) {
      throw new RangeError("maximumOrigins must be a positive safe integer or Infinity");
    }
    if (!Number.isSafeInteger(this.maximumPendingOrigins) || this.maximumPendingOrigins < 1) {
      throw new RangeError("maximumPendingOrigins must be a positive safe integer");
    }
  }

  get closed(): boolean {
    return !this.accepting;
  }

  get destroyed(): boolean {
    return this.destroyedState;
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (!this.accepting) return Promise.reject(new TypeError("Agent is closed"));
    if (request.signal.aborted) return Promise.reject(request.signal.reason);

    let origin: string;
    try {
      origin = originOf(request);
    } catch (error) {
      return Promise.reject(error);
    }

    const existing = this.records.get(origin);
    if (existing !== undefined) {
      this.touch(existing);
      this.dispatchedCount++;
      return this.dispatchWith(existing.dispatcher, request);
    }

    if (this.pendingOriginAcquisitions >= this.maximumPendingOrigins) {
      return Promise.reject(new AgentPendingLimitError(this.maximumPendingOrigins));
    }
    this.pendingOriginAcquisitions++;
    const acquired = this.serializeMutation(() => this.acquire(origin, request));
    return acquired.then(
      (record) => {
        this.pendingOriginAcquisitions--;
        this.dispatchedCount++;
        return this.dispatchWith(record.dispatcher, request);
      },
      (error) => {
        this.pendingOriginAcquisitions--;
        throw error;
      },
    );
  }

  close(): Promise<void> {
    if (this.destroyResult !== null) return this.destroyResult;
    if (this.closeResult !== null) return this.closeResult;
    this.accepting = false;
    this.closeResult = this.finishClose();
    return this.closeResult;
  }

  destroy(reason: unknown = new TypeError("Agent destroyed")): Promise<void> {
    if (this.destroyResult !== null) return this.destroyResult;
    this.accepting = false;
    this.destroyResult = this.finishDestroy(reason);
    return this.destroyResult;
  }

  get stats(): AgentStats {
    let idleOrigins = 0;
    let connections = 0;
    let pending = 0;
    let running = 0;
    const entries: AgentOriginStats[] = [];
    for (const record of this.records.values()) {
      const stats = record.dispatcher.stats;
      if (record.dispatcher.idle) idleOrigins++;
      connections += stats.connections;
      pending += stats.pending;
      running += stats.running;
      entries.push({
        origin: record.origin,
        idle: record.dispatcher.idle,
        connections: stats.connections,
        pending: stats.pending,
        running: stats.running,
      });
    }
    return {
      origins: this.records.size,
      idleOrigins,
      connections,
      pending,
      running,
      dispatched: this.dispatchedCount,
      evicted: this.evictedCount,
      pendingOriginAcquisitions: this.pendingOriginAcquisitions,
      entries,
    };
  }

  private dispatchWith(
    dispatcher: OriginDispatcher,
    request: TransportRequest,
  ): Promise<TransportResponse> {
    try {
      return dispatcher.dispatch(request);
    } catch (error) {
      return Promise.reject(error);
    }
  }

  private touch(record: AgentRecord): void {
    this.records.delete(record.origin);
    this.records.set(record.origin, record);
  }

  private serializeMutation<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.mutation.then(operation);
    this.mutation = result.then(
      () => {},
      () => {},
    );
    return result;
  }

  private async acquire(origin: string, request: TransportRequest): Promise<AgentRecord> {
    request.signal.throwIfAborted();
    const raced = this.records.get(origin);
    if (raced !== undefined) {
      this.touch(raced);
      return raced;
    }

    if (this.records.size >= this.maximumOrigins) {
      let evicted: AgentRecord | null = null;
      for (const candidate of this.records.values()) {
        if (!candidate.dispatcher.idle) continue;
        evicted = candidate;
        break;
      }
      if (evicted === null) throw new AgentOriginLimitError(this.maximumOrigins);
      this.records.delete(evicted.origin);
      try {
        await promiseFrom(() => evicted.dispatcher.close());
      } catch (error) {
        this.records.set(evicted.origin, evicted);
        throw error;
      }
      this.owned.delete(evicted.dispatcher);
      this.evictedCount++;
      request.signal.throwIfAborted();
    }

    const dispatcher = this.factory.create(origin);
    const record = { origin, dispatcher };
    this.records.set(origin, record);
    this.owned.add(dispatcher);
    return record;
  }

  private async finishClose(): Promise<void> {
    await this.mutation;
    if (this.destroyResult !== null) return this.destroyResult;
    const closing: Promise<void>[] = [];
    for (const dispatcher of this.owned) closing.push(promiseFrom(() => dispatcher.close()));
    this.records.clear();
    try {
      await Promise.all(closing);
    } finally {
      this.owned.clear();
      this.destroyedState = true;
    }
  }

  private async finishDestroy(reason: unknown): Promise<void> {
    await this.mutation;
    const destroying: Promise<void>[] = [];
    for (const dispatcher of this.owned) {
      destroying.push(promiseFrom(() => dispatcher.destroy(reason)));
    }
    this.records.clear();
    try {
      await Promise.all(destroying);
    } finally {
      this.owned.clear();
      this.destroyedState = true;
    }
  }
}

/** A standalone, single-origin dispatcher over one provider-owned transport. */
export class Client implements FetchTransport {
  readonly origin: string;
  private readonly dispatcher: OriginDispatcher;
  private closeResult: Promise<void> | null = null;
  private destroyResult: Promise<void> | null = null;
  private accepting = true;
  private destroyedState = false;

  constructor(origin: string, dispatcher: OriginDispatcher) {
    if (origin === "") throw new TypeError("Client origin must not be empty");
    this.origin = origin;
    this.dispatcher = dispatcher;
  }

  get closed(): boolean {
    return !this.accepting;
  }

  get destroyed(): boolean {
    return this.destroyedState;
  }

  get stats(): OriginDispatcherStats {
    return this.dispatcher.stats;
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (!this.accepting) return Promise.reject(new TypeError("Client is closed"));
    let origin: string;
    try {
      origin = originOf(request);
    } catch (error) {
      return Promise.reject(error);
    }
    if (origin !== this.origin) {
      return Promise.reject(new TypeError("Client request origin does not match its origin"));
    }
    try {
      return this.dispatcher.dispatch(request);
    } catch (error) {
      return Promise.reject(error);
    }
  }

  close(): Promise<void> {
    if (this.destroyResult !== null) return this.destroyResult;
    if (this.closeResult !== null) return this.closeResult;
    this.accepting = false;
    this.closeResult = promiseFrom(() => this.dispatcher.close()).finally(() => {
      this.destroyedState = true;
    });
    return this.closeResult;
  }

  destroy(reason: unknown = new TypeError("Client destroyed")): Promise<void> {
    if (this.destroyResult !== null) return this.destroyResult;
    this.accepting = false;
    this.destroyResult = promiseFrom(() => this.dispatcher.destroy(reason)).finally(() => {
      this.destroyedState = true;
    });
    return this.destroyResult;
  }
}

import { isHTTPTabOrSpace } from "../core/ascii.ts";
import { Headers } from "../fetch/headers.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type {
  FetchTransport,
  TransportRequest,
  TransportResponse,
} from "../fetch/transport.ts";
import type { FetchInterceptor } from "./interceptor.ts";
import { collectResponseBody } from "./response-body.ts";
import { headersRawEntries } from "../fetch/headers.ts";

/**
 * One challenge from a `WWW-Authenticate` field.
 *
 * `token68` and `parameters` are alternatives in the grammar, not a pair: a challenge
 * carries either a single opaque credential-like token or a set of named parameters,
 * and a challenge that appeared to have both would be malformed. Keeping them separate
 * rather than folding token68 into a nameless parameter means an authenticator can tell
 * `Negotiate abc==` from a parameter it does not recognise.
 */
export interface AuthenticationChallenge {
  /** Lower-cased, because schemes are case-insensitive and callers compare them. */
  readonly scheme: string;
  readonly token68: string | null;
  /** Lower-cased names; values exactly as sent, with quoted pairs unescaped. */
  readonly parameters: readonly HeaderEntry[];
}

export interface AuthenticationContext {
  readonly request: TransportRequest;
  readonly status: number;
  readonly headers: readonly HeaderEntry[];
  readonly challenges: readonly AuthenticationChallenge[];
  /** One for the first challenge answered, not the original request. */
  readonly attempt: number;
}

/** Return a complete `Authorization` value, or null to decline every challenge. */
export type OriginAuthenticator = (
  context: AuthenticationContext,
) => string | null | Promise<string | null>;

export interface AuthenticationOptions {
  readonly authenticate: OriginAuthenticator;
  /** Defaults to 1. A second failure with the same credentials is not a third chance. */
  readonly maximumAttempts?: number;
  /**
   * Statuses that carry a challenge. Defaults to `[401]`.
   *
   * `407` is deliberately not here: proxy authentication belongs to the proxy layer,
   * which knows which hop the challenge came from. An interceptor answering it would
   * send origin credentials to a proxy.
   */
  readonly statuses?: readonly number[];
  /** Bytes of the challenge response read and discarded. Defaults to 64 KiB. */
  readonly maxDiscardedBytes?: number;
}

const isTokenChar = (code: number): boolean =>
  (code >= 0x30 && code <= 0x39) ||
  (code >= 0x41 && code <= 0x5a) ||
  (code >= 0x61 && code <= 0x7a) ||
  code === 0x21 ||
  (code >= 0x23 && code <= 0x27) ||
  code === 0x2a ||
  code === 0x2b ||
  code === 0x2d ||
  code === 0x2e ||
  code === 0x5e ||
  code === 0x5f ||
  code === 0x60 ||
  code === 0x7c ||
  code === 0x7e;

/** token68 adds the base64 alphabet and its padding to the token characters. */
const isToken68Char = (code: number): boolean =>
  (code >= 0x30 && code <= 0x39) ||
  (code >= 0x41 && code <= 0x5a) ||
  (code >= 0x61 && code <= 0x7a) ||
  code === 0x2d ||
  code === 0x2e ||
  code === 0x5f ||
  code === 0x7e ||
  code === 0x2b ||
  code === 0x2f;

class ChallengeReader {
  readonly #value: string;
  #index = 0;

  constructor(value: string) {
    this.#value = value;
  }

  get done(): boolean {
    return this.#index >= this.#value.length;
  }

  get position(): number {
    return this.#index;
  }

  skipSpace(): void {
    while (this.#index < this.#value.length && isHTTPTabOrSpace(this.#value.charCodeAt(this.#index)))
      this.#index++;
  }

  /** Skips commas and whitespace, reporting whether any comma was there. */
  skipCommas(): boolean {
    let found = false;
    for (;;) {
      this.skipSpace();
      if (this.#index < this.#value.length && this.#value.charCodeAt(this.#index) === 0x2c) {
        found = true;
        this.#index++;
        continue;
      }
      return found;
    }
  }

  peek(): number {
    return this.#index < this.#value.length ? this.#value.charCodeAt(this.#index) : -1;
  }

  advance(): void {
    this.#index++;
  }

  /** Only ever backwards, to a position this reader has already returned. */
  rewind(position: number): void {
    if (position > this.#index) throw new RangeError("A challenge reader only rewinds");
    this.#index = position;
  }

  token(): string {
    const start = this.#index;
    while (this.#index < this.#value.length && isTokenChar(this.#value.charCodeAt(this.#index)))
      this.#index++;
    return this.#value.slice(start, this.#index);
  }

  token68(): string {
    const start = this.#index;
    while (this.#index < this.#value.length && isToken68Char(this.#value.charCodeAt(this.#index)))
      this.#index++;
    const end = this.#index;
    // Padding is trailing only, and a token68 that is all padding is not one.
    while (this.#index < this.#value.length && this.#value.charCodeAt(this.#index) === 0x3d)
      this.#index++;
    return end === start ? "" : this.#value.slice(start, this.#index);
  }

  /** A quoted string with `\` pairs unescaped, or null when it is unterminated. */
  quotedString(): string | null {
    if (this.peek() !== 0x22) return null;
    this.#index++;
    let out = "";
    while (this.#index < this.#value.length) {
      const code = this.#value.charCodeAt(this.#index);
      if (code === 0x5c && this.#index + 1 < this.#value.length) {
        out += this.#value.charAt(this.#index + 1);
        this.#index += 2;
        continue;
      }
      if (code === 0x22) {
        this.#index++;
        return out;
      }
      out += this.#value.charAt(this.#index);
      this.#index++;
    }
    return null;
  }
}

/**
 * Parses one or more challenges from a `WWW-Authenticate` field value.
 *
 * The grammar's difficulty is entirely that a comma separates both challenges and
 * auth-params, so `Basic realm="a", Bearer` is two challenges and `Digest realm="a",
 * qop="auth"` is one. The rule that resolves it: after a parameter, a comma followed by
 * `token=` continues the same challenge and a comma followed by a bare token starts a
 * new one. Lookahead is the only way to tell, which is why this is a reader and not a
 * split.
 *
 * A malformed tail ends parsing and keeps what was already understood. A field that
 * cannot be fully parsed is not a reason to discard a challenge the server did send.
 */
export function parseChallenges(value: string): readonly AuthenticationChallenge[] {
  const reader = new ChallengeReader(value);
  const challenges: AuthenticationChallenge[] = [];

  reader.skipCommas();
  while (!reader.done) {
    const scheme = reader.token();
    if (scheme === "") break;
    const parameters: HeaderEntry[] = [];
    let token68: string | null = null;
    // Set when the challenge ended because the next one had already begun, in which
    // case its separating comma has been consumed and must not be demanded again.
    let ranOn = false;

    reader.skipSpace();

    // token68 comes first, and only directly after the scheme. It is decided by what
    // follows rather than by its own characters: `realm` and `abc` are both valid
    // token68 syntax, and only the `=` after `realm` says which one this is. So it is
    // accepted just when the whole run reaches a comma or the end.
    if (!reader.done && reader.peek() !== 0x2c) {
      const mark = reader.position;
      const opaque = reader.token68();
      reader.skipSpace();
      if (opaque !== "" && (reader.done || reader.peek() === 0x2c)) {
        token68 = opaque;
      } else {
        reader.rewind(mark);
      }
    }

    while (token68 === null) {
      const before = reader.position;
      const hadComma = reader.skipCommas();
      if (reader.done) break;

      const mark = reader.position;
      const name = reader.token();
      if (name === "") break;

      reader.skipSpace();
      if (reader.peek() !== 0x3d) {
        // A bare token is the next challenge's scheme. It only reads as one once this
        // challenge has something of its own; directly after the scheme there is no
        // comma yet and the token68 attempt above has already had its turn.
        if (!hadComma && parameters.length === 0) break;
        reader.rewind(mark);
        ranOn = true;
        break;
      }
      reader.advance();
      reader.skipSpace();

      const quoted = reader.quotedString();
      if (quoted !== null) {
        parameters.push([name.toLowerCase(), quoted]);
        continue;
      }
      const bare = reader.token();
      if (bare === "") {
        // `name=` with nothing usable after it. Keep what is understood and stop.
        reader.rewind(before);
        break;
      }
      parameters.push([name.toLowerCase(), bare]);
    }

    challenges.push({ scheme: scheme.toLowerCase(), token68, parameters });
    if (ranOn) continue;
    if (!reader.skipCommas() && !reader.done) break;
  }
  return challenges;
}

/**
 * Answers origin authentication challenges by consulting an injected authenticator.
 *
 * Credentials are never invented and never sent before they are asked for: the first
 * request goes out as the caller wrote it, and only a challenge produces a second one.
 * That is the whole difference between an authentication hook and a credential leak —
 * a preemptive `Authorization` header goes to whoever answers the address, including
 * whoever answers it wrongly.
 */
export class AuthenticationInterceptor implements FetchInterceptor {
  readonly #authenticate: OriginAuthenticator;
  readonly #maximumAttempts: number;
  readonly #statuses: readonly number[];
  readonly #maxDiscardedBytes: number;

  constructor(options: AuthenticationOptions) {
    this.#authenticate = options.authenticate;
    this.#maximumAttempts = options.maximumAttempts ?? 1;
    this.#statuses = options.statuses ?? [401];
    this.#maxDiscardedBytes = options.maxDiscardedBytes ?? 64 * 1024;
    if (!Number.isSafeInteger(this.#maximumAttempts) || this.#maximumAttempts < 1) {
      throw new RangeError("maximumAttempts must be a positive safe integer");
    }
    if (!Number.isSafeInteger(this.#maxDiscardedBytes) || this.#maxDiscardedBytes < 0) {
      throw new RangeError("maxDiscardedBytes must be a non-negative safe integer");
    }
    for (const status of this.#statuses) {
      if (!Number.isInteger(status) || status < 100 || status > 599) {
        throw new RangeError("Authentication status is invalid");
      }
      if (status === 407) {
        throw new RangeError(
          "407 is proxy authentication and belongs to the proxy layer, which knows the hop",
        );
      }
    }
  }

  async dispatch(request: TransportRequest, next: FetchTransport): Promise<TransportResponse> {
    let attempt = 0;
    let current = request;
    for (;;) {
      const response = await next.dispatch(current);
      if (!this.#challenged(response.status)) return response;
      if (attempt >= this.#maximumAttempts) return response;

      const challenges = collectChallenges(response.headers);
      attempt++;
      const credential = await this.#authenticate({
        request,
        status: response.status,
        headers: response.headers,
        challenges,
        attempt,
      });
      if (credential === null) return response;

      // The body of a challenge is an explanation nobody is going to read, but it has
      // to be consumed or cancelled before the connection can carry the next attempt.
      await this.#discard(response, request);

      const headers = new Headers(current.headers);
      headers.set("authorization", credential);
      current = {
        url: request.url,
        method: request.method,
        headers: headers[headersRawEntries](),
        body: replayBody(request),
        bodyLength: request.bodyLength,
        replayBody: request.replayBody,
        signal: request.signal,
        ...(request.onInformational === undefined
          ? {}
          : { onInformational: request.onInformational }),
      };
    }
  }

  #challenged(status: number): boolean {
    for (const candidate of this.#statuses) if (candidate === status) return true;
    return false;
  }

  async #discard(response: TransportResponse, request: TransportRequest): Promise<void> {
    try {
      await collectResponseBody(response, request.signal, this.#maxDiscardedBytes);
    } catch {
      // A challenge body that is too large, or fails, changes nothing about the
      // challenge itself. The connection is the transport's to give up on.
    }
  }
}

/**
 * The request body for a second attempt.
 *
 * A request that cannot replay its body has nothing to send twice, and answering a
 * challenge with an empty body would be worse than not answering it: the server would
 * see an authenticated request that is not the one the caller made.
 */
function replayBody(request: TransportRequest): TransportRequest["body"] {
  if (request.body === null) return null;
  const source = request.replayBody;
  if (source === undefined || source === null) {
    throw new TypeError("Cannot answer an authentication challenge for a one-shot body");
  }
  return source.open();
}

/** Every challenge across every `WWW-Authenticate` field, in the order sent. */
function collectChallenges(headers: readonly HeaderEntry[]): readonly AuthenticationChallenge[] {
  const challenges: AuthenticationChallenge[] = [];
  for (const [name, value] of headers) {
    if (name.toLowerCase() !== "www-authenticate") continue;
    for (const challenge of parseChallenges(value)) challenges.push(challenge);
  }
  return challenges;
}

import { AbortController } from "../core/abort.ts";
import type { AbortSignal } from "../core/abort.ts";
import { ignoreRejection } from "../core/promise.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import { Fifo } from "../streams/fifo.ts";
import {
  ReadableStream,
  type ReadableStreamDefaultController,
  type ReadableStreamDefaultReader,
  type UnderlyingSource,
} from "../streams/readable.ts";
import type { FetchInterceptor } from "./interceptor.ts";
import { abortSignalSubscribe } from "../core/abort.ts";

const safeMethods = ["GET", "HEAD", "OPTIONS", "TRACE"] as const;

export interface DeduplicationOptions {
  readonly methods?: readonly string[];
  readonly skipHeaderNames?: readonly string[];
  readonly excludeHeaderNames?: readonly string[];
  readonly maximumPendingRequests?: number;
  readonly maximumSubscribersPerRequest?: number;
  readonly maximumBufferedBytesPerSubscriber?: number;
  readonly maximumTotalBufferedBytes?: number;
}

export class DeduplicationBufferError extends Error {
  readonly code = "UND_ERR_ABORTED";
  readonly maximumBytes: number;
  readonly scope: "subscriber" | "total";

  constructor(maximumBytes: number, scope: "subscriber" | "total" = "subscriber") {
    super(
      scope === "subscriber"
        ? "Deduplicated response subscriber exceeded its buffer limit"
        : "Deduplicated responses exceeded their shared buffer limit",
    );
    this.name = "DeduplicationBufferError";
    this.maximumBytes = maximumBytes;
    this.scope = scope;
  }
}

class BufferBudget {
  readonly maximumBytes: number;
  private used = 0;

  constructor(maximum: number) {
    this.maximumBytes = maximum;
  }

  reserve(bytes: number): boolean {
    if (bytes > this.maximumBytes - this.used) return false;
    this.used += bytes;
    return true;
  }

  release(bytes: number): void {
    this.used -= bytes;
    if (this.used < 0) throw new Error("Deduplication buffer accounting underflow");
  }
}

function validatePositiveSafeInteger(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new RangeError(name + " must be a positive safe integer");
  }
}

function normalizedNames(values: readonly string[], name: string): readonly string[] {
  const result: string[] = [];
  for (const value of values) {
    if (typeof value !== "string") throw new TypeError(name + " must contain only strings");
    result.push(value.toLowerCase());
  }
  return result;
}

function includes(values: readonly string[], candidate: string): boolean {
  for (const value of values) if (value === candidate) return true;
  return false;
}

function part(value: string): string {
  return String(value.length) + ":" + value;
}

function requestKey(request: TransportRequest, excluded: readonly string[]): string {
  const url =
    request.url.protocol + "//" + request.url.host + request.url.pathname + request.url.search;
  let result = part(request.method.toUpperCase()) + part(url);
  let count = 0;
  for (const [rawName, value] of request.headers) {
    const name = rawName.toLowerCase();
    if (includes(excluded, name)) continue;
    result += part(name) + part(value);
    count++;
  }
  return String(count) + ":" + result;
}

function hasSkippedHeader(request: TransportRequest, skipped: readonly string[]): boolean {
  if (skipped.length === 0) return false;
  for (const [rawName] of request.headers) {
    if (includes(skipped, rawName.toLowerCase())) return true;
  }
  return false;
}

function copyHeaders(entries: readonly HeaderEntry[]): HeaderEntry[] {
  const copy: HeaderEntry[] = [];
  for (const [name, value] of entries) copy.push([name, value]);
  return copy;
}

function copyTrailers(
  pending: Promise<readonly HeaderEntry[]>,
  signal: AbortSignal,
): Promise<readonly HeaderEntry[]> {
  signal.throwIfAborted();
  const result = Promise.withResolvers<readonly HeaderEntry[]>();
  const unsubscribe = signal[abortSignalSubscribe](() => result.reject(signal.reason));
  pending.then((entries) => {
    const copy = copyHeaders(entries);
    if (signal.aborted) return;
    result.resolve(copy);
  }, result.reject);
  const copied = result.promise.finally(unsubscribe);
  ignoreRejection(copied);
  return copied;
}

class SubscriberSource implements UnderlyingSource<Uint8Array> {
  private readonly subscriber: DeduplicationSubscriber;

  constructor(subscriber: DeduplicationSubscriber) {
    this.subscriber = subscriber;
  }

  start(controller: ReadableStreamDefaultController<Uint8Array>): void {
    this.subscriber.start(controller);
  }

  pull(): void {
    this.subscriber.pull();
  }

  cancel(reason: unknown): Promise<void> {
    return this.subscriber.cancel(reason);
  }
}

class DeduplicationSubscriber {
  readonly result = Promise.withResolvers<TransportResponse>();
  private readonly owner: PendingDeduplication;
  private readonly budget: BufferBudget;
  private readonly maximumBufferedBytes: number;
  private readonly cancellation = new AbortController();
  private readonly queue = new Fifo<Uint8Array>();
  private readonly unsubscribeRequest: () => void;
  private controller: ReadableStreamDefaultController<Uint8Array> | null = null;
  private queuedBytes = 0;
  private responseSettled = false;
  private active = true;
  private wantsChunk = false;
  private sourceDone = false;

  constructor(
    owner: PendingDeduplication,
    requestSignal: AbortSignal,
    budget: BufferBudget,
    maximumBufferedBytes: number,
  ) {
    this.owner = owner;
    this.budget = budget;
    this.maximumBufferedBytes = maximumBufferedBytes;
    this.unsubscribeRequest = requestSignal[abortSignalSubscribe](() => this.abort(requestSignal.reason));
  }

  get isActive(): boolean {
    return this.active;
  }

  get waitingForChunk(): boolean {
    return this.active && this.wantsChunk;
  }

  attach(response: TransportResponse): void {
    if (!this.active) return;
    const body =
      response.body === null
        ? null
        : new ReadableStream<Uint8Array>(new SubscriberSource(this), { highWaterMark: 0 });
    this.responseSettled = true;
    this.result.resolve({
      status: response.status,
      statusText: response.statusText,
      headers: copyHeaders(response.headers),
      body,
      trailers:
        response.trailers === undefined
          ? undefined
          : copyTrailers(response.trailers, this.cancellation.signal),
    });
    if (body === null) this.finish();
  }

  start(controller: ReadableStreamDefaultController<Uint8Array>): void {
    this.controller = controller;
  }

  pull(): void {
    if (!this.active) return;
    const chunk = this.queue.dequeue();
    if (chunk !== undefined) {
      this.queuedBytes -= chunk.length;
      this.budget.release(chunk.length);
      this.controller?.enqueue(chunk);
      return;
    }
    if (this.sourceDone) {
      this.controller?.close();
      this.finish();
      return;
    }
    this.wantsChunk = true;
    this.owner.pump();
  }

  deliver(chunk: Uint8Array): void {
    if (!this.active) return;
    if (this.wantsChunk) {
      this.wantsChunk = false;
      this.controller?.enqueue(chunk.slice());
      return;
    }
    if (chunk.length > this.maximumBufferedBytes - this.queuedBytes) {
      this.fail(new DeduplicationBufferError(this.maximumBufferedBytes));
      return;
    }
    if (!this.budget.reserve(chunk.length)) {
      this.fail(new DeduplicationBufferError(this.budget.maximumBytes, "total"));
      return;
    }
    let copy: Uint8Array;
    try {
      copy = chunk.slice();
    } catch (error) {
      this.budget.release(chunk.length);
      this.fail(error);
      return;
    }
    this.queue.enqueue(copy);
    this.queuedBytes += copy.length;
  }

  end(): void {
    if (!this.active) return;
    this.sourceDone = true;
    if (!this.queue.empty) return;
    this.controller?.close();
    this.finish();
  }

  fail(reason: unknown): void {
    this.stop(reason, true, true);
  }

  abort(reason: unknown): void {
    this.stop(reason, true, true);
  }

  cancel(reason: unknown): Promise<void> {
    return this.stop(reason, false, true);
  }

  private finish(): void {
    if (!this.active) return;
    this.active = false;
    this.wantsChunk = false;
    this.unsubscribeRequest();
  }

  private stop(reason: unknown, errorStream: boolean, notifyOwner: boolean): Promise<void> {
    if (!this.active) return Promise.resolve();
    this.active = false;
    this.wantsChunk = false;
    this.releaseQueue();
    this.unsubscribeRequest();
    this.cancellation.abort(reason);
    if (!this.responseSettled) this.result.reject(reason);
    else if (errorStream) this.controller?.error(reason);
    return notifyOwner ? this.owner.subscriberStopped(reason) : Promise.resolve();
  }

  private releaseQueue(): void {
    while (!this.queue.empty) {
      const chunk = this.queue.dequeue();
      if (chunk !== undefined) this.budget.release(chunk.length);
    }
    this.queuedBytes = 0;
  }
}

class PendingDeduplication {
  private readonly key: string;
  private readonly request: TransportRequest;
  private readonly next: FetchTransport;
  private readonly owner: DeduplicationInterceptor;
  private readonly budget: BufferBudget;
  private readonly maximumSubscribers: number;
  private readonly maximumBufferedBytes: number;
  private readonly cancellation = new AbortController();
  private readonly subscribers: DeduplicationSubscriber[] = [];
  private response: TransportResponse | null = null;
  private reader: ReadableStreamDefaultReader<Uint8Array> | null = null;
  private reading = false;
  private dataStarted = false;
  private sourceDone = false;
  private stopped = false;
  private stopReason: unknown;

  constructor(
    key: string,
    request: TransportRequest,
    next: FetchTransport,
    owner: DeduplicationInterceptor,
    budget: BufferBudget,
    maximumSubscribers: number,
    maximumBufferedBytes: number,
  ) {
    this.key = key;
    this.request = request;
    this.next = next;
    this.owner = owner;
    this.budget = budget;
    this.maximumSubscribers = maximumSubscribers;
    this.maximumBufferedBytes = maximumBufferedBytes;
  }

  start(): void {
    const request: TransportRequest = {
      url: this.request.url,
      method: this.request.method,
      headers: this.request.headers,
      body: this.request.body,
      bodyLength: this.request.bodyLength,
      replayBody: this.request.replayBody,
      signal: this.cancellation.signal,
    };
    Promise.resolve()
      .then(() => this.next.dispatch(request))
      .then((response) => this.responseStarted(response))
      .catch((error) => this.sourceFailed(error));
  }

  subscribe(signal: AbortSignal): Promise<TransportResponse> | null {
    if (this.stopped || this.dataStarted || this.subscribers.length >= this.maximumSubscribers) {
      return null;
    }
    if (signal.aborted) return Promise.reject(signal.reason);
    const subscriber = new DeduplicationSubscriber(
      this,
      signal,
      this.budget,
      this.maximumBufferedBytes,
    );
    this.subscribers.push(subscriber);
    if (this.response !== null) subscriber.attach(this.response);
    return subscriber.result.promise;
  }

  pump(): void {
    if (this.reader === null || this.reading || this.sourceDone || this.stopped) return;
    let demanded = false;
    for (const subscriber of this.subscribers) {
      if (subscriber.waitingForChunk) {
        demanded = true;
        break;
      }
    }
    if (!demanded) return;
    this.reading = true;
    this.reader.read().then(
      (item) => {
        this.reading = false;
        if (this.stopped) return;
        if (item.done) {
          this.sourceCompleted();
          return;
        }
        if (!(item.value instanceof Uint8Array)) {
          this.sourceFailed(new TypeError("Transport response body chunks must be Uint8Array"));
          return;
        }
        if (!this.dataStarted) {
          this.dataStarted = true;
          this.owner.removePending(this.key, this);
        }
        for (const subscriber of this.subscribers) subscriber.deliver(item.value);
        this.pump();
      },
      (error) => {
        this.reading = false;
        this.sourceFailed(error);
      },
    );
  }

  async subscriberStopped(reason: unknown): Promise<void> {
    if (this.sourceDone || this.stopped) return;
    for (const subscriber of this.subscribers) if (subscriber.isActive) return;
    this.stopped = true;
    this.stopReason = reason;
    this.owner.removePending(this.key, this);
    this.cancellation.abort(reason);
    const reader = this.reader;
    if (reader !== null) {
      try {
        await reader.cancel(reason);
      } finally {
        this.releaseReader();
      }
    }
  }

  private async responseStarted(response: TransportResponse): Promise<void> {
    if (this.stopped) {
      if (response.body !== null) {
        try {
          await response.body.cancel(this.stopReason);
        } catch {
          // No subscriber remains to observe cleanup failure.
        }
      }
      if (response.trailers !== undefined) ignoreRejection(response.trailers);
      return;
    }
    this.response = response;
    for (const subscriber of this.subscribers) subscriber.attach(response);
    if (response.body === null) {
      this.sourceCompleted();
      return;
    }
    this.reader = response.body.getReader();
    this.pump();
  }

  private sourceCompleted(): void {
    if (this.sourceDone) return;
    this.sourceDone = true;
    this.owner.removePending(this.key, this);
    this.releaseReader();
    for (const subscriber of this.subscribers) subscriber.end();
  }

  private sourceFailed(reason: unknown): void {
    if (this.sourceDone) return;
    this.sourceDone = true;
    this.owner.removePending(this.key, this);
    this.releaseReader();
    for (const subscriber of this.subscribers) subscriber.fail(reason);
  }

  private releaseReader(): void {
    const reader = this.reader;
    if (reader === null) return;
    this.reader = null;
    reader.releaseLock();
  }
}

/** Coalesce compatible in-flight safe requests without sharing response-body identity. */
export class DeduplicationInterceptor implements FetchInterceptor {
  private readonly methods: readonly string[];
  private readonly skipHeaderNames: readonly string[];
  private readonly excludeHeaderNames: readonly string[];
  private readonly maximumPendingRequests: number;
  private readonly maximumSubscribers: number;
  private readonly maximumBufferedBytes: number;
  private readonly budget: BufferBudget;
  private readonly pending = new Map<string, PendingDeduplication>();

  constructor(options: DeduplicationOptions = {}) {
    const methods = options.methods ?? ["GET"];
    const normalizedMethods: string[] = [];
    for (const value of methods) {
      if (typeof value !== "string") throw new TypeError("Deduplication methods must be strings");
      const method = value.toUpperCase();
      if (!includes(safeMethods, method)) {
        throw new TypeError("Deduplication supports only safe HTTP methods");
      }
      normalizedMethods.push(method);
    }
    this.methods = normalizedMethods;
    this.skipHeaderNames = normalizedNames(
      options.skipHeaderNames ?? [],
      "Deduplication skipHeaderNames",
    );
    this.excludeHeaderNames = normalizedNames(
      options.excludeHeaderNames ?? [],
      "Deduplication excludeHeaderNames",
    );
    this.maximumPendingRequests = options.maximumPendingRequests ?? 1024;
    this.maximumSubscribers = options.maximumSubscribersPerRequest ?? 64;
    this.maximumBufferedBytes = options.maximumBufferedBytesPerSubscriber ?? 5 * 1024 * 1024;
    const maximumTotalBufferedBytes = options.maximumTotalBufferedBytes ?? 64 * 1024 * 1024;
    validatePositiveSafeInteger(this.maximumPendingRequests, "Deduplication pending limit");
    validatePositiveSafeInteger(this.maximumSubscribers, "Deduplication subscriber limit");
    validatePositiveSafeInteger(this.maximumBufferedBytes, "Deduplication subscriber byte limit");
    validatePositiveSafeInteger(maximumTotalBufferedBytes, "Deduplication total byte limit");
    this.budget = new BufferBudget(maximumTotalBufferedBytes);
  }

  dispatch(request: TransportRequest, next: FetchTransport): Promise<TransportResponse> {
    const method = request.method.toUpperCase();
    if (
      !includes(this.methods, method) ||
      request.body !== null ||
      hasSkippedHeader(request, this.skipHeaderNames)
    ) {
      return next.dispatch(request);
    }
    const key = requestKey(request, this.excludeHeaderNames);
    const existing = this.pending.get(key);
    if (existing !== undefined) {
      const joined = existing.subscribe(request.signal);
      return joined ?? next.dispatch(request);
    }
    if (this.pending.size >= this.maximumPendingRequests) return next.dispatch(request);

    const entry = new PendingDeduplication(
      key,
      request,
      next,
      this,
      this.budget,
      this.maximumSubscribers,
      this.maximumBufferedBytes,
    );
    const result = entry.subscribe(request.signal);
    if (result === null) return next.dispatch(request);
    this.pending.set(key, entry);
    entry.start();
    return result;
  }

  /** @internal */ removePending(key: string, entry: PendingDeduplication): void {
    if (this.pending.get(key) === entry) this.pending.delete(key);
  }
}

import type { Scheduler } from "../provider/primitives.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import { ignoreRejection } from "../core/promise.ts";
import type { FetchInterceptor } from "./interceptor.ts";

const sensitiveHeaderNames = [
  "authorization",
  "cookie",
  "proxy-authorization",
  "set-cookie",
] as const;

export interface DispatchDiagnosticRequest {
  readonly method: string;
  readonly url: string;
  readonly queryRedacted: boolean;
  readonly headers: readonly HeaderEntry[];
  readonly bodyLength: number | null;
}

/** Object identity, rather than the display sequence, identifies one dispatch. */
export class DispatchDiagnosticContext {
  readonly sequence: number;
  readonly request: DispatchDiagnosticRequest;

  constructor(sequence: number, request: DispatchDiagnosticRequest) {
    this.sequence = sequence;
    this.request = request;
  }
}

export interface DispatchRequestCreatedEvent {
  readonly type: "request:create";
  readonly context: DispatchDiagnosticContext;
}

export interface DispatchResponseHeadersEvent {
  readonly type: "response:headers";
  readonly context: DispatchDiagnosticContext;
  readonly status: number;
  readonly statusText: string;
  readonly headers: readonly HeaderEntry[];
}

export interface DispatchResponseTrailersEvent {
  readonly type: "response:trailers";
  readonly context: DispatchDiagnosticContext;
  readonly headers: readonly HeaderEntry[];
}

export interface DispatchRequestErrorEvent {
  readonly type: "request:error";
  readonly context: DispatchDiagnosticContext;
  readonly phase: "dispatch" | "trailers";
  readonly error: unknown;
}

export type DispatchDiagnosticEvent =
  | DispatchRequestCreatedEvent
  | DispatchResponseHeadersEvent
  | DispatchResponseTrailersEvent
  | DispatchRequestErrorEvent;

/** Provider and Node facades adapt this typed sink; shared code has no host event bus. */
export interface DispatchDiagnosticObserver {
  publish(event: DispatchDiagnosticEvent): void;
}

export interface DispatchDiagnosticsPolicy {
  /** Query values are omitted by default because they commonly carry credentials. */
  readonly includeQueryString?: boolean;
  /** These names are redacted in addition to the built-in credential headers. */
  readonly additionalRedactedHeaderNames?: readonly string[];
}

export interface DiagnosticsInterceptorOptions extends DispatchDiagnosticsPolicy {
  readonly observer: DispatchDiagnosticObserver;
  readonly scheduler: Scheduler;
}

function includes(values: readonly string[], candidate: string): boolean {
  for (const value of values) if (value === candidate) return true;
  return false;
}

function redactedHeaders(
  entries: readonly HeaderEntry[],
  additionalNames: readonly string[],
): HeaderEntry[] {
  const result: HeaderEntry[] = [];
  for (const [name, value] of entries) {
    const lower = name.toLowerCase();
    result.push([
      name,
      includes(sensitiveHeaderNames, lower) || includes(additionalNames, lower)
        ? "[REDACTED]"
        : value,
    ]);
  }
  return result;
}

function diagnosticURL(
  request: TransportRequest,
  includeQueryString: boolean,
): {
  readonly value: string;
  readonly queryRedacted: boolean;
} {
  const url = request.url;
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    return { value: url.protocol + "<redacted>", queryRedacted: url.search !== "" };
  }
  const queryRedacted = !includeQueryString && url.search !== "";
  return {
    value:
      url.protocol +
      "//" +
      url.host +
      url.pathname +
      (includeQueryString ? url.search : queryRedacted ? "?<redacted>" : ""),
    queryRedacted,
  };
}

/**
 * Typed, environment-local request diagnostics.
 *
 * The interceptor deliberately does not wrap request or response bodies: observing a
 * stream by acquiring a reader or substituting a proxy stream changes ownership and
 * scheduling. Body-sent and connection events therefore belong at provider delivery
 * points and can feed the same observer without weakening the transport contract.
 */
export class DiagnosticsInterceptor implements FetchInterceptor {
  private readonly observer: DispatchDiagnosticObserver;
  private readonly scheduler: Scheduler;
  private readonly includeQueryString: boolean;
  private readonly additionalRedactedHeaderNames: readonly string[];
  private nextSequence = 1;

  constructor(options: DiagnosticsInterceptorOptions) {
    this.observer = options.observer;
    this.scheduler = options.scheduler;
    this.includeQueryString = options.includeQueryString === true;
    const additional: string[] = [];
    for (const name of options.additionalRedactedHeaderNames ?? []) {
      if (typeof name !== "string") {
        throw new TypeError("Additional redacted header names must be strings");
      }
      additional.push(name.toLowerCase());
    }
    this.additionalRedactedHeaderNames = additional;
  }

  dispatch(request: TransportRequest, next: FetchTransport): Promise<TransportResponse> {
    const context = this.context(request);
    this.publish({ type: "request:create", context });

    let pending: Promise<TransportResponse>;
    try {
      pending = next.dispatch(request);
    } catch (error) {
      this.publish({ type: "request:error", context, phase: "dispatch", error });
      throw error;
    }

    return pending.then(
      (response) => {
        this.publish({
          type: "response:headers",
          context,
          status: response.status,
          statusText: response.statusText,
          headers: redactedHeaders(response.headers, this.additionalRedactedHeaderNames),
        });
        this.observeTrailers(context, response);
        return response;
      },
      (error) => {
        this.publish({ type: "request:error", context, phase: "dispatch", error });
        throw error;
      },
    );
  }

  private context(request: TransportRequest): DispatchDiagnosticContext {
    const diagnostic = diagnosticURL(request, this.includeQueryString);
    const context = new DispatchDiagnosticContext(this.nextSequence, {
      method: request.method,
      url: diagnostic.value,
      queryRedacted: diagnostic.queryRedacted,
      headers: redactedHeaders(request.headers, this.additionalRedactedHeaderNames),
      bodyLength: request.bodyLength,
    });
    this.nextSequence = this.nextSequence === Number.MAX_SAFE_INTEGER ? 1 : this.nextSequence + 1;
    return context;
  }

  private observeTrailers(context: DispatchDiagnosticContext, response: TransportResponse): void {
    const trailers = response.trailers;
    if (trailers === undefined) return;
    const observation = trailers.then(
      (headers) => {
        this.publish({
          type: "response:trailers",
          context,
          headers: redactedHeaders(headers, this.additionalRedactedHeaderNames),
        });
      },
      (error) => {
        this.publish({ type: "request:error", context, phase: "trailers", error });
      },
    );
    ignoreRejection(observation);
  }

  private publish(event: DispatchDiagnosticEvent): void {
    try {
      this.observer.publish(event);
    } catch (error) {
      try {
        this.scheduler.reportError(error);
      } catch {
        // A broken diagnostic sink and reporter cannot alter transport semantics.
      }
    }
  }
}

import { AbortController } from "../core/abort.ts";
import type { AbortSignal } from "../core/abort.ts";
import { TransportError } from "../fetch/transport.ts";
import type {
  ByteConnection,
  CancelHandle,
  ConnectAddress,
  DnsAddress,
  DnsAddressFamily,
  DnsResolver,
  Scheduler,
  SocketConnector,
} from "../provider/primitives.ts";
import { abortSignalSubscribe } from "../core/abort-brand.ts";

const DEFAULT_MAXIMUM_ITEMS = 256;
const DEFAULT_MAXIMUM_PENDING = 64;
const DEFAULT_MAXIMUM_ADDRESSES = 32;
const DEFAULT_MAXIMUM_TTL_MILLISECONDS = 10000;
const DEFAULT_ATTEMPT_DELAY_MILLISECONDS = 250;
const DEFAULT_MAXIMUM_ATTEMPTS = 8;

interface CachedAddress {
  readonly address: string;
  readonly family: DnsAddressFamily;
  readonly expiresAt: number;
}

interface CacheRecord {
  readonly hostname: string;
  addresses: CachedAddress[];
  ipv4Offset: number;
  ipv6Offset: number;
}

interface PendingLookup {
  readonly key: string;
  readonly controller: AbortController;
  promise: Promise<readonly DnsAddress[]>;
  consumers: number;
  settled: boolean;
}

export interface DnsCacheOptions {
  readonly resolver: DnsResolver;
  /** A monotonic environment clock, never a wall clock. */
  readonly nowMilliseconds: () => number;
  readonly maximumItems?: number;
  readonly maximumPendingLookups?: number;
  readonly maximumAddressesPerHostname?: number;
  readonly maximumTTLMilliseconds?: number;
}

export interface DnsCacheStats {
  readonly entries: number;
  readonly pending: number;
  readonly cacheHits: number;
  readonly resolverCalls: number;
  readonly evictions: number;
}

export class DnsLookupLimitError extends Error {
  readonly code = "UND_ERR_DNS_QUEUE_FULL";
  readonly maximumPendingLookups: number;

  constructor(maximumPendingLookups: number) {
    super("The DNS lookup queue is full");
    this.name = "DnsLookupLimitError";
    this.maximumPendingLookups = maximumPendingLookups;
  }
}

export class DnsNoAddressError extends TransportError {
  readonly hostname: string;

  constructor(hostname: string) {
    super("ENOTFOUND", "No DNS address was returned for " + hostname);
    this.name = "DnsNoAddressError";
    this.hostname = hostname;
  }
}

export class DnsConnectionError extends TransportError {
  readonly hostname: string;
  readonly failures: readonly unknown[];

  constructor(hostname: string, failures: readonly unknown[]) {
    const cause = failures.length === 0 ? undefined : failures[failures.length - 1];
    super("UND_ERR_SOCKET", "Every resolved address failed for " + hostname, cause);
    this.name = "DnsConnectionError";
    this.hostname = hostname;
    this.failures = failures.slice();
  }
}

function validatePositiveInteger(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new RangeError(name + " must be a positive safe integer");
  }
}

function validateNonNegativeFinite(value: number, name: string): void {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(name + " must be a non-negative finite number");
  }
}

function familyKey(families: readonly DnsAddressFamily[]): string {
  if (families.length === 1 && families[0] === 4) return "4";
  if (families.length === 1 && families[0] === 6) return "6";
  if (
    families.length === 2 &&
    ((families[0] === 4 && families[1] === 6) || (families[0] === 6 && families[1] === 4))
  ) {
    return "46";
  }
  throw new TypeError("DNS families must contain 4, 6, or each exactly once");
}

function hasFamily(families: readonly DnsAddressFamily[], family: DnsAddressFamily): boolean {
  for (const candidate of families) if (candidate === family) return true;
  return false;
}

function isAsciiDigit(code: number): boolean {
  return code >= 48 && code <= 57;
}

function isIPv4Address(value: string): boolean {
  const parts = value.split(".");
  if (parts.length !== 4) return false;
  for (const part of parts) {
    if (part.length === 0 || part.length > 3) return false;
    let number = 0;
    for (let index = 0; index < part.length; index++) {
      const code = part.charCodeAt(index);
      if (!isAsciiDigit(code)) return false;
      number = number * 10 + code - 48;
    }
    if (number > 255) return false;
  }
  return true;
}

function isIPv6Address(value: string): boolean {
  const compression = value.indexOf("::");
  if (compression !== value.lastIndexOf("::")) return false;
  if (compression < 0) {
    const groups = value.split(":");
    return ipv6GroupCount(groups, true) === 8;
  }
  const left = value.slice(0, compression);
  const right = value.slice(compression + 2);
  const leftGroups = left === "" ? [] : left.split(":");
  const rightGroups = right === "" ? [] : right.split(":");
  const leftCount = ipv6GroupCount(leftGroups, false);
  const rightCount = ipv6GroupCount(rightGroups, true);
  return leftCount !== null && rightCount !== null && leftCount + rightCount < 8;
}

function ipv6GroupCount(groups: readonly string[], mayEndWithIPv4: boolean): number | null {
  let count = 0;
  for (let groupIndex = 0; groupIndex < groups.length; groupIndex++) {
    const group = groups[groupIndex];
    if (group === undefined || group.length === 0) return null;
    if (group.includes(".")) {
      if (!mayEndWithIPv4 || groupIndex !== groups.length - 1 || !isIPv4Address(group)) {
        return null;
      }
      count += 2;
      continue;
    }
    if (group.length > 4) return null;
    for (let index = 0; index < group.length; index++) {
      const code = group.charCodeAt(index);
      if (!isAsciiDigit(code) && !(code >= 65 && code <= 70) && !(code >= 97 && code <= 102)) {
        return null;
      }
    }
    count++;
  }
  return count;
}

function isLiteralAddress(value: string): boolean {
  return isIPv4Address(value) || isIPv6Address(value);
}

function copyAddresses(addresses: readonly DnsAddress[]): readonly DnsAddress[] {
  const copied: DnsAddress[] = [];
  for (const address of addresses) {
    copied.push({
      address: address.address,
      family: address.family,
      ttlMilliseconds: address.ttlMilliseconds,
    });
  }
  return copied;
}

function callResolver(
  resolver: DnsResolver,
  hostname: string,
  families: readonly DnsAddressFamily[],
  maximumAddresses: number,
  signal: AbortSignal,
): Promise<readonly DnsAddress[]> {
  try {
    return resolver.resolve(hostname, { families, maximumAddresses }, signal);
  } catch (error) {
    return Promise.reject(error);
  }
}

/** Environment-local positive DNS cache with bounded LRU storage and miss coalescing. */
export class DnsCache {
  private readonly resolver: DnsResolver;
  private readonly clock: () => number;
  private readonly maximumItems: number;
  private readonly maximumPendingLookups: number;
  private readonly maximumAddresses: number;
  private readonly maximumTTL: number;
  private readonly records = new Map<string, CacheRecord>();
  private readonly pending = new Map<string, PendingLookup>();
  private hitCount = 0;
  private resolverCallCount = 0;
  private evictionCount = 0;

  constructor(options: DnsCacheOptions) {
    this.resolver = options.resolver;
    this.clock = options.nowMilliseconds;
    this.maximumItems = options.maximumItems ?? DEFAULT_MAXIMUM_ITEMS;
    this.maximumPendingLookups = options.maximumPendingLookups ?? DEFAULT_MAXIMUM_PENDING;
    this.maximumAddresses = options.maximumAddressesPerHostname ?? DEFAULT_MAXIMUM_ADDRESSES;
    this.maximumTTL = options.maximumTTLMilliseconds ?? DEFAULT_MAXIMUM_TTL_MILLISECONDS;
    validatePositiveInteger(this.maximumItems, "maximumItems");
    validatePositiveInteger(this.maximumPendingLookups, "maximumPendingLookups");
    validatePositiveInteger(this.maximumAddresses, "maximumAddressesPerHostname");
    validateNonNegativeFinite(this.maximumTTL, "maximumTTLMilliseconds");
  }

  get stats(): DnsCacheStats {
    return {
      entries: this.records.size,
      pending: this.pending.size,
      cacheHits: this.hitCount,
      resolverCalls: this.resolverCallCount,
      evictions: this.evictionCount,
    };
  }

  lookup(
    hostname: string,
    families: readonly DnsAddressFamily[],
    signal: AbortSignal,
  ): Promise<readonly DnsAddress[]> {
    if (hostname.length === 0) return Promise.reject(new TypeError("DNS hostname is empty"));
    if (signal.aborted) return Promise.reject(signal.reason);
    const requested = familyKey(families);
    const normalizedHostname = hostname.toLowerCase();
    const cached = this.takeCached(normalizedHostname, families);
    if (cached.length !== 0) {
      this.hitCount++;
      return Promise.resolve(cached);
    }

    const pendingKey = normalizedHostname + "|" + requested;
    let lookup = this.pending.get(pendingKey);
    if (lookup === undefined) {
      if (this.pending.size >= this.maximumPendingLookups) {
        return Promise.reject(new DnsLookupLimitError(this.maximumPendingLookups));
      }
      lookup = this.startLookup(pendingKey, hostname, normalizedHostname, families);
    }
    return this.joinLookup(lookup, signal);
  }

  /**
   * Endpoints already known for this hostname, without resolving.
   *
   * Read-only on purpose: it neither performs a lookup nor advances the round-robin
   * rotation nor refreshes recency, because a caller deciding how to pool must not
   * change what the next real lookup answers. An empty result means "not known", never
   * "no addresses exist".
   */
  knownAddresses(
    hostname: string,
    families: readonly DnsAddressFamily[] = [4, 6],
  ): readonly string[] {
    if (hostname.length === 0) return [];
    const record = this.records.get(hostname.toLowerCase());
    if (record === undefined) return [];
    const now = this.now();
    const known: string[] = [];
    for (const address of record.addresses) {
      if (address.expiresAt <= now) continue;
      if (!hasFamily(families, address.family)) continue;
      known.push(address.address);
    }
    return known;
  }

  invalidate(hostname: string): boolean {
    return this.records.delete(hostname.toLowerCase());
  }

  clear(): void {
    this.records.clear();
  }

  private now(): number {
    const value = this.clock();
    if (!Number.isFinite(value) || value < 0) {
      throw new TypeError("DNS monotonic clock returned an invalid value");
    }
    return value;
  }

  private takeCached(
    hostname: string,
    families: readonly DnsAddressFamily[],
  ): readonly DnsAddress[] {
    const record = this.records.get(hostname);
    if (record === undefined) return [];
    const now = this.now();
    const valid: CachedAddress[] = [];
    for (const address of record.addresses) if (address.expiresAt > now) valid.push(address);
    record.addresses = valid;
    if (valid.length === 0) {
      this.records.delete(hostname);
      return [];
    }

    this.records.delete(hostname);
    this.records.set(hostname, record);
    const ipv4: DnsAddress[] = [];
    const ipv6: DnsAddress[] = [];
    for (const address of valid) {
      if (!hasFamily(families, address.family)) continue;
      const copy = {
        address: address.address,
        family: address.family,
        ttlMilliseconds: address.expiresAt - now,
      };
      if (address.family === 4) ipv4.push(copy);
      else ipv6.push(copy);
    }
    const result: DnsAddress[] = [];
    this.appendRotated(result, ipv4, record.ipv4Offset);
    this.appendRotated(result, ipv6, record.ipv6Offset);
    if (ipv4.length !== 0) record.ipv4Offset = (record.ipv4Offset + 1) % ipv4.length;
    if (ipv6.length !== 0) record.ipv6Offset = (record.ipv6Offset + 1) % ipv6.length;
    return result;
  }

  private appendRotated(result: DnsAddress[], source: readonly DnsAddress[], offset: number): void {
    for (let index = 0; index < source.length; index++) {
      const address = source[(offset + index) % source.length];
      if (address !== undefined) result.push(address);
    }
  }

  private startLookup(
    key: string,
    originalHostname: string,
    normalizedHostname: string,
    families: readonly DnsAddressFamily[],
  ): PendingLookup {
    const controller = new AbortController();
    const lookup: PendingLookup = {
      key,
      controller,
      promise: Promise.resolve<readonly DnsAddress[]>([]),
      consumers: 0,
      settled: false,
    };
    this.resolverCallCount++;
    lookup.promise = callResolver(
      this.resolver,
      originalHostname,
      families,
      this.maximumAddresses,
      controller.signal,
    ).then(
      (addresses) => {
        try {
          const normalized = this.normalize(addresses, families);
          if (normalized.length === 0) throw new DnsNoAddressError(originalHostname);
          this.store(normalizedHostname, families, normalized);
          return normalized;
        } finally {
          lookup.settled = true;
          this.pending.delete(key);
        }
      },
      (error) => {
        lookup.settled = true;
        this.pending.delete(key);
        throw error;
      },
    );
    this.pending.set(key, lookup);
    return lookup;
  }

  private joinLookup(lookup: PendingLookup, signal: AbortSignal): Promise<readonly DnsAddress[]> {
    const result = Promise.withResolvers<readonly DnsAddress[]>();
    let finished = false;
    lookup.consumers++;
    const release = (): void => {
      if (finished) return;
      finished = true;
      lookup.consumers--;
      if (lookup.consumers === 0 && !lookup.settled) {
        lookup.controller.abort(new TypeError("DNS lookup has no remaining consumer"));
      }
    };
    const unsubscribe = signal[abortSignalSubscribe](() => {
      if (finished) return;
      result.reject(signal.reason);
      release();
    });
    lookup.promise.then(
      (addresses) => {
        if (!finished) result.resolve(copyAddresses(addresses));
        unsubscribe();
        release();
      },
      (error) => {
        if (!finished) result.reject(error);
        unsubscribe();
        release();
      },
    );
    return result.promise;
  }

  private normalize(
    addresses: readonly DnsAddress[],
    families: readonly DnsAddressFamily[],
  ): readonly DnsAddress[] {
    if (addresses.length > this.maximumAddresses) {
      throw new TypeError("DNS provider exceeded the requested address bound");
    }
    const result: DnsAddress[] = [];
    const seen = new Set<string>();
    for (const address of addresses) {
      if (result.length >= this.maximumAddresses) break;
      if (!hasFamily(families, address.family)) continue;
      if (address.address.length === 0) throw new TypeError("DNS returned an empty address");
      if (address.family === 4 && !isIPv4Address(address.address)) {
        throw new TypeError("DNS returned an invalid IPv4 address");
      }
      if (address.family === 6 && !isIPv6Address(address.address)) {
        throw new TypeError("DNS returned an invalid IPv6 address");
      }
      validateNonNegativeFinite(address.ttlMilliseconds, "DNS record TTL");
      const key = String(address.family) + "|" + address.address;
      if (seen.has(key)) continue;
      seen.add(key);
      result.push({
        address: address.address,
        family: address.family,
        ttlMilliseconds: Math.min(address.ttlMilliseconds, this.maximumTTL),
      });
    }
    return result;
  }

  private store(
    hostname: string,
    families: readonly DnsAddressFamily[],
    addresses: readonly DnsAddress[],
  ): void {
    const now = this.now();
    const retained: CachedAddress[] = [];
    const previous = this.records.get(hostname);
    if (previous !== undefined) {
      for (const address of previous.addresses) {
        if (address.expiresAt > now && !hasFamily(families, address.family)) {
          retained.push(address);
        }
      }
    }
    for (const address of addresses) {
      if (address.ttlMilliseconds === 0) continue;
      retained.push({
        address: address.address,
        family: address.family,
        expiresAt: Math.min(Number.MAX_SAFE_INTEGER, now + address.ttlMilliseconds),
      });
    }
    if (retained.length === 0) return;

    if (previous === undefined && this.records.size >= this.maximumItems) {
      for (const oldest of this.records.keys()) {
        this.records.delete(oldest);
        this.evictionCount++;
        break;
      }
    }
    this.records.delete(hostname);
    this.records.set(hostname, {
      hostname,
      addresses: retained,
      ipv4Offset: previous?.ipv4Offset ?? 0,
      ipv6Offset: previous?.ipv6Offset ?? 0,
    });
  }
}

export interface DnsConnectorOptions {
  readonly cache: DnsCache;
  readonly connector: SocketConnector;
  readonly scheduler: Scheduler;
  readonly families?: readonly DnsAddressFamily[];
  readonly preferredFamily?: DnsAddressFamily;
  readonly attemptDelayMilliseconds?: number;
  readonly maximumAttempts?: number;
}

function connectWith(
  connector: SocketConnector,
  address: ConnectAddress,
  signal: AbortSignal,
): Promise<ByteConnection> {
  try {
    return connector.connect(address, signal);
  } catch (error) {
    return Promise.reject(error);
  }
}

/** DNS-caching connector with bounded RFC 8305-style staggered address attempts. */
export class DnsConnector implements SocketConnector {
  private readonly cache: DnsCache;
  private readonly connector: SocketConnector;
  private readonly scheduler: Scheduler;
  private readonly families: readonly DnsAddressFamily[];
  private readonly preferredFamily: DnsAddressFamily | undefined;
  private readonly attemptDelay: number;
  private readonly maximumAttempts: number;

  constructor(options: DnsConnectorOptions) {
    this.cache = options.cache;
    this.connector = options.connector;
    this.scheduler = options.scheduler;
    this.families = options.families ?? [4, 6];
    familyKey(this.families);
    this.preferredFamily = options.preferredFamily;
    if (this.preferredFamily !== undefined && !hasFamily(this.families, this.preferredFamily)) {
      throw new RangeError("preferredFamily must be present in families");
    }
    this.attemptDelay = options.attemptDelayMilliseconds ?? DEFAULT_ATTEMPT_DELAY_MILLISECONDS;
    this.maximumAttempts = options.maximumAttempts ?? DEFAULT_MAXIMUM_ATTEMPTS;
    validateNonNegativeFinite(this.attemptDelay, "attemptDelayMilliseconds");
    validatePositiveInteger(this.maximumAttempts, "maximumAttempts");
  }

  connect(address: ConnectAddress, signal: AbortSignal): Promise<ByteConnection> {
    if (signal.aborted) return Promise.reject(signal.reason);
    if (address.resolvedAddress !== undefined || isLiteralAddress(address.hostname)) {
      return connectWith(this.connector, address, signal);
    }
    return this.cache.lookup(address.hostname, this.families, signal).then((addresses) => {
      signal.throwIfAborted();
      return this.connectResolved(address, this.order(addresses), signal);
    });
  }

  private order(addresses: readonly DnsAddress[]): readonly DnsAddress[] {
    const ipv4: DnsAddress[] = [];
    const ipv6: DnsAddress[] = [];
    for (const address of addresses) {
      if (address.family === 4) ipv4.push(address);
      else ipv6.push(address);
    }
    const firstFamily = this.preferredFamily ?? addresses[0]?.family ?? 4;
    const first = firstFamily === 4 ? ipv4 : ipv6;
    const second = firstFamily === 4 ? ipv6 : ipv4;
    const ordered: DnsAddress[] = [];
    let index = 0;
    while (
      ordered.length < this.maximumAttempts &&
      (index < first.length || index < second.length)
    ) {
      const primary = first[index];
      if (primary !== undefined) ordered.push(primary);
      if (ordered.length >= this.maximumAttempts) break;
      const alternate = second[index];
      if (alternate !== undefined) ordered.push(alternate);
      index++;
    }
    return ordered;
  }

  private connectResolved(
    logical: ConnectAddress,
    addresses: readonly DnsAddress[],
    signal: AbortSignal,
  ): Promise<ByteConnection> {
    if (addresses.length === 0) return Promise.reject(new DnsNoAddressError(logical.hostname));
    const result = Promise.withResolvers<ByteConnection>();
    const controllers = new Set<AbortController>();
    const failures: unknown[] = [];
    let nextIndex = 0;
    let active = 0;
    let settled = false;
    let nextTimer: CancelHandle | null = null;
    let unsubscribe = (): void => {};

    const stopOthers = (reason: unknown): void => {
      nextTimer?.cancel();
      nextTimer = null;
      for (const controller of controllers) controller.abort(reason);
      controllers.clear();
    };
    const rejectAll = (reason: unknown): void => {
      if (settled) return;
      settled = true;
      unsubscribe();
      stopOthers(reason);
      result.reject(reason);
    };
    const rejectExhausted = (): void => {
      if (settled || active !== 0 || nextIndex < addresses.length) return;
      this.cache.invalidate(logical.hostname);
      rejectAll(new DnsConnectionError(logical.hostname, failures));
    };
    const armNext = (): void => {
      if (settled || nextTimer !== null || nextIndex >= addresses.length) return;
      try {
        nextTimer = this.scheduler.delay(this.attemptDelay, () => {
          nextTimer = null;
          launchNext();
        });
      } catch (error) {
        rejectAll(error);
      }
    };
    const launchNext = (): void => {
      if (settled) return;
      const resolved = addresses[nextIndex];
      if (resolved === undefined) {
        rejectExhausted();
        return;
      }
      nextIndex++;
      active++;
      const controller = new AbortController();
      controllers.add(controller);
      const target: ConnectAddress =
        logical.alpnProtocols === undefined
          ? {
              hostname: logical.hostname,
              port: logical.port,
              secure: logical.secure,
              connectTimeoutMs: logical.connectTimeoutMs,
              resolvedAddress: resolved.address,
              resolvedFamily: resolved.family,
            }
          : {
              hostname: logical.hostname,
              port: logical.port,
              secure: logical.secure,
              connectTimeoutMs: logical.connectTimeoutMs,
              alpnProtocols: logical.alpnProtocols,
              resolvedAddress: resolved.address,
              resolvedFamily: resolved.family,
            };
      connectWith(this.connector, target, controller.signal).then(
        (connection) => {
          controllers.delete(controller);
          active--;
          if (settled) {
            connection.close();
            return;
          }
          settled = true;
          unsubscribe();
          stopOthers(new TypeError("Another DNS address connected first"));
          result.resolve(connection);
        },
        (error) => {
          controllers.delete(controller);
          active--;
          if (settled) return;
          failures.push(error);
          if (nextTimer !== null) {
            nextTimer.cancel();
            nextTimer = null;
          }
          if (nextIndex < addresses.length) launchNext();
          else rejectExhausted();
        },
      );
      armNext();
    };

    unsubscribe = signal[abortSignalSubscribe](() => rejectAll(signal.reason));
    launchNext();
    return result.promise;
  }
}

import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import type { FetchInterceptor } from "./interceptor.ts";
import {
  collectResponseBody,
  settleResponseTrailers,
  validateResponseBodyLimit,
} from "./response-body.ts";

export interface DumpOptions {
  readonly maximumBytes?: number;
}

/** Consume and discard a complete response under an explicit byte bound. */
export class DumpInterceptor implements FetchInterceptor {
  private readonly maximumBytes: number;

  constructor(options: DumpOptions = {}) {
    this.maximumBytes = options.maximumBytes ?? 1024 * 1024;
    validateResponseBodyLimit(this.maximumBytes);
  }

  async dispatch(request: TransportRequest, next: FetchTransport): Promise<TransportResponse> {
    const response = await next.dispatch(request);
    await collectResponseBody(response, request.signal, this.maximumBytes);
    const trailers = await settleResponseTrailers(response, request.signal);
    return {
      status: response.status,
      statusText: response.statusText,
      headers: response.headers,
      body: null,
      trailers: trailers === undefined ? undefined : Promise.resolve(trailers),
    };
  }
}

import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";

/** A shared policy layer. The first interceptor is the outermost request observer. */
export interface FetchInterceptor {
  dispatch(request: TransportRequest, next: FetchTransport): Promise<TransportResponse>;
}

class InterceptorTransport implements FetchTransport {
  private readonly interceptor: FetchInterceptor;
  private readonly next: FetchTransport;

  constructor(interceptor: FetchInterceptor, next: FetchTransport) {
    this.interceptor = interceptor;
    this.next = next;
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    return this.interceptor.dispatch(request, this.next);
  }
}

/**
 * Request flow follows array order; response and error flow unwind in reverse.
 * The input array is copied structurally by building immutable transport layers.
 *
 * **Which order to put them in is not free, and three of the constraints are
 * demonstrable rather than stylistic.** Each is a test in
 * `runtime/web-platform/test/interceptor-order.test.ts`, which runs both
 * arrangements and asserts that the wrong one misbehaves — so these are claims with
 * their own controls rather than advice.
 *
 * - `ResponseErrorInterceptor` must be **outside** `RetryInterceptor`. It throws on any
 *   status at or above 400, so from the inside it converts a retryable `503` into an
 *   exception before retry ever sees a status to retry.
 * - `ResponseErrorInterceptor` must be **outside** `AuthenticationInterceptor`, for the
 *   same reason with a sharper edge: a `401` is a challenge, and thrown from the inside
 *   it is an error the authenticator is never offered.
 * - `AuthenticationInterceptor` should be **outside** `RetryInterceptor`. Both orders
 *   work and the difference is arithmetic, but it runs the opposite way to the guess
 *   that a challenge is best answered close to the transport. A `401` is not a
 *   retryable status, so retry never loops on a challenge; what happens instead is that
 *   with retry on the outside, *every* retry of a retryable failure re-runs the whole
 *   authentication exchange from unauthenticated. With authentication outside, the
 *   credential is obtained once and retry re-sends a request that already carries it.
 *   The difference only shows when a retryable status and a challenge both occur, which
 *   is exactly what the test scripts.
 *
 * `DumpInterceptor` is not on that list because it is not an ordering question but an
 * exclusion: it returns `body: null`, so anything outside it that needs a body — which
 * is exactly `ResponseErrorInterceptor`, whose error carries one — gets nothing. Compose
 * one or the other.
 *
 * Nothing is claimed here about where `DiagnosticsInterceptor` or
 * `DeduplicationInterceptor` belong. Both have defensible positions and this lane has
 * not demonstrated either, so saying so is more useful than a preference dressed as a
 * rule.
 */
export function composeFetchTransport(
  transport: FetchTransport,
  interceptors: readonly FetchInterceptor[],
): FetchTransport {
  let result = transport;
  for (let index = interceptors.length - 1; index >= 0; index--) {
    const interceptor = interceptors[index];
    if (interceptor !== undefined) result = new InterceptorTransport(interceptor, result);
  }
  return result;
}

import { ignoreRejection } from "../core/promise.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type { ByteConnection } from "../provider/primitives.ts";
import type {
  FetchTransport,
  TransportRequest,
  TransportResponse,
} from "../fetch/transport.ts";
import { ReadableStream } from "../streams/readable.ts";
import type { WritableStream } from "../streams/writable.ts";
import { collectResponseBody, settleResponseTrailers } from "./response-body.ts";

/**
 * What every operation reports before the body is dealt with.
 *
 * A status that a caller would treat as a failure is still a result here. Deciding what
 * a 404 means belongs to the caller; a dispatcher that threw on it would make the body
 * unreachable for the callers who want to read it.
 */
export interface DispatchInfo {
  readonly status: number;
  readonly statusText: string;
  readonly headers: readonly HeaderEntry[];
}

export interface BufferedResult extends DispatchInfo {
  readonly body: Uint8Array;
  /** Absent when the provider cannot expose trailers, which is not the same as none. */
  readonly trailers: readonly HeaderEntry[] | undefined;
}

export interface StreamedResult extends DispatchInfo {
  readonly trailers: readonly HeaderEntry[] | undefined;
}

export interface TunnelEstablished extends DispatchInfo {
  readonly tunnelled: true;
  /** The caller owns it: it has left its pool and nothing else will close it. */
  readonly connection: ByteConnection;
}

export interface TunnelDeclined {
  readonly tunnelled: false;
  /** An ordinary response, body included -- usually the explanation. */
  readonly response: TransportResponse;
}

export type TunnelOutcome = TunnelEstablished | TunnelDeclined;

export interface BufferedOptions {
  /** Required, and validated. A default here would be a size limit nobody chose. */
  readonly maxBytes: number;
}

/** Receives the response head and returns where the body should go. */
export type StreamFactory = (info: DispatchInfo) => WritableStream<Uint8Array>;

/** Receives the response and returns the stream the caller will read. */
export type PipelineHandler = (
  info: DispatchInfo,
  body: ReadableStream<Uint8Array> | null,
) => ReadableStream<Uint8Array>;

function infoOf(response: TransportResponse): DispatchInfo {
  return {
    status: response.status,
    statusText: response.statusText,
    headers: response.headers,
  };
}

async function discard(response: TransportResponse, reason: unknown): Promise<void> {
  if (response.body !== null) {
    try {
      await response.body.cancel(reason);
    } catch {
      // The original failure stays the observable one.
    }
  }
  if (response.trailers !== undefined) ignoreRejection(response.trailers);
}

/**
 * The Undici-shaped operations, over any transport that can dispatch.
 *
 * These are methods rather than exported functions because `request`, `stream` and
 * `pipeline` are the names the shape is known by, and three exports with those names in
 * a shared module namespace would be indefensible — quite apart from what a backend that
 * resolves collisions by qualifying both would make of them.
 *
 * **This is not a claim of Undici parity.** The plan separates the architecture and
 * behaviour, which are required, from package-level `import "undici"` compatibility,
 * which is a facade decision; and no Undici revision is pinned in this repository, so
 * an API ledger with evidence per export cannot honestly be written. What is written
 * down here is what these operations do, tested — not what somebody else's do.
 *
 * `connect` and `upgrade` need a transport that can surrender its connection, which is
 * what `TransportRequest.acceptTunnel` and `TransportResponse.connection` are for. A
 * transport that cannot do it answers normally, so both operations report a response
 * that was not a switch rather than pretending; they never invent a connection.
 */
export class DispatcherOperations {
  readonly #transport: FetchTransport;

  constructor(transport: FetchTransport) {
    this.#transport = transport;
  }

  /** Dispatches and reads the whole body, bounded. */
  async request(
    request: TransportRequest,
    options: BufferedOptions,
  ): Promise<BufferedResult> {
    const response = await this.#transport.dispatch(request);
    const body = await collectResponseBody(response, request.signal, options.maxBytes);
    const trailers = await settleResponseTrailers(response, request.signal);
    return { ...infoOf(response), body, trailers };
  }

  /**
   * Dispatches and writes the body into the stream `factory` returns.
   *
   * The factory is called once, after the head arrives and before any byte is read, so
   * it can choose a destination from the status. A factory that throws cancels the
   * response with that error rather than leaving the body unread.
   */
  async stream(request: TransportRequest, factory: StreamFactory): Promise<StreamedResult> {
    const response = await this.#transport.dispatch(request);
    const info = infoOf(response);

    let destination: WritableStream<Uint8Array>;
    try {
      request.signal.throwIfAborted();
      destination = factory(info);
    } catch (error) {
      await discard(response, error);
      throw error;
    }

    const writer = destination.getWriter();
    const reader = response.body?.getReader() ?? null;
    try {
      while (reader !== null) {
        const item = await reader.read();
        if (item.done) break;
        if (item.value !== undefined) await writer.write(item.value);
      }
      await writer.close();
    } catch (error) {
      // Both ends, because either may be the one that failed and the other is then
      // still holding resources that nothing else will release.
      if (reader !== null) {
        await reader.cancel(error).then(
          () => {},
          () => {},
        );
      }
      await writer.abort(error).then(
        () => {},
        () => {},
      );
      if (response.trailers !== undefined) ignoreRejection(response.trailers);
      throw error;
    } finally {
      reader?.releaseLock();
      writer.releaseLock();
    }

    return { ...info, trailers: await settleResponseTrailers(response, request.signal) };
  }

  /**
   * Opens a tunnel with `CONNECT` and hands back the connection.
   *
   * The request is dispatched through the whole stack, so proxies, DNS and pooling
   * apply to the tunnel exactly as they do to a request — which is the reason for
   * routing it through `dispatch` rather than reaching for a connector.
   */
  async connect(request: TransportRequest): Promise<TunnelOutcome> {
    return this.#tunnel({ ...request, method: "CONNECT", acceptTunnel: true });
  }

  /**
   * Asks the server to switch to `protocol` and hands back the connection if it does.
   *
   * The protocol is named here rather than through `Connection` and `Upgrade` headers,
   * which the transport manages; omitting it sends no upgrade request at all, which is
   * still useful for a server that switches on its own terms.
   */
  async upgrade(request: TransportRequest, protocol?: string): Promise<TunnelOutcome> {
    return this.#tunnel({
      ...request,
      acceptTunnel: true,
      ...(protocol === undefined ? {} : { upgradeProtocol: protocol }),
    });
  }

  async #tunnel(request: TransportRequest): Promise<TunnelOutcome> {
    const response = await this.#transport.dispatch(request);
    const connection = response.connection;
    if (connection === undefined) {
      // Declined, or a transport that cannot surrender its socket. Either way the
      // response is the answer, body and all, and the caller can tell the difference
      // by reading it.
      return { tunnelled: false, response };
    }
    return { tunnelled: true, ...infoOf(response), connection };
  }

  /**
   * Dispatches and hands the response to `handler`, returning what it produces.
   *
   * Synchronous in the sense that matters: the stream is returned before the dispatch
   * completes, so a caller can wire it up and read. A dispatch that fails surfaces as
   * an error on that stream rather than as a rejected promise nobody is awaiting, and
   * cancelling it cancels the response body underneath.
   */
  pipeline(request: TransportRequest, handler: PipelineHandler): ReadableStream<Uint8Array> {
    const transport = this.#transport;
    let inner: ReadableStreamDefaultReaderLike | null = null;
    let cancelled: { reason: unknown } | null = null;

    return new ReadableStream<Uint8Array>({
      async start(controller) {
        let response: TransportResponse;
        try {
          response = await transport.dispatch(request);
        } catch (error) {
          controller.error(error);
          return;
        }
        let produced: ReadableStream<Uint8Array>;
        try {
          produced = handler(infoOf(response), response.body);
        } catch (error) {
          await discard(response, error);
          controller.error(error);
          return;
        }
        const reader = produced.getReader();
        inner = reader;
        // A cancel that arrived while the dispatch was still in flight has nothing to
        // act on yet; it is applied here instead of being lost.
        if (cancelled !== null) {
          await reader.cancel(cancelled.reason).then(
            () => {},
            () => {},
          );
          return;
        }
        try {
          for (;;) {
            const item = await reader.read();
            if (item.done) break;
            if (item.value !== undefined) controller.enqueue(item.value);
          }
          controller.close();
        } catch (error) {
          controller.error(error);
        } finally {
          reader.releaseLock();
        }
      },
      async cancel(reason) {
        cancelled = { reason };
        if (inner !== null) {
          await inner.cancel(reason).then(
            () => {},
            () => {},
          );
        }
      },
    });
  }
}

/** The part of a reader this module uses; named so `inner` needs no cast. */
interface ReadableStreamDefaultReaderLike {
  read(): Promise<{ done: boolean; value?: Uint8Array }>;
  cancel(reason?: unknown): Promise<void>;
  releaseLock(): void;
}

import { TransportError } from "../fetch/transport.ts";
import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import type { URLRecord } from "../provider/primitives.ts";
import type { OriginDispatcher, OriginDispatcherStats } from "./agent.ts";

export interface PoolStats extends OriginDispatcherStats {
  readonly dispatchers: number;
  readonly idleDispatchers: number;
  readonly dispatched: number;
}

function promiseFrom(action: () => Promise<void>): Promise<void> {
  try {
    return action();
  } catch (error) {
    return Promise.reject(error);
  }
}

function dispatchWith(
  dispatcher: OriginDispatcher,
  request: TransportRequest,
): Promise<TransportResponse> {
  try {
    return dispatcher.dispatch(request);
  } catch (error) {
    return Promise.reject(error);
  }
}

/** A fixed-size, same-origin dispatcher pool with deterministic round-robin selection. */
export class RoundRobinPool implements OriginDispatcher {
  private readonly origin: string;
  private readonly dispatchers: readonly OriginDispatcher[];
  private nextIndex = 0;
  private dispatchedCount = 0;
  private accepting = true;
  private destroyedState = false;
  private closeResult: Promise<void> | null = null;
  private destroyResult: Promise<void> | null = null;

  constructor(origin: URLRecord, dispatchers: readonly OriginDispatcher[]) {
    if (dispatchers.length === 0) {
      throw new RangeError("A round-robin pool requires at least one dispatcher");
    }
    this.origin = upstreamOrigin(origin);
    this.dispatchers = dispatchers.slice();
  }

  get closed(): boolean {
    return !this.accepting;
  }

  get destroyed(): boolean {
    return this.destroyedState;
  }

  get idle(): boolean {
    for (const dispatcher of this.dispatchers) if (!dispatcher.idle) return false;
    return true;
  }

  get stats(): PoolStats {
    let connections = 0;
    let pending = 0;
    let running = 0;
    let idleDispatchers = 0;
    for (const dispatcher of this.dispatchers) {
      const stats = dispatcher.stats;
      connections += stats.connections;
      pending += stats.pending;
      running += stats.running;
      if (dispatcher.idle) idleDispatchers++;
    }
    return {
      dispatchers: this.dispatchers.length,
      idleDispatchers,
      connections,
      pending,
      running,
      dispatched: this.dispatchedCount,
    };
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (!this.accepting) return Promise.reject(new TypeError("Pool is closed"));
    if (request.signal.aborted) return Promise.reject(request.signal.reason);
    if (request.url.origin !== this.origin) {
      return Promise.reject(new TypeError("Pool request origin does not match its upstream"));
    }
    const dispatcher = this.dispatchers[this.nextIndex];
    if (dispatcher === undefined) {
      return Promise.reject(new TypeError("Pool has no dispatcher at its selected index"));
    }
    this.nextIndex = (this.nextIndex + 1) % this.dispatchers.length;
    this.dispatchedCount++;
    return dispatchWith(dispatcher, request);
  }

  close(): Promise<void> {
    if (this.destroyResult !== null) return this.destroyResult;
    if (this.closeResult !== null) return this.closeResult;
    this.accepting = false;
    const closing: Promise<void>[] = [];
    for (const dispatcher of this.dispatchers) {
      closing.push(promiseFrom(() => dispatcher.close()));
    }
    this.closeResult = Promise.all(closing)
      .then(() => {})
      .finally(() => {
        this.destroyedState = true;
      });
    return this.closeResult;
  }

  destroy(reason: unknown = new TypeError("Pool destroyed")): Promise<void> {
    if (this.destroyResult !== null) return this.destroyResult;
    this.accepting = false;
    const destroying: Promise<void>[] = [];
    for (const dispatcher of this.dispatchers) {
      destroying.push(promiseFrom(() => dispatcher.destroy(reason)));
    }
    this.destroyResult = Promise.all(destroying)
      .then(() => {})
      .finally(() => {
        this.destroyedState = true;
      });
    return this.destroyResult;
  }
}

/** The common Pool contract uses deterministic round-robin selection. */
export class Pool extends RoundRobinPool {}

export interface BalancedPoolUpstream {
  /** A parsed canonical upstream; its path, query, fragment and credentials are ignored. */
  readonly url: URLRecord;
  readonly dispatcher: OriginDispatcher;
  readonly weight?: number;
}

export interface BalancedPoolOptions {
  readonly maximumUpstreams?: number;
  /** Amount removed after a typed transport failure and restored after success. */
  readonly errorPenalty?: number;
}

export interface BalancedPoolUpstreamStats extends OriginDispatcherStats {
  readonly origin: string;
  readonly configuredWeight: number;
  readonly healthWeight: number;
  readonly idle: boolean;
  readonly dispatched: number;
  readonly failures: number;
}

export interface BalancedPoolStats extends OriginDispatcherStats {
  readonly upstreams: number;
  readonly idleUpstreams: number;
  readonly dispatched: number;
  readonly entries: readonly BalancedPoolUpstreamStats[];
}

interface BalancedRecord {
  readonly origin: string;
  readonly url: URLRecord;
  readonly dispatcher: OriginDispatcher;
  readonly configuredWeight: number;
  healthWeight: number;
  currentWeight: number;
  dispatched: number;
  failures: number;
}

const MAXIMUM_BALANCING_VALUE = 1_000_000;

export class BalancedPoolMissingUpstreamError extends Error {
  readonly code = "UND_ERR_BPL_MISSING_UPSTREAM";

  constructor() {
    super("No upstream is available in the balanced pool");
    this.name = "BalancedPoolMissingUpstreamError";
  }
}

export class BalancedPoolLimitError extends Error {
  readonly code = "UND_ERR_BPL_UPSTREAM_LIMIT";
  readonly maximumUpstreams: number;

  constructor(maximumUpstreams: number) {
    super("The balanced pool upstream limit has been reached");
    this.name = "BalancedPoolLimitError";
    this.maximumUpstreams = maximumUpstreams;
  }
}

function upstreamOrigin(url: URLRecord): string {
  if (url.protocol !== "http:" && url.protocol !== "https:") {
    throw new TypeError("Balanced pool upstreams require an HTTP(S) URL");
  }
  if (url.host === "") throw new TypeError("Balanced pool upstreams require a nonempty host");
  if (url.username !== "" || url.password !== "") {
    throw new TypeError("Balanced pool upstream URLs cannot contain credentials");
  }
  return url.protocol + "//" + url.host;
}

function routedRequest(request: TransportRequest, upstream: BalancedRecord): TransportRequest {
  const url: URLRecord = {
    href: upstream.origin + request.url.pathname + request.url.search + request.url.hash,
    protocol: upstream.url.protocol,
    hostname: upstream.url.hostname,
    port: upstream.url.port,
    host: upstream.url.host,
    origin: upstream.origin,
    pathname: request.url.pathname,
    search: request.url.search,
    hash: request.url.hash,
    username: "",
    password: "",
  };
  return {
    url,
    method: request.method,
    headers: request.headers,
    body: request.body,
    bodyLength: request.bodyLength,
    replayBody: request.replayBody,
    signal: request.signal,
  };
}

/** Smooth weighted round-robin over mutable, provider-owned upstream dispatchers. */
export class BalancedPool implements FetchTransport {
  private readonly records = new Map<string, BalancedRecord>();
  /** Includes records removed from selection while their graceful close is pending. */
  private readonly owned = new Set<OriginDispatcher>();
  private readonly maximumUpstreams: number;
  private readonly errorPenalty: number;
  private accepting = true;
  private destroyedState = false;
  private dispatchedCount = 0;
  private closeResult: Promise<void> | null = null;
  private destroyResult: Promise<void> | null = null;

  constructor(upstreams: readonly BalancedPoolUpstream[] = [], options: BalancedPoolOptions = {}) {
    this.maximumUpstreams = options.maximumUpstreams ?? 64;
    this.errorPenalty = options.errorPenalty ?? 15;
    for (const [value, name] of [
      [this.maximumUpstreams, "maximumUpstreams"],
      [this.errorPenalty, "errorPenalty"],
    ] as const) {
      if (!Number.isSafeInteger(value) || value < 1 || value > MAXIMUM_BALANCING_VALUE) {
        throw new RangeError(name + " must be an integer from 1 through 1000000");
      }
    }
    for (const upstream of upstreams) this.addUpstream(upstream);
  }

  get closed(): boolean {
    return !this.accepting;
  }

  get destroyed(): boolean {
    return this.destroyedState;
  }

  get idle(): boolean {
    for (const record of this.records.values()) if (!record.dispatcher.idle) return false;
    return true;
  }

  get upstreams(): readonly string[] {
    return Array.from(this.records.keys());
  }

  get stats(): BalancedPoolStats {
    let connections = 0;
    let pending = 0;
    let running = 0;
    let idleUpstreams = 0;
    const entries: BalancedPoolUpstreamStats[] = [];
    for (const record of this.records.values()) {
      const stats = record.dispatcher.stats;
      if (record.dispatcher.idle) idleUpstreams++;
      connections += stats.connections;
      pending += stats.pending;
      running += stats.running;
      entries.push({
        origin: record.origin,
        configuredWeight: record.configuredWeight,
        healthWeight: record.healthWeight,
        idle: record.dispatcher.idle,
        dispatched: record.dispatched,
        failures: record.failures,
        connections: stats.connections,
        pending: stats.pending,
        running: stats.running,
      });
    }
    return {
      upstreams: this.records.size,
      idleUpstreams,
      dispatched: this.dispatchedCount,
      connections,
      pending,
      running,
      entries,
    };
  }

  addUpstream(upstream: BalancedPoolUpstream): boolean {
    if (!this.accepting) throw new TypeError("Balanced pool is closed");
    const origin = upstreamOrigin(upstream.url);
    if (this.records.has(origin)) return false;
    if (this.records.size >= this.maximumUpstreams) {
      throw new BalancedPoolLimitError(this.maximumUpstreams);
    }
    const weight = upstream.weight ?? 100;
    if (!Number.isSafeInteger(weight) || weight < 1 || weight > MAXIMUM_BALANCING_VALUE) {
      throw new RangeError("Upstream weight must be an integer from 1 through 1000000");
    }
    this.records.set(origin, {
      origin,
      url: upstream.url,
      dispatcher: upstream.dispatcher,
      configuredWeight: weight,
      healthWeight: weight,
      currentWeight: 0,
      dispatched: 0,
      failures: 0,
    });
    this.owned.add(upstream.dispatcher);
    return true;
  }

  removeUpstream(origin: string): Promise<boolean> {
    const record = this.records.get(origin);
    if (record === undefined) return Promise.resolve(false);
    this.records.delete(origin);
    return promiseFrom(() => record.dispatcher.close()).then(
      () => {
        this.owned.delete(record.dispatcher);
        return true;
      },
      (error) => {
        if (this.accepting && !this.records.has(origin)) this.records.set(origin, record);
        throw error;
      },
    );
  }

  /** Provider lifecycle hooks use this when a response body or live connection fails later. */
  reportFailure(origin: string, error: unknown): boolean {
    const record = this.records.get(origin);
    if (record === undefined || !(error instanceof TransportError)) return false;
    record.failures++;
    record.healthWeight = Math.max(1, record.healthWeight - this.errorPenalty);
    return true;
  }

  /** A successful provider lifecycle event restores one health step. */
  reportSuccess(origin: string): boolean {
    const record = this.records.get(origin);
    if (record === undefined) return false;
    record.healthWeight = Math.min(
      record.configuredWeight,
      record.healthWeight + this.errorPenalty,
    );
    return true;
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (!this.accepting) return Promise.reject(new TypeError("Balanced pool is closed"));
    if (request.signal.aborted) return Promise.reject(request.signal.reason);
    let selected: BalancedRecord;
    try {
      selected = this.select();
    } catch (error) {
      return Promise.reject(error);
    }
    selected.dispatched++;
    this.dispatchedCount++;
    return dispatchWith(selected.dispatcher, routedRequest(request, selected)).then(
      (response) => {
        this.restoreRecord(selected);
        return response;
      },
      (error) => {
        this.penalizeRecord(selected, error);
        throw error;
      },
    );
  }

  close(): Promise<void> {
    if (this.destroyResult !== null) return this.destroyResult;
    if (this.closeResult !== null) return this.closeResult;
    this.accepting = false;
    const closing: Promise<void>[] = [];
    for (const dispatcher of this.owned) closing.push(promiseFrom(() => dispatcher.close()));
    this.records.clear();
    this.closeResult = Promise.all(closing).then(() => {
      this.owned.clear();
      this.destroyedState = true;
    });
    return this.closeResult;
  }

  destroy(reason: unknown = new TypeError("Balanced pool destroyed")): Promise<void> {
    if (this.destroyResult !== null) return this.destroyResult;
    this.accepting = false;
    const destroying: Promise<void>[] = [];
    for (const dispatcher of this.owned) {
      destroying.push(promiseFrom(() => dispatcher.destroy(reason)));
    }
    this.records.clear();
    this.destroyResult = Promise.all(destroying).then(() => {
      this.owned.clear();
      this.destroyedState = true;
    });
    return this.destroyResult;
  }

  private select(): BalancedRecord {
    if (this.records.size === 0) throw new BalancedPoolMissingUpstreamError();
    let selected: BalancedRecord | null = null;
    let total = 0;
    for (const record of this.records.values()) {
      record.currentWeight += record.healthWeight;
      total += record.healthWeight;
      if (selected === null || record.currentWeight > selected.currentWeight) {
        selected = record;
      }
    }
    if (selected === null) throw new BalancedPoolMissingUpstreamError();
    selected.currentWeight -= total;
    return selected;
  }

  private penalizeRecord(record: BalancedRecord, error: unknown): void {
    if (!(error instanceof TransportError)) return;
    record.failures++;
    record.healthWeight = Math.max(1, record.healthWeight - this.errorPenalty);
  }

  private restoreRecord(record: BalancedRecord): void {
    record.healthWeight = Math.min(
      record.configuredWeight,
      record.healthWeight + this.errorPenalty,
    );
  }
}

import { addressOf } from "../http/address.ts";
import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import { Http1Transport } from "../http1/transport.ts";
import type { Http1Options } from "../http1/transport.ts";
import { Http2Transport } from "../http2/transport.ts";
import type { Http2TransportOptions } from "../http2/transport.ts";
import { connectNegotiated, offeredProtocols } from "../provider/primitives.ts";
import type {
  ByteConnection,
  ConnectAddress,
  NegotiatedConnection,
  ProtocolPreference,
  Scheduler,
  SocketConnector,
} from "../provider/primitives.ts";
import { AbortController } from "../core/abort.ts";
import type { AbortSignal } from "../core/abort.ts";

/** The peer selected an application protocol this connection was not opened for. */
export class ProtocolMismatchError extends Error {
  readonly expected: string;
  readonly selected: string | null;

  constructor(expected: string, selected: string | null) {
    super(
      "The peer selected " +
        (selected === null ? "no application protocol" : selected) +
        " where " +
        expected +
        " was required",
    );
    this.name = "ProtocolMismatchError";
    this.expected = expected;
    this.selected = selected;
  }
}

const HTTP_1_1 = "http/1.1";
const H2 = "h2";

export const defaultProtocolPreference: ProtocolPreference = {
  ordered: [H2, HTTP_1_1],
  whenUnreportable: HTTP_1_1,
};

export interface ProtocolSelectingTransportOptions {
  readonly scheduler: Scheduler;
  readonly connector: SocketConnector;
  /** Protocols offered to a connector that reports its selection. */
  readonly preference?: ProtocolPreference;
  /**
   * Cleartext origins never negotiate, so HTTP/2 there is prior knowledge rather
   * than a discovery. It is opt-in per this transport and is never inferred from a
   * URL, because sending the connection preface to an HTTP/1.1 peer is not a
   * recoverable mistake.
   */
  readonly cleartextHttp2?: boolean;
  readonly http1?: Http1Options;
  readonly http2?: Http2TransportOptions;
  /** Retained protocol decisions, one per canonical origin. */
  readonly maxOrigins?: number;
}

interface Engine {
  readonly protocol: string;
  readonly transport: FetchTransport;
  drain(): Promise<void>;
  close(): void;
}

/**
 * Connector that gives an engine the connection already negotiated for it.
 *
 * The first connect adopts that stream, so selecting a protocol costs no extra
 * round trip and no second connection: the decision is made on the connection the
 * engine then uses. Later connections for the same origin negotiate again and must
 * agree; a peer that answers differently produces a typed mismatch rather than an
 * engine speaking into a stream that is not what it thinks it is.
 */
class AdoptingConnector implements SocketConnector {
  readonly reportsNegotiatedProtocol = false;
  #adopted: ByteConnection | null;
  readonly #expected: string;
  readonly #connector: SocketConnector;
  readonly #offered: readonly string[];

  constructor(
    adopted: ByteConnection,
    expected: string,
    connector: SocketConnector,
    offered: readonly string[],
  ) {
    this.#adopted = adopted;
    this.#expected = expected;
    this.#connector = connector;
    this.#offered = offered;
  }

  async connect(address: ConnectAddress, signal: AbortSignal): Promise<ByteConnection> {
    const adopted = this.#adopted;
    if (adopted !== null) {
      this.#adopted = null;
      signal.throwIfAborted();
      return adopted;
    }
    const result = await connectNegotiated(
      this.#connector,
      { ...address, alpnProtocols: this.#offered },
      signal,
    );
    if (!address.secure) return result.connection;
    // A reported selection that disagrees is a mismatch. An unreported one is not:
    // the contract means such a connector was offered exactly one protocol, so
    // there was nothing else it could have chosen.
    if (result.protocol !== null && result.protocol !== this.#expected) {
      result.connection.close();
      throw new ProtocolMismatchError(this.#expected, result.protocol);
    }
    return result.connection;
  }

  /** Releases an adopted connection that no engine ever took. */
  discard(): void {
    const adopted = this.#adopted;
    this.#adopted = null;
    adopted?.close();
  }
}

/**
 * Chooses HTTP/1.1 or HTTP/2 from what TLS actually negotiated, once per origin.
 *
 * The protocol is decided on a connection that has already been established and is
 * then handed to the engine that speaks it. Nothing reconnects to change engines and
 * nothing infers a protocol from request intent or from a URL scheme.
 */
export class ProtocolSelectingTransport implements FetchTransport {
  readonly #options: ProtocolSelectingTransportOptions;
  readonly #preference: ProtocolPreference;
  readonly #engines = new Map<string, Engine>();
  readonly #selecting = new Map<string, Promise<Engine>>();
  readonly #maxOrigins: number;
  #accepting = true;
  #drainResult: Promise<void> | null = null;

  constructor(options: ProtocolSelectingTransportOptions) {
    this.#options = options;
    this.#preference = options.preference ?? defaultProtocolPreference;
    this.#maxOrigins = options.maxOrigins ?? 64;
    if (!Number.isSafeInteger(this.#maxOrigins) || this.#maxOrigins < 1) {
      throw new RangeError("maxOrigins must be a positive safe integer");
    }
  }

  async dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (!this.#accepting) throw new TypeError("Protocol-selecting transport is closed");
    const engine = await this.#engineFor(request);
    return engine.transport.dispatch(request);
  }

  /** The protocol chosen for an origin, or null while none has been decided. */
  protocolFor(origin: string): string | null {
    return this.#engines.get(origin)?.protocol ?? null;
  }

  async drain(): Promise<void> {
    if (this.#drainResult !== null) return this.#drainResult;
    this.#accepting = false;
    this.#drainResult = this.#finishDrain();
    return this.#drainResult;
  }

  close(): void {
    this.#accepting = false;
    for (const engine of this.#engines.values()) engine.close();
    this.#engines.clear();
    this.#selecting.clear();
  }

  async #finishDrain(): Promise<void> {
    // A selection still in flight owns a connection that no engine holds yet, so it
    // is awaited before the engines are drained rather than dropped.
    const selecting = [...this.#selecting.values()];
    await Promise.all(
      selecting.map((selection) =>
        selection.then(
          () => {},
          () => {},
        ),
      ),
    );
    const draining: Promise<void>[] = [];
    for (const engine of this.#engines.values()) draining.push(engine.drain());
    await Promise.all(draining);
    this.#engines.clear();
  }

  #originOf(request: TransportRequest): string {
    const url = request.url;
    if (url.protocol !== "http:" && url.protocol !== "https:") {
      throw new TypeError("Protocol selection requires an HTTP(S) URL");
    }
    if (url.host === "") throw new TypeError("Protocol selection requires a nonempty host");
    return url.protocol + "//" + url.host;
  }

  async #engineFor(request: TransportRequest): Promise<Engine> {
    const origin = this.#originOf(request);
    const existing = this.#engines.get(origin);
    if (existing !== undefined) return existing;
    // Concurrent first requests to one origin negotiate once, not once each.
    const pending = this.#selecting.get(origin);
    if (pending !== undefined) return pending;
    const selection = this.#select(origin, request);
    this.#selecting.set(origin, selection);
    selection.then(
      () => this.#selecting.delete(origin),
      () => this.#selecting.delete(origin),
    );
    return selection;
  }

  async #select(origin: string, request: TransportRequest): Promise<Engine> {
    if (this.#engines.size >= this.#maxOrigins) {
      throw new TypeError("Protocol-selecting transport reached its origin limit");
    }
    const secure = request.url.protocol === "https:";
    if (!secure) {
      // Cleartext negotiates nothing. HTTP/2 here is configured prior knowledge.
      const engine = this.#buildEngine(
        this.#options.cleartextHttp2 === true ? H2 : HTTP_1_1,
        null,
        [],
      );
      this.#retain(origin, engine);
      return engine;
    }

    const offered = offeredProtocols(this.#options.connector, this.#preference);
    const address = addressOf(request.url, this.#options.http1?.connectTimeoutMs ?? 30000, offered);
    const cancellation = new AbortController();
    const negotiated: NegotiatedConnection = await connectNegotiated(
      this.#options.connector,
      address,
      cancellation.signal,
    );
    if (!this.#accepting) {
      negotiated.connection.close();
      throw new TypeError("Protocol-selecting transport is closed");
    }
    const protocol = negotiated.protocol ?? this.#preference.whenUnreportable;
    if (protocol !== H2 && protocol !== HTTP_1_1) {
      negotiated.connection.close();
      throw new ProtocolMismatchError(this.#preference.whenUnreportable, negotiated.protocol);
    }
    const engine = this.#buildEngine(protocol, negotiated.connection, offered);
    this.#retain(origin, engine);
    return engine;
  }

  #retain(origin: string, engine: Engine): void {
    this.#engines.set(origin, engine);
  }

  #buildEngine(
    protocol: string,
    adopted: ByteConnection | null,
    offered: readonly string[],
  ): Engine {
    const base = this.#options.connector;
    const adopting =
      adopted === null ? null : new AdoptingConnector(adopted, protocol, base, offered);
    const connector: SocketConnector = adopting ?? base;
    // An engine may be retired before it ever connects, and the adopted stream is
    // then owned by nothing. Retiring the engine releases it in both paths.
    const release = (): void => adopting?.discard();
    if (protocol === H2) {
      const transport = new Http2Transport(connector, this.#options.scheduler, this.#options.http2);
      return {
        protocol,
        transport,
        drain: () => transport.drain().finally(release),
        close: () => {
          transport.close();
          release();
        },
      };
    }
    const transport = new Http1Transport(connector, this.#options.scheduler, this.#options.http1);
    return {
      protocol,
      transport,
      drain: () => transport.drain().finally(release),
      close: () => {
        transport.close();
        release();
      },
    };
  }
}

import type { AbortSignal } from "../core/abort.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import { addressOf } from "../http/address.ts";
import { Http1Transport } from "../http1/transport.ts";
import type { Http1DispatchRoute, Http1Options } from "../http1/transport.ts";
import type {
  ByteConnection,
  ConnectAddress,
  NegotiatedConnection,
  NegotiatingSocketConnector,
  Scheduler,
  SocketConnector,
  TlsUpgrader,
  URLParser,
} from "../provider/primitives.ts";
import {
  connectNegotiated,
  isNegotiatingSocketConnector,
  isNegotiatingTlsUpgrader,
} from "../provider/primitives.ts";
import {
  basicAuthorization,
  callAuthenticator,
  HttpConnectProxyConnector,
  parseHttpEndpoint,
  proxyAddress,
  Socks5ProxyConnector,
  validateAuthorization,
  validateProxyHeaders,
} from "./proxy.ts";
import type { ProxyAuthenticator, ProxyEndpoint, Socks5ProxyOptions } from "./proxy.ts";
import { EnvironmentProxyPolicy } from "./proxy-policy.ts";
import type { EnvironmentProxyOptions, ProxyEnvironment } from "./proxy-policy.ts";

const DEFAULT_MAXIMUM_AUTHENTICATION_ATTEMPTS = 2;

export interface ProxyAgentOptions extends Http1Options {
  readonly connector: SocketConnector;
  readonly tls: TlsUpgrader;
  readonly scheduler: Scheduler;
  readonly urls: URLParser;
  readonly uri: string;
  readonly headers?: readonly HeaderEntry[];
  readonly authorization?: string;
  readonly authenticate?: ProxyAuthenticator;
  readonly maximumAuthenticationAttempts?: number;
  /** Tunnel plaintext HTTP as well as HTTPS. HTTPS always uses CONNECT. */
  readonly proxyTunnel?: boolean;
}

export interface Socks5ProxyAgentOptions extends Http1Options, Socks5ProxyOptions {}

export interface EnvironmentProxyConnectorOptions extends EnvironmentProxyOptions {
  readonly connector: SocketConnector;
  readonly tls: TlsUpgrader;
  readonly scheduler: Scheduler;
  readonly urls: URLParser;
  /** Snapshot supplied by the host facade. Shared code never reads process.env. */
  readonly environment?: ProxyEnvironment;
  readonly headers?: readonly HeaderEntry[];
  readonly authorization?: string;
  readonly authenticate?: ProxyAuthenticator;
  readonly maximumAuthenticationAttempts?: number;
}

export interface EnvHttpProxyAgentOptions extends Http1Options, EnvironmentProxyConnectorOptions {
  readonly proxyTunnel?: boolean;
}

function absoluteRequestTarget(request: TransportRequest): string {
  return (
    request.url.protocol +
    "//" +
    request.url.host +
    (request.url.pathname + request.url.search || "/")
  );
}

function retryRequest(request: TransportRequest): TransportRequest | null {
  if (request.body === null) return request;
  const replay = request.replayBody;
  if (replay === undefined || replay === null) return null;
  return { ...request, body: replay.open(), bodyLength: replay.length };
}

async function discard(response: TransportResponse): Promise<void> {
  if (response.body !== null) await response.body.cancel();
}

/**
 * Standalone-Undici-shaped HTTP proxy dispatcher.
 *
 * Plain HTTP uses absolute-form forwarding by default. HTTPS, and every request
 * when proxyTunnel is true, uses CONNECT and keeps target TLS end to end.
 */
export class ProxyAgent implements FetchTransport {
  readonly proxy: ProxyEndpoint;
  private readonly forward: Http1Transport;
  private readonly tunnel: Http1Transport;
  private readonly headers: readonly HeaderEntry[];
  private readonly authenticate: ProxyAuthenticator | undefined;
  private readonly maximumAuthenticationAttempts: number;
  private readonly initialAuthorization: string | null;
  private readonly connectTimeout: number;
  private readonly proxyTunnel: boolean;
  private closeResult: Promise<void> | null = null;

  constructor(options: ProxyAgentOptions) {
    this.proxy = parseHttpEndpoint(options.urls, options.uri);
    this.headers = validateProxyHeaders(options.headers ?? []);
    this.authenticate = options.authenticate;
    this.maximumAuthenticationAttempts =
      options.maximumAuthenticationAttempts ?? DEFAULT_MAXIMUM_AUTHENTICATION_ATTEMPTS;
    if (
      !Number.isSafeInteger(this.maximumAuthenticationAttempts) ||
      this.maximumAuthenticationAttempts < 1
    ) {
      throw new RangeError("maximumAuthenticationAttempts must be a positive safe integer");
    }
    this.initialAuthorization =
      options.authorization === undefined
        ? basicAuthorization(this.proxy.username, this.proxy.password)
        : validateAuthorization(options.authorization);
    this.connectTimeout = options.connectTimeoutMs ?? 30000;
    this.proxyTunnel = options.proxyTunnel ?? false;
    this.forward = new Http1Transport(options.connector, options.scheduler, options);
    this.tunnel = new Http1Transport(
      new HttpConnectProxyConnector(options),
      options.scheduler,
      options,
    );
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (this.proxyTunnel || request.url.protocol === "https:") return this.tunnel.dispatch(request);
    if (request.url.protocol !== "http:") {
      return Promise.reject(new TypeError("ProxyAgent requests require an HTTP(S) URL"));
    }
    return this.dispatchForward(request);
  }

  private async dispatchForward(request: TransportRequest): Promise<TransportResponse> {
    const target = addressOf(request.url, this.connectTimeout, ["http/1.1"]);
    let current = request;
    let authorization = this.initialAuthorization;
    let attempt = 1;
    while (true) {
      const headers: HeaderEntry[] = this.headers.slice();
      if (authorization !== null) headers.push(["proxy-authorization", authorization]);
      const route: Http1DispatchRoute = {
        address: proxyAddress(this.proxy, target),
        requestTarget: absoluteRequestTarget(current),
        headers,
      };
      const response = await this.forward.dispatchRouted(current, route);
      if (
        response.status !== 407 ||
        this.authenticate === undefined ||
        attempt >= this.maximumAuthenticationAttempts
      ) {
        return response;
      }
      let next: string | null;
      try {
        next = await callAuthenticator(this.authenticate, {
          proxy: this.proxy,
          target,
          attempt,
          status: response.status,
          headers: response.headers,
        });
      } catch (error) {
        await discard(response);
        throw error;
      }
      if (next === null) return response;
      const retry = retryRequest(request);
      if (retry === null) return response;
      await discard(response);
      authorization = validateAuthorization(next);
      current = retry;
      attempt++;
    }
  }

  close(): Promise<void> {
    if (this.closeResult !== null) return this.closeResult;
    this.closeResult = Promise.all([this.forward.drain(), this.tunnel.drain()]).then(() => {});
    return this.closeResult;
  }

  destroy(): Promise<void> {
    this.forward.close();
    this.tunnel.close();
    return Promise.resolve();
  }
}

/** SOCKS5 dispatcher with proxy-side DNS and end-to-end target TLS. */
export class Socks5ProxyAgent implements FetchTransport {
  private readonly transport: Http1Transport;
  private closeResult: Promise<void> | null = null;

  constructor(options: Socks5ProxyAgentOptions) {
    this.transport = new Http1Transport(
      new Socks5ProxyConnector(options),
      options.scheduler,
      options,
    );
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    return this.transport.dispatch(request);
  }

  close(): Promise<void> {
    if (this.closeResult !== null) return this.closeResult;
    this.closeResult = this.transport.drain();
    return this.closeResult;
  }

  destroy(): Promise<void> {
    this.transport.close();
    return Promise.resolve();
  }
}

/**
 * Environment-selected tunnel connector for protocols that require an end-to-end
 * byte stream, including WebSocket and HTTP/2. Plain HTTP forwarding stays in
 * ProxyAgent because it changes HTTP serialization rather than socket routing.
 */
export class EnvironmentProxyConnector implements NegotiatingSocketConnector {
  readonly policy: EnvironmentProxyPolicy;
  private readonly options: EnvironmentProxyConnectorOptions;
  private readonly proxies = new Map<string, SocketConnector>();

  constructor(options: EnvironmentProxyConnectorOptions) {
    this.options = options;
    this.policy = new EnvironmentProxyPolicy(options.urls, options.environment, options);
  }

  /**
   * Whether a given address is proxied is a policy decision made per connect, while
   * this declaration is read once. It is therefore the conservative conjunction: only
   * when both the direct connector and the tunnels' TLS upgrader report a selection is
   * more than one protocol offered. Declaring less than a route can do costs a
   * protocol; declaring more than a route can do is the mismatch the contract exists
   * to prevent.
   */
  get reportsNegotiatedProtocol(): boolean {
    return (
      isNegotiatingSocketConnector(this.options.connector) &&
      this.options.connector.reportsNegotiatedProtocol &&
      isNegotiatingTlsUpgrader(this.options.tls) &&
      this.options.tls.reportsNegotiatedProtocol
    );
  }

  connect(address: ConnectAddress, signal: AbortSignal): Promise<ByteConnection> {
    return this.#route(address).connect(address, signal);
  }

  connectNegotiated(address: ConnectAddress, signal: AbortSignal): Promise<NegotiatedConnection> {
    return connectNegotiated(this.#route(address), address, signal);
  }

  #route(address: ConnectAddress): SocketConnector {
    const uri = this.policy.proxyForAddress(address);
    if (uri === null) return this.options.connector;
    let connector = this.proxies.get(uri);
    if (connector === undefined) {
      const protocol = this.options.urls.parse(uri).protocol;
      connector =
        protocol === "socks:" || protocol === "socks5:"
          ? new Socks5ProxyConnector({ ...this.options, uri })
          : new HttpConnectProxyConnector({ ...this.options, uri });
      this.proxies.set(uri, connector);
    }
    return connector;
  }
}

/** Environment-selected direct/HTTP/SOCKS dispatcher with NO_PROXY support. */
export class EnvHttpProxyAgent implements FetchTransport {
  readonly policy: EnvironmentProxyPolicy;
  private readonly options: EnvHttpProxyAgentOptions;
  private readonly direct: Http1Transport;
  private readonly proxies = new Map<string, ProxyAgent | Socks5ProxyAgent>();
  private closed = false;
  private closeResult: Promise<void> | null = null;

  constructor(options: EnvHttpProxyAgentOptions, direct?: Http1Transport) {
    this.options = options;
    this.policy = new EnvironmentProxyPolicy(options.urls, options.environment, options);
    this.direct = direct ?? new Http1Transport(options.connector, options.scheduler, options);
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (this.closed) return Promise.reject(new TypeError("EnvHttpProxyAgent is closed"));
    const uri = this.policy.proxyFor(request.url);
    if (uri === null) return this.direct.dispatch(request);
    let dispatcher = this.proxies.get(uri);
    if (dispatcher === undefined) {
      const protocol = this.options.urls.parse(uri).protocol;
      dispatcher =
        protocol === "socks:" || protocol === "socks5:"
          ? new Socks5ProxyAgent({ ...this.options, uri })
          : new ProxyAgent({ ...this.options, uri });
      this.proxies.set(uri, dispatcher);
    }
    return dispatcher.dispatch(request);
  }

  close(): Promise<void> {
    if (this.closeResult !== null) return this.closeResult;
    this.closed = true;
    const closing: Promise<void>[] = [this.direct.drain()];
    for (const dispatcher of this.proxies.values()) closing.push(dispatcher.close());
    this.closeResult = Promise.all(closing).then(() => {
      this.proxies.clear();
    });
    return this.closeResult;
  }

  destroy(): Promise<void> {
    this.closed = true;
    this.direct.close();
    for (const dispatcher of this.proxies.values()) dispatcher.destroy();
    this.proxies.clear();
    return Promise.resolve();
  }
}

import type { ConnectAddress, URLParser, URLRecord } from "../provider/primitives.ts";
import { ProxyConfigurationError } from "./proxy.ts";

export interface ProxyEnvironment {
  readonly HTTP_PROXY?: string;
  readonly HTTPS_PROXY?: string;
  readonly NO_PROXY?: string;
  readonly http_proxy?: string;
  readonly https_proxy?: string;
  readonly no_proxy?: string;
}

export interface EnvironmentProxyOptions {
  /** Explicit values take precedence over environment entries, including empty strings. */
  readonly httpProxy?: string;
  readonly httpsProxy?: string;
  readonly noProxy?: string;
}

export interface NoProxyEntry {
  readonly hostname: string;
  /** Zero means every destination port. */
  readonly port: number;
}

function isAsciiWhitespace(code: number): boolean {
  return code === 9 || code === 10 || code === 11 || code === 12 || code === 13 || code === 32;
}

function splitNoProxy(value: string): readonly string[] {
  const result: string[] = [];
  let start = 0;
  for (let index = 0; index <= value.length; index++) {
    const code = index === value.length ? 44 : value.charCodeAt(index);
    if (code !== 44 && !isAsciiWhitespace(code)) continue;
    if (index > start) result.push(value.slice(start, index));
    start = index + 1;
  }
  return result;
}

function decimalPort(value: string): number | null {
  if (value.length === 0) return null;
  let port = 0;
  for (let index = 0; index < value.length; index++) {
    const code = value.charCodeAt(index);
    if (code < 48 || code > 57) return null;
    port = port * 10 + code - 48;
  }
  return port;
}

function colonCount(value: string): number {
  let count = 0;
  for (let index = 0; index < value.length; index++) if (value.charCodeAt(index) === 58) count++;
  return count;
}

function stripTrailingDot(hostname: string): string {
  return hostname.length > 1 && hostname.charCodeAt(hostname.length - 1) === 46
    ? hostname.slice(0, hostname.length - 1)
    : hostname;
}

function normalizePattern(hostname: string): string {
  let result = hostname;
  if (result.startsWith("*.")) result = result.slice(2);
  else if (result.startsWith(".")) result = result.slice(1);
  return stripTrailingDot(result).toLowerCase();
}

function parseNoProxyEntry(value: string): NoProxyEntry | null {
  let hostname = value;
  let port = 0;
  if (value.startsWith("[")) {
    const close = value.indexOf("]");
    if (close < 0) return null;
    hostname = value.slice(1, close);
    const rest = value.slice(close + 1);
    if (rest !== "") {
      if (!rest.startsWith(":")) return null;
      const parsed = decimalPort(rest.slice(1));
      if (parsed === null) return null;
      port = parsed;
    }
  } else if (colonCount(value) === 1) {
    const colon = value.indexOf(":");
    const parsed = decimalPort(value.slice(colon + 1));
    if (parsed !== null) {
      hostname = value.slice(0, colon);
      port = parsed;
    }
  }
  hostname = normalizePattern(hostname);
  if (hostname === "") return null;
  return { hostname, port };
}

function urlHostname(url: URLRecord): string {
  const hostname =
    url.hostname.startsWith("[") && url.hostname.endsWith("]")
      ? url.hostname.slice(1, url.hostname.length - 1)
      : url.hostname;
  return stripTrailingDot(hostname).toLowerCase();
}

function urlPort(url: URLRecord): number {
  if (url.port !== "") return Number(url.port);
  if (url.protocol === "http:") return 80;
  if (url.protocol === "https:") return 443;
  return 0;
}

/** Parsed immutable no-proxy list with exact label-boundary and port matching. */
export class NoProxyMatcher {
  readonly entries: readonly NoProxyEntry[];
  readonly bypassAll: boolean;

  constructor(value = "") {
    const entries: NoProxyEntry[] = [];
    const bypassAll = value === "*";
    for (const part of splitNoProxy(value)) {
      if (part === "*") continue;
      const entry = parseNoProxyEntry(part);
      if (entry !== null) entries.push(entry);
    }
    this.entries = entries;
    this.bypassAll = bypassAll;
  }

  bypasses(url: URLRecord): boolean {
    return this.bypassesAddress(urlHostname(url), urlPort(url));
  }

  bypassesAddress(hostname: string, port: number): boolean {
    if (this.bypassAll) return true;
    hostname = stripTrailingDot(hostname).toLowerCase();
    for (const entry of this.entries) {
      if (entry.port !== 0 && entry.port !== port) continue;
      if (hostname === entry.hostname) return true;
      const difference = hostname.length - entry.hostname.length;
      if (
        difference > 1 &&
        hostname.charCodeAt(difference - 1) === 46 &&
        hostname.slice(difference) === entry.hostname
      ) {
        return true;
      }
    }
    return false;
  }
}

function environmentValue(lower: string | undefined, upper: string | undefined): string | null {
  return lower ?? upper ?? null;
}

function checkedProxy(urls: URLParser, value: string | null): string | null {
  if (value === null || value === "") return null;
  if (value.includes("\r") || value.includes("\n")) {
    throw new ProxyConfigurationError("Proxy URL contains a line break");
  }
  let parsed: URLRecord;
  try {
    parsed = urls.parse(value);
  } catch {
    throw new ProxyConfigurationError("Invalid proxy URL");
  }
  if (
    parsed.protocol !== "http:" &&
    parsed.protocol !== "https:" &&
    parsed.protocol !== "socks:" &&
    parsed.protocol !== "socks5:"
  ) {
    throw new ProxyConfigurationError("Unsupported proxy URL scheme");
  }
  if (parsed.hostname === "") throw new ProxyConfigurationError("Proxy hostname is empty");
  return value;
}

/**
 * Portable route selection matching standalone Undici's environment precedence.
 * Reading process.env is intentionally left to the Node facade.
 */
export class EnvironmentProxyPolicy {
  readonly httpProxy: string | null;
  readonly httpsProxy: string | null;
  private readonly environment: ProxyEnvironment;
  private readonly explicitNoProxy: string | undefined;
  private noProxyValue = "";
  private noProxyMatcher = new NoProxyMatcher();

  constructor(
    urls: URLParser,
    environment: ProxyEnvironment = {},
    options: EnvironmentProxyOptions = {},
  ) {
    this.environment = environment;
    this.explicitNoProxy = options.noProxy;
    const httpValue =
      options.httpProxy ?? environmentValue(environment.http_proxy, environment.HTTP_PROXY);
    const httpsValue =
      options.httpsProxy ?? environmentValue(environment.https_proxy, environment.HTTPS_PROXY);
    this.httpProxy = checkedProxy(urls, httpValue);
    this.httpsProxy = checkedProxy(urls, httpsValue) ?? this.httpProxy;
    this.refreshNoProxy();
  }

  get noProxy(): NoProxyMatcher {
    this.refreshNoProxy();
    return this.noProxyMatcher;
  }

  proxyFor(url: URLRecord): string | null {
    if (url.protocol !== "http:" && url.protocol !== "https:") return null;
    if (this.noProxy.bypasses(url)) return null;
    return url.protocol === "https:" ? this.httpsProxy : this.httpProxy;
  }

  proxyForAddress(address: ConnectAddress): string | null {
    if (this.noProxy.bypassesAddress(address.hostname, address.port)) return null;
    return address.secure ? this.httpsProxy : this.httpProxy;
  }

  private refreshNoProxy(): void {
    const value =
      this.explicitNoProxy ??
      environmentValue(this.environment.no_proxy, this.environment.NO_PROXY) ??
      "";
    if (value === this.noProxyValue) return;
    this.noProxyValue = value;
    this.noProxyMatcher = new NoProxyMatcher(value);
  }
}

// Proxy auto-configuration results, and deliberately not proxy auto-configuration.
//
// A PAC file is a JavaScript program: `FindProxyForURL(url, host)` returning a string. This
// module does not evaluate one, and the omission is the design rather than a gap. Running
// PAC needs a JavaScript engine, and every platform this project targets already has one
// wired to its own proxy stack -- Android resolves PAC inside `ProxySelector`, Apple inside
// `CFNetworkCopyProxiesForURL`. Reimplementing the interpreter would mean shipping a second,
// worse answer to a question the host already answers, and answering it differently from
// every other application on the same device.
//
// So the portable contract is "ask the host what proxy applies to this URL", and what comes
// back is the classic PAC result grammar. That grammar is the same whether a PAC file
// produced it or a settings panel did, which is why parsing it is shared source while
// producing it is not.
//
// The grammar, as every implementation actually accepts it: semicolon-separated directives,
// tried in order, where `DIRECT` means no proxy. Keywords are matched case-insensitively and
// unrecognised ones are skipped, because a result naming one scheme this project cannot
// speak must not take the routes beside it down with it.
import { currentWebPlatformRuntime } from "../provider/environment.ts";
import type { URLRecord } from "../provider/primitives.ts";
import { NoProxyMatcher } from "./proxy-policy.ts";

/**
 * A single resolved route.
 *
 * `socks4` is represented rather than silently folded into `socks5`. They are different
 * protocols -- SOCKS4 has no authentication, no IPv6, and no hostname in its original form --
 * and a bare `SOCKS` directive means SOCKS4, not SOCKS5. Mapping one to the other would turn
 * an unsupported configuration into a connection that fails somewhere less legible.
 */
export type ProxyRouteKind = "direct" | "http-connect" | "socks4" | "socks5";

export interface ProxyRoute {
  readonly kind: ProxyRouteKind;
  /** Empty for `direct`. IPv6 appears without brackets, matching `ConnectAddress`. */
  readonly hostname: string;
  /** Zero for `direct`. */
  readonly port: number;
  /** Whether the hop to the proxy itself is TLS. Only an `HTTPS` directive sets it. */
  readonly secure: boolean;
}

/** An ordered resolution, with the directives that were understood but cannot be used. */
export interface ProxyResolution {
  /** Usable routes, in the order the result listed them. */
  readonly routes: readonly ProxyRoute[];
  /**
   * Directives recognised as proxy directives and rejected, verbatim.
   *
   * Kept rather than dropped so that a host returning only `SOCKS proxy:1080` is
   * distinguishable from one returning nothing. Both end at `DIRECT`; only one of them is a
   * configuration the operator expected to work.
   */
  readonly unsupported: readonly string[];
}

const DIRECT: ProxyRoute = { kind: "direct", hostname: "", port: 0, secure: false };

/** The single `DIRECT` resolution, used for an absent, empty or unusable result. */
export const directResolution: ProxyResolution = { routes: [DIRECT], unsupported: [] };

function isAsciiWhitespace(code: number): boolean {
  return code === 9 || code === 10 || code === 11 || code === 12 || code === 13 || code === 32;
}

function trimAscii(value: string): string {
  let start = 0;
  let end = value.length;
  while (start < end && isAsciiWhitespace(value.charCodeAt(start))) start++;
  while (end > start && isAsciiWhitespace(value.charCodeAt(end - 1))) end--;
  return value.slice(start, end);
}

function decimalPort(value: string): number | null {
  if (value.length === 0 || value.length > 5) return null;
  let port = 0;
  for (let index = 0; index < value.length; index++) {
    const code = value.charCodeAt(index);
    if (code < 48 || code > 57) return null;
    port = port * 10 + code - 48;
  }
  return port > 0 && port <= 65535 ? port : null;
}

function asciiLowerCase(value: string): string {
  let result = "";
  for (let index = 0; index < value.length; index++) {
    const code = value.charCodeAt(index);
    result += code >= 65 && code <= 90 ? String.fromCharCode(code + 32) : value.charAt(index);
  }
  return result;
}

interface Address {
  readonly hostname: string;
  readonly port: number;
}

/**
 * `host:port`, `host`, or `[v6]:port`.
 *
 * A missing port takes the scheme default. The original specification required one, and no
 * implementation enforces that; results in the wild omit it often enough that rejecting them
 * would mean routing traffic direct because a settings panel was terse.
 */
function parseAddress(text: string, defaultPort: number): Address | null {
  if (text.startsWith("[")) {
    const close = text.indexOf("]");
    if (close < 0) return null;
    const hostname = text.slice(1, close);
    if (hostname === "") return null;
    const rest = text.slice(close + 1);
    if (rest === "") return { hostname, port: defaultPort };
    if (!rest.startsWith(":")) return null;
    const port = decimalPort(rest.slice(1));
    return port === null ? null : { hostname, port };
  }
  const colon = text.lastIndexOf(":");
  if (colon < 0) return text === "" ? null : { hostname: text, port: defaultPort };
  // More than one colon and no brackets is a bare IPv6 literal, which this grammar cannot
  // express unambiguously -- `::1:8080` is a valid address as well as a host and a port.
  if (text.indexOf(":") !== colon) return null;
  const hostname = text.slice(0, colon);
  const port = decimalPort(text.slice(colon + 1));
  return hostname === "" || port === null ? null : { hostname, port };
}

function parseDirective(directive: string): ProxyRoute | "unsupported" | null {
  const trimmed = trimAscii(directive);
  if (trimmed === "") return null;
  let split = 0;
  while (split < trimmed.length && !isAsciiWhitespace(trimmed.charCodeAt(split))) split++;
  const keyword = asciiLowerCase(trimmed.slice(0, split));
  const rest = trimAscii(trimmed.slice(split));

  // `DIRECT` takes no address, and implementations ignore one rather than reject the
  // directive. Anything after the keyword is dropped.
  if (keyword === "direct") return DIRECT;

  if (keyword === "proxy" || keyword === "http") {
    const address = parseAddress(rest, 80);
    return address === null
      ? "unsupported"
      : { kind: "http-connect", hostname: address.hostname, port: address.port, secure: false };
  }
  if (keyword === "https") {
    const address = parseAddress(rest, 443);
    return address === null
      ? "unsupported"
      : { kind: "http-connect", hostname: address.hostname, port: address.port, secure: true };
  }
  if (keyword === "socks5") {
    const address = parseAddress(rest, 1080);
    return address === null
      ? "unsupported"
      : { kind: "socks5", hostname: address.hostname, port: address.port, secure: false };
  }
  // Bare `SOCKS` is SOCKS4, and so is `SOCKS4`. Both are parsed so that the result can say
  // which proxy was named, and neither is usable.
  if (keyword === "socks" || keyword === "socks4") {
    const address = parseAddress(rest, 1080);
    return address === null
      ? "unsupported"
      : { kind: "socks4", hostname: address.hostname, port: address.port, secure: false };
  }
  return "unsupported";
}

/**
 * Parse a proxy auto-configuration result string.
 *
 * Never throws and never returns an empty route list: an unparseable result is a reason to
 * go direct, not a reason to fail a request that would otherwise succeed. A result that
 * named only proxies this project cannot speak still ends at `direct`, with `unsupported`
 * carrying what was dropped.
 */
export function parseProxyResult(value: string): ProxyResolution {
  const routes: ProxyRoute[] = [];
  const unsupported: string[] = [];
  let start = 0;
  for (let index = 0; index <= value.length; index++) {
    if (index !== value.length && value.charCodeAt(index) !== 59) continue;
    const directive = value.slice(start, index);
    start = index + 1;
    const parsed = parseDirective(directive);
    if (parsed === null) continue;
    if (parsed === "unsupported" || parsed.kind === "socks4") {
      unsupported.push(trimAscii(directive));
      continue;
    }
    // A result may repeat `DIRECT`; the second one is the same instruction twice.
    if (parsed.kind === "direct" && routes.some((route) => route.kind === "direct")) continue;
    routes.push(parsed);
  }
  if (routes.length === 0) return { routes: [DIRECT], unsupported };
  // Every result ends at direct if it did not say so itself: a fallback list that runs out
  // is a failed request, and no implementation treats it that way.
  if (!routes.some((route) => route.kind === "direct")) routes.push(DIRECT);
  return { routes, unsupported };
}

/**
 * What the host is asked. Synchronous because both platform APIs that back it are, and
 * because a proxy lookup on the request path must not introduce a turn of the event loop.
 */
export type SystemProxyResolver = (url: URLRecord) => string | null;

/**
 * System proxy lookup, with the caller's bypass list applied on this side.
 *
 * **Two independent reasons, and the second was measured after the first was written.**
 *
 * This is the caller's list, which no provider can know about, and it has to be honoured on
 * every platform including those with no system bypass list at all. That alone is sufficient.
 *
 * And the platform may not apply its own. On Android API 26, measured from a real
 * application rather than from a bare `app_process`, the framework propagates the proxy's
 * host and port and **does not propagate the exclusion list**: with
 * `global_http_proxy_exclusion_list` set to `localhost,127.0.0.1`, `http.nonProxyHosts`
 * arrives empty and a request to `127.0.0.1` is routed to the proxy. So on that version this
 * application is not a second opinion -- it is the only thing keeping a loopback request off
 * the proxy.
 *
 * An earlier measurement through `app_process` with the property set by hand showed the
 * selector honouring `nonProxyHosts`, which is true of the selector and says nothing about
 * what a device hands it. Both facts are recorded because the difference between them is the
 * whole point.
 */
export class SystemProxyPolicy {
  private readonly resolver: SystemProxyResolver;
  private readonly noProxy: NoProxyMatcher;

  constructor(resolver: SystemProxyResolver, noProxy: NoProxyMatcher = new NoProxyMatcher()) {
    this.resolver = resolver;
    this.noProxy = noProxy;
  }

  resolve(url: URLRecord): ProxyResolution {
    if (url.protocol !== "http:" && url.protocol !== "https:") return directResolution;
    if (this.noProxy.bypasses(url)) return directResolution;
    const result = this.resolver(url);
    return result === null ? directResolution : parseProxyResult(result);
  }
}

/**
 * A {@link SystemProxyPolicy} backed by the installed platform.
 *
 * The environment is read when a URL is resolved rather than when the policy is built, so a
 * policy can be constructed before a runtime exists -- and so that a provider whose proxy
 * settings change during the process is asked again rather than cached.
 */
export function systemProxyPolicy(noProxy?: NoProxyMatcher): SystemProxyPolicy {
  return new SystemProxyPolicy(
    (url) => currentWebPlatformRuntime().systemProxyFor(url),
    noProxy,
  );
}

import { decodeUTF8, encodeByteString, utf8 } from "../core/encoding.ts";
import { DOMException, ProtocolError } from "../core/errors.ts";
import { percentDecodeBytes } from "../core/percent.ts";
import { AbortController } from "../core/abort.ts";
import type { AbortSignal } from "../core/abort.ts";
import { isToken } from "../fetch/headers.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import { BufferedReader, writeAll } from "../http1/io.ts";
import { defaultHeadLimits, readHead, validateWireValue } from "../http1/parser.ts";
import type {
  ByteConnection,
  CancelHandle,
  ConnectAddress,
  NegotiatedConnection,
  NegotiatingSocketConnector,
  Scheduler,
  SocketConnector,
  TlsUpgrader,
  URLParser,
  URLRecord,
} from "../provider/primitives.ts";
import { isNegotiatingTlsUpgrader, upgradeNegotiated } from "../provider/primitives.ts";
import { abortSignalSubscribe } from "../core/abort-brand.ts";

const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const DEFAULT_MAXIMUM_AUTHENTICATION_ATTEMPTS = 2;

export type ProxyKind = "http-connect" | "socks5";

export interface ProxyEndpoint {
  readonly kind: ProxyKind;
  readonly hostname: string;
  readonly port: number;
  readonly secure: boolean;
  readonly username: string;
  readonly password: string;
}

export interface ProxyAuthenticationContext {
  readonly proxy: ProxyEndpoint;
  readonly target: ConnectAddress;
  readonly attempt: number;
  readonly status: number;
  readonly headers: readonly HeaderEntry[];
}

/** Return a complete Proxy-Authorization value, or null to decline the challenge. */
export type ProxyAuthenticator = (
  context: ProxyAuthenticationContext,
) => string | null | Promise<string | null>;

export interface HttpConnectProxyOptions {
  readonly connector: SocketConnector;
  readonly tls: TlsUpgrader;
  readonly scheduler: Scheduler;
  readonly urls: URLParser;
  readonly uri: string;
  readonly headers?: readonly HeaderEntry[];
  readonly authorization?: string;
  readonly authenticate?: ProxyAuthenticator;
  readonly maximumAuthenticationAttempts?: number;
}

export interface Socks5ProxyOptions {
  readonly connector: SocketConnector;
  readonly tls: TlsUpgrader;
  readonly scheduler: Scheduler;
  readonly urls: URLParser;
  readonly uri: string;
  /** Establish TLS to the SOCKS server itself. End-to-end target TLS is separate. */
  readonly secureProxy?: boolean;
  readonly username?: string;
  readonly password?: string;
}

export class ProxyConfigurationError extends Error {
  readonly code = "UND_ERR_INVALID_ARG";

  constructor(message: string) {
    super(message);
    this.name = "ProxyConfigurationError";
  }
}

export class ProxyResponseError extends Error {
  readonly code = "UND_ERR_PRX";
  readonly status: number;
  readonly headers: readonly HeaderEntry[];

  constructor(status: number, headers: readonly HeaderEntry[]) {
    super("Proxy CONNECT response was not successful: " + String(status));
    this.name = "ProxyResponseError";
    this.status = status;
    this.headers = headers.slice();
  }
}

export class Socks5ProxyError extends Error {
  readonly code = "UND_ERR_PRX";
  readonly reply: number;

  constructor(message: string, reply = 0) {
    super(message);
    this.name = "Socks5ProxyError";
    this.reply = reply;
  }
}

function base64(bytes: Uint8Array): string {
  let result = "";
  for (let index = 0; index < bytes.length; index += 3) {
    const first = bytes[index] ?? 0;
    const second = bytes[index + 1] ?? 0;
    const third = bytes[index + 2] ?? 0;
    result +=
      BASE64_ALPHABET.charAt(first >>> 2) +
      BASE64_ALPHABET.charAt(((first & 3) << 4) | (second >>> 4));
    result +=
      index + 1 < bytes.length ? BASE64_ALPHABET.charAt(((second & 15) << 2) | (third >>> 6)) : "=";
    result += index + 2 < bytes.length ? BASE64_ALPHABET.charAt(third & 63) : "=";
  }
  return result;
}

function decodeUserInfo(value: string): string {
  return decodeUTF8(percentDecodeBytes(value), true, true);
}

function endpointPort(record: URLRecord, defaultPort: number): number {
  const value = record.port === "" ? defaultPort : Number(record.port);
  if (!Number.isSafeInteger(value) || value < 1 || value > 65535) {
    throw new ProxyConfigurationError("Proxy URL has an invalid port");
  }
  return value;
}

function hostnameWithoutBrackets(hostname: string): string {
  return hostname.startsWith("[") && hostname.endsWith("]")
    ? hostname.slice(1, hostname.length - 1)
    : hostname;
}

/** @internal Shared by CONNECT and absolute-form HTTP proxy transports. */
export function parseHttpEndpoint(urls: URLParser, uri: string): ProxyEndpoint {
  let record: URLRecord;
  try {
    record = urls.parse(uri);
  } catch {
    throw new ProxyConfigurationError("Invalid HTTP proxy URL");
  }
  if (record.protocol !== "http:" && record.protocol !== "https:") {
    throw new ProxyConfigurationError("HTTP proxy URL must use http: or https:");
  }
  if (record.hostname === "") throw new ProxyConfigurationError("Proxy hostname is empty");
  return {
    kind: "http-connect",
    hostname: hostnameWithoutBrackets(record.hostname),
    port: endpointPort(record, record.protocol === "https:" ? 443 : 80),
    secure: record.protocol === "https:",
    username: decodeUserInfo(record.username),
    password: decodeUserInfo(record.password),
  };
}

function parseSocksEndpoint(
  urls: URLParser,
  uri: string,
  secure: boolean,
  username: string | undefined,
  password: string | undefined,
): ProxyEndpoint {
  let record: URLRecord;
  try {
    record = urls.parse(uri);
  } catch {
    throw new ProxyConfigurationError("Invalid SOCKS5 proxy URL");
  }
  if (record.protocol !== "socks:" && record.protocol !== "socks5:") {
    throw new ProxyConfigurationError("SOCKS5 proxy URL must use socks: or socks5:");
  }
  if (record.hostname === "") throw new ProxyConfigurationError("Proxy hostname is empty");
  return {
    kind: "socks5",
    hostname: hostnameWithoutBrackets(record.hostname),
    port: endpointPort(record, 1080),
    secure,
    username: username ?? decodeUserInfo(record.username),
    password: password ?? decodeUserInfo(record.password),
  };
}

function validateTarget(target: ConnectAddress): void {
  if (target.hostname === "") throw new ProxyConfigurationError("Target hostname is empty");
  if (!Number.isSafeInteger(target.port) || target.port < 1 || target.port > 65535) {
    throw new ProxyConfigurationError("Target port is invalid");
  }
}

/** @internal Physical proxy endpoint while preserving the caller's timeout. */
export function proxyAddress(proxy: ProxyEndpoint, target: ConnectAddress): ConnectAddress {
  if (!proxy.secure) {
    return {
      hostname: proxy.hostname,
      port: proxy.port,
      secure: false,
      connectTimeoutMs: target.connectTimeoutMs,
    };
  }
  return {
    hostname: proxy.hostname,
    port: proxy.port,
    secure: true,
    connectTimeoutMs: target.connectTimeoutMs,
    alpnProtocols: ["http/1.1"],
  };
}

function authority(target: ConnectAddress): string {
  const host = target.hostname.includes(":") ? "[" + target.hostname + "]" : target.hostname;
  return host + ":" + String(target.port);
}

/** @internal Validate an authorization value before it reaches the wire. */
export function validateAuthorization(value: string): string {
  validateWireValue(value);
  if (value.length === 0) throw new ProxyConfigurationError("Proxy authorization is empty");
  return value;
}

/** @internal Construct URL-userinfo Basic credentials. */
export function basicAuthorization(username: string, password: string): string | null {
  if (username === "" && password === "") return null;
  return "Basic " + base64(utf8.encode(username + ":" + password));
}

/** @internal Validate immutable configuration headers. */
export function validateProxyHeaders(entries: readonly HeaderEntry[]): readonly HeaderEntry[] {
  const result: HeaderEntry[] = [];
  for (const [rawName, value] of entries) {
    const name = rawName.toLowerCase();
    if (!isToken(name)) throw new ProxyConfigurationError("Invalid proxy header name");
    validateWireValue(value);
    if (
      name === "host" ||
      name === "proxy-authorization" ||
      name === "content-length" ||
      name === "transfer-encoding" ||
      name === "connection"
    ) {
      throw new ProxyConfigurationError("Proxy-managed header: " + name);
    }
    result.push([name, value]);
  }
  return result;
}

/** @internal Normalize a synchronous or asynchronous authenticator. */
export function callAuthenticator(
  authenticate: ProxyAuthenticator,
  context: ProxyAuthenticationContext,
): Promise<string | null> {
  try {
    return Promise.resolve(authenticate(context));
  } catch (error) {
    return Promise.reject(error);
  }
}

async function finishTunnel(
  connection: ByteConnection,
  tls: TlsUpgrader,
  target: ConnectAddress,
  signal: AbortSignal,
): Promise<NegotiatedConnection> {
  signal.throwIfAborted();
  // A cleartext target through a tunnel negotiates nothing, which is the same absence
  // the direct path reports for a cleartext connect.
  if (!target.secure) return { connection, protocol: null, certificateNames: [] };
  return upgradeNegotiated(tls, connection, target, signal);
}

/**
 * A tunnel negotiates through its TLS upgrader, so that is where its ability to report
 * a selection comes from. Declaring it here keeps the shared contract's one rule --
 * a connector that cannot report is never offered a choice -- true through a proxy.
 */
function tunnelReportsProtocol(tls: TlsUpgrader): boolean {
  return isNegotiatingTlsUpgrader(tls) && tls.reportsNegotiatedProtocol;
}

function withConnectDeadline<T>(
  scheduler: Scheduler,
  target: ConnectAddress,
  signal: AbortSignal,
  operation: (signal: AbortSignal) => Promise<T>,
): Promise<T> {
  if (!Number.isSafeInteger(target.connectTimeoutMs) || target.connectTimeoutMs < 1) {
    return Promise.reject(new RangeError("Connect timeout must be a positive safe integer"));
  }
  if (signal.aborted) return Promise.reject(signal.reason);
  const controller = new AbortController();
  const unsubscribe = signal[abortSignalSubscribe](() => controller.abort(signal.reason));
  let timer: CancelHandle;
  try {
    timer = scheduler.delay(target.connectTimeoutMs, () =>
      controller.abort(new DOMException("Proxy connection timed out", "TimeoutError")),
    );
  } catch (error) {
    unsubscribe();
    return Promise.reject(error);
  }
  let result: Promise<T>;
  try {
    result = operation(controller.signal);
  } catch (error) {
    result = Promise.reject(error);
  }
  return result.finally(() => {
    timer.cancel();
    unsubscribe();
  });
}

/** Strict HTTP CONNECT tunneling shared by Fetch, HTTP/2 and WebSocket transports. */
export class HttpConnectProxyConnector implements NegotiatingSocketConnector {
  readonly proxy: ProxyEndpoint;
  private readonly connector: SocketConnector;
  private readonly tls: TlsUpgrader;
  private readonly scheduler: Scheduler;
  private readonly headers: readonly HeaderEntry[];
  private readonly authenticate: ProxyAuthenticator | undefined;
  private readonly maximumAuthenticationAttempts: number;
  private readonly initialAuthorization: string | null;

  constructor(options: HttpConnectProxyOptions) {
    this.connector = options.connector;
    this.tls = options.tls;
    this.scheduler = options.scheduler;
    this.proxy = parseHttpEndpoint(options.urls, options.uri);
    this.headers = validateProxyHeaders(options.headers ?? []);
    this.authenticate = options.authenticate;
    this.maximumAuthenticationAttempts =
      options.maximumAuthenticationAttempts ?? DEFAULT_MAXIMUM_AUTHENTICATION_ATTEMPTS;
    if (
      !Number.isSafeInteger(this.maximumAuthenticationAttempts) ||
      this.maximumAuthenticationAttempts < 1
    ) {
      throw new RangeError("maximumAuthenticationAttempts must be a positive safe integer");
    }
    this.initialAuthorization =
      options.authorization === undefined
        ? basicAuthorization(this.proxy.username, this.proxy.password)
        : validateAuthorization(options.authorization);
  }

  get reportsNegotiatedProtocol(): boolean {
    return tunnelReportsProtocol(this.tls);
  }

  connect(target: ConnectAddress, signal: AbortSignal): Promise<ByteConnection> {
    return this.connectNegotiated(target, signal).then((result) => result.connection);
  }

  connectNegotiated(target: ConnectAddress, signal: AbortSignal): Promise<NegotiatedConnection> {
    validateTarget(target);
    return withConnectDeadline(this.scheduler, target, signal, (deadlineSignal) =>
      this.open(target, deadlineSignal),
    );
  }

  private async open(target: ConnectAddress, signal: AbortSignal): Promise<NegotiatedConnection> {
    let authorization = this.initialAuthorization;
    let attempt = 1;
    while (true) {
      const connection = await this.connector.connect(proxyAddress(this.proxy, target), signal);
      const unsubscribe = signal[abortSignalSubscribe](() => connection.close());
      try {
        signal.throwIfAborted();
        const targetAuthority = authority(target);
        let head = "CONNECT " + targetAuthority + " HTTP/1.1\r\nHost: " + targetAuthority + "\r\n";
        for (const [name, value] of this.headers) head += name + ": " + value + "\r\n";
        if (authorization !== null) {
          head += "proxy-authorization: " + validateAuthorization(authorization) + "\r\n";
        }
        await writeAll(connection, encodeByteString(head + "\r\n"));
        const reader = new BufferedReader(connection);
        let response = await readHead(reader);
        let informational = 0;
        while (response.status < 200) {
          if (++informational > defaultHeadLimits.maxInformational) {
            throw new ProtocolError("Too many informational proxy responses");
          }
          response = await readHead(reader);
        }
        if (reader.bufferedBytes !== 0) {
          throw new ProtocolError("Proxy sent bytes beyond the CONNECT response");
        }
        if (response.status >= 200 && response.status < 300) {
          const result = await finishTunnel(connection, this.tls, target, signal);
          unsubscribe();
          return result;
        }
        if (
          response.status === 407 &&
          this.authenticate !== undefined &&
          attempt < this.maximumAuthenticationAttempts
        ) {
          const next = await callAuthenticator(this.authenticate, {
            proxy: this.proxy,
            target,
            attempt,
            status: response.status,
            headers: response.headers,
          });
          if (next !== null) {
            authorization = validateAuthorization(next);
            attempt++;
            connection.close();
            unsubscribe();
            continue;
          }
        }
        throw new ProxyResponseError(response.status, response.headers);
      } catch (error) {
        connection.close();
        unsubscribe();
        throw signal.aborted ? signal.reason : error;
      }
    }
  }
}

function ipv4Bytes(hostname: string): Uint8Array | null {
  const parts = hostname.split(".");
  if (parts.length !== 4) return null;
  const result = new Uint8Array(4);
  for (let index = 0; index < parts.length; index++) {
    const part = parts[index];
    if (part === undefined || part === "") return null;
    for (let digit = 0; digit < part.length; digit++) {
      const code = part.charCodeAt(digit);
      if (code < 48 || code > 57) return null;
    }
    const value = Number(part);
    if (!Number.isInteger(value) || value < 0 || value > 255) return null;
    result[index] = value;
  }
  return result;
}

function ipv6Part(value: string): readonly number[] | null {
  if (value.includes(".")) {
    const bytes = ipv4Bytes(value);
    if (bytes === null) return null;
    return [(bytes[0] ?? 0) * 256 + (bytes[1] ?? 0), (bytes[2] ?? 0) * 256 + (bytes[3] ?? 0)];
  }
  if (value.length < 1 || value.length > 4) return null;
  for (let index = 0; index < value.length; index++) {
    const code = value.charCodeAt(index);
    if (
      !((code >= 48 && code <= 57) || (code >= 65 && code <= 70) || (code >= 97 && code <= 102))
    ) {
      return null;
    }
  }
  return [Number.parseInt(value, 16)];
}

function appendIpv6Parts(output: number[], text: string): boolean {
  if (text === "") return true;
  const parts = text.split(":");
  for (const part of parts) {
    const values = ipv6Part(part);
    if (values === null) return false;
    for (const value of values) output.push(value);
  }
  return true;
}

function ipv6Bytes(hostname: string): Uint8Array | null {
  if (hostname.indexOf("::") !== hostname.lastIndexOf("::")) return null;
  const compression = hostname.indexOf("::");
  const left: number[] = [];
  const right: number[] = [];
  if (compression < 0) {
    if (!appendIpv6Parts(left, hostname) || left.length !== 8) return null;
  } else {
    if (
      !appendIpv6Parts(left, hostname.slice(0, compression)) ||
      !appendIpv6Parts(right, hostname.slice(compression + 2)) ||
      left.length + right.length >= 8
    ) {
      return null;
    }
    const missing = 8 - left.length - right.length;
    for (let index = 0; index < missing; index++) left.push(0);
    for (const value of right) left.push(value);
  }
  const result = new Uint8Array(16);
  for (let index = 0; index < left.length; index++) {
    const value = left[index] ?? 0;
    result[index * 2] = value >>> 8;
    result[index * 2 + 1] = value & 255;
  }
  return result;
}

function socksTarget(target: ConnectAddress): Uint8Array {
  const ipv4 = ipv4Bytes(target.hostname);
  if (ipv4 !== null) {
    const result = new Uint8Array(1 + ipv4.length + 2);
    result[0] = 1;
    result.set(ipv4, 1);
    result[result.length - 2] = target.port >>> 8;
    result[result.length - 1] = target.port & 255;
    return result;
  }
  const ipv6 = ipv6Bytes(target.hostname);
  if (ipv6 !== null) {
    const result = new Uint8Array(1 + ipv6.length + 2);
    result[0] = 4;
    result.set(ipv6, 1);
    result[result.length - 2] = target.port >>> 8;
    result[result.length - 1] = target.port & 255;
    return result;
  }
  const hostname = encodeByteString(target.hostname);
  if (hostname.length < 1 || hostname.length > 255) {
    throw new ProxyConfigurationError("SOCKS5 target hostname exceeds 255 bytes");
  }
  const result = new Uint8Array(2 + hostname.length + 2);
  result[0] = 3;
  result[1] = hostname.length;
  result.set(hostname, 2);
  result[result.length - 2] = target.port >>> 8;
  result[result.length - 1] = target.port & 255;
  return result;
}

async function readSocksReply(reader: BufferedReader): Promise<void> {
  const head = await reader.exact(4);
  if (head[0] !== 5 || head[2] !== 0) throw new ProtocolError("Malformed SOCKS5 reply");
  const reply = head[1] ?? 255;
  if (reply !== 0) throw new Socks5ProxyError("SOCKS5 proxy rejected the target", reply);
  const addressType = head[3];
  let addressLength: number;
  if (addressType === 1) addressLength = 4;
  else if (addressType === 4) addressLength = 16;
  else if (addressType === 3) addressLength = (await reader.exact(1))[0] ?? 0;
  else throw new ProtocolError("SOCKS5 reply has an invalid address type");
  await reader.exact(addressLength + 2);
}

/** RFC 1928/1929 tunnel connector. Target DNS is delegated to the proxy. */
export class Socks5ProxyConnector implements NegotiatingSocketConnector {
  readonly proxy: ProxyEndpoint;
  private readonly connector: SocketConnector;
  private readonly tls: TlsUpgrader;
  private readonly scheduler: Scheduler;

  constructor(options: Socks5ProxyOptions) {
    this.connector = options.connector;
    this.tls = options.tls;
    this.scheduler = options.scheduler;
    this.proxy = parseSocksEndpoint(
      options.urls,
      options.uri,
      options.secureProxy ?? false,
      options.username,
      options.password,
    );
    if (
      utf8.encode(this.proxy.username).length > 255 ||
      utf8.encode(this.proxy.password).length > 255
    ) {
      throw new ProxyConfigurationError("SOCKS5 credentials exceed 255 bytes");
    }
    if (this.proxy.username === "" && this.proxy.password !== "") {
      throw new ProxyConfigurationError("SOCKS5 password requires a username");
    }
  }

  get reportsNegotiatedProtocol(): boolean {
    return tunnelReportsProtocol(this.tls);
  }

  connect(target: ConnectAddress, signal: AbortSignal): Promise<ByteConnection> {
    return this.connectNegotiated(target, signal).then((result) => result.connection);
  }

  connectNegotiated(target: ConnectAddress, signal: AbortSignal): Promise<NegotiatedConnection> {
    validateTarget(target);
    return withConnectDeadline(this.scheduler, target, signal, (deadlineSignal) =>
      this.open(target, deadlineSignal),
    );
  }

  private async open(target: ConnectAddress, signal: AbortSignal): Promise<NegotiatedConnection> {
    const connection = await this.connector.connect(proxyAddress(this.proxy, target), signal);
    const unsubscribe = signal[abortSignalSubscribe](() => connection.close());
    try {
      const username = utf8.encode(this.proxy.username);
      const password = utf8.encode(this.proxy.password);
      const hasCredentials = username.length !== 0 || password.length !== 0;
      await writeAll(
        connection,
        hasCredentials ? new Uint8Array([5, 2, 0, 2]) : new Uint8Array([5, 1, 0]),
      );
      const methodReply = await new BufferedReader(connection).exact(2);
      if (methodReply[0] !== 5) throw new ProtocolError("Malformed SOCKS5 method reply");
      const method = methodReply[1];
      if (method === 2) {
        if (!hasCredentials || username.length === 0) {
          throw new Socks5ProxyError("SOCKS5 proxy requires unavailable credentials");
        }
        const auth = new Uint8Array(3 + username.length + password.length);
        auth[0] = 1;
        auth[1] = username.length;
        auth.set(username, 2);
        auth[2 + username.length] = password.length;
        auth.set(password, 3 + username.length);
        await writeAll(connection, auth);
        const authReply = await new BufferedReader(connection).exact(2);
        if (authReply[0] !== 1 || authReply[1] !== 0) {
          throw new Socks5ProxyError("SOCKS5 username/password authentication failed");
        }
      } else if (method !== 0) {
        throw new Socks5ProxyError("SOCKS5 proxy selected no acceptable authentication method");
      }

      const encodedTarget = socksTarget(target);
      const request = new Uint8Array(3 + encodedTarget.length);
      request[0] = 5;
      request[1] = 1;
      request[2] = 0;
      request.set(encodedTarget, 3);
      await writeAll(connection, request);
      const reader = new BufferedReader(connection);
      await readSocksReply(reader);
      if (reader.bufferedBytes !== 0) {
        throw new ProtocolError("SOCKS5 proxy sent bytes beyond the connect reply");
      }
      const result = await finishTunnel(connection, this.tls, target, signal);
      unsubscribe();
      return result;
    } catch (error) {
      connection.close();
      unsubscribe();
      throw signal.aborted ? signal.reason : error;
    }
  }
}

import type { AbortSignal } from "../core/abort.ts";
import type { HeldRequestBody, RequestBodyStore } from "../fetch/transport.ts";
import type { ReadableStream } from "../streams/readable.ts";
import type { DurableSpillArea } from "../storage/spill.ts";

/**
 * Holds streaming request bodies in a spill area so they can be replayed.
 *
 * This lives in `dispatch` rather than in `storage` on purpose. A policy may know about
 * storage; storage must not know about dispatch, or the byte store ends up carrying the
 * vocabulary of every consumer that ever wanted bytes.
 *
 * The spill area's own threshold still applies, so a small body is held in memory and a
 * large one goes to the store — the caller chooses somewhere to put the body, not how
 * big a body has to be before it costs anything.
 */
export function spilledRequestBodyStore(area: DurableSpillArea): RequestBodyStore {
  return {
    async hold(body: ReadableStream<Uint8Array>, signal: AbortSignal): Promise<HeldRequestBody> {
      const spilled = await area.spill(body, signal);
      const blob = spilled.blob;
      return {
        source: {
          length: blob.size,
          open(): ReadableStream<Uint8Array> {
            return blob.stream();
          },
        },
        release(): Promise<void> {
          return spilled.release();
        },
      };
    },
  };
}

import type { AbortSignal } from "../core/abort.ts";
import { concatBytes } from "../core/encoding.ts";
import { ignoreRejection } from "../core/promise.ts";
import { Headers } from "../fetch/headers.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type { TransportResponse } from "../fetch/transport.ts";
import type { ReadResult, ReadableStreamDefaultReader } from "../streams/readable.ts";
import { abortSignalSubscribe } from "../core/abort-brand.ts";

export class ResponseExceededMaxSizeError extends Error {
  readonly code = "UND_ERR_RES_EXCEEDED_MAX_SIZE";
  readonly maximumBytes: number;
  readonly receivedBytes: number;

  constructor(maximumBytes: number, receivedBytes: number) {
    super("Response content exceeded the configured limit of " + String(maximumBytes) + " bytes");
    this.name = "ResponseExceededMaxSizeError";
    this.maximumBytes = maximumBytes;
    this.receivedBytes = receivedBytes;
  }
}

export function validateResponseBodyLimit(maximumBytes: number): void {
  if (!Number.isSafeInteger(maximumBytes) || maximumBytes < 1) {
    throw new RangeError("Response body limit must be a positive safe integer");
  }
}

function declaredContentLength(headers: readonly HeaderEntry[]): number | null {
  const value = new Headers(headers).get("content-length");
  if (value === null || !/^[0-9]+$/.test(value)) return null;
  const length = Number(value);
  return Number.isSafeInteger(length) ? length : Number.POSITIVE_INFINITY;
}

async function cancelWithoutMasking(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  reason: unknown,
): Promise<void> {
  try {
    await reader.cancel(reason);
  } catch {
    // The read/limit/abort reason remains the observable failure.
  }
}

async function readWithAbort(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  signal: AbortSignal,
): Promise<ReadResult<Uint8Array>> {
  signal.throwIfAborted();
  const result = Promise.withResolvers<ReadResult<Uint8Array>>();
  const unsubscribe = signal[abortSignalSubscribe](() => result.reject(signal.reason));
  reader.read().then(result.resolve, result.reject);
  try {
    return await result.promise;
  } finally {
    unsubscribe();
  }
}

export async function collectResponseBody(
  response: TransportResponse,
  signal: AbortSignal,
  maximumBytes: number,
): Promise<Uint8Array> {
  validateResponseBodyLimit(maximumBytes);
  signal.throwIfAborted();
  const declared = declaredContentLength(response.headers);
  if (declared !== null && declared > maximumBytes) {
    const error = new ResponseExceededMaxSizeError(maximumBytes, declared);
    if (response.body !== null) {
      try {
        await response.body.cancel(error);
      } catch {
        // The declared size violation remains the observable failure.
      }
    }
    if (response.trailers !== undefined) ignoreRejection(response.trailers);
    throw error;
  }
  if (response.body === null) return new Uint8Array(0);

  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let received = 0;
  try {
    while (true) {
      const item = await readWithAbort(reader, signal);
      if (item.done) return concatBytes(chunks, received);
      if (!(item.value instanceof Uint8Array)) {
        throw new TypeError("Transport response body chunks must be Uint8Array values");
      }
      received += item.value.length;
      if (received > maximumBytes) {
        throw new ResponseExceededMaxSizeError(maximumBytes, received);
      }
      chunks.push(item.value.slice());
    }
  } catch (error) {
    await cancelWithoutMasking(reader, error);
    if (response.trailers !== undefined) ignoreRejection(response.trailers);
    throw error;
  } finally {
    reader.releaseLock();
  }
}

export async function settleResponseTrailers(
  response: TransportResponse,
  signal: AbortSignal,
): Promise<readonly HeaderEntry[] | undefined> {
  const pending = response.trailers;
  if (pending === undefined) return undefined;
  signal.throwIfAborted();
  const result = Promise.withResolvers<readonly HeaderEntry[]>();
  const unsubscribe = signal[abortSignalSubscribe](() => result.reject(signal.reason));
  pending.then(result.resolve, result.reject);
  try {
    const entries = await result.promise;
    signal.throwIfAborted();
    const copy: HeaderEntry[] = [];
    for (const [name, value] of entries) copy.push([name, value]);
    return copy;
  } finally {
    unsubscribe();
  }
}

import { TextDecoder } from "../core/encoding.ts";
import { Headers } from "../fetch/headers.ts";
import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import type { FetchInterceptor } from "./interceptor.ts";
import {
  collectResponseBody,
  settleResponseTrailers,
  validateResponseBodyLimit,
} from "./response-body.ts";

export type ResponseErrorBody = string | Uint8Array | null;

export interface ResponseErrorOptions {
  readonly maximumBodyBytes?: number;
}

export class ResponseError extends Error {
  readonly code = "UND_ERR_RESPONSE";
  readonly statusCode: number;
  readonly statusMessage: string;
  readonly headers: Headers;
  readonly body: ResponseErrorBody;

  constructor(response: TransportResponse, body: ResponseErrorBody) {
    super("Response Error");
    this.name = "ResponseError";
    this.statusCode = response.status;
    this.statusMessage = response.statusText;
    this.headers = new Headers(response.headers);
    this.body = body;
  }
}

function errorBody(response: TransportResponse, bytes: Uint8Array): ResponseErrorBody {
  if (response.body === null) return null;
  const contentType = new Headers(response.headers).get("content-type")?.toLowerCase() ?? "";
  const separator = contentType.indexOf(";");
  const essence = (separator < 0 ? contentType : contentType.slice(0, separator)).trim();
  if (essence === "text/plain" || essence === "application/json" || essence.endsWith("+json")) {
    return new TextDecoder().decode(bytes);
  }
  return bytes;
}

/** Convert status responses at or above 400 into a stable, bounded typed error. */
export class ResponseErrorInterceptor implements FetchInterceptor {
  private readonly maximumBodyBytes: number;

  constructor(options: ResponseErrorOptions = {}) {
    this.maximumBodyBytes = options.maximumBodyBytes ?? 1024 * 1024;
    validateResponseBodyLimit(this.maximumBodyBytes);
  }

  async dispatch(request: TransportRequest, next: FetchTransport): Promise<TransportResponse> {
    const response = await next.dispatch(request);
    if (response.status < 400) return response;
    const bytes = await collectResponseBody(response, request.signal, this.maximumBodyBytes);
    await settleResponseTrailers(response, request.signal);
    throw new ResponseError(response, errorBody(response, bytes));
  }
}

import { parseHTTPDate } from "../cache/freshness.ts";
import type { AbortSignal } from "../core/abort.ts";
import { ignoreRejection } from "../core/promise.ts";
import { Headers } from "../fetch/headers.ts";
import type {
  FetchTransport,
  HeldRequestBody,
  RequestBodyStore,
  TransportBodySource,
  TransportErrorCode,
  TransportRequest,
  TransportResponse,
} from "../fetch/transport.ts";
import { TransportError } from "../fetch/transport.ts";
import type { CancelHandle, Scheduler } from "../provider/primitives.ts";
import type { ReadableStream } from "../streams/readable.ts";
import type { FetchInterceptor } from "./interceptor.ts";
import { abortSignalSubscribe } from "../core/abort-brand.ts";

const defaultMethods = ["GET", "HEAD", "OPTIONS", "PUT", "DELETE", "TRACE"] as const;
const defaultStatusCodes = [500, 502, 503, 504, 429] as const;
const defaultErrorCodes: readonly TransportErrorCode[] = [
  "ECONNRESET",
  "ECONNREFUSED",
  "ENOTFOUND",
  "ENETDOWN",
  "ENETUNREACH",
  "EHOSTDOWN",
  "EHOSTUNREACH",
  "EPIPE",
  "UND_ERR_SOCKET",
];

export interface RetryContext {
  readonly request: TransportRequest;
  /** One for the first retry, not the initial attempt. */
  readonly retryCount: number;
  readonly proposedDelayMilliseconds: number;
  readonly response: TransportResponse | null;
  readonly error: unknown;
}

export interface RetryDecision {
  readonly retry: boolean;
  readonly delayMilliseconds?: number;
}

export type RetryDecider = (context: RetryContext) => RetryDecision | Promise<RetryDecision>;
export type RetryObserver = (context: RetryContext) => void;
export type RetryErrorClassifier = (error: unknown) => boolean;

export interface RetryOptions {
  readonly scheduler: Scheduler;
  readonly maxRetries?: number;
  readonly minTimeoutMilliseconds?: number;
  readonly maxTimeoutMilliseconds?: number;
  readonly timeoutFactor?: number;
  readonly retryAfter?: boolean;
  readonly methods?: readonly string[];
  readonly statusCodes?: readonly number[];
  readonly errorCodes?: readonly TransportErrorCode[];
  readonly throwOnStatusExhaustion?: boolean;
  readonly nowMilliseconds?: () => number;
  readonly decide?: RetryDecider;
  readonly classifyError?: RetryErrorClassifier;
  readonly onRetry?: RetryObserver;
  /**
   * Somewhere to hold a streaming request body so it can be replayed.
   *
   * Absent, a body that cannot replay itself is still an
   * {@link UnreplayableRequestError} -- the interceptor does not decide on a caller's
   * behalf that an arbitrary upload may be buffered.
   */
  readonly requestBodyStore?: RequestBodyStore;
}

export class RetryExhaustedError extends Error {
  readonly code = "UND_ERR_REQ_RETRY";
  readonly statusCode: number;
  readonly retryCount: number;
  readonly headers: Headers;

  constructor(response: TransportResponse, retryCount: number) {
    super("Retry attempts exhausted for HTTP status " + String(response.status));
    this.name = "RetryExhaustedError";
    this.statusCode = response.status;
    this.retryCount = retryCount;
    this.headers = new Headers(response.headers);
  }
}

export class UnreplayableRequestError extends Error {
  readonly code = "UND_ERR_REQ_RETRY";

  constructor() {
    super("Request body cannot be replayed for a retry");
    this.name = "UnreplayableRequestError";
  }
}

class RetryCancellation extends Error {
  constructor(status: number) {
    super("HTTP status " + String(status) + " is being retried");
    this.name = "RetryCancellation";
  }
}

function validateCount(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new RangeError(name + " must be a non-negative safe integer");
  }
}

function validateDelay(value: number, name: string): void {
  if (!Number.isFinite(value) || value < 0) {
    throw new RangeError(name + " must be a non-negative finite number");
  }
}

function validateFactor(value: number): void {
  if (!Number.isFinite(value) || value <= 0) {
    throw new RangeError("Retry timeout factor must be a positive finite number");
  }
}

function includesNumber(values: readonly number[], candidate: number): boolean {
  for (const value of values) if (value === candidate) return true;
  return false;
}

function includesErrorCode(
  values: readonly TransportErrorCode[],
  candidate: TransportErrorCode,
): boolean {
  for (const value of values) if (value === candidate) return true;
  return false;
}

function defaultNow(): number {
  return 0;
}

function retryAfterMilliseconds(
  response: TransportResponse,
  nowMilliseconds: number,
): number | null {
  const value = new Headers(response.headers).get("retry-after");
  if (value === null) return null;
  if (/^[0-9]+$/.test(value)) {
    const seconds = Number(value);
    // An arbitrarily large decimal delay is still valid. Returning infinity lets
    // the caller clamp it without depending on bigint support in this layer.
    if (!Number.isFinite(seconds)) return Number.POSITIVE_INFINITY;
    return seconds * 1000;
  }
  const date = parseHTTPDate(value, nowMilliseconds);
  return date === null ? null : Math.max(0, date - nowMilliseconds);
}

async function waitForRetry(
  scheduler: Scheduler,
  delayMilliseconds: number,
  signal: AbortSignal,
): Promise<void> {
  signal.throwIfAborted();
  const result = Promise.withResolvers<void>();
  let timer: CancelHandle | null = null;
  const unsubscribe = signal[abortSignalSubscribe](() => {
    timer?.cancel();
    result.reject(signal.reason);
  });
  timer = scheduler.delay(delayMilliseconds, result.resolve);
  try {
    await result.promise;
    signal.throwIfAborted();
  } finally {
    timer.cancel();
    unsubscribe();
  }
}

/**
 * The same request, reading from the held body instead of the stream it arrived on.
 *
 * `bodyLength` is carried over rather than taken from the source, so a request that
 * declared a length the body does not have is still an error. Correcting it here would
 * turn a caller's inconsistency into a silent success.
 */
function replayableRequest(
  request: TransportRequest,
  source: TransportBodySource,
): TransportRequest {
  return {
    url: request.url,
    method: request.method,
    headers: request.headers,
    body: source.open(),
    bodyLength: request.bodyLength,
    replayBody: source,
    signal: request.signal,
  };
}

function requestForRetry(request: TransportRequest): TransportRequest {
  if (request.body === null) {
    return {
      url: request.url,
      method: request.method,
      headers: request.headers,
      body: null,
      bodyLength: request.bodyLength,
      replayBody: request.replayBody,
      signal: request.signal,
    };
  }
  const source = request.replayBody;
  if (source === undefined || source === null) throw new UnreplayableRequestError();
  validateReplaySource(source, request.bodyLength);
  return {
    url: request.url,
    method: request.method,
    headers: request.headers,
    body: source.open(),
    bodyLength: source.length,
    replayBody: source,
    signal: request.signal,
  };
}

function ensureReplayable(request: TransportRequest): void {
  if (request.body === null) return;
  const source = request.replayBody;
  if (source === undefined || source === null) throw new UnreplayableRequestError();
  validateReplaySource(source, request.bodyLength);
}

function validateReplaySource(source: TransportBodySource, declaredLength: number | null): void {
  if (!Number.isSafeInteger(source.length) || source.length < 0) {
    throw new TypeError("Replayable request body has an invalid length");
  }
  if (declaredLength !== null && source.length !== declaredLength) {
    throw new TypeError("Replayable request body length does not match the request");
  }
}

function responseBody(response: TransportResponse): ReadableStream<Uint8Array> | null {
  return response.body;
}

async function discardResponse(response: TransportResponse, reason: unknown): Promise<void> {
  const body = responseBody(response);
  if (body !== null) await body.cancel(reason);
  if (response.trailers !== undefined) ignoreRejection(response.trailers);
}

async function throwIfResponseAborted(
  response: TransportResponse,
  signal: AbortSignal,
): Promise<void> {
  if (!signal.aborted) return;
  await discardResponse(response, signal.reason);
  throw signal.reason;
}

export class RetryInterceptor implements FetchInterceptor {
  private readonly scheduler: Scheduler;
  private readonly maximumRetries: number;
  private readonly minimumTimeout: number;
  private readonly maximumTimeout: number;
  private readonly timeoutFactor: number;
  private readonly useRetryAfter: boolean;
  private readonly methods: readonly string[];
  private readonly statusCodes: readonly number[];
  private readonly errorCodes: readonly TransportErrorCode[];
  private readonly throwOnStatusExhaustion: boolean;
  private readonly nowMilliseconds: () => number;
  private readonly decide: RetryDecider | undefined;
  private readonly classifyError: RetryErrorClassifier | undefined;
  private readonly observer: RetryObserver | undefined;
  private readonly requestBodyStore: RequestBodyStore | undefined;

  constructor(options: RetryOptions) {
    this.scheduler = options.scheduler;
    this.maximumRetries = options.maxRetries ?? 5;
    this.minimumTimeout = options.minTimeoutMilliseconds ?? 500;
    this.maximumTimeout = options.maxTimeoutMilliseconds ?? 30000;
    this.timeoutFactor = options.timeoutFactor ?? 2;
    this.useRetryAfter = options.retryAfter ?? true;
    this.methods = options.methods ?? defaultMethods;
    this.statusCodes = options.statusCodes ?? defaultStatusCodes;
    this.errorCodes = options.errorCodes ?? defaultErrorCodes;
    this.throwOnStatusExhaustion = options.throwOnStatusExhaustion ?? true;
    this.nowMilliseconds = options.nowMilliseconds ?? defaultNow;
    this.decide = options.decide;
    this.classifyError = options.classifyError;
    this.observer = options.onRetry;
    this.requestBodyStore = options.requestBodyStore;
    validateCount(this.maximumRetries, "Maximum retry count");
    validateDelay(this.minimumTimeout, "Minimum retry timeout");
    validateDelay(this.maximumTimeout, "Maximum retry timeout");
    validateFactor(this.timeoutFactor);
    if (this.minimumTimeout > this.maximumTimeout) {
      throw new RangeError("Minimum retry timeout exceeds maximum retry timeout");
    }
    for (const status of this.statusCodes) {
      if (!Number.isInteger(status) || status < 100 || status > 599) {
        throw new RangeError("Retry status code is invalid");
      }
    }
  }

  async dispatch(incoming: TransportRequest, next: FetchTransport): Promise<TransportResponse> {
    const method = incoming.method.toUpperCase();
    // Held before the first attempt, not on the first failure. By the time a retry is
    // wanted the body has already been sent, and there is nothing left to hold.
    const held = await this.holdRequestBody(incoming, method);
    const request = held === null ? incoming : replayableRequest(incoming, held.source);
    try {
      return await this.attempts(request, method, next);
    } finally {
      // Safe while a transport is still uploading: `source()` was resolved when the
      // body was held, and a source pins what it was opened over, so a reader opened
      // from it reads the original bytes whether or not the key still exists.
      if (held !== null) await held.release();
    }
  }

  private async holdRequestBody(
    request: TransportRequest,
    method: string,
  ): Promise<HeldRequestBody | null> {
    if (this.requestBodyStore === undefined) return null;
    if (request.body === null) return null;
    if (request.replayBody !== null && request.replayBody !== undefined) return null;
    // A method this interceptor would never retry is a body held for nothing.
    if (!this.methodEligible(method)) return null;
    return this.requestBodyStore.hold(request.body, request.signal);
  }

  private async attempts(
    request: TransportRequest,
    method: string,
    next: FetchTransport,
  ): Promise<TransportResponse> {
    let retryCount = 0;
    let attempt = request;
    while (true) {
      request.signal.throwIfAborted();
      let response: TransportResponse;
      try {
        response = await next.dispatch(attempt);
      } catch (error) {
        request.signal.throwIfAborted();
        if (!this.methodEligible(method) || !this.errorEligible(error)) throw error;
        if (retryCount >= this.maximumRetries) throw error;
        retryCount++;
        const context = this.context(request, retryCount, null, error);
        const decision = await this.retryDecision(context);
        if (!decision.retry) throw error;
        ensureReplayable(request);
        this.observe(context);
        await waitForRetry(this.scheduler, this.decisionDelay(context, decision), request.signal);
        attempt = requestForRetry(request);
        continue;
      }

      await throwIfResponseAborted(response, request.signal);

      if (!this.methodEligible(method) || !includesNumber(this.statusCodes, response.status)) {
        return response;
      }
      if (retryCount >= this.maximumRetries) {
        if (!this.throwOnStatusExhaustion) return response;
        await discardResponse(response, new RetryCancellation(response.status));
        throw new RetryExhaustedError(response, retryCount);
      }
      retryCount++;
      let context: RetryContext;
      let decision: RetryDecision;
      try {
        context = this.context(request, retryCount, response, null);
        decision = await this.retryDecision(context);
      } catch (error) {
        await discardResponse(response, new RetryCancellation(response.status));
        throw error;
      }
      await throwIfResponseAborted(response, request.signal);
      if (!decision.retry) return response;
      try {
        ensureReplayable(request);
      } catch (error) {
        await discardResponse(response, new RetryCancellation(response.status));
        throw error;
      }
      await discardResponse(response, new RetryCancellation(response.status));
      this.observe(context);
      await waitForRetry(this.scheduler, this.decisionDelay(context, decision), request.signal);
      attempt = requestForRetry(request);
    }
  }

  private methodEligible(method: string): boolean {
    for (const candidate of this.methods) {
      if (candidate.toUpperCase() === method) return true;
    }
    return false;
  }

  private errorEligible(error: unknown): boolean {
    if (this.classifyError !== undefined) return this.classifyError(error);
    return error instanceof TransportError && includesErrorCode(this.errorCodes, error.code);
  }

  private proposedDelay(retryCount: number, response: TransportResponse | null): number {
    if (this.useRetryAfter && response !== null) {
      const now = this.nowMilliseconds();
      if (!Number.isFinite(now))
        throw new TypeError("Retry wall clock returned a non-finite value");
      const fromHeader = retryAfterMilliseconds(response, now);
      if (fromHeader !== null) return Math.min(fromHeader, this.maximumTimeout);
    }
    const exponential = this.minimumTimeout * this.timeoutFactor ** (retryCount - 1);
    return Math.min(exponential, this.maximumTimeout);
  }

  private context(
    request: TransportRequest,
    retryCount: number,
    response: TransportResponse | null,
    error: unknown,
  ): RetryContext {
    return {
      request,
      retryCount,
      proposedDelayMilliseconds: this.proposedDelay(retryCount, response),
      response,
      error,
    };
  }

  private retryDecision(context: RetryContext): Promise<RetryDecision> {
    return Promise.resolve(
      this.decide?.(context) ?? {
        retry: true,
        delayMilliseconds: context.proposedDelayMilliseconds,
      },
    );
  }

  private decisionDelay(context: RetryContext, decision: RetryDecision): number {
    const delay = decision.delayMilliseconds ?? context.proposedDelayMilliseconds;
    validateDelay(delay, "Retry decision delay");
    return Math.min(delay, this.maximumTimeout);
  }

  private observe(context: RetryContext): void {
    if (this.observer === undefined) return;
    try {
      this.observer(context);
    } catch (error) {
      this.scheduler.reportError(error);
    }
  }
}

export class RetryAgent implements FetchTransport {
  private readonly transport: FetchTransport;
  private readonly interceptor: RetryInterceptor;

  constructor(transport: FetchTransport, options: RetryOptions) {
    this.transport = transport;
    this.interceptor = new RetryInterceptor(options);
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    return this.interceptor.dispatch(request, this.transport);
  }
}

import { AbortController } from "../core/abort.ts";
import type { EventHandlerSlot } from "../core/events.ts";
import { Event, EventTarget, MessageEvent } from "../core/events.ts";
import { DOMException, LimitError } from "../core/errors.ts";
import { latin1, TextDecoder, utf8 } from "../core/encoding.ts";
import {
  coerceToBoolean,
  coerceToUSVString,
  requireArguments,
  requireDictionary,
} from "../core/webidl.ts";
import type { CancelHandle, Scheduler, URLParser } from "../provider/primitives.ts";
import { currentWebPlatformRuntime } from "../provider/environment.ts";
import type { RequestInit } from "../fetch/request.ts";
import type { Response } from "../fetch/response.ts";
import { parseMIMEType } from "../forms/mime.ts";
import { eventTargetDispatchTrusted, eventTargetSetErrorReporter, eventTargetSetHandler } from "../core/events.ts";

export interface EventSourceInit {
  withCredentials?: boolean;
}

export interface EventSourceOptions {
  initialReconnectDelayMs?: number;
  maxEventBufferCharacters?: number;
  maxLineBufferCharacters?: number;
}

export interface EventSourcePolicy {
  readonly initialReconnectDelayMs: number;
  readonly maxEventBufferCharacters: number;
  readonly maxLineBufferCharacters: number;
}

export interface EventSourceContext {
  readonly scheduler: Scheduler;
  readonly urls: URLParser;
  readonly baseURL: string | undefined;
  readonly eventSourcePolicy: EventSourcePolicy;

  fetch(input: string, init?: RequestInit): Promise<Response>;

  registerEventSource(source: EventSource): void;

  unregisterEventSource(source: EventSource): void;
}

interface ParsedEvent {
  readonly type: string;
  readonly data: string;
  readonly lastEventId: string;
}

interface EventStreamTarget {
  dispatchParsedEvent(event: ParsedEvent): Promise<void>;

  setLastEventId(value: string): void;

  setReconnectDelay(milliseconds: number): void;
}

interface ReconnectWait {
  readonly timer: CancelHandle;
  readonly result: PromiseWithResolvers<void>;
}

export function readEventSourcePolicy(options: EventSourceOptions | undefined): EventSourcePolicy {
  const policy: EventSourcePolicy = {
    initialReconnectDelayMs: options?.initialReconnectDelayMs ?? 3000,
    maxEventBufferCharacters: options?.maxEventBufferCharacters ?? 16 * 1024 * 1024,
    maxLineBufferCharacters: options?.maxLineBufferCharacters ?? 1024 * 1024,
  };
  validateLimit(policy.initialReconnectDelayMs, "EventSource reconnect delay", true);
  validateLimit(policy.maxEventBufferCharacters, "EventSource event buffer", false);
  validateLimit(policy.maxLineBufferCharacters, "EventSource line buffer", false);
  return policy;
}

function validateLimit(value: number, name: string, allowZero: boolean): void {
  if (!Number.isSafeInteger(value) || value < (allowZero ? 0 : 1)) {
    throw new RangeError(name + " limit is invalid");
  }
}

function convertEventSourceInit(init: EventSourceInit | null | undefined): boolean {
  requireDictionary(init, "EventSource init");
  if (init === undefined || init === null) return false;
  return coerceToBoolean(init.withCredentials);
}

function reconnectMilliseconds(value: string): number | null {
  if (value.length === 0) return null;
  let result = 0;
  for (let index = 0; index < value.length; index++) {
    const code = value.charCodeAt(index);
    if (code < 48 || code > 57) return null;
    result = result * 10 + code - 48;
    if (result > Number.MAX_SAFE_INTEGER) result = Number.MAX_SAFE_INTEGER;
  }
  return result;
}

function lastEventIdHeaderValue(value: string): string {
  // HTML requires Last-Event-ID to carry the UTF-8 encoding of the event ID.
  // Fetch header values are Web IDL ByteStrings, so preserve those wire bytes
  // as code units instead of passing the Unicode string through public Headers.
  return latin1(utf8.encode(value));
}

/** Incremental parser for the HTML event-stream format. */
export class EventStreamParser {
  private readonly target: EventStreamTarget;
  private readonly policy: EventSourcePolicy;
  private line = "";
  private data = "";
  private eventType = "";
  private lastEventId = "";
  private skipLeadingLF = false;

  constructor(target: EventStreamTarget, policy: EventSourcePolicy, initialLastEventId = "") {
    this.target = target;
    this.policy = policy;
    this.lastEventId = initialLastEventId;
  }

  async push(text: string): Promise<void> {
    let start = 0;
    for (let index = 0; index < text.length; index++) {
      const code = text.charCodeAt(index);
      if (this.skipLeadingLF) {
        this.skipLeadingLF = false;
        if (code === 10) {
          start = index + 1;
          continue;
        }
      }
      if (code !== 10 && code !== 13) continue;

      this.appendLineFragment(text.slice(start, index));
      await this.processLine(this.line);
      this.line = "";
      this.skipLeadingLF = code === 13;
      start = index + 1;
    }
    this.appendLineFragment(text.slice(start));
  }

  finish(): void {
    // EOF never dispatches an unterminated event or processes an unterminated line.
    this.line = "";
    this.data = "";
    this.eventType = "";
  }

  private appendLineFragment(fragment: string): void {
    if (fragment.length === 0) return;
    if (this.line.length + fragment.length > this.policy.maxLineBufferCharacters) {
      throw new LimitError("EventSource line exceeded the configured buffer limit");
    }
    this.line += fragment;
  }

  private async processLine(line: string): Promise<void> {
    if (line.length === 0) {
      await this.dispatchEvent();
      return;
    }
    if (line.charCodeAt(0) === 58) return;

    const colon = line.indexOf(":");
    const field = colon < 0 ? line : line.slice(0, colon);
    let value = colon < 0 ? "" : line.slice(colon + 1);
    if (value.charCodeAt(0) === 32) value = value.slice(1);

    if (field === "event") {
      this.eventType = value;
      return;
    }
    if (field === "data") {
      if (this.data.length + value.length + 1 > this.policy.maxEventBufferCharacters) {
        throw new LimitError("EventSource event exceeded the configured buffer limit");
      }
      this.data += value + "\n";
      return;
    }
    if (field === "id") {
      if (!value.includes("\0")) this.lastEventId = value;
      return;
    }
    if (field === "retry") {
      const milliseconds = reconnectMilliseconds(value);
      if (milliseconds !== null) this.target.setReconnectDelay(milliseconds);
    }
  }

  private async dispatchEvent(): Promise<void> {
    this.target.setLastEventId(this.lastEventId);
    if (this.data.length === 0) {
      this.eventType = "";
      return;
    }

    const parsed: ParsedEvent = {
      type: this.eventType === "" ? "message" : this.eventType,
      data: this.data.slice(0, -1),
      lastEventId: this.lastEventId,
    };
    this.data = "";
    this.eventType = "";
    await this.target.dispatchParsedEvent(parsed);
  }
}

// HTML EventHandler values retain non-callable objects, independently of the
// callable used by the active listener. Protocol events keep their public types.
interface EventSourceHandlerSlot extends EventHandlerSlot<EventSource, Event> {
  value: unknown;
}

function ignoreNonCallableHandler(): void {}

function acceptsEvent(_event: Event): _event is Event {
  return true;
}

/** HTML server-sent events over the canonical environment-owned Fetch implementation. */
export class EventSource extends EventTarget {
  static readonly CONNECTING = 0;
  static readonly OPEN = 1;
  static readonly CLOSED = 2;

  readonly CONNECTING = 0;
  readonly OPEN = 1;
  readonly CLOSED = 2;
  readonly url: string;
  readonly withCredentials: boolean;

  private readonly context: EventSourceContext;
  private readonly retryableScheme: boolean;
  private state = EventSource.CONNECTING;
  private reconnectDelay: number;
  private lastEventId = "";
  private connection: AbortController | null = null;
  private reconnectWait: ReconnectWait | null = null;
  private registered = false;
  private readonly openHandler: EventSourceHandlerSlot = {
    value: null,
    callback: null,
    listener: null,
  };
  private readonly messageHandler: EventSourceHandlerSlot = {
    value: null,
    callback: null,
    listener: null,
  };
  private readonly errorHandler: EventSourceHandlerSlot = {
    value: null,
    callback: null,
    listener: null,
  };

  constructor(...args: [url: string, init?: EventSourceInit]) {
    requireArguments(args, 1, "EventSource constructor");
    const input = coerceToUSVString(args[0]);
    const withCredentials = convertEventSourceInit(args[1]);
    // The public API is `(url, init)`. Nothing constructs an EventSource with an
    // explicit context, so the capability is never an argument: it is read from the
    // environment and cannot be substituted by a surplus argument.
    const context = currentWebPlatformRuntime();
    super();
    this[eventTargetSetErrorReporter]((error) => context.scheduler.reportError(error));
    try {
      const parsed = context.urls.parse(input, context.baseURL);
      this.url = parsed.href;
      this.retryableScheme = parsed.protocol === "http:" || parsed.protocol === "https:" ||
        parsed.protocol === "data:" || parsed.protocol === "blob:" || parsed.protocol === "file:";
    } catch {
      throw new DOMException("Invalid EventSource URL", "SyntaxError");
    }
    this.withCredentials = withCredentials;
    this.context = context;
    this.reconnectDelay = context.eventSourcePolicy.initialReconnectDelayMs;
    context.registerEventSource(this);
    this.registered = true;
    context.scheduler.enqueue(() => {
      this.run().catch((error) => context.scheduler.reportError(error));
    });
  }

  get readyState(): number {
    return this.state;
  }

  get onopen(): ((this: EventSource, event: Event) => void) | null {
    return this.openHandler.value as ((this: EventSource, event: Event) => void) | null;
  }

  set onopen(callback: ((this: EventSource, event: Event) => void) | null) {
    this.#setHandler(this.openHandler, "open", callback);
  }

  get onmessage(): ((this: EventSource, event: MessageEvent<string>) => void) | null {
    return this.messageHandler.value as ((this: EventSource, event: MessageEvent<string>) => void) | null;
  }

  set onmessage(callback: ((this: EventSource, event: MessageEvent<string>) => void) | null) {
    this.#setHandler(this.messageHandler, "message", callback);
  }

  get onerror(): ((this: EventSource, event: Event) => void) | null {
    return this.errorHandler.value as ((this: EventSource, event: Event) => void) | null;
  }

  set onerror(callback: ((this: EventSource, event: Event) => void) | null) {
    this.#setHandler(this.errorHandler, "error", callback);
  }

  #setHandler(slot: EventSourceHandlerSlot, type: string, value: unknown): void {
    // HTML 8.1.8.1; Web IDL 3.2.19, 3.2.20 and 3.4.8:
    // https://webidl.spec.whatwg.org/#LegacyTreatNonObjectAsNull
    let callback: ((this: EventSource, event: Event) => void) | null = null;
    if (typeof value === "function") {
      slot.value = value;
      callback = value as (this: EventSource, event: Event) => void;
    } else if (typeof value === "object" && value !== null) {
      slot.value = value;
      // Keep an active listener's position without trying to call the object.
      callback = ignoreNonCallableHandler;
    } else {
      slot.value = null;
    }
    this[eventTargetSetHandler](this, slot, type, callback, acceptsEvent);
  }

  close(): void {
    if (this.state === EventSource.CLOSED) return;
    this.state = EventSource.CLOSED;
    this.connection?.abort();
    this.connection = null;
    const wait = this.reconnectWait;
    this.reconnectWait = null;
    if (wait !== null) {
      wait.timer.cancel();
      wait.result.resolve();
    }
    this.unregister();
  }

  private async run(): Promise<void> {
    while (this.state !== EventSource.CLOSED) {
      const outcome = await this.connectOnce();
      if (this.state === EventSource.CLOSED) return;
      if (outcome === "fatal") {
        await this.failConnection();
        return;
      }
      if (!(await this.waitToReconnect())) return;
    }
  }

  private async connectOnce(): Promise<"reconnect" | "fatal"> {
    const controller = new AbortController();
    this.connection = controller;
    try {
      const headers: [string, string][] = [
        ["accept", "text/event-stream"],
        ["cache-control", "no-cache"],
      ];
      if (this.lastEventId !== "") {
        headers.push(["last-event-id", lastEventIdHeaderValue(this.lastEventId)]);
      }
      const init: RequestInit = {
        cache: "no-store",
        credentials: this.withCredentials ? "include" : "same-origin",
        headers,
        signal: controller.signal,
      };
      const response = await this.context.fetch(this.url, init);
      if (this.state === EventSource.CLOSED) return "fatal";
      const mime = parseMIMEType(response.headers.get("content-type") ?? "");
      if (response.status !== 200 || mime?.essence !== "text/event-stream") {
        try {
          await response.body?.cancel();
        } catch {
          // The response is already terminal; cancellation failure cannot make it reconnectable.
        }
        return "fatal";
      }

      const origin = this.context.urls.parse(response.url || this.url).origin;
      await this.queueTask(() => {
        if (this.state === EventSource.CLOSED) return;
        this.state = EventSource.OPEN;
        this[eventTargetDispatchTrusted](new Event("open"));
      });
      if (this.state === EventSource.CLOSED) return "fatal";
      await this.consume(response, origin);
      return "reconnect";
    } catch (error) {
      if (this.state === EventSource.CLOSED || controller.signal.aborted) return "fatal";
      if (error instanceof LimitError) {
        // Retire this Fetch before the terminal error task unregisters us.
        // Keep the parser's failure as the abort reason, not a new AbortError.
        controller.abort(error);
        return "fatal";
      }
      // HTML 9.2.2 step 15.2 permits terminal failure when retrying is known
      // to be futile. Fetch cannot service other schemes in this environment.
      return this.retryableScheme ? "reconnect" : "fatal";
    } finally {
      if (this.connection === controller) this.connection = null;
    }
  }

  private async consume(response: Response, origin: string): Promise<void> {
    const body = response.body;
    if (body === null) return;
    const reader = body.getReader();
    const decoder = new TextDecoder();
    const parser = new EventStreamParser(
      {
        dispatchParsedEvent: async (event) => {
          await this.queueTask(() => {
            if (this.state === EventSource.CLOSED) return;
            this[eventTargetDispatchTrusted](
              new MessageEvent<string>(event.type, {
                data: event.data,
                lastEventId: event.lastEventId,
                origin,
              }),
            );
