/** Common methods for Request/Response. json() returns unknown, never a fictitious caller-chosen T. */
export abstract class Body {
  /** @internal */ protected bodyState: BodyState;

  constructor(state: BodyState) {
    this.bodyState = state;
  }

  get body(): ReadableStream<Uint8Array> | null {
    return this.bodyState.stream;
  }

  get bodyUsed(): boolean {
    return this.bodyState.used;
  }

  async bytes(): Promise<Uint8Array> {
    return this.bodyState.consume();
  }

  async arrayBuffer(): Promise<ArrayBuffer> {
    const bytes = await this.bodyState.consume();
    const output = new ArrayBuffer(bytes.length);
    new Uint8Array(output).set(bytes);
    return output;
  }

  async text(): Promise<string> {
    return decodeUTF8(await this.bodyState.consume());
  }

  textStream(): ReadableStream<string> {
    if (this.bodyState.unusable) throw new TypeError("Body is already used or locked");
    const stream = this.bodyState.stream;
    if (stream === null) {
      const empty = new ReadableStream<string>();
      readableStreamClose(empty);
      return empty;
    }
    // Fetch always chooses UTF-8, independently of any Content-Type charset.
    const decoder = new TextDecoderStream();
    // Fetch runs ReadableStreamPipeTo internally; subclass overrides of the
    // public pipeThrough/getReader methods cannot intercept the operation.
    ignoreRejection(readableStreamPipeTo(stream, decoder.writable, {
      preventAbort: false, preventCancel: false, preventClose: false, signal: undefined,
    }));
    return decoder.readable;
  }

  async json(): Promise<unknown> {
    // The shared implementation rather than the host's, because there is no host `JSON` on a
    // compiled target -- which made this method the functional hole that the JSON work exists
    // to close. `parse a JSON string` in the Fetch specification is `JSON.parse` with no
    // reviver, so the graph is materialized straight into ordinary values.
    //
    // The materialization is the host-only step. At a typed boundary -- `await r.json() as T`
    // -- the compiler generates a parser that builds `T` directly and this generic path is not
    // reached; see the note at the head of `json/plain.ts`.
    // One pass. `toPlainValue(parseJsonText(...))` builds the erased graph and then
    // walks it into ordinary objects, and nothing between those two passes is
    // observable at a boundary that takes no reviver -- 23.681ms against 8.450ms on
    // a 1.67MB document. `parsePlainText` shares the scanner, so the grammar, the
    // error text and the number conversion are still spelled once.
    return parsePlainText(decodeUTF8(await this.bodyState.consume()));
  }

  async blob(): Promise<Blob> {
    const bytes = await this.bodyState.consume();
    const mime = extractBodyMIMEType(this[bodyContentType]());
    return new Blob([bytes], { type: mime === null ? "" : serializeMIMEType(mime) });
  }

  async formData(): Promise<FormData> {
    const bytes = await this.bodyState.consume();
    const mime = extractBodyMIMEType(this[bodyContentType]());

    if (mime?.essence === "multipart/form-data") return decodeMultipart(bytes, mime);
    if (mime?.essence !== "application/x-www-form-urlencoded")
      throw new TypeError("Unsupported form Content-Type");
    return decodeURLEncoded(bytes);
  }

  protected abstract [bodyContentType](): string | null;

  /** @internal */ getState(): BodyState {
    return this.bodyState;
  }
}

import { LimitError } from "../core/errors.ts";
import { ReadableStream } from "../streams/readable.ts";
import type { ContentDecoder } from "./transport.ts";

/** Resource policy applied to the final body produced by a content-coding stack. */
export interface ContentCodingPolicy {
  /** Maximum decoded bytes exposed by one response body. */
  readonly maxDecodedBytes: number;
  /** Maximum final-decoded/wire-byte expansion after the grace allowance. */
  readonly maxExpansionRatio: number;
  /** Decoded bytes allowed before the expansion ratio becomes binding. */
  readonly ratioGraceBytes: number;
}

/**
 * Server/mobile defaults. They are a configurable safety policy, not a Fetch
 * standard limit: providers that intentionally accept larger bodies can raise or
 * disable either bound explicitly.
 */
export const standardContentCodingPolicy: ContentCodingPolicy = {
  maxDecodedBytes: 256 * 1024 * 1024,
  maxExpansionRatio: 100,
  ratioGraceBytes: 1024 * 1024,
};

export function readContentCodingPolicy(
  input: Partial<ContentCodingPolicy> | undefined,
): ContentCodingPolicy {
  const policy: ContentCodingPolicy = {
    maxDecodedBytes: input?.maxDecodedBytes ?? standardContentCodingPolicy.maxDecodedBytes,
    maxExpansionRatio: input?.maxExpansionRatio ?? standardContentCodingPolicy.maxExpansionRatio,
    ratioGraceBytes: input?.ratioGraceBytes ?? standardContentCodingPolicy.ratioGraceBytes,
  };
  validateByteLimit(policy.maxDecodedBytes);
  validateByteLimit(policy.ratioGraceBytes);
  if (
    Number.isNaN(policy.maxExpansionRatio) ||
    policy.maxExpansionRatio < 1 ||
    (policy.maxExpansionRatio !== Infinity && !Number.isFinite(policy.maxExpansionRatio))
  ) {
    throw new RangeError("Invalid content-coding expansion ratio");
  }
  return policy;
}

/** Decode in HTTP order while enforcing one budget around the complete stack. */
export function decodeContentCodings(
  source: ReadableStream<Uint8Array>,
  codings: readonly string[],
  decoder: ContentDecoder,
  policy: ContentCodingPolicy,
): ReadableStream<Uint8Array> {
  if (codings.length === 0) return source;

  const budget = { encodedBytes: 0, decodedBytes: 0 };
  let decoded = countBytes(source, (length) => {
    budget.encodedBytes += length;
  });
  for (let index = codings.length - 1; index >= 0; --index) {
    const coding = codings[index];
    if (coding !== undefined) decoded = decoder.decode(coding, decoded);
  }
  return countBytes(decoded, (length) => {
    budget.decodedBytes += length;
    if (budget.decodedBytes > policy.maxDecodedBytes) {
      throw new LimitError("Decoded response exceeded configured byte limit");
    }
    const ratioLimit = budget.encodedBytes * policy.maxExpansionRatio + policy.ratioGraceBytes;
    if (budget.decodedBytes > ratioLimit) {
      throw new LimitError("Decoded response exceeded configured expansion ratio");
    }
  });
}

function countBytes(
  source: ReadableStream<Uint8Array>,
  observe: (length: number) => void,
): ReadableStream<Uint8Array> {
  const reader = source.getReader();
  let released = false;
  const release = (): void => {
    if (released) return;
    released = true;
    reader.releaseLock();
  };
  return new ReadableStream<Uint8Array>(
    {
      async pull(controller) {
        try {
          const result = await reader.read();
          if (result.done) {
            release();
            controller.close();
            return;
          }
          if (!(result.value instanceof Uint8Array)) {
            throw new TypeError("Content decoder produced a non-byte chunk");
          }
          observe(result.value.length);
          controller.enqueue(result.value);
        } catch (error) {
          try {
            await reader.cancel(error);
          } catch {
            /* The source may already have failed while the limit was observed. */
          } finally {
            release();
          }
          controller.error(error);
        }
      },
      async cancel(reason) {
        try {
          await reader.cancel(reason);
        } finally {
          release();
        }
      },
    },
    { highWaterMark: 0, size: (value) => value.length },
  );
}

function validateByteLimit(limit: number): void {
  if (Number.isNaN(limit) || limit < 0 || (limit !== Infinity && !Number.isSafeInteger(limit))) {
    throw new RangeError("Invalid content-coding byte limit");
  }
}

import { forgivingBase64Decode } from "../core/base64.ts";
import { percentDecodeBytes } from "../core/percent.ts";
import { trimASCIIWhitespace } from "../core/ascii.ts";
import { parseMIMEType, serializeMIMEType } from "../forms/mime.ts";
import type { URLRecord } from "../provider/primitives.ts";

export interface DataURLResult {
  readonly body: Uint8Array;
  readonly mimeType: string;
}

function withoutFragment(url: URLRecord): string {
  return url.hash === "" ? url.href : url.href.slice(0, url.href.length - url.hash.length);
}

function removeBase64Marker(input: string): string | null {
  if (input.length < 7 || input.slice(input.length - 6).toLowerCase() !== "base64") return null;
  let semicolon = input.length - 7;
  while (semicolon >= 0 && input.charCodeAt(semicolon) === 0x20) semicolon--;
  if (input.charAt(semicolon) !== ";") return null;
  let end = semicolon;
  while (end > 0 && input.charCodeAt(end - 1) === 0x20) end--;
  return input.slice(0, end);
}

/** The Fetch Standard's data: URL processor. */
export function processDataURL(url: URLRecord): DataURLResult | null {
  const serialized = withoutFragment(url);
  if (url.protocol !== "data:" || !serialized.startsWith("data:")) return null;
  const input = serialized.slice(5);
  const comma = input.indexOf(",");
  if (comma < 0) return null;

  let mimeType = trimASCIIWhitespace(input.slice(0, comma));
  let body = percentDecodeBytes(input.slice(comma + 1));
  const withoutBase64 = removeBase64Marker(mimeType);
  if (withoutBase64 !== null) {
    const decoded = forgivingBase64Decode(body);
    if (decoded === null) return null;
    body = decoded;
    mimeType = withoutBase64;
  }

  if (mimeType.startsWith(";")) mimeType = "text/plain" + mimeType;
  const parsed = parseMIMEType(mimeType);
  return {
    body,
    mimeType: parsed === null ? "text/plain;charset=US-ASCII" : serializeMIMEType(parsed),
  };
}

import { AbortSignal } from "../core/abort.ts";
import type { HttpCache, HttpCacheDispatchResult } from "../cache/http-cache.ts";
import type { CookieAccessContext, CookieJar } from "../cookies/jar.ts";
import { trimHTTPTabOrSpace } from "../core/ascii.ts";
import { concatBytes } from "../core/encoding.ts";
import { networkError } from "../core/errors.ts";
import { checkNetworkPort } from "../core/network-port.ts";
import type { URLRecord } from "../provider/primitives.ts";
import { currentWebPlatformRuntime } from "../provider/environment.ts";
import { bytesStream, ReadableStream } from "../streams/readable.ts";
import { BodyState } from "./body.ts";
import { Headers, isToken } from "./headers.ts";
import { createInternalRequest, Request, validateRequestURL } from "./request.ts";
import type { RequestContext, RequestInit } from "./request.ts";
import { isRedirectStatus, nullBodyStatus, Response } from "./response.ts";
