  | "ECONNREFUSED"
  | "ENOTFOUND"
  | "ENETDOWN"
  | "ENETUNREACH"
  | "EHOSTDOWN"
  | "EHOSTUNREACH"
  | "EPIPE"
  | "UND_ERR_SOCKET";

