function decoderForLabel(label: string): TextDecoder | null {
  try {
    return new TextDecoder(label);
  } catch (error) {
    if (!(error instanceof RangeError)) throw error;
    if (unavailableEncodingLabels.test(trimASCIIWhitespace(label))) {
      // A valid label must not silently fall back to a different codec. This
      // explicit capability limitation goes away when canonical TextDecoder
      // supplies that encoding; it is not a File API decoding result.
      throw new DOMException("The provider does not support this text encoding", "NotSupportedError");
    }
    return null;
  }
}

function decodeFileText(bytes: Uint8Array, mimeType: string, encodingLabel: string | undefined): string {
  // Encoding's decode algorithm lets a UTF BOM override the fallback encoding.
  // The canonical decoder consumes the BOM; no conversion is implemented here.
  if (bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) {
    return new TextDecoder("utf-8").decode(bytes);
  }
  if (bytes[0] === 0xff && bytes[1] === 0xfe) return new TextDecoder("utf-16le").decode(bytes);
  if (bytes[0] === 0xfe && bytes[1] === 0xff) return new TextDecoder("utf-16be").decode(bytes);
  let decoder = encodingLabel === undefined ? null : decoderForLabel(encodingLabel);
  if (decoder === null) {
    const charset = parseMIMEType(mimeType)?.parameters.get("charset");
    if (charset !== undefined) decoder = decoderForLabel(charset);
  }
  return (decoder ?? new TextDecoder()).decode(bytes);
}

function requireBlob(value: unknown): Blob {
  if (!isBlob(value)) throw new TypeError("FileReader requires a Blob");
  return value;
}

function readError(error: unknown): DOMException {
  return error instanceof DOMException ? error : new DOMException("The blob could not be read", "NotReadableError");
}

async function cancelRead(reader: ReadableStreamDefaultReader<Uint8Array>): Promise<void> {
  try {
    await reader.cancel();
  } catch {
    // Cancellation cleanup cannot turn abort into a later read-error event.
  } finally {
    reader.releaseLock();
  }
}

// Typed nts programs cannot replace Function.prototype.call or attach an own
// call property to a function. Handler callbacks keep their receiver directly.
let invokeHandler!: (reader: FileReader, index: number, event: Event) => void;

function isReaderEvent(_event: Event): _event is Event { return true; }

function onLoadstart(this: FileReader, event: Event): void { invokeHandler(this, 0, event); }
function onProgress(this: FileReader, event: Event): void { invokeHandler(this, 1, event); }
function onLoad(this: FileReader, event: Event): void { invokeHandler(this, 2, event); }
function onAbort(this: FileReader, event: Event): void { invokeHandler(this, 3, event); }
function onError(this: FileReader, event: Event): void { invokeHandler(this, 4, event); }
function onLoadend(this: FileReader, event: Event): void { invokeHandler(this, 5, event); }

/**
 * File API §6.2: asynchronous reads over canonical immutable Blob storage.
 *
 * readAsDataURL is deliberately absent until the provider exposes a base64
 * encoder. Recognized legacy text encodings likewise require codec support.
 */
export class FileReader extends EventTarget {
  static readonly EMPTY = 0;
  static readonly LOADING = 1;
  static readonly DONE = 2;
  readonly EMPTY = 0;
  readonly LOADING = 1;
  readonly DONE = 2;
  readonly [Symbol.toStringTag] = "FileReader";

  #state = 0;
  #result: string | ArrayBuffer | null = null;
  #error: DOMException | null = null;
  #operation: ReadOperation | null = null;
  readonly #handlers: readonly ReaderHandlerSlot[] = [
    new ReaderHandlerSlot(), new ReaderHandlerSlot(), new ReaderHandlerSlot(),
    new ReaderHandlerSlot(), new ReaderHandlerSlot(), new ReaderHandlerSlot(),
  ];

  static {
    invokeHandler = (reader, index, event): void => {
      const callback = reader.#handlers[index]?.value;
      // LegacyTreatNonObjectAsNull retains non-callable objects, whose invocation
      // is a no-op. Keep the FileReader receiver on the callback call.
      if (typeof callback === "function" && (callback as FileReaderEventHandler).call(reader, event) === false) {
        cancelEvent(event);
      }
    };
  }

  get readyState(): number { return this.#state; }
  get result(): string | ArrayBuffer | null { return this.#result; }
  get error(): DOMException | null { return this.#error; }

  get onloadstart(): FileReaderEventHandlerValue { return this.#handlerValue(0); }
  set onloadstart(value: FileReaderEventHandlerValue) { this.#setHandler(0, "loadstart", value, onLoadstart); }
  get onprogress(): FileReaderEventHandlerValue { return this.#handlerValue(1); }
  set onprogress(value: FileReaderEventHandlerValue) { this.#setHandler(1, "progress", value, onProgress); }
  get onload(): FileReaderEventHandlerValue { return this.#handlerValue(2); }
  set onload(value: FileReaderEventHandlerValue) { this.#setHandler(2, "load", value, onLoad); }
  get onabort(): FileReaderEventHandlerValue { return this.#handlerValue(3); }
  set onabort(value: FileReaderEventHandlerValue) { this.#setHandler(3, "abort", value, onAbort); }
  get onerror(): FileReaderEventHandlerValue { return this.#handlerValue(4); }
  set onerror(value: FileReaderEventHandlerValue) { this.#setHandler(4, "error", value, onError); }
  get onloadend(): FileReaderEventHandlerValue { return this.#handlerValue(5); }
  set onloadend(value: FileReaderEventHandlerValue) { this.#setHandler(5, "loadend", value, onLoadend); }

  #handlerValue(index: number): FileReaderEventHandlerValue {
    return this.#handlers[index]?.value ?? null;
  }

  #setHandler(index: number, type: FileReaderEventType, value: unknown, callback: FileReaderEventHandler): void {
    const slot = this.#handlers[index];
    if (slot === undefined) throw new Error("FileReader handler slot is missing");
    slot.value = value !== null && (typeof value === "object" || typeof value === "function") ? value : null;
    setEventHandlerAttribute(this, slot, type, slot.value === null ? null : callback, isReaderEvent);
  }

  readAsArrayBuffer(blob: Blob): void {
    if (!(#state in this)) throw new TypeError("FileReader method called on an incompatible receiver");
    requireArguments(arguments, 1, "FileReader.readAsArrayBuffer");
    this.#read(requireBlob(blob), "ArrayBuffer", undefined);
  }

  readAsBinaryString(blob: Blob): void {
    if (!(#state in this)) throw new TypeError("FileReader method called on an incompatible receiver");
    requireArguments(arguments, 1, "FileReader.readAsBinaryString");
    this.#read(requireBlob(blob), "BinaryString", undefined);
  }

  readAsText(blob: Blob, encoding: string | undefined = undefined): void {
    if (!(#state in this)) throw new TypeError("FileReader method called on an incompatible receiver");
    requireArguments(arguments, 1, "FileReader.readAsText");
    const convertedBlob = requireBlob(blob);
    const label = encoding === undefined ? undefined : coerceToDOMString(encoding);
    this.#read(convertedBlob, "Text", label);
  }

  #read(blob: Blob, kind: ReadKind, encodingLabel: string | undefined): void {
    if (this.#state === 1) throw new DOMException("A read is already in progress", "InvalidStateError");
    const runtime = currentWebPlatformRuntime();
    this.#state = 1;
    this.#result = null;
    this.#error = null;
    const operation = new ReadOperation(blob, kind, encodingLabel, runtime);
    this.#operation = operation;
    void this.#readChunks(operation);
  }

  async #readChunks(operation: ReadOperation): Promise<void> {
    let first = true;
    try {
      while (this.#operation === operation) {
        const chunk = await operation.reader.read();
        if (this.#operation !== operation) return;
        if (first) {
          first = false;
          this.#queueProgressEvent(operation, "loadstart", 0);
        }
        if (chunk.done) {
          // File API's progress invariant requires the final nonempty byte count,
          // including reads which complete before the roughly 50ms interval.
          if (operation.loaded > operation.lastProgressLoaded) {
            this.#queueProgressEvent(operation, "progress", operation.loaded);
          }
          operation.runtime.scheduler.enqueue(() => this.#finish(operation));
          return;
        }
        if (!(chunk.value instanceof Uint8Array)) throw new DOMException("Invalid Blob chunk", "NotReadableError");
        operation.chunks.push(chunk.value);
        operation.loaded += chunk.value.byteLength;
        const now = operation.runtime.monotonicMilliseconds();
        if (now - operation.lastProgressTime >= 50) {
          operation.lastProgressTime = now;
          operation.lastProgressLoaded = operation.loaded;
          this.#queueProgressEvent(operation, "progress", operation.loaded);
        }
      }
    } catch (error) {
      if (this.#operation === operation) {
        operation.runtime.scheduler.enqueue(() => this.#finish(operation, readError(error)));
      }
    }
  }

  #queueProgressEvent(operation: ReadOperation, type: FileReaderEventType, loaded: number): void {
    operation.runtime.scheduler.enqueue(() => {
      if (this.#operation === operation) this.#fire(type, loaded, operation.total);
    });
  }

  #finish(operation: ReadOperation, failure: DOMException | null = null): void {
    if (this.#operation !== operation) return;
    this.#operation = null;
    this.#state = 2;
    this.#error = failure;
    if (failure === null) {
      try {
        const bytes = concatBytes(operation.chunks, operation.loaded);
        switch (operation.kind) {
          case "ArrayBuffer": this.#result = bytes.buffer; break;
          case "BinaryString": this.#result = latin1(bytes); break;
          case "Text": this.#result = decodeFileText(bytes, getBlobType(operation.blob), operation.encodingLabel); break;
        }
      } catch (error) {
        this.#error = readError(error);
      }
    }
    operation.chunks.length = 0;
    operation.reader.releaseLock();
    this.#fire(this.#error === null ? "load" : "error", operation.loaded, operation.total);
    // A load/error handler can start another read. Its loadend belongs to that
    // new operation; the completed operation must not emit one while loading.
    if (this.#state !== 1) this.#fire("loadend", operation.loaded, operation.total);
  }

  abort(): void {
    this.#result = null;
    if (this.#state !== 1) return;
    const operation = this.#operation;
    this.#operation = null;
    this.#state = 2;
    if (operation === null) return;
    operation.chunks.length = 0;
    void cancelRead(operation.reader);
    // Retiring the operation also retires every queued task and pending read
    // continuation. The events below are synchronous, as abort() specifies.
    this.#fire("abort", operation.loaded, operation.total);
    if (this.#state !== 1) this.#fire("loadend", operation.loaded, operation.total);
  }

  #fire(type: FileReaderEventType, loaded: number, total: number): void {
    dispatchTrustedEvent(this, new ProgressEvent(type, { lengthComputable: total !== 0, loaded, total }));
  }
}

import type { RandomSource, URLRecord } from "../provider/primitives.ts";
import { Blob } from "./blob.ts";

const UUID_BYTES = 16;
const MAX_UUID_ATTEMPTS = 16;
const HEX = "0123456789abcdef";

/**
 * The File API's Blob URL store for one NTS environment.
 *
 * Entries hold the Blob itself, not a materialized byte copy. That preserves
 * reopenable provider storage and keeps the object alive until revocation or
 * environment teardown. A Request captures the resolved Blob when its URL is
 * parsed, so later revocation cannot invalidate an already-started fetch.
 */
export class BlobURLStore {
  private readonly entries = new Map<string, Blob>();
  private readonly random: RandomSource;
  private readonly prefix: string;

  constructor(random: RandomSource, origin: string | undefined, prefix: string | undefined) {
    this.random = random;
    this.prefix = prefix ?? `blob:${origin ?? "null"}/`;
    if (!this.prefix.startsWith("blob:") || this.prefix.length === 5) {
      throw new TypeError("Invalid Blob URL prefix");
    }
  }

  create(blob: Blob): string {
    if (!(blob instanceof Blob)) {
      throw new TypeError("Object URL source must be a Blob");
    }

    for (let attempt = 0; attempt < MAX_UUID_ATTEMPTS; attempt++) {
      const url = this.prefix + generateUUID(this.random);
      if (!this.entries.has(url)) {
        this.entries.set(url, blob);
        return url;
      }
    }
    throw new Error("Random source repeatedly generated an existing Blob URL");
  }

  /** Resolve using URL serialization with its fragment excluded. */
  resolve(url: URLRecord): Blob | null {
    if (url.protocol !== "blob:") {
      return null;
    }
    const fragment = url.href.indexOf("#");
    const key = fragment < 0 ? url.href : url.href.slice(0, fragment);
    return this.entries.get(key) ?? null;
  }

  /** Revoke using the exact parsed serialization; fragments are significant here. */
  revoke(url: URLRecord): void {
    if (url.protocol === "blob:") {
      this.entries.delete(url.href);
    }
  }

  close(): void {
    this.entries.clear();
  }
}

function generateUUID(random: RandomSource): string {
  const bytes = new Uint8Array(UUID_BYTES);
  random.fill(bytes);
  const version = bytes[6];
  const variant = bytes[8];
  if (version === undefined || variant === undefined) {
    throw new Error("Random source did not fill a UUID buffer");
  }
  bytes[6] = (version & 0x0f) | 0x40;
  bytes[8] = (variant & 0x3f) | 0x80;

  let result = "";
  for (let index = 0; index < bytes.length; index++) {
    if (index === 4 || index === 6 || index === 8 || index === 10) {
      result += "-";
    }
    const byte = bytes[index];
    if (byte === undefined) {
      throw new Error("Random source did not fill a UUID buffer");
    }
    result += HEX.charAt(byte >>> 4) + HEX.charAt(byte & 0x0f);
  }
  return result;
}

import { coerceToUSVString, requireArguments } from "../core/webidl.ts";
import { Blob, File } from "../file/blob.ts";
import { currentWebPlatformRuntime } from "../provider/environment.ts";

export type FormDataEntryValue = string | File;

export type FormDataEntry = readonly [name: string, value: FormDataEntryValue];
type StoredFormDataEntry = [name: string, value: FormDataEntryValue];
type FormDataValueArguments = [value?: unknown, filename?: unknown];
type FormDataNameArguments = [name?: unknown];
type FormDataForEachCallback = (
  this: unknown,
  value: FormDataEntryValue,
  name: string,
  parent: FormData,
) => void;

function selectEntry(item: StoredFormDataEntry): FormDataEntry {
  return [item[0], item[1]];
}

function selectName(item: StoredFormDataEntry): string {
  return item[0];
}

function selectValue(item: StoredFormDataEntry): FormDataEntryValue {
  return item[1];
}

class FormDataIterator<T> extends Iterator<T> {
  readonly #list: readonly StoredFormDataEntry[];
  readonly #select: (item: StoredFormDataEntry) => T;
  #position = 0;

  constructor(list: readonly StoredFormDataEntry[], select: (item: StoredFormDataEntry) => T) {
    super();
    this.#list = list;
    this.#select = select;
  }

  next(): IteratorResult<T, undefined> {
    const list = this.#list;
    const position = this.#position;
    if (position >= list.length) {
      return { value: undefined, done: true };
    }
    const item = list[position];
    if (item === undefined) {
      return { value: undefined, done: true };
    }
    this.#position = position + 1;
    return { value: this.#select(item), done: false };
  }

  override get [Symbol.toStringTag](): "FormData Iterator" {
    return "FormData Iterator";
  }
}

function convertFormDataValue(
  value: unknown,
  filenameGiven: boolean,
  rawFilename: unknown,
): FormDataEntryValue {
  if (!(value instanceof Blob)) {
    if (filenameGiven) {
      throw new TypeError("A filename requires a Blob");
    }
    return coerceToUSVString(value);
  }
  const suppliedFilename = rawFilename === undefined ? undefined : coerceToUSVString(rawFilename);
  if (value instanceof File && suppliedFilename === undefined) {
    return value;
  }
  return new File([value], suppliedFilename === undefined ? "blob" : suppliedFilename, {
    type: value.type,
    lastModified:
      value instanceof File
        ? value.lastModified
        : currentWebPlatformRuntime().wallTimeMilliseconds(),
  });
}

export class FormData implements Iterable<FormDataEntry> {
  readonly #list: StoredFormDataEntry[] = [];

  constructor();
  constructor(form: undefined);
  constructor(...args: [] | [form: undefined]) {
    if (args.length !== 0 && args[0] !== undefined) {
      throw new TypeError("FormData constructor does not accept an HTML form in this environment");
    }
  }

  append(name: string, value: string): void;
  append(name: string, value: Blob, filename?: string): void;
  append(name: unknown, ...args: FormDataValueArguments): void {
    const list = this.#list;
    if (args.length === 0) {
      throw new TypeError("FormData.append requires at least 2 argument(s)");
    }
    const key = coerceToUSVString(name);
    const converted = convertFormDataValue(args[0], args.length > 1, args[1]);
    list.push([key, converted]);
  }

  set(name: string, value: string): void;
  set(name: string, value: Blob, filename?: string): void;
  set(name: unknown, ...args: FormDataValueArguments): void {
    const list = this.#list;
    if (args.length === 0) {
      throw new TypeError("FormData.set requires at least 2 argument(s)");
    }
    const key = coerceToUSVString(name);
    const converted = convertFormDataValue(args[0], args.length > 1, args[1]);
    let found = false;
    let write = 0;
    for (const item of list) {
      if (item[0] !== key) {
        list[write++] = item;
      } else if (!found) {
        item[1] = converted;
        list[write++] = item;
        found = true;
      }
    }
    if (!found) {
      list[write++] = [key, converted];
    }
    list.length = write;
  }

  get(name: string): FormDataEntryValue | null;
  get(...args: FormDataNameArguments): FormDataEntryValue | null {
    const list = this.#list;
    requireArguments(args, 1, "FormData.get");
    const key = coerceToUSVString(args[0]);
    for (const item of list) {
      if (item[0] === key) {
        return item[1];
      }
    }
    return null;
  }

  getAll(name: string): FormDataEntryValue[];
  getAll(...args: FormDataNameArguments): FormDataEntryValue[] {
    const list = this.#list;
    requireArguments(args, 1, "FormData.getAll");
    const key = coerceToUSVString(args[0]);
    const values: FormDataEntryValue[] = [];
    for (const item of list) {
      if (item[0] === key) {
        values.push(item[1]);
      }
    }
    return values;
  }

  has(name: string): boolean;
  has(...args: FormDataNameArguments): boolean {
    const list = this.#list;
    requireArguments(args, 1, "FormData.has");
    const key = coerceToUSVString(args[0]);
    for (const item of list) {
      if (item[0] === key) {
        return true;
      }
    }
    return false;
  }

  delete(name: string): void;
  delete(...args: FormDataNameArguments): void {
    const list = this.#list;
    requireArguments(args, 1, "FormData.delete");
    const key = coerceToUSVString(args[0]);
    let write = 0;
    for (const item of list) {
      if (item[0] !== key) {
        list[write++] = item;
      }
    }
    list.length = write;
  }

  entries(): IterableIterator<FormDataEntry> {
    return new FormDataIterator(this.#list, selectEntry);
  }

  keys(): IterableIterator<string> {
    return new FormDataIterator(this.#list, selectName);
  }

  values(): IterableIterator<FormDataEntryValue> {
    return new FormDataIterator(this.#list, selectValue);
  }

  forEach(callback: FormDataForEachCallback, thisArg?: unknown): void {
    const list = this.#list;
    if (typeof callback !== "function") {
      throw new TypeError("FormData.forEach callback must be callable");
    }
    for (const item of list) {
      callback.call(thisArg, item[1], item[0], this);
    }
  }

  [Symbol.iterator](): IterableIterator<FormDataEntry> {
    return new FormDataIterator(this.#list, selectEntry);
  }

  get [Symbol.toStringTag](): string {
    return "FormData";
  }
}

import { isHTTPWhitespace, trimHTTPWhitespace, trimTrailingHTTPWhitespace } from "../core/ascii.ts";
import { isToken } from "../fetch/headers.ts";

export interface MIMEType {
  readonly type: string;
  readonly subtype: string;
  readonly essence: string;
  readonly parameters: ReadonlyMap<string, string>;
}

export interface ParameterizedValue {
  value: string;
  parameters: ReadonlyMap<string, string>;
}

/** Serialize a parsed MIME type without inventing or reordering parameters. */
export function serializeMIMEType(mimeType: MIMEType): string {
  let output = mimeType.essence;
  for (const [name, value] of mimeType.parameters) {
    output += ";" + name + "=";
    if (isToken(value)) {
      output += value;
      continue;
    }
    output += '"';
    for (let index = 0; index < value.length; index++) {
      const character = value.charAt(index);
      if (character === '"' || character === "\\") output += "\\";
      output += character;
    }
    output += '"';
  }
  return output;
}

function isHTTPQuotedString(value: string): boolean {
  for (let i = 0; i < value.length; ++i) {
    const code = value.charCodeAt(i);

    if (code !== 9 && (code < 32 || code === 127 || code > 255)) {
      return false;
    }
  }
  return true;
}

/** WHATWG MIME parsing. Invalid parameters are ignored; an invalid essence fails. */
export function parseMIMEType(input: string): MIMEType | null {
  const source = trimHTTPWhitespace(input);
  const slash = source.indexOf("/");

  if (slash <= 0) {
    return null;
  }

  const type = source.slice(0, slash);
  let at = source.indexOf(";", slash + 1);
  const subtype = trimTrailingHTTPWhitespace(
    at < 0 ? source.slice(slash + 1) : source.slice(slash + 1, at),
  );

  if (!isToken(type) || !isToken(subtype)) {
    return null;
  }

  const parameters = new Map<string, string>();

  while (at >= 0 && at < source.length) {
    at++;
    while (isHTTPWhitespace(source.charCodeAt(at))) {
      at++;
    }

    const nameStart = at;

    while (at < source.length && source.charAt(at) !== ";" && source.charAt(at) !== "=") {
      at++;
    }

    const name = source.slice(nameStart, at).toLowerCase();

    if (at >= source.length) {
      break;
    }
    if (source.charAt(at) === ";") {
      continue;
    }

    at++;
    if (at >= source.length) {
      break;
    }

    let value = "";

    if (source.charAt(at) === '"') {
      at++;
      while (at < source.length) {
        const char = source.charAt(at++);

        if (char === '"') {
          break;
        }
        if (char === "\\") {
          if (at >= source.length) {
            value += "\\";
            break;
          }
          value += source.charAt(at++);
        } else {
          value += char;
        }
      }
      while (at < source.length && source.charAt(at) !== ";") {
        at++;
      }
    } else {
      const valueStart = at;

      while (at < source.length && source.charAt(at) !== ";") {
        at++;
      }
      value = trimTrailingHTTPWhitespace(source.slice(valueStart, at));
      if (value.length === 0) {
        continue;
      }
    }

    if (isToken(name) && isHTTPQuotedString(value) && !parameters.has(name)) {
      parameters.set(name, value);
    }
  }

  const lowerType = type.toLowerCase();
  const lowerSubtype = subtype.toLowerCase();

  return {
    type: lowerType,
    subtype: lowerSubtype,
    essence: lowerType + "/" + lowerSubtype,
    parameters,
  };
}

/** Strict Content-Disposition parameter grammar; first duplicate wins. */
export function parseContentDisposition(input: string): ParameterizedValue {
  let at = input.indexOf(";");
  const value = trimHTTPWhitespace(at < 0 ? input : input.slice(0, at)).toLowerCase();
  const parameters = new Map<string, string>();

  if (at < 0) {
    return { value, parameters };
  }

  while (at < input.length) {
    at++;
    while (isHTTPWhitespace(input.charCodeAt(at))) {
      at++;
    }
    const start = at;
    while (at < input.length && input.charAt(at) !== "=" && input.charAt(at) !== ";") {
      at++;
    }
    const name = input.slice(start, at).toLowerCase();
    if (!isToken(name) || input.charAt(at) !== "=") {
      throw new TypeError("Malformed Content-Disposition parameter");
    }
    at++;
    while (isHTTPWhitespace(input.charCodeAt(at))) {
      at++;
    }
    let result = "";
    if (input.charAt(at) === '"') {
      at++;
      let closed = false;
      while (at < input.length) {
        let char = input.charAt(at++);
        if (char === '"') {
          closed = true;
          break;
        }
        if (char === "\\") {
          if (at >= input.length) {
            throw new TypeError("Invalid quoted Content-Disposition parameter");
          }
          char = input.charAt(at++);
        }
        if (char === "\r" || char === "\n" || char === "\0") {
          throw new TypeError("Invalid Content-Disposition parameter byte");
        }
        result += char;
      }
      if (!closed) {
        throw new TypeError("Unclosed Content-Disposition parameter");
      }
      while (isHTTPWhitespace(input.charCodeAt(at))) {
        at++;
      }
      if (at < input.length && input.charAt(at) !== ";") {
        throw new TypeError("Trailing Content-Disposition parameter characters");
      }
    } else {
      const startValue = at;
      while (at < input.length && input.charAt(at) !== ";") {
        at++;
      }
      result = trimHTTPWhitespace(input.slice(startValue, at));
      if (!isToken(result)) {
        throw new TypeError("Invalid unquoted Content-Disposition parameter");
      }
    }
    if (!parameters.has(name)) {
      parameters.set(name, result);
    }
  }
  return { value, parameters };
}

import { trimHTTPTabOrSpace } from "../core/ascii.ts";
import { decodeUTF8, encodeByteString } from "../core/encoding.ts";
import { LimitError } from "../core/errors.ts";
import { isToken } from "../fetch/headers.ts";
import { File } from "../file/blob.ts";
import { FormData } from "./form-data.ts";
import { parseContentDisposition } from "./mime.ts";
import type { MIMEType } from "./mime.ts";

export interface MultipartDecodeLimits {
  maxParts?: number;
  maxPartHeaderBytes?: number;
}

/** KMP search avoids quadratic behavior on adversarial repeated boundary prefixes. */
class BytePattern {
  private readonly needle: Uint8Array;
  private readonly prefix: number[];

  constructor(needle: Uint8Array) {
    this.needle = needle;
    this.prefix = new Array<number>(needle.length).fill(0);
    for (let i = 1, matched = 0; i < needle.length; i++) {
      while (matched > 0 && needle[i] !== needle[matched]) {
        matched = this.prefix[matched - 1] ?? 0;
      }
      if (needle[i] === needle[matched]) {
        matched++;
      }
      this.prefix[i] = matched;
    }
  }

  find(bytes: Uint8Array, from: number): number {
    for (let i = from, matched = 0; i < bytes.length; i++) {
      while (matched > 0 && bytes[i] !== this.needle[matched]) {
        matched = this.prefix[matched - 1] ?? 0;
      }
      if (bytes[i] === this.needle[matched]) {
        matched++;
      }
      if (matched === this.needle.length) {
        return i - matched + 1;
      }
    }
    return -1;
  }
}

function hasPair(bytes: Uint8Array, position: number, a: number, b: number): boolean {
  return bytes[position] === a && bytes[position + 1] === b;
}

function skipTransportPadding(bytes: Uint8Array, position: number): number {
  // RFC 2046 section 5.1.1: receivers must accept SP/HTAB after delimiters.
  while (bytes[position] === 32 || bytes[position] === 9) position++;
  return position;
}

function startsWith(bytes: Uint8Array, prefix: Uint8Array): boolean {
  if (bytes.length < prefix.length) {
    return false;
  }
  for (let i = 0; i < prefix.length; i++) {
    if (bytes[i] !== prefix[i]) {
      return false;
    }
  }
  return true;
}

/** Materializing Body.formData() parser, not an implicit network buffer. */
export function decodeMultipart(
  bytes: Uint8Array,
  mime: MIMEType,
  limits: MultipartDecodeLimits = {},
): FormData {
  const boundary = mime.parameters.get("boundary");

  if (
    mime.essence !== "multipart/form-data" ||
    boundary === undefined ||
    boundary.length < 1 ||
    boundary.length > 70 ||
    !/^[0-9A-Za-z'()+_,\-./:=? ]+$/.test(boundary) ||
    boundary.endsWith(" ")
  ) {
    throw new TypeError("Invalid multipart boundary");
  }
  const opening = encodeByteString("--" + boundary);
  const marker = encodeByteString("\r\n--" + boundary);
  const search = new BytePattern(marker);
  const headersEnd = new BytePattern(Uint8Array.of(13, 10, 13, 10));
  const maxParts = limits.maxParts ?? 10_000;
  const maxPartHeaderBytes = limits.maxPartHeaderBytes ?? 16_384;
  let offset = 0;

  if (!startsWith(bytes, opening)) {
    // MIME permits a preamble. Only a boundary at a line boundary is recognized.
    const first = search.find(bytes, 0);
    if (first < 0) {
      throw new TypeError("Missing multipart opening boundary");
    }
    offset = first + 2;
  }
  offset += opening.length;
  const result = new FormData();
  let parts = 0;

  while (true) {
    if (hasPair(bytes, offset, 45, 45)) {
      const end = skipTransportPadding(bytes, offset + 2);
      if (end !== bytes.length && !hasPair(bytes, end, 13, 10)) {
        throw new TypeError("Malformed multipart closing boundary");
      }
      return result; // An optional CRLF and arbitrary MIME epilogue are ignored.
    }
    offset = skipTransportPadding(bytes, offset);
    if (!hasPair(bytes, offset, 13, 10)) {
      throw new TypeError("Malformed multipart boundary separator");
    }
    offset += 2;
    parts++;
    if (parts > maxParts) {
      throw new LimitError("Too many multipart fields");
    }
    const end = headersEnd.find(bytes, offset);
    const headerBytes = (end < 0 ? bytes.length : end) - offset;
    if (headerBytes > maxPartHeaderBytes) {
      throw new LimitError("Multipart headers too large");
    }
    if (end < 0) {
      // Fetch formData(): malformed multipart syntax is a TypeError. A missing
      // terminator is not itself evidence that the configured limit was crossed.
      // https://fetch.spec.whatwg.org/#dom-body-formdata
      throw new TypeError("Missing multipart part headers");
    }
    let disposition: string | null = null;
    let type = "text/plain";
    for (const line of decodeUTF8(bytes.subarray(offset, end)).split("\r\n")) {
      const colon = line.indexOf(":");
      const name = line.slice(0, colon).toLowerCase();
      const value = trimHTTPTabOrSpace(line.slice(colon + 1));
      if (colon < 1 || !isToken(name) || /[\r\n\0]/.test(value)) {
        throw new TypeError("Malformed multipart part header");
      }
      if (name === "content-disposition") {
        if (disposition !== null) {
          throw new TypeError("Duplicate Content-Disposition");
        }
        disposition = value;
      } else if (name === "content-type") {
        type = value;
      } else if (name === "content-transfer-encoding") {
        const encoding = value.toLowerCase();
        if (encoding !== "binary" && encoding !== "8bit") {
          throw new TypeError("Encoded multipart parts are not supported");
        }
      }
    }
    if (disposition === null) {
      throw new TypeError("Missing multipart Content-Disposition");
    }
    const parameters = parseContentDisposition(disposition);
    const name = parameters.parameters.get("name");
    if (parameters.value !== "form-data" || name === undefined) {
      throw new TypeError("Invalid multipart disposition");
    }
    const bodyStart = end + 4;
    let next = search.find(bytes, bodyStart);
    while (next >= 0) {
      const suffix = next + marker.length;
      const closing = hasPair(bytes, suffix, 45, 45);
      const end = skipTransportPadding(bytes, suffix + (closing ? 2 : 0));
      if (
        hasPair(bytes, end, 13, 10) ||
        (closing && end === bytes.length)
      ) {
        break;
      }
      next = search.find(bytes, next + marker.length);
    }
    if (next < 0) {
      throw new TypeError("Missing multipart closing boundary");
    }
    const data = bytes.subarray(bodyStart, next);
    const filename = parameters.parameters.get("filename");
    if (filename === undefined) {
      result.append(name, decodeUTF8(data));
    } else {
      result.append(name, new File([data], filename, { type }));
    }
    offset = next + marker.length;
  }
}

import type { RandomSource } from "../provider/primitives.ts";
import { Blob } from "../file/blob.ts";
import type { BlobPart } from "../file/blob.ts";
import { FormData } from "./form-data.ts";

const HEX_DIGITS = "0123456789abcdef";

export interface EncodedMultipart {
  blob: Blob;
  contentType: string;
}

function newlines(input: string): string {
  return input.replace(/\r\n|\r|\n/g, "\r\n");
}

function quoted(input: string): string {
  return newlines(input).replace(/\r/g, "%0D").replace(/\n/g, "%0A").replace(/"/g, "%22");
}

/** Blob concatenation shares immutable segments; file contents are NOT eagerly materialized. */
export function encodeMultipart(form: FormData, random: RandomSource): EncodedMultipart {
  const entropy = new Uint8Array(24);

  random.fill(entropy);
  let boundary = "----nts-";

  for (const byte of entropy) {
    boundary += HEX_DIGITS.charAt(byte >>> 4) + HEX_DIGITS.charAt(byte & 15);
  }
  const parts: BlobPart[] = [];

  for (const [name, value] of form) {
    let header =
      "--" + boundary + '\r\nContent-Disposition: form-data; name="' + quoted(name) + '"';
    if (typeof value === "string") {
      header += "\r\n\r\n";
      parts.push(header, newlines(value), "\r\n");
    } else {
      header +=
        '; filename="' +
        quoted(value.name) +
        '"\r\nContent-Type: ' +
        (value.type || "application/octet-stream") +
        "\r\n\r\n";
      parts.push(header, value, "\r\n");
    }
  }

  parts.push("--" + boundary + "--\r\n");
  const contentType = "multipart/form-data; boundary=" + boundary;
  return { blob: new Blob(parts, { type: contentType }), contentType };
}

import { decodeUTF8, utf8 } from "../core/encoding.ts";
import { idlIterator, idlIteratorPrototype } from "../core/idl-iterator.ts";
import { coerceToUSVString } from "../core/webidl.ts";

export type SearchParamEntry = readonly [name: string, value: string];
export type SearchParamSequenceEntry = Iterable<string> & object;
export type SearchParamSequence = Iterable<SearchParamSequenceEntry>;
export type SearchParamRecord = Readonly<Record<string, string>>;
export type URLSearchParamsInit = string | SearchParamSequence | SearchParamRecord;

const upperHex = "0123456789ABCDEF";

function hexDigit(code: number | undefined): number {
  if (code === undefined) {
    return -1;
  }
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 65 && code <= 70) {
    return code - 55;
  }
  if (code >= 97 && code <= 102) {
    return code - 87;
  }
  return -1;
}

function compareEntriesByName(left: SearchParamEntry, right: SearchParamEntry): number {
  if (left[0] < right[0]) {
    return -1;
  }
  return left[0] > right[0] ? 1 : 0;
}

function isFormSafe(byte: number): boolean {
  return (
    (byte >= 65 && byte <= 90) ||
    (byte >= 97 && byte <= 122) ||
    (byte >= 48 && byte <= 57) ||
    byte === 42 ||
    byte === 45 ||
    byte === 46 ||
    byte === 95
  );
}

function isSearchParamSequence(
  init: SearchParamSequence | SearchParamRecord,
): init is SearchParamSequence {
  return Symbol.iterator in init;
}

function convertSequenceEntry(entry: SearchParamSequenceEntry): SearchParamEntry {
  if ((typeof entry !== "object" || entry === null) && typeof entry !== "function") {
    throw new TypeError("Each query pair must be an iterable [name, value] tuple");
  }

  let name = "";
  let value = "";
  let length = 0;
  for (const item of entry) {
    if (length === 0) name = coerceToUSVString(item);
    else if (length === 1) value = coerceToUSVString(item);
    else throw new TypeError("Each query pair must be an iterable [name, value] tuple");
    length++;
  }
  if (length !== 2) {
    throw new TypeError("Each query pair must be an iterable [name, value] tuple");
  }
  return [name, value];
}

export function formEncode(input: string): string {
  const source = utf8.encode(input);
  let length = 0;

  for (const byte of source) {
    length += isFormSafe(byte) || byte === 32 ? 1 : 3;
  }

  const output = new Uint8Array(length);
  let offset = 0;
  for (const byte of source) {
    if (isFormSafe(byte)) {
      output[offset++] = byte;
    } else if (byte === 32) {
      output[offset++] = 43;
    } else {
      output[offset++] = 37;
      output[offset++] = upperHex.charCodeAt(byte >>> 4);
      output[offset++] = upperHex.charCodeAt(byte & 15);
    }
  }
  return decodeUTF8(output, false, true);
}

export function formDecode(input: string): string {
  const source = utf8.encode(input);
  const bytes = new Uint8Array(source.length);
  let length = 0;

  for (let i = 0; i < source.length; ++i) {
    const byte = source[i];
    if (byte === undefined) {
      break;
    }
    if (byte === 43) {
      bytes[length++] = 32;
    } else if (byte === 37) {
      const high = hexDigit(source[i + 1]);
      const low = hexDigit(source[i + 2]);
      if (high >= 0 && low >= 0) {
        bytes[length++] = high * 16 + low;
        i += 2;
        continue;
      }
      bytes[length++] = byte;
    } else {
      bytes[length++] = byte;
    }
  }
  return decodeUTF8(bytes.subarray(0, length), false, true);
}

/** Standalone URLSearchParams. Live linkage to URL is supplied by the existing NTS URL package. */
/** Shared by every iterator `URLSearchParams` hands out; see `idl-iterator.ts`. */
const SEARCH_PARAMS_ITERATOR_PROTOTYPE = idlIteratorPrototype("URLSearchParams Iterator");

export class URLSearchParams {
  private readonly list: SearchParamEntry[] = [];

  constructor(init: URLSearchParamsInit = "") {
    if (typeof init === "string") {
      const query = init.startsWith("?") ? init.slice(1) : init;
      for (const part of query.split("&")) {
        if (part === "") {
          continue;
        }
        const index = part.indexOf("=");
        this.append(
          formDecode(index < 0 ? part : part.slice(0, index)),
          formDecode(index < 0 ? "" : part.slice(index + 1)),
        );
      }
    } else if (isSearchParamSequence(init)) {
      for (const entry of init) {
        this.list.push(convertSequenceEntry(entry));
      }
    } else {
      for (const [name, value] of Object.entries(init)) {
        this.append(name, value);
      }
    }
  }

  get size(): number {
    return this.list.length;
  }

  append(name: string, value: string): void {
    this.list.push([coerceToUSVString(name), coerceToUSVString(value)]);
  }

  get(name: string): string | null {
    const key = coerceToUSVString(name);
    for (const item of this.list) {
      if (item[0] === key) {
        return item[1];
      }
    }
    return null;
  }

  getAll(name: string): string[] {
    const key = coerceToUSVString(name);
    const values: string[] = [];
    for (const item of this.list) {
      if (item[0] === key) {
        values.push(item[1]);
      }
    }
    return values;
  }

  has(name: string, value?: string): boolean {
    const key = coerceToUSVString(name);
    const match = value === undefined ? undefined : coerceToUSVString(value);
    for (const item of this.list) {
      if (item[0] === key && (match === undefined || item[1] === match)) {
        return true;
      }
    }
    return false;
  }

  delete(name: string, value?: string): void {
    const key = coerceToUSVString(name);
    const match = value === undefined ? undefined : coerceToUSVString(value);
    let write = 0;
    for (const item of this.list) {
      if (item[0] !== key || (match !== undefined && item[1] !== match)) {
        this.list[write++] = item;
      }
    }
    this.list.length = write;
  }

  set(name: string, value: string): void {
    const key = coerceToUSVString(name);
    const val = coerceToUSVString(value);
    let found = false;
    let write = 0;
    for (const item of this.list) {
      if (item[0] !== key) {
        this.list[write++] = item;
      } else if (!found) {
        this.list[write++] = [key, val];
        found = true;
      }
    }
    if (!found) {
      this.list[write++] = [key, val];
    }
    this.list.length = write;
  }

  sort(): void {
    this.list.sort(compareEntriesByName);
  }

  // WebIDL iterator objects rather than the generators themselves; see `idl-iterator.ts` and
  // the note on `Headers`. The traversals are unchanged.
  entries(): IterableIterator<SearchParamEntry> {
    return idlIterator(SEARCH_PARAMS_ITERATOR_PROTOTYPE, this.#entrySteps());
  }

  keys(): IterableIterator<string> {
    return idlIterator(SEARCH_PARAMS_ITERATOR_PROTOTYPE, this.#keySteps());
  }

  values(): IterableIterator<string> {
    return idlIterator(SEARCH_PARAMS_ITERATOR_PROTOTYPE, this.#valueSteps());
  }

  *#entrySteps(): Generator<SearchParamEntry, void, unknown> {
    for (const entry of this.list) {
      yield [entry[0], entry[1]];
    }
  }

  *#keySteps(): Generator<string, void, unknown> {
    for (const entry of this.#entrySteps()) {
      yield entry[0];
    }
  }

  *#valueSteps(): Generator<string, void, unknown> {
    for (const entry of this.#entrySteps()) {
      yield entry[1];
    }
  }

  forEach(
    callback: (this: unknown, value: string, name: string, parent: URLSearchParams) => void,
    thisArg?: unknown,
  ): void {
    for (const [name, value] of this.entries()) {
      callback.call(thisArg, value, name, this);
    }
  }

  toString(): string {
    const result: string[] = [];
    for (const entry of this.list) {
      if (result.length !== 0) result.push("&");
      result.push(formEncode(entry[0]), "=", formEncode(entry[1]));
    }
    return result.join("");
  }

  [Symbol.iterator](): IterableIterator<SearchParamEntry> {
    return this.entries();
  }
}
// Web IDL surface shape; see core/interface-tag.ts for the rule and why it is
// written inline rather than through a helper.
// Web IDL member attributes. This prototype carries no non-standard names, so the pass
// reaches only the interface's own members.
for (const key of Object.getOwnPropertyNames(URLSearchParams.prototype)) {
  if (key === "constructor") continue;
  const descriptor = Object.getOwnPropertyDescriptor(URLSearchParams.prototype, key);
  if (descriptor === undefined || descriptor.enumerable) continue;
  descriptor.enumerable = true;
  Object.defineProperty(URLSearchParams.prototype, key, descriptor);
}
Object.defineProperty(URLSearchParams.prototype, Symbol.toStringTag, {
  value: "URLSearchParams",
  writable: false,
  enumerable: false,
  configurable: true,
});

import { decodeUTF8 } from "../core/encoding.ts";
import { FormData } from "./form-data.ts";

function hexValue(byte: number): number {
  if (byte >= 0x30 && byte <= 0x39) return byte - 0x30;
  if (byte >= 0x41 && byte <= 0x46) return byte - 0x41 + 10;
  if (byte >= 0x61 && byte <= 0x66) return byte - 0x61 + 10;
  return -1;
}

function decodeComponent(input: Uint8Array, start: number, end: number): string {
  let firstEscape = start;
  while (firstEscape < end && input[firstEscape] !== 0x25 && input[firstEscape] !== 0x2b) {
    firstEscape++;
  }
  if (firstEscape === end) return decodeUTF8(input.subarray(start, end), false, true);

  const output = new Uint8Array(end - start);
  output.set(input.subarray(start, firstEscape));
  let written = firstEscape - start;
  for (let index = firstEscape; index < end; index++) {
    const byte = input[index]!;
    if (byte === 0x2b) {
      output[written++] = 0x20;
    } else if (byte === 0x25 && index + 2 < end) {
      const high = hexValue(input[index + 1]!);
      const low = hexValue(input[index + 2]!);
      if (high >= 0 && low >= 0) {
        output[written++] = high * 16 + low;
        index += 2;
      } else output[written++] = byte;
    } else output[written++] = byte;
  }
  // This is UTF-8 decode without BOM: a leading U+FEFF is form data. Decode
  // after percent decoding so raw and escaped UTF-8 bytes can form one scalar.
  return decodeUTF8(output.subarray(0, written), false, true);
}

/** Fetch's byte-input application/x-www-form-urlencoded parser (URL §5.1). */
export function decodeURLEncoded(input: Uint8Array): FormData {
  const result = new FormData();
  let start = 0;
  while (start < input.length) {
    let end = start;
    let separator = -1;
    while (end < input.length && input[end] !== 0x26) {
      if (separator < 0 && input[end] === 0x3d) separator = end;
      end++;
    }
    if (end !== start) {
      const nameEnd = separator < 0 ? end : separator;
      const valueStart = separator < 0 ? end : separator + 1;
      result.append(decodeComponent(input, start, nameEnd), decodeComponent(input, valueStart, end));
    }
    start = end + 1;
  }
  return result;
}

import type { ConnectAddress, URLRecord } from "../provider/primitives.ts";

/** Convert a parsed network URL to the provider-neutral socket boundary. */
export function addressOf(
  url: URLRecord,
  connectTimeoutMs: number,
  alpnProtocols: readonly string[],
): ConnectAddress {
  const secure = url.protocol === "https:" || url.protocol === "wss:";
  const hostname =
    url.hostname.startsWith("[") && url.hostname.endsWith("]")
      ? url.hostname.slice(1, -1)
      : url.hostname;
  return {
    hostname,
    port: url.port === "" ? (secure ? 443 : 80) : Number(url.port),
    secure,
    connectTimeoutMs,
    alpnProtocols,
  };
}

/**
 * dNSName matching for connection reuse.
 *
 * Reusing one HTTP/2 connection for a second origin is sound only when the peer's
 * certificate actually covers that origin. Matching on hostname alone, or trusting
 * that two names "look related", is a cross-origin routing defect rather than a
 * performance shortcut, so these rules are deliberately narrow.
 */

/** Lowercases and strips one trailing root label, which is the same name. */
function normalizeName(name: string): string {
  const lower = name.toLowerCase();
  return lower.endsWith(".") ? lower.slice(0, -1) : lower;
}

/**
 * Whether one presented dNSName covers a host.
 *
 * A wildcard is accepted only as the complete leftmost label of a name with at least
 * three labels, and it matches exactly one label. `*.example.com` therefore covers
 * `a.example.com` but not `example.com` and not `a.b.example.com`, and `*.com` is
 * refused outright. Partial-label wildcards such as `f*.example.com` are not honoured:
 * they are permitted by some readings of RFC 6125 and rejected by mainstream TLS
 * stacks, and the safe reading is the one that reuses fewer connections.
 */
export function dnsNameCovers(presented: string, host: string): boolean {
  const name = normalizeName(presented);
  const target = normalizeName(host);
  if (name === "" || target === "") return false;
  if (!name.startsWith("*.")) return name === target;

  const suffix = name.slice(2);
  if (suffix === "") return false;
  // `*.com` would cover an entire registry; require a label beneath the wildcard.
  if (suffix.indexOf(".") < 0) return false;
  if (suffix.indexOf("*") >= 0) return false;
  if (!target.endsWith("." + suffix)) return false;
  const label = target.slice(0, target.length - suffix.length - 1);
  // Exactly one label, and never an empty one.
  return label !== "" && label.indexOf(".") < 0;
}

/** Whether any presented dNSName covers the host. */
export function certificateCovers(names: readonly string[], host: string): boolean {
  for (const name of names) if (dnsNameCovers(name, host)) return true;
  return false;
}

import { trimHTTPTabOrSpace } from "../core/ascii.ts";
import { ProtocolError } from "../core/errors.ts";
import type { Headers } from "../fetch/headers.ts";

/** Parse a normalized Content-Length field list under RFC 9110/9112 rules. */
export function contentLength(headers: Headers): number | null {
  const raw = headers.get("content-length");
  if (raw === null) return null;

  let result: number | null = null;
  let index = 0;
  while (true) {
    while (index < raw.length) {
      const code = raw.charCodeAt(index);
      if (code !== 9 && code !== 32) break;
      index++;
    }

    const digitsStart = index;
    let length = 0;
    while (index < raw.length) {
      const digit = raw.charCodeAt(index) - 48;
      if (digit < 0 || digit > 9) break;
      length = length * 10 + digit;
      index++;
    }
    if (index === digitsStart) throw new ProtocolError("Invalid Content-Length");
    if (!Number.isSafeInteger(length)) throw new ProtocolError("Content-Length is too large");

    while (index < raw.length) {
      const code = raw.charCodeAt(index);
      if (code !== 9 && code !== 32) break;
      index++;
    }
    if (result !== null && result !== length) {
      throw new ProtocolError("Conflicting Content-Length fields");
    }
    result = length;
    if (index === raw.length) return result;
    if (raw.charCodeAt(index) !== 44) throw new ProtocolError("Invalid Content-Length");
    index++;
  }
}

/** Test a comma-separated HTTP field for one case-insensitive token. */
export function hasToken(headers: Headers, name: string, token: string): boolean {
  const raw = headers.get(name);
  if (raw === null) return false;
  const expected = token.toLowerCase();
  let start = 0;
  while (start <= raw.length) {
    const comma = raw.indexOf(",", start);
    const end = comma < 0 ? raw.length : comma;
    if (trimHTTPTabOrSpace(raw.slice(start, end)).toLowerCase() === expected) return true;
    if (comma < 0) return false;
    start = comma + 1;
  }
  return false;
}

import type { ByteConnection } from "../provider/primitives.ts";
import { ProtocolError, LimitError } from "../core/errors.ts";
import { concatBytes, latin1 } from "../core/encoding.ts";
export async function writeAll(connection: ByteConnection, data: Uint8Array): Promise<void> {
  let offset = 0;

  while (offset < data.length) {
    const part = data.subarray(offset, Math.min(offset + 65536, data.length));
    const written = await connection.write(part);
    if (!Number.isInteger(written) || written <= 0 || written > part.length)
      throw new ProtocolError("Invalid write progress from transport");
    offset += written;
  }
}

/** Incremental buffered reader; an upgrade keeps this object so no head bytes are lost. */
export class BufferedReader {
  private readonly connection: ByteConnection;
  private buffer: Uint8Array = new Uint8Array(0);
  private position = 0;

  constructor(connection: ByteConnection) {
    this.connection = connection;
  }

  get bufferedBytes(): number {
    return this.buffer.length - this.position;
  }
  async some(maxBytes = 65536): Promise<Uint8Array | null> {
    if (!Number.isInteger(maxBytes) || maxBytes < 1)
      throw new RangeError("maxBytes must be positive");
    if (this.position === this.buffer.length) {
      const data = await this.connection.read(Math.min(65536, maxBytes));
      if (data === null) return null;
      if (data.length === 0 || data.length > Math.min(65536, maxBytes))
        throw new ProtocolError("Invalid read size from transport");
      this.buffer = data;
      this.position = 0;
    }
    const end = Math.min(this.position + maxBytes, this.buffer.length);
    const result = this.buffer.subarray(this.position, end);
    this.position = end;
    return result;
  }
  async exact(length: number): Promise<Uint8Array> {
    if (!Number.isSafeInteger(length) || length < 0) throw new RangeError("Invalid byte length");
    const result = new Uint8Array(length);
    let offset = 0;
    while (offset < length) {
      const chunk = await this.some(length - offset);
      if (chunk === null) throw new ProtocolError("Unexpected EOF");
      result.set(chunk, offset);
      offset += chunk.length;
    }
    return result;
  }
  async line(maxBytes: number): Promise<string> {
    const parts: Uint8Array[] = [];
    let size = 0;
    while (true) {
      if (this.position === this.buffer.length) {
        const chunk = await this.connection.read(65536);
        if (chunk === null) throw new ProtocolError("EOF inside an HTTP line");
        if (chunk.length === 0 || chunk.length > 65536)
          throw new ProtocolError("Invalid transport read size");
        this.buffer = chunk;
        this.position = 0;
      }
      const lf = this.buffer.indexOf(10, this.position);
      const end = lf < 0 ? this.buffer.length : lf + 1;
      const part = this.buffer.subarray(this.position, end);
      this.position = end;
      size += part.length;
      if (size > maxBytes) throw new LimitError("HTTP line exceeds configured limit");
      parts.push(part);
      if (lf >= 0) {
        const bytes = parts.length === 1 ? part : concatBytes(parts, size);
        if (bytes.length < 2 || bytes[bytes.length - 2] !== 13)
          throw new ProtocolError("HTTP requires CRLF, not bare LF");
        return latin1(bytes.subarray(0, bytes.length - 2));
      }
    }
  }
}

import { trimHTTPTabOrSpace } from "../core/ascii.ts";
import { LimitError, ProtocolError } from "../core/errors.ts";
import { Headers, isToken } from "../fetch/headers.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import { contentLength } from "../http/fields.ts";
import type { BufferedReader } from "./io.ts";

export { contentLength, hasToken } from "../http/fields.ts";

export interface HeadLimits {
  maxHeaderBytes: number;
  maxHeaders: number;
  maxInformational: number;
}

export const defaultHeadLimits: HeadLimits = {
  maxHeaderBytes: 32768,
  maxHeaders: 256,
  maxInformational: 16,
};

export interface ResponseHead {
  version: "1.0" | "1.1";
  status: number;
  statusText: string;
  headers: HeaderEntry[];
}

export interface RequestHead {
  method: string;
  /** The request target exactly as it arrived, unparsed and unnormalised. */
  target: string;
  version: "1.0" | "1.1";
  headers: HeaderEntry[];
}

export function validateWireValue(value: string): void {
  for (let i = 0; i < value.length; ++i) {
    const c = value.charCodeAt(i);
    if ((c < 32 && c !== 9) || c === 127 || c > 255) {
      throw new ProtocolError("Invalid HTTP field value");
    }
  }
}

export async function readHeaderFields(
  reader: BufferedReader,
  limits: HeadLimits,
  initialBytes = 0,
): Promise<HeaderEntry[]> {
  const headers: HeaderEntry[] = [];
  let bytes = initialBytes;

  while (true) {
    const line = await reader.line(limits.maxHeaderBytes - bytes);
    bytes += line.length + 2;
    if (line === "") {
      return headers;
    }
    if (headers.length >= limits.maxHeaders) {
      throw new LimitError("Too many HTTP headers");
    }
    const colon = line.indexOf(":");
    const name = line.slice(0, colon);
    if (colon <= 0 || !isToken(name)) {
      throw new ProtocolError("Malformed HTTP header or obsolete folding");
    }
    const value = line.slice(colon + 1);
    validateWireValue(value);
    headers.push([name.toLowerCase(), trimHTTPTabOrSpace(value)]);
  }
}

export async function readHead(
  reader: BufferedReader,
  limits: HeadLimits = defaultHeadLimits,
): Promise<ResponseHead> {
  const line = await reader.line(limits.maxHeaderBytes);
  if (
    line.length < 13 ||
    line.slice(0, 5) !== "HTTP/" ||
    line.charCodeAt(8) !== 32 ||
    line.charCodeAt(12) !== 32
  ) {
    throw new ProtocolError("Malformed HTTP response status line");
  }
  const version = line.slice(5, 8);
  const first = line.charCodeAt(9) - 48;
  const second = line.charCodeAt(10) - 48;
  const third = line.charCodeAt(11) - 48;
  if (
    (version !== "1.0" && version !== "1.1") ||
    first < 0 ||
    first > 9 ||
    second < 0 ||
    second > 9 ||
    third < 0 ||
    third > 9
  ) {
    throw new ProtocolError("Invalid HTTP status line");
  }

  const statusText = line.slice(13);
  validateWireValue(statusText);
  const status = first * 100 + second * 10 + third;

  if (status < 100 || status > 599) {
    throw new ProtocolError("Unsupported HTTP status code");
  }
  return {
    version,
    status,
    statusText,
    headers: await readHeaderFields(reader, limits, line.length + 2),
  };
}

/**
 * Reads an inbound request head: the request line and its header fields.
 *
 * The mirror of {@link readHead}, which reads a response. A server needs this before it
 * can decide anything -- whether to upgrade, which host was asked for, whether the
 * framing is one it can accept -- and until now the only implementation of it in this
 * repository was in a test harness, which is the wrong place for the thing under test.
 *
 * The target is returned exactly as it arrived. Normalising it here would put a URL
 * policy inside a framing parser, and a server that routes on a normalised target while
 * logging the original is how the two disagree.
 */
export async function readRequestHead(
  reader: BufferedReader,
  limits: HeadLimits = defaultHeadLimits,
): Promise<RequestHead> {
  const line = await reader.line(limits.maxHeaderBytes);
  const firstSpace = line.indexOf(" ");
  const lastSpace = line.lastIndexOf(" ");
  // Three parts, and the target may not be empty.
  //
  // `lastIndexOf` and "the second space" accept exactly the same request lines here,
  // because a target may not contain a space and the byte check below refuses one that
  // does. Sabotaging one into the other changes no test, and that is a fact about the
  // code rather than a gap in the tests. `lastIndexOf` is kept because it anchors the
  // version at the end, which is the property RFC 9112 states; the difference is which
  // of the two errors a malformed line reports, not whether it is refused.
  if (firstSpace <= 0 || lastSpace <= firstSpace + 1) {
    throw new ProtocolError("Malformed HTTP request line");
  }

  const method = line.slice(0, firstSpace);
  if (!isToken(method)) throw new ProtocolError("Invalid HTTP method");

  const target = line.slice(firstSpace + 1, lastSpace);
  for (let index = 0; index < target.length; index++) {
    const code = target.charCodeAt(index);
    if (code < 0x21 || code > 0x7e) throw new ProtocolError("Invalid HTTP request target");
  }

  const versionField = line.slice(lastSpace + 1);
  if (versionField.length !== 8 || versionField.slice(0, 5) !== "HTTP/") {
    throw new ProtocolError("Malformed HTTP request line");
  }
  const version = versionField.slice(5);
  if (version !== "1.0" && version !== "1.1") {
    throw new ProtocolError("Unsupported HTTP version");
  }

  return {
    method,
    target,
    version,
    headers: await readHeaderFields(reader, limits, line.length + 2),
  };
}

export function responseFraming(headers: Headers): {
  kind: "chunked" | "fixed" | "eof";
  length: number;
} {
  const length = contentLength(headers);
  const transferEncoding = headers.get("transfer-encoding");

  if (transferEncoding !== null) {
    if (length !== null) {
      throw new ProtocolError("Ambiguous Transfer-Encoding and Content-Length");
    }
    if (trimHTTPTabOrSpace(transferEncoding).toLowerCase() !== "chunked") {
      throw new ProtocolError("Unsupported or ambiguous Transfer-Encoding");
    }
    return { kind: "chunked", length: 0 };
  }
  return length === null ? { kind: "eof", length: 0 } : { kind: "fixed", length };
}

function isTabOrSpace(code: number): boolean {
  return code === 9 || code === 32;
}

function isQuotedText(code: number): boolean {
  return (
    code === 9 ||
    code === 32 ||
    code === 33 ||
    (code >= 35 && code <= 91) ||
    (code >= 93 && code <= 126) ||
    code >= 128
  );
}

function isQuotedPairValue(code: number): boolean {
  return code === 9 || code === 32 || (code >= 33 && code <= 126) || code >= 128;
}

function skipBadWhitespace(line: string, start: number): number {
  let index = start;
  while (index < line.length && isTabOrSpace(line.charCodeAt(index))) {
    index++;
  }
  return index;
}

function skipChunkExtensionValue(line: string, start: number): number {
  if (line.charCodeAt(start) !== 34) {
    let end = start;
    while (
      end < line.length &&
      !isTabOrSpace(line.charCodeAt(end)) &&
      line.charCodeAt(end) !== 59
    ) {
      end++;
    }
    if (!isToken(line.slice(start, end))) {
      throw new ProtocolError("Invalid HTTP chunk extension");
    }
    return end;
  }

  let index = start + 1;
  while (index < line.length) {
    const code = line.charCodeAt(index++);
    if (code === 34) {
      return index;
    }
    if (code === 92) {
      if (index === line.length || !isQuotedPairValue(line.charCodeAt(index++))) {
        throw new ProtocolError("Invalid HTTP chunk extension escape");
      }
    } else if (!isQuotedText(code)) {
      throw new ProtocolError("Invalid HTTP chunk extension string");
    }
  }
  throw new ProtocolError("Unterminated HTTP chunk extension string");
}

function hexDigit(code: number): number {
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 65 && code <= 70) {
    return code - 55;
  }
  if (code >= 97 && code <= 102) {
    return code - 87;
  }
  return -1;
}

/** Parse an RFC 9112 chunk-size line and validate ignored chunk extensions. */
export function parseChunkSize(line: string): number {
  validateWireValue(line);
  let index = 0;
  let size = 0;

  while (index < line.length) {
    const digit = hexDigit(line.charCodeAt(index));
    if (digit < 0) {
      break;
    }
    size = size * 16 + digit;
    index++;
  }
  if (index === 0) {
    throw new ProtocolError("Invalid HTTP chunk size");
  }

  while (index < line.length) {
    index = skipBadWhitespace(line, index);
    if (index === line.length || line.charCodeAt(index++) !== 59) {
      throw new ProtocolError("Invalid HTTP chunk extension delimiter");
    }

    index = skipBadWhitespace(line, index);
    const nameStart = index;
    while (
      index < line.length &&
      !isTabOrSpace(line.charCodeAt(index)) &&
      line.charCodeAt(index) !== 59 &&
      line.charCodeAt(index) !== 61
    ) {
      index++;
    }
    if (!isToken(line.slice(nameStart, index))) {
      throw new ProtocolError("Invalid HTTP chunk extension name");
    }

    const nameEnd = index;
    index = skipBadWhitespace(line, index);
    if (index === line.length && index !== nameEnd) {
      throw new ProtocolError("Invalid trailing whitespace in HTTP chunk extension");
    }
    if (index < line.length && line.charCodeAt(index) === 61) {
      index = skipBadWhitespace(line, index + 1);
      if (index === line.length) {
        throw new ProtocolError("Missing HTTP chunk extension value");
      }
      index = skipChunkExtensionValue(line, index);
    }
  }

  if (!Number.isSafeInteger(size)) {
    throw new LimitError("HTTP chunk is too large");
  }
  return size;
}

import { AbortController } from "../core/abort.ts";
import type { AbortSignal } from "../core/abort.ts";
import { LimitError } from "../core/errors.ts";
import type {
  ByteConnection,
  CancelHandle,
  ConnectAddress,
  Scheduler,
  SocketConnector,
} from "../provider/primitives.ts";
import { BufferedReader } from "./io.ts";
import { abortSignalSubscribe } from "../core/abort.ts";

export interface PoolOptions {
  maxConnections?: number;
  maxConnectionsPerOrigin?: number;
  maxPending?: number;
  idleTimeoutMs?: number;
}

interface RecordEntry {
  key: string;
  connection: ByteConnection;
  reader: BufferedReader;
  busy: boolean;
  timer: CancelHandle | null;
}

interface Waiter {
  key: string;
  address: ConnectAddress;
  signal: AbortSignal;
  result: PromiseWithResolvers<ConnectionLease>;
  unsubscribe: () => void;
  previous: Waiter | null;
  next: Waiter | null;
  queued: boolean;
  settled: boolean;
}

function resolveWaiter(waiter: Waiter, lease: ConnectionLease): void {
  if (waiter.settled) return;
  waiter.settled = true;
  waiter.result.resolve(lease);
}

function rejectWaiter(waiter: Waiter, reason: unknown): void {
  if (waiter.settled) return;
  waiter.settled = true;
  waiter.result.reject(reason);
}

export class ConnectionLease {
  readonly connection: ByteConnection;
  readonly reader: BufferedReader;
  private readonly record: RecordEntry;
  private readonly pool: ConnectionPool;
  private released = false;

  constructor(record: RecordEntry, pool: ConnectionPool) {
    this.connection = record.connection;
    this.reader = record.reader;
    this.record = record;
    this.pool = pool;
  }

  release(reusable: boolean): void {
    if (this.released) return;
    this.released = true;
    this.pool.release(this.record, reusable);
  }

  /**
   * Gives the connection to the caller and forgets it, without closing it.
   *
   * A protocol switch ends this pool's interest in the socket while the socket is very
   * much still alive: `release(false)` would close it, and `release(true)` would offer
   * a connection now speaking someone else's protocol to the next HTTP request. The
   * accounting is freed either way, so a detached connection does not go on occupying
   * a slot it no longer competes for.
   */
  detach(): void {
    if (this.released) return;
    this.released = true;
    this.pool.detach(this.record);
  }
}

export class ConnectionPool {
  private readonly connector: SocketConnector;
  private readonly scheduler: Scheduler;
  private readonly maxConnections: number;
  private readonly maxPerOrigin: number;
  private readonly maxPending: number;
  private readonly idleTimeoutMs: number;
  private readonly records = new Set<RecordEntry>();
  private readonly counts = new Map<string, number>();
  private firstPending: Waiter | null = null;
  private lastPending: Waiter | null = null;
  private pendingCount = 0;
  private readonly connecting = new Map<Waiter, AbortController>();
  private total = 0;
  private accepting = true;
  private destroyed = false;
  private drainResult: Promise<void> | null = null;
  /**
   * The drain **capability**, not its settler.
   *
   * `this.drainResolve = result.resolve` extracts a member as a value, which is
   * refused for the same reason `new Promise(r => { f = r })` is: a settler is a
   * settle with the promise as receiver, not a function object. Holding the
   * capability instead works because in this representation it *is* the promise
   * -- see `tests/programs/promise-with-resolvers` and
   * `tests/programs/a-capability-settled-through-an-optional-link`, which already keeps
   * one in a field.
   */
  private drainCapability: PromiseWithResolvers<void> | null = null;

  constructor(connector: SocketConnector, scheduler: Scheduler, options: PoolOptions = {}) {
    this.connector = connector;
    this.scheduler = scheduler;
    this.maxConnections = options.maxConnections ?? 64;
    this.maxPerOrigin = options.maxConnectionsPerOrigin ?? 8;
    this.maxPending = options.maxPending ?? 256;
    this.idleTimeoutMs = options.idleTimeoutMs ?? 15000;
    for (const value of [this.maxConnections, this.maxPerOrigin, this.maxPending]) {
      if (!Number.isSafeInteger(value) || value < 1) throw new RangeError("Invalid pool capacity");
    }
    if (!Number.isFinite(this.idleTimeoutMs) || this.idleTimeoutMs < 0)
      throw new RangeError("Invalid pool idle timeout");
  }

  acquire(address: ConnectAddress, signal: AbortSignal): Promise<ConnectionLease> {
    if (!this.accepting) return Promise.reject(new TypeError("Connection pool is closed"));
    if (signal.aborted) return Promise.reject(signal.reason);
    if (this.pendingCount >= this.maxPending)
      return Promise.reject(new LimitError("Connection pool queue is full"));
    const key = (address.secure ? "tls:" : "tcp:") + address.hostname + ":" + address.port;
    const waiter: Waiter = {
      key,
      address,
      signal,
      result: Promise.withResolvers(),
      unsubscribe: () => {},
      previous: null,
      next: null,
      queued: false,
      settled: false,
    };
    waiter.unsubscribe = signal[abortSignalSubscribe](() => {
      rejectWaiter(waiter, signal.reason);
      this.connecting.get(waiter)?.abort(signal.reason);
      if (waiter.queued) {
        this.removePending(waiter);
        this.pump();
      }
    });
    this.appendPending(waiter);
    this.pump();
    return waiter.result.promise;
  }

  private appendPending(waiter: Waiter): void {
    waiter.previous = this.lastPending;
    waiter.queued = true;
    if (this.lastPending === null) this.firstPending = waiter;
    else this.lastPending.next = waiter;
    this.lastPending = waiter;
    this.pendingCount++;
  }

  private removePending(waiter: Waiter): void {
    if (!waiter.queued) return;
    const previous = waiter.previous;
    const next = waiter.next;
    if (previous === null) this.firstPending = next;
    else previous.next = next;
    if (next === null) this.lastPending = previous;
    else next.previous = previous;
    waiter.previous = null;
    waiter.next = null;
    waiter.queued = false;
    this.pendingCount--;
  }

  private changeCount(key: string, delta: number): void {
    const count = (this.counts.get(key) ?? 0) + delta;
    if (count === 0) this.counts.delete(key);
    else this.counts.set(key, count);
    this.total += delta;
  }
  private drop(record: RecordEntry): void {
    if (!this.records.delete(record)) return;
    record.timer?.cancel();
    record.connection.close();
    this.changeCount(record.key, -1);
  }

  /** @internal Forget a record without closing it; see {@link ConnectionLease.detach}. */
  detach(record: RecordEntry): void {
    if (!this.records.delete(record)) return;
    record.timer?.cancel();
    this.changeCount(record.key, -1);
    this.pump();
  }
  private pump(): void {
    if (this.destroyed) return;
    for (const record of this.records)
      if (!record.busy && record.connection.closed) this.drop(record);
    let waiter = this.firstPending;
    while (waiter !== null) {
      const current = waiter;
      const next = current.next;
      if (current.settled) {
        this.removePending(current);
        current.unsubscribe();
        waiter = next;
        continue;
      }
      let idle: RecordEntry | undefined;
      for (const record of this.records)
        if (!record.busy && record.key === current.key) {
          idle = record;
          break;
        }
      if (idle !== undefined) {
        this.removePending(current);
        idle.busy = true;
        idle.timer?.cancel();
        idle.timer = null;
        current.unsubscribe();
        resolveWaiter(current, new ConnectionLease(idle, this));
        waiter = next;
        continue;
      }
      // Reclaim an unrelated idle connection before blocking on the global cap.
      if (this.total >= this.maxConnections) {
        for (const record of this.records)
          if (!record.busy) {
            this.drop(record);
            break;
          }
      }
      if (
        this.total >= this.maxConnections ||
        (this.counts.get(current.key) ?? 0) >= this.maxPerOrigin
      ) {
        waiter = next;
        continue;
      }
      this.removePending(current);
      this.changeCount(current.key, 1);
      const controller = new AbortController();
      this.connecting.set(current, controller);
      Promise.resolve()
        .then(() => this.connector.connect(current.address, controller.signal))
        .then(
          (connection) => {
            this.connecting.delete(current);
            current.unsubscribe();
            if (this.destroyed || current.settled || current.signal.aborted) {
              connection.close();
              this.changeCount(current.key, -1);
              rejectWaiter(
                current,
                current.signal.aborted
                  ? current.signal.reason
                  : new TypeError("Connection pool closed"),
              );
            } else {
              const record: RecordEntry = {
                key: current.key,
                connection,
                reader: new BufferedReader(connection),
                busy: true,
                timer: null,
              };
              this.records.add(record);
              resolveWaiter(current, new ConnectionLease(record, this));
            }
            this.pump();
          },
          (error) => {
            this.connecting.delete(current);
            current.unsubscribe();
            this.changeCount(current.key, -1);
            rejectWaiter(current, error);
            this.pump();
          },
        );
      waiter = next;
    }
    this.checkDrained();
  }

  /** @internal */ release(record: RecordEntry, reusable: boolean): void {
    if (!this.records.has(record)) return;
    if (
      !reusable ||
      !this.accepting ||
      record.connection.closed ||
      record.reader.bufferedBytes !== 0 ||
      this.idleTimeoutMs === 0
    ) {
      this.drop(record);
    } else {
      record.busy = false;
      record.timer = this.scheduler.delay(this.idleTimeoutMs, () => {
        this.drop(record);
        this.pump();
      });
    }
    this.pump();
  }

  close(): void {
    if (this.destroyed) return;
    this.accepting = false;
    this.destroyed = true;
    for (const [waiter, controller] of this.connecting) {
      const error = new TypeError("Connection pool is closed");
      rejectWaiter(waiter, error);
      controller.abort(error);
    }
    for (const record of this.records) this.drop(record);
    let waiter = this.firstPending;
    while (waiter !== null) {
      const next = waiter.next;
      this.removePending(waiter);
      waiter.unsubscribe();
      rejectWaiter(waiter, new TypeError("Connection pool is closed"));
      waiter = next;
    }
    const pending = this.drainCapability;
    this.drainCapability = null;
    pending?.resolve();
  }

  drain(): Promise<void> {
    if (this.destroyed) return Promise.resolve();
    if (this.drainResult !== null) return this.drainResult;
    this.accepting = false;
    const result = Promise.withResolvers<void>();
    this.drainResult = result.promise;
    this.drainCapability = result;
    for (const record of this.records) if (!record.busy) this.drop(record);
    this.pump();
    this.checkDrained();
    return this.drainResult;
  }

  private checkDrained(): void {
    if (
      this.accepting ||
      this.destroyed ||
      this.drainCapability === null ||
      this.pendingCount !== 0 ||
      this.connecting.size !== 0 ||
      this.records.size !== 0
    ) {
      return;
    }
    const pending = this.drainCapability;
    this.drainCapability = null;
    pending.resolve();
  }

  get stats(): { connections: number; pending: number; idle: number } {
    let idle = 0;
    for (const record of this.records) if (!record.busy) idle++;
    return { connections: this.total, pending: this.pendingCount, idle };
  }
}

