export type MockStringMatcher = string | RegExp | ((value: string) => boolean);
export type MockBodyMatcher =
  | string
  | Uint8Array
  | RegExp
  | ((bytes: Uint8Array, text: string) => boolean);
export type MockHeadersMatcher = readonly HeaderEntry[] | ((headers: Headers) => boolean);

export interface MockInterceptorOptions {
  readonly path: MockStringMatcher;
  readonly method?: MockStringMatcher;
  readonly body?: MockBodyMatcher;
  readonly headers?: MockHeadersMatcher;
  /** Matches the serialized query without its leading question mark. */
  readonly query?: MockStringMatcher;
}

export type MockReplyBody = string | Uint8Array | null;

export interface MockReplyOptions {
  readonly headers?: readonly HeaderEntry[];
  readonly trailers?: readonly HeaderEntry[];
}

export interface MockReply {
  readonly status: number;
  readonly statusText?: string;
  readonly body?: MockReplyBody;
  readonly headers?: readonly HeaderEntry[];
  readonly trailers?: readonly HeaderEntry[];
}

export interface MockRequestSnapshot {
  readonly url: URLRecord;
  readonly method: string;
  readonly headers: readonly HeaderEntry[];
  readonly body: Uint8Array | null;
  readonly bodyText: string | null;
}

export type MockReplyFactory = (request: MockRequestSnapshot) => MockReply | Promise<MockReply>;

export interface MockAgentOptions {
  readonly fallback?: FetchTransport;
  readonly maxRequestBodyBytes?: number;
  readonly maxCallHistoryEntries?: number;
  readonly ignoreTrailingSlash?: boolean;
  readonly enableCallHistory?: boolean;
}

export interface PendingMockInterceptor {
  readonly origin: MockStringMatcher;
  readonly options: MockInterceptorOptions;
  readonly remaining: number | null;
  readonly persistent: boolean;
}

export class MockNotMatchedError extends TypeError {
  readonly code = "UND_MOCK_ERR_MOCK_NOT_MATCHED";

  constructor(message = "Mock request did not match any registered interceptor") {
    super(message);
    this.name = "MockNotMatchedError";
  }
}

function validatePositiveInteger(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new RangeError(name + " must be a positive safe integer");
  }
}

function copyBytes(bytes: Uint8Array): Uint8Array {
  const result = new Uint8Array(bytes.length);
  result.set(bytes);
  return result;
}

class CapturedTransportBody implements TransportBodySource {
  readonly length: number;
  private readonly bytes: Uint8Array;

  constructor(bytes: Uint8Array) {
    this.bytes = copyBytes(bytes);
    this.length = bytes.length;
  }

  open(): ReadableStream<Uint8Array> {
    return bytesStream(this.bytes);
  }
}

function byteEqual(left: Uint8Array, right: Uint8Array): boolean {
  if (left.length !== right.length) return false;
  for (let index = 0; index < left.length; index++) {
    if (left[index] !== right[index]) return false;
  }
  return true;
}

function regularExpressionMatches(expression: RegExp, value: string): boolean {
  const previous = expression.lastIndex;
  expression.lastIndex = 0;
  const matched = expression.test(value);
  expression.lastIndex = previous;
  return matched;
}

function stringMatches(matcher: MockStringMatcher, value: string): boolean {
  if (typeof matcher === "string") return matcher === value;
  if (matcher instanceof RegExp) return regularExpressionMatches(matcher, value);
  return matcher(value);
}

function bodyMatches(matcher: MockBodyMatcher, bytes: Uint8Array, text: string): boolean {
  if (typeof matcher === "string") return matcher === text;
  if (matcher instanceof Uint8Array) return byteEqual(matcher, bytes);
  if (matcher instanceof RegExp) return regularExpressionMatches(matcher, text);
  return matcher(bytes, text);
}

function queryOf(url: URLRecord): string {
  return url.search.startsWith("?") ? url.search.slice(1) : url.search;
}

function pathOf(url: URLRecord, ignoreTrailingSlash: boolean): string {
  let path = url.pathname + url.search;
  if (!ignoreTrailingSlash) return path;
  const query = path.indexOf("?");
  const pathEnd = query < 0 ? path.length : query;
  if (pathEnd > 1 && path.charAt(pathEnd - 1) === "/") {
    path = path.slice(0, pathEnd - 1) + path.slice(pathEnd);
  }
  return path;
}

function originMatches(matcher: MockStringMatcher, origin: string): boolean {
  if (typeof matcher !== "string") return stringMatches(matcher, origin);
  const normalized = matcher.endsWith("/") ? matcher.slice(0, -1) : matcher;
  return normalized === origin;
}

function copyHeaders(entries: readonly HeaderEntry[]): HeaderEntry[] {
  const result: HeaderEntry[] = [];
  for (const [name, value] of entries) result.push([name, value]);
  return result;
}

function headersMatch(matcher: MockHeadersMatcher, entries: readonly HeaderEntry[]): boolean {
  const headers = new Headers(entries);
  if (typeof matcher === "function") return matcher(headers);
  for (const [name, expected] of matcher) {
    if (headers.get(name) !== expected) return false;
  }
  return true;
}

/** @internal Shared by the deterministic snapshot transport. */
export async function captureMockRequest(
  request: TransportRequest,
  maximumBytes: number,
): Promise<MockRequestSnapshot> {
  if (request.body === null) {
    return {
      url: request.url,
      method: request.method,
      headers: copyHeaders(request.headers),
      body: null,
      bodyText: null,
    };
  }
  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let length = 0;
  try {
    while (true) {
      request.signal.throwIfAborted();
      const item = await reader.read();
      if (item.done) break;
      length += item.value.length;
      if (length > maximumBytes) {
        const error = new LimitError("Mock request body exceeds configured limit");
        await reader.cancel(error);
        throw error;
      }
      chunks.push(copyBytes(item.value));
    }
  } finally {
    reader.releaseLock();
  }
  const body = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.length;
  }
  return {
    url: request.url,
    method: request.method,
    headers: copyHeaders(request.headers),
    body,
    bodyText: new TextDecoder().decode(body),
  };
}

/** @internal Reconstructs a consumed request without sharing its captured bytes. */
export function replayMockRequest(
  request: TransportRequest,
  snapshot: MockRequestSnapshot,
): TransportRequest {
  return {
    url: request.url,
    method: request.method,
    headers: copyHeaders(request.headers),
    body: snapshot.body === null ? null : bytesStream(snapshot.body),
    bodyLength: snapshot.body === null ? null : snapshot.body.length,
    replayBody: snapshot.body === null ? null : new CapturedTransportBody(snapshot.body),
    signal: request.signal,
  };
}

async function waitForDelay(
  scheduler: Scheduler,
  milliseconds: number,
  signal: AbortSignal,
): Promise<void> {
  signal.throwIfAborted();
  const result = Promise.withResolvers<void>();
  let timer: CancelHandle | null = null;
  const dispose = signal[abortSignalSubscribe](() => {
    timer?.cancel();
    result.reject(signal.reason);
  });
  timer = scheduler.delay(milliseconds, result.resolve);
  try {
    await result.promise;
    signal.throwIfAborted();
  } finally {
    timer.cancel();
    dispose();
  }
}

class MockDispatch {
  readonly options: MockInterceptorOptions;
  response: MockReplyFactory | null = null;
  error: Error | null = null;
  delayMilliseconds = 0;
  remaining = 1;
  persistent = false;
  defaultHeaders: HeaderEntry[] = [];
  defaultTrailers: HeaderEntry[] = [];
  addContentLength = false;

  constructor(options: MockInterceptorOptions) {
    this.options = options;
  }

  get available(): boolean {
    return this.persistent || this.remaining > 0;
  }

  get pending(): boolean {
    return this.remaining > 0;
  }

  matches(snapshot: MockRequestSnapshot, ignoreTrailingSlash: boolean): boolean {
    if (!this.available) return false;
    if (!stringMatches(this.options.path, pathOf(snapshot.url, ignoreTrailingSlash))) return false;
    if (this.options.method !== undefined && !stringMatches(this.options.method, snapshot.method)) {
      return false;
    }
    if (
      this.options.query !== undefined &&
      !stringMatches(this.options.query, queryOf(snapshot.url))
    ) {
      return false;
    }
    if (
      this.options.headers !== undefined &&
      !headersMatch(this.options.headers, snapshot.headers)
    ) {
      return false;
    }
    if (this.options.body === undefined) return true;
    if (snapshot.body === null || snapshot.bodyText === null) return false;
    return bodyMatches(this.options.body, snapshot.body, snapshot.bodyText);
  }

  consume(): void {
    if (this.remaining > 0) this.remaining--;
  }
}

export class MockScope {
  private readonly dispatch: MockDispatch;

  constructor(dispatch: MockDispatch) {
    this.dispatch = dispatch;
  }

  delay(milliseconds: number): this {
    validatePositiveInteger(milliseconds, "Mock reply delay");
    this.dispatch.delayMilliseconds = milliseconds;
    return this;
  }

  persist(): this {
    this.dispatch.persistent = true;
    return this;
  }

  times(count: number): this {
    validatePositiveInteger(count, "Mock reply count");
    this.dispatch.remaining = count;
    return this;
  }
}

export class MockInterceptor {
  private readonly options: MockInterceptorOptions;
  private readonly pool: MockPool;
  private defaultHeaders: HeaderEntry[] = [];
  private defaultTrailers: HeaderEntry[] = [];
  private addContentLength = false;

  constructor(options: MockInterceptorOptions, pool: MockPool) {
    this.options = options;
    this.pool = pool;
  }

  reply(status: number, body: MockReplyBody = "", options: MockReplyOptions = {}): MockScope {
    if (!Number.isInteger(status) || status < 100 || status > 599) {
      throw new RangeError("Invalid mock response status");
    }
    const dispatch = this.createDispatch();
    dispatch.response = () => ({
      status,
      body,
      headers: options.headers,
      trailers: options.trailers,
    });
    this.pool.register(dispatch);
    return new MockScope(dispatch);
  }

  replyUsing(factory: MockReplyFactory): MockScope {
    const dispatch = this.createDispatch();
    dispatch.response = factory;
    this.pool.register(dispatch);
    return new MockScope(dispatch);
  }

  replyWithError(error: Error): MockScope {
    if (!(error instanceof Error)) throw new TypeError("Mock reply error must be an Error");
    const dispatch = this.createDispatch();
    dispatch.error = error;
    this.pool.register(dispatch);
    return new MockScope(dispatch);
  }

  defaultReplyHeaders(headers: readonly HeaderEntry[]): this {
    this.defaultHeaders = copyHeaders(headers);
    return this;
  }

  defaultReplyTrailers(trailers: readonly HeaderEntry[]): this {
    this.defaultTrailers = copyHeaders(trailers);
    return this;
  }

  replyContentLength(): this {
    this.addContentLength = true;
    return this;
  }

  private createDispatch(): MockDispatch {
    const dispatch = new MockDispatch(this.options);
    dispatch.defaultHeaders = copyHeaders(this.defaultHeaders);
    dispatch.defaultTrailers = copyHeaders(this.defaultTrailers);
    dispatch.addContentLength = this.addContentLength;
    return dispatch;
  }
}

export class MockCallHistoryLog {
  readonly protocol: string;
  readonly host: string;
  readonly port: string;
  readonly origin: string;
  readonly path: string;
  readonly hash: string;
  readonly fullURL: string;
  readonly method: string;
  readonly bodyText: string | null;
  private readonly bodyBytes: Uint8Array | null;
  private readonly headerEntries: HeaderEntry[];

  constructor(snapshot: MockRequestSnapshot) {
    this.protocol = snapshot.url.protocol;
    this.host = snapshot.url.hostname;
    this.port = snapshot.url.port;
    this.origin = snapshot.url.origin;
    this.path = snapshot.url.pathname;
    this.hash = snapshot.url.hash;
    this.fullURL = snapshot.url.href;
    this.method = snapshot.method;
    this.bodyBytes = snapshot.body === null ? null : copyBytes(snapshot.body);
    this.bodyText = snapshot.bodyText;
    this.headerEntries = copyHeaders(snapshot.headers);
  }

  get body(): Uint8Array | null {
    return this.bodyBytes === null ? null : copyBytes(this.bodyBytes);
  }

  get headers(): readonly HeaderEntry[] {
    return copyHeaders(this.headerEntries);
  }
}

export type MockCallHistoryPredicate = (log: MockCallHistoryLog) => boolean;

export class MockCallHistory {
  private readonly entries: MockCallHistoryLog[] = [];
  private readonly maximumEntries: number;
  private dropped = 0;

  constructor(maximumEntries = 10000) {
    validatePositiveInteger(maximumEntries, "Mock call-history limit");
    this.maximumEntries = maximumEntries;
  }

  record(snapshot: MockRequestSnapshot): void {
    if (this.entries.length === this.maximumEntries) {
      this.entries.shift();
      this.dropped++;
    }
    this.entries.push(new MockCallHistoryLog(snapshot));
  }

  get droppedEntries(): number {
    return this.dropped;
  }

  calls(): MockCallHistoryLog[] {
    return this.entries.slice();
  }

  firstCall(): MockCallHistoryLog | undefined {
    return this.entries[0];
  }

  lastCall(): MockCallHistoryLog | undefined {
    return this.entries[this.entries.length - 1];
  }

  nthCall(position: number): MockCallHistoryLog | undefined {
    if (!Number.isSafeInteger(position) || position < 1) return undefined;
    return this.entries[position - 1];
  }

  filterCalls(predicate: MockCallHistoryPredicate): MockCallHistoryLog[] {
    const result: MockCallHistoryLog[] = [];
    for (const entry of this.entries) if (predicate(entry)) result.push(entry);
    return result;
  }

  clear(): void {
    this.entries.length = 0;
    this.dropped = 0;
  }

  *[Symbol.iterator](): Generator<MockCallHistoryLog> {
    yield* this.entries;
  }
}

export class MockPool implements FetchTransport {
  readonly origin: MockStringMatcher;
  private readonly agent: MockAgent;
  private readonly dispatches: MockDispatch[] = [];
  private closed = false;

  constructor(origin: MockStringMatcher, agent: MockAgent) {
    this.origin = origin;
    this.agent = agent;
  }

  intercept(options: MockInterceptorOptions): MockInterceptor {
    if (this.closed) throw new TypeError("Mock pool is closed");
    return new MockInterceptor(options, this);
  }

  dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (!originMatches(this.origin, request.url.origin)) {
      return Promise.reject(new MockNotMatchedError("Request origin does not match mock pool"));
    }
    return this.agent.dispatchFrom(this, request);
  }

  close(): Promise<void> {
    this.closed = true;
    return Promise.resolve();
  }

  cleanMocks(): void {
    this.dispatches.length = 0;
  }

  /** @internal */
  register(dispatch: MockDispatch): void {
    if (this.closed) throw new TypeError("Mock pool is closed");
    this.dispatches.push(dispatch);
  }

  /** @internal */
  find(snapshot: MockRequestSnapshot, ignoreTrailingSlash: boolean): MockDispatch | null {
    if (this.closed) return null;
    for (const dispatch of this.dispatches) {
      if (dispatch.matches(snapshot, ignoreTrailingSlash)) return dispatch;
    }
    return null;
  }

  /** @internal */
  pending(): MockDispatch[] {
    const result: MockDispatch[] = [];
    for (const dispatch of this.dispatches) if (dispatch.pending) result.push(dispatch);
    return result;
  }
}

export class MockClient extends MockPool {}

export class MockAgent implements FetchTransport {
  private readonly scheduler: Scheduler;
  private readonly fallback: FetchTransport | undefined;
  private readonly maximumBodyBytes: number;
  private readonly maximumHistoryEntries: number;
  private readonly ignoreTrailingSlash: boolean;
  private readonly pools: MockPool[] = [];
  private readonly networkMatchers: MockStringMatcher[] = [];
  private history: MockCallHistory | null;
  private active = true;
  private allowAllNetwork = true;
  private closed = false;
  private inFlight = 0;
  private inFlightDone: PromiseWithResolvers<void> | null = null;
  private closeResult: Promise<void> | null = null;

  constructor(scheduler: Scheduler, options: MockAgentOptions = {}) {
    this.scheduler = scheduler;
    this.fallback = options.fallback;
    this.maximumBodyBytes = options.maxRequestBodyBytes ?? 16 * 1024 * 1024;
    validatePositiveInteger(this.maximumBodyBytes, "Mock request body limit");
    this.maximumHistoryEntries = options.maxCallHistoryEntries ?? 10000;
    validatePositiveInteger(this.maximumHistoryEntries, "Mock call-history limit");
    this.ignoreTrailingSlash = options.ignoreTrailingSlash ?? false;
    this.history =
      options.enableCallHistory === true ? new MockCallHistory(this.maximumHistoryEntries) : null;
  }

  get(origin: MockStringMatcher): MockPool {
    if (this.closed) throw new TypeError("Mock agent is closed");
    for (const pool of this.pools) if (pool.origin === origin) return pool;
    const pool = new MockPool(origin, this);
    this.pools.push(pool);
    return pool;
  }

  async dispatch(request: TransportRequest): Promise<TransportResponse> {
    return await this.dispatchInternal(request, null);
  }

  /** @internal */
  async dispatchFrom(pool: MockPool, request: TransportRequest): Promise<TransportResponse> {
    return await this.dispatchInternal(request, pool);
  }

  private async dispatchInternal(
    request: TransportRequest,
    preferredPool: MockPool | null,
  ): Promise<TransportResponse> {
    if (this.closed) throw new TypeError("Mock agent is closed");
    this.inFlight++;
    try {
      if (!this.active) return await this.dispatchFallback(request);
      const snapshot = await captureMockRequest(request, this.maximumBodyBytes);
      request.signal.throwIfAborted();
      this.history?.record(snapshot);
      if (preferredPool !== null) {
        const dispatch = preferredPool.find(snapshot, this.ignoreTrailingSlash);
        if (dispatch !== null) return await this.reply(dispatch, snapshot, request.signal);
        return await this.dispatchNetwork(replayMockRequest(request, snapshot));
      }
      for (const pool of this.pools) {
        if (!originMatches(pool.origin, request.url.origin)) continue;
        const dispatch = pool.find(snapshot, this.ignoreTrailingSlash);
        if (dispatch !== null) return await this.reply(dispatch, snapshot, request.signal);
      }
      return await this.dispatchNetwork(replayMockRequest(request, snapshot));
    } finally {
      this.inFlight--;
      if (this.closed && this.inFlight === 0) this.inFlightDone?.resolve();
    }
  }

  activate(): void {
    if (this.closed) throw new TypeError("Mock agent is closed");
    this.active = true;
  }

  deactivate(): void {
    if (this.closed) throw new TypeError("Mock agent is closed");
    this.active = false;
  }

  enableNetConnect(matcher?: MockStringMatcher): void {
    if (matcher === undefined) {
      this.allowAllNetwork = true;
      this.networkMatchers.length = 0;
      return;
    }
    this.allowAllNetwork = false;
    this.networkMatchers.push(matcher);
  }

  disableNetConnect(): void {
    this.allowAllNetwork = false;
    this.networkMatchers.length = 0;
  }

  enableCallHistory(): this {
    if (this.history === null) this.history = new MockCallHistory(this.maximumHistoryEntries);
    return this;
  }

  disableCallHistory(): this {
    this.history = null;
    return this;
  }

  getCallHistory(): MockCallHistory | undefined {
    return this.history ?? undefined;
  }

  clearCallHistory(): void {
    this.history?.clear();
  }

  pendingInterceptors(): PendingMockInterceptor[] {
    const result: PendingMockInterceptor[] = [];
    for (const pool of this.pools) {
      for (const dispatch of pool.pending()) {
        result.push({
          origin: pool.origin,
          options: dispatch.options,
          remaining: dispatch.persistent ? null : dispatch.remaining,
          persistent: dispatch.persistent,
        });
      }
    }
    return result;
  }

  assertNoPendingInterceptors(): void {
    const pending = this.pendingInterceptors();
    if (pending.length !== 0) {
      throw new TypeError(String(pending.length) + " mock interceptor(s) remain pending");
    }
  }

  close(): Promise<void> {
    if (this.closeResult !== null) return this.closeResult;
    this.closed = true;
    this.closeResult = this.finishClose();
    return this.closeResult;
  }

  private async finishClose(): Promise<void> {
    if (this.inFlight > 0) {
      this.inFlightDone = Promise.withResolvers<void>();
      await this.inFlightDone.promise;
    }
    const closing: Promise<void>[] = [];
    for (const pool of this.pools) closing.push(pool.close());
    await Promise.all(closing);
  }

  private async reply(
    dispatch: MockDispatch,
    snapshot: MockRequestSnapshot,
    signal: AbortSignal,
  ): Promise<TransportResponse> {
    dispatch.consume();
    if (dispatch.delayMilliseconds > 0) {
      await waitForDelay(this.scheduler, dispatch.delayMilliseconds, signal);
    } else {
      await Promise.resolve();
      signal.throwIfAborted();
    }
    if (dispatch.error !== null) throw dispatch.error;
    if (dispatch.response === null) {
      throw new MockNotMatchedError("Mock interceptor has no configured reply");
    }
    const reply = await dispatch.response(snapshot);
    signal.throwIfAborted();
    if (!Number.isInteger(reply.status) || reply.status < 100 || reply.status > 599) {
      throw new RangeError("Invalid mock response status");
    }
    const body = this.replyBody(reply.body ?? "");
    const headers = new Headers(dispatch.defaultHeaders);
    if (dispatch.addContentLength && body !== null)
      headers.set("content-length", String(body.length));
    this.overrideHeaders(headers, reply.headers ?? []);
    const trailers = new Headers(dispatch.defaultTrailers);
    this.overrideHeaders(trailers, reply.trailers ?? []);
    return {
      status: reply.status,
      statusText: reply.statusText ?? "",
      headers: headers[headersRawEntries](),
      body: body === null ? null : bytesStream(body),
      trailers: Promise.resolve(trailers[headersRawEntries]()),
    };
  }

  private replyBody(body: MockReplyBody): Uint8Array | null {
    if (body === null) return null;
    return typeof body === "string" ? new TextEncoder().encode(body) : copyBytes(body);
  }

  private overrideHeaders(headers: Headers, entries: readonly HeaderEntry[]): void {
    const replaced: string[] = [];
    for (const [name, value] of entries) {
      const lower = name.toLowerCase();
      if (!replaced.includes(lower)) {
        headers.delete(name);
        replaced.push(lower);
      }
      headers.append(name, value);
    }
  }

  private dispatchNetwork(request: TransportRequest): Promise<TransportResponse> {
    if (!this.networkAllowed(request.url)) {
      return Promise.reject(
        new MockNotMatchedError(
          "Mock request was not matched and network access is disabled for " + request.url.origin,
        ),
      );
    }
    return this.dispatchFallback(request);
  }

  private dispatchFallback(request: TransportRequest): Promise<TransportResponse> {
    if (this.fallback === undefined) {
      return Promise.reject(
        new MockNotMatchedError("Mock request was not matched and no fallback transport exists"),
      );
    }
    return this.fallback.dispatch(request);
  }

  private networkAllowed(url: URLRecord): boolean {
    if (this.allowAllNetwork) return true;
    for (const matcher of this.networkMatchers) {
      if (stringMatches(matcher, url.host)) return true;
    }
    return false;
  }
}

import type { AbortSignal } from "../core/abort.ts";
import { LimitError } from "../core/errors.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type { FetchTransport, TransportRequest, TransportResponse } from "../fetch/transport.ts";
import type { CancelHandle, Scheduler, URLRecord } from "../provider/primitives.ts";
import { bytesStream } from "../streams/readable.ts";
import {
  captureMockRequest,
  replayMockRequest,
  type MockRequestSnapshot,
  type MockStringMatcher,
} from "./mock-agent.ts";

export type SnapshotMode = "record" | "playback" | "update";

export interface SnapshotRequestRecord {
  readonly method: string;
  readonly url: string;
  readonly headers: readonly HeaderEntry[];
  readonly body: Uint8Array | null;
}

export interface SnapshotResponseRecord {
  readonly status: number;
  readonly statusText: string;
  readonly headers: readonly HeaderEntry[];
  readonly body: Uint8Array | null;
  readonly trailers: readonly HeaderEntry[];
}

/**
 * Portable on-disk/in-database shape. `key` is collision-free canonical material,
 * not a provider hash; a file facade may hash it for names without changing matching.
 */
export interface SnapshotData {
  readonly key: string;
  readonly request: SnapshotRequestRecord;
  responses: SnapshotResponseRecord[];
  callCount: number;
  recordedAtMilliseconds: number;
}

export interface SnapshotInfo {
  readonly key: string;
  readonly request: SnapshotRequestRecord;
  readonly responseCount: number;
  readonly callCount: number;
  readonly recordedAtMilliseconds: number;
}

/** Implementations atomically replace the complete collection or reject. */
export interface SnapshotStore {
  loadAll(): Promise<readonly SnapshotData[]>;

  replaceAll(snapshots: readonly SnapshotData[]): Promise<void>;
}

export type SnapshotBodyNormalizer = (body: Uint8Array | null) => Uint8Array | null;
export type SnapshotQueryNormalizer = (query: string) => string;
export type SnapshotRequestPredicate = (request: SnapshotRequestRecord) => boolean;

export interface SnapshotAgentOptions {
  readonly mode?: SnapshotMode;
  readonly fallback?: FetchTransport;
  readonly store?: SnapshotStore;
  readonly maxSnapshots?: number;
  readonly maxResponsesPerSnapshot?: number;
  readonly maxTotalBytes?: number;
  readonly maxRequestBodyBytes?: number;
  readonly maxResponseBodyBytes?: number;
  readonly autoFlush?: boolean;
  readonly flushIntervalMilliseconds?: number;
  readonly matchHeaders?: readonly string[];
  readonly ignoreHeaders?: readonly string[];
  /** These fields are excluded from both matching and persistent snapshots. */
  readonly excludeHeaders?: readonly string[];
  readonly matchBody?: boolean;
  readonly normalizeBody?: SnapshotBodyNormalizer;
  readonly matchQuery?: boolean;
  readonly normalizeQuery?: SnapshotQueryNormalizer;
  readonly caseSensitiveHeaders?: boolean;
  readonly shouldRecord?: SnapshotRequestPredicate;
  readonly shouldPlayback?: SnapshotRequestPredicate;
  readonly excludeURLs?: readonly MockStringMatcher[];
  /** Inject the environment wall clock; the deterministic default is zero. */
  readonly nowMilliseconds?: () => number;
}

export class SnapshotNotFoundError extends Error {
  readonly code = "UND_SNAPSHOT_NOT_FOUND";

  constructor(method: string, url: string) {
    super("No snapshot found for " + method + " " + url);
    this.name = "SnapshotNotFoundError";
  }
}

function validatePositiveInteger(value: number, name: string): void {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new RangeError(name + " must be a positive safe integer");
  }
}

function copyBytes(bytes: Uint8Array | null): Uint8Array | null {
  return bytes === null ? null : bytes.slice();
}

function copyHeaders(headers: readonly HeaderEntry[]): HeaderEntry[] {
  const result: HeaderEntry[] = [];
  for (const [name, value] of headers) result.push([name, value]);
  return result;
}

function copyRequest(request: SnapshotRequestRecord): SnapshotRequestRecord {
  return {
    method: request.method,
    url: request.url,
    headers: copyHeaders(request.headers),
    body: copyBytes(request.body),
  };
}

function copyResponse(response: SnapshotResponseRecord): SnapshotResponseRecord {
  return {
    status: response.status,
    statusText: response.statusText,
    headers: copyHeaders(response.headers),
    body: copyBytes(response.body),
    trailers: copyHeaders(response.trailers),
  };
}

function copySnapshot(snapshot: SnapshotData): SnapshotData {
  const responses: SnapshotResponseRecord[] = [];
  for (const response of snapshot.responses) responses.push(copyResponse(response));
  return {
    key: snapshot.key,
    request: copyRequest(snapshot.request),
    responses,
    callCount: snapshot.callCount,
    recordedAtMilliseconds: snapshot.recordedAtMilliseconds,
  };
}

export class MemorySnapshotStore implements SnapshotStore {
  private snapshots: SnapshotData[] = [];

  constructor(initial: readonly SnapshotData[] = []) {
    for (const snapshot of initial) this.snapshots.push(copySnapshot(snapshot));
  }

  async loadAll(): Promise<readonly SnapshotData[]> {
    const result: SnapshotData[] = [];
    for (const snapshot of this.snapshots) result.push(copySnapshot(snapshot));
    return result;
  }

  async replaceAll(snapshots: readonly SnapshotData[]): Promise<void> {
    const replacement: SnapshotData[] = [];
    for (const snapshot of snapshots) replacement.push(copySnapshot(snapshot));
    this.snapshots = replacement;
  }
}

interface PreparedRequest {
  readonly key: string;
  readonly record: SnapshotRequestRecord;
}

interface CapturedResponse {
  readonly status: number;
  readonly statusText: string;
  readonly headers: readonly HeaderEntry[];
  readonly body: Uint8Array | null;
  readonly trailers: readonly HeaderEntry[] | null;
}

interface RecorderOptions {
  readonly store: SnapshotStore;
  readonly scheduler: Scheduler;
  readonly maximumSnapshots: number;
  readonly maximumResponsesPerSnapshot: number;
  readonly maximumTotalBytes: number;
  readonly maximumRequestBodyBytes: number;
  readonly maximumResponseBodyBytes: number;
  readonly autoFlush: boolean;
  readonly flushIntervalMilliseconds: number;
  readonly matchHeaders: readonly string[];
  readonly ignoreHeaders: readonly string[];
  readonly excludeHeaders: readonly string[];
  readonly matchBody: boolean;
  readonly normalizeBody: SnapshotBodyNormalizer | undefined;
  readonly matchQuery: boolean;
  readonly normalizeQuery: SnapshotQueryNormalizer | undefined;
  readonly caseSensitiveHeaders: boolean;
  readonly shouldRecord: SnapshotRequestPredicate | undefined;
  readonly shouldPlayback: SnapshotRequestPredicate | undefined;
  readonly excludeURLs: readonly MockStringMatcher[];
  readonly nowMilliseconds: () => number;
}

function normalHeaderName(name: string, caseSensitive: boolean): string {
  return caseSensitive ? name : name.toLowerCase();
}

function containsHeader(names: readonly string[], name: string, caseSensitive: boolean): boolean {
  const normal = normalHeaderName(name, caseSensitive);
  for (const candidate of names) {
    if (normalHeaderName(candidate, caseSensitive) === normal) return true;
  }
  return false;
}

function filterHeadersForStorage(
  headers: readonly HeaderEntry[],
  excluded: readonly string[],
  caseSensitive: boolean,
): HeaderEntry[] {
  const result: HeaderEntry[] = [];
  for (const [name, value] of headers) {
    if (containsHeader(excluded, name, caseSensitive)) continue;
    result.push([normalHeaderName(name, caseSensitive), value]);
  }
  return result;
}

function filterHeadersForMatching(
  headers: readonly HeaderEntry[],
  options: RecorderOptions,
): HeaderEntry[] {
  const result: HeaderEntry[] = [];
  for (const [name, value] of headers) {
    if (containsHeader(options.excludeHeaders, name, options.caseSensitiveHeaders)) continue;
    if (containsHeader(options.ignoreHeaders, name, options.caseSensitiveHeaders)) continue;
    if (
      options.matchHeaders.length !== 0 &&
      !containsHeader(options.matchHeaders, name, options.caseSensitiveHeaders)
    ) {
      continue;
    }
    result.push([normalHeaderName(name, options.caseSensitiveHeaders), value]);
  }
  result.sort((left, right) => {
    if (left[0] < right[0]) return -1;
    if (left[0] > right[0]) return 1;
    if (left[1] < right[1]) return -1;
    if (left[1] > right[1]) return 1;
    return 0;
  });
  return result;
}

function queryWithoutQuestionMark(search: string): string {
  return search.startsWith("?") ? search.slice(1) : search;
}

function normalizedURL(url: URLRecord, options: RecorderOptions): string {
  if (!options.matchQuery) return url.origin + url.pathname;
  const rawQuery = queryWithoutQuestionMark(url.search);
  const query = options.normalizeQuery?.(rawQuery) ?? rawQuery;
  return url.origin + url.pathname + (query === "" ? "" : "?" + query);
}

function keyPart(value: string): string {
  return String(value.length) + ":" + value;
}

function bytesKey(bytes: Uint8Array | null): string {
  if (bytes === null) return "null";
  const digits = "0123456789abcdef";
  let result = "";
  for (const byte of bytes) {
    result += digits.charAt(byte >>> 4) + digits.charAt(byte & 15);
  }
  return result;
}

function requestKey(
  method: string,
  url: string,
  headers: readonly HeaderEntry[],
  body: Uint8Array | null,
): string {
  let result = keyPart(method) + keyPart(url);
  for (const [name, value] of headers) result += keyPart(name) + keyPart(value);
  return result + keyPart(bytesKey(body));
}

function stringMatcherMatches(matcher: MockStringMatcher, value: string): boolean {
  if (typeof matcher === "string") return value.toLowerCase().includes(matcher.toLowerCase());
  if (matcher instanceof RegExp) {
    const previous = matcher.lastIndex;
    matcher.lastIndex = 0;
    const result = matcher.test(value);
    matcher.lastIndex = previous;
    return result;
  }
  return matcher(value);
}

function estimateHeaders(headers: readonly HeaderEntry[]): number {
  let size = 0;
  for (const [name, value] of headers) size += (name.length + value.length) * 2;
  return size;
}

function estimateSnapshot(snapshot: SnapshotData): number {
  let size =
    (snapshot.key.length + snapshot.request.method.length + snapshot.request.url.length) * 2;
  size += estimateHeaders(snapshot.request.headers) + (snapshot.request.body?.length ?? 0);
  for (const response of snapshot.responses) {
    size += response.statusText.length * 2;
    size += estimateHeaders(response.headers) + estimateHeaders(response.trailers);
    size += response.body?.length ?? 0;
  }
  return size;
}

function validateResponse(
  response: SnapshotResponseRecord,
  maximumResponseBodyBytes: number,
): void {
  if (!Number.isInteger(response.status) || response.status < 100 || response.status > 599) {
    throw new TypeError("Snapshot response status is invalid");
  }
  if ((response.body?.length ?? 0) > maximumResponseBodyBytes) {
    throw new LimitError("Snapshot response body exceeds configured limit");
  }
}

function validateSnapshot(snapshot: SnapshotData, options: RecorderOptions): number {
  if (snapshot.responses.length < 1) throw new TypeError("Snapshot has no responses");
  if (snapshot.responses.length > options.maximumResponsesPerSnapshot) {
    throw new LimitError("Snapshot response count exceeds configured limit");
  }
  if (!Number.isSafeInteger(snapshot.callCount) || snapshot.callCount < 0) {
    throw new TypeError("Snapshot call count is invalid");
  }
  if (!Number.isFinite(snapshot.recordedAtMilliseconds)) {
    throw new TypeError("Snapshot recorded time is invalid");
  }
  if ((snapshot.request.body?.length ?? 0) > options.maximumRequestBodyBytes) {
    throw new LimitError("Snapshot request body exceeds configured limit");
  }
  for (const response of snapshot.responses)
    validateResponse(response, options.maximumResponseBodyBytes);
  return estimateSnapshot(snapshot);
}

export class SnapshotRecorder {
  readonly maximumRequestBodyBytes: number;
  readonly maximumResponseBodyBytes: number;
  private readonly options: RecorderOptions;
  private snapshots: SnapshotData[] = [];
  private totalBytes = 0;
  private dirty = false;
  private version = 0;
  private flushTimer: CancelHandle | null = null;
  private saveTail: Promise<void> = Promise.resolve();

  constructor(options: RecorderOptions) {
    this.options = options;
    this.maximumRequestBodyBytes = options.maximumRequestBodyBytes;
    this.maximumResponseBodyBytes = options.maximumResponseBodyBytes;
  }

  isURLExcluded(url: string): boolean {
    for (const matcher of this.options.excludeURLs) {
      if (stringMatcherMatches(matcher, url)) return true;
    }
    return false;
  }

  prepare(snapshot: MockRequestSnapshot): PreparedRequest {
    let body = this.options.matchBody ? copyBytes(snapshot.body) : null;
    if (this.options.matchBody && this.options.normalizeBody !== undefined) {
      body = copyBytes(this.options.normalizeBody(copyBytes(body)));
      if ((body?.length ?? 0) > this.maximumRequestBodyBytes) {
        throw new LimitError("Normalized snapshot request body exceeds configured limit");
      }
    }
    const url = normalizedURL(snapshot.url, this.options);
    const storedHeaders = filterHeadersForStorage(
      snapshot.headers,
      this.options.excludeHeaders,
      this.options.caseSensitiveHeaders,
    );
    const matchHeaders = filterHeadersForMatching(snapshot.headers, this.options);
    const record: SnapshotRequestRecord = {
      method: snapshot.method,
      url,
      headers: storedHeaders,
      body,
    };
    return {
      key: requestKey(snapshot.method, url, matchHeaders, body),
      record,
    };
  }

  prepareResponse(response: CapturedResponse): SnapshotResponseRecord {
    return {
      status: response.status,
      statusText: response.statusText,
      headers: filterHeadersForStorage(
        response.headers,
        this.options.excludeHeaders,
        this.options.caseSensitiveHeaders,
      ),
      body: copyBytes(response.body),
      trailers: filterHeadersForStorage(
        response.trailers ?? [],
        this.options.excludeHeaders,
        this.options.caseSensitiveHeaders,
      ),
    };
  }

  mayRecord(request: SnapshotRequestRecord): boolean {
    return this.options.shouldRecord?.(copyRequest(request)) ?? true;
  }

  mayPlayback(request: SnapshotRequestRecord): boolean {
    return this.options.shouldPlayback?.(copyRequest(request)) ?? true;
  }

  find(key: string): SnapshotResponseRecord | null {
    for (const snapshot of this.snapshots) {
      if (snapshot.key !== key) continue;
      const position = Math.min(snapshot.callCount, snapshot.responses.length - 1);
      if (snapshot.callCount < Number.MAX_SAFE_INTEGER) snapshot.callCount++;
      const response = snapshot.responses[position];
      if (response === undefined) throw new TypeError("Snapshot response sequence is empty");
      return copyResponse(response);
    }
    return null;
  }

  record(prepared: PreparedRequest, response: SnapshotResponseRecord): void {
    validateResponse(response, this.options.maximumResponseBodyBytes);
    for (const snapshot of this.snapshots) {
      if (snapshot.key !== prepared.key) continue;
      if (snapshot.responses.length >= this.options.maximumResponsesPerSnapshot) {
        throw new LimitError("Snapshot response count exceeds configured limit");
      }
      const recordedAtMilliseconds = this.readNow();
      const addition = estimateSnapshot({
        key: "",
        request: { method: "", url: "", headers: [], body: null },
        responses: [response],
        callCount: 0,
        recordedAtMilliseconds: 0,
      });
      if (estimateSnapshot(snapshot) + addition > this.options.maximumTotalBytes) {
        throw new LimitError("Snapshot response sequence exceeds configured total byte limit");
      }
      this.makeRoom(addition, snapshot);
      snapshot.responses = [...snapshot.responses, copyResponse(response)];
      snapshot.recordedAtMilliseconds = recordedAtMilliseconds;
      this.totalBytes += addition;
      this.changed();
      return;
    }

    const recordedAtMilliseconds = this.readNow();
    const snapshot: SnapshotData = {
      key: prepared.key,
      request: copyRequest(prepared.record),
      responses: [copyResponse(response)],
      callCount: 0,
      recordedAtMilliseconds,
    };
    const size = validateSnapshot(snapshot, this.options);
    if (size > this.options.maximumTotalBytes) {
      throw new LimitError("Snapshot exceeds configured total byte limit");
    }
    while (this.snapshots.length >= this.options.maximumSnapshots) this.evictOldest(null);
    this.makeRoom(size, null);
    this.snapshots.push(snapshot);
    this.totalBytes += size;
    this.changed();
  }

  async loadSnapshots(): Promise<void> {
    await this.saveTail;
    const loaded = await this.options.store.loadAll();
    if (loaded.length > this.options.maximumSnapshots) {
      throw new LimitError("Snapshot count exceeds configured limit");
    }
    const replacement: SnapshotData[] = [];
    let totalBytes = 0;
    const keys: string[] = [];
    for (const candidate of loaded) {
      const snapshot = copySnapshot(candidate);
      if (keys.includes(snapshot.key))
        throw new TypeError("Snapshot store contains a duplicate key");
      if (snapshot.key !== this.keyFromRecord(snapshot.request)) {
        throw new TypeError("Snapshot key does not match its recorded request");
      }
      keys.push(snapshot.key);
      totalBytes += validateSnapshot(snapshot, this.options);
      if (totalBytes > this.options.maximumTotalBytes) {
        throw new LimitError("Stored snapshots exceed configured total byte limit");
      }
      replacement.push(snapshot);
    }
    this.snapshots = replacement;
    this.totalBytes = totalBytes;
    this.dirty = false;
    this.version++;
  }

  saveSnapshots(): Promise<void> {
    this.flushTimer?.cancel();
    this.flushTimer = null;
    const version = this.version;
    const data = this.getSnapshots();
    const saving = this.saveTail.then(() => this.options.store.replaceAll(data));
    this.saveTail = saving.then(
      () => {},
      () => {},
    );
    return saving.then(() => {
      if (this.version === version) this.dirty = false;
      if (this.dirty) this.scheduleFlush();
    });
  }

  getSnapshots(): SnapshotData[] {
    const result: SnapshotData[] = [];
    for (const snapshot of this.snapshots) result.push(copySnapshot(snapshot));
    return result;
  }

  size(): number {
    return this.snapshots.length;
  }

  clear(): void {
    if (this.snapshots.length === 0) return;
    this.snapshots.length = 0;
    this.totalBytes = 0;
    this.changed();
  }

  resetCallCounts(): void {
    for (const snapshot of this.snapshots) snapshot.callCount = 0;
  }

  deleteSnapshot(key: string): boolean {
    for (let index = 0; index < this.snapshots.length; index++) {
      const snapshot = this.snapshots[index];
      if (snapshot === undefined || snapshot.key !== key) continue;
      this.totalBytes -= estimateSnapshot(snapshot);
      this.snapshots.splice(index, 1);
      this.changed();
      return true;
    }
    return false;
  }

  getSnapshotInfo(key: string): SnapshotInfo | null {
    for (const snapshot of this.snapshots) {
      if (snapshot.key !== key) continue;
      return {
        key: snapshot.key,
        request: copyRequest(snapshot.request),
        responseCount: snapshot.responses.length,
        callCount: snapshot.callCount,
        recordedAtMilliseconds: snapshot.recordedAtMilliseconds,
      };
    }
    return null;
  }

  replaceSnapshots(snapshots: readonly SnapshotData[]): void {
    if (snapshots.length > this.options.maximumSnapshots) {
      throw new LimitError("Snapshot count exceeds configured limit");
    }
    const replacement: SnapshotData[] = [];
    const keys: string[] = [];
    let totalBytes = 0;
    for (const candidate of snapshots) {
      const snapshot = copySnapshot(candidate);
      if (keys.includes(snapshot.key)) throw new TypeError("Snapshots contain a duplicate key");
      if (snapshot.key !== this.keyFromRecord(snapshot.request)) {
        throw new TypeError("Snapshot key does not match its recorded request");
      }
      keys.push(snapshot.key);
      totalBytes += validateSnapshot(snapshot, this.options);
      if (totalBytes > this.options.maximumTotalBytes) {
        throw new LimitError("Snapshots exceed configured total byte limit");
      }
      replacement.push(snapshot);
    }
    this.snapshots = replacement;
    this.totalBytes = totalBytes;
    this.changed();
  }

  async close(save: boolean): Promise<void> {
    this.flushTimer?.cancel();
    this.flushTimer = null;
    if (save && this.dirty) await this.saveSnapshots();
    else await this.saveTail;
  }

  private changed(): void {
    this.version++;
    this.dirty = true;
    this.scheduleFlush();
  }

  private keyFromRecord(request: SnapshotRequestRecord): string {
    return requestKey(
      request.method,
      request.url,
      filterHeadersForMatching(request.headers, this.options),
      this.options.matchBody ? request.body : null,
    );
  }

  private readNow(): number {
    const result = this.options.nowMilliseconds();
    if (!Number.isFinite(result)) {
      throw new TypeError("Snapshot wall clock returned a non-finite value");
    }
    return result;
  }

  private scheduleFlush(): void {
    if (!this.options.autoFlush || !this.dirty || this.flushTimer !== null) return;
    this.flushTimer = this.options.scheduler.delay(this.options.flushIntervalMilliseconds, () => {
      this.flushTimer = null;
      this.saveSnapshots().catch((error) => this.options.scheduler.reportError(error));
    });
  }

  private makeRoom(addition: number, protectedSnapshot: SnapshotData | null): void {
    while (this.totalBytes + addition > this.options.maximumTotalBytes) {
      if (!this.evictOldest(protectedSnapshot)) {
        throw new LimitError("Snapshots exceed configured total byte limit");
      }
    }
  }

  private evictOldest(protectedSnapshot: SnapshotData | null): boolean {
    for (let index = 0; index < this.snapshots.length; index++) {
      const snapshot = this.snapshots[index];
      if (snapshot === undefined || snapshot === protectedSnapshot) continue;
      this.snapshots.splice(index, 1);
      this.totalBytes -= estimateSnapshot(snapshot);
      return true;
    }
    return false;
  }
}

async function captureBody(
  response: TransportResponse,
  maximumBytes: number,
  signal: AbortSignal,
): Promise<Uint8Array | null> {
  if (response.body === null) return null;
  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let length = 0;
  try {
    while (true) {
      signal.throwIfAborted();
      const item = await reader.read();
      if (item.done) break;
      length += item.value.length;
      if (length > maximumBytes) {
        const error = new LimitError("Snapshot response body exceeds configured limit");
        await reader.cancel(error);
        throw error;
      }
      chunks.push(item.value.slice());
    }
  } finally {
    reader.releaseLock();
  }
  const body = new Uint8Array(length);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.length;
  }
  return body;
}

async function captureResponse(
  response: TransportResponse,
  maximumBytes: number,
  signal: AbortSignal,
): Promise<CapturedResponse> {
  const body = await captureBody(response, maximumBytes, signal);
  signal.throwIfAborted();
  const trailers = response.trailers === undefined ? null : copyHeaders(await response.trailers);
  signal.throwIfAborted();
  return {
    status: response.status,
    statusText: response.statusText,
    headers: copyHeaders(response.headers),
    body,
    trailers,
  };
}

function transportResponse(response: CapturedResponse): TransportResponse {
  return {
    status: response.status,
    statusText: response.statusText,
    headers: copyHeaders(response.headers),
    body: response.body === null ? null : bytesStream(response.body),
    trailers:
      response.trailers === null ? undefined : Promise.resolve(copyHeaders(response.trailers)),
  };
}

function recordedTransportResponse(response: SnapshotResponseRecord): TransportResponse {
  return {
    status: response.status,
    statusText: response.statusText,
    headers: copyHeaders(response.headers),
    body: response.body === null ? null : bytesStream(response.body),
    trailers: Promise.resolve(copyHeaders(response.trailers)),
  };
}

function defaultNow(): number {
  return 0;
}

export class SnapshotAgent implements FetchTransport {
  private readonly mode: SnapshotMode;
  private readonly fallback: FetchTransport | undefined;
  private readonly recorder: SnapshotRecorder;
  private loaded: boolean;
  private loading: Promise<void> | null = null;
  private closed = false;
  private inFlight = 0;
  private inFlightDone: PromiseWithResolvers<void> | null = null;
  private closeResult: Promise<void> | null = null;

  constructor(scheduler: Scheduler, options: SnapshotAgentOptions = {}) {
    const mode = options.mode ?? "record";
    if (mode !== "record" && mode !== "playback" && mode !== "update") {
      throw new TypeError("Invalid snapshot mode");
    }
    const maximumSnapshots = options.maxSnapshots ?? 1000;
    const maximumResponsesPerSnapshot = options.maxResponsesPerSnapshot ?? 1000;
    const maximumTotalBytes = options.maxTotalBytes ?? 256 * 1024 * 1024;
    const maximumRequestBodyBytes = options.maxRequestBodyBytes ?? 16 * 1024 * 1024;
    const maximumResponseBodyBytes = options.maxResponseBodyBytes ?? 64 * 1024 * 1024;
    const flushIntervalMilliseconds = options.flushIntervalMilliseconds ?? 30000;
    validatePositiveInteger(maximumSnapshots, "Snapshot count limit");
    validatePositiveInteger(maximumResponsesPerSnapshot, "Snapshot response count limit");
    validatePositiveInteger(maximumTotalBytes, "Snapshot total byte limit");
    validatePositiveInteger(maximumRequestBodyBytes, "Snapshot request body limit");
    validatePositiveInteger(maximumResponseBodyBytes, "Snapshot response body limit");
    validatePositiveInteger(flushIntervalMilliseconds, "Snapshot flush interval");
    this.mode = mode;
    this.fallback = options.fallback;
    if (mode !== "playback" && this.fallback === undefined) {
      throw new TypeError("Record and update snapshot modes require a fallback transport");
    }
    if ((options.excludeURLs?.length ?? 0) !== 0 && this.fallback === undefined) {
      throw new TypeError("Excluded snapshot URLs require a fallback transport");
    }
    this.loaded = mode === "record";
    this.recorder = new SnapshotRecorder({
      store: options.store ?? new MemorySnapshotStore(),
      scheduler,
      maximumSnapshots,
      maximumResponsesPerSnapshot,
      maximumTotalBytes,
      maximumRequestBodyBytes,
      maximumResponseBodyBytes,
      autoFlush: options.autoFlush ?? false,
      flushIntervalMilliseconds,
      matchHeaders: options.matchHeaders ?? [],
      ignoreHeaders: options.ignoreHeaders ?? [],
      excludeHeaders: options.excludeHeaders ?? [],
      matchBody: options.matchBody ?? true,
      normalizeBody: options.normalizeBody,
      matchQuery: options.matchQuery ?? true,
      normalizeQuery: options.normalizeQuery,
      caseSensitiveHeaders: options.caseSensitiveHeaders ?? false,
      shouldRecord: options.shouldRecord,
      shouldPlayback: options.shouldPlayback,
      excludeURLs: options.excludeURLs ?? [],
      nowMilliseconds: options.nowMilliseconds ?? defaultNow,
    });
  }

  async dispatch(request: TransportRequest): Promise<TransportResponse> {
    if (this.closed) throw new TypeError("Snapshot agent is closed");
    this.inFlight++;
    try {
      if (this.recorder.isURLExcluded(request.url.href)) return await this.dispatchLive(request);
      await this.ensureLoaded();
      const captured = await captureMockRequest(request, this.recorder.maximumRequestBodyBytes);
      request.signal.throwIfAborted();
      const prepared = this.recorder.prepare(captured);
      if (
        (this.mode === "playback" || this.mode === "update") &&
        this.recorder.mayPlayback(prepared.record)
      ) {
        const found = this.recorder.find(prepared.key);
        if (found !== null) {
          await Promise.resolve();
          request.signal.throwIfAborted();
          return recordedTransportResponse(found);
        }
      }
      if (this.mode === "playback") {
        throw new SnapshotNotFoundError(prepared.record.method, prepared.record.url);
      }
      const live = await this.dispatchLive(replayMockRequest(request, captured));
      if (!this.recorder.mayRecord(prepared.record)) return live;
      const response = await captureResponse(
        live,
        this.recorder.maximumResponseBodyBytes,
        request.signal,
      );
      this.recorder.record(prepared, this.recorder.prepareResponse(response));
      return transportResponse(response);
    } finally {
      this.inFlight--;
      if (this.closed && this.inFlight === 0) this.inFlightDone?.resolve();
    }
  }

  getMode(): SnapshotMode {
    return this.mode;
  }

  getRecorder(): SnapshotRecorder {
    return this.recorder;
  }

  async loadSnapshots(): Promise<void> {
    if (this.loading !== null) return await this.loading;
    const loading = this.recorder.loadSnapshots();
    this.loading = loading;
    try {
      await loading;
      this.loaded = true;
    } finally {
      if (this.loading === loading) this.loading = null;
    }
  }

  async saveSnapshots(): Promise<void> {
    await this.ensureLoaded();
    await this.recorder.saveSnapshots();
  }

  clearSnapshots(): void {
    this.recorder.clear();
  }

  resetCallCounts(): void {
    this.recorder.resetCallCounts();
  }

  deleteSnapshot(key: string): boolean {
    return this.recorder.deleteSnapshot(key);
  }

  getSnapshotInfo(key: string): SnapshotInfo | null {
    return this.recorder.getSnapshotInfo(key);
  }

  replaceSnapshots(snapshots: readonly SnapshotData[]): void {
    this.recorder.replaceSnapshots(snapshots);
    this.loaded = true;
  }

  close(): Promise<void> {
    if (this.closeResult !== null) return this.closeResult;
    this.closed = true;
    this.closeResult = this.finishClose();
    return this.closeResult;
  }

  private async ensureLoaded(): Promise<void> {
    if (!this.loaded) await this.loadSnapshots();
  }

  private async dispatchLive(request: TransportRequest): Promise<TransportResponse> {
    if (this.fallback === undefined) {
      throw new TypeError("Snapshot agent has no fallback transport");
    }
    return await this.fallback.dispatch(request);
  }

  private async finishClose(): Promise<void> {
    if (this.inFlight > 0) {
      this.inFlightDone = Promise.withResolvers<void>();
      await this.inFlightDone.promise;
    }
    await this.recorder.close(this.mode !== "playback");
  }
}

import type { NavigatorCapability } from "../provider/navigator.ts";

const navigatorConstructorKey = Symbol("Navigator constructor");

/** HTML 8.10.1: the minimal environment-owned Navigator identity surface. */
export class Navigator {
  readonly #capability: NavigatorCapability;
  readonly [Symbol.toStringTag] = "Navigator";

  constructor(
    key: typeof navigatorConstructorKey | undefined = undefined,
    capability?: NavigatorCapability,
  ) {
    if (key !== navigatorConstructorKey || capability === undefined) {
      throw new TypeError("Illegal constructor");
    }
    this.#capability = capability;
  }

  /** https://html.spec.whatwg.org/multipage/system-state.html#dom-navigator-useragent */
  get userAgent(): string {
    return this.#capability.userAgent();
  }
}

/** @internal Bootstrap creates one instance for its environment's global. */
export function createNavigator(capability: NavigatorCapability): Navigator {
  return new Navigator(navigatorConstructorKey, capability);
}

import { DOMException } from "../core/errors.ts";
import { EventTarget } from "../core/events.ts";
import { coerceToDOMString, requireArguments, requireDictionary } from "../core/webidl.ts";
import { currentWebPlatformRuntime } from "../provider/environment.ts";
import type { PerformanceCapabilities, PerformanceDetailCloner } from "../provider/performance.ts";
import type { WebPlatformRuntime } from "../provider/web-platform-runtime.ts";

export interface PerformanceMarkOptions {
  detail?: unknown;
  startTime?: number;
}

export interface PerformanceMeasureOptions {
  detail?: unknown;
  duration?: number;
  end?: string | number;
  start?: string | number;
}

export interface PerformanceEntryJSON {
  name: string;
  entryType: string;
  startTime: number;
  duration: number;
}

export interface PerformanceUserTimingJSON extends PerformanceEntryJSON {
  detail: unknown;
}

export interface PerformanceJSON {
  timeOrigin: number;
}

class EntryConstruction {
  readonly name: string;
  readonly type: "mark" | "measure";
  readonly start: number;
  readonly duration: number;
  readonly detail: unknown;

  constructor(name: string, type: "mark" | "measure", start: number, duration: number, detail: unknown) {
    this.name = name;
    this.type = type;
    this.start = start;
    this.duration = duration;
    this.detail = detail;
  }
}

class PerformanceConstruction {
  readonly runtime: WebPlatformRuntime;
  readonly capabilities: PerformanceCapabilities;

  constructor(runtime: WebPlatformRuntime, capabilities: PerformanceCapabilities) {
    this.runtime = runtime;
    this.capabilities = capabilities;
  }
}

class ConvertedMarkOptions {
  detail: unknown = null;
  start: number | undefined = undefined;
}

class ConvertedMeasureOptions {
  detail: unknown = undefined;
  duration: number | undefined = undefined;
  end: string | number | undefined = undefined;
  start: string | number | undefined = undefined;
}

function finiteDouble(value: number): number {
  const number = +value;
  if (!Number.isFinite(number)) throw new TypeError("Performance timestamp must be finite");
  return number;
}

function markOrTimestamp(value: string | number): string | number {
  // Web IDL's union chooses double only for a Number; other values use DOMString.
  return typeof value === "number" ? finiteDouble(value) : coerceToDOMString(value);
}

function convertMarkOptions(value: PerformanceMarkOptions | null | undefined): ConvertedMarkOptions {
  requireDictionary(value, "PerformanceMark options");
  const result = new ConvertedMarkOptions();
  if (value !== undefined && value !== null) {
    // Dictionary members are read and converted once, in lexical order.
    const detail = value.detail;
    result.detail = detail === undefined ? null : detail;
    const start = value.startTime;
    if (start !== undefined) result.start = finiteDouble(start);
  }
  return result;
}

function convertMeasureOptions(
  value: string | PerformanceMeasureOptions | null | undefined,
): string | ConvertedMeasureOptions {
  if (value !== undefined && value !== null && typeof value !== "object" && typeof value !== "function") {
    return coerceToDOMString(value);
  }
  const result = new ConvertedMeasureOptions();
  if (value !== undefined && value !== null) {
    const options = value as PerformanceMeasureOptions;
    result.detail = options.detail;
    const duration = options.duration;
    if (duration !== undefined) result.duration = finiteDouble(duration);
    const end = options.end;
    if (end !== undefined) result.end = markOrTimestamp(end);
    const start = options.start;
    if (start !== undefined) result.start = markOrTimestamp(start);
  }
  return result;
}

function cloneDetail(value: unknown, cloner: PerformanceDetailCloner | undefined): unknown {
  // Primitive serialization carries the same value and cannot inspect storage.
  if (value === null || (typeof value !== "object" && typeof value !== "function" && typeof value !== "symbol")) {
    return value;
  }
  if (typeof value === "function" || typeof value === "symbol") {
    throw new DOMException("Performance detail cannot be cloned", "DataCloneError");
  }
  if (cloner === undefined) {
    throw new DOMException("Performance object detail requires a structured-clone capability", "NotSupportedError");
  }
  const result = cloner.clone(value);
  if (!result.ok) throw result.error;
  return result.value;
}

const navigationTimingNames = new Set([
  "navigationStart", "unloadEventStart", "unloadEventEnd", "redirectStart", "redirectEnd",
  "fetchStart", "domainLookupStart", "domainLookupEnd", "connectStart", "connectEnd",
  "secureConnectionStart", "requestStart", "responseStart", "responseEnd", "domLoading",
  "domInteractive", "domContentLoadedEventStart", "domContentLoadedEventEnd", "domComplete",
  "loadEventStart", "loadEventEnd",
]);

let entryData!: (entry: PerformanceEntry) => EntryConstruction;
let markData!: (performance: Performance, name: string, options: ConvertedMarkOptions) => EntryConstruction;
const performances = new WeakMap<WebPlatformRuntime, Performance>();

function currentPerformance(): Performance {
  const runtime = currentWebPlatformRuntime();
  const performance = performances.get(runtime);
  if (performance === undefined) {
    throw new DOMException("Performance requires provider bootstrap initialization", "NotSupportedError");
  }
  return performance;
}

/** Performance Timeline's immutable common entry attributes. */
export class PerformanceEntry {
  readonly #data: EntryConstruction;

  static {
    entryData = (entry) => entry.#data;
  }

  constructor(data: EntryConstruction | undefined = undefined) {
    if (!(data instanceof EntryConstruction)) throw new TypeError("Illegal constructor");
    this.#data = data;
  }

  get name(): string { return this.#data.name; }
  get entryType(): string { return this.#data.type; }
  get startTime(): number { return this.#data.start; }
  get duration(): number { return this.#data.duration; }
  get [Symbol.toStringTag](): string { return "PerformanceEntry"; }

  toJSON(): PerformanceEntryJSON {
    const data = this.#data;
    return { name: data.name, entryType: data.type, startTime: data.start, duration: data.duration };
  }
}

/** User Timing §3.2.1. Direct construction does not add the mark to a timeline. */
export class PerformanceMark extends PerformanceEntry {
  readonly #detail: unknown;

  constructor(name: string, options?: PerformanceMarkOptions);
  /** @internal Converted construction used by the owning Performance object. */
  constructor(data: EntryConstruction);
  constructor(name: string | EntryConstruction, options: PerformanceMarkOptions = {}) {
    let data: EntryConstruction;
    if (name instanceof EntryConstruction) {
      data = name;
    } else {
      requireArguments(arguments, 1, "PerformanceMark constructor");
      const convertedName = coerceToDOMString(name);
      const convertedOptions = convertMarkOptions(options);
      // Use the same private creation algorithm without dispatching public now().
      data = markData(currentPerformance(), convertedName, convertedOptions);
    }
    super(data);
    this.#detail = data.detail;
  }

  get detail(): unknown { return this.#detail; }
  override get [Symbol.toStringTag](): string { return "PerformanceMark"; }
  override toJSON(): PerformanceUserTimingJSON { return { ...super.toJSON(), detail: this.#detail }; }
}

/** User Timing §3.3: measure() is the only public construction operation. */
export class PerformanceMeasure extends PerformanceEntry {
  readonly #detail: unknown;

  constructor(data: EntryConstruction | undefined = undefined) {
    if (!(data instanceof EntryConstruction)) throw new TypeError("Illegal constructor");
    super(data);
    this.#detail = data.detail;
  }

  get detail(): unknown { return this.#detail; }
  override get [Symbol.toStringTag](): string { return "PerformanceMeasure"; }
  override toJSON(): PerformanceUserTimingJSON { return { ...super.toJSON(), detail: this.#detail }; }
}

/** HR Time and User Timing for a non-Window environment. */
export class Performance extends EventTarget {
  readonly #runtime: WebPlatformRuntime;
  readonly #origin: number;
  readonly #epochOrigin: number | undefined;
  readonly #cloner: PerformanceDetailCloner | undefined;
  readonly #entries: PerformanceEntry[] = [];

  static {
    markData = (performance, name, options) => performance.#makeMarkData(name, options);
  }

  constructor(construction: PerformanceConstruction | undefined = undefined) {
    if (!(construction instanceof PerformanceConstruction)) throw new TypeError("Illegal constructor");
    super();
    const origin = construction.capabilities.timeOrigin;
    if (origin !== undefined && (!Number.isFinite(origin.epochMilliseconds) || !Number.isFinite(origin.monotonicMilliseconds))) {
      throw new TypeError("Performance time origin must contain finite clock values");
    }
    this.#runtime = construction.runtime;
    this.#origin = origin?.monotonicMilliseconds ?? 0;
    this.#epochOrigin = origin?.epochMilliseconds;
    this.#cloner = construction.capabilities.detailCloner;
  }

  // The hot path is one direct provider method call and one constant subtraction.
  now(): number { return this.#runtime.monotonicMilliseconds() - this.#origin; }

  get timeOrigin(): number {
    if (this.#epochOrigin === undefined) {
      throw new DOMException("Performance timeOrigin requires a correlated environment origin", "NotSupportedError");
    }
    return this.#epochOrigin;
  }

  get [Symbol.toStringTag](): string { return "Performance"; }

  toJSON(): PerformanceJSON {
    // Use the intrinsic getter's state, rather than a replaceable public member.
    if (this.#epochOrigin === undefined) {
      throw new DOMException("Performance timeOrigin requires a correlated environment origin", "NotSupportedError");
    }
    return { timeOrigin: this.#epochOrigin };
  }

  mark(name: string, options: PerformanceMarkOptions = {}): PerformanceMark {
    if (!(#entries in this)) throw new TypeError("Performance method called on an incompatible receiver");
    requireArguments(arguments, 1, "Performance.mark");
    const convertedName = coerceToDOMString(name);
    const convertedOptions = convertMarkOptions(options);
    const mark = new PerformanceMark(this.#makeMarkData(convertedName, convertedOptions));
    this.#entries.push(mark);
    return mark;
  }

  #makeMarkData(name: string, options: ConvertedMarkOptions): EntryConstruction {
    if (options.start !== undefined && options.start < 0) throw new TypeError("Mark startTime must not be negative");
    const start = options.start ?? this.#runtime.monotonicMilliseconds() - this.#origin;
    const detail = cloneDetail(options.detail, this.#cloner);
    return new EntryConstruction(name, "mark", start, 0, detail);
  }

  clearMarks(name?: string): void {
    if (!(#entries in this)) throw new TypeError("Performance method called on an incompatible receiver");
    this.#clear("mark", name === undefined ? undefined : coerceToDOMString(name));
  }

  measure(
    name: string,
    startOrOptions: string | PerformanceMeasureOptions = {},
    endMark?: string,
  ): PerformanceMeasure {
    if (!(#entries in this)) throw new TypeError("Performance method called on an incompatible receiver");
    requireArguments(arguments, 1, "Performance.measure");
    const convertedName = coerceToDOMString(name);
    const options = convertMeasureOptions(startOrOptions);
    const convertedEnd = endMark === undefined ? undefined : coerceToDOMString(endMark);
    if (typeof options !== "string" && (options.start !== undefined || options.end !== undefined ||
        options.duration !== undefined || options.detail !== undefined)) {
      if (convertedEnd !== undefined) throw new TypeError("Measure options and an end mark cannot both be supplied");
      if (options.start === undefined && options.end === undefined) throw new TypeError("Measure options require start or end");
      if (options.start !== undefined && options.end !== undefined && options.duration !== undefined) {
        throw new TypeError("Measure options cannot supply start, end and duration together");
      }
    }

    let end: number;
    if (convertedEnd !== undefined) end = this.#timestamp(convertedEnd);
    else if (typeof options !== "string" && options.end !== undefined) end = this.#timestamp(options.end);
    else if (typeof options !== "string" && options.start !== undefined && options.duration !== undefined) {
      end = this.#timestamp(options.start) + this.#timestamp(options.duration);
    } else end = this.#runtime.monotonicMilliseconds() - this.#origin;

    let start: number;
    if (typeof options !== "string" && options.start !== undefined) start = this.#timestamp(options.start);
    else if (typeof options !== "string" && options.duration !== undefined && options.end !== undefined) {
      const duration = this.#timestamp(options.duration);
      start = this.#timestamp(options.end) - duration;
    } else if (typeof options === "string") start = this.#timestamp(options);
    else start = 0;
    const detail = typeof options !== "string" && options.detail !== undefined
      ? cloneDetail(options.detail, this.#cloner) : null;
    const entry = new PerformanceMeasure(new EntryConstruction(convertedName, "measure", start, end - start, detail));
    this.#entries.push(entry);
    return entry;
  }

  #timestamp(mark: string | number): number {
    if (typeof mark === "number") {
      if (mark < 0) throw new TypeError("Measure timestamp must not be negative");
      return mark;
    }
    if (navigationTimingNames.has(mark)) {
      throw new TypeError("Navigation timing names require a Window environment");
    }
    for (let index = this.#entries.length - 1; index >= 0; index--) {
      const entry = this.#entries[index]!;
      const data = entryData(entry);
      if (data.type === "mark" && data.name === mark) return data.start;
    }
    throw new DOMException("The requested performance mark does not exist", "SyntaxError");
  }

  clearMeasures(name?: string): void {
    if (!(#entries in this)) throw new TypeError("Performance method called on an incompatible receiver");
    this.#clear("measure", name === undefined ? undefined : coerceToDOMString(name));
  }

  #clear(type: string, name: string | undefined): void {
    let retained = 0;
    for (const entry of this.#entries) {
      const data = entryData(entry);
      if (data.type !== type || (name !== undefined && data.name !== name)) this.#entries[retained++] = entry;
    }
    this.#entries.length = retained;
  }

  getEntries(): PerformanceEntry[] { return this.#filter(undefined, undefined); }

  getEntriesByType(type: string): PerformanceEntry[] {
    if (!(#entries in this)) throw new TypeError("Performance method called on an incompatible receiver");
    requireArguments(arguments, 1, "Performance.getEntriesByType");
    return this.#filter(undefined, coerceToDOMString(type));
  }

  getEntriesByName(name: string, type?: string): PerformanceEntry[] {
    if (!(#entries in this)) throw new TypeError("Performance method called on an incompatible receiver");
    requireArguments(arguments, 1, "Performance.getEntriesByName");
    const convertedName = coerceToDOMString(name);
    const convertedType = type === undefined ? undefined : coerceToDOMString(type);
    return this.#filter(convertedName, convertedType);
  }

  #filter(name: string | undefined, type: string | undefined): PerformanceEntry[] {
    const result: PerformanceEntry[] = [];
    for (const entry of this.#entries) {
      const data = entryData(entry);
      if ((name === undefined || data.name === name) && (type === undefined || data.type === type)) result.push(entry);
    }
    return result.sort((left, right) => entryData(left).start - entryData(right).start);
  }
}

/** @internal Provider bootstrap installs one canonical Performance per runtime. */
export function createPerformance(runtime: WebPlatformRuntime, capabilities: PerformanceCapabilities = {}): Performance {
  if (performances.has(runtime)) throw new TypeError("Performance is already installed for this runtime");
  const performance = new Performance(new PerformanceConstruction(runtime, capabilities));
  performances.set(runtime, performance);
  return performance;
}

