  readonly saltBytes: number | undefined;
  readonly labelBytes: number | undefined;
}

export interface CryptoEcSupport {
  readonly kind: "ec";
  readonly name: "ECDSA" | "ECDH";
  readonly namedCurve: string | undefined;
  readonly hash: CryptoDigestName | undefined;
}

export interface CryptoOkpSupport {
  readonly kind: "okp";
  readonly name: CryptoOkpCurve;
  readonly contextBytes: number | undefined;
}

export interface CryptoKdfSupport {
  readonly kind: "kdf";
  readonly name: "HKDF" | "PBKDF2";
  readonly hash: CryptoDigestName | undefined;
  readonly saltBytes: number | undefined;
  readonly infoBytes: number | undefined;
  readonly iterations: number | undefined;
}

export interface CryptoArgon2Support {
  readonly kind: "argon2";
  readonly name: "Argon2d" | "Argon2i" | "Argon2id";
  readonly nonceBytes: number | undefined;
  readonly parallelism: number | undefined;
  readonly memory: number | undefined;
  readonly passes: number | undefined;
  readonly secretBytes: number | undefined;
  readonly associatedDataBytes: number | undefined;
}

export interface CryptoMlSupport {
  readonly kind: "ml";
  readonly name: "ML-DSA-44" | "ML-DSA-65" | "ML-DSA-87" | "ML-KEM-512" | "ML-KEM-768" | "ML-KEM-1024";
  readonly contextBytes: number | undefined;
}

export type CryptoSupportParameters = CryptoDigestSupport | CryptoCShakeSupport
  | CryptoCipherSupport | CryptoHmacSupport | CryptoKmacSupport | CryptoRsaSupport
  | CryptoEcSupport | CryptoOkpSupport | CryptoKdfSupport | CryptoArgon2Support | CryptoMlSupport;

/** One normalized algorithm requirement; composed operations query in specification order. */
export interface CryptoSupportQuery {
  readonly operation: CryptoSupportOperation;
  readonly parameters: CryptoSupportParameters;
  /** Requested derivation bits; null for omitted length or another operation. */
  readonly length: number | null;
}

/**
 * Complete seam proposed for review before implementing the remaining algorithms.
 * No method performs Web Crypto's operation registration, input conversion, usage,
 * extractability or format-policy checks. Invalid mathematical key material may
 * return { failure: "invalid-key" }; other native failures return
 * { failure: "operation" }. Native code does not throw across this interface.
 * Verification distinguishes an invalid-signature false result from a reported
 * native failure. The shared caller alone selects observable errors and their order.
 */
export interface CryptoProvider extends CryptoDigestProvider {
  /**
   * Read native algorithm availability and known implementation limits without
   * generating/importing keys, deriving secrets, hashing, signing or encrypting.
   * Shared code has already checked its registry and the specification's policy.
   * Only primitive names, typed metadata and borrowed generation exponent bytes
   * cross this seam; author dictionaries, CryptoKeys and JWKs never do.
   * Return false when the operation must fail for every possible key/data due to
   * a native limitation. Unknown key/data-dependent outcomes do not imply lack
   * of support. A query failure is a value, which shared code maps to false.
   * No randomness, scheduled crypto task, cryptographic probe or retained input.
   * A composed operation first queries its additional algorithm and stops on
   * false before normalizing/querying the primary operation. KEM composition
   * first normalizes its algorithm to obtain the shared-key length (§3.2.6).
   * https://wicg.github.io/webcrypto-modern-algos/#partial-subtlecrypto-interface-checking-support-for-algorithm
   */
  supports(query: CryptoSupportQuery): boolean | CryptoFailure;

  /** One whole-message cSHAKE call; SHAKE-equivalent empty N/S stays native too. */
  digestXof(parameters: CryptoCshakeParameters, bytes: Uint8Array): Uint8Array | CryptoFailure;

  /**
   * Shared code validates the original DER's structure, exact consumption, OIDs,
   * versions and parameter presence before calling this method. Native parsers can
   * accept trailing bytes or normalize AlgorithmIdentifier parameters, so successful
   * native import is not evidence that the original encoding meets the specification.
   * Components have already been decoded from JWK and checked by shared code.
   * Report the actual type, curve, modulus and exponent in info. Mathematical
   * decoding must not strengthen the API's import requirements: in particular,
   * OKP public imports retain the supplied encoded point without imposing an
   * on-curve, canonical-encoding or small-order test. ML-KEM public imports also
   * preserve the supplied encoded key: FIPS 203's encapsulation-key check belongs
   * to encapsulation. Verification/agreement/encapsulation apply the requested
   * cryptographic operation's rules when the key is used. Shared
   * code is responsible for any format-specific public/private consistency check.
   */
  importKey(input: CryptoKeyImport): CryptoKeyRecord | CryptoFailure;

  /**
   * Shared code selects the permitted format and checks extractability first.
   * DER output uses the standard key's SPKI/PKCS #8 structures, never encrypted
   * PKCS #8, PEM, native structs or a provider-specific algorithm identifier.
   * Modern Algorithms §§6.4.6 and 8.4.5: ML-KEM/ML-DSA raw export returns
   * public-key bytes, and raw-seed returns the original private seed. ML-KEM's
   * 64-byte seed is the 32-byte d followed by the 32-byte z. Their PKCS #8
   * exports must use RFC 9935/RFC 9881's seed-only [0] IMPLICIT OCTET STRING,
   * respectively, never expandedKey or both.
   */
  exportKey(key: CryptoKeyHandle, format: "raw" | "raw-seed" | "spki" | "pkcs8"): Uint8Array | CryptoFailure;

  /**
   * Derive a public handle from a private handle without exporting secret bytes.
   * The returned record has actual public metadata and an independently owned
   * handle. No Web Crypto usage or extractability policy crosses this boundary.
   */
  getPublicKey(key: CryptoKeyHandle): CryptoKeyRecord | CryptoFailure;

  /** Return decoded components; the shared layer constructs and validates JWK. */
  exportComponents(key: CryptoKeyHandle): CryptoKeyComponents | CryptoFailure;

  generateKeyPair(parameters: CryptoKeyPairGeneration): CryptoKeyPairRecord | CryptoFailure;

  /** CBC input is already padded; AEAD returns its tag separately, others use null. */
  encrypt(parameters: CryptoCipherParameters, key: CryptoKeyHandle, data: Uint8Array): CryptoCiphertext | CryptoFailure;

  /** CBC output remains padded. Authentication failure must not return plaintext. */
  decrypt(parameters: CryptoCipherParameters, key: CryptoKeyHandle, data: CryptoCiphertext): Uint8Array | CryptoFailure;

  sign(parameters: CryptoSignatureParameters, key: CryptoKeyHandle, data: Uint8Array): CryptoSignature | CryptoFailure;

  /** Invalid signatures return false; HMAC comparison must be constant-time. */
  verify(
    parameters: CryptoSignatureParameters,
    key: CryptoKeyHandle,
    signature: CryptoSignature,
    data: Uint8Array,
  ): boolean | CryptoFailure;

  /**
   * FIPS 203 §7.2: check the encoded encapsulation key and perform ML-KEM.Encaps
   * using native secure randomness. Return both complete outputs in one call.
   * An invalid key or native failure is a failure value, never partial output.
   */
  encapsulate(parameters: CryptoKemParameters, key: CryptoKeyHandle): CryptoEncapsulation | CryptoFailure;

  /**
   * FIPS 203 §7.3: check the decapsulation input and perform ML-KEM.Decaps in one
   * native call. Implicit rejection is part of this primitive: a correctly sized
   * altered ciphertext normally yields the complete 32-byte rejection secret,
   * not an authentication error. Input-check or native failures return a value.
   */
  decapsulate(parameters: CryptoKemParameters, key: CryptoKeyHandle, ciphertext: Uint8Array): Uint8Array | CryptoFailure;

  /**
   * Agreement returns the complete fixed-width secret; shared code applies the
   * requested bit length and X25519/X448's all-zero rule. It must do that comparison
   * without data-dependent early exit. KDF requests specify the complete byte count;
   * shared code validates their bit-length/iteration rules before the single call.
   */
  derive(parameters: CryptoDerivationParameters, key: CryptoKeyHandle): Uint8Array | CryptoFailure;
}

import type { WebPlatformRuntime } from "./web-platform-runtime.ts";

/**
 * Native environment slot implemented by each NTS provider.
 *
 * These declarations are intentionally not properties of `globalThis`. Compiled
 * TypeScript calls a typed native ABI; host-only conformance providers may supply
 * equivalent globals while executing the same source as ordinary JavaScript.
 */
/** @ntsAbi intrinsic */
declare function nts_environment_install_platform(runtime: WebPlatformRuntime): void;
/** @ntsAbi intrinsic */
declare function nts_environment_platform(): WebPlatformRuntime;
/** @ntsAbi intrinsic */
declare function nts_environment_has_platform(): boolean;

/** Associate the shared Web-platform state with the current NTS environment. */
export function installWebPlatformRuntime(runtime: WebPlatformRuntime): void {
  nts_environment_install_platform(runtime);
}

/**
 * Whether this environment has a Web-platform runtime, without provoking one.
 *
 * `has` rather than a nullable read, and the reason belongs with the accessor below:
 * reading before installation aborts *so that* the declared return stays non-nullable
 * and bootstrap does not depend on how absence is represented. A nullable form would put
 * that dependency back. Ask, then read.
 */
export function hasWebPlatformRuntime(): boolean {
  return nts_environment_has_platform();
}

/** Obtain the Web-platform state owned by the current NTS environment. */
export function currentWebPlatformRuntime(): WebPlatformRuntime {
  return nts_environment_platform();
}

import type { ErrorEvent, Event } from "../core/events.ts";

/** Implementation-defined error metadata, extracted without invoking script getters. */
export interface GlobalErrorInformation {
  readonly message: string;
  readonly filename: string;
  readonly lineno: number;
  readonly colno: number;
  /** Whether HTML's selected classic script has its muted-errors flag set. */
  readonly muted: boolean;
}

/** Canonical ErrorEvent data, independent of overridable public accessors. */
export interface GlobalErrorEventData {
  readonly message: string;
  readonly filename: string;
  readonly lineno: number;
  readonly colno: number;
  readonly error: unknown;
}

export type GlobalErrorEventType = "error" | "unhandledrejection" | "rejectionhandled";
export type GlobalErrorListener = (event: Event) => void;

/** HTML's two argument lists for a global's event-handler IDL attributes. */
export type GlobalHandlerArguments =
  | [event: Event]
  | [message: string, filename: string, lineno: number, colno: number, error: unknown];
export type GlobalHandlerCallback = (this: object, ...args: GlobalHandlerArguments) => unknown;

/** Opaque provider-owned callback context; source retains it without inspection. */
export type GlobalHandlerContext = object;

/** Web IDL's callback completion crosses the native binding as a value. */
export type GlobalHandlerInvocationResult =
  | { readonly ok: true; readonly value: unknown }
  | { readonly ok: false; readonly error: unknown };

/** A source-owned reporting destination, including one in a different realm. */
export interface GlobalExceptionReporter {
  reportException(exception: unknown, omitError?: boolean): void;
}

/**
 * Engine/provider boundaries for HTML's global error policy.
 *
 * These operations are infallible: native bindings must never throw into
 * TypeScript. A binding must not advertise this capability until it can supply
 * the actual global's event state, exception metadata, and Promise internal
 * slots. A detached EventTarget or a thenable inspection is not equivalent.
 * Source code owns event construction, cancellation policy and rejection lists.
 */
export interface GlobalErrorCapabilities {
  /** The actual global (or WindowProxy exposed as its this value). */
  readonly globalObject: object;

  /** Web IDL receiver resolution for reportError borrowed across globals. */
  resolveGlobalReporter(receiver: object): GlobalExceptionReporter | null;

  /** No Get, ToString, stack parsing, or other script-observable input access. */
  extractErrorInformation(exception: unknown): GlobalErrorInformation;

  /**
   * Read the canonical ErrorEvent fields initialized by its constructor. This
   * infallible intrinsic must not dispatch subclass getters, inspect public
   * properties, or coerce values. The compiler/provider owns these layouts.
   */
  readErrorEventData(event: ErrorEvent): GlobalErrorEventData;

  /**
   * Internal non-capture listener operations at the real global target.
   * Route by the event's internal type, never an overridable `type` getter.
   */
  addGlobalEventListener(type: GlobalErrorEventType, callback: GlobalErrorListener): void;
  removeGlobalEventListener(type: GlobalErrorEventType, callback: GlobalErrorListener): void;

  /**
   * Capture the assigning script's incumbent settings during Web IDL callback
   * conversion. This infallible operation runs for every object assignment,
   * even when the same callback is assigned again. The token must retain that
   * conversion-time context, not derive it later from the callback's realm or
   * the invocation context. Internal source frames are implementation steps,
   * not a replacement for the assigning script's incumbent settings.
   */
  captureGlobalHandlerContext(): GlobalHandlerContext;

  /**
   * Invoke the actual IDL handler, not the source's internal listener wrapper.
   * Apply HTML's scripting-enabled and callback-realm fully-active checks; an
   * inactive handler returns { ok: true, value: undefined } without invocation.
   * Use Web IDL callback preparation, the callback's relevant settings and the
   * supplied assignment-time context as its stored settings,
   * and cleanup after running callback/script before returning its completion.
   * Cleanup includes a microtask checkpoint when HTML requires one. A thrown
   * callback value is returned as { ok: false, error }, never thrown by native
   * code. Source rethrows it and applies cancellation only to a normal result.
   */
  invokeGlobalHandler(
    callback: GlobalHandlerCallback, receiver: object, args: GlobalHandlerArguments,
    context: GlobalHandlerContext,
  ): GlobalHandlerInvocationResult;

  /**
   * Dispatch a trusted canonical Event at globalObject; return !canceled.
   * Route listeners by the event's internal type, not its public properties.
   * target/currentTarget and callback this must be the actual global. Enter its
   * realm for source listener wrappers. Ordinary script listeners use Web IDL
   * callback setup/cleanup; the internal handler wrappers call the separate
   * invokeGlobalHandler boundary before applying HTML's cancellation policy.
   * Cleaning up only after such a wrapper returns is too late. Apply the
   * platform's scripting-enabled and fully-active Document checks, when any.
   * Listener exceptions go to reportException and never escape dispatch.
   */
  dispatchGlobalEvent(event: Event, reportException: (exception: unknown) => void): boolean;

  /** Queue on this global's DOM manipulation task source, never inline. */
  enqueueGlobalTask(task: () => void): void;

  /** Read [[PromiseIsHandled]] and [[PromiseResult]], not public properties. */
  promiseIsHandled(promise: object): boolean;
  promiseResult(promise: object): unknown;

  /** Optional reporting chosen by the embedder; these must not throw. */
  reportExceptionToConsole(exception: unknown): void;
  reportRejectionToConsole(reason: unknown): void;

  /**
   * Optional dedicated-worker owner. A real worker provider supplies the parent
   * event/task boundary. Source policy below that boundary omits event.error.
   */
  readonly dedicatedWorkerOwner?: GlobalWorkerErrorOwner;
}

/** The worker owner crosses a realm boundary that source alone cannot enter. */
export interface GlobalWorkerErrorOwner extends GlobalExceptionReporter {
  enqueueGlobalTask(task: () => void): void;
  /**
   * Dispatch at the associated Worker object in its owner's realm; suppress
   * that worker's handlers when its connecting port is disentangled.
   */
  dispatchWorkerError(event: ErrorEvent, reportException: (exception: unknown) => void): boolean;
}

/** The environment-owned Navigator identity capability. */
export interface NavigatorCapability {
  /**
   * Return this environment's configured default User-Agent value as a string.
   * This operation is infallible; a native binding must never throw into source.
   * It must agree with the same environment default used by the Fetch provider.
   */
  userAgent(): string;
}

/** An environment origin measured in both clock domains by its provider. */
export interface PerformanceTimeOrigin {
  /** Epoch-relative milliseconds for the selected environment time origin. */
  readonly epochMilliseconds: number;
  /** The same instant in this runtime's monotonicMilliseconds() clock domain. */
  readonly monotonicMilliseconds: number;
}

/** Native serialization failures cross the binding as values, never throws. */
export type PerformanceDetailCloneResult =
  | { readonly ok: true; readonly value: unknown }
  | { readonly ok: false; readonly error: unknown };

export interface PerformanceDetailCloner {
  /** StructuredSerialize followed by StructuredDeserialize in this environment. */
  clone(value: object): PerformanceDetailCloneResult;
}

/**
 * Optional capabilities beyond PlatformPrimitives' relative monotonic clock.
 *
 * The provider must select the environment origin and supply both measurements
 * of that same instant. Sampling wallTimeMilliseconds() - monotonicMilliseconds()
 * is not an equivalent correlation. Clock coarsening and cross-context agreement
 * are the provider's responsibility. No epoch or origin is invented when absent.
 */
export interface PerformanceCapabilities {
  readonly timeOrigin?: PerformanceTimeOrigin;
  readonly detailCloner?: PerformanceDetailCloner;
}

import type { AbortSignal } from "../core/abort.ts";

/** A provider-owned cancellation token. Repeated cancellation is harmless. */
export interface CancelHandle {
  cancel(): void;
}

/** enqueue MUST enqueue a task, never invoke inline. Timer cancellation is idempotent. */
export interface Scheduler {
  enqueue(task: () => void): void;

  delay(milliseconds: number, task: () => void): CancelHandle;

  reportError(error: unknown): void;
}

export interface RandomSource {
  fill(bytes: Uint8Array): void;
}

export interface URLRecord {
  readonly href: string;
  readonly protocol: string;
  readonly hostname: string;
  readonly port: string;
  readonly host: string;
  readonly origin: string;
  readonly pathname: string;
  readonly search: string;
  readonly hash: string;
  readonly username: string;
  readonly password: string;
}

/** Bind the project's WHATWG URL implementation here, not java.net.URI. */
export interface URLParser {
  parse(input: string, base?: string): URLRecord;
}

export interface ConnectAddress {
  /** Logical authority used for pooling, HTTP Host, TLS SNI and certificate verification. */
  readonly hostname: string; // IPv6 has no surrounding brackets at this boundary.
  readonly port: number;
  readonly secure: boolean;
  readonly connectTimeoutMs: number;
  /** Ordered application protocols required of a TLS connection. */
  readonly alpnProtocols?: readonly string[];
  /** Optional physical endpoint selected by the shared resolver; never use it as TLS identity. */
  readonly resolvedAddress?: string;
  readonly resolvedFamily?: DnsAddressFamily;
}

export type DnsAddressFamily = 4 | 6;

export interface DnsAddress {
  readonly address: string;
  readonly family: DnsAddressFamily;
  /** Provider-reported positive-cache lifetime. Zero keeps the answer request-local. */
  readonly ttlMilliseconds: number;
}

export interface DnsResolveOptions {
  readonly families: readonly DnsAddressFamily[];
  /** Provider must not materialize more records than this shared-policy bound. */
  readonly maximumAddresses: number;
}

/** Provider-owned nonblocking DNS primitive. Shared code owns cache and selection policy. */
export interface DnsResolver {
  resolve(
    hostname: string,
    options: DnsResolveOptions,
    signal: AbortSignal,
  ): Promise<readonly DnsAddress[]>;
}

/**
 * One concurrent read and one concurrent write are allowed. No overlapping reads
 * or overlapping writes. read() transfers ownership of a nonempty chunk of at
 * most maxBytes bytes; null means EOF. write() borrows data until it settles and
 * returns 1..data.length. close() is idempotent and MUST interrupt pending I/O.
 */
export interface ByteConnection {
  readonly closed: boolean;

  read(maxBytes: number): Promise<Uint8Array | null>;

  write(data: Uint8Array): Promise<number>;

  close(): void;
}

export interface ListenAddress {
  readonly hostname: string;
  /** Zero asks the provider to choose one; {@link BoundAddress.port} reports which. */
  readonly port: number;
  /**
   * How many connections may be waiting for an {@link SocketListener.accept},
   * **wherever the waiting happens**.
   *
   * The wording is deliberate and was corrected by the Node lane, which has written the
   * adapter. `net.Server` is not pull-based: libuv accepts a connection and node emits
   * it before any consumer is consulted, so on that provider there are two queues -- the
   * kernel's and the adapter's -- and "the OS backlog is the only queue" would have been
   * a false sentence about a real implementation.
   *
   * So this bounds the total. A provider that cannot defer the OS accept may hold up to
   * `backlog` connections itself and closes them past that, as the kernel would have
   * dropped them. One number, one meaning, on every provider.
   */
  readonly backlog?: number;
}

export interface BoundAddress {
  /**
   * The literal address bound, never the name that was asked for.
   *
   * `listen({ hostname: "localhost" })` binds `::1` or `127.0.0.1` depending on
   * resolution order, and a caller that echoes back `"localhost"` and connects to it can
   * reach the other family and fail intermittently on a machine with both. Answering
   * with the literal is what makes this field worth having.
   */
  readonly hostname: string;
  readonly port: number;
}

/**
 * A bound socket that accepts inbound connections.
 *
 * Pull-shaped rather than push-shaped: the caller loops on {@link accept}, mirroring
 * {@link SocketConnector.connect}. A callback or stream would put the concurrency policy
 * in the provider, which cannot see how many sessions the server above is willing to
 * hold.
 */
export interface SocketListener {
  readonly address: BoundAddress;

  /**
   * The next inbound connection, or `null` once the listener is closed.
   *
   * `null` rather than an error, matching {@link ByteConnection.read} at end of stream:
   * a listener is a stream of connections and its end should spell the same way, so that
   * `while ((c = await accept(signal)) !== null)` is the correct loop rather than a
   * `try`/`catch` around every shutdown.
   *
   * An aborted `signal` **rejects**, and aborting one `accept` does not close the
   * listener -- abort is a caller changing its mind about one call, close is the
   * listener finishing. Collapsing them loses a distinction the rest of the platform
   * makes, and is the kind of thing implemented the other way round exactly once.
   */
  accept(signal: AbortSignal): Promise<ByteConnection | null>;

  close(): void;
}

/**
 * Binds listening sockets. Optional, and on policy grounds rather than capability.
 *
 * The Android provider measured this on a device: `bind` with port 0 works, reports the
 * port it got, and needs no permission beyond the `INTERNET` one a client already
 * declares. So a provider omitting it is choosing not to expose a server on a client
 * target, which is what the governing plan asks for by default -- not working around
 * something the platform cannot do.
 *
 * Three things a provider should surface rather than translate: binding below port 1024
 * needs root as on any Unix; a socket on `0.0.0.0` is reachable only while an interface
 * exists; and a mobile platform's background execution limits govern whether the
 * *process* survives, not whether the bind is legal, so that failure is the server being
 * killed and is the embedder's problem rather than this interface's.
 */
export interface SocketBinder {
  /**
   * Binds and begins listening.
   *
   * Rejects if the bind fails. A provider whose platform reports bind failure
   * asynchronously -- node emits `'error'` a tick after `listen()` returns -- must wire
   * that to this promise, or a taken port becomes an unhandled event rather than a
   * rejection.
   */
  listen(address: ListenAddress, signal: AbortSignal): Promise<SocketListener>;
}

export interface SocketConnector {
  connect(address: ConnectAddress, signal: AbortSignal): Promise<ByteConnection>;

  /**
   * Optional negotiation capability. Declared here rather than only on
   * {@link NegotiatingSocketConnector} so a provider author reading the interface
   * they implement can see that it exists, and so callers ask a declared question
   * instead of probing for a member the type does not mention.
   */
  readonly reportsNegotiatedProtocol?: boolean;

  connectNegotiated?(address: ConnectAddress, signal: AbortSignal): Promise<NegotiatedConnection>;
}

/**
 * A connected byte stream together with what TLS actually negotiated for it.
 *
 * The selection is reported on the connect result rather than as a field on
 * `ByteConnection`, so a raw byte stream carries no TLS concept it has no use for,
 * and the asymmetry stays visible: the caller offers a list and is told the one that
 * was chosen.
 */
export interface NegotiatedConnection {
  readonly connection: ByteConnection;
  /**
   * The application protocol TLS selected, or null when nothing was negotiated.
   *
   * Null is unambiguous only because of the contract on
   * {@link NegotiatingSocketConnector}: a connector that cannot report a selection
   * is never offered a choice, so null means cleartext or a single known answer and
   * never "negotiation happened and this provider cannot say what it chose".
   */
  readonly protocol: string | null;
  /**
   * dNSName subject-alternative names as presented by the peer certificate, empty
   * for cleartext. Reusing a connection for a second origin is sound only when the
   * certificate covers it, so a pool that coalesces on hostname alone is a
   * cross-origin routing defect; an empty list simply cannot coalesce.
   */
  readonly certificateNames: readonly string[];
  /**
   * The physical endpoint this connection actually reached, when the connector knows
   * it. Absent when nothing below chose an address.
   *
   * Reuse decisions need the endpoint a live connection *is on*, not the one a fresh
   * lookup would pick now, and only the layer that chose it can say which it was.
   */
  readonly endpoint?: string;
}

/**
 * A connector that reports what TLS negotiated.
 *
 * `reportsNegotiatedProtocol` is a capability declaration rather than documentation.
 * Shared policy may offer more than one protocol in `ConnectAddress.alpnProtocols`
 * only to a connector that declares `true`. A provider that cannot report the
 * selection declares `false` and is then offered exactly one protocol, so an absent
 * answer cannot be confused with an unreported one.
 *
 * This is not hypothetical caution. Android exposes
 * `SSLSocket.getApplicationProtocol` only from API 29 while this project targets API
 * 26; the method compiles against the API-26 stub and is absent on the device. A
 * provider there that offered `["h2", "http/1.1"]`, negotiated h2, and reported
 * nothing would have shared policy select HTTP/1.1 and speak it into an h2
 * connection.
 *
 * The declaration is therefore a property of this connector instance, answerable at
 * runtime, and never a build-time constant: one Android build runs on both API 26 and
 * API 29, so a provider decides per instance rather than needing two providers.
 */
export interface NegotiatingSocketConnector extends SocketConnector {
  readonly reportsNegotiatedProtocol: boolean;

  connectNegotiated(address: ConnectAddress, signal: AbortSignal): Promise<NegotiatedConnection>;
}

/** Ordered protocols to offer, and the single one to request when none can be reported. */
export interface ProtocolPreference {
  /** Offered in order to a connector that reports its selection. */
  readonly ordered: readonly string[];
  /**
   * Requested alone when the connector cannot report. Named explicitly rather than
   * taken from a position in `ordered`, because the safe single choice is the most
   * compatible protocol and not the most preferred one.
   */
  readonly whenUnreportable: string;
}

export function isNegotiatingSocketConnector(
  connector: SocketConnector,
): connector is NegotiatingSocketConnector {
  return (
    typeof connector.reportsNegotiatedProtocol === "boolean" &&
    connector.connectNegotiated !== undefined
  );
}

/**
 * The protocols shared policy is allowed to offer this connector.
 *
 * This is where the contract is enforced, so that a provider cannot be merely
 * careful about it and every caller gets the same rule.
 */
export function offeredProtocols(
  connector: SocketConnector,
  preference: ProtocolPreference,
): readonly string[] {
  if (preference.ordered.length === 0) throw new TypeError("A protocol preference cannot be empty");
  if (!preference.ordered.includes(preference.whenUnreportable)) {
    throw new TypeError("The unreportable protocol must be one of the offered protocols");
  }
  if (isNegotiatingSocketConnector(connector) && connector.reportsNegotiatedProtocol) {
    return preference.ordered;
  }
  return [preference.whenUnreportable];
}

/**
 * Connect through any connector and describe the result uniformly.
 *
 * A connector that does not report a selection yields `protocol: null` and no
 * certificate names, which is exactly what the contract above makes safe: it was
 * offered one protocol, so there is nothing it could have chosen instead.
 */
export async function connectNegotiated(
  connector: SocketConnector,
  address: ConnectAddress,
  signal: AbortSignal,
): Promise<NegotiatedConnection> {
  if (isNegotiatingSocketConnector(connector)) {
    return connector.connectNegotiated(address, signal);
  }
  const connection = await connector.connect(address, signal);
  return { connection, protocol: null, certificateNames: [] };
}

/**
 * A TLS upgrader that reports what it negotiated.
 *
 * Proxied TLS reaches the peer through {@link TlsUpgrader} rather than through a
 * connector, so the same declaration and the same contract have to exist here or
 * automatic protocol selection would silently stop working the moment a tunnel is
 * involved. `reportsNegotiatedProtocol` carries the identical meaning and the
 * identical per-instance requirement.
 */
export interface NegotiatingTlsUpgrader extends TlsUpgrader {
  readonly reportsNegotiatedProtocol: boolean;

  upgradeNegotiated(
    connection: ByteConnection,
    target: ConnectAddress,
    signal: AbortSignal,
  ): Promise<NegotiatedConnection>;
}

export function isNegotiatingTlsUpgrader(
  upgrader: TlsUpgrader,
): upgrader is NegotiatingTlsUpgrader {
  return (
    typeof upgrader.reportsNegotiatedProtocol === "boolean" &&
    upgrader.upgradeNegotiated !== undefined
  );
}

/** The protocols shared policy may offer this upgrader, under the same contract. */
export function offeredUpgradeProtocols(
  upgrader: TlsUpgrader,
  preference: ProtocolPreference,
): readonly string[] {
  if (preference.ordered.length === 0) throw new TypeError("A protocol preference cannot be empty");
  if (!preference.ordered.includes(preference.whenUnreportable)) {
    throw new TypeError("The unreportable protocol must be one of the offered protocols");
  }
  if (isNegotiatingTlsUpgrader(upgrader) && upgrader.reportsNegotiatedProtocol) {
    return preference.ordered;
  }
  return [preference.whenUnreportable];
}

/** Upgrade through any upgrader and describe the result uniformly. */
export async function upgradeNegotiated(
  upgrader: TlsUpgrader,
  connection: ByteConnection,
  target: ConnectAddress,
  signal: AbortSignal,
): Promise<NegotiatedConnection> {
  if (isNegotiatingTlsUpgrader(upgrader)) {
    return upgrader.upgradeNegotiated(connection, target, signal);
  }
  const upgraded = await upgrader.upgrade(connection, target, signal);
  return { connection: upgraded, protocol: null, certificateNames: [] };
}

/**
 * Provider-owned TLS over an already connected byte stream.
 *
 * The target carries the logical hostname used for SNI and certificate
 * verification. The upgrader consumes the input connection immediately and must
 * close it if the handshake fails; callers never reuse the plaintext handle.
 */
export interface TlsUpgrader {
  upgrade(
    connection: ByteConnection,
    target: ConnectAddress,
    signal: AbortSignal,
  ): Promise<ByteConnection>;

  /** Optional negotiation capability; see {@link NegotiatingTlsUpgrader}. */
  readonly reportsNegotiatedProtocol?: boolean;

  upgradeNegotiated?(
    connection: ByteConnection,
    target: ConnectAddress,
    signal: AbortSignal,
  ): Promise<NegotiatedConnection>;
}

export interface PlatformPrimitives {
  readonly sockets: SocketConnector;
  readonly random: RandomSource;
  readonly scheduler: Scheduler;
  readonly urls: URLParser;
  readonly nativeLineEnding: "\n" | "\r\n";

  wallTimeMilliseconds(): number;

  /**
   * The system's proxy answer for this URL, or null where the platform has no opinion.
   *
   * The classic proxy auto-configuration result grammar --
   * `"PROXY host:port; SOCKS5 host:port; DIRECT"` -- parsed by `parseProxyResult` above
   * this seam. A string rather than a structured type because that grammar is the shape
   * both platform APIs already produce, and because it keeps the parsing on the side
   * where it is tested.
   *
   * **Synchronous, and measured to be affordable.** `ProxySelector.getDefault().select`
   * on an API-26 device is 46-87us on the first call of a cold process and 2-11us after,
   * with no network, no file read and no PAC fetch behind it. A lookup that turned the
   * event loop would reorder everything downstream of it, so this was specified
   * synchronous first and confirmed second rather than the other way round.
   *
   * **A provider does not evaluate PAC, and must not.** A PAC file is a JavaScript
   * program, and every platform that supports one already runs it inside its own proxy
   * stack -- Android in a framework service that publishes an ordinary `host:port`,
   * Apple in `CFNetworkCopyProxiesForURL`. A second evaluation would answer differently
   * from every other application on the same device. What crosses this seam is the
   * resolved answer.
   *
   * **The result may or may not have the platform's own bypass rules applied.** On Android
   * API 26, measured from a real application, it does **not**: the framework propagates the
   * proxy host and port but not `global_http_proxy_exclusion_list`, so a loopback request
   * resolves to the proxy. A caller's own no-proxy list is applied above this seam in either
   * case, because nothing below can know it -- and on that version it is the only thing
   * applied at all.
   *
   * Returning null means "no opinion", which a caller treats as `DIRECT`. Android never
   * produces it -- an unconfigured selector answers `Proxy.NO_PROXY` for every URL, so
   * the null arm is unreachable there. It stays for platforms that have no proxy story
   * at all, so that an always-`DIRECT` provider is not mistaken for a broken one.
   */
  systemProxyFor(url: URLRecord): string | null;

  /**
   * Milliseconds since an origin fixed for the lifetime of this provider.
   *
   * Monotonically non-decreasing, sub-millisecond where the provider has it. Two values
   * from one provider are comparable; values from different providers are not. It
   * promises neither per-realm origins nor comparability across threads: the first is
   * the browser's shape, the second an accident of one host, and either written down
   * would make a correct provider look broken.
   *
   * Deliberately not "measures elapsed real time". Both providers measured use a clock
   * that stalls rather than reverses while a device sleeps -- `performance.now()` over
   * `uv_hrtime` on the host, `System.nanoTime()` with 36ns steps on an API-26 device --
   * so it is a stopwatch for intervals within a wakeful period, not a duration across
   * one.
   *
   * Separate from {@link wallTimeMilliseconds} because a cache's "now" must be in the
   * same frame as the `Date` headers it compares against. Two clocks; the mistake
   * available is letting this one satisfy something that wanted the other.
   */
  monotonicMilliseconds(): number;
}

import type { URLRecord } from "./primitives.ts";
import type { WebPlatformRuntime } from "./web-platform-runtime.ts";

export type URLPatternCanonicalComponent =
  | "username" | "password" | "hostname" | "port"
  | "pathname" | "opaquePathname" | "search" | "hash";

/** A native URL primitive returns failure as a value, never by throwing. */
export type URLPatternCanonicalResult =
  | { readonly ok: true; readonly value: string }
  | { readonly ok: false; readonly error: "invalid-input" | "unsupported" };

/**
 * URL Pattern §3.1's URL state overrides and setters. The existing URLParser
 * still owns parsing complete URLs. These operations do not parse patterns.
 * https://urlpattern.spec.whatwg.org/#canonicalization
 */
export interface URLPatternURLCapability {
  canonicalize(
    component: URLPatternCanonicalComponent,
    value: string,
    protocol?: string,
  ): URLPatternCanonicalResult;

  /** Read URL's opaque-path flag, including a non-special authority's empty path. */
  hasOpaquePath(url: URLRecord): boolean;
}

const capabilities = new WeakMap<WebPlatformRuntime, URLPatternURLCapability>();

/** Provider bootstrap installs the environment-owned URL primitives explicitly. */
export function installURLPatternURLCapability(
  runtime: WebPlatformRuntime,
  capability: URLPatternURLCapability,
): void {
  capabilities.set(runtime, capability);
}

/** A capability refusal is distinct from an invalid URL or an unsuccessful match. */
export class URLPatternCapabilityError extends Error {
  constructor() {
    super("URLPattern requires the provider's URL component canonicalization capability");
    this.name = "URLPatternCapabilityError";
  }
}

export function getURLPatternURLCapability(runtime: WebPlatformRuntime): URLPatternURLCapability {
  const capability = capabilities.get(runtime);
  if (capability === undefined) throw new URLPatternCapabilityError();
  return capability;
}

import type { CancelHandle, Scheduler } from "./primitives.ts";

interface VirtualTimer {
  readonly deadline: number;
  /** Insertion order, so equal deadlines have one defined outcome rather than a race. */
  readonly sequence: number;
  readonly task: () => void;
  cancelled: boolean;
}

export interface VirtualSchedulerOptions {
  /** Logical milliseconds at construction. */
  readonly startMilliseconds?: number;
  /**
   * Where task exceptions go. The default collects them in {@link VirtualScheduler.errors}
   * rather than throwing, so one failing task does not abandon a run mid-way and hide
   * every later assertion behind it.
   */
  readonly reportError?: (error: unknown) => void;
}

/**
 * A `Scheduler` whose clock only moves when it is told to.
 *
 * The integration contract requires deterministic oracle tests to use virtual time and
 * requires that network activity never silently advances it. Both follow from the same
 * property: nothing here observes a real clock, so time passes only through
 * {@link VirtualScheduler.advance}. A test that expects a timeout must say so.
 *
 * This is a provider, not a test helper, and it is portable: it has no host
 * dependency, so every target can run the same deterministic corpus.
 */
export class VirtualScheduler implements Scheduler {
  #now: number;
  #sequence = 0;
  #timers: VirtualTimer[] = [];
  #queue: (() => void)[] = [];
  #draining = false;
  readonly #report: ((error: unknown) => void) | undefined;
  /** Exceptions from tasks, in the order they were reported. */
  readonly errors: unknown[] = [];

  constructor(options: VirtualSchedulerOptions = {}) {
    const start = options.startMilliseconds ?? 0;
    if (!Number.isFinite(start) || start < 0) {
      throw new RangeError("Virtual time must start at a non-negative finite value");
    }
    this.#now = start;
    this.#report = options.reportError;
  }

  /** The current logical time. */
  get now(): number {
    return this.#now;
  }

  /** Whether anything is waiting: a queued task or an uncancelled timer. */
  get hasPending(): boolean {
    if (this.#queue.length !== 0) return true;
    for (const timer of this.#timers) if (!timer.cancelled) return true;
    return false;
  }

  /** The logical time of the earliest uncancelled timer, or null. */
  get nextDeadline(): number | null {
    let earliest: number | null = null;
    for (const timer of this.#timers) {
      if (timer.cancelled) continue;
      if (earliest === null || timer.deadline < earliest) earliest = timer.deadline;
    }
    return earliest;
  }

  enqueue(task: () => void): void {
    this.#queue.push(task);
  }

  delay(milliseconds: number, task: () => void): CancelHandle {
    if (!Number.isFinite(milliseconds) || milliseconds < 0) {
      throw new RangeError("A delay must be a non-negative finite number of milliseconds");
    }
    const timer: VirtualTimer = {
      deadline: this.#now + milliseconds,
      sequence: this.#sequence++,
      task,
      cancelled: false,
    };
    this.#timers.push(timer);
    return {
      cancel: (): void => {
        // Cancelling is idempotent and takes effect even mid-advance, because a task
        // that runs may cancel a timer this advance has not reached yet.
        timer.cancelled = true;
      },
    };
  }

  reportError(error: unknown): void {
    if (this.#report !== undefined) {
      this.#report(error);
      return;
    }
    this.errors.push(error);
  }

  /** Runs queued tasks and any timer already due, without moving the clock. */
  runPending(): void {
    this.#runDue(this.#now);
  }

  /**
   * Moves the clock forward, running everything that becomes due on the way.
   *
   * The clock stops at each deadline rather than jumping to the end, so a task
   * scheduling another timer sees the time its own deadline implies and a timer it
   * schedules inside the remaining window still runs in this advance. Jumping would
   * make the result depend on how the caller chose to divide the interval.
   */
  advance(milliseconds: number): void {
    if (!Number.isFinite(milliseconds) || milliseconds < 0) {
      throw new RangeError("Advancing requires a non-negative finite number of milliseconds");
    }
    const target = this.#now + milliseconds;
    this.#runDue(target);
    this.#now = target;
    this.#runDue(target);
  }

  /**
   * Advances to the next deadline, or does nothing when none is pending.
   *
   * Returns whether it moved, so a caller can drive a scheduler to quiescence without
   * guessing an interval.
   */
  advanceToNextDeadline(): boolean {
    const next = this.nextDeadline;
    if (next === null) return false;
    this.advance(Math.max(0, next - this.#now));
    return true;
  }

  #runDue(limit: number): void {
    // A task may enqueue or schedule more work; re-entering would run it out of order,
    // so the outermost call owns the loop.
    if (this.#draining) return;
    this.#draining = true;
    try {
      while (true) {
        if (this.#queue.length !== 0) {
          const queued = this.#queue;
          this.#queue = [];
          for (const task of queued) this.#run(task);
          continue;
        }
        const due = this.#takeEarliestDue(limit);
        if (due === null) return;
        this.#now = due.deadline;
        this.#run(due.task);
      }
    } finally {
      this.#draining = false;
    }
  }

  #takeEarliestDue(limit: number): VirtualTimer | null {
    let chosen: VirtualTimer | null = null;
    let chosenIndex = -1;
    for (let index = 0; index < this.#timers.length; index++) {
      const timer = this.#timers[index];
      if (timer === undefined || timer.cancelled || timer.deadline > limit) continue;
      if (
        chosen === null ||
        timer.deadline < chosen.deadline ||
        (timer.deadline === chosen.deadline && timer.sequence < chosen.sequence)
      ) {
        chosen = timer;
        chosenIndex = index;
      }
    }
    if (chosen === null) {
      this.#compact();
      return null;
    }
    this.#timers.splice(chosenIndex, 1);
    return chosen;
  }

  #compact(): void {
    let write = 0;
    for (let read = 0; read < this.#timers.length; read++) {
      const timer = this.#timers[read];
      if (timer !== undefined && !timer.cancelled) this.#timers[write++] = timer;
    }
    this.#timers.length = write;
  }

  #run(task: () => void): void {
    try {
      task();
    } catch (error) {
      this.reportError(error);
    }
  }
}

import type { BodyPolicy } from "../fetch/body.ts";
import {
  CacheStorage,
  MemoryCacheStorageStore,
  createCacheStorage,
