import { readContentCodingPolicy, type ContentCodingPolicy } from "../fetch/content-coding.ts";
import { EventSource, readEventSourcePolicy } from "../eventsource/event-source.ts";
import type {
  EventSourceContext,
  EventSourceOptions,
  EventSourcePolicy,
} from "../eventsource/event-source.ts";
import { Blob } from "../file/blob.ts";
import { BlobURLStore } from "../file/object-url.ts";
import { createCrypto } from "../crypto/crypto.ts";
import type { Crypto } from "../crypto/crypto.ts";
import type { CryptoProvider } from "./crypto.ts";
import type { CompressionProvider } from "./compression.ts";
import { Http1Transport } from "../http1/transport.ts";
import type { Http1Options } from "../http1/transport.ts";
import { RawWebSocketTransport } from "../websocket/raw-transport.ts";
import type { RawWebSocketOptions } from "../websocket/raw-transport.ts";
import type { WebSocketDeflateProvider, WebSocketTransport } from "../websocket/transport.ts";
import {
  createInternalWebSocket,
  WebSocket,
  type WebSocketContext,
} from "../websocket/websocket.ts";
import {
  createInternalWebSocketStream,
  WebSocketStream,
  type WebSocketStreamContext,
  type WebSocketStreamOptions,
} from "../websocket/websocket-stream.ts";
import type {
  PlatformPrimitives,
  TlsUpgrader,
  URLRecord,
} from "./primitives.ts";
import { webSocketCloseForRuntime } from "../websocket/websocket.ts";

export interface WebPlatformProxyOptions extends EnvironmentProxyOptions {
  /** TLS over an existing stream is required for CONNECT and SOCKS target security. */
  readonly tls: TlsUpgrader;
  /** Host-supplied environment view. Shared code never reads process.env. */
  readonly environment?: ProxyEnvironment;
  readonly headers?: readonly HeaderEntry[];
  readonly authorization?: string;
  readonly authenticate?: ProxyAuthenticator;
  readonly maximumAuthenticationAttempts?: number;
  readonly proxyTunnel?: boolean;
}

export interface WebPlatformOptions {
  baseURL?: string;
  origin?: string;
  bodyPolicy?: Partial<BodyPolicy>;
  /**
   * Capability-scoped `file:` access. Absent by default, in which case a `file:` URL
   * fails exactly like any other unsupported scheme.
   */
  fileURLs?: FileURLProvider;
  /** Digest primitive for subresource integrity. Without it, integrity requests fail. */
  digest?: DigestProvider;
  /** Native Web Crypto capability. Bootstrap owns global and secure-context exposure. */
  crypto?: CryptoProvider;
  /** Native streaming compression capability. Bootstrap owns global exposure. */
  compression?: CompressionProvider;
  http1?: Http1Options;
  /** Environment/explicit proxy policy shared by Fetch, EventSource and WebSocket. */
  proxy?: WebPlatformProxyOptions;
  websocket?: RawWebSocketOptions;
  maxRedirects?: number;
  maxWebSocketBufferedAmount?: number;
  fetchTransport?: FetchTransport;
  /** Typed diagnostics are scoped to this Web-platform runtime/environment. */
  diagnostics?: DispatchDiagnosticObserver;
  diagnosticsPolicy?: DispatchDiagnosticsPolicy;
  webSocketTransport?: WebSocketTransport;
  /** Raw DEFLATE contexts. RFC 7692 negotiation and framing remain shared. */
  webSocketDeflate?: WebSocketDeflateProvider | null;
  contentDecoder?: ContentDecoder;
  /** Configurable server/mobile defense against decompression bombs. */
  contentCodingPolicy?: Partial<ContentCodingPolicy>;
  eventSource?: EventSourceOptions;
  /** Injected policy is not owned or closed by this runtime. */
  cookies?: FetchCookiePolicy;
  /** Injected policy/store is not owned or closed by this runtime. */
  httpCache?: HttpCache;
  /**
   * Public Cache API storage for this runtime's storage key. Production providers
   * inject durable quota-managed storage; the reference default is volatile.
   */
  cacheStorageStore?: CacheStorageStore;
  /** Provider-specific serialization, e.g. Node's `blob:nodedata:` prefix. */
  blobURLPrefix?: string;
}

/**
 * Environment-owned Web networking state.
 *
 * The public Web constructors remain top-level canonical classes. This object owns
 * transports, pools, policy, and open sessions; it is not a constructor-producing
 * JavaScript realm. Provider bootstrap associates one runtime with an
 * `NtsEnvironment` and installs the canonical values for that environment.
 */
export class WebPlatformRuntime
  implements EventSourceContext, WebSocketContext, WebSocketStreamContext
{
  readonly http1: Http1Transport;
  readonly requestContext: RequestContext;
  readonly fetch: (input: string | Request, init?: RequestInit) => Promise<Response>;
  readonly nativeLineEnding: "\n" | "\r\n";
  readonly scheduler: PlatformPrimitives["scheduler"];
  readonly urls: PlatformPrimitives["urls"];
  readonly baseURL: string | undefined;
  readonly origin: string | undefined;
  readonly maxBufferedAmount: number | undefined;
  readonly eventSourcePolicy: EventSourcePolicy;
  readonly caches: CacheStorage;
  /** One environment-owned facade, absent when no native capability was supplied. */
  readonly crypto: Crypto | undefined;
  /** Captured capability; each Compression Stream creates and owns its context. */
  readonly compression: CompressionProvider | undefined;
  readonly transport: WebSocketTransport;

  private readonly ownedWebSocketTransport: RawWebSocketTransport | null;
  private readonly ownedFetchProxy: EnvHttpProxyAgent | null;
  private readonly primitives: PlatformPrimitives;
  private readonly blobURLs: BlobURLStore;
  private readonly eventSources: EventSource[] = [];
  private readonly webSockets: WebSocket[] = [];
  private readonly webSocketStreams: WebSocketStream[] = [];
  private closed = false;

  constructor(primitives: PlatformPrimitives, options: WebPlatformOptions = {}) {
    if (options.fetchTransport !== undefined && options.proxy !== undefined) {
      throw new TypeError("fetchTransport and proxy cannot both select the Fetch transport");
    }
    const bodyPolicy = readBodyPolicy(options.bodyPolicy);
    const contentCodingPolicy = readContentCodingPolicy(options.contentCodingPolicy);
    const maxRedirects = options.maxRedirects ?? 20;
    if (!Number.isSafeInteger(maxRedirects) || maxRedirects < 0) {
      throw new RangeError("Invalid redirect limit");
    }

    this.primitives = primitives;
    this.nativeLineEnding = primitives.nativeLineEnding;
    this.scheduler = primitives.scheduler;
    const cryptoProvider = options.crypto;
    this.crypto = cryptoProvider === undefined ? undefined : createCrypto(primitives.random, cryptoProvider, this.scheduler);
    this.compression = options.compression;
    this.urls = primitives.urls;
    this.baseURL = options.baseURL;
    this.origin = options.origin;
    this.maxBufferedAmount = options.maxWebSocketBufferedAmount;
    this.eventSourcePolicy = readEventSourcePolicy(options.eventSource);
    this.blobURLs = new BlobURLStore(primitives.random, options.origin, options.blobURLPrefix);
    this.requestContext = {
      urls: primitives.urls,
      random: primitives.random,
      bodyPolicy,
      baseURL: options.baseURL,
      origin: options.origin,
      blobURLs: this.blobURLs,
      fileURLs: options.fileURLs,
      digest: options.digest,
    };
    this.http1 = new Http1Transport(primitives.sockets, primitives.scheduler, options.http1);

    const proxyConnector =
      options.proxy === undefined
        ? primitives.sockets
        : new EnvironmentProxyConnector({
            ...options.proxy,
            connector: primitives.sockets,
            scheduler: primitives.scheduler,
            urls: primitives.urls,
          });

    if (options.webSocketTransport === undefined) {
      const transport = new RawWebSocketTransport(
        proxyConnector,
        primitives.random,
        primitives.scheduler,
        options.websocket,
        options.webSocketDeflate ?? undefined,
      );
      this.transport = transport;
      this.ownedWebSocketTransport = transport;
    } else {
      this.transport = options.webSocketTransport;
      this.ownedWebSocketTransport = null;
    }

    this.ownedFetchProxy =
      options.proxy === undefined
        ? null
        : new EnvHttpProxyAgent(
            {
              ...options.http1,
              ...options.proxy,
              connector: primitives.sockets,
              scheduler: primitives.scheduler,
              urls: primitives.urls,
            },
            this.http1,
          );
    let fetchTransport = options.fetchTransport ?? this.ownedFetchProxy ?? this.http1;
    if (options.diagnostics !== undefined) {
      fetchTransport = composeFetchTransport(fetchTransport, [
        new DiagnosticsInterceptor({
          ...options.diagnosticsPolicy,
          observer: options.diagnostics,
          scheduler: primitives.scheduler,
        }),
      ]);
    }

    const client = new FetchClient(
      fetchTransport,
      this.requestContext,
      options.contentDecoder,
      maxRedirects,
      options.cookies,
      options.httpCache,
      contentCodingPolicy,
    );
    this.fetch = client.fetch;
    this.caches = createCacheStorage(
      options.cacheStorageStore ?? new MemoryCacheStorageStore(),
      this.requestContext,
      this.fetch,
    );
  }

  wallTimeMilliseconds(): number {
    return this.primitives.wallTimeMilliseconds();
  }

  monotonicMilliseconds(): number {
    return this.primitives.monotonicMilliseconds();
  }

  systemProxyFor(url: URLRecord): string | null {
    return this.primitives.systemProxyFor(url);
  }

  createObjectURL(blob: Blob): string {
    if (this.closed) throw new TypeError("Web-platform runtime is closed");
    return this.blobURLs.create(blob);
  }

  revokeObjectURL(value: string): void {
    try {
      this.blobURLs.revoke(this.primitives.urls.parse(value));
    } catch {
      return;
    }
  }

  createWebSocket(url: string, protocols: string | readonly string[] = []): WebSocket {
    if (this.closed) throw new TypeError("Web-platform runtime is closed");
    return createInternalWebSocket(url, protocols, this);
  }

  createWebSocketStream(url: string, options: WebSocketStreamOptions | null = {}): WebSocketStream {
    if (this.closed) throw new TypeError("Web-platform runtime is closed");
    return createInternalWebSocketStream(url, options, this);
  }

  registerWebSocket(socket: WebSocket): void {
    if (this.closed) throw new TypeError("Web-platform runtime is closed");
    this.webSockets.push(socket);
  }

  unregisterWebSocket(socket: WebSocket): void {
    const index = this.webSockets.indexOf(socket);
    if (index < 0) return;
    this.webSockets.splice(index, 1);
  }

  registerWebSocketStream(stream: WebSocketStream): void {
    if (this.closed) throw new TypeError("Web-platform runtime is closed");
    this.webSocketStreams.push(stream);
  }

  unregisterWebSocketStream(stream: WebSocketStream): void {
    const index = this.webSocketStreams.indexOf(stream);
    if (index < 0) return;
    this.webSocketStreams.splice(index, 1);
  }

  registerEventSource(source: EventSource): void {
    if (this.closed) throw new TypeError("Web-platform runtime is closed");
    this.eventSources.push(source);
  }

  unregisterEventSource(source: EventSource): void {
    const index = this.eventSources.indexOf(source);
    if (index < 0) return;
    this.eventSources.splice(index, 1);
  }

  close(): void {
    if (this.closed) return;
    this.closed = true;
    const eventSources = this.eventSources.slice();
    for (const source of eventSources) source.close();
    const webSockets = this.webSockets.slice();
    for (const socket of webSockets) socket[webSocketCloseForRuntime]();
    const webSocketStreams = this.webSocketStreams.slice();
    for (const stream of webSocketStreams) stream[webSocketCloseForRuntime]();
    this.blobURLs.close();
    this.ownedFetchProxy?.destroy();
    this.http1.close();
    if (this.ownedWebSocketTransport !== null) {
      this.ownedWebSocketTransport.close();
    }
  }
}

function readBodyPolicy(input: Partial<BodyPolicy> | undefined): BodyPolicy {
  const policy: BodyPolicy = {
    maxConsumeBytes: input?.maxConsumeBytes ?? Infinity,
    maxCloneBufferBytes: input?.maxCloneBufferBytes ?? Infinity,
  };

  validateByteLimit(policy.maxConsumeBytes);
  validateByteLimit(policy.maxCloneBufferBytes);
  return policy;
}

function validateByteLimit(limit: number): void {
  if (Number.isNaN(limit) || limit < 0 || (limit !== Infinity && !Number.isSafeInteger(limit))) {
    throw new RangeError("Invalid body byte limit");
  }
}

import type { AbortSignal } from "../core/abort.ts";
import type { BlobExternalSource } from "../file/blob.ts";

/** Metadata for one stored value. */
export interface DurableRecord {
  readonly key: string;
  readonly size: number;
  /** Provider wall-clock time of the last commit, in milliseconds. */
  readonly modifiedMilliseconds: number;
}

/**
 * A write in progress. Nothing appended is visible until {@link DurableWrite.commit}.
 *
 * Streaming exists on the write side and not the read side, which is asymmetric on
 * purpose. "Spill to disk so large payloads are not forced into RAM" cannot be served
 * by a whole-value write, because the bytes parameter *is* the payload in RAM -- the
 * whole-value form contradicts the requirement it exists for. Reading back does not
 * have that problem: {@link DurableByteStore.source} already returns a ranged
 * `BlobExternalSource`, and a second ranged-read seam in the store would be a second
 * answer to one question.
 */
export interface DurableWrite {
  /**
   * Appends bytes. Cancellation is checked here rather than interrupting a write in
   * progress; see {@link DurableByteStore.write}.
   */
  append(bytes: Uint8Array): Promise<void>;

  /**
   * Makes everything appended visible under the key, atomically and durably.
   *
   * Durably means both the bytes and the act of replacing survive a crash. Those are
   * two separate things on a filesystem -- syncing the data leaves a committed value
   * losable if the directory entry is not also synced -- and a provider that does only
   * the first is approximating durability rather than providing it.
   */
  commit(): Promise<void>;

  /** Abandons the write. Idempotent, and a no-op once committed. */
  discard(): Promise<void>;
}

/**
 * Narrow provider-owned durable byte store.
 *
 * Deliberately small. RFC 9111 freshness, `Vary`, invalidation, eviction, quota policy
 * and CacheStorage matching are shared TypeScript above this; nothing here is a
 * "storage primitive" for those. What a provider owns is bytes, atomicity, durability
 * and enumeration.
 *
 * **What a key holds after a crash mid-write is part of this contract, not a provider
 * detail:** the old value or the new one, never a mix and never absent. On a filesystem
 * that falls out of temp-file-plus-rename; a database-backed provider owes the same
 * guarantee through its own transaction. Stating it here is what lets a caller reason
 * about recovery without knowing which provider it has.
 *
 * Commit is a handle operation rather than an ABI verb pair. Separate
 * `begin`/`rollback` would force a filesystem provider to model a transaction it does
 * not have, and would let a caller open one and never close it.
 */
export interface DurableByteStore {
  /** The whole value, or null when the key is absent. */
  read(namespace: string, key: string, signal: AbortSignal): Promise<Uint8Array | null>;

  /**
   * A reopenable ranged view of the value, or null when the key is absent.
   *
   * This is the large-value read path, and it is the seam Blob already consumes, so a
   * spilled body is read back through the same code as any other external Blob.
   *
   * **A reader that has been opened keeps reading what it was opened over, even after
   * the key is replaced or deleted.** The replacement half of that was already required
   * -- a Blob composes and slices immutable ranges, and a reader that saw a replacement
   * mid-read would break it. Deletion is the same guarantee and it is what makes a
   * lifetime possible above this seam: without it nothing can release stored bytes
   * while anything might still be reading them, and every caller ends up either leaking
   * or guessing. Both current providers already behave this way; it is written down
   * here because it is now depended upon rather than merely true.
   */
  source(namespace: string, key: string, signal: AbortSignal): Promise<BlobExternalSource | null>;

  /**
   * Begins replacing a key.
   *
   * **Cancellation is cooperative and checked between chunks.** A blocking write cannot
   * be interrupted mid-syscall on every platform, and closing the descriptor underneath
   * one produces a torn file rather than a stopped write. So the guarantee this makes
   * is *no partial value becomes visible* -- not that the write stops immediately. A
   * provider that promised promptness would have to lie about it.
   *
   * **A second concurrent write to a key that already has one is refused, not queued.**
   * This ABI is sequential per key, and honouring that by waiting would turn a caller's
   * mistake into a pause -- with the pause as the only evidence it made one. Refusing
   * names it. A caller that genuinely wants the later value serializes above this seam,
   * where it can also decide which value should win; the store cannot know that.
   */
  write(namespace: string, key: string, signal: AbortSignal): Promise<DurableWrite>;

  /** Removes a key. Absent is not an error; the result says whether anything went. */
  delete(namespace: string, key: string, signal: AbortSignal): Promise<boolean>;

  /**
   * Every committed record in a namespace. Uncommitted writes are not records.
   *
   * One observation, not a key list plus a lookup per key. Two calls cannot be made
   * atomic, so a key created or removed between them makes the metadata disagree with
   * the names, and the caller has no way to tell which half is stale.
   */
  list(namespace: string, signal: AbortSignal): Promise<readonly DurableRecord[]>;

  /** Total committed bytes retained in a namespace. */
  size(namespace: string, signal: AbortSignal): Promise<number>;

  close(): Promise<void>;
}

import type { AbortSignal } from "../core/abort.ts";
import { TextDecoder } from "../core/encoding.ts";
import type { BlobExternalReader, BlobExternalSource } from "../file/blob.ts";
import type { DurableByteStore, DurableRecord, DurableWrite } from "./durable.ts";

/**
 * The flat surface a provider exposes for a byte store.
 *
 * Synchronous scalars, strings and byte views, because that is what a foreign-function
 * boundary can carry. Everything the {@link DurableByteStore} contract adds on top of
 * it -- promises, an `AbortSignal` checked between chunks, a write as an object with a
 * lifetime -- is shared and lives in {@link durableStoreFromFlat}, so it is implemented
 * once rather than once per provider. A provider that reimplemented it would be
 * reimplementing the parts most likely to differ subtly between platforms.
 *
 * Buffers are caller-owned throughout, matching the rest of the intrinsic surface:
 * the caller allocates and the provider fills.
 */
export interface FlatDurableStore {
  /** A write handle, or -1 when the key already has a live write. */
  open(namespace: string, key: string): number;

  append(handle: number, from: Uint8Array): void;

  commit(handle: number): void;

  discard(handle: number): void;

  /** The value's full size, or -1 when absent. Writes `min(size, into.length)`. */
  read(namespace: string, key: string, into: Uint8Array): number;

  remove(namespace: string, key: string): boolean;

  /** Total bytes the records need. Writes `min(needed, into.length)`. */
  list(namespace: string, into: Uint8Array): number;

  size(namespace: string): number;

  /** A source handle, or -1 when absent. */
  sourceOpen(namespace: string, key: string, start: number, length: number): number;

  /** Bytes read, or -1 at the end. Never zero, so an empty chunk cannot occur. */
  sourceRead(handle: number, into: Uint8Array): number;

  sourceClose(handle: number): void;

  /** The value's size, or -1 when absent. */
  sourceSize(namespace: string, key: string): number;

  close(): void;
}

const INITIAL_BUFFER_BYTES = 4096;
const READ_CHUNK_BYTES = 64 * 1024;

/**
 * Fills a caller-owned buffer, growing once if the first guess was short.
 *
 * Both fill-buffer calls answer what there was and write what fits, so one retry is
 * always enough: the second buffer is the size the provider just reported. Guessing
 * again would be a loop with no bound.
 */
function fill(
  request: (into: Uint8Array) => number,
): { readonly bytes: Uint8Array<ArrayBuffer>; readonly length: number } | null {
  let buffer = new Uint8Array(new ArrayBuffer(INITIAL_BUFFER_BYTES));
  let needed = request(buffer);
  if (needed < 0) return null;
  if (needed > buffer.length) {
    buffer = new Uint8Array(new ArrayBuffer(needed));
    needed = request(buffer);
    if (needed < 0) return null;
  }
  return { bytes: buffer, length: needed };
}

/** Decimal digits terminated by NUL, as the record encoding writes them. */
function readNumber(bytes: Uint8Array, from: number): { value: number; next: number } {
  let value = 0;
  let index = from;
  while (index < bytes.length && bytes[index] !== 0) {
    const digit = (bytes[index] ?? 0) - 0x30;
    if (digit < 0 || digit > 9) throw new TypeError("Malformed durable record");
    value = value * 10 + digit;
    index++;
  }
  if (index >= bytes.length) throw new TypeError("Truncated durable record");
  return { value, next: index + 1 };
}

/**
 * Parses `size NUL modified NUL keyByteLength NUL key`, repeated.
 *
 * The explicit key length is what makes concatenation unambiguous: a key may contain
 * any byte, including the separator, so scanning for the next NUL after the key would
 * split a legal key in two.
 */
function parseRecords(bytes: Uint8Array, length: number): readonly DurableRecord[] {
  const decoder = new TextDecoder();
  const records: DurableRecord[] = [];
  let index = 0;
  while (index < length) {
    const size = readNumber(bytes, index);
    const modified = readNumber(bytes, size.next);
    const keyLength = readNumber(bytes, modified.next);
    const end = keyLength.next + keyLength.value;
    if (end > length) throw new TypeError("Truncated durable record key");
    records.push({
      key: decoder.decode(bytes.subarray(keyLength.next, end)),
      size: size.value,
      modifiedMilliseconds: modified.value,
    });
    index = end;
  }
  return records;
}

class FlatDurableWrite implements DurableWrite {
  readonly #flat: FlatDurableStore;
  readonly #handle: number;
  readonly #signal: AbortSignal;
  #settled = false;

  constructor(flat: FlatDurableStore, handle: number, signal: AbortSignal) {
    this.#flat = flat;
    this.#handle = handle;
    this.#signal = signal;
  }

  append(bytes: Uint8Array): Promise<void> {
    if (this.#settled) {
      return Promise.reject(new TypeError("This durable write has already settled"));
    }
    // Between chunks, which is where the contract says cancellation is honoured.
    if (this.#signal.aborted) return Promise.reject(this.#signal.reason);
    try {
      this.#flat.append(this.#handle, bytes);
    } catch (error) {
      return Promise.reject(error);
    }
    return Promise.resolve();
  }

  commit(): Promise<void> {
    if (this.#settled) return Promise.resolve();
    if (this.#signal.aborted) return Promise.reject(this.#signal.reason);
    this.#settled = true;
    try {
      this.#flat.commit(this.#handle);
    } catch (error) {
      return Promise.reject(error);
    }
    return Promise.resolve();
  }

  discard(): Promise<void> {
    if (this.#settled) return Promise.resolve();
    this.#settled = true;
    // Deliberately not signal-checked: discarding is the cleanup path and has to work
    // when the signal is already aborted, which is exactly when it is most needed.
    try {
      this.#flat.discard(this.#handle);
    } catch (error) {
      return Promise.reject(error);
    }
    return Promise.resolve();
  }
}

/**
 * Gives a provider's flat byte store the {@link DurableByteStore} shape.
 *
 * Portable on purpose: the flat surface is the same wherever a provider offers bytes,
 * so the promise, cancellation and handle-lifetime semantics are written once here and
 * a provider supplies twelve synchronous functions.
 */
export function durableStoreFromFlat(flat: FlatDurableStore): DurableByteStore {
  return {
    read(namespace: string, key: string, signal: AbortSignal): Promise<Uint8Array | null> {
      try {
        signal.throwIfAborted();
        const result = fill((into) => flat.read(namespace, key, into));
        if (result === null) return Promise.resolve(null);
        return Promise.resolve(result.bytes.subarray(0, result.length));
      } catch (error) {
        return Promise.reject(error);
      }
    },

    source(
      namespace: string,
      key: string,
      signal: AbortSignal,
    ): Promise<BlobExternalSource | null> {
      try {
        signal.throwIfAborted();
        const size = flat.sourceSize(namespace, key);
        if (size < 0) return Promise.resolve(null);
        return Promise.resolve({
          size,
          open(start: number, length: number): BlobExternalReader {
            const handle = flat.sourceOpen(namespace, key, start, length);
            let closed = handle < 0;
            return {
              read(maximumBytes: number): Promise<Uint8Array<ArrayBuffer> | undefined> {
                if (closed) {
                  return Promise.reject(new TypeError("The stored value is no longer readable"));
                }
                // Allocated per read. `BlobExternalReader` transfers ownership of each
                // chunk, so a consumer may keep two of them; a reused buffer would make
                // the older one change underneath it, and nothing would say so until a
                // consumer happened to keep both.
                const into = new Uint8Array(
                  new ArrayBuffer(Math.min(maximumBytes, READ_CHUNK_BYTES)),
                );
                let count: number;
                try {
                  count = flat.sourceRead(handle, into);
                } catch (error) {
                  return Promise.reject(error);
                }
                if (count < 0) return Promise.resolve(undefined);
                return Promise.resolve(into.subarray(0, count) as Uint8Array<ArrayBuffer>);
              },
              close(): Promise<void> {
                if (closed) return Promise.resolve();
                closed = true;
                try {
                  flat.sourceClose(handle);
                } catch (error) {
                  return Promise.reject(error);
                }
                return Promise.resolve();
              },
            };
          },
        });
      } catch (error) {
        return Promise.reject(error);
      }
    },

    write(namespace: string, key: string, signal: AbortSignal): Promise<DurableWrite> {
      try {
        signal.throwIfAborted();
        const handle = flat.open(namespace, key);
        if (handle < 0) {
          // Refused rather than queued, as the contract says; the provider reports it
          // because that is where the state lives.
          return Promise.reject(new TypeError("A write to this key is already open"));
        }
        return Promise.resolve(new FlatDurableWrite(flat, handle, signal));
      } catch (error) {
        return Promise.reject(error);
      }
    },

    delete(namespace: string, key: string, signal: AbortSignal): Promise<boolean> {
      try {
        signal.throwIfAborted();
        return Promise.resolve(flat.remove(namespace, key));
      } catch (error) {
        return Promise.reject(error);
      }
    },

    list(namespace: string, signal: AbortSignal): Promise<readonly DurableRecord[]> {
      try {
        signal.throwIfAborted();
        const result = fill((into) => flat.list(namespace, into));
        if (result === null) return Promise.resolve([]);
        return Promise.resolve(parseRecords(result.bytes, result.length));
      } catch (error) {
        return Promise.reject(error);
      }
    },

    size(namespace: string, signal: AbortSignal): Promise<number> {
      try {
        signal.throwIfAborted();
        return Promise.resolve(flat.size(namespace));
      } catch (error) {
        return Promise.reject(error);
      }
    },

    close(): Promise<void> {
      try {
        flat.close();
      } catch (error) {
        return Promise.reject(error);
      }
      return Promise.resolve();
    },
  };
}

import { AbortController } from "../core/abort.ts";
import type { AbortSignal } from "../core/abort.ts";
import { LimitError } from "../core/errors.ts";
import { Blob, _createBlobFromExternalSource } from "../file/blob.ts";
import type { ReadableStream } from "../streams/readable.ts";
import type { DurableByteStore, DurableWrite } from "./durable.ts";

/**
 * A body that has been read to the end, held wherever it fits.
 *
 * The `blob` is the same value either way -- the point of the pairing is that a consumer
 * of a spilled body reads it through exactly the code that reads any other Blob. Only
 * `release` differs, and only in whether it has anything to do.
 */
export interface SpilledBody {
  readonly blob: Blob;

  /** True when the bytes are in the durable store rather than in memory. */
  readonly spilled: boolean;

  readonly size: number;

  /**
   * Removes whatever this spill wrote.
   *
   * Idempotent. The blob must not be read afterwards; a Blob has no disposal of its
   * own, so the lifetime belongs to whoever asked for the spill. That is deliberate:
   * the alternative is a finalizer deciding when stored bytes go away, and a cache of
   * spilled bodies would then be at the mercy of when collection happens to run.
   */
  release(): Promise<void>;
}

export interface DurableSpillAreaOptions {
  /** Defaults to `"spill"`. */
  namespace?: string;
  /** Bytes held in memory before anything is written. Defaults to 1 MiB. */
  memoryThresholdBytes?: number;
  /** Refused beyond this. Defaults to 512 MiB. */
  maxBytes?: number;
}

function validateLimit(value: number | undefined, fallback: number, name: string): number {
  const result = value ?? fallback;
  if (!Number.isSafeInteger(result) || result < 0) {
    throw new RangeError("Invalid spill " + name);
  }
  return result;
}

function joinChunks(chunks: readonly Uint8Array[], length: number): Uint8Array<ArrayBuffer> {
  const out = new Uint8Array(new ArrayBuffer(length));
  let offset = 0;
  for (const chunk of chunks) {
    out.set(chunk, offset);
    offset += chunk.length;
  }
  return out;
}

/**
 * Scratch space in the durable store for bodies too large to hold in memory.
 *
 * The threshold is the whole design. A body under it never touches the store, so the
 * common case pays nothing; a body over it is written as it arrives and is never
 * assembled in memory at all, which is the requirement the streaming write side of the
 * byte store exists for. What comes back is a Blob either way.
 *
 * **Spilled bytes do not survive the process that wrote them.** {@link open} clears the
 * namespace, because anything left in it is from a run that has ended and nothing can
 * name it again. That makes the namespace unshareable with a store whose contents are
 * meant to last, which is why it is a namespace of its own rather than a key prefix.
 */
export class DurableSpillArea {
  readonly #store: DurableByteStore;
  readonly #namespace: string;
  readonly #memoryThresholdBytes: number;
  readonly #maxBytes: number;
  readonly #signal: AbortSignal;
  #nextId = 0;

  private constructor(store: DurableByteStore, options: DurableSpillAreaOptions) {
    this.#store = store;
    this.#namespace = options.namespace ?? "spill";
    this.#memoryThresholdBytes = validateLimit(
      options.memoryThresholdBytes,
      1024 * 1024,
      "memory threshold",
    );
    this.#maxBytes = validateLimit(options.maxBytes, 512 * 1024 * 1024, "byte limit");
    this.#signal = new AbortController().signal;
  }

  static async open(
    store: DurableByteStore,
    options: DurableSpillAreaOptions = {},
  ): Promise<DurableSpillArea> {
    const area = new DurableSpillArea(store, options);
    await area.clear();
    return area;
  }

  /** Discards every spilled body in the namespace. */
  async clear(): Promise<void> {
    for (const record of await this.#store.list(this.#namespace, this.#signal)) {
      await this.#store.delete(this.#namespace, record.key, this.#signal);
    }
  }

  #memoryBody(chunks: readonly Uint8Array[], length: number, type: string): SpilledBody {
    const blob = new Blob([joinChunks(chunks, length)], { type });
    return {
      blob,
      spilled: false,
      size: length,
      release(): Promise<void> {
        return Promise.resolve();
      },
    };
  }

  async #spilledBody(key: string, length: number, type: string): Promise<SpilledBody> {
    const source = await this.#store.source(this.#namespace, key, this.#signal);
    if (source === null) throw new TypeError("The spilled body vanished before it was read");
    const store = this.#store;
    const namespace = this.#namespace;
    const signal = this.#signal;
    let released = false;
    return {
      blob: _createBlobFromExternalSource(source, type),
      spilled: true,
      size: length,
      async release(): Promise<void> {
        if (released) return;
        released = true;
        await store.delete(namespace, key, signal);
      },
    };
  }

  /**
   * Reads `stream` to the end, spilling once it outgrows the threshold.
   *
   * The stream is cancelled and anything written is discarded if the limit is exceeded,
   * if `signal` aborts, or if the stream itself fails -- a partial body is never handed
   * back as a whole one, and a refusal never leaves bytes in the namespace.
   */
  async spill(
    stream: ReadableStream<Uint8Array>,
    signal: AbortSignal,
    type = "",
  ): Promise<SpilledBody> {
    signal.throwIfAborted();
    const key = String(this.#nextId++);
    const reader = stream.getReader();
    const held: Uint8Array[] = [];
    let length = 0;
    let write: DurableWrite | null = null;

    const abandon = async (reason: unknown): Promise<void> => {
      // Order matters only in that both must happen: the stream is cancelled so the
      // producer stops, and the write is discarded so no bytes are left named.
      await reader.cancel(reason).then(
        () => {},
        () => {},
      );
      if (write !== null) await write.discard();
      await this.#store.delete(this.#namespace, key, this.#signal);
    };

    try {
      for (;;) {
        const next = await reader.read();
        if (next.done) break;
        const chunk = next.value;
        if (chunk === undefined) continue;
        if (signal.aborted) throw signal.reason;
        if (length + chunk.length > this.#maxBytes) {
          throw new LimitError("Spilled body exceeded configured byte limit");
        }
        length += chunk.length;

        if (write === null && length > this.#memoryThresholdBytes) {
          // Crossing the threshold: everything held so far goes out in one append, and
          // nothing is held from here on. Assembling the whole body to write it would
          // defeat the reason for spilling.
          write = await this.#store.write(this.#namespace, key, this.#signal);
          for (const previous of held) await write.append(previous);
          held.length = 0;
        }

        if (write === null) held.push(chunk.slice());
        else await write.append(chunk);
      }
    } catch (error) {
      // One cleanup path for every way this can end badly -- the limit, the signal, and
      // the stream failing on its own. Three call sites would be three chances to leave
      // bytes in the namespace.
      await abandon(error);
      throw error;
    } finally {
      reader.releaseLock();
    }

    if (write === null) return this.#memoryBody(held, length, type);
    await write.commit();
    return this.#spilledBody(key, length, type);
  }
}

