      result = Reflect.apply(pull, source, [this.#controller]);
    } catch (error) {
      this.#pulling = false;
      this.stream[kStreamFail](error);
      return;
    }
    this.#observePull(result);
  }

  async #observePull(result: void | PromiseLike<void>): Promise<void> {
    try {
      await result;
      this.#pulling = false;
      if (this.#pullAgain) {
        this.#pullAgain = false;
        this.#maybePull();
      }
    } catch (error) {
      this.#pulling = false;
      this.stream[kStreamFail](error);
    }
  }

  #clearAlgorithms(): void {
    this.#source = null;
    this.#pullAlgorithm = undefined;
    this.#cancelAlgorithm = undefined;
  }
}

