  async #readInto(view: ReadableStreamBYOBView, index: number): Promise<void> {
    const reader = this.#byobReader();
    let result: ReadableStreamBYOBReadResult<ReadableStreamBYOBView>;
    try {
      result = await reader.read(view);
    } catch (error) {
