    }
  }

  #resetReadAgain(): void {
    this.#readAgainFirst = false;
    this.#readAgainSecond = false;
  }

  #finishRead(): void {
    this.#reading = false;
    if (this.#done) return;
    if (this.#readAgainFirst) this.pull(0);
    else if (this.#readAgainSecond) this.pull(1);
  }
}

class TeeBranch<T> {
  controller: ReadableStreamDefaultController<T> | undefined;
  canceled = false;
  reason: unknown;
  readonly stream: ReadableStream<T>;

  constructor(owner: TeeState<T>, index: number, size: (chunk: T) => number) {
    this.stream = new ReadableStream<T>(
      {
        start: (controller) => {
          this.controller = controller;
        },
        pull: () => owner.pull(),
        cancel: (reason) => owner.cancel(index, reason),
        type: undefined,
      },
      { highWaterMark: 1, size },
    );
  }

  close(): void {
    if (!this.canceled) {
      this.controller?.close();
    }
  }

  fail(error: unknown): void {
    if (!this.canceled) {
      this.controller?.error(error);
    }
  }

  enqueue(value: T): void {
    if (!this.canceled) {
      this.controller?.enqueue(value);
    }
  }
}

class TeeState<T> {
  readonly branches: [TeeBranch<T>, TeeBranch<T>];
  // Tee permanently owns this reader. Releasing it after a terminal transition
  // would make the original stream observably unlocked, unlike the Streams API.
  private readonly reader: ReadableStreamDefaultReader<T>;
  private readonly clone: (chunk: T) => T;
  private readonly size: (chunk: T) => number;
  private readonly limit: number;
  private readonly canceled = Promise.withResolvers<void>();
  private reading: Promise<void> | null = null;
  private readAgain = false;
  private sourceClosePending = false;
  private sourceErrorPending = false;
  private sourceError: unknown;
  private done = false;

  constructor(stream: ReadableStream<T>, options: TeeOptions<T>) {
    this.clone = options.clone ?? identity;
    this.size = options.size ?? countChunk;
    this.limit = options.maxBufferedSize ?? Infinity;
    if (Number.isNaN(this.limit) || this.limit < 0) {
      throw new RangeError("Invalid clone buffer limit");
    }
    this.reader = new ReadableStreamDefaultReader(stream);
    this.branches = [new TeeBranch(this, 0, this.size), new TeeBranch(this, 1, this.size)];
    ignoreRejection(this.canceled.promise);
    this.observeSourceState();
  }

  private async observeSourceState(): Promise<void> {
    try {
      await this.reader.closed;
      this.sourceClosed();
    } catch (error) {
      this.sourceErrored(error);
    }
  }

  pull(): Promise<void> {
    if (this.done) {
      return Promise.resolve();
    }
    if (this.reading !== null) {
      this.readAgain = true;
      return this.reading;
    }
    const reading = this.readOne();
    this.reading = reading;
    this.finishReading(reading);
    return reading;
  }

  private async finishReading(reading: Promise<void>): Promise<void> {
    let failed = false;
    let readError: unknown;
    try {
      await reading;
    } catch (error) {
      failed = true;
      readError = error;
    }
    if (this.reading !== reading) {
      return;
    }
    this.reading = null;
    if (this.done) {
      return;
    }
    if (failed) {
      this.sourceErrored(readError);
      return;
    }
    this.flushPendingSourceState();
    if (this.done) {
      return;
    }
    if (this.readAgain) {
      this.readAgain = false;
      this.pull();
    }
  }

  private async readOne(): Promise<void> {
    // A read request, not `read()`; see `readChunk`.
    const slot = new ChunkSlot<T>();
    try {
      await readChunk(this.reader, slot);
    } catch (error) {
      this.sourceErrored(error);
      this.flushPendingSourceState();
      return;
    }

    try {
      if (this.done) {
        return;
      }
      if (slot.done) {
        this.sourceClosed();
        this.flushPendingSourceState();
        return;
      }
      const value = slot.value as T;
      const sizeOf = this.size;
      const size = sizeOf(value);
      if (!Number.isFinite(size) || size < 0) {
        throw new RangeError("Invalid chunk size");
      }
      for (const branch of this.branches) {
        if (!branch.canceled && branch.stream[kStreamQueuedSize] + size > this.limit) {
          throw new LimitError("Clone backlog exceeded configured limit");
        }
      }
      const first = this.branches[0];
      const second = this.branches[1];
      // Clone before handing either branch a mutable chunk.
      const clone = this.clone;
      const secondValue = second.canceled ? value : clone(value);
      first.enqueue(value);
      second.enqueue(secondValue);
      this.flushPendingSourceState();
    } catch (error) {
      if (!this.done) {
        this.failTee(error);
      }
    }
  }

  cancel(index: number, reason: unknown): Promise<void> {
    const branch = this.branches[index];
    if (branch !== undefined) {
      branch.canceled = true;
      branch.reason = reason;
    }
    if (this.branches[0].canceled && this.branches[1].canceled && !this.done) {
      this.retire();
      const cancellation = this.reader.cancel([this.branches[0].reason, this.branches[1].reason]);
      this.finishCancellation(cancellation);
    }
    return this.canceled.promise;
  }

  private sourceClosed(): void {
    if (this.done) {
      return;
    }
    if (this.reading !== null) {
      this.sourceClosePending = true;
      return;
    }
    this.finishSourceClose();
  }

  private finishSourceClose(): void {
    this.retire();
    for (const branch of this.branches) {
      branch.close();
    }
    this.canceled.resolve();
  }

  private sourceErrored(error: unknown): void {
    if (this.done) {
      return;
    }
    if (this.reading !== null) {
      this.sourceErrorPending = true;
      this.sourceError = error;
      return;
    }
    this.finishSourceError(error);
  }

  private finishSourceError(error: unknown): void {
    this.retire();
    for (const branch of this.branches) {
      branch.fail(error);
    }
    // A branch canceled before the source failed has fulfilled its cancellation
    // contract; the source error is observed by the branch that remained active.
    this.canceled.resolve();
  }

  private flushPendingSourceState(): void {
    if (this.done) {
      return;
    }
    if (this.sourceErrorPending) {
      const error = this.sourceError;
      this.sourceErrorPending = false;
      this.sourceError = undefined;
      this.finishSourceError(error);
      return;
    }
    if (this.sourceClosePending) {
      this.sourceClosePending = false;
      this.finishSourceClose();
    }
  }

  private failTee(error: unknown): void {
    this.retire();
    for (const branch of this.branches) {
      branch.fail(error);
    }
    const cancellation = this.reader.cancel(error);
    this.finishCancellation(cancellation);
  }

  private async finishCancellation(cancellation: Promise<void>): Promise<void> {
    try {
      await cancellation;
      this.canceled.resolve();
    } catch (error) {
      this.canceled.reject(error);
    }
  }

  private retire(): void {
    this.done = true;
    this.readAgain = false;
    this.sourceClosePending = false;
    this.sourceErrorPending = false;
    this.sourceError = undefined;
  }
}

export function tee<T>(
  stream: ReadableStream<T>,
  options: TeeOptions<T> = defaultTeeOptions,
): [ReadableStream<T>, ReadableStream<T>] {
  if (stream[kStreamByteStream]) {
    const state = new ByteTeeState(stream, options);
    return [state.branches[0].stream, state.branches[1].stream];
  }
  const state = new TeeState(stream, options);
  return [state.branches[0].stream, state.branches[1].stream];
}

export function bytesStream(bytes: Uint8Array, chunkSize = 65536): ReadableStream<Uint8Array> {
  if (!Number.isSafeInteger(chunkSize) || chunkSize < 1) {
    throw new RangeError("Invalid byte chunk size");
  }
  let position = 0;
  return new ReadableStream<Uint8Array>(
    {
      type: "bytes",
      pull(controller) {
        if (position === bytes.length) {
          const request = controller.byobRequest;
          controller.close();
          request?.respond(0);
          return;
        }
        const request = controller.byobRequest;
        const view = request?.view;
        if (request !== null && request !== undefined && view !== null && view !== undefined) {
          const count = Math.min(view.byteLength, chunkSize, bytes.length - position);
          new Uint8Array(view.buffer, view.byteOffset, count).set(
            bytes.subarray(position, position + count),
          );
          position += count;
          request.respond(count);
          return;
        }
        const end = Math.min(position + chunkSize, bytes.length);
        controller.enqueue(bytes.slice(position, end));
        position = end;
      },
    },
    { highWaterMark: 0 },
  );
}

class ByteTransferSource<T> implements UnderlyingByteSource {
  readonly type = "bytes";
  readonly #source: ReadableStream<T>;
  #reader: ReadableStreamDefaultReader<T> | ReadableStreamBYOBReader;

  constructor(source: ReadableStream<T>) {
    this.#source = source;
    this.#reader = new ReadableStreamDefaultReader(source);
  }

  async pull(controller: ReadableByteStreamController): Promise<void> {
    const request = controller.byobRequest;
    const view = request?.view;
    if (request === null || request === undefined || view === null || view === undefined) {
      const result = await this.#defaultReader().read();
      if (result.done) {
        controller.close();
        return;
      }
      if (!(result.value instanceof Uint8Array) || !(result.value.buffer instanceof ArrayBuffer)) {
        throw new TypeError("A byte stream produced a non-byte chunk");
      }
      controller.enqueue(
        new Uint8Array(result.value.buffer, result.value.byteOffset, result.value.byteLength),
      );
      return;
    }

    const result = await this.#byobReader().read(view);
    if (result.done) {
      controller.close();
      if (result.value === undefined) request.respond(0);
      else request.respondWithNewView(result.value);
      return;
    }
    request.respondWithNewView(result.value);
  }

  async cancel(reason: unknown): Promise<void> {
    await this.#reader.cancel(reason);
  }

  #defaultReader(): ReadableStreamDefaultReader<T> {
    const reader = this.#reader;
    if (reader instanceof ReadableStreamDefaultReader) return reader;
    reader.releaseLock();
    const replacement = new ReadableStreamDefaultReader(this.#source);
    this.#reader = replacement;
    return replacement;
  }

  #byobReader(): ReadableStreamBYOBReader {
    const reader = this.#reader;
    if (reader instanceof ReadableStreamBYOBReader) return reader;
    reader.releaseLock();
    const replacement = new ReadableStreamBYOBReader(this.#source);
    this.#reader = replacement;
    return replacement;
  }
}

/**
 * The source becomes disturbed immediately and stays locked, matching Fetch body
 * transfer. The proxy stream owns its reader even after a terminal transition.
 */
export function transfer<T>(stream: ReadableStream<T>): ReadableStream<T> {
  if (stream[kStreamByteStream]) {
    const source = new ByteTransferSource(stream);
    stream[kStreamMarkDisturbed]();
    return new ReadableStream<T>(source, { highWaterMark: 0 });
  }
  const reader = stream.getReader();

  stream[kStreamMarkDisturbed]();
  return new ReadableStream<T>(
    {
      async pull(controller) {
        // A read request, not `read()`: teeing must not be observable to a replaced
        // `Object.prototype.then`. See `readChunk`.
        const slot = new ChunkSlot<T>();
        await readChunk(reader, slot);
        if (slot.done) {
          controller.close();
        } else {
          controller.enqueue(slot.value as T);
        }
      },
      async cancel(reason) {
        await reader.cancel(reason);
      },
    },
    { highWaterMark: 0 },
  );
}

import { requireDictionary } from "../core/webidl.ts";
import {
  ReadableStream,
  readableStreamCanCloseOrEnqueue,
  readableStreamClose,
  readableStreamDesiredSize,
  readableStreamEnqueue,
  readableStreamError,
  readableStreamIsErrored,
  readableStreamStoredError,
  type UnderlyingSource,
} from "./readable.ts";
import {
  extractHighWaterMark,
  extractSizeAlgorithm,
  type QueuingStrategy,
} from "./queuing-strategy.ts";
import {
  WritableStream,
  writableStreamError,
  writableStreamIsFullyErrored,
  writableStreamIsErrored,
  writableStreamStoredError,
  type UnderlyingSink,
} from "./writable.ts";

export type TransformerStartCallback<I, O> = (
  this: Transformer<I, O>,
  controller: TransformStreamDefaultController<O>,
) => void | PromiseLike<void>;

export type TransformerTransformCallback<I, O> = (
  this: Transformer<I, O>,
  chunk: I | undefined,
  controller: TransformStreamDefaultController<O>,
) => void | PromiseLike<void>;

export type TransformerFlushCallback<I, O> = (
  this: Transformer<I, O>,
  controller: TransformStreamDefaultController<O>,
) => void | PromiseLike<void>;

export type TransformerCancelCallback<I, O> = (
  this: Transformer<I, O>,
  reason: unknown,
) => void | PromiseLike<void>;

export interface Transformer<I, O> {
  cancel?: TransformerCancelCallback<I, O>;
  flush?: TransformerFlushCallback<I, O>;
  readableType?: undefined;
  start?: TransformerStartCallback<I, O>;
  transform?: TransformerTransformCallback<I, O>;
  writableType?: undefined;
}

const transformStreamBrand: unique symbol = Symbol("TransformStream brand");
const transformControllerBrand: unique symbol = Symbol("TransformStreamDefaultController brand");
const transformControllerKey: unique symbol = Symbol("construct TransformStreamDefaultController");

const defaultTransformer = {
  cancel: undefined,
  flush: undefined,
  readableType: undefined,
  start: undefined,
  transform: undefined,
  writableType: undefined,
};
const defaultWritableStrategy = {
  highWaterMark: undefined,
  size: undefined,
};
const defaultReadableStrategy = {
  highWaterMark: undefined,
  size: undefined,
};

interface TransformReadableAlgorithms {
  pull(): Promise<void>;
  cancelReadable(reason: unknown): Promise<void>;
}

interface TransformWritableAlgorithms<I> {
  write(chunk: I | undefined): Promise<void>;
  closeWritable(): Promise<void>;
  abortWritable(reason: unknown): Promise<void>;
}

interface TransformControllerState<O> {
  readonly desiredSize: number | null;
  enqueue(chunk: O): void;
  error(reason: unknown): void;
  terminate(): void;
}

class TransformReadableSource<O> implements UnderlyingSource<O> {
  readonly start: () => Promise<void>;
  readonly pull: () => Promise<void>;
  readonly cancel: (reason: unknown) => Promise<void>;
  readonly type = undefined;

  constructor(owner: TransformReadableAlgorithms, startPromise: Promise<void>) {
    this.start = () => startPromise;
    this.pull = () => owner.pull();
    this.cancel = (reason) => owner.cancelReadable(reason);
  }
}

class TransformWritableSink<I> implements UnderlyingSink<I> {
  readonly start: () => Promise<void>;
  readonly write: (chunk: I | undefined) => Promise<void>;
  readonly close: () => Promise<void>;
  readonly abort: (reason: unknown) => Promise<void>;
  readonly type = undefined;

  constructor(owner: TransformWritableAlgorithms<I>, startPromise: Promise<void>) {
    this.start = () => startPromise;
    this.write = (chunk) => owner.write(chunk);
    this.close = () => owner.closeWritable();
    this.abort = (reason) => owner.abortWritable(reason);
  }
}

class TransformStreamState<I, O> {
  readonly readable: ReadableStream<O>;
  readonly writable: WritableStream<I>;
  readonly controller: TransformStreamDefaultController<O>;
  #transformer: Transformer<I, O> | null;
  #transformAlgorithm: TransformerTransformCallback<I, O> | undefined;
  #flushAlgorithm: TransformerFlushCallback<I, O> | undefined;
  #cancelAlgorithm: TransformerCancelCallback<I, O> | undefined;
  #backpressure = true;
  #backpressureChange: PromiseWithResolvers<void> | null = null;
  #finish: PromiseWithResolvers<void> | null = null;

  constructor(
    transformer: Transformer<I, O>,
    writableHighWaterMark: number,
    writableSizeAlgorithm: (chunk: I | undefined) => number,
    readableHighWaterMark: number,
    readableSizeAlgorithm: (chunk: O) => number,
    startCapability: PromiseWithResolvers<void>,
  ) {
    this.#transformer = transformer;
    this.#transformAlgorithm = transformer.transform;
    this.#flushAlgorithm = transformer.flush;
    this.#cancelAlgorithm = transformer.cancel;
    this.controller = new TransformStreamDefaultController(transformControllerKey, this);

    this.writable = new WritableStream<I>(
      new TransformWritableSink<I>(this, startCapability.promise),
      { highWaterMark: writableHighWaterMark, size: writableSizeAlgorithm },
    );
    this.readable = new ReadableStream<O>(
      new TransformReadableSource<O>(this, startCapability.promise),
      { highWaterMark: readableHighWaterMark, size: readableSizeAlgorithm },
    );
  }

  get desiredSize(): number | null {
    return readableStreamDesiredSize(this.readable);
  }

  enqueue(chunk: O): void {
    if (!readableStreamCanCloseOrEnqueue(this.readable)) {
      throw new TypeError("TransformStream readable side cannot accept a chunk");
    }
    try {
      readableStreamEnqueue(this.readable, chunk);
    } catch (error) {
      this.#errorWritableAndUnblock(error);
      throw readableStreamStoredError(this.readable);
    }
    const backpressure = (readableStreamDesiredSize(this.readable) ?? 0) <= 0;
    if (backpressure !== this.#backpressure) {
      this.#setBackpressure(backpressure);
    }
  }

  error(reason: unknown): void {
    readableStreamError(this.readable, reason);
    this.#errorWritableAndUnblock(reason);
  }

  terminate(): void {
    if (readableStreamCanCloseOrEnqueue(this.readable)) {
      readableStreamClose(this.readable);
    }
    this.#errorWritableAndUnblock(new TypeError("TransformStream has been terminated"));
  }

  async write(chunk: I | undefined): Promise<void> {
    if (this.#backpressure) {
      await this.#backpressureChangePromise();
      if (writableStreamIsErrored(this.writable)) {
        throw writableStreamStoredError(this.writable);
      }
    }

    const transformer = this.#transformer;
    const transform = this.#transformAlgorithm;
    if (transformer === null) {
      return;
    }
    try {
      if (transform === undefined) {
        this.enqueue(chunk as O);
      } else {
        await Reflect.apply(transform, transformer, [chunk, this.controller]);
      }
    } catch (error) {
      this.error(error);
      throw error;
    }
  }

  pull(): Promise<void> {
    if (this.#backpressure) {
      this.#setBackpressure(false);
    }
    return this.#backpressureChangePromise();
  }

  async closeWritable(): Promise<void> {
    const existing = this.#finish;
    if (existing !== null) {
      return existing.promise;
    }
    const finish = Promise.withResolvers<void>();
    this.#finish = finish;
    this.#finishWritableClose(finish);
    return finish.promise;
  }

  async abortWritable(reason: unknown): Promise<void> {
    const existing = this.#finish;
    if (existing !== null) {
      return existing.promise;
    }
    const finish = Promise.withResolvers<void>();
    this.#finish = finish;
    this.#finishWritableAbort(reason, finish);
    return finish.promise;
  }

  async cancelReadable(reason: unknown): Promise<void> {
    const existing = this.#finish;
    if (existing !== null) {
      return existing.promise;
    }
    const finish = Promise.withResolvers<void>();
    this.#finish = finish;
    this.#finishReadableCancel(reason, finish);
    return finish.promise;
  }

  #backpressureChangePromise(): Promise<void> {
    if (this.#backpressureChange === null) {
      this.#backpressureChange = Promise.withResolvers<void>();
    }
    return this.#backpressureChange.promise;
  }

  #setBackpressure(backpressure: boolean): void {
    if (backpressure === this.#backpressure) {
      return;
    }
    const change = this.#backpressureChange;
    this.#backpressureChange = null;
    this.#backpressure = backpressure;
    change?.resolve();
  }

  #clearAlgorithms(): void {
    this.#transformer = null;
    this.#transformAlgorithm = undefined;
    this.#flushAlgorithm = undefined;
    this.#cancelAlgorithm = undefined;
  }

  #errorWritableAndUnblock(reason: unknown): void {
    this.#clearAlgorithms();
    writableStreamError(this.writable, reason);
    if (this.#backpressure) {
      this.#setBackpressure(false);
    }
  }

  async #finishWritableClose(finish: PromiseWithResolvers<void>): Promise<void> {
    const transformer = this.#transformer;
    const flush = this.#flushAlgorithm;
    try {
      let flushResult: void | PromiseLike<void> = undefined;
      if (transformer !== null && flush !== undefined) {
        flushResult = Reflect.apply(flush, transformer, [this.controller]);
      }
      await flushResult;
      this.#clearAlgorithms();
      if (readableStreamIsErrored(this.readable)) {
        throw readableStreamStoredError(this.readable);
      }
      if (readableStreamCanCloseOrEnqueue(this.readable)) {
        readableStreamClose(this.readable);
      }
      finish.resolve();
    } catch (error) {
      this.#clearAlgorithms();
      readableStreamError(this.readable, error);
      finish.reject(error);
    }
  }

  async #finishWritableAbort(reason: unknown, finish: PromiseWithResolvers<void>): Promise<void> {
    const transformer = this.#transformer;
    const cancel = this.#cancelAlgorithm;
    try {
      let cancelResult: void | PromiseLike<void> = undefined;
      if (transformer !== null && cancel !== undefined) {
        cancelResult = Reflect.apply(cancel, transformer, [reason]);
      }
      await cancelResult;
      this.#clearAlgorithms();
      if (readableStreamIsErrored(this.readable)) {
        throw readableStreamStoredError(this.readable);
      }
      readableStreamError(this.readable, reason);
      finish.resolve();
    } catch (error) {
      this.#clearAlgorithms();
      readableStreamError(this.readable, error);
      finish.reject(error);
    }
  }

  async #finishReadableCancel(reason: unknown, finish: PromiseWithResolvers<void>): Promise<void> {
    const transformer = this.#transformer;
    const cancel = this.#cancelAlgorithm;
    const hadCancelAlgorithm = transformer !== null && cancel !== undefined;
    const startedErrored = writableStreamIsFullyErrored(this.writable);
    try {
      let cancelResult: void | PromiseLike<void> = undefined;
      if (hadCancelAlgorithm) {
        cancelResult = Reflect.apply(cancel, transformer, [reason]);
      }
      await cancelResult;
      this.#clearAlgorithms();
      if (writableStreamIsFullyErrored(this.writable) && (hadCancelAlgorithm || startedErrored)) {
        throw writableStreamStoredError(this.writable);
      }
      writableStreamError(this.writable, reason);
      if (this.#backpressure) {
        this.#setBackpressure(false);
      }
      finish.resolve();
    } catch (error) {
      this.#clearAlgorithms();
      writableStreamError(this.writable, error);
      if (this.#backpressure) {
        this.#setBackpressure(false);
      }
      finish.reject(error);
    }
  }
}

export class TransformStream<I = unknown, O = unknown> {
  readonly [transformStreamBrand] = true;
  readonly #state: TransformStreamState<I, O>;

  constructor(
    transformer: Transformer<I, O> | null = defaultTransformer,
    writableStrategy: QueuingStrategy<I | undefined> | null = defaultWritableStrategy,
    readableStrategy: QueuingStrategy<O> | null = defaultReadableStrategy,
  ) {
    requireDictionary(transformer, "Transformer");
    if (transformer === null) {
      throw new TypeError("Transformer must be an object");
    }

    const readableType = transformer.readableType;
    const writableType = transformer.writableType;
    const start = transformer.start;
    if (readableType !== undefined) {
      throw new RangeError("Transformer readableType is not supported");
    }
    if (writableType !== undefined) {
      throw new RangeError("Transformer writableType is not supported");
    }
    if (start !== undefined && typeof start !== "function") {
      throw new TypeError("Transformer start must be callable");
    }
    if (transformer.transform !== undefined && typeof transformer.transform !== "function") {
      throw new TypeError("Transformer transform must be callable");
    }
    if (transformer.flush !== undefined && typeof transformer.flush !== "function") {
      throw new TypeError("Transformer flush must be callable");
    }
    if (transformer.cancel !== undefined && typeof transformer.cancel !== "function") {
      throw new TypeError("Transformer cancel must be callable");
    }

    const readableSize = extractSizeAlgorithm(readableStrategy);
    const readableHighWaterMark = extractHighWaterMark(readableStrategy, 0);
    const writableSize = extractSizeAlgorithm(writableStrategy);
    const writableHighWaterMark = extractHighWaterMark(writableStrategy, 1);
    const startCapability = Promise.withResolvers<void>();
    this.#state = new TransformStreamState(
      transformer,
      writableHighWaterMark,
      writableSize,
      readableHighWaterMark,
      readableSize,
      startCapability,
    );

    try {
      startCapability.resolve(
        start === undefined
          ? undefined
          : Reflect.apply(start, transformer, [this.#state.controller]),
      );
    } catch (error) {
      startCapability.reject(error);
      throw error;
    }
