  protocol?: string;
  username?: string;
  password?: string;
  hostname?: string;
  port?: string;
  pathname?: string;
  search?: string;
  hash?: string;
  baseURL?: string;
}
export type URLPatternInput = string | URLPatternInit;
export interface URLPatternOptions { ignoreCase?: boolean; }
export interface URLPatternComponentResult {
  input: string;
  groups: Record<string, string | undefined>;
}
export interface URLPatternResult {
  inputs: URLPatternInput[];
  protocol: URLPatternComponentResult;
  username: URLPatternComponentResult;
  password: URLPatternComponentResult;
  hostname: URLPatternComponentResult;
  port: URLPatternComponentResult;
  pathname: URLPatternComponentResult;
  search: URLPatternComponentResult;
  hash: URLPatternComponentResult;
}
export type ComponentName = "protocol" | "username" | "password" | "hostname" |
  "port" | "pathname" | "search" | "hash";
export const componentNames: readonly ComponentName[] = [
  "protocol", "username", "password", "hostname", "port", "pathname", "search", "hash",
];

import { coerceToUSVString, requireDictionary } from "../core/webidl.ts";
import { currentWebPlatformRuntime } from "../provider/environment.ts";
import type { URLParser, URLRecord } from "../provider/primitives.ts";
import { getURLPatternURLCapability, URLPatternCapabilityError } from "../provider/url-pattern.ts";
import type { URLPatternCanonicalComponent, URLPatternURLCapability } from "../provider/url-pattern.ts";
import { parseConstructorString } from "./constructor-string.ts";
import { Component, defaultOptions, escapePattern, matchesSpecialScheme } from "./pattern.ts";
import { componentNames } from "./types.ts";
import type { ComponentName, URLPatternComponentResult, URLPatternInit, URLPatternInput, URLPatternOptions, URLPatternResult } from "./types.ts";

const dictionaryNames: readonly (keyof URLPatternInit)[] = [
  "baseURL", "hash", "hostname", "password", "pathname", "port", "protocol", "search", "username",
];
function object(value: unknown): value is object {
  return value !== null && (typeof value === "object" || typeof value === "function");
}
function convertInput(value: unknown): URLPatternInput {
  if (value === undefined || value === null || object(value)) {
    const result: URLPatternInit = {};
    if (value !== undefined && value !== null) {
      const input = value as URLPatternInit;
      for (const name of dictionaryNames) {
        const member = input[name];
        if (member !== undefined) result[name] = coerceToUSVString(member);
      }
    }
    return result;
  }
  return coerceToUSVString(value);
}
function convertOptions(value: URLPatternOptions | undefined): boolean {
  requireDictionary(value, "URLPattern options");
  return value === undefined || value === null ? false : !!value.ignoreCase;
}
function special(protocol: string): boolean {
  return protocol === "ftp" || protocol === "file" || protocol === "http" || protocol === "https" || protocol === "ws" || protocol === "wss";
}
function defaultPort(protocol: string): string {
  switch (protocol) {
    case "ftp": return "21";
    case "http": case "ws": return "80";
    case "https": case "wss": return "443";
    default: return "";
  }
}
function values(url: URLRecord): Record<ComponentName, string> {
  return { protocol: url.protocol.slice(0, -1), username: url.username, password: url.password,
    hostname: url.hostname, port: url.port, pathname: url.pathname,
    search: url.search.slice(1), hash: url.hash.slice(1) };
}
function resultFor(component: Component, value: string, match: RegExpExecArray): URLPatternComponentResult {
  // Object.fromEntries creates data properties even for the name "__proto__".
  // No descriptor/prototype operation or inherited setter is involved.
  const pairs: [string, string | undefined][] = [];
  for (let index = 0; index < component.names.length; index++) pairs.push([component.names[index]!, match[index + 1]]);
  return { input: value, groups: Object.fromEntries(pairs) };
}

class URLPolicy {
  readonly urls: URLParser;
  readonly capability: URLPatternURLCapability;
  constructor(urls: URLParser, capability: URLPatternURLCapability) {
    this.urls = urls;
    this.capability = capability;
  }
  protocol(value: string): string {
    if (value === "") return value;
    // URL Pattern §3.1 explicitly specifies this complete dummy URL parse.
    return this.urls.parse(value + "://dummy.invalid/").protocol.slice(0, -1);
  }
  canonical(component: URLPatternCanonicalComponent, value: string, protocol?: string): string {
    if (value === "") return value;
    const result = this.capability.canonicalize(component, value, protocol);
    if (result.ok) return result.value;
    if (result.error === "unsupported") throw new URLPatternCapabilityError();
    throw new TypeError("Invalid URLPattern " + component);
  }
  process(init: URLPatternInit, pattern: boolean): URLPatternInit {
    const result: URLPatternInit = pattern ? {} : {
      protocol: "", username: "", password: "", hostname: "", port: "", pathname: "", search: "", hash: "",
    };
    let base: URLRecord | undefined;
    if (init.baseURL !== undefined) {
      base = this.urls.parse(init.baseURL);
      const baseValues = values(base);
      const encode = pattern ? escapePattern : (value: string): string => value;
      if (init.protocol === undefined) result.protocol = encode(baseValues.protocol);
      const authorityMissing = init.protocol === undefined && init.hostname === undefined && init.port === undefined;
      if (!pattern && authorityMissing && init.username === undefined) result.username = encode(baseValues.username);
      if (!pattern && authorityMissing && init.username === undefined && init.password === undefined) result.password = encode(baseValues.password);
      if (init.protocol === undefined && init.hostname === undefined) result.hostname = encode(baseValues.hostname);
      if (authorityMissing) result.port = baseValues.port;
      if (authorityMissing && init.pathname === undefined) result.pathname = encode(baseValues.pathname);
      if (authorityMissing && init.pathname === undefined && init.search === undefined) result.search = encode(baseValues.search);
      if (authorityMissing && init.pathname === undefined && init.search === undefined && init.hash === undefined) result.hash = encode(baseValues.hash);
    }
    if (init.protocol !== undefined) {
      const value = init.protocol.endsWith(":") ? init.protocol.slice(0, -1) : init.protocol;
      result.protocol = pattern ? value : this.protocol(value);
    }
    for (const name of ["username", "password", "hostname"] as const) {
      const value = init[name];
      if (value !== undefined) result[name] = pattern ? value : this.canonical(name, value);
    }
    const protocol = result.protocol ?? "";
    if (init.port !== undefined) result.port = pattern ? init.port : this.canonical("port", init.port, protocol);
    if (init.pathname !== undefined) {
      let pathname = init.pathname;
      const absolute = pathname.startsWith("/") || (pattern && (pathname.startsWith("\\/") || pathname.startsWith("{/")));
      if (base !== undefined && !this.capability.hasOpaquePath(base) && !absolute) {
        const basePath = pattern ? escapePattern(base.pathname) : base.pathname;
        const slash = basePath.lastIndexOf("/");
        if (slash !== -1) pathname = basePath.slice(0, slash + 1) + pathname;
      }
      result.pathname = pattern ? pathname : this.canonical(protocol === "" || special(protocol) ? "pathname" : "opaquePathname", pathname);
    }
    for (const name of ["search", "hash"] as const) {
      const value = init[name];
      if (value !== undefined) {
        const stripped = value.startsWith(name === "search" ? "?" : "#") ? value.slice(1) : value;
        result[name] = pattern ? stripped : this.canonical(name, stripped);
      }
    }
    return result;
  }
}

/** URL Pattern §1.2. The provider owns URL parsing; this class owns patterns. */
export class URLPattern {
  readonly [Symbol.toStringTag] = "URLPattern";
  readonly #components: Record<ComponentName, Component>;
  readonly #policy: URLPolicy;

  constructor(input?: URLPatternInput, options?: URLPatternOptions);
  constructor(input: URLPatternInput, baseURL: string, options?: URLPatternOptions);
  constructor(input: URLPatternInput = {}, baseOrOptions: string | URLPatternOptions | undefined = undefined, options?: URLPatternOptions) {
    const converted = convertInput(input);
    const withBase = arguments.length >= 3 || (baseOrOptions !== undefined && baseOrOptions !== null && !object(baseOrOptions));
    const base = withBase ? coerceToUSVString(baseOrOptions) : undefined;
    const ignoreCase = convertOptions(withBase ? options : baseOrOptions as URLPatternOptions | undefined);
    const runtime = currentWebPlatformRuntime();
    const policy = new URLPolicy(runtime.urls, getURLPatternURLCapability(runtime));
    this.#policy = policy;
    let init: URLPatternInit;
    if (typeof converted === "string") {
      init = parseConstructorString(converted, (value) => policy.protocol(value));
      if (base === undefined && init.protocol === undefined) throw new TypeError("A relative URLPattern needs a base URL");
      if (base !== undefined) init.baseURL = base;
    } else {
      if (base !== undefined) throw new TypeError("A URLPatternInit cannot have a separate base URL");
      init = converted;
    }
    const processed = policy.process(init, true);
    const protocolPattern = processed.protocol ?? "*";
    let portPattern = processed.port ?? "*";
    if (defaultPort(protocolPattern) !== "" && /^[0-9]+$/.test(portPattern) && Number(portPattern) === Number(defaultPort(protocolPattern))) portPattern = "";
    const protocol = new Component(protocolPattern, defaultOptions, (value) => policy.protocol(value));
    const hostnamePattern = processed.hostname ?? "*";
    const ipv6 = hostnamePattern.startsWith("[") || hostnamePattern.startsWith("{[") || hostnamePattern.startsWith("\\[");
    const hostnameEncode = ipv6 ? (value: string): string => {
      if (!/^[0-9a-fA-F\[\]:]*$/.test(value)) throw new TypeError("Invalid IPv6 hostname pattern");
      return value.toLowerCase();
    } : (value: string): string => policy.canonical("hostname", value);
    const specialPath = matchesSpecialScheme(protocol);
    const optionsForText = { ...defaultOptions, ignoreCase };
    this.#components = {
      protocol,
      username: new Component(processed.username ?? "*", defaultOptions, (value) => policy.canonical("username", value)),
      password: new Component(processed.password ?? "*", defaultOptions, (value) => policy.canonical("password", value)),
      hostname: new Component(hostnamePattern, { delimiter: ".", prefix: "", ignoreCase: false }, hostnameEncode),
      port: new Component(portPattern, defaultOptions, (value) => policy.canonical("port", value)),
      pathname: new Component(processed.pathname ?? "*", specialPath ? { delimiter: "/", prefix: "/", ignoreCase } : optionsForText,
        (value) => policy.canonical(specialPath ? "pathname" : "opaquePathname", value)),
      search: new Component(processed.search ?? "*", optionsForText, (value) => policy.canonical("search", value)),
      hash: new Component(processed.hash ?? "*", optionsForText, (value) => policy.canonical("hash", value)),
    };
  }
  get protocol(): string { return this.#components.protocol.pattern; }
  get username(): string { return this.#components.username.pattern; }
  get password(): string { return this.#components.password.pattern; }
  get hostname(): string { return this.#components.hostname.pattern; }
  get port(): string { return this.#components.port.pattern; }
  get pathname(): string { return this.#components.pathname.pattern; }
  get search(): string { return this.#components.search.pattern; }
  get hash(): string { return this.#components.hash.pattern; }
  get hasRegExpGroups(): boolean {
    for (const name of componentNames) if (this.#components[name].hasRegExpGroups) return true;
    return false;
  }
  test(input: URLPatternInput = {}, baseURL?: string): boolean {
    if (!(#components in this)) throw new TypeError("URLPattern method called on an incompatible receiver");
    return this.#match(convertInput(input), baseURL === undefined ? undefined : coerceToUSVString(baseURL)) !== null;
  }
  exec(input: URLPatternInput = {}, baseURL?: string): URLPatternResult | null {
    if (!(#components in this)) throw new TypeError("URLPattern method called on an incompatible receiver");
    return this.#match(convertInput(input), baseURL === undefined ? undefined : coerceToUSVString(baseURL));
  }
  #match(input: URLPatternInput, base?: string): URLPatternResult | null {
    const inputs: URLPatternInput[] = [input];
    let components: URLPatternInit;
    if (typeof input !== "string") {
      if (base !== undefined) throw new TypeError("A URLPatternInit cannot have a separate base URL");
      try { components = this.#policy.process(input, false); }
      catch (error) { if (error instanceof URLPatternCapabilityError) throw error; return null; }
    } else {
      try {
        if (base !== undefined) {
          this.#policy.urls.parse(base);
          inputs.push(base);
        }
        components = values(this.#policy.urls.parse(input, base));
      } catch { return null; }
    }
    const matches: URLPatternComponentResult[] = [];
    for (const name of componentNames) {
      const value = components[name]!;
      const match = this.#components[name].exec(value);
      if (match === null) return null;
      matches.push(resultFor(this.#components[name], value, match));
    }
    return { inputs, protocol: matches[0]!, username: matches[1]!, password: matches[2]!,
      hostname: matches[3]!, port: matches[4]!, pathname: matches[5]!, search: matches[6]!, hash: matches[7]! };
  }
}

import type { AbortSignal } from "../core/abort.ts";
import { BufferedReader } from "../http1/io.ts";
import { defaultHeadLimits, readRequestHead } from "../http1/parser.ts";
import type { HeadLimits, RequestHead } from "../http1/parser.ts";
import type { ByteConnection, SocketListener } from "../provider/primitives.ts";
import type { WebSocketServer, WebSocketUpgradeResult } from "./server.ts";

export interface WebSocketAcceptOptions {
  /** Limits for reading the request head. Defaults to the shared HTTP/1 limits. */
  readonly limits?: HeadLimits;
  /**
   * Called for each accepted connection before the upgrade is attempted.
   *
   * The request head is the only thing a server has to route on, and this is where an
   * embedder decides that `/socket` is a WebSocket and `/health` is not. Returning
   * `false` closes the connection without upgrading.
   */
  readonly accept?: (head: RequestHead) => boolean | Promise<boolean>;
  /**
   * Receives each session as it is adopted, with the request head that produced it.
   *
   * Without this the loop would upgrade connections and hand them to nobody, which is
   * the shape of thing this ledger keeps recording: a mechanism that runs and produces
   * nothing a caller can reach. The head comes with it because a server that routed on
   * the target needs to know which route this session is.
   *
   * Awaited, so an embedder that wants to serve one session at a time can simply not
   * return until it is done -- which is also how the loop's backpressure reaches the
   * application rather than stopping at the framing layer.
   */
  readonly onSession?: (
    result: WebSocketUpgradeResult,
    head: RequestHead,
  ) => void | Promise<void>;
  /** Reports a connection that failed before it became a session. */
  readonly onError?: (error: unknown) => void;
}

/**
 * Accepts connections from `listener` and upgrades each one through `server`.
 *
 * `WebSocketServer` is deliberately not an accept loop, and this is deliberately not a
 * `WebSocketServer`: the two are separable because listening and framing are separable,
 * and an embedder that already has a server — one that also serves HTTP, say — wants the
 * second without the first.
 *
 * **The loop is the backpressure.** It accepts one connection at a time and does not ask
 * for the next until the current one has either become a session or been refused, so a
 * server at its connection limit stops accepting rather than accepting and discarding.
 * That is why `accept` is pull-shaped, and it is the only reason a `backlog` means
 * anything.
 *
 * Returns when the listener closes or `signal` aborts. A connection that fails its
 * handshake is closed and reported; it never stops the loop, because one malformed
 * client must not be able to take the server down.
 */
export async function serveWebSocketUpgrades(
  listener: SocketListener,
  server: WebSocketServer,
  signal: AbortSignal,
  options: WebSocketAcceptOptions = {},
): Promise<void> {
  const limits = options.limits ?? defaultHeadLimits;
  for (;;) {
    let connection: ByteConnection | null;
    try {
      connection = await listener.accept(signal);
    } catch (error) {
      // An aborted signal ends the loop; it is the caller asking to stop, not a failure
      // of a connection.
      if (signal.aborted) return;
      throw error;
    }
    if (connection === null) return;

    try {
      await upgradeOne(connection, server, limits, options);
    } catch (error) {
      connection.close();
      options.onError?.(error);
    }
    if (signal.aborted) return;
  }
}

async function upgradeOne(
  connection: ByteConnection,
  server: WebSocketServer,
  limits: HeadLimits,
  options: WebSocketAcceptOptions,
): Promise<WebSocketUpgradeResult | null> {
  // One reader for the head and the frames alike: bytes a client sent immediately after
  // its handshake are already buffered here, and a second reader would lose them.
  const reader = new BufferedReader(connection);
  const head = await readRequestHead(reader, limits);

  if (options.accept !== undefined && !(await options.accept(head))) {
    connection.close();
    return null;
  }
  const result = await server.upgrade(head.method, head.headers, connection, reader);
  if (options.onSession !== undefined) await options.onSession(result, head);
  return result;
}

import { decodeUTF8 } from "../core/encoding.ts";
import { percentDecodeBytes } from "../core/percent.ts";
import { parseChallenges } from "../dispatch/authenticate.ts";
import { basicAuthorization } from "../dispatch/proxy.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import type { URLRecord } from "../provider/primitives.ts";

/** RFC 6455 §4.1 response step 1 and RFC 7617 §2: answer an origin Basic challenge. */
export function webSocketBasicAuthorization(
  url: URLRecord,
  status: number,
  headers: readonly HeaderEntry[],
): string | null {
  if (status !== 401 || (url.username === "" && url.password === "")) return null;
  for (const [name, value] of headers) {
    if (name.toLowerCase() !== "www-authenticate") continue;
    for (const challenge of parseChallenges(value)) {
      if (challenge.scheme !== "basic") continue;
      // Match the existing proxy userinfo policy: percent-decode once, preserve
      // literal '+', and reject invalid UTF-8 rather than changing credentials.
      return basicAuthorization(
        decodeUTF8(percentDecodeBytes(url.username), true, true),
        decodeUTF8(percentDecodeBytes(url.password), true, true),
      );
    }
  }
  return null;
}

import { ProtocolError, LimitError } from "../core/errors.ts";
import type { RandomSource } from "../provider/primitives.ts";
import type { BufferedReader } from "../http1/io.ts";
import { decodeUTF8, utf8 } from "../core/encoding.ts";

export type Opcode = 0 | 1 | 2 | 8 | 9 | 10;

export interface Frame {
  fin: boolean;
  opcode: Opcode;
  payload: Uint8Array;
  compressed?: boolean;
}

function opcode(value: number): Opcode {
  switch (value) {
    case 0:
    case 1:
    case 2:
    case 8:
    case 9:
    case 10:
      return value;
    default:
      throw new ProtocolError("Reserved WebSocket opcode");
  }
}
export async function readFrame(
  reader: BufferedReader,
  expectMasked = false,
  maxFrameBytes = 16 * 1024 * 1024,
  allowCompressed = false,
): Promise<Frame> {
  const base = await reader.exact(2);
  const a = base[0] ?? 0;
  const b = base[1] ?? 0;
  const fin = (a & 128) !== 0;
  const code = opcode(a & 15);
  const compressed = (a & 64) !== 0;

  if ((a & 0x30) !== 0) throw new ProtocolError("Unsupported WebSocket reserved bit");
  if (compressed && (!allowCompressed || code === 0 || code >= 8)) {
    throw new ProtocolError("Invalid permessage-deflate RSV1 bit");
  }

  if (((b & 128) !== 0) !== expectMasked)
    throw new ProtocolError("Invalid WebSocket masking direction");
  let length = b & 127;

  if (code >= 8 && (!fin || length > 125))
    throw new ProtocolError("Fragmented or oversized control frame");

  if (length === 126) {
    const bytes = await reader.exact(2);
    length = (bytes[0] ?? 0) * 256 + (bytes[1] ?? 0);
    if (length < 126) throw new ProtocolError("Nonminimal frame length");
  } else if (length === 127) {
    const bytes = await reader.exact(8);
    if (((bytes[0] ?? 0) & 128) !== 0) throw new ProtocolError("Invalid 64-bit frame length");
    length = 0;
    for (const byte of bytes) {
      length = length * 256 + byte;
      if (!Number.isSafeInteger(length))
        throw new LimitError("Frame length exceeds safe integer range");
    }
    if (length < 65536) throw new ProtocolError("Nonminimal frame length");
  }

  if (length > maxFrameBytes) throw new LimitError("WebSocket frame exceeds configured limit");
  const mask = expectMasked ? await reader.exact(4) : null;
  const payload = await reader.exact(length);

  if (mask !== null)
    for (let i = 0; i < payload.length; i++) payload[i] = (payload[i] ?? 0) ^ (mask[i & 3] ?? 0);
  return { fin, opcode: code, payload, compressed };
}

/** Returned chunks may be gathered by native writev. ownPayload allows in-place masking. */
export function encodeFrame(
  frame: Frame,
  random: RandomSource,
  masked = true,
  ownPayload = false,
): readonly Uint8Array[] {
  const size = frame.payload.length;

  if (frame.opcode >= 8 && (!frame.fin || size > 125))
    throw new ProtocolError("Invalid control frame");
  const extended = size < 126 ? 0 : size < 65536 ? 2 : 8;
  const header = new Uint8Array(2 + extended + (masked ? 4 : 0));
  if (frame.compressed && (frame.opcode === 0 || frame.opcode >= 8)) {
    throw new ProtocolError("RSV1 is valid only on a message's first data frame");
  }
  header[0] = (frame.fin ? 128 : 0) | (frame.compressed ? 64 : 0) | frame.opcode;
  header[1] = (masked ? 128 : 0) | (size < 126 ? size : size < 65536 ? 126 : 127);

  if (extended === 2) {
    header[2] = size >>> 8;
    header[3] = size & 255;
  } else if (extended === 8) {
    let remaining = size;
    for (let i = 9; i >= 2; --i) {
      header[i] = remaining % 256;
      remaining = Math.floor(remaining / 256);
    }
  }
  let payload = frame.payload;

  if (masked) {
    const mask = header.subarray(2 + extended);
    random.fill(mask);
    if (!ownPayload) payload = payload.slice();
    for (let i = 0; i < size; i++) payload[i] = (payload[i] ?? 0) ^ (mask[i & 3] ?? 0);
  }
  return [header, payload];
}

export function isValidWireCloseCode(code: number): boolean {
  if (code >= 3000 && code <= 4999) return true;

  switch (code) {
    case 1000:
    case 1001:
    case 1002:
    case 1003:
    case 1007:
    case 1008:
    case 1009:
    case 1010:
    case 1011:
    case 1012:
    case 1013:
    case 1014:
      return true;
    default:
      return false;
  }
}

export function closePayload(code: number | null, reason: string): Uint8Array {
  if (code === null) {
    if (reason !== "") throw new ProtocolError("A close reason needs a code");
    return new Uint8Array(0);
  }

  if (!isValidWireCloseCode(code)) throw new ProtocolError("Invalid close code");
  const text = utf8.encode(reason);

  if (text.length > 123) throw new LimitError("WebSocket close reason exceeds 123 UTF-8 bytes");
  const payload = new Uint8Array(2 + text.length);
  payload[0] = code >>> 8;
  payload[1] = code & 255;

  payload.set(text, 2);
  return payload;
}

export function parseClose(payload: Uint8Array): { code: number; reason: string } {
  if (payload.length === 0) return { code: 1005, reason: "" };

  if (payload.length === 1) throw new ProtocolError("One-byte close payload");
  const code = (payload[0] ?? 0) * 256 + (payload[1] ?? 0);

  if (!isValidWireCloseCode(code)) throw new ProtocolError("Invalid peer close code");
  return { code, reason: decodeUTF8(payload.subarray(2), true, true) };
}

import { abortSignalSubscribe } from "../core/abort.ts";
import type { AbortSignal } from "../core/abort.ts";
import type { URLRecord } from "../provider/primitives.ts";

/** Serialize CONNECTING attempts, not the lifetime of established sessions. */
export class WebSocketConnectionQueue {
  private readonly tails: Map<string, Promise<void>> = new Map();

  async acquire(url: URLRecord, signal: AbortSignal): Promise<() => void> {
    signal.throwIfAborted();
    // RFC 6455 §4.1 step 2: the connector does not expose the resolved peer IP,
    // so use the permitted hostname fallback and the effective destination port.
    const port = url.port || (url.protocol === "wss:" || url.protocol === "https:" ? "443" : "80");
    const key = url.hostname.toLowerCase() + ":" + port;
    const previous = this.tails.get(key) ?? Promise.resolve();
    const released = Promise.withResolvers<void>();
    // An aborted waiter releases its own place immediately, but its successors
    // must still wait for the earlier connection to leave CONNECTING.
    const tail = previous.then(() => released.promise);
    this.tails.set(key, tail);
    tail.then(() => {
      if (this.tails.get(key) === tail) this.tails.delete(key);
    });

    const turn = Promise.withResolvers<void>();
    const detach = signal[abortSignalSubscribe](() => turn.reject(signal.reason));
    previous.then(turn.resolve);
    try {
      await turn.promise;
      signal.throwIfAborted();
      return released.resolve;
    } catch (error) {
      released.resolve();
      throw error;
    } finally {
      detach();
    }
  }
}

