}

/** Which end of a connection a session is. Masking is the only framing asymmetry. */
export type WebSocketRole = "client" | "server";

export class RawWebSocketTransport implements WebSocketTransport {
  private readonly sockets: SocketConnector;
  private readonly random: RandomSource;
  private readonly scheduler: Scheduler;
  private readonly options: RawWebSocketOptions;
  private readonly deflate: WebSocketDeflateProvider | undefined;
  private readonly sessions = new Set<RawWebSocketSession>();
  private readonly connecting = new Set<AbortController>();
  private readonly connectionQueue = new WebSocketConnectionQueue();
  private closed = false;

  constructor(
    sockets: SocketConnector,
    random: RandomSource,
    scheduler: Scheduler,
    options: RawWebSocketOptions = {},
    deflate?: WebSocketDeflateProvider,
  ) {
    for (const value of [
      options.maxFrameBytes,
      options.maxMessageBytes,
      options.maxCompressedMessageBytes,
      options.outgoingFrameBytes,
      options.maxFragments,
      options.connectTimeoutMs,
      options.handshakeTimeoutMs,
      options.closeTimeoutMs,
    ]) {
      if (value !== undefined && (!Number.isSafeInteger(value) || value < 1))
        throw new RangeError("Invalid WebSocket limit or timeout");
    }
    this.sockets = sockets;
    this.random = random;
    this.scheduler = scheduler;
    this.options = options;
    this.deflate = deflate;
  }
  async connect(handshake: WebSocketHandshake, signal: AbortSignal): Promise<WebSocketSession> {
    signal.throwIfAborted();
    if (this.closed) throw new TypeError("WebSocket transport is closed");
    const controller = new AbortController();
    this.connecting.add(controller);
    const detach = signal[abortSignalSubscribe](() => controller.abort(signal.reason));
    try {
      const release = await this.connectionQueue.acquire(handshake.url, controller.signal);
      try {
        controller.signal.throwIfAborted();
        return await this.open(handshake, controller.signal);
      } finally {
        release();
      }
    } finally {
      detach();
      this.connecting.delete(controller);
    }
  }
  private async open(
    handshake: WebSocketHandshake,
    signal: AbortSignal,
    authorization: string | null = null,
  ): Promise<WebSocketSession> {
    signal.throwIfAborted();
    const connection = await this.sockets.connect(
      addressOf(handshake.url, this.options.connectTimeoutMs ?? 30000, ["http/1.1"]),
      signal,
    );
    const dispose = signal[abortSignalSubscribe](() => connection.close());
    const timer = this.scheduler.delay(this.options.handshakeTimeoutMs ?? 30000, () =>
      connection.close(),
    );
    let retryAuthorization: string | null = null;
    try {
      signal.throwIfAborted();
      const key = createKey(this.random);
      const target = handshake.url.pathname + handshake.url.search;
      if (/[^\x21-\x7e]/.test(target)) throw new TypeError("Invalid WebSocket HTTP target");
      validateWireValue(handshake.origin);
      let head =
        "GET " +
        (target || "/") +
        " HTTP/1.1\r\nHost: " +
        handshake.url.host +
        "\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: " +
        key +
        "\r\nSec-WebSocket-Version: 13\r\nOrigin: " +
        handshake.origin +
        "\r\n";
      if (authorization !== null) head += "Authorization: " + authorization + "\r\n";
      if (handshake.protocols.length !== 0)
        head += "Sec-WebSocket-Protocol: " + handshake.protocols.join(", ") + "\r\n";
      if (this.deflate !== undefined) {
        head += "Sec-WebSocket-Extensions: " + perMessageDeflateOffer + "\r\n";
      }
      await writeAll(connection, encodeByteString(head + "\r\n"));
      const reader = new BufferedReader(connection);
      let response = await readHead(reader);
      let informational = 0;
      while (response.status < 200 && response.status !== 101) {
        if (++informational > defaultHeadLimits.maxInformational)
          throw new LimitError("Too many interim upgrade responses");
        response = await readHead(reader);
      }
      if (authorization === null) {
        retryAuthorization = webSocketBasicAuthorization(handshake.url, response.status, response.headers);
      }
      if (retryAuthorization === null) {
        const validated = validateHandshake(
          response.status,
          new Headers(response.headers),
          key,
          handshake.protocols,
          this.deflate !== undefined,
        );
        signal.throwIfAborted();
        const session = new RawWebSocketSession(
          connection,
          reader,
          validated,
          this.deflate,
          this.random,
          this.scheduler,
          this.options,
          (item) => this.sessions.delete(item),
        );
        this.sessions.add(session);
        return session;
      }
      // A challenge is an HTTP response, not an upgrade. Discard its connection
      // before the one permitted retry, retaining the destination's queue slot.
      connection.close();
    } catch (error) {
      connection.close();
      throw signal.aborted ? signal.reason : error;
    } finally {
      timer.cancel();
      dispose();
    }
    return this.open(handshake, signal, retryAuthorization);
  }

  close(): void {
    if (this.closed) return;
    this.closed = true;
    for (const controller of this.connecting)
      controller.abort(new TypeError("WebSocket transport is closed"));
    for (const session of this.sessions) session.abort();
  }
}

class RawWebSocketSession implements WebSocketSession {
  readonly protocol: string;
  readonly extensions: string;
  private readonly connection: ByteConnection;
  private readonly reader: BufferedReader;
  private readonly random: RandomSource;
  private readonly scheduler: Scheduler;
  private readonly options: RawWebSocketOptions;
  private writeTail: Promise<void> = Promise.resolve();
  private sentClose = false;
  private receivedClose = false;
  private ended = false;
  private closeTimer: CancelHandle | null = null;
  private messageOpcode: 0 | 1 | 2 = 0;
  private messageCompressed = false;
  private chunks: Uint8Array[] = [];
  private messageSize = 0;
  private decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
  private textChunks: string[] = [];
  private fragments = 0;
  private readonly compression: PerMessageDeflate | null;
  private readonly onEnd: (session: RawWebSocketSession) => void;
  /**
   * Which end of the connection this is.
   *
   * RFC 6455 makes masking the one asymmetry in the framing: a client masks every
   * frame it sends and a server masks none, and each rejects the other spelling. The
   * message engine is otherwise identical in both directions, so the role is a field
   * rather than a reason for a second implementation of fragmentation, UTF-8
   * validation, compression and the close handshake.
   */
  private readonly role: WebSocketRole;

  constructor(
    connection: ByteConnection,
    reader: BufferedReader,
    handshake: ValidatedWebSocketHandshake,
    deflate: WebSocketDeflateProvider | undefined,
    random: RandomSource,
    scheduler: Scheduler,
    options: RawWebSocketOptions,
    onEnd: (session: RawWebSocketSession) => void,
    role: WebSocketRole = "client",
  ) {
    this.role = role;
    this.onEnd = onEnd;
    this.connection = connection;
    this.reader = reader;
    this.protocol = handshake.protocol;
    this.extensions = handshake.extensions;
    this.compression =
      handshake.perMessageDeflate === null
        ? null
        : new PerMessageDeflate(requireDeflate(deflate), handshake.perMessageDeflate);
    this.random = random;
    this.scheduler = scheduler;
    this.options = options;
  }
  private write(frame: Frame, owned = false): Promise<void> {
    const write = this.writeTail.then(async () => {
      if (this.ended) throw new DOMException("WebSocket transport is closed", "InvalidStateError");
      for (const part of encodeFrame(frame, this.random, this.role === "client", owned))
        await writeAll(this.connection, part);
    });
    this.writeTail = write;
    write.catch(() => {});
    return write;
  }
  async send(message: SocketMessage): Promise<void> {
    if (this.sentClose || this.ended)
      throw new DOMException("WebSocket is closing", "InvalidStateError");
    const source = message.kind === "text" ? utf8.encode(message.data) : message.data;
    const messageLimit = this.options.maxMessageBytes ?? 16 * 1024 * 1024;
    if (source.length > messageLimit) {
      throw new LimitError("WebSocket message exceeds configured limit");
    }
    const compressed = this.compression !== null;
    const payload = compressed
      ? await this.compression.compress(
          source,
          this.options.maxCompressedMessageBytes ?? messageLimit + 65536,
        )
      : source;
    const limit = this.options.outgoingFrameBytes ?? 65536;
    if (!Number.isInteger(limit) || limit < 1) throw new RangeError("Invalid outgoingFrameBytes");
    let offset = 0;
    let first = true;
    do {
      if (this.sentClose || this.ended)
        throw new DOMException("Peer closed during send", "InvalidStateError");
      const end = Math.min(offset + limit, payload.length);
      await this.write(
        {
          fin: end === payload.length,
          opcode: first ? (message.kind === "text" ? 1 : 2) : 0,
          payload: payload.subarray(offset, end),
          compressed: compressed && first,
        },
        true,
      );
      offset = end;
      first = false;
    } while (offset < payload.length);
  }
  async close(code: number | null, reason: string): Promise<void> {
    if (this.sentClose || this.ended) return;
    const payload = closePayload(code, reason);
    this.sentClose = true;
    this.closeTimer = this.scheduler.delay(this.options.closeTimeoutMs ?? 5000, () => this.abort());
    await this.write({ fin: true, opcode: 8, payload }, true);
  }

  abort(): void {
    if (this.ended) return;
    this.ended = true;
    this.closeTimer?.cancel();
    this.compression?.close();
    this.connection.close();
    this.onEnd(this);
  }
  async next(): Promise<SocketIncoming> {
    if (this.ended)
      return {
        kind: "close",
        code: 1006,
        reason: "",
        wasClean: false,
        failed: !this.receivedClose,
      };
    try {
      while (true) {
        const frame = await readFrame(
          this.reader,
          this.role === "server",
          this.options.maxFrameBytes ?? 16 * 1024 * 1024,
          this.compression !== null,
        );
        if (frame.opcode === 9) {
          if (!this.sentClose)
            await this.write({ fin: true, opcode: 10, payload: frame.payload }, true);
          continue;
        }
        if (frame.opcode === 10) continue;
        if (frame.opcode === 8) {
          const peer = parseClose(frame.payload);
          this.receivedClose = true;
          if (!this.sentClose) await this.close(peer.code === 1005 ? null : peer.code, peer.reason);
          // Both close frames have been exchanged. No more application bytes are accepted.
          this.abort();
          return {
            kind: "close",
            code: peer.code,
            reason: peer.reason,
            wasClean: true,
            failed: false,
          };
        }
        if (frame.opcode === 0) {
          if (this.messageOpcode === 0) throw new ProtocolError("Unexpected continuation frame");
        } else {
          if (this.messageOpcode !== 0)
            throw new ProtocolError("New data frame during a fragmented message");
          this.messageOpcode = frame.opcode;
          this.messageCompressed = frame.compressed ?? false;
          this.chunks = [];
          this.textChunks = [];
          this.messageSize = 0;
          this.fragments = 0;
          this.decoder = new TextDecoder("utf-8", { fatal: true, ignoreBOM: true });
        }
        if (++this.fragments > (this.options.maxFragments ?? 65536))
          throw new LimitError("Too many WebSocket fragments");
        this.messageSize += frame.payload.length;
        const messageLimit = this.options.maxMessageBytes ?? 16 * 1024 * 1024;
        const wireLimit = this.messageCompressed
          ? (this.options.maxCompressedMessageBytes ?? messageLimit + 65536)
          : messageLimit;
        if (this.messageSize > wireLimit)
          throw new LimitError("WebSocket message exceeds configured limit");
        if (this.messageCompressed) {
          if (frame.payload.length !== 0) this.chunks.push(frame.payload);
        } else if (this.messageOpcode === 1) {
          const text = this.decoder.decode(frame.payload, { stream: !frame.fin });
          if (text.length !== 0) this.textChunks.push(text);
        } else if (frame.payload.length !== 0) this.chunks.push(frame.payload);
        if (frame.fin) {
          let message: SocketMessage;
          if (this.messageCompressed) {
            const compression = this.compression;
            if (compression === null)
              throw new ProtocolError("Compressed message was not negotiated");
            const inflated = await compression.decompress(
              concatBytes(this.chunks, this.messageSize),
              messageLimit,
            );
            message =
              this.messageOpcode === 1
                ? { kind: "text", data: decodeUTF8(inflated, true, true) }
                : { kind: "binary", data: inflated };
          } else {
            message =
              this.messageOpcode === 1
                ? { kind: "text", data: this.textChunks.join("") }
                : { kind: "binary", data: concatBytes(this.chunks, this.messageSize) };
          }
          this.messageOpcode = 0;
          this.messageCompressed = false;
          this.chunks = [];
          this.textChunks = [];
          this.messageSize = 0;
          return message;
        }
      }
    } catch (error) {
      if (!this.sentClose && !this.ended) {
        const code = error instanceof LimitError ? 1009 : error instanceof TypeError ? 1007 : 1002;
        try {
          await this.close(code, "");
        } catch {
          /* A broken transport cannot carry a failure close. */
        }
      }
      this.abort();
      return { kind: "close", code: 1006, reason: "", wasClean: false, failed: true };
    }
  }
}

function requireDeflate(provider: WebSocketDeflateProvider | undefined): WebSocketDeflateProvider {
  if (provider === undefined) {
    throw new ProtocolError("permessage-deflate was negotiated without a provider");
  }
  return provider;
}

/**
 * @internal Adopt an already-upgraded connection as the server end of a session.
 *
 * The handshake is the caller's: `acceptWebSocketUpgrade` decides the response and the
 * embedding HTTP server writes it and hands over the socket. What arrives here is a
 * byte stream that is already a WebSocket, so this only has to drive the shared
 * message engine from the other side.
 *
 * `reader` must be the reader that consumed the request head, so bytes a client sent
 * immediately after its handshake are not lost between the two.
 */
/**
 * Drives a client session over a connection somebody else obtained and validated.
 *
 * The mirror of {@link adoptServerWebSocketSession}, and it exists for the same reason:
 * masking is the only asymmetry in the framing, so the message engine takes a role
 * rather than being written twice. What differs here is only where the connection came
 * from — a transport that dispatched an upgrade through the HTTP stack ends up holding
 * exactly what {@link RawWebSocketTransport} holds after its own handshake.
 */
export function adoptClientWebSocketSession(options: {
  readonly connection: ByteConnection;
  readonly reader: BufferedReader;
  readonly handshake: ValidatedWebSocketHandshake;
  readonly deflate?: WebSocketDeflateProvider | undefined;
  readonly random: RandomSource;
  readonly scheduler: Scheduler;
  readonly transport?: RawWebSocketOptions;
  readonly onEnd?: () => void;
}): WebSocketSession {
  const end = options.onEnd;
  return new RawWebSocketSession(
    options.connection,
    options.reader,
    options.handshake,
    options.deflate,
    options.random,
    options.scheduler,
    options.transport ?? {},
    () => {
      if (end !== undefined) end();
    },
    "client",
  );
}

export function adoptServerWebSocketSession(options: {
  readonly connection: ByteConnection;
  readonly reader: BufferedReader;
  readonly protocol: string;
  readonly extensions: string;
  readonly perMessageDeflate: PerMessageDeflateNegotiation | null;
  readonly deflate?: WebSocketDeflateProvider | undefined;
  readonly random: RandomSource;
  readonly scheduler: Scheduler;
  readonly transport?: RawWebSocketOptions;
  readonly onEnd?: () => void;
}): WebSocketSession {
  const end = options.onEnd;
  return new RawWebSocketSession(
    options.connection,
    options.reader,
    {
      protocol: options.protocol,
      extensions: options.extensions,
      perMessageDeflate: options.perMessageDeflate,
    },
    options.deflate,
    options.random,
    options.scheduler,
    options.transport ?? {},
    () => {
      if (end !== undefined) end();
    },
    "server",
  );
}

import { DOMException } from "../core/errors.ts";
import { utf8Length } from "../core/utf8.ts";
import {
  coerceToDOMString,
  coerceToUSVString,
  requireDictionary,
  toClampedUnsignedShort,
} from "../core/webidl.ts";
import { isToken } from "../fetch/headers.ts";
import type { URLParser, URLRecord } from "../provider/primitives.ts";

export interface WebSocketURLContext {
  readonly urls: URLParser;
  readonly baseURL?: string;
}

export interface WebSocketCloseInfo {
  closeCode?: number;
  reason?: string;
}

export interface NormalizedWebSocketClose {
  readonly closeCode: number | null;
  readonly reason: string;
}

function isObject(value: unknown): value is object {
  return value !== null && (typeof value === "object" || typeof value === "function");
}

/** Convert the WebSocket constructor's DOMString-or-sequence union. */
export function convertWebSocketProtocolUnion(input: unknown): string[] {
  // Only undefined selects the optional argument's default sequence.
  // https://webidl.spec.whatwg.org/#es-overloads
  if (input === undefined) return [];
  // GetMethod selects the sequence branch only for an object with an iterator.
  // https://webidl.spec.whatwg.org/#es-union
  if (isObject(input)) {
    const method = (input as { [Symbol.iterator]?: unknown })[Symbol.iterator];
    if (method !== undefined && method !== null) {
      if (typeof method !== "function") throw new TypeError("WebSocket protocols iterator must be callable");
      const iterator = method.call(input) as Iterator<unknown>;
      if (!isObject(iterator)) throw new TypeError("WebSocket protocols iterator must be an object");
      const next = iterator.next;
      if (typeof next !== "function") throw new TypeError("WebSocket protocols iterator must have a next method");
      const values: string[] = [];
      // Convert every element before token validation. Web IDL sequence conversion
      // does not IteratorClose when an element conversion throws.
      // https://webidl.spec.whatwg.org/#create-sequence-from-iterable
      while (true) {
        const result = next.call(iterator) as IteratorResult<unknown>;
        if (!isObject(result)) throw new TypeError("WebSocket protocols iterator result must be an object");
        if (result.done) return values;
        values.push(coerceToDOMString(result.value));
      }
    }
  }
  return [coerceToDOMString(input)];
}

/** Apply the URL conversion and validation shared by both WebSocket APIs. */
export function normalizeWebSocketURL(input: unknown, context: WebSocketURLContext): URLRecord {
  const value = coerceToUSVString(input);
  let parsed: URLRecord;
  try {
    parsed = context.urls.parse(value, context.baseURL);
    if (parsed.protocol === "http:" || parsed.protocol === "https:") {
      parsed = context.urls.parse(
        (parsed.protocol === "http:" ? "ws:" : "wss:") + parsed.href.slice(parsed.protocol.length),
      );
    }
  } catch {
    throw new DOMException("Invalid WebSocket URL", "SyntaxError");
  }
  if ((parsed.protocol !== "ws:" && parsed.protocol !== "wss:") || parsed.href.includes("#")) {
    throw new DOMException("WebSocket requires a ws(s) URL without a fragment", "SyntaxError");
  }
  return parsed;
}

/** Convert and validate the RFC 6455 protocol offer list. */
export function normalizeWebSocketProtocols(input: string | Iterable<string>): string[] {
  const values = typeof input === "string" ? [input] : input;
  const protocols: string[] = [];
  const seen = new Set<string>();
  for (const value of values) {
    const protocol = coerceToDOMString(value);
    if (!isToken(protocol)) {
      throw new DOMException("Invalid or duplicate WebSocket subprotocol", "SyntaxError");
    }
    // The token is ASCII. Match deployed duplicate detection without changing
    // its spelling in the offer; WebSockets 3.1 step 9 does not specify folding.
    const key = protocol.toLowerCase();
    if (seen.has(key)) {
      throw new DOMException("Invalid or duplicate WebSocket subprotocol", "SyntaxError");
    }
    protocols.push(protocol);
    seen.add(key);
  }
  return protocols;
}

/** Convert a WebSocketStream close dictionary, including reason-only defaulting. */
export function normalizeWebSocketCloseInfo(
  input: WebSocketCloseInfo | null | undefined,
): NormalizedWebSocketClose {
  requireDictionary(input, "WebSocket close options");
  const closeCode = input?.closeCode;
  const reasonValue = input?.reason;
  const reason = coerceToUSVString(reasonValue === undefined ? "" : reasonValue);
  return validateWebSocketClose(
    closeCode === undefined ? null : toClampedUnsignedShort(closeCode),
    reason,
  );
}

/** Convert the positional WebSocket.close() arguments. */
export function normalizeWebSocketCloseArguments(
  code: number | undefined,
  reason: string,
): NormalizedWebSocketClose {
  return validateWebSocketClose(
    code === undefined ? null : toClampedUnsignedShort(code),
    coerceToUSVString(reason),
  );
}

function validateWebSocketClose(
  closeCode: number | null,
  reason: string,
): NormalizedWebSocketClose {
  let code = closeCode;
  if (code !== null && code !== 1000 && (code < 3000 || code > 4999)) {
    throw new DOMException("Close code must be 1000 or 3000..4999", "InvalidAccessError");
  }
  if (utf8Length(reason) > 123) {
    throw new DOMException("Close reason exceeds 123 UTF-8 bytes", "SyntaxError");
  }
  if (code === null && reason !== "") code = 1000;
  return { closeCode: code, reason };
}

import { forgivingBase64Decode } from "../core/base64.ts";
import { encodeByteString } from "../core/encoding.ts";
import { Headers } from "../fetch/headers.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import { hasToken } from "../http/fields.ts";
import { websocketAccept } from "./handshake.ts";
import { negotiatePerMessageDeflateOffer } from "./permessage-deflate.ts";
import type { PerMessageDeflateServerNegotiation } from "./permessage-deflate.ts";

/** The only version RFC 6455 defines, and the only one this server speaks. */
const VERSION = "13";

export interface WebSocketUpgradeOptions {
  /**
   * Subprotocols this server supports, in the server's order of preference.
   *
   * Selection is the server's choice among what the client offered, so the server's
   * order wins rather than the client's. Omitting this declines every offer, which is
   * what a server that speaks no subprotocol must do.
   */
  readonly protocols?: readonly string[];
  /**
   * Negotiate `permessage-deflate` when the client offers it.
   *
   * Off by default, because a handshake that agrees to compression the embedder cannot
   * perform produces a session neither side can read. Turn it on only alongside a
   * deflate provider, and use the returned negotiation to configure it.
   */
  readonly perMessageDeflate?: boolean;
}

export interface WebSocketUpgradeAccepted {
  readonly accepted: true;
  readonly status: 101;
  readonly statusText: string;
  readonly headers: readonly HeaderEntry[];
  /** The selected subprotocol, or null when none was selected. */
  readonly protocol: string | null;
  /**
   * The agreed compression parameters, or null when compression was declined.
   *
   * Returned rather than merely echoed in a header: the embedder has to configure its
   * codec with exactly what was agreed, and re-parsing its own response to find out
   * would be a second implementation of the same decision.
   */
  readonly perMessageDeflate: PerMessageDeflateServerNegotiation | null;
}

export interface WebSocketUpgradeRefused {
  readonly accepted: false;
  readonly status: number;
  readonly statusText: string;
  readonly headers: readonly HeaderEntry[];
  /** Why it was refused. Diagnostic text, not a wire value. */
  readonly reason: string;
}

export type WebSocketUpgradeOutcome = WebSocketUpgradeAccepted | WebSocketUpgradeRefused;

function refuse(
  status: number,
  statusText: string,
  reason: string,
  extra: readonly HeaderEntry[] = [],
): WebSocketUpgradeRefused {
  return {
    accepted: false,
    status,
    statusText,
    reason,
    headers: [...extra, ["connection", "close"]],
  };
}

/**
 * Whether a client's `Sec-WebSocket-Key` is well formed.
 *
 * The RFC defines it as the base64 encoding of sixteen random bytes. The accept value
 * is computed from the literal string either way, so a malformed key would still
 * produce a handshake both sides agree on — which is exactly why it is checked here
 * rather than left to work by accident.
 */
function isWellFormedKey(key: string): boolean {
  if (key.length === 0) return false;
  for (let index = 0; index < key.length; index++) {
    const code = key.charCodeAt(index);
    // No whitespace, and nothing outside the base64 alphabet's byte range.
    if (code <= 0x20 || code > 0x7e) return false;
  }
  const decoded = forgivingBase64Decode(encodeByteString(key));
  return decoded !== null && decoded.length === 16;
}

/** Comma-separated subprotocol tokens, in the order the client offered them. */
function offeredProtocols(header: string | null): readonly string[] {
  if (header === null) return [];
  const offered: string[] = [];
  for (const piece of header.split(",")) {
    const token = piece.trim();
    if (token !== "") offered.push(token);
  }
  return offered;
}

/**
 * Decides a server's response to a WebSocket upgrade request.
 *
 * This is the handshake only: it validates the request and produces the response
 * headers, and performs no I/O. The caller owns reading the request, writing the
 * response, and taking over the connection, because those belong to whatever HTTP
 * server this is embedded in.
 *
 * Every refusal is a real HTTP response rather than a dropped connection, so a client
 * learns why. A wrong version is the one refusal the RFC gives a specific shape: it
 * must advertise the version the server does speak.
 */
export function acceptWebSocketUpgrade(
  method: string,
  requestHeaders: Headers | readonly HeaderEntry[],
  options: WebSocketUpgradeOptions = {},
): WebSocketUpgradeOutcome {
  const headers =
    requestHeaders instanceof Headers ? requestHeaders : new Headers([...requestHeaders]);

  if (method !== "GET") {
    return refuse(405, "Method Not Allowed", "A WebSocket upgrade must be a GET", [
      ["allow", "GET"],
    ]);
  }
  if (!hasToken(headers, "upgrade", "websocket")) {
    return refuse(400, "Bad Request", "Upgrade must name websocket");
  }
  if (!hasToken(headers, "connection", "upgrade")) {
    return refuse(400, "Bad Request", "Connection must contain the Upgrade token");
  }
  const version = headers.get("sec-websocket-version");
  if (version === null || version.trim() !== VERSION) {
    // The RFC requires the supported version to be advertised, so a client can retry
    // knowing what to send rather than guessing.
    return refuse(426, "Upgrade Required", "Unsupported WebSocket version", [
      ["sec-websocket-version", VERSION],
    ]);
  }
  const key = headers.get("sec-websocket-key");
  if (key === null || !isWellFormedKey(key.trim())) {
    return refuse(400, "Bad Request", "Sec-WebSocket-Key must be sixteen base64 bytes");
  }

  const supported = options.protocols ?? [];
  const offered = offeredProtocols(headers.get("sec-websocket-protocol"));
  let protocol: string | null = null;
  for (const candidate of supported) {
    if (offered.includes(candidate)) {
      protocol = candidate;
      break;
    }
  }

  const responseHeaders: HeaderEntry[] = [
    ["upgrade", "websocket"],
    ["connection", "Upgrade"],
    ["sec-websocket-accept", websocketAccept(key.trim())],
  ];
  if (protocol !== null) responseHeaders.push(["sec-websocket-protocol", protocol]);
  // Declining is always valid, and is what an absent offer, an unusable one, or a
  // server that cannot compress all produce.
  const deflate =
    options.perMessageDeflate === true
      ? negotiatePerMessageDeflateOffer(headers.get("sec-websocket-extensions"))
      : null;
  if (deflate !== null) responseHeaders.push(["sec-websocket-extensions", deflate.response]);
  return {
    accepted: true,
    status: 101,
    statusText: "Switching Protocols",
    headers: responseHeaders,
    protocol,
    perMessageDeflate: deflate,
  };
}

/** Serializes an outcome as an HTTP/1.1 response head, including the blank line. */
export function serializeUpgradeResponse(outcome: WebSocketUpgradeOutcome): string {
  let head = "HTTP/1.1 " + String(outcome.status) + " " + outcome.statusText + "\r\n";
  for (const [name, value] of outcome.headers) head += name + ": " + value + "\r\n";
  return head + "\r\n";
}

import { adoptServerWebSocketSession } from "./raw-transport.ts";
import type { RawWebSocketOptions } from "./raw-transport.ts";
import { acceptWebSocketUpgrade, serializeUpgradeResponse } from "./server-handshake.ts";
import type { WebSocketUpgradeOptions } from "./server-handshake.ts";
import type { WebSocketDeflateProvider } from "./transport.ts";
import type { WebSocketSession } from "./transport.ts";
import { encodeByteString } from "../core/encoding.ts";
import type { HeaderEntry } from "../fetch/headers.ts";
import { BufferedReader, writeAll } from "../http1/io.ts";
import type { ByteConnection, RandomSource, Scheduler } from "../provider/primitives.ts";

/** RFC 6455 close code for a server shutting down. */
const GOING_AWAY = 1001;

export interface WebSocketServerOptions extends WebSocketUpgradeOptions {
  readonly random: RandomSource;
  readonly scheduler: Scheduler;
  /** Required only when {@link WebSocketUpgradeOptions.perMessageDeflate} is enabled. */
  readonly deflate?: WebSocketDeflateProvider;
  readonly transport?: RawWebSocketOptions;
  /**
   * Live sessions this server will hold at once.
   *
   * A refusal above this bound is an HTTP response rather than a dropped connection,
   * so a client learns it was turned away rather than timing out. Unbounded is not an
   * option: a server that accepts every upgrade has no way to shed load.
   */
  readonly maxConnections?: number;
}

/** What an upgrade attempt produced. */
export type WebSocketUpgradeResult =
  | {
      readonly accepted: true;
      readonly session: WebSocketSession;
      readonly protocol: string | null;
    }
  | { readonly accepted: false; readonly status: number; readonly reason: string };

/**
 * Owns the lifetime of server-side WebSocket sessions.
 *
 * It is deliberately not an accept loop. Listening, TLS, and HTTP request parsing
 * belong to the server this is embedded in, which already has them; what does not
 * exist anywhere else is something that knows how many sessions are open, refuses when
 * that is too many, and can close all of them once. That is what this is.
 */
export class WebSocketServer {
  readonly #options: WebSocketServerOptions;
  readonly #sessions = new Set<WebSocketSession>();
  readonly #maxConnections: number;
  #accepting = true;
  #closeResult: Promise<void> | null = null;

  constructor(options: WebSocketServerOptions) {
    this.#options = options;
    this.#maxConnections = options.maxConnections ?? 1024;
    if (!Number.isSafeInteger(this.#maxConnections) || this.#maxConnections < 1) {
      throw new RangeError("maxConnections must be a positive safe integer");
    }
  }

  /** Sessions currently open. */
  get connections(): number {
    return this.#sessions.size;
  }

  get accepting(): boolean {
    return this.#accepting;
  }

  /**
   * Completes an upgrade on an already-read request and adopts the session.
   *
   * The response is written here rather than returned, because the handshake and the
   * first frame share one connection and one reader: handing the response back would
   * let a caller write it late, or not at all, while this object already believed the
   * session was live.
   */
  async upgrade(
    method: string,
    requestHeaders: readonly HeaderEntry[],
    connection: ByteConnection,
    reader: BufferedReader,
  ): Promise<WebSocketUpgradeResult> {
    if (!this.#accepting) {
      return this.#refuse(connection, 503, "Service Unavailable", "The server is closing");
    }
    if (this.#sessions.size >= this.#maxConnections) {
      return this.#refuse(connection, 503, "Service Unavailable", "Too many open connections");
    }
    const outcome = acceptWebSocketUpgrade(method, requestHeaders, this.#options);
    await writeAll(connection, encodeByteString(serializeUpgradeResponse(outcome)));
    if (!outcome.accepted) {
      connection.close();
      return { accepted: false, status: outcome.status, reason: outcome.reason };
    }
    // Registration happens before the session is handed out, so a caller that starts
    // reading immediately cannot retire a session this server has not counted.
    const session: WebSocketSession = adoptServerWebSocketSession({
      connection,
      reader,
      protocol: outcome.protocol ?? "",
      extensions: outcome.perMessageDeflate?.response ?? "",
      perMessageDeflate: outcome.perMessageDeflate,
      deflate: this.#options.deflate,
      random: this.#options.random,
      scheduler: this.#options.scheduler,
      transport: this.#options.transport,
      onEnd: () => {
        this.#sessions.delete(session);
      },
    });
    this.#sessions.add(session);
    return { accepted: true, session, protocol: outcome.protocol };
  }

  /**
   * Stops accepting and closes every open session with the going-away code.
   *
   * Waits for each close to settle, so completion means no session is still writing.
   * Repeated calls share one result rather than starting a second shutdown.
   */
  close(): Promise<void> {
    if (this.#closeResult !== null) return this.#closeResult;
    this.#accepting = false;
    this.#closeResult = this.#finishClose();
    return this.#closeResult;
  }

  /** Stops accepting and abandons every session without a close handshake. */
  destroy(): void {
    this.#accepting = false;
    for (const session of this.#sessions) session.abort();
    this.#sessions.clear();
  }

  async #finishClose(): Promise<void> {
    // A snapshot, because closes are started together and a `Set` cannot be mapped.
    // Concurrency here is a preference rather than a requirement: shutting down
    // sequentially passes these tests too, and the comment says so rather than
    // claiming a property nothing checks.
    const open = [...this.#sessions];
    await Promise.all(
      open.map((session) =>
        session.close(GOING_AWAY, "").then(
          () => {},
          () => {},
        ),
      ),
    );
    this.#sessions.clear();
  }

  async #refuse(
    connection: ByteConnection,
    status: number,
    statusText: string,
    reason: string,
  ): Promise<WebSocketUpgradeResult> {
    const head = "HTTP/1.1 " + String(status) + " " + statusText + "\r\nconnection: close\r\n\r\n";
    try {
      await writeAll(connection, encodeByteString(head));
    } catch {
      // The refusal stands whether or not the peer was still there to read it.
    }
    connection.close();
    return { accepted: false, status, reason };
  }
}

import type { AbortSignal } from "../core/abort.ts";
import type { URLRecord } from "../provider/primitives.ts";

export type SocketMessage = { kind: "text"; data: string } | { kind: "binary"; data: Uint8Array };

export interface SocketClose {
  kind: "close";
  code: number;
  reason: string;
  wasClean: boolean;
  failed: boolean;
}

export type SocketIncoming = SocketMessage | SocketClose;

export interface WebSocketHandshake {
  url: URLRecord;
  protocols: readonly string[];
  origin: string;
}

/**
 * One provider-owned raw-DEFLATE context. `process()` performs a synchronous
 * flush and returns every byte produced by that flush. The caller supplies a
 * hard output bound; providers must stop before retaining unbounded output.
 */
export interface WebSocketDeflateContext {
  process(input: Uint8Array, maxOutputBytes: number): Promise<Uint8Array>;

  reset(): void;

  close(): void;
}

/** Native raw-DEFLATE contexts; RFC 7692 framing and policy remain shared. */
export interface WebSocketDeflateProvider {
  createDeflater(windowBits: number): WebSocketDeflateContext;

  createInflater(windowBits: number): WebSocketDeflateContext;
}

/** Public WebSocket state does not know whether the provider owns RFC 6455 framing. */
export interface WebSocketSession {
  readonly protocol: string;
  readonly extensions: string;

  next(): Promise<SocketIncoming>;

  send(message: SocketMessage): Promise<void>;

  close(code: number | null, reason: string): Promise<void>;

  abort(): void;
}

export interface WebSocketTransport {
  connect(handshake: WebSocketHandshake, signal: AbortSignal): Promise<WebSocketSession>;
}

import { AbortController, AbortSignal } from "../core/abort.ts";
import { DOMException } from "../core/errors.ts";
import { checkNetworkPort } from "../core/network-port.ts";
import { ignoreRejection } from "../core/promise.ts";
import {
  coerceToDOMString,
  coerceToUSVString,
  requireArguments,
  requireDictionary,
} from "../core/webidl.ts";
import { currentWebPlatformRuntime } from "../provider/environment.ts";
import type { Scheduler, URLRecord } from "../provider/primitives.ts";
import { ReadableStream, type ReadableStreamDefaultController } from "../streams/readable.ts";
import { WritableStream, type WritableStreamDefaultController } from "../streams/writable.ts";
import {
  normalizeWebSocketCloseInfo,
  normalizeWebSocketProtocols,
  normalizeWebSocketURL,
  type NormalizedWebSocketClose,
  type WebSocketCloseInfo,
  type WebSocketURLContext,
} from "./semantics.ts";
import type {
  SocketClose,
  SocketIncoming,
  SocketMessage,
  WebSocketSession,
  WebSocketTransport,
} from "./transport.ts";
import { abortSignalSubscribe } from "../core/abort.ts";
import { webSocketCloseForRuntime } from "./websocket.ts";

export type { WebSocketCloseInfo } from "./semantics.ts";

export type WebSocketStreamData = string | Uint8Array;

export type WebSocketStreamSendData = string | ArrayBuffer | ArrayBufferView;

export interface WebSocketStreamOptions {
  protocols?: Iterable<string>;
  signal?: AbortSignal;
}

export interface WebSocketOpenInfo {
  readonly readable: ReadableStream<WebSocketStreamData>;
  readonly writable: WritableStream<unknown>;
  readonly extensions: string;
  readonly protocol: string;
}

export interface WebSocketStreamContext extends WebSocketURLContext {
  readonly scheduler: Scheduler;
  readonly transport: WebSocketTransport;
  readonly origin?: string;
  registerWebSocketStream(stream: WebSocketStream): void;
  unregisterWebSocketStream(stream: WebSocketStream): void;
}

const internalErrorKey: unique symbol = Symbol("construct internal WebSocketError");

interface InternalErrorInit {
  readonly closeCode: number | null;
  readonly key: typeof internalErrorKey;
  readonly reason: string;
}

/** The error type used by the WebSocketStream proposal. */
export class WebSocketError extends DOMException {
  readonly closeCode: number | null;
  readonly reason: string;

  constructor(message?: string, options?: WebSocketCloseInfo | null);
  /** @internal */ constructor(
    message: string,
    options: WebSocketCloseInfo | null | undefined,
    internal: InternalErrorInit,
  );
  constructor(
    ...args: [message?: string, options?: WebSocketCloseInfo | null, internal?: InternalErrorInit]
  ) {
    super(coerceToDOMString(args[0] === undefined ? "" : args[0]), "WebSocketError");
    const internal = args[2];
    if (internal?.key === internalErrorKey) {
      this.closeCode = internal.closeCode;
      this.reason = internal.reason;
      return;
    }
    const close = normalizeWebSocketCloseInfo(args[1]);
    this.closeCode = close.closeCode;
    this.reason = close.reason;
  }
}

type ConnectionState = "connecting" | "open" | "closing" | "closed";
type CloseOrigin = "public" | "readable-cancel" | "writable-abort" | "writable-close";

const webSocketStreamConstructorKey: unique symbol = Symbol("construct NTS WebSocketStream");

/** A backpressure-aware WebSocket exposed as a readable/writable stream pair. */
export class WebSocketStream {
  readonly url: string;
  readonly opened: Promise<WebSocketOpenInfo>;
  readonly closed: Promise<WebSocketCloseInfo>;

  readonly #context: WebSocketStreamContext;
  readonly #connectionController = new AbortController();
  readonly #openedCapability = Promise.withResolvers<WebSocketOpenInfo>();
  readonly #closedCapability = Promise.withResolvers<WebSocketCloseInfo>();
  readonly #closeCapability = Promise.withResolvers<void>();
  #state: ConnectionState = "connecting";
  #session: WebSocketSession | null = null;
  #readable: ReadableStream<WebSocketStreamData> | null = null;
  #writable: WritableStream<unknown> | null = null;
  #readableController: ReadableStreamDefaultController<WebSocketStreamData> | null = null;
  #writableController: WritableStreamDefaultController<unknown> | null = null;
  #removeAbortAlgorithm: (() => void) | null = null;
  #connectionFailure: WebSocketError | null = null;
  #readInFlight = false;
  #readCompletion: PromiseWithResolvers<void> | null = null;
  #readDeliversMessage = false;
  #pendingIncoming: SocketIncoming | null = null;
  #pendingReadFailure: WebSocketError | null = null;
  #writeCompletion: PromiseWithResolvers<void> | null = null;
  #pendingCloseFailure: WebSocketError | null = null;
  #readableTerminal = false;
  #writableTerminal = false;
  #closeOrigin: CloseOrigin | null = null;
  #pendingWrites = 0;
  #hasUnwrittenData = false;
  #terminalWriteError: unknown = null;
  #registered = false;

  // Draft sections 4.1 and 4.2 use the WebSocket task source. These callbacks
  // are allocated once per stream; the receive and write slots each hold at
  // most one operation, without copying its payload or closing over a frame.
  readonly #onConnected = (session: WebSocketSession): void => {
    if (this.#state !== "connecting") {
      session.abort();
      return;
    }
    // Signal abort applies to the handshake, which is already established
    // even though its feedback task has not published opened yet.
    this.#removeAbortAlgorithm?.();
    this.#removeAbortAlgorithm = null;
    this.#session = session;
    this.#context.scheduler.enqueue(this.#runConnectionTask);
  };

  readonly #onConnectionFailed = (reason: unknown): void => {
    if (this.#state !== "connecting") return;
    this.#connectionFailure = connectionError(reason);
    this.#context.scheduler.enqueue(this.#runConnectionTask);
  };

  readonly #runConnectionTask = (): void => {
    const error = this.#connectionFailure;
    this.#connectionFailure = null;
    const session = this.#session;
    if (this.#state !== "connecting") {
      session?.abort();
      return;
    }
    if (error !== null) {
      this.#failBeforeOpen(error);
      return;
    }
    if (session === null) {
      this.#failBeforeOpen(new WebSocketError("WebSocketStream is not connected"));
      return;
    }
    this.#state = "open";
    try {
      this.#createStreams();
      const readable = this.#readable;
      const writable = this.#writable;
      if (readable === null || writable === null) {
        throw new Error("WebSocketStream failed to create its streams");
      }
      this.#openedCapability.resolve({
        readable,
        writable,
        extensions: session.extensions,
        protocol: session.protocol,
      });
    } catch (reason) {
      const failure = connectionError(reason);
      this.#openedCapability.reject(failure);
      this.#finishFailure(failure);
    }
  };

  readonly #onIncoming = (incoming: SocketIncoming): void => {
    if (!this.#readInFlight) return;
    this.#pendingIncoming = incoming;
    this.#context.scheduler.enqueue(this.#runReadTask);
  };

  readonly #onReadFailed = (reason: unknown): void => {
    if (!this.#readInFlight) return;
    this.#pendingReadFailure = connectionError(reason);
    this.#context.scheduler.enqueue(this.#runReadTask);
  };

  readonly #runReadTask = (): void => {
    const incoming = this.#pendingIncoming;
    const error = this.#pendingReadFailure;
    this.#pendingIncoming = null;
    this.#pendingReadFailure = null;
    try {
      if (this.#state === "closed" || !this.#readInFlight) {
        this.#completeRead();
      } else if (error !== null) {
        this.#finishFailure(error);
      } else if (incoming?.kind === "close") {
        this.#finishFromPeer(incoming);
        this.#completeRead();
      } else if (incoming !== null) {
        if (this.#readDeliversMessage && this.#state === "open" && !this.#readableTerminal) {
          this.#readableController?.enqueue(incoming.data);
          this.#completeRead();
        } else {
          this.#readDeliversMessage = false;
          this.#requestRead();
        }
      }
    } catch (reason) {
      this.#finishFailure(connectionError(reason));
    }
  };

  readonly #onSent = (): void => {
    if (this.#writeCompletion !== null) this.#context.scheduler.enqueue(this.#runWriteTask);
  };

  readonly #onSendFailed = (_reason: unknown): void => {
    if (this.#writeCompletion === null) return;
    if (this.#terminalWriteError !== null) {
      this.#rejectWrite(this.#terminalWriteError);
      return;
    }
    const error = invalidStateError();
    this.#terminalWriteError = error;
    this.#hasUnwrittenData = true;
    if (this.#state === "open") {
      // A concurrent read is authoritative for the peer's close code. Raw
      // transports commonly reject the write just before that read settles.
      this.#state = "closing";
      this.#ensureCloseDrain();
    }
    this.#rejectWrite(error);
  };

  readonly #runWriteTask = (): void => {
    const completion = this.#writeCompletion;
    if (completion === null) return;
    this.#writeCompletion = null;
    this.#pendingWrites--;
    completion.resolve();
  };

  readonly #onCloseFailed = (reason: unknown): void => {
    if (this.#state === "closed" || this.#pendingCloseFailure !== null) return;
    this.#pendingCloseFailure = connectionError(reason);
    this.#context.scheduler.enqueue(this.#runCloseFailureTask);
  };

  readonly #runCloseFailureTask = (): void => {
    const error = this.#pendingCloseFailure;
    this.#pendingCloseFailure = null;
    if (error !== null) this.#finishFailure(error);
  };

  constructor(url: string, options?: WebSocketStreamOptions | null);
  /** @internal Reached only through {@link createInternalWebSocketStream}. */ constructor(
    url: string,
    options: WebSocketStreamOptions | null | undefined,
    key: typeof webSocketStreamConstructorKey,
    context: WebSocketStreamContext,
  );
  constructor(
    ...args: [
      url: string,
      options?: WebSocketStreamOptions | null,
      key?: typeof webSocketStreamConstructorKey,
      context?: WebSocketStreamContext,
    ]
  ) {
    requireArguments(args, 1, "WebSocketStream constructor");
    requireDictionary(args[1], "WebSocketStream options");
    // The public API is `(url, options)`. Surplus arguments are ignored because the
    // construction key is module-private and therefore unforgeable by script, so a
    // caller cannot substitute the transports, proxy policy or scheduler in use.
    const supplied = args[3];
    const context =
      args[2] === webSocketStreamConstructorKey && supplied !== undefined
        ? supplied
        : currentWebPlatformRuntime();
    const parsed = normalizeWebSocketURL(args[0], context);
    const protocols = readProtocols(args[1]?.protocols);
    const signal = args[1]?.signal;
    if (signal !== undefined && !(signal instanceof AbortSignal)) {
      throw new TypeError("WebSocketStream signal must be an AbortSignal");
    }

    this.url = parsed.href;
    this.opened = this.#openedCapability.promise;
    this.closed = this.#closedCapability.promise;
    this.#context = context;
    ignoreRejection(this.opened);
    ignoreRejection(this.closed);
    ignoreRejection(this.#closeCapability.promise);
    context.registerWebSocketStream(this);
    this.#registered = true;

    if (signal?.aborted) {
      this.#failBeforeOpen(signal.reason);
      return;
    }
    if (signal !== undefined) {
      this.#removeAbortAlgorithm = signal[abortSignalSubscribe](() => {
        if (this.#state !== "connecting") return;
        this.#connectionController.abort(signal.reason);
        this.#failBeforeOpen(signal.reason);
      });
    }
    this.#connect(parsed, protocols);
  }

  close(options?: WebSocketCloseInfo | null): void {
    const close = normalizeWebSocketCloseInfo(options);
    this.#beginClose(close, "public");
  }

  [webSocketCloseForRuntime](): void {
    if (this.#state === "closed") return;
    const error = createConnectionError("Web-platform runtime is closed", {
      closeCode: 1006,
      reason: "",
    });
    this.#connectionController.abort(error);
    this.#session?.abort();
    this.#finishFailure(error);
  }

  #connect(url: URLRecord, protocols: readonly string[]): void {
    try {
      checkNetworkPort(url.port);
      this.#context.transport.connect(
        { url, protocols, origin: this.#context.origin ?? "null" },
        this.#connectionController.signal,
      ).then(this.#onConnected, this.#onConnectionFailed);
    } catch (reason) {
      this.#onConnectionFailed(reason);
    }
  }

  #createStreams(): void {
    const owner = this;
    this.#readable = new ReadableStream<WebSocketStreamData>(
      {
        start(controller) {
          owner.#readableController = controller;
        },
        pull() {
          return owner.#pull();
        },
        cancel(reason) {
          return owner.#cancelReadable(reason);
        },
      },
      { highWaterMark: 1 },
    );
    this.#writable = new WritableStream<unknown>(
      {
        start(controller) {
          owner.#writableController = controller;
        },
        write(chunk) {
          return owner.#write(chunk);
        },
        close() {
          return owner.#closeWritable();
        },
        abort(reason) {
          return owner.#abortWritable(reason);
        },
      },
      { highWaterMark: 1 },
    );
  }

  #pull(): void | Promise<void> {
    if (this.#state !== "open" || this.#readInFlight) return;
    return this.#receive(true);
  }

  #receive(deliverMessage: boolean): void | Promise<void> {
    const session = this.#session;
    if (session === null || this.#state === "closed" || this.#readInFlight) return;
    // One pull capability replaces the previous nested async pull/receive
    // promises and stays pending until the scheduled feedback has been handled.
    const completion = Promise.withResolvers<void>();
    this.#readCompletion = completion;
    this.#readInFlight = true;
    this.#readDeliversMessage = deliverMessage;
    this.#requestRead();
    return completion.promise;
  }

  #requestRead(): void {
    const session = this.#session;
    if (session === null || this.#state === "closed") {
      this.#completeRead();
      return;
    }
    try {
      session.next().then(this.#onIncoming, this.#onReadFailed);
    } catch (reason) {
      this.#onReadFailed(reason);
    }
  }

  #completeRead(): void {
    const completion = this.#readCompletion;
    this.#readCompletion = null;
    this.#readInFlight = false;
    this.#pendingIncoming = null;
    this.#pendingReadFailure = null;
    completion?.resolve();
    if (this.#state === "closing") this.#ensureCloseDrain();
  }

  #write(value: unknown): Promise<void> {
    if (this.#state !== "open") throw invalidStateError();
    const session = this.#session;
    if (session === null) throw invalidStateError();
    const message = snapshotMessage(value);
    // The draft's write promise is settled by the task, with no extra async
    // wrapper or per-write continuation closure around the provider promise.
    const completion = Promise.withResolvers<void>();
    this.#writeCompletion = completion;
    this.#pendingWrites++;
    try {
      session.send(message).then(this.#onSent, this.#onSendFailed);
    } catch (reason) {
      this.#onSendFailed(reason);
    }
    return completion.promise;
  }

  #rejectWrite(reason: unknown): void {
    const completion = this.#writeCompletion;
    if (completion === null) return;
    this.#writeCompletion = null;
    this.#pendingWrites--;
    completion.reject(reason);
  }

  #cancelReadable(reason: unknown): Promise<void> {
    // ReadableStream closes itself before it invokes the source cancel algorithm.
    this.#readableTerminal = true;
    const close = reason instanceof WebSocketError ? closeFromError(reason) : emptyClose();
    this.#beginClose(close, "readable-cancel");
    return Promise.resolve();
  }

  #closeWritable(): Promise<void> {
    return this.#beginClose(emptyClose(), "writable-close");
  }

  #abortWritable(reason: unknown): Promise<void> {
    const close = reason instanceof WebSocketError ? closeFromError(reason) : emptyClose();
    this.#beginClose(close, "writable-abort");
    return Promise.resolve();
  }

  #beginClose(close: NormalizedWebSocketClose, origin: CloseOrigin): Promise<void> {
