// A WebSocket server that listens, accepts and upgrades, end to end.
//
// This closes the largest row that was open in the plan. The handshake, the server-side
// session and the connection lifetime owner all existed; what did not was a way to get a
// connection in the first place, because the provider ABI had `connect` and no `listen`.
//
// Both peer lanes weighed in on that interface before it was written. The JVM lane
// measured `bind`, port 0 and `accept` on an API-26 device; the Node lane, which has
// written this adapter, corrected the backlog contract, the close semantics and the
// bound-address field. Every one of those decisions has a test here.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { connect } from "node:net";

import { AbortController } from "../src/index.ts";
import {
  serveWebSocketUpgrades,
  WebSocketServer,
} from "../src/provider.ts";
import {
  HostNodeScheduler,
  HostNodeSocketBinder,
  hostNodeRandom,
} from "../host/node-primitives.ts";
import type { ListenAddress, SocketListener } from "../src/provider/primitives.ts";
import type { WebSocketServerOptions } from "../src/websocket/server.ts";
import type { WebSocketSession } from "../src/websocket/transport.ts";
import type { Event } from "../src/index.ts";
import { MessageEvent } from "../src/index.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const none = () => new AbortController().signal;

function serverOf(t: TestContext, options: Partial<WebSocketServerOptions> = {}): WebSocketServer {
  const scheduler = new HostNodeScheduler(() => {});
  const server = new WebSocketServer({
    random: hostNodeRandom,
    scheduler,
    protocols: ["chat"],
    ...options,
  });
  t.after(() => server.close());
  return server;
}

async function listening(t: TestContext, options: Partial<ListenAddress> = {}): Promise<SocketListener> {
  const listener = await new HostNodeSocketBinder().listen(
    { hostname: "127.0.0.1", port: 0, ...options },
    none(),
  );
  t.after(() => listener.close());
  return listener;
}

suite("port zero is answered with the port that was bound", async (t) => {
  const listener = await listening(t);
  assert.equal(typeof listener.address.port, "number");
  assert.ok(listener.address.port > 0, "a real port, not the zero that was asked for");
  assert.equal(listener.address.hostname, "127.0.0.1");
});

suite("the bound address is the literal one, not the name that was asked for", async (t) => {
  // Asking for "127.0.0.1" cannot distinguish the two, because the request and the
  // literal are the same string. `localhost` can: it resolves to one family or the
  // other, and a caller that echoes the name back can reach the wrong one.
  const listener = await listening(t, { hostname: "localhost" });
  assert.notEqual(listener.address.hostname, "localhost");
  assert.match(listener.address.hostname, /^(127\.0\.0\.1|::1)$/);
});

suite("a bind failure rejects the listen rather than escaping as an event", async (t) => {
  const first = await listening(t);
  // Node reports this on `'error'` a tick after `listen()` returns. Wired to the call
  // instead, a taken port becomes an unhandled event on the server.
  await assert.rejects(
    () =>
      new HostNodeSocketBinder().listen(
        { hostname: "127.0.0.1", port: first.address.port },
        none(),
      ),
    // A thrown value is `unknown`, and only some carry a `code`; reading it through a
    // widened shape is what the untyped version was doing implicitly.
    (error: unknown) => String((error as { code?: unknown }).code ?? "") === "EADDRINUSE",
  );
});

suite("closing the listener resolves a waiting accept with null", async (t) => {
  const listener = await listening(t);
  const pending = listener.accept(none());
  listener.close();
  // A closed listener is a normal ending, so the obvious loop terminates rather than
  // needing a try/catch around every shutdown.
  assert.equal(await pending, null);
  assert.equal(await listener.accept(none()), null);
});

suite("aborting one accept rejects it and leaves the listener open", async (t) => {
  const listener = await listening(t);
  const controller = new AbortController();
  const reason = new Error("this caller changed its mind");
  const abandoned = listener.accept(controller.signal);
  controller.abort(reason);
  await assert.rejects(() => abandoned, (thrown) => thrown === reason);

  // The listener is still live: a second accept succeeds against a real connection.
  const accepted = listener.accept(none());
  const client = connect(listener.address.port, "127.0.0.1");
  t.after(() => client.destroy());
  const connection = await accepted;
  assert.ok(connection !== null, "the listener accepted a connection");
  connection.close();
});

suite("an already-aborted signal never reaches the accept", async (t) => {
  const listener = await listening(t);
  const controller = new AbortController();
  const reason = new Error("too late");
  controller.abort(reason);
  await assert.rejects(
    () => listener.accept(controller.signal),
    (thrown) => thrown === reason,
  );
});

suite("an aborted signal rejects even on a listener that is already closed", async (t) => {
  // This is the only case where checking the signal up front differs from relying on
  // the subscription: a closed listener answers `null`, and abort has to win, because
  // abort is about this call rather than about the listener.
  const listener = await listening(t);
  listener.close();
  const controller = new AbortController();
  const reason = new Error("aborted after close");
  controller.abort(reason);
  await assert.rejects(
    () => listener.accept(controller.signal),
    (thrown) => thrown === reason,
  );
});

suite("the loop serves a real WebSocket client over a real socket", async (t) => {
  const listener = await listening(t);
  const server = serverOf(t);
  const controller = new AbortController();
  // The shape `onSession` pushes, named so the accumulator is not `any[]`.
  const sessions: { session: WebSocketSession; target: string }[] = [];
  const errors: unknown[] = [];

  const loop = serveWebSocketUpgrades(listener, server, controller.signal, {
    onSession: (result, head) => {
      if (result.accepted) sessions.push({ session: result.session, target: head.target });
    },
    onError: (error: unknown) => errors.push(error),
  });
  t.after(async () => {
    controller.abort();
    listener.close();
    await loop;
  });

  // Drive the canonical client against it.
  const { createHostNodeWebPlatform } = await import("../host/node-runtime.ts"
  );
  const api = createHostNodeWebPlatform();
  t.after(() => api.close());
  const socket = api.createWebSocket(`ws://127.0.0.1:${listener.address.port}/`, ["chat"]);
  await new Promise((resolve, reject) => {
    socket.addEventListener("open", resolve);
    socket.addEventListener("error", () => reject(new Error("handshake refused")));
  });
  assert.equal(socket.protocol, "chat");
  assert.equal(server.connections, 1, "the server counted the session it owns");

  assert.equal(sessions.length, 1, "the loop handed the session to its caller");
  assert.equal(sessions[0]?.target, "/", "with the request head that produced it");

  const echoed = new Promise<unknown>((resolve) => {
    // `addEventListener` is typed with the base `Event`; a message event carries `data`, and
    // the listener narrows to it rather than the handler being widened.
    socket.addEventListener("message", (event: Event) => {
      resolve(event instanceof MessageEvent ? event.data : undefined);
    });
  });
  socket.send("through the accept loop");

  // The server side of the session is the embedder's to drive.
  const first = sessions[0];
  assert.ok(first !== undefined, "the loop handed over a session");
  const incoming = await first.session.next();
  assert.equal(incoming.kind, "text");
  assert.equal(incoming.data, "through the accept loop");
  await first.session.send(incoming);
  assert.equal(await echoed, "through the accept loop");

  socket.close(1000, "done");
  assert.deepEqual(errors, []);
});

suite("a connection that is not an upgrade is refused without stopping the loop", async (t) => {
  const listener = await listening(t);
  const server = serverOf(t);
  const controller = new AbortController();
  const errors = [];
  const malformed = Promise.withResolvers<void>();
  const loop = serveWebSocketUpgrades(listener, server, controller.signal, {
    onError: (error: unknown) => { errors.push(error); malformed.resolve(); },
  });
  t.after(async () => {
    controller.abort();
    listener.close();
    await loop;
  });

  // Plain HTTP, no upgrade headers: refused with a status, and the loop carries on.
  const CRLF = String.fromCharCode(13, 10);
  const plain = connect(listener.address.port, "127.0.0.1", () => {
    plain.write(`GET / HTTP/1.1${CRLF}Host: x${CRLF}${CRLF}`);
  });
  t.after(() => plain.destroy());
  const status = await new Promise<string>((resolve) => {
    let text = "";
    plain.on("data", (chunk) => {
      text += chunk.toString("latin1");
      // `split` always yields at least one element; the fallback says so without an assertion.
      if (text.includes(CRLF)) resolve(text.split(CRLF)[0] ?? "");
    });
    plain.on("error", () => resolve("error"));
  });
  assert.match(status, /^HTTP\/1\.1 (400|426)/, `refused with a status, got ${status}`);

  // And a connection that cannot even be parsed, which is the case that actually
  // reaches the loop's error path: a status refusal is a normal return, not a throw.
  const garbage = connect(listener.address.port, "127.0.0.1", () => {
    garbage.write(`not a request line at all${CRLF}${CRLF}`);
  });
  t.after(() => garbage.destroy());
  await malformed.promise;
  assert.ok(errors.length >= 1, "the malformed connection was reported");

  // And the loop is still serving: a real client connects afterwards.
  const { createHostNodeWebPlatform } = await import("../host/node-runtime.ts"
  );
  const api = createHostNodeWebPlatform();
  t.after(() => api.close());
  const socket = api.createWebSocket(`ws://127.0.0.1:${listener.address.port}/`, ["chat"]);
  await new Promise((resolve, reject) => {
    socket.addEventListener("open", resolve);
    socket.addEventListener("error", () => reject(new Error("the loop stopped serving")));
  });
  socket.close(1000, "done");
});

import test from "node:test";
import assert from "node:assert/strict";
import {
  AbortController,
  Agent,
  AgentOriginLimitError,
  AgentPendingLimitError,
  Client,
} from "../src/index.ts";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import type { OriginDispatcher } from "../src/dispatch/agent.ts";
import type {
  FetchTransport,
  TransportRequest,
  TransportResponse,
} from "../src/fetch/transport.ts";
import type { AbortSignal } from "../src/index.ts";
import { must } from "./harness.ts";

function request(
  origin: string,
  path = "/",
  signal: AbortSignal = new AbortController().signal,
): TransportRequest {
  const primitives = createHostNodePrimitives();
  return {
    url: primitives.urls.parse(origin + path),
    method: "GET",
    headers: [],
    body: null,
    bodyLength: null,
    signal,
  };
}

class FakeDispatcher implements OriginDispatcher {
  readonly origin: string;
  idle = true;
  readonly requests: TransportRequest[] = [];
  closeCalls = 0;
  readonly destroyReasons: unknown[] = [];
  /** Set by a test that wants `close()` to stay pending until it decides otherwise. */
  closeGate: PromiseWithResolvers<void> | null = null;
  stats = { connections: 1, pending: 0, running: 0 };

  constructor(origin: string) {
    this.origin = origin;
  }

  dispatch(value: TransportRequest): Promise<TransportResponse> {
    this.requests.push(value);
    return Promise.resolve({
      status: 200,
      statusText: this.origin,
      headers: [],
      body: null,
    });
  }

  close(): Promise<void> {
    this.closeCalls++;
    return this.closeGate?.promise ?? Promise.resolve();
  }

  destroy(reason?: unknown): Promise<void> {
    this.destroyReasons.push(reason);
    return Promise.resolve();
  }
}

/**
 * The dispatcher the agent created at `index`, asserted present.
 *
 * The tests index this list right after asserting how long it is, so the element is there --
 * saying so once beats a non-null assertion at each of the eight sites, and a run where the
 * agent created fewer than expected now fails with that sentence.
 */
function createdAt(state: { created: FakeDispatcher[] }, index: number): FakeDispatcher {
  const dispatcher = state.created[index];
  assert.ok(dispatcher !== undefined, `the agent did not create a dispatcher at ${index}`);
  return dispatcher;
}

function agent(options = {}) {
  const created: FakeDispatcher[] = [];
  const value = new Agent({
    factory: {
      create(origin) {
        const dispatcher = new FakeDispatcher(origin);
        created.push(dispatcher);
        return dispatcher;
      },
    },
    ...options,
  });
  return { agent: value, created };
}

test("Agent lazily creates and reuses one dispatcher per canonical origin", async () => {
  const state = agent();
  const one = await state.agent.dispatch(request("https://one.test", "/a"));
  const two = await state.agent.dispatch(request("https://one.test", "/b"));
  const three = await state.agent.dispatch(request("http://two.test"));
  assert.equal(one.statusText, "https://one.test");
  assert.equal(two.statusText, "https://one.test");
  assert.equal(three.statusText, "http://two.test");
  assert.equal(state.created.length, 2);
  assert.equal(createdAt(state, 0).requests.length, 2);
  assert.deepEqual(state.agent.stats, {
    origins: 2,
    idleOrigins: 2,
    connections: 2,
    pending: 0,
    running: 0,
    dispatched: 3,
    evicted: 0,
    pendingOriginAcquisitions: 0,
    entries: [
      {
        origin: "https://one.test",
        idle: true,
        connections: 1,
        pending: 0,
        running: 0,
      },
      {
        origin: "http://two.test",
        idle: true,
        connections: 1,
        pending: 0,
        running: 0,
      },
    ],
  });
});

test("bounded Agent evicts the least-recently-used idle origin and awaits close", async () => {
  const state = agent({ maximumOrigins: 2 });
  await state.agent.dispatch(request("https://old.test"));
  await state.agent.dispatch(request("https://recent.test"));
  await state.agent.dispatch(request("https://old.test"));
  const recent = createdAt(state, 1);
  recent.closeGate = Promise.withResolvers<void>();
  const pending = state.agent.dispatch(request("https://new.test"));
  await Promise.resolve();
  assert.equal(recent.closeCalls, 1);
  assert.equal(state.created.length, 2);
  recent.closeGate.resolve();
  await pending;
  assert.equal(state.created.length, 3);
  assert.deepEqual(
    state.agent.stats.entries.map((entry) => entry.origin),
    ["https://old.test", "https://new.test"],
  );
  assert.equal(state.agent.stats.evicted, 1);
});

test("a failed eviction close restores the old origin and preserves the bound", async () => {
  const state = agent({ maximumOrigins: 1 });
  await state.agent.dispatch(request("https://old.test"));
  const failure = new Error("close failed");
  createdAt(state, 0).closeGate = Promise.withResolvers<void>();
  const pending = state.agent.dispatch(request("https://new.test"));
  await Promise.resolve();
  must(createdAt(state, 0).closeGate, "the gate was just installed").reject(failure);
  await assert.rejects(pending, (error: unknown) => error === failure);
  assert.equal(state.created.length, 1);
  assert.equal(state.agent.stats.origins, 1);
  assert.equal(must(state.agent.stats.entries[0], "the agent kept one entry").origin, "https://old.test");
  assert.equal(state.agent.stats.evicted, 0);
});

test("origin pressure never evicts a dispatcher with live work", async () => {
  const state = agent({ maximumOrigins: 1 });
  await state.agent.dispatch(request("https://busy.test"));
  createdAt(state, 0).idle = false;
  await assert.rejects(
    state.agent.dispatch(request("https://blocked.test")),
    (error: unknown) =>
      error instanceof AgentOriginLimitError &&
      error.code === "UND_ERR_MAX_ORIGINS_REACHED" &&
      error.maximumOrigins === 1,
  );
  assert.equal(state.created.length, 1);
  assert.equal(createdAt(state, 0).closeCalls, 0);
});

test("an abort during serialized eviction does not create the replacement", async () => {
  const state = agent({ maximumOrigins: 1 });
  await state.agent.dispatch(request("https://old.test"));
  const closeGate = Promise.withResolvers<void>();
  createdAt(state, 0).closeGate = closeGate;
  const controller = new AbortController();
  const failure = new Error("stop waiting");
  const pending = state.agent.dispatch(request("https://new.test", "/", controller.signal));
  await Promise.resolve();
  controller.abort(failure);
  closeGate.resolve();
  await assert.rejects(pending, (error: unknown) => error === failure);
  assert.equal(state.created.length, 1);
  assert.equal(state.agent.stats.origins, 0);
});

test("the origin-creation queue has explicit bounded backpressure", async () => {
  const state = agent({ maximumOrigins: 1, maximumPendingOrigins: 1 });
  await state.agent.dispatch(request("https://old.test"));
  const closeGate = Promise.withResolvers<void>();
  createdAt(state, 0).closeGate = closeGate;
  const first = state.agent.dispatch(request("https://one.test"));
  await Promise.resolve();
  await assert.rejects(
    state.agent.dispatch(request("https://two.test")),
    (error: unknown) =>
      error instanceof AgentPendingLimitError &&
      error.code === "UND_ERR_AGENT_QUEUE_FULL" &&
      error.maximumPendingOrigins === 1,
  );
  assert.equal(state.agent.stats.pendingOriginAcquisitions, 1);
  closeGate.resolve();
  await first;
  assert.equal(state.agent.stats.pendingOriginAcquisitions, 0);
});

test("concurrent first requests serialize origin creation without duplicates", async () => {
  const state = agent();
  await Promise.all([
    state.agent.dispatch(request("https://same.test", "/one")),
    state.agent.dispatch(request("https://same.test", "/two")),
    state.agent.dispatch(request("https://same.test", "/three")),
  ]);
  assert.equal(state.created.length, 1);
  assert.equal(createdAt(state, 0).requests.length, 3);
});

test("Agent close is graceful, idempotent, and rejects new dispatch", async () => {
  const state = agent();
  await Promise.all([
    state.agent.dispatch(request("https://one.test")),
    state.agent.dispatch(request("https://two.test")),
  ]);
  const first = state.agent.close();
  const second = state.agent.close();
  assert.equal(first, second);
  assert.equal(state.agent.closed, true);
  await assert.rejects(state.agent.dispatch(request("https://three.test")), TypeError);
  await first;
  assert.equal(state.agent.destroyed, true);
  assert.deepEqual(
    state.created.map((dispatcher) => dispatcher.closeCalls),
    [1, 1],
  );
  assert.equal(state.agent.stats.origins, 0);
});

test("Agent destroy forwards the exact reason to every owned dispatcher", async () => {
  const state = agent();
  await Promise.all([
    state.agent.dispatch(request("https://one.test")),
    state.agent.dispatch(request("https://two.test")),
  ]);
  const reason = new Error("destroy now");
  const first = state.agent.destroy(reason);
  const second = state.agent.destroy(new Error("ignored"));
  assert.equal(first, second);
  await first;
  assert.equal(state.agent.closed, true);
  assert.equal(state.agent.destroyed, true);
  for (const dispatcher of state.created) {
    assert.deepEqual(dispatcher.destroyReasons, [reason]);
  }
});

test("Client enforces its canonical origin and owns lifecycle", async () => {
  const dispatcher = new FakeDispatcher("https://client.test");
  const client = new Client("https://client.test", dispatcher);
  assert.equal((await client.dispatch(request("https://client.test"))).status, 200);
  await assert.rejects(client.dispatch(request("https://other.test")), TypeError);
  assert.equal(client.stats, dispatcher.stats);
  const closing = client.close();
  assert.equal(closing, client.close());
  await closing;
  assert.equal(client.closed, true);
  assert.equal(client.destroyed, true);
  await assert.rejects(client.dispatch(request("https://client.test")), TypeError);
});

test("factory and synchronous dispatcher errors retain exact identity", async () => {
  const factoryFailure = new Error("factory failed");
  const broken = new Agent({
    factory: {
      create() {
        throw factoryFailure;
      },
    },
  });
  await assert.rejects(broken.dispatch(request("https://factory.test")), (error: unknown) => {
    return error === factoryFailure;
  });

  const dispatchFailure = new Error("dispatch failed");
  const dispatcher = new FakeDispatcher("https://client.test");
  dispatcher.dispatch = () => {
    throw dispatchFailure;
  };
  const client = new Client("https://client.test", dispatcher);
  await assert.rejects(client.dispatch(request("https://client.test")), (error: unknown) => {
    return error === dispatchFailure;
  });
});

test("Agent validates bounds and refuses non-network origins", async () => {
  assert.throws(() => agent({ maximumOrigins: 0 }), RangeError);
  assert.throws(() => agent({ maximumOrigins: 1.5 }), RangeError);
  assert.throws(() => agent({ maximumPendingOrigins: 0 }), RangeError);
  const state = agent();
  await assert.rejects(state.agent.dispatch(request("data:text/plain,hello")), TypeError);
  assert.equal(state.created.length, 0);
});

// Origin authentication: parsing challenges, and answering them exactly once.
//
// The plan asks for "authentication hooks with explicit ordering and ownership" and
// this lane had proxy authentication only. Proxy credentials are not origin credentials
// and the two must not be answered by the same thing: a hop that challenges is not
// necessarily the hop the caller has an account with.
//
// The parser is where the difficulty is. A comma separates both challenges and
// auth-params, so the same character means two things and only lookahead tells them
// apart.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import {
  AbortController,
  AuthenticationInterceptor,
  parseChallenges,
  ReadableStream,
  TextEncoder,
} from "../src/index.ts";
import { must } from "./harness.ts";
import type { HeaderEntry } from "../src/fetch/headers.ts";
import type {
  FetchTransport,
  TransportRequest,
  TransportResponse,
} from "../src/fetch/transport.ts";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import type {
  AuthenticationChallenge,
  AuthenticationContext,
} from "../src/dispatch/authenticate.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const encoder = new TextEncoder();

const schemes = (value: string): string[] =>
  parseChallenges(value).map((challenge) => challenge.scheme);
const paramsOf = (value: string, index = 0): readonly HeaderEntry[] | undefined =>
  parseChallenges(value)[index]?.parameters;

/** The challenge at `index`, asserted present -- every use here has just parsed one. */
function challengeAt(value: string, index = 0): AuthenticationChallenge {
  return must(parseChallenges(value)[index], `expected a challenge at ${index} in ${value}`);
}

suite("a single challenge with one parameter", () => {
  const challenge = challengeAt('Basic realm="simple"');
  assert.equal(challenge.scheme, "basic");
  assert.equal(challenge.token68, null);
  assert.deepEqual(challenge.parameters, [["realm", "simple"]]);
});

suite("a comma separates challenges and parameters, and lookahead tells them apart", () => {
  // One challenge: every comma is followed by `token=`.
  assert.deepEqual(schemes('Digest realm="a", qop="auth", nonce="x"'), ["digest"]);
  assert.deepEqual(paramsOf('Digest realm="a", qop="auth", nonce="x"'), [
    ["realm", "a"],
    ["qop", "auth"],
    ["nonce", "x"],
  ]);

  // Two challenges: the comma is followed by a bare token.
  assert.deepEqual(schemes('Basic realm="a", Bearer'), ["basic", "bearer"]);
  assert.deepEqual(schemes("Negotiate, Basic"), ["negotiate", "basic"]);
});

suite("RFC 7235's own ambiguous example parses as the RFC says", () => {
  // The example the specification uses to explain why this is hard, including an
  // escaped quote inside a parameter value.
  const value =
    'Newauth realm="apps", type=1, title="Login to \\"apps\\"", Basic realm="simple"';
  const parsed = parseChallenges(value);
  assert.deepEqual(
    parsed.map((challenge) => challenge.scheme),
    ["newauth", "basic"],
  );
  assert.deepEqual(must(parsed[0], "the header parsed to that many challenges").parameters, [
    ["realm", "apps"],
    ["type", "1"],
    ["title", 'Login to "apps"'],
  ]);
  assert.deepEqual(must(parsed[1], "the header parsed to that many challenges").parameters, [["realm", "simple"]]);
});

suite("a scheme with nothing after it is still a challenge", () => {
  assert.deepEqual(schemes("Negotiate"), ["negotiate"]);
  const challenge = challengeAt("Negotiate");
  assert.equal(challenge.token68, null);
  assert.deepEqual(challenge.parameters, []);
});

suite("token68 is kept apart from parameters", () => {
  // `Negotiate abc==` is an opaque credential, not a nameless parameter, and an
  // authenticator has to be able to tell the difference.
  const challenge = challengeAt("Negotiate a87421bK3bkfhk==");
  assert.equal(challenge.scheme, "negotiate");
  assert.equal(challenge.token68, "a87421bK3bkfhk==");
  assert.deepEqual(challenge.parameters, []);
});

suite("schemes and parameter names are matched case-insensitively", () => {
  const challenge = challengeAt('BASIC REALM="Kept As Sent"');
  assert.equal(challenge.scheme, "basic");
  // The name is folded because callers compare it; the value is not, because it is data.
  assert.deepEqual(challenge.parameters, [["realm", "Kept As Sent"]]);
});

suite("a bare token parameter value is read", () => {
  assert.deepEqual(paramsOf("Bearer error=invalid_token"), [["error", "invalid_token"]]);
});

suite("surrounding and repeated commas are tolerated", () => {
  assert.deepEqual(schemes(",, Basic ,, Bearer ,,"), ["basic", "bearer"]);
  assert.deepEqual(schemes(""), []);
  assert.deepEqual(schemes("   "), []);
  assert.deepEqual(schemes(","), []);
});

suite("a malformed tail keeps what was already understood", () => {
  // A field that cannot be fully parsed is not a reason to discard a challenge the
  // server did send -- refusing the lot would turn a server's sloppiness into a client
  // that cannot authenticate at all.
  assert.deepEqual(schemes('Basic realm="unterminated'), ["basic"]);
  assert.deepEqual(schemes('Basic realm="a", Bearer realm='), ["basic", "bearer"]);
  assert.deepEqual(paramsOf('Basic realm="a", Bearer realm=', 0), [["realm", "a"]]);
});

const urls = createHostNodePrimitives().urls;

function request(overrides: Partial<TransportRequest> = {}): TransportRequest {
  return {
    // A parsed record rather than a `{ href }` stub: `TransportRequest.url` is a `URLRecord`.
    url: urls.parse("https://auth.test/resource"),
    method: "GET",
    headers: [["accept", "*/*"]] as HeaderEntry[],
    body: null,
    bodyLength: null,
    signal: new AbortController().signal,
    ...overrides,
  };
}

function bodyOf(text: string): ReadableStream<Uint8Array> {
  return new ReadableStream<Uint8Array>({
    start(controller) {
      controller.enqueue(encoder.encode(text));
      controller.close();
    },
  });
}

/** Answers `401` until an `Authorization` header arrives, recording every attempt. */
/** What a test may vary about the challenging transport. */
interface ChallengeOptions {
  readonly acceptCredential?: boolean;
  readonly status?: number;
  readonly headers?: readonly HeaderEntry[];
}

function challengingTransport(options: ChallengeOptions = {}): FetchTransport & {
  seen: TransportRequest[];
  readonly cancelled: number;
  readonly drained: number;
} {
  const seen: TransportRequest[] = [];
  let cancelled = 0;
  let drained = 0;
  return {
    seen,
    get cancelled() {
      return cancelled;
    },
    /** Challenge bodies read all the way to their close. */
    get drained() {
      return drained;
    },
    async dispatch(value: TransportRequest): Promise<TransportResponse> {
      seen.push(value);
      const authorization = value.headers.find(([name]) => name === "authorization");
      if (authorization !== undefined && options.acceptCredential !== false) {
        return { status: 200, statusText: "OK", headers: [], body: null };
      }
      return {
        status: options.status ?? 401,
        statusText: "Unauthorized",
        headers: options.headers ?? [["www-authenticate", 'Basic realm="test"']],
        // A zero high-water mark, so `pull` fires only when something actually reads.
        // With the default of one, the stream prefetches on construction and `drained`
        // would count that rather than the interceptor -- which is how this assertion
        // was wrong the first time it was written.
        body: new ReadableStream(
          {
            pull(controller) {
              drained++;
              controller.enqueue(encoder.encode("please authenticate"));
              controller.close();
            },
            cancel() {
              cancelled++;
            },
          },
          { highWaterMark: 0 },
        ),
      };
    },
  };
}

suite("a challenge is answered once and the retry carries the credential", async () => {
  const transport = challengingTransport();
  const contexts: AuthenticationContext[] = [];
  const interceptor = new AuthenticationInterceptor({
    authenticate: (context: AuthenticationContext) => {
      contexts.push(context);
      return "Basic dXNlcjpwYXNz";
    },
  });

  const response = await interceptor.dispatch(request(), transport);
  assert.equal(response.status, 200);
  assert.equal(transport.seen.length, 2);

  // Never preemptive: the first request goes out as the caller wrote it.
  assert.equal(
    must(transport.seen[0], "the transport saw that many attempts").headers.some(([name]) => name === "authorization"),
    false,
    "credentials must not be sent before they are asked for",
  );
  assert.deepEqual(
    must(transport.seen[1], "the transport saw that many attempts").headers.find(([name]) => name === "authorization"),
    ["authorization", "Basic dXNlcjpwYXNz"],
  );
  // And the rest of the request survives the rewrite.
  assert.deepEqual(must(transport.seen[1], "the transport saw that many attempts").headers.find(([name]) => name === "accept"), [
    "accept",
    "*/*",
  ]);

  assert.equal(contexts.length, 1);
  assert.equal(must(contexts[0], "the interceptor authenticated that many times").attempt, 1);
  assert.equal(must(contexts[0], "the interceptor authenticated that many times").status, 401);
  assert.deepEqual(
    must(contexts[0], "the interceptor authenticated that many times").challenges.map((challenge) => challenge.scheme),
    ["basic"],
  );
});

suite("an authenticator that declines returns the challenge untouched", async () => {
  const transport = challengingTransport();
  const interceptor = new AuthenticationInterceptor({ authenticate: () => null });

  const response = await interceptor.dispatch(request(), transport);
  assert.equal(response.status, 401);
  assert.equal(transport.seen.length, 1);
  // The body is left for the caller to read: declining is not consuming.
  assert.notEqual(response.body, null);
  assert.equal(transport.cancelled, 0);
  assert.equal(transport.drained, 0, "declining is not consuming");
});

suite("attempts are bounded, and the last challenge is what the caller gets", async () => {
  const transport = challengingTransport({ acceptCredential: false });
  let calls = 0;
  const interceptor = new AuthenticationInterceptor({
    authenticate: () => {
      calls++;
      return "Basic wrong";
    },
    maximumAttempts: 2,
  });

  const response = await interceptor.dispatch(request(), transport);
  assert.equal(response.status, 401);
  assert.equal(calls, 2, "two attempts, not an unbounded retry");
  assert.equal(transport.seen.length, 3, "the original and two answers");
});

suite("a status that is not a challenge never reaches the authenticator", async () => {
  const transport = challengingTransport({ status: 403 });
  let called = false;
  const interceptor = new AuthenticationInterceptor({
    authenticate: () => {
      called = true;
      return "Basic x";
    },
  });

  const response = await interceptor.dispatch(request(), transport);
  assert.equal(response.status, 403);
  assert.equal(called, false);
});

suite("challenges from several fields are collected in order", async () => {
  const transport = challengingTransport({
    headers: [
      ["www-authenticate", 'Basic realm="one"'],
      ["x-other", "ignored"],
      ["www-authenticate", "Negotiate"],
    ],
  });
  // Assigned from inside the authenticate callback, so it says what it will hold.
  let seen: readonly AuthenticationChallenge[] | undefined;
  const interceptor = new AuthenticationInterceptor({
    authenticate: (context: AuthenticationContext) => {
      seen = context.challenges;
      return null;
    },
  });

  await interceptor.dispatch(request(), transport);
  assert.deepEqual(
    must(seen, "the interceptor was asked to authenticate").map((challenge) => challenge.scheme),
    ["basic", "negotiate"],
  );
});

suite("proxy authentication cannot be configured here", () => {
  // 407 is the proxy's, and the proxy layer knows which hop challenged. Answering it
  // here would send origin credentials to a proxy.
  assert.throws(
    () => new AuthenticationInterceptor({ authenticate: () => null, statuses: [401, 407] }),
    RangeError,
  );
  assert.throws(
    () => new AuthenticationInterceptor({ authenticate: () => null, maximumAttempts: 0 }),
    RangeError,
  );
});

suite("a one-shot body is refused rather than answered with an empty one", async () => {
  const transport = challengingTransport();
  const interceptor = new AuthenticationInterceptor({ authenticate: () => "Basic x" });

  // Answering with an empty body would show the server an authenticated request that
  // is not the one the caller made, which is worse than not answering.
  await assert.rejects(
    () =>
      interceptor.dispatch(
        request({ body: bodyOf("payload"), bodyLength: 7 }),
        transport,
      ),
    TypeError,
  );
});

suite("a replayable body is sent again with the credential", async () => {
  const transport = challengingTransport();
  const interceptor = new AuthenticationInterceptor({ authenticate: () => "Basic x" });
  const source = { length: 7, open: () => bodyOf("payload") };

  const response = await interceptor.dispatch(
    request({ body: source.open(), bodyLength: 7, replayBody: source }),
    transport,
  );
  assert.equal(response.status, 200);
  assert.notEqual(must(transport.seen[1], "the transport saw that many attempts").body, null);
  assert.equal(must(transport.seen[1], "the transport saw that many attempts").bodyLength, 7);
});

suite("the challenge body is consumed before the connection carries the answer", async () => {
  const transport = challengingTransport();
  const interceptor = new AuthenticationInterceptor({ authenticate: () => "Basic x" });

  await interceptor.dispatch(request(), transport);
  // Read to the end rather than cancelled, which is what leaves an HTTP/1 connection
  // reusable. Asserting only "not cancelled" would hold equally if nothing read it.
  assert.equal(transport.drained, 1, "the challenge body was read to its close");
  assert.equal(transport.cancelled, 0);
});

import test from "node:test";
import assert from "node:assert/strict";
import {
  Cache,
  CacheStorage,
  Headers,
  MemoryCacheStorageStore,
  ReadableStream,
  Request,
  Response,
} from "../src/index.ts";
import { createHostNodeWebPlatform } from "../host/node-runtime.ts";
// Symbol-keyed internals: not on the interface prototype and not on the public barrel,
// so a test reaches them the same way the runtime does.
import {
  abortSignalSubscribe,
} from "../src/core/abort-brand.ts";
import { must } from "./harness.ts";
import type {
  CacheStorageEntry,
  CacheStorageHandle,
  CacheStorageStore,
} from "../src/cache/cache-storage.ts";
import type { HeaderEntry } from "../src/fetch/headers.ts";
import type {
  FetchTransport,
  TransportResponse,
} from "../src/fetch/transport.ts";
import type { WebPlatformRuntime } from "../src/provider.ts";
import type { WebPlatformOptions } from "../src/provider.ts";

function stream(text: string): ReadableStream<Uint8Array> {
  const bytes = new globalThis.TextEncoder().encode(text);
  let sent = false;
  return new ReadableStream<Uint8Array>({
    pull(controller) {
      if (sent) controller.close();
      else {
        sent = true;
        controller.enqueue(bytes);
      }
    },
  });
}

function transportResponse(
  status: number,
  text: string | null,
  headers: readonly HeaderEntry[] = [],
): TransportResponse {
  return {
    status,
    statusText: status >= 200 && status <= 299 ? "OK" : "Failure",
    headers,
    body: text === null ? null : stream(text),
  };
}

function runtimeWithTransport(
  dispatch: FetchTransport["dispatch"],
  options: WebPlatformOptions = {},
): WebPlatformRuntime {
  return createHostNodeWebPlatform({
    ...options,
    fetchTransport: { dispatch },
  });
}

function quietRuntime(options: WebPlatformOptions = {}): WebPlatformRuntime {
  return runtimeWithTransport(async () => {
    throw new Error("Unexpected network request");
  }, options);
}

test("Cache and CacheStorage are illegal constructors", () => {
  const runtime = quietRuntime();
  assert.throws(() => new Cache(), TypeError);
  assert.throws(() => new CacheStorage(), TypeError);
  assert.equal(Cache.length, 0);
  assert.equal(CacheStorage.length, 0);
  assert.equal(Cache.prototype.match.length, 1);
  assert.equal(Cache.prototype.matchAll.length, 0);
  assert.equal(Cache.prototype.add.length, 1);
  assert.equal(Cache.prototype.addAll.length, 1);
  assert.equal(Cache.prototype.put.length, 2);
  assert.equal(Cache.prototype.delete.length, 1);
  assert.equal(Cache.prototype.keys.length, 0);
  assert.equal(CacheStorage.prototype.match.length, 1);
  assert.equal(CacheStorage.prototype.open.length, 1);
  assert.equal(CacheStorage.prototype.keys.length, 0);
  assert.equal(Object.prototype.toString.call(new Headers()), "[object Headers]");
  assert.equal(
    Object.prototype.toString.call(new Request("https://cache.test")),
    "[object Request]",
  );
  assert.equal(Object.prototype.toString.call(new Response()), "[object Response]");
  runtime.close();
});

test("Cache algorithms do not redispatch through overridable public methods", async () => {
  const runtime = runtimeWithTransport(async () => transportResponse(200, "network"));
  const cache = await runtime.caches.open("dispatch");
  await cache.put("https://cache.test/item", new Response("stored"));

  cache.matchAll = () => {
    throw new Error("Cache.match called the public matchAll method");
  };
  cache.addAll = () => {
    throw new Error("Cache.add called the public addAll method");
  };
  assert.equal(await must(await cache.match("https://cache.test/item"), "the cache holds that entry").text(), "stored");
  await cache.add("https://cache.test/network");

  const inheritedMatch = Cache.prototype.match;
  Cache.prototype.match = () => {
    throw new Error("CacheStorage.match called Cache.prototype.match");
  };
  try {
    assert.equal(await must(await runtime.caches.match("https://cache.test/item"), "the cache holds that entry").text(), "stored");
  } finally {
    Cache.prototype.match = inheritedMatch;
  }
});

test("named caches preserve insertion order, share lists, and survive name deletion", async () => {
  const runtime = quietRuntime();
  const first = await runtime.caches.open("first");
  const sameList = await runtime.caches.open("first");
  await runtime.caches.open("second");
  await first.put("https://cache.test/one", new Response("one"));

  assert.notStrictEqual(first, sameList);
  assert.equal(await must(await sameList.match("https://cache.test/one"), "the cache holds that entry").text(), "one");
  assert.deepEqual(await runtime.caches.keys(), ["first", "second"]);
  assert.equal(await runtime.caches.has("first"), true);
  assert.equal(await runtime.caches.delete("first"), true);
  assert.equal(await runtime.caches.delete("first"), false);
  assert.equal(await runtime.caches.has("first"), false);

  // Deleting a name does not invalidate Cache objects already associated with its list.
  assert.equal(await must(await first.match("https://cache.test/one"), "the cache holds that entry").text(), "one");
  const replacement = await runtime.caches.open("first");
  assert.equal(await replacement.match("https://cache.test/one"), undefined);
  assert.deepEqual(await runtime.caches.keys(), ["second", "first"]);

  // A copy, because `keys()` returns a readonly sequence and the assertion is that pushing to
  // what a caller holds is ordinary rather than a view into the storage.
  const names = [...(await runtime.caches.keys())];
  names.push("ordinary-sequence");
  assert.equal(names.at(-1), "ordinary-sequence");
});

test("cache names use DOMString conversion without replacing lone surrogates", async () => {
