test("freshness lifetime follows s-maxage, max-age, Expires, then heuristic order", () => {
  const parsed = parseCacheControl("s-maxage=10, max-age=20");
  assert.deepEqual(
    freshnessLifetime({
      shared: true,
      parsed,
      responseTime: 0,
      dateValue: 0,
      heuristicAllowed: true,
    }),
    { seconds: 10, source: "s-maxage" },
  );
  assert.deepEqual(
    freshnessLifetime({
      shared: false,
      parsed,
      responseTime: 0,
      dateValue: 0,
      heuristicAllowed: true,
    }),
    { seconds: 20, source: "max-age" },
  );
  assert.deepEqual(
    freshnessLifetime({
      shared: false,
      parsed: parseCacheControl("public"),
      responseTime: 1_000_000,
      dateValue: 1_000_000,
      expiresValue: 1_060_000,
      lastModifiedValue: 0,
      heuristicAllowed: true,
    }),
    { seconds: 60, source: "expires" },
  );
  assert.deepEqual(
    freshnessLifetime({
      shared: false,
      parsed: parseCacheControl("public"),
      responseTime: 1_000_000,
      dateValue: 1_000_000,
      lastModifiedValue: 0,
      heuristicAllowed: true,
    }),
    { seconds: 100, source: "heuristic" },
  );
});

test("request freshness constraints and response revalidation rules compose", () => {
  const response = parseCacheControl("must-revalidate").directives;
  assert.equal(
    cacheReuseDecision({
      currentAge: 20,
      freshnessLifetime: 30,
      request: parseCacheControl("min-fresh=15").directives,
      response,
      shared: false,
    }),
    "revalidate",
  );
  assert.equal(
    cacheReuseDecision({
      currentAge: 40,
      freshnessLifetime: 30,
      request: parseCacheControl("max-stale=10").directives,
      response: parseCacheControl("").directives,
      shared: false,
    }),
    "stale-allowed",
  );
  assert.equal(
    cacheReuseDecision({
      currentAge: 40.001,
      freshnessLifetime: 30,
      request: parseCacheControl("max-stale=10").directives,
      response: parseCacheControl("").directives,
      shared: false,
    }),
    "revalidate",
  );
});

function body(text: string): ReadableStream<Uint8Array> {
  const bytes = new globalThis.TextEncoder().encode(text);
  let sent = false;
  return new ReadableStream<Uint8Array>({
    pull(controller) {
      if (sent) controller.close();
      else {
        sent = true;
        controller.enqueue(bytes);
      }
    },
  });
}

function header(entries: readonly HeaderEntry[], name: string): string | null {
  for (const [entryName, value] of entries) {
    if (entryName.toLowerCase() === name) return value;
  }
  return null;
}

/** What a test may override when it builds a caching runtime. */
interface CacheRuntimeOptions {
  readonly store?: HttpCacheStore;
  readonly type?: HttpCacheType;
  readonly diagnostics?: HttpCacheDiagnostics;
}

function cacheRuntime(
  transport: FetchTransport,
  now: { value: number },
  options: CacheRuntimeOptions = {},
): WebPlatformRuntime {
  const store = options.store ?? new MemoryHttpCacheStore();
  const httpCache = new HttpCache({
    store,
    type: options.type,
    wallTimeMilliseconds: () => now.value,
    urls: bootstrapRuntime.urls,
    diagnostics: options.diagnostics,
  });
  return createHostNodeWebPlatform({ fetchTransport: transport, httpCache });
}

