// The provider capability of a canonical Web value is owned by its NTS environment.
// It is reached through an internal factory, never through a public constructor
// argument, so script cannot substitute the URL parser, body policy, transports or
// proxy policy that a Request, Response, WebSocket, WebSocketStream or EventSource
// uses. These are host-level conformance tests of the shared algorithm; they are not
// compiled-provider evidence.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import { createHostNodeWebPlatform } from "../host/node-runtime.ts";
import {
  EventSource,
  Request,
  Response,
  WebSocket,
  WebSocketStream,
} from "../src/index.ts";
import type { WebPlatformRuntime } from "../src/provider.ts";
import type { WebPlatformOptions } from "../src/provider.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const tick = () => new Promise((resolve) => setImmediate(resolve));

// A complete second runtime is the most plausible forgery: script that obtained one
// legitimate runtime must not be able to bind another value to it.
/** A runtime with counting transports, so a test can see which one was reached. */
interface CountingRuntime {
  connects: number;
  dispatches: number;
  api: WebPlatformRuntime;
}

/**
 * A constructor reached with a surplus argument its overloads do not admit.
 *
 * Every use below is a forgery attempt, and the attempt is the test: the third argument used to
 * be a context seam, so these calls assert that offering one now changes nothing. The arity is
 * the violation rather than any one argument's type -- `Request` takes one or two arguments
 * publicly and four to six internally, and three matches neither -- so it is the constructor
 * that is widened, once and by name, instead of a cast at every site. A reader sees a
 * deliberate violation rather than a silenced error.
 */
function withSurplus<T>(constructor: new (...args: never) => T): new (...args: unknown[]) => T {
  return constructor as unknown as new (...args: unknown[]) => T;
}

function makeRuntime(t: TestContext, options: WebPlatformOptions = {}): CountingRuntime {
  const record: CountingRuntime = {
    connects: 0,
    dispatches: 0,
    // Replaced immediately below; the transports it is built from close over `record`.
    api: undefined as unknown as WebPlatformRuntime,
  };
  const webSocketTransport = {
    connect() {
      record.connects += 1;
      return Promise.reject(new Error("this transport never completes a handshake"));
    },
  };
  const fetchTransport = {
    dispatch() {
      record.dispatches += 1;
      return Promise.reject(new Error("this transport never reaches a network"));
    },
  };
  record.api = createHostNodeWebPlatform(
    { ...options, webSocketTransport, fetchTransport },
    {},
    () => {},
  );
  t.after(() => record.api.close());
  return record;
}

suite("public Web constructors ignore a surplus capability argument", async (t) => {
  // The last runtime installed owns the environment; `other` is a live but unelected
  // runtime, exactly what a caller would try to smuggle in.
  const other = makeRuntime(t, {
    baseURL: "https://other.test/",
    bodyPolicy: { maxConsumeBytes: 4 },
  });
  const environment = makeRuntime(t, { baseURL: "https://environment.test/base/" });

  // Request: the third argument used to be the context seam.
  const request = new (withSurplus(Request))("relative", undefined, other.api.requestContext);
  assert.equal(request.url, "https://environment.test/base/relative");

  // Response: `other` would cap consumption at four bytes.
  const response = new (withSurplus(Response))("payload", {}, other.api.requestContext);
  assert.equal(await response.text(), "payload");

  // WebSocket and WebSocketStream: the environment's transport is the only one used.
  new (withSurplus(WebSocket))("ws://example.test/socket", [], other.api);
  new (withSurplus(WebSocketStream))("ws://example.test/socket", {}, other.api);
  await tick();
  assert.equal(environment.connects, 2, "the environment transport must carry both sockets");
  assert.equal(other.connects, 0, "a surplus argument must not select a transport");

  // EventSource has no context parameter at all.
  const source = new (withSurplus(EventSource))("feed", undefined, other.api);
  assert.equal(source.url, "https://environment.test/base/feed");
  source.close();
  await tick();
  assert.equal(other.dispatches, 0, "a surplus argument must not select a fetch transport");
});

suite("internal factories still deliver an explicit capability", async (t) => {
  const other = makeRuntime(t, {
    baseURL: "https://other.test/",
    bodyPolicy: { maxConsumeBytes: 4 },
  });
  const environment = makeRuntime(t, { baseURL: "https://environment.test/base/" });

  // Cache reaches the internal Request factory, so `other`'s base URL resolves here
  // even though `environment` owns the ambient runtime.
  const cache = await other.api.caches.open("confinement");
  await cache.put("relative", new Response("stored"));
  const [key] = await cache.keys();
  assert.ok(key !== undefined, "the cache kept the entry that was put in it");
  assert.equal(key.url, "https://other.test/relative");
  assert.equal(new Request("relative").url, "https://environment.test/base/relative");

  // Cache reaches the internal Response factory, so `other`'s four-byte consumption
  // limit governs the response it produced.
  const stored = await cache.match("relative");
  assert.ok(stored !== undefined, "the cache matched the entry it stored");
  await assert.rejects(stored.text(), (error: unknown) => error instanceof RangeError);
  assert.equal(await new Response("stored").text(), "stored");

  // The runtime's own factories bind the socket to that runtime's transport.
  other.api.createWebSocket("ws://example.test/socket");
  other.api.createWebSocketStream("ws://example.test/socket");
  await tick();
  assert.equal(other.connects, 2, "an internal factory must use its own transport");
  assert.equal(environment.connects, 0, "the ambient runtime must not be substituted");
});

// Reusing one HTTP/2 connection for a second origin is sound only when the peer's
// certificate covers that origin and the endpoint is the same one. Getting this wrong
// is a cross-origin routing defect rather than a slow path, so the conditions are
// tested individually and the certificate check has its own sabotage.
//
// Host evidence for the shared decision. It is not evidence about any provider's own
// connection management.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import http2 from "node:http2";
import { createServer as createTlsServer } from "node:tls";

import {
  AbortController,
  DnsCache,
} from "../src/index.ts";
import {
  certificateCovers,
  dnsNameCovers,
} from "../src/provider.ts";
import { Http2Transport } from "../src/http2/transport.ts";
import {
  HostNodeSocketConnector,
  createHostNodePrimitives,
  hostNodeURLs,
} from "../host/node-primitives.ts";
import { tlsFixtureFor } from "./tls-fixture.ts";
import type { Socket } from "node:net";
import { causeText, portOf } from "./harness.ts";
import type { TransportRequest } from "../src/fetch/transport.ts";
import type { ReadableStream } from "../src/streams/readable.ts";
import type {
  ConnectAddress,
  SocketConnector,
} from "../src/provider/primitives.ts";
import type { AbortSignal } from "../src/index.ts";
import type { TlsFixture } from "./tls-fixture.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

async function consume(stream: ReadableStream<Uint8Array> | null): Promise<string> {
  if (stream === null) return "";
  const reader = stream.getReader();
  const parts = [];
  try {
    while (true) {
      const result = await reader.read();
      if (result.done) break;
      parts.push(Buffer.from(result.value));
    }
  } finally {
    reader.releaseLock();
  }
  return Buffer.concat(parts).toString();
}

function transportRequest(url: string): TransportRequest {
  return {
    url: hostNodeURLs.parse(url),
    method: "GET",
    headers: [],
    body: null,
    bodyLength: null,
    signal: new AbortController().signal,
  };
}

suite("a dNSName covers exactly what it says and no more", () => {
  assert.equal(dnsNameCovers("example.test", "example.test"), true);
  assert.equal(dnsNameCovers("EXAMPLE.test", "example.TEST"), true, "names are case-folded");
  assert.equal(
    dnsNameCovers("example.test.", "example.test"),
    true,
    "a root label is the same name",
  );
  assert.equal(dnsNameCovers("example.test", "other.test"), false);
  assert.equal(dnsNameCovers("", "example.test"), false);

  assert.equal(dnsNameCovers("*.example.test", "a.example.test"), true);
  assert.equal(dnsNameCovers("*.example.test", "example.test"), false, "a wildcard needs a label");
  assert.equal(dnsNameCovers("*.example.test", "a.b.example.test"), false, "one label, not many");
  assert.equal(dnsNameCovers("*.example.test", ".example.test"), false, "never an empty label");
  assert.equal(dnsNameCovers("*.test", "example.test"), false, "a registry-wide wildcard");
  assert.equal(dnsNameCovers("f*.example.test", "foo.example.test"), false, "no partial labels");
  assert.equal(dnsNameCovers("*", "example.test"), false);
  assert.equal(dnsNameCovers("*.*.test", "a.b.test"), false);

  assert.equal(certificateCovers(["a.test", "*.b.test"], "x.b.test"), true);
  assert.equal(certificateCovers(["a.test", "*.b.test"], "x.c.test"), false);
  assert.equal(certificateCovers([], "a.test"), false, "cleartext covers nothing");
});

/** One h2 origin whose certificate covers alpha and beta but not gamma. */
async function h2Origin(t: TestContext): Promise<{ fixture: TlsFixture; port: number }> {
  const fixture = tlsFixtureFor(["IP:127.0.0.1", "DNS:alpha.test", "DNS:beta.test"]);
  const sockets = new Set<Socket>();
  const h2 = http2.createServer();
  h2.on("stream", (stream, headers) => {
    stream.respond({ ":status": 200, "content-type": "text/plain" });
    stream.end(String(headers[":authority"]));
  });
  const server = createTlsServer({ ...fixture, ALPNProtocols: ["h2"] }, (socket) => {
    sockets.add(socket);
    socket.on("error", () => {});
    socket.on("close", () => sockets.delete(socket));
    h2.emit("connection", socket);
  });
  server.listen(0, "127.0.0.1");
  await new Promise<void>((resolve) => server.once("listening", () => resolve()));
  t.after(() => {
    for (const socket of sockets) socket.destroy();
    return new Promise<void>((resolve) => server.close(() => resolve()));
  });
  return { fixture, port: portOf(server) };
}

/** Counts connects and supplies the endpoint the shared DNS policy would have. */
function resolvingConnector(
  base: SocketConnector,
  resolvedAddress = "127.0.0.1",
): SocketConnector & { opened: string[] } {
  const opened: string[] = [];
  return {
    opened,
    reportsNegotiatedProtocol: true,
    connect(address: ConnectAddress, signal: AbortSignal) {
      opened.push(address.hostname);
      return base.connect({ ...address, resolvedAddress }, signal);
    },
    connectNegotiated(address: ConnectAddress, signal: AbortSignal) {
      opened.push(address.hostname);
      const negotiate = base.connectNegotiated;
      assert.ok(negotiate !== undefined, "the wrapped connector negotiates");
      return negotiate.call(base, { ...address, resolvedAddress }, signal);
    },
  };
}

suite("a covered origin on the same endpoint reuses the connection", async (t) => {
  const endpointsFor = (_address: ConnectAddress): readonly string[] => ["127.0.0.1"];
  const { fixture, port } = await h2Origin(t);
  const primitives = createHostNodePrimitives();
  const connector = resolvingConnector(
    new HostNodeSocketConnector({ ca: fixture.cert.toString() }),
  );
  const transport = new Http2Transport(connector, primitives.scheduler, {
    coalesceConnections: true,
    knownEndpoints: (address: ConnectAddress) => endpointsFor(address),
  });
  t.after(() => transport.close());

  const first = await transport.dispatch(transportRequest(`https://alpha.test:${port}/a`));
  assert.equal(await consume(first.body), `alpha.test:${port}`);
  const second = await transport.dispatch(transportRequest(`https://beta.test:${port}/b`));
  // The second origin is served over the first connection, and its own authority is
  // still what reaches the server.
  assert.equal(await consume(second.body), `beta.test:${port}`);
  assert.deepEqual(connector.opened, ["alpha.test"], "beta must not open a connection");
  assert.equal(transport.stats.connections, 1);
});

suite("coalescing is off unless it is asked for", async (t) => {
  const { fixture, port } = await h2Origin(t);
  const primitives = createHostNodePrimitives();
  const connector = resolvingConnector(
    new HostNodeSocketConnector({ ca: fixture.cert.toString() }),
  );
  const transport = new Http2Transport(connector, primitives.scheduler);
  t.after(() => transport.close());

  await consume((await transport.dispatch(transportRequest(`https://alpha.test:${port}/a`))).body);
  await consume((await transport.dispatch(transportRequest(`https://beta.test:${port}/b`))).body);
  assert.deepEqual(connector.opened, ["alpha.test", "beta.test"]);
  assert.equal(transport.stats.connections, 2);
});

suite("an origin the certificate does not cover is never routed over the connection", async (t) => {
  const endpointsFor = (_address: ConnectAddress): readonly string[] => ["127.0.0.1"];
  const { fixture, port } = await h2Origin(t);
  const primitives = createHostNodePrimitives();
  const connector = resolvingConnector(
    new HostNodeSocketConnector({ ca: fixture.cert.toString() }),
  );
  const transport = new Http2Transport(connector, primitives.scheduler, {
    coalesceConnections: true,
    knownEndpoints: (address: ConnectAddress) => endpointsFor(address),
  });
  t.after(() => transport.close());

  await consume((await transport.dispatch(transportRequest(`https://alpha.test:${port}/a`))).body);
  // gamma.test resolves to the same endpoint and the connection is live, so every
  // condition except certificate coverage is met. It must open its own connection and
  // fail identity verification there, rather than being answered by a server that does
  // not speak for it.
  await assert.rejects(
    transport.dispatch(transportRequest(`https://gamma.test:${port}/c`)),
    (error: unknown) => /gamma\.test|altnames|certificate/i.test(String(error) + causeText(error)),
  );
  assert.deepEqual(connector.opened, ["alpha.test", "gamma.test"]);
});

suite("a different endpoint is a different peer even under one certificate", async (t) => {
  const { fixture, port } = await h2Origin(t);
  const primitives = createHostNodePrimitives();
  const base = new HostNodeSocketConnector({ ca: fixture.cert.toString() });
  const opened: string[] = [];
  // alpha resolves to the loopback address; beta claims a different endpoint, so the
  // certificate covering both is not on its own a reason to reuse the connection.
  const connector = {
    reportsNegotiatedProtocol: true,
    connect(address: ConnectAddress, signal: AbortSignal) {
      opened.push(address.hostname);
      return base.connect(
        { ...address, resolvedAddress: endpointsFor(address)[0] ?? "127.0.0.1" },
        signal,
      );
    },
    connectNegotiated(address: ConnectAddress, signal: AbortSignal) {
      opened.push(address.hostname);
      return base.connectNegotiated(
        { ...address, resolvedAddress: endpointsFor(address)[0] ?? "127.0.0.1" },
        signal,
      );
    },
  };
  function endpointsFor(address: ConnectAddress): string[] {
    return address.hostname === "alpha.test" ? ["127.0.0.1"] : ["127.0.0.2"];
  }
  const transport = new Http2Transport(connector, primitives.scheduler, {
    coalesceConnections: true,
    knownEndpoints: (address: ConnectAddress) => endpointsFor(address),
  });
  t.after(() => transport.close());

  await consume((await transport.dispatch(transportRequest(`https://alpha.test:${port}/a`))).body);
  // 127.0.0.2 has no listener here, so a refused connection is the proof that beta was
  // not silently answered over alpha's.
  await assert.rejects(transport.dispatch(transportRequest(`https://beta.test:${port}/b`)));
  assert.deepEqual(opened, ["alpha.test", "beta.test"]);
});

suite("a connection with no known endpoint does not coalesce", async (t) => {
  const endpointsFor = (_address: ConnectAddress): readonly string[] | undefined => undefined;
  const { fixture, port } = await h2Origin(t);
  const primitives = createHostNodePrimitives();
  // No resolvedAddress at all: certificate coverage alone must not be enough.
  const base = new HostNodeSocketConnector({ ca: fixture.cert.toString() });
  const opened: string[] = [];
  const connector = {
    reportsNegotiatedProtocol: true,
    connect(address: ConnectAddress, signal: AbortSignal) {
      opened.push(address.hostname);
      return base.connect(address, signal);
    },
    connectNegotiated(address: ConnectAddress, signal: AbortSignal) {
      opened.push(address.hostname);
      return base.connectNegotiated(address, signal);
    },
  };
  const transport = new Http2Transport(connector, primitives.scheduler, {
    coalesceConnections: true,
    knownEndpoints: (address: ConnectAddress) => endpointsFor(address),
  });
  t.after(() => transport.close());
  await assert.rejects(transport.dispatch(transportRequest(`https://alpha.test:${port}/a`)));
  assert.deepEqual(opened, ["alpha.test"]);
});

suite("the live endpoint may be any of the ones the origin is known to reach", async (t) => {
  const { fixture, port } = await h2Origin(t);
  const primitives = createHostNodePrimitives();
  const connector = resolvingConnector(
    new HostNodeSocketConnector({ ca: fixture.cert.toString() }),
  );
  const transport = new Http2Transport(connector, primitives.scheduler, {
    coalesceConnections: true,
    // beta is known to reach two addresses and the live connection is on the second.
    // Asking which endpoint a fresh lookup would pick would answer 127.0.0.9 and miss
    // a connection that legitimately serves this origin.
    knownEndpoints: (address: ConnectAddress) =>
      address.hostname === "alpha.test" ? ["127.0.0.1"] : ["127.0.0.9", "127.0.0.1"],
  });
  t.after(() => transport.close());

  await consume((await transport.dispatch(transportRequest(`https://alpha.test:${port}/a`))).body);
  const second = await transport.dispatch(transportRequest(`https://beta.test:${port}/b`));
  assert.equal(await consume(second.body), `beta.test:${port}`);
  assert.deepEqual(connector.opened, ["alpha.test"]);
  assert.equal(transport.stats.connections, 1);
});

suite("the shared DNS cache answers the probe without resolving or rotating", async (t) => {
  let resolverCalls = 0;
  const cache = new DnsCache({
    resolver: {
      resolve() {
        resolverCalls += 1;
        return Promise.resolve([
          { address: "127.0.0.1", family: 4, ttlMilliseconds: 60_000 },
          { address: "127.0.0.9", family: 4, ttlMilliseconds: 60_000 },
        ]);
      },
    },
    nowMilliseconds: () => 0,
  });

  // Nothing is known before a lookup, and probing must not cause one.
  assert.deepEqual(cache.knownAddresses("alpha.test"), []);
  assert.equal(resolverCalls, 0);

  const signal = new AbortController().signal;
  const first = await cache.lookup("alpha.test", [4], signal);
  assert.deepEqual(
    first.map((entry) => entry.address),
    ["127.0.0.1", "127.0.0.9"],
  );
  assert.equal(resolverCalls, 1);

  // The probe answers both addresses and repeating it resolves nothing.
  for (let attempt = 0; attempt < 3; attempt++) {
    assert.deepEqual(cache.knownAddresses("alpha.test"), ["127.0.0.1", "127.0.0.9"]);
  }
  assert.equal(resolverCalls, 1, "the probe never resolves");

  // Whatever the rotation rule is, probing must not advance it. A control cache that
  // was never probed answers the comparison, so this asserts "the probe changed
  // nothing" rather than a hardcoded order.
  const control = new DnsCache({
    resolver: {
      resolve() {
        return Promise.resolve([
          { address: "127.0.0.1", family: 4, ttlMilliseconds: 60_000 },
          { address: "127.0.0.9", family: 4, ttlMilliseconds: 60_000 },
        ]);
      },
    },
    nowMilliseconds: () => 0,
  });
  const controlFirst = await control.lookup("alpha.test", [4], signal);
  assert.deepEqual(
    controlFirst.map((entry) => entry.address),
    first.map((entry) => entry.address),
  );
  const second = await cache.lookup("alpha.test", [4], signal);
  const controlSecond = await control.lookup("alpha.test", [4], signal);
  assert.deepEqual(
    second.map((entry) => entry.address),
    controlSecond.map((entry) => entry.address),
    "three probes must leave the next lookup exactly where it would have been",
  );
  assert.equal(resolverCalls, 1);

  // Family filtering and unknown hosts.
  assert.deepEqual(cache.knownAddresses("alpha.test", [6]), []);
  assert.deepEqual(cache.knownAddresses("unknown.test"), []);
  assert.deepEqual(cache.knownAddresses(""), []);
});

