  let at = 0;
  return new BufferedReader({
    closed: false,
    async read(max) {
      if (at === bytes.length) return null;
      const end = Math.min(at + split, at + max, bytes.length);
      const part = bytes.slice(at, end);
      at = end;
      return part;
    },
    async write() {
      throw new Error("unused");
    },
    close() {},
  });
}
