// Secure Curves §§4.3, 6.4; RFC 8410 §§3–4, 7; RFC 8032 §§5.2.2, 5.2.5;
// RFC 7748 §5; RFC 5208 §5; X.690 DER. No point or scalar mathematics here.
// https://wicg.github.io/webcrypto-secure-curves/
import assert from "node:assert/strict";
import test from "node:test";
import { DOMException } from "../src/core/errors.ts";
import { parseOkpDer } from "../src/crypto/der.ts";
import {
  curve448Pkcs8, curve448PrivateJwk, curve448RawPublic, curve448Spki,
} from "./curve448-fixtures.ts";
import type { Curve448FixtureName } from "./curve448-fixtures.ts";

function bytes(...values: number[]): Uint8Array { return new Uint8Array(values); }
function concat(...parts: readonly Uint8Array[]): Uint8Array { return new Uint8Array(Buffer.concat(parts)); }
function der(tag: number, ...parts: readonly Uint8Array[]): Uint8Array {
  const value = concat(...parts);
  return concat(bytes(tag), value.length < 128 ? bytes(value.length)
    : value.length < 256 ? bytes(0x81, value.length) : bytes(0x82, value.length >>> 8, value.length & 255), value);
}
function integer(...value: number[]): Uint8Array { return der(2, bytes(...value)); }
function algorithm(name: Curve448FixtureName, parameters = bytes()): Uint8Array {
  return der(0x30, der(6, bytes(0x2b, 0x65, name === "Ed448" ? 0x71 : 0x6f)), parameters);
}
function privateBytes(name: Curve448FixtureName): Uint8Array {
  return new Uint8Array(Buffer.from(curve448PrivateJwk(name).d, "base64url"));
}
function spki(name: Curve448FixtureName, point = curve448RawPublic(name), parameters = bytes(), unused = 0): Uint8Array {
  return der(0x30, algorithm(name, parameters), der(3, bytes(unused), point));
}
function pkcs8(name: Curve448FixtureName, inner = der(4, privateBytes(name)), parameters = bytes(), version = integer(0), tail = bytes()): Uint8Array {
  return der(0x30, version, algorithm(name, parameters), der(4, inner), tail);
}
function dataError(error: unknown): boolean { return error instanceof DOMException && error.name === "DataError"; }

for (const name of ["Ed448", "X448"] as const) {
  const width = name === "Ed448" ? 57 : 56;
  for (const format of ["spki", "pkcs8"] as const) {
    test(name + " " + format + " decodes fixed RFC material at its exact encoded width", () => {
      const original = format === "spki" ? curve448Spki(name) : curve448Pkcs8(name);
      const padded = concat(bytes(7, 8), original, bytes(9));
      const result = parseOkpDer(format, padded.subarray(2, padded.length - 1));
      assert.equal(result.namedCurve, name);
      if (format === "spki") {
        assert.deepEqual(result.x, curve448RawPublic(name));
        assert.equal(result.x!.byteLength, width);
        assert.equal(result.x!.buffer, padded.buffer);
        assert.equal(result.d, undefined);
      } else {
        assert.deepEqual(result.d, privateBytes(name));
        assert.equal(result.d!.byteLength, width);
        assert.equal(result.d!.buffer, padded.buffer);
        assert.equal(result.x, undefined);
      }
    });

    test(name + " " + format + " requires the RFC 8410 OID with absent parameters", () => {
      for (const parameters of [der(5), der(0x30), der(4), der(6, bytes(0x2b, 0x65, 0x71)), der(5, bytes(0))]) {
        const encoded = format === "spki" ? spki(name, curve448RawPublic(name), parameters) : pkcs8(name, der(4, privateBytes(name)), parameters);
        assert.throws(() => parseOkpDer(format, encoded), dataError);
      }
      const encoded = format === "spki" ? spki(name) : pkcs8(name);
      const position = Buffer.from(encoded).indexOf(Buffer.from([6, 3, 0x2b, 0x65]));
      assert.ok(position >= 0);
      for (const oid of [0x6e, 0x70, name === "Ed448" ? 0x6f : 0x71, 0x72, 0xff]) {
        const altered = encoded.slice(); altered[position + 4] = oid;
        assert.throws(() => parseOkpDer(format, altered), dataError);
      }
      for (const at of [position + 2, position + 3]) {
        const altered = encoded.slice(); altered[at]! ^= 1;
        assert.throws(() => parseOkpDer(format, altered), dataError);
      }
    });

    test(name + " " + format + " consumes exactly one canonical DER envelope", () => {
      const encoded = format === "spki" ? spki(name) : pkcs8(name);
      for (let end = 0; end < encoded.length; end++) {
        assert.throws(() => parseOkpDer(format, encoded.subarray(0, end)), dataError);
      }
      assert.throws(() => parseOkpDer(format, concat(encoded, bytes(0))), dataError);
      const body = encoded.subarray(2);
      for (const altered of [
        concat(bytes(0x30, 0x80), body, bytes(0, 0)),
        concat(bytes(0x30, 0x81, body.length), body),
        concat(bytes(0x30, 0x82, 0, body.length), body),
        concat(bytes(0x30, 0x81, 255), body),
        concat(bytes(0x30, 0x87, 1, 0, 0, 0, 0, 0, 0), body),
        concat(bytes(0x31, body.length), body),
      ]) assert.throws(() => parseOkpDer(format, altered), dataError);
    });
  }

  test(name + " SPKI preserves opaque public octets and rejects every adjacent width", () => {
    for (const point of [new Uint8Array(width), new Uint8Array(width).fill(0xff), concat(bytes(1), new Uint8Array(width - 1))]) {
      assert.deepEqual(parseOkpDer("spki", spki(name, point)).x, point);
    }
    for (const size of [0, 32, width - 1, width + 1, width * 2]) {
      assert.throws(() => parseOkpDer("spki", spki(name, new Uint8Array(size))), dataError);
    }
  });

  test(name + " SPKI requires a primitive byte-aligned BIT STRING without suffixes", () => {
    for (const unused of [1, 7, 8, 255]) {
      assert.throws(() => parseOkpDer("spki", spki(name, curve448RawPublic(name), bytes(), unused)), dataError);
    }
    for (const encoded of [
      der(0x30, algorithm(name), der(3)),
      der(0x30, algorithm(name), der(0x23, der(3, bytes(0), curve448RawPublic(name)))),
      der(0x30, algorithm(name), der(4, curve448RawPublic(name))),
      der(0x30, algorithm(name), der(3, bytes(0), curve448RawPublic(name)), der(5)),
      der(0x30, der(3, bytes(0), curve448RawPublic(name))),
    ]) assert.throws(() => parseOkpDer("spki", encoded), dataError);
  });

  test(name + " PKCS8 contains exactly one nested primitive CurvePrivateKey", () => {
    for (const seed of [new Uint8Array(width), new Uint8Array(width).fill(0xff)]) {
      assert.deepEqual(parseOkpDer("pkcs8", pkcs8(name, der(4, seed))).d, seed);
    }
    for (const size of [0, 32, width - 1, width + 1, width * 2]) {
      assert.throws(() => parseOkpDer("pkcs8", pkcs8(name, der(4, new Uint8Array(size)))), dataError);
    }
    for (const inner of [
      privateBytes(name), concat(der(4, privateBytes(name)), bytes(0)),
      concat(der(4, privateBytes(name)), der(5)), der(0x24, der(4, privateBytes(name))),
      der(0x30, integer(1), der(4, privateBytes(name))), der(3, bytes(0), privateBytes(name)),
    ]) assert.throws(() => parseOkpDer("pkcs8", pkcs8(name, inner)), dataError);
    assert.throws(() => parseOkpDer("pkcs8", der(0x30, integer(0), algorithm(name), der(0x24, der(4, der(4, privateBytes(name)))))), dataError);
  });

  test(name + " PKCS8 uses version zero and rejects OneAsymmetricKey public fields", () => {
    for (const version of [integer(), integer(1), integer(2), integer(0, 0), integer(0xff), der(5)]) {
      assert.throws(() => parseOkpDer("pkcs8", pkcs8(name, der(4, privateBytes(name)), bytes(), version)), dataError);
    }
    for (const suffix of [der(0x81, bytes(0), curve448RawPublic(name)), der(0xa1, der(3, bytes(0), curve448RawPublic(name))), der(5)]) {
      for (const version of [integer(0), integer(1)]) {
        assert.throws(() => parseOkpDer("pkcs8", pkcs8(name, der(4, privateBytes(name)), bytes(), version, suffix)), dataError);
      }
    }
  });

  test(name + " PKCS8 accepts canonical optional attributes including long DER lengths", () => {
    const oid = der(6, bytes(0x2a, 3));
    const attribute = der(0x30, oid, der(0x31, der(0x0c, bytes(0x61))));
    const longAttribute = der(0x30, oid, der(0x31, der(4, new Uint8Array(200).fill(0x61))));
    for (const suffix of [der(0xa0), der(0xa0, attribute), der(0xa0, longAttribute)]) {
      assert.deepEqual(parseOkpDer("pkcs8", pkcs8(name, der(4, privateBytes(name)), bytes(), integer(0), suffix)).d, privateBytes(name));
    }
    for (const suffix of [
      concat(der(0xa0, attribute), der(0xa0)),
      der(0xa0, der(0x30, oid, der(0x31))),
      der(0xa0, der(0x30, oid, der(0x31, integer(2), integer(1)))),
      der(0xa0, der(0x30, der(6, bytes(0x80, 0x2a)), der(0x31, integer(1)))),
    ]) assert.throws(() => parseOkpDer("pkcs8", pkcs8(name, der(4, privateBytes(name)), bytes(), integer(0), suffix)), dataError);
  });
}

test("Ed448 uses the RFC 8032 57-octet encoding despite the draft raw-import 448-bit typo", () => {
  // Secure Curves §6.4 currently says 448 bits. RFC 8032 §§5.2.2 and 5.2.5
  // require 456-bit encodings: 57-byte public points and original private seeds.
  assert.equal(parseOkpDer("spki", spki("Ed448")).x!.byteLength, 57);
  assert.equal(parseOkpDer("pkcs8", pkcs8("Ed448")).d!.byteLength, 57);
  assert.throws(() => parseOkpDer("spki", spki("Ed448", new Uint8Array(56))), dataError);
  assert.throws(() => parseOkpDer("pkcs8", pkcs8("Ed448", der(4, new Uint8Array(56)))), dataError);
});

// Secure Curves §§4, 6 and Web Cryptography §§14.3.7, 14.3.11–12.
// Target-key expectations start with RFC 7748's independent X448 secret.
import assert from "node:assert/strict";
import { createHmac, hkdfSync, pbkdf2Sync } from "node:crypto";
import test from "node:test";
import { DOMException } from "../src/core/errors.ts";
import { createCrypto } from "../src/crypto/crypto.ts";
import type { KeyUsage } from "../src/crypto/crypto-key.ts";
import type { CryptoDerivationParameters, CryptoFailure, CryptoKeyHandle, CryptoKeyImport, CryptoKeyRecord } from "../src/provider/crypto.ts";
import { VirtualScheduler } from "../src/provider/virtual-time.ts";
import { NodeCryptoProvider } from "./node-crypto-provider.ts";
import { curve448PrivateJwk, curve448PublicJwk, ed448Message, ed448Signature,
  x448PrivateJwk, x448PublicJwk, x448Secret } from "./curve448-fixtures.ts";

class RecordingProvider extends NodeCryptoProvider {
  derives = 0;
  imports = 0;
  derived: Uint8Array | CryptoFailure | undefined;
  importFailure: CryptoFailure | undefined;
  override derive(parameters: CryptoDerivationParameters, key: CryptoKeyHandle): Uint8Array | CryptoFailure {
    this.derives++;
    return this.derived ?? super.derive(parameters, key);
  }
  override importKey(input: CryptoKeyImport): CryptoKeyRecord | CryptoFailure {
    this.imports++;
    return this.importFailure ?? super.importKey(input);
  }
}

class CountingScheduler extends VirtualScheduler {
  enqueues = 0;
  override enqueue(task: () => void): void { this.enqueues++; super.enqueue(task); }
}

function fixture() {
  const provider = new RecordingProvider();
  const scheduler = new CountingScheduler();
  const subtle = createCrypto({ fill(bytes: Uint8Array): void { bytes.fill(1); } }, provider, scheduler).subtle;
  function settle<T>(promise: Promise<T>): Promise<T> { scheduler.runPending(); return promise; }
  async function agreement(usages: readonly KeyUsage[] = ["deriveKey", "deriveBits"]) {
    const base = await settle(subtle.importKey("jwk", x448PrivateJwk("alice"), "X448", false, usages));
    const peer = await settle(subtle.importKey("jwk", x448PublicJwk("bob"), "X448", false, []));
    provider.derives = 0;
    provider.imports = 0;
    scheduler.enqueues = 0;
    return { base, algorithm: { name: "X448", public: peer } };
  }
  return { provider, scheduler, subtle, settle, agreement };
}

function dom(name: string): (error: unknown) => boolean {
  return error => error instanceof DOMException && error.name === name;
}

function prefix(bits: number): Uint8Array {
  const result = x448Secret().slice(0, Math.ceil(bits / 8));
  if (bits % 8 !== 0) result[result.length - 1]! &= 0xff << (8 - bits % 8);
  return result;
}

for (const name of ["AES-CTR", "AES-CBC", "AES-GCM", "AES-KW"] as const) {
  test(`X448 derives ${name} at all AES lengths with one primitive and one settlement`, async () => {
    const f = fixture();
    const { base, algorithm } = await f.agreement();
    for (const length of [128, 192, 256]) {
      const usages = name === "AES-KW" ? ["wrapKey", "unwrapKey"] : ["encrypt", "decrypt"];
      const derives = f.provider.derives;
      const imports = f.provider.imports;
      const enqueues = f.scheduler.enqueues;
      const pending = f.subtle.deriveKey(algorithm, base, { name, length }, true, usages);
      assert.equal(f.provider.derives, derives + 1);
      assert.equal(f.provider.imports, imports + 1);
      assert.equal(f.scheduler.enqueues, enqueues + 1);
      const key = await f.settle(pending);
      assert.deepEqual(key.algorithm, { name, length });
      assert.deepEqual(await f.settle(f.subtle.exportKey("raw", key)), prefix(length).buffer);
    }
  });
}

for (const hash of ["SHA-1", "SHA-256", "SHA-384", "SHA-512"] as const) {
  test(`X448 derives ${hash} HMAC prefixes and rejects its oversized default after agreement`, async () => {
    const f = fixture();
    const { base, algorithm } = await f.agreement();
    const data = new Uint8Array([8, 9, 10]);
    for (const length of [1, 9, 256, 447, 448]) {
      const key = await f.settle(f.subtle.deriveKey(algorithm, base, { name: "HMAC", hash, length }, true, ["sign"]));
      const bytes = prefix(length);
      assert.deepEqual(await f.settle(f.subtle.exportKey("raw", key)), bytes.buffer);
      assert.deepEqual(new Uint8Array(await f.settle(f.subtle.sign("HMAC", key, data))),
        new Uint8Array(createHmac(hash.replace("-", "").toLowerCase(), bytes).update(data).digest()));
    }
    const derives = f.provider.derives;
    const imports = f.provider.imports;
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base, { name: "HMAC", hash }, true, ["sign"])), dom("OperationError"));
    assert.equal(f.provider.derives, derives + 1, "Secure Curves checks requested length after X448 agreement");
    assert.equal(f.provider.imports, imports);
  });
}

for (const name of ["HKDF", "PBKDF2"] as const) {
  test(`X448 derives a nonextractable ${name} key from all 56 secret octets`, async () => {
    const f = fixture();
    const { base, algorithm } = await f.agreement();
    const key = await f.settle(f.subtle.deriveKey(algorithm, base, name, false, ["deriveBits"]));
    assert.deepEqual(key.algorithm, { name });
    assert.equal(key.extractable, false);
    const salt = new Uint8Array([1, 2]);
    const info = new Uint8Array([3, 4]);
    const output = await f.settle(f.subtle.deriveBits({ name, hash: "SHA-256", salt, info, iterations: 2 }, key, 256));
    const expected = name === "HKDF" ? new Uint8Array(hkdfSync("sha256", x448Secret(), salt, info, 32))
      : new Uint8Array(pbkdf2Sync(x448Secret(), salt, 2, 32, "sha256"));
    assert.deepEqual(new Uint8Array(output), expected);
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base, name, true, ["deriveBits"])), dom("SyntaxError"));
  });
}

test("X448 deriveKey permissions, length normalization and import errors remain distinct", async () => {
  const f = fixture();
  const { base, algorithm } = await f.agreement(["deriveKey"]);
  await assert.rejects(f.settle(f.subtle.deriveBits(algorithm, base, 128)), dom("InvalidAccessError"));
  await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base,
    { name: "AES-GCM", length: 129 }, true, ["encrypt"])), dom("OperationError"));
  assert.equal(f.provider.derives, 0);
  await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base,
    { name: "AES-GCM", length: 128 }, true, ["sign"])), dom("SyntaxError"));
  assert.equal(f.provider.derives, 1);
  assert.equal(f.provider.imports, 0);
  await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base,
    { name: "AES-GCM", length: 128 }, true, [])), dom("SyntaxError"));
  assert.equal(f.provider.imports, 1);
  const key = await f.settle(f.subtle.deriveKey(algorithm, base, { name: "AES-GCM", length: 128 }, false, ["encrypt"]));
  await assert.rejects(f.settle(f.subtle.exportKey("raw", key)), dom("InvalidAccessError"));
});

test("X448 tests all 56 secret octets before truncation and target import", async () => {
  const f = fixture();
  const { base, algorithm } = await f.agreement();
  f.provider.derived = new Uint8Array(56);
  await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base, { name: "AES-GCM", length: 128 }, true, ["encrypt"])), dom("OperationError"));
  assert.equal(f.provider.imports, 0);
  f.provider.derived[55] = 1;
  const key = await f.settle(f.subtle.deriveKey(algorithm, base, { name: "AES-GCM", length: 128 }, true, ["encrypt"]));
  assert.deepEqual(await f.settle(f.subtle.exportKey("raw", key)), new ArrayBuffer(16));
  assert.equal(f.provider.derived[55], 1);
});

test("X448 normalizes import and get-key-length separately and rejects OKP targets", async () => {
  const f = fixture();
  const { base, algorithm } = await f.agreement();
  let reads = 0;
  const target = { name: "HMAC", hash: "SHA-256", get length() { return ++reads === 1 ? 9 : 16; } };
  const key = await f.settle(f.subtle.deriveKey(algorithm, base, target, true, ["sign"]));
  assert.equal(reads, 2);
  assert.deepEqual(key.algorithm, { name: "HMAC", hash: { name: "SHA-256" }, length: 9 });
  assert.deepEqual(await f.settle(f.subtle.exportKey("raw", key)), prefix(9).buffer);
  for (const name of ["Ed25519", "X25519", "Ed448", "X448"]) {
    const pending = f.subtle.deriveKey(algorithm, base, name, true, ["sign"]);
    assert.equal(f.scheduler.hasPending, false);
    await assert.rejects(pending, dom("NotSupportedError"));
  }
});

for (const failure of ["invalid-key", "operation"] as const) {
  test(`X448 deriveKey maps ${failure} values and settles each result once`, async () => {
    const f = fixture();
    const { base, algorithm } = await f.agreement();
    const target = { name: "AES-GCM", length: 128 };
    f.provider.derived = { failure };
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base, target, true, ["encrypt"])), dom("OperationError"));
    assert.equal(f.provider.imports, 0);
    assert.equal(f.scheduler.enqueues, 1);
    f.provider.derived = undefined;
    f.provider.importFailure = { failure };
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base, target, true, ["encrypt"])),
      dom(failure === "invalid-key" ? "DataError" : "OperationError"));
    assert.equal(f.scheduler.enqueues, 2);
  });
}

for (const name of ["Ed448", "X448"] as const) {
  for (const [type, format] of [["public", "raw"], ["public", "spki"], ["private", "pkcs8"], ["public", "jwk"], ["private", "jwk"]] as const) {
    test(`AES-GCM wraps ${name} ${type} ${format} and restores usable material`, async () => {
      const f = fixture();
      const usages = name === "Ed448" ? [type === "private" ? "sign" : "verify"] : type === "private" ? ["deriveBits"] : [];
      const key = await f.settle(f.subtle.importKey("jwk", type === "private" ? curve448PrivateJwk(name) : curve448PublicJwk(name), name, true, usages));
      const wrapper = await f.settle(f.subtle.importKey("raw", new Uint8Array(16), "AES-GCM", false, ["wrapKey", "unwrapKey"]));
      const cipher = { name: "AES-GCM", iv: new Uint8Array(12) };
      const original = await f.settle(f.subtle.exportKey(format, key));
      const wrapped = await f.settle(f.subtle.wrapKey(format, key, wrapper, cipher));
      const restored = await f.settle(f.subtle.unwrapKey(format, wrapped, wrapper, cipher, name, true, usages));
      assert.deepEqual(await f.settle(f.subtle.exportKey(format, restored)), original);
      if (name === "Ed448") {
        if (type === "private") assert.deepEqual(new Uint8Array(await f.settle(f.subtle.sign(name, restored, ed448Message()))), ed448Signature());
        else assert.equal(await f.settle(f.subtle.verify(name, restored, ed448Signature(), ed448Message())), true);
      } else {
        const peer = await f.settle(f.subtle.importKey("jwk", type === "private" ? x448PublicJwk("bob") : x448PrivateJwk("bob"),
          name, false, type === "private" ? [] : ["deriveBits"]));
        const bits = await f.settle(f.subtle.deriveBits({ name, public: type === "public" ? restored : peer }, type === "private" ? restored : peer));
        assert.deepEqual(new Uint8Array(bits), x448Secret());
      }
    });
  }

  test(`AES-KW wraps ${name} JWK and enforces each binary encoding's octet alignment`, async () => {
    const f = fixture();
    const wrapper = await f.settle(f.subtle.importKey("raw", new Uint8Array(16), "AES-KW", false, ["wrapKey", "unwrapKey"]));
    for (const type of ["public", "private"] as const) {
      const usages = name === "Ed448" ? [type === "private" ? "sign" : "verify"] : type === "private" ? ["deriveBits"] : [];
      const key = await f.settle(f.subtle.importKey("jwk", type === "private" ? curve448PrivateJwk(name) : curve448PublicJwk(name), name, true, usages));
      const formats = type === "public" ? ["jwk", "raw", "spki"] : ["jwk", "pkcs8"];
      for (const format of formats) {
        const supported = format === "jwk" || (name === "X448" && format !== "spki");
        const pending = f.subtle.wrapKey(format, key, wrapper, "AES-KW");
        if (!supported) { await assert.rejects(f.settle(pending), dom("OperationError")); continue; }
        const wrapped = await f.settle(pending);
        const restored = await f.settle(f.subtle.unwrapKey(format, wrapped, wrapper, "AES-KW", name, true, usages));
        assert.deepEqual(await f.settle(f.subtle.exportKey(format, restored)), await f.settle(f.subtle.exportKey(format, key)));
      }
    }
  });
}

// Secure Curves §§4.3, 6.4; Web Cryptography §§9, 13–17;
// RFC 8410 §§3–4, 7, RFC 8032 §5.2, RFC 8037 §2 and RFC 7517 §4.
// https://wicg.github.io/webcrypto-secure-curves/
// Specification controls over native primitives, never Node WebCrypto.
import assert from "node:assert/strict";
import { createPrivateKey, createPublicKey } from "node:crypto";
import test from "node:test";
import { DOMException } from "../src/core/errors.ts";
import { createCrypto } from "../src/crypto/crypto.ts";
import { getCryptoKeySlots } from "../src/crypto/crypto-key.ts";
import type { CryptoKey, CryptoKeyPair, KeyUsage } from "../src/crypto/crypto-key.ts";
import type { JsonWebKeyObject } from "../src/crypto/jwk.ts";
import type {
  CryptoFailure, CryptoKeyComponents, CryptoKeyHandle, CryptoKeyImport,
  CryptoKeyPairGeneration, CryptoKeyPairRecord, CryptoKeyRecord, CryptoOkpComponents,
} from "../src/provider/crypto.ts";
import { VirtualScheduler } from "../src/provider/virtual-time.ts";
import {
  curve448Pkcs8, curve448PrivateJwk, curve448PublicJwk, curve448RawPublic, curve448Spki,
} from "./curve448-fixtures.ts";
import type { Curve448FixtureName } from "./curve448-fixtures.ts";
import { NodeCryptoProvider } from "./node-crypto-provider.ts";
import { okpPkcs8, okpSpki } from "./okp-fixtures.ts";

class RecordingProvider extends NodeCryptoProvider {
  imports = 0;
  exports = 0;
  componentExports = 0;
  generations = 0;
  importInput: CryptoKeyImport | undefined;
  exportFormat: "raw" | "spki" | "pkcs8" | undefined;
  generationInput: CryptoKeyPairGeneration | undefined;
  importFailure: CryptoFailure | undefined;
  exportFailure: CryptoFailure | undefined;
  generationFailure: CryptoFailure | undefined;
  importRecord: CryptoKeyRecord | undefined;
  generationRecord: CryptoKeyPairRecord | undefined;
  exportBytes: Uint8Array | undefined;
  exportParts: CryptoKeyComponents | undefined;

  override importKey(input: CryptoKeyImport): CryptoKeyRecord | CryptoFailure {
    this.imports++; this.importInput = input;
    return this.importFailure ?? this.importRecord ?? super.importKey(input);
  }
  override exportKey(key: CryptoKeyHandle, format: "raw" | "spki" | "pkcs8"): Uint8Array | CryptoFailure {
    this.exports++; this.exportFormat = format;
    return this.exportFailure ?? this.exportBytes ?? super.exportKey(key, format);
  }
  override exportComponents(key: CryptoKeyHandle): CryptoKeyComponents | CryptoFailure {
    this.componentExports++;
    return this.exportFailure ?? this.exportParts ?? super.exportComponents(key);
  }
  override generateKeyPair(parameters: CryptoKeyPairGeneration): CryptoKeyPairRecord | CryptoFailure {
    this.generations++; this.generationInput = parameters;
    return this.generationFailure ?? this.generationRecord ?? super.generateKeyPair(parameters);
  }
}

function usagesFor(name: Curve448FixtureName, type: "public" | "private"): KeyUsage[] {
  return name === "Ed448" ? [type === "public" ? "verify" : "sign"] : type === "private" ? ["deriveKey", "deriveBits"] : [];
}
function fixture() {
  const provider = new RecordingProvider();
  const scheduler = new VirtualScheduler();
  let fills = 0;
  const subtle = createCrypto({ fill(bytes: Uint8Array): void { fills++; bytes.fill(0x37); } }, provider, scheduler).subtle;
  function settle<T>(promise: Promise<T>): Promise<T> { scheduler.runPending(); return promise; }
  async function imported(name: Curve448FixtureName, type: "public" | "private", extractable = true): Promise<CryptoKey> {
    return settle(subtle.importKey(type === "public" ? "spki" : "pkcs8", type === "public" ? curve448Spki(name) : curve448Pkcs8(name), name, extractable, usagesFor(name, type)));
  }
  return { provider, scheduler, subtle, settle, imported, fills: () => fills };
}
function dom(name: string): (error: unknown) => boolean { return error => error instanceof DOMException && error.name === name; }
function pair(result: CryptoKey | CryptoKeyPair): CryptoKeyPair { assert.ok("privateKey" in result && "publicKey" in result); return result; }
function jwk(result: ArrayBuffer | JsonWebKeyObject): JsonWebKeyObject { assert.ok(!(result instanceof ArrayBuffer)); return result; }
function buffer(result: ArrayBuffer | JsonWebKeyObject): Uint8Array { assert.ok(result instanceof ArrayBuffer); return new Uint8Array(result); }
function parts(name: Curve448FixtureName, value: JsonWebKeyObject): CryptoOkpComponents {
  const x = new Uint8Array(Buffer.from(value.x!, "base64url"));
  return value.d === undefined ? { family: "OKP", namedCurve: name, x }
    : { family: "OKP", namedCurve: name, x, d: new Uint8Array(Buffer.from(value.d, "base64url")) };
}
function der(tag: number, ...parts: readonly Uint8Array[]): Uint8Array {
  const value = Buffer.concat(parts);
  assert.ok(value.length < 128);
  return new Uint8Array(Buffer.concat([Buffer.from([tag, value.length]), value]));
}
function publicDer(name: Curve448FixtureName, x: Uint8Array): Uint8Array {
  return der(0x30, der(0x30, der(6, new Uint8Array([0x2b, 0x65, name === "Ed448" ? 0x71 : 0x6f]))), der(3, new Uint8Array([0]), x));
}
function privateDer(name: Curve448FixtureName, d: Uint8Array): Uint8Array {
  return der(0x30, der(2, new Uint8Array([0])), der(0x30, der(6, new Uint8Array([0x2b, 0x65, name === "Ed448" ? 0x71 : 0x6f]))), der(4, der(4, d)));
}

for (const name of ["Ed448", "X448"] as const) {
  const width = name === "Ed448" ? 57 : 56;

  test(name + " imports and exports each key format with name-only metadata", async () => {
    const f = fixture();
    for (const format of ["raw", "spki", "jwk"] as const) {
      const data = format === "raw" ? curve448RawPublic(name) : format === "spki" ? curve448Spki(name) : curve448PublicJwk(name);
      const usages = usagesFor(name, "public");
      const key = await f.settle(f.subtle.importKey(format, data, name.toLowerCase(), true, usages));
      assert.equal(key.type, "public");
      assert.equal(key.extractable, true);
      assert.deepEqual(key.algorithm, { name });
      assert.deepEqual(Object.keys(key.algorithm), ["name"]);
      assert.deepEqual(key.usages, usages);
      const input = f.provider.importInput;
      assert.ok(input !== undefined);
      if (input.format === "raw" || input.format === "spki") assert.equal(input.bytes, data);
      else assert.ok(input.format === "components" && input.components.family === "OKP");
      const raw = buffer(await f.settle(f.subtle.exportKey("raw", key)));
      assert.equal(raw.byteLength, width);
      assert.deepEqual(raw, curve448RawPublic(name));
      assert.deepEqual(buffer(await f.settle(f.subtle.exportKey("spki", key))), curve448Spki(name));
      assert.deepEqual(jwk(await f.settle(f.subtle.exportKey("jwk", key))), {
        ...curve448PublicJwk(name), ...(name === "Ed448" ? { alg: "Ed448" } : {}), ext: true, key_ops: usages,
      });
    }
    for (const format of ["pkcs8", "jwk"] as const) {
      const key = await f.settle(f.subtle.importKey(format, format === "pkcs8" ? curve448Pkcs8(name) : curve448PrivateJwk(name), name, true, usagesFor(name, "private")));
      assert.equal(key.type, "private");
      assert.deepEqual(key.algorithm, { name });
      assert.deepEqual(buffer(await f.settle(f.subtle.exportKey("pkcs8", key))), curve448Pkcs8(name));
      assert.deepEqual(jwk(await f.settle(f.subtle.exportKey("jwk", key))), {
        ...curve448PrivateJwk(name), ...(name === "Ed448" ? { alg: "Ed448" } : {}), ext: true, key_ops: usagesFor(name, "private"),
      });
    }
    assert.equal(f.provider.imports, 5);
    assert.equal(f.fills(), 0);
  });

  test(name + " generation splits usages and keeps public metadata snapshots independent", async () => {
    const f = fixture();
    const usages = name === "Ed448" ? ["verify", "sign", "verify"] : ["deriveBits", "deriveKey", "deriveBits"];
    const generated = pair(await f.settle(f.subtle.generateKey(name, false, usages)));
    assert.equal(generated.publicKey.extractable, true);
    assert.equal(generated.privateKey.extractable, false);
    assert.deepEqual(generated.publicKey.usages, usagesFor(name, "public"));
    assert.deepEqual(generated.privateKey.usages, usagesFor(name, "private"));
    assert.deepEqual(generated.publicKey.algorithm, { name });
    assert.deepEqual(generated.privateKey.algorithm, { name });
    assert.notEqual(generated.publicKey.algorithm, generated.privateKey.algorithm);
    assert.equal(generated.publicKey.algorithm, generated.publicKey.algorithm);
    assert.equal(buffer(await f.settle(f.subtle.exportKey("raw", generated.publicKey))).byteLength, width);
    const publicAlgorithm = generated.publicKey.algorithm as { name: string };
    publicAlgorithm.name = "changed";
    generated.publicKey.usages.push("encrypt");
    assert.deepEqual(jwk(await f.settle(f.subtle.exportKey("jwk", generated.publicKey))).key_ops, usagesFor(name, "public"));
    assert.deepEqual(generated.privateKey.algorithm, { name });
    assert.deepEqual(f.provider.generationInput, { family: "OKP", namedCurve: name });
    assert.equal(f.provider.generations, 1);
    assert.equal(f.fills(), 0);
  });

  test(name + " rejects generation usages before native work and empty private usages afterwards", async () => {
    const f = fixture();
    for (const usage of name === "Ed448" ? ["deriveBits", "deriveKey", "encrypt"] : ["sign", "verify", "encrypt"]) {
      await assert.rejects(f.settle(f.subtle.generateKey(name, true, [usage])), dom("SyntaxError"));
    }
    assert.equal(f.provider.generations, 0);
    await assert.rejects(f.settle(f.subtle.generateKey(name, true, [])), dom("SyntaxError"));
    assert.equal(f.provider.generations, 1);
    if (name === "Ed448") {
      await assert.rejects(f.settle(f.subtle.generateKey(name, true, ["verify"])), dom("SyntaxError"));
      assert.equal(f.provider.generations, 2);
    }
  });

  test(name + " validates import usage before encoding and empty private usage after consistency", async () => {
    const f = fixture();
    for (const format of ["raw", "spki", "pkcs8"] as const) {
      await assert.rejects(f.settle(f.subtle.importKey(format, new Uint8Array(), name, true, ["encrypt"])), dom("SyntaxError"));
      await assert.rejects(f.settle(f.subtle.importKey(format, new Uint8Array(), name, true, [])), dom("DataError"));
    }
    await assert.rejects(f.settle(f.subtle.importKey("jwk", { kty: "wrong", d: "" }, name, true, ["verify"])), dom("SyntaxError"));
    assert.equal(f.provider.imports, 0);
