    const f = fixture();
    const wrapping = await f.settle(f.subtle.importKey("raw", new Uint8Array(16), "AES-GCM", false, ["encrypt", "unwrapKey"]));
    const cipher = { name: "AES-GCM", iv: new Uint8Array(12) };
