// Native primitive controls. Published answers: RFC 6979 §§A.2.5–A.2.7
// and RFC 5903 §§8.1–8.3; no host Web Crypto implementation is called.
import assert from "node:assert/strict";
import { Buffer } from "node:buffer";
import { createPrivateKey, createPublicKey, verify } from "node:crypto";
import test from "node:test";
import type {
  CryptoEcComponents,
  CryptoEcdsaSignature,
  CryptoFailure,
  CryptoKeyHandle,
  CryptoKeyRecord,
  CryptoNamedCurve,
} from "../src/provider/crypto.ts";
import {
  ecdhPrivateJwk,
  ecdhPublicJwk,
  ecdhSecret,
  ecdsaMessage,
  ecdsaSignature,
  ecOrder,
  ecPkcs8,
  ecPrivateJwk,
  ecPublicJwk,
  ecRawPublic,
  ecSpki,
} from "./ec-fixtures.ts";
import type { EcFixturePrivateJwk, EcFixturePublicJwk } from "./ec-fixtures.ts";
import { NodeCryptoProvider } from "./node-crypto-provider.ts";

function success<T extends object>(result: T | CryptoFailure): T {
  if ("failure" in result) assert.fail("Unexpected native failure: " + result.failure);
  return result;
}

function components(jwk: EcFixturePrivateJwk | EcFixturePublicJwk): CryptoEcComponents {
  const result: CryptoEcComponents = {
    family: "EC", namedCurve: jwk.crv,
    x: new Uint8Array(Buffer.from(jwk.x, "base64url")),
    y: new Uint8Array(Buffer.from(jwk.y, "base64url")),
  };
  return "d" in jwk ? { ...result, d: new Uint8Array(Buffer.from(jwk.d, "base64url")) } : result;
}

function imported(provider: NodeCryptoProvider, curve: CryptoNamedCurve, type: "public" | "private"): CryptoKeyRecord {
  return success(provider.importKey({
    format: type === "public" ? "spki" : "pkcs8", bytes: type === "public" ? ecSpki(curve) : ecPkcs8(curve),
  }));
}

function signatureParts(bytes: Uint8Array): CryptoEcdsaSignature {
  const width = bytes.byteLength / 2;
  return { kind: "ecdsa", r: bytes.subarray(0, width), s: bytes.subarray(width) };
}

function fixedSignature(signature: CryptoEcdsaSignature, width: number): Uint8Array {
  const bytes = new Uint8Array(width * 2);
  bytes.set(signature.r, width - signature.r.byteLength);
  bytes.set(signature.s, 2 * width - signature.s.byteLength);
  return bytes;
}

function assertOwned(bytes: Uint8Array): void {
  assert.ok(bytes.buffer instanceof ArrayBuffer);
  assert.equal(bytes.byteOffset, 0);
  assert.equal(bytes.byteLength, bytes.buffer.byteLength);
}

for (const curve of ["P-256", "P-384", "P-521"] as const) {
  test(`native EC ${curve} imports raw, SPKI, PKCS8 and components with actual metadata`, () => {
    const provider = new NodeCryptoProvider();
    const publicInputs = [
      { format: "raw", family: "EC", namedCurve: curve, bytes: ecRawPublic(curve) },
      { format: "spki", bytes: ecSpki(curve) },
      { format: "components", components: components(ecPublicJwk(curve)) },
    ] as const;
    const privateInputs = [
      { format: "pkcs8", bytes: ecPkcs8(curve) },
      { format: "components", components: components(ecPrivateJwk(curve)) },
    ] as const;
    for (const input of [...publicInputs, ...privateInputs]) {
      const key = success(provider.importKey(input));
      const type = input.format === "pkcs8" || (input.format === "components" && input.components.d !== undefined)
        ? "private" : "public";
      assert.deepEqual(key.info, { family: "EC", type, namedCurve: curve });
      assert.deepEqual(Object.keys(key.handle), []);
      assert.deepEqual(success(provider.exportComponents(key.handle)), components(type === "private" ? ecPrivateJwk(curve) : ecPublicJwk(curve)));
    }
  });

  test(`native EC ${curve} imports own material and exports exact independent buffers`, () => {
    const provider = new NodeCryptoProvider();
    const input = components(ecPrivateJwk(curve));
    const privateKey = success(provider.importKey({ format: "components", components: input }));
    input.x.fill(0);
    input.y.fill(0);
    input.d!.fill(0);
    const first = success(provider.exportComponents(privateKey.handle));
    const second = success(provider.exportComponents(privateKey.handle));
    assert.deepEqual(first, components(ecPrivateJwk(curve)));
    assert.ok(first.family === "EC" && second.family === "EC");
    for (const member of ["x", "y", "d"] as const) {
      assertOwned(first[member]!);
      assert.notEqual(first[member]!.buffer, second[member]!.buffer);
      first[member]!.fill(0);
    }
    assert.deepEqual(second, components(ecPrivateJwk(curve)));
    const raw = ecRawPublic(curve);
    const offset = new Uint8Array(raw.byteLength + 8);
    offset.set(raw, 3);
    const publicKey = success(provider.importKey({
      format: "raw", family: "EC", namedCurve: curve, bytes: offset.subarray(3, raw.byteLength + 3),
    }));
    offset.fill(0);
    for (const [record, format, expected] of [
      [privateKey, "pkcs8", ecPkcs8(curve)],
      [publicKey, "spki", ecSpki(curve)],
      [publicKey, "raw", raw],
    ] as const) {
      const output = success(provider.exportKey(record.handle, format));
      const repeat = success(provider.exportKey(record.handle, format));
      assertOwned(output);
      assertOwned(repeat);
      assert.deepEqual(output, expected);
      assert.notEqual(output.buffer, repeat.buffer);
      output.fill(0);
      assert.deepEqual(repeat, expected);
    }
    assert.deepEqual(provider.exportKey(privateKey.handle, "raw"), { failure: "operation" });
    assert.deepEqual(provider.exportKey(privateKey.handle, "spki"), { failure: "operation" });
    assert.deepEqual(provider.exportKey(publicKey.handle, "pkcs8"), { failure: "operation" });
  });

  test(`native EC ${curve} regenerates the private key's actual point for shared consistency checks`, () => {
    const provider = new NodeCryptoProvider();
    const original = ecPrivateJwk(curve);
    const unrelated = ecdhPublicJwk(curve, "initiator");
    const mismatched = { ...original, x: unrelated.x, y: unrelated.y };
    // This control establishes why native import success/export alone cannot
    // validate the supplied public point: Node preserves this inconsistent pair.
    const native = createPrivateKey({ key: mismatched, format: "jwk" });
    assert.equal(createPublicKey(native).export({ format: "jwk" }).x, unrelated.x);
    for (const input of [
      { format: "components", components: components(mismatched) },
      { format: "pkcs8", bytes: native.export({ format: "der", type: "pkcs8" }) },
    ] as const) {
      const key = success(provider.importKey(input));
      // The shared import algorithm compares these actual components with its
      // parsed originals, and reports DataError when they differ.
      assert.deepEqual(success(provider.exportComponents(key.handle)), components(original));
    }
  });

  test(`native EC ${curve} validates mathematical public points and private scalar bounds`, () => {
    const provider = new NodeCryptoProvider();
    const valid = components(ecPrivateJwk(curve));
    for (const d of [new Uint8Array(valid.d!.byteLength), ecOrder(curve)]) {
      assert.deepEqual(provider.importKey({ format: "components", components: { ...valid, d } }), { failure: "invalid-key" });
    }
    const zeroPoint = new Uint8Array(1 + 2 * valid.x.byteLength);
    zeroPoint[0] = 4;
    assert.deepEqual(provider.importKey({ format: "raw", family: "EC", namedCurve: curve, bytes: zeroPoint }), { failure: "invalid-key" });
    assert.deepEqual(provider.importKey({
      format: "components", components: { family: "EC", namedCurve: curve, x: valid.x, y: new Uint8Array(valid.y.byteLength) },
    }), { failure: "invalid-key" });
    const invalidPoint = ecSpki(curve);
    invalidPoint[invalidPoint.length - 1] = invalidPoint[invalidPoint.length - 1]! ^ 1;
    assert.deepEqual(provider.importKey({ format: "spki", bytes: invalidPoint }), { failure: "invalid-key" });
  });

  test(`native EC ${curve} generation produces independent usable key handles`, () => {
    const provider = new NodeCryptoProvider();
    const pair = success(provider.generateKeyPair({ family: "EC", namedCurve: curve }));
    assert.deepEqual(pair.publicKey.info, { family: "EC", type: "public", namedCurve: curve });
    assert.deepEqual(pair.privateKey.info, { family: "EC", type: "private", namedCurve: curve });
    assert.notEqual(pair.publicKey.handle, pair.privateKey.handle);
    const publicParts = success(provider.exportComponents(pair.publicKey.handle));
    const privateParts = success(provider.exportComponents(pair.privateKey.handle));
    assert.ok(publicParts.family === "EC" && privateParts.family === "EC");
    assert.deepEqual(publicParts.x, privateParts.x);
    assert.deepEqual(publicParts.y, privateParts.y);
    assert.notEqual(publicParts.x.buffer, privateParts.x.buffer);
    const signature = success(provider.sign({ name: "ECDSA", hash: "SHA-256" }, pair.privateKey.handle, ecdsaMessage()));
    assert.ok(signature.kind === "ecdsa");
    assert.equal(provider.verify({ name: "ECDSA", hash: "SHA-256" }, pair.publicKey.handle,
      signatureParts(fixedSignature(signature, publicParts.x.byteLength)), ecdsaMessage()), true);
  });

  for (const hash of ["SHA-1", "SHA-256", "SHA-384", "SHA-512"] as const) {
    test(`native ECDSA ${curve}/${hash} verifies RFC 6979 and signs through the selected hash`, () => {
      const provider = new NodeCryptoProvider();
      const publicKey = imported(provider, curve, "public");
      const privateKey = imported(provider, curve, "private");
      const parameters = { name: "ECDSA", hash } as const;
      const answer = signatureParts(ecdsaSignature(curve, hash));
      assert.equal(provider.verify(parameters, publicKey.handle, answer, ecdsaMessage()), true);
      assert.equal(provider.verify(parameters, publicKey.handle, answer, new Uint8Array()), false);
      assert.equal(provider.verify({ name: "ECDSA", hash: hash === "SHA-256" ? "SHA-384" : "SHA-256" },
        publicKey.handle, answer, ecdsaMessage()), false);
      answer.s[answer.s.length - 1] = answer.s[answer.s.length - 1]! ^ 1;
      assert.equal(provider.verify(parameters, publicKey.handle, answer, ecdsaMessage()), false);
      const generated = success(provider.sign(parameters, privateKey.handle, ecdsaMessage()));
      assert.ok(generated.kind === "ecdsa");
      const width = answer.r.byteLength;
      for (const part of [generated.r, generated.s]) {
        assertOwned(part);
        assert.ok(part.byteLength > 0 && part.byteLength <= width);
        assert.notEqual(part[0], 0, "native signature integers are minimal and nonzero");
      }
      assert.notEqual(generated.r.buffer, generated.s.buffer);
      const p1363 = fixedSignature(generated, width);
      assert.equal(verify(hash.toLowerCase().replace("-", ""), ecdsaMessage(), {
        key: createPublicKey({ key: Buffer.from(ecSpki(curve)), format: "der", type: "spki" }), dsaEncoding: "ieee-p1363",
      }, p1363), true);
      assert.equal(provider.verify(parameters, publicKey.handle, signatureParts(p1363), ecdsaMessage()), true);
    });
  }

  test(`native ECDSA ${curve} returns false for invalid scalar encodings and signature kinds`, () => {
    const provider = new NodeCryptoProvider();
    const publicKey = imported(provider, curve, "public");
    const parameters = { name: "ECDSA", hash: "SHA-256" } as const;
    const valid = signatureParts(ecdsaSignature(curve));
    for (const r of [new Uint8Array(valid.r.byteLength), ecOrder(curve), valid.r.subarray(1), new Uint8Array(valid.r.byteLength + 1)]) {
      assert.equal(provider.verify(parameters, publicKey.handle, { kind: "ecdsa", r, s: valid.s }, ecdsaMessage()), false);
    }
    assert.equal(provider.verify(parameters, publicKey.handle, { kind: "ecdsa", r: valid.r, s: ecOrder(curve) }, ecdsaMessage()), false);
    assert.equal(provider.verify(parameters, publicKey.handle, { kind: "bytes", bytes: ecdsaSignature(curve) }, ecdsaMessage()), false);
    assert.equal(provider.verify(parameters, imported(provider, curve, "private").handle, valid, ecdsaMessage()), false);
    assert.deepEqual(provider.sign(parameters, publicKey.handle, ecdsaMessage()), { failure: "invalid-key" });
  });

  test(`native ECDH ${curve} returns RFC 5903's full-width shared secret in both directions`, () => {
    const first = new NodeCryptoProvider();
    const second = new NodeCryptoProvider();
    const initiator = success(first.importKey({ format: "components", components: components(ecdhPrivateJwk(curve, "initiator")) }));
    const responder = success(second.importKey({ format: "components", components: components(ecdhPrivateJwk(curve, "responder")) }));
    const initiatorPublic = success(first.importKey({ format: "components", components: components(ecdhPublicJwk(curve, "initiator")) }));
    const responderPublic = success(second.importKey({ format: "components", components: components(ecdhPublicJwk(curve, "responder")) }));
    const forward = success(first.derive({ name: "ECDH", publicKey: responderPublic.handle }, initiator.handle));
    const reverse = success(second.derive({ name: "ECDH", publicKey: initiatorPublic.handle }, responder.handle));
    assert.deepEqual(forward, ecdhSecret(curve));
    assert.deepEqual(reverse, ecdhSecret(curve));
    assertOwned(forward);
    assertOwned(reverse);
    assert.notEqual(forward.buffer, reverse.buffer);
    forward.fill(0);
    assert.deepEqual(reverse, ecdhSecret(curve));
    assert.deepEqual(success(first.derive({ name: "ECDH", publicKey: responderPublic.handle }, initiator.handle)), ecdhSecret(curve));
    if (curve === "P-521") assert.equal(reverse.byteLength, 66);
  });
}

test("native EC foreign handles and incompatible agreements return failure values", () => {
  const provider = new NodeCryptoProvider();
  const foreign = {} as CryptoKeyHandle;
  const publicKey = imported(provider, "P-256", "public");
  const privateKey = imported(provider, "P-256", "private");
  const differentCurve = imported(provider, "P-384", "public");
  const secret = success(provider.importKey({ format: "raw", family: "secret", bytes: new Uint8Array(16) }));
  assert.deepEqual(provider.exportKey(foreign, "raw"), { failure: "invalid-key" });
  assert.deepEqual(provider.exportComponents(foreign), { failure: "invalid-key" });
  assert.deepEqual(provider.sign({ name: "ECDSA", hash: "SHA-256" }, foreign, ecdsaMessage()), { failure: "invalid-key" });
  assert.equal(provider.verify({ name: "ECDSA", hash: "SHA-256" }, foreign, signatureParts(ecdsaSignature()), ecdsaMessage()), false);
  for (const [base, peer] of [[foreign, publicKey.handle], [privateKey.handle, foreign], [publicKey.handle, publicKey.handle],
    [privateKey.handle, privateKey.handle], [secret.handle, publicKey.handle], [privateKey.handle, secret.handle]]) {
    assert.deepEqual(provider.derive({ name: "ECDH", publicKey: peer! }, base!), { failure: "invalid-key" });
  }
  assert.deepEqual(provider.derive({ name: "ECDH", publicKey: differentCurve.handle }, privateKey.handle), { failure: "operation" });
  assert.deepEqual(provider.derive({ name: "X25519", publicKey: publicKey.handle }, privateKey.handle), { failure: "invalid-key" });
  assert.deepEqual(provider.derive({ name: "X448", publicKey: publicKey.handle }, privateKey.handle), { failure: "invalid-key" });
  assert.deepEqual(provider.generateKeyPair({ family: "EC", namedCurve: "unsupported" as CryptoNamedCurve }), { failure: "operation" });
});

// Web Cryptography §§14.3.11–12, 23–24, 27–30: EC key wrapping uses the
// existing shared export/import and JSON policy, never a second crypto adapter.
import assert from "node:assert/strict";
import test from "node:test";
import { DOMException } from "../src/core/errors.ts";
import { createCrypto } from "../src/crypto/crypto.ts";
import type { KeyUsage } from "../src/crypto/crypto-key.ts";
import type { CryptoNamedCurve } from "../src/provider/crypto.ts";
import { VirtualScheduler } from "../src/provider/virtual-time.ts";
import { ecPrivateJwk, ecPublicJwk, ecdsaMessage, ecdsaSignature } from "./ec-fixtures.ts";
import { NodeCryptoProvider } from "./node-crypto-provider.ts";
import { rsaPkcs8, rsaSpki } from "./rsa-fixtures.ts";

function fixture() {
  const scheduler = new VirtualScheduler();
  const subtle = createCrypto({ fill(bytes: Uint8Array): void { bytes.fill(1); } }, new NodeCryptoProvider(), scheduler).subtle;
  function settle<T>(promise: Promise<T>): Promise<T> { scheduler.runPending(); return promise; }
  async function ec(curve: CryptoNamedCurve, name: "ECDSA" | "ECDH", type: "private" | "public") {
    const usages: KeyUsage[] = name === "ECDSA" ? [type === "private" ? "sign" : "verify"]
      : type === "private" ? ["deriveBits", "deriveKey"] : [];
    return settle(subtle.importKey("jwk", type === "private" ? ecPrivateJwk(curve) : ecPublicJwk(curve),
      { name, namedCurve: curve }, true, usages));
  }
  async function wrapping(name = "AES-GCM") {
    return settle(subtle.importKey("raw", new Uint8Array(16).fill(0x67), name, false, ["wrapKey", "unwrapKey"]));
  }
  return { subtle, settle, ec, wrapping };
}

function dom(name: string): (error: unknown) => boolean {
  return error => error instanceof DOMException && error.name === name;
}

for (const curve of ["P-256", "P-384", "P-521"] as const) {
  for (const name of ["ECDSA", "ECDH"] as const) {
    for (const [type, format] of [["public", "raw"], ["public", "spki"], ["private", "pkcs8"], ["public", "jwk"], ["private", "jwk"]] as const) {
      test(`AES-GCM wraps and unwraps ${curve} ${name} ${type} ${format}`, async () => {
        const f = fixture();
        const key = await f.ec(curve, name, type);
        const wrapping = await f.wrapping();
        const original = await f.settle(f.subtle.exportKey(format, key));
        const algorithm = { name: "AES-GCM", iv: new Uint8Array(12), additionalData: new Uint8Array([2, 7, 1, 8]) };
        const wrapped = await f.settle(f.subtle.wrapKey(format, key, wrapping, algorithm));
        const restored = await f.settle(f.subtle.unwrapKey(format, wrapped, wrapping, algorithm,
          { name, namedCurve: curve }, true, key.usages));
        assert.equal(restored.type, type);
        assert.deepEqual(restored.algorithm, key.algorithm);
        assert.deepEqual(restored.usages, key.usages);
        assert.deepEqual(await f.settle(f.subtle.exportKey(format, restored)), original);
        if (name === "ECDSA") {
          const verifyKey = type === "public" ? restored : await f.ec(curve, name, "public");
          const signature = type === "public" ? ecdsaSignature(curve, "SHA-256")
            : await f.settle(f.subtle.sign({ name, hash: "SHA-256" }, restored, ecdsaMessage()));
          assert.equal(await f.settle(f.subtle.verify({ name, hash: "SHA-256" }, verifyKey, signature, ecdsaMessage())), true);
        } else {
          const publicKey = type === "public" ? restored : await f.ec(curve, name, "public");
          const privateKey = type === "private" ? restored : await f.ec(curve, name, "private");
          const bits = await f.settle(f.subtle.deriveBits({ name, public: publicKey }, privateKey));
          const originalPublic = type === "public" ? key : publicKey;
          const originalPrivate = type === "private" ? key : privateKey;
          assert.deepEqual(bits, await f.settle(f.subtle.deriveBits({ name, public: originalPublic }, originalPrivate)));
        }
      });
    }
  }

  test(`AES-KW pads ${curve} EC JWK JSON and restores both key types`, async () => {
    const f = fixture();
    const wrapping = await f.wrapping("AES-KW");
    for (const type of ["public", "private"] as const) {
      const key = await f.ec(curve, "ECDSA", type);
      const wrapped = await f.settle(f.subtle.wrapKey("jwk", key, wrapping, "AES-KW"));
      assert.equal(wrapped.byteLength % 8, 0);
      const restored = await f.settle(f.subtle.unwrapKey("jwk", wrapped, wrapping, "AES-KW",
        { name: "ECDSA", namedCurve: curve }, true, key.usages));
      assert.deepEqual(await f.settle(f.subtle.exportKey("jwk", restored)), await f.settle(f.subtle.exportKey("jwk", key)));
    }
    const raw = await f.ec(curve, "ECDSA", "public");
    await assert.rejects(f.settle(f.subtle.wrapKey("raw", raw, wrapping, "AES-KW")), dom("OperationError"));
  });
}

test("RSA-OAEP wraps the largest supported raw EC public key", async () => {
  const f = fixture();
  const publicKey = await f.settle(f.subtle.importKey("spki", rsaSpki(), { name: "RSA-OAEP", hash: "SHA-256" }, false, ["wrapKey"]));
  const privateKey = await f.settle(f.subtle.importKey("pkcs8", rsaPkcs8(), { name: "RSA-OAEP", hash: "SHA-256" }, false, ["unwrapKey"]));
  const key = await f.ec("P-521", "ECDSA", "public");
  const wrapped = await f.settle(f.subtle.wrapKey("raw", key, publicKey, "RSA-OAEP"));
  const restored = await f.settle(f.subtle.unwrapKey("raw", wrapped, privateKey, "RSA-OAEP",
    { name: "ECDSA", namedCurve: "P-521" }, true, ["verify"]));
  assert.deepEqual(await f.settle(f.subtle.exportKey("raw", restored)), await f.settle(f.subtle.exportKey("raw", key)));
});

test("EC unwrap enforces curve and JWK usage policy after authenticated decryption", async () => {
  const f = fixture();
  const wrapping = await f.wrapping();
  const key = await f.ec("P-256", "ECDSA", "private");
  const algorithm = { name: "AES-GCM", iv: new Uint8Array(12) };
  const wrapped = new Uint8Array(await f.settle(f.subtle.wrapKey("jwk", key, wrapping, algorithm)));
  await assert.rejects(f.settle(f.subtle.unwrapKey("jwk", wrapped, wrapping, algorithm,
    { name: "ECDSA", namedCurve: "P-384" }, true, ["sign"])), dom("DataError"));
  await assert.rejects(f.settle(f.subtle.unwrapKey("jwk", wrapped, wrapping, algorithm,
    { name: "ECDH", namedCurve: "P-256" }, true, ["deriveKey"])), dom("DataError"));
  wrapped[0]! ^= 1;
  await assert.rejects(f.settle(f.subtle.unwrapKey("jwk", wrapped, wrapping, algorithm,
    { name: "ECDSA", namedCurve: "unsupported" }, true, ["sign"])), dom("OperationError"));
});

test("EC unwrap snapshots cipher parameters before reading namedCurve", async () => {
  const f = fixture();
  const wrapping = await f.wrapping();
  const key = await f.ec("P-256", "ECDSA", "public");
  const iv = new Uint8Array(12).fill(0x1a);
  const additionalData = new Uint8Array([1, 2, 3]);
  const algorithm = { name: "AES-GCM", iv, additionalData };
  const wrapped = await f.settle(f.subtle.wrapKey("spki", key, wrapping, algorithm));
  const restored = await f.settle(f.subtle.unwrapKey("spki", wrapped, wrapping, algorithm, {
    name: "ECDSA",
    get namedCurve() { iv.fill(0); additionalData.fill(0); return "P-256"; },
  }, true, ["verify"]));
  assert.deepEqual(await f.settle(f.subtle.exportKey("spki", restored)), await f.settle(f.subtle.exportKey("spki", key)));
});

// Specification controls, not copies of WPT.
// Web Cryptography §§23.7.1–2 and 24.4.2: https://w3c.github.io/webcrypto/
// Independent known answers: RFC 6979 Appendix A.2.5–7 and RFC 5903 §8;
// source and license notices are retained in ec-fixtures.ts.
import assert from "node:assert/strict";
import { createPublicKey, verify as verifySignature } from "node:crypto";
import test from "node:test";
import { DOMException } from "../src/core/errors.ts";
import type { EcAlgorithmName } from "../src/crypto/algorithms.ts";
import { createCrypto } from "../src/crypto/crypto.ts";
import { createCryptoKey, getCryptoKeySlots } from "../src/crypto/crypto-key.ts";
import type { CryptoKey, KeyUsage } from "../src/crypto/crypto-key.ts";
import type {
  CryptoDerivationParameters,
  CryptoDigestName,
  CryptoFailure,
  CryptoKeyHandle,
  CryptoNamedCurve,
  CryptoSignature,
  CryptoSignatureParameters,
} from "../src/provider/crypto.ts";
import { VirtualScheduler } from "../src/provider/virtual-time.ts";
import { NodeCryptoProvider } from "./node-crypto-provider.ts";
import {
  ecOrder, ecPrivateJwk, ecPublicJwk, ecSpki,
  ecdhPrivateJwk, ecdhPublicJwk, ecdhSecret, ecdsaMessage, ecdsaSignature,
} from "./ec-fixtures.ts";

class RecordingProvider extends NodeCryptoProvider {
  signs = 0;
  verifies = 0;
  derives = 0;
  digests = 0;
  signed: Uint8Array | undefined;
  verified: Uint8Array | undefined;
  signature: CryptoSignature | undefined;
  signatureParameters: CryptoSignatureParameters | undefined;
  agreementParameters: CryptoDerivationParameters | undefined;
  agreementKey: CryptoKeyHandle | undefined;
  failure: CryptoFailure | undefined;
  returnedSignature: CryptoSignature | undefined;
  returnedSecret: Uint8Array | undefined;

  override digest(name: CryptoDigestName, bytes: Uint8Array): Uint8Array | CryptoFailure {
    this.digests++;
    return super.digest(name, bytes);
  }

  override sign(parameters: CryptoSignatureParameters, key: CryptoKeyHandle, bytes: Uint8Array): CryptoSignature | CryptoFailure {
    this.signs++;
    this.signed = bytes;
    this.signatureParameters = parameters;
    return this.failure ?? this.returnedSignature ?? super.sign(parameters, key, bytes);
  }

  override verify(parameters: CryptoSignatureParameters, key: CryptoKeyHandle, signature: CryptoSignature, bytes: Uint8Array): boolean | CryptoFailure {
    this.verifies++;
    this.verified = bytes;
    this.signature = signature;
    this.signatureParameters = parameters;
    return super.verify(parameters, key, signature, bytes);
  }

  override derive(parameters: CryptoDerivationParameters, key: CryptoKeyHandle): Uint8Array | CryptoFailure {
    this.derives++;
    this.agreementParameters = parameters;
    this.agreementKey = key;
    return this.failure ?? this.returnedSecret ?? super.derive(parameters, key);
  }
}

function fixture() {
  const provider = new RecordingProvider();
  const scheduler = new VirtualScheduler();
  const random = { fill(bytes: Uint8Array): void { bytes.fill(0x42); } };
  const subtle = createCrypto(random, provider, scheduler).subtle;
  function settle<T>(promise: Promise<T>): Promise<T> { scheduler.runPending(); return promise; }
  async function key(name: EcAlgorithmName, curve: CryptoNamedCurve, type: "public" | "private", usages?: readonly KeyUsage[]): Promise<CryptoKey> {
    const use: readonly KeyUsage[] = usages ?? (name === "ECDH"
      ? type === "public" ? [] : ["deriveBits"]
      : type === "public" ? ["verify"] : ["sign"]);
    return settle(subtle.importKey("jwk", type === "public" ? ecPublicJwk(curve) : ecPrivateJwk(curve), { name, namedCurve: curve }, true, use));
  }
  async function agreement(curve: CryptoNamedCurve) {
    const algorithm = { name: "ECDH", namedCurve: curve };
    const privateKey = await settle(subtle.importKey("jwk", ecdhPrivateJwk(curve, "initiator"), algorithm, false, ["deriveBits"]));
    const publicKey = await settle(subtle.importKey("jwk", ecdhPublicJwk(curve, "responder"), algorithm, false, []));
    return { privateKey, publicKey };
  }
  return { provider, scheduler, subtle, settle, key, agreement };
}

function dom(name: string): (error: unknown) => boolean {
  return error => error instanceof DOMException && error.name === name;
}

const curves: readonly { name: CryptoNamedCurve; width: number }[] = [
  { name: "P-256", width: 32 }, { name: "P-384", width: 48 }, { name: "P-521", width: 66 },
];
const hashes: readonly CryptoDigestName[] = ["SHA-1", "SHA-256", "SHA-384", "SHA-512"];

for (const curve of curves) {
  for (const hash of hashes) {
    test("ECDSA " + curve.name + " " + hash + " verifies RFC 6979's independent fixed-width answer", async () => {
      const f = fixture();
      const publicKey = await f.key("ECDSA", curve.name, "public");
      const signature = ecdsaSignature(curve.name, hash);
      const bytes = ecdsaMessage();
      assert.equal(signature.byteLength, curve.width * 2);
      assert.equal(await f.settle(f.subtle.verify({ name: "ECDSA", hash }, publicKey, signature, bytes)), true);
      assert.equal(f.provider.verifies, 1);
      assert.equal(f.provider.digests, 0, "the whole signature operation crosses one native boundary");
      assert.equal(f.provider.verified, bytes);
      assert.deepEqual(f.provider.signatureParameters, { name: "ECDSA", hash });
      assert.equal(f.provider.signature!.kind, "ecdsa");
      if (f.provider.signature!.kind !== "ecdsa") assert.fail("wrong native signature kind");
      assert.equal(f.provider.signature!.r.buffer, signature.buffer);
      assert.equal(f.provider.signature!.s.buffer, signature.buffer);
      assert.equal(f.provider.signature!.r.byteLength, curve.width);
      assert.equal(f.provider.signature!.s.byteOffset, signature.byteOffset + curve.width);
      const damaged = signature.slice(); damaged[curve.width - 1]! ^= 1;
      assert.equal(await f.settle(f.subtle.verify({ name: "ECDSA", hash }, publicKey, damaged, bytes)), false);
      assert.equal(await f.settle(f.subtle.verify({ name: "ECDSA", hash }, publicKey, signature, new Uint8Array())), false);
      const otherHash = hash === "SHA-256" ? "SHA-384" : "SHA-256";
      assert.equal(await f.settle(f.subtle.verify({ name: "ECDSA", hash: otherHash }, publicKey, signature, bytes)), false);
    });
  }

  test("ECDSA " + curve.name + " signs with each requested hash into fresh P1363 output", async () => {
    const f = fixture();
    const privateKey = await f.key("ECDSA", curve.name, "private");
    const publicKey = await f.key("ECDSA", curve.name, "public");
    const nativePublic = createPublicKey({ key: Buffer.from(ecSpki(curve.name)), format: "der", type: "spki" });
    for (const hash of hashes) {
      for (const bytes of [ecdsaMessage(), new Uint8Array()]) {
        const signature = await f.settle(f.subtle.sign({ name: "ECDSA", hash }, privateKey, bytes));
        assert.equal(signature.byteLength, curve.width * 2);
        assert.equal(f.provider.signed, bytes);
        assert.deepEqual(f.provider.signatureParameters, { name: "ECDSA", hash });
        assert.equal(await f.settle(f.subtle.verify({ name: "ECDSA", hash }, publicKey, signature, bytes)), true);
        assert.equal(verifySignature(hash.toLowerCase().replace("-", ""), bytes, { key: nativePublic, dsaEncoding: "ieee-p1363" }, new Uint8Array(signature)), true);
        const next = await f.settle(f.subtle.sign({ name: "ECDSA", hash }, privateKey, bytes));
        assert.notEqual(signature, next);
        new Uint8Array(signature).fill(0);
        assert.equal(await f.settle(f.subtle.verify({ name: "ECDSA", hash }, publicKey, next, bytes)), true);
      }
    }
    assert.equal(f.provider.digests, 0);
  });

  test("ECDSA " + curve.name + " rejects noncanonical signature widths before native verification", async () => {
    const f = fixture();
    const publicKey = await f.key("ECDSA", curve.name, "public");
    const algorithm = { name: "ECDSA", hash: "SHA-256" };
    const signature = ecdsaSignature(curve.name);
    for (const invalid of [new Uint8Array(), signature.subarray(1), signature.subarray(0, signature.length - 1), new Uint8Array(signature.length + 1)]) {
      assert.equal(await f.settle(f.subtle.verify(algorithm, publicKey, invalid, ecdsaMessage())), false);
    }
    assert.equal(f.provider.verifies, 0);
    assert.equal(await f.settle(f.subtle.verify(algorithm, publicKey, signature, ecdsaMessage())), true);
    assert.equal(f.provider.verifies, 1);
  });

  test("ECDSA " + curve.name + " leaves zero and out-of-range signature integers to native verification", async () => {
    const f = fixture();
    const publicKey = await f.key("ECDSA", curve.name, "public");
    const algorithm = { name: "ECDSA", hash: "SHA-256" };
    const valid = ecdsaSignature(curve.name);
    const zeroR = valid.slice(); zeroR.fill(0, 0, curve.width);
    const zeroS = valid.slice(); zeroS.fill(0, curve.width);
    const orderR = valid.slice(); orderR.set(ecOrder(curve.name));
    const orderS = valid.slice(); orderS.set(ecOrder(curve.name), curve.width);
    for (const invalid of [zeroR, zeroS, orderR, orderS]) {
      assert.equal(await f.settle(f.subtle.verify(algorithm, publicKey, invalid, ecdsaMessage())), false);
    }
    assert.equal(f.provider.verifies, 4);
  });

  test("ECDH " + curve.name + " derives RFC 5903's full-width shared secret in both directions", async () => {
    const f = fixture();
    for (const [local, peer] of [["initiator", "responder"], ["responder", "initiator"]] as const) {
      const algorithm = { name: "ECDH", namedCurve: curve.name };
      const privateKey = await f.settle(f.subtle.importKey("jwk", ecdhPrivateJwk(curve.name, local), algorithm, false, ["deriveBits"]));
      const publicKey = await f.settle(f.subtle.importKey("jwk", ecdhPublicJwk(curve.name, peer), algorithm, false, []));
      const result = await f.settle(f.subtle.deriveBits({ name: "ECDH", public: publicKey }, privateKey, null));
      assert.equal(result.byteLength, curve.width);
      assert.deepEqual(new Uint8Array(result), ecdhSecret(curve.name));
      assert.equal(f.provider.agreementKey, getCryptoKeySlots(privateKey).handle);
      assert.deepEqual(f.provider.agreementParameters, { name: "ECDH", publicKey: getCryptoKeySlots(publicKey).handle });
    }
    assert.equal(f.provider.derives, 2);
    assert.equal(f.provider.digests, 0);
  });

  test("ECDH " + curve.name + " truncates leading bits with exact output ownership", async () => {
    const f = fixture();
    const { privateKey, publicKey } = await f.agreement(curve.name);
    const algorithm = { name: "ECDH", public: publicKey };
    const full = ecdhSecret(curve.name);
    for (const bits of [0, 1, 7, 8, 9, 13, curve.width * 8 - 1, curve.width * 8]) {
      const result = await f.settle(f.subtle.deriveBits(algorithm, privateKey, bits));
      const expected = full.slice(0, Math.ceil(bits / 8));
      if (bits % 8 !== 0) expected[expected.length - 1]! &= 0xff << (8 - bits % 8);
      assert.equal(result.byteLength, Math.ceil(bits / 8));
      assert.deepEqual(new Uint8Array(result), expected);
    }
    assert.equal(f.provider.derives, 8, "even zero requested bits validate and perform ECDH");
    await assert.rejects(f.settle(f.subtle.deriveBits(algorithm, privateKey, curve.width * 8 + 1)), dom("OperationError"));
    assert.equal(f.provider.derives, 8, "the maximum output bound precedes native execution");
    const first = await f.settle(f.subtle.deriveBits(algorithm, privateKey));
    const second = await f.settle(f.subtle.deriveBits(algorithm, privateKey));
    assert.notEqual(first, second);
    new Uint8Array(first).fill(0);
    assert.deepEqual(new Uint8Array(second), full);
  });
}

test("ECDSA left-pads minimal native r and s without aliasing either component", async () => {
  const f = fixture();
  const key = await f.key("ECDSA", "P-521", "private");
  const r = new Uint8Array([1, 2]);
  const s = new Uint8Array([3]);
  f.provider.returnedSignature = { kind: "ecdsa", r, s };
  const result = new Uint8Array(await f.settle(f.subtle.sign({ name: "ECDSA", hash: "SHA-512" }, key, new Uint8Array())));
  assert.equal(result.length, 132);
  assert.deepEqual([...result.subarray(0, 64)], Array<number>(64).fill(0));
  assert.deepEqual([...result.subarray(64, 66)], [1, 2]);
  assert.deepEqual([...result.subarray(66, 131)], Array<number>(65).fill(0));
  assert.equal(result[131], 3);
  r.fill(9); s.fill(9);
  assert.equal(result[64], 1);
  assert.equal(result[131], 3);
  assert.equal(result.byteOffset, 0);
  assert.equal(result.buffer.byteLength, result.byteLength);
});

test("ECDSA native failure values and invalid result shapes become OperationError", async () => {
  const f = fixture();
  const key = await f.key("ECDSA", "P-256", "private");
  for (const failure of ["invalid-key", "operation"] as const) {
    f.provider.failure = { failure };
    await assert.rejects(f.settle(f.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, new Uint8Array())), dom("OperationError"));
  }
  f.provider.failure = undefined;
  for (const result of [
    { kind: "bytes", bytes: new Uint8Array(64) },
    { kind: "ecdsa", r: new Uint8Array(), s: new Uint8Array([1]) },
    { kind: "ecdsa", r: new Uint8Array([1]), s: new Uint8Array() },
    { kind: "ecdsa", r: new Uint8Array(33), s: new Uint8Array([1]) },
    { kind: "ecdsa", r: new Uint8Array([1]), s: new Uint8Array(33) },
  ] as const) {
    f.provider.returnedSignature = result;
    await assert.rejects(f.settle(f.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, new Uint8Array())), dom("OperationError"));
  }
});

test("ECDSA key kind, name and private-slot usages precede native operations", async () => {
  const f = fixture();
  const signer = await f.key("ECDSA", "P-256", "private");
  const verifier = await f.key("ECDSA", "P-256", "public");
  const privateSlots = getCryptoKeySlots(signer);
  const publicSlots = getCryptoKeySlots(verifier);
  const wrongSigner = createCryptoKey("public", true, publicSlots.algorithm, ["sign"], publicSlots.handle);
  const wrongVerifier = createCryptoKey("private", true, privateSlots.algorithm, ["verify"], privateSlots.handle);
  const algorithm = { name: "ECDSA", hash: "SHA-256" };
  await assert.rejects(f.settle(f.subtle.sign(algorithm, wrongSigner, new Uint8Array())), dom("InvalidAccessError"));
  await assert.rejects(f.settle(f.subtle.verify(algorithm, wrongVerifier, new Uint8Array(), new Uint8Array())), dom("InvalidAccessError"));
  await assert.rejects(f.settle(f.subtle.sign(algorithm, verifier, new Uint8Array())), dom("InvalidAccessError"));
  await assert.rejects(f.settle(f.subtle.verify(algorithm, signer, new Uint8Array(), new Uint8Array())), dom("InvalidAccessError"));
  const ecdh = await f.key("ECDH", "P-256", "private");
  await assert.rejects(f.settle(f.subtle.sign(algorithm, ecdh, new Uint8Array())), dom("InvalidAccessError"));
  assert.equal(f.provider.signs, 0);
  assert.equal(f.provider.verifies, 0);
  (signer.algorithm as { name: string; namedCurve: string }).namedCurve = "P-521";
  signer.algorithm.name = "ECDH";
  signer.usages.push("deriveBits");
  const result = await f.settle(f.subtle.sign(algorithm, signer, ecdsaMessage()));
  assert.equal(result.byteLength, 64);
