test("wrapped JWK serialization never calls JSON.stringify or toJSON hooks", { skip: "rule 405266cf7 (call methods plainly): nts programs cannot redefine intrinsic methods, constructors, or prototypes" }, () => {
  const key = toJsonWebKey({ kty: "oct", k: "AA", alg: "HS256", key_ops: ["sign"], ext: true });
  const originalStringify = JSON.stringify;
  const objectHook = Object.getOwnPropertyDescriptor(Object.prototype, "toJSON");
  const arrayHook = Object.getOwnPropertyDescriptor(Array.prototype, "toJSON");
  let encoded: Uint8Array;
  try {
    JSON.stringify = () => { throw new Error("caller JSON.stringify"); };
    Object.defineProperty(Object.prototype, "toJSON", { configurable: true, value() { throw new Error("caller Object.toJSON"); } });
    Object.defineProperty(Array.prototype, "toJSON", { configurable: true, value() { throw new Error("caller Array.toJSON"); } });
    encoded = serializeWrappedJwk(key, false);
  } finally {
    JSON.stringify = originalStringify;
    if (objectHook === undefined) delete (Object.prototype as { toJSON?: unknown }).toJSON;
    else Object.defineProperty(Object.prototype, "toJSON", objectHook);
    if (arrayHook === undefined) delete (Array.prototype as { toJSON?: unknown }).toJSON;
    else Object.defineProperty(Array.prototype, "toJSON", arrayHook);
  }
  assert.equal(parseWrappedJwk(encoded).k, "AA");
});

test("late String, Array and Math replacements do not enter JWK serialization or base64", { skip: "rule 405266cf7 (call methods plainly): nts programs cannot redefine intrinsic methods, constructors, or prototypes" }, () => {
  const key = toJsonWebKey({ kty: "oct", k: "AA", alg: "HS256", key_ops: ["sign"], ext: true });
  const originalCode = String.prototype.charCodeAt;
  const originalSlice = String.prototype.slice;
  const originalPush = Array.prototype.push;
  const originalFloor = Math.floor;
  let encoded: string;
  let decoded: Uint8Array;
  let wrapped: Uint8Array;
  try {
    String.prototype.charCodeAt = () => { throw new Error("late charCodeAt"); };
    String.prototype.slice = () => { throw new Error("late String.slice"); };
    Array.prototype.push = () => { throw new Error("late Array.push"); };
    Math.floor = () => { throw new Error("late Math.floor"); };
    encoded = encodeBase64Url(new Uint8Array([251, 255]));
    decoded = decodeBase64Url("-_8");
    wrapped = serializeWrappedJwk(key, true);
  } finally {
    String.prototype.charCodeAt = originalCode;
    String.prototype.slice = originalSlice;
    Array.prototype.push = originalPush;
    Math.floor = originalFloor;
  }
  assert.equal(encoded, "-_8");
  assert.deepEqual([...decoded], [251, 255]);
  assert.equal(wrapped.byteLength % 8, 0);
  assert.equal(parseWrappedJwk(wrapped).k, "AA");
});

// Web Cryptography §§14.3.7, 14.3.12, 33–34. Agreement-to-KDF expectations
// begin with the independent RFC 5903 / RFC 7748 secrets, not a peer round trip.
import assert from "node:assert/strict";
import { createHmac, hkdfSync, pbkdf2Sync } from "node:crypto";
import test from "node:test";
import { DOMException } from "../src/core/errors.ts";
import { createCrypto } from "../src/crypto/crypto.ts";
import type { KeyUsage } from "../src/crypto/crypto-key.ts";
import type { CryptoDerivationParameters, CryptoDigestName, CryptoFailure, CryptoKeyHandle,
  CryptoKeyImport, CryptoKeyRecord } from "../src/provider/crypto.ts";
import { VirtualScheduler } from "../src/provider/virtual-time.ts";
import { ecdhPrivateJwk, ecdhPublicJwk, ecdhSecret } from "./ec-fixtures.ts";
import { NodeCryptoProvider } from "./node-crypto-provider.ts";
import { x25519PrivateJwk, x25519PublicJwk, x25519Secret } from "./okp-fixtures.ts";

type KdfName = "HKDF" | "PBKDF2";
const password = new Uint8Array([0, 0x80, 0xff, 1, 2, 3]);
const salt = new Uint8Array([13, 21, 34]);
const info = new Uint8Array([55, 89]);

class RecordingProvider extends NodeCryptoProvider {
  derives = 0;
  imports = 0;
  imported: CryptoKeyImport | undefined;
  derivedFailure: CryptoFailure | undefined;
  importFailure: CryptoFailure | undefined;
  override derive(parameters: CryptoDerivationParameters, key: CryptoKeyHandle): Uint8Array | CryptoFailure {
    this.derives++;
    return this.derivedFailure ?? super.derive(parameters, key);
  }
  override importKey(input: CryptoKeyImport): CryptoKeyRecord | CryptoFailure {
    this.imports++;
    this.imported = input;
    return this.importFailure ?? super.importKey(input);
  }
}

class CountingScheduler extends VirtualScheduler {
  enqueues = 0;
  override enqueue(task: () => void): void { this.enqueues++; super.enqueue(task); }
}

function fixture() {
  const provider = new RecordingProvider();
  const scheduler = new CountingScheduler();
  const subtle = createCrypto({ fill(bytes: Uint8Array): void { bytes.fill(7); } }, provider, scheduler).subtle;
  function settle<T>(promise: Promise<T>): Promise<T> { scheduler.runPending(); return promise; }
  async function key(name: KdfName, usages: readonly KeyUsage[] = ["deriveKey", "deriveBits"]) {
    const result = await settle(subtle.importKey("raw", password, name, false, usages));
    provider.derives = 0;
    provider.imports = 0;
    scheduler.enqueues = 0;
    return result;
  }
  return { provider, scheduler, subtle, settle, key };
}

function parameters(name: KdfName, hash: CryptoDigestName = "SHA-256") {
  return { name, hash, salt, info, iterations: 2 };
}

function expected(name: KdfName, hash: CryptoDigestName, key: Uint8Array, length: number): Uint8Array {
  const nativeHash = hash.replace("-", "").toLowerCase();
  return name === "HKDF" ? new Uint8Array(hkdfSync(nativeHash, key, salt, info, length))
    : new Uint8Array(pbkdf2Sync(key, salt, 2, length, nativeHash));
}

function dom(name: string): (error: unknown) => boolean {
  return error => error instanceof DOMException && error.name === name;
}

for (const name of ["HKDF", "PBKDF2"] as const) {
  for (const target of ["AES-CTR", "AES-CBC", "AES-GCM", "AES-KW"] as const) {
    test(`${name} derives ${target} at every AES key length`, async () => {
      const f = fixture();
      const base = await f.key(name, ["deriveKey"]);
      for (const length of [128, 192, 256]) {
        const usages = target === "AES-KW" ? ["wrapKey", "unwrapKey"] : ["encrypt", "decrypt"];
        const derives = f.provider.derives;
        const imports = f.provider.imports;
        const enqueues = f.scheduler.enqueues;
        const pending = f.subtle.deriveKey(parameters(name), base, { name: target, length }, true, usages);
        assert.equal(f.provider.derives, derives + 1);
        assert.equal(f.provider.imports, imports + 1);
        assert.equal(f.scheduler.enqueues, enqueues + 1);
        const key = await f.settle(pending);
        assert.deepEqual(key.algorithm, { name: target, length });
        assert.deepEqual(await f.settle(f.subtle.exportKey("raw", key)), expected(name, "SHA-256", password, length / 8).buffer);
      }
    });
  }

  for (const hash of ["SHA-1", "SHA-256", "SHA-384", "SHA-512"] as const) {
    test(`${name} derives usable HMAC ${hash} keys with explicit and default lengths`, async () => {
      const f = fixture();
      const base = await f.key(name);
      for (const length of [128, undefined]) {
        const bits = length ?? (hash === "SHA-384" || hash === "SHA-512" ? 1024 : 512);
        const key = await f.settle(f.subtle.deriveKey(parameters(name, hash), base,
          { name: "HMAC", hash, length }, true, ["verify", "sign", "sign"]));
        const bytes = expected(name, hash, password, bits / 8);
        assert.deepEqual(key.algorithm, { name: "HMAC", hash: { name: hash }, length: bits });
        assert.deepEqual(key.usages, ["sign", "verify"]);
        assert.deepEqual(await f.settle(f.subtle.exportKey("raw", key)), bytes.buffer);
        assert.deepEqual(new Uint8Array(await f.settle(f.subtle.sign("HMAC", key, info))),
          new Uint8Array(createHmac(hash.replace("-", "").toLowerCase(), bytes).update(info).digest()));
      }
    });
  }

  test(`${name} deriveKey preserves target length, permission and import error order`, async () => {
    const f = fixture();
    const base = await f.key(name, ["deriveKey"]);
    const algorithm = parameters(name);
    await assert.rejects(f.settle(f.subtle.deriveBits(algorithm, base, 128)), dom("InvalidAccessError"));
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base,
      { name: "HMAC", hash: "SHA-256", length: 0 }, true, ["sign"])), TypeError);
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base,
      { name: "AES-GCM", length: 129 }, true, ["encrypt"])), dom("OperationError"));
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base,
      { name: "HMAC", hash: "SHA-256", length: 9 }, true, ["sign"])), dom("OperationError"));
    assert.equal(f.provider.derives, 0);
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base,
      { name: "AES-GCM", length: 128 }, true, ["sign"])), dom("SyntaxError"));
    assert.equal(f.provider.derives, 1);
    assert.equal(f.provider.imports, 0);
    await assert.rejects(f.settle(f.subtle.deriveKey(algorithm, base,
      { name: "AES-GCM", length: 128 }, true, [])), dom("SyntaxError"));
    assert.equal(f.provider.derives, 2);
    assert.equal(f.provider.imports, 1);
    const key = await f.settle(f.subtle.deriveKey(algorithm, base,
      { name: "AES-GCM", length: 128 }, false, ["encrypt"]));
    assert.equal(key.extractable, false);
    await assert.rejects(f.settle(f.subtle.exportKey("raw", key)), dom("InvalidAccessError"));
  });

  test(`${name} cannot derive a KDF target whose requested length is null`, async () => {
    const f = fixture();
    const base = await f.key(name);
    for (const target of ["HKDF", "PBKDF2"]) {
      await assert.rejects(f.settle(f.subtle.deriveKey(parameters(name), base, target, false, ["deriveBits"])), dom("OperationError"));
    }
    assert.equal(f.provider.derives, 0);
    assert.equal(f.provider.imports, 0);
  });

  test(`${name} deriveKey snapshots parameters before normalizing its target twice`, async () => {
    const f = fixture();
    const base = await f.key(name);
    const mutableSalt = salt.slice();
    const mutableInfo = info.slice();
    const reads: string[] = [];
    const target = {
      get name() { reads.push("name"); mutableSalt.fill(0); mutableInfo.fill(0); return "HMAC"; },
      get hash() { reads.push("hash"); return "SHA-256"; },
      get length() { reads.push("length"); return 128; },
    };
    const key = await f.settle(f.subtle.deriveKey({ ...parameters(name), salt: mutableSalt, info: mutableInfo },
      base, target, true, ["sign"]));
    assert.deepEqual(reads, ["name", "name", "hash", "length", "name", "name", "hash", "length"]);
    assert.deepEqual(await f.settle(f.subtle.exportKey("raw", key)), expected(name, "SHA-256", password, 16).buffer);
  });

  test(`${name} uses the target length normalization independently of import length`, async () => {
    const f = fixture();
    const base = await f.key(name);
    let reads = 0;
    const target = { name: "HMAC", hash: "SHA-256", get length() { return ++reads === 1 ? 9 : 16; } };
    const key = await f.settle(f.subtle.deriveKey(parameters(name), base, target, true, ["sign"]));
    assert.equal(reads, 2);
    assert.deepEqual(key.algorithm, { name: "HMAC", hash: { name: "SHA-256" }, length: 9 });
    const bytes = expected(name, "SHA-256", password, 2);
    bytes[1]! &= 0x80;
    assert.deepEqual(await f.settle(f.subtle.exportKey("raw", key)), bytes.buffer);
  });

  for (const failure of ["invalid-key", "operation"] as const) {
    test(`${name} deriveKey maps ${failure} failures at the correct stage`, async () => {
      const f = fixture();
      const base = await f.key(name);
      f.provider.derivedFailure = { failure };
      await assert.rejects(f.settle(f.subtle.deriveKey(parameters(name), base,
        { name: "AES-GCM", length: 128 }, true, ["encrypt"])), dom("OperationError"));
      assert.equal(f.provider.imports, 0);
      assert.equal(f.scheduler.enqueues, 1);
      f.provider.derivedFailure = undefined;
      f.provider.importFailure = { failure };
      await assert.rejects(f.settle(f.subtle.deriveKey(parameters(name), base,
        { name: "AES-GCM", length: 128 }, true, ["encrypt"])), dom(failure === "invalid-key" ? "DataError" : "OperationError"));
      assert.equal(f.provider.imports, 1);
      assert.equal(f.scheduler.enqueues, 2);
    });
  }

  for (const curve of ["X25519", "P-256", "P-384", "P-521"] as const) {
    test(`${curve} derives a usable ${name} key from the complete published agreement secret`, async () => {
      const f = fixture();
      const x = curve === "X25519";
      const algorithm = x ? { name: "X25519" } : { name: "ECDH", namedCurve: curve };
      const privateKey = await f.settle(f.subtle.importKey("jwk", x ? x25519PrivateJwk("alice") : ecdhPrivateJwk(curve, "initiator"),
        algorithm, false, ["deriveKey"]));
      const publicKey = await f.settle(f.subtle.importKey("jwk", x ? x25519PublicJwk("bob") : ecdhPublicJwk(curve, "responder"),
        algorithm, false, []));
      const secret = x ? x25519Secret() : ecdhSecret(curve);
      const key = await f.settle(f.subtle.deriveKey({ name: algorithm.name, public: publicKey }, privateKey, name, false, ["deriveBits"]));
      assert.deepEqual(key.algorithm, { name });
      assert.equal(key.extractable, false);
      const imported = f.provider.imported;
      assert.ok(imported?.format === "raw" && imported.family === "secret");
      assert.deepEqual(imported.bytes, secret);
      assert.deepEqual(new Uint8Array(await f.settle(f.subtle.deriveBits(parameters(name), key, 256))),
        expected(name, "SHA-256", secret, 32));
      await assert.rejects(f.settle(f.subtle.deriveKey({ name: algorithm.name, public: publicKey }, privateKey,
        name, true, ["deriveBits"])), dom("SyntaxError"));
    });
  }

  test(`AES-GCM unwraps ${name} raw bytes and applies import policy after authentication`, async () => {
    const f = fixture();
    const aes = await f.settle(f.subtle.importKey("raw", new Uint8Array(16), "AES-GCM", false, ["encrypt", "unwrapKey"]));
    const cipher = { name: "AES-GCM", iv: new Uint8Array(12) };
    const wrapped = await f.settle(f.subtle.encrypt(cipher, aes, password));
    const key = await f.settle(f.subtle.unwrapKey("raw", wrapped, aes, cipher, name, false, ["deriveBits"]));
    assert.deepEqual(new Uint8Array(await f.settle(f.subtle.deriveBits(parameters(name), key, 128))),
      expected(name, "SHA-256", password, 16));
    await assert.rejects(f.settle(f.subtle.unwrapKey("raw", wrapped, aes, cipher, name, true, ["deriveBits"])), dom("SyntaxError"));
    await assert.rejects(f.settle(f.subtle.unwrapKey("spki", wrapped, aes, cipher, name, false, ["deriveBits"])), dom("NotSupportedError"));
    const corrupted = new Uint8Array(wrapped.slice(0));
    corrupted[0]! ^= 1;
    await assert.rejects(f.settle(f.subtle.unwrapKey("raw", corrupted, aes, cipher, name, true, ["deriveBits"])), dom("OperationError"));
  });
}

// Specification controls: Web Cryptography §§9, 13–17, 33.4.2–3, 34.4.2–3.
// https://w3c.github.io/webcrypto/#hkdf-operations-import-key
// https://w3c.github.io/webcrypto/#pbkdf2-operations-import-key
// Native primitives only; no Node WebCrypto or descriptor/prototype spoofing.
import assert from "node:assert/strict";
import test from "node:test";
import { DOMException } from "../src/core/errors.ts";
import type { KdfAlgorithmName } from "../src/crypto/algorithms.ts";
import { createCrypto } from "../src/crypto/crypto.ts";
import { getCryptoKeySlots } from "../src/crypto/crypto-key.ts";
import type { KeyUsage } from "../src/crypto/crypto-key.ts";
import { getKdfKeyLength } from "../src/crypto/kdf.ts";
import type { CryptoFailure, CryptoKeyImport, CryptoKeyRecord } from "../src/provider/crypto.ts";
import { VirtualScheduler } from "../src/provider/virtual-time.ts";
import { NodeCryptoProvider } from "./node-crypto-provider.ts";

class RecordingProvider extends NodeCryptoProvider {
  imports = 0;
  importInput: CryptoKeyImport | undefined;
  importFailure: CryptoFailure | undefined;
  importRecord: CryptoKeyRecord | undefined;

  override importKey(input: CryptoKeyImport): CryptoKeyRecord | CryptoFailure {
    this.imports++;
    this.importInput = input;
    return this.importFailure ?? this.importRecord ?? super.importKey(input);
  }
}

function fixture() {
  const provider = new RecordingProvider();
  const scheduler = new VirtualScheduler();
  let fills = 0;
  const subtle = createCrypto({ fill(bytes: Uint8Array): void { fills++; bytes.fill(0x37); } }, provider, scheduler).subtle;
  function settle<T>(promise: Promise<T>): Promise<T> { scheduler.runPending(); return promise; }
  return { provider, scheduler, subtle, settle, fills: () => fills };
}

function dom(name: string): (error: unknown) => boolean {
  return error => error instanceof DOMException && error.name === name;
}

const names: readonly KdfAlgorithmName[] = ["HKDF", "PBKDF2"];

for (const name of names) {
  test(name + " imports nonextractable raw secrets with name-only algorithm and normalized usages", async () => {
    const f = fixture();
    const data = new Uint8Array([0, 1, 255, 0]);
    const key = await f.settle(f.subtle.importKey("raw", data, name.toLowerCase(), false, ["deriveBits", "deriveKey", "deriveBits"]));
    assert.equal(key.type, "secret");
    assert.equal(key.extractable, false);
    assert.deepEqual(key.algorithm, { name });
    assert.deepEqual(Object.keys(key.algorithm), ["name"]);
    assert.deepEqual(key.usages, ["deriveKey", "deriveBits"]);
    assert.equal(f.provider.imports, 1);
    assert.equal(f.fills(), 0);
    const input = f.provider.importInput;
    assert.ok(input?.format === "raw" && input.family === "secret");
    assert.equal(input.bytes, data);
    assert.deepEqual(f.provider.exportKey(getCryptoKeySlots(key).handle, "raw"), data);
  });

  test(name + " import ignores operation parameters and does not attach a hash to the key", async () => {
    const f = fixture();
    const algorithm = {
      name,
      get hash(): never { throw new Error("import must not inspect hash"); },
      get salt(): never { throw new Error("import must not inspect salt"); },
      get info(): never { throw new Error("import must not inspect info"); },
      get iterations(): never { throw new Error("import must not inspect iterations"); },
      get length(): never { throw new Error("import must not inspect length"); },
    };
    const key = await f.settle(f.subtle.importKey("raw", new Uint8Array([1]), algorithm, false, ["deriveKey"]));
    assert.deepEqual(key.algorithm, { name });
    assert.deepEqual(key.usages, ["deriveKey"]);
  });

  test(name + " accepts empty and detached raw key material", async () => {
    const f = fixture();
    const detached = new ArrayBuffer(3);
    structuredClone(detached, { transfer: [detached] });
    for (const data of [new Uint8Array(), new ArrayBuffer(0), detached]) {
      const key = await f.settle(f.subtle.importKey("raw", data, name, false, ["deriveBits"]));
      assert.equal(key.type, "secret");
      assert.equal(key.extractable, false);
      assert.deepEqual(key.algorithm, { name });
      assert.deepEqual(f.provider.exportKey(getCryptoKeySlots(key).handle, "raw"), new Uint8Array());
    }
    assert.equal(f.provider.imports, 3);
  });

  test(name + " rejects non-raw formats before usage and extractability policy", async () => {
    const f = fixture();
    for (const format of ["spki", "pkcs8", "jwk"] as const) {
      const data = format === "jwk" ? {} : new Uint8Array();
      for (const usages of [["encrypt"], [], ["deriveBits"]]) {
        await assert.rejects(f.settle(f.subtle.importKey(format, data, name, true, usages)), dom("NotSupportedError"));
      }
    }
    assert.equal(f.provider.imports, 0);
  });

  test(name + " rejects invalid usages and extractability before importing", async () => {
    const f = fixture();
    for (const usage of ["encrypt", "decrypt", "sign", "verify", "wrapKey", "unwrapKey"]) {
      await assert.rejects(f.settle(f.subtle.importKey("raw", new Uint8Array(), name, false, [usage])), dom("SyntaxError"));
      await assert.rejects(f.settle(f.subtle.importKey("raw", new Uint8Array(), name, true, [usage])), dom("SyntaxError"));
    }
    for (const extractable of [true, 1, "true", {}]) {
      await assert.rejects(f.settle(f.subtle.importKey("raw", new Uint8Array(), name, extractable, ["deriveBits"])), dom("SyntaxError"));
    }
    assert.equal(f.provider.imports, 0);
    const key = await f.settle(f.subtle.importKey("raw", new Uint8Array(), name, false, ["deriveBits"]));
    assert.deepEqual(key.usages, ["deriveBits"]);
    assert.equal(f.provider.imports, 1);
  });

  test(name + " checks empty secret usages after native import and preserves failure precedence", async () => {
    const f = fixture();
    for (const data of [new Uint8Array(), new Uint8Array([1])]) {
      await assert.rejects(f.settle(f.subtle.importKey("raw", data, name, false, [])), dom("SyntaxError"));
    }
    assert.equal(f.provider.imports, 2);
    for (const failure of ["invalid-key", "operation"] as const) {
      f.provider.importFailure = { failure };
      await assert.rejects(f.settle(f.subtle.importKey("raw", new Uint8Array(), name, false, [])), dom(failure === "invalid-key" ? "DataError" : "OperationError"));
    }
    assert.equal(f.provider.imports, 4);
  });

  test(name + " maps both native import failure values at the import step", async () => {
    const f = fixture();
    for (const failure of ["invalid-key", "operation"] as const) {
      f.provider.importFailure = { failure };
      await assert.rejects(f.settle(f.subtle.importKey("raw", new Uint8Array([1]), name, false, ["deriveBits"])), dom(failure === "invalid-key" ? "DataError" : "OperationError"));
    }
    assert.equal(f.provider.imports, 2);
  });

  test(name + " checks actual native secret metadata including zero-bit material", async () => {
    const f = fixture();
    const real = new NodeCryptoProvider().importKey({ format: "raw", family: "secret", bytes: new Uint8Array([1]) });
    assert.ok(!("failure" in real));
    for (const info of [
      { family: "secret", type: "secret", length: 0 },
      { family: "secret", type: "secret", length: 7 },
      { family: "secret", type: "secret", length: 16 },
      { family: "secret", type: "secret", length: NaN },
      { family: "OKP", type: "public", namedCurve: "Ed25519" },
      { family: "RSA", type: "private", modulusLength: 2048, publicExponent: new Uint8Array([1, 0, 1]) },
    ] as const) {
      f.provider.importRecord = { handle: real.handle, info };
      await assert.rejects(f.settle(f.subtle.importKey("raw", new Uint8Array([1]), name, false, ["deriveBits"])), dom("OperationError"));
      await assert.rejects(f.settle(f.subtle.importKey("raw", new Uint8Array([1]), name, false, [])), dom("OperationError"));
    }
    f.provider.importRecord = real;
    await assert.rejects(f.settle(f.subtle.importKey("raw", new Uint8Array(), name, false, ["deriveBits"])), dom("OperationError"));
    f.provider.importRecord = undefined;
    const empty = await f.settle(f.subtle.importKey("raw", new Uint8Array(), name, false, ["deriveBits"]));
    assert.deepEqual(f.provider.exportKey(getCryptoKeySlots(empty).handle, "raw"), new Uint8Array());
  });

  test(name + " borrows input view bounds synchronously and owns imported material", async () => {
    const f = fixture();
    const storage = new Uint8Array([99, 1, 2, 3, 88]);
    const pending = f.subtle.importKey("raw", new DataView(storage.buffer, 1, 3), name, false, ["deriveBits"]);
    assert.equal(f.provider.imports, 1);
    const input = f.provider.importInput;
    assert.ok(input?.format === "raw");
    assert.equal(input.bytes.buffer, storage.buffer);
    assert.equal(input.bytes.byteOffset, 1);
    assert.equal(input.bytes.byteLength, 3);
    storage.fill(0);
    const key = await f.settle(pending);
    assert.deepEqual(f.provider.exportKey(getCryptoKeySlots(key).handle, "raw"), new Uint8Array([1, 2, 3]));
  });

  test(name + " isolates source usages and mutable cached dictionaries from private slots", async () => {
    const f = fixture();
    const usages: KeyUsage[] = ["deriveBits", "deriveKey"];
    const algorithm = { name };
    const pending = f.subtle.importKey("raw", new Uint8Array([1]), algorithm, false, usages);
    usages.length = 0;
    algorithm.name = name === "HKDF" ? "PBKDF2" : "HKDF";
    const key = await f.settle(pending);
    const sibling = await f.settle(f.subtle.importKey("raw", new Uint8Array([1]), name, false, ["deriveBits"]));
    assert.deepEqual(key.algorithm, { name });
    assert.deepEqual(key.usages, ["deriveKey", "deriveBits"]);
    assert.equal(key.algorithm, key.algorithm);
    assert.equal(key.usages, key.usages);
    assert.notEqual(key.algorithm, sibling.algorithm);
    const publicAlgorithm = key.algorithm as { name: string };
    publicAlgorithm.name = "HMAC";
    key.usages.length = 0;
    const slots = getCryptoKeySlots(key);
    assert.equal(slots.algorithm.name, name);
    assert.deepEqual(slots.usages, ["deriveKey", "deriveBits"]);
    assert.deepEqual(sibling.algorithm, { name });
    assert.deepEqual(sibling.usages, ["deriveBits"]);
  });

  test(name + " import performs native work before return and schedules success and errors", async () => {
    const f = fixture();
    const pending = f.subtle.importKey("raw", new Uint8Array(), name, false, ["deriveBits"]);
    assert.equal(f.provider.imports, 1);
    let settled = false;
    void pending.then(() => { settled = true; });
    await Promise.resolve();
    assert.equal(settled, false);
    const key = await f.settle(pending);
    assert.equal(key.type, "secret");
    assert.equal(settled, true);
    f.provider.importFailure = { failure: "operation" };
    const failed = f.subtle.importKey("raw", new Uint8Array(), name, false, ["deriveBits"]);
    assert.equal(f.provider.imports, 2);
    let rejected = false;
    void failed.catch(() => { rejected = true; });
    const rejection = assert.rejects(failed, dom("OperationError"));
    await Promise.resolve();
    assert.equal(rejected, false);
    f.scheduler.runPending();
    await rejection;
    assert.equal(rejected, true);
    const invalid = f.subtle.importKey("raw", new Uint8Array(), name, true, ["deriveBits"]);
    assert.equal(f.provider.imports, 2);
    assert.equal(f.scheduler.hasPending, true);
    await assert.rejects(f.settle(invalid), dom("SyntaxError"));
  });
}

