    assert.ok(first.every((byte) => byte === 0xa5));
    first.fill(1);
    const second = new Uint8Array(await complete(f, f.subtle.exportKey("raw-secret", key)) as ArrayBuffer);
    assert.ok(second.every((byte) => byte === 0xa5));
