    for (const length of badIv) {
      for (const method of ["encrypt", "decrypt"] as const) {
        await assert.rejects(complete(f, f.subtle[method]({ name, iv: new Uint8Array(length) }, key, new Uint8Array(32))), errorNamed("OperationError"));
      }
