  const invalid: readonly [number, readonly number[]][] = [
    [0, [3]], [3, [3]], [4, []], [4, [0]], [4, [1]], [4, [2]], [4, [4]],
    [4, [15]], [4, [17]], [8, [255]], [8, [1, 0, 1]], [9, [1, 255]], [9, [2, 1]],
