test("RSA imports SPKI and PKCS8 with omitted parameters, then exports canonical NULL parameters", async () => {
  const algorithm = new Uint8Array([0x30, 0x0d, 0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 1, 1, 1, 5, 0]);
  for (const format of ["spki", "pkcs8"] as const) {
    const f = fixture();
    const original = format === "spki" ? rsaSpki() : rsaPkcs8();
    const start = Buffer.from(original).indexOf(Buffer.from(algorithm));
    assert.ok(start >= 0);
    const omitted = new Uint8Array(original.length - 2);
    omitted.set(original.subarray(0, start + 13));
    omitted.set(original.subarray(start + 15), start + 13);
    omitted[start + 1] = 11;
    assert.equal(omitted[1], 0x82);
    const outerLength = (omitted[2]! * 256 + omitted[3]!) - 2;
    omitted[2] = outerLength >>> 8;
    omitted[3] = outerLength & 255;
    const key = await f.settle(f.subtle.importKey(format, omitted, alg("RSA-PSS"), true, [format === "spki" ? "verify" : "sign"]));
    assert.deepEqual(buffer(await f.settle(f.subtle.exportKey(format, key))), original);
    assert.equal(f.provider.imports, 1);
    const nonNull = original.slice(); nonNull[start + 13] = 4;
    await assert.rejects(f.settle(f.subtle.importKey(format, nonNull, alg("RSA-PSS"), true, [format === "spki" ? "verify" : "sign"])), dom("DataError"));
    assert.equal(f.provider.imports, 1, "non-NULL parameters rejected by shared policy");
  }
});

// Controls for the ordinary-Node RSA primitive fixture, independent of the
// shared Web Crypto algorithms. Known answers: RFC 7520 §§4.1, 4.2 and 5.2.
// https://www.rfc-editor.org/rfc/rfc7520.html
import assert from "node:assert/strict";
import { Buffer } from "node:buffer";
import { constants, createPrivateKey, privateDecrypt, verify } from "node:crypto";
import test from "node:test";
import type {
  CryptoDigestName,
  CryptoFailure,
  CryptoKeyHandle,
  CryptoKeyRecord,
  CryptoRsaComponents,
} from "../src/provider/crypto.ts";
import { NodeCryptoProvider } from "./node-crypto-provider.ts";
import {
  rsaOaepCiphertext,
  rsaOaepMessage,
  rsaOaepPrivateJwk,
  rsaPkcs1Message,
  rsaPkcs1Signature,
  rsaPkcs8,
  rsaPrivateJwk,
  rsaPssMessage,
  rsaPssSignature,
  rsaSpki,
} from "./rsa-fixtures.ts";
import type { RsaFixturePrivateJwk } from "./rsa-fixtures.ts";

function success<T extends object>(result: T | CryptoFailure): T {
  if ("failure" in result) assert.fail("Unexpected native failure: " + result.failure);
  return result;
}

function decoded(value: string): Uint8Array {
  return new Uint8Array(Buffer.from(value, "base64url"));
}

function privateComponents(jwk: RsaFixturePrivateJwk = rsaPrivateJwk()): CryptoRsaComponents {
  return {
    family: "RSA", n: decoded(jwk.n), e: decoded(jwk.e), d: decoded(jwk.d),
    p: decoded(jwk.p), q: decoded(jwk.q), dp: decoded(jwk.dp), dq: decoded(jwk.dq), qi: decoded(jwk.qi),
  };
}

function publicKey(provider: NodeCryptoProvider): CryptoKeyRecord {
  return success(provider.importKey({ format: "spki", bytes: rsaSpki() }));
}

function privateKey(provider: NodeCryptoProvider): CryptoKeyRecord {
  return success(provider.importKey({ format: "pkcs8", bytes: rsaPkcs8() }));
}

function assertOwned(bytes: Uint8Array): void {
  assert.ok(bytes.buffer instanceof ArrayBuffer);
  assert.equal(bytes.byteOffset, 0);
  assert.equal(bytes.byteLength, bytes.buffer.byteLength);
}

