function bytes(hex: string): Uint8Array { return new Uint8Array(Buffer.from(hex, "hex")); }
function base64url(hex: string): string { return Buffer.from(hex, "hex").toString("base64url"); }

function ed448Fixture(index: number): Ed448Fixture {
  const fixture = ed448[index];
  if (fixture === undefined) throw new RangeError("Unknown Ed448 fixture");
  return fixture;
}

export function ed448PublicJwk(index = 0): Curve448FixturePublicJwk {
  return { kty: "OKP", crv: "Ed448", x: base64url(ed448Fixture(index).x) };
}

export function ed448PrivateJwk(index = 0): Curve448FixturePrivateJwk {
  return { ...ed448PublicJwk(index), d: base64url(ed448Fixture(index).d) };
}

export function ed448Message(index = 0): Uint8Array { return bytes(ed448Fixture(index).message); }
export function ed448Signature(index = 0): Uint8Array { return bytes(ed448Fixture(index).signature); }
export function ed448Context(index = 0): Uint8Array { return bytes(ed448Fixture(index).context); }

export function x448PublicJwk(side: "alice" | "bob" = "alice"): Curve448FixturePublicJwk {
  return { kty: "OKP", crv: "X448", x: base64url(peers[side].x) };
}

export function x448PrivateJwk(side: "alice" | "bob" = "alice"): Curve448FixturePrivateJwk {
  return { ...x448PublicJwk(side), d: base64url(peers[side].d) };
}

export function x448Secret(): Uint8Array {
  return bytes("07fff4181ac6cc95ec1c16a94a0f74d12da232ce40a77552281d282b" +
    "b60c0b56fd2464c335543936521c24403085d59a449a5037514a879d");
}

export function x448ScalarVector(index: 0 | 1): { scalar: Uint8Array; publicKey: Uint8Array; secret: Uint8Array } {
  const vector = scalarVectors[index];
  return { scalar: bytes(vector.scalar), publicKey: bytes(vector.publicKey), secret: bytes(vector.secret) };
}

export function curve448PublicJwk(name: Curve448FixtureName): Curve448FixturePublicJwk {
  return name === "Ed448" ? ed448PublicJwk() : x448PublicJwk();
}

export function curve448PrivateJwk(name: Curve448FixtureName): Curve448FixturePrivateJwk {
  return name === "Ed448" ? ed448PrivateJwk() : x448PrivateJwk();
}

export function curve448RawPublic(name: Curve448FixtureName): Uint8Array {
  return new Uint8Array(Buffer.from(curve448PublicJwk(name).x, "base64url"));
}

export function curve448Spki(name: Curve448FixtureName): Uint8Array {
  const prefix = name === "Ed448" ? "3043300506032b6571033a00" : "3042300506032b656f033900";
  const x = Buffer.from(curve448PublicJwk(name).x, "base64url").toString("hex");
  return bytes(prefix + x);
}

export function curve448Pkcs8(name: Curve448FixtureName): Uint8Array {
  const prefix = name === "Ed448" ? "3047020100300506032b6571043b0439" : "3046020100300506032b656f043a0438";
  const d = Buffer.from(curve448PrivateJwk(name).d, "base64url").toString("hex");
  return bytes(prefix + d);
}

import test from "node:test";
import assert from "node:assert/strict";
import {
  AbortController,
  DeduplicationBufferError,
  DeduplicationInterceptor,
  ReadableStream,
  TextDecoder,
  TextEncoder,
} from "../src/index.ts";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import { must } from "./harness.ts";
import type {
  FetchTransport,
  TransportRequest,
  TransportResponse,
} from "../src/fetch/transport.ts";

function request(path = "/resource", overrides: Partial<TransportRequest> = {}): TransportRequest {
  const primitives = createHostNodePrimitives();
  return {
    url: primitives.urls.parse("https://deduplicate.test" + path),
    method: "GET",
    headers: [],
    body: null,
    bodyLength: null,
    signal: new AbortController().signal,
    ...overrides,
  };
}

function body(
  chunks: readonly string[],
  onCancel: (reason?: unknown) => void = () => {},
): ReadableStream<Uint8Array> {
  const encoder = new TextEncoder();
  let index = 0;
  return new ReadableStream(
    {
      pull(controller) {
        const value = chunks[index++];
        if (value === undefined) controller.close();
        else controller.enqueue(encoder.encode(value));
      },
      cancel: onCancel,
    },
    { highWaterMark: 0 },
  );
}

async function consume(stream: ReadableStream<Uint8Array> | null): Promise<string> {
  if (stream === null) return "";
  const reader = stream.getReader();
  const bytes: number[] = [];
  try {
    while (true) {
      const item = await reader.read();
      if (item.done) break;
      bytes.push(...item.value);
    }
  } finally {
    reader.releaseLock();
  }
  return new TextDecoder().decode(Uint8Array.from(bytes));
}

test("concurrent identical requests share one dispatch and independent bodies", async () => {
  const interceptor = new DeduplicationInterceptor();
  const deferred = Promise.withResolvers<TransportResponse>();
  let dispatches = 0;
  const transport: FetchTransport = {
    dispatch(): Promise<TransportResponse> {
      dispatches++;
      return deferred.promise;
    },
  };
  const first = interceptor.dispatch(request(), transport);
  const second = interceptor.dispatch(request(), transport);
  const third = interceptor.dispatch(request(), transport);
  deferred.resolve({
    status: 200,
    statusText: "OK",
    headers: [["x-source", "one"]],
    body: body(["shared", "-body"]),
    trailers: Promise.resolve([["x-end", "yes"]]),
  });
  const responses = await Promise.all([first, second, third]);
  assert.equal(dispatches, 1);
  assert.deepEqual(await Promise.all(responses.map((response) => consume(response.body))), [
    "shared-body",
    "shared-body",
    "shared-body",
  ]);
  const trailers = await Promise.all(responses.map((response) => response.trailers));
  assert.deepEqual(trailers, [[["x-end", "yes"]], [["x-end", "yes"]], [["x-end", "yes"]]]);
  assert.notEqual(trailers[0], trailers[1]);
});

