test("DnsConnector alternates families, preserves logical identity and closes a late loser", async () => {
  const scheduler = new ManualScheduler();
  // One recorded connect: what it was asked for, and the resolver that decides its outcome.
  const attempts: {
    target: ConnectAddress;
    signal: AbortSignal;
    result: PromiseWithResolvers<ByteConnection>;
  }[] = [];
  const cache = new DnsCache({
    resolver: {
      resolve: () => Promise.resolve([v6("2001:db8::1"), v6("2001:db8::2"), v4("192.0.2.1")]),
    },
    nowMilliseconds: () => 0,
  });
  const connector = new DnsConnector({
    cache,
    scheduler,
    preferredFamily: 6,
    attemptDelayMilliseconds: 25,
    connector: {
      connect(target: ConnectAddress, signal: AbortSignal): Promise<ByteConnection> {
        const result = Promise.withResolvers<ByteConnection>();
        attempts.push({ target, signal, result });
        return result.promise;
      },
    },
  });
  const connecting = connector.connect(address(), new AbortController().signal);
  await flushMicrotasks();
  assert.equal(attempts.length, 1);
  assert.deepEqual(must(attempts[0], "the connector made that many attempts").target, {
    hostname: "service.test",
    port: 443,
    secure: true,
    connectTimeoutMs: 5000,
    resolvedAddress: "2001:db8::1",
    resolvedFamily: 6,
  });
  assert.equal(scheduler.runNext(), 25);
  assert.equal(must(attempts[1], "the connector made that many attempts").target.resolvedAddress, "192.0.2.1");
  const winner = new FakeConnection("winner");
  must(attempts[1], "the connector made that many attempts").result.resolve(winner);
  assert.equal(await connecting, winner);
  assert.equal(must(attempts[0], "the connector made that many attempts").signal.aborted, true);
  const late = new FakeConnection("late");
  must(attempts[0], "the connector made that many attempts").result.resolve(late);
  await Promise.resolve();
  assert.equal(late.closed, true);
});

test("a failed address accelerates the next attempt and exhaustion invalidates DNS", async () => {
  let resolverCalls = 0;
  const cache = new DnsCache({
    resolver: {
      resolve() {
        resolverCalls++;
        return Promise.resolve([v4("192.0.2.1"), v6("2001:db8::1")]);
      },
    },
    nowMilliseconds: () => 0,
  });
  // One recorded connect: what it was asked for, and the resolver that decides its outcome.
  const attempts: (string | undefined)[] = [];
  const connector = new DnsConnector({
    cache,
    scheduler: new ManualScheduler(),
    connector: {
      connect(target: ConnectAddress): Promise<ByteConnection> {
        attempts.push(target.resolvedAddress);
        return Promise.reject(new Error("failed " + target.resolvedAddress));
      },
    },
  });
  await assert.rejects(connector.connect(address(), new AbortController().signal), (error: unknown) => {
    return error instanceof DnsConnectionError && error.failures.length === 2;
  });
  assert.deepEqual(attempts, ["192.0.2.1", "2001:db8::1"]);
  await assert.rejects(connector.connect(address(), new AbortController().signal));
  assert.equal(resolverCalls, 2);
});

test("DnsConnector preserves exact external cancellation and bypasses literal addresses", async () => {
  let resolverCalls = 0;
  // Captured from inside the connector, so it says what it will hold.
  let attemptedSignal: AbortSignal | undefined;
  const cache = new DnsCache({
    resolver: {
      resolve() {
        resolverCalls++;
        return Promise.resolve([v4("192.0.2.1")]);
      },
    },
    nowMilliseconds: () => 0,
  });
  const connector = new DnsConnector({
    cache,
    scheduler: new ManualScheduler(),
    connector: {
      connect(_target, signal) {
        attemptedSignal = signal;
        return new Promise((_resolve, reject) => {
          signal[abortSignalSubscribe](() => reject(signal.reason));
        });
      },
    },
  });
  const controller = new AbortController();
  const connecting = connector.connect(address(), controller.signal);
  await flushMicrotasks();
  const reason = new Error("cancel exact");
  controller.abort(reason);
  await assert.rejects(connecting, (error: unknown) => error === reason);
  assert.equal(must(attemptedSignal, "the connector was asked to connect").aborted, true);

  const literalConnection = new FakeConnection("literal");
  const literal = new DnsConnector({
    cache,
    scheduler: new ManualScheduler(),
    connector: { connect: () => Promise.resolve(literalConnection) },
  });
  assert.equal(
    await literal.connect(address("127.0.0.1"), new AbortController().signal),
    literalConnection,
  );
  assert.equal(resolverCalls, 1);
});

test("HostNodeSocketConnector connects physically while retaining logical hostname", async () => {
  const server = createServer((socket) => socket.end());
  server.listen(0, "127.0.0.1");
  await new Promise<void>((resolve) => server.once("listening", () => resolve()));
  const serverPort = portOf(server);
  const connector = new HostNodeSocketConnector();
  const connection = await connector.connect(
    {
      hostname: "does-not-resolve.invalid",
      port: serverPort,
      secure: false,
      connectTimeoutMs: 1000,
      resolvedAddress: "127.0.0.1",
      resolvedFamily: 4,
    },
    new AbortController().signal,
  );
  connection.close();
  await new Promise<void>((resolve) => server.close(() => resolve()));
});

import assert from "node:assert/strict";
import test from "node:test";
import { DOMException } from "../src/core/errors.ts";

const NativeDOMException = globalThis.DOMException;

function construct(message?: unknown, name?: unknown): DOMException {
  return new DOMException(message as string | undefined, name as string | undefined);
}

test("DOMException string conversion agrees with Node for ordinary argument values", () => {
  const values: unknown[] = [undefined, null, false, true, 0, -0, 1n, NaN, Infinity, "", "AbortError", {}, [1, 2]];
  // Node 24.20 has a nonstandard object-valued second-argument options overload.
  // Compare its DOMString branch here; the separate object-name controls follow
  // Web IDL's normative DOMString argument rather than that Node extension.
  const names = values.filter((value) => value === null || typeof value !== "object");
  for (const message of values) {
    for (const name of names) {
      const actual = construct(message, name);
      const expected = new NativeDOMException(message as string, name as string);
      assert.equal(actual.message, expected.message);
      assert.equal(actual.name, expected.name);
      assert.equal(actual.code, expected.code);
    }
  }
});

test("DOMException converts message then name exactly once", () => {
  const order: string[] = [];
  const message = { toString() { order.push("message"); return "detail"; } };
  const name = { toString() { order.push("name"); return "AbortError"; } };
  const actual = construct(message, name);
  assert.deepEqual(order, ["message", "name"]);
  assert.equal(actual.message, "detail");
  assert.equal(actual.name, "AbortError");
  assert.equal(actual.code, 20);
  assert.deepEqual(order, ["message", "name"]);
});

test("DOMException name conversion propagates its exact failure", () => {
  const failure = {};
  const name = { toString(): never { throw failure; } };
  assert.throws(() => construct("message", name), (error: unknown) => error === failure);
});

test("DOMException message conversion failure prevents name conversion", () => {
  const failure = {};
  let names = 0;
  const message = { toString(): never { throw failure; } };
  const name = { toString() { names++; return "AbortError"; } };
  assert.throws(() => construct(message, name), (error: unknown) => error === failure);
  assert.equal(names, 0);
});

test("DOMException rejects Symbol conversion in either argument", () => {
  assert.throws(() => construct(Symbol("message"), "name"), TypeError);
  assert.throws(() => construct("message", Symbol("name")), TypeError);
});

test("DOMException stores converted names without retaining a mutable input", () => {
  let name = "InvalidCharacterError";
  const input = { toString() { return name; } };
  const exception = construct("message", input);
  name = "WrongDocumentError";
  assert.equal(exception.name, "InvalidCharacterError");
  assert.equal(exception.code, 5);
});

test("DOMException code ignores an ordinary subclass name override", () => {
  class Derived extends DOMException {
    override get name(): string { return "WrongDocumentError"; }
  }
  class NativeDerived extends NativeDOMException {
    override get name(): string { return "WrongDocumentError"; }
  }
  const actual = new Derived("message", "InvalidCharacterError");
  const expected = new NativeDerived("message", "InvalidCharacterError");
  assert.equal(actual.name, expected.name);
  assert.equal(actual.code, expected.code);
  assert.equal(actual.code, 5);
  assert.equal(actual.toString(), expected.toString());
});

test("DOMException inherited name and message cannot be assigned", () => {
  const exception = new DOMException("detail", "AbortError");
  const writable: Error = exception;
  assert.throws(() => { writable.name = "WrongDocumentError"; }, TypeError);
  assert.throws(() => { writable.message = "changed"; }, TypeError);
  assert.equal(exception.name, "AbortError");
  assert.equal(exception.message, "detail");
  assert.equal(exception.code, 20);
});

test("DOMException inherits Error string formatting for default and empty names", () => {
  for (const [message, name] of [["", ""], ["detail", ""], ["", "AbortError"], ["detail", "AbortError"]]) {
    assert.equal(new DOMException(message, name).toString(), new NativeDOMException(message, name).toString());
  }
  assert.equal(new DOMException().toString(), new NativeDOMException().toString());
});

// The Cache API over provider-owned durable storage.
//
// The plan asks for "a separate Cache/CacheStorage API with provider-owned durable
// storage", and the memory store's own comment says production providers should inject
// a durable one. This is that store, driven two ways: directly, where the store's own
// contract lives (revisions, handles, body lifetime), and through the real `Cache` and
// `CacheStorage` objects, because a store that satisfies its interface and cannot serve
// the API above it has only passed a test of itself.
import assert from "node:assert/strict";
import test from "node:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  AbortController,
  DurableCacheStorageStore,
  Blob,
  Response,
} from "../src/index.ts";
import { durableStoreFromFlat } from "../src/provider.ts";
import { createHostNodeWebPlatform } from "../host/node-runtime.ts";
import { HostNodeDurableStore } from "../host/node-runtime.ts";
import { FakeFlat } from "./fake-flat.ts";
import type { TestContext } from "node:test";
import { must } from "./harness.ts";
import type { DurableByteStore } from "../src/provider.ts";
import type { CacheStorageEntry } from "../src/cache/cache-storage.ts";
import type { AbortSignal } from "../src/index.ts";

const encoder = new TextEncoder();
const none = () => new AbortController().signal;

const BACKENDS = [
  {
    name: "host filesystem",
    make(t: TestContext): DurableByteStore {
      const root = mkdtempSync(join(tmpdir(), "nts-cachestorage-"));
      t.after(() => rmSync(root, { recursive: true, force: true }));
      return new HostNodeDurableStore({ root });
    },
  },
  {
    name: "flat provider through the adapter",
    make() {
      return durableStoreFromFlat(new FakeFlat());
    },
  },
];

/** Every field set to something a lazy codec would lose. */
function requestRecord(
  url: string,
  overrides: Partial<CacheStorageEntry["request"]> = {},
): CacheStorageEntry["request"] {
  return {
    url,
    urlWithoutFragment: url,
    urlWithoutSearchOrFragment: url,
    method: "GET",
    headers: [
      ["accept", "*/*"],
      ["x-odd", "a, b; c=\"d\""],
    ],
    destination: "xslt",
    referrer: "about:client",
    referrerPolicy: "strict-origin-when-cross-origin",
    mode: "no-cors",
    credentials: "include",
    cache: "only-if-cached",
    redirect: "manual",
    integrity: "sha384-é中文",
    keepalive: true,
    priority: "low",
    isReloadNavigation: false,
    isHistoryNavigation: true,
    ...overrides,
  };
}

function responseRecord(
  body: Blob | null,
  overrides: Partial<CacheStorageEntry["response"]> = {},
): CacheStorageEntry["response"] {
  return {
    status: 203,
    statusText: "Non-Authoritative Information",
    headers: [["content-type", "text/plain;charset=UTF-8"]],
    body,
    url: "https://cache.test/final",
    redirected: true,
    type: "cors",
    ...overrides,
  };
}

function entry(
  url: string,
  body: Blob | null,
  overrides: Partial<CacheStorageEntry["response"]> = {},
): CacheStorageEntry {
  return { request: requestRecord(url), response: responseRecord(body, overrides) };
}

async function blobText(blob: Blob | null): Promise<string | null> {
  return blob === null ? null : await blob.text();
}

for (const backend of BACKENDS) {
  const only = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
    test(`${name} [${backend.name}]`, fn);
  };

  only("a cache list round-trips every field of both records", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    const handle = await store.open("v1");
    const original = entry("https://cache.test/a#frag", new Blob(["stored bytes"]));

    assert.equal(await store.compareExchange(handle, 0, [original]), true);
    const snapshot = await store.read(handle);
    assert.equal(snapshot.revision, 1);
    assert.equal(snapshot.entries.length, 1);
    const read = must(snapshot.entries[0], "the snapshot holds the entry that was written");
    assert.deepEqual(read.request, original.request);
    assert.equal(read.response.status, 203);
    assert.equal(read.response.statusText, "Non-Authoritative Information");
    assert.deepEqual(read.response.headers, original.response.headers);
    assert.equal(read.response.url, "https://cache.test/final");
    assert.equal(read.response.redirected, true);
    assert.equal(read.response.type, "cors");
    assert.equal(await blobText(read.response.body), "stored bytes");
  });

  only("a stale revision is refused and changes nothing", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    const handle = await store.open("v1");
    await store.compareExchange(handle, 0, [entry("https://cache.test/a", new Blob(["first"]))]);

    assert.equal(
      await store.compareExchange(handle, 0, [entry("https://cache.test/b", null)]),
      false,
      "the revision moved, so the exchange must not apply",
    );
    const snapshot = await store.read(handle);
    assert.equal(snapshot.revision, 1);
    assert.equal(must(snapshot.entries[0], "the snapshot holds the entry that was written").request.url, "https://cache.test/a");
    assert.equal(await blobText(must(snapshot.entries[0], "the snapshot holds the entry that was written").response.body), "first");
  });

  only("a body that came back from read is not stored twice", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    const handle = await store.open("v1");
    await store.compareExchange(handle, 0, [entry("https://cache.test/a", new Blob(["kept"]))]);

    const first = await store.read(handle);
    const keysBefore = (await bytes.list("cache-storage", none())).map((r) => r.key).sort();

    // The same entries handed straight back: a store that could not recognise its own
    // Blob would write the bytes again under a new key and orphan the old one.
    assert.equal(await store.compareExchange(handle, 1, first.entries), true);
    const keysAfter = (await bytes.list("cache-storage", none())).map((r) => r.key).sort();
    assert.deepEqual(keysAfter, keysBefore, "no body was rewritten");
    assert.equal(await blobText(must((await store.read(handle)).entries[0], "the snapshot holds the entry that was written").response.body), "kept");
  });

  only("read returns one Blob per stored body", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    const handle = await store.open("v1");
    await store.compareExchange(handle, 0, [entry("https://cache.test/a", new Blob(["same"]))]);

    const a = must((await store.read(handle)).entries[0], "the snapshot holds the entry that was written").response.body;
    const b = must((await store.read(handle)).entries[0], "the snapshot holds the entry that was written").response.body;
    assert.equal(a, b, "identity is what makes the round trip recognisable");
  });

  only("a body no entry names any longer is removed", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    const handle = await store.open("v1");
    await store.compareExchange(handle, 0, [
      entry("https://cache.test/a", new Blob(["a body"])),
      entry("https://cache.test/b", new Blob(["b body"])),
    ]);
    assert.equal((await bytes.list("cache-storage", none())).length, 4);

    const snapshot = await store.read(handle);
    const remaining = snapshot.entries.filter((e) => e.request.url === "https://cache.test/a");
    assert.equal(await store.compareExchange(handle, 1, remaining), true);
    assert.equal(
      (await bytes.list("cache-storage", none())).length,
      3,
      "names, one list, one body",
    );
    assert.equal(await blobText(must((await store.read(handle)).entries[0], "the snapshot holds the entry that was written").response.body), "a body");
  });

  only("names, lists and bodies all survive a reopen", async (t) => {
    const bytes = backend.make(t);
    const first = await DurableCacheStorageStore.open(bytes);
    const one = await first.open("v1");
    const two = await first.open("v2");
    await first.compareExchange(one, 0, [entry("https://cache.test/a", new Blob(["persisted"]))]);
    await first.compareExchange(two, 0, [entry("https://cache.test/b", null)]);

    const second = await DurableCacheStorageStore.open(bytes);
    assert.deepEqual(await second.keys(), ["v1", "v2"]);
    const reopened = must(await second.lookup("v1"), "the store kept that cache name");
    const snapshot = await second.read(reopened);
    assert.equal(snapshot.revision, 1);
    assert.equal(await blobText(must(snapshot.entries[0], "the snapshot holds the entry that was written").response.body), "persisted");
    assert.equal((await second.read(must(await second.lookup("v2"), "the store kept that cache name"))).entries[0]?.response.body, null);
  });

  only("deleting a name removes its list and its bodies", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    const handle = await store.open("v1");
    await store.open("keep");
    await store.compareExchange(handle, 0, [entry("https://cache.test/a", new Blob(["gone"]))]);

    assert.equal(await store.delete("v1"), true);
    assert.equal(await store.delete("v1"), false);
    assert.deepEqual(await store.keys(), ["keep"]);
    const keys = (await bytes.list("cache-storage", none())).map((r) => r.key).sort();
    assert.equal(keys.length, 2, `names plus the surviving list, saw ${keys}`);

    const reopened = await DurableCacheStorageStore.open(bytes);
    assert.deepEqual(await reopened.keys(), ["keep"]);
  });

  only("a body left by an interrupted exchange is reclaimed on open", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    const handle = await store.open("v1");
    await store.compareExchange(handle, 0, [entry("https://cache.test/a", new Blob(["real"]))]);

    // Exactly what an interruption between the body write and the list write leaves.
    const orphan = await bytes.write("cache-storage", "b9999", none());
    await orphan.append(encoder.encode("orphaned"));
    await orphan.commit();

    const reopened = await DurableCacheStorageStore.open(bytes);
    const keys = (await bytes.list("cache-storage", none())).map((r) => r.key).sort();
    assert.equal(keys.includes("b9999"), false, `the orphan is gone, saw ${keys}`);
    const snapshot = await reopened.read(must(await reopened.lookup("v1"), "the store kept that cache name"));
    assert.equal(await blobText(must(snapshot.entries[0], "the snapshot holds the entry that was written").response.body), "real");
  });

  only("an exchange interrupted between its keys leaves nothing dangling", async (t) => {
    const bytes = backend.make(t);
    // Bodies are written before the list that names them, and the byte store makes one
    // key atomic and says nothing about two. This fails the list write, which is the
    // window a crash lands in.
    let failLists = false;
    const interrupted = {
      read: (...args: Parameters<DurableByteStore["read"]>) => bytes.read(...args),
      source: (...args: Parameters<DurableByteStore["source"]>) => bytes.source(...args),
      delete: (...args: Parameters<DurableByteStore["delete"]>) => bytes.delete(...args),
      list: (...args: Parameters<DurableByteStore["list"]>) => bytes.list(...args),
      size: (...args: Parameters<DurableByteStore["size"]>) => bytes.size(...args),
      close: () => bytes.close(),
      async write(namespace: string, key: string, signal: AbortSignal) {
        const write = await bytes.write(namespace, key, signal);
        if (!failLists || !key.startsWith("l")) return write;
        return {
          append: (chunk: Uint8Array) => write.append(chunk),
          discard: () => write.discard(),
          async commit() {
            await write.discard();
            throw new Error("the power went out");
          },
        };
      },
    };

    const store = await DurableCacheStorageStore.open(interrupted);
    const handle = await store.open("v1");
    await store.compareExchange(handle, 0, [entry("https://cache.test/a", new Blob(["before"]))]);

    failLists = true;
    await assert.rejects(
      () => store.compareExchange(handle, 1, [entry("https://cache.test/b", new Blob(["lost"]))]),
      /power went out/,
    );
    failLists = false;

    // Checked before any reopen. Reclamation at open would hide a failed exchange that
    // left its body behind, so the claim has to be tested at the moment it is made.
    const afterFailure = (await bytes.list("cache-storage", none())).map((r) => r.key).sort();
    assert.deepEqual(afterFailure, ["b1", "l0", "names"], `saw ${afterFailure}`);

    const reopened = await DurableCacheStorageStore.open(bytes);
    const snapshot = await reopened.read(must(await reopened.lookup("v1"), "the store kept that cache name"));
    assert.equal(snapshot.revision, 1, "the list is still the one that committed");
    assert.equal(snapshot.entries.length, 1);
    assert.equal(await blobText(must(snapshot.entries[0], "the snapshot holds the entry that was written").response.body), "before");
    assert.equal(
      (await bytes.list("cache-storage", none())).length,
      3,
      "names, one list, one body -- the abandoned body is not among them",
    );
  });

  only("quotas are refused and leave the stored list alone", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes, {
      maxCaches: 1,
      maxEntriesPerCache: 1,
      maxBodyBytesPerCache: 4,
    });
    const handle = await store.open("bounded");
    await assert.rejects(() => store.open("second"), (e: unknown) => e instanceof Error && e.name === "QuotaExceededError");
    assert.equal(await store.compareExchange(handle, 0, [entry("https://c.test/a", null)]), true);

    await assert.rejects(
      () =>
        store.compareExchange(handle, 1, [
          entry("https://c.test/a", null),
          entry("https://c.test/b", null),
        ]),
      (e: unknown) => e instanceof Error && e.name === "QuotaExceededError",
    );
    await assert.rejects(
      () => store.compareExchange(handle, 1, [entry("https://c.test/a", new Blob(["toolong"]))]),
      (e: unknown) => e instanceof Error && e.name === "QuotaExceededError",
    );
    const snapshot = await store.read(handle);
    assert.equal(snapshot.revision, 1, "a refused exchange did not advance the revision");
    assert.equal(snapshot.entries.length, 1);
    // No refused body may be left in storage, including one written before the refusal.
    const keys = (await bytes.list("cache-storage", none())).map((r) => r.key).sort();
    assert.deepEqual(keys, ["l0", "names"], `saw ${keys}`);
  });

  only("a handle from another store is refused", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    // Deliberately made to collide: both stores allocate ids from zero, so the foreign
    // handle names a list that exists here too. Without the owner check this reads --
    // and worse, writes -- somebody else's cache rather than failing to find one.
    const mine = await store.open("mine");
    const other = await DurableCacheStorageStore.open(backend.make(t), { namespace: "other" });
    const foreign = await other.open("v1");
    await store.compareExchange(mine, 0, [entry("https://cache.test/mine", new Blob(["mine"]))]);

    await assert.rejects(() => store.read(foreign), TypeError);
    await assert.rejects(() => store.compareExchange(foreign, 1, []), TypeError);
    const snapshot = await store.read(mine);
    assert.equal(snapshot.entries.length, 1, "the foreign exchange did not touch this cache");
  });

  only("the real Cache API works over it, and what it stored is still there", async (t) => {
    const bytes = backend.make(t);
    const store = await DurableCacheStorageStore.open(bytes);
    const runtime = createHostNodeWebPlatform({
      cacheStorageStore: store,
      fetchTransport: {
        dispatch: async () => {
          throw new Error("Unexpected network request");
        },
      },
    });

    const cache = await runtime.caches.open("pages");
    await cache.put("https://cache.test/one", new Response("first page"));
    await cache.put("https://cache.test/two", new Response("second page", { status: 202 }));

    const matched = await cache.match("https://cache.test/one");
    assert.equal(await must(matched, "the cache holds that entry").text(), "first page");
    assert.equal((await cache.keys()).length, 2);
    assert.equal(await cache.delete("https://cache.test/two"), true);
    assert.equal(await cache.match("https://cache.test/two"), undefined);
    assert.deepEqual(await runtime.caches.keys(), ["pages"]);

    // The API is only half the claim; the other half is that a new process finds it.
    const reopened = await DurableCacheStorageStore.open(bytes);
    const laterRuntime = createHostNodeWebPlatform({
      cacheStorageStore: reopened,
      fetchTransport: {
        dispatch: async () => {
          throw new Error("Unexpected network request");
        },
      },
    });
    const laterCache = await laterRuntime.caches.open("pages");
    const survived = must(
      await laterCache.match("https://cache.test/one"),
      "the cache survived the reopen",
    );
    assert.equal(await survived.text(), "first page");
    assert.equal(survived.status, 200);
    assert.equal((await laterCache.keys()).length, 1);
  });
}

