//
// This is the byte store's first consumer. Until now the ABI had tests and no caller,
// which is the pattern this ledger keeps recording as a defect in other people's work:
// a mechanism nothing routes through is a mechanism nobody has checked the shape of.
//
// The suite runs twice, over two different providers reached two different ways. The
// host strawman is a real filesystem, so it answers whether atomic replace and crash
// ordering hold against something that can actually crash. The fake flat provider goes
// through `durableStoreFromFlat`, so the adapter carries a real workload rather than
// only its own unit tests -- and a disagreement between the two runs is a disagreement
// between the two halves of the seam, which is exactly what neither half can find alone.
import assert from "node:assert/strict";
import test from "node:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  AbortController,
  DurableHttpCacheStore,
} from "../src/index.ts";
import { durableStoreFromFlat } from "../src/provider.ts";
import { HostNodeDurableStore } from "../host/node-runtime.ts";
import { FakeFlat } from "./fake-flat.ts";

const encoder = new TextEncoder();
const none = () => new AbortController().signal;

const BACKENDS = [
  {
    name: "host filesystem",
    make(t) {
      const root = mkdtempSync(join(tmpdir(), "nts-cache-"));
      t.after(() => rmSync(root, { recursive: true, force: true }));
      return new HostNodeDurableStore({ root });
    },
  },
  {
    name: "flat provider through the adapter",
    make() {
      return durableStoreFromFlat(new FakeFlat());
    },
  },
];

function metadataFor(url, overrides = {}) {
  return {
    url,
    method: "GET",
    requestHeaders: [["accept", "*/*"]],
    status: 200,
    statusText: "OK",
    responseHeaders: [["content-type", "text/plain"]],
    vary: [],
    requestTime: 1_700_000_000_123,
    responseTime: 1_700_000_000_456,
    ...overrides,
  };
}

async function put(cache, metadata, text) {
  const writer = await cache.createWrite(metadata);
  await writer.write(encoder.encode(text));
  await writer.commit();
}

async function bodyText(entry) {
  const stream = await entry.body.open();
  const chunks = [];
  for await (const chunk of stream) chunks.push(chunk);
  let total = 0;
  for (const chunk of chunks) total += chunk.length;
  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.length;
  }
  return new TextDecoder().decode(bytes);
}

for (const backend of BACKENDS) {
  const suite = (name, fn) => test(`${name} [${backend.name}]`, fn);

  suite("an entry round-trips through the store byte for byte", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes);
    // Values chosen to break a codec that delimits rather than length-prefixes, and a
    // codec that round-trips times through 32 bits.
    const metadata = metadataFor("https://example.test/a", {
      statusText: "OK� and more",
      requestHeaders: [
        ["accept", "*/*"],
        ["x-odd", "a, b�c"],
      ],
      responseHeaders: [["etag", '"é中文"']],
      vary: [
        { name: "accept", value: "*/*" },
        { name: "accept-encoding", value: null },
      ],
      requestTime: 1_700_000_000_123,
      responseTime: 9_007_199_254_740_991,
    });
    await put(cache, metadata, "hello cached world");

    // Reopened deliberately: `find` answers from the index, so asserting on it in the
    // writing process would exercise the object that was handed in and not the codec.
    const reopened = await DurableHttpCacheStore.open(bytes);
    const found = await reopened.find("https://example.test/a");
    assert.equal(found.length, 1);
    const entry = found[0];
    assert.equal(entry.url, metadata.url);
    assert.equal(entry.method, "GET");
    assert.equal(entry.status, 200);
    assert.equal(entry.statusText, metadata.statusText);
    assert.deepEqual(entry.requestHeaders, metadata.requestHeaders);
    assert.deepEqual(entry.responseHeaders, metadata.responseHeaders);
    assert.deepEqual(entry.vary, metadata.vary);
    assert.equal(entry.requestTime, metadata.requestTime);
    assert.equal(entry.responseTime, metadata.responseTime);
    assert.equal(entry.body.length, 18);
    assert.equal(await bodyText(entry), "hello cached world");
  });

  suite("entries survive being reopened, metadata and bodies alike", async (t) => {
    const bytes = backend.make(t);
    const first = await DurableHttpCacheStore.open(bytes);
    await put(first, metadataFor("https://example.test/a"), "first body");
    await put(first, metadataFor("https://example.test/b"), "second body");

    const second = await DurableHttpCacheStore.open(bytes);
    const a = (await second.find("https://example.test/a"))[0];
    const b = (await second.find("https://example.test/b"))[0];
    assert.equal(await bodyText(a), "first body");
    assert.equal(await bodyText(b), "second body");
    assert.equal(a.status, 200);
    assert.equal((await second.find("https://example.test/missing")).length, 0);
  });

  suite("a variant with equal vary supersedes; a different one coexists", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes);
    const gzip = metadataFor("https://example.test/v", {
      vary: [{ name: "accept-encoding", value: "gzip" }],
    });
    const identity = metadataFor("https://example.test/v", {
      vary: [{ name: "accept-encoding", value: "identity" }],
    });

    await put(cache, gzip, "compressed");
    await put(cache, identity, "plain");
    assert.equal((await cache.find("https://example.test/v")).length, 2);

    // A shorter list that is a prefix of a longer one: equal for as far as the shorter
    // one goes, and a different variant all the same.
    const gzipAndLanguage = metadataFor("https://example.test/v", {
      vary: [
        { name: "accept-encoding", value: "gzip" },
        { name: "accept-language", value: "en" },
      ],
    });
    await put(cache, gzipAndLanguage, "compressed english");
    assert.equal((await cache.find("https://example.test/v")).length, 3);

    await put(cache, gzip, "compressed again");
    const found = await cache.find("https://example.test/v");
    assert.equal(found.length, 3, "the equal-vary variant replaced rather than added");
    const texts = [];
    for (const entry of found) texts.push(await bodyText(entry));
    assert.deepEqual(texts.sort(), ["compressed again", "compressed english", "plain"]);

    // And the superseded body is gone from storage rather than merely unreferenced.
    const reopened = await DurableHttpCacheStore.open(bytes);
    assert.equal((await reopened.find("https://example.test/v")).length, 3);
    assert.equal((await bytes.list("http-cache", none())).length, 6);
  });

  suite("delete removes every variant of a URL and both of its keys", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes);
    await put(cache, metadataFor("https://example.test/x", { vary: [] }), "one");
    await put(
      cache,
      metadataFor("https://example.test/x", { vary: [{ name: "accept", value: "text/html" }] }),
      "two",
    );
    await put(cache, metadataFor("https://example.test/keep"), "kept");

    await cache.delete("https://example.test/x");
    assert.equal((await cache.find("https://example.test/x")).length, 0);
    assert.equal((await cache.find("https://example.test/keep")).length, 1);
    assert.equal(
      (await bytes.list("http-cache", none())).length,
      2,
      "one metadata key and one body key are left",
    );
  });

  suite("replaceMetadata rewrites metadata and keeps the body", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes);
    await put(cache, metadataFor("https://example.test/r"), "unchanged body");
    const entry = (await cache.find("https://example.test/r"))[0];

    const replaced = await cache.replaceMetadata(
      entry,
      metadataFor("https://example.test/r", {
        status: 203,
        responseHeaders: [["content-type", "text/plain"], ["age", "12"]],
      }),
    );
    assert.equal(replaced.status, 203);
    assert.equal(await bodyText(replaced), "unchanged body");

    // Durable, not only in the index.
    const reopened = await DurableHttpCacheStore.open(bytes);
    const after = (await reopened.find("https://example.test/r"))[0];
    assert.equal(after.status, 203);
    assert.deepEqual(after.responseHeaders, [["content-type", "text/plain"], ["age", "12"]]);
    assert.equal(await bodyText(after), "unchanged body");
  });

  suite("an entry this store did not hand out is refused by touch and replace", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes);
    await put(cache, metadataFor("https://example.test/f"), "body");
    const foreign = { ...metadataFor("https://example.test/f"), body: null };

    assert.equal(await cache.replaceMetadata(foreign, metadataFor("https://example.test/f")), null);
    await cache.touch(foreign);
    assert.equal((await cache.find("https://example.test/f")).length, 1);

    // A stale entry from before a replacement is refused too.
    const entry = (await cache.find("https://example.test/f"))[0];
    await cache.replaceMetadata(entry, metadataFor("https://example.test/f", { status: 203 }));
    assert.equal(await cache.replaceMetadata(entry, metadataFor("https://example.test/f")), null);
  });

  suite("a body committed without its metadata is reclaimed on open", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes);
    await put(cache, metadataFor("https://example.test/a"), "real entry");

    // Exactly the state an interrupted commit leaves: the body landed, the metadata
    // never did. Nothing can name it again, so it is storage that leaks.
    const orphan = await bytes.write("http-cache", "b9999", none());
    await orphan.append(encoder.encode("orphaned bytes"));
    await orphan.commit();
    assert.equal((await bytes.list("http-cache", none())).length, 3);

    const reopened = await DurableHttpCacheStore.open(bytes);
    assert.equal((await reopened.find("https://example.test/a")).length, 1);
    const keys = (await bytes.list("http-cache", none())).map((record) => record.key).sort();
    assert.deepEqual(keys, ["b0", "m0"], "the orphan is gone and the real entry is not");
  });

  suite("a commit interrupted between its two keys leaves nothing dangling", async (t) => {
    const bytes = backend.make(t);
    // A publish writes the body's key and then the metadata's, and the byte store makes
    // one key atomic and says nothing about two. This fails the second commit, which is
    // the window a crash lands in.
    let failNext = false;
    const interrupted = {
      ...bytes,
      read: (...args) => bytes.read(...args),
      source: (...args) => bytes.source(...args),
      delete: (...args) => bytes.delete(...args),
      list: (...args) => bytes.list(...args),
      size: (...args) => bytes.size(...args),
      close: () => bytes.close(),
      async write(namespace, key, signal) {
        const write = await bytes.write(namespace, key, signal);
        if (!failNext || !key.startsWith("m")) return write;
        return {
          append: (chunk) => write.append(chunk),
          discard: () => write.discard(),
          async commit() {
            await write.discard();
            throw new Error("the power went out");
          },
        };
      },
    };

    const cache = await DurableHttpCacheStore.open(interrupted);
    await put(cache, metadataFor("https://example.test/before"), "survivor");
    failNext = true;
    const writer = await cache.createWrite(metadataFor("https://example.test/lost"));
    await writer.write(encoder.encode("bytes that reached storage"));
    await assert.rejects(() => writer.commit(), /power went out/);
    failNext = false;

    // The body did land -- that is the point of the window.
    assert.equal((await bytes.list("http-cache", none())).length, 3);

    const reopened = await DurableHttpCacheStore.open(bytes);
    assert.equal((await reopened.find("https://example.test/lost")).length, 0);
    assert.equal(await bodyText((await reopened.find("https://example.test/before"))[0]), "survivor");
    const keys = (await bytes.list("http-cache", none())).map((record) => record.key).sort();
    assert.deepEqual(keys, ["b0", "m0"], "the half-written entry left no trace");
  });

  suite("metadata that cannot be decoded is discarded with its body", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes);
    await put(cache, metadataFor("https://example.test/a"), "real entry");

    for (const [key, content] of [
      ["b4242", "body for the unreadable metadata"],
      ["m4242", "not a valid metadata record"],
    ]) {
      const write = await bytes.write("http-cache", key, none());
      await write.append(encoder.encode(content));
      await write.commit();
    }

    const reopened = await DurableHttpCacheStore.open(bytes);
    assert.equal((await reopened.find("https://example.test/a")).length, 1);
    const keys = (await bytes.list("http-cache", none())).map((record) => record.key).sort();
    assert.deepEqual(keys, ["b0", "m0"]);
  });

  suite("an oversized entry is refused and leaves nothing behind", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes, { maxEntryBytes: 8 });
    const writer = await cache.createWrite(metadataFor("https://example.test/big"));
    await writer.write(encoder.encode("12345"));
    await assert.rejects(() => writer.write(encoder.encode("678901")), { name: "LimitError" });
    await writer.abort(new Error("too big"));

    assert.equal((await cache.find("https://example.test/big")).length, 0);
    assert.deepEqual(await bytes.list("http-cache", none()), []);
    // And the key is free again, which an abandoned write holding its key would break.
    await put(cache, metadataFor("https://example.test/big"), "small");
    assert.equal((await cache.find("https://example.test/big")).length, 1);
  });

  suite("a zero limit means the store declines to write at all", async (t) => {
    const bytes = backend.make(t);
    for (const options of [{ maxEntries: 0 }, { maxTotalBytes: 0 }, { maxEntryBytes: 0 }]) {
      const cache = await DurableHttpCacheStore.open(bytes, options);
      assert.equal(await cache.createWrite(metadataFor("https://example.test/n")), null);
    }
  });

  suite("eviction drops the least recently used entry and its bytes", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes, { maxEntries: 3 });
    for (const name of ["a", "b", "c"]) {
      await put(cache, metadataFor(`https://example.test/${name}`), name.repeat(4));
    }
    // `a` becomes the most recently used, so `b` is the one that should go.
    await cache.touch((await cache.find("https://example.test/a"))[0]);
    await put(cache, metadataFor("https://example.test/d"), "dddd");

    assert.equal((await cache.find("https://example.test/b")).length, 0);
    for (const name of ["a", "c", "d"]) {
      assert.equal((await cache.find(`https://example.test/${name}`)).length, 1, name);
    }
    const keys = (await bytes.list("http-cache", none())).map((record) => record.key).sort();
    assert.equal(keys.length, 6, "three entries, two keys each");
  });

  suite("a byte budget evicts until it is met", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes, { maxTotalBytes: 20 });
    for (const name of ["a", "b", "c"]) {
      await put(cache, metadataFor(`https://example.test/${name}`), name.repeat(10));
    }
    let total = 0;
    for (const name of ["a", "b", "c"]) {
      for (const entry of await cache.find(`https://example.test/${name}`)) {
        total += entry.body.length;
      }
    }
    assert.ok(total <= 20, `kept ${total} bytes within a 20 byte budget`);
    assert.equal((await cache.find("https://example.test/a")).length, 0, "the oldest went first");
  });

  suite("a finished write refuses further use", async (t) => {
    const bytes = backend.make(t);
    const cache = await DurableHttpCacheStore.open(bytes);
    const writer = await cache.createWrite(metadataFor("https://example.test/w"));
    await writer.write(encoder.encode("done"));
    await writer.commit();
    await assert.rejects(() => writer.write(encoder.encode("more")), TypeError);
    await assert.rejects(() => writer.commit(), TypeError);
    await writer.abort(new Error("late"));
    assert.equal(await bodyText((await cache.find("https://example.test/w"))[0]), "done");
  });
}

// A cookie jar that survives the process.
//
// Run over two providers reached two different ways, following what the durable cache
// suite established: the host filesystem answers whether atomic replace really holds
// against something that can crash, and the fake flat provider carries the same workload
// through `durableStoreFromFlat` so the adapter is exercised by a real caller rather than
// only by its own unit tests. A disagreement between the two runs is a disagreement
// between the two halves of the seam.
//
// The cases that matter here are not the round trip. They are what happens to bytes that
// come back wrong, because a jar that silently starts empty has lost a user's session with
// no evidence anywhere and looks exactly like a first run.
import assert from "node:assert/strict";
import test from "node:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { createHostNodeWebPlatform } from "../host/node-runtime.ts";
import {
  AbortController,
  CookieJar,
  CookieJarStoreError,
  DurableCookieJarStore,
} from "../src/index.ts";
import { durableStoreFromFlat } from "../src/provider.ts";
import { HostNodeDurableStore } from "../host/node-runtime.ts";
import { FakeFlat } from "./fake-flat.ts";
import type { TestContext } from "node:test";
import type { DurableByteStore } from "../src/provider.ts";
import { must } from "./harness.ts";
import type { StoredCookie } from "../src/cookies/jar.ts";
import type { AbortSignal } from "../src/index.ts";

const none = () => new AbortController().signal;
const encoder = new TextEncoder();

const BACKENDS = [
  {
    name: "host filesystem",
    make(t: TestContext): DurableByteStore {
      const root = mkdtempSync(join(tmpdir(), "nts-jar-"));
      t.after(() => rmSync(root, { recursive: true, force: true }));
      return new HostNodeDurableStore({ root });
    },
  },
  {
    name: "flat provider through the adapter",
    make() {
      return durableStoreFromFlat(new FakeFlat());
    },
  },
];

function suite(
  name: string,
  fn: (t: TestContext, store: DurableByteStore) => void | Promise<void>,
): void {
  for (const backend of BACKENDS) {
    test(`${name} [${backend.name}]`, async (t) => {
      const api = createHostNodeWebPlatform();
      t.after(() => api.close());
      await fn(t, backend.make(t));
    });
  }
}

async function writeRaw(store: DurableByteStore, text: string): Promise<void> {
  const write = await store.write("cookies", "jar", none());
  await write.append(encoder.encode(text));
  await write.commit();
}

suite("a cookie set in one jar is present in the next one over the same store", async (t, store) => {
  const first = new CookieJar({ store: new DurableCookieJarStore(store, none()) });
  await first.setCookie("sid=abc; Path=/; Max-Age=3600", "https://example.test/a");
  await first.close();

  // A second jar over the same bytes, which is the whole point of the class.
  const second = new CookieJar({ store: new DurableCookieJarStore(store, none()) });
  assert.equal(await second.getCookieHeader("https://example.test/a"), "sid=abc");
  await second.close();
});

suite("a session cookie does not come back, because it was never persisted", async (t, store) => {
  const first = new CookieJar({ store: new DurableCookieJarStore(store, none()) });
  await first.setCookie("sid=abc; Path=/", "https://example.test/a");
  await first.close();

  const second = new CookieJar({ store: new DurableCookieJarStore(store, none()) });
  // Not an assertion about the store: the jar decides what it hands over. Written so that
  // a store which started persisting everything would be visible here.
  assert.equal(await second.getCookieHeader("https://example.test/a"), "");
  await second.close();
});

suite("saving replaces the snapshot rather than adding to it", async (t, store) => {
  const jarStore = new DurableCookieJarStore(store, none());
  const jar = new CookieJar({ store: jarStore });
  await jar.setCookie("a=1; Path=/; Max-Age=3600", "https://example.test/");
  await jar.setCookie("b=2; Path=/; Max-Age=3600", "https://example.test/");
  await jar.setCookie("a=; Path=/; Max-Age=0", "https://example.test/");
  await jar.close();

  const loaded = await new DurableCookieJarStore(store, none()).loadAll();
  // An append-shaped store would keep the expired `a` beside the deletion.
  assert.deepEqual(
    loaded.map((cookie) => cookie.name),
    ["b"],
  );
});

suite("an absent key is a first run, not a failure", async (t, store) => {
  assert.deepEqual(await new DurableCookieJarStore(store, none()).loadAll(), []);
});

suite("a snapshot that is not JSON is refused rather than read as empty", async (t, store) => {
  await writeRaw(store, "this is not json");
  await assert.rejects(
    () => new DurableCookieJarStore(store, none()).loadAll(),
    (error: unknown) => error instanceof CookieJarStoreError && /valid JSON/.test(error.message),
  );
});

suite("a snapshot that is JSON but not an array is refused", async (t, store) => {
  await writeRaw(store, '{"sid":"abc"}');
  await assert.rejects(
    () => new DurableCookieJarStore(store, none()).loadAll(),
    (error: unknown) => error instanceof CookieJarStoreError && /not an array/.test(error.message),
  );
});

suite("one unreadable cookie rejects the load by default", async (t, store) => {
  // The default has to be the loud one. Starting empty is indistinguishable from a first
  // run, so a caller cannot tell a corrupt store from a fresh one and will never look.
  await writeRaw(store, '[{"name":"sid"}]');
  await assert.rejects(
    () => new DurableCookieJarStore(store, none()).loadAll(),
    (error: unknown) => error instanceof CookieJarStoreError && /unreadable cookie/.test(error.message),
  );
});

suite("dropping is available, keeps the good ones, and says what it dropped", async (t, store) => {
  const good = {
    name: "sid",
    value: "abc",
    expiryTime: 4102444800000,
    domain: "example.test",
    path: "/",
    creationTime: 1,
    lastAccessTime: 1,
    creationIndex: 0,
    persistent: true,
    hostOnly: true,
    secure: false,
    httpOnly: false,
    sameSite: "Default",
  };
  await writeRaw(store, JSON.stringify([good, { name: "broken" }, null]));
  const reports: [number, number][] = [];
  const loaded = await new DurableCookieJarStore(store, none(), {
    onInvalid: "drop",
    reportDropped: (count, total) => reports.push([count, total]),
  }).loadAll();
  assert.deepEqual(
    loaded.map((cookie) => cookie.name),
    ["sid"],
  );
  // Dropping without a way to observe it is the failure the option exists to avoid.
  assert.deepEqual(reports, [[2, 3]]);
});

suite("dropping nothing reports nothing", async (t, store) => {
  await writeRaw(store, "[]");
  let called = 0;
  const loaded = await new DurableCookieJarStore(store, none(), {
    onInvalid: "drop",
    reportDropped: () => called++,
  }).loadAll();
  assert.deepEqual(loaded, []);
  assert.equal(called, 0, "a clean load must not report a drop");
});

suite("a cookie value outside ASCII survives the round trip", async (t, store) => {
  // The premise this test exists to pin: `JSON.stringify` escapes control characters and
  // lone surrogates, but passes ordinary non-ASCII through literally. A cookie value is an
  // octet string, so code units up to 0xFF are legitimate, and an encoder that assumed the
  // serialized form was ASCII would refuse a perfectly valid cookie.
  const jarStore = new DurableCookieJarStore(store, none());
  const cookie: StoredCookie = {
    name: "sid",
    value: "caf\u00e9-\u00ff",
    expiryTime: 4102444800000,
    domain: "example.test",
    path: "/",
    creationTime: 1,
    lastAccessTime: 1,
    creationIndex: 0,
    persistent: true,
    hostOnly: true,
    secure: false,
    httpOnly: false,
    sameSite: "Default",
  };
  await jarStore.saveAll([cookie]);
  const loaded = await jarStore.loadAll();
  assert.equal(loaded.length, 1);
  assert.equal(must(loaded[0], "the jar loaded the cookie it saved").value, "caf\u00e9-\u00ff");
});

suite("a snapshot that is not valid UTF-8 is refused, not repaired", async (t, store) => {
  // Refused rather than decoded with U+FFFD: a replacement character in a cookie value is
  // a value quietly different from the one stored, and it would be sent to a server.
  const write = await store.write("cookies", "jar", none());
  await write.append(Uint8Array.from([0x5b, 0xff, 0xfe, 0x5d]));
  await write.commit();
  await assert.rejects(
    () => new DurableCookieJarStore(store, none()).loadAll(),
    (error: unknown) => error instanceof CookieJarStoreError && /UTF-8/.test(error.message),
  );
});

suite("a save that fails mid-write leaves the key writable rather than stuck", async (t, store) => {
  // The store refuses a second concurrent write to a key rather than queueing it, so a
  // failed save that left its write open would make every later save fail too -- and the
  // symptom would appear at the next caller, not this one.
  let failNext = true;
  const failing = {
    ...store,
    write: async (namespace: string, key: string, signal: AbortSignal) => {
      const inner = await store.write(namespace, key, signal);
      return {
        append: async (bytes: Uint8Array) => {
          if (failNext) {
            failNext = false;
            throw new Error("the device is full");
          }
          await inner.append(bytes);
        },
        commit: () => inner.commit(),
        discard: () => inner.discard(),
      };
    },
  };
  const jarStore = new DurableCookieJarStore(failing, none());
  await assert.rejects(() => jarStore.saveAll([]), /device is full/);
  // The precondition this test exists for: the next save must succeed.
  await jarStore.saveAll([]);
  assert.deepEqual(await new DurableCookieJarStore(store, none()).loadAll(), []);
});

suite("the namespace and key are configurable and actually used", async (t, store) => {
  const jarStore = new DurableCookieJarStore(store, none(), {
    namespace: "other",
    key: "elsewhere",
  });
  await jarStore.saveAll([]);
  const records = await store.list("other", none());
  assert.deepEqual(
    records.map((record) => record.key),
    ["elsewhere"],
  );
  assert.deepEqual(await store.list("cookies", none()), []);
});

async function readRaw(store: DurableByteStore): Promise<string | null> {
  const bytes = await store.read("cookies", "jar", none());
  return bytes === null ? null : new TextDecoder().decode(bytes);
}

// Every field, not just the one that motivated the round trip above.
//
// That test asserts `loaded[0].value` alone, which was enough while the snapshot was written
// by reflecting over the record: `JSON.stringify(cookies)` cannot put one field's value under
// another field's name. The writer now names all thirteen fields by hand, so it can -- and a
// sabotage that swapped `hostOnly` with `secure` in the writer passed the entire suite. Every
// value below is distinct within its type so that any transposition changes the result, and
// the booleans are carried across three cookies whose patterns differ pairwise, since two of
// them sharing a value would hide a swap of exactly those two.
const ROUND_TRIP: readonly StoredCookie[] = [
  {
    name: "sid",
    value: "café-ÿ",
    expiryTime: 4102444800000,
    domain: "example.test",
    path: "/a",
    creationTime: 11,
    lastAccessTime: 22,
    creationIndex: 0,
    persistent: true,
    hostOnly: true,
    secure: false,
    httpOnly: false,
    sameSite: "Default",
  },
  {
    name: "pref",
    value: "dark",
    expiryTime: null,
    domain: "sub.example.test",
    path: "/b/c",
    creationTime: 33,
    lastAccessTime: 44,
    creationIndex: 1,
    persistent: false,
    hostOnly: false,
    secure: true,
    httpOnly: false,
    sameSite: "Strict",
  },
  {
    name: "tok",
    value: "",
    expiryTime: 1700000000123,
    domain: "other.test",
    path: "/",
    creationTime: 55,
    lastAccessTime: 66,
    creationIndex: 2,
    persistent: true,
    hostOnly: false,
    secure: false,
    httpOnly: true,
    sameSite: "None",
  },
];

suite("every field of every cookie survives the round trip unchanged", async (t, store) => {
  const jarStore = new DurableCookieJarStore(store, none());
  await jarStore.saveAll(ROUND_TRIP);
  assert.deepEqual(await jarStore.loadAll(), ROUND_TRIP);
});

suite("the snapshot on disk holds the field names it claims to", async (t, store) => {
  // A writer and a reader that swap the same two fields agree with each other, so the round
  // trip above cannot see it -- but the bytes are wrong, and a jar written by one version and
  // read by another would carry the values across swapped. Asserting the text is what pins
  // the format rather than the pair's internal consistency.
  const jarStore = new DurableCookieJarStore(store, none());
  await jarStore.saveAll([must(ROUND_TRIP[0], "the fixture has a first cookie")]);
  assert.equal(
    await readRaw(store),
    '[{"name":"sid","value":"café-ÿ","expiryTime":4102444800000,' +
      '"domain":"example.test","path":"/a","creationTime":11,"lastAccessTime":22,' +
      '"creationIndex":0,"persistent":true,"hostOnly":true,"secure":false,' +
      '"httpOnly":false,"sameSite":"Default"}]',
  );
});

suite("a field of the wrong kind is unreadable rather than coerced", async (t, store) => {
  // The reader checks each field's kind, and these are the coercions a reader written with
  // `String(x)` or `Number(x)` would silently accept: a number where a name goes, a string
  // where a timestamp goes, a string where a flag goes, and a sameSite outside the four.
  const base = must(ROUND_TRIP[0], "the round-trip fixture has a first cookie");
  const corruptions = [
    { name: 7 },
    { value: null },
    { creationTime: "11" },
    { secure: "false" },
    { sameSite: "Lax " },
    { expiryTime: "4102444800000" },
    { path: 1 },
    // The pair that a kind check alone catches and a cross-check alone does not. If a
    // wrong-kinded expiry degraded to `null` instead of being refused, `persistent` and
    // `expiryTime` would still agree with each other -- both saying "session cookie" -- and
    // the record would load as one, silently dropping an expiry the server had set.
    { expiryTime: "never", persistent: false },
    { expiryTime: true, persistent: false },
  ];
  for (const patch of corruptions) {
    await writeRaw(store, JSON.stringify([{ ...base, ...patch }]));
    await assert.rejects(
      () => new DurableCookieJarStore(store, none()).loadAll(),
      (error: unknown) => error instanceof CookieJarStoreError,
      `accepted ${JSON.stringify(patch)}`,
    );
  }
});

suite("a missing field is unreadable rather than defaulted", async (t, store) => {
  const base = must(ROUND_TRIP[0], "the round-trip fixture has a first cookie");
  for (const field of Object.keys(base)) {
    // Widened to a record so a field can be removed by its runtime name: the point is to hand
    // the reader a snapshot that is missing one, which a `StoredCookie` cannot be.
    const entry: Record<string, unknown> = { ...base };
    delete entry[field];
    await writeRaw(store, JSON.stringify([entry]));
    await assert.rejects(
      () => new DurableCookieJarStore(store, none()).loadAll(),
      (error: unknown) => error instanceof CookieJarStoreError,
      `accepted a snapshot with no ${field}`,
    );
  }
});

// The durable byte store's contract, exercised against the host filesystem strawman.
//
// The shape came from the JVM lane after they ran a capability check on a real API-26
// device: atomic rename and both syncs are available at the floor, so atomicity does
// not have to shape the ABI. Streaming is write-only on their reasoning that a
// whole-value write cannot serve "large payloads are not forced into RAM", because the
// bytes parameter *is* the payload in RAM.
//
// Host evidence for the contract. The Android provider is theirs and owes the same
// guarantees against its own storage.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { mkdtempSync, rmSync, readdirSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { AbortController } from "../src/index.ts";
import { HostNodeDurableStore } from "../host/node-runtime.ts";
import { must } from "./harness.ts";
import type { DurableByteStore } from "../src/provider.ts";
import type { AbortSignal } from "../src/index.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const encoder = new TextEncoder();
const decoder = new TextDecoder();
const none = () => new AbortController().signal;

function store(t: TestContext): { store: HostNodeDurableStore; root: string } {
  const root = mkdtempSync(join(tmpdir(), "nts-durable-"));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  return { store: new HostNodeDurableStore({ root }), root };
}

async function put(
  target: DurableByteStore,
  namespace: string,
  key: string,
  text: string,
  signal: AbortSignal = none(),
): Promise<void> {
  const write = await target.write(namespace, key, signal);
  await write.append(encoder.encode(text));
  await write.commit();
}

suite("a committed value reads back whole and by range", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "greeting", "hello durable world");

  assert.equal(
    decoder.decode(await target.read("cache", "greeting", none())),
    "hello durable world",
  );

  // The ranged path is the seam Blob already consumes.
  const source = must(await target.source("cache", "greeting", none()), "the key that was just written has a source");
  assert.equal(source.size, 19);
  const reader = source.open(6, 7);
  const chunk = await reader.read(64);
  assert.equal(decoder.decode(chunk), "durable");
  assert.equal(await reader.read(64), undefined, "the range ends where it was asked to");
  await reader.close();
});

suite("a reader opened before a delete keeps reading", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "doomed", "bytes that outlive their key");

  const source = must(await target.source("cache", "doomed", none()), "the key that was just written has a source");
  assert.equal(source.size, 28);
  const reader = source.open(0, source.size);
  assert.equal(decoder.decode(await reader.read(6)), "bytes ");

  assert.equal(await target.delete("cache", "doomed", none()), true);
  assert.equal(await target.read("cache", "doomed", none()), null, "the key is gone");

  // A descriptor pins what it was opened over -- the same guarantee that makes a
  // replaced value invisible to an open reader, extended to a removed one. Without it
  // nothing can release stored bytes while a reader might still hold them.
  assert.equal(decoder.decode(await reader.read(64)), "that outlive their key");
  assert.equal(await reader.read(64), undefined);
  await reader.close();
});

suite("an absent key is null rather than an error", async (t) => {
  const { store: target } = store(t);
  assert.equal(await target.read("cache", "missing", none()), null);
  assert.equal(await target.source("cache", "missing", none()), null);
  assert.equal(await target.delete("cache", "missing", none()), false);
  assert.deepEqual(await target.list("cache", none()), []);
  assert.equal(await target.size("cache", none()), 0);
});

suite("nothing appended is visible before commit", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "key", "original");

  const write = await target.write("cache", "key", none());
  await write.append(encoder.encode("replacement "));
  await write.append(encoder.encode("in progress"));
  // The whole point of the handle: the key still holds what it held.
  assert.equal(decoder.decode(await target.read("cache", "key", none())), "original");
  assert.deepEqual(
    (await target.list("cache", none())).map((record) => record.key),
    ["key"],
    "an uncommitted write is not a record",
  );

  await write.commit();
  assert.equal(
    decoder.decode(await target.read("cache", "key", none())),
    "replacement in progress",
  );
});

suite("discarding leaves the key holding what it held", async (t) => {
  const { store: target, root } = store(t);
  await put(target, "cache", "key", "original");

  const write = await target.write("cache", "key", none());
  await write.append(encoder.encode("never committed"));
  await write.discard();
  assert.equal(decoder.decode(await target.read("cache", "key", none())), "original");
  // Discarding is idempotent, and does not resurrect anything after a commit.
  await write.discard();
  assert.equal(decoder.decode(await target.read("cache", "key", none())), "original");

  // And it leaves no partial file behind for a later run to trip over.
  const namespaceDirectory = join(root, must(readdirSync(root)[0], "the store made a namespace directory"));
  assert.deepEqual(
    readdirSync(namespaceDirectory).filter((name) => name.startsWith(".partial-")),
    [],
  );
});

suite("cancelling makes no partial value visible", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "key", "original");

  const controller = new AbortController();
  const write = await target.write("cache", "key", controller.signal);
  await write.append(encoder.encode("first half "));
  controller.abort(new Error("caller went away"));

  // The guarantee is not that a write in progress stops immediately -- it is that no
  // partial value becomes visible. The next chunk is where the signal is honoured.
  await assert.rejects(write.append(encoder.encode("second half")));
  await assert.rejects(write.commit());
  assert.equal(
    decoder.decode(await target.read("cache", "key", none())),
    "original",
    "a cancelled write leaves the previous value exactly as it was",
  );
  await write.discard();
});

suite("a crashed write is invisible rather than half-present", async (t) => {
  const { store: target, root } = store(t);
  await put(target, "cache", "key", "original");

  // Simulating a crash: append, then abandon the handle without commit or discard,
  // exactly as a process that died would. The temporary file is still on disk.
  const write = await target.write("cache", "key", none());
  await write.append(encoder.encode("lost work"));
  const namespaceDirectory = join(root, must(readdirSync(root)[0], "the store made a namespace directory"));
  assert.equal(
    readdirSync(namespaceDirectory).some((name) => name.startsWith(".partial-")),
    true,
    "the test must actually leave a partial file, or it proves nothing",
  );

  // A fresh store over the same directory is what a restart looks like.
  const reopened = new HostNodeDurableStore({ root });
  assert.equal(decoder.decode(await reopened.read("cache", "key", none())), "original");
  assert.deepEqual(
    (await reopened.list("cache", none())).map((record) => record.key),
    ["key"],
    "a leftover partial is not a record",
  );
  await write.discard();
});

suite("records carry size and modification time, and namespaces are separate", async (t) => {
  const { store: target, root } = store(t);
  await put(target, "cache", "a", "one");
  await put(target, "cache", "b", "twotwo");
  await put(target, "cookies", "a", "elsewhere");

  const records = (await target.list("cache", none()))
    .slice()
    .sort((x, y) => (x.key < y.key ? -1 : 1));
  assert.deepEqual(
    records.map((record) => [record.key, record.size]),
    [
      ["a", 3],
      ["b", 6],
    ],
  );
  for (const record of records) {
    const path = join(root, Buffer.from("cache").toString("base64url"), Buffer.from(record.key).toString("base64url"));
    assert.equal(record.modifiedMilliseconds, statSync(path).mtimeMs, "the record reports its committed file's timestamp");
  }
  assert.equal(await target.size("cache", none()), 9);
  // One namespace cannot see or count another's keys.
  assert.equal(await target.size("cookies", none()), 9, "a namespace counts only its own");
  assert.equal(decoder.decode(await target.read("cookies", "a", none())), "elsewhere");
});

suite("keys are encoded rather than trusted as paths", async (t) => {
  const { store: target } = store(t);
  // A key that would escape the namespace if it were used as a path segment.
  const hostile = "../../escaped";
  await put(target, "cache", hostile, "contained");
  assert.equal(decoder.decode(await target.read("cache", hostile, none())), "contained");
  assert.deepEqual(
    (await target.list("cache", none())).map((record) => record.key),
    [hostile],
    "the key round-trips exactly, without ever being a path",
  );
});

suite("delete removes a key and a closed store refuses work", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "key", "value");
  assert.equal(await target.delete("cache", "key", none()), true);
  assert.equal(await target.read("cache", "key", none()), null);
  assert.equal(await target.delete("cache", "key", none()), false);

  await target.close();
  await assert.rejects(target.read("cache", "key", none()), /closed/);
  await assert.rejects(target.write("cache", "key", none()), /closed/);
});

suite("a second concurrent write to one key is refused, not queued", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "key", "original");

  const first = await target.write("cache", "key", none());
  await first.append(encoder.encode("mine"));

  // Refused rather than queued. Queueing would turn a caller's mistake into a pause,
  // with the pause as the only evidence it made one.
  await assert.rejects(target.write("cache", "key", none()), /already open/);
  // And the first writer is undisturbed by the attempt.
  await first.commit();
  assert.equal(decoder.decode(await target.read("cache", "key", none())), "mine");

  // Once settled, the key is writable again -- the guard tracks a write, not a key.
  const second = await target.write("cache", "key", none());
  await second.append(encoder.encode("later"));
  await second.commit();
  assert.equal(decoder.decode(await target.read("cache", "key", none())), "later");
});

suite("a discarded or cancelled write releases the key", async (t) => {
  const { store: target } = store(t);
  // Discarding must release, or one abandoned write locks a key for the process.
  const discarded = await target.write("cache", "key", none());
  await discarded.discard();
  const afterDiscard = await target.write("cache", "key", none());
  await afterDiscard.append(encoder.encode("after discard"));
  await afterDiscard.commit();
  assert.equal(decoder.decode(await target.read("cache", "key", none())), "after discard");

  // The same for a cancelled one, which is the path most likely to be abandoned.
  const controller = new AbortController();
  const cancelled = await target.write("cache", "key", controller.signal);
  controller.abort(new Error("gone"));
  await cancelled.discard();
  const afterCancel = await target.write("cache", "key", none());
  await afterCancel.append(encoder.encode("after cancel"));
  await afterCancel.commit();
  assert.equal(decoder.decode(await target.read("cache", "key", none())), "after cancel");
});

suite("two different keys write concurrently without interfering", async (t) => {
  const { store: target } = store(t);
  // Sequential *per key* -- not one write at a time for the whole store.
  const a = await target.write("cache", "a", none());
  const b = await target.write("cache", "b", none());
  await a.append(encoder.encode("first"));
  await b.append(encoder.encode("second"));
  // The same key name in another namespace is a different key, and this is opened
  // while `cache/a` is still unsettled -- committing first would let a guard that
  // ignored the namespace pass.
  const other = await target.write("cookies", "a", none());
  await other.append(encoder.encode("elsewhere"));

  await b.commit();
  await a.commit();
  await other.commit();
  assert.equal(decoder.decode(await target.read("cache", "a", none())), "first");
  assert.equal(decoder.decode(await target.read("cache", "b", none())), "second");
  assert.equal(decoder.decode(await target.read("cookies", "a", none())), "elsewhere");
});

suite("a source reads the value it was opened over, or fails", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "key", "the original value");

  const source = must(await target.source("cache", "key", none()), "the key that was just written has a source");
  assert.equal(source.size, 18);

  // The value is replaced after the source exists but before it is read. Blob shares
  // *immutable* stored ranges, so a source that silently started reading the new value
  // would break that guarantee for every Blob built on this store.
  await put(target, "cache", "key", "a completely different and longer value");

  const reader = source.open(0, 18);
  let bytes: Uint8Array | undefined = undefined;
  let failure: unknown = null;
  try {
    bytes = await reader.read(64);
  } catch (error) {
    failure = error;
  }
  await reader.close();

  if (failure !== null) {
    // Refusing is the correct outcome: the value it was opened over is gone.
    assert.match(String(failure), /replaced|no longer/i);
  } else {
    // If it read anything, it must be the value the source was opened over -- never a
    // prefix of a different one, which is what clamping to the new size would give.
    // The read succeeded, so it returned bytes; the branch it is in is the proof.
    const read = must(bytes, "a read that did not fail returned a chunk");
    assert.equal(decoder.decode(read), "the original value".slice(0, read.length));
    assert.ok(read.length > 0);
  }
});

suite("a reader opened before a replacement keeps reading the original", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "key", "the original value");
  const source = must(await target.source("cache", "key", none()), "the key that was just written has a source");
  const reader = source.open(0, 18);
  // Reading once pins the value; the descriptor outlives the rename that replaces it.
  const first = await reader.read(4);
  assert.equal(decoder.decode(first), "the ");

  await put(target, "cache", "key", "a completely different and longer value");

  // The rest of the *original* value, not the rest of the new one. This is what Blob
  // means by an immutable stored range, and it is the reason the descriptor is opened
  // rather than the path re-resolved.
  const parts: Uint8Array[] = [must(first, "the reader returned its first chunk")];
  while (true) {
    const chunk = await reader.read(64);
    if (chunk === undefined) break;
    parts.push(chunk);
  }
  await reader.close();
  assert.equal(Buffer.concat(parts.map((p: Uint8Array) => Buffer.from(p))).toString(), "the original value");
});

suite("two readers over one source are independent", async (t) => {
  const { store: target } = store(t);
  await put(target, "cache", "key", "abcdefghij");
  const source = must(await target.source("cache", "key", none()), "the key that was just written has a source");

  const left = source.open(0, 5);
  const right = source.open(5, 5);
  // Interleaved deliberately: a shared file offset would make these steal from each
  // other, and reading them one after the other would hide it.
  const leftFirst = await left.read(2);
  const rightFirst = await right.read(2);
  const leftRest = await left.read(64);
  const rightRest = await right.read(64);
  assert.equal(decoder.decode(leftFirst) + decoder.decode(leftRest), "abcde");
  assert.equal(decoder.decode(rightFirst) + decoder.decode(rightRest), "fghij");

  // Each range ends where it was asked to, and never returns an empty chunk.
  assert.equal(await left.read(64), undefined);
  assert.equal(await right.read(64), undefined);
  await left.close();
  await right.close();
  // Closing twice is safe, as is closing a reader that was never read.
  await left.close();
  const unread = source.open(0, 3);
  await unread.close();
});

// Interim (1xx) responses were counted and discarded, so `103 Early Hints` -- the one
// interim response a client is meant to act on -- could never be seen. These tests use
// a raw socket server, because Node's HTTP server will not emit a malformed or
// unusual interim sequence on request.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { createServer } from "node:net";

import { AbortController } from "../src/index.ts";
import { Http1Transport } from "../src/http1/transport.ts";
import {
  HostNodeSocketConnector,
  createHostNodePrimitives,
  hostNodeURLs,
} from "../host/node-primitives.ts";
import type { Socket } from "node:net";
import { portOf } from "./harness.ts";
import type {
  TransportInformationalResponse,
  TransportRequest,
} from "../src/fetch/transport.ts";
import type { ReadableStream } from "../src/streams/readable.ts";
import { must } from "./harness.ts";
import type { HeaderEntry } from "../src/fetch/headers.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const CRLF = String.fromCharCode(13, 10);

/** A server that writes exactly the response text it is given. */
async function rawServer(t: TestContext, responseText: string): Promise<number> {
  const sockets = new Set<Socket>();
  const server = createServer((socket) => {
    sockets.add(socket);
    socket.on("error", () => {});
    socket.on("close", () => sockets.delete(socket));
    let head = "";
    socket.on("data", (chunk) => {
      head += chunk.toString("latin1");
      if (!head.includes(CRLF + CRLF)) return;
      socket.write(responseText);
    });
  });
  server.listen(0, "127.0.0.1");
  await new Promise<void>((resolve) => server.once("listening", () => resolve()));
  t.after(() => {
    for (const socket of sockets) socket.destroy();
    return new Promise<void>((resolve) => server.close(() => resolve()));
  });
  return portOf(server);
}

function transportRequest(url: string, overrides: Partial<TransportRequest> = {}): TransportRequest {
  return {
    url: hostNodeURLs.parse(url),
    method: "GET",
    headers: [],
    body: null,
    bodyLength: null,
    signal: new AbortController().signal,
    ...overrides,
  };
}

async function consume(stream: ReadableStream<Uint8Array> | null): Promise<string> {
  if (stream === null) return "";
  const reader = stream.getReader();
  const parts = [];
  try {
    while (true) {
      const result = await reader.read();
      if (result.done) break;
      parts.push(Buffer.from(result.value));
    }
  } finally {
    reader.releaseLock();
  }
  return Buffer.concat(parts).toString();
}

function makeTransport(t: TestContext, options: Record<string, unknown> = {}): Http1Transport {
  const primitives = createHostNodePrimitives();
  const transport = new Http1Transport(
    new HostNodeSocketConnector(),
    primitives.scheduler,
    options,
  );
  t.after(() => transport.close());
  return transport;
}

suite("early hints reach the caller in order, before the final response", async (t) => {
  const port = await rawServer(
    t,
    "HTTP/1.1 103 Early Hints" +
      CRLF +
      "link: </style.css>; rel=preload; as=style" +
      CRLF +
      "link: </app.js>; rel=preload; as=script" +
      CRLF +
      CRLF +
      "HTTP/1.1 103 Early Hints" +
      CRLF +
      "link: </late.png>; rel=preload" +
      CRLF +
      CRLF +
      "HTTP/1.1 200 OK" +
      CRLF +
      "content-length: 4" +
      CRLF +
      "connection: close" +
      CRLF +
      CRLF +
      "done",
  );
  const transport = makeTransport(t);
  const seen: TransportInformationalResponse[] = [];
  const response = await transport.dispatch(
    transportRequest(`http://127.0.0.1:${port}/`, {
      onInformational: (interim: TransportInformationalResponse) => seen.push(interim),
    }),
  );

  // Both hints arrived, in order, before the final response was returned.
  assert.equal(seen.length, 2);
  assert.deepEqual(
    seen.map((interim: TransportInformationalResponse) => interim.status),
    [103, 103],
  );
  assert.deepEqual(must(seen[0], "the observer saw that many interim responses").headers, [
    ["link", "</style.css>; rel=preload; as=style"],
    ["link", "</app.js>; rel=preload; as=script"],
  ]);
  assert.deepEqual(must(seen[1], "the observer saw that many interim responses").headers, [["link", "</late.png>; rel=preload"]]);

  // And the final response is unaffected by having been preceded by them.
  assert.equal(response.status, 200);
  assert.equal(await consume(response.body), "done");
});

