    "HTTP/1.1 200 OK" +
      CRLF +
      "content-length: 2" +
      CRLF +
      "connection: close" +
      CRLF +
      CRLF +
      "ok",
  );
  const transport = makeTransport(t);
  const seen: TransportInformationalResponse[] = [];
  const response = await transport.dispatch(
    transportRequest(`http://127.0.0.1:${port}/`, {
