    spki: "MIGbMBAGByqGSM49AgEGBSuBBAAjA4GGAAQBiUVQ0HhZMuAOqiO2lPIT+MMSH4bcl6BOWnFn205bzTcRI9RuRdtrXVNwp/IPtjMVXTj/oW0r12HcrEdLmi9QI6QASTEByWLNTS/d94IoXmRYQTnC+RtH+H/4I1TWYw90aiig2yV0G1s0qCgAiyKswj+ST6r71NM/gepmlW3+qiv9/PU=",
    pkcs8: ""
  }
};

function jwk(curve: CryptoNamedCurve, key: EcHexKey): EcFixturePrivateJwk {
  return {
    kty: "EC", crv: curve,
    x: Buffer.from(key.x, "hex").toString("base64url"),
    y: Buffer.from(key.y, "hex").toString("base64url"),
    d: Buffer.from(key.d, "hex").toString("base64url"),
  };
}

export function ecPrivateJwk(curve: CryptoNamedCurve = "P-256"): EcFixturePrivateJwk {
  return jwk(curve, fixtures[curve]);
}

export function ecPublicJwk(curve: CryptoNamedCurve = "P-256"): EcFixturePublicJwk {
  const { kty, crv, x, y } = ecPrivateJwk(curve);
  return { kty, crv, x, y };
}

export function ecSpki(curve: CryptoNamedCurve = "P-256"): Uint8Array {
  return new Uint8Array(Buffer.from(fixtures[curve].spki, "base64"));
}

export function ecPkcs8(curve: CryptoNamedCurve = "P-256"): Uint8Array {
  return new Uint8Array(Buffer.from(fixtures[curve].pkcs8, "base64"));
}

export function ecRawPublic(curve: CryptoNamedCurve = "P-256"): Uint8Array {
  return new Uint8Array(Buffer.from("04" + fixtures[curve].x + fixtures[curve].y, "hex"));
}

export function ecOrder(curve: CryptoNamedCurve = "P-256"): Uint8Array {
  return new Uint8Array(Buffer.from(fixtures[curve].order, "hex"));
}

export function ecdsaMessage(): Uint8Array {
  return new Uint8Array([0x73, 0x61, 0x6d, 0x70, 0x6c, 0x65]);
}

export function ecdsaSignature(curve: CryptoNamedCurve = "P-256", hash: CryptoDigestName = "SHA-256"): Uint8Array {
  const signature = fixtures[curve].signatures[hash];
  if (signature === undefined) throw new TypeError("RFC 6979 does not contain this hash fixture");
  return new Uint8Array(Buffer.from(signature, "hex"));
}

export function ecdhPrivateJwk(curve: CryptoNamedCurve, side: "initiator" | "responder"): EcFixturePrivateJwk {
  return jwk(curve, fixtures[curve][side]);
}

export function ecdhPublicJwk(curve: CryptoNamedCurve, side: "initiator" | "responder"): EcFixturePublicJwk {
  const { kty, crv, x, y } = ecdhPrivateJwk(curve, side);
  return { kty, crv, x, y };
}

export function ecdhSecret(curve: CryptoNamedCurve): Uint8Array {
  return new Uint8Array(Buffer.from(fixtures[curve].secret, "hex"));
}

import assert from "node:assert/strict";
import test from "node:test";
import { TextDecoder, TextEncoder } from "../src/core/encoding.ts";

// Web IDL §3.7.6: check the operation's receiver before overload resolution
// converts its arguments. Encoding §7.2 and §7.4 define the two operations.
test("TextEncoder.encodeInto checks its receiver before source conversion", () => {
  const observed: string[] = [];
  const encodeInto = TextEncoder.prototype.encodeInto as (
    this: unknown,
    source: unknown,
    destination: Uint8Array,
  ) => unknown;
  const destination = new Uint8Array(1);
  assert.throws(() => encodeInto.call({}, {
    toString() {
      observed.push("source");
      return "x";
    },
  }, destination), TypeError);
  assert.deepEqual(observed, []);
  assert.deepEqual(destination, new Uint8Array(1));
});

test("TextDecoder.decode checks its receiver before reading stream options", () => {
  const observed: string[] = [];
  const decode = TextDecoder.prototype.decode as (
    this: unknown,
    input: Uint8Array,
    options: { readonly stream: boolean },
  ) => string;
  assert.throws(() => decode.call({}, Uint8Array.of(0x61), {
    get stream() {
      observed.push("stream");
      return true;
    },
  }), TypeError);
  assert.deepEqual(observed, []);
});

test("TextEncoder.encode checks its receiver before string conversion", () => {
  let converted = false;
  const encode = TextEncoder.prototype.encode as (this: unknown, input: unknown) => Uint8Array;
  assert.throws(() => encode.call({}, {
    toString() {
      converted = true;
      return "x";
    },
  }), TypeError);
  assert.equal(converted, false);
});

test("encoding operations accept genuine subclass receivers", () => {
  class Encoder extends TextEncoder {}
  class Decoder extends TextDecoder {}
  const destination = new Uint8Array(4);
  assert.deepEqual(new Encoder().encodeInto("\ud83d\udc99", destination), { read: 2, written: 4 });
  assert.equal(new Decoder().decode(destination), "\ud83d\udc99");
});

// Web IDL §3.2.26 converts BufferSource without reading its bytes. Encoding
// §7.2 takes the byte copy only after converting the options dictionary.
test("TextDecoder treats a detached DataView as an empty byte sequence", () => {
  const buffer = Uint8Array.of(0x61).buffer;
  const view = new DataView(buffer);
  buffer.transfer();
  let optionsRead = false;
  assert.equal(new TextDecoder().decode(view, {
    get stream() {
      optionsRead = true;
      return false;
    },
  }), "");
  assert.equal(optionsRead, true);
});

test("TextDecoder reads the bytes after converting stream options", () => {
  const bytes = Uint8Array.of(0x61);
  assert.equal(new TextDecoder().decode(bytes, {
    get stream() {
      bytes[0] = 0x62;
      return false;
    },
  }), "b");
});

test("TextDecoder accepts a DataView detached during option conversion", () => {
  const buffer = Uint8Array.of(0x61).buffer;
  const view = new DataView(buffer);
  assert.equal(new TextDecoder().decode(view, {
    get stream() {
      buffer.transfer();
      return false;
    },
  }), "");
});

test("TextDecoder rejects resizable buffer inputs before options conversion", () => {
  const inputs = [
    new ArrayBuffer(2, { maxByteLength: 4 }),
    new SharedArrayBuffer(2, { maxByteLength: 4 }),
    new Uint8Array(new ArrayBuffer(2, { maxByteLength: 4 })),
    new DataView(new ArrayBuffer(2, { maxByteLength: 4 })),
    new Uint8Array(new SharedArrayBuffer(2, { maxByteLength: 4 })),
    new DataView(new SharedArrayBuffer(2, { maxByteLength: 4 })),
  ];
  for (const input of inputs) {
    let optionsRead = false;
    assert.throws(() => new TextDecoder().decode(input, {
      get stream() {
        optionsRead = true;
        return false;
      },
    }), TypeError);
    assert.equal(optionsRead, false);
  }
});

test("TextEncoder.encodeInto rejects resizable destinations after source conversion", () => {
  for (const buffer of [
    new ArrayBuffer(2, { maxByteLength: 4 }),
    new SharedArrayBuffer(2, { maxByteLength: 4 }),
  ]) {
    let converted = false;
    const encoder = new TextEncoder();
    const encodeInto = encoder.encodeInto as (source: unknown, destination: Uint8Array) => unknown;
    assert.throws(() => encodeInto.call(encoder, {
      toString() {
        converted = true;
        return "a";
      },
    }, new Uint8Array(buffer)), TypeError);
    assert.equal(converted, true);
  }
});

test("fixed shared buffers remain valid at both encoding boundaries", () => {
  const buffer = new SharedArrayBuffer(4);
  const bytes = new Uint8Array(buffer);
  assert.deepEqual(new TextEncoder().encodeInto("\ud83d\udc99", bytes), { read: 2, written: 4 });
  assert.equal(new TextDecoder().decode(new DataView(buffer)), "\ud83d\udc99");
});

test("ordinary decoder properties cannot reset a pending UTF-8 sequence", () => {
  const decoder = new TextDecoder();
  assert.equal(decoder.decode(Uint8Array.of(0xc2), { stream: true }), "");
  Object.assign(decoder, { needed: 0, seen: 0, code: 0, doNotFlush: false });
  assert.equal(decoder.decode(Uint8Array.of(0xa2)), "\u00a2");
});

test("ordinary decoder properties cannot change UTF-16 or BOM state", () => {
  const decoder = new TextDecoder("utf-16le");
  assert.equal(decoder.decode(Uint8Array.of(0xff), { stream: true }), "");
  Object.assign(decoder, { pendingByte: 0x61, pendingLead: 0xd800, bomSeen: true });
  assert.equal(decoder.decode(Uint8Array.of(0xfe, 0x61, 0)), "a");
});

test("encoding classes retain their ordinary string tags", () => {
  assert.equal(Object.prototype.toString.call(new TextEncoder()), "[object TextEncoder]");
  assert.equal(Object.prototype.toString.call(new TextDecoder()), "[object TextDecoder]");
});

// Encoding §7.2 preserves the I/O queue across streaming calls, including a
// call that throws. §8.1.1 restores a rejected continuation; §14.2.1 restores
// both bytes of a non-trailing UTF-16 code unit after a leading surrogate.
test("a fatal streaming UTF-8 error preserves unprocessed bytes", () => {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  assert.throws(() => decoder.decode(Uint8Array.of(0xff, 0x61), { stream: true }), TypeError);
  assert.equal(decoder.decode(), "a");
});

test("a fatal UTF-8 continuation error restores the offending byte", () => {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  assert.throws(() => decoder.decode(Uint8Array.of(0xc2, 0x61, 0x62), { stream: true }), TypeError);
  assert.equal(decoder.decode(), "ab");
});

test("successive fatal streaming errors consume one invalid leading byte each", () => {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  assert.throws(() => decoder.decode(Uint8Array.of(0xff, 0xff, 0x61), { stream: true }), TypeError);
  assert.throws(() => decoder.decode(undefined, { stream: true }), TypeError);
  assert.equal(decoder.decode(), "a");
});

test("pending bytes after a fatal streaming error are a copy of the input", () => {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  const bytes = Uint8Array.of(0xff, 0x61);
  assert.throws(() => decoder.decode(bytes, { stream: true }), TypeError);
  bytes[1] = 0x62;
  assert.equal(decoder.decode(), "a");
});

test("new input is appended after a fatal streaming error's remaining queue", () => {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  assert.throws(() => decoder.decode(Uint8Array.of(0xff, 0x61), { stream: true }), TypeError);
  assert.equal(decoder.decode(Uint8Array.of(0x62)), "ab");
});

for (const encoding of ["utf-16le", "utf-16be"]) {
  const bytes = (units: readonly number[]): Uint8Array => {
    const output = new Uint8Array(units.length * 2);
    for (let index = 0; index < units.length; index++) {
      const unit = units[index]!;
      output[index * 2] = encoding === "utf-16le" ? unit & 255 : unit >> 8;
      output[index * 2 + 1] = encoding === "utf-16le" ? unit >> 8 : unit & 255;
    }
    return output;
  };

  test(`a fatal ${encoding} leading-surrogate error restores a unit split across calls`, () => {
    const decoder = new TextDecoder(encoding, { fatal: true });
    const input = bytes([0xd800, 0x61, 0x62]);
    assert.equal(decoder.decode(input.subarray(0, 3), { stream: true }), "");
    assert.throws(() => decoder.decode(input.subarray(3), { stream: true }), TypeError);
    assert.equal(decoder.decode(), "ab");
  });

  test(`a fatal ${encoding} trailing-surrogate error preserves following units`, () => {
    const decoder = new TextDecoder(encoding, { fatal: true });
    assert.throws(() => decoder.decode(bytes([0xdc00, 0x61]), { stream: true }), TypeError);
    assert.equal(decoder.decode(), "a");
  });

  test(`${encoding} emits one replacement for a lead surrogate and odd byte at EOF`, () => {
    const decoder = new TextDecoder(encoding);
    const input = bytes([0xd800, 0x61]).subarray(0, 3);
    assert.equal(decoder.decode(input), "\ufffd");
    assert.equal(decoder.decode(), "");
  });
}

test("a fatal streaming call does not serialize its discarded output or mark a BOM seen", () => {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  assert.throws(() => decoder.decode(Uint8Array.of(0x61, 0xff, 0xef, 0xbb, 0xbf, 0x62), {
    stream: true,
  }), TypeError);
  assert.equal(decoder.decode(), "b");
});

test("a prior successful streaming call's BOM state survives a later fatal error", () => {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  assert.equal(decoder.decode(Uint8Array.of(0x61), { stream: true }), "a");
  assert.throws(() => decoder.decode(Uint8Array.of(0xff, 0xef, 0xbb, 0xbf, 0x62), {
    stream: true,
  }), TypeError);
  assert.equal(decoder.decode(), "\ufeffb");
});

test("a non-streaming fatal call resets its queue on the next decode", () => {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  assert.throws(() => decoder.decode(Uint8Array.of(0xff, 0x61)), TypeError);
  assert.equal(decoder.decode(Uint8Array.of(0x62)), "b");
});

import "../host/environment-shim.ts";
import assert from "node:assert/strict";
import test from "node:test";
import { TextDecoderStream, TextEncoderStream } from "../src/core/encoding-streams.ts";
import type { AllowSharedBufferSource, TextDecoderOptions } from "../src/core/encoding.ts";
import type { ReadableStream } from "../src/streams/readable.ts";

async function collect<T>(readable: ReadableStream<T>): Promise<T[]> {
  const reader = readable.getReader();
  const output: T[] = [];
  try {
    for (;;) {
      const chunk = await reader.read();
      if (chunk.done) return output;
      output.push(chunk.value as T);
    }
  } finally {
    reader.releaseLock();
  }
}

async function encodeChunks(chunks: readonly unknown[]): Promise<number[][]> {
  const stream = new TextEncoderStream();
  const writer = stream.writable.getWriter();
  const reading = collect(stream.readable);
  const writing = (async (): Promise<void> => {
    try {
      for (const chunk of chunks) await writer.write(chunk as string);
      await writer.close();
    } finally {
      writer.releaseLock();
    }
  })();
  const [output] = await Promise.all([reading, writing]);
  return output.map((chunk) => Array.from(chunk));
}

// Encoding #encode-and-enqueue-a-chunk; Web IDL #es-DOMString.
test("TextEncoderStream rejects Symbol chunks instead of describing them", async () => {
  await assert.rejects(encodeChunks([Symbol("chunk")]), TypeError);
});

test("TextEncoderStream converts a chunk once with the string hint", async () => {
  const hints: string[] = [];
  const chunk = {
    [Symbol.toPrimitive](hint: string): string {
      hints.push(hint);
      return "A";
    },
  };
  assert.deepEqual(await encodeChunks([chunk]), [[0x41]]);
  assert.deepEqual(hints, ["string"]);
});

function constructDecoder(label: unknown, options: unknown): TextDecoderStream {
  return new TextDecoderStream(label as string, options as TextDecoderOptions);
}

// Encoding #dom-textdecoderstream; Web IDL #es-operations and #es-dictionary.
test("TextDecoderStream converts the label before rejecting a primitive dictionary", () => {
  const order: string[] = [];
  const label = { toString() { order.push("label"); return "utf-8"; } };
  assert.throws(() => constructDecoder(label, 1), TypeError);
  assert.deepEqual(order, ["label"]);
});

test("TextDecoderStream preserves label conversion failure before options conversion", () => {
  const failure = {};
  const label = { toString(): never { throw failure; } };
  assert.throws(() => constructDecoder(label, false), (error: unknown) => error === failure);
});

test("TextDecoderStream reads and converts its dictionary once in member order", () => {
  const order: string[] = [];
  const label = { toString() { order.push("label"); return "UTF-16BE"; } };
  const options = {
    get fatal() { order.push("fatal"); return 1; },
    get ignoreBOM() { order.push("ignoreBOM"); return 0; },
  };
  const decoder = constructDecoder(label, options);
  assert.deepEqual(order, ["label", "fatal", "ignoreBOM"]);
  assert.equal(decoder.encoding, "utf-16be");
  assert.equal(decoder.fatal, true);
  assert.equal(decoder.ignoreBOM, false);
});

test("TextDecoderStream finishes dictionary conversion before label lookup", () => {
  const failure = {};
  const options = { get fatal(): never { throw failure; } };
  assert.throws(() => new TextDecoderStream("not-an-encoding", options),
    (error: unknown) => error === failure);
});

async function decodeChunks(
  chunks: readonly unknown[],
  label = "utf-8",
  options?: TextDecoderOptions,
): Promise<string[]> {
  const stream = new TextDecoderStream(label, options);
  const writer = stream.writable.getWriter();
  const reading = collect(stream.readable);
  const writing = (async (): Promise<void> => {
    try {
      for (const chunk of chunks) await writer.write(chunk as AllowSharedBufferSource);
      await writer.close();
    } finally {
      writer.releaseLock();
    }
  })();
  const [output] = await Promise.all([reading, writing]);
  return output;
}

test("encoding streams expose plain tags and branded attributes", () => {
  const encoder = new TextEncoderStream();
  const decoder = new TextDecoderStream();
  assert.equal(Object.prototype.toString.call(encoder), "[object TextEncoderStream]");
  assert.equal(Object.prototype.toString.call(decoder), "[object TextDecoderStream]");
  assert.equal(encoder.encoding, "utf-8");
  assert.equal(decoder.encoding, "utf-8");
  assert.equal(decoder.fatal, false);
  assert.equal(decoder.ignoreBOM, false);
  assert.equal(encoder.readable, encoder.readable);
  assert.equal(encoder.writable, encoder.writable);
  assert.equal(decoder.readable, decoder.readable);
  assert.equal(decoder.writable, decoder.writable);
  assert.throws(() => TextEncoderStream.prototype.encoding, TypeError);
  assert.throws(() => TextEncoderStream.prototype.readable, TypeError);
  assert.throws(() => TextEncoderStream.prototype.writable, TypeError);
  assert.throws(() => TextDecoderStream.prototype.encoding, TypeError);
  assert.throws(() => TextDecoderStream.prototype.fatal, TypeError);
  assert.throws(() => TextDecoderStream.prototype.ignoreBOM, TypeError);
  assert.throws(() => TextDecoderStream.prototype.readable, TypeError);
  assert.throws(() => TextDecoderStream.prototype.writable, TypeError);
});

// Encoding #convert-code-unit-to-scalar-value and #encode-and-flush.
test("TextEncoderStream joins a split surrogate pair across empty chunks", async () => {
  assert.deepEqual(await encodeChunks(["", "A\ud83d", "", "\ude00B", ""]), [
    [0x41], [0xf0, 0x9f, 0x98, 0x80, 0x42],
  ]);
});

test("TextEncoderStream flushes a final high surrogate exactly once", async () => {
  assert.deepEqual(await encodeChunks(["A\ud800", ""]), [[0x41], [0xef, 0xbf, 0xbd]]);
  assert.deepEqual(await encodeChunks(["", ""]), []);
});

test("TextEncoderStream replaces unpaired surrogates without swallowing the next unit", async () => {
  assert.deepEqual(await encodeChunks(["\ud800", "\ud801", "A\udc00"]), [
    [0xef, 0xbf, 0xbd],
    [0xef, 0xbf, 0xbd, 0x41, 0xef, 0xbf, 0xbd],
  ]);
});

test("TextEncoderStream retains arbitrary string-conversion failures", async () => {
  const failure = {};
  await assert.rejects(encodeChunks([{ toString(): never { throw failure; } }]),
    (error: unknown) => error === failure);
});

test("TextEncoderStream stringifies null, undefined and primitive values", async () => {
  const chunks = await encodeChunks([null, undefined, false, 42, 12n]);
  const output = chunks.map((bytes) => String.fromCharCode(...bytes));
  assert.deepEqual(output, ["null", "undefined", "false", "42", "12"]);
});

test("TextEncoderStream waits for readable demand before converting a chunk", async () => {
  const stream = new TextEncoderStream();
  const writer = stream.writable.getWriter();
  let calls = 0;
  const chunk = { toString() { calls++; return "A"; } };
  const writing = writer.write(chunk as unknown as string);
  await Promise.resolve();
  await Promise.resolve();
  assert.equal(calls, 0);
  const reader = stream.readable.getReader();
  const first = await reader.read();
  await writing;
  assert.equal(calls, 1);
  assert.deepEqual(Array.from(first.value as Uint8Array), [0x41]);
  await writer.close();
  assert.equal((await reader.read()).done, true);
  reader.releaseLock();
  writer.releaseLock();
});

// Encoding #decode-and-enqueue-a-chunk, #flush-and-enqueue and #serialize-i-o-queue.
test("TextDecoderStream buffers split UTF-8 input without emitting empty strings", async () => {
  assert.deepEqual(await decodeChunks([
    new Uint8Array(), new Uint8Array([0xf0]), new Uint8Array([0x9f, 0x98]),
    new Uint8Array(), new Uint8Array([0x80, 0x41]), new Uint8Array(),
  ]), ["😀A"]);
});

test("TextDecoderStream strips only the first complete BOM", async () => {
  const chunks = [
    new Uint8Array([0xef]), new Uint8Array(), new Uint8Array([0xbb]),
    new Uint8Array([0xbf]), new Uint8Array([0x41]), new Uint8Array([0xef, 0xbb, 0xbf]),
  ];
  assert.deepEqual(await decodeChunks(chunks), ["A", "\ufeff"]);
  assert.deepEqual(await decodeChunks(chunks, "utf-8", { ignoreBOM: true }),
    ["\ufeff", "A", "\ufeff"]);
});

test("TextDecoderStream never strips a BOM after a replacement character", async () => {
  assert.deepEqual(await decodeChunks([
    new Uint8Array([0xff]), new Uint8Array([0xef, 0xbb, 0xbf]),
  ]), ["\ufffd", "\ufeff"]);
});

test("TextDecoderStream restores an invalid continuation as the next input byte", async () => {
  assert.deepEqual(await decodeChunks([
    new Uint8Array([0xe2]), new Uint8Array([0x41, 0xc0, 0xaf, 0xe2, 0x82]),
  ]), ["\ufffdA\ufffd\ufffd", "\ufffd"]);
});

for (const [label, bytes] of [
  ["utf-16le", [0xff, 0xfe, 0x3d, 0xd8, 0x00, 0xde, 0x41, 0x00]],
  ["utf-16be", [0xfe, 0xff, 0xd8, 0x3d, 0xde, 0x00, 0x00, 0x41]],
] as const) {
  test(`TextDecoderStream retains ${label} bytes and surrogate state across chunks`, async () => {
    assert.deepEqual(await decodeChunks(bytes.map((byte) => new Uint8Array([byte])), label),
      ["😀", "A"]);
    assert.deepEqual(await decodeChunks(bytes.map((byte) => new Uint8Array([byte])), label,
      { ignoreBOM: true }), ["\ufeff", "😀", "A"]);
  });
}

test("TextDecoderStream uses UTF-16 label endianness instead of sniffing a BOM", async () => {
  assert.deepEqual(await decodeChunks([new Uint8Array([0xfe, 0xff, 0x00, 0x41])], "utf-16"),
    ["\ufffe\u4100"]);
});

test("TextDecoderStream decodes only the bytes inside a view", async () => {
  const backing = new Uint8Array([0xff, 0x41, 0x42, 0xff]);
  assert.deepEqual(await decodeChunks([new DataView(backing.buffer, 1, 2)]), ["AB"]);
  assert.deepEqual(await decodeChunks([backing.subarray(1, 3)]), ["AB"]);
});

test("TextDecoderStream refuses every non-buffer-source chunk", async () => {
  for (const chunk of [undefined, null, 0, "A", {}, [0x41], Symbol("bytes")]) {
    await assert.rejects(decodeChunks([chunk]), TypeError);
  }
});

test("TextDecoderStream errors both stream sides with the same fatal-chunk error", async () => {
  const stream = new TextDecoderStream("utf-8", { fatal: true });
  const writer = stream.writable.getWriter();
  const reader = stream.readable.getReader();
  const results = await Promise.allSettled([
    reader.read(), reader.closed, writer.closed, writer.write(new Uint8Array([0x41, 0xff])),
  ]);
  let failure: unknown;
  for (const result of results) {
    assert.equal(result.status, "rejected");
    if (result.status !== "rejected") continue;
    assert.ok(result.reason instanceof TypeError);
    if (failure === undefined) failure = result.reason;
    assert.equal(result.reason, failure);
  }
  reader.releaseLock();
  writer.releaseLock();
});

for (const [label, bytes] of [
  ["utf-8", [0xe2, 0x82]],
  ["utf-16le", [0x00, 0xd8, 0x41]],
  ["utf-16be", [0xd8, 0x00, 0x41]],
] as const) {
  test(`TextDecoderStream flushes incomplete ${label} input with the chosen error policy`, async () => {
    assert.deepEqual(await decodeChunks([new Uint8Array(bytes)], label), ["\ufffd"]);
    await assert.rejects(decodeChunks([new Uint8Array(bytes)], label, { fatal: true }), TypeError);
  });
}

// The error taxonomy is a compatibility contract.
//
// Consumers switch on `error.name`, and two dispatch policies switch on whether an
// error is a `TransportError`: retry only retries typed transport failures, and only
// typed transport failures reduce a balanced upstream's health. Both are load-bearing
// and neither was asserted anywhere, so a class added to the wrong base — or renamed —
// would change retry and routing behaviour silently.
//
// This pins the taxonomy as it is. It is not a claim that every classification is the
// one we would choose today; see the note on proxy errors below.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import * as api from "../src/index.ts";
import { DOMException } from "../src/core/errors.ts";
import { memberNamed } from "./harness.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

/**
 * Every error this runtime exports, how to build one, and whether it is a typed
 * transport failure.
 *
 * `transport: true` is not documentation. It is exactly the set that `RetryInterceptor`
 * will retry and that reduces a `BalancedPool` upstream's health, so moving an entry
 * across that column changes what the network does.
 */
/**
 * How to construct one error, and whether it belongs to the transport set.
 *
 * `build` takes the constructor rather than closing over it, because the test looks each one
 * up by name off the module namespace -- which is the thing being checked.
 */
interface TaxonomyEntry {
  readonly build: (constructor: new (...args: readonly unknown[]) => Error) => Error;
  readonly transport: boolean;
}

const TAXONOMY: Readonly<Record<string, TaxonomyEntry>> = {
  AgentOriginLimitError: { build: (C: new (...args: readonly unknown[]) => Error) => new C(1), transport: false },
  AgentPendingLimitError: { build: (C: new (...args: readonly unknown[]) => Error) => new C(1), transport: false },
  BalancedPoolLimitError: { build: (C: new (...args: readonly unknown[]) => Error) => new C(1), transport: false },
  BalancedPoolMissingUpstreamError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("origin"), transport: false },
  // Not a transport failure, and the classification is the whole decision. A corrupt or
  // unreadable stored snapshot fails the same way every time it is read, so retrying it
  // spends attempts to reach an identical answer -- and letting it reduce an upstream's
  // health would blame a server for a local storage fault it never saw.
  CookieJarStoreError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("unreadable"), transport: false },
  DeduplicationBufferError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("limit"), transport: false },
  DnsConnectionError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("host", []), transport: true },
  DnsLookupLimitError: { build: (C: new (...args: readonly unknown[]) => Error) => new C(1), transport: false },
  DnsNoAddressError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("host"), transport: true },
  MockNotMatchedError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("no match"), transport: false },
  ProtocolMismatchError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("h2", "http/1.1"), transport: false },
  ProxyConfigurationError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("bad"), transport: false },
  ProxyResponseError: { build: (C: new (...args: readonly unknown[]) => Error) => new C(502, []), transport: false },
  QuotaExceededError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("quota"), transport: false },
  ResponseError: {
    build: (C: new (...args: readonly unknown[]) => Error) => new C({ status: 500, statusText: "Server Error", headers: [] }, null),
    transport: false,
  },
  ResponseExceededMaxSizeError: { build: (C: new (...args: readonly unknown[]) => Error) => new C(1, 2), transport: false },
  RetryExhaustedError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("exhausted"), transport: false },
  SnapshotNotFoundError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("key"), transport: false },
  Socks5ProxyError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("refused"), transport: false },
  TransportError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("other", "failed"), transport: true },
  UnreplayableRequestError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("body"), transport: false },
  WebSocketError: { build: (C: new (...args: readonly unknown[]) => Error) => new C("closed"), transport: false },
};

function exportedErrorNames() {
  return Object.keys(api)
    .filter((name) => /Error$/.test(name))
    .sort();
}

suite("the set of exported errors is exactly the taxonomy", () => {
  // Adding an error class is a decision about retry and routing, so it fails here
  // until it is made. Removing one is a compatibility break and fails here too.
  assert.deepEqual(exportedErrorNames(), Object.keys(TAXONOMY).sort());
});

/** The error `name` denotes, built through its taxonomy entry. */
function errorNamed(name: string): Error {
  const entry = TAXONOMY[name];
  assert.ok(entry !== undefined, `${name} is not in the taxonomy`);
  const constructor = memberNamed(api, name);
  assert.equal(typeof constructor, "function", `${name} must be exported as a class`);
  return entry.build(constructor as new (...args: readonly unknown[]) => Error);
}

suite("every error names itself and is an Error", () => {
  const seen = new Set();
  for (const [name, entry] of Object.entries(TAXONOMY)) {
    const constructor = memberNamed(api, name);
    assert.equal(typeof constructor, "function", `${name} must be exported as a class`);
    const instance = entry.build(constructor as new (...args: readonly unknown[]) => Error);
    assert.ok(instance instanceof Error, `${name} must be an Error`);
    // `name` is what a consumer switches on; the class's own identifier is not it.
    assert.equal(instance.name, name, `${name} must report its own name`);
    assert.equal(typeof instance.message, "string");
    assert.ok(!seen.has(instance.name), `${instance.name} is not a unique name`);
    seen.add(instance.name);
  }
  assert.equal(seen.size, Object.keys(TAXONOMY).length);
});

suite("exactly the declared errors are typed transport failures", () => {
  const actual: string[] = [];
  const expected: string[] = [];
  for (const [name, entry] of Object.entries(TAXONOMY)) {
    const instance = errorNamed(name);
    if (instance instanceof api.TransportError) actual.push(name);
    if (entry.transport) expected.push(name);
  }
  // This is the set retry retries and the set that costs an upstream its health.
  assert.deepEqual(actual.sort(), expected.sort());
  // And a transport failure always carries the code those policies read.
  for (const name of expected) {
    const instance = errorNamed(name);
    // `code` is not on `Error`; it is what the transport set adds, and reading it through a
    // widened shape is what the untyped version did implicitly.
    const code: unknown = (instance as { code?: unknown }).code;
    assert.equal(typeof code, "string", `${name} must carry a transport code`);
    assert.ok(typeof code === "string" && code.length > 0);
  }
});

suite("the errors with a specialized Error base keep it", () => {
  // `MockNotMatchedError` is a `TypeError` because an unmatched mock is a programming
  // mistake, and `WebSocketError` is a `DOMException` because the WebSockets standard
  // says so. QuotaExceededError likewise inherits DOMException as Web IDL defines.
  // These bases are observable through `instanceof` and are not incidental.
  const mock = errorNamed("MockNotMatchedError");
  assert.ok(mock instanceof TypeError);
  const socket = errorNamed("WebSocketError");
  assert.ok(socket instanceof DOMException);
  assert.equal(socket.name, "WebSocketError");
  const quota = errorNamed("QuotaExceededError");
  assert.ok(quota instanceof DOMException);
  assert.equal(quota.name, "QuotaExceededError");
});

suite("proxy failures are deliberately outside the transport set", () => {
  // Recorded rather than asserted as ideal. A proxy that refuses a CONNECT is a
  // transport-layer failure by any ordinary reading, yet `ProxyResponseError`,
  // `Socks5ProxyError` and `ProxyConfigurationError` are not `TransportError`s, so a
  // failing proxy upstream never loses health and a proxy failure is never retried.
  //
  // For configuration and authentication that is right: retrying cannot help and
  // penalising an upstream for a fixed misconfiguration would route traffic away from
  // it forever. For a transient 502 from a proxy it is arguably wrong. Changing it
  // changes routing, so it is pinned here and left as a decision rather than drifting.
  for (const name of ["ProxyResponseError", "Socks5ProxyError", "ProxyConfigurationError"]) {
    const instance = errorNamed(name);
    assert.ok(
      !(instance instanceof api.TransportError),
      `${name} is outside the transport set; changing that changes retry and routing`,
    );
  }
});

// An `Event` built with no Web-platform runtime installed.
//
// Its own file, and that is the point rather than tidiness. The environment slot is
// process-global, so any suite that builds a runtime installs one for everything after
// it — a "no runtime" assertion sharing a file with a runtime test is asserting nothing,
// and it passed for the wrong reason until it was moved here.
//
// The behaviour matters because `AbortController`, `AbortSignal` and `EventTarget` are
// all usable without a platform. Reading the environment unguarded in `Event`'s
// constructor fails 41 tests in this lane, which is how that was established rather than
// reasoned about.
import assert from "node:assert/strict";
import test from "node:test";

import { AbortController, Event } from "../src/index.ts";

test("an event built with no runtime installed is stamped zero, not thrown over", () => {
  const event = new Event("bare");
  assert.equal(event.timeStamp, 0);
  assert.equal(event.type, "bare");
});

test("the abort primitives work with no runtime at all", () => {
  // The reason the guard exists: these construct events internally.
  const controller = new AbortController();
  const reason = new Error("no platform here");
  let seen;
  controller.signal.addEventListener("abort", () => (seen = controller.signal.reason));
  controller.abort(reason);
  assert.equal(seen, reason);
});

// `Event.timeStamp`, and the parts of it WPT does not pin.
//
// The upstream fixture asserts `ev.timeStamp > 0`, which a wall clock satisfies just as
// well as a monotonic one — an epoch millisecond count is emphatically greater than zero.
// The contract this lane wrote says something narrower: milliseconds since an origin
// fixed for the lifetime of the provider, monotonically non-decreasing, and deliberately
// *not* the same clock the cache compares `Date` headers against.
//
// Two clocks, and the mistake available is letting the monotonic one satisfy an interface
// that wanted the other, or the reverse. Nothing upstream would notice either.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import { createHostNodePrimitives, createHostNodeWebPlatform } from "../host/node-runtime.ts";
import { WebPlatformRuntime, installWebPlatformRuntime } from "../src/provider.ts";
import { Event } from "../src/index.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

function runtime(t: TestContext, now?: () => number): WebPlatformRuntime {
  const api = now === undefined ? createHostNodeWebPlatform() : new WebPlatformRuntime({
    ...createHostNodePrimitives(), monotonicMilliseconds: now,
  });
  if (now !== undefined) installWebPlatformRuntime(api);
  t.after(() => api.close());
  return api;
}

suite("timeStamp is time since an origin, not a wall clock", (t) => {
  runtime(t);
  const event = new Event("x");
  // An epoch millisecond count is around 1.7e12. A time-since-origin is the age of this
  // process, which is a handful of seconds at most in a test run. This is the assertion
  // that fails if somebody wires the wall clock in, and the one WPT cannot make.
  // Strictly positive, not merely non-negative. `timeStamp` returning a constant zero
  // satisfies every other assertion in this file -- captured-once, non-decreasing, and
  // not-an-epoch are all true of zero -- and only the upstream fixture caught it. A file
  // claiming to cover the semantics should not need the fixture to notice that.
  assert.ok(event.timeStamp > 0, `expected a real timestamp, got ${event.timeStamp}`);
  assert.ok(
    event.timeStamp < 1_000_000_000,
    `timeStamp looks like an epoch value rather than time since an origin: ${event.timeStamp}`,
  );
});

suite("timeStamp is captured once, at construction", (t) => {
  let now = 1;
  runtime(t, () => now);
  const event = new Event("x");
  const first = event.timeStamp;
  assert.equal(first, 1);
  now = 9;
  assert.equal(event.timeStamp, first, "reading it twice must give the same value");
});

suite("a later event is not stamped earlier than an earlier one", (t) => {
  let now = 1;
  runtime(t, () => now);
  const first = new Event("a");
  now = 9;
  const second = new Event("b");
  assert.deepEqual([first.timeStamp, second.timeStamp], [1, 9]);
  // Non-decreasing is the whole contract: the clock may stall, and must not reverse.
  assert.ok(
    second.timeStamp >= first.timeStamp,
    `${second.timeStamp} < ${first.timeStamp}`,
  );
});

import "../host/environment-shim.ts";
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { AbortController } from "../src/core/abort.ts";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import { WebPlatformRuntime } from "../src/provider.ts";
import {
  currentWebPlatformRuntime,
  hasWebPlatformRuntime,
  installWebPlatformRuntime,
} from "../src/provider/environment.ts";

import {
  CustomEvent,
  Event,
  EventTarget,
  addInternalEventListener,
  eventTargetSetErrorReporter,
} from "../src/core/events.ts";
import type { CustomEventInit } from "../src/core/events.ts";

test("listener errors without an installed runtime remain nonthrowing", () => {
  assert.equal(hasWebPlatformRuntime(), false);
  const target = new EventTarget();
  let followingCalls = 0;
  target.addEventListener("x", () => { throw new Error("no provider installed"); });
  target.addEventListener("x", () => { followingCalls++; });

  assert.doesNotThrow(() => target.dispatchEvent(new Event("x")));
  assert.equal(followingCalls, 1);
});

// DOM, dispatch and inner invoke:
// https://dom.spec.whatwg.org/#concept-event-dispatch
// https://dom.spec.whatwg.org/#concept-event-inner-invoke
test("a bare EventTarget invokes capture listeners before non-capture listeners", () => {
  for (const bubbles of [false, true]) {
    const target = new EventTarget();
    const order: string[] = [];
    target.addEventListener("x", (event) => {
      assert.equal(event.eventPhase, Event.AT_TARGET);
      order.push("bubble");
    });
    target.addEventListener("x", (event) => {
      assert.equal(event.eventPhase, Event.AT_TARGET);
      order.push("capture");
    }, true);

    target.dispatchEvent(new Event("x", { bubbles }));
    assert.deepEqual(order, ["capture", "bubble"]);
  }
});

test("each invocation snapshots listeners independently at the target", () => {
  const target = new EventTarget();
  const order: string[] = [];
  const lateCapture = (): void => { order.push("late capture"); };
  const lateBubble = (): void => { order.push("late bubble"); };
  target.addEventListener("x", () => {
    order.push("capture");
    target.addEventListener("x", lateCapture, true);
    target.addEventListener("x", lateBubble);
  }, true);
  target.addEventListener("x", () => { order.push("bubble"); });

  target.dispatchEvent(new Event("x"));
  assert.deepEqual(order, ["capture", "bubble", "late bubble"]);
  order.length = 0;
  target.dispatchEvent(new Event("x"));
  assert.deepEqual(order, ["capture", "late capture", "bubble", "late bubble"]);
});

test("capture stopPropagation finishes its invocation but suppresses the next", () => {
  const target = new EventTarget();
  const order: string[] = [];
  target.addEventListener("x", (event) => {
    order.push("first capture");
    event.stopPropagation();
  }, true);
  target.addEventListener("x", () => { order.push("second capture"); }, true);
  target.addEventListener("x", () => { order.push("bubble"); });

  target.dispatchEvent(new Event("x"));
  assert.deepEqual(order, ["first capture", "second capture"]);
});

test("an event stopped before dispatch skips listeners and can be dispatched again", () => {
  const target = new EventTarget();
  const order: string[] = [];
  target.addEventListener("x", () => { order.push("capture"); }, true);
  target.addEventListener("x", () => { order.push("bubble"); });
  const event = new Event("x");
  event.stopPropagation();

  target.dispatchEvent(event);
  assert.deepEqual(order, []);
  target.dispatchEvent(event);
  assert.deepEqual(order, ["capture", "bubble"]);
});

test("internal resisting listeners remain reachable after a capture listener stops dispatch", () => {
  const target = new EventTarget();
  const order: string[] = [];
  target.addEventListener("x", (event) => {
    order.push("capture");
    event.stopImmediatePropagation();
  }, true);
  target.addEventListener("x", () => { order.push("later capture"); }, true);
  target.addEventListener("x", () => { order.push("bubble"); });
  addInternalEventListener(target, "x", () => { order.push("internal"); }, {
    resistStopPropagation: true,
  });

  target.dispatchEvent(new Event("x"));
  assert.deepEqual(order, ["capture", "internal"]);
});

// DOM removeEventListener searches the current listener list, not records that
// were already removed from it: https://dom.spec.whatwg.org/#dom-eventtarget-removeeventlistener
for (const removeAgain of [false, true]) {
  test(`a listener removed and re-added during dispatch is ${removeAgain ? "removable" : "retained"}`, () => {
    const target = new EventTarget();
    let calls = 0;
    const listener = (): void => { calls++; };
    target.addEventListener("x", () => {
      target.removeEventListener("x", listener);
      target.addEventListener("x", listener);
      if (removeAgain) target.removeEventListener("x", listener);
    }, { once: true });
    target.addEventListener("x", listener);

    target.dispatchEvent(new Event("x"));
    assert.equal(calls, 0, "the new listener is outside the current invocation's snapshot");
    target.dispatchEvent(new Event("x"));
    assert.equal(calls, removeAgain ? 0 : 1);
  });
}

// DOM initialize clears trust, but initEvent is a no-op during dispatch:
// https://dom.spec.whatwg.org/#concept-event-initialize
// https://dom.spec.whatwg.org/#dom-event-initevent
test("initEvent clears trust on a completed provider-created event", () => {
  const controller = new AbortController();
  const events: Event[] = [];
  controller.signal.addEventListener("abort", (event) => { events.push(event); });
  controller.abort();
  const event = events[0];
  assert.ok(event !== undefined);
  assert.equal(event.isTrusted, true);

  event.initEvent("reinitialized", true, true);
  assert.equal(event.isTrusted, false);
  assert.equal(event.target, null);
  assert.equal(event.type, "reinitialized");
});

test("initEvent preserves trust while the event is dispatching", () => {
  const controller = new AbortController();
  let calls = 0;
  controller.signal.addEventListener("abort", (event) => {
    assert.equal(event.isTrusted, true);
    event.initEvent("ignored", true, true);
    assert.equal(event.isTrusted, true);
    assert.equal(event.type, "abort");
    calls++;
  });
  controller.abort();
  assert.equal(calls, 1);
});

test("script construction and dispatch cannot make an event trusted", () => {
  const init = { bubbles: false, isTrusted: true };
  const event = new Event("x", init);
  assert.equal(event.isTrusted, false);
  assert.throws(() => Object.assign(event, { isTrusted: true }), TypeError);
  assert.equal(event.isTrusted, false);
  const target = new EventTarget();
  let calls = 0;
  target.addEventListener("x", (received) => {
    assert.equal(received.isTrusted, false);
    calls++;
  });
  target.dispatchEvent(event);
  assert.equal(calls, 1);
  assert.equal(event.isTrusted, false);
});

// Web IDL attributes and operations require an object implementing the interface.
// The corresponding DOM algorithms use internal state, not overridable accessors.
// https://webidl.spec.whatwg.org/#es-attributes
// https://webidl.spec.whatwg.org/#es-operations
test("Event getters reject receivers without Event internal state", () => {
  const event = new Event("x");
  for (const name of [
    "type", "target", "srcElement", "currentTarget", "eventPhase", "bubbles",
    "cancelable", "returnValue", "defaultPrevented", "composed", "timeStamp", "cancelBubble",
  ] as const) {
    const get = Object.getOwnPropertyDescriptor(Event.prototype, name)?.get;
    assert.ok(get !== undefined, name);
    assert.equal(get.call(event), event[name]);
    assert.throws(() => get.call({}), TypeError, name);
    assert.throws(() => get.call(Object.create(Event.prototype)), TypeError, name);
  }
  const trusted = Object.getOwnPropertyDescriptor(Event.prototype, "isTrusted")?.get;
  assert.ok(trusted !== undefined);
  assert.equal(trusted.call(event), false);
  assert.throws(() => trusted.call({}), TypeError);
});

test("Event setters reject an invalid receiver even when their value is a no-op", () => {
  const returnValue = Object.getOwnPropertyDescriptor(Event.prototype, "returnValue")?.set;
  const cancelBubble = Object.getOwnPropertyDescriptor(Event.prototype, "cancelBubble")?.set;
  assert.ok(returnValue !== undefined && cancelBubble !== undefined);
  assert.throws(() => returnValue.call({}, true), TypeError);
  assert.throws(() => cancelBubble.call({}, false), TypeError);
});

test("Event and EventTarget validate the receiver before argument conversion", () => {
  const wrongEvent = {} as Event;
  const wrongTarget = {} as EventTarget;
  let conversions = 0;
  const type = {
    toString(): string {
      conversions++;
      return "x";
    },
  } as unknown as string;
  assert.throws(() => Event.prototype.initEvent.call(wrongEvent, type), TypeError);
  assert.throws(() => EventTarget.prototype.addEventListener.call(wrongTarget, type, null), TypeError);
  assert.throws(() => EventTarget.prototype.removeEventListener.call(wrongTarget, type, null), TypeError);
  assert.equal(conversions, 0);
});

test("dispatchEvent rejects an Event prototype without initialized internal state", () => {
  const target = new EventTarget();
  assert.equal(target.dispatchEvent(new Event("x")), true);
  assert.throws(() => target.dispatchEvent(Object.create(Event.prototype)), TypeError);
});

test("CustomEvent requires its own brand for detail and initCustomEvent", () => {
  const get = Object.getOwnPropertyDescriptor(CustomEvent.prototype, "detail")?.get;
  assert.ok(get !== undefined);
  const custom = new CustomEvent("x", { detail: 42 });
  assert.equal(get.call(custom), 42);
  assert.throws(() => get.call(new Event("x")), TypeError);
  assert.throws(() => CustomEvent.prototype.initCustomEvent.call({} as CustomEvent, "x"), TypeError);
  const ordinary = new Event("original");
  assert.throws(() => CustomEvent.prototype.initCustomEvent.call(ordinary as CustomEvent, "changed"), TypeError);
  assert.equal(ordinary.type, "original");
});

test("event and target expandos cannot replace their internal state", () => {
  const event = new Event("x", { cancelable: true });
  const eventProperties = event as unknown as Record<string, unknown>;
  eventProperties.eventType = "forged";
  eventProperties.eventCancelable = false;
  eventProperties.canceled = true;
  eventProperties.dispatching = true;
  const target = new EventTarget();
  let calls = 0;
  target.addEventListener("x", () => { calls++; });
  const targetProperties = target as unknown as Record<string, unknown>;
  targetProperties.listeners = [];

  assert.equal(event.type, "x");
  assert.equal(event.cancelable, true);
  assert.equal(event.defaultPrevented, false);
  assert.equal(target.dispatchEvent(event), true);
  assert.equal(calls, 1);
});

test("dispatch uses event state even when public accessors are overridden", () => {
  class OverriddenEvent extends Event {
    override get type(): string { return "shadow"; }
    override get defaultPrevented(): boolean { return true; }
  }
  const event = new OverriddenEvent("actual");
  const target = new EventTarget();
  const order: string[] = [];
  target.addEventListener("actual", () => { order.push("actual"); });
  target.addEventListener("shadow", () => { order.push("shadow"); });

  assert.equal(target.dispatchEvent(event), true);
  assert.deepEqual(order, ["actual"]);
  assert.equal(event.type, "shadow", "the script accessor remains observable to script");
  assert.equal(event.defaultPrevented, true);
});

test("the returnValue setter sets the canceled flag without calling preventDefault", () => {
  let calls = 0;
  class OverriddenEvent extends Event {
    override preventDefault(): void { calls++; }
  }
  const event = new OverriddenEvent("x", { cancelable: true });
  event.returnValue = false;

  assert.equal(calls, 0);
  assert.equal(event.defaultPrevented, true);
  assert.equal(new EventTarget().dispatchEvent(event), false);
});

// Web IDL constants: https://webidl.spec.whatwg.org/#es-constants
test("Event constants have immutable descriptors on the interface and prototype", {
  skip: "Deferred: nts fixed class layouts do not support property descriptors; Event uses static readonly constants.",
}, () => {
  for (const [name, value] of [
    ["NONE", 0],
    ["CAPTURING_PHASE", 1],
    ["AT_TARGET", 2],
    ["BUBBLING_PHASE", 3],
  ] as const) {
    for (const owner of [Event, Event.prototype]) {
      assert.deepEqual(Object.getOwnPropertyDescriptor(owner, name), {
        value,
        writable: false,
        enumerable: true,
        configurable: false,
      });
    }
  }
});

// Web IDL calls the callback, not its overridable `call` property:
// https://webidl.spec.whatwg.org/#call-a-user-objects-operation
// https://webidl.spec.whatwg.org/#invoke-a-callback-function
test("function listeners ignore an own call property and receive the target", { skip: "a function object with an own call property cannot arise in a typed nts program" }, () => {
  const target = new EventTarget();
  const event = new Event("x");
  const calls: { receiver: unknown; event: Event }[] = [];
  let shadowCalls = 0;
  const listener = Object.assign(function (this: unknown, event: Event): void {
    calls.push({ receiver: this, event });
  }, {
    call(): void { shadowCalls++; },
  });
  target.addEventListener("x", listener, true);
  target.addEventListener("x", listener);

  target.dispatchEvent(event);
  assert.equal(shadowCalls, 0);
  assert.deepEqual(calls, [
    { receiver: target, event },
    { receiver: target, event },
  ]);
});

test("object listeners read handleEvent once and ignore the returned function's call", { skip: "a function object with an own call property cannot arise in a typed nts program" }, () => {
  const target = new EventTarget();
  const event = new Event("x");
  const calls: { receiver: unknown; event: Event }[] = [];
  let shadowCalls = 0;
  let reads = 0;
  const callback = Object.assign(function (this: unknown, event: Event): void {
    calls.push({ receiver: this, event });
  }, {
    call(): void { shadowCalls++; },
  });
  const listener = {
    get handleEvent() {
      reads++;
      return callback;
    },
  };
  target.addEventListener("x", listener);
  assert.equal(reads, 0, "the callback member is read at invocation time");

  target.dispatchEvent(event);
  assert.equal(reads, 1);
  assert.equal(shadowCalls, 0);
  assert.deepEqual(calls, [{ receiver: listener, event }]);
});

test("event handler attributes ignore an own call property on their callback", { skip: "a function object with an own call property cannot arise in a typed nts program" }, () => {
  const controller = new AbortController();
  const calls: { receiver: unknown; event: Event }[] = [];
  let shadowCalls = 0;
  controller.signal.onabort = Object.assign(function (this: unknown, event: Event): void {
    calls.push({ receiver: this, event });
  }, {
    call(): void { shadowCalls++; },
  });

  controller.abort();
  assert.equal(shadowCalls, 0);
  assert.equal(calls.length, 1);
  assert.equal(calls[0]?.receiver, controller.signal);
