  assert.deepEqual(order, ["capture", "later capture"]);
  assert.equal(eventAttribute(event, "cancelBubble"), false);
  order.length = 0;
  assert.equal(target.dispatchEvent(event), true);
  assert.deepEqual(order, ["later capture", "bubble"]);
});

