    assert.deepEqual(records.map((record) => record.type), ["loadstart", "progress", "error", "loadend"]);
  }
  await completeRead(reader, () => reader.readAsText(new Blob([new Uint8Array([0x80])], { type: "text/plain;charset=latin1" })));
  assert.ok(isDOMException("NotSupportedError")(reader.error));
});

// https://html.spec.whatwg.org/multipage/webappapis.html#event-handlers
test("FileReader handler replacement preserves registration order and clearing re-adds at the end", () => {
  const reader = new FileReader();
  const order: string[] = [];
  reader.addEventListener("load", () => order.push("first"));
  reader.onload = () => order.push("old");
  reader.addEventListener("load", () => order.push("last"));
  reader.onload = () => order.push("replacement");
  reader.dispatchEvent(new Event("load"));
  assert.deepEqual(order, ["first", "replacement", "last"]);
  order.length = 0;
  reader.onload = null;
  reader.onload = () => order.push("re-added");
  reader.dispatchEvent(new Event("load"));
  assert.deepEqual(order, ["first", "last", "re-added"]);
});

test("FileReader HTML handlers retain non-callable objects but treat primitives as null", () => {
  const reader = new FileReader();
  let calls = 0;
  const object = { handleEvent() { calls++; } };
  reader.onload = object;
  assert.equal(reader.onload, object);
  reader.dispatchEvent(new Event("load"));
  assert.equal(calls, 0);
  for (const value of [undefined, false, 0, "handler", Symbol("handler")]) {
    reader.onload = value as unknown as FileReaderEventHandlerValue;
    assert.equal(reader.onload, null);
  }
});

test("FileReader handlers preserve their receiver and return false cancels synthetic events", () => {
  const reader = new FileReader();
  const calls: unknown[] = [];
  reader.onload = function (this: FileReader, event: Event) {
    calls.push(this, event);
    return false;
  };
  const event = new Event("load", { cancelable: true });
  assert.equal(reader.dispatchEvent(event), false);
  assert.equal(event.defaultPrevented, true);
  assert.deepEqual(calls, [reader, event]);
});

test("FileReader listener exceptions reach the provider without stopping later listeners", (t) => {
  const scheduler = virtualRuntime(t);
  const reader = new FileReader();
  const marker = new Error("listener failed");
  const calls: string[] = [];
  reader.onload = () => { calls.push("handler"); throw marker; };
  reader.addEventListener("load", () => calls.push("listener"));
  assert.doesNotThrow(() => reader.dispatchEvent(new Event("load")));
  assert.deepEqual(calls, ["handler", "listener"]);
  assert.deepEqual(scheduler.errors, [marker]);
});

// HTML activates/deactivates handler listeners internally, without invoking the
// target's user-overridable addEventListener/removeEventListener methods.
test("FileReader handler assignment bypasses subclass listener-registration overrides", () => {
  const calls: string[] = [];
  class DerivedReader extends FileReader {
    override addEventListener(): never { calls.push("public add"); throw new Error("public add"); }
    override removeEventListener(): never { calls.push("public remove"); throw new Error("public remove"); }
  }
  const reader = new DerivedReader();
  assert.doesNotThrow(() => { reader.onload = () => calls.push("handler"); });
  reader.dispatchEvent(new Event("load"));
  assert.deepEqual(calls, ["handler"]);
  assert.doesNotThrow(() => { reader.onload = null; });
  reader.dispatchEvent(new Event("load"));
  assert.deepEqual(calls, ["handler"]);
  assert.doesNotThrow(() => { reader.onload = () => calls.push("replacement"); });
  reader.dispatchEvent(new Event("load"));
  assert.deepEqual(calls, ["handler", "replacement"]);
});

test("FileReader handler callback.call spoofing", { skip: "typed nts programs cannot attach an own call property to a function" }, () => {});

test("FileReader handler cancellation bypasses a public preventDefault override", () => {
  let overrides = 0;
  class CustomEvent extends Event {
    override preventDefault(): void { overrides++; }
  }
  const reader = new FileReader();
  reader.onload = () => false;
  const event = new CustomEvent("load", { cancelable: true });
  assert.equal(reader.dispatchEvent(event), false);
  assert.equal(event.defaultPrevented, true);
  assert.equal(overrides, 0);
});

test("FileReader fires trusted events without invoking a public dispatchEvent override", async () => {
  let overrides = 0;
  class CustomReader extends FileReader {
    override dispatchEvent(): never { overrides++; throw new Error("public dispatchEvent"); }
  }
  const reader = new CustomReader();
  const completed = Promise.withResolvers<void>();
  reader.onloadend = (event) => {
    assert.equal(event.isTrusted, true);
    completed.resolve();
  };
  reader.readAsText(new Blob(["abc"]));
  await completed.promise;
  assert.equal(reader.result, "abc");
  assert.equal(overrides, 0);
});

// `file:` is a capability-scoped provider extension: absent by default, and when
// present it is the provider that decides which files exist and which may be read.
// The shared layer owns which URLs are fetchable at all and the shape of the response.
//
// Host evidence for the shared algorithm and for one provider's scoping. A different
// provider's scoping is its own to prove.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { mkdtempSync, mkdirSync, symlinkSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

import {
  createHostNodeWebPlatform,
  HostNodeFileURLProvider,
} from "../host/node-runtime.ts";
import type { WebPlatformRuntime } from "../src/provider.ts";
import { causeText } from "./harness.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

// Fetch reports every failure as an opaque `TypeError: Network request failed`, so the
// reason lives on the cause chain. That is the specified behaviour and it is also why
// a refused path never puts a filesystem detail into the message script sees.
function because(pattern: RegExp): (error: unknown) => boolean {
  return (error: unknown) => {
    assert.ok(error instanceof Error, "fetch rejects with an Error");
    assert.equal(error.name, "TypeError");
    assert.equal(error.message, "Network request failed");
    assert.match(causeText(error.cause), pattern);
    return true;
  };
}

function tree(t: TestContext): { dir: string; root: string } {
  const dir = mkdtempSync(join(tmpdir(), "nts-file-url-"));
  const root = join(dir, "root");
  mkdirSync(root);
  mkdirSync(join(root, "nested"));
  writeFileSync(join(root, "hello.txt"), "hello from a file");
  writeFileSync(join(root, "nested", "deep.json"), '{"ok":true}');
  writeFileSync(join(dir, "secret.txt"), "outside the root");
  symlinkSync(join(dir, "secret.txt"), join(root, "escape.txt"));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  return { dir, root };
}

function runtimeWith(t: TestContext, root: string | null): WebPlatformRuntime {
  const api = createHostNodeWebPlatform({
    fileURLs:
      root === null
        ? undefined
        : new HostNodeFileURLProvider({
            root,
            types: { ".txt": "text/plain;charset=UTF-8", ".json": "application/json" },
          }),
  });
  t.after(() => api.close());
  return api;
}

suite("file: is unsupported until a provider is supplied", async (t) => {
  const { root } = tree(t);
  const api = runtimeWith(t, null);
  const url = pathToFileURL(join(root, "hello.txt")).href;
  await assert.rejects(api.fetch(url), because(/Unsupported URL scheme/));
});

suite("a scoped provider serves files with length and media type", async (t) => {
  const { root } = tree(t);
  const api = runtimeWith(t, root);

  const text = await api.fetch(pathToFileURL(join(root, "hello.txt")).href);
  assert.equal(text.status, 200);
  assert.equal(text.headers.get("content-type"), "text/plain;charset=UTF-8");
  assert.equal(text.headers.get("content-length"), "17");
  assert.equal(await text.text(), "hello from a file");

  const json = await api.fetch(pathToFileURL(join(root, "nested", "deep.json")).href);
  assert.equal(json.headers.get("content-type"), "application/json");
  assert.deepEqual(await json.json(), { ok: true });
});

suite("HEAD answers with the headers and no body", async (t) => {
  const { root } = tree(t);
  const api = runtimeWith(t, root);
  const response = await api.fetch(pathToFileURL(join(root, "hello.txt")).href, {
    method: "HEAD",
  });
  assert.equal(response.status, 200);
  assert.equal(response.headers.get("content-length"), "17");
  assert.equal(response.body, null);
});

suite("a range request reads only the requested bytes", async (t) => {
  const { root } = tree(t);
  const api = runtimeWith(t, root);
  const response = await api.fetch(pathToFileURL(join(root, "hello.txt")).href, {
    headers: { range: "bytes=6-9" },
  });
  assert.equal(response.status, 206);
  assert.equal(await response.text(), "from");
  assert.equal(response.headers.get("content-range"), "bytes 6-9/17");
});

suite("a method other than GET or HEAD fails deterministically", async (t) => {
  const { root } = tree(t);
  const api = runtimeWith(t, root);
  await assert.rejects(
    api.fetch(pathToFileURL(join(root, "hello.txt")).href, { method: "POST", body: "x" }),
    because(/only GET and HEAD/),
  );
});

suite("a file URL naming a remote host or credentials is refused", async (t) => {
  const { root } = tree(t);
  const api = runtimeWith(t, root);
  await assert.rejects(api.fetch("file://elsewhere.example/etc/passwd"), because(/remote host/));
  await assert.rejects(api.fetch("file://user:pass@/etc/passwd"), TypeError);
  // localhost is the one host form that means "this machine" and is normalized away.
  const local = "file://localhost" + pathToFileURL(join(root, "hello.txt")).pathname;
  assert.equal(await (await api.fetch(local)).text(), "hello from a file");
});

suite("a path leaving the root is refused before it is opened", async (t) => {
  const { dir, root } = tree(t);
  const api = runtimeWith(t, root);
  // The URL parser normalizes dot segments, so this arrives as the parent path
  // rather than as traversal the provider has to detect textually.
  const traversal = pathToFileURL(join(root, "nested")).href + "/../../secret.txt";
  assert.equal(new URL(traversal).href, pathToFileURL(join(dir, "secret.txt")).href);
  await assert.rejects(api.fetch(traversal), because(/outside the permitted root/));
});

suite("a symlink inside the root pointing out of it is refused", async (t) => {
  const { root } = tree(t);
  const api = runtimeWith(t, root);
  // Textually this path is inside the root; only resolving it says otherwise.
  const escape = pathToFileURL(join(root, "escape.txt")).href;
  assert.match(escape, /\/root\/escape\.txt$/);
  await assert.rejects(api.fetch(escape), because(/outside the permitted root/));
});

// The flat-to-DurableByteStore adapter, exercised against a fake provider.
//
// This is the shared half of the storage seam. A provider gives twelve synchronous
// functions over scalars, strings and caller-owned views -- the shape a foreign-function
// boundary can carry -- and everything the contract adds above it is written once here:
// promises, the `AbortSignal` checked between chunks, the write as an object with a
// lifetime, the two-call retry when a fill buffer was short, and the record encoding.
//
// The fake provider is the point rather than a shortcut. Testing the adapter against a
// real store would mean every assertion below could also be answered by the store, and
// the parts most likely to differ between platforms are exactly these. The Android and
// host providers owe their own evidence for the flat surface; this owes the layer above.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import { AbortController } from "../src/index.ts";
import { durableStoreFromFlat } from "../src/provider.ts";
import { FakeFlat } from "./fake-flat.ts";
import { must } from "./harness.ts";
import type { DurableByteStore } from "../src/provider.ts";
import type { AbortSignal } from "../src/index.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const encoder = new TextEncoder();
const decoder = new TextDecoder();
const none = () => new AbortController().signal;

function adapted() {
  const flat = new FakeFlat();
  return { flat, store: durableStoreFromFlat(flat) };
}

async function put(
  target: DurableByteStore,
  namespace: string,
  key: string,
  bytes: Uint8Array,
  signal: AbortSignal = none(),
): Promise<void> {
  const write = await target.write(namespace, key, signal);
  await write.append(bytes);
  await write.commit();
}

suite("a value written through the adapter reads back whole and by range", async () => {
  const { store } = adapted();
  await put(store, "cache", "greeting", encoder.encode("hello durable world"));

  assert.equal(
    decoder.decode(await store.read("cache", "greeting", none())),
    "hello durable world",
  );

  const source = must(await store.source("cache", "greeting", none()), "the key that was just written has a source");
  assert.equal(source.size, 19);
  const reader = source.open(6, 7);
  assert.equal(decoder.decode(await reader.read(64)), "durable");
  assert.equal(await reader.read(64), undefined, "the range ends where it was asked to");
  await reader.close();
});

suite("a value larger than the first fill buffer reads back whole", async () => {
  const { flat, store } = adapted();
  // Larger than the adapter's initial guess, so the short-buffer retry is the only
  // way the whole value comes back.
  const payload = new Uint8Array(9001);
  for (let index = 0; index < payload.length; index++) payload[index] = index % 251;
  await put(store, "cache", "big", payload);

  const read = must(await store.read("cache", "big", none()), "the key that was just written reads back");
  assert.equal(read.length, 9001);
  assert.deepEqual(read, payload);
  assert.equal(flat.reads, 2, "the retry is one further call, not a search");
});

suite("a fill buffer that was long enough is not asked twice", async () => {
  const { flat, store } = adapted();
  await put(store, "cache", "small", encoder.encode("short"));
  assert.equal(decoder.decode(await store.read("cache", "small", none())), "short");
  assert.equal(flat.reads, 1);
});

suite("list survives keys that contain the separator and non-ASCII text", async () => {
  const { store } = adapted();
  // A key may hold any byte. The encoding carries an explicit key length for exactly
  // this: scanning for the next NUL would split this key into two records.
  const awkward = "with\u0000nul";
  await put(store, "cache", awkward, encoder.encode("a"));
  await put(store, "cache", "é中文", encoder.encode("bb"));
  await put(store, "other", "elsewhere", encoder.encode("ccc"));

  const records = await store.list("cache", none());
  assert.deepEqual(
    records.map((record) => record.key).sort(),
    [awkward, "é中文"].sort(),
  );
  const bySize = new Map(records.map((record) => [record.key, record.size]));
  assert.equal(bySize.get(awkward), 1);
  assert.equal(bySize.get("é中文"), 2);
  assert.ok(records.every((record) => record.modifiedMilliseconds > 0));
});

suite("a listing larger than the first fill buffer comes back complete", async () => {
  const { flat, store } = adapted();
  const expected = [];
  for (let index = 0; index < 400; index++) {
    const key = `key-${index}-${"p".repeat(20)}`;
    expected.push(key);
    await put(store, "cache", key, encoder.encode("v"));
  }
  const records = await store.list("cache", none());
  assert.equal(flat.lists, 2, "one retry, sized by what the provider reported");
  assert.equal(await store.size("cache", none()), 400);
  // The count alone is too weak to be evidence: a parser that loses its place in the
  // stream still consumes one record per turn, so it reports 400 mangled records.
  assert.deepEqual(
    records.map((record) => record.key).sort(),
    expected.sort(),
  );
  assert.ok(
    records.every((record) => record.size === 1),
    "every record carries the size it was written with",
  );
});

suite("each ranged read owns its chunk", async () => {
  const { store } = adapted();
  await put(store, "cache", "stream", encoder.encode("first-second-"));

  const source = must(await store.source("cache", "stream", none()), "the key that was just written has a source");
  const reader = source.open(0, 13);
  // The reader transfers ownership of what it returns, so a consumer may hold two
  // chunks at once. A buffer reused across calls would rewrite the first one here.
  // `read` returns nothing once the range is exhausted; both of these are inside it.
  const first = must(await reader.read(6), "the first six bytes of the range");
  const second = must(await reader.read(7), "the next seven bytes of the range");
  assert.equal(decoder.decode(first), "first-");
  assert.equal(decoder.decode(second), "second-");
  assert.notEqual(first.buffer, second.buffer, "chunks may not share a buffer");
  await reader.close();
});

suite("a reader opened before a delete keeps reading", async () => {
  const { store } = adapted();
  await put(store, "cache", "doomed", encoder.encode("bytes that outlive their key"));

  const source = must(await store.source("cache", "doomed", none()), "the key that was just written has a source");
  assert.equal(source.size, 28);
  const reader = source.open(0, source.size);
  assert.equal(decoder.decode(await reader.read(6)), "bytes ");

  assert.equal(await store.delete("cache", "doomed", none()), true);
  assert.equal(await store.read("cache", "doomed", none()), null, "the key is gone");

  // The reader pins what it was opened over. Without this a caller cannot release
  // stored bytes while anything might still be reading them, which is the whole
  // lifetime story for a spilled body.
  assert.equal(decoder.decode(await reader.read(64)), "that outlive their key");
  assert.equal(await reader.read(64), undefined);
  await reader.close();
});

suite("an absent key is null rather than an error", async () => {
  const { store } = adapted();
  assert.equal(await store.read("cache", "missing", none()), null);
  assert.equal(await store.source("cache", "missing", none()), null);
  assert.equal(await store.delete("cache", "missing", none()), false);
  assert.deepEqual(await store.list("cache", none()), []);
});

suite("a second write to a live key is refused rather than queued", async () => {
  const { store } = adapted();
  const first = await store.write("cache", "contended", none());
  await assert.rejects(() => store.write("cache", "contended", none()), TypeError);
  // And released when the first one settles, either way.
  await first.discard();
  const second = await store.write("cache", "contended", none());
  await second.commit();
});

suite("cancellation is honoured between chunks with the exact reason", async () => {
  const { flat, store } = adapted();
  const controller = new AbortController();
  const write = await store.write("cache", "cancelled", controller.signal);
  await write.append(encoder.encode("kept so far"));

  const reason = new Error("the caller changed its mind");
  controller.abort(reason);

  await assert.rejects(
    () => write.append(encoder.encode("more")),
    (thrown) => thrown === reason,
  );
  await assert.rejects(() => write.commit(), (thrown) => thrown === reason);
  // Discard is the cleanup path and has to work when the signal is already aborted,
  // which is precisely when a caller reaches for it.
  await write.discard();
  assert.equal(flat.live.size, 0, "an aborted write does not hold the key");
  assert.equal(await store.read("cache", "cancelled", none()), null);
});

suite("an already-aborted signal is refused before the provider is touched", async () => {
  const { flat, store } = adapted();
  await put(store, "cache", "present", encoder.encode("v"));
  const controller = new AbortController();
  const reason = new Error("too late");
  controller.abort(reason);
  const signal = controller.signal;

  const before = flat.reads;
  await assert.rejects(
    () => store.read("cache", "present", signal),
    (thrown) => thrown === reason,
  );
  await assert.rejects(
    () => store.write("cache", "present", signal),
    (thrown) => thrown === reason,
  );
  await assert.rejects(() => store.list("cache", signal), (thrown) => thrown === reason);
  await assert.rejects(() => store.size("cache", signal), (thrown) => thrown === reason);
  await assert.rejects(
    () => store.delete("cache", "present", signal),
    (thrown) => thrown === reason,
  );
  await assert.rejects(
    () => store.source("cache", "present", signal),
    (thrown) => thrown === reason,
  );
  assert.equal(flat.reads, before, "nothing reached the provider");
  assert.equal(flat.live.size, 0, "and no handle was opened");
});

suite("a settled write refuses further appends and repeats are no-ops", async () => {
  const { store } = adapted();
  const write = await store.write("cache", "settled", none());
  await write.append(encoder.encode("v"));
  await write.commit();
  await assert.rejects(() => write.append(encoder.encode("more")), TypeError);
  await write.commit();
  await write.discard();
  assert.equal(decoder.decode(await store.read("cache", "settled", none())), "v");
});

suite("a closed reader stays closed and closing twice is a no-op", async () => {
  const { store } = adapted();
  await put(store, "cache", "readable", encoder.encode("bytes"));
  const source = must(await store.source("cache", "readable", none()), "the key that was just written has a source");
  const reader = source.open(0, 5);
  await reader.close();
  await reader.close();
  await assert.rejects(() => reader.read(4), TypeError);
});

suite("a provider failure surfaces as a rejection rather than a throw", async () => {
  const { flat, store } = adapted();
  const failure = new Error("the device is gone");
  flat.size = () => {
    throw failure;
  };
  await assert.rejects(() => store.size("cache", none()), (thrown) => thrown === failure);
});

suite("close reaches the provider", async () => {
  const { flat, store } = adapted();
  await store.close();
  assert.equal(flat.closed, true);
});

// Deterministic protocol fuzzing.
//
// The plan lists fuzzing under testing and observability. The property under test is
// not "does it parse" -- malformed input is the point -- but that malformed input
// always reaches a *named* failure: a typed error from our own taxonomy, in bounded
// time, with nothing half-decoded escaping as a result.
//
// Seeded, so a failure is reproducible rather than a run nobody can repeat. The
// generator's own coverage is asserted, because a fuzzer that never produces the
// interesting shape passes forever while testing nothing.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import { BufferedReader } from "../src/provider.ts";
// Internal error types: a test may name them, but they are not widened into the
// provider boundary just to be asserted on.
import {
  LimitError,
  ProtocolError,
} from "../src/core/errors.ts";
import { readFrame } from "../src/websocket/codec.ts";
import { readHeaderFields } from "../src/http1/parser.ts";
import type { ByteConnection } from "../src/provider/primitives.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const CRLF = String.fromCharCode(13, 10);

/** xorshift32: small, deterministic, and identical on every run. */
function rng(seed: number): () => number {
  let state = seed >>> 0 || 1;
  return () => {
    state ^= state << 13;
    state >>>= 0;
    state ^= state >>> 17;
    state ^= state << 5;
    state >>>= 0;
    return state;
  };
}

function bytesFrom(bytes: Uint8Array | readonly number[]): ByteConnection {
  const source = Uint8Array.from(bytes);
  let offset = 0;
  return {
    get closed() {
      return false;
    },
    async read(maxBytes: number): Promise<Uint8Array | null> {
      if (offset >= source.length) return null;
      const end = Math.min(source.length, offset + maxBytes);
      const chunk = source.subarray(offset, end);
      offset = end;
      return chunk;
    },
    async write(data: Uint8Array): Promise<number> {
      return data.length;
    },
    close() {},
  };
}

/**
 * A failure that names itself.
 *
 * Reaching the end of the input is a legitimate outcome for a truncated frame. Anything
 * else must be one of our protocol errors: a raw `TypeError` from indexing past an
 * array, or a `RangeError` from an allocation, would mean the parser fell over rather
 * than refused.
 */
function isNamedFailure(error: unknown): boolean {
  if (error instanceof ProtocolError || error instanceof LimitError) return true;
  return error instanceof Error && /unexpected end|closed|EOF/i.test(error.message);
}

suite("malformed WebSocket frames always reach a named failure", async () => {
  const next = rng(0x5eed1234);
  const coverage = {
    accepted: 0,
    control: 0,
    reservedBits: 0,
    wrongMasking: 0,
    extendedLength: 0,
    hugeLength: 0,
  };
  let failures = 0;

  for (let iteration = 0; iteration < 4000; iteration++) {
    const length = 2 + (next() % 20);
    const bytes = [];
    for (let index = 0; index < length; index++) bytes.push(next() & 0xff);

    // Half the corpus is steered towards frame-shaped input, so the parser is reached
    // past its first byte rather than rejected immediately every time.
    if ((next() & 1) === 0) {
      const opcodes = [0x00, 0x01, 0x02, 0x08, 0x09, 0x0a, 0x03, 0x0b];
      bytes[0] = (next() & 1 ? 0x80 : 0x00) | (opcodes[next() % opcodes.length] ?? 0);
      const lengths = [0, 5, 125, 126, 127];
      bytes[1] = (next() & 1 ? 0x80 : 0x00) | (lengths[next() % lengths.length] ?? 0);
    }

    if (((bytes[0] ?? 0) & 0x70) !== 0) coverage.reservedBits += 1;
    if (((bytes[0] ?? 0) & 0x0f) >= 8) coverage.control += 1;
    if (((bytes[1] ?? 0) & 0x80) === 0) coverage.wrongMasking += 1;
    if (((bytes[1] ?? 0) & 0x7f) === 126) coverage.extendedLength += 1;
    if (((bytes[1] ?? 0) & 0x7f) === 127) coverage.hugeLength += 1;

    const reader = new BufferedReader(bytesFrom(bytes));
    try {
      // The server direction: a client must mask, so unmasked input is a real case.
      const frame = await readFrame(reader, true, 1 << 20, true);
      coverage.accepted += 1;
      // Anything accepted must be internally consistent.
      assert.ok(frame.payload instanceof Uint8Array);
      assert.ok([0, 1, 2, 8, 9, 10].includes(frame.opcode));
      if (frame.opcode >= 8) {
        assert.equal(frame.fin, true, "a control frame is never fragmented");
        assert.ok(frame.payload.length <= 125, "a control frame is never large");
      }
    } catch (error) {
      failures += 1;
      assert.ok(
        isNamedFailure(error),
        "iteration " + iteration + " produced an unnamed failure: " + String(error instanceof Error ? error.stack : error),
      );
    }
  }

  // The corpus reached every shape this test claims to exercise. Without this the whole
  // suite could pass while generating nothing but two random bytes.
  assert.ok(coverage.accepted > 0, "some frames must parse, or nothing was exercised");
  assert.ok(failures > 0, "some frames must fail, or nothing malformed was generated");
  for (const [name, count] of Object.entries(coverage)) {
    assert.ok(count > 0, "the generator never produced: " + name);
  }
});

suite("malformed HTTP/1 header blocks always reach a named failure", async () => {
  const next = rng(0x1234abcd);
  const limits = { maxHeaderBytes: 4096, maxHeaders: 32, maxInformational: 4 };
  const coverage = { accepted: 0, noColon: 0, spacedValue: 0, longLine: 0, manyFields: 0 };
  let failures = 0;

  for (let iteration = 0; iteration < 2000; iteration++) {
    const fields = next() % 6;
    let text = "";
    for (let index = 0; index < fields; index++) {
      const shape = next() % 5;
      if (shape === 0) text += "name" + index + ": value" + CRLF;
      else if (shape === 1) {
        text += "novalue" + index + CRLF;
        coverage.noColon += 1;
      } else if (shape === 2) {
        text += "bad" + index + ": va lue" + CRLF;
        coverage.spacedValue += 1;
      } else if (shape === 3) {
        text += "long" + index + ": " + "x".repeat(600) + CRLF;
        coverage.longLine += 1;
      } else {
        for (let extra = 0; extra < 40; extra++) text += "f" + extra + ": v" + CRLF;
        coverage.manyFields += 1;
      }
    }
    text += CRLF;

    const bytes = [];
    for (let index = 0; index < text.length; index++) bytes.push(text.charCodeAt(index) & 0xff);
    const reader = new BufferedReader(bytesFrom(bytes));
    try {
      const headers = await readHeaderFields(reader, limits);
      coverage.accepted += 1;
      assert.ok(Array.isArray(headers));
      assert.ok(headers.length <= limits.maxHeaders);
      for (const [name, value] of headers) {
        assert.equal(typeof name, "string");
        assert.equal(typeof value, "string");
        assert.ok(name.length > 0, "a parsed field always has a name");
      }
    } catch (error) {
      failures += 1;
      assert.ok(
        isNamedFailure(error),
        "iteration " + iteration + " produced an unnamed failure: " + String(error instanceof Error ? error.stack : error),
      );
    }
  }

  assert.ok(coverage.accepted > 0, "some header blocks must parse");
  assert.ok(failures > 0, "some header blocks must fail");
  for (const [name, count] of Object.entries(coverage)) {
    assert.ok(count > 0, "the generator never produced: " + name);
  }
});

suite("the corpus is the same on every run", () => {
  // A fuzzer whose corpus changes per run reports failures nobody can reproduce. Two
  // generators from one seed must agree exactly.
  const a = rng(99);
  const b = rng(99);
  for (let index = 0; index < 1000; index++) assert.equal(a(), b());
  // And different seeds must actually differ, or seeding is decoration.
  const c = rng(100);
  const d = rng(101);
  let differences = 0;
  for (let index = 0; index < 100; index++) if (c() !== d()) differences += 1;
  assert.ok(differences > 90, "different seeds must produce different corpora");
});

import assert from "node:assert/strict";
import test from "node:test";
import { WptHarness } from "./wpt/harness.ts";

test("WPT allow_uncaught_exception applies only to the explicit uncaught-global channel", async () => {
  let harness: WptHarness;
  harness = new WptHarness({ uncaught: () => harness.reportUncaughtException("expected uncaught") }, {}, 10000,
    { uncaughtExceptionChannel: true });
  harness.run('setup({allow_uncaught_exception:true}); test(() => uncaught(), "allowed");', "allowed.js");
  assert.deepEqual((await harness.finish()).map((result) => result.status), ["pass"]);
});

test("WPT uncaught-global reports fail when the option is false or absent", async () => {
  for (const setup of ["", "setup({allow_uncaught_exception:false});"]) {
    let harness: WptHarness;
    harness = new WptHarness({ uncaught: () => harness.reportUncaughtException("unexpected") }, {}, 10000,
      { uncaughtExceptionChannel: true });
    harness.run(setup + 'test(() => uncaught(), "not allowed");', "not-allowed.js");
    assert.deepEqual((await harness.finish()).map((result) => result.status), ["fail"]);
