// Narrowings this suite needs in many places, written once.
//
// Each of these exists because a value is legitimately wider than the tests use it as, and the
// honest way to close that gap is a check rather than an assertion that it cannot happen. Three
// of them recurred often enough that a local copy per file was the worse option: a helper that
// exists twice is a helper that drifts, and here it would drift in what it is willing to accept.
import assert from "node:assert/strict";
import type { Server } from "node:net";

import { MessageEvent } from "../src/index.ts";
import type { Event } from "../src/index.ts";

/**
 * The port a listening TCP server bound.
 *
 * `address()` is a union: a string for a pipe, `null` before the socket is bound. A server that
 * has emitted `listening` over TCP is always the object form, and checking says so where a
 * non-null assertion would only have claimed it.
 */
export function portOf(server: Server): number {
  const address = server.address();
  assert.ok(
    address !== null && typeof address === "object",
    "expected a listening TCP server with a bound port",
  );
  return address.port;
}

/**
 * An error's cause chain, flattened to one string.
 *
 * Every link is `unknown` -- `cause` is declared that way and a thrown value need not be an
 * Error at all -- so each step reads defensively rather than assuming a shape. Fetch reports
 * every failure as an opaque `TypeError: Network request failed`, which is why the reason a
 * test is actually looking for lives down here.
 */
export function causeText(from: unknown): string {
  let cause: unknown = from;
  let text = "";
  while (cause !== undefined && cause !== null) {
    const message: unknown = (cause as { message?: unknown }).message;
    text += String(message ?? cause) + " ";
    cause = (cause as { cause?: unknown }).cause;
  }
  return text;
}

/**
 * The payload of a message event.
 *
 * `addEventListener` hands its listener the base `Event`, because one signature serves every
 * type. A message event carries `data`, and this narrows to it rather than the field being read
 * off a type that does not declare it.
 */
export function messageData(event: Event): unknown {
  assert.ok(event instanceof MessageEvent, "expected a MessageEvent");
  return event.data;
}

/**
 * A value the API declares as optional, asserted present.
 *
 * Reaching for this rather than a non-null assertion is the difference between a check and a
 * claim: a store that returned nothing now fails with the sentence the caller wrote, at the
 * line that expected the value, instead of as a property read on `null` further down.
 */
export function must<T>(value: T | null | undefined, what: string): T {
  assert.ok(value !== null && value !== undefined, what);
  return value;
}

/**
 * A member of a module namespace or of `globalThis`, looked up by a runtime name.
 *
 * The one thing in this suite TypeScript cannot express: neither declares an index signature,
 * and the names come from tables the tests iterate. The read is widened to `unknown` rather
 * than to `any`, so a caller still has to say what it expects and gets no free property access
 * out of it.
 */
export function memberNamed(scope: object, name: string): unknown {
  return (scope as Record<string, unknown>)[name];
}

/**
 * The prototype of a constructor looked up by a runtime name, or `undefined`.
 *
 * Every step out of {@link memberNamed} is checked -- that the value is callable, and that its
 * `prototype` is an object -- so nothing is asserted that was not tested.
 */
export function prototypeNamed(scope: object, name: string): object | undefined {
  const found = memberNamed(scope, name);
  if (typeof found !== "function") return undefined;
  const proto: unknown = (found as { prototype?: unknown }).prototype;
  return typeof proto === "object" && proto !== null ? proto : undefined;
}

/**
 * A parsed JSON value, asserted to be an object.
 *
 * `response.json()` resolves to `unknown` -- the shared implementation cannot know the shape,
 * and inventing one would be a claim rather than a check. This asserts the shape the caller is
 * about to read fields off, so a body that arrived as an array or a string fails here with that
 * sentence instead of as `undefined` three assertions later.
 */
export function jsonObject(value: unknown): Record<string, unknown> {
  assert.ok(
    typeof value === "object" && value !== null && !Array.isArray(value),
    "expected the response body to be a JSON object",
  );
  return value as Record<string, unknown>;
}

import test from "node:test";
import assert from "node:assert/strict";
import {
  HpackDecoder,
  HpackEncoder,
  decodeHpackInteger,
} from "../src/http2/hpack.ts";
import {
  decodeHpackHuffman,
  encodeHpackHuffman,
} from "../src/http2/hpack-huffman.ts";
import type { DecodedHpackHeaderField, HpackHeaderField } from "../src/http2/hpack.ts";

/** A header as the RFC 7541 vectors write it: a name and a value, in order. */
type Pair = readonly [string, string];

function bytes(hex: string): Uint8Array {
  return Uint8Array.from(Buffer.from(hex.replaceAll(" ", ""), "hex"));
}

function hex(value: Uint8Array): string {
  return Buffer.from(value).toString("hex");
}

function fields(...pairs: readonly Pair[]): DecodedHpackHeaderField[] {
  return pairs.map(([name, value]) => ({ name, value, neverIndexed: false }));
}

// Annotated rather than inferred: an array of two-element arrays widens to `string[][]`, and
// every use here destructures a name and a value from a fixed pair.
const firstRequest: readonly Pair[] = [
  [":method", "GET"],
  [":scheme", "http"],
  [":path", "/"],
  [":authority", "www.example.com"],
];
const secondRequest: readonly Pair[] = [...firstRequest, ["cache-control", "no-cache"]];
const thirdRequest: readonly Pair[] = [
  [":method", "GET"],
  [":scheme", "https"],
  [":path", "/index.html"],
  [":authority", "www.example.com"],
  ["custom-key", "custom-value"],
];

test("RFC 7541 integer examples and malformed integer bounds", () => {
  // Each vector is an encoding, a prefix width and the integer it denotes; without the
  // annotation the array widens to `(string | number)[][]` and none of the three has a type.
  const integers: readonly (readonly [string, number, number])[] = [
    ["0a", 5, 10],
    ["1f9a0a", 5, 1337],
    ["2a", 8, 42],
  ];
  for (const [encoded, prefix, expected] of integers) {
    const cursor = { bytes: bytes(encoded), offset: 0 };
    assert.equal(decodeHpackInteger(cursor, prefix), expected);
    assert.equal(cursor.offset, cursor.bytes.length);
  }

  assert.throws(
    () => decodeHpackInteger({ bytes: bytes("1f"), offset: 0 }, 5),
    /Truncated HPACK block/,
  );
  assert.throws(
    () => decodeHpackInteger({ bytes: bytes("1fffffffff7f"), offset: 0 }, 5),
    /exceeds|too long/,
  );
});

test("RFC 7541 literal and indexed field examples", () => {
  const incremental = new HpackDecoder();
  assert.deepEqual(
    incremental.decode(bytes("400a637573746f6d2d6b65790d637573746f6d2d686561646572")),
    fields(["custom-key", "custom-header"]),
  );
  assert.equal(incremental.dynamicTableLength, 1);
  assert.equal(incremental.dynamicTableSize, 55);

  assert.deepEqual(
    new HpackDecoder().decode(bytes("040c2f73616d706c652f70617468")),
    fields([":path", "/sample/path"]),
  );
  assert.deepEqual(new HpackDecoder().decode(bytes("100870617373776f726406736563726574")), [
    { name: "password", value: "secret", neverIndexed: true },
  ]);
  assert.deepEqual(new HpackDecoder().decode(bytes("82")), fields([":method", "GET"]));
});

test("RFC 7541 request sequence without Huffman coding", () => {
  const decoder = new HpackDecoder();
  const encoder = new HpackEncoder(4096, false);
  const vectors: readonly (readonly [string, readonly Pair[]])[] = [
    ["828684410f7777772e6578616d706c652e636f6d", firstRequest],
    ["828684be58086e6f2d6361636865", secondRequest],
    ["828785bf400a637573746f6d2d6b65790c637573746f6d2d76616c7565", thirdRequest],
  ];

  for (const [encoded, expected] of vectors) {
    assert.deepEqual(decoder.decode(bytes(encoded)), fields(...expected));
    assert.equal(hex(encoder.encode(expected.map(([name, value]) => ({ name, value })))), encoded);
  }
  assert.equal(decoder.dynamicTableLength, 3);
  assert.equal(decoder.dynamicTableSize, 164);
});

test("RFC 7541 request sequence with Huffman coding", () => {
  const decoder = new HpackDecoder();
  const encoder = new HpackEncoder();
  const vectors: readonly (readonly [string, readonly Pair[]])[] = [
    ["828684418cf1e3c2e5f23a6ba0ab90f4ff", firstRequest],
    ["828684be5886a8eb10649cbf", secondRequest],
    ["828785bf408825a849e95ba97d7f8925a849e95bb8e8b4bf", thirdRequest],
  ];

  for (const [encoded, expected] of vectors) {
    assert.deepEqual(decoder.decode(bytes(encoded)), fields(...expected));
    assert.equal(hex(encoder.encode(expected.map(([name, value]) => ({ name, value })))), encoded);
  }
  assert.equal(decoder.dynamicTableLength, 3);
  assert.equal(decoder.dynamicTableSize, 164);
});

const firstResponse: readonly Pair[] = [
  [":status", "302"],
  ["cache-control", "private"],
  ["date", "Mon, 21 Oct 2013 20:13:21 GMT"],
  ["location", "https://www.example.com"],
];
const secondResponse: readonly Pair[] = [
  [":status", "307"],
  ["cache-control", "private"],
  ["date", "Mon, 21 Oct 2013 20:13:21 GMT"],
  ["location", "https://www.example.com"],
];
const thirdResponse: readonly Pair[] = [
  [":status", "200"],
  ["cache-control", "private"],
  ["date", "Mon, 21 Oct 2013 20:13:22 GMT"],
  ["location", "https://www.example.com"],
  ["content-encoding", "gzip"],
  ["set-cookie", "foo=ASDJKHQKBZXOQWEOPIUAXQWEOIU; max-age=3600; version=1"],
];

test("RFC 7541 response sequences exercise the 256-byte eviction context", () => {
  const plain = [
    "4803333032580770726976617465611d4d6f6e2c203231204f637420323031332032303a31333a323120474d546e1768747470733a2f2f7777772e6578616d706c652e636f6d",
    "4803333037c1c0bf",
    "88c1611d4d6f6e2c203231204f637420323031332032303a31333a323220474d54c05a04677a69707738666f6f3d4153444a4b48514b425a584f5157454f50495541585157454f49553b206d61782d6167653d333630303b2076657273696f6e3d31",
  ];
  const compressed = [
    "488264025885aec3771a4b6196d07abe941054d444a8200595040b8166e082a62d1bff6e919d29ad171863c78f0b97c8e9ae82ae43d3",
    "4883640effc1c0bf",
    "88c16196d07abe941054d444a8200595040b8166e084a62d1bffc05a839bd9ab77ad94e7821dd7f2e6c7b335dfdfcd5b3960d5af27087f3672c1ab270fb5291f9587316065c003ed4ee5b1063d5007",
  ];
  const expected = [firstResponse, secondResponse, thirdResponse];

  for (const vectors of [plain, compressed]) {
    const decoder = new HpackDecoder(256);
    // Zipped rather than indexed twice: the two arrays are parallel by construction, and
    // `entries` gives both without either index needing to be asserted present.
    for (const [i, vector] of vectors.entries()) {
      assert.deepEqual(decoder.decode(bytes(vector)), fields(...(expected[i] ?? [])));
    }
    assert.equal(decoder.dynamicTableLength, 3);
    assert.equal(decoder.dynamicTableSize, 215);
  }

  const encoder = new HpackEncoder(256, false);
  for (const [i, encoded] of plain.entries()) {
    // Annotated, so `indexing` keeps its literal type: inferred, the object widens it to
    // `string` and the encoder takes only the three spellings `HpackIndexing` allows.
    const source: readonly HpackHeaderField[] = (expected[i] ?? []).map(([name, value]) => ({
      name,
      value,
      indexing: "incremental",
    }));
    assert.equal(hex(encoder.encode(source)), encoded);
  }
});

test("HPACK Huffman codec covers every octet and validates EOS padding", () => {
  const all = Uint8Array.from({ length: 256 }, (_, index) => index);
  const compressed = encodeHpackHuffman(all);
  assert.deepEqual(decodeHpackHuffman(compressed, all.length), all);
  assert.equal(
    hex(encodeHpackHuffman(bytes("7777772e6578616d706c652e636f6d"))),
    "f1e3c2e5f23a6ba0ab90f4ff",
  );

  assert.throws(() => decodeHpackHuffman(bytes("fffffffc"), 1024), /EOS/);
  assert.throws(() => decodeHpackHuffman(bytes("1e"), 1024), /padding/);
  assert.throws(() => decodeHpackHuffman(bytes("ff"), 1024), /padding/);
  assert.throws(() => decodeHpackHuffman(compressed, 255), /configured limit/);
});

test("dynamic table indexing, eviction, and oversized-entry clearing", () => {
  const encoder = new HpackEncoder(80, false);
  const decoder = new HpackDecoder(80);
  const custom = [{ name: "custom-key", value: "custom-value" }];

  const first = encoder.encode(custom);
  assert.deepEqual(decoder.decode(first), fields(["custom-key", "custom-value"]));
  assert.equal(decoder.dynamicTableLength, 1);
  const second = encoder.encode(custom);
  assert.deepEqual(decoder.decode(second), fields(["custom-key", "custom-value"]));
  assert.equal(hex(second), "be");

  const tooLarge = [{ name: "large", value: "x".repeat(80) }];
  assert.deepEqual(decoder.decode(encoder.encode(tooLarge)), fields(["large", "x".repeat(80)]));
  assert.equal(encoder.dynamicTableLength, 0);
  assert.equal(decoder.dynamicTableLength, 0);
});

test("never-indexed and without-indexing policy cannot collapse to indexed fields", () => {
  const encoder = new HpackEncoder(4096, false);
  const decoder = new HpackDecoder();
  const never = encoder.encode([{ name: "authorization", value: "secret", indexing: "never" }]);
  const without = encoder.encode([{ name: ":method", value: "GET", indexing: "without" }]);

  assert.equal(hex(never), "1f0806736563726574");
  assert.equal(hex(without), "0203474554");
  assert.deepEqual(decoder.decode(never), [
    { name: "authorization", value: "secret", neverIndexed: true },
  ]);
  assert.deepEqual(decoder.decode(without), fields([":method", "GET"]));
  assert.equal(encoder.dynamicTableLength, 0);
  assert.equal(decoder.dynamicTableLength, 0);
});

