suite("a clone gives a different stream, and the original keeps its own", async (t) => {
  runtime(t);
  const response = new Response("hello");
  const original = response.body;
  const clone = response.clone();
  // The negative of every case above: sharing the object here would mean one consumer
  // disturbs the other, which is precisely what clone exists to prevent.
  assert.notEqual(clone.body, original, "a clone must not share the original's stream");
  assert.equal(response.body, response.body, "the original still answers with one stream");
  assert.equal(await clone.text(), "hello");
  assert.equal(await response.text(), "hello");
});

suite("headers are one object across reads", (t) => {
  runtime(t);
  const response = new Response("x", { headers: { "x-a": "1" } });
  assert.equal(response.headers, response.headers);
  // Load-bearing for the same reason: a mutation through one read must be visible through
  // another, wherever the guard permits mutation at all.
  const request = new Request("http://example.test/");
  assert.equal(request.headers, request.headers);
  request.headers.set("x-b", "2");
  assert.equal(request.headers.get("x-b"), "2");
});

// The internal machinery that is publicly reachable, and the assertion that there is none.
//
// This file began as a measurement of a deviation too large to close in passing: sixty-three
// members that Web IDL does not define, sitting on interface prototypes because they were
// ordinary public methods. It recorded them, asserted the list could shrink and never grow,
// and named the mechanism that would close it.
//
// The list is empty. What the file is for now is keeping it that way.
//
// **The three mechanisms, in the order they apply.** `#private` where a member is used only
// inside its own class -- free on the frontier, measured, after this file spent a day
// carrying the opposite claim as a reason not to try. **Symbol keys** where it crosses
// classes or modules, because `Object.getOwnPropertyNames` does not report symbols. **Then**
// the enumerability fix, which is only safe once a prototype has no non-standard names left:
// a blanket pass before that point would have enumerated the internals too, making one
// deviation worse to improve the other.
//
// **`tsc` finds every syntactic use of a renamed member and none of the reflective ones.**
// `in`, `typeof x.name`, `hasOwnProperty`, a name in a lookup table. Run that grep first.
//
// The oracle is node's prototype per interface, with the divergences cited individually in
// `webidl-surface.test.mjs` -- five places where node is the best available oracle for
// interface shape and is not the standard.

import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import * as api from "../src/index.ts";
import { prototypeNamed } from "./harness.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

/** Web IDL constants legitimately appear on the interface prototype object. */
const IDL_CONSTANTS = new Set([
  "NONE",
  "CAPTURING_PHASE",
  "AT_TARGET",
  "BUBBLING_PHASE",
  "CONNECTING",
  "OPEN",
  "CLOSING",
  "CLOSED",
]);

/**
 * Members this runtime exposes on an interface prototype that Web IDL does not define.
 *
 * Forty-five, down from sixty-three. Shrinking this table is progress; growing it is a
 * regression. The assertion is exact equality in both directions, so a removal has to
 * change this table and the count below rather than passing silently.
 */
// Empty, and the type is what keeps it meaningful: an untyped `{}` makes every read off it
// `unknown`, so the count assertion below could not add up its entries.
const INTERNAL_PROTOTYPE_MEMBERS: Readonly<Record<string, readonly string[]>> = {};

/**
 * Standard members this runtime has that the oracle does not implement.
 *
 * `CustomEvent.initCustomEvent` is declared in `interfaces/dom.idl` -- marked `// legacy`, but
 * declared -- and node does not provide it. Excluded by citation, not convenience: the claim
 * is checkable against an IDL file pinned in this repository.
 */
const ORACLE_OMITS: Readonly<Record<string, readonly string[]>> = {
  CustomEvent: ["initCustomEvent"],
};

function internalMembers(name: string): string[] {
  const ours = prototypeNamed(api, name);
  const theirs = prototypeNamed(globalThis, name);
  if (ours === undefined || theirs === undefined) return [];
  const mine = Object.getOwnPropertyNames(ours).filter(
    (key) => key !== "constructor" && !IDL_CONSTANTS.has(key),
  );
  const conformant = new Set([
    ...Object.getOwnPropertyNames(theirs),
    ...(ORACLE_OMITS[name] ?? []),
  ]);
  return mine.filter((key) => !conformant.has(key)).sort();
}

suite("the non-standard prototype surface is exactly what is written down", () => {
  for (const [name, expected] of Object.entries(INTERNAL_PROTOTYPE_MEMBERS)) {
    assert.notEqual(prototypeNamed(globalThis, name), undefined, `${name} needs a conformant oracle`);
    assert.deepEqual(
      internalMembers(name),
      expected,
      `${name}: this list may shrink, never grow -- see the header`,
    );
  }
});

suite("no interface has grown a non-standard member", () => {
  // Enumerated from the barrel rather than from a list. The list version was written when the
  // table above held sixty-three entries and only a handful of interfaces were clean; with the
  // table empty it was checking thirteen names and missing every other interface in the
  // runtime -- including `ReadableStream`, which is where all seventeen of the last batch
  // were. A sabotage adding a named method to `ReadableStream` passed it.
  //
  // A gate whose coverage is a list goes stale the moment the thing it guards changes shape.
  const grown: string[] = [];
  for (const [name] of Object.entries(api)) {
    if (!/^[A-Z]/.test(name)) continue;
    if (prototypeNamed(api, name) === undefined) continue;
    if (prototypeNamed(globalThis, name) === undefined) continue;
    const extra = internalMembers(name);
    if (extra.length > 0) grown.push(`${name}: ${extra.join(" ")}`);
  }
  assert.deepEqual(grown, []);
});

suite("the count is stated, so shrinking it is visible", () => {
  const total = Object.values(INTERNAL_PROTOTYPE_MEMBERS).reduce((n, list) => n + list.length, 0);
  // Written as a number rather than derived, so that removing an entry has to change this
  // line too and cannot pass unnoticed as a no-op.
  assert.equal(total, 0);
});

suite("interface members are enumerable, as Web IDL requires", () => {
  // This assertion used to run the other way. It pinned the deviation -- every member
  // non-enumerable, where Web IDL gives operations
  // `{ writable: true, enumerable: true, configurable: true }` -- with a note saying that if
  // it ever started failing, the deviation was fixed and this was what needed updating.
  //
  // It started failing. The blocker was never enumerability itself: it was that a blanket
  // pass would also enumerate the sixty-three internal members, making one deviation worse to
  // improve the other. Those are gone, so this is safe, and the assertion is now the fix.
  const wrong: string[] = [];
  for (const name of ["Headers", "ReadableStream", "Request", "Response", "Event"]) {
    const proto = prototypeNamed(api, name);
    assert.notEqual(proto, undefined, `${name} is not on the platform surface`);
    if (proto === undefined) continue;
    for (const key of Object.getOwnPropertyNames(proto)) {
      if (key === "constructor") continue;
      // A descriptor for a name `getOwnPropertyNames` just returned is always present; saying
      // so out loud beats an assertion, because a missing one would otherwise read as enumerable.
      const descriptor = Object.getOwnPropertyDescriptor(proto, key);
      if (descriptor === undefined || !descriptor.enumerable) {
        wrong.push(`${name}.${key}`);
      }
    }
  }
  assert.deepEqual(wrong, []);
});

import assert from "node:assert/strict";
import test from "node:test";

import { Headers, ReadableStream, URLSearchParams } from "../src/index.ts";

// WebIDL 3.7.10: an interface with an `iterable<>` declaration has one *iterator prototype
// object*, whose [[Prototype]] is %IteratorPrototype%, carrying `next` as a writable,
// enumerable, configurable data property.
//
// `headers-basic.any.js` asserts exactly this upstream and cannot pass here: it computes
// %IteratorPrototype% from `[][Symbol.iterator]()` inside the vm context, `Array` is not among
// the intrinsics the runner injects, and our objects are built in the host realm. Two different
// %IteratorPrototype%s, so the identity check fails for any implementation. The runner says as
// much where it chooses which `Object` to inject: "the real fix is for the harness and the
// implementation to share a realm".
//
// So the requirement is checked here instead, same-realm, where the identity means something.
// Without it the three upstream failures would be the only record of this rule, and they fail
// whether the implementation is right or wrong -- which is no record at all.

const ITERATOR_PROTOTYPE = Object.getPrototypeOf(Object.getPrototypeOf([][Symbol.iterator]()));

const suite = (name: string, fn: () => void | Promise<void>): void => {
  void test(name, fn);
};

function checkIteratorProperties(iterator: IterableIterator<unknown>, tag: string): void {
  const prototype = Object.getPrototypeOf(iterator) as object;
  assert.strictEqual(
    Object.getPrototypeOf(prototype),
    ITERATOR_PROTOTYPE,
    "the iterator prototype object must inherit directly from %IteratorPrototype%",
  );
  const descriptor = Object.getOwnPropertyDescriptor(prototype, "next");
  assert.ok(descriptor, "`next` must be an own property of the iterator prototype object");
  assert.strictEqual(descriptor.configurable, true, "configurable");
  assert.strictEqual(descriptor.enumerable, true, "enumerable");
  assert.strictEqual(descriptor.writable, true, "writable");
  assert.strictEqual((prototype as { [Symbol.toStringTag]?: string })[Symbol.toStringTag], tag);
}

suite("Headers iterators have the Web IDL iterator prototype object", () => {
  const headers = new Headers({ b: "2", a: "1" });
  checkIteratorProperties(headers.keys(), "Headers Iterator");
  checkIteratorProperties(headers.values(), "Headers Iterator");
  checkIteratorProperties(headers.entries(), "Headers Iterator");
  checkIteratorProperties(headers[Symbol.iterator](), "Headers Iterator");
});

suite("one prototype object per interface, shared by every iterator it hands out", () => {
  const headers = new Headers({ a: "1" });
  const keys = Object.getPrototypeOf(headers.keys()) as object;
  assert.strictEqual(Object.getPrototypeOf(headers.values()), keys);
  assert.strictEqual(Object.getPrototypeOf(headers.entries()), keys);
  // A second instance shares it too: the prototype belongs to the interface, not the object.
  assert.strictEqual(Object.getPrototypeOf(new Headers({ z: "9" }).keys()), keys);
  // And it is not the one a *different* interface uses.
  assert.notStrictEqual(Object.getPrototypeOf(new URLSearchParams("a=1").keys()), keys);
});

suite("URLSearchParams iterators have the Web IDL iterator prototype object", () => {
  const params = new URLSearchParams("b=2&a=1");
  checkIteratorProperties(params.keys(), "URLSearchParams Iterator");
  checkIteratorProperties(params.values(), "URLSearchParams Iterator");
  checkIteratorProperties(params.entries(), "URLSearchParams Iterator");
  checkIteratorProperties(params[Symbol.iterator](), "URLSearchParams Iterator");
});

suite("the values and their order are what they were", () => {
  const headers = new Headers({ b: "2", a: "1" });
  assert.deepEqual([...headers.keys()], ["a", "b"]);
  assert.deepEqual([...headers.values()], ["1", "2"]);
  assert.deepEqual([...headers.entries()], [
    ["a", "1"],
    ["b", "2"],
  ]);
  const params = new URLSearchParams("b=2&a=1");
  assert.deepEqual([...params.keys()], ["b", "a"]);
  assert.deepEqual([...params.entries()], [
    ["b", "2"],
    ["a", "1"],
  ]);
});

suite("an iterator is drained once and stays done", () => {
  const keys = new Headers({ a: "1" }).keys();
  assert.deepEqual(keys.next(), { value: "a", done: false });
  assert.deepEqual(keys.next(), { value: undefined, done: true });
  assert.deepEqual(keys.next(), { value: undefined, done: true });
});

suite("`next` on something that is not one of these iterators throws", () => {
  const prototype = Object.getPrototypeOf(new Headers({ a: "1" }).keys()) as {
    next: () => unknown;
  };
  assert.throws(() => prototype.next.call({}), TypeError);
  assert.throws(() => prototype.next.call(Object.create(prototype)), TypeError);
});

suite("iteration observes mutation the way it did before", () => {
  // `Headers` re-reads its sorted view each step, so a header added mid-iteration is seen.
  const headers = new Headers({ a: "1" });
  const seen: string[] = [];
  for (const key of headers.keys()) {
    seen.push(key);
    if (key === "a") headers.append("b", "2");
  }
  assert.deepEqual(seen, ["a", "b"]);
});

// Web IDL 3.7.11, the asynchronous half of the same rule. `async-iterator.any.js` asserts it
// upstream and fails on the same realm mismatch as `headers-basic`: it computes
// %AsyncIteratorPrototype% from an `async function*` inside the vm context. Three of its four
// claims about the shape are realm-independent and all three were failing for real reasons --
// a class prototype inherits `Object.prototype`, carries an own `constructor`, and has
// non-enumerable methods.
const ASYNC_ITERATOR_PROTOTYPE = Object.getPrototypeOf(
  Object.getPrototypeOf(async function* () {}).prototype,
);

suite("the ReadableStream async iterator has the Web IDL async iterator prototype", () => {
  const iterator = new ReadableStream().values();
  const prototype = Object.getPrototypeOf(iterator) as object;
  assert.strictEqual(
    Object.getPrototypeOf(prototype),
    ASYNC_ITERATOR_PROTOTYPE,
    "must inherit directly from %AsyncIteratorPrototype%",
  );
  assert.deepEqual(
    Object.getOwnPropertyNames(prototype).sort(),
    ["next", "return"],
    "exactly `next` and `return`, so no own `constructor`",
  );
  for (const name of ["next", "return"] as const) {
    const descriptor = Object.getOwnPropertyDescriptor(prototype, name);
    assert.ok(descriptor, name);
    assert.strictEqual(descriptor.enumerable, true, `${name} enumerable`);
    assert.strictEqual(descriptor.configurable, true, `${name} configurable`);
    assert.strictEqual(descriptor.writable, true, `${name} writable`);
  }
  const asIndexed = iterator as unknown as Record<string, { name: string; length: number }>;
  assert.strictEqual(asIndexed["next"]?.name, "next");
  assert.strictEqual(asIndexed["next"]?.length, 0);
  assert.strictEqual(asIndexed["return"]?.name, "return");
  assert.strictEqual(asIndexed["return"]?.length, 1);
  assert.strictEqual(
    (iterator as unknown as { throw?: unknown }).throw,
    undefined,
    "`throw` is not part of the declaration",
  );
});

suite("reshaping the async iterator prototype did not stop it iterating", async () => {
  const stream = new ReadableStream<string>({
    start(controller) {
      controller.enqueue("a");
      controller.enqueue("b");
      controller.close();
    },
  });
  const seen: string[] = [];
  for await (const chunk of stream) seen.push(chunk);
  assert.deepEqual(seen, ["a", "b"]);
});

// `integrity` was accepted on a Request and never checked. A caller who wrote
// integrity metadata got no verification and no error, which is the one failure mode
// they cannot detect. These tests cover the check and, as much as the check itself,
// that an unverifiable requirement stops the request.
//
// Host evidence for the shared algorithm and one provider's digest.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import http from "node:http";
import { createHash } from "node:crypto";

import {
  createHostNodeWebPlatform,
  hostNodeDigest,
} from "../host/node-runtime.ts";
import {
  digestMatches,
  parseIntegrity,
} from "../src/provider.ts";
import type { WebPlatformRuntime } from "../src/provider.ts";
import type { WebPlatformOptions } from "../src/provider.ts";
import { causeText } from "./harness.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const BODY = "integrity subject";

function base64(algorithm: string, text: string): string {
  return createHash(algorithm).update(text).digest("base64");
}

async function origin(t: TestContext, body: string = BODY): Promise<string> {
  const server = http.createServer((_request, response) => {
    response.writeHead(200, { "content-type": "text/plain" });
    response.end(body);
  });
  server.listen(0, "127.0.0.1");
  await new Promise<void>((resolve) => server.once("listening", () => resolve()));
  t.after(() => new Promise<void>((resolve) => server.close(() => resolve())));
  // `address()` is a union with a pipe path and `null`; a TCP listener that has emitted
  // `listening` is always the object form, and narrowing says so rather than assuming it.
  const address = server.address();
  assert.ok(address !== null && typeof address === "object", "a listening TCP server has an address");
  return `http://127.0.0.1:${address.port}/`;
}

function runtimeWith(t: TestContext, digest: WebPlatformOptions["digest"]): WebPlatformRuntime {
  const api = createHostNodeWebPlatform({ digest });
  t.after(() => api.close());
  return api;
}

// A separate helper rather than `runtimeWith(t, undefined)`: passing `undefined`
// explicitly triggers a default parameter, so that spelling built a runtime that did
// have a provider and the fail-closed assertions passed for the wrong reason.
function runtimeWithoutDigest(t: TestContext): WebPlatformRuntime {
  const api = createHostNodeWebPlatform({});
  t.after(() => api.close());
  assert.equal(api.requestContext.digest, undefined, "this runtime must have no provider");
  return api;
}

function because(pattern: RegExp): (error: unknown) => boolean {
  return (error: unknown) => {
    assert.match(causeText(error), pattern);
    return true;
  };
}

suite("integrity metadata parses to the strongest algorithm present", () => {
  assert.deepEqual(parseIntegrity(""), []);
  assert.deepEqual(parseIntegrity("   "), []);
  // Unknown algorithms are dropped rather than failing otherwise-valid metadata.
  assert.deepEqual(parseIntegrity("md5-abc"), []);
  assert.deepEqual(parseIntegrity("sha256-AAA"), [{ algorithm: "sha256", digest: "AAA" }]);
  // A stronger entry present is the one that applies, and weaker ones drop out.
  assert.deepEqual(parseIntegrity("sha256-AAA sha512-BBB"), [
    { algorithm: "sha512", digest: "BBB" },
  ]);
  // Several entries of the strongest algorithm all remain; any match is a match.
  assert.deepEqual(parseIntegrity("sha384-AAA sha384-BBB sha256-CCC"), [
    { algorithm: "sha384", digest: "AAA" },
    { algorithm: "sha384", digest: "BBB" },
  ]);
  // Options after `?` carry no defined meaning and must not cause a failure.
  assert.deepEqual(parseIntegrity("sha256-AAA?ct=text/plain"), [
    { algorithm: "sha256", digest: "AAA" },
  ]);
  assert.deepEqual(parseIntegrity("SHA256-AAA"), [{ algorithm: "sha256", digest: "AAA" }]);
  assert.deepEqual(parseIntegrity("sha256-"), []);
  assert.deepEqual(parseIntegrity("notanentry"), []);
});

suite("a digest matches across padding and both base64 alphabets", () => {
  const bytes = new Uint8Array(createHash("sha256").update(BODY).digest());
  const standard = base64("sha256", BODY);
  assert.equal(digestMatches(bytes, parseIntegrity("sha256-" + standard)), true);
  // base64url spelling of the same digest.
  const urlSafe = standard.replace(/\+/g, "-").replace(/\//g, "_");
  assert.equal(digestMatches(bytes, parseIntegrity("sha256-" + urlSafe)), true);
  // Unpadded spelling of the same digest.
  assert.equal(digestMatches(bytes, parseIntegrity("sha256-" + standard.replace(/=+$/, ""))), true);
  // A digest of the right length that is simply wrong.
  assert.equal(digestMatches(bytes, parseIntegrity("sha256-" + base64("sha256", "other"))), false);
  // Any entry matching is enough.
  const several = parseIntegrity(`sha256-${base64("sha256", "other")} sha256-${standard}`);
  assert.equal(digestMatches(bytes, several), true);
  assert.equal(digestMatches(bytes, parseIntegrity("sha256-!!!not-base64!!!")), false);
});

suite("a matching response is returned and its bytes are the verified ones", async (t) => {
  const url = await origin(t);
  const api = runtimeWith(t, hostNodeDigest);
  const response = await api.fetch(url, { integrity: "sha256-" + base64("sha256", BODY) });
  assert.equal(response.status, 200);
  assert.equal(await response.text(), BODY);
});

suite("every supported algorithm verifies", async (t) => {
  const url = await origin(t);
  const api = runtimeWith(t, hostNodeDigest);
  for (const algorithm of ["sha256", "sha384", "sha512"]) {
    const response = await api.fetch(url, {
      integrity: `${algorithm}-${base64(algorithm, BODY)}`,
    });
    assert.equal(await response.text(), BODY);
  }
});

suite("a mismatching response is a network error and its body is never delivered", async (t) => {
  const url = await origin(t);
  const api = runtimeWith(t, hostNodeDigest);
  await assert.rejects(
    api.fetch(url, { integrity: "sha256-" + base64("sha256", "a different body") }),
    because(/did not match the requested integrity/),
  );
});

suite("the strongest algorithm is the one enforced", async (t) => {
  const url = await origin(t);
  const api = runtimeWith(t, hostNodeDigest);
  // A correct sha256 alongside a wrong sha512 must fail: the sha512 entry is the one
  // that applies, and a weaker correct entry does not rescue it.
  await assert.rejects(
    api.fetch(url, {
      integrity: `sha256-${base64("sha256", BODY)} sha512-${base64("sha512", "wrong")}`,
    }),
    because(/did not match the requested integrity/),
  );
  // The reverse ordering behaves the same, so this is about strength and not position.
  await assert.rejects(
    api.fetch(url, {
      integrity: `sha512-${base64("sha512", "wrong")} sha256-${base64("sha256", BODY)}`,
    }),
    because(/did not match the requested integrity/),
  );
});

suite("metadata naming only unknown algorithms places no requirement", async (t) => {
  const url = await origin(t);
  const api = runtimeWith(t, hostNodeDigest);
  const response = await api.fetch(url, { integrity: "md5-" + base64("sha256", "anything") });
  assert.equal(await response.text(), BODY);
});

suite("a check that cannot be performed stops the request", async (t) => {
  const url = await origin(t);
  // No digest provider at all.
  const none = runtimeWithoutDigest(t);
  await assert.rejects(
    none.fetch(url, { integrity: "sha256-" + base64("sha256", BODY) }),
    because(/cannot verify it/),
  );
  // A provider that does not offer the requested algorithm.
  const partial = runtimeWith(t, {
    algorithms: ["sha256"],
    digest: hostNodeDigest.digest.bind(hostNodeDigest),
  });
  await assert.rejects(
    partial.fetch(url, { integrity: "sha512-" + base64("sha512", BODY) }),
    because(/algorithm is not available: sha512/),
  );
  // And the same environment still serves a request it can verify.
  const ok = await partial.fetch(url, { integrity: "sha256-" + base64("sha256", BODY) });
  assert.equal(await ok.text(), BODY);
});

suite("a request without integrity is unaffected by the absence of a provider", async (t) => {
  const url = await origin(t);
  const api = runtimeWithoutDigest(t);
  assert.equal(await (await api.fetch(url)).text(), BODY);
});

// A digest is a base64 value, and until this was checked at parse time a digest holding
// any code unit above U+00FF reached `encodeByteString` at *match* time and threw
// `TypeError: Expected an HTTP ByteString`. `integrity` is a DOMString a script sets, so
// `new Request(url, { integrity: "sha256-\u0100" })` turned an integrity check into an
// exception thrown from a layer below the one the caller was addressing.
//
// Found by the NodeJS lane reporting three bugs of exactly this shape in their own
// base64 and hex -- decoding a string's characters where node decodes its bytes. This
// codebase does not have their bug, because `encodeByteString` refuses rather than
// masking; it had the other half of it, where the refusal escaped as the wrong error.
test("a digest that is not a base64 value is discarded, not thrown over", () => {
  for (const metadata of [
    "sha256-\u0100",
    "sha256-\u{1F600}",
    "sha256-!!!!",
    "sha384-\u00ff\u0100",
  ]) {
    assert.deepEqual(parseIntegrity(metadata), [], metadata);
  }
});

test("the base64url alphabet and padding are digests, not junk", () => {
  // `-` and `_` are the URL alphabet's substitutes for `+` and `/`, and the match path
  // converts them; rejecting them here would break every caller using that spelling.
  const entries = parseIntegrity("sha256-YWJj-ZGVm_Z2hp=");
  assert.equal(entries.length, 1);
  assert.equal(entries[0]?.digest, "YWJj-ZGVm_Z2hp=");
});

test("metadata that parses to nothing means no check, not a check that fails", () => {
  // Worth asserting rather than assuming, because it is the security-relevant half of
  // discarding invalid entries: this is the Subresource Integrity behaviour, and a
  // caller wanting "invalid metadata must fail" has to validate before setting it.
  assert.deepEqual(parseIntegrity("sha256-!!!!"), []);
  assert.deepEqual(parseIntegrity("md5-abcd"), [], "an unsupported algorithm, the same way");
  assert.deepEqual(parseIntegrity("nonsense"), []);
});

// Interceptor order, as claims with their own controls.
//
// The plan asks for "explicit ordering and ownership". Composition order was defined --
// array order is outer to inner -- but which order to compose in was not, and an
// ordering rule nobody can falsify is a preference wearing a rule's clothes.
//
// So each test runs *both* arrangements: the documented one, and the swap. A test that
// only exercised the right order would pass just as happily if the order did not matter.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import {
  AbortController,
  AuthenticationInterceptor,
  composeFetchTransport,
  ResponseErrorInterceptor,
  RetryInterceptor,
  TransportError,
} from "../src/index.ts";
import type {
  FetchTransport,
  TransportRequest,
  TransportResponse,
} from "../src/fetch/transport.ts";
import type { Scheduler } from "../src/provider/primitives.ts";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import { must } from "./harness.ts";
import type { RetryOptions } from "../src/dispatch/retry.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

class ImmediateScheduler implements Scheduler {
  readonly delays: number[] = [];
  readonly errors: unknown[] = [];

  enqueue(task: () => void): void {
    queueMicrotask(task);
  }

  delay(milliseconds: number, task: () => void): { cancel(): void } {
    this.delays.push(milliseconds);
    queueMicrotask(task);
    return { cancel() {} };
  }

  reportError(error: unknown): void {
    this.errors.push(error);
  }
}

const urls = createHostNodePrimitives().urls;

function request(overrides: Partial<TransportRequest> = {}): TransportRequest {
  return {
    // A parsed record rather than a `{ href }` stub: `TransportRequest.url` is a `URLRecord`,
    // and a stub satisfied nothing but the one field this file happened to read.
    url: urls.parse("https://order.test/resource"),
    method: "GET",
    headers: [],
    body: null,
    bodyLength: null,
    signal: new AbortController().signal,
    ...overrides,
  };
}

/** Answers each status in turn, then 200 for ever. Counts what it was asked. */
function scripted(statuses: readonly number[]): FetchTransport & { attempts: TransportRequest[] } {
  const attempts: TransportRequest[] = [];
  let index = 0;
  return {
    attempts,
    async dispatch(value: TransportRequest): Promise<TransportResponse> {
      attempts.push(value);
      const status = statuses[index++];
      if (status === undefined || status === 200) {
        return { status: 200, statusText: "OK", headers: [], body: null };
      }
      if (status === 401) {
        const authorized = value.headers.some(([name]) => name === "authorization");
        if (authorized) return { status: 200, statusText: "OK", headers: [], body: null };
        return {
          status: 401,
          statusText: "Unauthorized",
          headers: [["www-authenticate", 'Basic realm="r"']],
          body: null,
        };
      }
      return { status, statusText: "Failure", headers: [], body: null };
    },
  };
}

const retrying = (options: Partial<RetryOptions> = {}): RetryInterceptor =>
  new RetryInterceptor({
    scheduler: new ImmediateScheduler(),
    maxRetries: options.maxRetries ?? 3,
    minTimeoutMilliseconds: 0,
    ...options,
  });

const authenticating = (options = {}) =>
  new AuthenticationInterceptor({ authenticate: () => "Basic dXNlcjpw", ...options });

suite("response-error outside retry lets a retryable status be retried", async () => {
  // Documented order: the error conversion sees the *final* status.
  const inner = scripted([503, 200]);
  const outside = composeFetchTransport(inner, [new ResponseErrorInterceptor(), retrying()]);
  const response = await outside.dispatch(request());
  assert.equal(response.status, 200);
  assert.equal(inner.attempts.length, 2, "the 503 was retried");

  // Swapped: response-error is inside, so it throws before retry has a status to act on.
  const other = scripted([503, 200]);
  const swapped = composeFetchTransport(other, [retrying(), new ResponseErrorInterceptor()]);
  await assert.rejects(() => swapped.dispatch(request()), { name: "ResponseError" });
  assert.equal(other.attempts.length, 1, "and nothing was retried");
});

suite("response-error outside authentication lets a challenge be answered", async () => {
  const inner = scripted([401]);
  const outside = composeFetchTransport(inner, [
    new ResponseErrorInterceptor(),
    authenticating(),
  ]);
  const response = await outside.dispatch(request());
  assert.equal(response.status, 200);
  assert.equal(inner.attempts.length, 2);
  assert.equal(
    must(inner.attempts[1], "the request was retried").headers.some(([name]) => name === "authorization"),
    true,
  );

  // Swapped: a 401 is a challenge, and thrown from the inside it is an error the
  // authenticator is never offered.
  const other = scripted([401]);
  let consulted = false;
  const swapped = composeFetchTransport(other, [
    authenticating({
      authenticate: () => {
        consulted = true;
        return "Basic dXNlcjpw";
      },
    }),
    new ResponseErrorInterceptor(),
  ]);
  await assert.rejects(() => swapped.dispatch(request()), { name: "ResponseError" });
  assert.equal(consulted, false, "the challenge never reached the authenticator");
  assert.equal(other.attempts.length, 1);
});

suite("authentication outside retry keeps the total attempts down", async () => {
  // Both orders work; the difference is arithmetic, and it runs the opposite way to the
  // intuition that a challenge is best answered close to the transport. A 401 is not a
  // retryable status, so retry never loops on a challenge -- what happens instead is
  // that with retry outside, every retry of a *retryable* failure re-runs the whole
  // authentication exchange from unauthenticated.
  //
  // This is the arrangement the documentation recommended until this test measured it.
  const script = [503, 401, 503, 401, 503, 401, 503, 401, 200];

  const documented = scripted(script);
  const outside = composeFetchTransport(documented, [
    authenticating(),
    retrying({ maxRetries: 2 }),
  ]);
  const documentedResult = await outside
    .dispatch(request())
    .then((response) => response.status, () => "threw");

  const other = scripted(script);
  const swapped = composeFetchTransport(other, [retrying({ maxRetries: 2 }), authenticating()]);
  const swappedResult = await swapped
    .dispatch(request())
    .then((response) => response.status, () => "threw");

  assert.ok(
    documented.attempts.length < other.attempts.length,
    `authentication outside retry should cost fewer attempts: ${documented.attempts.length} vs ${other.attempts.length}`,
  );
  // And it is not merely cheaper: on this script it is the arrangement that succeeds.
  assert.equal(documentedResult, 200);
  assert.equal(swappedResult, "threw");
});

suite("a transport error is retried the same way whichever of the two is outside", async () => {
  // The control on the control: retry and authentication do not interact at all when
  // the failure is not a status, so a difference in the tests above has to come from
  // the challenge handling rather than from composition overhead.
  const failing = (() => {
    let calls = 0;
    return {
      get calls() {
        return calls;
      },
      async dispatch() {
        calls++;
        if (calls <= 2) throw new TransportError("ECONNRESET", "reset");
        return { status: 200, statusText: "OK", headers: [], body: null };
      },
    };
  })();
  const outside = composeFetchTransport(failing, [retrying(), authenticating()]);
  const response = await outside.dispatch(request());
  assert.equal(response.status, 200);
  assert.equal(failing.calls, 3);
});

// The JSON parser, against node and against the grammar.
//
// Two oracles, deliberately. Node answers what a conforming engine produces for text that is
// valid, which is the strongest check available for values and key order. The pinned spec text
// at `runtime/web-platform/third_party/ecma262/json-25.5.txt` answers what is *valid*, which
// node cannot be asked about directly -- every case below that must be rejected is a place
// JavaScript's grammar is wider than JSON's, and a parser that reached for `eval` or a
// permissive scanner would accept it.
//
// Every literal control character and space-like character in the corpora below is written as
// a `\u` escape. Earlier in this lane a fixture was written with raw control bytes and became
// unreadable in the source; these are exactly the cases where the byte is the point.
//
// **This file imports the TypeScript source, not the build output**, which node runs directly
// under type stripping -- `erasableSyntaxOnly` is already set repository-wide, which is the
// flag that guarantees it can. The reason is not convenience: a test that reads a built emit
// can be run against the *previous* emit when a change fails to type-check, and this lane has
// had three separate readings spoiled by exactly that. Importing source makes a mutation
// always live. Type checking is not lost -- `check.sh` runs `tsc` as its own step.
import assert from "node:assert/strict";
import test from "node:test";

import { parseJsonText } from "../../ecmascript/src/json/parse.ts";
import type { JsonValue } from "../../ecmascript/src/json/value.ts";
import { stringifyJsonValue } from "../../ecmascript/src/json/stringify.ts";
import { INVALID, keyOrder, must, plain, VALID } from "./json-corpus.ts";

const suite = (name: string, fn: () => void): void => {
  test(name, fn);
};

suite("valid JSON agrees with node on value and on key order", () => {
  for (const text of VALID) {
    let expected;
    try {
      expected = JSON.parse(text);
    } catch (error) {
      assert.fail(
        `node rejected a case listed as valid: ${JSON.stringify(text)} (${String(error)})`,
      );
    }
    const actual = plain(parseJsonText(text));
    assert.deepEqual(actual, expected, `value for ${JSON.stringify(text)}`);
    assert.deepEqual(keyOrder(actual), keyOrder(expected), `key order for ${JSON.stringify(text)}`);
  }
});

suite("invalid JSON is rejected, and node rejects it too", () => {
  for (const text of INVALID) {
    // The second assertion is the control. Without it this only says the parser is strict,
    // not that it is strict about the right things -- a parser that rejected everything
    // would pass.
    assert.throws(
      () => JSON.parse(text),
      SyntaxError,
      `node accepted a case listed as invalid: ${JSON.stringify(text)}`,
    );
    assert.throws(
      () => parseJsonText(text),
      SyntaxError,
      `this parser accepted ${JSON.stringify(text)}`,
    );
  }
});

test("rows that spell their sibling's keys share its list, and a row that does not builds its own", () => {
  // Observable only as identity, which is the point: the shared list is the allocation saved.
  const rows = parseJsonText('[{"id":1,"name":"a"},{"id":2,"name":"b"},{"id":3,"nick":"c"}]').items;
  const [first, second, third] = rows as [JsonValue, JsonValue, JsonValue];
  assert.equal(second.keys, first.keys, "the second row shares the first's keys");
  assert.notEqual(third.keys, first.keys, "a row with another key has its own list");
  assert.deepEqual([...third.keys], ["id", "nick"]);
  assert.deepEqual([...first.keys], ["id", "name"]);
});

suite("an array of records reads each key the way the row before it spelled it, or afresh", () => {
  // `readKey` takes a key from the previous sibling's keys when the source spells it plainly.
  // The valid half: rows that agree, disagree, reorder, extend, shorten, nest, and repeat a key,
  // where only the comparison of units decides what is taken. The invalid half is the
  // correctness argument for "plainly": a key that needed an escape in one row must not let a
  // raw quote, newline or backslash through in the next.
  const valid = [
    '[{"id":1,"name":"a"},{"id":2,"name":"b"},{"id":3,"name":"c"}]',
    '[{"id":1,"name":"a"},{"name":"b","id":2}]',
    '[{"ab":1},{"a":2},{"abc":3},{"ab":4}]',
    '[{"a":1},{"a":2,"b":3},{"a":4}]',
    '[{"a":1},{},{"a":2}]',
    '[{"a":1,"b":2},{"a":3}]',
    '[{"a":1,"b":2},{"a":3,"a":4}]',
    '[{"a":{"x":1}},{"a":{"x":2,"y":3}}]',
    '[{"a":1,"a":2},{"a":3,"a":4}]',
    '[{"10":1,"b":2},{"10":3,"b":4}]',
    '[{"a\\"b":1},{"a\\"b":2}]',
    '[{"a\\nb":1},{"a\\nb":2}]',
    '[{"a\\\\b":1},{"a\\\\b":2}]',
    '[{"\\u0061":1},{"a":2},{"\\u0061":3}]',
    '[{"a\\\\b":1},{"a\\b":2}]',
    '[ { "id" : 1 } , { "id" : 2 } ]',
    '[[{"k":1}],[{"k":2}]]',
    '[{"k":1},[1],{"k":2}]',
  ];
  for (const text of valid) {
    const actual = plain(parseJsonText(text));
    const expected = JSON.parse(text);
    assert.deepEqual(actual, expected, `value for ${JSON.stringify(text)}`);
    assert.deepEqual(keyOrder(actual), keyOrder(expected), `key order for ${JSON.stringify(text)}`);
  }
  const invalid = [
    '[{"a\\"b":1},{"a"b":2}]',
    '[{"a\\nb":1},{"a\nb":2}]',
    '[{"a\\\\q":1},{"a\\q":2}]',
    '[{"id":1},{"id" 2}]',
    '[{"id":1},{"id":]',
    '[{"id":1},{"id',
  ];
  for (const text of invalid) {
    assert.throws(() => JSON.parse(text), SyntaxError, `node accepted ${JSON.stringify(text)}`);
    assert.throws(
      () => parseJsonText(text),
      SyntaxError,
      `this parser accepted ${JSON.stringify(text)}`,
    );
  }
});

suite("a lone surrogate survives parsing as a code unit", () => {
  // The plan is explicit that parsing operates on UTF-16 code units and that a lone surrogate
  // is not normalised through UTF-8 to U+FFFD. Comparing against node covers the value; this
  // checks the code unit, which `deepEqual` over two identical replacement characters would
  // not have distinguished.
  const parsed = parseJsonText('"\\ud800"');
  assert.equal(parsed.text.length, 1);
  assert.equal(parsed.text.charCodeAt(0), 0xd800);
  assert.equal(parsed.text, JSON.parse('"\\ud800"'));
});

suite("integer-like keys come first, in numeric order", () => {
  // `OrdinaryOwnPropertyKeys`, which the plan names directly. An insertion-ordered map passes
  // every value assertion above and fails this one.
  const text = '{"b":1,"10":2,"9":3,"a":4,"0":5}';
  const parsed = parseJsonText(text);
  assert.deepEqual([...parsed.keys], ["0", "9", "10", "b", "a"]);
  assert.deepEqual(Object.keys(JSON.parse(text)), ["0", "9", "10", "b", "a"]);
});

suite("names that only look like indices stay in the string bucket", () => {
  const text = '{"01":1,"-1":2,"1.5":3,"4294967295":4,"4294967294":5,"z":6}';
  const parsed = parseJsonText(text);
  assert.deepEqual([...parsed.keys], Object.keys(JSON.parse(text)));
  // 4294967294 is 2^32 - 2 and is an index; 4294967295 is 2^32 - 1 and is not.
  assert.equal(must(parsed.keys[0]), "4294967294");
});

suite("a repeated key takes the later value and keeps the earlier position", () => {
  const text = '{"a":1,"b":2,"a":3}';
  const parsed = parseJsonText(text);
  assert.deepEqual([...parsed.keys], ["a", "b"]);
  assert.equal(must(parsed.values[0]).number, 3);
  assert.deepEqual(plain(parsed), JSON.parse(text));
});

suite("source spans cover exactly the text of each value", () => {
  // The spans are what 25.5.2.4 turns into `context.source` for the reviver. Checked now,
  // while there is one producer, rather than after a consumer starts depending on them.
  const text = '{"a":  123 , "b":[true]}';
  const root = parseJsonText(text);
  assert.equal(text.slice(root.start, root.end), text);
  const first = must(root.values[0]);
  const second = must(root.values[1]);
  assert.equal(text.slice(first.start, first.end), "123");
  assert.equal(text.slice(second.start, second.end), "[true]");
  const inner = must(second.items[0]);
  assert.equal(text.slice(inner.start, inner.end), "true");
});

suite("deep nesting does not exhaust a native stack", () => {
  // The reason the parser carries an explicit frame stack. A recursive-descent parser dies
  // here, and the plan requires that it not die on one target while surviving on another.
  // 100k levels is far past any recursive implementation and far short of a memory problem.
  const depth = 100000;
  const text = "[".repeat(depth) + "]".repeat(depth);
  let node: JsonValue = parseJsonText(text);
  let seen = 0;
  while (node.items.length > 0) {
    node = must(node.items[0]);
    seen++;
  }
  assert.equal(seen, depth - 1);
});

suite("a syntax error names the offset it was found at", () => {
  // A plain `SyntaxError`, as 25.5.2.1 requires and as every engine throws, with the offset in
  // the message rather than in an invented numeric property.
  const thrownBy = (text: string): SyntaxError => {
    try {
      parseJsonText(text);
    } catch (error) {
      return error as SyntaxError;
    }
    return assert.fail(`expected ${JSON.stringify(text)} to throw`);
  };
  assert.ok(thrownBy("[1,]") instanceof SyntaxError);
  assert.match(thrownBy("[1,]").message, /position 3$/);
  assert.match(thrownBy('{"a" 1}').message, /position 5$/);
  assert.match(thrownBy("nul").message, /position 0$/);
  // The constructor is `SyntaxError` itself, not a subclass: node's is too, and code that
  // switches on `error.constructor` should not be able to tell the two apart.
  assert.equal(thrownBy("[1,]").constructor, SyntaxError);
});

suite("the scan and the map agree, on both sides of the threshold", () => {
  // Duplicate detection changes shape at a member count, so there are two implementations of
  // one rule and nothing in the corpus is wide enough to reach the second. Every size from
  // well below the threshold to well above is built with duplicates and array-index keys in
  // it, and compared with node -- which has one implementation and therefore cannot drift.
  for (let width = 1; width <= 40; width++) {
    const parts: string[] = [];
    for (let at = 0; at < width; at++) {
      parts.push(`"k${at}":${at}`);
      // A duplicate every third key, and index-shaped keys interleaved so both key spaces
      // cross the threshold rather than only the string one.
      if (at % 3 === 0) parts.push(`"k${at}":${at * 100}`);
      if (at % 4 === 0) parts.push(`"${at}":${at * 1000}`);
      if (at % 8 === 0) parts.push(`"${at}":${at * 10000}`);
    }
    const text = `{${parts.join(",")}}`;
    const node: unknown = JSON.parse(text);
    assert.deepEqual(keyOrder(plain(parseJsonText(text))), keyOrder(node), `width ${width} order`);
    assert.equal(stringifyJsonValue(parseJsonText(text)), JSON.stringify(node), `width ${width} values`);
  }
});

suite("a wide object of entirely repeated keys collapses to one member", () => {
  // The path where every lookup hits. Above the threshold this exercises the map's hit branch,
  // which the interleaved test above reaches only every third key.
  for (const width of [4, 16, 17, 64, 500]) {
    const text = `{${new Array(width).fill('"same":1').join(",")}}`;
    const parsed = parseJsonText(text);
    assert.deepEqual([...parsed.keys], ["same"], `width ${width}`);
    assert.equal(stringifyJsonValue(parsed), JSON.stringify(JSON.parse(text)), `width ${width}`);
  }
});

suite("an index key repeated past the threshold is still deduplicated", () => {
  // Reaching the map on the *index* side needs sixteen distinct array-index names in one
  // object, and then a repeat among them. Nothing else here has both: the interleaved test
  // above stays under the threshold on that side, and the ordering test below has no repeats.
  // A sabotage that stopped recording index keys in the map survived because of exactly that.
  const parts: string[] = [];
  for (let at = 0; at < 40; at++) parts.push(`"${at}":${at}`);
  parts.push('"0":999', '"20":888', '"39":777');
  const text = `{${parts.join(",")}}`;
  const parsed = parseJsonText(text);
  assert.equal(parsed.keys.length, 40, "a repeat added a member");
  assert.deepEqual(keyOrder(plain(parsed)), keyOrder(JSON.parse(text)));
  assert.equal(stringifyJsonValue(parsed), JSON.stringify(JSON.parse(text)));
});

suite("a wide object keeps ordinary-own-property-keys order", () => {
  // The ordering rule and the threshold interact: index keys are collected separately and
  // sorted, and the map is built per key space. A wide object with indices scattered through it
  // is where a mistake in that interaction shows.
  const parts: string[] = [];
  for (let at = 0; at < 60; at++) {
    parts.push(`"z${at}":${at}`);
    parts.push(`"${100 - at}":${at}`);
  }
  const text = `{${parts.join(",")}}`;
  assert.deepEqual(keyOrder(plain(parseJsonText(text))), keyOrder(JSON.parse(text)));
});

suite("the integer fast path agrees with node at and past its boundary", () => {
  // `readNumber` accumulates an integer while it scans and skips the substring, but only while
  // the value stays inside the integers a double holds exactly. The boundary is a digit count,
  // and a digit count is exactly the kind of constant that is right in the corpus and wrong one
  // either side of it -- so this walks every length across it rather than sampling.
  for (let digits = 1; digits <= 21; digits++) {
    for (const lead of ["1", "9"]) {
      const text = lead + "0".repeat(digits - 1);
      assert.equal(
        parseJsonText(text).number,
        JSON.parse(text),
        `${digits} digits, leading ${lead}`,
      );
      assert.equal(parseJsonText("-" + text).number, JSON.parse("-" + text), `negative, ${digits}`);
    }
    // The largest and smallest value of each width, which is where an accumulator that has
    // started to round disagrees first.
    const nines = "9".repeat(digits);
    assert.equal(parseJsonText(nines).number, JSON.parse(nines), `${digits} nines`);
  }

  // The values around `Number.MAX_SAFE_INTEGER`, named rather than generated.
  for (const text of [
    "9007199254740991",
    "9007199254740992",
    "9007199254740993",
    "999999999999999",
    "1000000000000000",
    "12345678901234567890",
  ]) {
    assert.equal(parseJsonText(text).number, JSON.parse(text), text);
  }
});

suite("negative zero survives the fast path as negative zero", () => {
  // `-0` is a number JSON can write, and the fast path returns it by negating an accumulated
  // zero. `assert.equal` does not separate it from `0`, so this asks the question directly.
  assert.equal(Object.is(parseJsonText("-0").number, -0), true, "-0 must stay negative zero");
  assert.equal(Object.is(parseJsonText("0").number, 0), true);
  assert.equal(Object.is(JSON.parse("-0"), -0), true, "node agrees");
  // And it serializes back as `0`, which is what 25.5.4.2 and `Number::toString` give.
  assert.equal(stringifyJsonValue(parseJsonText("-0")), "0");
});

suite("a number with a fraction or an exponent takes the slow path and still matches node", () => {
  // The fast path must decline these rather than accumulate a wrong answer, so each is compared
  // against node exactly.
  for (const text of [
    "1.5",
    "0.1",
    "1e3",
    "1E3",
    "1e+3",
    "1e-3",
    "-1.5e-7",
    "123456789012345.6",
    "1234567890123456789.5",
    "0e0",
    "-0.0",
    "5e-324",
    "1.7976931348623157e308",
  ]) {
    assert.equal(parseJsonText(text).number, JSON.parse(text), text);
  }
});

// `OrdinaryOwnPropertyKeys` ordering at a size where the algorithm shows.
//
// `objectValue` used to reach this with `Array#sort` and a comparator, which is not lowered --
// it was the only refusal between the whole parser and the compiled axis, so the sort is now
// hand-written. Two things have to hold afterwards and only one of them is obvious.
//
// This asserts the order, at a size where a sort that is merely *nearly* right shows up: four
// thousand shuffled indices interleaved with a string key.
//
// **It does not assert the complexity, and an earlier version of this comment claimed it did.**
// The sort is a merge rather than an insertion because an object carrying thousands of
// array-index keys is an ordinary document -- a sparse array written as an object is exactly
// that. But a timing assertion cannot check that here: swapping in an insertion sort runs this
// same case in 6.9ms, because four thousand elements is nowhere near where n^2 bites. Sizing up
// until it did would make the test slow *and* timing-dependent on a machine three sessions
// share, which is a flaky test bought with a real one. The complexity is a design decision
// recorded at `ascendingByIndex`; this is the correctness half.
suite("many array-index keys stay in ascending numeric order, and do not go quadratic", () => {
  // Shuffled deterministically, so the sort has real work to do and a failure reproduces.
  const indices: number[] = [];
  for (let at = 0; at < 4000; at++) indices.push(at);
  let state = 12345;
  for (let at = indices.length - 1; at > 0; at--) {
    state = (state * 1664525 + 1013904223) >>> 0;
    const swap = state % (at + 1);
    const held = indices[at] as number;
    indices[at] = indices[swap] as number;
    indices[swap] = held;
  }

  const members: string[] = [];
  for (const index of indices) members.push(`"${index}":${index}`);
  // One string key, to prove the index keys still sort ahead of it rather than merely among
  // themselves.
  members.push('"z":0');
  const text = `{${members.join(",")}}`;

  const parsed = parseJsonText(text);

  // The graph's own key list against node's, which is the ordering claim directly. `keyOrder`
  // walks a materialised value and is the right tool for nested shapes; here the object is flat
  // and the keys are the whole assertion.
  assert.deepEqual([...parsed.keys], Object.keys(JSON.parse(text) as object));
  assert.equal(parsed.keys.length, 4001);
  assert.equal(parsed.keys[0], "0");
  assert.equal(parsed.keys[3999], "3999");
  assert.equal(parsed.keys[4000], "z", "a non-index key sorts after every index key");
});

import assert from "node:assert/strict";
import { describe, it } from "node:test";

import { parseJsonText } from "../../ecmascript/src/json/parse.ts";
import { parsePlainText, toPlainValue } from "../../ecmascript/src/json/plain.ts";
import { INVALID, VALID } from "./json-corpus.ts";

// `parsePlainText` is a second route through the same grammar: it builds ordinary objects
// directly where `toPlainValue(parseJsonText(t))` builds the erased graph and walks it. Two
// routes is two places for a specification bug, and the only thing that makes it safe is
// holding them against each other -- and against node -- on every case there is.
//
// So this file asserts equivalence rather than behaviour. A case that belongs to JSON itself
// goes in `json-corpus.ts` with the others; what is here is the claim that the fast route
// cannot disagree with the canonical one.

/** The canonical route, spelled once. */
function canonical(text: string): unknown {
  return toPlainValue(parseJsonText(text));
}

function messageOf(run: () => unknown): string {
  try {
    run();
  } catch (error) {
    return (error as Error).message;
  }
  return "<no error>";
}

describe("parsePlainText agrees with the canonical route", () => {
  it("produces the same value as the graph route for every valid case", () => {
    for (const text of VALID) {
      assert.deepStrictEqual(
        parsePlainText(text),
        canonical(text),
        `one-pass and graph routes disagree on ${text}`,
      );
    }
  });

  it("produces the same value as node for every valid case", () => {
    for (const text of VALID) {
      assert.deepStrictEqual(
        parsePlainText(text),
        JSON.parse(text),
        `one-pass route disagrees with node on ${text}`,
      );
    }
  });

  it("orders keys identically to the graph route, index keys included", () => {
    for (const text of VALID) {
      const fast = parsePlainText(text);
      if (typeof fast !== "object" || fast === null || Array.isArray(fast)) continue;
      assert.deepStrictEqual(
        Object.keys(fast),
        Object.keys(canonical(text) as object),
        `key order differs on ${text}`,
      );
    }
  });

  it("fails with the identical message on every invalid case", () => {
    for (const text of INVALID) {
      const fast = messageOf(() => parsePlainText(text));
      const slow = messageOf(() => canonical(text));
      assert.notStrictEqual(fast, "<no error>", `accepted invalid text ${text}`);
      assert.strictEqual(fast, slow, `error text differs on ${text}`);
    }
  });
});

describe("the cases where building directly could differ", () => {
  it("keeps __proto__ as an own data property rather than setting the prototype", () => {
    const parsed = parsePlainText('{"__proto__":{"polluted":true}}') as Record<string, unknown>;
    assert.strictEqual(Object.getPrototypeOf(parsed), Object.prototype);
    assert.ok(Object.hasOwn(parsed, "__proto__"));
    assert.deepStrictEqual(parsed["__proto__"], { polluted: true });
    assert.strictEqual(({} as Record<string, unknown>)["polluted"], undefined);
    assert.deepStrictEqual(parsed, canonical('{"__proto__":{"polluted":true}}'));
  });

  it("gives a repeated key its first position and its last value", () => {
    const text = '{"b":1,"a":2,"b":3}';
    const parsed = parsePlainText(text) as Record<string, unknown>;
    assert.deepStrictEqual(Object.keys(parsed), ["b", "a"]);
    assert.strictEqual(parsed["b"], 3);
    assert.deepStrictEqual(parsed, canonical(text));
    assert.deepStrictEqual(parsed, JSON.parse(text));
  });

  it("puts array-index keys first in numeric order, as OrdinaryOwnPropertyKeys requires", () => {
    const text = '{"10":"a","x":"b","9":"c","2":"d"}';
    const parsed = parsePlainText(text) as Record<string, unknown>;
    assert.deepStrictEqual(Object.keys(parsed), ["2", "9", "10", "x"]);
    assert.deepStrictEqual(parsed, canonical(text));
    assert.deepStrictEqual(Object.keys(parsed), Object.keys(JSON.parse(text) as object));
  });

  it("keeps a key that only looks like an index in insertion order", () => {
    const text = '{"01":"a","b":"c","-1":"d","1.5":"e","4294967295":"f"}';
    const parsed = parsePlainText(text) as Record<string, unknown>;
    assert.deepStrictEqual(Object.keys(parsed), Object.keys(JSON.parse(text) as object));
    assert.deepStrictEqual(parsed, canonical(text));
  });

  it("gives an empty container the right identity and prototype", () => {
    assert.deepStrictEqual(parsePlainText("{}"), {});
    assert.deepStrictEqual(parsePlainText("[]"), []);
    assert.ok(Array.isArray(parsePlainText("[]")));
    assert.strictEqual(Object.getPrototypeOf(parsePlainText("{}")), Object.prototype);
  });

  it("nests deeply without recursing", () => {
    const depth = 20000;
    const text = "[".repeat(depth) + "]".repeat(depth);
    let node = parsePlainText(text) as unknown[];
    let seen = 1;
    while (node.length === 1) {
      node = node[0] as unknown[];
      seen++;
    }
    assert.strictEqual(seen, depth);
  });

  it("preserves lone surrogates exactly as the graph route does", () => {
    for (const text of ['"\\ud800"', '"\\udfff"', '"\\ud800\\ud800"', '"\\udbff\\udfff"']) {
      assert.strictEqual(parsePlainText(text), canonical(text));
      assert.strictEqual(parsePlainText(text), JSON.parse(text));
    }
  });
});

describe("randomised documents", () => {
  // A deterministic generator, so a failure is reproducible from the seed printed with it.
  function makeRandom(seed: number): () => number {
    let state = seed >>> 0;
    return () => {
      state = (state * 1664525 + 1013904223) >>> 0;
      return state / 0x100000000;
    };
  }

  const ALPHABET: readonly string[] = [
    "a",
    "z",
    " ",
    '"',
    "\\",
    "\n",
    "\t",
    "é",
    "日",
    "\u{1f600}",
    "\ud800",
    "",
  ];

  const KEYS: readonly string[] = ["a", "b", "0", "1", "10", "__proto__", "x y", '"', "日"];

  function build(random: () => number, depth: number): unknown {
    const pick = random();
    if (depth > 4 || pick < 0.3) {
      const leaf = random();
      if (leaf < 0.15) return null;
      if (leaf < 0.3) return random() < 0.5;
      if (leaf < 0.65) return Math.floor(random() * 2000) - 1000;
      if (leaf < 0.8) return (random() * 1e6 - 5e5) / 7;
      let text = "";
      const length = Math.floor(random() * 6);
      for (let at = 0; at < length; at++) {
        text += ALPHABET[Math.floor(random() * ALPHABET.length)] as string;
      }
      return text;
    }
    const count = Math.floor(random() * 5);
    if (pick < 0.65) {
      const items: unknown[] = [];
      for (let at = 0; at < count; at++) items.push(build(random, depth + 1));
      return items;
    }
    const object: Record<string, unknown> = {};
    for (let at = 0; at < count; at++) {
      object[KEYS[Math.floor(random() * KEYS.length)] as string] = build(random, depth + 1);
    }
    return object;
  }

  it("agrees with the graph route and with node on 2000 generated documents", () => {
    for (let seed = 1; seed <= 2000; seed++) {
      const random = makeRandom(seed);
      const text = JSON.stringify(build(random, 0));
      assert.deepStrictEqual(parsePlainText(text), canonical(text), `seed ${seed}: ${text}`);
      assert.deepStrictEqual(parsePlainText(text), JSON.parse(text), `seed ${seed}: ${text}`);
    }
  });

  it("agrees on truncations of generated documents, which are mostly invalid", () => {
    let rejected = 0;
    for (let seed = 1; seed <= 400; seed++) {
      const random = makeRandom(seed);
      const text = JSON.stringify(build(random, 0));
      for (let cut = 1; cut < text.length; cut++) {
        const piece = text.slice(0, cut);
        const fast = messageOf(() => parsePlainText(piece));
        const slow = messageOf(() => canonical(piece));
        assert.strictEqual(fast, slow, `seed ${seed} cut ${cut}: ${piece}`);
        if (fast !== "<no error>") rejected++;
      }
    }
    // A run where nothing was malformed would assert nothing and pass.
    assert.ok(rejected > 1000, `expected truncations to be rejected, got ${rejected}`);
  });
});

// The arbitrary-value bridge, against node.
//
// Everything here is a direct comparison with the host `JSON`, because for this file the host
// is not merely an oracle -- it is the same specification clause running on the same values, so
// a disagreement is a bug in one of them rather than a profile difference. The cases that are
// not a comparison are the ones where node's behaviour is unobservable through `JSON.stringify`
// alone: which errors propagate, and what `toPlainValue` builds.
import assert from "node:assert/strict";
import test from "node:test";

import { parseJsonText } from "../../ecmascript/src/json/parse.ts";
import { stringifyPlain, toPlainValue } from "../../ecmascript/src/json/plain.ts";
import { jsonRawJSON } from "../../ecmascript/src/json/json.ts";
import { VALID } from "./json-corpus.ts";

const suite = (name: string, fn: () => void): void => {
  test(name, fn);
};

suite("serializing a parsed document matches node for the whole corpus", () => {
  for (const text of VALID) {
    const value: unknown = JSON.parse(text);
    assert.equal(stringifyPlain(value), JSON.stringify(value), `stringify of ${JSON.stringify(text)}`);
  }
});

suite("materializing a parsed graph matches what node parsed", () => {
  for (const text of VALID) {
    assert.deepEqual(toPlainValue(parseJsonText(text)), JSON.parse(text), `materialize ${JSON.stringify(text)}`);
  }
});

suite("a materialized object has ordinary prototypes and own keys in order", () => {
  // `deepEqual` is blind to both of these. `JSON.parse` produces objects with
  // `Object.prototype`, and a `__proto__` member is an own property rather than a prototype
  // change -- which is what separates `CreateDataPropertyOrThrow` from assignment.
  const value = toPlainValue(parseJsonText('{"b":1,"2":2,"a":3,"0":4}'));
  assert.equal(Object.getPrototypeOf(value as object), Object.prototype);
  assert.deepEqual(Object.keys(value as object), Object.keys(JSON.parse('{"b":1,"2":2,"a":3,"0":4}')));
  assert.deepEqual(Object.keys(value as object), ["0", "2", "b", "a"]);

  const proto = toPlainValue(parseJsonText('{"__proto__":{"x":1}}')) as Record<string, unknown>;
  assert.equal(Object.getPrototypeOf(proto), Object.prototype, "the prototype was not replaced");
  assert.deepEqual(Object.getOwnPropertyNames(proto), ["__proto__"]);
  assert.equal(Object.getOwnPropertyDescriptor(proto, "__proto__")?.enumerable, true);
});

suite("an array materializes with its length and its indices", () => {
  const value = toPlainValue(parseJsonText("[1,[2],{}]")) as unknown[];
  assert.equal(Array.isArray(value), true);
  assert.equal(value.length, 3);
  assert.deepEqual(value, [1, [2], {}]);
});

const TRANSFORMED: unknown[] = [
  { toJSON: () => 42 },
  { toJSON: (key: string) => key },
  new Date(0),
  { at: new Date(86400000) },
  [new Date(0)],
  { toJSON: () => ({ nested: [1, 2] }) },
  Object.create({ toJSON: () => "inherited" }),
];

suite("toJSON is honoured wherever node honours it", () => {
  for (const value of TRANSFORMED) {
    assert.equal(stringifyPlain(value), JSON.stringify(value), `toJSON for ${Object.prototype.toString.call(value)}`);
  }
});

suite("values with no serialization are omitted, or null inside an array", () => {
  const cases: unknown[] = [
    undefined,
    Symbol("x"),
    () => 1,
    { a: undefined, b: 1, c: Symbol("y"), d: () => 1 },
    [undefined, 1, Symbol("y"), () => 1],
    [],
    {},
  ];
  for (let at = 0; at < cases.length; at++) {
    // Labelled by index rather than by value: `String(aSymbol)` throws, and a label that
    // throws replaces the assertion with an error about the label.
    assert.equal(stringifyPlain(cases[at]), JSON.stringify(cases[at]), `omission case ${at}`);
  }
});

suite("a boxed primitive is unwrapped rather than serialized as an object", () => {
  const cases: unknown[] = [
    new Number(1),
    new String("a"),
    new Boolean(true),
    { n: new Number(-0), s: new String(""), b: new Boolean(false) },
    [new Number(NaN)],
  ];
  for (const value of cases) {
    assert.equal(stringifyPlain(value), JSON.stringify(value), "boxed primitive");
  }
});

suite("a BigInt is refused rather than dropped, exactly as node refuses it", () => {
  assert.throws(() => stringifyPlain(1n), TypeError);
  assert.throws(() => JSON.stringify(1n), TypeError);
  assert.throws(() => stringifyPlain({ a: 1n }), TypeError);
  assert.throws(() => JSON.stringify({ a: 1n }), TypeError);
  // A `toJSON` on a BigInt is reached before the refusal, so this one does not throw.
  const value = Object.assign(Object.create(null), {});
  void value;
  assert.equal(stringifyPlain({ a: { toJSON: () => 1 } }), '{"a":1}');
});

suite("a cycle is a TypeError, at whatever depth it closes", () => {
  const direct: Record<string, unknown> = {};
  direct.self = direct;
  const deep: Record<string, unknown> = { a: { b: {} } };
  ((deep.a as Record<string, unknown>).b as Record<string, unknown>).back = deep;
  const arrayCycle: unknown[] = [1];
  arrayCycle.push(arrayCycle);
  const mixed: Record<string, unknown> = { list: [] as unknown[] };
  (mixed.list as unknown[]).push(mixed);

  for (const value of [direct, deep, arrayCycle, mixed]) {
    assert.throws(() => stringifyPlain(value), TypeError, "cycle not caught");
    assert.throws(() => JSON.stringify(value), TypeError, "node agrees");
  }
});

suite("the same object twice is not a cycle", () => {
  // The stack holds the open containers, not every container seen. A shared subobject appears
  // twice and is serialized twice; only an enclosing container is a cycle. An implementation
  // using a seen-set rather than a stack rejects this valid document.
  const shared = { x: 1 };
  const value = { a: shared, b: shared, c: [shared, shared] };
  assert.equal(stringifyPlain(value), JSON.stringify(value));
});

suite("a throwing getter propagates its own error", () => {
  class CustomError extends Error {}
  const value = {
    get boom(): number {
      throw new CustomError("bar");
    },
  };
  assert.throws(() => stringifyPlain(value), CustomError);
  assert.throws(() => JSON.stringify(value), CustomError);
});

suite("the key handed to user code is a string, even for an array element", () => {
  // The existing replacer suite logs `${key}` into a template, which stringifies a number
  // exactly as it stringifies a string -- so it would pass unchanged if an array element's
  // index reached user code as a number. 25.5.4.2 says the key is a String, and node agrees.
  // This is the only assertion that can tell the difference.
  test("a replacer is called with a string index", () => {
    const seen: string[] = [];
    stringifyPlain(["a", "b"], {
      replacer(this: unknown, key: string, held: unknown): unknown {
        seen.push(typeof key);
        return held;
      },
    });
    const theirs: string[] = [];
    JSON.stringify(["a", "b"], function (this: unknown, key: string, held: unknown): unknown {
      theirs.push(typeof key);
      return held;
    });
    assert.deepEqual(seen, theirs);
    assert.ok(seen.every((kind) => kind === "string"), `saw ${seen.join(",")}`);
  });

  test("toJSON is called with a string index", () => {
    const seen: string[] = [];
    const element = {
      toJSON(this: unknown, key: string): unknown {
        seen.push(typeof key);
        return 1;
      },
    };
    stringifyPlain([element, element]);
    const theirs: string[] = [];
    JSON.stringify([
      { toJSON(this: unknown, key: string): unknown { theirs.push(typeof key); return 1; } },
      { toJSON(this: unknown, key: string): unknown { theirs.push(typeof key); return 1; } },
    ]);
    assert.deepEqual(seen, theirs);
    assert.ok(seen.every((kind) => kind === "string"), `saw ${seen.join(",")}`);
  });
});

suite("a replacer sees the same keys, values and this as node's", () => {
  const shapes: unknown[] = [
    { a: 1, b: [1, 2], c: { d: null } },
    [1, [2, [3]]],
    { "": 0 },
    // A `toJSON` holder, so the log shows whether the replacer runs before or after step 2.
    { a: new Date(0) },
    // Boxed primitives, so the log shows whether step 4 runs before or after step 3. The
    // replacer must see the wrapper object, not the primitive: unwrapping first is invisible
    // to the output text and visible only here.
    { n: new Number(1), s: new String("a"), b: new Boolean(false) },
    [new Number(1)],
  ];
  for (const value of shapes) {
    const mine: string[] = [];
    const theirs: string[] = [];
    const record = (log: string[]) =>
      function (this: unknown, key: string, held: unknown): unknown {
        log.push(`${key}:${Array.isArray(held) ? "array" : typeof held}:${typeof this}`);
        return held;
      };
    assert.equal(
      stringifyPlain(value, { replacer: record(mine) }),
      JSON.stringify(value, record(theirs)),
    );
    assert.deepEqual(mine, theirs, "replacer call sequence");
  }
});

suite("a replacer that drops values matches node", () => {
  const value = { a: 1, b: 2, c: [1, 2, 3] };
  const drop = (key: string, held: unknown): unknown => (key === "b" || key === "1" ? undefined : held);
  assert.equal(stringifyPlain(value, { replacer: drop }), JSON.stringify(value, drop));
  assert.equal(stringifyPlain(value, { replacer: () => undefined }), JSON.stringify(value, () => undefined));
});

suite("a property list selects and orders keys as node does", () => {
  const value = { a: 1, b: 2, c: { a: 9, d: 8 } };
  for (const list of [["b", "a"], ["c", "a"], [], ["a", "zz"], ["d", "a"]]) {
    assert.equal(
      stringifyPlain(value, { propertyList: list }),
      JSON.stringify(value, list),
      `property list ${JSON.stringify(list)}`,
    );
  }
});

suite("the indent argument matches node for arbitrary values", () => {
  const shapes: unknown[] = [
    { a: 1, b: [1, 2], c: { d: { e: [] } } },
    [],
    {},
    [[], {}, [{}]],
    { a: {} },
  ];
  for (const space of [0, 1, 2, 10, 11, -1, NaN, "", "\t", "0123456789X"]) {
    for (const value of shapes) {
      assert.equal(
        stringifyPlain(value, { space }),
        JSON.stringify(value, null, space),
        `space ${JSON.stringify(space)}`,
      );
    }
  }
});

suite("the surrogate cases the fetch fixture pins come out byte for byte", () => {
  // `fetch/api/response/response-static-json.any.js` asserts these three as byte arrays, so
  // they are the exact strings that decide whether `Response.json` passes upstream.
  assert.equal(stringifyPlain("\u{1d306}"), '"\u{1d306}"');
  assert.equal(stringifyPlain("\udf06\ud834"), '"\\udf06\\ud834"');
  assert.equal(stringifyPlain("\udead"), '"\\udead"');
  for (const sample of ["\u{1d306}", "\udf06\ud834", "\udead"]) {
    assert.equal(stringifyPlain(sample), JSON.stringify(sample), "node agrees");
  }
});

suite("a rawJSON node splices its text into an arbitrary document", () => {
  const document = { a: jsonRawJSON("1e999"), b: [jsonRawJSON('"x"')] };
  assert.equal(stringifyPlain(document), '{"a":1e999,"b":["x"]}');
});

suite("deep nesting serializes and materializes without a native stack", () => {
  const depth = 20000;
  const text = "[".repeat(depth) + "]".repeat(depth);
  const materialized = toPlainValue(parseJsonText(text));
  assert.equal(stringifyPlain(materialized), text);
});

// Serialization, against node.
//
// The central assertion is a round trip: for every valid input in the shared corpus,
// `stringify(parse(text))` must equal what node produces for the same text. That single
// comparison covers escaping, number formatting, key order and container syntax at once, and
// it fails for any of them — which is the point, since a serializer that is wrong about
// exactly one escape is otherwise very hard to catch by reading.
//
// The specific assertions after it are for the cases the round trip cannot reach: characters
// that never appear in the corpus, and the `space` argument, which has no parse-side input.
import assert from "node:assert/strict";
import test from "node:test";

import { parseJsonText } from "../../ecmascript/src/json/parse.ts";
import {
  quoteJSONString,
  resolveGap,
  stringifyJsonValue,
} from "../../ecmascript/src/json/stringify.ts";
import { VALID } from "./json-corpus.ts";

const suite = (name: string, fn: () => void): void => {
  test(name, fn);
};

suite("every valid input round-trips exactly as node serializes it", () => {
  for (const text of VALID) {
    const expected = JSON.stringify(JSON.parse(text));
    const actual = stringifyJsonValue(parseJsonText(text));
    assert.equal(actual, expected, `round trip of ${JSON.stringify(text)}`);
  }
});

suite("the indent argument matches node for every gap it accepts", () => {
  // `space` has no parse-side input, so the round trip above never exercises it.
  const gaps: (number | string)[] = [0, 1, 2, 4, 10, 11, 100, -1, 1.9, NaN, "", "\t", "ab", "0123456789X"];
  const shapes = [
    '{"a":1,"b":[1,2],"c":{"d":{"e":[]}}}',
    "[]",
    "{}",
    "[[],{},[{}]]",
    '{"a":{}}',
    "[1]",
  ];
  for (const space of gaps) {
    for (const text of shapes) {
      const expected = JSON.stringify(JSON.parse(text), null, space);
      const actual = stringifyJsonValue(parseJsonText(text), { gap: resolveGap(space) });
      assert.equal(actual, expected, `${JSON.stringify(text)} with space ${JSON.stringify(space)}`);
    }
  }
});

suite("Table 78 is exactly seven escapes, and the rest go through UnicodeEscape", () => {
  // The table holds `\b` `\t` `\n` `\f` `\r` `\"` `\\` and nothing else. Vertical tab is the
  // case that catches an implementation which assumed the C escape set: U+000B has no short
  // form here and must come out as a Unicode escape.
  assert.equal(quoteJSONString("\b\t\n\f\r"), '"\\b\\t\\n\\f\\r"');
  assert.equal(quoteJSONString('"'), '"\\""');
  assert.equal(quoteJSONString("\\"), '"\\\\"');
  assert.equal(quoteJSONString("\v"), '"\\u000b"');
  assert.equal(quoteJSONString("\0"), '"\\u0000"');
  assert.equal(quoteJSONString("\u001f"), '"\\u001f"');
  // A solidus is not in the table: the parser accepts `\/` and the serializer never writes it.
  assert.equal(quoteJSONString("/"), '"/"');
  for (const sample of ["\b\t\n\f\r", '"', "\\", "\v", "\0", "\u001f", "/", "a/b"]) {
    assert.equal(quoteJSONString(sample), JSON.stringify(sample), `node agrees for ${JSON.stringify(sample)}`);
  }
});

suite("a lone surrogate is escaped and a well-formed pair is not", () => {
  // The other half of the parser preserving one. Escaping the unpaired half and leaving the
  // pair alone is what makes text with an astral character survive a round trip while text
  // with a broken pair stays broken rather than becoming U+FFFD.
  assert.equal(quoteJSONString("\ud800"), '"\\ud800"');
  assert.equal(quoteJSONString("\udfff"), '"\\udfff"');
  assert.equal(quoteJSONString("\ud800a"), '"\\ud800a"');
  assert.equal(quoteJSONString("\udc00\ud800"), '"\\udc00\\ud800"');
  assert.equal(quoteJSONString("😀"), '"😀"');
  for (const sample of ["\ud800", "\udfff", "\ud800a", "\udc00\ud800", "😀", "a\ud800b"]) {
    assert.equal(quoteJSONString(sample), JSON.stringify(sample), `node agrees for ${escapeAll(sample)}`);
  }
});

suite("numbers use the canonical conversion, and non-finite ones become null", () => {
  // `1e400` is valid JSON, parses to Infinity, and serializes back to `null` -- so it is a
  // case that legitimately does not round-trip, and the corpus contains it for that reason.
  assert.equal(stringifyJsonValue(parseJsonText("1e400")), "null");
  assert.equal(stringifyJsonValue(parseJsonText("-1e400")), "null");
  assert.equal(stringifyJsonValue(parseJsonText("-0")), "0");
  assert.equal(stringifyJsonValue(parseJsonText("1e-400")), "0");
  // Shortest round-tripping, not `%.17g`: these are the values that separate the two.
  for (const text of ["0.1", "1e21", "1e-7", "5e-324", "1.7976931348623157e308", "123456789012345678"]) {
    assert.equal(
      stringifyJsonValue(parseJsonText(text)),
      JSON.stringify(JSON.parse(text)),
      `number formatting for ${text}`,
    );
  }
});

suite("deep nesting serializes without exhausting a native stack", () => {
  // The serializer carries an explicit frame stack for the same reason the parser does. A
  // recursive one dies here, and the plan requires that it not die on one target and survive
  // on another.
  const depth = 50000;
  const text = "[".repeat(depth) + "]".repeat(depth);
  assert.equal(stringifyJsonValue(parseJsonText(text)), text);
});

suite("an indented container puts its closing bracket at the outer indent", () => {
  // 25.5.4.5 and 25.5.4.6 place the *outer* indent before the closing brace and the inner one
  // before each member. Getting that backwards produces output that still parses, which is
  // why it is asserted against exact text rather than by re-parsing.
  assert.equal(
    stringifyJsonValue(parseJsonText('{"a":[1,{"b":2}]}'), { gap: resolveGap(2) }),
    '{\n  "a": [\n    1,\n    {\n      "b": 2\n    }\n  ]\n}',
  );
  assert.equal(stringifyJsonValue(parseJsonText('{"a":{}}'), { gap: resolveGap(2) }), '{\n  "a": {}\n}');
});

function escapeAll(value: string): string {
  let out = "";
  for (let at = 0; at < value.length; at++) {
    out += "\\u" + value.charCodeAt(at).toString(16).padStart(4, "0");
  }
  return out;
}

// `JSON.parse` with a reviver, `JSON.stringify` with a replacer, and the raw-JSON pair.
//
// The reviver is compared with node on the two things that are hard to get right and easy to
// get plausibly wrong: the **order** values are offered in, and which of them carry a
// `source`. Both are recorded as a sequence on each side and compared, because a reviver that
// visits the right values in the wrong order transforms most documents identically.
import assert from "node:assert/strict";
import test from "node:test";

import {
  isRawJSON,
  jsonParse,
  jsonRawJSON,
  jsonStringify,
} from "../../ecmascript/src/json/json.ts";
import { parseJsonText } from "../../ecmascript/src/json/parse.ts";
import { JsonValue } from "../../ecmascript/src/json/value.ts";
import { must, plain } from "./json-corpus.ts";

const suite = (name: string, fn: () => void): void => {
  test(name, fn);
};

const SHAPES = [
  '{"a":1,"b":[1,2],"c":{"d":null}}',
  "[1,[2,[3]]]",
  '{"":0,"x":"y"}',
  "[]",
  "{}",
  '{"b":1,"0":2,"a":3}',
  '[{"a":[true,false]}]',
];

suite("a reviver sees the same values in the same order as node", () => {
  for (const text of SHAPES) {
    const theirs: string[] = [];
    JSON.parse(text, function (key, value) {
      theirs.push(`${key}:${Array.isArray(value) ? "array" : typeof value}`);
      return value;
    });
    const mine: string[] = [];
    jsonParse(text, (key, value) => {
      const shape = value.kind === "array" ? "array" : value.kind === "object" ? "object" : value.kind;
      mine.push(`${key}:${shape}`);
      return value;
    });
    // Node reports an object as "object" and an array as "array"; the graph names each kind,
    // so only the container words are normalised before comparing.
    const normalised = theirs.map((entry) =>
      entry
        .replace(/:object$/, ":object")
        .replace(/:number$/, ":number")
        .replace(/:string$/, ":string")
        .replace(/:boolean$/, ":boolean"),
    );
    const mineNormalised = mine.map((entry) => entry.replace(/:null$/, ":object"));
    assert.deepEqual(mineNormalised, normalised, `reviver order for ${text}`);
  }
});

suite("only a non-object carries a source, and it is its own text", () => {
  // 25.5.2.4 reaches the `source` branch only when the value is not an Object. Recording the
  // pairs on both sides catches both halves: a missing source on a primitive, and a source
  // invented for a container.
  for (const text of SHAPES) {
    const theirs: string[] = [];
    // The bundled lib types for `JSON.parse` predate the source-text proposal and declare a
    // two-parameter reviver, so the third argument is reached through a cast. The runtime has
    // it -- that is what this test is comparing against.
    type SourceReviver = (key: string, value: unknown, context: { source?: string }) => unknown;
    const parseWithSource = JSON.parse as unknown as (text: string, reviver: SourceReviver) => unknown;
    parseWithSource(text, (key, value, context) => {
      theirs.push(`${key}=${context.source ?? "-"}`);
      return value;
    });
    const mine: string[] = [];
    jsonParse(text, (key, value, context) => {
      mine.push(`${key}=${context.source ?? "-"}`);
      return value;
    });
    assert.deepEqual(mine, theirs, `sources for ${text}`);
  }
});

suite("an identity reviver leaves the document alone", () => {
  for (const text of SHAPES) {
    const revived = must(jsonParse(text, (_key, value) => value));
    assert.deepEqual(plain(revived), JSON.parse(text), `identity for ${text}`);
  }
});

suite("dropping an object key removes it", () => {
  const text = '{"a":1,"b":2,"c":3}';
  const revived = must(jsonParse(text, (key, value) => (key === "b" ? undefined : value)));
  assert.deepEqual(plain(revived), JSON.parse(text, (key, value) => (key === "b" ? undefined : value)));
  assert.deepEqual([...revived.keys], ["a", "c"]);
});

suite("dropping an array element leaves a hole, not a shorter array", () => {
  // 25.5.2.4 deletes rather than splices, so the array keeps its length and the gap
  // serializes as `null`. An implementation that removed the element produces `[1,3]`, which
  // is a different document and passes any test that only checks the surviving values.
  const text = "[1,2,3]";
  const drop = (key: string, value: unknown): unknown => (key === "1" ? undefined : value);
  const revived = must(jsonParse(text, (key, value) => (key === "1" ? undefined : value)));
  assert.equal(revived.items.length, 3);
  assert.equal(must(revived.items[1]).kind, "hole");
  assert.equal(jsonStringify(revived), JSON.stringify(JSON.parse(text, drop)));
  assert.equal(jsonStringify(revived), "[1,null,3]");
});

suite("a reviver replacing a value is reflected in its parent", () => {
  const text = '{"a":1,"b":{"c":2}}';
  const revived = must(
    jsonParse(text, (key, value) =>
      value.kind === "number" ? JsonValue.numberValue(value.number * 10, 0, 0) : value,
    ),
  );
  assert.deepEqual(
    plain(revived),
    JSON.parse(text, (_key, value) => (typeof value === "number" ? value * 10 : value)),
  );
});

suite("a replacer omits values, and an omitted array element becomes null", () => {
  const text = '{"a":1,"b":2,"c":[1,2,3]}';
  const mine = jsonStringify(parseJsonText(text), {
    replacer: (key, value) => (key === "b" || key === "1" ? undefined : value),
  });
  const theirs = JSON.stringify(JSON.parse(text), (key, value) =>
    key === "b" || key === "1" ? undefined : value,
  );
  assert.equal(mine, theirs);
  assert.equal(mine, '{"a":1,"c":[1,null,3]}');
});

suite("a replacer discarding the root produces no output at all", () => {
  assert.equal(jsonStringify(parseJsonText('{"a":1}'), { replacer: () => undefined }), undefined);
  assert.equal(JSON.stringify(JSON.parse('{"a":1}'), () => undefined), undefined);
});

suite("a property list selects keys and imposes its own order", () => {
  // 25.5.4.5 walks the list rather than the object, so the list decides the order too — which
  // is the half an implementation that filters the object's keys gets wrong.
  const text = '{"a":1,"b":2,"c":3}';
  for (const list of [["b", "a"], ["c"], [], ["a", "zz", "b"]]) {
    const mine = jsonStringify(parseJsonText(text), { propertyList: list });
    const theirs = JSON.stringify(JSON.parse(text), list);
    assert.equal(mine, theirs, `property list ${JSON.stringify(list)}`);
  }
});

suite("rawJSON emits its text verbatim and refuses anything that is not a primitive", () => {
  const raw = jsonRawJSON('{"a":1}'.slice(5, 6));
  assert.equal(isRawJSON(raw), true);
  assert.equal(jsonStringify(raw), "1");
  assert.equal(jsonStringify(jsonRawJSON("1e999")), "1e999", "the text is not re-formatted");
  assert.equal(jsonStringify(jsonRawJSON('"a\\u0041b"')), '"a\\u0041b"', "escapes are not rewritten");

  for (const bad of ["", " 1", "1 ", "[1]", "{}", "[", "+1", "-", "truer", "nul", "TRUE"]) {
    assert.throws(() => jsonRawJSON(bad), SyntaxError, `rawJSON accepted ${JSON.stringify(bad)}`);
  }
  for (const good of ["1", "-1", "1.5", "1e3", '""', '"a"', "true", "false", "null"]) {
    assert.equal(isRawJSON(jsonRawJSON(good)), true, `rawJSON rejected ${JSON.stringify(good)}`);
  }
});

suite("isRawJSON is false for everything the parser produces", () => {
  for (const text of ["1", '"a"', "true", "null", "[]", "{}"]) {
    assert.equal(isRawJSON(parseJsonText(text)), false, text);
  }
});

suite("a raw value nested in a document is spliced in unchanged", () => {
  const document = JsonValue.objectValue(
    ["a", "b"],
    [jsonRawJSON("1e999"), parseJsonText('"x"')],
    0,
    0,
  );
  assert.equal(jsonStringify(document), '{"a":1e999,"b":"x"}');
  assert.equal(jsonStringify(document, { space: 2 }), '{\n  "a": 1e999,\n  "b": "x"\n}');
});

