// Independent test-server frame encoder/parser. These do not call the implementation's codec.
function frame(
  opcode: number,
  payload: Uint8Array = Buffer.alloc(0),
  fin = true,
  compressed = false,
): Buffer {
  const bytes = Buffer.from(payload);
  const head = Buffer.alloc(bytes.length < 126 ? 2 : bytes.length <= 65535 ? 4 : 10);
  head[0] = (fin ? 128 : 0) | (compressed ? 64 : 0) | opcode;
  if (head.length === 2) head[1] = bytes.length;
  else if (head.length === 4) {
    head[1] = 126;
    head.writeUInt16BE(bytes.length, 2);
  } else {
    head[1] = 127;
    head.writeBigUInt64BE(BigInt(bytes.length), 2);
  }
  return Buffer.concat([head, bytes]);
}
/** One WebSocket frame as the peer parser hands it over. */
interface PeerFrame {
  readonly opcode: number;
  readonly fin: boolean;
  readonly compressed: boolean;
  readonly payload: Buffer;
}

function peerParser(socket: net.Socket, onFrame: (frame: PeerFrame) => void): void {
  let data = Buffer.alloc(0);
  socket.on("data", (part: Buffer) => {
    data = Buffer.concat([data, part]);
    while (data.length >= 2) {
      // Both bytes are present: the loop condition is `data.length >= 2`.
      const first = must(data[0], "a frame begins with its first byte");
      const second = must(data[1], "a frame carries its length byte");
      assert.equal(second & 128, 128, "Client frames must be masked");
      let length = second & 127,
        offset = 2;
      if (length === 126) {
        if (data.length < 4) return;
        length = data.readUInt16BE(2);
        offset = 4;
      } else if (length === 127) {
        if (data.length < 10) return;
        length = Number(data.readBigUInt64BE(2));
        offset = 10;
      }
      if (data.length < offset + 4 + length) return;
      const key = data.subarray(offset, offset + 4);
      offset += 4;
      const payload = Buffer.from(data.subarray(offset, offset + length));
      for (let i = 0; i < payload.length; i++) {
        payload[i] = (payload[i] ?? 0) ^ (key[i % 4] ?? 0);
      }
      data = data.subarray(offset + length);
      onFrame({ opcode: first & 15, fin: !!(first & 128), compressed: !!(first & 64), payload });
    }
  });
}

function zlibMessage(transform: DeflateRaw | InflateRaw, input: Uint8Array): Promise<Buffer> {
  return new Promise<Buffer>((resolve, reject) => {
    const chunks: Buffer[] = [];
    const accept = (chunk: Buffer): number => chunks.push(Buffer.from(chunk));
    const fail = (error: unknown) => {
      transform.off("data", accept);
      transform.off("error", fail);
      reject(error);
    };
    transform.on("data", accept);
    transform.once("error", fail);
    transform.write(input, (writeError: Error | null | undefined) => {
      if (writeError) {
        fail(writeError);
        return;
      }
      transform.flush(zlibConstants.Z_SYNC_FLUSH, () => {
        transform.off("data", accept);
        transform.off("error", fail);
        resolve(Buffer.concat(chunks));
      });
    });
  });
}

function stripDeflateTail(bytes: Buffer): Buffer {
  assert.deepEqual(bytes.subarray(bytes.length - 4), Buffer.from([0, 0, 255, 255]));
  return bytes.subarray(0, bytes.length - 4);
}

function deflateMessage(bytes: Buffer, windowBits = 15): Buffer {
  return stripDeflateTail(
    deflateRawSync(bytes, {
      finishFlush: zlibConstants.Z_SYNC_FLUSH,
      flush: zlibConstants.Z_SYNC_FLUSH,
      windowBits,
    }),
  );
}

function inflateMessage(bytes: Buffer, windowBits = 15): Buffer {
  return inflateRawSync(Buffer.concat([bytes, Buffer.from([0, 0, 255, 255])]), {
    finishFlush: zlibConstants.Z_SYNC_FLUSH,
    windowBits,
  });
}
async function websocketServer(
  t: TestContext,
  onOpen: (socket: net.Socket, req: http.IncomingMessage) => void,
  { badAccept = false, extra = "", secure = false } = {},
) {
  const s = await server(
    t,
    (_req: http.IncomingMessage, res: http.ServerResponse) => {
      res.writeHead(426);
      res.end();
    },
    false,
    secure,
  );
  s.listener.on("upgrade", (req, socket, head) => {
    assert.equal(head.length, 0);
    const accept = createHash("sha1")
      .update(req.headers["sec-websocket-key"] + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")
      .digest("base64");
    socket.write(
      "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: " +
        (badAccept ? "bad" : accept) +
        "\r\n" +
        extra +
        "\r\n",
    );
    onOpen(socket, req);
  });
  return { ...s, url: s.url.replace("http", "ws") };
}
function wsEvents(ws: WebSocket) {
  const log: string[] = [];
  const opened = new Promise<void>((resolve) =>
    ws.addEventListener("open", () => {
      log.push("open");
      resolve();
    }),
  );
  const closed = new Promise<CloseEvent>((resolve) =>
    ws.addEventListener("close", (event) => {
      log.push("close");
      resolve(event as unknown as CloseEvent);
    }),
  );
  ws.addEventListener("error", () => log.push("error"));
  return { opened, closed, log };
}

class ControlledWebSocketSession implements WebSocketSession {
  protocol = "chat";
  extensions = "";
  nextCalls = 0;
  sent: SocketMessage[] = [];
  closes: { code: number | null; reason: string }[] = [];
  aborted = false;
  incoming: SocketIncoming[] = [];
  reads: PromiseWithResolvers<SocketIncoming>[] = [];
  sendWait: PromiseWithResolvers<void> | null = null;

  next(): Promise<SocketIncoming> {
    this.nextCalls++;
    const queued = this.incoming.shift();
    if (queued !== undefined) return Promise.resolve(queued);
    const result = Promise.withResolvers<SocketIncoming>();
    this.reads.push(result);
    return result.promise;
  }

  push(value: SocketIncoming): void {
    if (value.kind === "close") this.sendWait?.reject(new Error("peer closed during send"));
    const read = this.reads.shift();
    if (read === undefined) this.incoming.push(value);
    else read.resolve(value);
  }

  send(message: SocketMessage): Promise<void> {
    this.sent.push(message);
    return this.sendWait?.promise ?? Promise.resolve();
  }

  close(code: number | null, reason: string): Promise<void> {
    this.closes.push({ code, reason });
    return Promise.resolve();
  }

  abort() {
    if (this.aborted) return;
    this.aborted = true;
    this.push({ kind: "close", code: 1006, reason: "", wasClean: false, failed: true });
  }
}

function controlledWebSocketRuntime(t: TestContext, session = new ControlledWebSocketSession()) {
  let connects = 0;
  const api = runtime(t, {
    webSocketTransport: {
      connect() {
        connects++;
        return Promise.resolve(session);
      },
    },
  });
  return {
    api,
    session,
    get connects() {
      return connects;
    },
  };
}

