  await writer.write(original);
  assert.deepEqual(await reader.read(), { done: false, value: original });
  assert.deepEqual(
    wireMessages[1],
    wireMessages[0],
    "client context must reset after each message",
  );
  await writer.write("");
  assert.deepEqual(await reader.read(), { done: false, value: "" });
  assert.equal((wireMessages[2] as Buffer).length <= 1, true, "empty compression adds no data payload");
  const closing = writer.close();
  await stream.closed;
  await closing;

  let closeCode = 0;
  const receivedClose = Promise.withResolvers<void>();
