import {
  constants,
  createBrotliCompress,
  createBrotliDecompress,
  createDeflate,
  createDeflateRaw,
  createGunzip,
  createGzip,
  createInflate,
  createInflateRaw,
} from "node:zlib";
import type { Deflate, ZlibOptions } from "node:zlib";
import type {
  CompressionContext,
  CompressionFailure,
  CompressionFlush,
  CompressionFormat,
  CompressionProvider,
  CompressionResult,
} from "../src/provider/compression.ts";

/**
 * The test adapter uses node:zlib's synchronous native streaming entry point.
 * Public sync convenience methods finish and close their context on every call;
 * retaining one native handle instead exercises chunking and dictionary history.
 * These fields are Node's test-host seam, never part of the shared runtime.
 *
 * Node 24.20.0 (the repository pin) provides rejectGarbageAfterEnd to prevent its
 * native gunzip wrapper from automatically consuming a second gzip member.
 * Brotli's native decoder already stops at the first stream end; its unused
 * input offsets let the shared caller enqueue output before rejecting trailers.
 * Its PROCESS/FLUSH/FINISH operations use a different enum from zlib's flushes.
 * https://github.com/nodejs/node/blob/v24.20.0/lib/zlib.js
 * https://github.com/nodejs/node/blob/v24.20.0/src/node_zlib.cc
 */
interface NativeZlibHandle {
  onerror: (message: string, errno: number, code: string) => void;
  writeSync(
    flush: number,
    input: Uint8Array,
    inputOffset: number,
    inputLength: number,
    output: Uint8Array,
    outputOffset: number,
    outputLength: number,
  ): void;
}

interface NativeZlibStream extends Deflate {
  readonly _handle: NativeZlibHandle | null;
  readonly _writeState: Uint32Array;
}

interface StrictZlibOptions extends ZlibOptions {
  readonly rejectGarbageAfterEnd: true;
}

const outputBlockSize = 16 * 1024;

class NodeCompressionContext implements CompressionContext {
  private readonly stream: NativeZlibStream;
  private readonly decompress: boolean;
  private readonly brotli: boolean;
  private scratch: Uint8Array = new Uint8Array(outputBlockSize);
  private error: CompressionFailure | null = null;
  private nativeCode: string | null = null;
  private closed: boolean = false;
  private finished: boolean = false;

  constructor(stream: NativeZlibStream, decompress: boolean, brotli: boolean = false) {
    this.stream = stream;
    this.decompress = decompress;
    this.brotli = brotli;
    const handle = stream._handle;
    if (handle === null) throw new Error("node:zlib did not create a native context");
    // writeSync invokes this callback synchronously. Replacing Node's default
    // event-emitting callback keeps native errors as values at the capability.
    handle.onerror = (_message, errno, code) => {
      this.nativeCode = code;
      // Brotli's negative format errors overlap zlib's unrelated errno values.
      // Its allocation/state errors remain operation failures, not bad input.
      const invalidData = brotli ? decompress && (code === "Z_BUF_ERROR" ||
        errno <= constants.BROTLI_DECODER_ERROR_FORMAT_EXUBERANT_NIBBLE &&
        errno >= constants.BROTLI_DECODER_ERROR_FORMAT_DISTANCE) :
        errno === constants.Z_DATA_ERROR ||
        errno === constants.Z_NEED_DICT || errno === constants.Z_BUF_ERROR;
      this.error = {
        failure: invalidData ? "invalid-data" : "operation",
      };
    };
  }

  process(
    input: Uint8Array,
    flush: CompressionFlush,
    maxOutputBytes: number,
  ): CompressionResult | CompressionFailure {
    if (this.closed || this.finished) return this.fail({ failure: "operation" });
    if (maxOutputBytes !== Infinity &&
        (!Number.isSafeInteger(maxOutputBytes) || maxOutputBytes < 0)) {
      return this.fail({ failure: "operation" });
    }
    const handle = this.stream._handle;
    if (handle === null) return this.fail({ failure: "operation" });
    const drainBeforeFinish = this.decompress && flush === "finish";
    const processFlag = this.brotli ? constants.BROTLI_OPERATION_PROCESS : constants.Z_NO_FLUSH;
    const syncFlag = this.brotli ? constants.BROTLI_OPERATION_FLUSH : constants.Z_SYNC_FLUSH;
    const finishFlag = this.brotli ? constants.BROTLI_OPERATION_FINISH : constants.Z_FINISH;
    let flag = flush === "none" || drainBeforeFinish ? processFlag :
      flush === "sync" ? syncFlag : finishFlag;
    let finishing = false;
    const chunks: Uint8Array[] = [];
    let outputBytes = 0;
    let offset = 0;
    let remaining = input.byteLength;

    try {
      while (true) {
        // Allow at most one byte beyond the budget to detect overflow. A full
        // scratch block transfers directly; only a short final block is copied.
        const output = this.scratch;
        const outputCapacity = Math.min(output.length, maxOutputBytes - outputBytes + 1);
        handle.writeSync(flag, input, offset, remaining, output, 0, outputCapacity);
        if (this.error !== null) {
          if (finishing && this.nativeCode === "Z_BUF_ERROR") {
            return this.fail({ failure: "incomplete", chunks });
          }
          return this.fail(this.error);
        }
        const availableOutput = this.stream._writeState[0];
        const availableInput = this.stream._writeState[1];
        if (availableOutput === undefined || availableInput === undefined ||
            availableOutput > outputCapacity || availableInput > remaining) {
          return this.fail({ failure: "operation" });
        }
        const produced = outputCapacity - availableOutput;
        if (produced > maxOutputBytes - outputBytes) {
          return this.fail({ failure: "output-limit" });
        }
        if (produced !== 0) {
          if (produced === output.length) {
            chunks.push(output);
            this.scratch = new Uint8Array(outputBlockSize);
          } else {
            chunks.push(output.slice(0, produced));
          }
          outputBytes += produced;
        }
        offset += remaining - availableInput;
        remaining = availableInput;
        if (availableOutput !== 0) {
          // The shared algorithm enqueues this output before rejecting unused
          // trailing bytes, as Compression Standard section 5 step 6 requires.
          if (remaining !== 0) return { chunks, consumed: offset };
          if (drainBeforeFinish && !finishing) {
            // Node does not update its write offsets on a FINISH error. Drain
            // available output first so an incomplete stream can return it to
            // the shared flush algorithm before that algorithm raises TypeError.
            finishing = true;
            flag = finishFlag;
            continue;
          }
          if (flush === "finish") this.finished = true;
          return { chunks, consumed: offset };
        }
      }
    } catch {
      return this.fail({ failure: "operation" });
    }
  }

  reset(): void | CompressionFailure {
    if (this.closed) return { failure: "operation" };
    try {
      this.error = null;
      this.nativeCode = null;
      this.stream.reset();
      if (this.error !== null) return this.fail(this.error);
      this.finished = false;
    } catch {
      return this.fail({ failure: "operation" });
    }
  }

  close(): void {
    if (this.closed) return;
    this.closed = true;
    try {
      this.stream.close();
    } catch {
      // Cleanup is terminal and idempotent, including after a native failure.
    }
  }

  private fail(error: CompressionFailure): CompressionFailure {
    this.close();
    return error;
  }
}

export class NodeCompressionProvider implements CompressionProvider {
  createCompressor(
    format: CompressionFormat,
    windowBits: number,
  ): CompressionContext | CompressionFailure {
    // windowBits negotiates DEFLATE only. Brotli uses native RFC 7932 defaults,
    // including the standard window range rather than the Large Window extension.
    if (format === "brotli") {
      try {
        return new NodeCompressionContext(createBrotliCompress() as NativeZlibStream, false, true);
      } catch {
        return { failure: "operation" };
      }
    }
    // zlib silently promotes an 8-bit compressor window to 9; an RFC 7692
    // provider must decline that request instead of violating the negotiated cap.
    if (!Number.isInteger(windowBits) || windowBits < 9 || windowBits > 15) {
      return { failure: "unsupported" };
    }
    const options: StrictZlibOptions = { windowBits, rejectGarbageAfterEnd: true };
    try {
      switch (format) {
        case "gzip": return new NodeCompressionContext(createGzip(options) as NativeZlibStream, false);
        case "deflate": return new NodeCompressionContext(createDeflate(options) as NativeZlibStream, false);
        case "deflate-raw": return new NodeCompressionContext(createDeflateRaw(options) as NativeZlibStream, false);
      }
    } catch {
      return { failure: "operation" };
    }
  }

  createDecompressor(
    format: CompressionFormat,
    windowBits: number,
  ): CompressionContext | CompressionFailure {
    if (format === "brotli") {
      try {
        return new NodeCompressionContext(createBrotliDecompress() as NativeZlibStream, true, true);
      } catch {
        return { failure: "operation" };
      }
    }
    if (!Number.isInteger(windowBits) || windowBits < 8 || windowBits > 15) {
      return { failure: "unsupported" };
    }
    const options: StrictZlibOptions = { windowBits, rejectGarbageAfterEnd: true };
    try {
      switch (format) {
        case "gzip": return new NodeCompressionContext(createGunzip(options) as NativeZlibStream, true);
        case "deflate": return new NodeCompressionContext(createInflate(options) as NativeZlibStream, true);
        case "deflate-raw": return new NodeCompressionContext(createInflateRaw(options) as NativeZlibStream, true);
      }
    } catch {
      return { failure: "operation" };
    }
  }
}

import { MessageChannel, receiveMessageOnPort, Worker } from "node:worker_threads";
import type { KeyObject } from "node:crypto";
import type { CryptoCshakeParameters, CryptoFailure, CryptoKmacParameters } from "../src/provider/crypto.ts";

export interface NativeModernCryptoOperation {
  readonly kind?: "operation";
  readonly parameters: CryptoCshakeParameters | CryptoKmacParameters;
  readonly data: Uint8Array;
  readonly key?: KeyObject;
  readonly signature?: Uint8Array;
}

export type NativeModernCryptoCapability = "cshake" | "kmac" | "argon2" | "rsa" | "ec"
  | "Ed25519" | "Ed448" | "X25519" | "X448"
  | "ML-DSA-44" | "ML-DSA-65" | "ML-DSA-87" | "ML-KEM-512" | "ML-KEM-768" | "ML-KEM-1024";

export interface NativeModernCryptoSupportRequest {
  readonly kind: "supports";
  readonly capability: NativeModernCryptoCapability;
}

export type NativeModernCryptoRequest = NativeModernCryptoOperation | NativeModernCryptoSupportRequest;

type NativeModernCryptoResult = ArrayBuffer | boolean | CryptoFailure;

class NativeModernCryptoWorker {
  readonly worker: Worker;
  readonly port: MessageChannel["port1"];
  readonly signal: Int32Array;
  failed = false;

  constructor() {
    const channel = new MessageChannel();
    this.port = channel.port1;
    this.signal = new Int32Array(new SharedArrayBuffer(4));
    // Node exposes these native jobs only to its internal test modules. Expose
    // them in this one test worker, not to the package or the WPT VM globals.
    this.worker = new Worker(new URL("./node-crypto-modern-worker.ts", import.meta.url), {
      execArgv: ["--expose-internals"],
      workerData: { port: channel.port2, signal: this.signal },
      transferList: [channel.port2],
    });
    this.worker.on("error", () => { this.failed = true; });
    this.worker.on("exit", () => { this.failed = true; });
    this.worker.unref();
    this.port.unref();
  }

  run(request: NativeModernCryptoRequest): NativeModernCryptoResult {
    if (this.failed) return { failure: "operation" };
    Atomics.store(this.signal, 0, 0);
    this.port.postMessage(request);
    // A watchdog only: completion is the native worker's notification, never a
    // correctness assertion about machine speed. A failed worker cannot hang a
    // standalone census indefinitely while its event-loop callbacks are blocked.
    if (Atomics.wait(this.signal, 0, 0, 60_000) === "timed-out") {
      this.failed = true;
      void this.worker.terminate();
      this.port.close();
      return { failure: "operation" };
    }
    const response: unknown = receiveMessageOnPort(this.port)?.message;
    if (response instanceof ArrayBuffer || typeof response === "boolean") return response;
    return { failure: "operation" };
  }
}

let nativeWorker: NativeModernCryptoWorker | undefined;

/** Whole-input synchronous bridge to Node 24.20 native jobs, without WebCrypto. */
export function runNativeModernCrypto(request: NativeModernCryptoRequest): NativeModernCryptoResult {
  try {
    nativeWorker ??= new NativeModernCryptoWorker();
    return nativeWorker.run(request);
  } catch {
    return { failure: "operation" };
  }
}

// Test-only bridge to the pinned native jobs used by Node 24.20's own crypto
// implementation. No WebCrypto method, hash, sponge or MAC algorithm is written
// here. API layouts are from node/v24.20.0/lib/internal/crypto/{hash,mac}.js.
import { createRequire } from "node:module";
import { timingSafeEqual } from "node:crypto";
import type { KeyObject } from "node:crypto";
import { workerData } from "node:worker_threads";
import type { MessagePort } from "node:worker_threads";
import type { NativeModernCryptoCapability, NativeModernCryptoRequest } from "./node-crypto-modern-jobs.ts";

interface NativeJob { run(): readonly [unknown, ArrayBuffer | boolean | undefined]; }
interface NativeCryptoBinding {
  readonly Argon2Job: unknown;
  readonly RsaKeyPairGenJob: unknown;
  readonly EcKeyPairGenJob: unknown;
  readonly NidKeyPairGenJob: unknown;
  readonly SignJob: unknown;
  readonly KEMEncapsulateJob: unknown;
  readonly KEMDecapsulateJob: unknown;
  readonly EVP_PKEY_ED25519: number | undefined;
  readonly EVP_PKEY_ED448: number | undefined;
  readonly EVP_PKEY_X25519: number | undefined;
  readonly EVP_PKEY_X448: number | undefined;
  readonly EVP_PKEY_ML_DSA_44: number | undefined;
  readonly EVP_PKEY_ML_DSA_65: number | undefined;
  readonly EVP_PKEY_ML_DSA_87: number | undefined;
  readonly EVP_PKEY_ML_KEM_512: number | undefined;
  readonly EVP_PKEY_ML_KEM_768: number | undefined;
  readonly EVP_PKEY_ML_KEM_1024: number | undefined;
  readonly kCryptoJobSync: number;
  readonly kSignJobModeSign: number;
  readonly CShakeJob: new (mode: number, name: string, data: Uint8Array, functionName: Uint8Array, customization: Uint8Array, outputLength: number) => NativeJob;
  readonly KmacJob: new (mode: number, signMode: number, key: object, name: string, customization: Uint8Array, keyLength: number, outputLength: number, data: Uint8Array, signature: undefined) => NativeJob;
}

const context = workerData as { port: MessagePort; signal: Int32Array };
const require = createRequire(import.meta.url);
let binding: NativeCryptoBinding | undefined;
let prepareSecretKey: ((key: KeyObject) => object) | undefined;
try {
  const testBinding = require("internal/test/binding") as { internalBinding(name: string): NativeCryptoBinding };
  binding = testBinding.internalBinding("crypto");
  prepareSecretKey = (require("internal/crypto/keys") as { prepareSecretKey(key: KeyObject): object }).prepareSecretKey;
} catch {
  // Every queued request still receives a failure value if this Node build lacks
  // the pinned native seam. Startup failure must not strand the caller's wait.
}

/** Build metadata only: never construct or run a native cryptographic job. */
function hasNativeCapability(capability: NativeModernCryptoCapability): boolean {
  if (binding === undefined) return false;
  switch (capability) {
    case "cshake": return typeof binding.CShakeJob === "function";
    case "kmac": return typeof binding.KmacJob === "function";
    case "argon2": return typeof binding.Argon2Job === "function";
    case "rsa": return typeof binding.RsaKeyPairGenJob === "function";
    case "ec": return typeof binding.EcKeyPairGenJob === "function";
  }
  if (typeof binding.NidKeyPairGenJob !== "function") return false;
  switch (capability) {
    case "Ed25519": return binding.EVP_PKEY_ED25519 !== undefined;
    case "Ed448": return binding.EVP_PKEY_ED448 !== undefined;
    case "X25519": return binding.EVP_PKEY_X25519 !== undefined;
    case "X448": return binding.EVP_PKEY_X448 !== undefined;
    case "ML-DSA-44": return binding.EVP_PKEY_ML_DSA_44 !== undefined && typeof binding.SignJob === "function";
    case "ML-DSA-65": return binding.EVP_PKEY_ML_DSA_65 !== undefined && typeof binding.SignJob === "function";
    case "ML-DSA-87": return binding.EVP_PKEY_ML_DSA_87 !== undefined && typeof binding.SignJob === "function";
    case "ML-KEM-512": return binding.EVP_PKEY_ML_KEM_512 !== undefined
      && typeof binding.KEMEncapsulateJob === "function" && typeof binding.KEMDecapsulateJob === "function";
    case "ML-KEM-768": return binding.EVP_PKEY_ML_KEM_768 !== undefined
      && typeof binding.KEMEncapsulateJob === "function" && typeof binding.KEMDecapsulateJob === "function";
    case "ML-KEM-1024": return binding.EVP_PKEY_ML_KEM_1024 !== undefined
      && typeof binding.KEMEncapsulateJob === "function" && typeof binding.KEMDecapsulateJob === "function";
  }
}

context.port.on("message", (request: NativeModernCryptoRequest) => {
  let response: ArrayBuffer | boolean | { failure: "operation" } = { failure: "operation" };
  try {
    if (request.kind === "supports") {
      response = hasNativeCapability(request.capability);
    } else if (binding !== undefined && prepareSecretKey !== undefined) {
      const p = request.parameters;
      let job: NativeJob;
      if (p.name === "cSHAKE128" || p.name === "cSHAKE256") {
        // cSHAKE's prefix is independent of requested output size. Request whole
        // octets because Node truncates non-octet outputs from the high end; the
        // adapter encodes §2.1's remaining low bits after this native call.
        if (p.outputLength > 0xfffffff8) throw new RangeError("Native rounded cSHAKE length exceeds uint32");
        job = new binding.CShakeJob(binding.kCryptoJobSync, p.name, request.data,
          p.functionName, p.customization, Math.ceil(p.outputLength / 8) * 8);
      } else if ("keyLength" in p) {
        if (request.key === undefined || p.outputLength % 8 !== 0) throw new TypeError("Invalid native KMAC request");
        job = new binding.KmacJob(binding.kCryptoJobSync, binding.kSignJobModeSign,
          prepareSecretKey(request.key), p.name, p.customization, p.keyLength, p.outputLength, request.data, undefined);
      } else {
        throw new TypeError("Unknown native modern algorithm");
      }
      const [error, result] = job.run();
      if (error === undefined && result instanceof ArrayBuffer) {
        const bits = new Uint8Array(result);
        if (p.outputLength % 8 !== 0) bits[bits.length - 1]! &= (1 << (p.outputLength % 8)) - 1;
        // KmacJob's verify mode rejects all empty MACs; native timingSafeEqual
        // supplies the specified constant-time comparison, including zero bits.
        response = request.signature === undefined ? result
          : bits.byteLength === request.signature.byteLength && timingSafeEqual(bits, request.signature);
      }
    }
  } catch {
    response = { failure: "operation" };
  }
  context.port.postMessage(response, response instanceof ArrayBuffer ? [response] : []);
  Atomics.store(context.signal, 0, 1);
  Atomics.notify(context.signal, 0);
});

