function bytes(hex: string): Uint8Array { return new Uint8Array(Buffer.from(hex, "hex")); }
function base64url(hex: string): string { return Buffer.from(hex, "hex").toString("base64url"); }

function ed25519Fixture(index: number): Ed25519Fixture {
  const fixture = ed25519[index];
  if (fixture === undefined) throw new RangeError("Unknown Ed25519 fixture");
  return fixture;
}

export function ed25519PublicJwk(index = 0): OkpFixturePublicJwk {
  return { kty: "OKP", crv: "Ed25519", x: base64url(ed25519Fixture(index).x) };
}

export function ed25519PrivateJwk(index = 0): OkpFixturePrivateJwk {
  return { ...ed25519PublicJwk(index), d: base64url(ed25519Fixture(index).d) };
}

export function ed25519Message(index = 0): Uint8Array { return bytes(ed25519Fixture(index).message); }
export function ed25519Signature(index = 0): Uint8Array { return bytes(ed25519Fixture(index).signature); }

export function x25519PublicJwk(side: "alice" | "bob" = "alice"): OkpFixturePublicJwk {
  return { kty: "OKP", crv: "X25519", x: base64url(peers[side].x) };
}

export function x25519PrivateJwk(side: "alice" | "bob" = "alice"): OkpFixturePrivateJwk {
  return { ...x25519PublicJwk(side), d: base64url(peers[side].d) };
}

export function x25519Secret(): Uint8Array {
  return bytes("4a5d9d5ba4ce2de1728e3bf480350f25e07e21c947d19e3376f09b3c1e161742");
}

export function x25519ScalarVector(index: 0 | 1): { scalar: Uint8Array; publicKey: Uint8Array; secret: Uint8Array } {
  const vector = scalarVectors[index]!;
  return { scalar: bytes(vector.scalar), publicKey: bytes(vector.publicKey), secret: bytes(vector.secret) };
}

export function okpPublicJwk(name: OkpFixtureName): OkpFixturePublicJwk {
  return name === "Ed25519" ? ed25519PublicJwk() : x25519PublicJwk();
}

export function okpPrivateJwk(name: OkpFixtureName): OkpFixturePrivateJwk {
  return name === "Ed25519" ? ed25519PrivateJwk() : x25519PrivateJwk();
}

export function okpRawPublic(name: OkpFixtureName): Uint8Array {
  return new Uint8Array(Buffer.from(okpPublicJwk(name).x, "base64url"));
}

export function okpSpki(name: OkpFixtureName): Uint8Array {
  const oid = name === "Ed25519" ? "70" : "6e";
  const x = Buffer.from(okpPublicJwk(name).x, "base64url").toString("hex");
  return bytes("302a300506032b65" + oid + "032100" + x);
}

export function okpPkcs8(name: OkpFixtureName): Uint8Array {
  const oid = name === "Ed25519" ? "70" : "6e";
  const d = Buffer.from(okpPrivateJwk(name).d, "base64url").toString("hex");
  return bytes("302e020100300506032b65" + oid + "04220420" + d);
}

// The Undici-shaped dispatcher operations: request, stream, pipeline.
//
// Not a parity claim. No Undici revision is pinned in this repository, so an API ledger
// with evidence per export cannot be written honestly, and the plan separates the
// architecture and behaviour — which are required — from package-level compatibility,
// which is a facade decision. What is asserted below is what these do.
//
// `connect` and `upgrade` are absent for a reason worth stating in the tests as well as
// the source: both must hand the caller a connection, and `FetchTransport` answers with
// a response and no way to reach the socket under it.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import {
  AbortController,
  DispatcherOperations,
  ReadableStream,
  TextDecoder,
  TextEncoder,
  WritableStream,
} from "../src/index.ts";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import { must } from "./harness.ts";
import type { HeaderEntry } from "../src/fetch/headers.ts";
import type { DispatchInfo } from "../src/dispatch/operations.ts";
import type {
  FetchTransport,
  TransportRequest,
  TransportResponse,
} from "../src/fetch/transport.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const encoder = new TextEncoder();
const decoder = new TextDecoder();

const urls = createHostNodePrimitives().urls;

function request(overrides: Partial<TransportRequest> = {}): TransportRequest {
  return {
    // A parsed record rather than a `{ href }` stub: `TransportRequest.url` is a `URLRecord`.
    url: urls.parse("https://ops.test/resource"),
    method: "GET",
    headers: [],
    body: null,
    bodyLength: null,
    signal: new AbortController().signal,
    ...overrides,
  };
}

/** A transport whose response body is `chunks`, recording how it was cancelled. */
/** What a test may vary about the stand-in transport. */
interface TransportOptions {
  readonly failWith?: unknown;
  readonly status?: number;
  readonly statusText?: string;
  readonly headers?: readonly HeaderEntry[];
  readonly trailers?: Promise<readonly HeaderEntry[]>;
}

/** How the response body was consumed, for a test to assert against afterwards. */
interface TransportState {
  cancelled: unknown;
  cancelCount: number;
  reads: number;
}

function transportOf(
  chunks: readonly string[] | null,
  options: TransportOptions = {},
): FetchTransport & { state: TransportState } {
  const state: TransportState = { cancelled: undefined, cancelCount: 0, reads: 0 };
  const transport = {
    state,
    async dispatch() {
      if (options.failWith !== undefined) throw options.failWith;
      let index = 0;
      const body =
        chunks === null
          ? null
          : new ReadableStream<Uint8Array>({
              pull(controller) {
                if (index >= chunks.length) {
                  controller.close();
                  return;
                }
                state.reads++;
                controller.enqueue(encoder.encode(chunks[index++]));
              },
              cancel(reason?: unknown) {
                state.cancelCount++;
                state.cancelled = reason;
              },
            });
      return {
        status: options.status ?? 200,
        statusText: options.statusText ?? "OK",
        headers: options.headers ?? [["content-type", "text/plain"]],
        body,
        ...(options.trailers === undefined ? {} : { trailers: options.trailers }),
      };
    },
  };
  return transport;
}

function collecting(): { written: string[]; stream: WritableStream<Uint8Array> } {
  const written: string[] = [];
  return {
    written,
    stream: new WritableStream<Uint8Array>({
      write(chunk) {
        written.push(decoder.decode(chunk));
      },
    }),
  };
}

async function readAll(stream: ReadableStream<Uint8Array> | null): Promise<string> {
  const reader = must(stream, "the response carries a body").getReader();
  // Decoded per chunk, so these are strings.
  const parts: string[] = [];
  try {
    for (;;) {
      const item = await reader.read();
      if (item.done) break;
      parts.push(decoder.decode(item.value));
    }
  } finally {
    reader.releaseLock();
  }
  return parts.join("");
}

suite("request buffers the body and reports the head and trailers", async () => {
  const transport = transportOf(["hello ", "buffered ", "world"], {
    status: 203,
    statusText: "Non-Authoritative Information",
    headers: [["x-a", "1"]],
    trailers: Promise.resolve([["x-checksum", "abc"]]),
  });
  const operations = new DispatcherOperations(transport);

  const result = await operations.request(request(), { maxBytes: 1024 });
  assert.equal(result.status, 203);
  assert.equal(result.statusText, "Non-Authoritative Information");
  assert.deepEqual(result.headers, [["x-a", "1"]]);
  assert.equal(decoder.decode(result.body), "hello buffered world");
  assert.deepEqual(result.trailers, [["x-checksum", "abc"]]);
});

suite("a transport that cannot expose trailers reports undefined, not none", async () => {
  const operations = new DispatcherOperations(transportOf(["body"]));
  const result = await operations.request(request(), { maxBytes: 1024 });
  assert.equal(result.trailers, undefined);
});

suite("a status the caller would call a failure is still a result", async () => {
  const operations = new DispatcherOperations(
    transportOf(["not found"], { status: 404, statusText: "Not Found" }),
  );
  const result = await operations.request(request(), { maxBytes: 1024 });
  assert.equal(result.status, 404);
  assert.equal(decoder.decode(result.body), "not found");
});

suite("a body past maxBytes is refused and the response is cancelled", async () => {
  // Long enough that the body is still producing when the limit trips. A short body is
  // buffered and closed before the limit is reached, and cancelling a closed stream is
  // a no-op -- so a two-chunk case asserts nothing about cancellation.
  const transport = transportOf(Array.from({ length: 20 }, () => "12345"));
  const operations = new DispatcherOperations(transport);
  await assert.rejects(() => operations.request(request(), { maxBytes: 6 }), {
    name: "ResponseExceededMaxSizeError",
  });
  assert.equal(transport.state.cancelCount, 1, "the producer is told to stop");
  const cancelled = transport.state.cancelled;
  assert.ok(cancelled instanceof Error, "the producer was cancelled with an Error");
  assert.equal(cancelled.name, "ResponseExceededMaxSizeError");
});

suite("an abort while buffering rejects with the exact reason", async () => {
  const controller = new AbortController();
  const reason = new Error("the caller gave up");
  const transport: FetchTransport = {
    async dispatch(): Promise<TransportResponse> {
      return {
        status: 200,
        statusText: "OK",
        headers: [],
        body: new ReadableStream<Uint8Array>({
          pull(streamController) {
            controller.abort(reason);
            streamController.enqueue(encoder.encode("a chunk"));
          },
        }),
      };
    },
  };
  const operations = new DispatcherOperations(transport);
  await assert.rejects(
    () => operations.request(request({ signal: controller.signal }), { maxBytes: 1024 }),
    (thrown) => thrown === reason,
  );
});

suite("stream writes the body into the factory's destination in order", async () => {
  const transport = transportOf(["one ", "two ", "three"], {
    trailers: Promise.resolve([["x-end", "yes"]]),
  });
  const operations = new DispatcherOperations(transport);
  const sink = collecting();
  const seen: DispatchInfo[] = [];

  const result = await operations.stream(request(), (info: DispatchInfo) => {
    seen.push(info);
    return sink.stream;
  });

  assert.equal(seen.length, 1, "the factory is called exactly once");
  assert.equal(must(seen[0], "the factory was called once").status, 200);
  assert.deepEqual(sink.written, ["one ", "two ", "three"]);
  assert.deepEqual(result.trailers, [["x-end", "yes"]]);
});

suite("the factory chooses a destination before anything is written to it", async () => {
  const transport = transportOf(["first", "second"]);
  const operations = new DispatcherOperations(transport);
  const order: string[] = [];

  // Not "no chunk was pulled": a stream fills its queue on construction, so the body
  // has already been read from before any operation touches it. What this operation
  // controls is that the destination is chosen from the head, before it is written to.
  await operations.stream(request(), (info) => {
    order.push(`factory:${info.status}`);
    return new WritableStream({
      write(chunk) {
        order.push(`write:${decoder.decode(chunk)}`);
      },
    });
  });
  assert.deepEqual(order, ["factory:200", "write:first", "write:second"]);
});

suite("a factory that throws cancels the response body", async () => {
  const transport = transportOf(["unwanted"]);
  const operations = new DispatcherOperations(transport);
  const failure = new Error("nowhere to put it");

  await assert.rejects(
    () =>
      operations.stream(request(), () => {
        throw failure;
      }),
    (thrown) => thrown === failure,
  );
  assert.equal(transport.state.cancelled, failure);
});

suite("a destination that fails mid-write cancels the response body", async () => {
  const transport = transportOf(["a", "b", "c"]);
  const operations = new DispatcherOperations(transport);
  const failure = new Error("the sink broke");
  let written = 0;

  await assert.rejects(
    () =>
      operations.stream(
        request(),
        () =>
          new WritableStream({
            write() {
              if (++written === 2) throw failure;
            },
          }),
      ),
    (thrown) => thrown === failure,
  );
  assert.equal(transport.state.cancelled, failure);
});

suite("a response with no body still gets a destination, closed empty", async () => {
  const transport = transportOf(null, { status: 204, statusText: "No Content" });
  const operations = new DispatcherOperations(transport);
  const sink = collecting();
  let called = 0;

  const result = await operations.stream(request(), () => {
    called++;
    return sink.stream;
  });
  assert.equal(called, 1);
  assert.equal(result.status, 204);
  assert.deepEqual(sink.written, []);
});

suite("pipeline yields what the handler produces", async () => {
  const transport = transportOf(["ab", "cd"]);
  const operations = new DispatcherOperations(transport);

  const out = operations.pipeline(request(), (info, body) => {
    assert.equal(info.status, 200);
    const reader = must(body, "the response carries a body").getReader();
    return new ReadableStream<Uint8Array>({
      async pull(controller) {
        const item = await reader.read();
        if (item.done) {
          controller.close();
          return;
        }
        controller.enqueue(encoder.encode(decoder.decode(item.value).toUpperCase()));
      },
    });
  });

  assert.equal(await readAll(out), "ABCD");
});

suite("a dispatch failure surfaces on the pipeline stream", async () => {
  const failure = new Error("the connection went away");
  const operations = new DispatcherOperations(transportOf(["x"], { failWith: failure }));

  const out = operations.pipeline(request(), () => {
    throw new Error("the handler must not be reached");
  });
  await assert.rejects(() => readAll(out), (thrown) => thrown === failure);
});

suite("a handler that throws errors the stream and cancels the body", async () => {
  const transport = transportOf(["x"]);
  const operations = new DispatcherOperations(transport);
  const failure = new Error("the handler refused");

  const out = operations.pipeline(request(), () => {
    throw failure;
  });
  await assert.rejects(() => readAll(out), (thrown) => thrown === failure);
  assert.equal(transport.state.cancelled, failure);
});

suite("cancelling the pipeline cancels what the handler was reading", async () => {
  const transport = transportOf(["a", "b", "c", "d"]);
  const operations = new DispatcherOperations(transport);
  let handlerCancelled;

  const out = operations.pipeline(request(), (_info, body) => {
    const reader = must(body, "the response carries a body").getReader();
    return new ReadableStream<Uint8Array>({
      async pull(controller) {
        const item = await reader.read();
        if (item.done) controller.close();
        else controller.enqueue(item.value);
      },
      async cancel(reason) {
        handlerCancelled = reason;
        await reader.cancel(reason);
      },
    });
  });

  const reader = out.getReader();
  assert.equal(decoder.decode((await reader.read()).value), "a");
  const reason = new Error("enough");
  await reader.cancel(reason);
  reader.releaseLock();

  assert.equal(handlerCancelled, reason);
  assert.equal(transport.state.cancelled, reason);
});

suite("a cancel that arrives before the dispatch settles is not lost", async () => {
  const released = Promise.withResolvers<void>();
  const handlerCompleted = Promise.withResolvers<void>();
  const transport = transportOf(["a", "b"]);
  const slow = {
    state: transport.state,
    async dispatch(value: TransportRequest): Promise<TransportResponse> {
      await released.promise;
      return transport.dispatch(value);
    },
  };
  const operations = new DispatcherOperations(slow);
  let handlerCancelled;

  const out = operations.pipeline(request(), (_info, body) => {
    const reader = must(body, "the response carries a body").getReader();
    return new ReadableStream<Uint8Array>({
      async pull(controller) {
        const item = await reader.read();
        if (item.done) controller.close();
        else controller.enqueue(item.value);
      },
      async cancel(reason) {
        handlerCancelled = reason;
        await reader.cancel(reason);
        handlerCompleted.resolve();
      },
    });
  });

  // Cancelled while the dispatch is still in flight: there is nothing to cancel yet,
  // so the request has to be remembered rather than dropped.
  const reason = new Error("changed my mind");
  const cancelling = out.cancel(reason);
  released.resolve();
  await cancelling;
  await handlerCompleted.promise;

  assert.equal(handlerCancelled, reason);
  assert.equal(transport.state.cancelled, reason);
});

import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import "../host/environment-shim.ts";
import { DOMException } from "../src/core/errors.ts";
import { Event } from "../src/core/events.ts";
import { installWebPlatformRuntime } from "../src/provider/environment.ts";
import { WebPlatformRuntime } from "../src/provider/web-platform-runtime.ts";
import type { PerformanceCapabilities } from "../src/provider/performance.ts";
import {
  createPerformance, Performance, PerformanceEntry, PerformanceMark, PerformanceMeasure,
} from "../src/performance/performance.ts";

function environment(t: TestContext, capabilities: PerformanceCapabilities = {}) {
  const clock = { now: 150, calls: 0, wallCalls: 0 };
  const runtime = new WebPlatformRuntime({
    ...createHostNodePrimitives(),
    monotonicMilliseconds() { clock.calls++; return clock.now; },
    wallTimeMilliseconds() { clock.wallCalls++; return 9_000_000; },
  });
  installWebPlatformRuntime(runtime);
  const performance = createPerformance(runtime, capabilities);
  t.after(() => runtime.close());
  return { performance, runtime, clock };
}

function call(fn: (...args: never[]) => unknown, receiver: unknown, args: unknown[]): unknown {
  return Reflect.apply(fn, receiver, args);
}

test("Performance now reads only the monotonic capability and applies the fixed origin", (t) => {
  const { performance, clock } = environment(t, { timeOrigin: { epochMilliseconds: 123_456, monotonicMilliseconds: 125 } });
  clock.calls = clock.wallCalls = 0;
  assert.equal(performance.now(), 25);
  clock.now = 175.125;
  assert.equal(performance.now(), 50.125);
  assert.equal(clock.calls, 2);
  assert.equal(clock.wallCalls, 0);
  assert.equal(performance.timeOrigin, 123_456);
  assert.deepEqual(performance.toJSON(), { timeOrigin: 123_456 });
  assert.notEqual(performance.toJSON(), performance.toJSON());
});

test("Performance refuses missing epoch correlation without approximating a wall-clock origin", (t) => {
  const { performance, clock } = environment(t);
  assert.equal(performance.now(), 150);
  for (const read of [() => performance.timeOrigin, () => performance.toJSON()]) {
    assert.throws(read, (error) => error instanceof DOMException && error.name === "NotSupportedError");
  }
  assert.equal(clock.wallCalls, 0);
});

test("Performance is an EventTarget and direct platform-only constructors reject", (t) => {
  const { performance } = environment(t);
  let count = 0;
  performance.addEventListener("sample", () => { count++; }, { once: true });
  performance.dispatchEvent(new Event("sample"));
  performance.dispatchEvent(new Event("sample"));
  assert.equal(count, 1);
  assert.throws(() => new Performance(), TypeError);
  assert.throws(() => new PerformanceEntry(), TypeError);
  assert.throws(() => new PerformanceMeasure(), TypeError);
  assert.equal(Performance.length, 0);
  assert.equal(PerformanceEntry.length, 0);
  assert.equal(PerformanceMark.length, 1);
  assert.equal(PerformanceMeasure.length, 0);
  assert.equal(Object.prototype.toString.call(performance), "[object Performance]");
});

test("Performance factory preserves one instance per runtime", (t) => {
  const { runtime } = environment(t);
  assert.throws(() => createPerformance(runtime), /already installed/);
});

test("PerformanceMark does not install an implicit capability-free Performance before bootstrap", async () => {
  const runtime = new WebPlatformRuntime(createHostNodePrimitives());
  installWebPlatformRuntime(runtime);
  try {
    assert.throws(() => new PerformanceMark("before bootstrap"), (error) => error instanceof DOMException &&
      error.name === "NotSupportedError" && error.message.includes("bootstrap"));
    const performance = createPerformance(runtime);
    assert.ok(new PerformanceMark("after bootstrap").startTime >= 0);
    assert.deepEqual(performance.getEntries(), []);
  } finally { await runtime.close(); }
});

test("Performance argument counts and receiver brands are checked before coercion", (t) => {
  const { performance } = environment(t);
  for (const fn of [performance.mark, performance.measure, performance.getEntriesByName, performance.getEntriesByType]) {
    assert.throws(() => call(fn, performance, []), TypeError);
    let converted = false;
    assert.throws(() => call(fn, {}, [{ toString() { converted = true; return "x"; } }]), TypeError);
    assert.equal(converted, false);
  }
  for (const fn of [performance.now, performance.toJSON, performance.getEntries, performance.clearMarks, performance.clearMeasures]) {
    assert.throws(() => call(fn, {}, []), TypeError);
  }
