// Which Request fields change what happens, and which are deliberately inert.
//
// The plan keeps browser-oriented fields observable even where their enforcement
// algorithm is excluded from this profile: there is no document, so there is no unload
// for `keepalive` to survive, no CORS for `mode` to select, and no document origin for
// `referrerPolicy` to derive from. Being inert is the correct behaviour for those.
//
// It is also indistinguishable, from outside, from a field that should do something and
// does not -- which is exactly what `integrity` was until this session. So the split is
// asserted rather than assumed, and adding a field to the wrong side fails here.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { createServer } from "node:net";

import {
  AbortController,
  ReadableStream,
  Request,
  Response,
} from "../src/index.ts";
import { createHostNodeWebPlatform } from "../host/node-runtime.ts";
import type { Socket } from "node:net";
import { portOf } from "./harness.ts";
import type { WebPlatformRuntime } from "../src/provider.ts";
import type { RequestInit } from "../src/fetch/request.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const CRLF = String.fromCharCode(13, 10);

/** Records every request head it is sent and answers each with a fixed response. */
/**
 * A `Request` attribute read by a runtime name.
 *
 * The field names come from a table, so the read cannot be expressed against the interface --
 * it declares no index signature. Widened to `unknown` here rather than to `any`, so a caller
 * still has to say what it expects.
 */
function attribute(request: Request, name: string): unknown {
  return (request as unknown as Record<string, unknown>)[name];
}

async function recordingServer(t: TestContext): Promise<{ heads: string[]; port: number }> {
  const heads: string[] = [];
  const sockets = new Set<Socket>();
  const server = createServer((socket) => {
    sockets.add(socket);
    socket.on("error", () => {});
    socket.on("close", () => sockets.delete(socket));
    let buffered = "";
    socket.on("data", (chunk) => {
      buffered += chunk.toString("latin1");
      const end = buffered.indexOf(CRLF + CRLF);
      if (end < 0) return;
      heads.push(buffered.slice(0, end));
      buffered = buffered.slice(end + 4);
      socket.write(
        "HTTP/1.1 200 OK" +
          CRLF +
          "content-length: 2" +
          CRLF +
          "connection: close" +
          CRLF +
          CRLF +
          "ok",
      );
    });
  });
  server.listen(0, "127.0.0.1");
  await new Promise<void>((resolve) => server.once("listening", () => resolve()));
  t.after(() => {
    for (const socket of sockets) socket.destroy();
    return new Promise<void>((resolve) => server.close(() => resolve()));
  });
  return { heads, port: portOf(server) };
}

function runtimeFor(t: TestContext): WebPlatformRuntime {
  const api = createHostNodeWebPlatform();
  t.after(() => api.close());
  return api;
}

/**
 * Fields whose value is observable and deliberately changes nothing on the wire.
 *
 * Each entry is two values that differ, so "inert" is checked by comparing two real
 * requests rather than by asserting a default.
 */
const INERT_FIELDS = {
  mode: ["cors", "no-cors"],
  referrerPolicy: ["", "no-referrer"],
  keepalive: [false, true],
};

/**
 * Accepted in the init and deliberately *not* exposed on the Request.
 *
 * Fetch defines `RequestInit.priority` and no matching `Request.priority` attribute, so
 * a getter here would be an invention. It is still checked for inertness on the wire.
 */
const UNEXPOSED_FIELDS = {
  priority: ["auto", "high"],
};

suite("an inert field is readable, survives a clone, and reaches the Request", (t) => {
  runtimeFor(t);
  for (const [field, [, second]] of Object.entries(INERT_FIELDS)) {
    const request = new Request("https://example.test/", { [field]: second });
    assert.equal(attribute(request, field), second, `${field} must be readable`);
    assert.equal(attribute(request.clone(), field), second, `${field} must survive a clone`);
  }
  // And the unexposed ones stay unexposed: inventing a getter Fetch does not define
  // would be as wrong as omitting one it does.
  for (const field of Object.keys(UNEXPOSED_FIELDS)) {
    const request = new Request("https://example.test/", { [field]: "high" });
    assert.equal(attribute(request, field), undefined, `${field} is not a Request attribute`);
  }
});

suite("two requests differing only in an inert field produce identical bytes", async (t) => {
  const { heads, port } = await recordingServer(t);
  const api = runtimeFor(t);
  const url = `http://127.0.0.1:${port}/path`;

  const wireInert = { ...INERT_FIELDS, ...UNEXPOSED_FIELDS };
  for (const [field, [first, second]] of Object.entries(wireInert)) {
    heads.length = 0;
    await (await api.fetch(url, { [field]: first })).text();
    await (await api.fetch(url, { [field]: second })).text();
    assert.equal(heads.length, 2, `${field}: both requests must have reached the server`);
    // The decisive assertion. If a field ever starts affecting the wire, this is where
    // it shows up, and the entry has to move to the enforced side deliberately.
    assert.equal(heads[0], heads[1], `${field} must not change the request on the wire`);
  }
});

suite("the enforced fields do change what happens", async (t) => {
  const { heads, port } = await recordingServer(t);
  const api = runtimeFor(t);
  const url = `http://127.0.0.1:${port}/path`;

  // method and headers reach the wire.
  heads.length = 0;
  await (await api.fetch(url, { method: "HEAD", headers: { "x-marker": "here" } })).text();
  const head = heads[0];
  assert.ok(head !== undefined, "the server recorded the request head");
  assert.match(head, /^HEAD \/path HTTP\/1\.1/);
  assert.match(head, /x-marker: here/);

  // redirect: "error" is a policy, not metadata.
  // Deliberately outside the type: rejecting it is the assertion, so the value has to reach
  // the call for the run-time check to be the thing under test.
  const badRedirect = { redirect: "nonsense" } as unknown as RequestInit;
  await assert.rejects(api.fetch(url, badRedirect), TypeError);

  // duplex is enforced at construction: a streaming body without it is refused.
  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      controller.close();
    },
  });
  assert.throws(() => new Request(url, { method: "POST", body: stream }), TypeError);

  // signal aborts a real request rather than being recorded.
  const controller = new AbortController();
  controller.abort();
  await assert.rejects(api.fetch(url, { signal: controller.signal }));

  // integrity is enforced, and its enforcement is what this test exists to contrast
  // with the inert fields: an unverifiable requirement stops the request.
  //
  // It stops it with a *descriptive* TypeError rather than an opaque network error,
  // because this environment has no digest provider and that is a configuration
  // mistake rather than a network outcome. A digest that is computed and does not
  // match is the opposite: that is a network error, opaque as Fetch requires, and is
  // asserted in the integrity suite.
  await assert.rejects(
    api.fetch(url, { integrity: "sha256-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=" }),
    (error: unknown) => {
      assert.ok(error instanceof TypeError);
      assert.match(error.message, /cannot verify it/);
      return true;
    },
  );
});

suite("an inert field survives a Cache round trip", async (t) => {
  const api = runtimeFor(t);
  const cache = await api.caches.open("fields");
  const request = new Request("https://example.test/kept", {
    mode: "no-cors",
    referrerPolicy: "no-referrer",
    keepalive: true,
  });
  await cache.put(request, new Response("stored"));
  const [restored] = await cache.keys();
  assert.ok(restored !== undefined, "the cache kept the request that was put in it");
  // Observable metadata that did not survive storage would be observable only until it
  // mattered, which is worse than not having it.
  assert.equal(restored.mode, "no-cors");
  assert.equal(restored.referrerPolicy, "no-referrer");
  assert.equal(restored.keepalive, true);
});

// Reading an inbound HTTP/1 request head.
//
// The mirror of the response reader, and until now the only implementation of it in
// this repository lived in a test harness -- which is the wrong place for the thing
// under test. An embedding server needs it before it can decide anything: whether to
// upgrade, which host was asked for, whether the framing is one it can accept.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import {
  BufferedReader,
  defaultHeadLimits,
  readRequestHead,
} from "../src/provider.ts";
import type { ByteConnection } from "../src/provider/primitives.ts";
import type { HeadLimits, RequestHead } from "../src/http1/parser.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const CRLF = String.fromCharCode(13, 10);
const encoder = new TextEncoder();

/** A ByteConnection over a fixed script, one chunk at a time. */
function connectionOf(text: string, chunkSize = 64): ByteConnection {
  const bytes = encoder.encode(text);
  let offset = 0;
  return {
    get closed() {
      return offset >= bytes.length;
    },
    async read(maxBytes: number): Promise<Uint8Array | null> {
      if (offset >= bytes.length) return null;
      const take = Math.min(maxBytes, chunkSize, bytes.length - offset);
      const chunk = bytes.subarray(offset, offset + take);
      offset += take;
      return chunk;
    },
    async write(data: Uint8Array): Promise<number> {
      return data.length;
    },
    close() {
      offset = bytes.length;
    },
  };
}

// `chunkSize` is optional rather than merely defaulted-past: it sits after a parameter with a
// default, so leaving it bare made it *required* and every one-argument call a type error.
const read = (
  text: string,
  limits: HeadLimits = defaultHeadLimits,
  chunkSize?: number,
): Promise<RequestHead> =>
  readRequestHead(new BufferedReader(connectionOf(text, chunkSize)), limits);

const request = (line: string, headers: readonly string[] = []): string =>
  [line, ...headers, "", ""].join(CRLF);

suite("a request line and its fields are read", async () => {
  const head = await read(
    request("GET /path?query=1 HTTP/1.1", ["Host: example.test", "X-Odd:   spaced   "]),
  );
  assert.equal(head.method, "GET");
  assert.equal(head.target, "/path?query=1");
  assert.equal(head.version, "1.1");
  assert.deepEqual(head.headers, [
    ["host", "example.test"],
    ["x-odd", "spaced"],
  ]);
});

suite("HTTP/1.0 is read and reported as itself", async () => {
  const head = await read(request("HEAD / HTTP/1.0"));
  assert.equal(head.version, "1.0");
  assert.equal(head.method, "HEAD");
});

suite("the target is returned exactly as it arrived", async () => {
  // Normalising here would put a URL policy inside a framing parser, and a server that
  // routes on a normalised target while logging the original is how the two disagree.
  for (const target of [
    "//a/../b",
    "/%2e%2e/",
    "/a//b",
    "http://origin.test/absolute",
    "*",
    "/" + "x".repeat(200),
  ]) {
    const head = await read(request(`GET ${target} HTTP/1.1`));
    assert.equal(head.target, target);
  }
});

suite("a chunk boundary in the middle of the line changes nothing", async () => {
  // One byte at a time: the reader has to reassemble the line rather than assume a
  // request arrives in one packet, which on a real socket it frequently does not.
  const head = await read(
    request("POST /submit HTTP/1.1", ["Host: example.test"]),
    defaultHeadLimits,
    1,
  );
  assert.equal(head.method, "POST");
  assert.equal(head.target, "/submit");
  assert.deepEqual(head.headers, [["host", "example.test"]]);
});

suite("a malformed request line is refused", async () => {
  const malformed = [
    "GET",
    "GET /",
    "GET  HTTP/1.1",
    " /path HTTP/1.1",
    "/path HTTP/1.1",
    "GET /path HTTP/1.1 extra",
    "GET /path HTTP/2.0",
    "GET /path HTTP/1.2",
    "GET /path HTTPS/1.1",
    "GET /path HTTP/11",
    "GET /path http/1.1",
  ];
  for (const line of malformed) {
    await assert.rejects(() => read(request(line)), line);
  }
});

suite("a method that is not a token is refused", async () => {
  // Written as escapes rather than the bytes themselves: a case a reader cannot see
  // is a case nobody can check, and several of these were invisible in the first draft.
  for (const method of ["GE T", "GET/", 'GE"T', "GET\u0080", "GET\u0000"]) {
    await assert.rejects(() => read(request(`${method} / HTTP/1.1`)), method);
  }
});

suite("a target outside visible ASCII is refused", async () => {
  // Written as escapes rather than the bytes themselves: a case a reader cannot see
  // is a case nobody can check, and several of these were invisible in the first draft.
  for (const target of ["/a\u0000b", "/a\u007fb", "/\u00e9", "/a b", "/a\u0080"]) {
    await assert.rejects(() => read(request(`GET ${target} HTTP/1.1`)), target);
  }
});

suite("header limits are enforced", async () => {
  const many: string[] = [];
  for (let index = 0; index < 200; index++) many.push(`x-${index}: v`);
  await assert.rejects(
    () => read(request("GET / HTTP/1.1", many), { ...defaultHeadLimits, maxHeaderBytes: 65536, maxHeaders: 8 }),
    { name: "LimitError" },
  );
  await assert.rejects(
    () => read(request("GET / HTTP/1.1", ["x-long: " + "v".repeat(500)]), {
      ...defaultHeadLimits,
      maxHeaderBytes: 128,
      maxHeaders: 64,
    }),
    { name: "LimitError" },
  );
});

suite("a truncated head does not resolve as a whole one", async () => {
  const reader = new BufferedReader(connectionOf("GET / HTTP/1.1" + CRLF + "Host: a.test"));
  await assert.rejects(() => readRequestHead(reader));
});

// Holding a one-shot request body so a retry has something to send.
//
// This is the spill area's caller. Until it existed, spilling was a mechanism with no
// consumer -- the pattern this ledger keeps naming -- and the retry interceptor refused
// every streaming body outright, which was correct and unhelpful in equal measure.
//
// The refusal is still the default. A body is held only because a caller supplied
// somewhere to hold it: nothing here decides on a caller's behalf that an arbitrary
// upload may be buffered, which is the guess the old error existed to avoid.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  AbortController,
  DurableSpillArea,
  ReadableStream,
  RetryInterceptor,
  spilledRequestBodyStore,
  TextDecoder,
  TextEncoder,
  TransportError,
  UnreplayableRequestError,
} from "../src/index.ts";
import { HostNodeDurableStore } from "../host/node-runtime.ts";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import type { RequestBodyStore } from "../src/fetch/transport.ts";
import type {
  FetchTransport,
  TransportRequest,
  TransportResponse,
} from "../src/fetch/transport.ts";
import { must } from "./harness.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const encoder = new TextEncoder();
const none = () => new AbortController().signal;

class ImmediateScheduler {
  readonly delays: number[] = [];
  readonly errors: unknown[] = [];

  enqueue(task: () => void): void {
    queueMicrotask(task);
  }

  delay(milliseconds: number, task: () => void): { cancel(): void } {
    this.delays.push(milliseconds);
    queueMicrotask(task);
    return { cancel() {} };
  }

  reportError(error: unknown): void {
    this.errors.push(error);
  }
}

function chunkedStream(chunks: readonly string[]): ReadableStream<Uint8Array> {
  let index = 0;
  return new ReadableStream<Uint8Array>({
    pull(controller) {
      if (index >= chunks.length) controller.close();
      else controller.enqueue(encoder.encode(chunks[index++]));
    },
  });
}

async function consume(body: ReadableStream<Uint8Array> | null | undefined): Promise<string> {
  if (body === null || body === undefined) return "";
  const reader = body.getReader();
  // Bytes rather than chunks: the loop spreads each chunk into this.
  const parts: number[] = [];
  try {
    while (true) {
      const item = await reader.read();
      if (item.done) break;
      parts.push(...item.value);
    }
  } finally {
    reader.releaseLock();
  }
  return new TextDecoder().decode(Uint8Array.from(parts));
}

/** Fails `failures` times with a retryable transport error, recording each body sent. */
function flakyTransport(failures: number): FetchTransport & {
  sent: string[];
  readonly attempts: number;
} {
  const sent: string[] = [];
  let attempts = 0;
  return {
    sent,
    get attempts() {
      return attempts;
    },
    async dispatch(request: TransportRequest): Promise<TransportResponse> {
      attempts++;
      sent.push(await consume(request.body));
      if (attempts <= failures) throw new TransportError("ECONNRESET", "reset");
      return { status: 200, statusText: "OK", headers: [], body: null, trailers: undefined };
    },
  };
}

function area(
  t: TestContext,
  options: Record<string, unknown> = {},
): { bytes: HostNodeDurableStore; open: () => Promise<DurableSpillArea> } {
  const root = mkdtempSync(join(tmpdir(), "nts-replay-"));
  t.after(() => rmSync(root, { recursive: true, force: true }));
  const bytes = new HostNodeDurableStore({ root });
  return { bytes, open: () => DurableSpillArea.open(bytes, options) };
}

function retrying(store?: RequestBodyStore): RetryInterceptor {
  return new RetryInterceptor({
    scheduler: new ImmediateScheduler(),
    maxRetries: 3,
    methods: ["POST", "GET"],
    minTimeoutMilliseconds: 0,
    ...(store === undefined ? {} : { requestBodyStore: store }),
  });
}

const urls = createHostNodePrimitives().urls;

function post(
  body: ReadableStream<Uint8Array> | null,
  overrides: Partial<TransportRequest> = {},
): TransportRequest {
  return {
    // A parsed record rather than a `{ href }` stub: `TransportRequest.url` is a `URLRecord`,
    // and the stub satisfied nothing but the one field this file happened to read.
    url: urls.parse("https://replay.test/upload"),
    method: "POST",
    headers: [],
    body,
    bodyLength: null,
    signal: none(),
    ...overrides,
  };
}

suite("without somewhere to hold it, a one-shot body is still refused", async (t) => {
  const transport = flakyTransport(1);
  const interceptor = retrying(undefined);

  await assert.rejects(
    () => interceptor.dispatch(post(chunkedStream(["one shot"])), transport),
    UnreplayableRequestError,
  );
  assert.equal(transport.attempts, 1, "the first attempt happened; the retry did not");
});

suite("a held one-shot body is replayed byte for byte", async (t) => {
  const { bytes, open } = area(t, { memoryThresholdBytes: 8 });
  const transport = flakyTransport(2);
  const interceptor = retrying(spilledRequestBodyStore(await open()));

  const response = await interceptor.dispatch(
    post(chunkedStream(["a body ", "in several ", "pieces"])),
    transport,
  );

  assert.equal(response.status, 200);
  assert.equal(transport.attempts, 3);
  assert.deepEqual(transport.sent, [
    "a body in several pieces",
    "a body in several pieces",
    "a body in several pieces",
  ]);
  assert.deepEqual(
    await bytes.list("spill", none()),
    [],
    "the held body is released when the dispatch settles",
  );
});

suite("a body under the threshold is held without touching the store", async (t) => {
  const { bytes, open } = area(t, { memoryThresholdBytes: 1024 });
  const transport = flakyTransport(1);
  const interceptor = retrying(spilledRequestBodyStore(await open()));

  // Assigned only from inside the dispatch, so it needs to say what it will hold.
  let listedDuring: readonly unknown[] | null = null;
  const watching = {
    async dispatch(request: TransportRequest): Promise<TransportResponse> {
      listedDuring ??= await bytes.list("spill", none());
      return transport.dispatch(request);
    },
  };

  await interceptor.dispatch(post(chunkedStream(["small"])), watching);
  assert.deepEqual(transport.sent, ["small", "small"]);
  assert.deepEqual(listedDuring, [], "nothing was written for a body that fits in memory");
});

suite("a body over the threshold is in the store while it is held", async (t) => {
  const { bytes, open } = area(t, { memoryThresholdBytes: 4 });
  const transport = flakyTransport(1);
  const interceptor = retrying(spilledRequestBodyStore(await open()));

  // Recorded into an array rather than a `let`: the only assignment is inside the dispatch, and
  // control-flow analysis cannot see that it ran, so afterwards the variable reads as still
  // holding its initialiser. Pushing keeps the first observation with the same first-write-wins
  // meaning `??=` had.
  const listedDuring: (readonly unknown[])[] = [];
  const watching = {
    async dispatch(request: TransportRequest): Promise<TransportResponse> {
      const result = await transport.dispatch(request);
      if (listedDuring.length === 0) listedDuring.push(await bytes.list("spill", none()));
      return result;
    },
  };

  // The first attempt fails and the second succeeds; the point is what was in the store
  // while the body was held.
  const response = await interceptor.dispatch(
    post(chunkedStream(["a body larger than the threshold"])),
    watching,
  );
  assert.equal(response.status, 200);
  assert.deepEqual(transport.sent, [
    "a body larger than the threshold",
    "a body larger than the threshold",
  ]);
  assert.equal(
    must(listedDuring[0], "the watcher observed the store during the dispatch").length,
    1,
    "the spilled body is in the store during the dispatch",
  );
  assert.deepEqual(await bytes.list("spill", none()), [], "and gone once the dispatch settles");
});

suite("the held body is released when the dispatch fails too", async (t) => {
  const { bytes, open } = area(t, { memoryThresholdBytes: 4 });
  const failing = {
    attempts: 0,
    async dispatch(request: TransportRequest): Promise<TransportResponse> {
      this.attempts++;
      await consume(request.body);
      throw new TransportError("ECONNRESET", "reset");
    },
  };
  const interceptor = retrying(spilledRequestBodyStore(await open()));

  await assert.rejects(
    () => interceptor.dispatch(post(chunkedStream(["a body larger than the threshold"])), failing),
    TransportError,
  );
  assert.equal(failing.attempts, 4, "the initial attempt and three retries");
  assert.deepEqual(await bytes.list("spill", none()), [], "a failed dispatch releases too");
});

suite("a declared length the body does not have is still an error", async (t) => {
  const { open } = area(t, { memoryThresholdBytes: 4 });
  const transport = flakyTransport(1);
  const interceptor = retrying(spilledRequestBodyStore(await open()));

  // Correcting the length here would turn a caller's inconsistency into a silent
  // success, which is exactly what the refusal is for.
  await assert.rejects(
    () =>
      interceptor.dispatch(
        post(chunkedStream(["twelve bytes"]), { bodyLength: 999 }),
        transport,
      ),
    TypeError,
  );
});

suite("a method this interceptor would not retry is not held", async (t) => {
  const { bytes, open } = area(t, { memoryThresholdBytes: 4 });
  const transport = flakyTransport(1);
  const interceptor = retrying(spilledRequestBodyStore(await open()));

  // Assigned only from inside the dispatch, so it needs to say what it will hold.
  let listedDuring: readonly unknown[] | null = null;
  const watching = {
    async dispatch(request: TransportRequest): Promise<TransportResponse> {
      listedDuring ??= await bytes.list("spill", none());
      return transport.dispatch(request);
    },
  };

  // PUT is not in this interceptor's method list, so the body would be held for a
  // retry that will never be attempted.
  await assert.rejects(
    () =>
      interceptor.dispatch(
        post(chunkedStream(["a body larger than the threshold"]), { method: "PUT" }),
        watching,
      ),
    TransportError,
  );
  assert.deepEqual(listedDuring, [], "nothing was held for an ineligible method");
});

suite("a body that can already replay itself is not held again", async (t) => {
  const { bytes, open } = area(t, { memoryThresholdBytes: 4 });
  const transport = flakyTransport(1);
  const interceptor = retrying(spilledRequestBodyStore(await open()));
  const text = "a body larger than the threshold";
  const source = {
    length: encoder.encode(text).length,
    open: () => chunkedStream([text]),
  };

  // Assigned only from inside the dispatch, so it needs to say what it will hold.
  let listedDuring: readonly unknown[] | null = null;
  const watching = {
    async dispatch(request: TransportRequest): Promise<TransportResponse> {
      listedDuring ??= await bytes.list("spill", none());
      return transport.dispatch(request);
    },
  };

  await interceptor.dispatch(
    post(source.open(), { replayBody: source, bodyLength: source.length }),
    watching,
  );
  assert.deepEqual(transport.sent, [text, text]);
  assert.deepEqual(listedDuring, [], "a body with its own replay source is left alone");
});

import test from "node:test";
import assert from "node:assert/strict";
import {
  AbortController,
  composeFetchTransport,
  Headers,
  ReadableStream,
  RetryAgent,
  RetryExhaustedError,
  TextDecoder,
  TextEncoder,
  TransportError,
  UnreplayableRequestError,
} from "../src/index.ts";
import { createHostNodePrimitives } from "../host/node-primitives.ts";
import { WebPlatformRuntime } from "../src/provider.ts";
import { must } from "./harness.ts";
import type { FetchInterceptor } from "../src/dispatch/interceptor.ts";
import type { RetryDecision } from "../src/dispatch/retry.ts";
import type {
  FetchTransport,
  TransportRequest,
