// Spill-to-disk: the plan's "large payloads are not forced into RAM" row.
//
// The byte store's second consumer, and the first to use its ranged-read side. What
// comes back is a Blob either way, which is the claim worth testing hardest -- a
// consumer of a spilled body must not be able to tell, except by asking.
import assert from "node:assert/strict";
import test from "node:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import {
  AbortController,
  DurableSpillArea,
  ReadableStream,
} from "../src/index.ts";
import { durableStoreFromFlat } from "../src/provider.ts";
import { HostNodeDurableStore } from "../host/node-runtime.ts";
import { FakeFlat } from "./fake-flat.ts";
import type { TestContext } from "node:test";
import { must } from "./harness.ts";
import type { DurableByteStore } from "../src/provider.ts";
import type { AbortSignal } from "../src/index.ts";

const encoder = new TextEncoder();
const none = () => new AbortController().signal;

const BACKENDS = [
  {
    name: "host filesystem",
    make(t: TestContext): DurableByteStore {
      const root = mkdtempSync(join(tmpdir(), "nts-spill-"));
      t.after(() => rmSync(root, { recursive: true, force: true }));
      return new HostNodeDurableStore({ root });
    },
  },
  {
    name: "flat provider through the adapter",
    make() {
      return durableStoreFromFlat(new FakeFlat());
    },
  },
];

/** A stream of `count` chunks of `size` bytes, each filled with its own index. */
/** What a test may observe or provoke while the stream is being read. */
interface StreamHooks {
  readonly failAt?: number;
  readonly failure?: unknown;
  readonly onChunk?: (index: number) => void;
  readonly onCancel?: (reason?: unknown) => void;
}

function chunkedStream(
  count: number,
  size: number,
  hooks: StreamHooks = {},
): ReadableStream<Uint8Array> {
  let index = 0;
  return new ReadableStream<Uint8Array>({
    pull(controller) {
      if (index >= count) {
        controller.close();
        return;
      }
      if (hooks.failAt === index) {
        controller.error(hooks.failure);
        return;
      }
      hooks.onChunk?.(index);
      controller.enqueue(new Uint8Array(size).fill(index % 251));
      index++;
    },
    cancel(reason?: unknown) {
      hooks.onCancel?.(reason);
    },
  });
}

function expectedBytes(count: number, size: number): Uint8Array {
  const out = new Uint8Array(count * size);
  for (let index = 0; index < count; index++) {
    out.fill(index % 251, index * size, (index + 1) * size);
  }
  return out;
}

/** Records what actually reached the store, so "streamed" can be more than a comment. */
function recording(store: DurableByteStore): {
  appends: number[];
  settled: string[];
  store: DurableByteStore;
} {
  const appends: number[] = [];
  const settled: string[] = [];
  return {
    appends,
    settled,
    store: {
      read: (...args: Parameters<DurableByteStore["read"]>) => store.read(...args),
      source: (...args: Parameters<DurableByteStore["source"]>) => store.source(...args),
      delete: (...args: Parameters<DurableByteStore["delete"]>) => store.delete(...args),
      list: (...args: Parameters<DurableByteStore["list"]>) => store.list(...args),
      size: (...args: Parameters<DurableByteStore["size"]>) => store.size(...args),
      close: () => store.close(),
      async write(namespace: string, key: string, signal: AbortSignal) {
        const write = await store.write(namespace, key, signal);
        return {
          async append(bytes: Uint8Array) {
            appends.push(bytes.length);
            await write.append(bytes);
          },
          commit() {
            settled.push("commit");
            return write.commit();
          },
          discard() {
            settled.push("discard");
            return write.discard();
          },
        };
      },
    },
  };
}

for (const backend of BACKENDS) {
  const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
    test(`${name} [${backend.name}]`, fn);
  };

  suite("a body under the threshold never reaches the store", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 4096 });
    const body = await area.spill(chunkedStream(4, 256), none(), "text/plain");

    assert.equal(body.spilled, false);
    assert.equal(body.size, 1024);
    assert.equal(body.blob.size, 1024);
    assert.equal(body.blob.type, "text/plain");
    assert.deepEqual(new Uint8Array(await body.blob.arrayBuffer()), expectedBytes(4, 256));
    assert.deepEqual(await bytes.list("spill", none()), []);
    await body.release();
  });

  suite("a body over the threshold spills and reads back byte for byte", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 1024 });
    const body = await area.spill(chunkedStream(16, 256), none(), "application/octet-stream");

    assert.equal(body.spilled, true);
    assert.equal(body.size, 4096);
    assert.equal(body.blob.size, 4096);
    assert.equal(body.blob.type, "application/octet-stream");
    assert.deepEqual(new Uint8Array(await body.blob.arrayBuffer()), expectedBytes(16, 256));
    assert.equal((await bytes.list("spill", none())).length, 1);

    await body.release();
    assert.deepEqual(await bytes.list("spill", none()), [], "release removes the stored bytes");
    await body.release();
  });

  suite("a spilled blob slices through the store's ranged reads", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 64 });
    const body = await area.spill(chunkedStream(8, 128), none());

    // The whole point of `BlobExternalSource`: a slice reopens the range rather than
    // materialising the body to cut a piece out of it.
    const middle = body.blob.slice(200, 400);
    assert.equal(middle.size, 200);
    assert.deepEqual(
      new Uint8Array(await middle.arrayBuffer()),
      expectedBytes(8, 128).subarray(200, 400),
    );
    // Two slices read independently, which a shared read offset would break.
    const first = body.blob.slice(0, 10);
    const last = body.blob.slice(1014, 1024);
    const [a, b] = await Promise.all([first.arrayBuffer(), last.arrayBuffer()]);
    assert.deepEqual(new Uint8Array(a), expectedBytes(8, 128).subarray(0, 10));
    assert.deepEqual(new Uint8Array(b), expectedBytes(8, 128).subarray(1014, 1024));
    await body.release();
  });

  suite("the body is written as it arrives, not assembled and then written", async (t) => {
    const recorder = recording(backend.make(t));
    const area = await DurableSpillArea.open(recorder.store, { memoryThresholdBytes: 1024 });
    const body = await area.spill(chunkedStream(16, 256), none());

    assert.equal(body.spilled, true);
    // The first append carries what was held while under the threshold; every later
    // chunk goes out on its own. A single append the size of the body would mean the
    // whole thing was in memory, which is the condition this exists to avoid.
    assert.ok(recorder.appends.length > 1, `expected streaming appends, saw ${recorder.appends}`);
    assert.ok(
      Math.max(...recorder.appends) <= 1280,
      `no append may carry the whole body: ${recorder.appends}`,
    );
    assert.equal(
      recorder.appends.reduce((total, size) => total + size, 0),
      4096,
    );
    await body.release();
  });

  suite("a body past the byte limit is refused and leaves nothing", async (t) => {
    const recorder = recording(backend.make(t));
    const bytes = recorder.store;
    const area = await DurableSpillArea.open(bytes, {
      memoryThresholdBytes: 128,
      maxBytes: 512,
    });
    // Captured from inside the cancel hook, so it says what it will hold.
    let cancelled: unknown;
    const stream = chunkedStream(16, 256, { onCancel: (reason) => (cancelled = reason) });

    await assert.rejects(() => area.spill(stream, none()), { name: "LimitError" });
    assert.ok(cancelled instanceof Error, "the producer was cancelled with an Error");
    assert.equal(cancelled.name, "LimitError", "the producer is told to stop");
    assert.deepEqual(await bytes.list("spill", none()), []);
    // An empty namespace is not proof the write went away: an uncommitted write is
    // invisible to `list` and still holds its key. The discard has to be observed.
    assert.deepEqual(recorder.settled, ["discard"]);
  });

  suite("an abort mid-body rejects with the exact reason and leaves nothing", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 128 });
    const controller = new AbortController();
    const reason = new Error("the caller gave up");
    // Captured from inside the cancel hook, so it says what it will hold.
    let cancelled: unknown;
    const stream = chunkedStream(16, 256, {
      onChunk: (index) => {
        if (index === 4) controller.abort(reason);
      },
      onCancel: (value) => (cancelled = value),
    });

    await assert.rejects(
      () => area.spill(stream, controller.signal),
      (thrown) => thrown === reason,
    );
    assert.equal(cancelled, reason);
    assert.deepEqual(await bytes.list("spill", none()), []);
  });

  suite("an already-aborted signal is refused without consuming the stream", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 8 });
    const controller = new AbortController();
    const reason = new Error("too late");
    controller.abort(reason);
    let cancelled = false;
    const stream = chunkedStream(4, 8, { onCancel: () => (cancelled = true) });

    await assert.rejects(
      () => area.spill(stream, controller.signal),
      (thrown) => thrown === reason,
    );
    assert.deepEqual(await bytes.list("spill", none()), []);
    // Not "no chunk was pulled" -- a stream fills its queue on construction, so that
    // would pass without anyone reading it. The claim is that spill left the stream
    // usable: neither cancelled nor part-consumed, so a caller can try again.
    assert.equal(cancelled, false);
    assert.equal(stream.locked, false);
    const retried = await area.spill(stream, none());
    assert.deepEqual(new Uint8Array(await retried.blob.arrayBuffer()), expectedBytes(4, 8));
    await retried.release();
  });

  suite("a stream that fails part way leaves nothing behind", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 128 });
    const failure = new Error("the producer broke");
    const stream = chunkedStream(16, 256, { failAt: 6, failure });

    await assert.rejects(
      () => area.spill(stream, none()),
      (thrown) => thrown === failure,
    );
    assert.deepEqual(await bytes.list("spill", none()), []);
  });

  suite("concurrent spills get their own keys and read back independently", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 64 });
    const [first, second] = await Promise.all([
      area.spill(chunkedStream(4, 128), none()),
      area.spill(chunkedStream(6, 128), none()),
    ]);

    assert.equal(first.spilled, true);
    assert.equal(second.spilled, true);
    assert.equal((await bytes.list("spill", none())).length, 2);
    assert.deepEqual(new Uint8Array(await first.blob.arrayBuffer()), expectedBytes(4, 128));
    assert.deepEqual(new Uint8Array(await second.blob.arrayBuffer()), expectedBytes(6, 128));

    await first.release();
    assert.equal((await bytes.list("spill", none())).length, 1, "one release, one survivor");
    assert.deepEqual(new Uint8Array(await second.blob.arrayBuffer()), expectedBytes(6, 128));
    await second.release();
  });

  suite("opening the area discards whatever the last run left", async (t) => {
    const bytes = backend.make(t);
    const first = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 64 });
    const stranded = await first.spill(chunkedStream(4, 128), none());
    assert.equal(stranded.spilled, true);
    assert.equal((await bytes.list("spill", none())).length, 1);

    // Nothing can name it again, so it is not data -- it is a leak.
    await DurableSpillArea.open(bytes);
    assert.deepEqual(await bytes.list("spill", none()), []);
  });

  suite("an empty body is a zero-length blob and touches nothing", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 0 });
    const body = await area.spill(chunkedStream(0, 0), none());
    assert.equal(body.spilled, false);
    assert.equal(body.size, 0);
    assert.equal(body.blob.size, 0);
    assert.deepEqual(await bytes.list("spill", none()), []);
  });

  suite("a zero threshold spills the very first chunk", async (t) => {
    const bytes = backend.make(t);
    const area = await DurableSpillArea.open(bytes, { memoryThresholdBytes: 0 });
    const body = await area.spill(chunkedStream(3, 32), none());
    assert.equal(body.spilled, true);
    assert.deepEqual(new Uint8Array(await body.blob.arrayBuffer()), expectedBytes(3, 32));
    await body.release();
  });
}

import assert from "node:assert/strict";
import test from "node:test";

import { ReadableStream, WritableStream } from "../src/index.ts";

// Moving a chunk must not be observable to a page that has replaced `Object.prototype.then`.
//
// Resolving a promise *with* an ordinary object performs a `Get` for `then` on it, so any
// internal path that hands a caller a `{ done, value }` through a promise lets a replaced `then`
// see every chunk the stream carries -- and call into it, and lie about it. The specification
// avoids this by giving internal consumers *read requests*, whose steps take the value directly,
// and building a promise only at the public `read()`.
//
// `then-interception.any.js` upstream asserts this for piping and teeing on a **default**
// stream, and it is pinned. It says nothing about byte streams, about the async iterator, or
// about `tee` on a byte source -- and the byte path was still observable after the default path
// was fixed, which is why this file exists. Upstream tests what upstream tests; the hole was
// found by asking whether the fix covered the cases upstream does not.
//
// **The interception must be well-behaved.** It calls the resolver it is handed. A `then` that
// does not is not a test of streams -- it takes the module system down with it, and did once.

/** The upstream fixture's interceptor, which records what it was allowed to see. */
function interceptThen(): unknown[] {
  const intercepted: unknown[] = [];
  let callCount = 0;
  (Object.prototype as unknown as { then?: unknown }).then = function (
    this: { done?: unknown; value?: unknown },
    resolve: (value: unknown) => void,
  ): void {
    if (!this.done) intercepted.push(this.value);
    const retval = Object.create(null) as { done: boolean; value: number };
    retval.done = ++callCount === 3;
    retval.value = callCount;
    resolve(retval);
    if (retval.done) delete (Object.prototype as unknown as { then?: unknown }).then;
  };
  return intercepted;
}

function releaseThen(): void {
  delete (Object.prototype as unknown as { then?: unknown }).then;
}

function defaultStream(): ReadableStream<string> {
  return new ReadableStream<string>({
    start(controller) {
      controller.enqueue("a");
      controller.close();
    },
  });
}

function byteStream(): ReadableStream<Uint8Array> {
  return new ReadableStream<Uint8Array>({
    type: "bytes",
    start(controller) {
      controller.enqueue(new Uint8Array([1, 2, 3]));
      controller.close();
    },
  });
}

const suite = (name: string, fn: () => Promise<void>): void => {
  void test(name, fn);
};

async function pipeUnobserved<T>(source: ReadableStream<T>): Promise<unknown[]> {
  const written: unknown[] = [];
  const sink = new WritableStream<T>({
    write(chunk) {
      written.push(chunk);
    },
  });
  const intercepted = interceptThen();
  try {
    await source.pipeTo(sink);
  } finally {
    releaseThen();
  }
  assert.equal(written.length, 1, "the chunk should still have been written");
  return intercepted;
}

suite("piping a default stream is not observable through Object.prototype.then", async () => {
  assert.deepEqual(await pipeUnobserved(defaultStream()), []);
});

suite("piping a byte stream is not observable through Object.prototype.then", async () => {
  // Upstream does not cover this and it was observable until the byte read path took a read
  // request too. `readDefault` returning a promise was the last place a chunk reached a caller
  // as the resolution value of one.
  assert.deepEqual(await pipeUnobserved(byteStream()), []);
});

/**
 * Both branches, one at a time.
 *
 * `Promise.all` cannot be used here and the reason is the subject of the file: it resolves with
 * an **array**, which is an ordinary object, so awaiting it performs exactly the `Get` for
 * `then` being measured and the harness reports its own interception as the stream's. That cost
 * three failing tests before it was spotted.
 */
async function teeUnobserved<T>(source: ReadableStream<T>): Promise<unknown[]> {
  const [first, second] = source.tee();
  const intercepted = interceptThen();
  try {
    await first.pipeTo(new WritableStream<T>());
    await second.pipeTo(new WritableStream<T>());
  } finally {
    releaseThen();
  }
  return intercepted;
}

suite("teeing a default stream is not observable", async () => {
  assert.deepEqual(await teeUnobserved(defaultStream()), []);
});

suite("teeing a byte stream is not observable", async () => {
  assert.deepEqual(await teeUnobserved(byteStream()), []);
});

suite("async iteration IS observable, because the standard says the result is an object", async () => {
  // Not a gap. 27.1.2 requires `next()` to fulfil with an ordinary `IteratorResult`, so `then`
  // is findable on it by construction, and upstream's `then-interception.any.js` covers piping
  // and teeing only -- it does not ask this of iteration.
  //
  // Pinned in the direction it actually holds, so that nobody "fixes" it into a spec violation
  // and so the three tests above are not quietly weakened to match it.
  const seen: string[] = [];
  const stream = defaultStream();
  const intercepted = interceptThen();
  try {
    for await (const chunk of stream) seen.push(chunk);
  } finally {
    releaseThen();
  }
  assert.ok(
    intercepted.length > 0,
    "the iterator result is an ordinary object and `then` is found on it",
  );
});

suite("the public read() still resolves with an ordinary object, as the standard requires", async () => {
  // The other side of the rule, so a future change cannot satisfy the tests above by making
  // `read()` resolve with something exotic. 25.5 says the result is an ordinary object, and its
  // prototype being `Object.prototype` is exactly what makes `then` findable on it.
  const reader = defaultStream().getReader();
  const result = await reader.read();
  assert.equal(Object.getPrototypeOf(result), Object.prototype);
  assert.deepEqual(Object.keys(result).sort(), ["done", "value"]);
  assert.equal(result.done, false);
  assert.equal(result.value, "a");
});

// Specification controls for source-policy edge cases absent from the pinned WPT.
// Upstream fixtures remain unedited in test/wpt/streams/.
import "../host/environment-shim.ts";
import assert from "node:assert/strict";
import test from "node:test";
import { ReadableStream } from "../src/streams/readable.ts";
import { CountQueuingStrategy } from "../src/streams/count-queuing-strategy.ts";
import { ByteLengthQueuingStrategy } from "../src/streams/byte-length-queuing-strategy.ts";
import type { QueuingStrategyInit } from "../src/streams/queuing-strategy.ts";
import type {
  ReadableByteStreamController,
  ReadableStreamBYOBView,
  UnderlyingByteSource,
} from "../src/streams/readable.ts";

const nextTurn = (): Promise<void> => new Promise((resolve) => setImmediate(resolve));

// https://streams.spec.whatwg.org/#readable-byte-stream-controller-pull-into
// Step 16.2 errors any queued underfill after close, including whole elements.
for (const fixture of [
  { name: "Uint8Array", bytes: [1, 2], view: (): ReadableStreamBYOBView => new Uint8Array(4) },
  { name: "Uint16Array", bytes: [1, 2, 3, 4], view: (): ReadableStreamBYOBView => new Uint16Array(4) },
]) {
  test(`BYOB aligned ${fixture.name} underfill after close rejects read and closed`, async (t) => {
    let controller!: ReadableByteStreamController;
    const callbacks: string[] = [];
    const stream = new ReadableStream({
      type: "bytes",
      start(value) {
        controller = value;
        value.enqueue(new Uint8Array(fixture.bytes));
        value.close();
      },
      pull() { callbacks.push("pull"); },
      cancel() { callbacks.push("cancel"); },
    });
    const reader = stream.getReader({ mode: "byob" });
    t.after(async () => { await reader.cancel().catch(() => {}); });
    const order: string[] = [];
    let readError: unknown;
    let closedError: unknown;
    void reader.closed.then(
      () => { order.push("closed fulfilled"); },
      (error: unknown) => { closedError = error; order.push("closed rejected"); },
    );
    void reader.read(fixture.view(), { min: 4 }).then(
      () => { order.push("read fulfilled"); },
      (error: unknown) => { readError = error; order.push("read rejected"); },
    );
    // The queued bytes and close request are already available. A task turn lets
    // their promise reactions run without waiting forever on the defective path.
    await nextTurn();
    assert.deepEqual(order, ["closed rejected", "read rejected"]);
    assert.ok(readError instanceof TypeError);
    assert.equal(readError, closedError);
    assert.equal(controller.desiredSize, null);
    assert.throws(() => controller.enqueue(new Uint8Array([5])), TypeError);
    assert.deepEqual(callbacks, []);
  });
}

test("BYOB minimum met by the final queued chunk succeeds before the closed read", async () => {
  const stream = new ReadableStream({
    type: "bytes",
    start(controller) {
      controller.enqueue(new Uint8Array([1, 2, 3, 4]));
      controller.close();
    },
  });
  const reader = stream.getReader({ mode: "byob" });
  const chunk = await reader.read(new Uint8Array(4), { min: 4 });
  assert.equal(chunk.done, false);
  assert.deepEqual(chunk.value, new Uint8Array([1, 2, 3, 4]));
  await reader.closed;
  const end = await reader.read(new Uint8Array(4), { min: 4 });
  assert.equal(end.done, true);
  assert.equal(end.value?.byteLength, 0);
});

// https://streams.spec.whatwg.org/#readable-stream-cancel
// Closing precedes the underlying cancellation callback, including for bytes.
test("byte cancellation invokes the saved callback with a closed controller", async () => {
  let controller!: ReadableByteStreamController;
  let calls = 0;
  let receiver: UnderlyingByteSource | undefined;
  let receivedReason: unknown;
  let desiredSize: number | null | undefined;
  let enqueueError: unknown;
  let closeError: unknown;
  const source: UnderlyingByteSource = {
    type: "bytes",
    start(value) { controller = value; },
    cancel(reason) {
      calls++;
      receiver = this;
      receivedReason = reason;
      desiredSize = controller.desiredSize;
      try { controller.enqueue(new Uint8Array([1])); }
      catch (error) { enqueueError = error; }
      try { controller.close(); }
      catch (error) { closeError = error; }
    },
  };
  const stream = new ReadableStream(source, { highWaterMark: 2 });
  const reason = {};
  await stream.cancel(reason);
  await stream.cancel("second cancellation");
  assert.equal(calls, 1);
  assert.equal(receiver, source);
  assert.equal(receivedReason, reason);
  assert.equal(desiredSize, 0);
  assert.ok(enqueueError instanceof TypeError);
  assert.ok(closeError instanceof TypeError);
  const end = await stream.getReader().read();
  assert.deepEqual(end, { done: true, value: undefined });
});

test("byte cancellation closes pending reads before a callback error rejects cancellation", async () => {
  let controller!: ReadableByteStreamController;
  const callbackError = new Error("underlying cancellation failed");
  const ignoredError = new Error("error after cancellation closed the stream");
  const events: string[] = [];
  const stream = new ReadableStream({
    type: "bytes",
    start(value) { controller = value; },
    cancel() {
      events.push("cancel callback");
      controller.error(ignoredError);
      throw callbackError;
    },
  });
  const reader = stream.getReader({ mode: "byob" });
  const closed = reader.closed.then(
    () => { events.push("closed fulfilled"); },
    () => { events.push("closed rejected"); },
  );
  const read = reader.read(new Uint8Array(4)).then(
    (result) => {
      events.push("read fulfilled");
      assert.deepEqual(result, { done: true, value: undefined });
    },
    () => { events.push("read rejected"); },
  );
  const cancellation = reader.cancel("reason").then(
    () => { assert.fail("the underlying cancellation error must reject cancellation"); },
    (error: unknown) => {
      events.push("cancel rejected");
      assert.equal(error, callbackError);
    },
  );
  await Promise.all([closed, read, cancellation]);
  assert.deepEqual(events, ["cancel callback", "closed fulfilled", "read fulfilled", "cancel rejected"]);
  assert.equal(controller.desiredSize, 0);
});

// https://webidl.spec.whatwg.org/#es-dictionary
// A required dictionary member with value undefined is missing, even if present.
for (const Strategy of [CountQueuingStrategy, ByteLengthQueuingStrategy]) {
  test(`${Strategy.name} rejects an undefined required highWaterMark after one getter read`, () => {
    let reads = 0;
    const init = {
      get highWaterMark(): number | undefined {
        reads++;
        return undefined;
      },
    };
    assert.throws(() => new Strategy(init as QueuingStrategyInit), TypeError);
    assert.equal(reads, 1);
    assert.throws(() => new Strategy({} as QueuingStrategyInit), TypeError);
  });

  test(`${Strategy.name} gets and converts highWaterMark once before starting a stream`, async () => {
    const order: string[] = [];
    const number = {
      valueOf(): number {
        order.push("convert");
        return 2;
      },
    };
    const init = {
      get highWaterMark(): number {
        order.push("get");
        return number as unknown as number;
      },
    };
    let desiredSize: number | null | undefined;
    const stream = new ReadableStream<Uint8Array<ArrayBuffer>>({
      start(controller) {
        order.push("start");
        controller.enqueue(new Uint8Array([7]));
        desiredSize = controller.desiredSize;
        controller.close();
      },
    }, new Strategy(init));
    assert.deepEqual(order, ["get", "convert", "start"]);
    assert.equal(desiredSize, 1);
    const result = await stream.getReader().read();
    assert.equal(result.done, false);
    assert.deepEqual(result.value, new Uint8Array([7]));
  });

  test(`${Strategy.name} propagates a dictionary getter error before a stream starts`, () => {
    const order: string[] = [];
    const error = new Error("highWaterMark getter failed");
    const init = {
      get highWaterMark(): number {
        order.push("get");
        throw error;
      },
    };
    assert.throws(() => new ReadableStream<Uint8Array<ArrayBuffer>>({
      start() { order.push("start"); },
    }, new Strategy(init)), (thrown: unknown) => thrown === error);
    assert.deepEqual(order, ["get"]);
  });
}

// Test-only deterministic driver for the explicit global-error engine contract.
// It is not a native global/Promise adapter and must never enter src/ or host/.
import assert from "node:assert/strict";
import type { TestContext } from "node:test";
import { GlobalErrorRuntime } from "../../src/core/global-errors.ts";
import { ErrorEvent, Event, eventBegin, eventEnd, eventStopped } from "../../src/core/events.ts";
import type { EventTarget } from "../../src/core/events.ts";
import type {
  GlobalErrorCapabilities, GlobalErrorEventData, GlobalErrorEventType, GlobalErrorInformation,
  GlobalErrorListener, GlobalExceptionReporter, GlobalWorkerErrorOwner,
  GlobalHandlerArguments, GlobalHandlerCallback, GlobalHandlerInvocationResult,
  GlobalHandlerContext,
} from "../../src/provider/global-errors.ts";

// Test-only intrinsic reads over the source classes. Native bindings access
// their known layouts directly; source policy must not use this reflection.
const eventType = Object.getOwnPropertyDescriptor(Event.prototype, "type")!.get!;
const errorMessage = Object.getOwnPropertyDescriptor(ErrorEvent.prototype, "message")!.get!;
const errorFilename = Object.getOwnPropertyDescriptor(ErrorEvent.prototype, "filename")!.get!;
const errorLine = Object.getOwnPropertyDescriptor(ErrorEvent.prototype, "lineno")!.get!;
const errorColumn = Object.getOwnPropertyDescriptor(ErrorEvent.prototype, "colno")!.get!;
const errorValue = Object.getOwnPropertyDescriptor(ErrorEvent.prototype, "error")!.get!;

interface HandlerInvocation {
  readonly callback: GlobalHandlerCallback;
  readonly receiver: object;
  readonly args: GlobalHandlerArguments;
  readonly context: GlobalHandlerContext;
}

class Listener {
  readonly type: GlobalErrorEventType;
  readonly callback: GlobalErrorListener;
  removed = false;
  constructor(type: GlobalErrorEventType, callback: GlobalErrorListener) {
    this.type = type;
    this.callback = callback;
  }
}

class PromiseState {
  handled = false;
  readonly result: unknown;
  constructor(result: unknown) { this.result = result; }
}

export class ErrorDriver implements GlobalErrorCapabilities {
  readonly globalObject = globalThis;
  readonly listeners: Listener[] = [];
  readonly tasks: (() => void)[] = [];
  readonly events: Event[] = [];
  readonly errors: unknown[] = [];
  readonly rejections: unknown[] = [];
  readonly extractions: unknown[] = [];
  readonly errorEventReads: ErrorEvent[] = [];
  readonly reads: string[] = [];
  readonly invocations: HandlerInvocation[] = [];
  readonly capturedContexts: GlobalHandlerContext[] = [];
  incumbentContext: GlobalHandlerContext = {};
  readonly inactiveHandlers = new WeakSet<GlobalHandlerCallback>();
  invocationCleanup: (() => void) | undefined = undefined;
  readonly globalDestinations = new WeakMap<object, GlobalExceptionReporter>();
  readonly promises = new WeakMap<object, PromiseState>();
  readonly runtime: GlobalErrorRuntime;
  dedicatedWorkerOwner: GlobalWorkerErrorOwner | undefined;
  information: GlobalErrorInformation = {
    message: "provider message", filename: "provider-source.ts", lineno: 23, colno: 7, muted: false,
  };

  constructor() { this.runtime = new GlobalErrorRuntime(this); }
  resolveGlobalReporter(receiver: object): GlobalExceptionReporter | null {
    return this.globalDestinations.get(receiver) ?? null;
  }
  extractErrorInformation(exception: unknown): GlobalErrorInformation {
    this.extractions.push(exception);
    return this.information;
  }
  readErrorEventData(event: ErrorEvent): GlobalErrorEventData {
    this.errorEventReads.push(event);
    return {
      message: errorMessage.call(event), filename: errorFilename.call(event),
      lineno: errorLine.call(event), colno: errorColumn.call(event), error: errorValue.call(event),
    };
  }
  addGlobalEventListener(type: GlobalErrorEventType, callback: GlobalErrorListener): void {
    this.listeners.push(new Listener(type, callback));
  }
  removeGlobalEventListener(type: GlobalErrorEventType, callback: GlobalErrorListener): void {
    for (const listener of this.listeners) {
      if (listener.type === type && listener.callback === callback) listener.removed = true;
    }
  }
  captureGlobalHandlerContext(): GlobalHandlerContext {
    // Opaque identity tags exercise source retention only. This driver does not
    // implement HTML settings objects or infer context from an actual JS realm.
    const context = this.incumbentContext;
    this.capturedContexts.push(context);
    return context;
  }
  invokeGlobalHandler(
    callback: GlobalHandlerCallback, receiver: object, args: GlobalHandlerArguments,
    context: GlobalHandlerContext,
  ): GlobalHandlerInvocationResult {
    this.invocations.push({ callback, receiver, args, context });
    if (this.inactiveHandlers.has(callback)) return { ok: true, value: undefined };
    let result: GlobalHandlerInvocationResult;
    try { result = { ok: true, value: Reflect.apply(callback, receiver, args) }; }
    catch (error) { result = { ok: false, error }; }
    // Deterministic test boundary only. A production provider supplies actual
    // realm preparation, callback cleanup and its engine's checkpoint behavior.
    this.invocationCleanup?.();
    return result;
  }
  dispatchGlobalEvent(event: Event, reportException: (exception: unknown) => void): boolean {
    this.events.push(event);
    const type: string = eventType.call(event);
    // The internal Event hooks let this deterministic driver exercise actual
    // canonical event cancellation/trust. A production native global binding
    // still has to supply its complete listener semantics and callback cleanup.
    event[eventBegin](globalThis as unknown as EventTarget, true);
    try {
      for (const listener of this.listeners.slice()) {
        if (event[eventStopped]) break;
        if (listener.removed || listener.type !== type) continue;
        try { listener.callback(event); }
        catch (error) { reportException(error); }
      }
    } finally { event[eventEnd](); }
    return !event.defaultPrevented;
  }
  enqueueGlobalTask(task: () => void): void { this.tasks.push(task); }
  promiseIsHandled(promise: object): boolean {
    const state = this.promises.get(promise);
    assert.ok(state, "test promise must have actual driver state");
    return state.handled;
  }
  promiseResult(promise: object): unknown {
    const state = this.promises.get(promise);
    assert.ok(state, "test promise must have actual driver state");
    return state.result;
  }
  reportExceptionToConsole(exception: unknown): void { this.errors.push(exception); }
  reportRejectionToConsole(reason: unknown): void { this.rejections.push(reason); }

  report(exception: unknown): void { this.runtime.reportError.call(globalThis, exception); }
  promise(reason: unknown, value: object = {}): object {
    this.promises.set(value, new PromiseState(reason));
    return value;
  }
  handle(promise: object): void {
    const state = this.promises.get(promise);
    assert.ok(state);
    state.handled = true;
    this.runtime.hostPromiseRejectionTracker(promise, "handle");
  }
  task(): void {
    const task = this.tasks.shift();
    assert.ok(task, "expected a queued global task");
    task();
  }
}

export function driver(t: TestContext): ErrorDriver {
  const driver = new ErrorDriver();
  // Test-only bootstrap of this process's actual globals. Production source
  // contains no Object.defineProperty or globalThis writes. Every descriptor is
  // restored, so the module never leaves handlers in Node's own environment.
  for (const name of ["onerror", "onunhandledrejection", "onrejectionhandled"] as const) {
    const old = Object.getOwnPropertyDescriptor(globalThis, name);
    Object.defineProperty(globalThis, name, {
      configurable: true,
      get() { driver.reads.push(name); return driver.runtime[name]; },
      set(value: object | null) { driver.runtime[name] = value; },
    });
    t.after(() => {
      if (old === undefined) delete (globalThis as Record<string, unknown>)[name];
      else Object.defineProperty(globalThis, name, old);
    });
  }
  return driver;
}

// `TextDecoder` against node's, across encodings, options and chunk boundaries.
//
// The pinned WPT fixtures cover the standard's cases. This covers the *combinations* —
// three encodings against `fatal` against `ignoreBOM` against arbitrary streaming splits
// — which is where a decoder with correct pieces still gets the interaction wrong, and
// which no fixture enumerates because the product is large and boring.
//
// UTF-16 landed today, so it is the newest code in this lane and the least exercised by
// anything other than the fixtures that motivated it. Node's `TextDecoder` is a genuine
// independent implementation rather than a reimplementation of the thing under test,
// which is the property that makes a differential worth running.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import { TextDecoder } from "../src/index.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const NativeTextDecoder = globalThis.TextDecoder;

const ENCODINGS = ["utf-8", "utf-16le", "utf-16be"];

function generator(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

/** Bytes with a deliberate bias towards the shapes that break decoders. */
function bytesFor(random: () => number): Uint8Array {
  const length = Math.floor(random() * 14);
  const out: number[] = [];
  for (let index = 0; index < length; index++) {
    const pick = random();
    if (pick < 0.3) out.push(Math.floor(random() * 0x80));
    else if (pick < 0.45) out.push(0x80 + Math.floor(random() * 0x40)); // continuations
    else if (pick < 0.6) out.push(0xc0 + Math.floor(random() * 0x40)); // lead bytes
    else if (pick < 0.7) out.push(0xd8 + Math.floor(random() * 0x08)); // UTF-16 surrogate halves
    else if (pick < 0.8) out.push(0xef, 0xbb, 0xbf); // a UTF-8 BOM, mid-stream too
    else if (pick < 0.9) out.push(0xff, 0xfe); // a UTF-16LE BOM
    else out.push(Math.floor(random() * 256));
  }
  return Uint8Array.from(out);
}

/**
 * The decoding surface this compares, structurally.
 *
 * Structural rather than `TextDecoder`, because the whole point is to run node's decoder and
 * the platform's through the same function; they are different types from different realms
 * and only their shape is shared.
 */
interface StreamingDecoder {
  decode(input: Uint8Array, options: { stream: boolean }): string;
}

/** What a decoder did, as a value, so throwing and returning compare the same way. */
interface DecodeOutcome {
  readonly text?: string;
  readonly threw?: string;
}

function outcome(decoder: StreamingDecoder, chunks: readonly Uint8Array[]): DecodeOutcome {
  try {
    let text = "";
    // `entries` rather than an index, so the chunk is not typed as possibly absent under
    // `noUncheckedIndexedAccess` and does not need an assertion to say what the loop bound
    // already guarantees.
    for (const [index, chunk] of chunks.entries()) {
      text += decoder.decode(chunk, { stream: index < chunks.length - 1 });
    }
    return { text };
  } catch (error) {
    // A caught value is `unknown`, and only an Error carries a meaningful constructor name.
    return { threw: error instanceof Error ? error.constructor.name : "Error" };
  }
}

function split(bytes: Uint8Array, random: () => number): Uint8Array[] {
  const pieces: Uint8Array[] = [];
  let offset = 0;
  while (offset < bytes.length) {
    const take = 1 + Math.floor(random() * 4);
    pieces.push(bytes.subarray(offset, Math.min(offset + take, bytes.length)));
    offset += take;
  }
  return pieces.length === 0 ? [bytes] : pieces;
}

for (const encoding of ENCODINGS) {
  for (const fatal of [false, true]) {
    for (const ignoreBOM of [false, true]) {
      const label = `${encoding} fatal=${fatal} ignoreBOM=${ignoreBOM}`;

      suite(`whole-buffer decode matches node: ${label}`, () => {
        const random = generator(0x1234 + encoding.length * 7 + (fatal ? 1 : 0) * 31 + (ignoreBOM ? 1 : 0) * 71);
        for (let n = 0; n < 4000; n++) {
          const bytes = bytesFor(random);
          const mine = outcome(new TextDecoder(encoding, { fatal, ignoreBOM }), [bytes]);
          const theirs = outcome(new NativeTextDecoder(encoding, { fatal, ignoreBOM }), [bytes]);
          assert.deepEqual(mine, theirs, `${label} :: ${JSON.stringify([...bytes])}`);
        }
      });

      suite(`a split changes nothing about the result: ${label}`, () => {
        // A chunk boundary in the middle of a sequence is the whole difficulty of a
        // streaming decoder, and the split is where an implementation with correct
        // pieces still loses or duplicates a code point.
        //
        // The oracle here is **this decoder's own whole-buffer result**, not node's, and
        // that is a deliberate downgrade with a reason. Node's streamed and whole-buffer
        // results disagree with each other for a `EF BB BF` that arrives after a chunk
        // boundary but is not at the start of the stream: `[EA EF BB BF 41]` decoded in
        // one call gives `U+FFFD U+FEFF U+0041`, and split gives `U+FFFD U+0041`. A BOM
        // is removed only when the stream *starts* with one, so the first answer is the
        // standard's and the second drops a code point that is data. An oracle that
        // contradicts itself cannot arbitrate the case it disagrees on.
        //
        // What survives is stronger than it sounds: chunking must not be observable, and
        // that property catches every split-boundary defect without borrowing anyone's
        // opinion about the BOM.
        const random = generator(0x9abc + encoding.length * 13 + (fatal ? 1 : 0) * 17 + (ignoreBOM ? 1 : 0) * 53);
        for (let n = 0; n < 3000; n++) {
          const bytes = bytesFor(random);
          const chunks = split(bytes, random);
          const streamed = outcome(new TextDecoder(encoding, { fatal, ignoreBOM }), chunks);
          const whole = outcome(new TextDecoder(encoding, { fatal, ignoreBOM }), [bytes]);
          assert.deepEqual(
            streamed,
            whole,
            `${label} :: ${JSON.stringify([...bytes])} split ${chunks.map((c) => c.length).join("/")}`,
          );
        }
      });
    }
  }
}

suite("node's answer depends on where the chunk boundary falls; this one does not", () => {
  // The case that cost node its role as a streaming oracle, pinned so the claim is
  // checked rather than asserted -- and pinned in the sharper form the NodeJS lane
  // established when they verified it, because the weaker form has a charitable reading
  // this one removes.
  //
  // A `EF BB BF` that is not at the start of the stream is U+FEFF and is data. Node
  // agrees when the bytes arrive whole, one at a time, or straddling a boundary. It
  // drops the code point only when a *complete* `EF BB BF` begins at the head of a
  // decode call that follows a call which emitted nothing.
  //
  // That rules out "streaming is allowed to differ": there is no rule under which
  // 1/1/1/1/1 and 4/1 are right and 1/3/1 is wrong. The answer depends on where the
  // boundary falls, which no reading of the standard makes defensible.
  const bytes = [0xea, 0xef, 0xbb, 0xbf, 0x41];
  const chunksOf = (sizes: readonly number[]): Uint8Array[] => {
    const out: Uint8Array[] = [];
    let offset = 0;
    for (const size of sizes) {
      out.push(Uint8Array.from(bytes.slice(offset, offset + size)));
      offset += size;
    }
    return out;
  };
  // Nine splits, built in three passes by two lanes each verifying the last. `1/2/2` is
  // the row that does the work: same empty first chunk as the two failures, but an
  // incomplete `EF BB` at the head, and node gets it right -- so the trigger needs both
  // halves and neither alone.
  const splits = [
    [5],
    [1, 3, 1],
    [1, 1, 1, 1, 1],
    [4, 1],
    [2, 3],
    [1, 4],
    [3, 2],
    [1, 2, 2],
    [2, 2, 1],
  ];
  const correct = "\uFFFD\uFEFF\u0041";

  const nodeAnswers = new Set();
  for (const sizes of splits) {
    const mine = outcome(new TextDecoder("utf-8"), chunksOf(sizes));
    assert.deepEqual(mine, { text: correct }, `this decoder, split ${sizes.join("/")}`);
    nodeAnswers.add(outcome(new NativeTextDecoder("utf-8"), chunksOf(sizes)).text);
  }

  // If node ever becomes self-consistent here, this fails and the workaround above --
  // comparing streamed output against this decoder's own whole-buffer output rather than
  // against node's -- can be reconsidered. A workaround whose reason has quietly expired
  // is worse than the bug it was for.
  assert.equal(
    nodeAnswers.size,
    2,
    `node gave ${nodeAnswers.size} distinct answers for one byte sequence: ${[...nodeAnswers]
      .map((text) => JSON.stringify(text))
      .join(" and ")}`,
  );
  // The two node answers it does give: the standard's, and the one missing U+FEFF.
  assert.ok(nodeAnswers.has(correct));
  assert.ok(nodeAnswers.has("\uFFFD\u0041"));
});

suite("the encoding name reported is the one the standard names", () => {
  // `utf-16` is a label for UTF-16LE, which reads as a mistake and is not one.
  for (const [label, expected] of [
    ["utf-8", "utf-8"],
    ["UTF-8", "utf-8"],
    ["utf-16", "utf-16le"],
    ["utf-16le", "utf-16le"],
    ["ucs-2", "utf-16le"],
    ["unicodefeff", "utf-16le"],
    ["utf-16be", "utf-16be"],
    ["unicodefffe", "utf-16be"],
  ]) {
    assert.equal(new TextDecoder(label).encoding, expected, label);
    assert.equal(new NativeTextDecoder(label).encoding, expected, `${label} (node)`);
  }
});

// Private test certificate generated in a temporary directory, never trusted globally.
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execFileSync } from "node:child_process";

/** A key and certificate in PEM, as `node:tls` wants them. */
export interface TlsFixture {
  readonly key: Buffer;
  readonly cert: Buffer;
}

let fixture: TlsFixture | undefined;
export function tlsFixture(): TlsFixture {
  if (fixture) return fixture;
  const dir = mkdtempSync(join(tmpdir(), "nts-web-tls-"));
  try {
    execFileSync(
      "openssl",
      [
        "req",
        "-x509",
        "-newkey",
        "rsa:2048",
        "-nodes",
        "-sha256",
        "-days",
        "2",
        "-subj",
        "/CN=NTS test only",
        "-addext",
        "subjectAltName=IP:127.0.0.1,DNS:target.test",
        "-keyout",
        join(dir, "key.pem"),
        "-out",
        join(dir, "cert.pem"),
      ],
      { stdio: "ignore" },
    );
    fixture = {
      key: readFileSync(join(dir, "key.pem")),
      cert: readFileSync(join(dir, "cert.pem")),
    };
    return fixture;
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

const named = new Map<string, TlsFixture>();

/**
 * A private certificate presenting exactly the given subjectAltName entries.
 *
 * Connection reuse decisions read dNSName SANs, so a test that exercises them needs a
 * certificate covering more than one name. Entries are passed through verbatim, for
 * example `"DNS:alpha.test"` or `"IP:127.0.0.1"`.
 */
export function tlsFixtureFor(entries: readonly string[]): TlsFixture {
  const subjectAltName = entries.join(",");
  const cached = named.get(subjectAltName);
  if (cached) return cached;
  const dir = mkdtempSync(join(tmpdir(), "nts-web-tls-"));
  try {
    execFileSync(
      "openssl",
      [
        "req",
        "-x509",
        "-newkey",
        "rsa:2048",
        "-nodes",
        "-sha256",
        "-days",
        "2",
        "-subj",
        "/CN=NTS test only",
        "-addext",
        "subjectAltName=" + subjectAltName,
        "-keyout",
        join(dir, "key.pem"),
        "-out",
        join(dir, "cert.pem"),
      ],
      { stdio: "ignore" },
    );
    const created = {
      key: readFileSync(join(dir, "key.pem")),
      cert: readFileSync(join(dir, "cert.pem")),
    };
    named.set(subjectAltName, created);
    return created;
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

// HTTP/1 trailers reach the caller.
//
// They were parsed, checked for forbidden framing names, and discarded. Every consumer
// of `TransportResponse.trailers` -- diagnostics, deduplication, the response
// collector, the snapshot recorder -- handled a field no real transport ever produced,
// so only the mock exercised them. This is the producing half.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { createServer } from "node:net";

import {
  AbortController,
  DiagnosticsInterceptor,
} from "../src/index.ts";
import { Http1Transport } from "../src/http1/transport.ts";
import {
  HostNodeSocketConnector,
  createHostNodePrimitives,
  hostNodeURLs,
} from "../host/node-primitives.ts";
import { portOf } from "./harness.ts";
import type { Socket } from "node:net";
import { must } from "./harness.ts";
import type { TransportRequest } from "../src/fetch/transport.ts";
import type { DispatchDiagnosticEvent } from "../src/dispatch/diagnostics.ts";
import type { ReadableStream } from "../src/streams/readable.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const CRLF = String.fromCharCode(13, 10);

async function rawServer(t: TestContext, responseText: string): Promise<number> {
  const sockets = new Set<Socket>();
  const server = createServer((socket) => {
    sockets.add(socket);
    socket.on("error", () => {});
    socket.on("close", () => sockets.delete(socket));
    let head = "";
    socket.on("data", (chunk) => {
      head += chunk.toString("latin1");
      if (!head.includes(CRLF + CRLF)) return;
      // Ending the socket matters: a truncated `content-length` body is only truncated
      // once the peer stops sending. Leaving it open makes the reader wait for bytes
      // that are not coming, which reads as "the trailers never settled" and is really
      // "the server never finished".
      socket.end(responseText);
    });
  });
  server.listen(0, "127.0.0.1");
  await new Promise<void>((resolve) => server.once("listening", () => resolve()));
  t.after(() => {
    for (const socket of sockets) socket.destroy();
    return new Promise<void>((resolve) => server.close(() => resolve()));
  });
  return portOf(server);
}

function transportRequest(url: string, overrides: Partial<TransportRequest> = {}): TransportRequest {
  return {
    url: hostNodeURLs.parse(url),
    method: "GET",
    headers: [],
    body: null,
    bodyLength: null,
    signal: new AbortController().signal,
    ...overrides,
  };
}

async function consume(stream: ReadableStream<Uint8Array> | null): Promise<string> {
  if (stream === null) return "";
  const reader = stream.getReader();
  const parts: Uint8Array[] = [];
  try {
    while (true) {
      const result = await reader.read();
      if (result.done) break;
      parts.push(Buffer.from(result.value));
    }
  } finally {
    reader.releaseLock();
  }
  return Buffer.concat(parts).toString();
}

function makeTransport(t: TestContext): Http1Transport {
  const primitives = createHostNodePrimitives();
  const transport = new Http1Transport(new HostNodeSocketConnector(), primitives.scheduler, {});
  t.after(() => transport.close());
  return transport;
}

/** A chunked body followed by a trailer section. */
function chunked(body: string, trailerLines: readonly string[]): string {
  let text = "HTTP/1.1 200 OK" + CRLF;
  text += "transfer-encoding: chunked" + CRLF;
  text += "trailer: x-checksum" + CRLF;
  text += "connection: close" + CRLF + CRLF;
  text += body.length.toString(16) + CRLF + body + CRLF;
  text += "0" + CRLF;
  for (const line of trailerLines) text += line + CRLF;
  return text + CRLF;
}

suite("a chunked response delivers its trailer section", async (t) => {
  const port = await rawServer(t, chunked("payload", ["x-checksum: abc123", "x-rows: 7"]));
  const transport = makeTransport(t);
  const response = await transport.dispatch(transportRequest(`http://127.0.0.1:${port}/`));
  assert.notEqual(response.trailers, undefined, "a real transport must produce trailers");
  assert.equal(await consume(response.body), "payload");
  assert.deepEqual(await response.trailers, [
    ["x-checksum", "abc123"],
    ["x-rows", "7"],
  ]);
});

suite("trailers settle only once the body has ended", async (t) => {
  const port = await rawServer(t, chunked("slow", ["x-checksum: zzz"]));
  const transport = makeTransport(t);
  const response = await transport.dispatch(transportRequest(`http://127.0.0.1:${port}/`));

  let settled = false;
  must(response.trailers, "a chunked response carries trailers").then(
    () => {
      settled = true;
    },
    () => {
      settled = true;
    },
  );
  // The body has not been read, so the trailer section has not been reached.
  for (let turn = 0; turn < 10; turn++) await new Promise((resolve) => setImmediate(resolve));
  assert.equal(settled, false, "trailers cannot be known before the body ends");

  assert.equal(await consume(response.body), "slow");
  assert.deepEqual(await response.trailers, [["x-checksum", "zzz"]]);
});

suite("a framing that carries no trailers settles empty rather than hanging", async (t) => {
  // Fixed length.
  const fixedPort = await rawServer(
    t,
    "HTTP/1.1 200 OK" +
      CRLF +
      "content-length: 5" +
      CRLF +
      "connection: close" +
      CRLF +
      CRLF +
      "fixed",
  );
  const transport = makeTransport(t);
  const fixed = await transport.dispatch(transportRequest(`http://127.0.0.1:${fixedPort}/`));
  assert.equal(await consume(fixed.body), "fixed");
  assert.deepEqual(await fixed.trailers, []);

  // A bodyless response.
  const emptyPort = await rawServer(
    t,
    "HTTP/1.1 204 No Content" + CRLF + "connection: close" + CRLF + CRLF,
  );
  const empty = await transport.dispatch(transportRequest(`http://127.0.0.1:${emptyPort}/`));
  assert.equal(empty.body, null);
  assert.deepEqual(await empty.trailers, []);
});

suite("a forbidden framing trailer is still refused", async (t) => {
  // A trailer section may not carry framing fields; that check predates this change
  // and must survive it.
  const port = await rawServer(t, chunked("x", ["transfer-encoding: chunked"]));
  const transport = makeTransport(t);
  const response = await transport.dispatch(transportRequest(`http://127.0.0.1:${port}/`));
  await assert.rejects(consume(response.body), /Forbidden framing trailer/);
  await assert.rejects(must(response.trailers, "a chunked response carries trailers"), /Forbidden framing trailer/);
});

suite("a truncated body rejects the trailers rather than leaving them pending", async (t) => {
  // Declares eight bytes and sends three, then closes.
  const port = await rawServer(
    t,
    "HTTP/1.1 200 OK" +
      CRLF +
      "content-length: 8" +
      CRLF +
      "connection: close" +
      CRLF +
      CRLF +
      "abc",
  );
  const transport = makeTransport(t);
  const response = await transport.dispatch(transportRequest(`http://127.0.0.1:${port}/`));
  await assert.rejects(consume(response.body));
  // A caller awaiting trailers learns the body failed instead of waiting forever.
  await assert.rejects(must(response.trailers, "a chunked response carries trailers"));
});

suite("cancelling the body rejects the trailers", async (t) => {
  const port = await rawServer(t, chunked("payload", ["x-checksum: abc"]));
  const transport = makeTransport(t);
  const response = await transport.dispatch(transportRequest(`http://127.0.0.1:${port}/`));
  await must(response.body, "a chunked response carries a body").cancel(new Error("caller lost interest"));
  await assert.rejects(must(response.trailers, "a chunked response carries trailers"));
});

suite("trailer consumers see real trailers, not only fixtures", async (t) => {
  // Until trailers were produced, every consumer of `TransportResponse.trailers` was
  // exercised only against `MockAgent`. This runs the diagnostics interceptor over a
  // real transport and a real server, which is the claim that change was worth making.
  const port = await rawServer(
    t,
    chunked("payload", ["x-checksum: abc123", "authorization: Bearer secret"]),
  );
  const events: DispatchDiagnosticEvent[] = [];
  const interceptor = new DiagnosticsInterceptor({
    observer: { publish: (event) => events.push(event) },
    scheduler: {
      enqueue() {},
      delay() {
        return { cancel() {} };
      },
      reportError() {},
    },
  });
  const transport = makeTransport(t);
  const response = await interceptor.dispatch(
    transportRequest(`http://127.0.0.1:${port}/`),
    transport,
  );
  assert.equal(await consume(response.body), "payload");
  // The observation settles after the body, so give it its turn.
  for (let turn = 0; turn < 20; turn++) await new Promise((resolve) => setImmediate(resolve));

  const trailerEvents = events.filter(
    (event): event is Extract<DispatchDiagnosticEvent, { type: "response:trailers" }> =>
      event.type === "response:trailers",
  );
  assert.equal(trailerEvents.length, 1, "a real response must publish its trailers once");
  const trailerEvent = trailerEvents[0];
  assert.ok(trailerEvent !== undefined, "the trailer event was published");
  assert.deepEqual(
    trailerEvent.headers.find(([name]) => name === "x-checksum"),
    ["x-checksum", "abc123"],
  );
  // Redaction applies to trailers exactly as it does to headers. A credential does not
  // become publishable by arriving after the body.
  const authorization = trailerEvent.headers.find(([name]) => name === "authorization");
  assert.ok(authorization !== undefined, "the field is reported");
  assert.notEqual(authorization[1], "Bearer secret", "but never its value");
});

