test("URLPattern rejects duplicate names and malformed ASCII RegExp syntax", (t) => {
  runtime(t);
  for (const pathname of ["/:id/:id", "()", "((a))", "(?=a)", "(é)", "(\\)", "(a", "{}?+", ":"])
    assert.throws(() => new URLPattern({ pathname }), TypeError, pathname);
