test("URLPattern uses UnicodeSets regex syntax and limits ignoreCase to path search and hash", (t) => {
  runtime(t);
  const pattern = new URLPattern({ pathname: "/:ascii([\\p{ASCII}&&\\p{Letter}]+)", username: "User", search: "Q", hash: "F" }, { ignoreCase: true });
