// Test-only adapter for the missing native URL component capability. The URL
// implementation is the same genuine Node primitive as the ordinary host
// provider. URLPattern itself is always the package's source implementation.
import { URL } from "node:url";
import type { URLRecord } from "../src/provider/primitives.ts";
import type { URLPatternCanonicalComponent, URLPatternCanonicalResult, URLPatternURLCapability } from "../src/provider/url-pattern.ts";

export class HostURLPatternURLCapability implements URLPatternURLCapability {
  canonicalize(component: URLPatternCanonicalComponent, value: string, protocol?: string): URLPatternCanonicalResult {
    if (value === "") return { ok: true, value };
    try {
      const url = new URL("https://dummy.invalid/");
      switch (component) {
        case "username": url.username = value; return { ok: true, value: url.username };
        case "password": url.password = value; return { ok: true, value: url.password };
        case "hostname": {
          const second = new URL("https://other.invalid/");
          url.hostname = value;
          second.hostname = value;
          // The setter silently ignores a parse failure. Distinct initial hosts
          // distinguish that from a valid spelling of either initial host.
          return url.hostname === second.hostname ? { ok: true, value: url.hostname } : { ok: false, error: "invalid-input" };
        }
        case "port": {
          // Only default-port recognition depends on scheme in port state.
          // file has no default port; its public setter rejects all writes, so
          // a non-special scheme supplies the same port-state semantics here.
          const scheme = protocol === undefined || protocol === "" || protocol === "file" ? "urlpattern-test" : protocol;
          const first = new URL(scheme + "://dummy.invalid:1/");
          const second = new URL(scheme + "://dummy.invalid:2/");
          first.port = value;
          second.port = value;
          return first.port === second.port ? { ok: true, value: first.port } : { ok: false, error: "invalid-input" };
        }
        case "pathname": {
          const slash = value.startsWith("/");
          url.pathname = slash ? value : "/-" + value;
          return { ok: true, value: slash ? url.pathname : url.pathname.slice(2) };
        }
        case "opaquePathname": {
          // The prefix forces opaque-path state even for an initial slash. The
          // suffix protects trailing C0/space from whole-URL input trimming.
          // URL's opaque path consumes ?/# as delimiters even with an override;
          // if present, the suffix belongs to query/fragment instead of path.
          const opaque = new URL("urlpattern-test:_" + value + "_");
          const path = opaque.pathname.slice(1);
          return { ok: true, value: /[?#]/.test(value) ? path : path.slice(0, -1) };
        }
        case "search": url.search = "?" + value; return { ok: true, value: url.search.slice(1) };
        case "hash": url.hash = "#" + value; return { ok: true, value: url.hash.slice(1) };
      }
    } catch { return { ok: false, error: "invalid-input" }; }
  }
  hasOpaquePath(record: URLRecord): boolean {
    const url = new URL(record.href);
    const candidate = url.pathname === "/__urlpattern_probe__" ? "/__urlpattern_probe_other__" : "/__urlpattern_probe__";
    url.pathname = candidate;
    return url.pathname !== candidate;
  }
}

// The UTF-8 codec against node's, on generated input, every run.
//
// Two things put this here rather than in a scratchpad.
//
// `core/utf8.ts` is the most depended-upon function in this lane that is not part of the
// Web surface: the NodeJS lane re-exports `utf8Decode` for `Buffer.toString("utf8")`,
// and thirteen of their modules stop building without it. It was nearly swapped for the
// WHATWG decoder earlier today, which would have changed their behaviour on any buffer
// beginning `EF BB BF` with every test on both sides staying green.
//
// And the argument the NodeJS lane and I both made today about checks that only run when
// somebody remembers. `percentDecodeBytes` was fuzzed against a hand-written oracle to
// establish the source was sound before blaming a backend — six thousand inputs, agreed
// on all of them — and then discarded, so the evidence lasted exactly as long as the
// question did. This one runs in the gate.
//
// The oracle is node's own `Buffer`, which is an independent implementation rather than
// a reimplementation of the thing under test. That matters: the hand-written oracle in
// the percent-decoding fuzz was wrong on its first run, and a comparison is only as good
// as the side nobody is testing.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import {
  utf8Decode,
  utf8Length,
  utf8Write,
} from "../src/core/utf8.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

/** Deterministic, so a failure names an input somebody can paste back in. */
function generator(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

function stringFor(random: () => number): string {
  const length = Math.floor(random() * 12);
  let out = "";
  for (let index = 0; index < length; index++) {
    const pick = random();
    if (pick < 0.35) {
      out += String.fromCharCode(Math.floor(random() * 0x80));
    } else if (pick < 0.55) {
      // Latin-1: one byte in UTF-16, two in UTF-8.
      out += String.fromCharCode(0x80 + Math.floor(random() * 0x80));
    } else if (pick < 0.75) {
      // The rest of the BMP outside the surrogate range.
      const code = Math.floor(random() * 0xd7ff) + 1;
      out += String.fromCharCode(code);
    } else if (pick < 0.9) {
      // Astral: a well-formed surrogate pair.
      out += String.fromCodePoint(0x10000 + Math.floor(random() * 0xfffff));
    } else {
      // A lone surrogate, which is where a codec either replaces or corrupts.
      out += String.fromCharCode(0xd800 + Math.floor(random() * 0x800));
    }
  }
  return out;
}

function encoded(text: string): Uint8Array {
  const bytes = new Uint8Array(utf8Length(text));
  utf8Write(bytes, text, 0, bytes.length);
  return bytes;
}

const FIXED = [
  "",
  "hello",
  "é",
  "中文",
  "\u{1f600}",
  "﻿with a BOM",
  "\ud800",
  "\udfff",
  "𐀀",
  "a\ud800b",
  "�",
  "߿ࠀ",
];

suite("utf8Length agrees with Buffer.byteLength on generated strings", () => {
  const random = generator(0x5eed);
  for (const text of FIXED) {
    assert.equal(utf8Length(text), Buffer.byteLength(text, "utf8"), JSON.stringify(text));
  }
  for (let n = 0; n < 20000; n++) {
    const text = stringFor(random);
    assert.equal(utf8Length(text), Buffer.byteLength(text, "utf8"), JSON.stringify(text));
  }
});

suite("utf8Write produces the bytes Buffer.from produces", () => {
  const random = generator(0xc0ffee);
  const check = (text: string): void => {
    assert.deepEqual(
      Buffer.from(encoded(text)),
      Buffer.from(text, "utf8"),
      JSON.stringify(text),
    );
  };
  for (const text of FIXED) check(text);
  for (let n = 0; n < 20000; n++) check(stringFor(random));
});

suite("utf8Decode agrees with Buffer.toString, including the BOM it must not eat", () => {
  // `Buffer.toString("utf8")` is the right oracle and `TextDecoder` is not: the WHATWG
  // decoder consumes a leading BOM and this codec must not, which is precisely the
  // difference `Buffer.toString("utf8")` depends on.
  const random = generator(0xd0d0);
  // Both forms reach here: the generated cases are plain arrays and the fixed ones are already
  // views, and `Uint8Array.from` takes either.
  const check = (bytes: readonly number[] | Uint8Array): void => {
    const view = Uint8Array.from(bytes);
    assert.equal(
      utf8Decode(view, 0, view.length),
      Buffer.from(view).toString("utf8"),
      JSON.stringify([...view]),
    );
  };

  for (const text of FIXED) check(encoded(text));
  // Well-formed input.
  for (let n = 0; n < 10000; n++) check(encoded(stringFor(random)));

  // And arbitrary bytes, which is where a decoder either matches node's replacement
  // behaviour or invents its own.
  for (let n = 0; n < 20000; n++) {
    const length = Math.floor(random() * 10);
    const bytes = [];
    for (let index = 0; index < length; index++) bytes.push(Math.floor(random() * 256));
    check(bytes);
  }
});

suite("a ranged decode reads exactly the range it was given", () => {
  const random = generator(0xbeef);
  for (let n = 0; n < 5000; n++) {
    const bytes = encoded(stringFor(random));
    if (bytes.length === 0) continue;
    const start = Math.floor(random() * bytes.length);
    const end = start + Math.floor(random() * (bytes.length - start));
    assert.equal(
      utf8Decode(bytes, start, end),
      Buffer.from(bytes.subarray(start, end)).toString("utf8"),
      `${JSON.stringify([...bytes])} [${start}, ${end})`,
    );
  }
});

// The integration contract requires deterministic oracle tests to use virtual time and
// requires that network activity never silently advances it. Both follow from one
// property: this clock moves only when told to.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import { VirtualScheduler } from "../src/provider.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

suite("nothing runs until the clock is told to move", () => {
  const clock = new VirtualScheduler();
  const ran: string[] = [];
  clock.delay(10, () => ran.push("timer"));
  assert.equal(clock.now, 0);
  assert.deepEqual(ran, [], "a timer must not fire because time passed elsewhere");
  assert.equal(clock.hasPending, true);
  assert.equal(clock.nextDeadline, 10);

  clock.advance(9);
  assert.deepEqual(ran, [], "the clock stops short of the deadline");
  assert.equal(clock.now, 9);
  clock.advance(1);
  assert.deepEqual(ran, ["timer"]);
  assert.equal(clock.now, 10);
  assert.equal(clock.hasPending, false);
  assert.equal(clock.nextDeadline, null);
});

suite("queued tasks run before timers and without moving the clock", () => {
  const clock = new VirtualScheduler({ startMilliseconds: 100 });
  const ran: string[] = [];
  clock.delay(0, () => ran.push("due-timer"));
  clock.enqueue(() => ran.push("queued"));
  assert.deepEqual(ran, []);

  clock.runPending();
  assert.deepEqual(ran, ["queued", "due-timer"]);
  assert.equal(clock.now, 100, "running what is due does not advance time");
});

suite("equal deadlines run in the order they were scheduled", () => {
  const clock = new VirtualScheduler();
  const ran: string[] = [];
  for (const label of ["a", "b", "c"]) clock.delay(5, () => ran.push(label));
  clock.delay(1, () => ran.push("early"));
  clock.advance(5);
  assert.deepEqual(ran, ["early", "a", "b", "c"]);
});

suite("the clock stops at each deadline rather than jumping to the end", () => {
  const clock = new VirtualScheduler();
  const seen: number[] = [];
  clock.delay(10, () => {
    seen.push(clock.now);
    // Scheduled from inside a timer, still inside the window being advanced.
    clock.delay(5, () => seen.push(clock.now));
  });
  clock.delay(40, () => seen.push(clock.now));
  clock.advance(100);
  // Each task sees the time its own deadline implies, not the end of the interval.
  assert.deepEqual(seen, [10, 15, 40]);
  assert.equal(clock.now, 100);
});

suite("a timer scheduled beyond the window waits for the next advance", () => {
  const clock = new VirtualScheduler();
  const ran: string[] = [];
  clock.delay(10, () => {
    clock.delay(100, () => ran.push("later"));
  });
  clock.advance(20);
  assert.deepEqual(ran, []);
  assert.equal(clock.nextDeadline, 110);
  clock.advance(90);
  assert.deepEqual(ran, ["later"]);
});

suite("cancelling takes effect even from inside a running task", () => {
  const clock = new VirtualScheduler();
  const ran: string[] = [];
  clock.delay(1, () => {
    ran.push("first");
    later.cancel();
  });
  const later = clock.delay(2, () => ran.push("cancelled"));
  clock.advance(10);
  assert.deepEqual(ran, ["first"], "a task may cancel a timer this advance has not reached");

  // Cancelling twice, and after firing, are both inert.
  const once = clock.delay(1, () => ran.push("once"));
  clock.advance(1);
  once.cancel();
  once.cancel();
  clock.advance(10);
  assert.deepEqual(ran, ["first", "once"]);
  assert.equal(clock.hasPending, false);
});

suite("a failing task is reported and does not abandon the run", () => {
  const clock = new VirtualScheduler();
  const ran: string[] = [];
  clock.delay(1, () => {
    throw new Error("task failed");
  });
  clock.delay(2, () => ran.push("after"));
  clock.advance(10);
  assert.deepEqual(ran, ["after"], "one failing task must not hide every later one");
  assert.equal(clock.errors.length, 1);
  assert.match(String(clock.errors[0]), /task failed/);

  // A supplied reporter takes over entirely.
  const reported = [];
  const routed = new VirtualScheduler({ reportError: (error: unknown) => reported.push(error) });
  routed.enqueue(() => {
    throw new Error("routed");
  });
  routed.runPending();
  assert.equal(routed.errors.length, 0);
  assert.equal(reported.length, 1);
});

suite("advancing to the next deadline drives a scheduler to quiescence", () => {
  const clock = new VirtualScheduler();
  const ran: string[] = [];
  clock.delay(3, () => {
    ran.push("a");
    clock.delay(7, () => ran.push("b"));
  });
  let steps = 0;
  while (clock.advanceToNextDeadline()) steps += 1;
  assert.deepEqual(ran, ["a", "b"]);
  assert.equal(steps, 2, "one step per deadline, including one discovered on the way");
  assert.equal(clock.now, 10);
  assert.equal(clock.advanceToNextDeadline(), false, "nothing pending is not a step");
});

suite("invalid times are refused rather than silently normalized", () => {
  const clock = new VirtualScheduler();
  for (const bad of [-1, Number.NaN, Number.POSITIVE_INFINITY]) {
    assert.throws(() => clock.delay(bad, () => {}), RangeError);
    assert.throws(() => clock.advance(bad), RangeError);
  }
  assert.throws(() => new VirtualScheduler({ startMilliseconds: -1 }), RangeError);
  assert.throws(() => new VirtualScheduler({ startMilliseconds: Number.NaN }), RangeError);
  // Zero is valid in every position.
  const zero = new VirtualScheduler({ startMilliseconds: 0 });
  const ran: string[] = [];
  zero.delay(0, () => ran.push("now"));
  zero.advance(0);
  assert.deepEqual(ran, ["now"]);
});

// A listener whose lifetime is bounded by a caller-supplied resource. Node's
// `util.aborted(signal, resource)` needs this: when the resource is collected the
// wait must stop being answered, so the promise stays pending forever rather than
// resolving on behalf of something that no longer exists.
//
// The seam is internal. It is not an `addEventListener` option and adds no property
// to EventTarget, so nothing here is Web-observable. These are host-level tests of
// the shared algorithm; they are not compiled-provider evidence.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";

import {
  AbortController,
  Event,
  EventTarget,
} from "../src/index.ts";
import {
  addInternalEventListener,
  addWeaklyHeldEventListener,
} from "../src/core/events.ts";
import type { ListenerOptions } from "../src/core/events.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const tick = (): Promise<void> => new Promise<void>((resolve) => setImmediate(resolve));

/**
 * Listener options carrying a key the interface does not declare.
 *
 * Each use below is a forgery attempt and the attempt is the test: script must not be able to
 * ask for a weakly held listener, or for one that resists `stopImmediatePropagation`, by
 * passing a property that looks like the internal one. Widened once and by name, so a reader
 * sees a deliberate violation rather than a silenced error.
 */
function forgedOptions(options: Record<string, unknown>): ListenerOptions {
  return options as ListenerOptions;
}

async function collectWeakReference(reference: WeakRef<object>): Promise<boolean> {
  assert.equal(typeof globalThis.gc, "function", "the conformance runner must expose GC");
  for (let attempt = 0; attempt < 100; attempt++) {
    await tick();
    // Asserted present above; this reads it back through that check rather than assuming.
    const collect = globalThis.gc;
    assert.equal(typeof collect, "function", "the conformance runner must expose GC");
    collect?.();
    await tick();
    if (reference.deref() === undefined) return true;
  }
  return false;
}

suite("a weakly held listener runs while its resource is alive", () => {
  const target = new EventTarget();
  const resource = {};
  const seen: string[] = [];
  addWeaklyHeldEventListener(target, "abort", (event) => seen.push(event.type), resource);

  target.dispatchEvent(new Event("abort"));
  target.dispatchEvent(new Event("abort"));
  assert.deepEqual(seen, ["abort", "abort"]);

  // `once` still retires the listener after one delivery.
  const onceTarget = new EventTarget();
  const onceSeen: number[] = [];
  addWeaklyHeldEventListener(onceTarget, "abort", () => onceSeen.push(1), resource, {
    once: true,
  });
  onceTarget.dispatchEvent(new Event("abort"));
  onceTarget.dispatchEvent(new Event("abort"));
  assert.deepEqual(onceSeen, [1]);

  // The resource is still reachable here, so nothing above depended on collection.
  assert.equal(typeof resource, "object");
});

// The resource lives and dies inside this call, and the callback is supplied from
// outside it, so nothing created alongside the resource closes over it. That mirrors
// `util.aborted(signal, resource)`, where the resolver comes from the caller's
// `Promise.withResolvers()`. A callback that captured the resource itself would keep
// it alive through the listener, which is a property of any strongly held callback
// rather than of this seam.
function registerWeakly(target: EventTarget, callback: () => void, once = true): WeakRef<object> {
  const resource = {};
  addWeaklyHeldEventListener(target, "abort", callback, resource, { once });
  return new WeakRef(resource);
}

suite("a collected resource retires the listener before it can be called", async () => {
  const controller = new AbortController();
  let resolved = false;
  const resolve = () => {
    resolved = true;
  };
  const reference = registerWeakly(controller.signal, resolve);

  assert.equal(
    await collectWeakReference(reference),
    true,
    "a weakly held listener must not keep its resource alive",
  );

  controller.abort();
  await tick();
  assert.equal(resolved, false, "a wait keyed to a collected resource must stay pending");
});

suite("an ordinary listener on the same signal is unaffected by collection", async () => {
  const controller = new AbortController();
  const order: string[] = [];
  const weak = () => order.push("weak");
  const reference = registerWeakly(controller.signal, weak);
  controller.signal.addEventListener("abort", () => order.push("strong"), { once: true });

  assert.equal(await collectWeakReference(reference), true);
  controller.abort();
  await tick();
  assert.deepEqual(order, ["strong"], "only the weakly held listener is retired");
});

suite("the weakly held seam is not reachable from the public Web API", () => {
  const target = new EventTarget();
  const seen: string[] = [];
  const resource = {};

  // A dictionary member cannot request weak retention: this registers an ordinary
  // strong listener, and the surplus members are ignored.
  target.addEventListener("abort", () => seen.push("ordinary"), forgedOptions({
    once: true,
    weakResource: resource,
    resource,
    weak: resource,
  }));
  target.dispatchEvent(new Event("abort"));
  assert.deepEqual(seen, ["ordinary"]);

  // The seam adds no property to EventTarget or its prototype.
  for (const name of ["addWeaklyHeldEventListener", "registerWeaklyHeld", "retireWeaklyHeld"]) {
    assert.equal(name in target, false, `EventTarget must not expose ${name}`);
    assert.equal(
      Object.prototype.hasOwnProperty.call(EventTarget.prototype, name),
      false,
      `EventTarget.prototype must not expose ${name}`,
    );
  }
  // Nothing named for this seam reaches the prototype at all. The list is filtered
  // rather than compared whole because TypeScript `private`/`protected` are erased,
  // so unrelated internal methods are already own properties here; that pre-existing
  // surface question is not this seam's to answer.
  const weakNames = Object.getOwnPropertyNames(EventTarget.prototype).filter((name) =>
    /weak/i.test(name),
  );
  assert.deepEqual(weakNames, []);
});

suite("a weakly held listener follows the public duplicate and removal rules", () => {
  const target = new EventTarget();
  const seen: number[] = [];
  const resource = {};
  const callback = () => seen.push(1);

  addWeaklyHeldEventListener(target, "abort", callback, resource);
  // Duplicate registration follows the public (type, callback, capture) rule, so
  // this seam cannot install a copy the public API would have rejected.
  addWeaklyHeldEventListener(target, "abort", callback, resource);
  target.dispatchEvent(new Event("abort"));
  assert.deepEqual(seen, [1], "a duplicate registration must not install a second copy");

  // An ordinary removeEventListener retires it; the caller does not need the seam
  // to take it back off.
  target.removeEventListener("abort", callback);
  target.dispatchEvent(new Event("abort"));
  assert.deepEqual(seen, [1]);
  assert.equal(typeof resource, "object");
});

suite("an internal listener can resist stopImmediatePropagation", () => {
  const target = new EventTarget();
  const order: string[] = [];

  // Registration order matters: the resisting listener is registered last, so without
  // the option it would be the one hidden by the stop.
  target.addEventListener("abort", (event: Event) => {
    order.push("script");
    event.stopImmediatePropagation();
  });
  target.addEventListener("abort", () => order.push("later-script"));
  addInternalEventListener(target, "abort", () => order.push("internal"), {
    resistStopPropagation: true,
  });

  target.dispatchEvent(new Event("abort"));
  // The ordinary later listener is silenced; the internal one is not.
  assert.deepEqual(order, ["script", "internal"]);
});

suite("an internal listener without the option is silenced like any other", () => {
  const target = new EventTarget();
  const order: string[] = [];
  target.addEventListener("abort", (event: Event) => {
    order.push("script");
    event.stopImmediatePropagation();
  });
  addInternalEventListener(target, "abort", () => order.push("internal"));
  target.dispatchEvent(new Event("abort"));
  assert.deepEqual(order, ["script"], "resisting is opt-in, not what internal means");
});

suite("stopImmediatePropagation is not observable through the public API", () => {
  const target = new EventTarget();
  const order: string[] = [];
  // No dictionary member requests resistance: a surplus member is inert, and the
  // listener is silenced exactly as it would be without it.
  target.addEventListener("abort", (event: Event) => {
    order.push("script");
    event.stopImmediatePropagation();
  });
  target.addEventListener("abort", () => order.push("forged"), forgedOptions({
    resistStopPropagation: true,
    kResistStopPropagation: true,
  }));
  target.dispatchEvent(new Event("abort"));
  assert.deepEqual(order, ["script"]);
  const resistNames = Object.getOwnPropertyNames(EventTarget.prototype).filter((name) =>
    /resist/i.test(name),
  );
  assert.deepEqual(resistNames, []);
});

suite("resisting and weak holding compose", async () => {
  const controller = new AbortController();
  const order: string[] = [];
  controller.signal.addEventListener("abort", (event: Event) => {
    order.push("script");
    event.stopImmediatePropagation();
  });

  // A live resource: the resisting weak listener runs despite the stop.
  const live = {};
  addWeaklyHeldEventListener(controller.signal, "abort", () => order.push("weak"), live, {
    once: true,
    resistStopPropagation: true,
  });

  // A collected resource: resisting does not resurrect a listener whose reason for
  // existing is gone.
  const reference = registerResistingWeakly(controller.signal, () => order.push("dead"));
  assert.equal(await collectWeakReference(reference), true);

  controller.abort();
  await tick();
  assert.deepEqual(order, ["script", "weak"]);
  assert.equal(typeof live, "object");
});

function registerResistingWeakly(target: EventTarget, callback: () => void): WeakRef<object> {
  const resource = {};
  addWeaklyHeldEventListener(target, "abort", callback, resource, {
    once: true,
    resistStopPropagation: true,
  });
  return new WeakRef(resource);
}

// Web IDL surface shape: `@@toStringTag` and constructor arity.
//
// WPT tests this through `idlharness`, which this corpus does not pin -- it needs the IDL
// definitions and a harness that parses them, which is a much larger dependency than a
// fixture file. So the surface was entirely unchecked here, and it was wrong in two ways
// that no behavioural test would ever notice.
//
// The oracle is the IDL text, not node. Node agrees with it on every interface it
// implements, and that agreement is worth having, but it is a cross-check rather than the
// authority: this lane has already found one place where node's own answer was the wrong
// one, and a table copied from a running implementation is a table chosen by whatever that
// implementation happens to do.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { createHostNodeWebPlatform } from "../host/node-runtime.ts";

import * as api from "../src/index.ts";
import { memberNamed, must, prototypeNamed } from "./harness.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

/**
 * Every Web IDL interface this runtime exports, and the constructor arity its IDL states.
 *
 * `length` is the number of *required* arguments. `null` means the interface has no
 * constructor, so only the tag is checked.
 */
const INTERFACES = {
  AbortController: 0,
  AbortSignal: null,
  Blob: 0,
  ByteLengthQueuingStrategy: 1,
  Cache: null,
  CacheStorage: null,
  CloseEvent: 1,
  CountQueuingStrategy: 1,
  CustomEvent: 1,
  DOMException: 0,
  ErrorEvent: 1,
  Event: 1,
  EventSource: 1,
  EventTarget: 0,
  File: 2,
  FileReader: 0,
  FormData: 0,
  Headers: 0,
  MessageEvent: 1,
  ProgressEvent: 1,
  ReadableByteStreamController: null,
  ReadableStream: 0,
  ReadableStreamBYOBReader: 1,
  ReadableStreamBYOBRequest: null,
  ReadableStreamDefaultController: null,
  ReadableStreamDefaultReader: 1,
  Request: 1,
  Response: 0,
  TextDecoder: 0,
  TextDecoderStream: 0,
  TextEncoder: 0,
  TextEncoderStream: 0,
  TransformStream: 0,
  TransformStreamDefaultController: null,
  URLSearchParams: 0,
  WebSocket: 1,
  WebSocketStream: 1,
  WritableStream: 0,
  WritableStreamDefaultController: null,
  WritableStreamDefaultWriter: 1,
};

// These interfaces use declared class members under the current cloud-agent
// fixed-layout rule. Keep each descriptor-only omission visible by name while
// retaining the descriptor checks for the unchanged legacy interfaces.
const PLAIN_CLASS_MEMBERS = new Set([
  "Blob", "DOMException", "File", "FileReader", "FormData", "ProgressEvent",
  "TextDecoder", "TextDecoderStream", "TextEncoder", "TextEncoderStream",
]);
const DESCRIPTOR_REASON = "nts fixed class layouts do not reproduce Web IDL property descriptors; members are declared plainly";

/**
 * The constructor `name` denotes on the platform surface, asserted exported.
 *
 * The names come from tables this file iterates, so the read cannot be expressed against the
 * module's type -- it declares no index signature. `memberNamed` widens it to `unknown` and
 * this checks it is callable before anything reads `prototype` or `length` off it.
 */
function constructorNamed(name: string): { prototype: object; length: number } {
  const found = memberNamed(api, name);
  assert.equal(typeof found, "function", `${name} must be exported`);
  const proto = prototypeNamed(api, name);
  assert.ok(proto !== undefined, `${name} must have a prototype`);
  return { prototype: proto, length: (found as { length: number }).length };
}

suite("every Web IDL interface prototype carries its @@toStringTag", async (t) => {
  for (const name of Object.keys(INTERFACES)) {
    await t.test(`${name} @@toStringTag descriptor`, {
      skip: PLAIN_CLASS_MEMBERS.has(name) ? DESCRIPTOR_REASON : false,
    }, () => {
      const constructor = constructorNamed(name);
      const descriptor = Object.getOwnPropertyDescriptor(constructor.prototype, Symbol.toStringTag);
      assert.ok(descriptor !== undefined, `${name}: absent`);
      assert.ok("value" in descriptor, `${name}: accessor, not a data property`);
      assert.equal(descriptor.value, name);
      assert.equal(descriptor.writable, false);
      assert.equal(descriptor.enumerable, false);
      assert.equal(descriptor.configurable, true);
    });
  }
});

suite("the tag is what Object.prototype.toString actually reports", (t) => {
  const runtime = createHostNodeWebPlatform();
  t.after(() => runtime.close());
  // The consequence, and the reason the descriptor is worth pinning: without the tag this
  // answers `[object Object]`, which is directly observable and differs from every other
  // implementation.
  assert.equal(Object.prototype.toString.call(new api.Event("x")), "[object Event]");
  assert.equal(Object.prototype.toString.call(new api.Headers()), "[object Headers]");
  assert.equal(Object.prototype.toString.call(new api.AbortController()), "[object AbortController]");
  assert.equal(Object.prototype.toString.call(new api.TextEncoder()), "[object TextEncoder]");
  assert.equal(Object.prototype.toString.call(new api.Blob()), "[object Blob]");
  assert.equal(Object.prototype.toString.call(new api.File([], "file")), "[object File]");
  assert.equal(Object.prototype.toString.call(new api.FormData()), "[object FormData]");
  assert.equal(Object.prototype.toString.call(new api.FileReader()), "[object FileReader]");
  assert.equal(Object.prototype.toString.call(new api.ProgressEvent("progress")), "[object ProgressEvent]");
});

suite("a constructor's length is its required-argument count", () => {
  const wrong: string[] = [];
  for (const [name, length] of Object.entries(INTERFACES)) {
    if (length === null) continue;
    const actual = constructorNamed(name).length;
    if (actual !== length) wrong.push(`${name}: ${actual} want ${length}`);
  }
  assert.deepEqual(wrong, []);
});

suite("length is declared, not inferred, and stays right when the signature is a tuple", () => {
  // The classes take `...args` tuples so an omitted argument is distinguishable from an
  // explicit `undefined` -- which Web IDL also requires, and which matters more than the
  // arity. That makes the inferred length 0 for all of them, so the arity is declared.
  // This asserts both halves still hold together.
  assert.equal(api.Event.length, 1);
  // Deliberately short of its required argument, because throwing is the assertion. The
  // constructor is widened rather than the call silenced, so the missing argument stays visible.
  const EventMissingType = api.Event as unknown as new () => unknown;
  assert.throws(() => new EventMissingType(), TypeError, "an omitted required argument still throws");
  assert.equal(new api.Event("x", undefined).type, "x", "an explicit undefined init is allowed");
});

suite("the Undici-shaped classes are deliberately untagged", () => {
  // Not Web IDL interfaces, and no implementation tags them. Asserted so that a later pass
  // adding tags "for consistency" has to change this test and say why.
  for (const name of ["Agent", "Pool", "RetryInterceptor", "MockAgent", "CookieJar"]) {
    const constructor = constructorNamed(name);
    assert.equal(
      Object.getOwnPropertyDescriptor(constructor.prototype, Symbol.toStringTag),
      undefined,
      `${name} is not a Web IDL interface and must not be tagged`,
    );
  }
});

/**
 * Interfaces whose prototypes carry no non-standard members, and whose members are therefore
 * safe to make enumerable as Web IDL requires.
 *
 * The list is short because the rest still expose internals; see
 * `idl-internal-surface.test.mjs`. Adding a class here without first clearing its internals
 * would enumerate those too, which is the ordering that makes this list the interesting part.
 */
const FULLY_CONFORMANT = [
  "AbortSignal",
  "Blob",
  "ByteLengthQueuingStrategy",
  "CountQueuingStrategy",
  "Event",
  "EventTarget",
  "File",
  "FileReader",
  "FormData",
  "Headers",
  "ProgressEvent",
  "ReadableByteStreamController",
  "ReadableStreamDefaultController",
  "TransformStream",
  "TransformStreamDefaultController",
  "URLSearchParams",
  "WebSocket",
  "WritableStream",
  "WritableStreamDefaultController",
  "WritableStreamDefaultWriter",
  "TextDecoder",
  "TextDecoderStream",
  "TextEncoder",
  "TextEncoderStream",
];

/**
 * Interfaces whose prototypes are clean and enumerable but which still deviate in shape.
 *
 * `Request` and `Response` include the `Body` mixin. Web IDL says an included mixin's members
 * are **copied onto the interface prototype**; here they are inherited from a shared `Body`
 * base class instead. Every value reads correctly, `instanceof` is unaffected, and the
 * difference is visible only in `Object.getOwnPropertyNames(Request.prototype)` and
 * `Request.prototype.hasOwnProperty("json")`.
 *
 * They were listed as fully conformant until the name-completeness check below was written,
 * which is the assertion that found it. Recorded rather than fixed: making the mixin members
 * own properties means the prototype chain stops inheriting from `Body`, which is a change to
 * a hierarchy that four other interfaces sit on.
 */
const MIXIN_INHERITED = ["Request", "Response"];

suite("members of a cleared interface are enumerable, as Web IDL requires", async (t) => {
  for (const name of [...FULLY_CONFORMANT, ...MIXIN_INHERITED]) {
    await t.test(`${name} Web IDL member enumerability`, {
      skip: PLAIN_CLASS_MEMBERS.has(name) ? DESCRIPTOR_REASON : false,
    }, () => {
      const proto = constructorNamed(name).prototype;
      const wrong: string[] = [];
      for (const key of Object.getOwnPropertyNames(proto)) {
        if (key === "constructor") continue;
        const descriptor = Object.getOwnPropertyDescriptor(proto, key);
        if (descriptor === undefined || !descriptor.enumerable) wrong.push(`${name}.${key}`);
      }
      assert.deepEqual(wrong, []);
    });
  }
});

suite("making them enumerable did not expose an internal", () => {
  // The other half of the same change. `getOwnPropertyNames` skips symbol keys, so the
  // internals other modules reach are untouched by the enumerability pass -- and that is
  // exactly why the pass is safe on these classes and not on the rest.
  for (const name of [...FULLY_CONFORMANT, ...MIXIN_INHERITED]) {
    const conformant = prototypeNamed(globalThis, name);
    if (conformant === undefined) continue;
    const theirs = new Set([
      ...Object.getOwnPropertyNames(conformant),
      ...(CONSTANTS_ON_PROTOTYPE[name] ?? []),
      ...(ORACLE_OMITS[name] ?? []),
    ]);
    const extra = Object.getOwnPropertyNames(constructorNamed(name).prototype).filter(
      (key) => key !== "constructor" && !theirs.has(key),
    );
    assert.deepEqual(extra, [], `${name} must expose no non-standard names`);
  }
});

/**
 * Members that other lanes reach **reflectively**, by name, as a duck-type brand check.
 *
 * Reported by the Node lane, which has five sites of the shape `!("aborted" in signal)` --
 * in `internal/validators.ts`, `util/src/main.ts` and two files under `stream/src/iter/`.
 * They are the argument for this suite existing in this form.
 *
 * The hazard is specific and it is the mirror of a defect this lane shipped and caught: a
 * reflective check is invisible to `tsc` -- the property genuinely might not exist, which is
 * what the check is asking -- so symbol-keying or privatising one of these names produces no
 * compile error here, no failing conformance test here, and five silent rejections of
 * perfectly valid `AbortSignal`s over there.
 *
 * These names stay named because Web IDL says so. This records that they are also
 * load-bearing outside this lane, so the decision is made knowingly rather than discovered.
 */
const REFLECTIVELY_REACHED: Readonly<Record<string, readonly string[]>> = {
  AbortSignal: ["aborted"],
};

/**
 * Members the conformant oracle has that the standard does not define.
 *
 * Node is a good oracle for interface shape and it is not the IDL. `Blob.prototype.textStream`
 * is a Node extension: `interfaces/FileAPI.idl`, pinned in this repository, declares `stream()`
 * and `text()` and nothing else on `Blob`. Excluded by citation rather than by convenience --
 * this is checkable, and the check is that the IDL does not mention it.
 */
const HOST_EXTENSIONS: Readonly<Record<string, readonly string[]>> = {
  Blob: ["textStream"],
  File: ["textStream"],
};

/**
 * Names this runtime has on a prototype that the oracle does not, and is right to have.
 *
 * Web IDL puts an interface's constants on **both** the interface object and the interface
 * prototype object. Node keeps `Event`'s four on the constructor only, so comparing prototypes
 * reports them as extras here. `interfaces/dom.idl` declares them as `const unsigned short`
 * members of `Event`, which is the citation.
 */
const CONSTANTS_ON_PROTOTYPE: Readonly<Record<string, readonly string[]>> = {
  Event: ["NONE", "CAPTURING_PHASE", "AT_TARGET", "BUBBLING_PHASE"],
  WebSocket: ["CONNECTING", "OPEN", "CLOSING", "CLOSED"],
};

/**
 * Standard members this runtime has that the oracle does not implement.
 *
 * `CustomEvent.initCustomEvent` is declared in `interfaces/dom.idl` — marked `// legacy`, but
 * declared — and node does not provide it. Listed so that having it does not read as an extra.
 */
const ORACLE_OMITS: Readonly<Record<string, readonly string[]>> = {
  CustomEvent: ["initCustomEvent"],
};

suite("every standard member is still reachable by its own name", () => {
  // The direction the extras check cannot see. `getOwnPropertyNames` skipping symbols is what
  // makes symbol-keying an internal invisible -- and it would make symbol-keying a *public*
  // member equally invisible, while breaking every consumer that looks the name up.
  const missing: string[] = [];
  for (const name of FULLY_CONFORMANT) {
    const conformant = prototypeNamed(globalThis, name);
    if (conformant === undefined) continue;
    const mine = new Set(Object.getOwnPropertyNames(constructorNamed(name).prototype));
    const excused = new Set([
      ...(HOST_EXTENSIONS[name] ?? []),
    ]);
    for (const key of Object.getOwnPropertyNames(conformant)) {
      if (key === "constructor" || excused.has(key)) continue;
      if (!mine.has(key)) missing.push(`${name}.${key}`);
    }
  }
  assert.deepEqual(missing, []);
});

suite("members other lanes brand-check by name are named, not symbol-keyed", () => {
  for (const [name, keys] of Object.entries(REFLECTIVELY_REACHED)) {
    for (const key of keys) {
      const descriptor = Object.getOwnPropertyDescriptor(constructorNamed(name).prototype, key);
      assert.ok(
        descriptor !== undefined,
        `${name}.${key} is reached reflectively by another lane; see the note above`,
      );
      // `in` walks the prototype chain and finds accessors, so an own accessor is what the
      // consuming check actually needs -- asserted as the shape, not merely as a truthy read.
      assert.ok(
        typeof descriptor.get === "function" || "value" in descriptor,
        `${name}.${key} must be a real prototype member`,
      );
      assert.ok(
        key in new api.AbortController().signal,
        `${key} must answer an "in" check on this runtime's signal, not the host's`,
      );
    }
  }
});

suite("the mixin deviation is exactly what it is claimed to be", () => {
  // Pinned in the direction it currently holds, so that fixing it fails here and the note
  // above has to be removed rather than quietly outliving its reason.
  for (const name of MIXIN_INHERITED) {
    const proto = constructorNamed(name).prototype;
    assert.equal(
      Object.prototype.hasOwnProperty.call(proto, "json"),
      false,
      `${name}.prototype owns its Body members now -- the mixin deviation is fixed`,
    );
    assert.equal(
      typeof memberNamed(proto, "json"),
      "function",
      `${name} must still reach the Body members by inheritance`,
    );
  }
});

test("a [LegacyUnforgeable] member is an own accessor, not a prototype one", {
  skip: "descriptor shape ([LegacyUnforgeable]): cloud rule, no descriptors",
}, () => {
  // This upstream descriptor contract is excluded for fixed-layout nts classes.
  // The private trust state and ordinary public reads have active controls.
  const event = new api.Event("x");
  const own = Object.getOwnPropertyDescriptor(event, "isTrusted");
  assert.ok(own !== undefined, "isTrusted must be an own property of the instance");
  assert.equal(typeof own.get, "function");
  assert.equal(own.configurable, false, "unforgeable means non-configurable");
  assert.equal(
    Object.getOwnPropertyDescriptor(api.Event.prototype, "isTrusted"),
    undefined,
    "and it must not also be on the prototype",
  );
});

suite("interface constants are on the prototype as well as the interface object", () => {
  for (const [name, constants] of Object.entries(CONSTANTS_ON_PROTOTYPE)) {
    for (const key of constants) {
      const descriptor = Object.getOwnPropertyDescriptor(constructorNamed(name).prototype, key);
      assert.ok(descriptor !== undefined, `${name}.prototype.${key}`);
      assert.equal(descriptor.writable, false, `${name}.${key} must not be writable`);
      assert.equal(descriptor.configurable, false, `${name}.${key} must not be configurable`);
      const onClass = memberNamed(must(memberNamed(api, name), `${name} is exported`) as object, key);
      assert.equal(typeof onClass, "number", `${name}.${key} must also be on the class`);
    }
  }
});

// An echoing WebSocket server over a real socket, built from the shared server pieces.
//
// Extracted rather than copied. Two suites need a real peer -- the server-session tests
// and the dispatched client -- and a harness that exists twice is a harness that drifts,
// which for a test peer means two suites quietly stop testing the same thing.
import { createServer } from "node:net";
import type { Socket } from "node:net";
import type { TestContext } from "node:test";
import type {
  ByteConnection,
  SocketMessage,
  WebSocketDeflateProvider,
  WebSocketUpgradeOptions,
} from "../src/provider.ts";

import {
  acceptWebSocketUpgrade,
  adoptServerWebSocketSession,
  BufferedReader,
  readRequestHead,
  serializeUpgradeResponse,
  writeAll,
} from "../src/provider.ts";
import {
  HostNodeScheduler,
  hostNodeRandom,
} from "../host/node-primitives.ts";

const encoder = new TextEncoder();

/** Minimal ByteConnection over an accepted Node socket. Test harness, not a provider. */
export function byteConnection(socket: Socket): ByteConnection {
  const pending: Uint8Array[] = [];
  // The resolver of a `read` that arrived before any bytes did. `null` when nobody waits.
  let waiting: ((chunk: Uint8Array | null) => void) | null = null;
  let ended = false;
  socket.on("data", (chunk: Buffer) => {
    if (waiting !== null) {
      const resolve = waiting;
      waiting = null;
      resolve(new Uint8Array(chunk));
      return;
    }
    pending.push(new Uint8Array(chunk));
  });
  socket.on("end", () => {
    ended = true;
    if (waiting !== null) {
      const resolve = waiting;
      waiting = null;
      resolve(null);
    }
  });
  socket.on("error", () => {});
  return {
    get closed() {
      return socket.destroyed;
    },
    // The contract is "a nonempty chunk of at most maxBytes"; returning a whole socket
    // chunk regardless is a contract violation the reader is entitled to trip over.
    async read(maxBytes: number): Promise<Uint8Array | null> {
      const take = (chunk: Uint8Array | null): Uint8Array | null => {
        if (chunk === null || chunk.length <= maxBytes) return chunk;
        pending.unshift(chunk.subarray(maxBytes));
        return chunk.subarray(0, maxBytes);
      };
      const next = pending.shift();
      if (next !== undefined) return take(next);
      if (ended) return null;
      return new Promise<Uint8Array | null>((resolve) => {
        waiting = (chunk) => resolve(take(chunk));
      });
    },
    async write(data: Uint8Array): Promise<number> {
      socket.write(Buffer.from(data));
      return data.length;
    },
    close() {
      socket.destroy();
    },
  };
}

/** What the server end observed, for a test to assert against afterwards. */
export interface WebSocketServerSeen {
  protocol: string | null;
  extensions: string | null;
  readonly messages: SocketMessage[];
  readonly errors: unknown[];
}

export interface WebSocketServerHandle {
  readonly port: number;
  readonly seen: WebSocketServerSeen;
}

export async function websocketServer(
  t: TestContext,
  upgradeOptions: WebSocketUpgradeOptions = {},
  // Optional in fact as well as in use: most callers want no compression, and leaving it
  // untyped made every one of those calls read as a missing argument.
  deflate?: WebSocketDeflateProvider,
): Promise<WebSocketServerHandle> {
  const seen: WebSocketServerSeen = { protocol: null, extensions: null, messages: [], errors: [] };
  const sockets = new Set<Socket>();
  const scheduler = new HostNodeScheduler(() => {});
  const server = createServer((socket) => {
    sockets.add(socket);
    socket.on("error", () => {});
    socket.on("close", () => sockets.delete(socket));
    void (async () => {
      const connection = byteConnection(socket);
      const reader = new BufferedReader(connection);
      const request = await readRequestHead(reader);
      const outcome = acceptWebSocketUpgrade(request.method, request.headers, upgradeOptions);
      await writeAll(connection, encoder.encode(serializeUpgradeResponse(outcome)));
      if (!outcome.accepted) {
        connection.close();
        return;
      }
      seen.protocol = outcome.protocol;
      seen.extensions = outcome.perMessageDeflate?.response ?? null;
      // The same reader continues into the frames: bytes a client sent immediately
      // after its handshake are already buffered here.
      const session = adoptServerWebSocketSession({
        connection,
        reader,
        protocol: outcome.protocol ?? "",
        extensions: seen.extensions ?? "",
        perMessageDeflate: outcome.perMessageDeflate,
        deflate,
        random: hostNodeRandom,
        scheduler,
      });
      try {
        while (true) {
          const incoming = await session.next();
          // `"close"`, not `"closed"`. It was the latter, which is not one of the three kinds
          // `SocketIncoming` has, so the comparison was always false: the loop never broke on
          // a close, pushed the close frame into `messages`, and then tried to echo it back as
          // a message. Typing this file is what surfaced it -- every run took the error path
          // at the end of every connection, and no assertion looked.
          if (incoming.kind === "close") break;
          seen.messages.push(incoming);
          await session.send(incoming);
        }
      } catch (error) {
        seen.errors.push(error);
      }
    })();
  });
  server.listen(0, "127.0.0.1");
  await new Promise<void>((resolve) => server.once("listening", () => resolve()));
  t.after(() => {
    for (const socket of sockets) socket.destroy();
    return new Promise<void>((resolve) => server.close(() => resolve()));
  });
  // A listening TCP server always has the object form; narrowing says so rather than assuming.
  const address = server.address();
  if (address === null || typeof address === "string") {
    throw new Error("the echo server did not bind a TCP port");
  }
  return { port: address.port, seen };
}

// RFC 6455 §4.1 step 2: serialize attempts until the opening handshake settles.
// Deferred provider operations make ordering observable without elapsed-time checks.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { setImmediate as nextTurn } from "node:timers/promises";
import "../host/environment-shim.ts";
import { AbortController, abortSignalSubscribe } from "../src/core/abort.ts";
import type { AbortSignal } from "../src/core/abort.ts";
import type { HeaderEntry } from "../src/fetch/headers.ts";
import type { TransportRequest, TransportResponse } from "../src/fetch/transport.ts";
import type { ByteConnection } from "../src/provider/primitives.ts";
import { ReadableStream } from "../src/streams/readable.ts";
import { DispatchedWebSocketTransport } from "../src/websocket/dispatched-transport.ts";
import { websocketAccept } from "../src/websocket/handshake.ts";
import { RawWebSocketTransport } from "../src/websocket/raw-transport.ts";
import { normalizeWebSocketURL } from "../src/websocket/semantics.ts";
import type { WebSocketDeflateProvider, WebSocketSession } from "../src/websocket/transport.ts";
import { HostNodeScheduler, hostNodeURLs } from "../host/node-primitives.ts";
import { must } from "./harness.ts";

type TransportKind = "raw" | "dispatched";

interface RequestHead {
  readonly target: string;
  readonly headers: ReadonlyMap<string, string>;
}

class ControlledConnection implements ByteConnection {
  closed = false;
  readonly written = Promise.withResolvers<string>();
  private readonly response = Promise.withResolvers<Uint8Array | null>();
  private readonly ended = Promise.withResolvers<Uint8Array | null>();
  private reads = 0;

  async read(maxBytes: number): Promise<Uint8Array | null> {
    const bytes = await (this.reads++ === 0 ? this.response.promise : this.ended.promise);
    assert.ok(bytes === null || bytes.length <= maxBytes, "the test head fits in one read");
    return bytes;
  }

  async write(bytes: Uint8Array): Promise<number> {
    this.written.resolve(new TextDecoder().decode(bytes));
    return bytes.length;
  }

  reply(head: string): void {
    this.response.resolve(new TextEncoder().encode(head));
  }

  close(): void {
    this.closed = true;
    this.response.resolve(null);
    this.ended.resolve(null);
  }
}

class HandshakeAttempt {
  readonly connection = new ControlledConnection();
  readonly signal: AbortSignal;
  readonly request: TransportRequest | undefined;
  private readonly connected = Promise.withResolvers<ByteConnection>();
  private readonly dispatched = Promise.withResolvers<TransportResponse>();

  constructor(signal: AbortSignal, request?: TransportRequest) {
    this.signal = signal;
    this.request = request;
  }

  async connect(): Promise<ByteConnection> {
    const detach = this.signal[abortSignalSubscribe](() => this.connected.reject(this.signal.reason));
    try {
      return await this.connected.promise;
    } finally {
      detach();
    }
  }

  async dispatch(): Promise<TransportResponse> {
    const detach = this.signal[abortSignalSubscribe](() => this.dispatched.reject(this.signal.reason));
    try {
      return await this.dispatched.promise;
    } finally {
      detach();
    }
  }

  async head(): Promise<RequestHead> {
    if (this.request !== undefined) {
      return {
        target: this.request.url.pathname + this.request.url.search,
        headers: new Map(this.request.headers),
      };
    }
    this.connected.resolve(this.connection);
    const lines = (await this.connection.written.promise).split("\r\n");
    const headers = new Map<string, string>();
    for (const line of lines.slice(1)) {
      const colon = line.indexOf(":");
      if (colon !== -1) headers.set(line.slice(0, colon).toLowerCase(), line.slice(colon + 1).trim());
    }
    return { target: must(lines[0], "request line").split(" ")[1] ?? "", headers };
  }

  async reply(
    status: number,
    headers: readonly HeaderEntry[] = [],
    body: ReadableStream<Uint8Array> | null = null,
  ): Promise<void> {
    await this.head();
    if (this.request !== undefined) {
      this.dispatched.resolve({
        status,
        statusText: "Test response",
        headers,
        body,
        ...(status === 101 ? { connection: this.connection } : {}),
      });
    } else {
      this.connection.reply(
        "HTTP/1.1 " + status + " Test response\r\n" +
        headers.map(([name, value]) => name + ": " + value + "\r\n").join("") + "\r\n",
      );
    }
  }

  async accept(protocol?: string): Promise<void> {
    const head = await this.head();
    await this.reply(101, [
      ["upgrade", "websocket"],
      ["connection", "Upgrade"],
      ["sec-websocket-accept", websocketAccept(must(head.headers.get("sec-websocket-key"), "nonce"))],
      ...(protocol === undefined ? [] : [["sec-websocket-protocol", protocol] as const]),
    ]);
  }

  fail(error: unknown): void {
    if (this.request === undefined) this.connected.reject(error);
    else this.dispatched.reject(error);
  }
}

class ControlledTransport {
  readonly transport: RawWebSocketTransport | DispatchedWebSocketTransport;
  readonly attempts: HandshakeAttempt[] = [];
  private cursor = 0;
  private changed = Promise.withResolvers<void>();

  constructor(t: TestContext, kind: TransportKind, deflate?: WebSocketDeflateProvider) {
    let nonce = 0;
    const random = { fill(bytes: Uint8Array): void { bytes.fill(++nonce); } };
    const scheduler = new HostNodeScheduler((error) => assert.fail(String(error)));
    this.transport = kind === "raw"
      ? new RawWebSocketTransport({
          connect: (_address, signal) => {
            const attempt = new HandshakeAttempt(signal);
            this.record(attempt);
            return attempt.connect();
          },
        }, random, scheduler, {}, deflate)
      : new DispatchedWebSocketTransport({
          dispatch: (request) => {
            const attempt = new HandshakeAttempt(request.signal, request);
            this.record(attempt);
            return attempt.dispatch();
          },
        }, random, scheduler, {}, deflate);
    t.after(() => this.transport.close());
  }

  private record(attempt: HandshakeAttempt): void {
    this.attempts.push(attempt);
    this.changed.resolve();
    this.changed = Promise.withResolvers<void>();
  }

  async next(): Promise<HandshakeAttempt> {
    while (this.cursor === this.attempts.length) await this.changed.promise;
    return must(this.attempts[this.cursor++], "the provider started an attempt");
  }

  connect(
    url: string,
    signal = new AbortController().signal,
    protocols: readonly string[] = [],
  ): Promise<WebSocketSession> {
    const result = this.transport.connect({
      url: hostNodeURLs.parse(url),
      protocols,
      origin: "https://client.test",
    }, signal);
    // A failing assertion still lets test cleanup abort every outstanding attempt.
    result.catch(() => {});
    return result;
  }
}

for (const kind of ["raw", "dispatched"] as const) {
  test(kind + " serializes the normalized destination until its handshake is validated", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const firstResult = controlled.connect("ws://EXAMPLE.test:80/first");
    const secondResult = controlled.connect("ws://example.test/second");
    const first = await controlled.next();
    await first.head();
    await nextTurn();
    assert.equal(controlled.attempts.length, 1, "connecting TCP is not a completed opening handshake");
    await first.accept();
    await firstResult;
    const second = await controlled.next();
    assert.equal(first.connection.closed, false, "an open session does not retain the CONNECTING slot");
    assert.equal((await second.head()).target, "/second");
    await second.accept();
    await secondResult;
  });

  test(kind + " connects different hosts and effective ports concurrently", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const pending = [
      controlled.connect("ws://a.test/"),
      controlled.connect("ws://b.test/"),
      controlled.connect("ws://a.test:81/"),
      controlled.connect("wss://a.test/"),
    ];
    for (let index = 0; index < pending.length; index++) await controlled.next();
    assert.equal(controlled.attempts.length, 4);
    await Promise.all(controlled.attempts.map((attempt) => attempt.accept()));
    await Promise.all(pending);
  });

  test(kind + " aborts a middle waiter without letting its successors overtake the active attempt", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const firstResult = controlled.connect("ws://queue.test/first");
    const middle = new AbortController();
    const middleResult = controlled.connect("ws://queue.test/middle", middle.signal);
    const thirdResult = controlled.connect("ws://queue.test/third");
    const first = await controlled.next();
    await first.head();
    const reason = new Error("cancel the queued attempt");
    middle.abort(reason);
    await assert.rejects(middleResult, (error) => error === reason);
    const fourthResult = controlled.connect("ws://queue.test/fourth");
    await nextTurn();
    assert.equal(controlled.attempts.length, 1, "an aborted waiter cannot release its predecessor");
    await first.accept();
    await firstResult;
    const third = await controlled.next();
    assert.equal((await third.head()).target, "/third");
    await nextTurn();
    assert.equal(controlled.attempts.length, 2, "a new tail must still wait for the third attempt");
    await third.accept();
    await thirdResult;
    const fourth = await controlled.next();
    assert.equal((await fourth.head()).target, "/fourth");
    await fourth.accept();
    await fourthResult;
  });

  test(kind + " releases the next attempt after a provider connection failure", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const firstResult = controlled.connect("ws://failure.test/first");
    const secondResult = controlled.connect("ws://failure.test/second");
    const first = await controlled.next();
    const reason = new Error("connection refused");
    first.fail(reason);
    await assert.rejects(firstResult, (error) => error === reason);
    const second = await controlled.next();
    await second.accept();
    await secondResult;
  });

  test(kind + " releases the next attempt after rejecting the handshake and closes the refused connection", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const firstResult = controlled.connect("ws://failure.test/first");
    const secondResult = controlled.connect("ws://failure.test/second");
    const first = await controlled.next();
    await first.reply(101, [["upgrade", "websocket"], ["connection", "Upgrade"], ["sec-websocket-accept", "wrong"]]);
    await assert.rejects(firstResult, /Invalid Sec-WebSocket-Accept/);
    assert.equal(first.connection.closed, true);
    const second = await controlled.next();
    await second.accept();
    await secondResult;
  });

  test(kind + " transport shutdown aborts its active and queued attempts", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const firstResult = controlled.connect("ws://closing.test/first");
    const secondResult = controlled.connect("ws://closing.test/second");
    const first = await controlled.next();
    await first.head();
    controlled.transport.close();
    await assert.rejects(firstResult, /WebSocket transport is closed/);
    await assert.rejects(secondResult, /WebSocket transport is closed/);
    assert.equal(first.signal.aborted, true);
    if (kind === "raw") assert.equal(first.connection.closed, true);
    assert.equal(controlled.attempts.length, 1);
    await assert.rejects(controlled.connect("ws://closing.test/new"), /WebSocket transport is closed/);
  });
}

// WHATWG WebSockets §§2.2 and 3.1, RFC 6455 §4.1 response step 1, and
// RFC 7617 §2: URL credentials can answer an HTTP Basic challenge.
test("WebSocket URL normalization preserves userinfo for the opening handshake", () => {
  const url = normalizeWebSocketURL("https://us%C3%A9r+:%2Bpass@host.test/socket", { urls: hostNodeURLs });
  assert.equal(url.protocol, "wss:");
  assert.equal(url.username, "us%C3%A9r+");
  assert.equal(url.password, "%2Bpass");
  assert.equal(url.href, "wss://us%C3%A9r+:%2Bpass@host.test/socket");
});

const credentials = [
  { name: "ASCII", userinfo: "foo:bar", decoded: "foo:bar" },
  { name: "percent-encoded UTF-8 and literal plus", userinfo: "us%C3%A9r+p%252B:p%C3%A4ss+%2B%25", decoded: "usér+p%2B:päss++%" },
];
const basicChallenge: readonly HeaderEntry[] = [["www-authenticate", 'Basic realm="WebSocket"']];

for (const kind of ["raw", "dispatched"] as const) {
  for (const credential of credentials) {
    test(kind + " answers a Basic challenge with " + credential.name + " credentials and preserves the upgrade", async (t) => {
      const deflate: WebSocketDeflateProvider = {
        createDeflater: () => assert.fail("the server did not negotiate compression"),
        createInflater: () => assert.fail("the server did not negotiate compression"),
      };
      const controlled = new ControlledTransport(t, kind, deflate);
      const url = "wss://" + credential.userinfo + "@auth.test/socket?query=kept";
      const result = controlled.connect(url, new AbortController().signal, ["chat", "other"]);
      const queuedResult = controlled.connect("wss://auth.test/queued");
      const first = await controlled.next();
      const firstHead = await first.head();
      assert.equal(firstHead.headers.has("authorization"), false, "credentials wait for a challenge");
      let canceled = 0;
      const body = new ReadableStream<Uint8Array>({ cancel() { canceled++; } });
      await first.reply(401, [
        ["www-authenticate", 'Bearer realm="not Basic"'],
        ["WWW-Authenticate", 'Digest realm="a,b", nonce="x", bAsIc realm="WebSocket"'],
      ], body);
      const retry = await controlled.next();
      const retryHead = await retry.head();
      assert.equal(retryHead.target, "/socket?query=kept", "the auth attempt retains its queue slot");
      assert.equal(retryHead.headers.get("authorization"), "Basic " + Buffer.from(credential.decoded, "utf8").toString("base64"));
      assert.notEqual(retryHead.headers.get("sec-websocket-key"), firstHead.headers.get("sec-websocket-key"));
      assert.equal(retryHead.headers.get("sec-websocket-version"), "13");
      assert.equal(retryHead.headers.get("sec-websocket-protocol"), "chat, other");
      assert.equal(retryHead.headers.get("origin"), "https://client.test");
      assert.equal(retryHead.headers.get("sec-websocket-extensions"), firstHead.headers.get("sec-websocket-extensions"));
      assert.ok(retryHead.headers.get("sec-websocket-extensions")?.startsWith("permessage-deflate"));
      if (kind === "raw") {
        assert.equal(first.connection.closed, true, "close the first TCP connection before retrying");
        assert.equal(retryHead.headers.get("upgrade"), "websocket");
        assert.equal(retryHead.headers.get("connection"), "Upgrade");
      } else {
        assert.equal(canceled, 1, "cancel the refused HTTP body before retrying");
        const request = must(retry.request, "dispatched retry metadata");
        assert.equal(request.url.href, url);
        assert.equal(request.signal, first.signal);
        assert.equal(request.method, "GET");
        assert.equal(request.body, null);
        assert.equal(request.bodyLength, null);
        assert.equal(request.acceptTunnel, true);
        assert.equal(request.upgradeProtocol, "websocket");
      }
      await nextTurn();
      assert.equal(controlled.attempts.length, 2, "a later WebSocket still waits during authentication");
      await retry.accept("chat");
      assert.equal((await result).protocol, "chat");
      const queued = await controlled.next();
      assert.equal((await queued.head()).target, "/queued");
      await queued.accept();
      await queuedResult;
    });
  }

  test(kind + " answers a repeated Basic challenge only once", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const result = controlled.connect("ws://foo:wrong@auth.test/");
    const first = await controlled.next();
    let canceled = 0;
    await first.reply(401, basicChallenge, new ReadableStream<Uint8Array>({ cancel() { canceled++; } }));
    const retry = await controlled.next();
    assert.equal((await retry.head()).headers.get("authorization"), "Basic Zm9vOndyb25n");
    await retry.reply(401, basicChallenge, new ReadableStream<Uint8Array>({ cancel() { canceled++; } }));
    await assert.rejects(result);
    await nextTurn();
    assert.equal(controlled.attempts.length, 2);
    if (kind === "raw") {
      assert.equal(first.connection.closed, true);
      assert.equal(retry.connection.closed, true);
    } else assert.equal(canceled, 2);
  });

  const refusals: readonly { name: string; status: number; headers: readonly HeaderEntry[]; userinfo: string }[] = [
    { name: "a Digest challenge mentioning Basic", status: 401, headers: [["www-authenticate", 'Digest realm="Basic", nonce="x"']], userinfo: "foo:bar@" },
    { name: "a response without an authentication challenge", status: 401, headers: [], userinfo: "foo:bar@" },
    { name: "a proxy authentication response", status: 407, headers: [...basicChallenge, ["proxy-authenticate", 'Basic realm="Proxy"']], userinfo: "foo:bar@" },
    { name: "a redirection", status: 302, headers: [...basicChallenge, ["location", "ws://other.test/"]], userinfo: "foo:bar@" },
    { name: "a Basic challenge without URL credentials", status: 401, headers: basicChallenge, userinfo: "" },
  ];
  for (const refusal of refusals) {
    test(kind + " does not retry " + refusal.name, async (t) => {
      const controlled = new ControlledTransport(t, kind);
      const result = controlled.connect("ws://" + refusal.userinfo + "auth.test/");
      const first = await controlled.next();
      let canceled = false;
      await first.reply(refusal.status, refusal.headers, new ReadableStream<Uint8Array>({ cancel() { canceled = true; } }));
      await assert.rejects(result);
      await nextTurn();
      assert.equal(controlled.attempts.length, 1);
      if (kind === "raw") assert.equal(first.connection.closed, true);
      else assert.equal(canceled, true);
    });
  }

  test(kind + " rejects invalid UTF-8 credentials without changing or sending them", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const result = controlled.connect("ws://%FF:password@auth.test/");
    const first = await controlled.next();
    let canceled = false;
    await first.reply(401, basicChallenge, new ReadableStream<Uint8Array>({ cancel() { canceled = true; } }));
    await assert.rejects(result, TypeError);
    assert.equal(controlled.attempts.length, 1);
    if (kind === "raw") assert.equal(first.connection.closed, true);
    else assert.equal(canceled, true);
  });

  test(kind + " cancellation interrupts the authentication retry and releases the queued connection", async (t) => {
    const controlled = new ControlledTransport(t, kind);
    const controller = new AbortController();
    const result = controlled.connect("ws://foo:bar@auth.test/auth", controller.signal);
    const queuedResult = controlled.connect("ws://auth.test/queued");
    const first = await controlled.next();
    await first.reply(401, basicChallenge);
    const retry = await controlled.next();
    await retry.head();
    const reason = new Error("cancel the authentication retry");
    controller.abort(reason);
    await assert.rejects(result, (error) => error === reason);
    assert.equal(retry.signal.aborted, true);
    if (kind === "raw") assert.equal(retry.connection.closed, true);
    const queued = await controlled.next();
    assert.equal((await queued.head()).target, "/queued");
    await queued.accept();
    await queuedResult;
  });
}

test("dispatched authentication waits for body cancellation and remains abortable", async (t) => {
  const controlled = new ControlledTransport(t, "dispatched");
  const controller = new AbortController();
  const result = controlled.connect("ws://foo:bar@auth.test/auth", controller.signal);
  const cancelStarted = Promise.withResolvers<void>();
  const cancelFinished = Promise.withResolvers<void>();
  t.after(() => cancelFinished.resolve());
  const body = new ReadableStream<Uint8Array>({
    cancel() {
      cancelStarted.resolve();
      return cancelFinished.promise;
    },
  });
  const first = await controlled.next();
  await first.reply(401, basicChallenge, body);
  await cancelStarted.promise;
  await nextTurn();
  assert.equal(controlled.attempts.length, 1, "the retry waits for disposal of the first response");
  const reason = new Error("cancel while disposing the challenge body");
  controller.abort(reason);
  await assert.rejects(result, (error) => error === reason);
  cancelFinished.resolve();
  await nextTurn();
  assert.equal(controlled.attempts.length, 1, "settling disposal cannot restart an aborted handshake");
});

test("a dispatched challenge-body cancellation error does not mask a valid Basic retry", async (t) => {
  const controlled = new ControlledTransport(t, "dispatched");
  const result = controlled.connect("ws://foo:bar@auth.test/");
  const first = await controlled.next();
  const body = new ReadableStream<Uint8Array>({ cancel() { throw new Error("body disposal failed"); } });
  await first.reply(401, basicChallenge, body);
  const retry = await controlled.next();
  await retry.accept();
  await result;
});

// Supplemental API controls for protocol interoperability and close conversion.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { createHostNodeWebPlatform } from "../host/node-runtime.ts";
import { DOMException, WebSocket, WebSocketError, WebSocketStream } from "../src/index.ts";
import type { NormalizedWebSocketClose } from "../src/websocket/semantics.ts";
import type {
  SocketIncoming,
  SocketMessage,
  WebSocketHandshake,
  WebSocketSession,
} from "../src/websocket/transport.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};

type SocketKind = "WebSocket" | "WebSocketStream";

class PolicySession implements WebSocketSession {
  readonly protocol: string;
  readonly extensions = "";
  readonly closes: { code: number | null; reason: string }[] = [];
  private readonly incoming = Promise.withResolvers<SocketIncoming>();

  constructor(protocol: string) {
    this.protocol = protocol;
  }

  next(): Promise<SocketIncoming> {
    return this.incoming.promise;
  }

  send(_message: SocketMessage): Promise<void> {
    return assert.fail("these controls send no application messages");
  }

  close(code: number | null, reason: string): Promise<void> {
    this.closes.push({ code, reason });
    this.incoming.resolve({ kind: "close", code: code ?? 1005, reason, wasClean: true, failed: false });
    return Promise.resolve();
  }

  abort(): void {
    this.incoming.resolve({ kind: "close", code: 1006, reason: "", wasClean: false, failed: true });
  }
}

function controlledRuntime(t: TestContext) {
  const handshakes: WebSocketHandshake[] = [];
  const sessions: PolicySession[] = [];
  const errors: unknown[] = [];
  const runtime = createHostNodeWebPlatform({
    webSocketTransport: {
      connect(handshake) {
        handshakes.push(handshake);
        const session = new PolicySession(handshake.protocols[0] ?? "");
        sessions.push(session);
        return Promise.resolve(session);
      },
    },
  }, {}, (error) => errors.push(error));
  t.after(async () => {
    runtime.close();
    await new Promise<void>((resolve) => setImmediate(resolve));
    assert.deepEqual(errors, []);
  });
  return { handshakes, sessions };
}

function construct(kind: SocketKind, protocols: readonly string[]): void {
  if (kind === "WebSocket") new WebSocket("ws://example.test/socket", protocols);
  else new WebSocketStream("ws://example.test/socket", { protocols });
}

function syntaxError(error: unknown): boolean {
  return error instanceof DOMException && error.name === "SyntaxError";
}

// WebSockets 3.1 and Web IDL 3.2.25: DOMString or sequence<DOMString>.
// https://websockets.spec.whatwg.org/#dom-websocket
// https://webidl.spec.whatwg.org/#es-union
// https://webidl.spec.whatwg.org/#create-sequence-from-iterable
const JavaScriptWebSocket = WebSocket as new (url: string, protocols?: unknown) => WebSocket;

suite("WebSocket protocols retain omitted, undefined, string and sequence controls", (t) => {
  const { handshakes } = controlledRuntime(t);
  new WebSocket("ws://example.test/socket");
  new JavaScriptWebSocket("ws://example.test/socket", undefined);
  new WebSocket("ws://example.test/socket", "Chat");
  new WebSocket("ws://example.test/socket", ["Chat", "Other"]);
  assert.deepEqual(handshakes.map((handshake) => handshake.protocols), [
    [], [], ["Chat"], ["Chat", "Other"],
  ]);
});

for (const [label, value, expected] of [
  ["explicit null", null, "null"],
  ["number", 17, "17"],
  ["boolean", true, "true"],
  ["bigint", 23n, "23"],
] as const) {
  suite(`WebSocket protocols convert ${label} to a single DOMString`, (t) => {
    const { handshakes } = controlledRuntime(t);
    new JavaScriptWebSocket("ws://example.test/socket", value);
    assert.deepEqual(handshakes.map((handshake) => handshake.protocols), [[expected]]);
  });
}

suite("WebSocket protocols convert an ordinary stringifiable object once", (t) => {
  const { handshakes } = controlledRuntime(t);
  let conversions = 0;
  new JavaScriptWebSocket("ws://example.test/socket", {
    toString() {
      conversions++;
      return "Chat";
    },
  });
  assert.equal(conversions, 1);
  assert.deepEqual(handshakes.map((handshake) => handshake.protocols), [["Chat"]]);
});

suite("WebSocket protocols use string fallback for a null or undefined iterator method", (t) => {
  const { handshakes } = controlledRuntime(t);
  for (const method of [null, undefined]) {
    const observations: string[] = [];
    new JavaScriptWebSocket("ws://example.test/socket", {
      get [Symbol.iterator]() {
        observations.push("iterator");
        return method;
      },
      toString() {
        observations.push("toString");
        return "Chat";
      },
    });
    assert.deepEqual(observations, ["iterator", "toString"]);
  }
  assert.deepEqual(handshakes.map((handshake) => handshake.protocols), [["Chat"], ["Chat"]]);
});

suite("WebSocket protocols capture iterator and next methods once with their receivers", (t) => {
  const { handshakes } = controlledRuntime(t);
  const observations: string[] = [];
  let index = 0;
  const iterator = {
    get next() {
      observations.push("get next");
      return function (this: unknown): IteratorResult<unknown> {
        assert.equal(this, iterator);
        observations.push("next");
        if (index++ === 0) {
          return { done: false, value: { toString() { observations.push("convert"); return "Chat"; } } };
        }
        return { done: true, get value(): never { return assert.fail("done skips value"); } };
      };
    },
  };
  const protocols = {
    get [Symbol.iterator]() {
      observations.push("get iterator");
      return function (this: unknown) {
        assert.equal(this, protocols);
        observations.push("iterator");
        return iterator;
      };
    },
    toString(): never { return assert.fail("the iterable branch must not stringify its container"); },
  };
  new JavaScriptWebSocket("ws://example.test/socket", protocols);
  assert.deepEqual(observations, ["get iterator", "iterator", "get next", "next", "convert", "next"]);
  assert.deepEqual(handshakes.map((handshake) => handshake.protocols), [["Chat"]]);
});

suite("WebSocket protocol conversion propagates string and iterator failures before connecting", (t) => {
  const { handshakes } = controlledRuntime(t);
  const failure = new Error("protocol conversion");
  assert.throws(() => new JavaScriptWebSocket("ws://example.test/socket", Symbol("protocol")), TypeError);
  for (const protocols of [
    { toString() { throw failure; } },
    { get [Symbol.iterator](): never { throw failure; } },
    { [Symbol.iterator]() { throw failure; } },
  ]) {
    assert.throws(() => new JavaScriptWebSocket("ws://example.test/socket", protocols),
      (error: unknown) => error === failure);
  }
  for (const protocols of [
    { [Symbol.iterator]: 17, toString: () => "Chat" },
    { [Symbol.iterator]: () => null },
    { [Symbol.iterator]: () => ({ next: 17 }) },
    { [Symbol.iterator]: () => ({ next: () => null }) },
  ]) assert.throws(() => new JavaScriptWebSocket("ws://example.test/socket", protocols), TypeError);
  assert.deepEqual(handshakes, []);
});

suite("WebSocket protocol sequence conversion finishes before token validation without IteratorClose", (t) => {
  const { handshakes } = controlledRuntime(t);
  const failure = new Error("later element conversion");
  let returns = 0;
  let nexts = 0;
  const protocols = {
    [Symbol.iterator]() {
      return {
        next(): IteratorResult<unknown> {
          nexts++;
          if (nexts === 1) return { done: false, value: "invalid token" };
          return { done: false, value: { toString() { throw failure; } } };
        },
        return(): IteratorResult<unknown> {
          returns++;
          return { done: true, value: undefined };
        },
      };
    },
  };
  assert.throws(() => new JavaScriptWebSocket("ws://example.test/socket", protocols),
    (error: unknown) => error === failure);
  assert.equal(nexts, 2);
  assert.equal(returns, 0);
  assert.deepEqual(handshakes, []);
});

suite("WebSocket converts URL then protocols before parsing the URL", (t) => {
  const { handshakes } = controlledRuntime(t);
  const observations: string[] = [];
  const Constructor = WebSocket as new (url: unknown, protocols: unknown) => WebSocket;
  assert.throws(() => new Constructor({
    toString() { observations.push("url"); return "not an absolute URL"; },
  }, {
    toString() { observations.push("protocols"); return "Chat"; },
  }), syntaxError);
  assert.deepEqual(observations, ["url", "protocols"]);
  assert.deepEqual(handshakes, []);
});

suite("WebSocket converted protocol elements retain ASCII-insensitive duplicate rejection", (t) => {
  const { handshakes } = controlledRuntime(t);
  assert.throws(() => new JavaScriptWebSocket("ws://example.test/socket", [
    { toString: () => "Chat" }, { toString: () => "cHAT" },
  ]), syntaxError);
  assert.deepEqual(handshakes, []);
});

suite("WebSocketStream protocols remain sequence-only when WebSocket accepts string fallback", (t) => {
  const { handshakes } = controlledRuntime(t);
  const Constructor = WebSocketStream as new (url: string, options: { protocols: unknown }) => WebSocketStream;
  for (const protocols of ["Chat", null, 17, { toString: () => "Chat" }, {
    [Symbol.iterator]: null, toString: () => "Chat",
  }]) assert.throws(() => new Constructor("ws://example.test/socket", { protocols }), TypeError);
  assert.deepEqual(handshakes, []);
});

// WHATWG WebSockets 3.1 constructor step 9 says values must not repeat.
// ASCII-insensitive comparison is the selected interop policy, not an explicit
// case-folding requirement in that wording. The original offer is preserved.
for (const kind of ["WebSocket", "WebSocketStream"] as const) {
  suite(`${kind} rejects ASCII-case variants of a repeated protocol`, (t) => {
    const { handshakes } = controlledRuntime(t);
    for (const protocols of [
      ["echo", "eCho"],
      ["ECHO", "echo"],
      ["chat", "other", "CHAT"],
      ["X!a", "x!A"],
    ]) assert.throws(() => construct(kind, protocols), syntaxError);
    assert.deepEqual(handshakes, [], "validation finishes before the provider is called");
  });

  suite(`${kind} still rejects exactly repeated protocols`, (t) => {
    const { handshakes } = controlledRuntime(t);
    assert.throws(() => construct(kind, ["echo", "echo"]), syntaxError);
    assert.throws(() => construct(kind, ["123", "123"]), syntaxError);
    assert.deepEqual(handshakes, []);
  });

  suite(`${kind} rejects invalid protocol tokens before duplicate comparison`, (t) => {
    const { handshakes } = controlledRuntime(t);
    for (const token of ["", "with space", "écho", "echo,chat", "\u007f"])
      assert.throws(() => construct(kind, [token]), syntaxError);
    assert.deepEqual(handshakes, []);
  });

  suite(`${kind} preserves distinct offered tokens and their original casing`, async (t) => {
    const { handshakes } = controlledRuntime(t);
    const protocols = ["EcHo", "Echo.V2", "Echo-V2", "123", "!#$%&'*+.^_`|~"];
    const expected = protocols.slice();
    if (kind === "WebSocket") {
      const socket = new WebSocket("ws://example.test/socket", protocols);
      const closed = new Promise<void>((resolve) => socket.addEventListener("close", () => resolve(), { once: true }));
      await new Promise<void>((resolve) => socket.addEventListener("open", () => resolve(), { once: true }));
      assert.equal(socket.protocol, "EcHo");
      socket.close(1000);
      await closed;
    } else {
      const stream = new WebSocketStream("ws://example.test/socket", { protocols });
      assert.equal((await stream.opened).protocol, "EcHo");
      stream.close({ closeCode: 1000 });
      await stream.closed;
    }
    assert.equal(handshakes.length, 1);
    const handshake = handshakes[0];
    assert.ok(handshake);
    assert.deepEqual(handshake.protocols, expected);
    assert.deepEqual(protocols, expected, "the caller's array is unchanged");
  });
}

// JavaScript callers may provide values outside the convenient TypeScript type.
interface JavaScriptCloseInfo {
  closeCode?: number;
  reason?: unknown;
}

type CloseConsumer = "WebSocketStream" | "WebSocketError";

function closeStream(stream: WebSocketStream, options?: JavaScriptCloseInfo | null): void {
  const close = stream.close as (this: WebSocketStream, options?: JavaScriptCloseInfo | null) => void;
  close.call(stream, options);
}

async function convertCloseInfo(
  t: TestContext,
  consumer: CloseConsumer,
  options?: JavaScriptCloseInfo | null,
): Promise<NormalizedWebSocketClose> {
  if (consumer === "WebSocketError") {
    const ErrorConstructor = WebSocketError as new (
      message?: string,
      options?: JavaScriptCloseInfo | null,
    ) => WebSocketError;
    const error = new ErrorConstructor("control", options);
    return { closeCode: error.closeCode, reason: error.reason };
  }
  const { sessions } = controlledRuntime(t);
  const stream = new WebSocketStream("ws://example.test/socket");
  await stream.opened;
  closeStream(stream, options);
  const closed = await stream.closed;
  const session = sessions[0];
  assert.ok(session);
  assert.equal(session.closes.length, 1);
  const sent = session.closes[0];
  assert.ok(sent);
  assert.deepEqual(closed, { closeCode: sent.code ?? 1005, reason: sent.reason });
  return { closeCode: sent.code, reason: sent.reason };
}

// Web IDL 3.2.17 steps 4.1.3–4.1.5: only undefined selects a dictionary default.
// USVString follows 3.2.10/3.2.12. Draft PR 48 sections 4, 4.3 and 5 validate
// the converted reason and choose close code 1000 for a reason without a code.
for (const consumer of ["WebSocketStream", "WebSocketError"] as const) {
  suite(`${consumer} converts an explicit null close reason to USVString`, async (t) => {
    assert.deepEqual(await convertCloseInfo(t, consumer, { reason: null }), {
      closeCode: 1000, reason: "null",
    });
    assert.deepEqual(await convertCloseInfo(t, consumer, { closeCode: 3001, reason: null }), {
      closeCode: 3001, reason: "null",
    });
  });

  suite(`${consumer} retains the empty reason default for omitted and undefined members`, async (t) => {
    for (const options of [undefined, null, {}, { reason: undefined }, { reason: "" }]) {
      assert.deepEqual(await convertCloseInfo(t, consumer, options), {
        closeCode: null, reason: "",
      });
    }
  });

  suite(`${consumer} reads the null reason getter once after closeCode`, async (t) => {
    const reads: string[] = [];
    const result = await convertCloseInfo(t, consumer, {
      get closeCode(): undefined {
        reads.push("closeCode");
        return undefined;
      },
      get reason(): null {
        reads.push("reason");
        return null;
      },
    });
    assert.deepEqual(reads, ["closeCode", "reason"]);
    assert.deepEqual(result, { closeCode: 1000, reason: "null" });
  });
}

suite("WebSocket.close also distinguishes explicit null from an undefined reason", async (t) => {
  const { sessions } = controlledRuntime(t);
  for (const reason of [null, undefined]) {
    const socket = new WebSocket("ws://example.test/socket");
    const closed = new Promise<void>((resolve) => socket.addEventListener("close", () => resolve(), { once: true }));
    await new Promise<void>((resolve) => socket.addEventListener("open", () => resolve(), { once: true }));
    const close = socket.close as (this: WebSocket, code?: number, reason?: unknown) => void;
    close.call(socket, undefined, reason);
    await closed;
  }
  assert.deepEqual(sessions.map((session) => session.closes), [
    [{ code: 1000, reason: "null" }],
    [{ code: null, reason: "" }],
  ]);
});

// The WebSocket server's lifetime owner.
//
// Not an accept loop: listening, TLS and HTTP parsing belong to the server this is
// embedded in. What does not exist elsewhere is something that knows how many sessions
// are open, refuses when that is too many, and can close all of them once. These tests
// drive it with the canonical client over real sockets.
import assert from "node:assert/strict";
import test from "node:test";
import type { TestContext } from "node:test";
import { createServer } from "node:net";

import {
  BufferedReader,
  WebSocketServer,
} from "../src/provider.ts";
import { createHostNodeWebPlatform } from "../host/node-runtime.ts";
import {
  HostNodeScheduler,
  hostNodeRandom,
} from "../host/node-primitives.ts";
import type { Socket } from "node:net";
import { messageData, must, portOf } from "./harness.ts";
import type { ByteConnection } from "../src/provider/primitives.ts";
import type { HeaderEntry } from "../src/fetch/headers.ts";
import type { WebPlatformRuntime } from "../src/provider.ts";
import type { WebSocketServerOptions } from "../src/websocket/server.ts";
import type { WebSocket } from "../src/websocket/websocket.ts";
import type { Event } from "../src/index.ts";
import { CloseEvent } from "../src/index.ts";

const suite = (name: string, fn: (t: TestContext) => void | Promise<void>): void => {
  test(name, fn);
};
const decoder = new TextDecoder();

/** Minimal ByteConnection over an accepted Node socket, honouring maxBytes. */
function byteConnection(socket: Socket): ByteConnection {
  const pending: Uint8Array[] = [];
  // The resolver of a `read` that arrived before any bytes did. `null` when nobody waits.
  let waiting: ((chunk: Uint8Array | null) => void) | null = null;
  let ended = false;
  // `null` is the end-of-stream signal, delivered the same way a chunk is.
  const deliver = (chunk: Uint8Array | null): void => {
    if (waiting !== null) {
      const resolve = waiting;
      waiting = null;
      resolve(chunk);
      return;
    }
    if (chunk !== null) pending.push(chunk);
    else ended = true;
  };
  socket.on("data", (chunk: Buffer) => deliver(new Uint8Array(chunk)));
  socket.on("end", () => {
    ended = true;
    deliver(null);
  });
  socket.on("error", () => {});
  return {
    get closed() {
      return socket.destroyed;
    },
    async read(maxBytes: number): Promise<Uint8Array | null> {
      const take = (chunk: Uint8Array | null): Uint8Array | null => {
        if (chunk === null || chunk.length <= maxBytes) return chunk;
        pending.unshift(chunk.subarray(maxBytes));
        return chunk.subarray(0, maxBytes);
      };
      const next = pending.shift();
      if (next !== undefined) return take(next);
      if (ended) return null;
      return new Promise<Uint8Array | null>((resolve) => {
        waiting = (chunk) => resolve(take(chunk));
      });
    },
    async write(data: Uint8Array): Promise<number> {
      socket.write(Buffer.from(data));
      return data.length;
    },
    close() {
      socket.destroy();
    },
  };
}

async function readRequestHead(reader: BufferedReader): Promise<{
  method: string;
  headers: HeaderEntry[];
}> {
  const requestLine = await reader.line(8192);
  const headers: HeaderEntry[] = [];
  while (true) {
    const line = await reader.line(8192);
    if (line === "") break;
    const colon = line.indexOf(":");
    headers.push([line.slice(0, colon).trim().toLowerCase(), line.slice(colon + 1).trim()]);
  }
  return { method: must(requestLine.split(" ")[0], "a request line begins with a method"), headers };
}

/** Runs a WebSocketServer behind a real listener and echoes whatever arrives. */
async function hosted(t: TestContext, serverOptions: Partial<WebSocketServerOptions> = {}) {
  const server = new WebSocketServer({
    random: hostNodeRandom,
    scheduler: new HostNodeScheduler(() => {}),
    ...serverOptions,
  });
  const refusals: number[] = [];
  const sessionEnded = Promise.withResolvers<void>();
  const sockets = new Set<Socket>();
  const listener = createServer((socket) => {
    sockets.add(socket);
    socket.on("error", () => {});
    socket.on("close", () => sockets.delete(socket));
    void (async () => {
      const connection = byteConnection(socket);
      const reader = new BufferedReader(connection);
      const request = await readRequestHead(reader);
      const result = await server.upgrade(request.method, request.headers, connection, reader);
      if (!result.accepted) {
        refusals.push(result.status);
        return;
      }
      try {
        while (true) {
          const incoming = await result.session.next();
          if (incoming.kind === "close") break;
          await result.session.send(incoming);
        }
      } catch {
        // A server closing under a live session is an ordinary ending here.
      } finally {
        sessionEnded.resolve();
      }
    })();
  });
  listener.listen(0, "127.0.0.1");
  await new Promise((resolve) => listener.once("listening", resolve));
  t.after(() => {
    server.destroy();
    for (const socket of sockets) socket.destroy();
    return new Promise<void>((resolve) => listener.close(() => resolve()));
  });
  return { server, port: portOf(listener), refusals, sessionEnded: sessionEnded.promise };
}

function clientFor(t: TestContext): WebPlatformRuntime {
  const api = createHostNodeWebPlatform();
  t.after(() => api.close());
  return api;
}

async function connected(
  api: WebPlatformRuntime,
  port: number,
  protocols?: readonly string[],
): Promise<WebSocket> {
  const socket = api.createWebSocket(`ws://127.0.0.1:${port}/`, protocols ?? []);
  await new Promise((resolve, reject) => {
    socket.addEventListener("open", resolve);
    socket.addEventListener("error", () => reject(new Error("handshake refused")));
  });
  return socket;
}

suite("the server counts the sessions it is holding", async (t) => {
  const { server, port, sessionEnded } = await hosted(t, { protocols: ["chat"] });
  const api = clientFor(t);
  assert.equal(server.connections, 0);

  const first = await connected(api, port, ["chat"]);
  const second = await connected(api, port, ["chat"]);
  assert.equal(server.connections, 2);
  assert.equal(first.protocol, "chat");

  // A round trip proves the counted sessions are the live ones.
  const back = new Promise<unknown>((resolve) => first.addEventListener("message", (e: Event) => resolve(messageData(e))));
  first.send("still here");
  assert.equal(await back, "still here");

  const closed = new Promise((resolve) => second.addEventListener("close", resolve));
  second.close();
  await closed;
  // The session removes itself when it ends, without the server being told.
  await sessionEnded;
  assert.equal(server.connections, 1, "a session that ends stops being held");
  first.close();
});

suite("the connection bound is enforced with a response, not a dropped socket", async (t) => {
  const { server, port, refusals } = await hosted(t, { maxConnections: 1 });
  const api = clientFor(t);
  const first = await connected(api, port);
  assert.equal(server.connections, 1);

  // The second upgrade is refused above the bound.
  const second = api.createWebSocket(`ws://127.0.0.1:${port}/`);
  const outcome = await new Promise((resolve) => {
    second.addEventListener("open", () => resolve("open"));
    second.addEventListener("error", () => resolve("error"));
  });
  assert.equal(outcome, "error", "a client above the bound must be turned away");
  assert.deepEqual(refusals, [503], "and told why, rather than left to time out");
  assert.equal(server.connections, 1, "the refusal did not become a held session");
  first.close();
});

suite("close reaches every open session and settles once", async (t) => {
  const { server, port } = await hosted(t);
  const api = clientFor(t);
  const sockets = [await connected(api, port), await connected(api, port)];
  assert.equal(server.connections, 2);

  const closes = sockets.map(
    (socket) =>
      new Promise<CloseEvent>((resolve) =>
        socket.addEventListener("close", (event: Event) => {
          // The close listener receives a `CloseEvent`; the assertions below read `code` and
          // `wasClean`, which only that arm carries.
          assert.ok(event instanceof CloseEvent, "a close listener receives a CloseEvent");
          resolve(event);
        }),
      ),
  );
  // Two callers share one shutdown rather than starting a second.
  const first = server.close();
  const second = server.close();
  assert.equal(first, second, "repeated close is one shutdown");
  await first;
  assert.equal(server.connections, 0);
  assert.equal(server.accepting, false);

  const events = await Promise.all(closes);
  for (const event of events) {
    assert.equal(event.code, 1001, "a closing server says it is going away");
    assert.equal(event.wasClean, true, "and closes cleanly rather than dropping the socket");
  }
});

