  const { writable } = await stream.opened;
  const writer = writable.getWriter();
  let conversions = 0;
  for (const value of [undefined, null, 17, true, 23n, "\ud800", "\udc00", "🔌", {
    [Symbol.toPrimitive](hint: string) {
      assert.equal(hint, "string");
