test("WPT WebSocket — pinned ordinary-host corpus", async (suite) => {
  assert.ok(manifest.fixtures.length > 0, "the WPT selection must not be empty");
  if (filter !== undefined) suite.diagnostic("Explicit targeted WPT filter: " + filter);
  suite.diagnostic("Selected WPT file/variant runs: " + manifest.fixtures.length);
  const server = await startWptServer();
  suite.after(async () => {
    await server.close();
    assert.deepEqual(server.errors, [], "the resource server recorded an unexpected failure");
  });
  await runWptFixtures(suite, root, manifest, (reportError, context) => {
    const runtime = createWptRuntime(server, {
      baseURL: context.url.href,
      origin: context.url.origin,
      websocket: { connectTimeoutMs: 60_000, handshakeTimeoutMs: 60_000, closeTimeoutMs: 60_000 },
    }, reportError);
    const globals: Record<string, unknown> = {
      AbortController, AbortSignal, Blob, CloseEvent, CustomEvent, DOMException,
      Event, EventTarget, File, MessageEvent, TextDecoder, TextEncoder,
      URLSearchParams, WebSocket,
      // URL is the existing ordinary-node URL capability used by the provider.
      // No Node WebSocket, EventSource, Blob or Event is supplied here.
      URL, location: context.url, performance,
      fetch: runtime.fetch,
      // The implementation and fixture use the same ECMAScript buffer realm.
      // Cross-realm exposure is outside this ordinary-host execution profile.
      ArrayBuffer, SharedArrayBuffer, DataView, Int8Array, Uint8Array, Uint8ClampedArray,
      Int16Array, Uint16Array, Int32Array, Uint32Array, Float16Array, Float32Array,
      Float64Array, BigInt64Array, BigUint64Array,
    };
    const snapshots = snapshotInterfaces(globals);
    return {
      globals,
      // window is only a global alias for three prototype-setter fixtures. No
      // Window interface, Document, navigation or browsing context is emulated.
      globalAliases: ["self", "window"],
      async close() {
        try {
          runtime.close();
          // Drain already-enqueued protocol cleanup tasks before the next VM.
          await new Promise<void>((resolve) => setImmediate(resolve));
        } finally {
          restoreInterfaces(snapshots);
        }
      },
    };
  }, {
    baseURL: (fixture) => (fixture.path.includes(".https.") ? server.httpsOrigin : server.httpOrigin) + "/",
    timeoutCategory: "network",
    timeouts: { default: 60_000, long: 120_000, network: 60_000, reconnect: 120_000 },
    transformScript(source) {
      return substitute(source, { host: "web-platform.test", ports: server.ports });
    },
  });
});

// Reproduce the per-file report directly from the verified, unedited corpus.
import assert from "node:assert/strict";
import { readFileSync, writeFileSync } from "node:fs";
import { observeWptFixture, loadWptFixtures } from "../runner.ts";
import { publishWptHangs, recordWptHung } from "../hung.ts";
import type { InstrumentResult } from "../../../../../tooling/gate/step-result.ts";
import type { WptManifest } from "../runner.ts";
import { createCompressionEnvironment, startCompressionResourceServer } from "./environment.ts";

interface ExcludedFixture {
  path: string;
  category: string;
  reason: string;
}
export interface CompressionManifest extends WptManifest {
  excludedFixtures: ExcludedFixture[];
}

const root = new URL("../", import.meta.url);
const manifest = JSON.parse(readFileSync(new URL("manifest.json", import.meta.url), "utf8")) as CompressionManifest;
const server = await startCompressionResourceServer();
const files: object[] = [];
const hangs: InstrumentResult[] = [];
const totals = { registered: 0, pass: 0, fail: 0, blocked: 0, notRunFiles: 0, harnessFailures: 0 };
try {
  for (const prepared of loadWptFixtures(root, manifest)) {
    const path = prepared.context.fixture.path;
    try {
      const observation = await observeWptFixture(prepared, (reportError) => createCompressionEnvironment(server, reportError));
      const { results, errors, hung } = observation;
      if (hung !== undefined) { hangs.push(hung.observation); recordWptHung(hung); }
      totals.harnessFailures += errors.length;
      const counts = { registered: results.length, pass: 0, fail: 0, blocked: 0 };
      for (const result of results) counts[result.status]++;
      totals.registered += counts.registered;
      totals.pass += counts.pass;
      totals.fail += counts.fail;
      totals.blocked += counts.blocked;
      files.push({ path, ...counts, cases: results.map((result) => ({
        name: result.name, status: result.status,
        ...(result.reason === undefined ? {} : { reason: result.reason }),
        ...(result.error === undefined ? {} : { error: String(result.error) }),
      })), ...(hung === undefined ? {} : { instrument: hung.observation, unfinished: observation.unfinished }),
        ...(errors.length === 0 ? {} : { harnessErrors: errors.map(String) }),
      });
      console.error(`${path}: ${counts.pass} pass, ${counts.fail} fail, ${counts.blocked} blocked`);
    } catch (error) {
      totals.harnessFailures++;
      files.push({ path, registered: null, pass: null, fail: null, blocked: null,
        harnessError: String(error),
        ...(error instanceof AggregateError ? { errors: error.errors.map(String) } : {}),
      });
      console.error(`${path}: harness failure: ${String(error)}`);
    }
  }
  for (const fixture of manifest.excludedFixtures) {
    totals.notRunFiles++;
    files.push({ ...fixture, registered: null, pass: null, fail: null, blocked: null, status: "not-run" });
  }
  for (const path of ["media/foo.vtt", "media/test-av-384k-44100Hz-1ch-320x240-30fps-10kfr.webm"]) {
    assert.ok(server.requested.has(path), `unchanged fixture did not fetch ${path}`);
  }
} finally {
  await server.close();
}
const report = { revision: "ae05f5cb53d3e290b91ae1e92069baa188292880", totals, files };
const json = JSON.stringify(report, null, 2) + "\n";
if (process.argv[2] === undefined) process.stdout.write(json);
else writeFileSync(process.argv[2], json);
process.exitCode = publishWptHangs(hangs, totals.fail + totals.harnessFailures);

// Test-only assembly for unchanged Compression Streams WPT. The local HTTP peer
// serves verified original media; the client's Fetch and stream classes are nts's.
import assert from "node:assert/strict";
import { createServer } from "node:http";
import { createHostNodeWebPlatform } from "../../../host/node-runtime.ts";
import {
  Blob, CompressionStream, DecompressionStream, DOMException,
  ReadableStream, TextDecoder, TextEncoder, TransformStream, WritableStream,
} from "../../../src/index.ts";
import type { CompressionContext, CompressionFailure, CompressionFormat } from "../../../src/provider.ts";
import { NodeCompressionProvider } from "../../node-compression-provider.ts";
import type { WptEnvironment } from "../runner.ts";
import { readWptVersions, verifiedWptSource } from "../versions.ts";

// The ESNext-only package config omits DOM's declaration for this actual Node
// ECMAScript global. The fixture, rather than this assembly, uses its Memory API.
declare const WebAssembly: unknown;

const root = new URL("../", import.meta.url);
const mediaTypes: Readonly<Record<string, string>> = {
  "media/foo.vtt": "text/vtt",
  "media/test-av-384k-44100Hz-1ch-320x240-30fps-10kfr.webm": "video/webm",
};

export interface CompressionResourceServer {
  readonly origin: string;
  readonly requested: ReadonlySet<string>;
  close(): Promise<void>;
}

/** A real HTTP peer for the corpus's two media requests; no fetch stand-in. */
export async function startCompressionResourceServer(): Promise<CompressionResourceServer> {
  const versions = readWptVersions(root);
  const resources = new Map<string, Buffer>();
  for (const path of Object.keys(mediaTypes)) resources.set(path, verifiedWptSource(root, path, versions));
  const requested = new Set<string>();
  const server = createServer((request, response) => {
    const path = new URL(request.url ?? "/", "http://127.0.0.1/").pathname.slice(1);
    const bytes = resources.get(path);
    if (request.method !== "GET" || bytes === undefined) {
      response.writeHead(404).end();
      return;
    }
    requested.add(path);
    response.writeHead(200, {
      "Content-Type": mediaTypes[path]!,
      "Content-Length": bytes.byteLength,
    }).end(bytes);
  });
  await new Promise<void>((resolve, reject) => {
    const failed = (error: Error): void => { server.off("listening", ready); reject(error); };
    const ready = (): void => { server.off("error", failed); resolve(); };
    server.once("error", failed);
    server.once("listening", ready);
    server.listen(0, "127.0.0.1");
  });
  const address = server.address();
  assert.ok(address !== null && typeof address !== "string");
  return {
    origin: `http://127.0.0.1:${address.port}`,
    requested,
    close: () => new Promise<void>((resolve, reject) => {
      server.close((error) => { if (error !== undefined) reject(error); else resolve(); });
      server.closeAllConnections();
    }),
  };
}

/** WPT sometimes leaves a stream open after its first read; end its native lifetime. */
class FixtureCompressionProvider extends NodeCompressionProvider {
  private readonly contexts: CompressionContext[] = [];

  override createCompressor(format: CompressionFormat, bits: number): CompressionContext | CompressionFailure {
    return this.retain(super.createCompressor(format, bits));
  }

  override createDecompressor(format: CompressionFormat, bits: number): CompressionContext | CompressionFailure {
    return this.retain(super.createDecompressor(format, bits));
  }

  private retain(result: CompressionContext | CompressionFailure): CompressionContext | CompressionFailure {
    if (!("failure" in result)) this.contexts.push(result);
    return result;
  }

  close(): void {
    for (const context of this.contexts) context.close();
    this.contexts.length = 0;
  }
}

export function createCompressionEnvironment(
  server: CompressionResourceServer,
  reportError: (error: unknown) => void,
): WptEnvironment {
  const compression = new FixtureCompressionProvider();
  const runtime = createHostNodeWebPlatform({
    compression, baseURL: server.origin + "/", origin: server.origin,
  }, {}, reportError);
  return {
    exposeSelf: true,
    globals: {
      Blob, CompressionStream, DecompressionStream, DOMException,
      ReadableStream, TextDecoder, TextEncoder, TransformStream, WritableStream,
      fetch: runtime.fetch,
      // Genuine implementation-realm ECMAScript constructors preserve BufferSource
      // identities. WebAssembly.Memory is used only to create shared rejection inputs.
      Object, Function, Promise, ArrayBuffer, SharedArrayBuffer, DataView,
      Int8Array, Uint8Array, Uint8ClampedArray, Int16Array, Uint16Array,
      Int32Array, Uint32Array, Float16Array, Float32Array, Float64Array,
      BigInt64Array, BigUint64Array, WebAssembly,
    },
    close(): void {
      compression.close();
      runtime.close();
    },
  };
}

