  }

  /** A provider's actual uncaught-global channel, separate from assertions. */
  reportUncaughtException(error: unknown): void {
    if (!this.allowUncaughtException) this.reportError(error);
  }

  recordError(error: unknown): void { this.errors.push(error); }

  /** Recheck recorded failures after awaited provider teardown, before file success. */
  assertNoErrors(): void {
    if (this.errors.length !== 0 || this.cleanupErrors.length !== 0) {
      throw new AggregateError([...this.errors, ...this.cleanupErrors], "WPT harness failed", { cause: this.hung });
    }
    if (this.hung) throw this.hung;
  }

  /** Body completion and file liveness are independent evidence. A failed body
   * remains complete even when its cleanup never settles. */
  snapshot(): { results: WptResult[]; unfinished: string[]; errors: unknown[]; hung?: WptHungError } {
    return {
      results: this.tests.filter(test => test.closed).map(test => ({ ...test.result })),
      unfinished: this.tests.filter(test => !test.closed).map(test => test.result.name),
      errors: [...this.errors, ...this.cleanupErrors],
      ...(this.hung === undefined ? {} : { hung: this.hung }),
    };
  }

  inTest<T>(test: WptTest, callback: () => T): T {
    return this.asyncTest.run(test, callback);
  }

  progress(test: WptTest, phase: "test" | "cleanup"): void {
    if (this.hung || this.finished) return;
    this.pending.set(test, phase);
    this.touch();
  }

  completed(test: WptTest): void {
    assert.ok(this.pending.delete(test), "completed WPT test was not pending");
    // The same pending inventory drives inactivity attribution and upstream
    // automatic completion, including promise tests still queued to start.
    if (this.loaded && !this.explicitDone && this.pending.size === 0) this.closeRegistration();
    this.touch();
  }

  private touch(): void {
    if (this.hung || this.finished) return;
    const [test, phase] = this.pending.entries().next().value ?? [];
    this.inactivity.renew({ file: test?.file ?? this.filename, test: test?.result.name ?? "<registration>",
      phase: phase ?? "registration" }, phase === "cleanup" ? test?.result : undefined);
  }

  private observeHung(file: string, test: string, phase: string, result?: WptResult): void {
    if (this.hung) return;
    this.hung = new WptHungError(file, test, phase, result);
    this.inactivity.close();
    for (const test of this.tests) test.abandon();
    this.notMeasured.reject(this.hung);
  }

  private checkSynchronousResult(result: unknown, description: string): void {
    if (isThenable(result)) {
      void Promise.resolve(result).catch((error: unknown) => this.recordError(error));
    }
    assert.equal(result, undefined, `${description} must return undefined`);
  }

  private closeRegistration(): void {
    this.registrationClosed = true;
    this.registrationDone.resolve();
    this.touch();
  }

  async finish(): Promise<WptResult[]> {
    try { return await Promise.race([this.drain(), this.notMeasured.promise]); }
    finally {
      this.finished = true;
      this.inactivity.close();
      for (const timer of this.globalTimers) clearTimeout(timer);
      this.globalTimers.clear();
    }
  }

  private async drain(): Promise<WptResult[]> {
    this.loaded = true;
    if ((!this.explicitDone && this.pending.size === 0) || this.errors.length !== 0) this.closeRegistration();
    this.touch();
    await this.registrationDone.promise;
    await this.promiseQueue;
    await Promise.all(this.tests.map((test) => test.completed));
    for (const name of Object.keys(this.blocks)) {
      assert.ok(this.seenBlocks.has(name), `stale WPT capability exclusion: ${name}`);
    }
    this.assertNoErrors();
    return this.tests.map((test) => test.result);
  }
}

// Liveness is an instrument observation, never a WPT verdict.
import { appendFileSync, readFileSync } from "node:fs";
import { pathToFileURL } from "node:url";
import { publishHung, type InstrumentResult } from "../../../../tooling/gate/step-result.ts";
import type { WptActivity, WptDeadlineScheduler, WptResult } from "./harness.ts";

export const wptHostDeadline: WptDeadlineScheduler = (callback, milliseconds) => {
  const timer = setTimeout(callback, milliseconds);
  return () => clearTimeout(timer);
};

/** Both WPT runners use one renewable, generously bounded file instrument. */
export class WptInactivityGuard {
  private cancel: (() => void) | undefined;
  private generation = 0;
  private closed = false;
  private readonly expired: (activity: WptActivity, result?: WptResult) => void;
  private readonly schedule: WptDeadlineScheduler;
  private readonly milliseconds: number;
  constructor(
    expired: (activity: WptActivity, result?: WptResult) => void,
    schedule: WptDeadlineScheduler = wptHostDeadline,
    milliseconds = 300000,
  ) {
    if (!Number.isSafeInteger(milliseconds) || milliseconds <= 0) throw new Error("invalid WPT inactivity bound");
    this.expired = expired;
    this.schedule = schedule;
    this.milliseconds = milliseconds;
  }
  renew(activity: WptActivity, result?: WptResult): void {
    if (this.closed) return;
    this.cancel?.();
    const generation = ++this.generation;
    this.cancel = this.schedule(() => {
      if (this.closed || generation !== this.generation) return;
      this.close();
      this.expired(activity, result);
    }, this.milliseconds, activity);
  }
  close(): void { this.closed = true; this.generation++; this.cancel?.(); }
}

export class WptHungError extends Error {
  readonly observation: InstrumentResult;
  readonly testResult: WptResult | undefined;
  constructor(file: string, test: string, phase: string, testResult?: WptResult) {
    const reason = `${file}: ${test}: ${phase} made no progress before the liveness bound`;
    super(reason);
    this.name = "WptHungError";
    this.observation = {
      version: 1, verdict: "NOT RUN", kind: "hung", reason,
      step: process.env.NTS_GATE_STEP ?? "web-platform",
      attempt: process.env.NTS_GATE_STEP_ATTEMPT ?? "standalone",
    };
    // A completed body and its unfinished cleanup are separate observations.
    this.testResult = testResult === undefined ? undefined : { ...testResult };
  }
}

function errorDetail(error: unknown): { message: string; stack?: string } {
  let message: string;
  try { message = String(error); } catch { message = "<unprintable thrown value>"; }
  let stack: string | undefined;
  try {
    if (typeof error === "object" && error !== null && "stack" in error && typeof error.stack === "string") stack = error.stack;
  } catch { /* A diagnostic getter cannot turn a hung instrument into a failure. */ }
  return { message, ...(stack === undefined ? {} : { stack }) };
}

/** Test children record only local evidence; the owner publishes after drain. */
export function recordWptHung(error: WptHungError, env: NodeJS.ProcessEnv = process.env,
  write: (text: string) => void = text => { process.stderr.write(text); }): void {
  const body = error.testResult;
  const testResult = body === undefined ? undefined : { ...body,
    ...(Object.hasOwn(body, "error") ? { error: errorDetail(body.error) } : {}) };
  const record = JSON.stringify({ ...error.observation, testResult });
  if (env.NTS_WPT_HUNG_RESULTS) appendFileSync(env.NTS_WPT_HUNG_RESULTS, record + "\n");
  write(`NOT RUN (hung): ${record}\n`);
}

/** A boundary with one observation may use this convenience directly. */
export function reportWptHung(error: WptHungError, env: NodeJS.ProcessEnv = process.env,
  write: (text: string) => void = text => { process.stderr.write(text); }, completedFailures = 0): void {
  recordWptHung(error, env, write);
  publishHung(error.observation.reason, env, completedFailures);
}

/** Shared owner rule for host tests and standalone census commands. */
export function publishWptHangs(observations: readonly InstrumentResult[], completedFailures: number,
  env: NodeJS.ProcessEnv = process.env): number {
  if (!observations.length) return completedFailures > 0 ? 1 : 0;
  publishHung(observations.map(row => row.reason).join("\n"), env, completedFailures);
  return completedFailures > 0 ? 1 : 124;
}

export function readWptHungResults(path: string): InstrumentResult[] {
  const lines = readFileSync(path, "utf8").split("\n").filter(Boolean);
  return lines.map(line => {
    const value: unknown = JSON.parse(line);
    if (typeof value !== "object" || value === null || !("version" in value) || value.version !== 1 ||
      !("verdict" in value) || value.verdict !== "NOT RUN" || !("kind" in value) || value.kind !== "hung" ||
      !("reason" in value) || typeof value.reason !== "string" || !value.reason ||
      !("step" in value) || typeof value.step !== "string" || !value.step ||
      !("attempt" in value) || typeof value.attempt !== "string" || !value.attempt)
      throw new Error("invalid WPT hung observation");
    return value as InstrumentResult;
  });
}

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  if (process.argv[2] === "--outer") {
    reportWptHung(new WptHungError("<host suite>", "<unfinished file>", "outer execution"));
    process.exitCode = 124;
  } else {
    const results = readWptHungResults(process.argv[2]!);
    for (const result of results) publishHung(result.reason);
    if (results.length) process.exitCode = 124;
  }
}

