// Node reproductions of eventsource/resources/*.py from the revision in
// upstream-manifest.json. The Python files remain the authority for these responses.
import type { IncomingMessage, ServerResponse } from "node:http";

/** Return false for resources served by the static-file or common-resource handler. */
export async function handleEventSource(
  request: IncomingMessage,
  response: ServerResponse,
  url: URL,
): Promise<boolean> {
  switch (url.pathname) {
    case "/eventsource/resources/message.py":
      await message(response, url);
      break;
    case "/eventsource/resources/message2.py":
      await message2(response);
      break;
    case "/eventsource/resources/last-event-id.py":
      lastEventId(request, response, url);
      break;
    case "/eventsource/resources/last-event-id2.py":
      lastEventId2(response, url);
      break;
    case "/eventsource/resources/status-error.py":
      statusError(response, url);
      break;
    case "/eventsource/resources/status-reconnect.py":
      statusReconnect(request, response, url);
      break;
    case "/eventsource/resources/reconnect-fail.py":
      reconnectFail(request, response, url);
      break;
    case "/eventsource/resources/cors.py":
      await cors(request, response, url);
      break;
    case "/eventsource/resources/cors-cookie.py":
      corsCookie(request, response, url);
      break;
    default:
      return false;
  }
  return true;
}

// WPT: eventsource/resources/message.py.
async function message(response: ServerResponse, url: URL): Promise<void> {
  const mime = query(url, "mime") ?? Buffer.from("text/event-stream");
  const data = query(url, "message") ?? Buffer.from("data: data");
  const newline = query(url, "newline")?.toString("latin1") === "none" ? "" : "\n\n";
  const sleep = integer(query(url, "sleep"), 0);
  if (sleep !== 0 && !(await delay(response, sleep))) return;
  response.setHeader("Content-Type", mime.toString("latin1"));
  response.end(Buffer.concat([data, Buffer.from(newline + "\n")]));
}

// WPT: eventsource/resources/message2.py.
async function message2(response: ServerResponse): Promise<void> {
  response.setHeader("Content-Type", "text/event-stream");
  response.setHeader("Cache-Control", "no-cache");
  response.flushHeaders();
  const chunks = [
    "data:msg", "\n", "data: msg", "\n\n",
    ":", "\n",
    "falsefield:msg", "\n\n",
    "falsefield:msg", "\n", "Data:data", "\n\n",
    "data", "\n\n",
    "data:end", "\n\n",
  ];
  while (!response.destroyed && !response.writableEnded) {
    for (const chunk of chunks) {
      if (!(await write(response, chunk))) return;
    }
    if (!(await delay(response, 2000))) return;
  }
}

// WPT: eventsource/resources/last-event-id.py.
function lastEventId(request: IncomingMessage, response: ServerResponse, url: URL): void {
  response.setHeader("Content-Type", "text/event-stream");
  const last = Buffer.from(header(request, "last-event-id"), "latin1");
  if (last.length !== 0) {
    response.end(Buffer.concat([Buffer.from("data: "), last, Buffer.from("\n\n")]));
  } else {
    const id = query(url, "idvalue") ?? Buffer.from("\u2026");
    response.end(Buffer.concat([
      Buffer.from("id: "), id, Buffer.from("\nretry: 200\ndata: hello\n\n"),
    ]));
  }
}

// WPT: eventsource/resources/last-event-id2.py.
function lastEventId2(response: ServerResponse, url: URL): void {
  response.setHeader("Content-Type", "text/event-stream");
  let type = 1;
  try {
    type = integer(query(url, "type"), 1);
  } catch {
    // The upstream resource deliberately treats malformed integers as ID_PERSISTS.
  }
  switch (type) {
    case 1:
      response.end("id: 1\ndata: 1\n\ndata: 2\n\nid: 2\ndata:3\n\ndata:4\n\n");
      break;
    case 2:
      response.end("id: 1\ndata: 1\n\nid:\ndata:2\n\ndata:3\n\n");
      break;
    case 3:
      response.end("id: 1\ndata: 1\n\nid\ndata:2\n\ndata:3\n\n");
      break;
    default:
      response.end("data: invalid_test\n\n");
  }
}

// WPT: eventsource/resources/status-error.py.
function statusError(response: ServerResponse, url: URL): void {
  const status = integer(query(url, "status"), 404);
  response.statusCode = status;
  response.statusMessage = "HAHAHAHA";
  response.setHeader("Content-Type", "text/event-stream");
  response.end(status === 204 || status === 205 ? "" : "data: data\n\n");
}

// WPT: eventsource/resources/status-reconnect.py.
function statusReconnect(request: IncomingMessage, response: ServerResponse, url: URL): void {
  const status = query(url, "status") ?? Buffer.from("204");
  const name = "request" + (query(url, "id") ?? status).toString("latin1");
  response.setHeader("Content-Type", "text/event-stream");
  if (cookie(request, name) === status.toString("latin1")) {
    response.statusCode = 200;
    removeCookie(response, name);
    response.end("data: data\n\n");
  } else {
    setCookie(response, name, status.toString("latin1"));
    response.statusCode = integer(status, 204);
    response.statusMessage = "TEST";
    response.end("retry: 2\n" + (query(url, "ok_first") === undefined ? "" : "data: ok\n\n"));
  }
}

// WPT: eventsource/resources/reconnect-fail.py.
function reconnectFail(request: IncomingMessage, response: ServerResponse, url: URL): void {
  const name = "recon_fail_" + requiredQuery(url, "id").toString("latin1");
  const state = cookie(request, name);
  response.setHeader("Content-Type", "text/event-stream");
  if (state === "opened") {
    response.statusCode = 200;
    response.statusMessage = "RECONNECT";
    setCookie(response, name, "reconnected");
    response.end("data: reconnected\n\n");
  } else if (state === "reconnected") {
    response.statusCode = 204;
    response.statusMessage = "NO CONTENT (CLOSE)";
    removeCookie(response, name);
    // Node suppresses the body of a 204, as wptserve does.
    response.end("data: closed\n\n");
  } else {
    response.statusCode = 200;
    response.statusMessage = "OPEN";
    setCookie(response, name, "opened");
    response.end("retry: 2\ndata: opened\n\n");
  }
}

// WPT: eventsource/resources/cors.py, including its delegation to common/redirect.py.
async function cors(request: IncomingMessage, response: ServerResponse, url: URL): Promise<void> {
  const origin = query(url, "origin")?.toString("latin1") ?? header(request, "origin");
  const credentials = query(url, "credentials")?.toString("latin1") ?? "true";
  response.setHeader("Access-Control-Allow-Origin", origin);
  response.setHeader("Access-Control-Allow-Credentials", credentials);
  switch (query(url, "run")?.toString("latin1")) {
    case "message":
      await message(response, url);
      break;
    case "status-reconnect":
      statusReconnect(request, response, url);
      break;
    case "cache-control":
      response.setHeader("Content-Type", "text/event-stream");
      response.end(Buffer.from("data: " + header(request, "cache-control") + "\n\n", "latin1"));
      break;
    case "redirect": {
      let status = 302;
      try {
        status = integer(query(url, "status"), 302);
      } catch {
        // common/redirect.py ignores an invalid status parameter.
      }
      response.statusCode = status;
      response.setHeader("Location", requiredQuery(url, "location").toString("latin1"));
      if (query(url, "enable-cors") !== undefined && header(request, "origin") !== "") {
        response.setHeader("Content-Type", "text/plain");
        response.setHeader("Access-Control-Allow-Origin", header(request, "origin"));
        response.setHeader("Access-Control-Allow-Credentials", "true");
      }
      response.end();
      break;
    }
    default:
      response.end();
  }
}

// WPT: eventsource/resources/cors-cookie.py.
function corsCookie(request: IncomingMessage, response: ServerResponse, url: URL): void {
  const last = header(request, "last-event-id");
  const ident = query(url, "ident")?.toString("latin1") ?? "test";
  const received = cookie(request, ident) === undefined ? "NO_COOKIE" : "COOKIE";
  const origin = query(url, "origin")?.toString("latin1") ?? header(request, "origin");
  const credentials = query(url, "credentials")?.toString("latin1") ?? "true";
  if (origin !== "none") response.setHeader("Access-Control-Allow-Origin", origin);
  if (credentials !== "none") response.setHeader("Access-Control-Allow-Credentials", credentials);
  if (last === "") {
    response.setHeader("Content-Type", "text/event-stream");
    setCookie(response, ident, "COOKIE");
    response.end("id: 1\nretry: 200\ndata: first " + received + "\n\n");
  } else if (last === "1") {
    response.setHeader("Content-Type", "text/event-stream");
    setCookie(response, ident, "COOKIE", "Fri, 27 Jul 2001 00:00:00 GMT");
    response.end("id: 2\ndata: second " + received + "\n\n");
  } else {
    response.setHeader("Content-Type", "stop");
    response.end(Buffer.from("data: " + last + received + "\n\n", "latin1"));
  }
}

/** WPT's request.GET contains decoded bytes, including deliberately invalid UTF-8. */
function query(url: URL, name: string): Buffer | undefined {
  for (const field of url.search.slice(1).split("&")) {
    const equals = field.indexOf("=");
    const key = equals < 0 ? field : field.slice(0, equals);
    if (decodeQueryBytes(key).toString("latin1") !== name) continue;
    return decodeQueryBytes(equals < 0 ? "" : field.slice(equals + 1));
  }
  return undefined;
}

function requiredQuery(url: URL, name: string): Buffer {
  const value = query(url, name);
  if (value === undefined) throw new TypeError("Missing WPT query parameter: " + name);
  return value;
}

function decodeQueryBytes(value: string): Buffer {
  const input = Buffer.from(value);
  const output = Buffer.allocUnsafe(input.length);
  let length = 0;
  for (let index = 0; index < input.length; index++) {
    const byte = input[index] ?? 0;
    if (byte === 37 && index + 2 < input.length) {
      const high = hex(input[index + 1] ?? 0);
      const low = hex(input[index + 2] ?? 0);
      if (high >= 0 && low >= 0) {
        output[length++] = high * 16 + low;
        index += 2;
        continue;
      }
    }
    output[length++] = byte === 43 ? 32 : byte;
  }
  return output.subarray(0, length);
}

function hex(byte: number): number {
  if (byte >= 48 && byte <= 57) return byte - 48;
  if (byte >= 65 && byte <= 70) return byte - 55;
  if (byte >= 97 && byte <= 102) return byte - 87;
  return -1;
}

function integer(value: Buffer | undefined, fallback: number): number {
  if (value === undefined) return fallback;
  const text = value.toString("latin1").trim();
  if (!/^[+-]?\d+$/.test(text)) throw new TypeError("Invalid WPT integer parameter");
  return Number(text);
}

function header(request: IncomingMessage, name: string): string {
  const value = request.headers[name];
  return Array.isArray(value) ? value.join(", ") : value ?? "";
}

function cookie(request: IncomingMessage, name: string): string | undefined {
  for (const item of header(request, "cookie").split(";")) {
    const equals = item.indexOf("=");
    if (equals < 0 || item.slice(0, equals).trim() !== name) continue;
    const value = item.slice(equals + 1).trim();
    return value.startsWith('"') && value.endsWith('"') ? value.slice(1, -1) : value;
  }
  return undefined;
}

function setCookie(response: ServerResponse, name: string, value: string, expires?: string): void {
  response.appendHeader("Set-Cookie", name + "=" + value + "; Path=/" +
    (expires === undefined ? "" : "; Expires=" + expires));
}

function removeCookie(response: ServerResponse, name: string): void {
  response.appendHeader("Set-Cookie", name + "=; Path=/; Max-Age=0");
}

/** Upstream delays control the resource; cancellation clears them without waiting. */
function delay(response: ServerResponse, milliseconds: number): Promise<boolean> {
  if (response.destroyed || response.writableEnded) return Promise.resolve(false);
  return new Promise((resolve) => {
    const finish = (live: boolean): void => {
      clearTimeout(timer);
      response.off("close", closed);
      resolve(live);
    };
    const closed = (): void => finish(false);
    const timer = setTimeout(() => finish(true), milliseconds);
    response.once("close", closed);
  });
}

function write(response: ServerResponse, chunk: string): Promise<boolean> {
  if (response.destroyed || response.writableEnded) return Promise.resolve(false);
  return new Promise((resolve) => {
    const closed = (): void => resolve(false);
    response.once("close", closed);
    response.write(chunk, (error?: Error | null) => {
      response.off("close", closed);
      resolve(!error && !response.destroyed);
    });
  });
}

// Node-only, finite HTTP resources for the network Fetch WPT corpus.
// Reference sources: web-platform-tests/wpt at
// 2b38ea1cb920a2d0f91bf140d0e1eba73db8e742, fetch/api/resources/.
// The copied WPT cases and source-policy fixes follow after the pending stack.
import type { IncomingMessage, ServerResponse } from "node:http";
import { decodePercentBytes, readQueryBytes } from "./http-resources.ts";
import type { WptServerState } from "./state.ts";

const namespace = "/fetch/api/resources/";
const routes = new Set([
  "echo-content.py", "method.py", "status.py", "inspect-headers.py", "echo-header-bytes.py",
  "redirect.py", "redirect-empty-location.py", "clean-stash.py", "authentication.py", "dump-authorization-header.py",
].map((name) => namespace + name));

function header(request: IncomingMessage, name: string): string | undefined {
  const value = request.headers[name.toLowerCase()];
  return Array.isArray(value) ? value.join(", ") : value;
}

function requiredQuery(url: URL, name: string): Buffer {
  const value = readQueryBytes(url, name);
  if (value === null) throw new Error("Missing WPT Fetch resource parameter: " + name);
  return value;
}

function integer(value: Buffer | null, fallback: number): number {
  if (value === null) return fallback;
  const text = value.toString("latin1");
  // Python int(bytes) accepts ASCII whitespace and digit separators, not a
  // Unicode trim or Node's high-bit-clearing ASCII decoder.
  const match = /^[\t\n\v\f\r ]*([+-]?[0-9](?:_?[0-9])*)[\t\n\v\f\r ]*$/.exec(text);
  if (match === null) throw new Error("Invalid WPT Fetch integer: " + text);
  const result = Number(match[1]!.replaceAll("_", ""));
  if (!Number.isSafeInteger(result)) throw new Error("WPT Fetch integer is outside the safe range");
  return result;
}

async function readBody(request: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  return Buffer.concat(chunks);
}

function formValue(body: Buffer, name: string): Buffer | null {
  // A POST form has no URL fragment syntax. Decode its bytes directly, retaining
  // raw '#', malformed percent escapes and non-UTF-8 octets.
  const decode = (value: string): string => value.replace(/\+|%([0-9a-fA-F]{2})/g,
    (part: string, hex: string | undefined) => part === "+" ? " " : String.fromCharCode(Number.parseInt(hex!, 16)));
  for (const field of body.toString("latin1").split("&")) {
    const equals = field.indexOf("=");
    if (decode(equals === -1 ? field : field.slice(0, equals)) === name) {
      return Buffer.from(decode(equals === -1 ? "" : field.slice(equals + 1)), "latin1");
    }
  }
  return null;
}

function echoRequestHeaders(request: IncomingMessage, response: ServerResponse): void {
  response.setHeader("X-Request-Method", request.method ?? "GET");
  response.setHeader("X-Request-Content-Length", header(request, "content-length") ?? "NO");
  response.setHeader("X-Request-Content-Type", header(request, "content-type") ?? "NO");
}

function inspectHeaders(request: IncomingMessage, response: ServerResponse, url: URL): void {
  // WPT fetch/api/resources/inspect-headers.py.
  const checked = readQueryBytes(url, "headers")?.toString("latin1").split("|") ?? [];
  for (const name of checked) {
    const value = header(request, name);
    if (value !== undefined) response.appendHeader("x-request-" + name, value);
  }
  if (readQueryBytes(url, "cors") !== null) {
    response.setHeader("Access-Control-Allow-Origin", header(request, "origin") ?? "*");
    response.setHeader("Access-Control-Allow-Credentials", "true");
    response.setHeader("Access-Control-Allow-Methods", "GET, POST, HEAD");
    response.setHeader("Access-Control-Expose-Headers", checked.map((name) => "x-request-" + name).join(", "));
    const allowed = readQueryBytes(url, "allow_headers");
    response.setHeader("Access-Control-Allow-Headers", allowed === null
      ? Object.keys(request.headers).join(", ")
      : allowed.toString("latin1"));
  }
  response.setHeader("Content-Type", "text/plain");
  response.end();
}

interface RedirectState {
  count: number;
  preflight: string;
}

function redirectState(value: unknown): RedirectState {
  if (value === null) return { count: 0, preflight: "0" };
  if (typeof value !== "object" || value === null
    || !("count" in value) || typeof value.count !== "number"
    || !("preflight" in value) || typeof value.preflight !== "string") {
    throw new Error("Unexpected WPT Fetch redirect stash value");
  }
  return { count: value.count, preflight: value.preflight };
}

/** Python urlencode() quotes UTF-8 strings with spaces as '+' and leaves '~'. */
function formQuote(value: string): string {
  return encodeURIComponent(value).replace(/[!'()*]/g, (character) =>
    "%" + character.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, "+");
}

/** WPT GET.items() gives the first value for each distinct byte-string key. */
function redirectQuery(url: URL): string {
  const parameters = new Map<string, string>();
  for (const field of url.search.slice(1).split("&")) {
    if (field === "") continue;
    const equals = field.indexOf("=");
    const key = decodePercentBytes(equals === -1 ? field : field.slice(0, equals)).toString("latin1");
    if (!parameters.has(key)) {
      parameters.set(key, decodePercentBytes(equals === -1 ? "" : field.slice(equals + 1)).toString("latin1"));
    }
  }
  return [...parameters].map(([key, value]) => formQuote(key) + "=" + formQuote(value)).join("&");
}

async function redirect(
  request: IncomingMessage,
  response: ServerResponse,
  url: URL,
  state: WptServerState,
): Promise<void> {
  // WPT fetch/api/resources/redirect.py. Delay-bearing modes need an injected
  // clock before they enter this deterministic server profile.
  const delay = readQueryBytes(url, "delay");
  if (delay !== null) {
    const value = delay.toString("latin1");
    if (!/^[\t\n\v\f\r ]*[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?[\t\n\v\f\r ]*$/.test(value)
      || Number(value) !== 0) {
      throw new Error("WPT Fetch redirect delay requires an injected clock");
    }
  }
  const token = readQueryBytes(url, "token")?.toString("latin1");
  const data = redirectState(token === undefined ? null : state.take(namespace, token));
  response.setHeader("Content-Type", "text/plain");
  response.setHeader("Cache-Control", "no-cache");
  response.setHeader("Pragma", "no-cache");
  const origin = header(request, "origin");
  response.setHeader("Access-Control-Allow-Origin", origin ?? "*");
  if (origin !== undefined) response.setHeader("Access-Control-Allow-Credentials", "true");
  if (request.method === "OPTIONS") {
    const allowed = readQueryBytes(url, "allow_headers");
    if (allowed !== null) response.setHeader("Access-Control-Allow-Headers", allowed.toString("latin1"));
    data.preflight = "1";
    if (readQueryBytes(url, "redirect_preflight") === null) {
      if (token) state.put(namespace, token, data);
      response.end();
      return;
    }
  }
  const body = await readBody(request);
  let status = readQueryBytes(url, "redirect_status");
  if (status === null) {
    const contentType = header(request, "content-type")?.split(";")[0]?.trim().toLowerCase();
    if (contentType === "application/x-www-form-urlencoded") status = formValue(body, "redirect_status");
    else if (contentType === "multipart/form-data") {
      throw new Error("WPT Fetch redirect multipart status requires multipart form parsing");
    }
  }
  response.statusCode = integer(status, 302);
  data.count++;
  const location = readQueryBytes(url, "location");
  if (location !== null) {
    let target = location.toString("latin1");
    if (readQueryBytes(url, "simple") === null) {
      const scheme = /^([A-Za-z][A-Za-z0-9+.-]*):/.exec(target)?.[1]?.toLowerCase() ?? "";
      if (scheme === "" || scheme === "http" || scheme === "https") {
        target += target.includes("?") ? "&" : "?";
        target += redirectQuery(url) + "&count=" + data.count;
      }
    }
    response.setHeader("Location", target);
  }
  const referrerPolicy = readQueryBytes(url, "redirect_referrerpolicy");
  if (referrerPolicy !== null) response.setHeader("Referrer-Policy", referrerPolicy.toString("latin1"));
  if (token) {
    state.put(namespace, token, data);
    const maximum = readQueryBytes(url, "max_count");
    if (maximum !== null && data.count > integer(maximum, 0)) {
      // Returning only a string in wptserve discards the pending redirect tuple.
      for (const name of response.getHeaderNames()) response.removeHeader(name);
      response.statusCode = 200;
      response.end(String(data.count - 1));
      return;
    }
  }
  response.end();
}

function authenticate(request: IncomingMessage, response: ServerResponse, url: URL): void {
  // WPT fetch/api/resources/authentication.py.
  const authorization = header(request, "authorization") ?? "";
  const basic = /^Basic\s+(.+)$/i.exec(authorization);
  if (basic !== null && Buffer.from(basic[1]!, "base64").toString("latin1") === "user:password") {
    response.end("Authentication done");
    return;
  }
  response.statusCode = 401;
  response.statusMessage = "Unauthorized";
  response.setHeader("WWW-Authenticate", 'Basic realm="' + (readQueryBytes(url, "realm")?.toString("latin1") ?? "test") + '"');
  response.end("Please login with credentials 'user' and 'password'");
}

function dumpAuthorization(request: IncomingMessage, response: ServerResponse, url: URL): void {
  // WPT fetch/api/resources/dump-authorization-header.py.
  response.setHeader("Content-Type", "text/html");
  response.setHeader("Cache-Control", "no-cache");
  if (readQueryBytes(url, "strip_auth_header")?.length && request.method === "OPTIONS"
    && (header(request, "access-control-request-headers") ?? "").toLowerCase().includes("authorization")) {
    response.statusCode = 500;
    response.end("fail");
    return;
  }
  const origin = header(request, "origin");
  response.setHeader("Access-Control-Allow-Origin", origin ?? "*");
  if (origin !== undefined) response.setHeader("Access-Control-Allow-Credentials", "true");
  response.setHeader("Access-Control-Allow-Headers", "Authorization");
  response.end(Buffer.from(header(request, "authorization") ?? "none", "latin1"));
}

/** Return false for resources owned by the existing server or not yet prepared. */
export async function handleFetchResource(
  request: IncomingMessage,
  response: ServerResponse,
  url: URL,
  state: WptServerState,
): Promise<boolean> {
  if (!routes.has(url.pathname)) return false;
  if (readQueryBytes(url, "pipe") !== null) {
    throw new Error("Unsupported WPT Fetch pipe modifier");
  }
  switch (url.pathname) {
    case "/fetch/api/resources/echo-content.py":
      // WPT fetch/api/resources/echo-content.py.
      echoRequestHeaders(request, response);
      response.setHeader("Content-Type", "text/plain");
      response.end(await readBody(request));
      return true;
    case "/fetch/api/resources/method.py":
      // WPT fetch/api/resources/method.py.
      if (readQueryBytes(url, "cors") !== null) {
        response.setHeader("Access-Control-Allow-Origin", "*");
        response.setHeader("Access-Control-Allow-Credentials", "true");
        response.setHeader("Access-Control-Allow-Methods", "GET, POST, PUT, FOO");
        response.setHeader("Access-Control-Allow-Headers", "x-test, x-foo");
        response.setHeader("Access-Control-Expose-Headers", "x-request-method");
      }
      echoRequestHeaders(request, response);
      for (const name of ["content-encoding", "content-language", "content-location"]) {
        response.setHeader("X-Request-" + name, header(request, name) ?? "NO");
      }
      response.end(await readBody(request));
      return true;
    case "/fetch/api/resources/status.py":
      // WPT fetch/api/resources/status.py.
      response.statusCode = integer(readQueryBytes(url, "code"), 200);
      response.statusMessage = readQueryBytes(url, "text")?.toString("latin1") ?? "OMG";
      response.setHeader("Content-Type", readQueryBytes(url, "type")?.toString("latin1") ?? "");
      response.setHeader("X-Request-Method", request.method ?? "GET");
      // An explicitly empty phrase is distinct from the default. Node's
      // implicit writeHead would replace the empty string with its status text.
      response.writeHead(response.statusCode, response.statusMessage);
      response.end(readQueryBytes(url, "content") ?? Buffer.alloc(0));
      return true;
    case "/fetch/api/resources/inspect-headers.py":
      inspectHeaders(request, response, url);
      return true;
    case "/fetch/api/resources/echo-header-bytes.py": {
      // WPT fetch/api/resources/echo-header-bytes.py.
      response.setHeader("Content-Type", "text/plain");
      const names = requiredQuery(url, "headers").toString("latin1").split("|");
      response.end(Buffer.from(names.map((name) => name + ": "
        + Buffer.from(header(request, name) ?? "", "latin1").toString("hex")).join("\n"), "latin1"));
      return true;
    }
    case "/fetch/api/resources/redirect.py":
      await redirect(request, response, url, state);
      return true;
    case "/fetch/api/resources/redirect-empty-location.py":
      // WPT fetch/api/resources/redirect-empty-location.py.
      response.statusCode = 302;
      response.setHeader("Location", "");
      response.end();
      return true;
    case "/fetch/api/resources/clean-stash.py":
      // WPT fetch/api/resources/clean-stash.py.
      response.end(state.take(namespace, requiredQuery(url, "token").toString("latin1")) === null ? "0" : "1");
      return true;
    case "/fetch/api/resources/authentication.py":
      authenticate(request, response, url);
      return true;
    case "/fetch/api/resources/dump-authorization-header.py":
      dumpAuthorization(request, response, url);
      return true;
    default:
      return false;
  }
}

// Node-only implementations of the WPT HTTP resources used by the realtime suites.
// The source paths below refer to unedited files pinned in upstream-manifest.json.
import { createHash } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";
import type { WptServerState } from "./state.ts";

/** Decode form values as bytes, preserving deliberately malformed UTF-8 fixtures. */
export function decodePercentBytes(value: string, form = true): Buffer {
  const source = Buffer.from(value);
  const result = Buffer.allocUnsafe(source.length);
  let length = 0;
  for (let index = 0; index < source.length; index++) {
    const byte = source[index]!;
    if (byte === 37 && index + 2 < source.length) {
      const high = hexDigit(source[index + 1]!);
      const low = hexDigit(source[index + 2]!);
      if (high !== -1 && low !== -1) {
        result[length++] = high * 16 + low;
        index += 2;
        continue;
      }
    }
    result[length++] = form && byte === 43 ? 32 : byte;
  }
  return result.subarray(0, length);
}

function hexDigit(byte: number): number {
  if (byte >= 48 && byte <= 57) return byte - 48;
  if (byte >= 65 && byte <= 70) return byte - 55;
  if (byte >= 97 && byte <= 102) return byte - 87;
  return -1;
}

/** Like wptserve request.GET.first(), without a UTF-8 decoding round trip. */
export function readQueryBytes(url: URL, name: string): Buffer | null {
  for (const field of url.search.slice(1).split("&")) {
    const equals = field.indexOf("=");
    const key = equals === -1 ? field : field.slice(0, equals);
    if (decodePercentBytes(key).toString("latin1") !== name) continue;
    return decodePercentBytes(equals === -1 ? "" : field.slice(equals + 1));
  }
  return null;
}

function requireQueryBytes(url: URL, name: string): Buffer {
  const value = readQueryBytes(url, name);
  if (value === null) throw new Error("Missing WPT resource parameter: " + name);
  return value;
}

function firstHeader(request: IncomingMessage, name: string): string | undefined {
  const value = request.headers[name];
  return Array.isArray(value) ? value[0] : value;
}

/** A fixture delay ends when the client goes away, including during server cleanup. */
async function delay(response: ServerResponse, milliseconds: number): Promise<boolean> {
  if (response.destroyed) return false;
  return new Promise<boolean>((resolve) => {
    const timer = setTimeout(() => finish(true), milliseconds);
    const closed = (): void => finish(false);
    function finish(completed: boolean): void {
      clearTimeout(timer);
      response.off("close", closed);
      resolve(completed);
    }
    response.once("close", closed);
  });
}

async function writeChunk(response: ServerResponse, chunk: Buffer): Promise<boolean> {
  if (response.destroyed) return false;
  if (response.write(chunk)) return true;
  return new Promise<boolean>((resolve, reject) => {
    const drained = (): void => finish(true);
    const closed = (): void => finish(false);
    const failed = (error: Error): void => {
      cleanup();
      reject(error);
    };
    function cleanup(): void {
      response.off("drain", drained);
      response.off("close", closed);
      response.off("error", failed);
    }
    function finish(completed: boolean): void {
      cleanup();
      resolve(completed);
    }
    response.once("drain", drained);
    response.once("close", closed);
    response.once("error", failed);
  });
}

function integerOr(value: Buffer | null, fallback: number): number {
  if (value === null) return fallback;
  const text = value.toString("ascii").trim();
  return /^[+-]?\d+$/.test(text) ? Number(text) : fallback;
}

function writeRedirect(request: IncomingMessage, response: ServerResponse, url: URL): void {
  // WPT common/redirect.py: preserve Location bytes and echo CORS only when requested.
  response.statusCode = integerOr(readQueryBytes(url, "status"), 302);
  response.setHeader("Location", requireQueryBytes(url, "location").toString("latin1"));
  if (readQueryBytes(url, "enable-cors") !== null) {
    const origin = firstHeader(request, "origin");
    if (origin !== undefined && origin !== "") {
      response.setHeader("Content-Type", "text/plain");
      response.setHeader("Access-Control-Allow-Origin", origin);
      response.setHeader("Access-Control-Allow-Credentials", "true");
    }
  }
  response.end();
}

function putStash(
  request: IncomingMessage,
  response: ServerResponse,
  url: URL,
  state: WptServerState,
): void {
  // WPT fetch/api/resources/stash-put.py. Its namespace is the URL directory.
  if (request.method === "OPTIONS") {
    response.setHeader("Access-Control-Allow-Origin", "*");
    response.setHeader("Access-Control-Allow-Methods", "*");
    response.setHeader("Access-Control-Allow-Headers", "*");
    response.end("done");
    return;
  }
  if (readQueryBytes(url, "disallow_cross_origin") === null) {
    response.setHeader("Access-Control-Allow-Origin", "*");
  } else if (readQueryBytes(url, "mode")?.toString("latin1") !== "no-cors") {
    // Keep the upstream assertion's spelling, including its trailing space.
    if (readQueryBytes(url, "frame_origin ") === null) {
      throw new Error("WPT stash-put requires frame_origin ");
    }
    const frameOrigin = requireQueryBytes(url, "frame_origin").toString("utf8");
    if (frameOrigin !== url.origin) {
      response.end("not stashing for cors request");
      return;
    }
  }
  state.put(
    "/fetch/api/resources/",
    requireQueryBytes(url, "key").toString("latin1"),
    requireQueryBytes(url, "value").toString("latin1"),
  );
  response.end("done");
}

async function chunkedContent(response: ServerResponse, url: URL): Promise<void> {
  // WPT xhr/resources/content-in-chunks.py. Each chunk is hex, not UTF-8 text.
  const chunks: Buffer[] = [];
  for (const raw of url.searchParams.getAll("chunk")) {
    const hex = raw.replace(/[\t\n\v\f\r ]/g, "");
    if (!/^(?:[0-9a-fA-F]{2})*$/.test(hex)) throw new Error("Invalid WPT hex chunk");
    chunks.push(Buffer.from(hex, "hex"));
  }
  const milliseconds = Number(readQueryBytes(url, "ms")?.toString("ascii") ?? "100");
  if (!Number.isFinite(milliseconds) || milliseconds < 0) {
    throw new Error("Invalid WPT chunk delay");
  }
  response.setHeader("Content-Type", readQueryBytes(url, "type")?.toString("latin1") ?? "text/plain");
  response.setHeader("Transfer-Encoding", "chunked");
  response.flushHeaders();
  for (const chunk of chunks) {
    if (!(await delay(response, milliseconds))) return;
    if (!(await writeChunk(response, chunk))) return;
  }
  response.end();
}

/** Return false for a static resource or a route this server does not implement. */
export async function handleHttpResource(
  request: IncomingMessage,
  response: ServerResponse,
  url: URL,
  state: WptServerState,
): Promise<boolean> {
  switch (url.pathname) {
    case "/common/redirect.py":
      writeRedirect(request, response, url);
      return true;
    case "/common/blank.html": {
      // WPT wptserve's pipe=trickle(d1/d2), used by WebSocket sync-XHR cases.
      const match = /^trickle\(d([0-9]+(?:\.[0-9]+)?)\)$/.exec(url.searchParams.get("pipe") ?? "");
      if (match === null) return false;
      response.setHeader("Content-Type", "text/html");
      response.flushHeaders();
      if (await delay(response, Number(match[1]) * 1000)) response.end();
      return true;
    }
    case "/xhr/resources/content-in-chunks.py":
      await chunkedContent(response, url);
      return true;
    case "/fetch/api/resources/stash-put.py":
      putStash(request, response, url, state);
      return true;
    case "/fetch/api/resources/stash-take.py":
      // WPT fetch/api/resources/stash-take.py: take consumes the value; absent is null.
      response.setHeader("Access-Control-Allow-Origin", "*");
      response.setHeader("Content-Type", "application/json");
      response.end(JSON.stringify(state.take("/fetch/api/resources/", requireQueryBytes(url, "key").toString("latin1"))));
      return true;
    case "/websockets/opening-handshake/resources/redirect_response.py":
      // WPT websockets/opening-handshake/resources/redirect_response.py.
      response.statusCode = 301;
      response.statusMessage = "moved";
      response.setHeader("Location", "/echo");
      response.end();
      return true;
    case "/websockets/security/check.py":
      // WPT websockets/security/check.py.
      response.end(firstHeader(request, "sec-websocket-key") === undefined ? "PASS" : "FAIL");
      return true;
    case "/websockets/cookies/support/set-cookie.py":
      // WPT websockets/cookies/support/set-cookie.py uses unquote(), not unquote_plus().
      response.setHeader("Set-Cookie", decodePercentBytes(url.search.slice(1), false).toString("utf8"));
      response.setHeader("Content-Type", "text/plain");
      response.end();
      return true;
    case "/websockets/resources/accept-handshake.py": {
      // WPT websockets/resources/accept-handshake.py leaves the upgraded socket open.
      const key = firstHeader(request, "sec-websocket-key");
      if (key === undefined) throw new Error("WPT accept-handshake requires Sec-WebSocket-Key");
      const accept = createHash("sha1")
        .update(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")
        .digest("base64");
      response.writeHead(101, "Switching Protocols", {
        Upgrade: "websocket",
        Connection: "Upgrade",
        "Sec-WebSocket-Accept": accept,
      });
      response.flushHeaders();
      return true;
    }
    default:
      return false;
  }
}

// Node-only peer for WPT's pywebsocket handlers. The runtime under test is never
// used to parse or generate its peer's frames (RFC 6455 sections 4, 5 and 7).
import { createHash } from "node:crypto";
import type { IncomingMessage } from "node:http";
import type { Socket } from "node:net";
import { constants, createDeflateRaw, createInflateRaw } from "node:zlib";
import type { DeflateRaw, InflateRaw } from "node:zlib";

export interface WptHandshakeOptions {
  protocol?: string;
  headers?: readonly (readonly [string, string])[];
  compression?: boolean;
  acceptKey?: string;
  statusText?: string;
  initialFrame?: Uint8Array;
}

export interface WptMessage {
  readonly binary: boolean;
  readonly data: Buffer;
}

const tail = Buffer.from([0, 0, 255, 255]);
const maximumMessageBytes = 64 * 1024 * 1024;

interface DeflateOffer {
  readonly response: string;
  readonly windowBits: number;
  readonly reset: boolean;
}

function deflateOffer(header: string): DeflateOffer | null {
  // Match the pinned pywebsocket3 processor's accepted offers. In particular its
  // client_max_window_bits is bare and client_no_context_takeover is declined.
  for (const offer of header.split(",")) {
    const parts = offer.split(";").map((part) => part.trim());
    if (parts[0] !== "permessage-deflate") continue;
    const seen = new Set<string>();
    let windowBits = 15;
    let limited = false;
    let reset = false;
    let valid = true;
    for (const part of parts.slice(1)) {
      const equals = part.indexOf("=");
      const name = (equals < 0 ? part : part.slice(0, equals)).trim();
      const value = equals < 0 ? null : part.slice(equals + 1).trim();
      if (seen.has(name)) { valid = false; break; }
      seen.add(name);
      if (name === "server_max_window_bits" && value !== null && /^(?:9|1[0-5]|"(?:9|1[0-5])")$/.test(value)) {
        // Node/zlib cannot produce an 8-bit raw stream. Declining the extension
        // is legal; never advertise a window the native codec cannot provide.
        windowBits = Number(value.replaceAll('"', ""));
        limited = true;
      } else if (name === "server_no_context_takeover" && value === null) reset = true;
      else if (name !== "client_max_window_bits" || value !== null) { valid = false; break; }
    }
    if (!valid) continue;
    return {
      response: "permessage-deflate" + (limited ? "; server_max_window_bits=" + windowBits : "")
        + (reset ? "; server_no_context_takeover" : ""),
      windowBits,
      reset,
    };
  }
  return null;
}

/** RFC 7692 contexts use Node's native zlib; framing stays in the test peer. */
class DeflateContext {
  private readonly codec: DeflateRaw | InflateRaw;
  private chunks: Buffer[] = [];
  private length = 0;
  private failure: Error | null = null;
  private pending: ((error: Error) => void) | null = null;

  constructor(inflate: boolean, windowBits = 15) {
    this.codec = inflate ? createInflateRaw({ windowBits }) : createDeflateRaw({ windowBits });
    this.codec.on("data", (chunk: Buffer) => {
      this.length += chunk.length;
      if (this.length > maximumMessageBytes) {
        this.codec.destroy(new Error("WPT peer message exceeds its buffer limit"));
      } else this.chunks.push(chunk);
    });
    this.codec.on("error", (error: Error) => {
      this.failure = error;
      this.pending?.(error);
    });
  }

  process(input: Uint8Array): Promise<Buffer> {
    if (this.failure !== null) return Promise.reject(this.failure);
    this.chunks = [];
    this.length = 0;
    return new Promise<Buffer>((resolve, reject) => {
      this.pending = reject;
      this.codec.write(input, (error) => {
        if (error) { this.pending = null; reject(error); return; }
        this.codec.flush(constants.Z_SYNC_FLUSH, () => {
          this.pending = null;
          if (this.failure !== null) reject(this.failure);
          else resolve(Buffer.concat(this.chunks, this.length));
        });
      });
    });
  }

  reset(): void { this.codec.reset(); }
  close(): void {
    this.failure ??= new Error("WPT compression context closed");
    this.pending?.(this.failure);
    this.pending = null;
    this.codec.destroy();
  }
}

export function serverFrame(opcode: number, payload: Uint8Array, fin = true, compressed = false): Buffer {
  const size = payload.byteLength;
  const header = Buffer.alloc(size < 126 ? 2 : size < 65536 ? 4 : 10);
  header[0] = (fin ? 128 : 0) | (compressed ? 64 : 0) | opcode;
  header[1] = size < 126 ? size : size < 65536 ? 126 : 127;
  if (size >= 65536) header.writeBigUInt64BE(BigInt(size), 2);
  else if (size >= 126) header.writeUInt16BE(size, 2);
  return Buffer.concat([header, payload]);
}

export class WptWebSocketPeer {
  readonly request: IncomingMessage;
  readonly url: URL;
  readonly secure: boolean;
  readonly socket: Socket;
  readonly signal: AbortSignal;
  closeCode: number | null = null;
  closeReason = "";
  closeReceived = false;
  private readonly controller = new AbortController();
  private input: Buffer;
  private offset = 0;
  private wake: (() => void) | null = null;
  private ended = false;
  private closeSent = false;
  private inflater: DeflateContext | null = null;
  private deflater: DeflateContext | null = null;
  private resetDeflater = false;

  constructor(request: IncomingMessage, socket: Socket, head: Buffer, secure: boolean) {
    this.request = request;
    this.socket = socket;
    this.secure = secure;
    this.url = new URL(request.url ?? "/", `${secure ? "https" : "http"}://${request.headers.host ?? "web-platform.test"}`);
    this.signal = this.controller.signal;
    this.input = head;
    // Paused reads are essential to the upstream backpressure handlers. A 'data'
    // listener that eagerly queues the whole message defeats the test.
    socket.pause();
    socket.on("readable", () => { this.wake?.(); });
    socket.on("end", () => { this.ended = true; this.wake?.(); });
    socket.on("error", () => { this.ended = true; this.wake?.(); });
    socket.on("close", () => {
      this.ended = true;
      this.wake?.();
      this.controller.abort(new Error("WPT peer closed"));
      this.inflater?.close();
      this.deflater?.close();
    });
  }

  header(name: string): string {
    const value = this.request.headers[name.toLowerCase()];
    return Array.isArray(value) ? value.join(", ") : value ?? "";
  }

  async validateHandshake(): Promise<boolean> {
    // pywebsocket3/handshake/hybi.py validates these before calling a handler.
    // Keeping the peer strict makes a broken client request observable.
    const valid = this.request.method === "GET" && this.request.httpVersion === "1.1"
      && this.header("host") !== "" && this.header("upgrade").toLowerCase() === "websocket"
      && this.header("connection").toLowerCase().split(",").some((token) => token.trim() === "upgrade")
      && /^[+/0-9A-Za-z]{21}[AQgw]==$/.test(this.header("sec-websocket-key"));
    const version = this.header("sec-websocket-version");
    if (valid && version === "13") return true;
    const unsupported = valid && version !== "";
    await this.writeRaw(`HTTP/1.1 ${unsupported ? "426 Upgrade Required" : "400 Bad Request"}\r\n`
      + (unsupported ? "Sec-WebSocket-Version: 13\r\n" : "") + "Content-Length: 0\r\n\r\n");
    this.end();
    return false;
  }

  async accept(options: WptHandshakeOptions = {}): Promise<void> {
    const headers: (readonly [string, string])[] = [
      ["Upgrade", "websocket"],
      ["Connection", "Upgrade"],
      ["Sec-WebSocket-Accept", options.acceptKey ?? createHash("sha1")
        .update(this.header("sec-websocket-key") + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")
        .digest("base64")],
    ];
    if (options.protocol !== undefined) headers.push(["Sec-WebSocket-Protocol", options.protocol]);
    if (options.compression !== false) {
      const offer = deflateOffer(this.header("sec-websocket-extensions"));
      if (offer !== null) {
        headers.push(["Sec-WebSocket-Extensions", offer.response]);
        this.inflater = new DeflateContext(true);
        this.deflater = new DeflateContext(false, offer.windowBits);
        this.resetDeflater = offer.reset;
      }
    }
    headers.push(...(options.headers ?? []));
    const response = Buffer.from(`HTTP/1.1 101 ${options.statusText ?? "Switching Protocols"}\r\n`
      + headers.map(([name, value]) => name + ": " + value + "\r\n").join("") + "\r\n", "latin1");
    await this.writeRaw(options.initialFrame === undefined
      ? response : Buffer.concat([response, options.initialFrame]));
  }

  private async exact(length: number): Promise<Buffer | null> {
    const chunks: Buffer[] = [];
    let remaining = length;
    while (remaining > 0) {
      if (this.offset === this.input.length) {
        const chunk: unknown = this.socket.read();
        if (chunk !== null) {
          if (!Buffer.isBuffer(chunk)) throw new TypeError("WPT socket must produce bytes");
          this.input = chunk;
          this.offset = 0;
        } else {
          if (this.ended || this.socket.destroyed || this.socket.readableEnded) return null;
          await new Promise<void>((resolve) => { this.wake = resolve; });
          this.wake = null;
          continue;
        }
      }
      const size = Math.min(remaining, this.input.length - this.offset);
      chunks.push(this.input.subarray(this.offset, this.offset + size));
      this.offset += size;
      remaining -= size;
    }
    return chunks.length === 1 ? chunks[0]! : Buffer.concat(chunks, length);
  }

  async readMessage(): Promise<WptMessage | null> {
    const fragments: Buffer[] = [];
    let size = 0;
    let messageOpcode = 0;
    let compressed = false;
    while (!this.closeReceived) {
      const header = await this.exact(2);
      if (header === null) return null;
      const first = header[0]!;
      const second = header[1]!;
      const opcode = first & 15;
      const fin = (first & 128) !== 0;
      if ((second & 128) === 0 || (first & 48) !== 0) throw new Error("Invalid client frame");
      let length = second & 127;
      if (length >= 126) {
        const extended = await this.exact(length === 126 ? 2 : 8);
        if (extended === null) return null;
        const value = length === 126 ? BigInt(extended.readUInt16BE()) : extended.readBigUInt64BE();
        if (value > BigInt(maximumMessageBytes)) throw new Error("WPT frame too large");
        length = Number(value);
      }
      const mask = await this.exact(4);
      const wire = await this.exact(length);
      if (mask === null || wire === null) return null;
      const payload = Buffer.allocUnsafe(length);
      for (let index = 0; index < length; index++) payload[index] = wire[index]! ^ mask[index & 3]!;
      if (opcode >= 8) {
        if (!fin || length > 125 || (first & 64) !== 0) throw new Error("Invalid control frame");
        if (opcode === 8) {
          this.closeReceived = true;
          if (length === 1) throw new Error("Invalid close payload");
          this.closeCode = length < 2 ? null : payload.readUInt16BE();
          this.closeReason = payload.subarray(2).toString("utf8");
          return null;
        }
        if (opcode === 9) await this.sendFrame(10, payload);
        else if (opcode !== 10) throw new Error("Invalid control opcode");
        continue;
      }
      if (opcode === 1 || opcode === 2) {
        if (messageOpcode !== 0) throw new Error("Interleaved messages");
        messageOpcode = opcode;
        compressed = (first & 64) !== 0;
      } else if (opcode !== 0 || messageOpcode === 0 || (first & 64) !== 0) {
        throw new Error("Invalid continuation");
      }
      fragments.push(payload);
      size += length;
      if (size > maximumMessageBytes) throw new Error("WPT message too large");
      if (!fin) continue;
      let data: Buffer = fragments.length === 1 ? payload : Buffer.concat(fragments, size);
      if (compressed) {
        if (this.inflater === null) throw new Error("Unnegotiated compression");
        data = await this.inflater.process(Buffer.concat([data, tail]));
      }
      return { binary: messageOpcode === 2, data };
    }
    return null;
  }

  async send(data: string | Uint8Array, binary = typeof data !== "string"): Promise<void> {
    let payload: Uint8Array = typeof data === "string" ? Buffer.from(data) : data;
    if (this.deflater !== null) {
      const flushed = await this.deflater.process(payload);
      payload = flushed.subarray(0, flushed.length - 4);
      if (this.resetDeflater) this.deflater.reset();
    }
    await this.writeRaw(serverFrame(binary ? 2 : 1, payload, true, this.deflater !== null));
  }

  sendFrame(opcode: number, payload: Uint8Array, fin = true): Promise<void> {
    return this.writeRaw(serverFrame(opcode, payload, fin));
  }

  writeRaw(data: string | Uint8Array): Promise<void> {
    if (this.socket.destroyed) return Promise.reject(new Error("WPT peer closed"));
    return new Promise<void>((resolve, reject) => {
      const closed = (): void => { reject(new Error("WPT peer closed during write")); };
      this.socket.once("close", closed);
      this.socket.write(data, (error?: Error | null) => {
        this.socket.off("close", closed);
        if (error) reject(error); else resolve();
      });
    });
  }

  async close(code: number | null = 1000, reason = ""): Promise<void> {
    if (!this.closeSent && !this.socket.destroyed) {
      this.closeSent = true;
      const payload = code === null ? Buffer.alloc(0) : Buffer.alloc(2 + Buffer.byteLength(reason));
      if (code !== null) { payload.writeUInt16BE(code); payload.write(reason, 2); }
      await this.sendFrame(8, payload);
    }
    while (!this.closeReceived && !this.socket.destroyed) {
      if (await this.readMessage() === null) break;
    }
    this.end();
  }

  delay(milliseconds: number): Promise<void> {
    if (this.signal.aborted) return Promise.resolve();
    return new Promise<void>((resolve) => {
      const done = (): void => { clearTimeout(timer); this.signal.removeEventListener("abort", done); resolve(); };
      const timer = setTimeout(done, milliseconds);
      this.signal.addEventListener("abort", done, { once: true });
    });
  }

  end(): void { this.socket.end(); }
  abort(): void { this.socket.destroy(); }
}

// A test-only capability assembly. Public classes still come from src/index.ts;
// this supplies sockets and the WPT CA, and does not install Node's Web APIs.
import "../../../host/environment-shim.ts";
import { createHostNodePrimitives, HostNodeSocketConnector } from "../../../host/node-primitives.ts";
import { HostNodeWebSocketDeflate } from "../../../host/node-websocket-deflate.ts";
import { HostNodeContentDecoder } from "../../../host/node-content-decoder.ts";
import { installWebPlatformRuntime, WebPlatformRuntime } from "../../../src/provider.ts";
import type { WebPlatformOptions } from "../../../src/provider.ts";
import type { ConnectAddress, NegotiatingSocketConnector } from "../../../src/provider/primitives.ts";
import type { WptServer } from "./server.ts";

export function createWptRuntime(
  server: WptServer,
  options: WebPlatformOptions = {},
  reportError?: (error: unknown) => void,
): WebPlatformRuntime {
  const host = new HostNodeSocketConnector({ ca: server.ca });
  const addressOf = (address: ConnectAddress): ConnectAddress => {
    // Preserve the logical name for Host, SNI and certificate verification. Only
    // WPT names on this server's own ports are routed to the loopback listener.
    const domain = address.hostname;
    const badPort = /^bad-port-([0-9]+)\.wpt$/.exec(domain);
    if (!address.secure && badPort !== null && Number(badPort[1]) === address.port) {
      // Reproduce Create-blocked-port.any.js's PAC destination at the capability
      // boundary. The runtime must reject the logical port before reaching us;
      // sabotaging that policy must connect successfully and fail the WPT case.
      return { ...address, port: server.ports.http[0]!, resolvedAddress: "127.0.0.1", resolvedFamily: 4 };
    }
    if (!/^(?:[a-z0-9-]+\.)*(?:web-platform|not-web-platform)\.test$/.test(domain)
      || ![...server.ports.http, ...server.ports.https].includes(address.port)) {
      throw new Error("Address is outside the local WPT server: " + domain + ":" + address.port);
    }
    return { ...address, resolvedAddress: "127.0.0.1", resolvedFamily: 4 };
  };
  const sockets: NegotiatingSocketConnector = {
    reportsNegotiatedProtocol: true,
    connect(address, signal) { return host.connect(addressOf(address), signal); },
    connectNegotiated(address, signal) { return host.connectNegotiated(addressOf(address), signal); },
  };
  const runtime = new WebPlatformRuntime({ ...createHostNodePrimitives({}, reportError), sockets }, {
    baseURL: server.httpOrigin + "/",
    origin: server.httpOrigin,
    contentDecoder: new HostNodeContentDecoder(),
    webSocketDeflate: new HostNodeWebSocketDeflate(),
    ...options,
  });
  installWebPlatformRuntime(runtime);
  return runtime;
}

// Node-only WPT resources. No Python, external server, testharness shim or global
// Web API replacement is part of this module.
import { readFile, realpath } from "node:fs/promises";
import { createServer, ServerResponse } from "node:http";
import type { IncomingMessage, Server } from "node:http";
import { createServer as createSecureServer } from "node:https";
import { Socket } from "node:net";
import { extname, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import { handleEventSource } from "./eventsource-handlers.ts";
import { handleFetchResource } from "./fetch-handlers.ts";
import { handleHttpResource } from "./http-resources.ts";
import { WptWebSocketPeer } from "./peer.ts";
import { WptServerState } from "./state.ts";
import { substitute } from "./substitutions.ts";
import type { WptPorts } from "./substitutions.ts";
import { handleWebSocket } from "./websocket-handlers.ts";

const root = fileURLToPath(new URL("../", import.meta.url));
const types: Readonly<Record<string, string>> = {
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json",
  ".html": "text/html; charset=utf-8",
  ".htm": "text/html; charset=utf-8",
  ".event_stream": "text/event-stream",
  ".pac": "application/x-ns-proxy-autoconfig",
  ".css": "text/css; charset=utf-8",
  ".txt": "text/plain; charset=utf-8",
};

export interface WptServer {
  readonly ports: WptPorts;
  readonly httpOrigin: string;
  readonly httpsOrigin: string;
  readonly wsOrigin: string;
  readonly wssOrigin: string;
  /** Trust only for these tests. The upstream CA is never installed globally. */
  readonly ca: string;
  /** Unexpected handler errors remain observable to the enclosing Node test. */
  readonly errors: readonly unknown[];
  readonly state: WptServerState;
  close(): Promise<void>;
}

function requestURL(request: IncomingMessage, secure: boolean): URL {
  return new URL(request.url ?? "/", `${secure ? "https" : "http"}://${request.headers.host ?? "web-platform.test"}`);
}

async function serveStatic(request: IncomingMessage, response: ServerResponse, url: URL, ports: WptPorts): Promise<void> {
  let path: string;
  try { path = decodeURIComponent(url.pathname); }
  catch { response.writeHead(404).end(); return; }
  const type = types[extname(path)];
  // The Python references and certificates are provenance, not public resources.
  if (type === undefined || path.includes("\0") || path.includes("\\")) {
    response.writeHead(404).end();
    return;
  }
  let file: string;
  let bytes: Buffer;
  try {
    file = await realpath(resolve(root, "." + path));
    const inside = relative(root, file);
    if (inside === ".." || inside.startsWith(".." + sep)) {
      response.writeHead(404).end();
      return;
    }
    bytes = await readFile(file);
  } catch (error) {
    if (error instanceof Error && "code" in error && (error.code === "ENOENT" || error.code === "ENOTDIR")) {
      response.writeHead(404).end();
      return;
    }
    throw error;
  }
  const substitutions = { host: url.hostname, ports, headers: request.headers };
  if (path.includes(".sub.") || url.searchParams.get("pipe") === "sub") {
    bytes = Buffer.from(substitute(bytes.toString("utf8"), substitutions));
  }
  response.setHeader("Content-Type", type);
  try {
    const headers = substitute(await readFile(file + ".headers", "utf8"), substitutions);
    for (const line of headers.split(/\r?\n/)) {
      const colon = line.indexOf(":");
      if (colon > 0) response.appendHeader(line.slice(0, colon), line.slice(colon + 1).trim());
    }
  } catch (error) {
    if (!(error instanceof Error && "code" in error && error.code === "ENOENT")) throw error;
  }
  response.end(bytes);
}

function listen(server: Server): Promise<number> {
  return new Promise((resolvePort, reject) => {
    const failed = (error: Error): void => { server.off("listening", ready); reject(error); };
    const ready = (): void => {
      server.off("error", failed);
      const address = server.address();
      if (address === null || typeof address === "string") reject(new Error("WPT server did not bind TCP"));
      else resolvePort(address.port);
    };
    server.once("error", failed);
    server.once("listening", ready);
    server.listen(0, "127.0.0.1");
  });
}

/** Four ephemeral listeners allow the corpus's same-host, different-port cases. */
export async function startWptServer(): Promise<WptServer> {
  const [key, cert, ca] = await Promise.all([
    readFile(new URL("../tools/certs/web-platform.test.key", import.meta.url)),
    readFile(new URL("../tools/certs/web-platform.test.pem", import.meta.url)),
    readFile(new URL("../tools/certs/cacert.pem", import.meta.url), "utf8"),
  ]);
  const sockets = new Set<Socket>();
  const pending = new Set<Promise<void>>();
  const errors: unknown[] = [];
  const state = new WptServerState();
  const httpPorts: number[] = [];
  const httpsPorts: number[] = [];
  const ports: WptPorts = { http: httpPorts, https: httpsPorts, ws: httpPorts, wss: httpsPorts };
  let closing: Promise<void> | null = null;

  const track = (operation: Promise<void>, failed: (error: unknown) => void): void => {
    const settled = operation.catch(failed).finally(() => pending.delete(settled));
    pending.add(settled);
  };
  const dispatch = async (request: IncomingMessage, response: ServerResponse, secure: boolean): Promise<void> => {
    let url: URL;
    try { url = requestURL(request, secure); }
    catch { response.writeHead(400).end(); return; }
    if (await handleEventSource(request, response, url)) return;
    if (await handleFetchResource(request, response, url, state)) return;
    if (await handleHttpResource(request, response, url, state)) return;
    await serveStatic(request, response, url, ports);
  };
  const handle = (request: IncomingMessage, response: ServerResponse, secure: boolean): void => {
    track(dispatch(request, response, secure), (error) => {
      if (closing !== null || response.destroyed) return;
      errors.push(error);
      if (response.headersSent) response.destroy();
      else response.writeHead(500).end("WPT resource failed");
    });
  };
  const servers: Server[] = [
    createServer((request, response) => handle(request, response, false)),
    createServer((request, response) => handle(request, response, false)),
    createSecureServer({ key, cert, ALPNProtocols: ["http/1.1"] }, (request, response) => handle(request, response, true)),
    createSecureServer({ key, cert, ALPNProtocols: ["http/1.1"] }, (request, response) => handle(request, response, true)),
  ];
  for (const [index, server] of servers.entries()) {
    // Upstream long/reconnection tests own the deadline. Node's HTTP request
    // timeout must not end their resource while other gate jobs are running.
    server.requestTimeout = 0;
    server.on("connection", (socket: Socket) => {
      sockets.add(socket);
      socket.on("error", () => {});
      socket.once("close", () => sockets.delete(socket));
    });
    server.on("upgrade", (request, socket, head) => {
      if (!(socket instanceof Socket)) { socket.destroy(); return; }
      let url: URL;
      try { url = requestURL(request, index >= 2); }
      catch { socket.end("HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n"); return; }
      if (url.pathname.endsWith(".py")) {
        // abort.any.js uses a stash-put URL as its forbidden handshake target.
        // The resource must observe the request even when it is an Upgrade.
        const response = new ServerResponse(request);
        response.assignSocket(socket);
        handle(request, response, index >= 2);
        response.once("finish", () => socket.end());
        return;
      }
      const peer = new WptWebSocketPeer(request, socket, head, index >= 2);
      const upgraded = async (): Promise<void> => {
        if (await peer.validateHandshake()) await handleWebSocket(peer, state);
      };
      track(upgraded(), (error) => {
        if (closing === null && !peer.signal.aborted && !socket.destroyed && !socket.readableEnded) errors.push(error);
        socket.destroy();
      });
    });
  }
  const close = (): Promise<void> => {
    if (closing !== null) return closing;
    closing = (async () => {
      const stopped = servers.map((server) => new Promise<void>((done) => {
        if (!server.listening) { done(); return; }
        server.close(() => done());
      }));
      for (const socket of sockets) socket.destroy();
      state.close();
      await Promise.all(stopped);
      await Promise.all(pending);
    })();
    return closing;
  };
  try {
    for (const [index, server] of servers.entries()) {
      (index < 2 ? httpPorts : httpsPorts).push(await listen(server));
    }
  } catch (error) {
    await close();
    throw error;
  }
  return {
    ports, ca, errors, state, close,
    httpOrigin: `http://web-platform.test:${httpPorts[0]}`,
    httpsOrigin: `https://web-platform.test:${httpsPorts[0]}`,
    wsOrigin: `ws://web-platform.test:${httpPorts[0]}`,
    wssOrigin: `wss://web-platform.test:${httpsPorts[0]}`,
  };
}

/** The wptserve stash belongs to one server instance, never to the process. */
export class WptServerState {
  readonly stash = new Map<string, unknown>();
  private readonly waiting = new Map<string, Set<(value: unknown) => void>>();
  private readonly controller = new AbortController();

  put(path: string, key: string, value: unknown): void {
    this.controller.signal.throwIfAborted();
    const id = JSON.stringify([path, key]);
    const receiver = this.waiting.get(id)?.values().next().value;
    if (receiver !== undefined) {
      receiver(value);
      return;
    }
    if (this.stash.has(id)) throw new Error("Duplicate WPT stash key: " + id);
    this.stash.set(id, value);
  }

  take(path: string, key: string): unknown {
    const id = JSON.stringify([path, key]);
    const value = this.stash.get(id) ?? null;
    this.stash.delete(id);
    return value;
  }

  wait(path: string, key: string, signal?: AbortSignal): Promise<unknown> {
    const combined = signal === undefined
      ? this.controller.signal
      : AbortSignal.any([this.controller.signal, signal]);
    if (combined.aborted) return Promise.reject(combined.reason);
    const value = this.take(path, key);
    if (value !== null) return Promise.resolve(value);
    const id = JSON.stringify([path, key]);
    return new Promise<unknown>((resolve, reject) => {
      const receivers = this.waiting.get(id) ?? new Set<(value: unknown) => void>();
      const cleanup = (): void => {
        combined.removeEventListener("abort", abort);
        receivers.delete(receive);
        if (receivers.size === 0) this.waiting.delete(id);
      };
      const receive = (result: unknown): void => { cleanup(); resolve(result); };
      const abort = (): void => { cleanup(); reject(combined.reason); };
      receivers.add(receive);
      this.waiting.set(id, receivers);
      combined.addEventListener("abort", abort, { once: true });
    });
  }

  close(): void {
    this.controller.abort(new Error("WPT server closed"));
    this.stash.clear();
  }
}

import type { IncomingHttpHeaders } from "node:http";

export interface WptPorts {
  readonly http: readonly number[];
  readonly https: readonly number[];
  readonly ws: readonly number[];
  readonly wss: readonly number[];
}

export interface WptSubstitutions {
  readonly host: string;
  readonly ports: WptPorts;
  readonly headers?: IncomingHttpHeaders;
}

/** The substitution vocabulary used by the pinned realtime resources. */
export function substitute(source: string, context: WptSubstitutions): string {
  return source.replace(/\{\{([^{}]+)\}\}/g, (_match, input: string) => {
    const expression = input.trim();
    if (expression === "host") return context.host;
    const host = /^hosts\[(alt)?\]\[([a-z0-9-]*)\]$/.exec(expression);
    if (host !== null) {
      const domain = host[1] === "alt" ? "not-web-platform.test" : "web-platform.test";
      return host[2] === "" ? domain : host[2] + "." + domain;
    }
    const domain = /^domains\[([a-z0-9-]*)\]$/.exec(expression);
    if (domain !== null) return domain[1] === "" ? "web-platform.test" : domain[1] + ".web-platform.test";
    const port = /^ports\[(http|https|ws|wss|https-public|h2)\]\[([0-9]+)\]$/.exec(expression);
    if (port !== null) {
      const protocol = port[1];
      // constants.sub.js includes h2 in an unused branch of ordinary WS tests.
      // No HTTP/2 environment is advertised: the literal is substituted so the
      // unchanged script parses, and the API runners must exclude h2 variants.
      const ports = protocol === "http" ? context.ports.http
        : protocol === "ws" ? context.ports.ws
        : protocol === "wss" ? context.ports.wss : context.ports.https;
      const value = ports[Number(port[2])];
      if (value === undefined) throw new Error("Unavailable WPT port: " + expression);
      return String(value);
    }
    const header = /^headers\[([^\]]+)\]$/.exec(expression);
    if (header !== null) {
      const value = context.headers?.[header[1]!.toLowerCase()];
      return Array.isArray(value) ? value.join(", ") : value ?? "";
    }
    throw new Error("Unsupported WPT substitution: " + expression);
  });
}

