export const ENVIRONMENT_EXPERIMENT = "NTS_GATE_ENV_EXPERIMENT";

export function launcherPolicyNames(env: NodeJS.ProcessEnv): string[] {
  return Object.keys(env).filter(name => env[name] !== undefined && !HOST.has(name) && !PARENT.has(name) && (
    name.startsWith("NTS_") || name.startsWith("CARGO_PROFILE_") || name.startsWith("CARGO_TARGET_") || EXTRA_POLICY.has(name)
  )).sort();
}

export function assertLandingEnvironment(env: NodeJS.ProcessEnv = process.env): void {
  const names = launcherPolicyNames(env);
  if (names.length) throw new Error(`launcher verdict-policy overrides are not allowed for land: ${names.join(", ")}; unset them; standalone experiments cannot serve as landing evidence`);
}

export function hostEnvironment(launcher: NodeJS.ProcessEnv): NodeJS.ProcessEnv {
  const host: NodeJS.ProcessEnv = {};
  for (const name of HOST_CAPABILITIES) if (launcher[name] !== undefined) host[name] = launcher[name];
  host.HOME ??= homedir();
  host.CARGO_HOME ||= join(host.HOME, ".cargo");
  host.RUSTUP_HOME ||= join(host.HOME, ".rustup");
  return host;
}

/** Only counted compiler invocations use upstream's fixed Rayon setting. */
export function measuredCompileEnvironment(base:NodeJS.ProcessEnv=process.env):NodeJS.ProcessEnv {
  return {...base,...FIXED_AMBIENT,RAYON_NUM_THREADS:"1"};
}

export function reportLauncherDrops(launcher: NodeJS.ProcessEnv, write: (text: string) => void = text => process.stderr.write(text)): void {
  const names = Object.keys(launcher).filter(name => !HOST.has(name) && !PARENT.has(name) && (
    !(name in FIXED_AMBIENT) || launcher[name] !== FIXED_AMBIENT[name]
  )).sort();
  if (names.length) write(`gate: discarded launcher variable names: ${names.join(", ")}\n`);
}

export type EnvironmentReport = {
  version: 1; canonical: boolean; host: Record<string, string | null>;
  ambient: Record<string, string | null>; dropped: string[];
  experiments: { name: string; value: string }[];
};
type Context = { report: EnvironmentReport; owned: Record<string, string>; temporary:RunTemporary };
export type GateEnvironment = { env: NodeJS.ProcessEnv; report: EnvironmentReport; temporary:RunTemporary };

function strings(values: NodeJS.ProcessEnv): Record<string, string> {
  return Object.fromEntries(Object.entries(values).filter((entry): entry is [string, string] => entry[1] !== undefined));
}

/** `owned` is supplied by the runner's code, never copied wholesale from a launcher. */
export function gateEnvironment(
  launcher: NodeJS.ProcessEnv,
  options: { run: string; owned?: NodeJS.ProcessEnv; standalone?: boolean; experiment?: string },
): GateEnvironment {
  const inherited = launcher[ENVIRONMENT_CONTEXT];
  let prior: Context | undefined;
  if (inherited) {
    prior = JSON.parse(inherited) as Context;
    if (prior.report?.version !== 1 || !prior.owned || typeof prior.report.canonical !== "boolean") throw new Error("invalid gate environment handoff");
  }
  const owned: Record<string,string> = { ...prior?.owned, ...strings(options.owned ?? {}), NTS_GATE_RUN_DIR: resolve(options.run) };
  // These markers describe a live descriptor or shell re-entry, not policy.
  // pinned.sh consumes the lock marker; a later re-entry must not revive it.
  for (const name of INFRASTRUCTURE) {
    if (name === "NTS_GATE_LOCK_FD" || name === "NTS_GATE_SCOPE_EXPECTED" || name === "NTS_GATE_SETUP_ONLY") {
      if (launcher[name] === undefined && options.owned?.[name] === undefined) delete owned[name];
    }
  }
  const selected = options.experiment ?? (!prior && options.standalone ? launcher[ENVIRONMENT_EXPERIMENT] : undefined);
  if (selected && selected !== "today") throw new Error(`unknown environment experiment: ${selected}`);
  const overrides: { name: string; value: string }[] = [];
  if (!prior && options.standalone) {
    for (const name of launcherPolicyNames(launcher)) {
      if (INFRASTRUCTURE.has(name)) { if (!(name in owned)) owned[name] = launcher[name]!; continue; }
      if (name === ENVIRONMENT_EXPERIMENT) continue;
      if (!EXPERIMENTS.has(name) && !/^CARGO_(?:PROFILE|TARGET)_/.test(name)) throw new Error(`unknown standalone policy override: ${name}`);
      overrides.push({ name, value: launcher[name]! });
      if (!(name in owned)) owned[name] = launcher[name]!;
    }
  }
  const legacy = selected === "today" || prior?.report.experiments.some(e => e.name === ENVIRONMENT_EXPERIMENT && e.value === "today");
  const host = hostEnvironment(launcher);
  const under = (root: string) => { const path = relative(root, resolve(options.run)); return path !== ".." && !path.startsWith("../") && !isAbsolute(path); };
  if (![join(homedir(),".cache"),join(host.HOME!,".cache")].some(under)) throw new Error("gate run directory must be under ~/.cache; /tmp is not a gate scratch directory");
  const ambient: Record<string, string | null> = {};
  for (const name of [...Object.keys(FIXED_AMBIENT), ...UNSET_AMBIENT]) {
    ambient[name] = legacy ? launcher[name] ?? null : FIXED_AMBIENT[name] ?? null;
  }
  const env: NodeJS.ProcessEnv = legacy ? { ...launcher } : { ...host };
  for (const [name, value] of Object.entries(ambient)) {
    if (value === null) delete env[name]; else env[name] = value;
  }
  Object.assign(env, owned);
  // /tmp is a small tmpfs. Neither a launcher nor an experiment owns this path.
  env.TMPDIR = join(resolve(options.run), "tmp");
  env.XDG_CACHE_HOME = join(host.HOME!, ".cache");
  ambient.TMPDIR = env.TMPDIR;
  ambient.XDG_CACHE_HOME = env.XDG_CACHE_HOME;
  if (!prior) pruneRunTemporaries(host.HOME!);
  const temporary=captureRunTemporary(options.run,prior?.temporary);
  const experiments = [...(prior?.report.experiments ?? []), ...overrides];
  if (selected === "today") experiments.push({ name: ENVIRONMENT_EXPERIMENT, value: "today" });
  delete env[ENVIRONMENT_EXPERIMENT];
  const retained = new Set<string>([...HOST_CAPABILITIES, ...Object.keys(owned), ENVIRONMENT_CONTEXT]);
  const dropped = [...new Set([...(prior?.report.dropped ?? []), ...Object.keys(launcher).filter(name =>
    !retained.has(name) && launcher[name] !== env[name]
  )])].sort();
  const report: EnvironmentReport = {
    version: 1, canonical: (prior?.report.canonical ?? true) && experiments.length === 0,
    host: Object.fromEntries(HOST_CAPABILITIES.map(name => [name, env[name] ?? null])),
    ambient, dropped, experiments,
  };
  env[ENVIRONMENT_CONTEXT] = JSON.stringify({ report, owned, temporary } satisfies Context);
  return { env, report, temporary };
}

export function reportEnvironment(report: EnvironmentReport, write: (text: string) => void = text => process.stderr.write(text)): void {
  if (report.dropped.length) write(`gate: discarded launcher variable names: ${report.dropped.join(", ")}\n`);
  if (!report.canonical) write(`gate: NON-CANONICAL experiment; not landing evidence (${report.experiments.map(e => e.name).join(", ")})\n`);
}

export function nodeHeapOomReason(text: string): string | null {
  return /JavaScript heap out of memory|Fatal process out of memory|v8::(?:internal::)?(?:V8::)?FatalProcessOutOfMemory|FATAL ERROR: (?:Reached heap limit|Ineffective mark-compacts)/i.test(text)
    ? "Node/V8 heap out of memory diagnostic" : null;
}

// The shell re-enters only after this helper has normalized its initial build
// environment, so pinned.sh's Cargo invocation has the same contract as steps.
if (process.argv[1] && pathToFileURL(resolve(process.argv[1])).href === import.meta.url) {
  try {
    const [mode, script, ...args] = process.argv.slice(2);
    if (mode !== "--pinned" || !script) throw new Error("usage: canonical-environment.ts --pinned <script> [commit] [steps...]");
    const base = process.env;
    if (base.NTS_GATE_STEP && base[ENVIRONMENT_CONTEXT]) throw new Error("nested pinned gate entry must use its own run directory and environment");
    const home = base.HOME ?? homedir();
    const run = base.NTS_GATE_RUN_DIR ?? join(home, ".cache/nts-gate/runs", `${Date.now()}-${process.pid}`);
    const target = base.NTS_GATE_TARGET ?? join(home, ".cache/nts-gate/target");
    const owned: NodeJS.ProcessEnv = {
      NTS_GATE_TREE: base.NTS_GATE_TREE ?? join(home, ".cache/nts-gate/tree"), NTS_GATE_TARGET: target,
      CARGO_TARGET_DIR: target, NTS_BIN: join(target, "release/nts"), NTS_SUITE_BIN: join(target, "release/nts-suite"), NTS_CHECKERS: "1",
    };
    for (const name of INFRASTRUCTURE) if (base[name] !== undefined) owned[name] = base[name];
    const planned = gateEnvironment(base, { run, owned, standalone: !base[ENVIRONMENT_CONTEXT] });
    reportEnvironment(planned.report);
    const result = spawnSync("sh", [script, "--environment-ready", ...args], {
      env: planned.env,
      // Preserve only the documented gate-tree lock handoff, not arbitrary
      // inherited descriptors. Its inode/ownership is checked by pinned.sh.
      stdio: base.NTS_GATE_LOCK_FD === "8" ? ["inherit", "inherit", "inherit", "ignore", "ignore", "ignore", "ignore", "ignore", 8] : "inherit",
    });
    // Setup-only success and failures before run.mjs still own a temporary
    // root. Normal row completion already records its lifecycle in summary.
    if (!existsSync(join(run,"summary.json"))) {
      const outcome=finishRunTemporary(planned.temporary,planned.env.HOME!,result.status===0 && !result.signal && !result.error);
      process.stderr.write(`gate tmp: ${outcome.state}: ${outcome.path}\n`);
    }
    if (result.error) throw result.error;
    process.exitCode = result.status ?? 1;
  } catch (error) { console.error(`gate environment: ${(error as Error).message}`); process.exitCode = 2; }
}

// Scope changes invalidate old baselines and kept listings. Inheritance covers
// the exec's threads and descendants; the runtime hir population has no child
// processes. CPU is perf's waited-command user+sys rusage in that same scope.
export const COUNTER_SCOPE = "exec-inherited-user-instructions-v1";
// Use upstream's single-threaded checker mode and documented Rayon setting.
export const COMPILE_CHECKERS = 1;
export const COMPILE_WORK_PROFILE = "upstream-single-threaded-v2:checkers=1;rayon=1";
export const COMPILE_WORK_SETTINGS = {checkers:1,single_threaded:true,rayon_num_threads:"1"} as const;
export function compileWorkSettings(env:NodeJS.ProcessEnv) {
  if(env.RAYON_NUM_THREADS!=="1")throw new Error("compile work profile requires RAYON_NUM_THREADS=1 in the measured environment");
  return {...COMPILE_WORK_SETTINGS,rayon_num_threads:env.RAYON_NUM_THREADS};
}
export function compileWorkProblem(row:{work_profile?:unknown;work_settings?:unknown}):string|null {
  if(row.work_profile!==COMPILE_WORK_PROFILE)return "incompatible compiler work profile";
  const settings=row.work_settings;
  if(!settings||typeof settings!=="object"||!("checkers" in settings)||settings.checkers!==1
    ||!("single_threaded" in settings)||settings.single_threaded!==true
    ||!("rayon_num_threads" in settings)||settings.rayon_num_threads!=="1")return "missing upstream single-threaded/Rayon measurement evidence";
  return null;
}

export type CompileArm = "nogc" | "rc";
export const COMPILE_ARMS = {
  nogc: { table: "compile-times.tsv", calibration: "compile-counter-calibration.json" },
  rc: { table: "compile-times-rc.tsv", calibration: "compile-counter-rc-calibration.json" },
} as const;

export function compileArm(args: readonly string[]): CompileArm {
  const at = args.indexOf("--arm");
  if (at < 0) return "nogc";
  const arm = args[at + 1];
  if (arm !== "nogc" && arm !== "rc") throw new Error("--arm requires nogc or rc");
  return arm;
}

export function compileCommand(arm: CompileArm, module: string): string[] {
  return ["hir", "--prepared", "--checkers", String(COMPILE_CHECKERS), ...(arm === "rc" ? ["--rc"] : []), module];
}

export interface CounterRow {
  work_profile?: unknown;
  work_settings?: unknown;
  counter_scope?: unknown;
  instructions?: number | null;
  cpu_s?: number | null;
  counter_error?: string | null;
  error?: string | null;
  status?: number | null;
  signal?: string | null;
}

export function counterProblem(row: CounterRow): string | null {
  if (row.error || row.counter_error) return row.error || row.counter_error || null;
  if(row.work_profile!==undefined){const problem=compileWorkProblem(row);if(problem)return problem;}
  if (row.counter_scope !== COUNTER_SCOPE) return "incompatible counter scope (old attached counts are not measurements)";
  if (row.signal || (row.status !== undefined && row.status !== 0)) return `counter run ended ${row.signal ?? row.status}`;
  const { instructions, cpu_s } = row;
  if (typeof instructions !== "number" || !Number.isFinite(instructions) || instructions <= 0) return "no positive instruction count";
  if (typeof cpu_s !== "number" || !Number.isFinite(cpu_s) || cpu_s <= 0) return "no waited-command CPU measurement";
  // A deliberately broad floor, far below this corpus's billions/s. It rejects
  // the observed missed-worker reading (319,570 instructions / 92.90 CPU-s)
  // even though perf reported success and 100% counter running time.
  if (instructions / cpu_s < 1_000_000) return `implausible instruction count (${instructions} instructions / ${cpu_s.toFixed(6)} CPU-s)`;
  return null;
}

export function readCounterTable(text: string, arm: CompileArm = "nogc") {
  if (!text.split("\n").includes(`# counter-scope: ${COUNTER_SCOPE}`)) throw new Error("incompatible compile-times.tsv counter scope; record a fresh five-repeat baseline");
  if (!text.split("\n").includes(`# work-profile: ${COMPILE_WORK_PROFILE}`)) throw new Error("incompatible compiler work profile; record a fresh five-repeat baseline");
  // Unlabelled legacy tables were recorded only for NoGC. An RC table must
  // identify itself; neither arm may consume the other arm's baseline.
  const recordedArm = text.split("\n").find(line => line.startsWith("# arm: "))?.slice(7) ?? "nogc";
  if (recordedArm !== arm) throw new Error(`incompatible preparation arm: expected ${arm}, table records ${recordedArm}`);
  const rows = new Map<string, number>();
  for (const line of text.split("\n")) {
    if (!line || line.startsWith("#")) continue;
    const [module, g] = line.split("\t");
    if (!module || !Number.isFinite(Number(g)) || !(Number(g) > 0)) throw new Error(`invalid baseline row: ${line}`);
    if (rows.has(module)) throw new Error(`duplicate baseline row: ${module}`);
    rows.set(module, Number(g));
  }
  const number = (name: string) => Number(text.split("\n").find(line => line.startsWith(`# ${name}: `))?.split(": ")[1]);
  const ratio = number("regression-ratio");
  if (!Number.isFinite(ratio) || ratio <= 1) throw new Error("missing or invalid calibrated relative threshold");
  if (text.includes("# regression-absolute-g:")) throw new Error("obsolete absolute-floor policy; record the relative-only baseline");
  return { rows, ratio };
}

export interface CalibrationRun extends CounterRow {
  arm?: CompileArm;
  module: string;
  repeat: number;
  listing_functions: number | null;
  listing_definitions: number;
  counter_file: string;
}
export interface Calibration {
  work_profile?: string;
  work_settings?: unknown;
  arm?: CompileArm;
  counter_scope: string;
  complete: boolean;
  nts_sha256: string;
  modules: { module: string; runs: CalibrationRun[] }[];
}

/** Publish only a full five-repeat population. The baseline is the median;
 * the ratio clears four times the measured max/min spread, with a 10% floor,
 * rounded up to 5 percentage points. There is no absolute floor: small-module
 * blow-ups must also fail. Raw measurements stay with the policy in results/.
 */
export function calibratedTable(summary: Calibration, expected: string[]) {
  if (!summary.complete || summary.counter_scope !== COUNTER_SCOPE || compileWorkProblem(summary) || !/^[a-f0-9]{64}$/.test(summary.nts_sha256)) throw new Error("incomplete or incompatible calibration");
  const modules = [...summary.modules].sort((a, b) => a.module < b.module ? -1 : a.module > b.module ? 1 : 0);
  const arm = summary.arm ?? "nogc";
  if (arm !== "nogc" && arm !== "rc") throw new Error("invalid calibration preparation arm");
  if (JSON.stringify(modules.map(m => m.module)) !== JSON.stringify([...expected].sort())) throw new Error("calibration population differs from the current runtime modules");
  const median = (xs: number[]) => [...xs].sort((a, b) => a - b)[2];
  let maxSpread = 0;
  const rows = modules.map(({ module, runs }) => {
    if (runs.length !== 5 || runs.some(r => r.module !== module || (r.arm ?? "nogc") !== arm || r.work_profile !== COMPILE_WORK_PROFILE || r.status !== 0 || counterProblem(r) !== null)
      || JSON.stringify(runs.map(r => r.repeat).sort()) !== "[1,2,3,4,5]"
      || runs.some(r => !Number.isInteger(r.listing_functions) || r.listing_functions! < 1 || r.listing_functions !== r.listing_definitions)
      || new Set(runs.map(r => r.listing_functions)).size !== 1) throw new Error(`incomplete five-repeat listing/count proof: ${module}`);
    const counts = runs.map(r => r.instructions!);
    maxSpread = Math.max(maxSpread, Math.max(...counts) / Math.min(...counts) - 1);
    return `${module}\t${(median(counts) / 1e9).toFixed(3)}\t${median(runs.map(r => r.cpu_s!)).toFixed(3)}`;
  });
  const ratio = 1 + Math.max(2, Math.ceil(80 * maxSpread)) / 20;
  const policy = { ratio, observed_max_spread: maxSpread, spread_multiplier: 4, relative_floor: 0.10 };
  const text = [`# counter-scope: ${COUNTER_SCOPE}`, `# work-profile: ${COMPILE_WORK_PROFILE}`, `# arm: ${arm}`, `# compiler-sha256: ${summary.nts_sha256}`,
    `# regression-ratio: ${ratio.toFixed(2)}`,
    `# Five-repeat medians; policy/evidence: results/${COMPILE_ARMS[arm].calibration}`,
    `# Rerecord with node tooling/gate/compile-time.mjs --record --arm ${arm}; explain why.`,
    "# module\tG user instructions (all threads/descendants from exec)\tCPU s", ...rows, ""].join("\n");
  return { text, policy };
}

import { FIXED_AMBIENT } from "./canonical-environment.ts";
// The CPU time a child process spends itself, sampled from /proc while it
// runs: `utime + stime` of the process (every thread of it), not of the
// children it starts. The native frontend runs in this process, so its CPU
// time is included; external compiler/linker processes are not.
//
// Sampled rather than taken from a wrapper such as /usr/bin/time, which would
// stand between the caller and the process: a signal would arrive as an exit
// status and a timeout's SIGTERM would kill the wrapper and leave the compiler
// running. The last sample is at most one interval before the process ends,
// so a measurement is short by at most that much per busy thread.
import { readFileSync, mkdirSync } from "node:fs";
import { execFileSync, spawn, spawnSync } from "node:child_process";
import { dirname } from "node:path";
import { COUNTER_SCOPE, counterProblem } from "./compile-counter.ts";

let TICK = 100;
try { TICK = Number(execFileSync("getconf", ["CLK_TCK"], { encoding: "utf8" }).trim()) || 100; } catch {}
export const SAMPLE_MS = 200;

/** Seconds of CPU `pid` has used so far, or null when /proc cannot say. */
export function cpuOf(pid) {
  try {
    const stat = readFileSync(`/proc/${pid}/stat`, "utf8");
    const f = stat.slice(stat.lastIndexOf(")") + 2).split(" ");
    // After the name: state(0) ... utime is field 14 overall, index 11 here.
    return (Number(f[11]) + Number(f[12])) / TICK;
  } catch {
    return null;
  }
}

/**
 * Follow `child` (a ChildProcess) until it exits; resolves to its CPU seconds,
 * or null if not one sample could be read (no /proc).
 */
export function followCpu(child) {
  let seen = null;
  const sample = () => {
    const c = cpuOf(child.pid);
    if (c !== null) seen = Math.max(seen ?? 0, c);
  };
  sample();
  const timer = setInterval(sample, SAMPLE_MS);
  return new Promise((resolve) => {
    child.on("exit", () => { clearInterval(timer); resolve(seen); });
    child.on("error", () => { clearInterval(timer); resolve(seen); });
  });
}

// Count from exec: inheritance includes every compiler thread, including threads
// created after launch, and forked descendants. The measured hir commands have
// no descendants (no adjacent nts.config.ts, GIR imports, toolchain or oracle).
// A different command must inventory its children before using this scope.
// Raw hybrid-PMU counts are summed: scaled counts double-count migration.
export const PERF_ARGS = ["stat", "--no-scale", "--no-big-num", "-e", "instructions:u"];
export { COUNTER_SCOPE, counterProblem } from "./compile-counter.ts";

/** Read raw counts from current human output or retained historical CSV. */
export function parsePerf(text) {
  let total = 0;
  let seen = false;
  for (const line of text.split("\n")) {
    const csv = line.split(",");
    const human = /^\s*(\d+|<not counted>)\s+(?:cpu_(?:core|atom)\/instructions\/u|instructions:u)(?:\s|$)/.exec(line);
    const value = csv.length >= 3 && /instructions/.test(csv[2]) ? csv[0].trim() : human?.[1];
    if (value === "<not counted>") { seen = true; continue; }
    if (value === undefined || value === "" || !Number.isFinite(Number(value))) continue;
    seen = true;
    total += Number(value);
  }
  return seen ? total : null;
}

/** perf's waited-command rusage, not PMU enabled/running time or a /proc sample. */
export function parseMeasurement(text) {
  const seconds = (kind) => {
    const match = new RegExp(`^\\s*([0-9]+(?:\\.[0-9]+)?) seconds ${kind}\\s*$`, "m").exec(text);
    const csv = new RegExp(`^\\s*([0-9]+(?:\\.[0-9]+)?),seconds ${kind}(?:,.*)?$`, "m").exec(text);
    return match ? Number(match[1]) : csv ? Number(csv[1]) : null;
  };
  const user_s = seconds("user");
  const sys_s = seconds("sys");
  return { counter_scope: COUNTER_SCOPE, instructions: parsePerf(text), user_s, sys_s,
    cpu_s: user_s === null || sys_s === null ? null : user_s + sys_s };
}

const EXTRA_EVENTS = ["cycles", "branches", "branch-misses", "cache-references", "cache-misses"];

/** Additional counters use explicit user-only events on one pinned CPU.
 * An inactive hybrid PMU is not a zero measurement of an active event. */
export function parseUserEvents(text, events) {
  const lines = text.split("\n").flatMap(line => {
    const c = line.split(",").map(x => x.trim());
    if (c.length >= 5) return [{value:c[0],event:c[2],runtime:c[3],percent:c[4],format:"csv"}];
    const m = /^\s*(\d+|<not counted>|<not supported>)\s+((?:cpu_(?:core|atom)\/[^\s]+\/u)|(?:[\w-]+:u))(?:\s+(.*))?$/.exec(line);
    if (!m) return [];
    const percent = /\((\d+(?:\.\d+)?)%\)\s*$/.exec(m[3] ?? "");
    const annotations = (m[3]?.match(/\([^)]*%/g) ?? []).length;
    if ((annotations && !percent) || annotations > 1) throw Error("malformed counter running percentage");
    // perf's human format omits the percentage when the event ran fully.
    return [{value:m[1],event:m[2],runtime:null,percent:percent?.[1] ?? "100",format:"human"}];
  });
  const result = {};
  for (const event of events) {
    const rows = lines.filter(c => c.event === `${event}:u` || c.event === `cpu_core/${event}/u` || c.event === `cpu_atom/${event}/u`);
    if (!rows.length || new Set(rows.map(c => c.event)).size !== rows.length) throw Error(`missing or duplicate event: ${event}`);
    const active = [], inactive = [];
    for (const c of rows) {
      if (c.value === "<not counted>" && /^cpu_(core|atom)\//.test(c.event)
        && /^0(?:\.0+)?$/.test(c.percent) && (c.format === "human" || /^0(?:\.0+)?$/.test(c.runtime))) {
        inactive.push(c.event); continue;
      }
      if (!/^\d+$/.test(c.value) || !Number.isSafeInteger(Number(c.value))
        || (c.format === "csv" && (!/^\d+(?:\.\d+)?$/.test(c.runtime) || Number(c.runtime) <= 0))
        || !/^\d+(?:\.\d+)?$/.test(c.percent) || Number(c.percent) < 99 || Number(c.percent) > 100)
        throw Error(`invalid, unsupported or multiplexed event: ${event}`);
      active.push({pmu:c.event,value:Number(c.value),running_percent:Number(c.percent),format:c.format});
    }
    if (active.length !== 1) throw Error(`event must run on one pinned PMU: ${event}`);
    if ((event === "instructions" || event === "cycles") && active[0].value <= 0) throw Error(`nonpositive event: ${event}`);
    result[event] = {...active[0], inactive};
  }
  return result;
}

export function countedLaunch(command, args, {timeoutMs = 900_000, events = [], cpu} = {}) {
  if (!Array.isArray(events) || new Set(events).size !== events.length || events.some(e => !EXTRA_EVENTS.includes(e))) throw Error("invalid extra counter events");
  if (cpu !== undefined && (!Number.isSafeInteger(cpu) || cpu < 0 || cpu > 1023)) throw Error("invalid pinned CPU");
  if (events.length && cpu === undefined) throw Error("extra counters require an explicit pinned CPU");
  // CSV mode suppresses perf's waited-command user/sys footer. Retain the
  // human format so extra events share the default counter's exact CPU scope.
  const perf = events.length ? ["stat", "--no-scale", "--no-big-num", "-e", ["instructions", ...events].map(e => e + ":u").join(",")] : PERF_ARGS;
  const argv = ["timeout", "--signal=TERM", "--kill-after=5s", `${timeoutMs / 1000}s`, "perf", ...perf];
  return {command: cpu === undefined ? argv.shift() : "taskset", args: cpu === undefined ? argv : ["-c", String(cpu), ...argv],
    target: [command,...args], events: events.length ? ["instructions",...events] : []};
}

let probed;
/** A bounded launch probe; attachment to an already-running process is forbidden. */
export function instructionsWork() {
  if (probed !== undefined) return probed;
  const r = spawnSync("perf", [...PERF_ARGS, "--", "sh", "-c", "i=0; while [ $i -lt 10000 ]; do i=$((i+1)); done"],
    { encoding: "utf8", env: { ...process.env, ...FIXED_AMBIENT }, timeout: 120_000 });
  const measurement = parseMeasurement(r.stderr ?? "");
  probed = r.error ? `no perf (${r.error.message})` : r.status !== 0 ? `perf exited ${r.status}: ${r.stderr.trim()}` : counterProblem(measurement);
  return probed;
}

/**
 * Launch under perf before exec can create a thread. GNU timeout owns its child
 * process group and forwards termination to the whole run; killing a wrapper
 * alone would leave the compiler running. Its deadline is only a hang guard:
 * every nonzero status (including timeout's 124/137) invalidates the count.
 * The raw file belongs to the caller's run and is never deleted here.
 */
export function spawnCounted(command, args, { counterFile, timeoutMs = 900_000, events = [], cpu, ...options }) {
  if (!counterFile) throw new Error("a retained counterFile is required");
  mkdirSync(dirname(counterFile), { recursive: true });
  const launch = countedLaunch(command,args,{timeoutMs,events,cpu});
  const child = spawn(launch.command, [...launch.args, "-o", counterFile, "--", ...launch.target],
    { ...options, env: { ...(options.env ?? process.env), ...FIXED_AMBIENT } });
  const measurement = new Promise((resolve) => {
    let launchError;
    child.on("error", (error) => { launchError = error.message; });
    child.on("close", (status, signal) => {
      let raw = "";
      try { raw = readFileSync(counterFile, "utf8"); } catch {}
      const row = { ...parseMeasurement(raw), counter_file: counterFile, status, signal };
      let metricError;
      if (launch.events.length) {
        try { row.metrics = parseUserEvents(raw,launch.events); row.counter_cpu = cpu; }
        catch (error) { metricError = error.message; }
      }
      row.counter_error = launchError ?? metricError ?? (signal ? `counter run ended by ${signal}` : status !== 0 ? `counter run exited ${status}` : counterProblem(row));
      resolve(row);
    });
  });
  return { child, measurement };
}

// Only registered, closed run/tmp roots are an evictable cache. Logs, published
// artifacts and other scratch roots are outside this policy.
import {createHash} from "node:crypto";
import {execFileSync} from "node:child_process";
import {existsSync,lstatSync,mkdirSync,readdirSync,readFileSync,realpathSync,renameSync,rmSync,statfsSync,writeFileSync} from "node:fs";
import {homedir} from "node:os";
import {dirname,join,resolve,relative,isAbsolute} from "node:path";

export const FAILED_TEMP_MAX_BYTES=8*2**30;
export const TEMP_DISK_FLOOR_BYTES=40*2**30;
export type RunTemporary={path:string;parent:string;dev:number;ino:number;uid:number};
const registry=(home:string)=>join(home,".cache/nts-gate/closed-temporaries");
const key=(owned:RunTemporary)=>createHash("sha256").update(owned.path).digest("hex")+".json";
const under=(root:string,path:string)=>{const part=relative(root,path);return part!==".." && !part.startsWith("../") && !isAbsolute(part);};

export function captureRunTemporary(run:string,previous?:RunTemporary):RunTemporary {
  mkdirSync(run,{recursive:true});
  const path=join(resolve(run),"tmp");
  if (!existsSync(path)) mkdirSync(path);
  const stat=lstatSync(path),parent=realpathSync(run);
  if (!stat.isDirectory() || stat.isSymbolicLink() || stat.uid!==process.getuid?.()) throw new Error(`run temporary root is not an owned real directory: ${path}`);
  const owned={path,parent,dev:stat.dev,ino:stat.ino,uid:stat.uid};
  if (previous?.path===path && (previous.dev!==owned.dev || previous.ino!==owned.ino || previous.parent!==parent)) throw new Error(`run temporary directory was replaced: ${path}`);
  return owned;
}

function checked(owned:RunTemporary,home:string):void {
  if (!owned || !isAbsolute(owned.path) || ![join(home,".cache"),join(homedir(),".cache")].some(root=>under(root,owned.path)) || owned.path!==join(dirname(owned.path),"tmp")) throw new Error("invalid registered run temporary path");
  const stat=lstatSync(owned.path);
  if (!stat.isDirectory() || stat.isSymbolicLink() || stat.uid!==process.getuid?.() || stat.uid!==owned.uid || stat.dev!==owned.dev || stat.ino!==owned.ino || realpathSync(dirname(owned.path))!==owned.parent) throw new Error(`run temporary directory was replaced: ${owned.path}`);
}

/** Bounds apply to closed failures, and may evict them further for admission.
 * An invalid identity is reported and kept; it can never authorize a removal. */
export function pruneRunTemporaries(home:string,options:{maxBytes?:number;minimumFreeBytes?:number;write?:(line:string)=>void;freeBytes?:()=>number}={}) {
  const directory=registry(home),removed:string[]=[],protectedPaths:string[]=[];
  if (!existsSync(directory)) return {removed,protected:protectedPaths,retained_bytes:0};
  const write=options.write ?? (text=>process.stderr.write(text+"\n"));
  const entries:{file:string;owned:RunTemporary;closed:number;bytes:number}[]=[];
  for (const name of readdirSync(directory).filter(name=>name.endsWith(".json"))) {
    const file=join(directory,name);
    try {
      const entry=JSON.parse(readFileSync(file,"utf8"));
      if (!existsSync(entry.owned.path)) {rmSync(file);continue;}
      checked(entry.owned,home);
      if (!Number.isFinite(entry.closed)) throw new Error("missing closed-run timestamp");
      const bytes=Number(execFileSync("du",["-sx","-B1","--",entry.owned.path],{encoding:"utf8"}).split("\t")[0]);
      if (!Number.isFinite(bytes)) throw new Error("cannot measure closed temporary bytes");
      entries.push({file,owned:entry.owned,closed:entry.closed,bytes});
    } catch(error) {protectedPaths.push(file);write(`gate tmp: kept ${file}: ${(error as Error).message}`);}
  }
  entries.sort((a,b)=>a.closed-b.closed || a.file.localeCompare(b.file));
  let total=entries.reduce((sum,entry)=>sum+entry.bytes,0);
  const free=options.freeBytes ?? (()=>{const stat=statfsSync(directory);return stat.bavail*stat.bsize;});
  for (const entry of entries) {
    if (total<=(options.maxBytes??FAILED_TEMP_MAX_BYTES) && free()>=(options.minimumFreeBytes??TEMP_DISK_FLOOR_BYTES)) break;
    try {
      checked(entry.owned,home);
      rmSync(entry.owned.path,{recursive:true});rmSync(entry.file);
      total-=entry.bytes;removed.push(entry.owned.path);write(`gate tmp: evicted closed failure ${entry.owned.path} (${entry.bytes} allocated bytes); logs retained`);
    } catch(error) {protectedPaths.push(entry.owned.path);write(`gate tmp: kept ${entry.owned.path}: ${(error as Error).message}`);}
  }
  return {removed,protected:protectedPaths,retained_bytes:total};
}

export function finishRunTemporary(owned:RunTemporary,home:string,green:boolean) {
  try {
    checked(owned,home);
    const directory=registry(home),file=join(directory,key(owned));
    if (green) {rmSync(owned.path,{recursive:true});rmSync(file,{force:true});return {path:owned.path,state:"removed after green"};}
    mkdirSync(directory,{recursive:true});
    const next=file+"."+process.pid;
    writeFileSync(next,JSON.stringify({owned,closed:Date.now()})+"\n");renameSync(next,file);
    const pruning=pruneRunTemporaries(home);
    return {path:owned.path,state:existsSync(owned.path)?"retained after red":"evicted by failed-temporary bound",pruning};
  } catch(error) {return {path:owned.path,state:"kept: cleanup guard or operation failed",error:(error as Error).message};}
}

